import { fetchHeadquartersUser, listHeadquartersUsers } from '../../security/headquartersUsers.ts';
import { parseHqDirectoryListQuery } from '@/app/domain/admin/hqDirectoryQuery';
import { isPostgresUuidSubject } from '../../security/postgresUuidSubject.ts';

export const runtime = 'nodejs';

export async function GET(request: Request): Promise<Response> {
    try {
        const gate = await requireTrustedHeadquartersAdmin(request);
        if (!gate.ok) return gate.response;

        const allowed = await consumeRateLimitSlot(`admin-hq-users:${gate.userId}`, {
            maxRequests: 120,
            windowMs: 60_000,
        });
        if (!allowed) {
            return wifeJsonNoStore(429, { ok: false, error: 'تجاوزت حد عمليات المقر — حاول لاحقاً' });
        }

        const admin = getSupabaseAdminClient();
        if (!admin) {
            return wifeJsonNoStore(503, { ok: false, error: 'Database client not configured' });
        }

        const query = parseHqDirectoryListQuery(new URL(request.url).searchParams);
        const listed = await listHeadquartersUsers(admin, query);
        const includeId = query.includeId;
        if (isPostgresUuidSubject(includeId) && !listed.users.some((user) => user.id === includeId)) {
            const extra = await fetchHeadquartersUser(admin, includeId);
            if (extra) {
                listed.users = [extra, ...listed.users].slice(0, query.limit);
            }
        }
        return wifeJsonNoStore(200, {
            ok: true,
            users: listed.users,
            total: listed.matched,
            usersTotal: listed.usersTotal,
            offset: listed.offset,
            limit: listed.limit,
            hasMore: listed.hasMore,
            matchedExact: listed.matchedExact,
            capped: listed.capped,
        });
    } catch {
        return wifeJsonNoStore(500, { ok: false, error: 'Internal admin users error' });
    }
}

import { isAdminUserId } from '../../security/adminCheck.ts';
import {
  extractUserTokenFromRequest,
  getVerifiedTokenSubject,
  wifeUnauthorizedResponse,
} from '../../security/wifeValidator.ts';
import { wifeJsonResponse } from '../../security/wifeSecurityHeaders.ts';
import { rejectHeadquartersPublicSurface } from '../../security/headquartersOriginGate.ts';
import { assertSameOriginRequest } from '../../security/wifeSameOrigin.ts';

export const runtime = 'nodejs';

/**
 * تحقق هوية مقر القيادة من جلسة HttpOnly — مثل /api/auth/session.
 * لا يُطلب توقيع WIFE: طبقة التوقيع كانت ترفض مدير المنصّة قبل فحص البريد.
 * الرد دائماً { ok, isAdmin } فقط — لا userId ولا سبب الصلاحية في أي بيئة.
 */
export async function GET(request: Request): Promise<Response> {
  try {
    const surface = rejectHeadquartersPublicSurface(request);
    if (surface) return surface;
    if (!assertSameOriginRequest(request)) {
      return wifeJsonResponse(403, { ok: false, error: 'Forbidden origin' });
    }
    const token = extractUserTokenFromRequest(request);
    if (!token) {
      return wifeUnauthorizedResponse({ request, reason: 'unauthorized_token' });
    }

    const userId = await getVerifiedTokenSubject(token);
    if (!userId) {
      return wifeUnauthorizedResponse({ request, reason: 'unauthorized_token' });
    }

    const isAdmin = await isAdminUserId(userId, token);
    return wifeJsonResponse(200, { ok: true, isAdmin });
  } catch {
    return wifeJsonResponse(500, { ok: false, error: 'Internal admin verify error' });
  }
}

import { isJsonObjectRecord, sanitizePayload } from '../../security/sanitizer.ts';
import { requireWifeUser, unwrapWifeUser } from '../../security/bffAuth.ts';
import { getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';
import { wifeJsonResponse } from '../../security/wifeSecurityHeaders.ts';

export const runtime = 'nodejs';

const TABLE = 'audit_logs';
const MAX_ACTION_LEN = 128;
const MAX_DETAILS_CHARS = 4_096;

/** أحداث يكتبها العميل بعد نجاح مسار حقيقي — ليست صلاحيات ولا أحداث مقر. */
const CLIENT_AUDIT_ACTIONS = new Set([
  'login_success',
  'local_guest_enter',
  'lawyer_register_account',
  'lawyer_register_pending',
  'dev_unlock_enter',
]);

function clipClientAuditDetails(details: unknown): unknown {
  if (details == null) return null;
  try {
    const serialized = JSON.stringify(details);
    if (!serialized) return null;
    if (serialized.length > MAX_DETAILS_CHARS) return { truncated: true };
    return details;
  } catch {
    return null;
  }
}

function normalizeClientAuditAction(action: string): string {
  return action
    .normalize('NFKC')
    .replace(/[\u0000-\u001F\u007F\u200B-\u200F\u202A-\u202E\u2060-\u206F\uFEFF]/g, '')
    .trim();
}

function isMissingRelationError(message: string): boolean {
  const hay = message.toLowerCase();
  return hay.includes('does not exist') || hay.includes('relation') || hay.includes('schema cache');
}

export async function POST(request: Request): Promise<Response> {
  try {
    const authGate = unwrapWifeUser(await requireWifeUser(request));
    if ('response' in authGate) return authGate.response;
    const { userId } = authGate;

    let payload: unknown = null;
    try {
      payload = sanitizePayload(await request.json());
    } catch {
      payload = null;
    }
    if (!isJsonObjectRecord(payload) || typeof payload.action !== 'string') {
      return wifeJsonResponse(400, { ok: false, error: 'action مطلوب' });
    }

    const action = normalizeClientAuditAction(payload.action).slice(0, MAX_ACTION_LEN);
    if (!action) {
      return wifeJsonResponse(400, { ok: false, error: 'action مطلوب' });
    }
    if (/^hq\s*:/i.test(action)) {
      return wifeJsonResponse(403, { ok: false, error: 'Headquarters audit is server-only' });
    }
    if (!CLIENT_AUDIT_ACTIONS.has(action)) {
      return wifeJsonResponse(400, { ok: false, error: 'action غير مسموح' });
    }

    const admin = getSupabaseAdminClient();
    if (!admin) {
      return wifeJsonResponse(503, { ok: false, error: 'Database client not configured' });
    }

    const { error } = await admin.from(TABLE).insert({
      user_id: userId,
      action,
      details: clipClientAuditDetails(payload.details),
    });

    if (error) {
      if (isMissingRelationError(error.message ?? '')) {
        return wifeJsonResponse(200, { ok: true, skipped: true });
      }
      return wifeJsonResponse(500, { ok: false, error: 'Failed to write audit log' });
    }

    return wifeJsonResponse(200, { ok: true });
  } catch {
    return wifeJsonResponse(500, { ok: false, error: 'Internal audit error' });
  }
}

