    });

    it('يرفض إعادة استخدام الرمز نفسه بعد استهلاكه', async () => {
        const fake = buildFakeAdmin({
            id: 'chal-2',
            code_hash: hashCode('654321'),
            expires_at: new Date(Date.now() + 60_000).toISOString(),
            attempts: 0,
            consumed_at: null,
        });
        adminHolder.client = fake.admin;

        await expect(
