import {
    isAdminMailerConfigured,
    sendAdminMail,
} from '../../security/adminMailer.ts';
import { readHqMailerEnv } from '../../security/adminMailerEnv.ts';
import { toIraqWhatsAppMsisdn } from './whatsappMsisdn.ts';
import {
    buildWhatsAppOtpTemplatePayload,
    type WhatsAppOtpTemplateKind,
} from './whatsappOtpTemplate.ts';
import type { AuthOtpChannel, AuthOtpPurpose } from './authOtpTypes.ts';

function purposeLabel(purpose: AuthOtpPurpose): string {
    return purpose === 'password_reset' ? 'استعادة كلمة المرور' : 'تأكيد البريد الإلكتروني';
}

function isHttpsUrl(value: string): boolean {
    return /^https:\/\//i.test(value);
}

export function isAuthOtpEmailChannelReady(): boolean {
    return isAdminMailerConfigured();
}

export function isMetaWhatsAppCloudReady(): boolean {
    const token = readHqMailerEnv('WHATSAPP_TOKEN');
    const phoneId = readHqMailerEnv('WHATSAPP_PHONE_NUMBER_ID');
    const template = readHqMailerEnv('WHATSAPP_OTP_TEMPLATE');
    return Boolean(token && phoneId && template);
}

/** وسيط واتساب مخصّص، أو EMAIL_WEBHOOK فقط إذا صُرّح WHATSAPP_VIA_EMAIL_WEBHOOK=true */
export function isAuthOtpWhatsAppWebhookReady(): boolean {
    if (isHttpsUrl(readHqMailerEnv('WHATSAPP_WEBHOOK_URL'))) return true;
    const viaEmail = readHqMailerEnv('WHATSAPP_VIA_EMAIL_WEBHOOK').toLowerCase() === 'true';
    return viaEmail && isHttpsUrl(readHqMailerEnv('EMAIL_WEBHOOK_URL'));
}

export function isAuthOtpWhatsAppChannelReady(): boolean {
    return isMetaWhatsAppCloudReady() || isAuthOtpWhatsAppWebhookReady();
}

export async function sendAuthOtpEmail(input: {
    to: string;
    code: string;
    purpose: AuthOtpPurpose;
}): Promise<{ ok: true } | { ok: false; error: string }> {
    const label = purposeLabel(input.purpose);
    const mail = await sendAdminMail({
        to: input.to,
        subject: `رمز التحقق — حامي (${label})`,
        text: `رمز التحقق لتطبيق حامي (${label}): ${input.code}\nصالح لمدة 10 دقائق.\nإن لم تطلبه فتجاهل الرسالة.`,
        html: `<p>رمز التحقق لتطبيق حامي (${label}):</p><p style="font-size:24px;letter-spacing:4px;"><strong>${input.code}</strong></p><p>صالح لمدة 10 دقائق. إن لم تطلبه فتجاهل الرسالة.</p>`,
    });
    if (!mail.ok) return { ok: false, error: mail.error };
    return { ok: true };
}

function whatsappGraphVersion(): string {
    const raw = readHqMailerEnv('WHATSAPP_GRAPH_VERSION') || 'v21.0';
    return /^v\d+(\.\d+)?$/.test(raw) ? raw : 'v21.0';
}

async function sendWhatsAppCloudTemplate(toMsisdn: string, code: string): Promise<boolean> {
    const token = readHqMailerEnv('WHATSAPP_TOKEN');
    const phoneId = readHqMailerEnv('WHATSAPP_PHONE_NUMBER_ID');
    const template = readHqMailerEnv('WHATSAPP_OTP_TEMPLATE');
    const lang = readHqMailerEnv('WHATSAPP_OTP_TEMPLATE_LANG') || 'ar';
    if (!token || !phoneId || !template) return false;
    const kinds: WhatsAppOtpTemplateKind[] = ['authentication', 'body_only'];
    for (const kind of kinds) {
        try {
            const res = await fetch(
                `https://graph.facebook.com/${whatsappGraphVersion()}/${phoneId}/messages`,
                {
                    method: 'POST',
                    headers: {
                        Authorization: `Bearer ${token}`,
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify(
                        buildWhatsAppOtpTemplatePayload({
                            toMsisdn,
                            code,
                            template,
                            lang,
                            kind,
                        }),
                    ),
                },
            );
            if (res.ok) return true;
        } catch {
            /* جرّب الشكل التالي */
        }
    }
    return false;
}

function resolveWhatsAppWebhookTarget(): { url: string; token: string } | null {
    const dedicated = readHqMailerEnv('WHATSAPP_WEBHOOK_URL');
    if (isHttpsUrl(dedicated)) {
        return {
            url: dedicated,
            token: readHqMailerEnv('WHATSAPP_WEBHOOK_TOKEN') || readHqMailerEnv('EMAIL_WEBHOOK_TOKEN'),
        };
    }
    const viaEmail = readHqMailerEnv('WHATSAPP_VIA_EMAIL_WEBHOOK').toLowerCase() === 'true';
    const emailUrl = readHqMailerEnv('EMAIL_WEBHOOK_URL');
    if (viaEmail && isHttpsUrl(emailUrl)) {
        return { url: emailUrl, token: readHqMailerEnv('EMAIL_WEBHOOK_TOKEN') };
    }
    return null;
}

async function sendWhatsAppWebhook(
    toMsisdn: string,
    code: string,
    purpose: AuthOtpPurpose,
): Promise<boolean> {
    const target = resolveWhatsAppWebhookTarget();
    if (!target) return false;
    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (target.token) headers.Authorization = `Bearer ${target.token}`;
    try {
        const res = await fetch(target.url, {
            method: 'POST',
            headers,
            body: JSON.stringify({
                channel: 'whatsapp',
                to: toMsisdn,
                text: `رمز حامي: ${code} — صالح 10 دقائق.`,
                purpose,
            }),
        });
        return res.ok;
    } catch {
        return false;
    }
}

export async function sendAuthOtpWhatsApp(input: {
    phone: string;
    code: string;
    purpose: AuthOtpPurpose;
}): Promise<{ ok: true } | { ok: false; error: string }> {
    const msisdn = toIraqWhatsAppMsisdn(input.phone);
    if (!msisdn) return { ok: false, error: 'invalid_phone' };
    if (await sendWhatsAppCloudTemplate(msisdn, input.code)) return { ok: true };
    if (await sendWhatsAppWebhook(msisdn, input.code, input.purpose)) return { ok: true };
    return { ok: false, error: 'whatsapp_send_failed' };
}

export async function deliverAuthOtp(input: {
    channel: AuthOtpChannel;
    email: string;
    phone: string | null;
    code: string;
    purpose: AuthOtpPurpose;
}): Promise<{ ok: true } | { ok: false; error: string }> {
    if (input.channel === 'email') {
        return sendAuthOtpEmail({ to: input.email, code: input.code, purpose: input.purpose });
    }
    if (!input.phone) return { ok: false, error: 'no_phone' };
    return sendAuthOtpWhatsApp({ phone: input.phone, code: input.code, purpose: input.purpose });
}

import { resolve4, resolveMx } from 'node:dns/promises';
import {
    isTrustedEmailProviderDomain,
    normalizeRegistrationEmail,
} from '../../../services/auth/registrationCredentialsSecurity.ts';

const MX_TIMEOUT_MS = 2500;

async function domainHasMailExchanger(domain: string): Promise<boolean> {
    try {
        const mx = await resolveMx(domain);
        if (mx.length > 0) return true;
    } catch {
        /* NXDOMAIN / ENODATA */
    }
    try {
        const records = await resolve4(domain);
        return records.length > 0;
    } catch {
        return false;
    }
}

/** مزوّد معروف يُعدّ حقيقياً بلا DNS. غيره يُفحص MX/A خلال مهلة قصيرة. */
export async function emailDomainAcceptsMail(email: string): Promise<boolean> {
    const normalized = normalizeRegistrationEmail(email);
    const at = normalized.lastIndexOf('@');
    if (at <= 0) return false;
    const domain = normalized.slice(at + 1);
    if (isTrustedEmailProviderDomain(domain)) return true;
    return Promise.race([
        domainHasMailExchanger(domain),
        new Promise<boolean>((resolve) => {
            setTimeout(() => resolve(false), MX_TIMEOUT_MS);
        }),
    ]);
}

import { applyWifeSecurityHeaders } from '../../security/wifeSecurityHeaders.ts';

export function readAuthOtpClientIp(request: Request): string {
    const forwarded = request.headers.get('x-forwarded-for');
    const firstHop = forwarded?.split(',')[0]?.trim();
    return firstHop || request.headers.get('x-real-ip')?.trim() || 'unknown';
}

export function authOtpJson(status: number, body: Record<string, unknown>): Response {
    return applyWifeSecurityHeaders(
        new Response(JSON.stringify(body), {
            status,
            headers: { 'Content-Type': 'application/json; charset=utf-8' },
        }),
    );
}

import { kvGet } from '../../security/kvStoreAdmin.ts';
import { getGoTrueAdminApi, getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';

export type AuthOtpAccount = {
    userId: string;
    email: string;
    phone: string | null;
    emailConfirmed: boolean;
};

export function readPhoneFromUnknown(value: unknown): string | null {
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    const phone = (value as { phone?: unknown }).phone;
    return typeof phone === 'string' && phone.trim() ? phone.trim() : null;
}

async function readVerificationRecordPhone(userId: string): Promise<string | null> {
    try {
        return readPhoneFromUnknown(await kvGet(`lawyer-verification:${userId}`));
    } catch {
        return null;
    }
}

export async function lookupAuthOtpAccountByEmail(email: string): Promise<AuthOtpAccount | null> {
    const admin = getSupabaseAdminClient();
    if (!admin) return null;
    const trimmed = email.trim().toLowerCase();
    if (!trimmed.includes('@')) return null;

    const { data, error } = await admin.rpc('hq_lookup_auth_email', { p_email: trimmed });
    const userId = typeof data === 'string' ? data.trim() : '';
    if (error || !userId) return null;

    const { data: packed } = await getGoTrueAdminApi(admin).getUserById(userId);
    const user = packed?.user;
    if (!user?.id) return null;

    const goTruePhone =
        (typeof (user as { phone?: unknown }).phone === 'string'
            ? String((user as { phone?: string }).phone).trim()
            : '') || readPhoneFromUnknown(user.user_metadata);

    const phone = goTruePhone || (await readVerificationRecordPhone(user.id));

    return {
        userId: user.id,
        email: (user.email ?? trimmed).trim().toLowerCase(),
        phone: phone || null,
        emailConfirmed: Boolean(user.email_confirmed_at),
    };
}

import { getSupabaseAuthConfigFromEnv } from '../../security/sessionCookie.ts';
import { revokeGoTrueSession } from '../goTrueSession.ts';

export type AuthOtpPasswordConfirmResult = 'live' | 'failed' | 'skipped';

/**
 * بعد Admin updateUserById: يمنح جلسة بالكلمة الجديدة ثم يلغيها.
 * skipped = لا إعداد GoTrue للتحقق (اختبار/خادم ناقص).
 */
export async function confirmGoTruePasswordIsLive(
    email: string,
    password: string,
): Promise<AuthOtpPasswordConfirmResult> {
    const cfg = getSupabaseAuthConfigFromEnv();
    if (!cfg) return 'skipped';
    try {
        const res = await fetch(`${cfg.url}/auth/v1/token?grant_type=password`, {
            method: 'POST',
            headers: {
                apikey: cfg.key,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify({ email, password }),
        });
        const data = (await res.json().catch(() => null)) as { access_token?: unknown } | null;
        const token = typeof data?.access_token === 'string' ? data.access_token.trim() : '';
        if (!res.ok || !token) return 'failed';
        await revokeGoTrueSession(token, { scope: 'global' });
        return 'live';
    } catch {
        return 'failed';
    }
}

import { createHash, randomInt, timingSafeEqual } from 'node:crypto';
import { applyHqMailerEnvFromFiles } from '../../security/adminMailerEnv.ts';
import { getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';
import { isWifeProduction } from '../../security/wifeStoreEnv.ts';
import {
    AUTH_OTP_CODE_LEN,
    AUTH_OTP_MAX_ATTEMPTS,
    AUTH_OTP_TTL_MS,
    type AuthOtpChannel,
    type AuthOtpPurpose,
} from './authOtpTypes.ts';

const MIN_PEPPER_LEN = 16;
const DEV_OTP_PEPPER = 'hami-auth-otp-dev-pepper';

function resolveAuthOtpPepper(): string | null {
    applyHqMailerEnvFromFiles();
    const dedicated = (process.env.AUTH_OTP_PEPPER ?? process.env.ADMIN_OTP_PEPPER ?? '').trim();
    if (dedicated.length >= MIN_PEPPER_LEN) return dedicated;
    if (isWifeProduction()) return null;
    const serviceSlice = (process.env.SUPABASE_SERVICE_ROLE_KEY ?? '').trim().slice(0, 32);
    if (serviceSlice.length >= MIN_PEPPER_LEN) return serviceSlice;
    return DEV_OTP_PEPPER;
}

function hashAuthOtpCode(code: string): string {
    const pepper = resolveAuthOtpPepper();
    if (!pepper) throw new Error('AUTH_OTP_PEPPER is required');
    return createHash('sha256').update(`${pepper}:${code.trim()}`, 'utf8').digest('hex');
}

function hashesEqual(leftHex: string, rightHex: string): boolean {
    try {
        const left = Buffer.from(leftHex, 'hex');
        const right = Buffer.from(rightHex, 'hex');
        if (left.length === 0 || left.length !== right.length) return false;
        return timingSafeEqual(left, right);
    } catch {
        return false;
    }
}

export function generateAuthOtpCode(): string {
    let out = '';
    for (let i = 0; i < AUTH_OTP_CODE_LEN; i += 1) {
        out += String(randomInt(0, 10));
    }
    return out;
}

function pepperError(): string {
    return isWifeProduction()
        ? 'OTP is not configured'
        : 'AUTH_OTP_PEPPER or ADMIN_OTP_PEPPER (16+ chars) is required in production';
}

function isMissingTable(detail: string): boolean {
    return /could not find the table|does not exist|PGRST205|42P01|schema cache/i.test(detail);
}

export async function createAuthOtpChallenge(input: {
    userId: string;
    purpose: AuthOtpPurpose;
    channel: AuthOtpChannel;
    requestIp?: string | null;
}): Promise<{ code: string; expiresAt: string } | { error: string }> {
    if (!resolveAuthOtpPepper()) return { error: pepperError() };
    const admin = getSupabaseAdminClient();
    if (!admin) return { error: 'Database client not configured' };

    const code = generateAuthOtpCode();
    let codeHash: string;
    try {
        codeHash = hashAuthOtpCode(code);
    } catch {
        return { error: pepperError() };
    }
    const expiresAt = new Date(Date.now() + AUTH_OTP_TTL_MS).toISOString();
    const nowIso = new Date().toISOString();

    const { error: rotateError } = await admin
        .from('auth_otp_challenges')
        .update({ consumed_at: nowIso })
        .eq('user_id', input.userId)
        .eq('purpose', input.purpose)
        .is('consumed_at', null);
    if (rotateError) {
        const detail = typeof rotateError.message === 'string' ? rotateError.message : '';
        if (isMissingTable(detail)) {
            return {
                error:
                    'جدول رموز التحقق غير موجود — طبّق supabase/migrations/20260829050000_auth_otp_challenges.sql',
            };
        }
        return { error: isWifeProduction() ? 'Failed to create OTP challenge' : detail };
    }

    const { error } = await admin.from('auth_otp_challenges').insert({
        user_id: input.userId,
        purpose: input.purpose,
        channel: input.channel,
        code_hash: codeHash,
        expires_at: expiresAt,
        request_ip: input.requestIp ?? null,
    });
    if (error) {
        const detail = typeof error.message === 'string' ? error.message : '';
        if (isMissingTable(detail)) {
            return {
                error:
                    'جدول رموز التحقق غير موجود — طبّق supabase/migrations/20260829050000_auth_otp_challenges.sql',
            };
        }
        return { error: isWifeProduction() ? 'Failed to create OTP challenge' : detail };
    }
    return { code, expiresAt };
}

export type ConsumeAuthOtpResult =
    | { ok: true }
    | { ok: false; error: 'invalid' | 'expired' | 'locked' | 'store' };

type AuthOtpAdmin = NonNullable<ReturnType<typeof getSupabaseAdminClient>>;

function readFailedAttemptLock(data: unknown): boolean | null {
    const row = (Array.isArray(data) ? data[0] : data) as { locked?: unknown } | null;
    if (!row || typeof row !== 'object') return null;
    return row.locked === true;
}

/**
 * زيادة المحاولات على الخادم (RPC) أو CAS على الصف. الحساب في Node
 * يفشل تحت التوازي فيسمح بتجاوز السقف.
 */
async function registerFailedAuthOtpAttempt(
    admin: AuthOtpAdmin,
    challengeId: string,
    attempts: number,
): Promise<'invalid' | 'locked' | 'store'> {
    const nextAttempts = attempts + 1;
    const locked = nextAttempts >= AUTH_OTP_MAX_ATTEMPTS;

    if (typeof admin.rpc === 'function') {
        const { data, error } = await admin.rpc('auth_otp_register_failed_attempt', {
            p_id: challengeId,
            p_max: AUTH_OTP_MAX_ATTEMPTS,
        });
        if (!error) {
            const rpcLocked = readFailedAttemptLock(data);
            if (rpcLocked === true) return 'locked';
            if (rpcLocked === false) return 'invalid';
        }
    }

    const patch: Record<string, unknown> = { attempts: nextAttempts };
    if (locked) patch.consumed_at = new Date().toISOString();

    const { data: bumped, error: casError } = await admin
        .from('auth_otp_challenges')
        .update(patch)
        .eq('id', challengeId)
        .eq('attempts', attempts)
        .is('consumed_at', null)
        .select('id')
        .maybeSingle();
    if (casError) return 'store';
    if (!bumped?.id) return 'invalid';
    return locked ? 'locked' : 'invalid';
}

export async function consumeAuthOtpChallenge(input: {
    userId: string;
    purpose: AuthOtpPurpose;
    code: string;
}): Promise<ConsumeAuthOtpResult> {
    if (!resolveAuthOtpPepper()) return { ok: false, error: 'store' };
    const admin = getSupabaseAdminClient();
    if (!admin) return { ok: false, error: 'store' };

    const { data, error } = await admin
        .from('auth_otp_challenges')
        .select('id, code_hash, expires_at, attempts')
        .eq('user_id', input.userId)
        .eq('purpose', input.purpose)
        .is('consumed_at', null)
        .order('created_at', { ascending: false })
        .limit(1)
        .maybeSingle();
    if (error || !data?.id || typeof data.code_hash !== 'string') {
        return { ok: false, error: 'invalid' };
    }

    const expiresAt = Date.parse(String(data.expires_at ?? ''));
    if (!Number.isFinite(expiresAt) || expiresAt <= Date.now()) {
        await admin
            .from('auth_otp_challenges')
            .update({ consumed_at: new Date().toISOString() })
            .eq('id', data.id);
        return { ok: false, error: 'expired' };
    }

    const attempts = typeof data.attempts === 'number' ? data.attempts : 0;
    if (attempts >= AUTH_OTP_MAX_ATTEMPTS) {
        await admin
            .from('auth_otp_challenges')
            .update({ consumed_at: new Date().toISOString() })
            .eq('id', data.id);
        return { ok: false, error: 'locked' };
    }

    let expectedHash: string;
    try {
        expectedHash = hashAuthOtpCode(input.code);
    } catch {
        return { ok: false, error: 'store' };
    }

    if (!hashesEqual(String(data.code_hash), expectedHash)) {
        const outcome = await registerFailedAuthOtpAttempt(admin, String(data.id), attempts);
        if (outcome === 'store') return { ok: false, error: 'store' };
        return { ok: false, error: outcome };
    }

    /*
     * الاستهلاك يجب أن يفوز به طلب واحد فقط: الشرط `consumed_at is null` مع إرجاع
     * الصف المُحدَّث يجعل الطلب المتزامن الثاني لا يجد صفاً فيُرفَض بدل أن يمرّ.
     */
    const { data: consumedRow, error: consumeError } = await admin
        .from('auth_otp_challenges')
        .update({ consumed_at: new Date().toISOString() })
        .eq('id', data.id)
        .is('consumed_at', null)
        .select('id')
        .maybeSingle();
    if (consumeError) return { ok: false, error: 'store' };
    if (!consumedRow?.id) return { ok: false, error: 'invalid' };
    return { ok: true };
}

export const AUTH_OTP_PURPOSES = ['password_reset', 'email_confirm'] as const;
export type AuthOtpPurpose = (typeof AUTH_OTP_PURPOSES)[number];

export const AUTH_OTP_CHANNELS = ['email', 'whatsapp'] as const;
export type AuthOtpChannel = (typeof AUTH_OTP_CHANNELS)[number];

export const AUTH_OTP_TTL_MS = 10 * 60 * 1000;
export const AUTH_OTP_RESEND_SEC = 60;
export const AUTH_OTP_MAX_ATTEMPTS = 5;
export const AUTH_OTP_CODE_LEN = 6;

export function isAuthOtpPurpose(value: unknown): value is AuthOtpPurpose {
    return typeof value === 'string' && (AUTH_OTP_PURPOSES as readonly string[]).includes(value);
}

export function isAuthOtpChannel(value: unknown): value is AuthOtpChannel {
    return typeof value === 'string' && (AUTH_OTP_CHANNELS as readonly string[]).includes(value);
}

