const WINDOW_MS = 15 * 60_000;
const MAX_PER_IP = 10;
const MAX_PER_EMAIL = 4;

export const runtime = 'nodejs';

async function sendGoTrueRecover(email: string, redirectTo: string, request: Request): Promise<void> {
    const cfg = getSupabaseAuthConfigFromEnv();
    if (!cfg) return;
    const safeRedirect = resolvePasswordResetRedirectTo(redirectTo, request);
    try {
        const payload: Record<string, unknown> = { email };
        if (safeRedirect) payload.redirect_to = safeRedirect;
        await fetch(`${cfg.url}/auth/v1/recover`, {
            method: 'POST',
            headers: {
                apikey: cfg.key,
                'Content-Type': 'application/json',
            },
            body: JSON.stringify(payload),
        });
    } catch {
        /* generic */
    }
}

/**
 * POST /api/auth/otp/request — رمز تحقق بعد التأكد أن البريد مسجّل.
 * واتساب غير المضبوط يُرفض كإعداد خادم. غياب الحساب يُعلن صراحة بطلب المستخدم.
 */
export async function POST(request: Request): Promise<Response> {
    const ip = readAuthOtpClientIp(request);
    if (
        !(await consumeRateLimitSlot(ip, {
            scope: 'auth-otp-request-ip',
            maxRequests: MAX_PER_IP,
            windowMs: WINDOW_MS,
            fallbackToMemory: true,
        }))
    ) {
        return authOtpJson(429, { ok: false, error: 'تجاوزت حد الطلبات — حاول لاحقاً' });
    }

    let email = '';
    let channelRaw: unknown = '';
    let purposeRaw: unknown = '';
    let redirectTo = '';
    try {
        const body = (await request.json()) as {
            email?: unknown;
            channel?: unknown;
            purpose?: unknown;
            redirectTo?: unknown;
        };
        email = typeof body.email === 'string' ? normalizeRegistrationEmail(body.email) : '';
        channelRaw = body.channel;
        purposeRaw = body.purpose;
        redirectTo = typeof body.redirectTo === 'string' ? body.redirectTo.trim() : '';
    } catch {
        return authOtpJson(400, { ok: false, error: 'Invalid JSON body' });
    }

    const shape = validateRecoveryEmailShape(email);
    if (shape) return authOtpJson(400, { ok: false, error: shape });
    if (!isAuthOtpChannel(channelRaw) || !isAuthOtpPurpose(purposeRaw)) {
        return authOtpJson(400, { ok: false, error: 'قناة أو غرض غير صالح' });
    }

    if (!(await emailDomainAcceptsMail(email))) {
        return authOtpJson(400, { ok: false, error: AUTH_OTP_MAILBOX_UNREAL_AR });
    }

    const emailAllowed = await consumeRateLimitSlot(email, {
        scope: `auth-otp-request-${purposeRaw}`,
        maxRequests: MAX_PER_EMAIL,
        windowMs: WINDOW_MS,
        fallbackToMemory: true,
    });
    if (!emailAllowed) {
        return authOtpJson(429, { ok: false, error: 'تجاوزت حد الطلبات — حاول لاحقاً' });
    }

    const account = await lookupAuthOtpAccountByEmail(email);
    if (!account) {
        return authOtpJson(404, { ok: false, error: AUTH_OTP_ACCOUNT_MISSING_AR });
    }

    const phoneTail = phoneLastTwoDigits(account.phone);

    if (channelRaw === 'whatsapp' && !isAuthOtpWhatsAppChannelReady()) {
        return authOtpJson(503, { ok: false, error: AUTH_OTP_WHATSAPP_UNCONFIGURED_AR });
    }
    if (channelRaw === 'whatsapp' && !phoneTail) {
        return authOtpJson(400, { ok: false, error: AUTH_OTP_NO_PHONE_AR });
    }

    if (channelRaw === 'email' && !isAuthOtpEmailChannelReady()) {
        if (purposeRaw === 'password_reset') {
            await sendGoTrueRecover(account.email, redirectTo, request);
            return authOtpJson(200, {
                ok: true,
                delivery: 'link',
                resendAfterSec: AUTH_OTP_RESEND_SEC,
                phoneTail,
                message: 'أُرسل رابط استعادة كلمة المرور إلى بريدك.',
            });
        }
        return authOtpJson(503, {
            ok: false,
            error: 'إرسال رمز البريد غير مضبوط على الخادم. استخدم رابط التأكيد أو تواصل مع الإدارة.',
        });
    }

    const created = await createAuthOtpChallenge({
        userId: account.userId,
        purpose: purposeRaw,
        channel: channelRaw,
        requestIp: ip === 'unknown' ? null : ip,
    });
    if ('error' in created) {
        return authOtpJson(503, { ok: false, error: created.error });
    }
    const delivered = await deliverAuthOtp({
        channel: channelRaw,
        email: account.email,
        phone: account.phone,
        code: created.code,
        purpose: purposeRaw,
    });
    if (!delivered.ok) {
        if (
            channelRaw === 'email' &&
            purposeRaw === 'password_reset' &&
            isResendTestSenderRestriction(delivered.error)
        ) {
            await sendGoTrueRecover(account.email, redirectTo, request);
            return authOtpJson(200, {
                ok: true,
                delivery: 'link',
                resendAfterSec: AUTH_OTP_RESEND_SEC,
                phoneTail,
                message:
                    'تعذّر إرسال الرمز القصير من المرسل التجريبي إلى هذا البريد (وليس لأن الاستعادة لحساب المدير فقط). أُرسل رابط استعادة إلى صندوقك. افتحه وعيّن كلمة المرور الجديدة.',
            });
        }
        return authOtpJson(503, {
            ok: false,
            error: authOtpDeliverErrorAr(delivered.error),
        });
    }

    return authOtpJson(200, {
        ok: true,
        delivery: 'otp',
        resendAfterSec: AUTH_OTP_RESEND_SEC,
        phoneTail,
        message: authOtpSentMessage(channelRaw, phoneTail),
    });
}

import { normalizeIraqiPhoneInput } from '../../../services/auth/registrationCredentialsSecurity.ts';

/** MSISDN واتساب العراقي بدون + — 9647xxxxxxxx */
export function toIraqWhatsAppMsisdn(raw: string | null | undefined): string | null {
    if (!raw) return null;
    const local = normalizeIraqiPhoneInput(raw);
    if (!/^07[5789]\d{8}$/.test(local)) return null;
    return `964${local.slice(1)}`;
}

/** آخر رقمين فقط — لا يُكشف الرقم كاملاً */
export function phoneLastTwoDigits(raw: string | null | undefined): string | null {
    const msisdn = toIraqWhatsAppMsisdn(raw);
    if (!msisdn || msisdn.length < 2) return null;
    return msisdn.slice(-2);
}

/**
 * حمولات قالب واتساب لرمز لمرة واحدة.
 * قوالب AUTHENTICATION (copy-code) تحتاج الرمز في الجسم وفي زر URL.
 * قوالب UTILITY بجسم {{1}} فقط ترفض مكوّن الزر — نُجرّب الاثنين بالترتيب.
 */

export type WhatsAppOtpTemplateKind = 'authentication' | 'body_only';

export function buildWhatsAppOtpTemplatePayload(input: {
    toMsisdn: string;
    code: string;
    template: string;
    lang: string;
    kind: WhatsAppOtpTemplateKind;
}): Record<string, unknown> {
    const body = {
        type: 'body',
        parameters: [{ type: 'text', text: input.code }],
    };
    const components =
        input.kind === 'authentication'
            ? [
                  body,
                  {
                      type: 'button',
                      sub_type: 'url',
                      index: '0',
                      parameters: [{ type: 'text', text: input.code }],
                  },
              ]
            : [body];

    return {
        messaging_product: 'whatsapp',
        recipient_type: 'individual',
        to: input.toMsisdn,
        type: 'template',
        template: {
            name: input.template,
            language: { code: input.lang },
            components,
        },
    };
}

import { beforeEach, describe, expect, it, vi } from 'vitest';
import { resolvePasswordResetRedirectTo } from './passwordResetRedirectAllowlist.ts';

function req(origin?: string): Request {
    const request = new Request('https://app.hami.legal/api/auth/forgot-password', {
        method: 'POST',
        headers: origin ? { origin } : {},
    });
    if (origin && !request.headers.get('origin')) {
        vi.spyOn(request.headers, 'get').mockImplementation((name: string) =>
            name.toLowerCase() === 'origin' ? origin : null,
        );
    }
    return request;
}

describe('passwordResetRedirectAllowlist', () => {
    beforeEach(() => {
        delete process.env.PASSWORD_RESET_ALLOWED_ORIGINS;
        delete process.env.PUBLIC_APP_URL;
        delete process.env.SITE_URL;
    });

    it('rejects attacker-controlled https origins', () => {
        expect(
            resolvePasswordResetRedirectTo('https://evil.example/steal', req('https://app.hami.legal')),
        ).toBe('');
    });

    it('allows hami.legal https origins', () => {
        expect(
            resolvePasswordResetRedirectTo('https://app.hami.legal/reset', req()),
        ).toBe('https://app.hami.legal/reset');
    });

    it('allows capacitor deep link schemes', () => {
        expect(resolvePasswordResetRedirectTo('iq.hami.legal://auth/reset', req())).toBe(
            'iq.hami.legal://auth/reset',
        );
    });

    it('falls back to request origin when redirect empty', () => {
        expect(resolvePasswordResetRedirectTo('', req('https://app.hami.legal'))).toBe(
            'https://app.hami.legal',
        );
    });

    it('ignores evil origin header', () => {
        expect(resolvePasswordResetRedirectTo('', req('https://evil.example'))).toBe('');
    });
});

/**
 * Allowlist لـ redirect_to في استعادة كلمة المرور — يمنع سرقة الرابط عبر origin خبيث.
 */

const DEFAULT_HOST_SUFFIXES = ['hami.legal', 'localhost', '127.0.0.1'] as const;

function parseOrigin(raw: string): URL | null {
    try {
        const u = new URL(raw);
        if (u.protocol !== 'https:' && u.protocol !== 'http:') return null;
        return u;
    } catch {
        return null;
    }
}

function envAllowlist(): string[] {
    const raw =
        process.env.PASSWORD_RESET_ALLOWED_ORIGINS ??
        process.env.PUBLIC_APP_URL ??
        process.env.SITE_URL ??
        '';
    return raw
        .split(/[,;\s]+/)
        .map((s) => s.trim())
        .filter(Boolean);
}

function hostAllowed(hostname: string): boolean {
    const host = hostname.toLowerCase();
    if (host === 'localhost' || host === '127.0.0.1') return true;
    for (const suffix of DEFAULT_HOST_SUFFIXES) {
        if (host === suffix || host.endsWith(`.${suffix}`)) return true;
    }
    for (const entry of envAllowlist()) {
        const u = parseOrigin(entry) ?? (() => {
            try {
                return new URL(`https://${entry}`);
            } catch {
                return null;
            }
        })();
        if (!u) continue;
        if (host === u.hostname.toLowerCase()) return true;
    }
    return false;
}

/** Capacitor / deep-link schemes المسموحة فقط */
function isAllowedAppScheme(raw: string): boolean {
    const lower = raw.toLowerCase();
    return (
        lower.startsWith('iq.hami.legal://') ||
        lower.startsWith('com.hami.app://') ||
        lower.startsWith('hami://')
    );
}

/**
 * يُرجع redirect آمناً أو سلسلة فارغة (تجاهل غير المسموح بدل تمريره).
 * إن وُجد Origin للطلب ومطابق للقائمة يُفضَّل origin الطلب عند غياب redirect.
 */
export function resolvePasswordResetRedirectTo(
    requested: string,
    request: Request,
): string {
    const trimmed = requested.trim();
    if (trimmed) {
        if (isAllowedAppScheme(trimmed)) return trimmed;
        const u = parseOrigin(trimmed);
        if (u && hostAllowed(u.hostname)) {
            return u.origin + (u.pathname === '/' ? '' : u.pathname) + u.search;
        }
        return '';
    }

    const originHeader = request.headers.get('origin')?.trim() ?? '';
    if (originHeader) {
        const u = parseOrigin(originHeader);
        if (u && hostAllowed(u.hostname)) return u.origin;
        return '';
    }

    const fromEnv = envAllowlist()[0];
    if (fromEnv) {
        const u = parseOrigin(fromEnv);
        if (u && hostAllowed(u.hostname)) return u.origin;
    }
    return '';
}

import { readSupabasePrivilegedKey } from '../security/supabasePrivilegedEnv.ts';

export const SIGNUP_MAIL_RATE_LIMIT_AR =
    'تعذّر إكمال التسجيل لأن حد رسائل Auth ممتلئ. انتظر نحو ساعة ثم أعد المحاولة مرة واحدة.';

export const SIGNUP_DUPLICATE_AR =
    'هذا البريد مسجّل مسبقاً — سجّل الدخول أو استخدم استعادة كلمة المرور';

export type LawyerGoTrueProvision =
    | {
          ok: true;
          user: Record<string, unknown>;
          access_token?: string;
          refresh_token?: string;
          expires_in?: number;
      }
    | {
          ok: false;
          status: 400 | 409 | 429 | 503;
          code: 'EMAIL_ALREADY_REGISTERED' | 'SIGNUP_FAILED' | 'EMAIL_RATE_LIMIT' | 'AUTH_UNAVAILABLE';
          error: string;
      };

type GoTrueBody = {
    access_token?: string;
    refresh_token?: string;
    expires_in?: number;
    user?: Record<string, unknown>;
    id?: string;
    email?: string;
    error_description?: string;
    msg?: string;
    message?: string;
    error?: string;
    error_code?: string;
    code?: string;
};

function readGoTrueMessage(data: GoTrueBody, fallback: string): string {
    for (const value of [data.error_description, data.msg, data.message, data.error]) {
        if (typeof value === 'string' && value.trim()) return value.trim();
    }
    return fallback;
}

function isDuplicateIdentity(message: string, status: number): boolean {
    return (
        status === 422 ||
        /already\s+registered|already\s+exists|duplicate|user.?exists|email_exists/i.test(message)
    );
}

function isEmailRateLimit(message: string, status: number, code?: string): boolean {
    if (status === 429) return true;
    if ((code ?? '').toLowerCase() === 'over_email_send_rate_limit') return true;
    return /rate limit|too many requests/i.test(message);
}

function failFromGoTrue(data: GoTrueBody, status: number): Extract<LawyerGoTrueProvision, { ok: false }> {
    const message = readGoTrueMessage(data, 'Signup failed');
    const code = data.error_code ?? data.code;
    if (isEmailRateLimit(message, status, code)) {
        return {
            ok: false,
            status: 429,
            code: 'EMAIL_RATE_LIMIT',
            error: SIGNUP_MAIL_RATE_LIMIT_AR,
        };
    }
    if (isDuplicateIdentity(message, status)) {
        return {
            ok: false,
            status: 409,
            code: 'EMAIL_ALREADY_REGISTERED',
            error: SIGNUP_DUPLICATE_AR,
        };
    }
    return {
        ok: false,
        status: status === 503 ? 503 : 400,
        code: status === 503 ? 'AUTH_UNAVAILABLE' : 'SIGNUP_FAILED',
        error: status === 503 ? 'Auth service unavailable' : 'Signup failed',
    };
}

function userFromAdminPayload(data: GoTrueBody): Record<string, unknown> | null {
    if (data.user && typeof data.user === 'object') return data.user;
    if (typeof data.id === 'string' && data.id.trim()) {
        return { id: data.id.trim(), email: data.email };
    }
    return null;
}

async function grantPasswordSession(
    url: string,
    anonKey: string,
    email: string,
    password: string,
): Promise<Pick<GoTrueBody, 'access_token' | 'refresh_token' | 'expires_in' | 'user'>> {
    const res = await fetch(`${url}/auth/v1/token?grant_type=password`, {
        method: 'POST',
        headers: {
            apikey: anonKey,
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({ email, password }),
    });
    if (!res.ok) return {};
    return (await res.json()) as GoTrueBody;
}

async function provisionViaAdmin(
    url: string,
    serviceKey: string,
    anonKey: string,
    email: string,
    password: string,
    meta: Record<string, unknown>,
): Promise<LawyerGoTrueProvision> {
    const res = await fetch(`${url}/auth/v1/admin/users`, {
        method: 'POST',
        headers: {
            apikey: serviceKey,
            Authorization: `Bearer ${serviceKey}`,
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            email,
            password,
            email_confirm: true,
            user_metadata: meta,
        }),
    });
    const data = (await res.json().catch(() => ({}))) as GoTrueBody;
    if (!res.ok) return failFromGoTrue(data, res.status);

    const user = userFromAdminPayload(data);
    if (!user) {
        return { ok: false, status: 400, code: 'SIGNUP_FAILED', error: 'Signup failed' };
    }

    const session = await grantPasswordSession(url, anonKey, email, password);
    return {
        ok: true,
        user: session.user ?? user,
        access_token: session.access_token,
        refresh_token: session.refresh_token,
        expires_in: session.expires_in,
    };
}

async function provisionViaPublicSignup(
    url: string,
    anonKey: string,
    email: string,
    password: string,
    meta: Record<string, unknown>,
): Promise<LawyerGoTrueProvision> {
    const res = await fetch(`${url}/auth/v1/signup`, {
        method: 'POST',
        headers: {
            apikey: anonKey,
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            email,
            password,
            data: meta,
        }),
    });
    const data = (await res.json().catch(() => ({}))) as GoTrueBody;
    if (!res.ok) return failFromGoTrue(data, res.status);
    return {
        ok: true,
        user: data.user ?? {},
        access_token: data.access_token,
        refresh_token: data.refresh_token,
        expires_in: data.expires_in,
    };
}

/**
 * إنشاء محامٍ عبر Admin API مع تأكيد البريد داخل الخادم — بلا رسالة Confirmation
 * حتى لا يشارك حصة بريد Auth مع رمز مقر القيادة.
 * إن غاب مفتاح الخدمة نرجع لمسار signup العام.
 */
export async function provisionLawyerGoTrueAccount(args: {
    url: string;
    anonKey: string;
    email: string;
    password: string;
    meta: Record<string, unknown>;
}): Promise<LawyerGoTrueProvision> {
    const serviceKey = readSupabasePrivilegedKey();
    try {
        if (serviceKey) {
            return await provisionViaAdmin(
                args.url,
                serviceKey,
                args.anonKey,
                args.email,
                args.password,
                args.meta,
            );
        }
        return await provisionViaPublicSignup(
            args.url,
            args.anonKey,
            args.email,
            args.password,
            args.meta,
        );
    } catch {
        return {
            ok: false,
            status: 503,
            code: 'AUTH_UNAVAILABLE',
            error: 'Auth service unavailable',
        };
    }
}

