                    const admin = await loadForumSupabaseAdmin();
                    if (!admin) return;
                    const { data } = await admin
                        .from('forum_comments')
                        .select('author_id, content, post_id')
                        .eq('id', commentId)
                        .maybeSingle();
                    if (!data) return;
                    const row = data as { author_id: string; content: string; post_id: string };
