    }

    return jsonResponse(200, { ok: true, action: payload.action });
  } catch {
    return jsonResponse(500, { ok: false, error: 'Internal server error' });
  }
}

import { requireForumAuth, jsonResponse } from '../../_auth.ts';
import { applyWifeSecurityHeaders } from '../../../security/wifeSecurityHeaders.ts';
import { ServerNotificationDB } from '../../../../services/notifications/notificationForumStorage.server.ts';



const POLL_MS_MIN = 2_000;

const POLL_MS_MAX = 10_000;

const MAX_DURATION_MS = 55_000;



function resolveLastEventId(request: Request): string {

    const header = request.headers.get('Last-Event-ID')?.trim();

    if (header) return header;

    const url = new URL(request.url);

    return url.searchParams.get('lastEventId')?.trim() ?? '';

}



function nextPollDelayMs(stableTicks: number, currentMs: number): number {

    if (stableTicks < 2) return POLL_MS_MIN;

    return Math.min(POLL_MS_MAX, currentMs * 2);

}



export async function GET(request: Request): Promise<Response> {

    try {

        const auth = await requireForumAuth(request);
        if ('response' in auth) return auth.response;
        const { userId } = auth;



        const encoder = new TextEncoder();

        const startedAt = Date.now();

        let lastSentEventId = resolveLastEventId(request);

        let pollDelayMs = POLL_MS_MIN;

        let stableTicks = 0;

        let timeoutId: ReturnType<typeof setTimeout> | null = null;



        const stream = new ReadableStream<Uint8Array>({

            async start(controller) {

                const send = (payload: Record<string, unknown>, eventId?: string | null) => {

                    if (eventId) {

                        controller.enqueue(encoder.encode(`id: ${eventId}\n`));

                        lastSentEventId = eventId;

                    }

                    controller.enqueue(encoder.encode(`data: ${JSON.stringify(payload)}\n\n`));

                };



                const tick = async (): Promise<boolean> => {

                    if (request.signal.aborted || Date.now() - startedAt > MAX_DURATION_MS) {

                        return false;

                    }



                    const notifications = await ServerNotificationDB.getNotifications(userId);

                    const unreadCount = await ServerNotificationDB.getUnreadCount(userId);

                    const latest = notifications[0] ?? null;

                    const latestId = latest?.id ?? null;



                    if (latestId && latestId !== lastSentEventId) {

                        stableTicks = 0;

                        pollDelayMs = POLL_MS_MIN;

                        send(

                            {

                                type: 'notification',

                                unreadCount,

                                latestId,

                                notification: latest,

                            },

                            latestId,

                        );

                    } else if (lastSentEventId === '' && latest) {

                        stableTicks = 0;

                        pollDelayMs = POLL_MS_MIN;

                        send(

                            {

                                type: 'snapshot',

                                unreadCount,

                                latestId,

                                notification: latest,

                            },

                            latestId,

                        );

                    } else {

                        stableTicks += 1;

                        pollDelayMs = nextPollDelayMs(stableTicks, pollDelayMs);

                    }



                    return true;

                };



                send({

                    type: 'connected',

                    unreadCount: await ServerNotificationDB.getUnreadCount(userId),

                });



                const loop = async () => {

                    const cont = await tick();

                    if (!cont) {

                        if (timeoutId) clearTimeout(timeoutId);

                        try {

                            controller.close();

                        } catch {

                            /* closed */

                        }

                        return;

                    }

                    timeoutId = setTimeout(() => void loop(), pollDelayMs);

                };

                timeoutId = setTimeout(() => void loop(), pollDelayMs);



                request.signal.addEventListener('abort', () => {

                    if (timeoutId) clearTimeout(timeoutId);

                    try {

                        controller.close();

                    } catch {

                        /* closed */

                    }

                });

            },

        });



        return applyWifeSecurityHeaders(new Response(stream, {

            status: 200,

            headers: {

                'Content-Type': 'text/event-stream; charset=utf-8',

                'Cache-Control': 'no-cache, no-transform',

                Connection: 'keep-alive',

            },

        }));

    } catch {

        return jsonResponse(500, { ok: false, error: 'Internal server error' });

    }

}

import { sanitizePayload } from '../../security/sanitizer.ts';
import { ForumRepository } from '../../../services/forum/forumRepository.ts';
import { checkForumActionRateLimit } from '../../../services/forum/forumRateLimitServer.ts';
import { redactAnonymousAuthor } from '../../../services/forum/forumMapper.ts';
import { assertForumPostGroupAccess } from '../../../services/forum/forumGroupMutationGate.ts';
import { requireForumAuthAndUnbanned, jsonResponse, forumCatchJsonResponse } from '../_auth.ts';

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value) && typeof value === 'object';
}

export async function POST(request: Request): Promise<Response> {
    try {
        const auth = await requireForumAuthAndUnbanned(request);
        if ('response' in auth) {
            return auth.response;
        }

        if (!auth.isAdmin) {
            return jsonResponse(403, { ok: false, error: 'غير مصرح لك' });
        }

        if (!(await checkForumActionRateLimit(auth.userId, 'pin'))) {
            return jsonResponse(429, { ok: false, error: 'تجاوزت حد التثبيت، انتظر قليلاً' });
        }

        const payload = sanitizePayload(await request.json());
        if (!isRecord(payload) || typeof payload.postId !== 'string' || typeof payload.pinned !== 'boolean') {
            return jsonResponse(400, { ok: false, error: 'postId و pinned مطلوبان' });
        }

        const postId = payload.postId.trim();
        if (!postId) {
            return jsonResponse(400, { ok: false, error: 'postId و pinned مطلوبان' });
        }

        const existing = await ForumRepository.getPostById(postId);
        if (!existing) {
            return jsonResponse(404, { ok: false, error: 'المنشور غير موجود' });
        }
        await assertForumPostGroupAccess(existing, auth.userId, auth.isAdmin);

        const updated = await ForumRepository.togglePin(postId, payload.pinned);

        return jsonResponse(200, {
            ok: true,
            action: 'toggle_pin',
            postId,
            pinned: payload.pinned,
            post: redactAnonymousAuthor(updated, auth.userId, auth.isAdmin),
        });
    } catch (err) {
        return forumCatchJsonResponse(err);
    }
}

