            const rows = table === 'lawsuit_files' ? lawsuits : executions;
            const error = table === 'lawsuit_files' ? lawsuitError : execError;
            return {
                select() {
                    return {
                        eq() {
                            return {
                                limit: async () => ({ data: error ? null : rows, error }),
                            };
                        },
                    };
                },
            };
        },
    } as unknown as SupabaseClient;
}

