    return (
        `تم تجميد حسابك${until}. المنتدى والخدمات الشبكية موقوفة. ` +
        'يمكنك متابعة أعمالك المحلية في الدعاوى والمعاملات — لم تُحذف ولم تُمس.'
    );
}

export function accountUnfrozenUserMessage(): string {
