import {
  extractUserTokenFromRequest,
  getVerifiedTokenIdentity,
  verifyWifeSignatureStatus,
  wifeRateLimitedResponse,
  wifeSignatureFailedResponse,
  wifeUnauthorizedResponse,
  wifeAccountLockedResponse,
  wifeAccountFrozenResponse,
} from './wifeValidator.ts';
import { getWifeUserRestrictionLive } from './wifeUserStatus.ts';
import { accountFrozenUserMessage, accountLoginDeniedPayload, formatAccountUntilLabel } from './accountRestrictionCopy.ts';
import { isPlatformAdminUserId } from './roleResolver.ts';

export type WifeAuthOk = { ok: true; userId: string };
export type WifeAuthFail = { ok: false; response: Response };
export type WifeAuthResult = WifeAuthOk | WifeAuthFail;

export type RequireWifeUserOptions = {
  /** بوابة الشبكة تحتاج هوية صالحة حتى تعيد رسالة القفل لا 401 عام */
  allowLoginLocked?: boolean;
  /** الكتابة السحابية/المزامنة — التجميد يوقفها مع بقاء صندوق الإشعارات */
  rejectFrozen?: boolean;
};

export function wifeAuthDenied(auth: WifeAuthResult): Response | null {
  if (auth.ok === false) return auth.response;
  return null;
}

/** بعد فحص wifeAuthDenied — يُرجع userId أو Response للإرجاع المباشر. */
export function unwrapWifeUser(
  auth: WifeAuthResult,
): { userId: string } | { response: Response } {
  if (auth.ok === false) return { response: auth.response };
  return { userId: auth.userId };
}

export async function requireWifeUser(
  request: Request,
  options: RequireWifeUserOptions = {},
): Promise<WifeAuthResult> {
  const userToken = extractUserTokenFromRequest(request);
  if (!userToken) {
    return {
      ok: false as const,
      response: wifeUnauthorizedResponse({ request, reason: 'unauthorized_token' }),
    };
  }
  const userId = await getVerifiedTokenIdentity(userToken);
  if (!userId) {
    return {
      ok: false as const,
      response: wifeUnauthorizedResponse({ request, reason: 'unauthorized_token' }),
    };
  }
  const signatureStatus = await verifyWifeSignatureStatus(request, userToken);
  if (signatureStatus === 'rate_limited') {
    return {
      ok: false as const,
      response: wifeRateLimitedResponse({ request, reason: 'rate_limited' }),
    };
  }
  if (signatureStatus !== 'valid') {
    return {
      ok: false as const,
      response: wifeSignatureFailedResponse(request),
    };
  }
  if (!(await isPlatformAdminUserId(userId))) {
    const restriction = await getWifeUserRestrictionLive(userId);
    if (!options.allowLoginLocked && !restriction.loginAllowed) {
      const denied = accountLoginDeniedPayload(restriction);
      return {
        ok: false as const,
        response: wifeAccountLockedResponse({
          request,
          reason: 'account_locked',
          userId,
          message: denied.error,
        }),
      };
    }
    if (options.rejectFrozen && restriction.frozen) {
      const until = formatAccountUntilLabel(restriction.freezeUntil);
      return {
        ok: false as const,
        response: wifeAccountFrozenResponse({
          request,
          reason: 'account_frozen',
          userId,
          message: accountFrozenUserMessage(until || undefined),
        }),
      };
    }
  }
  return { ok: true as const, userId };
}

/** كتابة سحابية — التجميد يُرفض هنا؛ صندوق الإشعارات يبقى عبر requireWifeUser. */
export async function requireWifeCloudWrite(request: Request): Promise<WifeAuthResult> {
  return requireWifeUser(request, { rejectFrozen: true });
}

/**
 * Single source of truth for Content-Security-Policy (WIFE / Hami).
 * Dev: relaxed for Vite HMR. Production: strict — no unsafe-eval, no inline scripts.
 */

export type CspMode = 'development' | 'production' | 'e2e-preview';

export function buildContentSecurityPolicy(mode: CspMode): string {
  const isDev = mode === 'development';
  const isE2ePreview = mode === 'e2e-preview';

  const connectSrc = [
    "'self'",
    'blob:',
    'data:',
    'https://*.supabase.co',
    'wss://*.supabase.co',
    'https://sentry.io',
    'https://*.ingest.sentry.io',
    'https://*.ingest.us.sentry.io',
  ];
  if (isDev || isE2ePreview) {
    connectSrc.push('http://localhost:*', 'http://127.0.0.1:*', 'ws://localhost:*', 'ws://127.0.0.1:*');
  }

  const scriptSrc = isDev
    ? ["'self'", "'unsafe-inline'", "'unsafe-eval'", 'https://js.sentry-cdn.com']
    : ["'self'", 'https://js.sentry-cdn.com'];

  return [
    "default-src 'self'",
    `script-src ${scriptSrc.join(' ')}`,
    "script-src-attr 'none'",
    "style-src 'self' 'unsafe-inline' https://fonts.googleapis.com",
    "font-src 'self' https://fonts.gstatic.com data:",
    "img-src 'self' data: https: blob:",
    `connect-src ${connectSrc.join(' ')}`,
    "frame-src 'none'",
    "frame-ancestors 'none'",
    "base-uri 'self'",
    "form-action 'self'",
    "object-src 'none'",
    /* عامل pdf.js يُشحن معنا — لا أصل خارجي يُنفِّذ شيفرة فوق مستندات الموكّلين */
    "worker-src 'self' blob:",
    ...(isDev || isE2ePreview ? [] : ['upgrade-insecure-requests']),
  ].join('; ');
}

export function resolveCspMode(nodeEnv?: string, viteMode?: string): CspMode {
  const env = (nodeEnv ?? process.env.NODE_ENV ?? '').toLowerCase();
  const mode = (viteMode ?? '').toLowerCase();
  if (env === 'development' || mode === 'development') return 'development';
  return 'production';
}

/**
 * Server-side derivation of in-memory crypto wrap credential for BFF auth.
 * لا يُرسل JWT — فقط مادة اشتقاق مرتبطة بالجلسة تُخزَّن في RAM على العميل.
 */
function toBase64Url(data: Uint8Array): string {
  const binary = Array.from(data, (b) => String.fromCharCode(b)).join('');
  const base64 = btoa(binary);
  return base64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/g, '');
}

async function sha256Bytes(input: string): Promise<Uint8Array> {
  const bytes = new TextEncoder().encode(input);
  const digest = await crypto.subtle.digest('SHA-256', bytes);
  return new Uint8Array(digest);
}

export async function deriveClientCryptoWrapCredential(accessToken: string): Promise<string> {
  const token = accessToken.trim();
  if (!token) return '';
  const hash = await sha256Bytes(`${token}:hami-crypto-wrap-v1`);
  return `bff:${toBase64Url(hash)}`;
}

/**
 * HttpOnly CSRF Set-Cookie builders — single source for API routes.
 */
import { CSRF_COOKIE_NAME } from '@/app/security/csrfConstants';

export { CSRF_COOKIE_NAME };

export function isSecureRequest(request: Request): boolean {
  return (
    request.url.startsWith('https://') ||
    (request.headers.get('x-forwarded-proto') ?? '').toLowerCase() === 'https'
  );
}

export function buildCsrfSetCookie(token: string, secure: boolean): string {
  const flags = [`${CSRF_COOKIE_NAME}=${encodeURIComponent(token)}`, 'Path=/', 'SameSite=Strict', 'Max-Age=86400'];
  if (secure) flags.push('Secure');
  flags.push('HttpOnly');
  return flags.join('; ');
}

export function buildCsrfClearCookie(secure: boolean): string {
  const flags = [`${CSRF_COOKIE_NAME}=`, 'Path=/', 'SameSite=Strict', 'Max-Age=0'];
  if (secure) flags.push('Secure');
  flags.push('HttpOnly');
  return flags.join('; ');
}

