    return hay.includes('legal_display_name') && (hay.includes('does not exist') || hay.includes('schema cache'));
}

function asText(raw: unknown): string {
    return String(raw ?? '').trim();
}

function asIso(raw: unknown): string | null {
    const text = asText(raw);
    if (!text) return null;
    const at = Date.parse(text);
    return Number.isFinite(at) ? new Date(at).toISOString() : null;
}

function policyFromRow(row: NameRow | null, fallbackName: string): DisplayNamePolicy {
    const fullName = normalizeLegalDisplayName(row?.legal_display_name) || normalizeLegalDisplayName(fallbackName);
    return toDisplayNamePolicy({
        fullName,
        previousFullName: asText(row?.previous_legal_display_name) || null,
        correctedAt: asIso(row?.legal_display_name_corrected_at),
        corrections: Number(row?.legal_display_name_corrections ?? 0),
    });
}

export async function readDisplayNamePolicy(userId: string): Promise<DisplayNamePolicy | null> {
    const id = userId.trim();
    if (!isPostgresUuidSubject(id)) return null;
    const admin = getSupabaseAdminClient();
    if (!admin) return null;
    const fallback = await readAuthFullName(admin, id);
    const { data, error } = await admin
        .from('profiles')
        .select(
            'legal_display_name, previous_legal_display_name, legal_display_name_corrections, legal_display_name_corrected_at',
        )
        .eq('id', id)
        .maybeSingle();
    if (error) {
        if (isMissingDisplayNameColumn(error.message ?? '')) {
            return toDisplayNamePolicy({ fullName: fallback, corrections: 0 });
        }
        return toDisplayNamePolicy({ fullName: fallback, corrections: 0 });
    }
    return policyFromRow((data ?? null) as NameRow | null, fallback);
}

async function readAuthFullName(admin: SupabaseClient, userId: string): Promise<string> {
    try {
        const { data } = await getGoTrueAdminApi(admin).getUserById(userId);
        const meta =
            data?.user?.user_metadata && typeof data.user.user_metadata === 'object'
                ? (data.user.user_metadata as Record<string, unknown>)
                : {};
        return normalizeLegalDisplayName(meta.fullName ?? meta.full_name);
    } catch {
        return '';
    }
}

export async function applyCanonicalDisplayNameToProfileValue(
    userId: string,
    value: unknown,
): Promise<unknown> {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return value;
    const rec = value as Record<string, unknown>;
    const header = rec.header;
    if (!header || typeof header !== 'object' || Array.isArray(header)) return value;
    const policy = await readDisplayNamePolicy(userId);
    const canonical = policy?.fullName?.trim() ?? '';
    if (!canonical) return value;
    return {
        ...rec,
        header: { ...(header as Record<string, unknown>), name: canonical },
    };
}

export type CorrectDisplayNameResult =
    | { ok: true; policy: DisplayNamePolicy }
    | { ok: false; status: 400 | 409 | 503; error: string };

export async function correctDisplayNameOnce(
    userId: string,
    requestedName: string,
): Promise<CorrectDisplayNameResult> {
    const id = userId.trim();
    if (!isPostgresUuidSubject(id)) {
        return { ok: false, status: 400, error: 'معرّف غير صالح' };
    }
    const next = normalizeLegalDisplayName(requestedName);
    if (next.length < 3) {
        return { ok: false, status: 400, error: 'الاسم الثلاثي مطلوب' };
    }
    const admin = getSupabaseAdminClient();
    if (!admin) {
        return { ok: false, status: 503, error: 'تعذّر حفظ الاسم' };
    }

    const current = await readDisplayNamePolicy(id);
    if (!current) {
        return { ok: false, status: 503, error: 'تعذّر قراءة الاسم' };
    }
    if (current.fullName === next) {
        return { ok: true, policy: current };
    }
    if (!current.canCorrect) {
        return { ok: false, status: 409, error: 'يمكن تصحيح الاسم مرة واحدة فقط' };
    }

    try {
        const { data } = await getGoTrueAdminApi(admin).getUserById(id);
        const meta =
            data?.user?.user_metadata && typeof data.user.user_metadata === 'object'
                ? { ...(data.user.user_metadata as Record<string, unknown>) }
                : {};
        const { error } = await getGoTrueAdminApi(admin).updateUserById(id, {
            user_metadata: { ...meta, fullName: next },
        });
        if (error) {
            return { ok: false, status: 503, error: 'تعذّر حفظ الاسم' };
        }
    } catch {
        return { ok: false, status: 503, error: 'تعذّر حفظ الاسم' };
    }

    const after = await readDisplayNamePolicy(id);
    if (!after || after.fullName !== next) {
        return { ok: false, status: 409, error: 'يمكن تصحيح الاسم مرة واحدة فقط' };
    }
    return { ok: true, policy: after };
}

import { createHash, createHmac, timingSafeEqual } from 'node:crypto';

const SHA256_HEX = /^[0-9a-f]{64}$/i;

/** SHA-256 UTF-8 hex — يطابق CryptoService.generateDataSignature على العميل */
export function sha256HexUtf8(value: string): string {
    return createHash('sha256').update(value, 'utf8').digest('hex');
}

function dossierPayloadMacSecret(): string {
    return String(process.env.HAMI_DOSSIER_PAYLOAD_MAC_SECRET ?? '').trim();
}

/** إنتاج Vercel أو HAMI_DOSSIER_PAYLOAD_MAC_ENFORCE — صف بلا MAC يُرفض عند وجود السر */
export function dossierPayloadMacEnforced(): boolean {
    if (!dossierPayloadMacSecret()) return false;
    const flag = String(process.env.HAMI_DOSSIER_PAYLOAD_MAC_ENFORCE ?? '').trim().toLowerCase();
    if (flag === '1' || flag === 'true' || flag === 'yes') return true;
    return String(process.env.VERCEL_ENV ?? '').trim().toLowerCase() === 'production';
}

/** HMAC-SHA256 hex إن وُجد سر الخادم — يكتشف عبث الصف خارج BFF */
export function computeDossierPayloadMac(encryptedData: string): string | null {
    const secret = dossierPayloadMacSecret();
    if (!secret) return null;
    return createHmac('sha256', secret).update(encryptedData, 'utf8').digest('hex');
}

export function dossierPayloadMacMatches(encryptedData: string, payloadMac: string): boolean {
    const expected = computeDossierPayloadMac(encryptedData);
    const got = String(payloadMac ?? '').trim().toLowerCase();
    if (!expected || !SHA256_HEX.test(got) || !SHA256_HEX.test(expected)) return false;
    try {
        return timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(got, 'hex'));
    } catch {
        return false;
    }
}

/**
 * صف بلا MAC: يُقبل إن لم يُفرض التحقق. صف له MAC لا يطابق السر يُستبعد.
 * إن غاب السر لا تُصفّى الصفوف.
 */
export function retainCloudRowIfPayloadMacOk(row: {
    encrypted_data?: string | null;
    payload_mac?: string | null;
}): boolean {
    if (!dossierPayloadMacSecret()) return true;
    const mac = String(row.payload_mac ?? '').trim();
    if (!mac) return !dossierPayloadMacEnforced();
    return dossierPayloadMacMatches(String(row.encrypted_data ?? ''), mac);
}

/**
 * سلامة الحمولة المشفّرة المخزّنة: data_signature يجب أن يساوي SHA-256(encrypted_data).
 * ليس HMAC بمفتاح — يمنع تخزين توقيع لا يطابق النص المشفر (عبث أثناء النقل/عميل تالف).
 */
export function encryptedPayloadSignatureMatches(
    encryptedData: string,
    dataSignature: string,
): boolean {
    const expected = sha256HexUtf8(encryptedData);
    const got = String(dataSignature ?? '').trim().toLowerCase();
    if (!SHA256_HEX.test(got) || !SHA256_HEX.test(expected)) return false;
    try {
        return timingSafeEqual(Buffer.from(expected, 'hex'), Buffer.from(got, 'hex'));
    } catch {
        return false;
    }
}

/**
 * File signature (magic bytes) validator against extension spoofing/polyglots.
 * Strict mode: only allows PDF/JPEG/PNG and rejects SVG entirely.
 */
import { createHash } from 'node:crypto';

function fileExtension(name: string): string {
  const dot = name.lastIndexOf('.');
  if (dot < 0) return '';
  return name.slice(dot + 1).toLowerCase();
}

function startsWithBytes(buffer: Buffer, bytes: number[]): boolean {
  if (buffer.length < bytes.length) return false;
  for (let i = 0; i < bytes.length; i++) {
    if (buffer[i] !== bytes[i]) return false;
  }
  return true;
}

function looksLikeSvg(buffer: Buffer): boolean {
  const sample = buffer.subarray(0, Math.min(buffer.length, 2048)).toString('utf8').toLowerCase();
  return sample.includes('<svg') || sample.includes('image/svg+xml');
}

function isPdf(buffer: Buffer): boolean {
  // %PDF-
  return startsWithBytes(buffer, [0x25, 0x50, 0x44, 0x46, 0x2d]);
}

function isPng(buffer: Buffer): boolean {
  return startsWithBytes(buffer, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
}

function isJpeg(buffer: Buffer): boolean {
  return startsWithBytes(buffer, [0xff, 0xd8, 0xff]);
}

export function validateFileBuffer(buffer: Buffer, originalName: string): boolean {
  if (!buffer || buffer.length === 0) return false;

  const ext = fileExtension(originalName);
  if (!ext) return false;

  // Hard reject SVG regardless of extension/content-type claims.
  if (ext === 'svg' || looksLikeSvg(buffer)) return false;

  // Strict extension-to-signature matching.
  if (ext === 'pdf') return isPdf(buffer);
  if (ext === 'png') return isPng(buffer);
  if (ext === 'jpg' || ext === 'jpeg') return isJpeg(buffer);

  // Reject all unsupported types in strict mode.
  return false;
}

export function verifyFileContentHash(buffer: Buffer, expectedHash: string): boolean {
  const normalizedExpected = expectedHash.trim().toLowerCase();
  if (!normalizedExpected || !/^[a-f0-9]{64}$/.test(normalizedExpected)) return false;
  const computed = createHash('sha256').update(buffer).digest('hex');
  return computed === normalizedExpected;
}

import type { HqAccountActivity, HqAccountTimelineItem } from '@/app/domain/admin/HqAccountActivity';
import type { SupabaseClient } from '@supabase/supabase-js';
import { hqAuditActionLabel, hqAuditFactsCaption } from '@/app/domain/admin/hqAuditLabels';
import { stripHqControlChars } from '@/app/domain/admin/hqSafeText';
import {
    formatHqConnectionDetail,
    formatHqNetworkPlace,
    parseHqDeviceFromUserAgent,
    sanitizeHqIp,
    type HqConnectionFact,
} from '@/app/domain/admin/hqConnectionSignal';
import { listHeadquartersConnectionSignals } from './headquartersConnectionSignal.ts';
import { getGoTrueAdminApi } from './supabaseAdminClient.ts';

export type { HqAccountActivity, HqAccountTimelineItem };

const TIMELINE_CAP = 40;
const EXCERPT_MAX = 80;

function asIso(raw: unknown): string | null {
    if (raw == null || String(raw).trim() === '') return null;
    const iso = raw instanceof Date ? raw.toISOString() : String(raw).trim();
    return Number.isNaN(Date.parse(iso)) ? null : iso;
}

function excerpt(raw: unknown): string | null {
    const text = stripHqControlChars(raw, EXCERPT_MAX);
    return text || null;
}

function pushItem(
    items: HqAccountTimelineItem[],
    at: string | null,
    kind: string,
    label: string,
    detail: string | null,
): void {
    if (!at) return;
    items.push({ at, kind, label, detail });
}

function ingestHqAuditRows(
    data: unknown,
    into: Map<string, { action: string; created_at: unknown; details: unknown }>,
): void {
    for (const row of Array.isArray(data) ? data : []) {
        const rec = row as { id?: unknown; action?: unknown; created_at?: unknown; details?: unknown };
        const action = String(rec.action ?? '').trim();
        if (!action.startsWith('hq:')) continue;
        const key = String(rec.id ?? '').trim() || `${action}:${String(rec.created_at)}`;
        if (!into.has(key)) {
            into.set(key, { action, created_at: rec.created_at, details: rec.details });
        }
    }
}

export async function loadHeadquartersAccountActivity(
    admin: SupabaseClient,
    userId: string,
    profileCreatedAt: string | null,
): Promise<HqAccountActivity> {
    const gaps: string[] = [];
    const timeline: HqAccountTimelineItem[] = [];
    pushItem(timeline, profileCreatedAt, 'account', 'إنشاء الحساب', null);

    let lastSignInAt: string | null = null;
    let emailConfirmedAt: string | null = null;
    let bannedUntil: string | null = null;
    try {
        const { data, error } = await getGoTrueAdminApi(admin).getUserById(userId);
        if (error || !data?.user) {
            gaps.push('auth');
        } else {
            lastSignInAt = asIso(data.user.last_sign_in_at);
            emailConfirmedAt = asIso(data.user.email_confirmed_at);
            bannedUntil = asIso(data.user.banned_until);
            pushItem(timeline, asIso(data.user.created_at), 'auth', 'إنشاء جلسة التوثيق', null);
            pushItem(timeline, lastSignInAt, 'auth', 'آخر دخول مسجّل', null);
            pushItem(timeline, emailConfirmedAt, 'auth', 'تأكيد البريد', null);
        }
    } catch {
        gaps.push('auth');
    }

    let sessionCount: number | null = null;
    let lastDevice: string | null = null;
    let lastIp: string | null = null;
    let lastPlace: string | null = null;
    const connections: HqConnectionFact[] = [];
    try {
        const withIp = await admin
            .from('hq_account_sessions')
            .select('created_at, updated_at, not_after, user_agent, ip', { count: 'exact' })
            .eq('user_id', userId)
            .order('created_at', { ascending: false })
            .limit(20);
        const missingIp =
            Boolean(withIp.error) &&
            /ip/i.test(String(withIp.error?.message ?? '')) &&
            /does not exist|schema cache/i.test(String(withIp.error?.message ?? ''));
        const sessionResult = missingIp
            ? await admin
                  .from('hq_account_sessions')
                  .select('created_at, updated_at, not_after, user_agent', { count: 'exact' })
                  .eq('user_id', userId)
                  .order('created_at', { ascending: false })
                  .limit(20)
            : withIp;
        const { data, error, count } = sessionResult;
        if (error) {
            gaps.push('sessions');
        } else {
            sessionCount = typeof count === 'number' ? count : Array.isArray(data) ? data.length : 0;
            for (const row of Array.isArray(data) ? data : []) {
                const rec = row as {
                    created_at?: unknown;
                    updated_at?: unknown;
                    not_after?: unknown;
                    user_agent?: unknown;
                    ip?: unknown;
                };
                const device = parseHqDeviceFromUserAgent(rec.user_agent);
                const ip = sanitizeHqIp(rec.ip);
                const place = formatHqNetworkPlace({ ip });
                const detail = formatHqConnectionDetail({
                    deviceLabel: device.deviceLabel,
                    ip,
                    place,
                });
                if (!lastDevice && (ip || String(rec.user_agent ?? '').trim())) {
                    lastDevice = device.deviceLabel;
                    lastIp = ip;
                    lastPlace = place;
                }
                pushItem(timeline, asIso(rec.created_at), 'session', 'جلسة', detail);
                const last = asIso(rec.updated_at) ?? asIso(rec.not_after);
                if (last && last !== asIso(rec.created_at)) {
                    pushItem(timeline, last, 'session', 'آخر نشاط للجلسة', detail);
                }
            }
        }
    } catch {
        gaps.push('sessions');
    }

    const signalPack = await listHeadquartersConnectionSignals(admin, userId);
    if (signalPack.failed) {
        gaps.push('connections');
    } else if (signalPack.rows.length > 0) {
        connections.push(...signalPack.rows);
        lastDevice = signalPack.rows[0].deviceLabel;
        lastIp = signalPack.rows[0].ip;
        lastPlace = signalPack.rows[0].place;
    }

    let forumPosts: number | null = null;
    try {
        const { data, error, count } = await admin
            .from('forum_posts')
            .select('content, created_at', { count: 'exact' })
            .eq('author_id', userId)
            .order('created_at', { ascending: false })
            .limit(8);
        if (error) {
            gaps.push('forum_posts');
        } else {
            forumPosts = typeof count === 'number' ? count : Array.isArray(data) ? data.length : 0;
            for (const row of Array.isArray(data) ? data : []) {
                const rec = row as { content?: unknown; created_at?: unknown };
                pushItem(timeline, asIso(rec.created_at), 'forum_post', 'منشور منتدى', excerpt(rec.content));
            }
        }
    } catch {
        gaps.push('forum_posts');
    }

    let forumComments: number | null = null;
    try {
        const { data, error, count } = await admin
            .from('forum_comments')
            .select('content, created_at', { count: 'exact' })
            .eq('author_id', userId)
            .order('created_at', { ascending: false })
            .limit(8);
        if (error) {
            gaps.push('forum_comments');
        } else {
            forumComments = typeof count === 'number' ? count : Array.isArray(data) ? data.length : 0;
            for (const row of Array.isArray(data) ? data : []) {
                const rec = row as { content?: unknown; created_at?: unknown };
                pushItem(timeline, asIso(rec.created_at), 'forum_comment', 'تعليق منتدى', excerpt(rec.content));
            }
        }
    } catch {
        gaps.push('forum_comments');
    }

    let forumBanned: boolean | null = null;
    let forumBanReason: string | null = null;
    let forumBanExpiresAt: string | null = null;
    try {
        const { data, error } = await admin.from('forum_bans').select('reason, expires_at, banned_at').eq('user_id', userId).maybeSingle();
        if (error) {
            gaps.push('forum_bans');
        } else if (data) {
            const expires = asIso((data as { expires_at?: unknown }).expires_at);
            const active = !expires || Date.parse(expires) > Date.now();
            forumBanned = active;
            forumBanReason = active ? excerpt((data as { reason?: unknown }).reason) : null;
            forumBanExpiresAt = active ? expires : null;
            pushItem(
                timeline,
                asIso((data as { banned_at?: unknown }).banned_at),
                'forum_ban',
                active ? 'حظر منتدى ساري' : 'حظر منتدى سابق',
                forumBanReason,
            );
        } else {
            forumBanned = false;
        }
    } catch {
        gaps.push('forum_bans');
    }

    const auditMap = new Map<string, { action: string; created_at: unknown; details: unknown }>();
    let auditFailed = false;
    try {
        const byTarget = await admin
            .from('audit_logs')
            .select('id, action, details, created_at')
            .eq('details->>targetId', userId)
            .order('created_at', { ascending: false })
            .limit(30);
        if (byTarget.error) {
            auditFailed = true;
        } else {
            ingestHqAuditRows(byTarget.data, auditMap);
        }
    } catch {
        auditFailed = true;
    }
    try {
        const byActor = await admin
            .from('audit_logs')
            .select('id, action, details, created_at')
            .eq('user_id', userId)
            .order('created_at', { ascending: false })
            .limit(30);
        if (byActor.error) {
            auditFailed = true;
        } else {
            ingestHqAuditRows(byActor.data, auditMap);
        }
    } catch {
        auditFailed = true;
    }
    if (auditFailed && auditMap.size === 0) {
        gaps.push('audit');
    } else {
        for (const rec of auditMap.values()) {
            pushItem(
                timeline,
                asIso(rec.created_at),
                'audit',
                hqAuditActionLabel(rec.action),
                hqAuditFactsCaption(rec.details) || null,
            );
        }
    }

    timeline.sort((a, b) => Date.parse(b.at) - Date.parse(a.at));
    return {
        createdAt: profileCreatedAt,
        lastSignInAt,
        emailConfirmedAt,
        bannedUntil,
        sessionCount,
        lastDevice,
        lastIp,
        lastPlace,
        connections,
        forumPosts,
        forumComments,
        forumBanned,
        forumBanReason,
        forumBanExpiresAt,
        timeline: timeline.slice(0, TIMELINE_CAP),
        gaps,
    };
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { getGoTrueAdminApi, getSupabaseAdminClient } from './supabaseAdminClient.ts';
import { invalidateCsrfForSubject } from './csrfServerStore.ts';
import { invalidateWifeSessionsForSubject } from './wifeSessionServerStore.ts';
import { revokeTokenSessionsForSubject } from './stolenTokenServer.ts';

export const HQ_FREEZE_DURATION_HOURS = [0, 24, 72, 168] as const;
export type HqFreezeDurationHours = (typeof HQ_FREEZE_DURATION_HOURS)[number];

export function isHqFreezeDurationHours(value: unknown): value is HqFreezeDurationHours {
    return value === 0 || value === 24 || value === 72 || value === 168;
}

export function freezeProfileUpdates(hours: HqFreezeDurationHours): Record<string, unknown> {
    const now = Date.now();
    return {
        is_banned: true,
        is_active: false,
        status: 'suspended',
        freeze_until: hours > 0 ? new Date(now + hours * 3_600_000).toISOString() : null,
        updated_at: new Date(now).toISOString(),
    };
}

export function unfreezeProfileUpdates(): Record<string, unknown> {
    return {
        is_banned: false,
        is_active: true,
        status: 'active',
        freeze_until: null,
        updated_at: new Date().toISOString(),
    };
}

function isMissingProfileColumn(message: string, column: string): boolean {
    const hay = message.toLowerCase();
    return hay.includes(column) && (hay.includes('does not exist') || hay.includes('schema cache'));
}

export function loginLockProfileUpdates(hours: HqFreezeDurationHours): Record<string, unknown> {
    const now = Date.now();
    return {
        login_blocked: hours === 0,
        login_until: hours > 0 ? new Date(now + hours * 3_600_000).toISOString() : null,
        updated_at: new Date(now).toISOString(),
    };
}

export function loginUnlockProfileUpdates(): Record<string, unknown> {
    return {
        login_blocked: false,
        login_until: null,
        updated_at: new Date().toISOString(),
    };
}

export function softDeleteProfileUpdates(): Record<string, unknown> {
    const now = new Date().toISOString();
    return {
        is_deleted: true,
        deleted_at: now,
        login_blocked: true,
        login_until: null,
        is_banned: true,
        is_active: false,
        status: 'suspended',
        freeze_until: null,
        updated_at: now,
    };
}

export function restoreProfileUpdates(): Record<string, unknown> {
    return {
        is_deleted: false,
        deleted_at: null,
        ...loginUnlockProfileUpdates(),
        ...unfreezeProfileUpdates(),
    };
}

export function publicVerifiedBadgeProfileUpdates(shown: boolean): Record<string, unknown> {
    return {
        public_verified_badge: shown === true,
        updated_at: new Date().toISOString(),
    };
}

export function goTrueBanDurationHours(hours: HqFreezeDurationHours): string {
    return hours > 0 ? `${hours}h` : '876000h';
}

export function isHqProfileLoginLocked(row: {
    isDeleted?: boolean;
    loginBlocked?: boolean;
    loginUntil?: string | null;
}): boolean {
    if (row.isDeleted || row.loginBlocked) return true;
    const until = row.loginUntil;
    if (!until) return false;
    const at = Date.parse(until);
    return Number.isFinite(at) && at > Date.now();
}

export async function updateHeadquartersProfile(
    admin: SupabaseClient,
    userId: string,
    updates: Record<string, unknown>,
): Promise<{ error: { message?: string } | null }> {
    let payload = { ...updates };
    for (let attempt = 0; attempt < 5; attempt += 1) {
        const result = await admin.from('profiles').update(payload).eq('id', userId);
        const error = result.error as { message?: string } | null;
        if (!error) return { error: null };
        const next = { ...payload };
        let stripped = false;
        for (const column of [
            'freeze_until',
            'login_until',
            'login_blocked',
            'deleted_at',
            'public_verified_badge',
        ] as const) {
            if (
                Object.prototype.hasOwnProperty.call(next, column) &&
                isMissingProfileColumn(error.message ?? '', column)
            ) {
                delete next[column];
                stripped = true;
            }
        }
        if (!stripped) return { error };
        payload = next;
    }
    return { error: { message: 'Profile update failed' } };
}

