    try {
        await appendIncomingNotificationServer(id, {
            title: copy.title,
            message: copy.message,
            type: 'system_alert',
            category: 'system',
            direction: 'incoming',
            dedupeKey,
        });
        return true;
    } catch {
        return false;
    }
}

