import { getSupabaseAdminClient } from './supabaseAdminClient.ts';

const ACTION_MAX = 96;

/**
 * سجل تدقيق من الخادم فقط — لا يعتمد على /api/audit/log من المتصفح.
 * فشل الكتابة لا يوقف عملية المقر، لكن يُعاد صراحة حتى لا يُبتلع.
 */
export async function recordHeadquartersAudit(input: {
    actorId: string;
    action: string;
    targetId?: string;
    details?: Record<string, unknown>;
}): Promise<boolean> {
    const actorId = String(input.actorId ?? '').trim();
    const action = String(input.action ?? '').trim().slice(0, ACTION_MAX);
    if (!actorId || !action) return false;
    try {
        const admin = getSupabaseAdminClient();
        if (!admin) {
            console.error('[hq-audit] admin client missing');
            return false;
        }
        const details: Record<string, unknown> = {
            targetId: input.targetId ?? null,
        };
        if (input.details) {
            for (const [key, value] of Object.entries(input.details).slice(0, 8)) {
                const clippedKey = key.slice(0, 48);
                if (typeof value === 'string') details[clippedKey] = value.slice(0, 240);
                else if (typeof value === 'number' || typeof value === 'boolean' || value === null) {
                    details[clippedKey] = value;
                }
            }
        }
        const { error } = await admin.from('audit_logs').insert({
            user_id: actorId,
            action: `hq:${action}`,
            details,
        });
        if (error) {
            const code = typeof error.code === 'string' ? error.code : '';
            console.error('[hq-audit] insert failed', code);
            return false;
        }
        return true;
    } catch {
        console.error('[hq-audit] insert threw');
        return false;
    }
}

const ACTION_LIKE = 'hq:%';
const LIST_CAP = 80;
const DETAIL_KEY_MAX = 48;
const DETAIL_VALUE_MAX = 240;
const BLOCKED_DETAIL = /password|secret|token|otp|code|hash|pepper|cookie|fingerprint/i;

export type HeadquartersAuditRow = {
    id: string;
    action: string;
    actorId: string;
    targetId: string | null;
    createdAt: string;
    details: Record<string, string | number | boolean | null>;
};

function sanitizeDetails(raw: unknown): Record<string, string | number | boolean | null> {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return {};
    const out: Record<string, string | number | boolean | null> = {};
    for (const [key, value] of Object.entries(raw).slice(0, 8)) {
        const clippedKey = key.slice(0, DETAIL_KEY_MAX);
        if (!clippedKey || BLOCKED_DETAIL.test(clippedKey)) continue;
        if (typeof value === 'string') {
            if (BLOCKED_DETAIL.test(value)) continue;
            out[clippedKey] = value.slice(0, DETAIL_VALUE_MAX);
        } else if (typeof value === 'number' || typeof value === 'boolean' || value === null) {
            out[clippedKey] = value;
        }
    }
    return out;
}

export async function listHeadquartersAudit(
    admin: {
        from: (table: string) => {
            select: (cols: string) => {
                like: (col: string, pattern: string) => {
                    order: (
                        col: string,
                        opts: { ascending: boolean },
                    ) => { limit: (n: number) => PromiseLike<{ data: unknown; error: { message?: string } | null }> };
                };
            };
        };
    },
): Promise<HeadquartersAuditRow[]> {
    const { data, error } = await admin
        .from('audit_logs')
        .select('id, user_id, action, details, created_at')
        .like('action', ACTION_LIKE)
        .order('created_at', { ascending: false })
        .limit(LIST_CAP);
    if (error) {
        const detail = typeof error.message === 'string' ? error.message : '';
        throw new Error(detail || 'Failed to list headquarters audit');
    }
    const rows: HeadquartersAuditRow[] = [];
    for (const raw of Array.isArray(data) ? data : []) {
        const rec = raw as {
            id?: unknown;
            user_id?: unknown;
            action?: unknown;
            details?: unknown;
            created_at?: unknown;
        };
        const id = String(rec.id ?? '').trim();
        const action = String(rec.action ?? '').trim();
        if (!id || !action.startsWith('hq:')) continue;
        const details = sanitizeDetails(rec.details);
        const targetRaw = details.targetId;
        rows.push({
            id,
            action,
            actorId: String(rec.user_id ?? '').trim(),
            targetId: typeof targetRaw === 'string' && targetRaw.trim() ? targetRaw.trim() : null,
            createdAt: String(rec.created_at ?? ''),
            details,
        });
    }
    return rows;
}

import { getSupabaseAdminClient } from './supabaseAdminClient.ts';
import { isPostgresUuidSubject } from './postgresUuidSubject.ts';
import { readForwardedClientIp } from './wifeSameOrigin.ts';
import {
    formatHqNetworkPlace,
    parseHqDeviceFromRequest,
    readHqEdgeCity,
    readHqEdgeCountry,
    sanitizeHqIp,
    type HqConnectionFact,
    type HqConnectionSource,
} from '@/app/domain/admin/hqConnectionSignal';
import { stripHqControlChars } from '@/app/domain/admin/hqSafeText';

const DEBOUNCE_MS = 6 * 60 * 60 * 1000;
const LABEL_MAX = 80;

type SignalRow = {
    id?: unknown;
    seen_at?: unknown;
    ip?: unknown;
    device_class?: unknown;
    device_label?: unknown;
    country_code?: unknown;
    city?: unknown;
    source?: unknown;
};

function asIso(raw: unknown): string | null {
    if (raw == null || String(raw).trim() === '') return null;
    const iso = raw instanceof Date ? raw.toISOString() : String(raw).trim();
    return Number.isNaN(Date.parse(iso)) ? null : iso;
}

function mapSignalRow(row: SignalRow): HqConnectionFact | null {
    const at = asIso(row.seen_at);
    const deviceLabel = stripHqControlChars(row.device_label, LABEL_MAX);
    if (!at || !deviceLabel) return null;
    const sourceRaw = String(row.source ?? '').trim();
    const source: HqConnectionSource =
        sourceRaw === 'login' || sourceRaw === 'signup' || sourceRaw === 'refresh' || sourceRaw === 'session'
            ? sourceRaw
            : 'session';
    const ip = sanitizeHqIp(row.ip);
    const countryCode = String(row.country_code ?? '').trim().toUpperCase() || null;
    const city = stripHqControlChars(row.city, 80) || null;
    return {
        at,
        deviceLabel,
        ip,
        place: formatHqNetworkPlace({ ip, countryCode, city }),
        source,
    };
}

/** يسجّل إشارة اتصال للمقر. الفشل لا يمنع الدخول. لا GPS ولا إحداثيات. */
export async function recordHeadquartersConnectionSignal(
    userId: string,
    request: Request,
    source: 'login' | 'signup' | 'refresh',
): Promise<void> {
    const id = userId.trim();
    if (!isPostgresUuidSubject(id)) return;
    try {
        const admin = getSupabaseAdminClient();
        if (!admin) return;
        const device = parseHqDeviceFromRequest(request);
        const ip = sanitizeHqIp(readForwardedClientIp(request));
        const countryCode = readHqEdgeCountry(request);
        const city = readHqEdgeCity(request);
        const { data: latest } = await admin
            .from('hq_connection_signals')
            .select('id, ip, device_class, country_code, city, seen_at')
            .eq('user_id', id)
            .order('seen_at', { ascending: false })
            .limit(1)
            .maybeSingle();
        const last = latest as SignalRow | null;
        const same =
            last &&
            String(last.device_class ?? '') === device.deviceClass &&
            sanitizeHqIp(last.ip) === ip &&
            String(last.country_code ?? '').toUpperCase() === (countryCode ?? '') &&
            stripHqControlChars(last.city, 80) === (city ?? '');
        const lastAt = last ? Date.parse(String(last.seen_at ?? '')) : NaN;
        if (same && Number.isFinite(lastAt) && Date.now() - lastAt < DEBOUNCE_MS && last?.id) {
            await admin
                .from('hq_connection_signals')
                .update({ seen_at: new Date().toISOString() })
                .eq('id', last.id);
            return;
        }
        await admin.from('hq_connection_signals').insert({
            user_id: id,
            ip,
            device_class: device.deviceClass,
            device_label: device.deviceLabel.slice(0, LABEL_MAX),
            country_code: countryCode,
            city: city?.slice(0, 80) ?? null,
            source,
        });
    } catch {
        /* الدخول لا يعتمد على سجل المقر */
    }
}

export async function listHeadquartersConnectionSignals(
    admin: {
        from: (table: string) => {
            select: (cols: string) => {
                eq: (col: string, value: string) => {
                    order: (
                        col: string,
                        opts: { ascending: boolean },
                    ) => { limit: (n: number) => PromiseLike<{ data: unknown; error: { message?: string } | null }> };
                };
            };
        };
    },
    userId: string,
): Promise<{ rows: HqConnectionFact[]; failed: boolean }> {
    try {
        const { data, error } = await admin
            .from('hq_connection_signals')
            .select('seen_at, ip, device_label, country_code, city, source')
            .eq('user_id', userId)
            .order('seen_at', { ascending: false })
            .limit(8);
        if (error) {
            const hay = String(error.message ?? '').toLowerCase();
            if (hay.includes('hq_connection_signals') && (hay.includes('does not exist') || hay.includes('schema cache'))) {
                return { rows: [], failed: false };
            }
            return { rows: [], failed: true };
        }
        const rows: HqConnectionFact[] = [];
        for (const raw of Array.isArray(data) ? data : []) {
            const mapped = mapSignalRow(raw as SignalRow);
            if (mapped) rows.push(mapped);
        }
        return { rows, failed: false };
    } catch {
        return { rows: [], failed: true };
    }
}

export const HEADQUARTERS_CONSULTATIONS_CAP = 80;
export const HEADQUARTERS_CONSULTATION_REPLY_SCAN_CAP = 2000;
const CONTENT_PREVIEW_MAX = 2500;

export type HeadquartersConsultation = {
    id: string;
    name: string;
    content: string;
    time: string;
    isLawyer: boolean;
    pinned: boolean;
    locked: boolean;
    replyCount: number;
    offers: Array<{ lawyerName: string; price: number }>;
};

function clipText(value: unknown, max: number): string {
    return String(value ?? '')
        .replace(/[\u0000-\u001F\u007F]/g, '')
        .trim()
        .slice(0, Math.max(0, max));
}

function formatConsultationTime(iso: string): string {
    const date = new Date(iso);
    if (Number.isNaN(date.getTime())) return '—';
    try {
        return new Intl.DateTimeFormat('ar-IQ', {
            year: 'numeric',
            month: 'short',
            day: 'numeric',
        }).format(date);
    } catch {
        return date.toLocaleDateString('ar');
    }
}

export function mapHeadquartersConsultation(post: {
    id?: unknown;
    authorName?: unknown;
    isAnonymous?: unknown;
    content?: unknown;
    createdAt?: unknown;
    pinned?: unknown;
    locked?: unknown;
    comments?: unknown;
    replyCount?: unknown;
}): HeadquartersConsultation | null {
    const id = String(post.id ?? '')
        .replace(/[\u0000-\u001F\u007F]/g, '')
        .trim();
    if (!id || id.length > 80) return null;
    const anonymous = post.isAnonymous === true;
    const name = anonymous ? 'مجهول' : clipText(post.authorName, 80) || '—';
    const content = clipText(post.content, CONTENT_PREVIEW_MAX);
    const comments = Array.isArray(post.comments) ? post.comments : [];
    const offers: HeadquartersConsultation['offers'] = [];
    for (const comment of comments) {
        if (!comment || typeof comment !== 'object') continue;
        const lawyerName = clipText((comment as { authorName?: unknown }).authorName, 80);
        offers.push({ lawyerName: lawyerName || '—', price: 0 });
    }
    const replyFromField = Number(post.replyCount);
    const replyCount =
        Number.isFinite(replyFromField) && replyFromField >= 0
            ? Math.min(Math.floor(replyFromField), 10_000)
            : offers.length;
    return {
        id,
        name,
        content,
        time: formatConsultationTime(String(post.createdAt ?? '')),
        isLawyer: false,
        pinned: post.pinned === true,
        locked: post.locked === true,
        replyCount,
        offers,
    };
}

