/**
 * قائمة استشارات المقر من Postgres مباشرة —
 * بلا ForumRepository / CommunityDB / ترحيل KV / توقيع مرفقات.
 * عدّ الردود بلا أسماء المعلّقين.
 */
export async function listHeadquartersConsultations(
    admin: SupabaseClient,
): Promise<HeadquartersConsultation[]> {
    const { data: posts, error } = await admin
        .from('forum_posts')
        .select('id, author_name, is_anonymous, content, created_at, is_pinned, is_locked')
        .is('group_id', null)
        .order('created_at', { ascending: false })
        .limit(HEADQUARTERS_CONSULTATIONS_CAP);
    if (error) {
        const detail = typeof error.message === 'string' ? error.message : '';
        if (isMissingRelation(detail)) return [];
        throw new Error(detail || 'Failed to list consultations');
    }
    const rows = Array.isArray(posts) ? (posts as PostRow[]) : [];
    const ids = rows.map((row) => String(row.id ?? '').trim()).filter((id) => isPostgresUuidSubject(id));

    const replyCountByPost = new Map<string, number>();
    if (ids.length > 0) {
        const { data: comments, error: commentError } = await admin
            .from('forum_comments')
            .select('post_id')
            .in('post_id', ids)
            .limit(HEADQUARTERS_CONSULTATION_REPLY_SCAN_CAP);
        if (commentError) {
            const detail = typeof commentError.message === 'string' ? commentError.message : '';
            if (!isMissingRelation(detail)) {
                throw new Error(detail || 'Failed to list consultation replies');
            }
        } else if (Array.isArray(comments)) {
            for (const raw of comments as CommentCountRow[]) {
                const postId = String(raw.post_id ?? '').trim();
                if (!postId) continue;
                replyCountByPost.set(postId, (replyCountByPost.get(postId) ?? 0) + 1);
            }
        }
    }

    const consultations: HeadquartersConsultation[] = [];
    for (const row of rows) {
        const mapped = mapHeadquartersConsultation({
            id: row.id,
            authorName: row.author_name,
            isAnonymous: row.is_anonymous === true,
            content: row.content,
            createdAt: row.created_at,
            pinned: row.is_pinned === true,
            locked: row.is_locked === true,
            replyCount: replyCountByPost.get(String(row.id ?? '').trim()) ?? 0,
        });
        if (mapped) consultations.push(mapped);
    }
    return consultations;
}

export type HqConsultationMutationResult = 'missing' | { ok: true; authorId: string };

export async function deleteHeadquartersConsultation(
    admin: SupabaseClient,
    postId: string,
): Promise<HqConsultationMutationResult> {
    const post = await loadPublicForumPost(admin, postId);
    if (!post) return 'missing';
    const { error: commentsError } = await admin.from('forum_comments').delete().eq('post_id', post.id);
    if (commentsError) throw new Error(commentsError.message || 'Failed to delete consultation replies');
    const { error: postError } = await admin.from('forum_posts').delete().eq('id', post.id);
    if (postError) throw new Error(postError.message || 'Failed to delete consultation');
    return { ok: true, authorId: post.authorId };
}

export async function setHeadquartersPostFlags(
    admin: SupabaseClient,
    postId: string,
    flags: { pinned?: boolean; locked?: boolean },
): Promise<HqConsultationMutationResult> {
    const post = await loadPublicForumPost(admin, postId);
    if (!post) return 'missing';
    const patch: Record<string, boolean | string> = {
        updated_at: new Date().toISOString(),
    };
    if (typeof flags.pinned === 'boolean') patch.is_pinned = flags.pinned;
    if (typeof flags.locked === 'boolean') patch.is_locked = flags.locked;
    if (Object.keys(patch).length <= 1) return 'missing';

    const { error: updateError } = await admin.from('forum_posts').update(patch).eq('id', post.id);
    if (updateError) throw new Error(updateError.message || 'Failed to update post flags');
    return { ok: true, authorId: post.authorId };
}

import type { AdminUser } from '@/app/domain/admin/AdminUser';
import type { SupabaseClient } from '@supabase/supabase-js';
import {
    isHeadquartersAdminRole,
    isHeadquartersProtectedAdminId,
} from './headquartersUserMap.ts';
import { fetchHeadquartersUser } from './headquartersUsers.ts';
import { isPostgresUuidSubject } from './postgresUuidSubject.ts';

export type HeadquartersControlTarget =
    | { ok: true; user: AdminUser | null }
    | { ok: false; status: number; error: string };

export function rejectHeadquartersTargetId(
    targetUserId: string,
    actorId: string,
    options: { allowSelf?: boolean } = {},
): { status: number; error: string } | null {
    if (!isPostgresUuidSubject(targetUserId)) {
        return { status: 400, error: 'targetUserId مطلوب' };
    }
    if (!options.allowSelf && targetUserId === actorId) {
        return { status: 400, error: 'لا يمكن تعديل الحساب الحالي بهذا المسار' };
    }
    if (isHeadquartersProtectedAdminId(targetUserId)) {
        return { status: 403, error: 'لا يمكن تعديل مدير المنصّة' };
    }
    return null;
}

/**
 * هدف سيطرة المقر: UUID حيّ، ليس الفاعل، ليس مدير المنصّة، ليس role=admin.
 * `allowMissing` لرفع حظر يتيم بعد اختفاء الصف.
 */
export async function resolveHeadquartersControlTarget(
    admin: SupabaseClient,
    targetUserId: string,
    actorId: string,
    options: { allowMissing?: boolean } = {},
): Promise<HeadquartersControlTarget> {
    const rejected = rejectHeadquartersTargetId(targetUserId, actorId);
    if (rejected) return { ok: false, ...rejected };
    const user = await fetchHeadquartersUser(admin, targetUserId);
    if (!user) {
        if (options.allowMissing) return { ok: true, user: null };
        return { ok: false, status: 404, error: 'المستخدم غير موجود' };
    }
    if (isHeadquartersAdminRole(user.role)) {
        return { ok: false, status: 403, error: 'لا يمكن تعديل حساب إدارة' };
    }
    return { ok: true, user };
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { raceBudget } from './promiseBudget.ts';

export const HEADQUARTERS_STATS_ROW_CAP = 8000;
export const HEADQUARTERS_STATS_COURT_CAP = 60;

export type HeadquartersCourtStat = {
    court: string;
    lawsuits: number;
    transactions: number;
};

export function normalizeCourtLabel(raw: unknown): string {
    const s = String(raw ?? '')
        .replace(/[\u0000-\u001F\u007F]/g, '')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 80);
    return s || 'غير محدد';
}

function asCourtCount(value: unknown): number {
    const n = Number(value);
    if (!Number.isFinite(n) || n < 0) return 0;
    return Math.min(Math.floor(n), 1_000_000_000);
}

async function countByCourt(
    admin: SupabaseClient,
    table: 'lawsuit_files' | 'execution_files',
): Promise<Map<string, number>> {
    const counts = new Map<string, number>();
    try {
        const { data, error } = await admin
            .from(table)
            .select('court')
            .eq('status', 'active')
            .limit(HEADQUARTERS_STATS_ROW_CAP);
        if (error) {
            return counts;
        }
        if (!Array.isArray(data)) return counts;
        for (const row of data) {
            if (!row || typeof row !== 'object') continue;
            const court = normalizeCourtLabel((row as { court?: unknown }).court);
            counts.set(court, (counts.get(court) ?? 0) + 1);
        }
    } catch {
        return counts;
    }
    return counts;
}

export function mergeCourtCounts(
    lawsuits: Map<string, number>,
    executions: Map<string, number>,
): HeadquartersCourtStat[] {
    const courts = new Set<string>([...lawsuits.keys(), ...executions.keys()]);
    const rows: HeadquartersCourtStat[] = [];
    for (const court of courts) {
        rows.push({
            court,
            lawsuits: asCourtCount(lawsuits.get(court)),
            /**
             * واجهة المقر تسمّي الحقل الثاني «معاملات رسمية».
             * المصدر السحابي الوحيد بعمود محكمة عدا الدعاوى هو execution_files.
             */
            transactions: asCourtCount(executions.get(court)),
        });
    }
    rows.sort((a, b) => b.lawsuits + b.transactions - (a.lawsuits + a.transactions));
    return rows.slice(0, HEADQUARTERS_STATS_COURT_CAP);
}

function mapRpcCourtRows(data: unknown): HeadquartersCourtStat[] | null {
    if (!Array.isArray(data)) return null;
    const rows: HeadquartersCourtStat[] = [];
    for (const row of data) {
        if (!row || typeof row !== 'object') continue;
        const rec = row as { court?: unknown; lawsuits?: unknown; executions?: unknown };
        rows.push({
            court: normalizeCourtLabel(rec.court),
            lawsuits: asCourtCount(rec.lawsuits),
            transactions: asCourtCount(rec.executions),
        });
    }
    return rows.slice(0, HEADQUARTERS_STATS_COURT_CAP);
}

export const HEADQUARTERS_STATS_RPC_BUDGET_MS = 2_500;
export const HEADQUARTERS_STATS_SCAN_BUDGET_MS = 3_500;
export const HEADQUARTERS_COURT_STATS_CACHE_TTL_MS = 8_000;

type CourtCacheBox = { expiresAt: number; courts: HeadquartersCourtStat[] };
let courtCache: CourtCacheBox | null = null;
let courtInflight: Promise<HeadquartersCourtStat[]> | null = null;

export function resetHeadquartersCourtStatsCacheForTests(): void {
    courtCache = null;
    courtInflight = null;
}

export async function listHeadquartersCourtStats(
    admin: SupabaseClient,
): Promise<HeadquartersCourtStat[]> {
    try {
        const rpcResult = await raceBudget(
            Promise.resolve().then(() => admin.rpc('headquarters_court_counts')),
            HEADQUARTERS_STATS_RPC_BUDGET_MS,
        );
        if (rpcResult) {
            const { data, error } = rpcResult as {
                data: unknown;
                error: { message?: string } | null;
            };
            if (!error) {
                const mapped = mapRpcCourtRows(data);
                if (mapped && mapped.length > 0) return mapped;
            }
            /* RPC فارغ أو مفقود أو معطوب — مسح محدود بدل إسقاط اللوحة */
        }

        const scanned = await raceBudget(
            Promise.all([
                countByCourt(admin, 'lawsuit_files'),
                countByCourt(admin, 'execution_files'),
            ]).then(([lawsuits, executions]) => mergeCourtCounts(lawsuits, executions)),
            HEADQUARTERS_STATS_SCAN_BUDGET_MS,
        );
        return scanned ?? [];
    } catch {
        return [];
    }
}

export async function listHeadquartersCourtStatsCached(
    admin: SupabaseClient,
    opts?: { fresh?: boolean },
): Promise<HeadquartersCourtStat[]> {
    const now = Date.now();
    if (!opts?.fresh && courtCache && courtCache.expiresAt > now) {
        return courtCache.courts;
    }
    if (courtInflight) return courtInflight;
    courtInflight = (async () => {
        const courts = await listHeadquartersCourtStats(admin);
        courtCache = { expiresAt: Date.now() + HEADQUARTERS_COURT_STATS_CACHE_TTL_MS, courts };
        return courts;
    })().finally(() => {
        courtInflight = null;
    });
    return courtInflight;
}

import type { SupabaseClient } from '@supabase/supabase-js';
import type { AdminUser } from '@/app/domain/admin/AdminUser';
import {
    EMPTY_HQ_DIRECTORY_QUERY,
    HEADQUARTERS_NOTIFY_RECIPIENT_CAP,
    HEADQUARTERS_NOTIFY_RECIPIENT_PAGE,
    HQ_DIRECTORY_SCAN_BATCH,
    HQ_DIRECTORY_SCAN_CAP,
    needsHqDirectoryPresenceScan,
    type HqDirectoryListQuery,
    type HqDirectoryListResult,
} from '@/app/domain/admin/hqDirectoryQuery';
import {
    matchesHqUserCreatedFilter,
    matchesHqUserQuery,
    matchesHqUserStatusFilter,
} from '@/app/domain/admin/hqDirectoryMatch';
import { parseAdminVerificationStatus, resolveHqDirectoryKycStatus } from '@/app/domain/admin/hqUserPresence';
import { isPostgresUuidSubject } from './postgresUuidSubject.ts';
import {
    isHeadquartersAdminRole,
    isHeadquartersProtectedAdminId,
    mapHeadquartersUser,
} from './headquartersUserMap.ts';
import { withHeadquartersProfileColumns } from './headquartersProfileSelect.ts';
import { hqFrozenProfilesOrFilter, hqLoginLockedProfilesOrFilter } from './headquartersStatus.ts';
import { kvReadUserStatusMapByKeys, type HqKvVerificationHint } from './kvStoreAdmin.ts';

type AuthIdentity = {
    email: string;
    fullName: string;
    familyName: string;
    phone: string;
    governorate: string;
    lawyerBarRoom: string;
    appVerificationStatus: ReturnType<typeof parseAdminVerificationStatus>;
};

const EMPTY_AUTH_IDENTITY: AuthIdentity = {
    email: '',
    fullName: '',
    familyName: '',
    phone: '',
    governorate: '',
    lawyerBarRoom: '',
    appVerificationStatus: 'none',
};

type ProfileChain = {
    eq: (column: string, value: string | boolean) => ProfileChain;
    or: (filters: string) => ProfileChain;
    gte: (column: string, value: string) => ProfileChain;
    in: (column: string, values: string[]) => ProfileChain;
    order: (column: string, opts: { ascending: boolean }) => ProfileChain;
    range: (
        from: number,
        to: number,
    ) => Promise<{ data: unknown; error: { message?: string } | null; count?: number | null }>;
};

function escapeIlike(raw: string): string {
    return raw.replace(/\\/g, '\\\\').replace(/[%_,()]/g, ' ').replace(/\s+/g, ' ').trim();
}

function isEmailQuery(q: string): boolean {
    return q.includes('@') && q.length >= 5 && q.length <= 80;
}

function normalizePhoneQuery(q: string): string {
    return q.replace(/[\s-]/g, '');
}

function isPhoneQuery(q: string): boolean {
    const d = normalizePhoneQuery(q);
    return /^0[0-9]{9,11}$/.test(d) || /^\+964[0-9]{8,11}$/.test(d);
}

async function lookupAuthSubjectId(admin: SupabaseClient, q: string): Promise<string | null> {
    try {
        if (isEmailQuery(q)) {
            const { data, error } = await admin.rpc('hq_lookup_auth_email', { p_email: q.trim() });
            const id = String(data ?? '').trim();
            if (!error && isPostgresUuidSubject(id)) return id;
        }
        if (isPhoneQuery(q)) {
            const { data, error } = await admin.rpc('hq_lookup_auth_phone', {
                p_phone: normalizePhoneQuery(q),
            });
            const id = String(data ?? '').trim();
            if (!error && isPostgresUuidSubject(id)) return id;
        }
    } catch {
        /* البحث بالاسم يبقى */
    }
    return null;
}

async function loadPageIdentities(
    admin: SupabaseClient,
    ids: string[],
): Promise<Map<string, AuthIdentity>> {
    const map = new Map<string, AuthIdentity>();
    const uuidIds = ids.filter((id) => isPostgresUuidSubject(id));
    if (uuidIds.length === 0) return map;
    try {
        const { data, error } = await admin.rpc('hq_directory_identities', { p_ids: uuidIds });
        if (error || !Array.isArray(data)) return map;
        for (const row of data) {
            if (!row || typeof row !== 'object') continue;
            const rec = row as Record<string, unknown>;
            const id = String(rec.id ?? '').trim();
            if (!isPostgresUuidSubject(id)) continue;
            map.set(id, {
                email: String(rec.email ?? '').trim(),
                fullName: '',
                familyName: String(rec.family_name ?? '').trim().slice(0, 160),
                phone: String(rec.phone ?? '').trim().slice(0, 20),
                governorate: String(rec.governorate ?? '').trim().slice(0, 40),
                lawyerBarRoom: String(rec.lawyer_bar_room ?? '').trim().slice(0, 80),
                appVerificationStatus: parseAdminVerificationStatus(rec.app_verification_status),
            });
        }
    } catch {
        /* الأسماء على profiles تكفي — البريد يُستكمل في الإضبارة */
    }
    return map;
}

function applySqlDirectoryFilters(
    chain: ProfileChain,
    query: HqDirectoryListQuery,
    nowIso: string,
    pinnedId: string | null,
    nameSearch: boolean,
): ProfileChain {
    let next = chain;
    if (pinnedId) {
        return next.eq('id', pinnedId);
    }
    if (query.role !== 'all') {
        next = next.eq('role', query.role);
    }
    if (query.created === '24h') {
        next = next.gte('created_at', new Date(Date.parse(nowIso) - 24 * 60 * 60 * 1000).toISOString());
    } else if (query.created === '7d') {
        next = next.gte('created_at', new Date(Date.parse(nowIso) - 7 * 24 * 60 * 60 * 1000).toISOString());
    }
    if (query.status === 'deleted') {
        next = next.eq('is_deleted', true);
    } else if (query.status === 'locked') {
        next = next.eq('is_deleted', false).or(hqLoginLockedProfilesOrFilter(nowIso));
    } else if (query.status === 'frozen') {
        next = next.eq('is_deleted', false).or(hqFrozenProfilesOrFilter(nowIso));
    } else if (
        query.status === 'pending' ||
        query.status === 'unsubmitted' ||
        query.status === 'rejected'
    ) {
        next = next.eq('is_deleted', false).eq('role', 'lawyer');
    } else if (query.status === 'active' || query.status === 'name_mismatch') {
        next = next.eq('is_deleted', false);
    }
    const tokens = nameSearch
        ? query.q.split(/\s+/).map(escapeIlike).filter((token) => token.length >= 1)
        : [];
    for (const token of tokens) {
        if (isPostgresUuidSubject(token) || isEmailQuery(token) || isPhoneQuery(token)) continue;
        next = next.or(
            `legal_display_name.ilike.%${token}%,previous_legal_display_name.ilike.%${token}%`,
        );
    }
    return next;
}

async function selectProfilePage(
    admin: SupabaseClient,
    query: HqDirectoryListQuery,
    nowIso: string,
    from: number,
    to: number,
    pinnedId: string | null,
) {
    return withHeadquartersProfileColumns((columns) => {
        const selected = admin.from('profiles').select(columns, { count: 'exact' });
        const filtered = applySqlDirectoryFilters(
            selected as unknown as ProfileChain,
            query,
            nowIso,
            pinnedId,
            columns.includes('legal_display_name'),
        );
        return filtered.order('created_at', { ascending: false }).range(from, to);
    });
}

async function mapProfileRows(
    rows: unknown[],
    identities: Map<string, AuthIdentity>,
    verificationMap: Map<string, HqKvVerificationHint> | null,
): Promise<AdminUser[]> {
    const kvAvailable = verificationMap != null;
    const out: AdminUser[] = [];
    for (const row of rows) {
        if (!row || typeof row !== 'object') continue;
        const id = String((row as { id?: unknown }).id ?? '');
        const identity = identities.get(id) ?? EMPTY_AUTH_IDENTITY;
        const kvHint = verificationMap?.get(id);
        const mapped = mapHeadquartersUser(
            row,
            { ...identity, kycSubmittedName: kvHint?.kycName },
            resolveHqDirectoryKycStatus(kvHint?.status, kvAvailable, identity.appVerificationStatus),
        );
        if (mapped) out.push(mapped);
    }
    return out;
}

function rowMatchesQuery(user: AdminUser, query: HqDirectoryListQuery, nowMs: number): boolean {
    if (!matchesHqUserQuery(user, query.q)) return false;
    if (!matchesHqUserStatusFilter(user, query.status)) return false;
    if (query.role !== 'all' && user.role !== query.role) return false;
    if (!matchesHqUserCreatedFilter(user.createdAt, query.created, nowMs)) return false;
    return true;
}

async function hydrateUsers(
    admin: SupabaseClient,
    rows: unknown[],
): Promise<AdminUser[]> {
    const ids: string[] = [];
    for (const row of rows) {
        if (!row || typeof row !== 'object') continue;
        const id = String((row as { id?: unknown }).id ?? '').trim();
        if (isPostgresUuidSubject(id)) ids.push(id);
    }
    let verificationMap: Map<string, HqKvVerificationHint> | null = new Map();
    try {
        verificationMap = await kvReadUserStatusMapByKeys('lawyer-verification:', ids);
    } catch {
        verificationMap = null;
    }
    const identities = await loadPageIdentities(admin, ids);
    return mapProfileRows(rows, identities, verificationMap);
}

function asRowArray(data: unknown): unknown[] {
    return Array.isArray(data) ? data : [];
}

export async function listHeadquartersUsers(
    admin: SupabaseClient,
    query: HqDirectoryListQuery = EMPTY_HQ_DIRECTORY_QUERY,
): Promise<HqDirectoryListResult> {
    const nowMs = Date.now();
    const nowIso = new Date(nowMs).toISOString();
    let pinnedId: string | null = null;
    if (isPostgresUuidSubject(query.q)) {
        pinnedId = query.q.trim();
    } else if (isEmailQuery(query.q) || isPhoneQuery(query.q)) {
        pinnedId = await lookupAuthSubjectId(admin, query.q);
        if (!pinnedId) {
            const emptyTotal = await countAllProfiles(admin);
            return {
                users: [],
                matched: 0,
                usersTotal: emptyTotal,
                offset: query.offset,
                limit: query.limit,
                hasMore: false,
                matchedExact: true,
                capped: false,
            };
        }
    }

    const scan = needsHqDirectoryPresenceScan(query.status) && !pinnedId;
    const usersTotal = await countAllProfiles(admin);

    if (!scan) {
        const page = await selectProfilePage(
            admin,
            query,
            nowIso,
            query.offset,
            query.offset + query.limit - 1,
            pinnedId,
        );
        if (page.error) {
            throw new Error(page.error.message || 'Failed to list headquarters users');
        }
        const rows = asRowArray(page.data);
        const mapped = await hydrateUsers(admin, rows);
        const users = mapped.filter((user) => rowMatchesQuery(user, query, nowMs));
        const matched = typeof page.count === 'number' ? page.count : query.offset + users.length;
        return {
            users,
            matched,
            usersTotal,
            offset: query.offset,
            limit: query.limit,
            hasMore: query.offset + users.length < matched,
            matchedExact: typeof page.count === 'number',
            capped: false,
        };
    }

    const matches: AdminUser[] = [];
    let scanned = 0;
    let exhausted = false;
    while (scanned < HQ_DIRECTORY_SCAN_CAP && matches.length < query.offset + query.limit) {
        const to = scanned + HQ_DIRECTORY_SCAN_BATCH - 1;
        const batch = await selectProfilePage(admin, query, nowIso, scanned, to, null);
        if (batch.error) {
            throw new Error(batch.error.message || 'Failed to list headquarters users');
        }
        const rows = asRowArray(batch.data);
        if (rows.length === 0) {
            exhausted = true;
            break;
        }
        const mapped = await hydrateUsers(admin, rows);
        for (const user of mapped) {
            if (rowMatchesQuery(user, query, nowMs)) matches.push(user);
        }
        scanned += rows.length;
        if (rows.length < HQ_DIRECTORY_SCAN_BATCH) {
            exhausted = true;
            break;
        }
    }

    const pageUsers = matches.slice(query.offset, query.offset + query.limit);
    const capped = !exhausted && scanned >= HQ_DIRECTORY_SCAN_CAP;
    const matched = exhausted ? matches.length : Math.max(matches.length, query.offset + pageUsers.length + (capped ? 1 : 0));
    return {
        users: pageUsers,
        matched,
        usersTotal,
        offset: query.offset,
        limit: query.limit,
        hasMore: query.offset + pageUsers.length < matched,
        matchedExact: exhausted,
        capped,
    };
}

async function countAllProfiles(admin: SupabaseClient): Promise<number> {
    try {
        const { count, error } = await admin.from('profiles').select('id', { count: 'exact', head: true });
        if (error || typeof count !== 'number') return 0;
        return count;
    } catch {
        return 0;
    }
}

export async function listHeadquartersNotifyRecipientIds(
    admin: SupabaseClient,
): Promise<{ ids: string[]; capped: boolean }> {
    const ids: string[] = [];
    let offset = 0;
    let sawFullPage = true;
    while (ids.length < HEADQUARTERS_NOTIFY_RECIPIENT_CAP && sawFullPage) {
        const to = offset + HEADQUARTERS_NOTIFY_RECIPIENT_PAGE - 1;
        const { data, error } = await admin
            .from('profiles')
            .select('id, role')
            .eq('is_deleted', false)
            .range(offset, to);
        if (error || !Array.isArray(data)) {
            throw new Error(error?.message || 'Failed to list notify recipients');
        }
        sawFullPage = data.length === HEADQUARTERS_NOTIFY_RECIPIENT_PAGE;
        for (const row of data) {
            const id = String((row as { id?: unknown })?.id ?? '').trim();
            const role = (row as { role?: unknown }).role;
            if (!isPostgresUuidSubject(id) || isHeadquartersProtectedAdminId(id)) continue;
            if (isHeadquartersAdminRole(role)) continue;
            ids.push(id);
            if (ids.length >= HEADQUARTERS_NOTIFY_RECIPIENT_CAP) break;
        }
        offset += data.length;
        if (data.length === 0) break;
    }
    return { ids, capped: ids.length >= HEADQUARTERS_NOTIFY_RECIPIENT_CAP && sawFullPage };
}

export type { HqDirectoryListQuery, HqDirectoryListResult };

/** مدة حظر المنتدى من المقر — الواجهة تعرض دائماً / ٢٤ ساعة / ٧ أيام فقط. */

export const HQ_FORUM_BAN_DURATION_HOURS = [24, 168] as const;
export const HQ_FORUM_BAN_TIMED_MAX_MS = 8 * 24 * 60 * 60 * 1000;
export const HQ_FORUM_BAN_PAST_SKEW_MS = 60_000;
export const HQ_FORUM_BAN_REASON_MIN = 3;
export const HQ_FORUM_BAN_NAME_MAX = 80;
export const HQ_FORUM_BAN_REASON_MAX = 240;

export function isHqForumBanActive(expiresAt: string | undefined, nowMs: number = Date.now()): boolean {
    if (!expiresAt) return true;
    const until = Date.parse(expiresAt);
    if (!Number.isFinite(until)) return false;
    return until > nowMs;
}

export function parseHqForumBanExpiry(raw: unknown, nowMs: number = Date.now()): string | undefined | 'invalid' {
    if (raw === undefined || raw === null || raw === '') return undefined;
    if (typeof raw !== 'string') return 'invalid';
    const parsed = Date.parse(raw.trim());
    if (!Number.isFinite(parsed)) return 'invalid';
    if (parsed + HQ_FORUM_BAN_PAST_SKEW_MS < nowMs) return 'invalid';
    if (parsed - nowMs > HQ_FORUM_BAN_TIMED_MAX_MS) return 'invalid';
    return new Date(parsed).toISOString();
}

export function resolveHqForumBanExpiry(
    payload: { durationHours?: unknown; expiresAt?: unknown },
    nowMs: number = Date.now(),
): string | undefined | 'invalid' {
    if (payload.durationHours !== undefined && payload.durationHours !== null && payload.durationHours !== '') {
        const hours = Number(payload.durationHours);
        if (hours === 0) return undefined;
        if (hours === 24 || hours === 168) {
            return new Date(nowMs + hours * 3_600_000).toISOString();
        }
        return 'invalid';
    }
    return parseHqForumBanExpiry(payload.expiresAt, nowMs);
}

