export const HQ_FROZEN_PROFILES_LEGACY_OR = 'is_banned.eq.true,is_active.eq.false';

export function hqFrozenProfilesOrFilter(nowIso: string): string {
    return `freeze_until.gt."${nowIso}",and(freeze_until.is.null,or(is_banned.eq.true,is_active.eq.false,status.eq.suspended,status.eq.banned,status.eq.frozen))`;
}

export function hqLoginLockedProfilesOrFilter(nowIso: string): string {
    return `login_blocked.eq.true,login_until.gt."${nowIso}"`;
}

async function countCurrentlyFrozen(
    admin: SupabaseClient,
    nowIso: string,
): Promise<number | null> {
    const accurate = await headCount(admin, 'profiles', (q) =>
        q.eq('is_deleted', false).or(hqFrozenProfilesOrFilter(nowIso)),
    );
    if (accurate != null) return accurate;
    return headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).or(HQ_FROZEN_PROFILES_LEGACY_OR));
}

/**
 * نبض المقر — أعداد head-only رخيصة + مسح KV للتوثيق.
 * جدول أو استعلام فاشل يُدرج في contentGaps ولا يُعرض صفراً كواقع.
 */
export async function loadHeadquartersStatus(
    admin: SupabaseClient,
    nowMs: number = Date.now(),
): Promise<HeadquartersStatusPayload> {
    const nowIso = new Date(nowMs).toISOString();
    const since24h = new Date(nowMs - 24 * 60 * 60 * 1000).toISOString();
    const since7d = new Date(nowMs - 7 * 24 * 60 * 60 * 1000).toISOString();
    const frozenFilter = hqFrozenProfilesOrFilter(nowIso);
    const lockedFilter = hqLoginLockedProfilesOrFilter(nowIso);

    const [
        usersTotal,
        usersFrozen,
        usersLocked,
        usersFrozenLocked,
        usersLawyer,
        usersModerator,
        usersAdmin,
        usersNew24h,
        usersNew7d,
        pendingReports,
        pendingCommentReports,
        forumPosts,
        forumComments,
        forumBans,
        forumBansPermanent,
        forumBansTimedActive,
        forumDocuments,
        forumPinned,
        forumLocked,
    ] = await Promise.all([
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false)),
        countCurrentlyFrozen(admin, nowIso),
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).or(lockedFilter)),
        headCount(admin, 'profiles', (q) =>
            q.eq('is_deleted', false).or(lockedFilter).or(frozenFilter),
        ),
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).eq('role', 'lawyer')),
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).eq('role', 'moderator')),
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).eq('role', 'admin')),
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).gte('created_at', since24h)),
        headCount(admin, 'profiles', (q) => q.eq('is_deleted', false).gte('created_at', since7d)),
        headCount(admin, 'forum_reports', (q) => q.eq('status', 'pending')),
        headCount(admin, 'forum_comment_reports', (q) => q.eq('status', 'pending')),
        headCount(admin, 'forum_posts', (q) => q.is('group_id', null)),
        headCount(admin, 'forum_comments'),
        headCount(admin, 'forum_bans'),
        headCount(admin, 'forum_bans', (q) => q.is('expires_at', null)),
        headCount(admin, 'forum_bans', (q) => q.gt('expires_at', nowIso)),
        headCount(admin, 'forum_posts', (q) => q.is('group_id', null).not('attachment', 'is', null)),
        headCount(admin, 'forum_posts', (q) => q.is('group_id', null).eq('is_pinned', true)),
        headCount(admin, 'forum_posts', (q) => q.is('group_id', null).eq('is_locked', true)),
    ]);

    const db = usersTotal !== null;
    const total = asCount(usersTotal);
    const frozenRaw = asCount(usersFrozen);
    const lockedKnown = usersLocked != null;
    const locked = asCount(usersLocked);
    const overlap = lockedKnown && usersFrozen != null ? asCount(usersFrozenLocked) : 0;
    /**
     * شارة القائمة: القفل يتقدّم على التجميد.
     * العدد المعروض للمجمّد = مجمّد وليس مقفل الدخول.
     */
    const frozen =
        lockedKnown && usersFrozen != null ? Math.max(0, frozenRaw - overlap) : frozenRaw;
    const activeKnown = usersTotal != null && usersFrozen != null;
    const usersActive = activeKnown
        ? Math.max(0, total - frozenRaw - (lockedKnown ? locked : 0) + overlap)
        : 0;

    let kvOk = true;
    let pendingVerification = 0;
    let verificationApproved = 0;
    let verificationRejected = 0;
    let verificationCapped = false;
    try {
        const { statuses, capped } = await kvReadJsonStatusByPrefix('lawyer-verification:');
        verificationCapped = capped;
        for (const status of statuses) {
            if (status === 'pending') pendingVerification += 1;
            else if (status === 'active') verificationApproved += 1;
            else if (status === 'rejected') verificationRejected += 1;
        }
    } catch {
        kvOk = false;
    }

    let system: HeadquartersSystemState = 'down';
    if (db && kvOk) system = 'connected';
    else if (db) system = 'degraded';

    const contentGaps: string[] = [];
    if (usersTotal == null) contentGaps.push('usersTotal');
    if (usersFrozen == null) contentGaps.push('usersFrozen');
    if (!activeKnown) contentGaps.push('usersActive');
    if (!lockedKnown) contentGaps.push('usersLocked');
    if (usersLawyer == null) contentGaps.push('usersLawyer');
    if (usersModerator == null) contentGaps.push('usersModerator');
    if (usersAdmin == null) contentGaps.push('usersAdmin');
    if (usersNew24h == null) contentGaps.push('usersNew24h');
    if (usersNew7d == null) contentGaps.push('usersNew7d');
    if (!kvOk) contentGaps.push('pendingVerification');
    if (pendingReports == null) contentGaps.push('pendingReports');
    if (pendingCommentReports == null) contentGaps.push('pendingCommentReports');
    if (forumPosts == null) contentGaps.push('forumPosts');
    if (forumComments == null) contentGaps.push('forumComments');
    if (forumBans == null) contentGaps.push('forumBans');
    if (forumBansPermanent == null || forumBansTimedActive == null) contentGaps.push('forumBansActive');
    if (forumDocuments == null) contentGaps.push('forumDocuments');
    if (forumPinned == null) contentGaps.push('forumPinned');
    if (forumLocked == null) contentGaps.push('forumLocked');

    return {
        system,
        db,
        kvOk,
        pendingVerification,
        verificationApproved,
        verificationRejected,
        pendingReports: asCount(pendingReports),
        pendingCommentReports: asCount(pendingCommentReports),
        usersTotal: total,
        usersFrozen: frozen,
        usersLocked: locked,
        usersActive,
        usersLawyer: asCount(usersLawyer),
        usersModerator: asCount(usersModerator),
        usersAdmin: asCount(usersAdmin),
        usersNew24h: asCount(usersNew24h),
        usersNew7d: asCount(usersNew7d),
        forumPosts: asCount(forumPosts),
        forumComments: asCount(forumComments),
        forumBans: asCount(forumBans),
        forumBansActive: asCount(forumBansPermanent) + asCount(forumBansTimedActive),
        forumDocuments: asCount(forumDocuments),
        forumPinned: asCount(forumPinned),
        forumLocked: asCount(forumLocked),
        verificationCapped,
        contentPartial: contentGaps.length > 0,
        contentGaps,
    };
}

import type { SupabaseClient } from '@supabase/supabase-js';
import { emptyHeadquartersStatus, loadHeadquartersStatus, type HeadquartersStatusPayload } from './headquartersStatus.ts';
import { raceBudget } from './promiseBudget.ts';

export const HEADQUARTERS_STATUS_CACHE_TTL_MS = 4_000;
export const HEADQUARTERS_STATUS_BUDGET_MS = 5_000;

type CacheBox = { expiresAt: number; payload: HeadquartersStatusPayload };
let cache: CacheBox | null = null;
let inflight: Promise<HeadquartersStatusPayload> | null = null;

export function resetHeadquartersStatusCacheForTests(): void {
    cache = null;
    inflight = null;
}

/**
 * تجميع طلبات النبض + مهلة صامتة.
 * fresh يتجاوز الذاكرة فقط، لا يتجاوز بوابة المقر أو حد المعدّل.
 */
export async function loadHeadquartersStatusCached(
    admin: SupabaseClient,
    opts?: {
        fresh?: boolean;
        nowMs?: number;
        load?: (client: SupabaseClient, nowMs: number) => Promise<HeadquartersStatusPayload>;
    },
): Promise<HeadquartersStatusPayload> {
    const nowMs = opts?.nowMs ?? Date.now();
    if (!opts?.fresh && cache && cache.expiresAt > nowMs) {
        return cache.payload;
    }
    if (inflight) return inflight;

    const load = opts?.load ?? loadHeadquartersStatus;
    inflight = (async () => {
        const loaded = await raceBudget(load(admin, nowMs), HEADQUARTERS_STATUS_BUDGET_MS);
        if (loaded) {
            cache = { expiresAt: Date.now() + HEADQUARTERS_STATUS_CACHE_TTL_MS, payload: loaded };
            return loaded;
        }
        if (cache) return cache.payload;
        return emptyHeadquartersStatus('down');
    })().finally(() => {
        inflight = null;
    });
    return inflight;
}

import { isPostgresUuidSubject } from './postgresUuidSubject.ts';
import { HAMI_PLATFORM_ADMIN_UUID, getConfiguredAdminUuid } from './roleResolver.ts';
import { type AdminUser, type AdminUserRole, type AdminVerificationStatus } from '@/app/domain/admin/AdminUser';
import { parseAdminVerificationStatus } from '@/app/domain/admin/hqUserPresence';

type ProfileHqRow = {
    id?: unknown;
    role?: unknown;
    status?: unknown;
    created_at?: unknown;
    is_banned?: unknown;
    is_active?: unknown;
    is_deleted?: unknown;
    deleted_at?: unknown;
    freeze_until?: unknown;
    login_until?: unknown;
    login_blocked?: unknown;
    public_verified_badge?: unknown;
    legal_display_name?: unknown;
    previous_legal_display_name?: unknown;
    legal_display_name_corrections?: unknown;
    legal_display_name_corrected_at?: unknown;
};

/** مدير المنصّة الكانوني + ADMIN_UUID إن كان UUID حقيقياً — لا يُحظر ولا يُغيَّر دوره من المقر */
export function isHeadquartersProtectedAdminId(userId: string): boolean {
    const id = String(userId ?? '').trim().toLowerCase();
    if (!isPostgresUuidSubject(id)) return false;
    if (id === HAMI_PLATFORM_ADMIN_UUID.toLowerCase()) return true;
    const configured = getConfiguredAdminUuid().trim().toLowerCase();
    return isPostgresUuidSubject(configured) && id === configured;
}

/** أي حساب بدور إدارة — الواجهة تقفله، والخادم يجب أن يقفله أيضاً. */
export function isHeadquartersAdminRole(role: unknown): boolean {
    return String(role ?? '').trim().toLowerCase() === 'admin';
}

export function mapHeadquartersStatus(row: ProfileHqRow): AdminUser['status'] {
    const untilRaw = (row as { freeze_until?: unknown }).freeze_until;
    if (untilRaw != null && String(untilRaw).trim() !== '') {
        const until = Date.parse(String(untilRaw));
        if (Number.isFinite(until) && until > Date.now()) return 'suspended';
        return 'active';
    }
    const statusRaw = String(row.status ?? '').trim().toLowerCase();
    if (statusRaw === 'banned' || statusRaw === 'suspended' || statusRaw === 'frozen') {
        return 'suspended';
    }
    if (row.is_banned === true || row.is_active === false) return 'suspended';
    return 'active';
}

export function mapHeadquartersRole(raw: unknown): AdminUserRole {
    const role = String(raw ?? '').trim().toLowerCase();
    if (role === 'admin' || role === 'moderator' || role === 'lawyer') {
        return role;
    }
    return 'lawyer';
}

export function mapHeadquartersUser(
    row: ProfileHqRow,
    identity?: {
        email?: string;
        fullName?: string;
        familyName?: string;
        phone?: string;
        governorate?: string;
        lawyerBarRoom?: string;
        kycSubmittedName?: string;
    },
    verificationStatus: AdminVerificationStatus | unknown = 'none',
): AdminUser | null {
    const id = String(row.id ?? '').trim();
    if (!isPostgresUuidSubject(id)) return null;
    const email = String(identity?.email ?? '').trim();
    const given =
        String(row.legal_display_name ?? '').trim() || String(identity?.fullName ?? '').trim();
    const familyName = String(identity?.familyName ?? '').trim();
    const createdAtRaw = row.created_at;
    const createdAt =
        typeof createdAtRaw === 'string' && createdAtRaw.trim()
            ? createdAtRaw.trim()
            : createdAtRaw instanceof Date
              ? createdAtRaw.toISOString()
              : new Date(0).toISOString();
    return {
        id,
        email,
        fullName: given,
        familyName,
        phone: String(identity?.phone ?? '').trim(),
        governorate: String(identity?.governorate ?? '').trim(),
        lawyerBarRoom: String(identity?.lawyerBarRoom ?? '').trim(),
        role: mapHeadquartersRole(row.role),
        status: mapHeadquartersStatus(row),
        createdAt,
        freezeUntil: readIso(row.freeze_until),
        loginUntil: readIso(row.login_until),
        loginBlocked: row.login_blocked === true,
        isDeleted: row.is_deleted === true || Boolean(readIso(row.deleted_at)),
        verificationStatus: parseAdminVerificationStatus(verificationStatus),
        publicVerifiedBadge: row.public_verified_badge === true,
        previousLegalDisplayName: String(row.previous_legal_display_name ?? '').trim() || null,
        legalDisplayNameCorrectedAt: readIso(row.legal_display_name_corrected_at),
        legalDisplayNameCorrections: Number(row.legal_display_name_corrections ?? 0) >= 1 ? 1 : 0,
        kycSubmittedName: String(identity?.kycSubmittedName ?? '').trim() || null,
    };
}

function readIso(raw: unknown): string | null {
    if (raw == null || String(raw).trim() === '') return null;
    const iso = raw instanceof Date ? raw.toISOString() : String(raw).trim();
    return iso || null;
}

