    }
}

export async function fetchHeadquartersUser(
    admin: SupabaseClient,
    userId: string,
): Promise<AdminUser | null> {
    try {
        const { data, error } = await selectHeadquartersProfileById(admin, userId);
        if (error || !data) return null;
        const identity = await loadAuthIdentity(admin, userId);
        let kvAvailable = false;
        let kvValue: unknown;
        let kycSubmittedName = '';
        try {
            const raw = await kvGet(`lawyer-verification:${userId}`);
            kvAvailable = true;
            if (raw && typeof raw === 'object') {
                kvValue = (raw as { status?: unknown }).status;
                kycSubmittedName = String((raw as { fullName?: unknown }).fullName ?? '').trim();
            }
        } catch {
            /* نعتمد app_metadata إن تعذّر KV */
        }
        return mapHeadquartersUser(
            data,
            { ...identity, kycSubmittedName },
            resolveHqDirectoryKycStatus(kvValue, kvAvailable, identity.appVerificationStatus),
        );
    } catch {
        return null;
    }
}

export async function readHeadquartersBanFlags(
    admin: SupabaseClient,
    userId: string,
): Promise<{ frozen: boolean } | null> {
    try {
        const first = await admin
            .from('profiles')
            .select('is_banned, is_active, is_deleted, status, freeze_until')
            .eq('id', userId)
            .maybeSingle();
        const result =
            first.error && isMissingProfileColumn(first.error.message ?? '', 'freeze_until')
                ? await admin
                      .from('profiles')
                      .select('is_banned, is_active, is_deleted, status')
                      .eq('id', userId)
                      .maybeSingle()
                : first;
        const { data, error } = result;
        if (error || !data || (data as { is_deleted?: unknown }).is_deleted === true) {
            return null;
        }
        const freezeUntil = (data as { freeze_until?: unknown }).freeze_until;
        if (freezeUntil != null && String(freezeUntil).trim() !== '') {
            const until = Date.parse(String(freezeUntil));
            if (Number.isFinite(until) && until > Date.now()) return { frozen: true };
            if (Number.isFinite(until) && until <= Date.now()) return { frozen: false };
        }
        const status = String((data as { status?: unknown }).status ?? '')
            .trim()
            .toLowerCase();
        const frozen =
            (data as { is_banned?: unknown }).is_banned === true ||
            (data as { is_active?: unknown }).is_active === false ||
            status === 'suspended' ||
            status === 'banned' ||
            status === 'frozen';
        return { frozen };
    } catch {
        return null;
    }
}

import { isPostgresUuidSubject } from './postgresUuidSubject.ts';
import { isWifeProduction } from './wifeStoreEnv.ts';

const DEV_ACCESS_TOKEN_PREFIX = 'dev-access-token-';

/** إقلاع مقر التطوير فقط — يُغلق في الإنتاج. */
export function isHeadquartersDevUnlockEnabled(): boolean {
    return !isWifeProduction();
}

export function headquartersDevAccessTokenFor(userId: string): string {
    return `${DEV_ACCESS_TOKEN_PREFIX}${userId.trim()}`;
}

export function readBearerAuthorizationToken(request: Request): string | null {
    const raw = request.headers.get('authorization') ?? request.headers.get('Authorization');
    if (!raw) return null;
    const [scheme, token] = raw.split(' ');
    if (!scheme || !token || scheme.toLowerCase() !== 'bearer') return null;
    const normalized = token.trim();
    return normalized || null;
}

/**
 * موضوع توكن التطوير فقط (`dev-access-token-<uuid>`).
 * لا يقبل JWT حياً حتى لا يُستعمل هذا المسار لتجاوز الرمز بحساب حقيقي.
 */
export function parseHeadquartersDevUnlockSubject(token: string): string | null {
    const normalized = token.trim();
    if (!normalized.startsWith(DEV_ACCESS_TOKEN_PREFIX)) return null;
    const subject = normalized.slice(DEV_ACCESS_TOKEN_PREFIX.length).trim();
    if (!isPostgresUuidSubject(subject)) return null;
    if (normalized !== headquartersDevAccessTokenFor(subject)) return null;
    return subject;
}

