import { wifeJsonResponse } from './wifeSecurityHeaders.ts';

/** Postgres `uuid` columns reject `guest-lawyer-1` with 22P02 → HTTP 500. */
const POSTGRES_UUID_RE =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isPostgresUuidSubject(userId: string): boolean {
  return POSTGRES_UUID_RE.test(userId.trim());
}

export function emptyUuidScopedRows(userId: string): Response | null {
  if (isPostgresUuidSubject(userId)) return null;
  return wifeJsonResponse(200, { ok: true, rows: [] });
}

export function emptyUuidScopedEventIds(userId: string): Response | null {
  if (isPostgresUuidSubject(userId)) return null;
  return wifeJsonResponse(200, { ok: true, eventIds: [] });
}

export function rejectNonUuidCloudWrite(userId: string): Response | null {
  if (isPostgresUuidSubject(userId)) return null;
  return wifeJsonResponse(403, {
    ok: false,
    error: 'Cloud identity required',
    code: 'NON_UUID_SUBJECT',
  });
}

/** مهلة صامتة — لا ترمي، تعيد undefined عند النفاد أو الرفض. */
export function raceBudget<T>(promise: Promise<T>, ms: number): Promise<T | undefined> {
    return new Promise((resolve) => {
        const timer = setTimeout(() => resolve(undefined), ms);
        promise.then(
            (value) => {
                clearTimeout(timer);
                resolve(value);
            },
            () => {
                clearTimeout(timer);
                resolve(undefined);
            },
        );
    });
}

import { normalizeWifeMethod } from '@/app/security/wifeRequestSigningShared.ts';
import { isAdminUserId } from './adminCheck.ts';
import { assertSameOriginRequest } from './wifeSameOrigin.ts';
import { verifyCsrfToken } from './wifeCsrfVerify.ts';
import {
    extractUserTokenFromRequest,
    getVerifiedTokenSubject,
    isTokenAuthorized,
    wifeUnauthorizedResponse,
} from './wifeValidator.ts';
import { rejectHeadquartersPublicSurface } from './headquartersOriginGate.ts';
import { wifeJsonResponse } from './wifeSecurityHeaders.ts';

const CSRF_SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

export type HeadquartersCookieAuth =
    | { ok: true; userId: string; token: string }
    | { ok: false; response: Response };

/**
 * جلسة مقر القيادة من كوكي HttpOnly — بلا توقيع WIFE (إقلاع OTP).
 * الأصل + CSRF يمنعان طلبات عبر المواقع حتى مع كوكي الجلسة.
 */
export async function requireHeadquartersCookieAuth(request: Request): Promise<HeadquartersCookieAuth> {
    const surface = rejectHeadquartersPublicSurface(request);
    if (surface) return { ok: false, response: surface };

    if (!assertSameOriginRequest(request)) {
        return {
            ok: false,
            response: wifeJsonResponse(403, { ok: false, error: 'Forbidden origin' }),
        };
    }

    const token = extractUserTokenFromRequest(request);
    if (!token || !(await isTokenAuthorized(token))) {
        return {
            ok: false,
            response: wifeUnauthorizedResponse({ request, reason: 'unauthorized_token' }),
        };
    }
    const method = normalizeWifeMethod(request.method);
    if (!CSRF_SAFE_METHODS.has(method) && !(await verifyCsrfToken(request, token))) {
        return {
            ok: false,
            response: wifeJsonResponse(403, { ok: false, error: 'CSRF validation failed' }),
        };
    }
    const userId = await getVerifiedTokenSubject(token);
    if (!userId) {
        return {
            ok: false,
            response: wifeUnauthorizedResponse({ request, reason: 'unauthorized_token' }),
        };
    }
    if (!(await isAdminUserId(userId, token))) {
        return {
            ok: false,
            response: wifeJsonResponse(403, { ok: false, error: 'Unauthorized Access' }),
        };
    }
    return { ok: true, userId, token };
}

import { HQ_STEP_UP_CODE } from '@/app/domain/admin/hqStepUp';
import { requireWifeUser, unwrapWifeUser } from './bffAuth.ts';
import { isAdminRequest } from './adminCheck.ts';
import {
    isAdminDeviceStepUpFresh,
    isAdminDeviceTrusted,
    isValidDeviceFingerprint,
} from './adminOtpStore.ts';
import { rejectHeadquartersPublicSurface } from './headquartersOriginGate.ts';
import { wifeJsonResponse } from './wifeSecurityHeaders.ts';

export type TrustedHeadquartersAdmin =
    | { ok: true; userId: string; deviceFingerprint: string }
    | { ok: false; response: Response };

export type HeadquartersAdminGateOptions = {
    /** إعادة رمز تحقق خلال نافذة قصيرة للتجميد/الدور/الاعتماد/مسح القوانين. */
    stepUp?: boolean;
};

/**
 * بوابة مقر القيادة عن بعد: جلسة WIFE + مدير منصّة + جهاز موثّق OTP.
 * أي عملية تحكم (حظر / دور / قائمة) تمر من هنا — لا RPC من المتصفح.
 */
export async function requireTrustedHeadquartersAdmin(
    request: Request,
    options?: HeadquartersAdminGateOptions,
): Promise<TrustedHeadquartersAdmin> {
    const surface = rejectHeadquartersPublicSurface(request);
    if (surface) return { ok: false, response: surface };

    const authGate = unwrapWifeUser(await requireWifeUser(request));
    if ('response' in authGate) return { ok: false, response: authGate.response };
    const { userId } = authGate;

    if (!(await isAdminRequest(request, userId))) {
        return {
            ok: false,
            response: wifeJsonResponse(403, { ok: false, error: 'Unauthorized Access' }),
        };
    }

    const deviceFingerprint = String(request.headers.get('x-wife-device-id') ?? '').trim();
    if (!isValidDeviceFingerprint(deviceFingerprint)) {
        return {
            ok: false,
            response: wifeJsonResponse(403, { ok: false, error: 'Trusted device required' }),
        };
    }
    if (!(await isAdminDeviceTrusted({ userId, deviceFingerprint }))) {
        return {
            ok: false,
            response: wifeJsonResponse(403, { ok: false, error: 'Trusted device required' }),
        };
    }
    if (options?.stepUp && !(await isAdminDeviceStepUpFresh({ userId, deviceFingerprint }))) {
        return {
            ok: false,
            response: wifeJsonResponse(403, {
                ok: false,
                error: 'أعد إدخال رمز التحقق لتأكيد هذا الإجراء',
                code: HQ_STEP_UP_CODE,
            }),
        };
    }

    return { ok: true, userId, deviceFingerprint };
}

function firstQueryValue(raw: string | string[] | undefined): string {
    if (Array.isArray(raw)) return raw.map(String).filter(Boolean).join('/');
    return typeof raw === 'string' ? raw : '';
}

/** Catch-all `[...slug]` or rewrite `/api/:slug*` → `/api/handler`. */
export function resolveVercelApiSlug(req: {
    query?: { [key: string]: string | string[] };
    url?: string | null;
}): string {
    const fromQuery = firstQueryValue(req.query?.slug) || firstQueryValue(req.query?.path);
    const cleanedQuery = fromQuery.replace(/^\/+/, '').replace(/\/+$/, '');
    if (cleanedQuery && cleanedQuery !== 'handler' && cleanedQuery !== '[...slug]') {
        return cleanedQuery;
    }
    const pathOnly = (req.url ?? '').split('?')[0] ?? '';
    const stripped = pathOnly.replace(/^\/api\/?/, '').replace(/\/+$/, '');
    if (!stripped || stripped === 'handler' || stripped === '[...slug]') return '';
    return stripped;
}

