/**
 * Server-side role resolution — NEVER trust JWT user_metadata for privileges.
 * Sources: ADMIN_UUID env, canonical UUID, master admin email via GoTrue, profiles.role.
 */
import { UserRole } from '@/app/types/admin-types';
import { HAMI_PLATFORM_ADMIN_UUID } from '@/app/constants/hamiPlatformAdminId.ts';
import { getGoTrueAdminApi, getSupabaseAdminClient } from './supabaseAdminClient.ts';

export { HAMI_PLATFORM_ADMIN_UUID, isHamiPlatformAdminUserId } from '@/app/constants/hamiPlatformAdminId.ts';

const ROLE_CACHE_TTL_MS = 60_000;
const roleCache = new Map<string, { role: string | null; expiresAt: number }>();
const emailCache = new Map<string, { email: string | null; expiresAt: number }>();

const DEFAULT_PLATFORM_ADMIN_EMAIL = 'hami.apps@proton.me';

type ProfileRoleRow = {
  role?: unknown;
  is_banned?: unknown;
  is_deleted?: unknown;
  is_active?: unknown;
};

function normalizeRole(raw: unknown): string | null {
  if (typeof raw !== 'string') return null;
  const trimmed = raw.trim().toLowerCase();
  return trimmed || null;
}

function readCachedRole(userId: string): string | null | undefined {
  const cached = roleCache.get(userId);
  if (!cached) return undefined;
  if (Date.now() >= cached.expiresAt) {
    roleCache.delete(userId);
    return undefined;
  }
  return cached.role;
}

function writeCachedRole(userId: string, role: string | null): void {
  roleCache.set(userId, { role, expiresAt: Date.now() + ROLE_CACHE_TTL_MS });
}

function isInactiveProfile(row: ProfileRoleRow | null | undefined): boolean {
  if (!row) return true;
  if (row.is_banned === true) return true;
  if (row.is_deleted === true) return true;
  if (row.is_active === false) return true;
  return false;
}

/** Test-only */
export function resetRoleResolverCacheForTests(): void {
  roleCache.clear();
  emailCache.clear();
}

/** بعد حظر/تغيير دور من مقر القيادة — لا يبقى الدور القديم 60 ثانية */
export function invalidateProfileRoleCache(userId: string): void {
  const id = userId.trim();
  if (id) {
    roleCache.delete(id);
    emailCache.delete(id);
  }
}

function normalizeEmail(raw: string): string {
  return raw.trim().toLowerCase();
}

function idsEqual(left: string, right: string): boolean {
  return left.trim().toLowerCase() === right.trim().toLowerCase();
}

export function getConfiguredAdminUuid(): string {
  const configured = (process.env.ADMIN_UUID ?? '').trim();
  if (configured) return configured;
  // لا نرجع admin-uuid-1 الوهمي — يمنع رفض المدير الحقيقي بصمت
  return HAMI_PLATFORM_ADMIN_UUID;
}

/** بريد مدير المنصّة — نفس مصدر OTP المقر، مع الافتراضي المتفق عليه */
export function getConfiguredAdminEmails(): string[] {
  const emails = new Set<string>();
  const fromEnv = (process.env.ADMIN_MASTER_EMAIL ?? '').trim();
  const fromVite = (process.env.VITE_ADMIN_MASTER_EMAIL ?? '').trim();
  if (fromEnv) emails.add(normalizeEmail(fromEnv));
  if (fromVite) emails.add(normalizeEmail(fromVite));
  emails.add(DEFAULT_PLATFORM_ADMIN_EMAIL);
  return [...emails];
}

export function isConfiguredAdminEmail(email: string | null | undefined): boolean {
  const normalized = normalizeEmail(email ?? '');
  if (!normalized.includes('@')) return false;
  return getConfiguredAdminEmails().includes(normalized);
}

function readCachedEmail(userId: string): string | null | undefined {
  const cached = emailCache.get(userId);
  if (!cached) return undefined;
  if (Date.now() >= cached.expiresAt) {
    emailCache.delete(userId);
    return undefined;
  }
  return cached.email;
}

function writeCachedEmail(userId: string, email: string | null): void {
  emailCache.set(userId, { email, expiresAt: Date.now() + ROLE_CACHE_TTL_MS });
}

async function readGoTrueEmailForUserId(userId: string): Promise<string | null> {
  const cached = readCachedEmail(userId);
  if (cached !== undefined) return cached;

  const admin = getSupabaseAdminClient();
  if (!admin) {
    writeCachedEmail(userId, null);
    return null;
  }

  try {
    const { data, error } = await getGoTrueAdminApi(admin).getUserById(userId);
    if (error || !data?.user?.email) {
      writeCachedEmail(userId, null);
      return null;
    }
    const email = normalizeEmail(data.user.email);
    writeCachedEmail(userId, email);
    return email;
  } catch {
    writeCachedEmail(userId, null);
    return null;
  }
}

export async function getProfileRole(userId: string): Promise<string | null> {
  if (!userId) return null;

  const cached = readCachedRole(userId);
  if (cached !== undefined) return cached;

  const admin = getSupabaseAdminClient();
  if (!admin) {
    writeCachedRole(userId, null);
    return null;
  }

  const { data, error } = await admin
    .from('profiles')
    .select('role, is_banned, is_deleted, is_active')
    .eq('id', userId)
    .maybeSingle();
  if (error || !data) {
    writeCachedRole(userId, null);
    return null;
  }

  const profile = data as ProfileRoleRow;
  const role = isInactiveProfile(profile) ? null : normalizeRole(profile.role);
  writeCachedRole(userId, role);
  return role;
}

export async function isPlatformAdminUserId(userId: string, liveEmail?: string | null): Promise<boolean> {
  if (!userId) return false;
  const adminUuid = getConfiguredAdminUuid();
  if (adminUuid && idsEqual(userId, adminUuid)) return true;
  if (idsEqual(userId, HAMI_PLATFORM_ADMIN_UUID)) return true;
  if (isConfiguredAdminEmail(liveEmail)) {
    writeCachedEmail(userId, normalizeEmail(liveEmail ?? ''));
    return true;
  }
  const email = await readGoTrueEmailForUserId(userId);
  if (email && isConfiguredAdminEmail(email)) return true;
  const role = await getProfileRole(userId);
  return role === 'admin';
}

export async function isForumModeratorUserId(userId: string): Promise<boolean> {
  if (!userId) return false;
  if (await isPlatformAdminUserId(userId)) return true;
  const role = await getProfileRole(userId);
  return role === 'moderator';
}

export async function canAccessLawyerForumUserId(userId: string): Promise<boolean> {
  if (!userId) return false;
  if (await isPlatformAdminUserId(userId)) return true;
  const role = await getProfileRole(userId);
  return role === 'lawyer' || role === 'moderator' || role === 'admin';
}

export async function resolveForumRoleForUser(userId: string): Promise<UserRole | null> {
  if (await isPlatformAdminUserId(userId)) return UserRole.SUPER_ADMIN;
  const role = await getProfileRole(userId);
  if (role === 'moderator') return UserRole.MODERATOR;
  return null;
}

import { describe, expect, it } from 'vitest';
import { isJsonObjectRecord, sanitizePayload } from './sanitizer.ts';

describe('sanitizePayload', () => {
  it('strips script tags and keeps safe text', () => {
    const input = '<script>alert("xss")</script>Hello';
    const output = sanitizePayload(input);
    expect(output).toBe('Hello');
  });

  it('removes dangerous attributes/protocol payloads from html fragments', () => {
    const input = '<img src=x onerror=alert(1) /><a href="javascript:alert(1)">Click</a>';
    const output = sanitizePayload(input);
    expect(output).toContain('Click');
    expect(output).not.toContain('onerror');
    expect(output).not.toContain('javascript:');
    expect(output).not.toContain('<img');
    expect(output).not.toContain('<a');
  });

  it('sanitizes nested objects and arrays recursively', () => {
    const input = {
      name: '<b>Ali</b>',
      notes: ['<svg onload=alert(1)>x</svg>', 'safe'],
      nested: {
        text: '<iframe src="https://evil.test"></iframe>ok',
      },
    };

    const output = sanitizePayload(input);
    expect(output.name).toBe('Ali');
    expect(output.notes[0]).toBe('');
    expect(output.notes[0]).not.toContain('<svg');
    expect(output.nested.text).toBe('ok');
  });

    it('preserves non-string primitive values and null/undefined safely', () => {
    expect(sanitizePayload(123)).toBe(123);
    expect(sanitizePayload(true)).toBe(true);
    expect(sanitizePayload(null)).toBe(null);
    expect(sanitizePayload(undefined)).toBe(undefined);
  });

  it('drops prototype-pollution keys and does not pollute Object.prototype', () => {
    const poisoned = JSON.parse('{"__proto__":{"polluted":true},"ok":"yes","constructor":{"pro":1}}') as Record<
      string,
      unknown
    >;
    const output = sanitizePayload(poisoned) as Record<string, unknown>;
    expect(output.ok).toBe('yes');
    expect(Object.prototype.hasOwnProperty.call(output, '__proto__')).toBe(false);
    expect(Object.prototype.hasOwnProperty.call(output, 'constructor')).toBe(false);
    expect(({} as { polluted?: boolean }).polluted).toBeUndefined();
  });

  it('rejects arrays as JSON object records', () => {
    expect(isJsonObjectRecord([])).toBe(false);
    expect(isJsonObjectRecord(null)).toBe(false);
    expect(isJsonObjectRecord({ a: 1 })).toBe(true);
  });
});

import DOMPurify from 'isomorphic-dompurify';

type JsonPrimitive = string | number | boolean | null | undefined;
type JsonLike = JsonPrimitive | JsonLike[] | { [key: string]: JsonLike };

const SANITIZE_CONFIG: Readonly<Record<string, unknown>> = {
  ALLOWED_TAGS: [],
  ALLOWED_ATTR: [],
  KEEP_CONTENT: true,
};

const POLLUTION_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

/** كائن JSON عادي — يستثني المصفوفات حتى لا تُعامل كمُدخل سجلّ. */
export function isJsonObjectRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function sanitizeString(value: string): string {
  return DOMPurify.sanitize(value, SANITIZE_CONFIG);
}

export function sanitizePayload<T = JsonLike>(payload: T): T {
  if (typeof payload === 'string') {
    return sanitizeString(payload) as T;
  }

  if (payload === null || payload === undefined) {
    return payload;
  }

  if (Array.isArray(payload)) {
    return payload.map((item) => sanitizePayload(item)) as T;
  }

  if (typeof payload === 'object') {
    const out: Record<string, unknown> = Object.create(null);
    for (const [key, value] of Object.entries(payload as Record<string, unknown>)) {
      if (POLLUTION_KEYS.has(key)) continue;
      out[key] = sanitizePayload(value);
    }
    return out as T;
  }

  return payload;
}

/**
 * HttpOnly session cookies — BFF auth (JWT لا يُخزَّن في localStorage).
 */

export const ACCESS_COOKIE_NAME = 'hami_access_token';
export const REFRESH_COOKIE_NAME = 'hami_refresh_token';

/**
 * Node adapters copy the real `Cookie` header here because undici may drop
 * `Cookie` on `new Request()`. Adapters MUST strip any client-supplied value
 * first and set this only from IncomingMessage.cookie.
 */
export const INCOMING_COOKIE_FALLBACK_HEADER = 'x-hami-incoming-cookie';

export const ACCESS_COOKIE_MAX_AGE_SEC = 60 * 60;
export const REFRESH_COOKIE_MAX_AGE_SEC = 60 * 60 * 24 * 7;

export function isSecureRequest(request: Request): boolean {
    return (
        request.url.startsWith('https://') ||
        (request.headers.get('x-forwarded-proto') ?? '').toLowerCase() === 'https'
    );
}

export function readIncomingCookieHeader(request: Request): string | null {
    const direct = request.headers.get('cookie')?.trim();
    if (direct) return direct;
    const fallback = request.headers.get(INCOMING_COOKIE_FALLBACK_HEADER)?.trim();
    return fallback || null;
}

export function parseCookieHeader(cookieHeader: string | null): Record<string, string> {
    const out: Record<string, string> = {};
    if (!cookieHeader) return out;
    for (const part of cookieHeader.split(';')) {
        const idx = part.indexOf('=');
        if (idx <= 0) continue;
        const name = part.slice(0, idx).trim();
        const value = part.slice(idx + 1).trim();
        if (name) out[name] = value;
    }
    return out;
}

export function parseAccessCookie(cookieHeader: string | null): string | null {
    const raw = parseCookieHeader(cookieHeader)[ACCESS_COOKIE_NAME]?.trim();
    if (!raw) return null;
    try {
        return decodeURIComponent(raw);
    } catch {
        return raw;
    }
}

export function parseRefreshCookie(cookieHeader: string | null): string | null {
    const raw = parseCookieHeader(cookieHeader)[REFRESH_COOKIE_NAME]?.trim();
    if (!raw) return null;
    try {
        return decodeURIComponent(raw);
    } catch {
        return raw;
    }
}

export function readAccessTokenFromRequest(request: Request): string | null {
    return parseAccessCookie(readIncomingCookieHeader(request));
}

export function readRefreshTokenFromRequest(request: Request): string | null {
    return parseRefreshCookie(readIncomingCookieHeader(request));
}

function buildSetCookie(name: string, value: string, maxAgeSec: number, secure: boolean): string {
    const flags = [
        `${name}=${encodeURIComponent(value)}`,
        'Path=/',
        'SameSite=Strict',
        'HttpOnly',
        `Max-Age=${maxAgeSec}`,
    ];
    if (secure) flags.push('Secure');
    return flags.join('; ');
}

function buildClearCookie(name: string, secure: boolean): string {
    const flags = [`${name}=`, 'Path=/', 'SameSite=Strict', 'HttpOnly', 'Max-Age=0'];
    if (secure) flags.push('Secure');
    return flags.join('; ');
}

export function buildAccessSetCookie(token: string, secure: boolean, maxAgeSec = ACCESS_COOKIE_MAX_AGE_SEC): string {
    return buildSetCookie(ACCESS_COOKIE_NAME, token, maxAgeSec, secure);
}

export function buildRefreshSetCookie(token: string, secure: boolean, maxAgeSec = REFRESH_COOKIE_MAX_AGE_SEC): string {
    return buildSetCookie(REFRESH_COOKIE_NAME, token, maxAgeSec, secure);
}

export function buildClearSessionCookies(secure: boolean): string[] {
    return [buildClearCookie(ACCESS_COOKIE_NAME, secure), buildClearCookie(REFRESH_COOKIE_NAME, secure)];
}

export function getSupabaseAuthConfigFromEnv(): { url: string; key: string } | null {
    const supabaseUrl = (process.env.SUPABASE_URL ?? '').trim();
    const supabaseKey = (process.env.SUPABASE_ANON_KEY ?? '').trim();
    if (!supabaseUrl || !supabaseKey) return null;
    return { url: supabaseUrl.replace(/\/+$/, ''), key: supabaseKey };
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
