  });

  afterEach(() => {
    vi.restoreAllMocks();
  });

  it('يقرأ توكن Supabase الحقيقي — لا jti بل session_id', () => {
    const fields = extractJwtSessionFields(supabaseToken({ sub: 'user-shape' }));
    expect(fields).not.toBeNull();
    expect(fields?.sessionId).toBe('11111111-2222-3333-4444-555555555555');
  });

  it('registers first seen token in memory store (non-production)', async () => {
    const token = supabaseToken({ sub: 'user-a' });

    const first = await detectStolenTokenServer(token, 'device-aaaaaaaa');
    expect(first.status).toBe('valid');

    const registered = await registerTokenSessionServer(token, 'device-aaaaaaaa');
    expect(registered).toBe(true);
  });

  it('flags cloned token when the same session arrives without a device id', async () => {
    const token = supabaseToken({ sub: 'user-empty-device', sessionId: 'session-empty-dev' });

    await registerTokenSessionServer(token, 'device-bound0001');
    const verdict = await detectStolenTokenServer(token, '');
    expect(verdict.status).toBe('cloned');
  });

  it('flags stolen token when an unregistered older session is replayed', async () => {
    const older = supabaseToken({
      sub: 'user-c',
      sessionId: 'session-old',
      iat: nowSec() - 600,
    });
    const newer = supabaseToken({ sub: 'user-c', sessionId: 'session-new' });

    await registerTokenSessionServer(newer, 'device-dddddddd');
    const verdict = await detectStolenTokenServer(older, 'device-dddddddd');
    expect(verdict.status).toBe('stolen');
  });

  /*
   * الحالتان التاليتان تحرسان ضدّ الحبس الكاذب: تجديد التوكن كل ساعة، ومحامٍ
   * يعمل على هاتف ولوح في آن. كلاهما سلوك يومي، وإطلاق حكم «مسروق» عليه يقفل
   * الإضبارة في وجه صاحبها.
   */
  it('لا يحبس تجديد التوكن — الجلسة نفسها بطابع زمني أحدث', async () => {
    const sub = 'user-refresh';
    const sessionId = 'session-kept-across-refresh';
    const initial = supabaseToken({ sub, sessionId, iat: nowSec() - 3600 });
    await detectStolenTokenServer(initial, 'device-eeeeeeee');

    const refreshed = supabaseToken({ sub, sessionId, iat: nowSec() });
    const verdict = await detectStolenTokenServer(refreshed, 'device-eeeeeeee');

    expect(verdict.status).toBe('valid');
  });

  it('لا يحبس جهازين لنفس المحامي — جلستان مسجّلتان', async () => {
    const sub = 'user-two-devices';
    const phone = supabaseToken({ sub, sessionId: 'session-phone', iat: nowSec() - 1800 });
    const tablet = supabaseToken({ sub, sessionId: 'session-tablet', iat: nowSec() });

    expect((await detectStolenTokenServer(phone, 'device-phone0001')).status).toBe('valid');
    expect((await detectStolenTokenServer(tablet, 'device-tablet01')).status).toBe('valid');
    // الهاتف يعود بعد دخول اللوح: جلسته مسجّلة فلا يُقرأ كتوكن قديم مُعاد
    expect((await detectStolenTokenServer(phone, 'device-phone0001')).status).toBe('valid');
  });

  it('validates device id format for production binding', () => {
    expect(isValidWifeDeviceId('device-aaaaaaaa')).toBe(true);
    expect(isValidWifeDeviceId('short')).toBe(false);
    expect(isValidWifeDeviceId('')).toBe(false);
    expect(isValidWifeDeviceId('<script>')).toBe(false);
  });
});

/** حمولة على شكل توكن Supabase: session_id مطلوب، jti غائب */
function supabaseToken(options: { sub: string; sessionId?: string; iat?: number }): string {
  const iat = options.iat ?? nowSec();
  return buildFakeJwt({
    iss: 'https://project.supabase.co/auth/v1',
    aud: 'authenticated',
    role: 'authenticated',
    aal: 'aal1',
    email: 'lawyer@example.iq',
    phone: '',
    is_anonymous: false,
    session_id: options.sessionId ?? '11111111-2222-3333-4444-555555555555',
    sub: options.sub,
    iat,
    exp: iat + 3600,
  });
}

function buildFakeJwt(payload: Record<string, unknown>): string {
  const header = b64Json({ alg: 'HS256', typ: 'JWT' });
  const body = b64Json(payload);
  return `${header}.${body}.signature`;
}

function b64Json(value: Record<string, unknown>): string {
  return Buffer.from(JSON.stringify(value)).toString('base64url');
}

/**
 * Server-side stolen/cloned JWT detection for WIFE.
 * Persistence: Redis → Supabase → in-memory (see stolenTokenStores.ts).
 */
import { extractJwtSessionFields } from '@/app/security/jwtFields.ts';
import { getWifeEnv, isWifeProduction } from './wifeStoreEnv.ts';
import {
  resetStolenTokenMemoryForTests,
  withStolenTokenStore,
  type TokenSessionRecord,
} from './stolenTokenStores.ts';

const IAT_GRACE_PERIOD_MS = 45_000;
const SESSION_RETENTION_MS = 7 * 24 * 60 * 60 * 1000;
const DEVICE_ID_RE = /^[A-Za-z0-9\-_]{8,128}$/;
/** أحكام «سليم» التي تستوجب تثبيت الجلسة في المخزن بعد إصدارها */
const REGISTERABLE_REASONS = new Set(['first-seen', 'new-session', 'refreshed']);

export type StolenTokenStatus = 'valid' | 'stolen' | 'cloned';

export interface StolenTokenVerdict {
  status: StolenTokenStatus;
  reason?: string;
}

function normalizeDeviceId(raw: string | null | undefined): string {
  const trimmed = (raw ?? '').trim();
  if (!trimmed || !DEVICE_ID_RE.test(trimmed)) return '';
  return trimmed;
}

export function isValidWifeDeviceId(raw: string | null | undefined): boolean {
  return normalizeDeviceId(raw).length > 0;
}

export function extractDeviceIdFromRequest(req: Request): string {
  const raw =
    req.headers.get('x-wife-device-id') ??
    req.headers.get('X-WIFE-Device-Id') ??
    '';
  return normalizeDeviceId(raw);
}

export async function registerTokenSessionServer(
  token: string,
  deviceId: string,
): Promise<boolean> {
  const fields = extractJwtSessionFields(token);
  if (!fields) return false;

  const normalized = normalizeDeviceId(deviceId);
  if (!normalized) return false;

  const record: TokenSessionRecord = {
    sub: fields.sub,
    sessionId: fields.sessionId,
    iat: fields.iat,
    deviceId: normalized,
    expiresAt: fields.exp + SESSION_RETENTION_MS,
  };

  const result = await withStolenTokenStore(async (store) => {
    await store.upsertSession(record);
    return true;
  });
  return result ?? false;
}

export async function detectStolenTokenServer(
  token: string,
  deviceId: string,
): Promise<StolenTokenVerdict> {
  const fields = extractJwtSessionFields(token);
  if (!fields) return { status: 'valid', reason: 'cannot-decode' };

  const nowMs = Date.now();
  const normalizedDeviceId = normalizeDeviceId(deviceId);

  const storeResult = await withStolenTokenStore(async (store) => {
    await store.deleteExpired(nowMs);
    const activeRecords = await store.listActiveBySub(fields.sub, nowMs);

    if (activeRecords.length === 0) {
      return { status: 'valid' as const, reason: 'first-seen' };
    }

    const matchingRecord = activeRecords.find((r) => r.sessionId === fields.sessionId);
    if (matchingRecord) {
      if (matchingRecord.deviceId && matchingRecord.deviceId !== normalizedDeviceId) {
        if (
          normalizedDeviceId &&
          getWifeEnv('NODE_ENV').toLowerCase() === 'development' &&
          getWifeEnv('VITEST') !== 'true'
        ) {
          return { status: 'valid' as const, reason: 'refreshed' };
        }
        return {
          status: 'cloned' as const,
          reason: 'Same session from a different device',
        };
      }
      if (fields.iat > matchingRecord.iat) {
        return { status: 'valid' as const, reason: 'refreshed' };
      }
      return { status: 'valid' as const, reason: 'match' };
    }

    const latestRecord = activeRecords.reduce(
      (latest, r) => (r.iat > latest.iat ? r : latest),
      activeRecords[0],
    );
    if (fields.iat < latestRecord.iat - IAT_GRACE_PERIOD_MS) {
      return {
        status: 'stolen' as const,
        reason: 'Unregistered session older than an active one',
      };
    }

    return { status: 'valid' as const, reason: 'new-session' };
  });

  if (!storeResult) {
    if (isWifeProduction()) {
      return { status: 'stolen', reason: 'session-store-unavailable-fail-closed' };
    }
    return { status: 'valid', reason: 'store-unavailable' };
  }

  if (storeResult.status === 'valid' && REGISTERABLE_REASONS.has(storeResult.reason ?? '')) {
    await registerTokenSessionServer(token, normalizedDeviceId);
  }

  return storeResult;
}

export async function revokeTokenSessionsForSubject(subject: string): Promise<void> {
  const trimmed = subject.trim();
  if (!trimmed) return;
  const nowMs = Date.now();
  await withStolenTokenStore(async (store) => {
    await store.deleteActiveBySub(trimmed, nowMs);
    return true;
  });
}

export function resetStolenTokenServerForTests(): void {
  resetStolenTokenMemoryForTests();
}

import { getSupabaseAdminClient } from './supabaseAdminClient.ts';
import { supabasePrivilegedKeyEnvName } from './supabasePrivilegedEnv.ts';
import { wifeRedisJson } from './wifeRedisRest.ts';
import { getWifeEnv, hasWifeRedisConfig, isWifeProduction } from './wifeStoreEnv.ts';

const DEFAULT_SESSION_TABLE = 'wife_token_sessions';

export type TokenSessionRecord = {
  sub: string;
  /** `session_id` من توكن Supabase — يُخزَّن في عمود اسمه `jti` تاريخياً */
  sessionId: string;
  iat: number;
  deviceId: string;
  expiresAt: number;
};

export type StolenTokenSessionStore = {
  listActiveBySub(sub: string, nowMs: number): Promise<TokenSessionRecord[]>;
  upsertSession(record: TokenSessionRecord): Promise<void>;
  deleteExpired(nowMs: number): Promise<void>;
  deleteActiveBySub(sub: string, nowMs: number): Promise<void>;
};

const IN_MEMORY_SESSIONS = new Map<string, TokenSessionRecord>();

function sessionKey(sub: string, sessionId: string): string {
  return `${sub}:${sessionId}`;
}

function pruneInMemory(nowMs: number): void {
  for (const [key, record] of IN_MEMORY_SESSIONS.entries()) {
    if (record.expiresAt <= nowMs) IN_MEMORY_SESSIONS.delete(key);
  }
}

const memoryStore: StolenTokenSessionStore = {
  async listActiveBySub(sub: string, nowMs: number): Promise<TokenSessionRecord[]> {
    pruneInMemory(nowMs);
    return [...IN_MEMORY_SESSIONS.values()].filter((r) => r.sub === sub && r.expiresAt > nowMs);
  },
  async upsertSession(record: TokenSessionRecord): Promise<void> {
    IN_MEMORY_SESSIONS.set(sessionKey(record.sub, record.sessionId), record);
  },
  async deleteExpired(nowMs: number): Promise<void> {
    pruneInMemory(nowMs);
  },
  async deleteActiveBySub(sub: string, nowMs: number): Promise<void> {
    pruneInMemory(nowMs);
    for (const [key, record] of IN_MEMORY_SESSIONS.entries()) {
      if (record.sub === sub && record.expiresAt > nowMs) IN_MEMORY_SESSIONS.delete(key);
    }
  },
};

function redisSessionKey(sub: string, sessionId: string): string {
  return encodeURIComponent(`wife:toksess:${sub}:${sessionId}`);
}

async function redisScanTokenSessionKeys(sub: string): Promise<string[]> {
  const prefix = encodeURIComponent(`wife:toksess:${sub}:`);
  const scan = await wifeRedisJson(`/keys/${prefix}*`);
  if (!scan.ok) throw new Error(`Redis session scan failed: ${scan.status}`);
  return Array.isArray(scan.result) ? scan.result.filter((k): k is string => typeof k === 'string') : [];
}

async function redisReadTokenSession(key: string): Promise<TokenSessionRecord | null> {
  const get = await wifeRedisJson(`/get/${encodeURIComponent(key)}`);
  if (!get.ok || typeof get.result !== 'string' || !get.result) return null;
  try {
    return JSON.parse(get.result) as TokenSessionRecord;
  } catch {
    return null;
  }
}

const redisStore: StolenTokenSessionStore = {
  async listActiveBySub(sub: string, nowMs: number): Promise<TokenSessionRecord[]> {
    const keys = await redisScanTokenSessionKeys(sub);
    const records: TokenSessionRecord[] = [];
    for (const key of keys) {
      const parsed = await redisReadTokenSession(key);
      if (parsed && parsed.sub === sub && parsed.expiresAt > nowMs) records.push(parsed);
    }
    return records;
  },
  async upsertSession(record: TokenSessionRecord): Promise<void> {
    const ttlMs = Math.max(60_000, record.expiresAt - Date.now());
    const key = redisSessionKey(record.sub, record.sessionId);
    const response = await wifeRedisJson(
      `/set/${key}/${encodeURIComponent(JSON.stringify(record))}?PX=${ttlMs}`,
      'POST',
    );
    if (!response.ok) throw new Error(`Redis session set failed: ${response.status}`);
  },
  async deleteExpired(_nowMs: number): Promise<void> {
    /* Redis TTL handles expiry */
  },
  async deleteActiveBySub(sub: string, nowMs: number): Promise<void> {
    const keys = await redisScanTokenSessionKeys(sub);
    for (const key of keys) {
      const parsed = await redisReadTokenSession(key);
      if (!parsed || parsed.sub !== sub || parsed.expiresAt <= nowMs) continue;
      await wifeRedisJson(`/del/${encodeURIComponent(key)}`, 'POST');
    }
  },
};

function hasSupabaseConfig(): boolean {
  return Boolean(getWifeEnv('SUPABASE_URL') && getWifeEnv(supabasePrivilegedKeyEnvName()));
}

const supabaseStore: StolenTokenSessionStore = {
  async listActiveBySub(sub: string, nowMs: number): Promise<TokenSessionRecord[]> {
    const admin = getSupabaseAdminClient();
    if (!admin) throw new Error('Supabase session store is not configured.');
    const table = getWifeEnv('WIFE_TOKEN_SESSION_TABLE') || DEFAULT_SESSION_TABLE;

    void admin.from(table).delete().lt('expires_at_ms', nowMs);

    const { data, error } = await admin
      .from(table)
      .select('sub,jti,iat_ms,device_id,expires_at_ms')
      .eq('sub', sub)
      .gt('expires_at_ms', nowMs);
    if (error) throw new Error(`Supabase session list failed: ${error.message}`);

    return (data ?? []).map((row: Record<string, unknown>) => ({
      sub: String(row.sub ?? ''),
      sessionId: String(row.jti ?? ''),
      iat: Number(row.iat_ms ?? 0),
      deviceId: String(row.device_id ?? ''),
      expiresAt: Number(row.expires_at_ms ?? 0),
    }));
  },
  async upsertSession(record: TokenSessionRecord): Promise<void> {
    const admin = getSupabaseAdminClient();
    if (!admin) throw new Error('Supabase session store is not configured.');
    const table = getWifeEnv('WIFE_TOKEN_SESSION_TABLE') || DEFAULT_SESSION_TABLE;

    const { error } = await admin.from(table).upsert(
      {
        sub: record.sub,
        jti: record.sessionId,
        iat_ms: record.iat,
        device_id: record.deviceId,
        expires_at_ms: record.expiresAt,
      },
      { onConflict: 'sub,jti' },
    );
    if (error) throw new Error(`Supabase session upsert failed: ${error.message}`);
  },
  async deleteExpired(nowMs: number): Promise<void> {
    const admin = getSupabaseAdminClient();
    if (!admin) return;
    const table = getWifeEnv('WIFE_TOKEN_SESSION_TABLE') || DEFAULT_SESSION_TABLE;
    void admin.from(table).delete().lt('expires_at_ms', nowMs);
  },
  async deleteActiveBySub(sub: string, nowMs: number): Promise<void> {
    const admin = getSupabaseAdminClient();
    if (!admin) throw new Error('Supabase session store is not configured.');
    const table = getWifeEnv('WIFE_TOKEN_SESSION_TABLE') || DEFAULT_SESSION_TABLE;
    const { error } = await admin.from(table).delete().eq('sub', sub).gt('expires_at_ms', nowMs);
    if (error) throw new Error(`Supabase session revoke failed: ${error.message}`);
  },
};

function resolvePrimaryStore(): StolenTokenSessionStore | null {
  if (hasWifeRedisConfig()) return redisStore;
  if (hasSupabaseConfig()) return supabaseStore;
  if (!isWifeProduction()) return memoryStore;
  return null;
}

export async function withStolenTokenStore<T>(
  fn: (store: StolenTokenSessionStore) => Promise<T>,
): Promise<T | null> {
  const primary = resolvePrimaryStore();
  if (!primary) return null;
  try {
    return await fn(primary);
  } catch {
    if (isWifeProduction()) return null;
    return fn(memoryStore);
  }
}

