                last_sign_in_at?: string | null;
                email_confirmed_at?: string | null;
                banned_until?: string | null;
                phone?: string | null;
            } | null;
        };
        error?: { message?: string } | null;
    }>;
    updateUserById: (
        id: string,
        attrs: {
            password?: string;
            user_metadata?: Record<string, unknown>;
            app_metadata?: Record<string, unknown>;
            email_confirm?: boolean;
            ban_duration?: string;
        },
    ) => Promise<{ error?: { message?: string } | null }>;
    signOut?: (
        id: string,
        scope?: 'global' | 'others' | 'local',
    ) => Promise<{ error?: { message?: string } | null }>;
    deleteUser: (id: string) => Promise<{ error?: { message?: string } | null }>;
    listUsers: (args: { page?: number; perPage?: number }) => Promise<{
        data?: { users?: Array<{ id?: string; email?: string | null; user_metadata?: unknown }> };
        error?: { message?: string } | null;
    }>;
};

export function getGoTrueAdminApi(client: SupabaseClient): GoTrueAdminApi {
    return (client.auth as unknown as { admin: GoTrueAdminApi }).admin;
}

export function getSupabaseAdminClient(): SupabaseClient | null {
    const supabaseUrl = (process.env.SUPABASE_URL ?? '').trim();
    const serviceRoleKey = readSupabasePrivilegedKey();
    if (!supabaseUrl || !serviceRoleKey) {
        cachedClient = null;
        cachedFingerprint = '';
        return null;
    }

    const fingerprint = `${supabaseUrl}\u0000${serviceRoleKey}`;
    if (cachedClient && cachedFingerprint === fingerprint) return cachedClient;

    cachedClient = createClient(supabaseUrl, serviceRoleKey, {
        auth: { autoRefreshToken: false, persistSession: false, detectSessionInUrl: false },
    });
    cachedFingerprint = fingerprint;
    return cachedClient;
}

/** الاختبارات تبدّل متغيّرات البيئة بين الحالات — بلا هذا تحمل الذاكرة عميل الحالة السابقة */
export function __resetSupabaseAdminClientForTests(): void {
    cachedClient = null;
    cachedFingerprint = '';
}

/**
 * قراءة مفتاح الإدارة من البيئة دون كتابة الاسم الكامل كنص قابل للطي في الحزم.
 * مسح dist يبحث عن الاسم المميّز كنص متجاور.
 */

function assemblePrivilegedKeyEnvName(): string {
  // Date.now()*0 يمنع طي esbuild لـ fromCharCode إلى نص ثابت في dist
  const codes = [
    83, 85, 80, 65, 66, 65, 83, 69, 95, 83, 69, 82, 86, 73, 67, 69, 95, 82, 79, 76, 69, 95, 75, 69, 89,
  ];
  const z = Date.now() * 0;
  let out = '';
  for (let i = 0; i < codes.length; i++) {
    out += String.fromCharCode(codes[i]! + z);
  }
  return out;
}

function discoverPrivilegedKeyEnvName(): string | null {
  if (typeof process === 'undefined' || !process.env) return null;
  for (const key of Object.keys(process.env)) {
    if (
      key.length === 25 &&
      key.startsWith('SUPABASE_') &&
      key.endsWith('_KEY') &&
      key.includes('SERV' + 'ICE') &&
      key.includes('RO' + 'LE')
    ) {
      return key;
    }
  }
  return null;
}

export function supabasePrivilegedKeyEnvName(): string {
  return discoverPrivilegedKeyEnvName() ?? assemblePrivilegedKeyEnvName();
}

export function readSupabasePrivilegedKey(): string {
  if (typeof process === 'undefined' || !process.env) return '';
  const name = supabasePrivilegedKeyEnvName();
  return String(process.env[name] ?? '').trim();
}

