import { extractJwtSessionFields } from '@/app/security/jwtFields.ts';
import { CSRF_COOKIE_NAME, CSRF_META_NAME } from '@/app/security/csrfConstants.ts';
import { normalizeWifeMethod } from '@/app/security/wifeRequestSigningShared.ts';
import { readCsrfTokenForSubject, validateCsrfForSubject } from './csrfServerStore.ts';
import { parseCookieHeader, readIncomingCookieHeader } from './sessionCookie.ts';
import { isWifeProduction as isProductionNodeEnv } from './wifeStoreEnv.ts';
import { wifeTimingSafeEqual } from './wifeTimingSafe.ts';
import { getVerifiedTokenSubject } from './wifeTokenSubject.ts';

function getCsrfTokenHeader(req: Request): string | null {
    return req.headers.get(CSRF_META_NAME) ?? null;
}

function cookieMatchesCsrfHeader(req: Request, csrfToken: string): boolean {
    const cookieHeader = readIncomingCookieHeader(req);
    if (!cookieHeader || !cookieHeader.trim()) return false;

    const cookies = parseCookieHeader(cookieHeader);
    const csrfCookieRaw = cookies[CSRF_COOKIE_NAME];
    if (!csrfCookieRaw || !csrfCookieRaw.trim()) return false;

    let csrfCookie = csrfCookieRaw.trim();
    try {
        csrfCookie = decodeURIComponent(csrfCookie);
    } catch {
        /* use raw */
    }

    if (csrfCookie.length < 16 || csrfCookie.length > 128) return false;
    if (!/^[A-Za-z0-9\-_]+$/.test(csrfCookie)) return false;

    return wifeTimingSafeEqual(csrfToken, csrfCookie);
}

/**
 * Server-side CSRF validation (double-submit cookie pattern).
 * Mutating methods also require the subject-bound server registry in production.
 *
 * Non-production registry miss (Vite duplicate module graphs) may fall back to
 * header === HttpOnly cookie. A registry *mismatch* still rejects (subject binding).
 */
export async function verifyCsrfToken(req: Request, userToken: string): Promise<boolean> {
    const method = normalizeWifeMethod(req.method);
    const safeMethods = ['GET', 'HEAD', 'OPTIONS'];
    if (safeMethods.includes(method)) return true;

    const csrfToken = getCsrfTokenHeader(req)?.trim();
    if (!csrfToken || csrfToken.length < 16 || csrfToken.length > 128) return false;
    if (!/^[A-Za-z0-9\-_]+$/.test(csrfToken)) return false;

    const verifiedSub = await getVerifiedTokenSubject(userToken);
    if (verifiedSub) {
        if (await validateCsrfForSubject(verifiedSub, csrfToken)) return true;
        if (isProductionNodeEnv()) return false;
        // Registry mismatch stays rejected; empty registry may use cookie double-submit in dev.
        if (await readCsrfTokenForSubject(verifiedSub)) return false;
        return cookieMatchesCsrfHeader(req, csrfToken);
    }

    const jwtFields = extractJwtSessionFields(userToken);
    if (jwtFields?.sub) {
        const serverValid = await validateCsrfForSubject(jwtFields.sub, csrfToken);
        if (serverValid) return true;
        if (isProductionNodeEnv()) return false;
        return true;
    }

    if (cookieMatchesCsrfHeader(req, csrfToken)) return true;

    const cookieHeader = readIncomingCookieHeader(req);
    if (!cookieHeader?.trim()) return !isProductionNodeEnv();
    const csrfCookieRaw = parseCookieHeader(cookieHeader)[CSRF_COOKIE_NAME];
    if (!csrfCookieRaw?.trim()) return !isProductionNodeEnv();
    return false;
}

import {
  buildWifeTokenCanonicalPayload,
  canonicalWifePathAndQuery,
  randomWifeNonce,
  sha256Bytes,
  toBase64Url,
  toBufferSource,
} from '@/app/security/wifeRequestSigningShared.ts';

const HMAC_ALGORITHM = 'HMAC';
const HASH_ALGORITHM = 'SHA-256';
const HMAC_KEY_CACHE_TTL_MS = 60_000;
const HMAC_KEY_CACHE_MAX = 500;

const hmacKeyCache = new Map<string, { key: CryptoKey; expiresAt: number }>();

function pruneHmacKeyCache(nowMs: number): void {
  if (hmacKeyCache.size <= HMAC_KEY_CACHE_MAX) return;
  for (const [key, entry] of hmacKeyCache.entries()) {
    if (entry.expiresAt <= nowMs) hmacKeyCache.delete(key);
    if (hmacKeyCache.size <= HMAC_KEY_CACHE_MAX * 0.75) break;
  }
}

async function getOrCreateHmacKey(userToken: string): Promise<CryptoKey> {
  const combinedKeyMaterial = `${userToken}:wife-sign-v1`;
  const tokenHash = await sha256Bytes(combinedKeyMaterial);
  const cacheKey = toBase64Url(tokenHash);
  const nowMs = Date.now();
  pruneHmacKeyCache(nowMs);

  const cached = hmacKeyCache.get(cacheKey);
  if (cached && cached.expiresAt > nowMs) return cached.key;

  const key = await crypto.subtle.importKey(
    'raw',
    toBufferSource(tokenHash),
    { name: HMAC_ALGORITHM, hash: HASH_ALGORITHM },
    false,
    ['sign'],
  );
  hmacKeyCache.set(cacheKey, { key, expiresAt: nowMs + HMAC_KEY_CACHE_TTL_MS });
  return key;
}

export async function createHmacSignature(payload: string, userToken: string): Promise<string> {
  const key = await getOrCreateHmacKey(userToken);
  const payloadBytes = new TextEncoder().encode(payload);
  const signature = await crypto.subtle.sign(HMAC_ALGORITHM, key, toBufferSource(payloadBytes));
  return toBase64Url(new Uint8Array(signature));
}

/** Server-side WIFE header builder — used by /api/security/wife-sign (HttpOnly BFF). */
export async function createWifeSignedHeaders(
  method: string,
  url: string,
  body: string,
  userToken: string,
  contentHash?: string,
): Promise<Record<string, string>> {
  const timestamp = String(Date.now());
  const nonce = randomWifeNonce();
  const payload = buildWifeTokenCanonicalPayload(method, canonicalWifePathAndQuery(url), timestamp, nonce, body);
  const signature = await createHmacSignature(payload, userToken);
  const headers: Record<string, string> = {
    'X-WIFE-Signature': signature,
    'X-WIFE-Timestamp': timestamp,
    'X-WIFE-Nonce': nonce,
  };
  if (contentHash) {
    headers['X-WIFE-Content-Hash'] = contentHash;
  }
  return headers;
}

export function resetWifeHmacKeyCacheForTests(): void {
  hmacKeyCache.clear();
}

/**
 * Distributed nonce store adapter for WIFE anti-replay protection.
 *
 * Priority:
 * 1) Redis (Upstash REST) when configured
 * 2) Supabase PostgREST table fallback
 * 3) Ephemeral in-memory fallback (development safety net)
 *
 * Notes:
 * - Redis path is atomic using SET NX PX.
 * - Supabase path expects a unique constraint on "nonce" column to enforce atomicity.
 */

import { supabasePrivilegedKeyEnvName } from './supabasePrivilegedEnv.ts';
import { wifeRedisJson } from './wifeRedisRest.ts';
import { getWifeEnv, hasWifeRedisConfig, isWifeProduction } from './wifeStoreEnv.ts';

const DEFAULT_NONCE_TABLE = 'wife_nonce_store';
const IN_MEMORY_NONCE_FALLBACK = new Map<string, number>();

type NonceStore = {
  consumeNonce(nonce: string, nowMs: number, ttlMs: number): Promise<boolean>;
};

function buildNonceKey(nonce: string): string {
  return `wife:nonce:${nonce}`;
}

function pruneInMemory(nowMs: number): void {
  for (const [nonce, expiresAt] of IN_MEMORY_NONCE_FALLBACK.entries()) {
    if (expiresAt <= nowMs) IN_MEMORY_NONCE_FALLBACK.delete(nonce);
  }
}

const memoryStore: NonceStore = {
  async consumeNonce(nonce: string, nowMs: number, ttlMs: number): Promise<boolean> {
    pruneInMemory(nowMs);
    if (IN_MEMORY_NONCE_FALLBACK.has(nonce)) return false;
    IN_MEMORY_NONCE_FALLBACK.set(nonce, nowMs + ttlMs);
    return true;
  },
};

const redisStore: NonceStore = {
  async consumeNonce(nonce: string, _nowMs: number, ttlMs: number): Promise<boolean> {
    const key = encodeURIComponent(buildNonceKey(nonce));
    const response = await wifeRedisJson(`/set/${key}/1?NX=true&PX=${ttlMs}`, 'POST');
    if (!response.ok) {
      throw new Error(`Redis nonce store failed: ${response.status}`);
    }
    // Upstash returns { result: "OK" } when SET NX succeeds.
    return response.result === 'OK';
  },
};

function hasSupabaseConfig(): boolean {
  return Boolean(getWifeEnv('SUPABASE_URL') && (getWifeEnv(supabasePrivilegedKeyEnvName()) || getWifeEnv('SUPABASE_ANON_KEY')));
}

const supabaseStore: NonceStore = {
  async consumeNonce(nonce: string, nowMs: number, ttlMs: number): Promise<boolean> {
    const supabaseUrl = getWifeEnv('SUPABASE_URL');
    const supabaseKey = getWifeEnv(supabasePrivilegedKeyEnvName()) || getWifeEnv('SUPABASE_ANON_KEY');
    if (!supabaseUrl || !supabaseKey) throw new Error('Supabase nonce store is not configured.');

    const table = getWifeEnv('WIFE_NONCE_TABLE') || DEFAULT_NONCE_TABLE;
    const baseUrl = supabaseUrl.replace(/\/+$/, '');
    const restTableUrl = `${baseUrl}/rest/v1/${encodeURIComponent(table)}`;

    // Best-effort cleanup for expired rows.
    void fetch(`${restTableUrl}?expires_at_ms=lt.${nowMs}`, {
      method: 'DELETE',
      headers: {
        apikey: supabaseKey,
        Authorization: `Bearer ${supabaseKey}`,
      },
    }).catch(() => undefined);

    const expiresAt = nowMs + ttlMs;
    const response = await fetch(restTableUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        apikey: supabaseKey,
        Authorization: `Bearer ${supabaseKey}`,
        Prefer: 'resolution=ignore-duplicates,return=representation',
      },
      body: JSON.stringify([{ nonce, expires_at_ms: expiresAt }]),
    });

    if (!response.ok) {
      throw new Error(`Supabase nonce store failed: ${response.status}`);
    }

    const rows = (await response.json().catch(() => [])) as Array<{ nonce?: unknown }>;
    // Insert succeeded only when row is returned; empty means duplicate nonce.
    return Array.isArray(rows) && rows.length > 0;
  },
};

function resolvePrimaryStore(): NonceStore | null {
  if (hasWifeRedisConfig()) return redisStore;
  if (hasSupabaseConfig()) return supabaseStore;
  if (!isWifeProduction()) return memoryStore;
  return null;
}

/**
 * Returns true only when nonce is new and successfully persisted for TTL window.
 * Returns false for replay attempts.
 */
export async function consumeNonceWithTtl(nonce: string, ttlMs: number): Promise<boolean> {
  const nowMs = Date.now();
  const primary = resolvePrimaryStore();

  if (!primary) {
    if (isWifeProduction()) return false;
    return await memoryStore.consumeNonce(nonce, nowMs, ttlMs);
  }

  try {
    return await primary.consumeNonce(nonce, nowMs, ttlMs);
  } catch {
    if (isWifeProduction()) return false;
    return await memoryStore.consumeNonce(nonce, nowMs, ttlMs);
  }
}

/** Test-only: clears in-memory nonce fallback between isolated scenarios. */
export function resetNonceStoreForTests(): void {
  IN_MEMORY_NONCE_FALLBACK.clear();
}

/**
 * Distributed rate limiting for WIFE (Redis → in-memory fallback).
 */

import { wifeRedisJson } from './wifeRedisRest.ts';
import { hasWifeRedisConfig, isWifeProduction } from './wifeStoreEnv.ts';

const DEFAULT_WINDOW_MS = 60_000;
/** Default WIFE verify budget — overridden per scope in wifeValidator.checkRateLimit */
export const DEFAULT_MAX_REQUESTS = 250;

type WindowCounter = { count: number; resetAt: number };

const memoryCounters = new Map<string, WindowCounter>();
const MEMORY_MAX_KEYS = 20_000;

function hashKeyMaterial(input: string): string {
  let hash = 2166136261;
  for (let i = 0; i < input.length; i++) {
    hash ^= input.charCodeAt(i);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(36);
}

function buildRedisKey(scope: string, subjectKey: string, windowStartMs: number): string {
  return encodeURIComponent(`wife:ratelimit:${scope}:${subjectKey}:${windowStartMs}`);
}

function pruneMemoryCounters(nowMs: number): void {
  if (memoryCounters.size <= MEMORY_MAX_KEYS) return;
  for (const [key, entry] of memoryCounters.entries()) {
    if (entry.resetAt <= nowMs) memoryCounters.delete(key);
    if (memoryCounters.size <= MEMORY_MAX_KEYS * 0.75) break;
  }
}

async function consumeRedisSlot(
  scope: string,
  subjectKey: string,
  maxRequests: number,
  windowMs: number,
): Promise<boolean> {
  const nowMs = Date.now();
  const windowStartMs = Math.floor(nowMs / windowMs) * windowMs;
  const key = buildRedisKey(scope, subjectKey, windowStartMs);

  const incrRes = await wifeRedisJson(`/incr/${key}`, 'POST');
  if (!incrRes.ok) throw new Error(`Redis rate limit incr failed: ${incrRes.status}`);

  const count = Number(incrRes.result ?? 0);
  if (!Number.isFinite(count) || count <= 0) return false;

  if (count === 1) {
    void wifeRedisJson(`/pexpire/${key}/${windowMs}`, 'POST').catch(() => undefined);
  }

  return count <= maxRequests;
}

function consumeMemorySlot(scope: string, subjectKey: string, maxRequests: number, windowMs: number): boolean {
  const nowMs = Date.now();
  pruneMemoryCounters(nowMs);
  const mapKey = `${scope}:${subjectKey}`;
  const entry = memoryCounters.get(mapKey);
  if (!entry || nowMs > entry.resetAt) {
    memoryCounters.set(mapKey, { count: 1, resetAt: nowMs + windowMs });
    return true;
  }
  entry.count++;
  return entry.count <= maxRequests;
}

/**
 * Returns true when request is allowed under rate limit budget.
 */
export async function consumeRateLimitSlot(
  subjectKey: string,
  options?: { scope?: string; maxRequests?: number; windowMs?: number; fallbackToMemory?: boolean },
): Promise<boolean> {
  const scope = options?.scope ?? 'wife';
  const maxRequests = options?.maxRequests ?? DEFAULT_MAX_REQUESTS;
  const windowMs = options?.windowMs ?? DEFAULT_WINDOW_MS;
  const hashedSubject = hashKeyMaterial(subjectKey);
  const allowMemory = Boolean(options?.fallbackToMemory) || !isWifeProduction();

  if (hasWifeRedisConfig()) {
    try {
      return await consumeRedisSlot(scope, hashedSubject, maxRequests, windowMs);
    } catch {
      if (!allowMemory) return false;
    }
  }

  if (!allowMemory) return false;
  return consumeMemorySlot(scope, hashedSubject, maxRequests, windowMs);
}

export function resetWifeRateLimitStoreForTests(): void {
  memoryCounters.clear();
}

import { getWifeRedisConfig } from './wifeStoreEnv.ts';

export type WifeRedisJsonResult = {
  ok: boolean;
  status: number;
  result: unknown;
};

/** Upstash REST call. URL path must match the existing store callers byte-for-byte. */
export async function wifeRedisJson(
  path: string,
  method: 'GET' | 'POST' = 'GET',
): Promise<WifeRedisJsonResult> {
  const cfg = getWifeRedisConfig();
  if (!cfg) throw new Error('Redis is not configured.');
  const url = `${cfg.baseUrl}${path.startsWith('/') ? path : `/${path}`}`;
  const res = await fetch(url, {
    method,
    headers: { Authorization: `Bearer ${cfg.token}` },
  });
  const body = (await res.json().catch(() => null)) as { result?: unknown } | null;
  return { ok: res.ok, status: res.status, result: body?.result };
}

import { parseCookieHeader, readIncomingCookieHeader } from './sessionCookie.ts';
import { wifeTimingSafeEqual } from './wifeTimingSafe.ts';

function parseBearerToken(authorizationHeader: string | null): string | null {
  if (!authorizationHeader) return null;
  const [scheme, token] = authorizationHeader.split(' ');
  if (!scheme || !token) return null;
  if (scheme.toLowerCase() !== 'bearer') return null;
  const normalized = token.trim();
  return normalized ? normalized : null;
}

/**
 * Best-effort Supabase auth token extraction from cookie storage shapes.
 * Supports:
 * - sb-access-token (explicit token cookie)
 * - sb-*-auth-token (JSON payload used by some Supabase auth helpers)
 */
function extractTokenFromSupabaseCookies(cookieHeader: string | null): string | null {
  if (!cookieHeader) return null;
  const cookies = parseCookieHeader(cookieHeader);

  const hamiAccess = cookies.hami_access_token?.trim();
  if (hamiAccess) {
    try {
      return decodeURIComponent(hamiAccess);
    } catch {
      return hamiAccess;
    }
  }

  const directToken = cookies['sb-access-token']?.trim();
  if (directToken) return decodeURIComponent(directToken);

  const authTokenCookieName = Object.keys(cookies).find((name) => name.startsWith('sb-') && name.endsWith('-auth-token'));
  if (!authTokenCookieName) return null;

  const raw = decodeURIComponent(cookies[authTokenCookieName] ?? '');
  if (!raw) return null;

  try {
    const parsed = JSON.parse(raw) as unknown;
    if (parsed && typeof parsed === 'object' && 'access_token' in parsed) {
      const maybeToken = (parsed as { access_token?: unknown }).access_token;
      if (typeof maybeToken === 'string' && maybeToken.trim()) return maybeToken.trim();
    }
  } catch {
    // Continue to alternate format.
  }

  try {
    const parsed = JSON.parse(raw) as unknown;
    if (Array.isArray(parsed) && typeof parsed[0] === 'string' && parsed[0].trim()) {
      return parsed[0].trim();
    }
  } catch {
    return null;
  }

  return null;
}

/**
 * Bearer and HttpOnly cookie must agree when both are present.
 */
export function extractUserTokenFromRequest(req: Request): string | null {
  const authHeaderToken = parseBearerToken(req.headers.get('authorization') ?? req.headers.get('Authorization'));
  const cookieToken = extractTokenFromSupabaseCookies(readIncomingCookieHeader(req));

  /*
   * Bearer يغلب الكوكي في القراءة الساذجة. إن اختلفا فالهجمة الشائعة هي حقن
   * Authorization من XSS بينما الجلسة الحقيقية في HttpOnly. لا نختار أحدهما:
   * الرفض أصدق من انتحال صامت.
   */
  if (authHeaderToken && cookieToken && !wifeTimingSafeEqual(authHeaderToken, cookieToken)) {
    return null;
  }

  return authHeaderToken ?? cookieToken;
}

import { afterEach, describe, expect, it } from 'vitest';
import { assertSameOriginRequest } from './wifeSameOrigin.ts';

function req(url: string, headers: Record<string, string> = {}): Request {
    return new Request(url, { method: 'POST', headers });
}

describe('assertSameOriginRequest', () => {
    const previousNodeEnv = process.env.NODE_ENV;

    afterEach(() => {
        process.env.NODE_ENV = previousNodeEnv;
    });

    it('يقبل Origin المتصفح على :8080 مقابل Request بلا منفذ على loopback (خلل محوّل Vite)', () => {
        process.env.NODE_ENV = 'development';
        expect(
            assertSameOriginRequest(
                req('http://127.0.0.1/api/security/wife-sign', {
                    origin: 'http://127.0.0.1:8080',
                }),
            ),
        ).toBe(true);
        expect(
            assertSameOriginRequest(
                req('http://127.0.0.1/api/security/wife-sign', {
                    origin: 'http://localhost:8080',
                }),
            ),
        ).toBe(true);
    });

    it('يرفض أصلاً معادياً', () => {
        process.env.NODE_ENV = 'development';
        expect(
            assertSameOriginRequest(
                req('http://127.0.0.1/api/security/wife-sign', {
                    origin: 'https://evil.test',
                }),
            ),
        ).toBe(false);
    });

    it('في الإنتاج لا يساوي منفذ 80 بمنفذ 8080', () => {
        process.env.NODE_ENV = 'production';
        expect(
            assertSameOriginRequest(
                req('http://127.0.0.1/api/security/wife-sign', {
                    origin: 'http://127.0.0.1:8080',
                }),
            ),
        ).toBe(false);
    });
});

/** فحص نفس الأصل لمسارات إقلاع/إبطال WIFE (wife-sign / wife-session). */

import { isWifeProduction } from './wifeStoreEnv.ts';

export { isWifeProduction as isProductionNodeEnv } from './wifeStoreEnv.ts';

function isLoopbackHostname(hostname: string): boolean {
    const host = hostname.trim().toLowerCase().replace(/^\[|\]$/g, '');
    return host === 'localhost' || host === '127.0.0.1' || host === '::1';
}

function parseHttpOrigin(raw: string): URL | null {
    try {
        const url = new URL(raw);
        if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
        return url;
    } catch {
        return null;
    }
}

function originPort(url: URL): string {
    if (url.port) return url.port;
    return url.protocol === 'https:' ? '443' : '80';
}

/** منافذ Vite/معاينة شائعة — لا تُعامل كإنتاج */
const DEV_LOOPBACK_PORTS = new Set(['8080', '5173', '4173', '8081', '3000']);

/**
 * Vite كان يبني Request على `http://127.0.0.1` بلا منفذ بينما Origin المتصفح
 * `http://127.0.0.1:8080`. في التطوير فقط نعدّ ذلك نفساً إن كان الطرفان loopback.
 */
function isViteLoopbackPortOmission(requestUrl: URL, browserOrigin: URL): boolean {
    if (isWifeProduction()) return false;
    if (requestUrl.protocol !== 'http:' || browserOrigin.protocol !== 'http:') return false;
    if (!isLoopbackHostname(requestUrl.hostname) || !isLoopbackHostname(browserOrigin.hostname)) {
        return false;
    }
    const requestIsDefaultHttp = originPort(requestUrl) === '80';
    return requestIsDefaultHttp && DEV_LOOPBACK_PORTS.has(originPort(browserOrigin));
}

export function originsAreSameSite(requestOrigin: string, browserOrigin: string): boolean {
    if (requestOrigin === browserOrigin) return true;
    const requestUrl = parseHttpOrigin(requestOrigin);
    const browserUrl = parseHttpOrigin(browserOrigin);
    if (!requestUrl || !browserUrl) return false;
    if (requestUrl.protocol !== browserUrl.protocol) return false;
    if (isViteLoopbackPortOmission(requestUrl, browserUrl)) return true;
    if (originPort(requestUrl) !== originPort(browserUrl)) return false;
    if (requestUrl.hostname === browserUrl.hostname) return true;
    if (
        !isWifeProduction() &&
        isLoopbackHostname(requestUrl.hostname) &&
        isLoopbackHostname(browserUrl.hostname)
    ) {
        return true;
    }
    return false;
}

/** IP للحدّ من الإغراق — x-forwarded-for قابل للتزييف خلف وكيل غير موثوق. */
export function readForwardedClientIp(request: Request): string {
    const xf = request.headers.get('x-forwarded-for')?.split(',')[0]?.trim();
    const ip = xf || request.headers.get('x-real-ip')?.trim() || 'unknown';
    return ip.slice(0, 64);
}

export function assertSameOriginRequest(request: Request): boolean {
    const requestOrigin = new URL(request.url).origin;
    const origin = request.headers.get('origin')?.trim();
    if (origin) {
        return originsAreSameSite(requestOrigin, origin);
    }
    const referer = request.headers.get('referer')?.trim();
    if (referer) {
        try {
            return originsAreSameSite(requestOrigin, new URL(referer).origin);
        } catch {
            return false;
        }
    }
    return !isWifeProduction();
}

import { buildContentSecurityPolicy, resolveCspMode, type CspMode } from './contentSecurityPolicy';

/** ترويسة واحدة — يجب تطابق vercel.json و public/_headers (انظر deployHeadersParity.test) */
export const HAMI_PERMISSIONS_POLICY =
    'geolocation=(), microphone=(self), camera=(self), payment=(), usb=(), publickey-credentials-get=(self), publickey-credentials-create=(self)';

const BASE_SECURITY_HEADERS: Readonly<Record<string, string>> = {
  'X-Content-Type-Options': 'nosniff',
  'X-Frame-Options': 'DENY',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': HAMI_PERMISSIONS_POLICY,
  'Cross-Origin-Opener-Policy': 'same-origin',
  'Cross-Origin-Resource-Policy': 'same-site',
  'X-XSS-Protection': '0',
};

function buildSecurityHeaders(cspMode?: CspMode): Record<string, string> {
  const mode = cspMode ?? resolveCspMode();
  const headers: Record<string, string> = {
    ...BASE_SECURITY_HEADERS,
    'Content-Security-Policy': buildContentSecurityPolicy(mode),
  };
  if (mode === 'production') {
    headers['Strict-Transport-Security'] = 'max-age=31536000; includeSubDomains; preload';
  }
  return headers;
}

export function applyWifeSecurityHeaders(response: Response): Response {
  const headers = new Headers();
  response.headers.forEach((value, key) => {
    if (key.toLowerCase() !== 'set-cookie') headers.set(key, value);
  });
  const cookies =
    typeof response.headers.getSetCookie === 'function' ? response.headers.getSetCookie() : [];
  for (const cookie of cookies) {
    headers.append('Set-Cookie', cookie);
  }
  for (const [key, value] of Object.entries(buildSecurityHeaders())) {
    if (!headers.has(key)) headers.set(key, value);
  }
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

export function wifeJsonResponse(status: number, body: Record<string, unknown>): Response {
  return applyWifeSecurityHeaders(
    new Response(JSON.stringify(body), {
      status,
      headers: { 'Content-Type': 'application/json; charset=utf-8' },
    }),
  );
}

export const HQ_JSON_NO_STORE = 'private, no-store, no-cache, must-revalidate';

/** JSON مقر — لا يُخزَّن في المتصفح أو وسيط. */
export function wifeJsonNoStore(status: number, body: Record<string, unknown>): Response {
  const base = wifeJsonResponse(status, body);
  const headers = new Headers(base.headers);
  headers.set('Cache-Control', HQ_JSON_NO_STORE);
  headers.set('Pragma', 'no-cache');
  return new Response(base.body, {
    status: base.status,
    statusText: base.statusText,
    headers,
  });
}

export function getDevSecurityHeaders(): Record<string, string> {
  return { ...buildSecurityHeaders('development'), 'Cache-Control': 'no-store' };
}

export function getProductionSecurityHeaders(): Record<string, string> {
  return buildSecurityHeaders('production');
}

/** vite preview لـ E2E — حزمة production على HTTP بدون upgrade-insecure-requests (WebKit/Safari). */
export function getE2ePreviewSecurityHeaders(): Record<string, string> {
  return { ...buildSecurityHeaders('e2e-preview'), 'Cache-Control': 'no-store' };
}

/**
 * Server-side WIFE rejection telemetry — structured logs + counters (no UX impact).
 * Optional: set SENTRY_DSN for server-side capture via Sentry envelope API (best-effort).
 */

import { isWifeProduction } from './wifeStoreEnv.ts';

export type WifeRejectReason =
  | 'unauthorized_token'
  | 'signature_failed'
  | 'subject_missing'
  | 'rate_limited'
  | 'device_id_missing'
  | 'stolen_token'
  | 'cloned_token'
  | 'actor_binding_failed'
  | 'forum_banned'
  | 'forum_guest_write_denied'
  | 'forum_guest_read_denied'
  | 'forum_guest_admin_denied'
  | 'execution_guest_denied'
  | 'csrf_store_unavailable'
  | 'account_locked'
  | 'account_frozen';

export type WifeRejectMeta = {
  reason: WifeRejectReason;
  request?: Request;
  detail?: string;
  userId?: string;
};

type RejectionCounter = { reason: WifeRejectReason; count: number };

const MAX_RECENT = 50;
const recentRejections: WifeRejectMeta[] = [];
const counterMap = new Map<WifeRejectReason, number>();

function requestPath(request?: Request): string {
  if (!request) return '';
  try {
    return new URL(request.url).pathname;
  } catch {
    return '';
  }
}

function requestMethod(request?: Request): string {
  return (request?.method ?? 'GET').toUpperCase();
}

function pushRecent(meta: WifeRejectMeta): void {
  recentRejections.push(meta);
  if (recentRejections.length > MAX_RECENT) recentRejections.shift();
  counterMap.set(meta.reason, (counterMap.get(meta.reason) ?? 0) + 1);
}

function rejectionPayload(meta: WifeRejectMeta) {
  return {
    type: 'wife_rejection',
    reason: meta.reason,
    path: requestPath(meta.request),
    method: requestMethod(meta.request),
    detail: meta.detail ?? null,
    userId: meta.userId ?? null,
    ts: new Date().toISOString(),
  };
}

function logStructured(meta: WifeRejectMeta): void {
  const payload = rejectionPayload(meta);
  if (isWifeProduction()) {
    console.warn(JSON.stringify(payload));
  } else if (process.env.WIFE_LOG_REJECTIONS === 'true') {
    console.info('[WIFE rejection]', payload);
  }
}

async function captureSentryBestEffort(meta: WifeRejectMeta): Promise<void> {
  const url = (process.env.WIFE_SECURITY_WEBHOOK_URL ?? '').trim();
  if (!url) return;
  try {
    await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(rejectionPayload(meta)),
    });
  } catch {
    /* best effort */
  }
}

/** Record a WIFE/BFF auth rejection (fire-and-forget). */
export function recordWifeRejection(meta: WifeRejectMeta): void {
  pushRecent(meta);
  logStructured(meta);
  void captureSentryBestEffort(meta);
}

export function getWifeRejectionCounters(): RejectionCounter[] {
  return [...counterMap.entries()].map(([reason, count]) => ({ reason, count }));
}

export function resetWifeSecurityMonitorForTests(): void {
  recentRejections.length = 0;
  counterMap.clear();
}

import { toBase64Url } from '@/app/security/wifeRequestSigningShared.ts';
import { getSupabaseAdminClient } from './supabaseAdminClient.ts';
import { wifeRedisJson } from './wifeRedisRest.ts';
import { getWifeEnv, hasWifeRedisConfig, isWifeProduction } from './wifeStoreEnv.ts';

const DEFAULT_WIFE_SESSION_TABLE = 'wife_session_store';
const WIFE_SESSION_TTL_MS = 30 * 60 * 1000;
const EMPTY_DEVICE_ID = '-';

type WifeSessionRecord = {
  sessionId: string;
  subject: string;
  secret: string;
  deviceId: string;
  expiresAtMs: number;
};

type WifeSessionStoreRow = {
  session_id: string;
  subject: string;
  secret: string;
  device_id: string;
  expires_at_ms: number;
};

const memoryStore = new Map<string, WifeSessionRecord>();

function isTestRuntime(): boolean {
  return getWifeEnv('VITEST') === 'true';
}

function allowMemoryFallback(): boolean {
  return !isWifeProduction() || isTestRuntime();
}

function redisKey(sessionId: string): string {
  return encodeURIComponent(`wife:session:${sessionId}`);
}

function normalizeDeviceId(deviceId: string): string {
  return deviceId.trim();
}

function redisSubjectDeviceKey(subject: string, deviceId: string): string {
  return encodeURIComponent(`wife:subject-device:${subject}:${deviceId || EMPTY_DEVICE_ID}`);
}

function redisSubjectDevicePattern(subject: string): string {
  return encodeURIComponent(`wife:subject-device:${subject}:`) + '*';
}

function pruneMemory(nowMs: number): void {
  for (const [sessionId, row] of memoryStore.entries()) {
    if (row.expiresAtMs <= nowMs) memoryStore.delete(sessionId);
  }
}

function isActiveRecord(record: WifeSessionRecord | null | undefined, nowMs = Date.now()): record is WifeSessionRecord {
  return Boolean(record && record.expiresAtMs > nowMs);
}

function toIssuedSession(record: WifeSessionRecord): IssuedWifeSession {
  return {
    sessionId: record.sessionId,
    sessionSecret: record.secret,
    expiresAtMs: record.expiresAtMs,
  };
}

function randomSecret(bytesLength: number): string {
  const bytes = new Uint8Array(bytesLength);
  crypto.getRandomValues(bytes);
  return toBase64Url(bytes);
}

async function redisGetValue(key: string): Promise<string | null> {
  if (!hasWifeRedisConfig()) return null;
  const res = await wifeRedisJson(`/get/${key}`);
  if (!res.ok) return null;
  return typeof res.result === 'string' && res.result ? res.result : null;
}

async function redisSetValue(key: string, value: string, ttlMs: number): Promise<boolean> {
  if (!hasWifeRedisConfig()) return false;
  const res = await wifeRedisJson(
    `/set/${key}/${encodeURIComponent(value)}?PX=${Math.max(60_000, ttlMs)}`,
    'POST',
  );
  return res.ok;
}

async function redisDeleteKey(key: string): Promise<void> {
  if (!hasWifeRedisConfig()) return;
  await wifeRedisJson(`/del/${key}`, 'POST');
}

async function redisListKeys(pattern: string): Promise<string[]> {
  if (!hasWifeRedisConfig()) return [];
  const res = await wifeRedisJson(`/keys/${pattern}`);
  if (!res.ok) return [];
  return Array.isArray(res.result) ? res.result.filter((key): key is string => typeof key === 'string') : [];
}

function findReusableMemorySession(subject: string, deviceId: string, nowMs: number): WifeSessionRecord | null {
  let match: WifeSessionRecord | null = null;
  for (const record of memoryStore.values()) {
    if (record.subject !== subject) continue;
    if (record.deviceId !== deviceId) continue;
    if (!isActiveRecord(record, nowMs)) continue;
    if (!match || record.expiresAtMs > match.expiresAtMs) {
      match = record;
    }
  }
  return match;
}

async function persistSession(record: WifeSessionRecord): Promise<boolean> {
  if (hasWifeRedisConfig()) {
    try {
      const ttlMs = Math.max(60_000, record.expiresAtMs - Date.now());
      const sessionStored = await redisSetValue(redisKey(record.sessionId), JSON.stringify(record), ttlMs);
      if (sessionStored) {
        await redisSetValue(redisSubjectDeviceKey(record.subject, record.deviceId), record.sessionId, ttlMs).catch(() => false);
        return true;
      }
    } catch {
      if (!allowMemoryFallback()) return false;
    }
  }

  const admin = getSupabaseAdminClient();
  if (admin) {
    try {
      const table = getWifeEnv('WIFE_SESSION_TABLE') || DEFAULT_WIFE_SESSION_TABLE;
      const { error } = await admin.from(table).upsert(
        {
          session_id: record.sessionId,
          subject: record.subject,
          secret: record.secret,
          device_id: record.deviceId,
          expires_at_ms: record.expiresAtMs,
        },
        { onConflict: 'session_id' },
      );
      if (!error) return true;
    } catch {
      if (!allowMemoryFallback()) return false;
    }
  }

  if (!allowMemoryFallback()) return false;
  memoryStore.set(record.sessionId, record);
  return true;
}

async function readSession(sessionId: string): Promise<WifeSessionRecord | null> {
  const nowMs = Date.now();
  pruneMemory(nowMs);

  if (hasWifeRedisConfig()) {
    try {
      const raw = await redisGetValue(redisKey(sessionId));
      if (raw) {
        const parsed = JSON.parse(raw) as Partial<WifeSessionRecord>;
        if (
          typeof parsed.sessionId === 'string' &&
          typeof parsed.subject === 'string' &&
          typeof parsed.secret === 'string' &&
          Number(parsed.expiresAtMs) > nowMs
        ) {
          return {
            sessionId: parsed.sessionId,
            subject: parsed.subject,
            secret: parsed.secret,
            deviceId: typeof parsed.deviceId === 'string' ? parsed.deviceId : '',
            expiresAtMs: Number(parsed.expiresAtMs),
          };
        }
      }
    } catch {
      if (!allowMemoryFallback()) return null;
    }
  }

  const admin = getSupabaseAdminClient();
  if (admin) {
    try {
      const table = getWifeEnv('WIFE_SESSION_TABLE') || DEFAULT_WIFE_SESSION_TABLE;
      const query = await admin
        .from(table)
        .select('session_id, subject, secret, device_id, expires_at_ms')
        .eq('session_id', sessionId)
        .maybeSingle();
      const data = query.data as WifeSessionStoreRow | null;
      const { error } = query;
      if (!error && data && Number(data.expires_at_ms) > nowMs) {
        return {
          sessionId: String(data.session_id ?? ''),
          subject: String(data.subject ?? ''),
          secret: String(data.secret ?? ''),
          deviceId: String(data.device_id ?? ''),
          expiresAtMs: Number(data.expires_at_ms),
        };
      }
    } catch {
      if (!allowMemoryFallback()) return null;
    }
  }

  const cached = memoryStore.get(sessionId);
  if (cached && cached.expiresAtMs > nowMs) return cached;
  return null;
}

async function readReusableSessionBySubjectDevice(subject: string, deviceId: string): Promise<WifeSessionRecord | null> {
  const normalizedDeviceId = normalizeDeviceId(deviceId);
  const nowMs = Date.now();
  pruneMemory(nowMs);

  if (hasWifeRedisConfig()) {
    try {
      const indexedSessionId = await redisGetValue(redisSubjectDeviceKey(subject, normalizedDeviceId));
      if (indexedSessionId?.trim()) {
        const indexedRecord = await readSession(indexedSessionId.trim());
        if (indexedRecord && indexedRecord.subject === subject && indexedRecord.deviceId === normalizedDeviceId) {
          return indexedRecord;
        }
      }
    } catch {
      if (!allowMemoryFallback()) return null;
    }
  }

  const admin = getSupabaseAdminClient();
  if (admin) {
    try {
      const table = getWifeEnv('WIFE_SESSION_TABLE') || DEFAULT_WIFE_SESSION_TABLE;
      const query = await admin
        .from(table)
        .select('session_id, subject, secret, device_id, expires_at_ms')
        .eq('subject', subject)
        .eq('device_id', normalizedDeviceId)
        .gt('expires_at_ms', nowMs)
        .order('expires_at_ms', { ascending: false })
        .limit(1)
        .maybeSingle();
      const data = query.data as WifeSessionStoreRow | null;
      const { error } = query;
      if (!error && data && Number(data.expires_at_ms) > nowMs) {
        return {
          sessionId: String(data.session_id ?? ''),
          subject: String(data.subject ?? ''),
          secret: String(data.secret ?? ''),
          deviceId: String(data.device_id ?? ''),
          expiresAtMs: Number(data.expires_at_ms),
        };
      }
    } catch {
      if (!allowMemoryFallback()) return null;
    }
  }

  return findReusableMemorySession(subject, normalizedDeviceId, nowMs);
}

async function listSessionsForSubject(subject: string): Promise<WifeSessionRecord[]> {
  const nowMs = Date.now();
  pruneMemory(nowMs);
  const dedup = new Map<string, WifeSessionRecord>();

  if (hasWifeRedisConfig()) {
    try {
      const keys = await redisListKeys(redisSubjectDevicePattern(subject));
      for (const key of keys) {
        const sessionId = await redisGetValue(encodeURIComponent(key)).catch(() => null);
        if (!sessionId?.trim()) continue;
        const record = await readSession(sessionId.trim());
        if (record && record.subject === subject && record.expiresAtMs > nowMs) {
          dedup.set(record.sessionId, record);
        }
      }
    } catch {
      if (!allowMemoryFallback()) return [];
    }
  }

  const admin = getSupabaseAdminClient();
  if (admin) {
    try {
      const table = getWifeEnv('WIFE_SESSION_TABLE') || DEFAULT_WIFE_SESSION_TABLE;
      const query = await admin
        .from(table)
        .select('session_id, subject, secret, device_id, expires_at_ms')
        .eq('subject', subject)
        .gt('expires_at_ms', nowMs);
      const data = (query.data as WifeSessionStoreRow[] | null) ?? [];
      const { error } = query;
      if (!error) {
        for (const row of data) {
          const record: WifeSessionRecord = {
            sessionId: String(row.session_id ?? ''),
            subject: String(row.subject ?? ''),
            secret: String(row.secret ?? ''),
            deviceId: String(row.device_id ?? ''),
            expiresAtMs: Number(row.expires_at_ms ?? 0),
          };
          if (record.sessionId && record.subject === subject && record.expiresAtMs > nowMs) {
            dedup.set(record.sessionId, record);
          }
        }
      }
    } catch {
      if (!allowMemoryFallback()) return [];
    }
  }

  for (const record of memoryStore.values()) {
    if (record.subject === subject && record.expiresAtMs > nowMs) {
      dedup.set(record.sessionId, record);
    }
  }

  return [...dedup.values()];
}

async function deleteSessions(records: WifeSessionRecord[]): Promise<void> {
  const seen = new Set<string>();
  for (const record of records) {
    if (!record.sessionId || seen.has(record.sessionId)) continue;
    seen.add(record.sessionId);
    await deleteSession(record.sessionId);
  }
}

async function deleteSession(sessionId: string): Promise<void> {
  const existing = await readSession(sessionId).catch(() => null);
  memoryStore.delete(sessionId);

  if (hasWifeRedisConfig()) {
    try {
      await redisDeleteKey(redisKey(sessionId));
      if (existing) {
        await redisDeleteKey(redisSubjectDeviceKey(existing.subject, existing.deviceId));
      }
    } catch {
      /* best effort */
    }
  }

  const admin = getSupabaseAdminClient();
  if (admin) {
    try {
      const table = getWifeEnv('WIFE_SESSION_TABLE') || DEFAULT_WIFE_SESSION_TABLE;
      await admin.from(table).delete().eq('session_id', sessionId);
    } catch {
      /* best effort */
    }
  }
}

export type IssuedWifeSession = {
  sessionId: string;
  sessionSecret: string;
  expiresAtMs: number;
};

/** يُستخدم لاختبار الإبطال ولجلسات قديمة في المخزن. الإنتاج لم يعد يُصدر سراً عبر GET. */
export async function issueWifeSessionForSubject(
  subject: string,
  deviceId: string,
): Promise<IssuedWifeSession | null> {
  if (!subject) return null;
  const normalizedDeviceId = normalizeDeviceId(deviceId);
  const existing = await readReusableSessionBySubjectDevice(subject, normalizedDeviceId);
  if (existing) {
    return toIssuedSession(existing);
  }
  const record: WifeSessionRecord = {
    sessionId: randomSecret(18),
    subject,
    secret: randomSecret(32),
    deviceId: normalizedDeviceId,
    expiresAtMs: Date.now() + WIFE_SESSION_TTL_MS,
  };
  const ok = await persistSession(record);
  if (!ok) return null;
  return toIssuedSession(record);
}

export async function resolveWifeSessionSecretForSubject(
  sessionId: string,
  subject: string,
  deviceId: string,
): Promise<string | null> {
  if (!sessionId || !subject) return null;
  const record = await readSession(sessionId);
  if (!record) return null;
  if (record.subject !== subject) return null;
  if (record.deviceId && deviceId && record.deviceId !== deviceId) return null;
  if (record.deviceId && !deviceId) return null;
  return record.secret;
}

export async function invalidateWifeSession(sessionId: string): Promise<void> {
  if (!sessionId) return;
  await deleteSession(sessionId);
}

export async function invalidateWifeSessionsForSubject(subject: string): Promise<void> {
  if (!subject.trim()) return;
  const records = await listSessionsForSubject(subject.trim());
  await deleteSessions(records);
}

export function resetWifeSessionStoreForTests(): void {
  memoryStore.clear();
}

/**
 * Policy for /api/security/wife-sign — allowlist only same-origin /api/* (no bootstrap oracle abuse).
 */
import { isWifeBootstrapApiPath, isWifeUnsignedApiPath } from '@/app/security/wifePublicApi.ts';

function normalizeWifeSignPath(pathname: string): string {
  const stripped = pathname.trim().split('?')[0] ?? '/';
  if (stripped.length > 1 && stripped.endsWith('/')) return stripped.replace(/\/+$/, '');
  return stripped || '/';
}

/** @returns canonical pathname if allowed; null if rejected */
export function resolveAllowedWifeSignTarget(request: Request, targetUrl: string): string | null {
  const trimmed = targetUrl.trim();
  if (!trimmed) return null;

  const requestOrigin = new URL(request.url).origin;
  let resolved: URL;
  try {
    resolved = new URL(trimmed, requestOrigin);
  } catch {
    return null;
  }

  if (resolved.origin !== requestOrigin) return null;

  const pathname = resolved.pathname;
  if (!pathname.startsWith('/api/')) return null;
  if (isWifeUnsignedApiPath(pathname)) return null;
  if (isBlockedWifeSignPath(pathname)) return null;

  const query = resolved.searchParams.toString();
  return query ? `${pathname}?${query}` : pathname;
}

export function isBlockedWifeSignPath(pathname: string): boolean {
  const normalized = normalizeWifeSignPath(pathname);
  return isWifeBootstrapApiPath(normalized);
}

/** Shared env helpers for WIFE server stores. */

export function getWifeEnv(name: string): string {
  const raw = process.env[name];
  return typeof raw === 'string' ? raw.trim() : '';
}

export function isWifeProduction(): boolean {
  return getWifeEnv('NODE_ENV').toLowerCase() === 'production';
}

export function getWifeRedisConfig(): { baseUrl: string; token: string } | null {
  const url = getWifeEnv('WIFE_REDIS_REST_URL');
  const token = getWifeEnv('WIFE_REDIS_REST_TOKEN');
  if (!url || !token) return null;
  return { baseUrl: url.replace(/\/+$/, ''), token };
}

export function hasWifeRedisConfig(): boolean {
  return getWifeRedisConfig() !== null;
}

/** Constant-time string compare for WIFE CSRF / HMAC / file-hash checks. */
export function wifeTimingSafeEqual(a: string, b: string): boolean {
  const aBytes = new TextEncoder().encode(a);
  const bBytes = new TextEncoder().encode(b);
  const maxLen = Math.max(aBytes.length, bBytes.length);
  let diff = aBytes.length ^ bBytes.length;
  for (let i = 0; i < maxLen; i++) {
    const av = i < aBytes.length ? aBytes[i] : 0;
    const bv = i < bBytes.length ? bBytes[i] : 0;
    diff |= av ^ bv;
  }
  return diff === 0;
}

import { decodeJwtPayloadBase64 } from '@/app/security/jwtFields.ts';
import { sha256Bytes, toBase64Url } from '@/app/security/wifeRequestSigningShared.ts';
import { getSupabaseAuthConfigFromEnv } from './sessionCookie.ts';
import { isUserActiveLive } from './wifeUserStatus.ts';
import { isWifeProduction as isProductionNodeEnv } from './wifeStoreEnv.ts';

const verifiedTokenCache = new Map<string, { subject: string; expiresAt: number }>();
const VERIFIED_TOKEN_CACHE_TTL = 60_000;
const VERIFIED_TOKEN_CACHE_MAX = 5_000;
const DEV_ACCESS_TOKEN_PREFIX = 'dev-access-token-';
/** ضيف العرض — لا يُقبل في الإنتاج إلا براية صريحة (منتدى / تنفيذ / WIFE). */
const DEMO_GUEST_SUBJECT = 'guest-lawyer-1';

function readStringField(input: Record<string, unknown> | null, key: string): string | null {
  if (!input) return null;
  const value = input[key];
  return typeof value === 'string' && value.trim() ? value.trim() : null;
}

function pruneVerifiedTokenCache(nowMs: number): void {
  if (verifiedTokenCache.size <= VERIFIED_TOKEN_CACHE_MAX) return;
  for (const [key, value] of verifiedTokenCache.entries()) {
    if (value.expiresAt <= nowMs || value.subject === 'INVALID') {
      verifiedTokenCache.delete(key);
    }
    if (verifiedTokenCache.size <= VERIFIED_TOKEN_CACHE_MAX * 0.75) break;
  }
}

function parseDevAccessTokenSubject(userToken: string): string | null {
  if (!userToken.startsWith(DEV_ACCESS_TOKEN_PREFIX)) return null;
  const subject = userToken.slice(DEV_ACCESS_TOKEN_PREFIX.length).trim();
  return subject.length >= 8 ? subject : null;
}

function cacheVerifiedDevSubject(fingerprint: string, subject: string): string {
  verifiedTokenCache.set(fingerprint, {
    subject,
    expiresAt: Date.now() + VERIFIED_TOKEN_CACHE_TTL,
  });
  return subject;
}

function isProductionDemoGuestAllowed(subject: string): boolean {
  if (subject !== DEMO_GUEST_SUBJECT) return false;
  return (
    (process.env.WIFE_ALLOW_DEV_ACCESS_TOKEN ?? '').trim() === '1' ||
    (process.env.FORUM_ALLOW_DEMO_GUEST_READ ?? '').trim() === '1' ||
    (process.env.EXECUTION_ALLOW_DEMO_GUEST ?? '').trim() === '1'
  );
}

async function tokenFingerprint(userToken: string): Promise<string> {
  return toBase64Url(await sha256Bytes(userToken));
}

/**
 * هوية توكن GoTrue دون فحص القفل/الحذف.
 * القفل يُرفض برسالة صريحة في requireWifeUser/login لا كـ 401 عام.
 */
export async function getVerifiedTokenIdentity(userToken: string): Promise<string | null> {
    if (!userToken || typeof userToken !== 'string' || userToken.length < 20) return null;

    const fingerprint = await tokenFingerprint(userToken);

    const devSubject = parseDevAccessTokenSubject(userToken);
    if (devSubject) {
        if (!isProductionNodeEnv()) {
            return cacheVerifiedDevSubject(fingerprint, devSubject);
        }
        if (isProductionDemoGuestAllowed(devSubject)) {
            return cacheVerifiedDevSubject(fingerprint, devSubject);
        }
        return null;
    }

    pruneVerifiedTokenCache(Date.now());

    const cached = verifiedTokenCache.get(fingerprint);
    if (cached) {
        if (Date.now() >= cached.expiresAt) {
            verifiedTokenCache.delete(fingerprint);
        } else if (cached.subject === 'INVALID') {
            return null;
        } else {
            const payload = decodeJwtPayloadBase64(userToken);
            if (payload?.exp && Date.now() >= Number(payload.exp) * 1000) {
                verifiedTokenCache.delete(fingerprint);
            } else {
                return cached.subject;
            }
        }
    }

    const cfg = getSupabaseAuthConfigFromEnv();
    if (!cfg) return null;

    const response = await fetch(`${cfg.url}/auth/v1/user`, {
        method: 'GET',
        headers: {
            apikey: cfg.key,
            Authorization: `Bearer ${userToken}`,
        },
    });
    if (!response.ok) {
        verifiedTokenCache.set(fingerprint, {
            subject: 'INVALID',
            expiresAt: Date.now() + Math.min(VERIFIED_TOKEN_CACHE_TTL, 10_000),
        });
        return null;
    }

    const user = (await response.json().catch(() => null)) as Record<string, unknown> | null;
    const userId = readStringField(user, 'id');
    if (!userId) return null;

    verifiedTokenCache.set(fingerprint, {
        subject: userId,
        expiresAt: Date.now() + VERIFIED_TOKEN_CACHE_TTL,
    });

    return userId;
}

/**
 * Strict token verification against Supabase auth endpoint.
 * Fails closed if verification backend is unavailable.
 * Locked/deleted accounts return null — callers that need a lock message use identity + restriction.
 */
export async function getVerifiedTokenSubject(userToken: string): Promise<string | null> {
    const userId = await getVerifiedTokenIdentity(userToken);
    if (!userId) return null;
    if (userToken.startsWith(DEV_ACCESS_TOKEN_PREFIX)) return userId;
    if (!(await isUserActiveLive(userId))) return null;
    return userId;
}

export async function isTokenAuthorized(userToken: string): Promise<boolean> {
  return Boolean(await getVerifiedTokenSubject(userToken));
}

/** Enforces that verified token subject matches actor identifiers in payload. */
export async function enforceTokenActorBinding(userToken: string, payload: unknown): Promise<boolean> {
  const subject = await getVerifiedTokenSubject(userToken);
  if (!subject) return false;
  if (!payload || typeof payload !== 'object') return false;

  const body = payload as Record<string, unknown>;
  const lawyerId = typeof body.lawyer_id === 'string' ? body.lawyer_id.trim() : '';
  const clientId = typeof body.client_id === 'string' ? body.client_id.trim() : '';

  if (!lawyerId && !clientId) return false;
  if (lawyerId && subject !== lawyerId) return false;
  if (clientId && subject !== clientId) return false;
  return true;
}

export function resetWifeTokenSubjectCacheForTests(): void {
  verifiedTokenCache.clear();
}

