import { getSupabaseAdminClient } from '../security/supabaseAdminClient.ts';
import { requireWifeCloudWrite, unwrapWifeUser } from '../security/bffAuth.ts';
import { wifeForbiddenResponse } from '../security/wifeValidator.ts';
import { validateFileBuffer, verifyFileContentHash } from '../security/fileValidator.ts';
import { scanBufferForMalware } from '../../services/server/MalwareScanService.ts';
import {
  ALLOWED_UPLOAD_CATEGORIES,
  buildCategoryObjectPath,
  isForumEncryptedUpload,
  resolveUploadBucketForCategory,
  SIGNED_URL_TTL_SEC,
} from './uploadStorageUtils.ts';

export const runtime = 'nodejs';

const MAX_FILE_SIZE_BYTES = 25 * 1024 * 1024; // 25 MB

function json(status: number, payload: Record<string, unknown>): Response {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
}

function pickUploadedFile(formData: FormData): File | null {
  const direct = formData.get('file');
  if (direct instanceof File) return direct;

  for (const value of formData.values()) {
    if (value instanceof File) return value;
  }
  return null;
}

export async function POST(request: Request): Promise<Response> {
  try {
    const authGate = unwrapWifeUser(await requireWifeCloudWrite(request));
    if ('response' in authGate) return authGate.response;
    const { userId } = authGate;

    const contentHashHeader =
      request.headers.get('x-wife-content-hash') ??
      request.headers.get('X-WIFE-Content-Hash');
    if (!contentHashHeader || !contentHashHeader.trim()) {
      return wifeForbiddenResponse({ request, reason: 'signature_failed', detail: 'missing_content_hash' });
    }

    // 3) Multipart extraction.
    const formData = await request.formData().catch(() => null);
    if (!formData) {
      return json(400, { ok: false, error: 'Invalid multipart payload' });
    }

    const file = pickUploadedFile(formData);
    if (!file) {
      return json(400, { ok: false, error: 'No file provided' });
    }

    const categoryRaw = formData.get('category');
    const category = typeof categoryRaw === 'string' ? categoryRaw.trim() : '';
    if (!ALLOWED_UPLOAD_CATEGORIES.has(category)) {
      return json(400, { ok: false, error: 'Invalid upload category' });
    }

    if (file.size <= 0) {
      return json(400, { ok: false, error: 'Empty file is not allowed' });
    }
    if (file.size > MAX_FILE_SIZE_BYTES) {
      return json(400, { ok: false, error: 'File exceeds maximum allowed size' });
    }
    if ((file.type || '').toLowerCase() === 'image/svg+xml') {
      return json(400, { ok: false, error: 'Invalid or malicious file' });
    }

    const arrayBuffer = await file.arrayBuffer();
    const buffer = Buffer.from(arrayBuffer);
    if (!verifyFileContentHash(buffer, contentHashHeader)) {
      return json(403, { ok: false, error: 'File Tampering Detected' });
    }

    const forumEncrypted = isForumEncryptedUpload(category, file.name);
    if (!forumEncrypted && !validateFileBuffer(buffer, file.name)) {
      return json(400, { ok: false, error: 'Invalid or malicious file' });
    }

    // 5) Malware scanning (heuristic and optional API adapter).
    const malwareScan = await scanBufferForMalware(buffer);
    if (!malwareScan.safe) {
      return json(400, {
        ok: false,
        error: 'Security warning: file failed malware scan',
        reason: malwareScan.reason ?? 'malware_detected',
      });
    }

    // 6) Secure storage upload via privileged admin client.
    const admin = getSupabaseAdminClient();
    if (!admin) {
      return json(500, { ok: false, error: 'Server storage client is not configured' });
    }

    const bucket = resolveUploadBucketForCategory(category);
    const objectPath = buildCategoryObjectPath(userId, category, file.name);

    const { error } = await admin.storage.from(bucket).upload(objectPath, buffer, {
      contentType: file.type || undefined,
      upsert: false,
    });
    if (error) {
      return json(500, { ok: false, error: 'Storage upload failed' });
    }

    const { data: signedData, error: signedErr } = await admin.storage
      .from(bucket)
      .createSignedUrl(objectPath, SIGNED_URL_TTL_SEC);
    if (signedErr) {
      return json(500, { ok: false, error: 'Failed to create download URL' });
    }

    return json(200, {
      ok: true,
      bucket,
      path: objectPath,
      fullPath: objectPath,
      downloadUrl: signedData?.signedUrl ?? null,
    });
  } catch {
    return json(500, { ok: false, error: 'Internal upload error' });
  }
}

import { getSupabaseAdminClient } from '../../security/supabaseAdminClient.ts';
import { requireWifeCloudWrite, unwrapWifeUser } from '../../security/bffAuth.ts';
import {
  isStoragePathOwnedByUser,
  resolveUploadBucket,
  FORUM_MEDIA_BUCKET,
  SIGNED_URL_TTL_SEC,
} from '../uploadStorageUtils.ts';

export const runtime = 'nodejs';

function json(status: number, payload: Record<string, unknown>): Response {
  return new Response(JSON.stringify(payload), {
    status,
    headers: { 'Content-Type': 'application/json; charset=utf-8' },
  });
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object';
}

/**
 * WIFE-protected signed URL for an object the user already owns in storage.
 */
export async function POST(request: Request): Promise<Response> {
  try {
    const authGate = unwrapWifeUser(await requireWifeCloudWrite(request));
    if ('response' in authGate) return authGate.response;
    const { userId } = authGate;

    const payload = (await request.json().catch(() => null)) as unknown;
    if (!isRecord(payload) || typeof payload.path !== 'string' || !payload.path.trim()) {
      return json(400, { ok: false, error: 'path مطلوب' });
    }

    const path = payload.path.trim();
    if (!isStoragePathOwnedByUser(path, userId)) {
      return json(403, { ok: false, error: 'Forbidden: path not owned by current user' });
    }

    const admin = getSupabaseAdminClient();
    if (!admin) {
      return json(500, { ok: false, error: 'Server storage client is not configured' });
    }

    const bucketRaw = typeof payload.bucket === 'string' ? payload.bucket.trim() : '';
    const bucket =
        bucketRaw === FORUM_MEDIA_BUCKET
            ? FORUM_MEDIA_BUCKET
            : resolveUploadBucket();
    const { data, error } = await admin.storage.from(bucket).createSignedUrl(path, SIGNED_URL_TTL_SEC);
    if (error || !data?.signedUrl) {
      return json(404, { ok: false, error: 'Object not found or signed URL failed' });
    }

    return json(200, { ok: true, downloadUrl: data.signedUrl, path });
  } catch {
    return json(500, { ok: false, error: 'Internal signed-url error' });
  }
}

export const DEFAULT_UPLOAD_BUCKET = 'make-f09713ba-legal-docs';
export const FORUM_MEDIA_BUCKET = 'forum-media';
export const SIGNED_URL_TTL_SEC = 60 * 60 * 24 * 7;

export const ALLOWED_UPLOAD_CATEGORIES = new Set([
  'scans',
  'audio',
  'drafts',
  'repository',
  'vault',
  'forum-media',
]);

export function resolveUploadBucket(): string {
  const fromEnv = (process.env.SUPABASE_UPLOAD_BUCKET ?? '').trim();
  return fromEnv || DEFAULT_UPLOAD_BUCKET;
}

export function resolveUploadBucketForCategory(category: string): string {
  if (category === 'forum-media') return FORUM_MEDIA_BUCKET;
  return resolveUploadBucket();
}

export function sanitizeUploadFileName(originalName: string): string {
  return originalName.replace(/[^a-zA-Z0-9.-]/g, '_');
}

function decodeStoragePathFully(raw: string): string | null {
  let current = raw.trim();
  for (let i = 0; i < 4; i += 1) {
    try {
      const next = decodeURIComponent(current);
      if (next === current) return current;
      current = next;
    } catch {
      return null;
    }
  }
  return current;
}

export function isStoragePathOwnedByUser(rawPath: unknown, userId: string): boolean {
  if (typeof rawPath !== 'string' || !rawPath.trim() || !userId) return false;
  if (rawPath.includes('\\') || rawPath.includes('\0')) return false;

  const decoded = decodeStoragePathFully(rawPath);
  if (decoded == null || decoded.includes('\0') || decoded.includes('\\')) return false;

  const normalized = decoded.replace(/^\/+/, '').replace(/\\/g, '/');
  const segments = normalized.split('/');
  if (segments.length < 2) return false;
  if (segments.some((segment) => segment === '' || segment === '.' || segment === '..')) return false;
  return normalized.startsWith(`${userId}/`);
}

/** صورة منتدى مشفّرة عند العميل — ليست JPEG/PNG على السلك. */
export function isForumEncryptedUpload(category: string, fileName: string): boolean {
  if (category !== 'forum-media') return false;
  const name = fileName.trim().toLowerCase();
  if (!name.endsWith('.enc')) return false;
  if (name.endsWith('.svg.enc') || name.includes('.svg.')) return false;
  return true;
}

export function buildCategoryObjectPath(
  userId: string,
  category: string,
  fileName: string,
): string {
  const cleanName = sanitizeUploadFileName(fileName);
  return `${userId}/${category}/${Date.now()}_${cleanName}`;
}

import type { VercelRequest, VercelResponse } from '../../../api/_vercelRuntimeTypes.ts';
import { routeLoaders, type RouteModule } from './vercelRouteManifest.ts';
import { applyWebResponseHeadersToNode, createWebRequestFromNode } from './security/nodeWebApiBridge.ts';
import {
    isHeadquartersOnlyApiPath,
    rejectHeadquartersPublicSurface,
} from './security/headquartersOriginGate.ts';
import { resolveVercelApiSlug } from './security/resolveVercelApiSlug.ts';

export const config = {
    api: {
        bodyParser: false,
    },
};

const METHODS = ['GET', 'POST', 'PUT', 'PATCH', 'DELETE'] as const;

function readRawBody(req: VercelRequest): Promise<Buffer> {
    return new Promise((resolve, reject) => {
        const chunks: Buffer[] = [];
        req.on('data', (chunk: Buffer | string) => {
            chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
        });
        req.on('end', () => resolve(Buffer.concat(chunks)));
        req.on('error', reject);
    });
}

async function toWebRequest(req: VercelRequest): Promise<Request> {
    const proto = String(req.headers['x-forwarded-proto'] ?? 'https');
    const host = String(req.headers.host ?? 'localhost');
    const pathWithQuery = req.url ?? '/';
    const url = `${proto}://${host}${pathWithQuery.startsWith('/') ? pathWithQuery : `/${pathWithQuery}`}`;
    const method = (req.method ?? 'GET').toUpperCase();
    const hasBody = method !== 'GET' && method !== 'HEAD';
    const raw = hasBody ? await readRawBody(req) : Buffer.alloc(0);
    return createWebRequestFromNode(url, req, raw.byteLength > 0 ? new Uint8Array(raw) : undefined);
}

async function pipeWebResponse(res: VercelResponse, webRes: Response): Promise<void> {
    res.statusCode = webRes.status;
    applyWebResponseHeadersToNode(res, webRes);
    if (!webRes.body) {
        res.end();
        return;
    }
    const reader = webRes.body.getReader();
    try {
        for (;;) {
            const { done, value } = await reader.read();
            if (done) break;
            if (value?.byteLength) res.write(Buffer.from(value));
        }
    } finally {
        reader.releaseLock();
    }
    res.end();
}

export default async function handler(req: VercelRequest, res: VercelResponse): Promise<void> {
    try {
        const slug = resolveVercelApiSlug(req);
        const pathname = `/api/${slug}`;
        const method = (req.method ?? 'GET').toUpperCase();
        if (isHeadquartersOnlyApiPath(pathname)) {
            const proto = String(req.headers['x-forwarded-proto'] ?? 'https');
            const host = String(req.headers.host ?? 'localhost');
            const pathWithQuery = req.url ?? '/';
            const url = `${proto}://${host}${pathWithQuery.startsWith('/') ? pathWithQuery : `/${pathWithQuery}`}`;
            const gateReq = createWebRequestFromNode(url, req);
            const denied = rejectHeadquartersPublicSurface(gateReq);
            if (denied) {
                if (method !== 'GET' && method !== 'HEAD') {
                    await readRawBody(req).catch(() => Buffer.alloc(0));
                }
                await pipeWebResponse(res, denied);
                return;
            }
        }

        const loader = routeLoaders[slug];
        if (!loader) {
            res.statusCode = 404;
            res.setHeader('Content-Type', 'application/json; charset=utf-8');
            res.end(JSON.stringify({ error: 'Not found' }));
            return;
        }

        if (!METHODS.includes(method as (typeof METHODS)[number])) {
            res.statusCode = 405;
            res.end();
            return;
        }

        const mod = (await loader()) as RouteModule;
        const fn = mod[method as keyof RouteModule];
        if (typeof fn !== 'function') {
            res.statusCode = 405;
            res.end();
            return;
        }

        const webReq = await toWebRequest(req);
        const webRes = await (fn as (request: Request) => Promise<Response>)(webReq);
        await pipeWebResponse(res, webRes);
    } catch (e) {
        console.error('[vercel-api]', e);
        if (!res.headersSent) {
            res.statusCode = 500;
            res.setHeader('Content-Type', 'application/json; charset=utf-8');
            res.end(JSON.stringify({ error: 'خطأ داخلي في الخادم' }));
        }
    }
}

