import type { FollowupHiddenActionSnapshot } from './resolveFollowupHiddenActions';
import type { FollowupScenarioDefinition } from './followupScenarioDefinitions';
import { resolveFollowupScenario } from './followupScenarioResolver';

export function assertFollowupHiddenInvariants(
    hidden: FollowupHiddenActionSnapshot,
    scenario: FollowupScenarioDefinition,
): void {
    if (!hidden.hiddenToggleVisible) {
        if (hidden.hasAnyHiddenContent) {
            throw new Error(`${scenario.id}: toggle off but hasAnyHiddenContent true`);
        }
        if (hidden.hiddenPersonalCoerciveKeys.length > 0) {
            throw new Error(`${scenario.id}: toggle off but personal keys non-empty`);
        }
        if (hidden.hiddenGuarantorKeys.length > 0) {
            throw new Error(`${scenario.id}: toggle off but guarantor keys non-empty`);
        }
        if (hidden.breakInventoryVisible) {
            throw new Error(`${scenario.id}: toggle off but breakInventory visible`);
        }
    }

    if (scenario.input.activeDebtorIsDeceased && hidden.hiddenToggleVisible) {
        throw new Error(`${scenario.id}: deceased debtor must hide toggle`);
    }

    if (hidden.breakInventoryVisible && !hidden.hasAnyHiddenContent) {
        throw new Error(`${scenario.id}: break inventory visible without hidden content`);
    }

    const scenarioResult = resolveFollowupScenario(scenario.input);
    if (
        scenarioResult.modalShowPersonalCoerciveFollowupTab &&
        !scenarioResult.personalTabLockedForEmployee &&
        hidden.hiddenToggleVisible
    ) {
        const buriedExceptForcedBring = hidden.hiddenPersonalCoerciveKeys.filter(
            (key) => key !== 'forced_bring_in',
        );
        if (buriedExceptForcedBring.length > 0) {
            throw new Error(
                `${scenario.id}: unlocked personal tab should not list buried coercive keys`,
            );
        }
    }
}

export function serializeFollowupHiddenSnapshot(
    hidden: FollowupHiddenActionSnapshot,
): Pick<
    FollowupHiddenActionSnapshot,
    | 'hiddenToggleVisible'
    | 'hiddenPersonalCoerciveKeys'
    | 'hiddenGuarantorKeys'
    | 'breakInventoryVisible'
    | 'hasAnyHiddenContent'
> {
    return {
        hiddenToggleVisible: hidden.hiddenToggleVisible,
        hiddenPersonalCoerciveKeys: hidden.hiddenPersonalCoerciveKeys,
        hiddenGuarantorKeys: hidden.hiddenGuarantorKeys,
        breakInventoryVisible: hidden.breakInventoryVisible,
        hasAnyHiddenContent: hidden.hasAnyHiddenContent,
    };
}

/**
 * محلّل سيناريوهات محضر المتابعة — يعكس سلسلة الإنتاج:
 * نوع المطالبة × كاسب/موظف × مركز مالي × كيان مدين × وفاة مدين
 */
import {
    buildFollowupModalTabsFromFlags,
    buildFollowupSectionTabOrderFromFlags,
} from '@/app/components/lawyer/ExecutionDashboard/hooks/executionDashboardCore/buildFollowupModalTabsFromFlags';
import { applyFollowupSpecializationOverlays } from '@/app/utils/applyFollowupSpecializationOverlays';
import { applyDebtorDeathFollowupOverlay } from '@/app/utils/partyDeathFollowupOverlay';
import {
    resolveFollowupSpecializationVisibility,
    isCustodyRemovalClaim,
    type FollowupSpecializationVisibility,
} from '@/app/utils/followupSpecializationVisibility';
import type { SpecificDeliveryItem } from '@/app/utils/specificDeliveryItemsUtils';
import type { DebtorEntityKind } from '@/app/utils/debtorEntityKindUtils';

/** التبويبات الثابتة في كل سيناريو (بعد بوابة restricted) */
export const FOLLOWUP_ALWAYS_TAB_IDS = [
    'correspondences',
    'admin',
    'dossier_controls',
    'other_party',
] as const;

export type FollowupScenarioTabId =
    | 'personal'
    | 'coercive'
    | 'seizure_requests'
    | typeof FOLLOWUP_ALWAYS_TAB_IDS[number];

export type FollowupScenarioInput = {
    claimType: string;
    isEmployee: boolean;
    /** متبقي المركز المالي الموحّد (د.ع) — يفعّل بوابة الكاسب */
    financialCenterTotalIqd?: number;
    debtorEntityKind?: DebtorEntityKind | string;
    activeDebtorIsDeceased?: boolean;
    /** وكيل مدين — يقيّد التبويبات الجبرية */
    hideCoerciveTabsForDebtorAgent?: boolean;
    /** كتلة تكليف بعد عدم الحضور — يظهر تبويب شخصي حتى لو مخفي بالأعلام */
    showEmployeeAssignmentCoerciveBlock?: boolean;
    /** فتح تبويب الموظف الشخصي من التخزين المحلي */
    personalTabUnlocked?: boolean;
    specificDeliveryItemNature?: string | null;
    specificDeliveryFinancialized?: boolean;
    specificDeliveryItems?: SpecificDeliveryItem[] | null;
    docType?: string | null;
    classification?: string | null;
    category?: string | null;
};

export type FollowupScenarioPipelineKind = 'effective_earner_gated' | 'debtor_pipeline_inline';

export type FollowupScenarioResult = {
    flagsBase: FollowupSpecializationVisibility;
    flagsWithEarnerGate: FollowupSpecializationVisibility;
    flagsDebtorPipeline: FollowupSpecializationVisibility;
    followupTabsRestricted: boolean;
    showPersonalCoerciveFollowupTab: boolean;
    modalShowPersonalCoerciveFollowupTab: boolean;
    personalTabLockedForEmployee: boolean;
    effectiveTabIds: FollowupScenarioTabId[];
    effectiveSectionTabOrder: FollowupScenarioTabId[];
    debtorPipelineInlineTabIds: FollowupScenarioTabId[];
};

function resolveSpecializationFlags(input: FollowupScenarioInput): FollowupSpecializationVisibility {
    return resolveFollowupSpecializationVisibility(input.claimType, input.isEmployee, {
        specificDeliveryItemNature: input.specificDeliveryItemNature,
        specificDeliveryFinancialized: input.specificDeliveryFinancialized,
        specificDeliveryItems: input.specificDeliveryItems,
        docType: input.docType,
        classification: input.classification,
        category: input.category,
        debtorEntityKind: input.debtorEntityKind ?? 'natural_person',
    });
}

function buildTabsFromFlags(
    flags: FollowupSpecializationVisibility,
    input: {
        showPersonalCoerciveFollowupTab: boolean;
        personalTabLockedForEmployee: boolean;
        followupTabsRestricted: boolean;
    },
): FollowupScenarioTabId[] {
    return buildFollowupModalTabsFromFlags({
        specialization: flags,
        showPersonalCoerciveFollowupTab: input.showPersonalCoerciveFollowupTab,
        personalTabLockedForEmployee: input.personalTabLockedForEmployee,
        followupTabsRestricted: input.followupTabsRestricted,
    }).map((t) => t.id as FollowupScenarioTabId);
}

export function resolveFollowupScenario(input: FollowupScenarioInput): FollowupScenarioResult {
    const financialCenterTotalIqd = Math.max(0, Math.round(Number(input.financialCenterTotalIqd) || 0));
    const flagsBase = resolveSpecializationFlags(input);

    const flagsDebtorPipeline = input.activeDebtorIsDeceased
        ? applyDebtorDeathFollowupOverlay(flagsBase, true)
        : flagsBase;

    const flagsWithEarnerGate = applyFollowupSpecializationOverlays(flagsBase, {
        isEmployee: input.isEmployee,
        financialCenterTotalIqd,
        activeDebtorIsDeceased: input.activeDebtorIsDeceased,
    });

    const followupTabsRestricted =
        Boolean(input.hideCoerciveTabsForDebtorAgent) ||
        String(input.debtorEntityKind ?? 'natural_person') === 'legal_entity';

    const custodyRemovalClaimActive = isCustodyRemovalClaim(input.claimType);
    const employeeCoerciveDetentionRestricted = input.isEmployee && !custodyRemovalClaimActive;

    const personalTabLockedForEmployee =
        employeeCoerciveDetentionRestricted &&
        !Boolean(input.personalTabUnlocked) &&
        !flagsWithEarnerGate.hidePersonalCoerciveFollowupTab;

    const showPersonalCoerciveFollowupTab = !flagsWithEarnerGate.hidePersonalCoerciveFollowupTab;

    const modalShowPersonalCoerciveFollowupTab =
        !flagsWithEarnerGate.hidePersonalCoerciveFollowupTab ||
        Boolean(input.showEmployeeAssignmentCoerciveBlock);

    const modalPersonalTabLockedForEmployee =
        employeeCoerciveDetentionRestricted &&
        !Boolean(input.personalTabUnlocked) &&
        !flagsWithEarnerGate.hidePersonalCoerciveFollowupTab;

    const effectiveTabIds = buildTabsFromFlags(flagsWithEarnerGate, {
        showPersonalCoerciveFollowupTab: modalShowPersonalCoerciveFollowupTab,
        personalTabLockedForEmployee,
        followupTabsRestricted,
    });

    const effectiveSectionTabOrder = buildFollowupSectionTabOrderFromFlags({
        showPersonalCoerciveFollowupTab,
        specialization: flagsWithEarnerGate,
        followupTabsRestricted,
    }) as FollowupScenarioTabId[];

    const debtorPipelineInlineTabIds = buildTabsFromFlags(flagsDebtorPipeline, {
        showPersonalCoerciveFollowupTab:
            !flagsDebtorPipeline.hidePersonalCoerciveFollowupTab ||
            Boolean(input.showEmployeeAssignmentCoerciveBlock),
        personalTabLockedForEmployee:
            employeeCoerciveDetentionRestricted &&
            !Boolean(input.personalTabUnlocked) &&
            !flagsDebtorPipeline.hidePersonalCoerciveFollowupTab,
        followupTabsRestricted,
    });

    return {
        flagsBase,
        flagsWithEarnerGate,
        flagsDebtorPipeline,
        followupTabsRestricted,
        showPersonalCoerciveFollowupTab,
        modalShowPersonalCoerciveFollowupTab,
        personalTabLockedForEmployee,
        effectiveTabIds,
        effectiveSectionTabOrder,
        debtorPipelineInlineTabIds,
    };
}

import type { ExecutionFile } from '@/app/types/execution';
import type {
    HiddenFollowupVisibilityInput,
    HiddenGuarantorContext,
    HiddenGuarantorRequestKey,
    HiddenPersonalCoerciveRequestKey,
} from '@/app/components/lawyer/ExecutionDashboard/components/hiddenFollowupRequestsUtils';
import {
    hasAnyHiddenFollowupContent,
    listHiddenGuarantorCatalog,
    listHiddenPersonalCoerciveCatalog,
    shouldAlwaysShowHiddenRequestsToggle,
    shouldShowGuarantorRequestInSeizureTab,
    shouldShowHiddenBreakInventoryRequest,
} from '@/app/components/lawyer/ExecutionDashboard/components/hiddenFollowupRequestsUtils';
import {
    isCustodyRemovalClaim,
    isPersonalStatusCourtDecisionsDossier,
} from '@/app/utils/followupSpecializationVisibility';
import { shouldShowEarnerExecutiveDetentionFromFinancialCenter } from '@/app/utils/earnerPersonalCoerciveFinancialGate';
import {
    registryIdForHiddenGuarantorKey,
    registryIdForHiddenPersonalKey,
    type FollowupRegistryActionId,
} from './followupActionRegistry';
import {
    resolveFollowupScenario,
    type FollowupScenarioInput,
    type FollowupScenarioResult,
} from './followupScenarioResolver';

export type FollowupHiddenActionContext = {
    settlementBreachTriggeredAt?: string | null;
    ledgerPendingSettlement?: unknown;
    /** محاكاة كفيل ضامن نشط في بيانات التنفيذ */
    guarantorFollowupActive?: boolean;
};

export type ResolveFollowupHiddenActionsInput = FollowupScenarioInput & FollowupHiddenActionContext;

export type FollowupHiddenActionSnapshot = {
    hiddenToggleVisible: boolean;
    hiddenPersonalCoerciveKeys: HiddenPersonalCoerciveRequestKey[];
    hiddenGuarantorKeys: HiddenGuarantorRequestKey[];
    breakInventoryVisible: boolean;
    hasAnyHiddenContent: boolean;
    registryActionIds: FollowupRegistryActionId[];
};

function financialCenterIqd(input: ResolveFollowupHiddenActionsInput): number {
    return Math.max(0, Math.round(Number(input.financialCenterTotalIqd) || 0));
}

function buildGuarantorExecutionStub(active: boolean): ExecutionFile | null {
    if (!active) return null;
    return {
        guarantor_followup: { executor_approved: true, details_saved: true },
    } as ExecutionFile;
}

/** يعكس بناء flags في ExecutionFollowupModalLatePanels */
export function buildFollowupHiddenVisibilityFlags(
    scenario: FollowupScenarioResult,
    input: ResolveFollowupHiddenActionsInput,
): HiddenFollowupVisibilityInput {
    const flags = scenario.flagsWithEarnerGate;
    const financialCenter = financialCenterIqd(input);
    const hideExecutiveDetentionJudgeCard = !shouldShowEarnerExecutiveDetentionFromFinancialCenter({
        isEmployee: input.isEmployee,
        financialCenterTotalIqd: financialCenter,
    });

    const isPersonalStatusExecutionClaim = isPersonalStatusCourtDecisionsDossier(
        input.docType,
        input.classification,
        input.category,
        input.debtorEntityKind ?? 'natural_person',
    );

    const visibilityFlags: HiddenFollowupVisibilityInput = {
        ...flags,
        showPersonalCoerciveFollowupTab: scenario.modalShowPersonalCoerciveFollowupTab,
        showGuarantorInSeizureTab: false,
        isPersonalStatusExecutionClaim,
        isAlimonyClaim: String(input.claimType ?? '').includes('نفقة'),
        activeDebtorIsEmployee: input.isEmployee,
        isCustodyRemovalClaim: isCustodyRemovalClaim(input.claimType),
        personalTabLockedForEmployee: scenario.personalTabLockedForEmployee,
        showHiddenExecutiveDossierPresentation:
            !hideExecutiveDetentionJudgeCard && !input.isEmployee && financialCenter > 0,
    };

    const guarantorCtx = buildFollowupGuarantorContext(input);
    visibilityFlags.showGuarantorInSeizureTab = shouldShowGuarantorRequestInSeizureTab(
        visibilityFlags,
        guarantorCtx,
    );

    return visibilityFlags;
}

export function buildFollowupGuarantorContext(
    input: ResolveFollowupHiddenActionsInput,
): HiddenGuarantorContext {
    return {
        executionData: buildGuarantorExecutionStub(Boolean(input.guarantorFollowupActive)),
        settlementBreachTriggeredAt: input.settlementBreachTriggeredAt ?? null,
        ledgerPendingSettlement: input.ledgerPendingSettlement ?? null,
        financialCenterTotalIqd: financialCenterIqd(input),
        activeDebtorIsDeceased: Boolean(input.activeDebtorIsDeceased),
        activeDebtorIsEmployee: input.isEmployee,
    };
}

export function resolveFollowupHiddenActions(
    input: ResolveFollowupHiddenActionsInput,
): FollowupHiddenActionSnapshot {
    const scenario = resolveFollowupScenario(input);
    const visibilityFlags = buildFollowupHiddenVisibilityFlags(scenario, input);
    const guarantorCtx = buildFollowupGuarantorContext(input);

    const hiddenToggleVisible = shouldAlwaysShowHiddenRequestsToggle({
        activeDebtorIsDeceased: input.activeDebtorIsDeceased,
    });

    const rawPersonalKeys = listHiddenPersonalCoerciveCatalog(visibilityFlags).map((item) => item.key);
    const rawGuarantorKeys = listHiddenGuarantorCatalog(visibilityFlags, guarantorCtx).map(
        (item) => item.key,
    );
    const rawBreakInventory = shouldShowHiddenBreakInventoryRequest(visibilityFlags);
    const rawHasHidden = hasAnyHiddenFollowupContent(visibilityFlags, guarantorCtx);

    const hiddenPersonalCoerciveKeys = hiddenToggleVisible ? rawPersonalKeys : [];
    const hiddenGuarantorKeys = hiddenToggleVisible ? rawGuarantorKeys : [];
    const breakInventoryVisible = hiddenToggleVisible && rawBreakInventory;
    const hasAnyHiddenContent = hiddenToggleVisible && rawHasHidden;

    const registryActionIds: FollowupRegistryActionId[] = [];
    if (hiddenToggleVisible) {
        registryActionIds.push('hidden:toggle');
        if (breakInventoryVisible) registryActionIds.push('hidden:break_inventory');
        for (const key of hiddenPersonalCoerciveKeys) {
            registryActionIds.push(registryIdForHiddenPersonalKey(key));
        }
        for (const key of hiddenGuarantorKeys) {
            registryActionIds.push(registryIdForHiddenGuarantorKey(key));
        }
    }

    return {
        hiddenToggleVisible,
        hiddenPersonalCoerciveKeys,
        hiddenGuarantorKeys,
        breakInventoryVisible,
        hasAnyHiddenContent: hiddenToggleVisible && rawHasHidden,
        registryActionIds,
    };
}

import {
    getDebtorSummonsProfile,
    shouldShowEmployeeSalaryCapture,
    type DebtorSummonsProfile,
} from '@/app/utils/debtorSummonsProfile';
import {
    inferDebtorEmploymentFlags,
    isDebtorRowEmployee,
    type DebtorEmploymentLike,
} from '@/app/domain/execution/followup/debtorEmployment';

type FollowupDebtorEntry = {
    d: DebtorEmploymentLike;
    isPrimary?: boolean;
} | null;

export type BuildDebtorSummonsProfileBundleInput = {
    debtors: DebtorEmploymentLike[];
    principalDebtAmount: number;
    parsedLawyerFees: number;
    claimType: string | undefined;
    isNonFinancialClaim: boolean;
    debtorBrowserTabsMode: boolean;
    activeWorkspaceDebtorForFollowup: FollowupDebtorEntry;
};

export function buildDebtorSummonsProfileBundle(input: BuildDebtorSummonsProfileBundleInput) {
    const {
        debtors,
        principalDebtAmount,
        parsedLawyerFees,
        claimType,
        isNonFinancialClaim,
        debtorBrowserTabsMode,
        activeWorkspaceDebtorForFollowup,
    } = input;
    const primaryFlags = inferDebtorEmploymentFlags(debtors[0]);
    const debtorOccupation = primaryFlags.occupation;
    const isDebtorGovernmentEmployee = primaryFlags.isGovernmentEmployee;
    const isDebtorFreelancer = primaryFlags.isFreelancer;
    const isDebtorRetired = primaryFlags.isRetired;

    const debtorSummonsProfile: DebtorSummonsProfile = getDebtorSummonsProfile({
        isGovernmentEmployee: isDebtorGovernmentEmployee || isDebtorRetired,
        parsedDebtAmount: principalDebtAmount,
        parsedLawyerFees,
        claimType: claimType || '',
        isNonFinancialClaim,
    });

    let followupDebtorSummonsProfile = debtorSummonsProfile;
    if (debtorBrowserTabsMode && activeWorkspaceDebtorForFollowup) {
        const followupFlags = inferDebtorEmploymentFlags(activeWorkspaceDebtorForFollowup.d);
        followupDebtorSummonsProfile = getDebtorSummonsProfile({
            isGovernmentEmployee: followupFlags.isGovernmentEmployee || followupFlags.isRetired,
            parsedDebtAmount: principalDebtAmount,
            parsedLawyerFees,
            claimType: claimType || '',
            isNonFinancialClaim,
        });
    }

    const followupIsDebtorGovernmentEmployee =
        debtorBrowserTabsMode && activeWorkspaceDebtorForFollowup && !activeWorkspaceDebtorForFollowup.isPrimary
            ? isDebtorRowEmployee(activeWorkspaceDebtorForFollowup.d)
            : isDebtorGovernmentEmployee;

    const followupIsDebtorRetired =
        debtorBrowserTabsMode && activeWorkspaceDebtorForFollowup && !activeWorkspaceDebtorForFollowup.isPrimary
            ? inferDebtorEmploymentFlags(activeWorkspaceDebtorForFollowup.d).isRetired
            : isDebtorRetired;

    const showSalaryCaptureForEmployee = shouldShowEmployeeSalaryCapture({
        profile: debtorSummonsProfile,
        claimType: claimType || '',
        parsedLawyerFees,
    });

    return {
        debtorOccupation,
        isDebtorGovernmentEmployee,
        isDebtorFreelancer,
        isDebtorRetired,
        debtorSummonsProfile,
        followupDebtorSummonsProfile,
        followupIsDebtorGovernmentEmployee,
        followupIsDebtorRetired,
        showSalaryCaptureForEmployee,
    };
}

import type { ExecutionFile, EmployeeSummonsAssignmentState } from '@/app/types/execution';
import { getEmployeeAssignmentForDebtorKey } from '@/app/utils/employeeSummonsAssignment';

export type ExecutorDecisionOutcomeLite = {
    executorOutcome?: string | null;
};

export type FollowupDerivedState = {
    anyExecutorDecisionResolvedForMemoBadge: boolean;
    primaryDebtorTaklifActive: boolean;
    resolvedEmployeeSummonsAssignment: EmployeeSummonsAssignmentState | null;
    showEmployeeAssignmentCoerciveBlock: boolean;
};

function isActiveAssignmentPhase(phase: string | null | undefined): boolean {
    return (
        phase === 'active' ||
        phase === 'absent_declared' ||
        phase === 'investigation_pending' ||
        phase === 'warrant_ui'
    );
}

export function buildFollowupDerivedState(input: {
    executionData: ExecutionFile | null | undefined;
    primaryDebtorKeyResolved: string | null;
    unifiedSummonsTargetDebtorKey: string | null;
    executorDecisionRows: ExecutorDecisionOutcomeLite[];
}): FollowupDerivedState {
    const {
        executionData,
        primaryDebtorKeyResolved,
        unifiedSummonsTargetDebtorKey,
        executorDecisionRows,
    } = input;

    const anyExecutorDecisionResolvedForMemoBadge = (executorDecisionRows || []).some((row) => {
        const outcome = String(row?.executorOutcome || '').trim().toLowerCase();
        return outcome === 'approved' || outcome === 'alternative';
    });

    const primaryDebtorTaklifActive = (() => {
        if (!executionData) return false;
        const debtorKey = primaryDebtorKeyResolved;
        const assignment = getEmployeeAssignmentForDebtorKey(executionData, debtorKey, debtorKey);
        return Boolean(assignment && isActiveAssignmentPhase(assignment.phase));
    })();

    const resolvedEmployeeSummonsAssignment = executionData
        ? getEmployeeAssignmentForDebtorKey(
              executionData,
              unifiedSummonsTargetDebtorKey,
              primaryDebtorKeyResolved,
          )
        : null;

    const showEmployeeAssignmentCoerciveBlock = Boolean(
        resolvedEmployeeSummonsAssignment &&
            isActiveAssignmentPhase(resolvedEmployeeSummonsAssignment.phase) &&
            resolvedEmployeeSummonsAssignment.phase !== 'active',
    );

    return {
        anyExecutorDecisionResolvedForMemoBadge,
        primaryDebtorTaklifActive,
        resolvedEmployeeSummonsAssignment,
        showEmployeeAssignmentCoerciveBlock,
    };
}

import type { DebtorSummonsProfile } from '@/app/utils/debtorSummonsProfile';
import {
    isEarnerLikeSummonsBranch,
    isEmployeeMonetaryFinancialPath,
} from '@/app/utils/debtorSummonsProfile';

type BuildSubsequentNoticePolicyInput = {
    debtorSummonsProfile: DebtorSummonsProfile | string | null;
    followupDebtorSummonsProfile: DebtorSummonsProfile | string | null;
    isEvictionExecutionModule: boolean;
    isDebtorGovernmentEmployee: boolean;
    isDebtorRetired: boolean;
    followupIsDebtorGovernmentEmployee: boolean;
    followupIsDebtorRetired: boolean;
    unifiedCollectionApproved: boolean;
    notificationCount: number;
    forcedAttendanceIssued: boolean;
    summoningRound: number;
    isEvictionGraceExpiredNow: boolean;
    isGracePeriodExpiredNow: boolean;
    debtorAttendedVoluntarily: boolean;
    voluntaryAttendanceCount: number;
    forcedPathAttendanceSecured: boolean;
    debtorForcedToAttend: boolean;
    investigationMemoIssued: boolean;
    debtorArrested: boolean;
    executionExecutorCoerciveUnlock?: boolean;
    executionNoticeVoluntaryPeriodEndDeclared?: boolean;
    executionEvictionVoluntaryPeriodEndDeclared?: boolean;
    executionEvictionLastSummonsForCollection?: boolean;
    executionEvictionLastCollectionSummonsBranch?: string;
    noticeVoluntaryPeriodEndOptimistic: boolean;
    voluntaryEndOptimistic: boolean;
    isEvictionGraceEffectivelyExpired: boolean;
    debtorNotifiedForEvictionGrace: boolean;
    activeCoerciveActions: string[];
    monetaryExecutionStrictPathFlag: boolean;
    isAlimonyClaim: boolean;
    activeDebtorIsDeceased: boolean;
    debtorBrowserTabsMode: boolean;
    activeWorkspaceDebtorForFollowup: { isPrimary?: boolean; key?: string } | null;
    executionGarnishmentAmount?: string | number | null;
    perDebtorGarnishments?: Record<string, unknown>;
};

export function buildSubsequentNoticePolicy(input: BuildSubsequentNoticePolicyInput) {
    const earnerForcedActionUnlocked = (() => {
        if (!isEarnerLikeSummonsBranch(input.debtorSummonsProfile as DebtorSummonsProfile)) return false;
        if (input.isEvictionExecutionModule && input.isDebtorGovernmentEmployee) return false;
        if (input.forcedAttendanceIssued) return false;
        if (input.summoningRound >= 2) return true;
        if (
            input.isEvictionExecutionModule &&
            !input.isDebtorGovernmentEmployee &&
            !input.isDebtorRetired &&
            input.unifiedCollectionApproved &&
            input.executionEvictionLastSummonsForCollection === true &&
            input.executionEvictionLastCollectionSummonsBranch === 'coercive'
        ) {
            return true;
        }
        const graceDone = input.isEvictionExecutionModule
            ? input.isEvictionGraceExpiredNow
            : input.isGracePeriodExpiredNow;
        if (!graceDone || input.debtorAttendedVoluntarily) return false;
        return true;
    })();

    const followupEarnerForcedActionUnlocked = (() => {
        if (!isEarnerLikeSummonsBranch(input.followupDebtorSummonsProfile as DebtorSummonsProfile)) return false;
        if (input.isEvictionExecutionModule && input.followupIsDebtorGovernmentEmployee) return false;
        if (input.forcedAttendanceIssued) return false;
        if (input.summoningRound >= 2) return true;
        if (
            input.isEvictionExecutionModule &&
            !input.followupIsDebtorGovernmentEmployee &&
            !input.followupIsDebtorRetired &&
            input.unifiedCollectionApproved &&
            input.executionEvictionLastSummonsForCollection === true &&
            input.executionEvictionLastCollectionSummonsBranch === 'coercive'
        ) {
            return true;
        }
        const graceDone = input.isEvictionExecutionModule
            ? input.isEvictionGraceExpiredNow
            : input.isGracePeriodExpiredNow;
        if (!graceDone || input.debtorAttendedVoluntarily) return false;
        return true;
    })();

    const baseSubsequentNoticeUnlocked = (() => {
        const voluntaryEndGeneral =
            !input.isEvictionExecutionModule &&
            Boolean(
                input.executionNoticeVoluntaryPeriodEndDeclared ||
                    input.noticeVoluntaryPeriodEndOptimistic,
            );
        const memoFirstVoluntaryCycle = input.notificationCount === 1;
        if (input.debtorSummonsProfile === 'employee_monetary') {
            return (
                input.debtorAttendedVoluntarily ||
                voluntaryEndGeneral ||
                (!memoFirstVoluntaryCycle && input.activeCoerciveActions.includes('salary')) ||
                (!memoFirstVoluntaryCycle &&
                    input.isGracePeriodExpiredNow &&
                    input.activeCoerciveActions.length > 0)
            );
        }
        return (
            input.voluntaryAttendanceCount > 0 ||
            voluntaryEndGeneral ||
            input.forcedPathAttendanceSecured ||
            input.debtorForcedToAttend ||
            input.investigationMemoIssued ||
            input.debtorArrested ||
            (!memoFirstVoluntaryCycle &&
                input.isGracePeriodExpiredNow &&
                input.activeCoerciveActions.length > 0)
        );
    })();

    const evictionSubsequentNoticeUnlocked =
        input.isEvictionExecutionModule &&
        input.debtorNotifiedForEvictionGrace &&
        input.notificationCount >= 1 &&
        (input.notificationCount >= 2 || input.isEvictionGraceEffectivelyExpired);

    const subsequentNoticeUnlocked =
        baseSubsequentNoticeUnlocked ||
        evictionSubsequentNoticeUnlocked ||
        Boolean(input.executionExecutorCoerciveUnlock);

    const noticeKindGoalStrictBinding =
        !input.isEvictionExecutionModule &&
        (input.followupDebtorSummonsProfile === 'employee_monetary' ||
            input.followupDebtorSummonsProfile === 'earner_like');

    const employeeAssignmentTabEnabled = input.notificationCount >= 1 && !input.activeDebtorIsDeceased;

    const employeeFinancialSalaryOnlyCoercive =
        isEmployeeMonetaryFinancialPath(input.debtorSummonsProfile as DebtorSummonsProfile);
    const monetaryCoerciveLimitedOnly =
        input.monetaryExecutionStrictPathFlag &&
        !input.isAlimonyClaim &&
        !employeeFinancialSalaryOnlyCoercive;

    const followupEmployeeFinancialSalaryOnlyCoercive =
        isEmployeeMonetaryFinancialPath(input.followupDebtorSummonsProfile as DebtorSummonsProfile);
    const followupMonetaryCoerciveLimitedOnly =
        input.monetaryExecutionStrictPathFlag &&
        !input.isAlimonyClaim &&
        !followupEmployeeFinancialSalaryOnlyCoercive;

    const followupGarnishmentAmountPreview = (() => {
        if (!input.debtorBrowserTabsMode || !input.activeWorkspaceDebtorForFollowup) {
            return input.executionGarnishmentAmount;
        }
        if (input.activeWorkspaceDebtorForFollowup.isPrimary) {
            return input.executionGarnishmentAmount;
        }
        const preview = input.perDebtorGarnishments?.[input.activeWorkspaceDebtorForFollowup.key || ''];
        return preview != null && String(preview) !== '' ? String(preview) : undefined;
    })();

    return {
        earnerForcedActionUnlocked,
        followupEarnerForcedActionUnlocked,
        baseSubsequentNoticeUnlocked,
        evictionSubsequentNoticeUnlocked,
        subsequentNoticeUnlocked,
        noticeKindGoalStrictBinding,
        employeeAssignmentTabEnabled,
        employeeFinancialSalaryOnlyCoercive,
        monetaryCoerciveLimitedOnly,
        followupEmployeeFinancialSalaryOnlyCoercive,
        followupMonetaryCoerciveLimitedOnly,
        followupGarnishmentAmountPreview,
    };
}

import { calculateDaysRemaining, isGracePeriodExpired } from '@/app/utils/executionStateMachine';

export type MemoNoticeBadge = {
    anchor: string;
    remaining: number;
    graceExpired: boolean;
};

export type DebtorAbsenceBadge = {
    label: string;
    className: string;
} | null;

export type FollowupDebtorNoticeLite = {
    notificationDate?: string | null;
};

export function buildSubsequentNoticePresentation(input: {
    notificationCount: number;
    subsequentNoticeUnlocked: boolean;
    isEvictionExecutionModule: boolean;
    executionDebtorNotificationDate?: string | null;
    executionMemoAnchorDate?: string | null;
    executionEvictionFirstNoticeDate?: string | null;
    executionNoticeVoluntaryPeriodEndDeclared?: boolean;
    executionEvictionVoluntaryPeriodEndDeclared?: boolean;
    debtorNotificationDate: string | null;
    manualGraceCalendarExtra: boolean;
    debtorAttendedVoluntarily: boolean;
    voluntaryAttendanceCount: number;
    lawyerStartedPostNoticeExecution: boolean;
    noticeVoluntaryPeriodEndOptimistic: boolean;
    voluntaryEndOptimistic: boolean;
    anyExecutorDecisionResolvedForMemoBadge: boolean;
    primaryDebtorTaklifActive: boolean;
    activeDebtorNoticeScope: { absenceBadgeDismissed?: boolean; [key: string]: unknown };
    executionDebtorSummonsMarkerId?: string | null;
    debtorSummonsMarkerLocalId?: string | null;
    effectiveDebtors: FollowupDebtorNoticeLite[];
    isEvictionGraceExpiredNow: boolean;
    isGracePeriodExpiredNow: boolean;
    now?: Date;
}): {
    primaryMemoNoticeBadge: MemoNoticeBadge | null;
    primaryDebtorNoticeYmdResolved: string | null;
    showDebtorUnservedMemoBadge: boolean;
    shouldWarnOnMemoClick: boolean;
    primaryDebtorAbsenceBadge: DebtorAbsenceBadge;
    showDebtorSummonsAttendanceBadge: boolean;
} {
    const now = input.now ?? new Date();

    const primaryMemoNoticeBadge = (() => {
        if (input.notificationCount !== 1 || input.subsequentNoticeUnlocked) return null;
        if (input.debtorAttendedVoluntarily || input.voluntaryAttendanceCount > 0) return null;
        if (input.lawyerStartedPostNoticeExecution) return null;
        if (
            !input.isEvictionExecutionModule &&
            (input.executionNoticeVoluntaryPeriodEndDeclared || input.noticeVoluntaryPeriodEndOptimistic)
        ) {
            return null;
        }
        if (
            input.isEvictionExecutionModule &&
            (input.executionEvictionVoluntaryPeriodEndDeclared || input.voluntaryEndOptimistic)
        ) {
            return null;
        }
        if (input.anyExecutorDecisionResolvedForMemoBadge) return null;
        if (input.primaryDebtorTaklifActive) return null;

        const extra = input.isEvictionExecutionModule ? 0 : input.manualGraceCalendarExtra ? 1 : 0;
        const anchor = input.isEvictionExecutionModule
            ? input.executionEvictionFirstNoticeDate ||
              input.executionDebtorNotificationDate ||
              input.debtorNotificationDate ||
              null
            : input.executionMemoAnchorDate ||
              input.executionDebtorNotificationDate ||
              input.debtorNotificationDate ||
              null;
        if (!anchor) return null;

        return {
            anchor,
            remaining: calculateDaysRemaining(anchor, now, extra),
            graceExpired: isGracePeriodExpired(anchor, now, extra),
        };
    })();

    const primaryDebtorNoticeYmdResolved =
        input.debtorNotificationDate ||
        input.executionDebtorNotificationDate ||
        input.effectiveDebtors[0]?.notificationDate ||
        null;

    const showDebtorUnservedMemoBadge =
        input.notificationCount === 0 &&
        !primaryDebtorNoticeYmdResolved &&
        !input.debtorAttendedVoluntarily &&
        input.voluntaryAttendanceCount === 0 &&
        !(input.executionNoticeVoluntaryPeriodEndDeclared || input.noticeVoluntaryPeriodEndOptimistic) &&
        !(input.executionEvictionVoluntaryPeriodEndDeclared || input.voluntaryEndOptimistic);

    const shouldWarnOnMemoClick = (() => {
        if (input.debtorAttendedVoluntarily || input.voluntaryAttendanceCount > 0) return false;
        if (input.lawyerStartedPostNoticeExecution) return false;
        const graceExpired = input.isEvictionExecutionModule
            ? input.isEvictionGraceExpiredNow
            : input.isGracePeriodExpiredNow;
        if (graceExpired) return false;
        const periodEnded = input.isEvictionExecutionModule
            ? (input.executionEvictionVoluntaryPeriodEndDeclared || input.voluntaryEndOptimistic)
            : (input.executionNoticeVoluntaryPeriodEndDeclared || input.noticeVoluntaryPeriodEndOptimistic);
        if (periodEnded) return false;
        return true;
    })();

    const primaryDebtorAbsenceBadge = (() => {
        if (input.activeDebtorNoticeScope.absenceBadgeDismissed) return null;
        if (input.lawyerStartedPostNoticeExecution) return null;
        if (input.primaryDebtorTaklifActive) return null;
        if (input.debtorAttendedVoluntarily || input.voluntaryAttendanceCount > 0) return null;

        const voluntaryEndNonEviction =
            !input.isEvictionExecutionModule &&
            input.notificationCount === 1 &&
            (input.executionNoticeVoluntaryPeriodEndDeclared || input.noticeVoluntaryPeriodEndOptimistic);

        const voluntaryEndEviction =
            input.isEvictionExecutionModule &&
            input.notificationCount === 1 &&
            (input.executionEvictionVoluntaryPeriodEndDeclared || input.voluntaryEndOptimistic);

        if (!voluntaryEndNonEviction && !voluntaryEndEviction) return null;
        if (!input.subsequentNoticeUnlocked) return null;

        return {
            label: 'عدم حضور المدين',
            className:
                'backdrop-blur-sm bg-rose-500/25 text-rose-200 px-2 py-0.5 rounded-lg text-[9px] border border-rose-400/35 font-bold',
        };
    })();

    const showDebtorSummonsAttendanceBadge =
        Boolean(input.subsequentNoticeUnlocked) &&
        !input.primaryDebtorTaklifActive &&
        !input.debtorAttendedVoluntarily &&
        input.voluntaryAttendanceCount === 0 &&
        !input.lawyerStartedPostNoticeExecution &&
        Boolean(
            input.executionDebtorSummonsMarkerId ||
                input.debtorSummonsMarkerLocalId ||
                input.notificationCount >= 2,
        );

    return {
        primaryMemoNoticeBadge,
        primaryDebtorNoticeYmdResolved,
        showDebtorUnservedMemoBadge,
        shouldWarnOnMemoClick,
        primaryDebtorAbsenceBadge,
        showDebtorSummonsAttendanceBadge,
    };
}

import type { OtherPartyActionLogEntry } from '@/app/types/execution';
import {
    isExecutorRowEffectivelyApproved,
    isExecutorRowRejectedAndFinal,
} from '@/app/utils/executorSeizureDecisionQueue';

export function resolveOtherPartyLogDecisionRow(
    entry: OtherPartyActionLogEntry,
    decisions: Record<string, unknown>[],
): Record<string, unknown> | null {
    const did = String(entry.decisionRowId || '').trim();
    if (did) {
        const linked = decisions.find((r) => String((r as { id?: string }).id || '').trim() === did);
        if (linked) return linked;
    }
    const pending = decisions.filter((r) => {
        if (String((r as { requestKind?: string }).requestKind || '') !== 'special_followup') {
            return false;
        }
        const title = String((r as { title?: string }).title || '').trim();
        if (!/تحرك الطرف الآخر/i.test(title)) return false;
        const out = String((r as { executorOutcome?: string }).executorOutcome ?? 'pending');
        return out === 'pending' || out === '';
    });
    if (pending.length === 0) return null;
    return pending.reduce((acc, cur) => {
        const a = String(
            (acc as { resolvedAt?: string; date?: string }).resolvedAt ??
                (acc as { date?: string }).date ??
                '',
        );
        const b = String(
            (cur as { resolvedAt?: string; date?: string }).resolvedAt ??
                (cur as { date?: string }).date ??
                '',
        );
        return b.localeCompare(a, undefined, { numeric: true }) > 0 ? cur : acc;
    }, pending[0]!);
}

function isPendingExecutorDecisionRow(row: Record<string, unknown> | null | undefined): boolean {
    if (!row) return false;
    const outcome = String((row as { executorOutcome?: string }).executorOutcome ?? 'pending');
    return outcome === 'pending' || outcome === '';
}

export function resolveOtherPartyLogEntryOutcome(
    entry: OtherPartyActionLogEntry,
    decisions: Record<string, unknown>[],
): OtherPartyActionLogEntry['outcome'] {
    const row = resolveOtherPartyLogDecisionRow(entry, decisions);
    if (row) {
        if (isExecutorRowRejectedAndFinal(row)) return 'rejected';
        if (isExecutorRowEffectivelyApproved(row)) return 'approved';
        if (isPendingExecutorDecisionRow(row)) return 'pending';
    }
    return entry.outcome ?? 'pending';
}

export function syncOtherPartyActionLogOutcomes(
    log: OtherPartyActionLogEntry[] | null | undefined,
    decisions: Record<string, unknown>[],
): { next: OtherPartyActionLogEntry[]; changed: boolean } {
    if (!Array.isArray(log) || log.length === 0) {
        return { next: [], changed: false };
    }
    let changed = false;
    const next = log.map((entry) => {
        const outcome = resolveOtherPartyLogEntryOutcome(entry, decisions);
        if (outcome !== entry.outcome) {
            changed = true;
            return { ...entry, outcome };
        }
        return entry;
    });
    return { next, changed };
}

import type { OtherPartyActionLogEntry } from '@/app/types/execution';

export function buildOtherPartyActionLogEntry(input: {
    date: string;
    content: string;
    decisionRowId?: string;
    id?: string;
}): OtherPartyActionLogEntry {
    const date = String(input.date || '').trim();
    const content = String(input.content || '').trim();
    const id =
        String(input.id || '').trim() ||
        `opa-${Date.now()}-${Math.random().toString(36).slice(2, 9)}`;
    return {
        id,
        date,
        content,
        outcome: 'pending',
        savedAt: new Date().toISOString(),
        ...(input.decisionRowId ? { decisionRowId: input.decisionRowId } : {}),
    };
}

export function prependOtherPartyActionLog(
    existing: OtherPartyActionLogEntry[] | null | undefined,
    entry: OtherPartyActionLogEntry,
): OtherPartyActionLogEntry[] {
    const prev = Array.isArray(existing) ? existing : [];
    const withoutDup = prev.filter((row) => row.id !== entry.id);
    return [entry, ...withoutDup];
}

export function persistOtherPartyActionLogEntry(
    persistExecutionMerge: ((patch: Record<string, unknown>) => boolean | void) | undefined,
    existing: OtherPartyActionLogEntry[] | null | undefined,
    entry: OtherPartyActionLogEntry,
): boolean {
    if (typeof persistExecutionMerge !== 'function') return false;
    const merged = prependOtherPartyActionLog(existing, entry);
    const ok = persistExecutionMerge({ other_party_actions_log: merged });
    return ok !== false;
}

import type { OtherPartyActionLogEntry } from '@/app/types/execution';
import SecureStoreService from '@/app/services/SecureStoreService';
import { appendSpecialFollowupRequest } from '@/app/utils/specialFollowupDecisionQueue';
import { DECISIONS_RELOAD_EVENT } from '@/app/utils/executorSeizureDecisionQueue';
import {
    buildOtherPartyActionLogEntry,
    persistOtherPartyActionLogEntry,
} from '@/app/application/execution/followup/otherPartyActionLogPersist';

export type SubmitOtherPartyFollowupActionInput = {
    date: string;
    content: string;
    decisionsStorageExecutionId: string | undefined;
    existingLog: OtherPartyActionLogEntry[] | null | undefined;
    executionData?: Record<string, unknown> | null;
    persistExecutionMerge?: (patch: Record<string, unknown>) => boolean | void;
    isRepresentingDebtor?: boolean;
    showToast?: (message: string, type?: string, opts?: Record<string, unknown>) => void;
};

function dispatchDecisionsReload(): void {
    if (typeof window === 'undefined') return;
    try {
        window.dispatchEvent(new CustomEvent(DECISIONS_RELOAD_EVENT));
    } catch {
        /* ignore */
    }
}

export function submitOtherPartyFollowupAction(
    input: SubmitOtherPartyFollowupActionInput,
): { ok: boolean; decisionId?: string; logEntryId?: string } {
    const d = String(input.date || '').trim();
    const content = String(input.content || '').trim();
    if (!d || !content) {
        input.showToast?.('أدخل تاريخ التحرك ومضمون الطلب', 'warning');
        return { ok: false };
    }

    if (input.isRepresentingDebtor) {
        const logEntry = buildOtherPartyActionLogEntry({
            date: d,
            content,
        });
        const persisted = persistOtherPartyActionLogEntry(
            input.persistExecutionMerge,
            input.existingLog,
            logEntry,
        );
        input.showToast?.(
            persisted
                ? 'تم تسجيل التحرك في السجل الزمني.'
                : 'تعذّر حفظ التحرك — أعد المحاولة',
            persisted ? 'success' : 'warning',
        );
        return persisted ? { ok: true, logEntryId: logEntry.id } : { ok: false };
    }

    const decisionId = appendSpecialFollowupRequest({
        executionId: input.decisionsStorageExecutionId,
        requestDate: d,
        content,
        appealRequestOrigin: 'debtor_side',
        decisionTitle: 'تحرك الطرف الآخر — قيد البت',
        executionData: input.executionData,
        otherPartyFollowup: true,
    });
    if (!decisionId) {
        input.showToast?.('تعذّر حفظ التحرك — أعد المحاولة', 'warning', { decisionsLink: true });
        return { ok: false };
    }
    try {
        SecureStoreService.flushHeavyPersistPending();
    } catch {
        /* ignore */
    }

    const logEntry = buildOtherPartyActionLogEntry({
        date: d,
        content,
        decisionRowId: decisionId,
    });
    const persisted = persistOtherPartyActionLogEntry(
        input.persistExecutionMerge,
        input.existingLog,
        logEntry,
    );

    dispatchDecisionsReload();

    input.showToast?.(
        persisted
            ? 'تم حفظ التحرك في السجل.'
            : 'تم إنشاء بطاقة القرار — أعد المحاولة إن لم يظهر السجل.',
        persisted ? 'success' : 'warning',
        persisted ? undefined : { decisionsLink: true },
    );

    return { ok: true, decisionId, logEntryId: logEntry.id };
}

import { useEffect } from 'react';
import type { ExecutionFile } from '@/app/types/execution';
import {
    DECISIONS_RELOAD_EVENT,
    readExecutorDecisionsArray,
} from '@/app/utils/executorSeizureDecisionQueue';
import { syncOtherPartyActionLogOutcomes } from './otherPartyActionLogOutcome';

type Params = {
    executionData: ExecutionFile | null | undefined;
    executionId: string | undefined;
    decisionsStorageExecutionId: string | undefined;
    decisionsReloadEpoch?: number;
    persistExecutionMerge: (patch: Record<string, unknown>) => boolean | void;
};

export function useOtherPartyActionLogOutcomeSync({
    executionData,
    executionId,
    decisionsStorageExecutionId,
    decisionsReloadEpoch = 0,
    persistExecutionMerge,
}: Params): void {
    useEffect(() => {
        const log = executionData?.other_party_actions_log;
        if (!Array.isArray(log) || log.length === 0) return;

        const storageId = String(decisionsStorageExecutionId || executionId || '').trim();
        if (!storageId) return;

        const decisions = readExecutorDecisionsArray(storageId);
        const { next, changed } = syncOtherPartyActionLogOutcomes(log, decisions);
        if (changed) {
            persistExecutionMerge({ other_party_actions_log: next });
        }
    }, [
        decisionsReloadEpoch,
        decisionsStorageExecutionId,
        executionData?.other_party_actions_log,
        executionId,
        persistExecutionMerge,
    ]);

    useEffect(() => {
        const onReload = () => {
            const log = executionData?.other_party_actions_log;
            if (!Array.isArray(log) || log.length === 0) return;

            const storageId = String(decisionsStorageExecutionId || executionId || '').trim();
            if (!storageId) return;

            const decisions = readExecutorDecisionsArray(storageId);
            const { next, changed } = syncOtherPartyActionLogOutcomes(log, decisions);
            if (changed) {
                persistExecutionMerge({ other_party_actions_log: next });
            }
        };

        if (typeof window === 'undefined') return undefined;
        window.addEventListener(DECISIONS_RELOAD_EVENT, onReload);
        return () => window.removeEventListener(DECISIONS_RELOAD_EVENT, onReload);
    }, [
        decisionsStorageExecutionId,
        executionData?.other_party_actions_log,
        executionId,
        persistExecutionMerge,
    ]);
}

/**
