import type { AdminUser, AdminVerificationStatus } from '@/app/domain/admin/AdminUser';

export type HqUserPresence =
    | 'active'
    | 'frozen'
    | 'pending'
    | 'unsubmitted'
    | 'rejected'
    | 'locked'
    | 'deleted';

export function parseAdminVerificationStatus(raw: unknown): AdminVerificationStatus {
    if (raw === 'pending' || raw === 'active' || raw === 'rejected') return raw;
    return 'none';
}

/**
 * KV أولاً إن وُجد صف بحالة صالحة.
 * إن غاب الصف (KV نجح بلا قيمة) أو تعذّر الخزن → app_metadata — ليس user_metadata.
 */
export function resolveHqDirectoryKycStatus(
    kvValue: unknown,
    kvAvailable: boolean,
    appMetadataStatus: unknown = 'none',
): AdminVerificationStatus {
    if (kvAvailable) {
        const fromKv = parseAdminVerificationStatus(kvValue);
        if (fromKv !== 'none') return fromKv;
    }
    return parseAdminVerificationStatus(appMetadataStatus);
}

export function resolveHqUserPresence(
    user: Pick<AdminUser, 'role' | 'status' | 'verificationStatus'> &
        Pick<AdminUser, 'isDeleted' | 'loginBlocked' | 'loginUntil'>,
): HqUserPresence {
    if (user.isDeleted) return 'deleted';
    const loginUntilMs = user.loginUntil ? Date.parse(user.loginUntil) : NaN;
    const loginLocked = user.loginBlocked === true || (Number.isFinite(loginUntilMs) && loginUntilMs > Date.now());
    if (loginLocked) return 'locked';
    if (user.status === 'suspended') return 'frozen';
    if (user.role === 'lawyer') {
        if (user.verificationStatus === 'rejected') return 'rejected';
        if (user.verificationStatus === 'pending') return 'pending';
        if (user.verificationStatus !== 'active') return 'unsubmitted';
    }
    return 'active';
}

export function hqUserPresenceLabel(kind: HqUserPresence): string {
    if (kind === 'deleted') return 'محذوف';
    if (kind === 'locked') return 'مقفل الدخول';
    if (kind === 'frozen') return 'موقوف';
    if (kind === 'pending') return 'قيد التدقيق';
    if (kind === 'unsubmitted') return 'بلا طلب';
    if (kind === 'rejected') return 'مرفوض';
    return 'نشط';
}

/** شارة الدليل — نفس ألفاظ تبويب التوثيق للمحامي */
export function hqDirectoryStatusLabel(
    user: Pick<AdminUser, 'role' | 'status' | 'verificationStatus' | 'isDeleted' | 'loginBlocked' | 'loginUntil'>,
): string {
    const kind = resolveHqUserPresence(user);
    if (kind === 'active' && user.role === 'lawyer') return 'معتمد';
    return hqUserPresenceLabel(kind);
}

export function isHqDirectoryActive(
    user: Pick<AdminUser, 'role' | 'status' | 'verificationStatus' | 'isDeleted' | 'loginBlocked' | 'loginUntil'>,
): boolean {
    return resolveHqUserPresence(user) === 'active';
}

/** علامة التوثيق العامة — يضعها المقر يدوياً، ليست حالة اعتماد الهوية */
export function isAccreditedLawyer(
    user: Pick<AdminUser, 'role' | 'isDeleted' | 'publicVerifiedBadge'>,
): boolean {
    return user.role === 'lawyer' && user.publicVerifiedBadge === true && user.isDeleted !== true;
}

export type HqVerificationOrderRow = {
    status: string;
    submittedAt: string;
};

export function compareHqVerificationQueueRows(
    a: HqVerificationOrderRow,
    b: HqVerificationOrderRow,
): number {
    const pendingRank = (status: string) => (status === 'pending' ? 0 : 1);
    const rank = pendingRank(a.status) - pendingRank(b.status);
    if (rank !== 0) return rank;
    const ta = Date.parse(a.submittedAt);
    const tb = Date.parse(b.submittedAt);
    const na = Number.isFinite(ta) ? ta : 0;
    const nb = Number.isFinite(tb) ? tb : 0;
    if (a.status === 'pending') return na - nb;
    return nb - na;
}

export function sortHqVerificationQueueRows<T extends HqVerificationOrderRow>(rows: readonly T[]): T[] {
    return [...rows].sort(compareHqVerificationQueueRows);
}

import type { TimelineEvent } from '@/app/types/execution';

export const INABA_SUB_FILE_ID = '__inaba__';
export const INABA_SUB_FILE_PREFIX = INABA_SUB_FILE_ID;
export const DOSSIER_SCOPE_INABA = 'inaba';
export const DOSSIER_SCOPE_PARENT = 'parent';

export function makeInabaSubFileId(parentFileId: string): string {
    const parentId = String(parentFileId || '').trim();
    return parentId ? `${INABA_SUB_FILE_PREFIX}:${parentId}` : INABA_SUB_FILE_PREFIX;
}

export function isInabaSubFileId(id: string | null | undefined): boolean {
    const value = String(id || '').trim();
    if (!value) return false;
    return value === INABA_SUB_FILE_PREFIX || value.startsWith(`${INABA_SUB_FILE_PREFIX}:`);
}

export type ResolveParentDossierState = {
    currentFile?: { id?: string | number | null; parentId?: string | number | null } | null;
    delegationParentFileId?: string | null;
    activeSubFileId?: string | null;
};

export function resolveParentDossierId(
    state: ResolveParentDossierState,
    fallbackId?: string | null,
): string {
    const fromDelegation = String(state.delegationParentFileId || '').trim();
    if (fromDelegation && !isInabaSubFileId(fromDelegation)) return fromDelegation;

    const currentId = String(state.currentFile?.id || '').trim();
    if (currentId && !isInabaSubFileId(currentId)) return currentId;

    const parentLink = String(state.currentFile?.parentId || '').trim();
    if (parentLink && !isInabaSubFileId(parentLink)) return parentLink;

    const fallback = String(fallbackId || '').trim();
    if (fallback && !isInabaSubFileId(fallback)) return fallback;

    return '';
}

export function timelineEventBelongsToInabaDossier(
    event: TimelineEvent | null | undefined,
    subFileId: string,
): boolean {
    if (!event || (event as { trashedAt?: string }).trashedAt) return false;
    const subId = String(subFileId || '').trim();
    if (!subId) return false;
    const metadata = ((event as { metadata?: Record<string, unknown> }).metadata || {}) as Record<string, unknown>;
    const scope = String(metadata.dossierScope || '');
    const taggedSub = String(metadata.inabaSubFileId || metadata.executionDossierId || '').trim();

    if (scope === DOSSIER_SCOPE_PARENT) return false;
    if (scope === DOSSIER_SCOPE_INABA) {
        return !taggedSub || taggedSub === subId;
    }
    if (taggedSub) return taggedSub === subId;
    return true;
}

export function timelineEventBelongsToParentDossier(
    event: TimelineEvent | null | undefined,
    parentId: string,
): boolean {
    if (!event || (event as { trashedAt?: string }).trashedAt) return false;
    const metadata = ((event as { metadata?: Record<string, unknown> }).metadata || {}) as Record<string, unknown>;
    if (String(metadata.dossierScope || '') === DOSSIER_SCOPE_INABA) return false;
    if (String(metadata.inabaSubFileId || '').trim()) return false;
    const resolvedParentId = String(parentId || '').trim();
    const taggedParent = String(metadata.parentExecutionId || '').trim();
    if (taggedParent && resolvedParentId && taggedParent !== resolvedParentId) return false;
    return true;
}

export function filterTimelineEventsForInabaDossier(
    events: TimelineEvent[],
    subFileId: string,
): TimelineEvent[] {
    return (events || []).filter((event) => timelineEventBelongsToInabaDossier(event, subFileId));
}

export function filterTimelineEventsForParentDossier(
    events: TimelineEvent[],
    parentId: string,
): TimelineEvent[] {
    return (events || []).filter((event) => timelineEventBelongsToParentDossier(event, parentId));
}

export function stampInabaTimelineEventMetadata(
    event: TimelineEvent,
    subFileId: string,
    parentId: string,
): TimelineEvent {
    const metadata = {
        ...(((event as { metadata?: Record<string, unknown> }).metadata || {}) as Record<string, unknown>),
        dossierScope: DOSSIER_SCOPE_INABA,
        inabaSubFileId: subFileId,
        parentExecutionId: parentId,
    };
    return { ...event, metadata } as TimelineEvent;
}

export function stampParentTimelineEventMetadata(
    event: TimelineEvent,
    parentId: string,
): TimelineEvent {
    const resolvedParentId = String(parentId || '').trim();
    const metadata = {
        ...(((event as { metadata?: Record<string, unknown> }).metadata || {}) as Record<string, unknown>),
        dossierScope: DOSSIER_SCOPE_PARENT,
        ...(resolvedParentId ? { parentExecutionId: resolvedParentId } : {}),
    };
    return { ...event, metadata } as TimelineEvent;
}

export type DebtorEmploymentLike = {
