    blue: 'backdrop-blur-sm bg-sky-500/15 text-sky-200 px-2 py-0.5 rounded-lg text-[9px] border border-sky-400/35 font-bold',
    purple: 'backdrop-blur-sm bg-purple-500/15 text-purple-200 px-2 py-0.5 rounded-lg text-[9px] border border-purple-400/35 font-bold',
    orange: 'backdrop-blur-sm bg-orange-500/15 text-orange-200 px-2 py-0.5 rounded-lg text-[9px] border border-orange-400/35 font-bold',
    red: 'backdrop-blur-sm bg-red-600/25 text-red-200 px-2 py-0.5 rounded-lg text-[9px] border border-red-400/40 font-bold',
} as const;

function ensureWaitingBadge(badges: SummoningBadge[]) {
    if (!badges.some((b) => b.id === 'waiting_notification_period')) {
        badges.unshift({
            id: 'waiting_notification_period',
            label: 'بانتظار انتهاء مدة الإخبار',
            className: BADGE.yellow,
        });
    }
}

function applyIssuedMemoLock(
    base: ForcedSummoningAnalysis,
    issued: boolean
): ForcedSummoningAnalysis {
    if (!issued) return base;
    const badges = [...base.badges];
    if (!badges.some((b) => b.id === 'warrant_memo_active')) {
        badges.push({
            id: 'warrant_memo_active',
            label: 'مطلوب بمذكرة قبض',
            className: BADGE.red,
        });
    }
    return {
        ...base,
        canForceSummon: false,
        lockReasonAr:
            'صدرت مذكرة إحضار — يُتابع بتأمين الإحضار ومفاتحة محكمة التحقيق وإصدار مذكرة قبض عند اللزوم.',
        badges,
    };
}

/**
 * تحديد إن كان يجوز المضي قانوناً بإحضار المدين جبراً (قبل تفعيل زر «إحضار جبري»).
 */
export function canBeForcefullySummoned(input: SummoningImmunityInput): ForcedSummoningAnalysis {
    const badges: SummoningBadge[] = [];

    if (!input.notificationDate) {
        ensureWaitingBadge(badges);
        return applyIssuedMemoLock(
            {
                canForceSummon: false,
                lockReasonAr:
                    'لا يصح الإحضار الجبري قبل إتمام التبليغ وتحديد تاريخ التبليغ الفعلي.',
                badges,
                calendarGateOpen: false,
            },
            input.forcedAttendanceIssued
        );
    }

    const extraGrace = Math.max(0, input.graceExtraCalendarDays ?? 0);
    const sevenDayPassed = isGracePeriodExpired(input.notificationDate, new Date(), extraGrace);
    const calendarGateOpen = sevenDayPassed || input.hasAttendanceHistory;

    if (!calendarGateOpen) {
        ensureWaitingBadge(badges);
    }

    /** متقاعد: راتب تقاعد — لا إحضار جبري؛ يُفضَّل حجز عبر هيئة التقاعد */
    if (input.employmentType === 'متقاعد') {
        if (!calendarGateOpen) {
            ensureWaitingBadge(badges);
        }
        badges.push({
            id: 'retiree_pension_garnishment_route',
            label: 'متقاعد — مسار حجز راتب التقاعد',
            className: BADGE.blue,
        });
        return applyIssuedMemoLock(
            {
                canForceSummon: false,
                lockReasonAr:
                    'المدين متقاعد ويتقاضى راتب تقاعد؛ يُكتفى بحجز الراتب التقاعدي عبر هيئة التقاعد الوطنية ولا يُفضَّل الإحضار الجبري أو الحبس التنفيذي في هذا المسار.',
                badges,
                employeeReplacementNoteAr: 'يُوجَّه الحجز إلى هيئة التقاعد الوطنية',
                calendarGateOpen,
            },
            input.forcedAttendanceIssued
        );
    }

    // درع الكفيل — دين مالي فقط
    if (input.hasGuarantor && input.claimNature === 'مالي') {
        badges.push({
            id: 'guarantor_redirect',
            label: 'يوجد كفيل ضامن',
            className: BADGE.purple,
        });
        if (!calendarGateOpen) {
            return applyIssuedMemoLock(
                {
                    canForceSummon: false,
                    lockReasonAr:
                        'ينتظر انتهاء مهلة الإخبار. عند وجود كفيل ضامن في المطالبة المالية يُوجَّه الإجراء للكفيل لا للمدين.',
                    badges,
                    guarantorReplacementNoteAr: 'يوجد كفيل ضامن — يوجه الإجراء للكفيل',
                    calendarGateOpen: false,
                },
                input.forcedAttendanceIssued
            );
        }
        return applyIssuedMemoLock(
            {
                canForceSummon: false,
                lockReasonAr:
                    'لا يجوز إحضار المدين جبراً: يوجد كفيل ضامن والمطالبة مالية — يُوجَّه الإجراء للكفيل الضامن.',
                badges,
                guarantorReplacementNoteAr: 'يوجد كفيل ضامن — يوجه الإجراء للكفيل',
                calendarGateOpen: true,
            },
            input.forcedAttendanceIssued
        );
    }

    // موظف + التزام غير مالي → لا حصانة إحضار (مثل التسليم)
    if (input.employmentType === 'موظف' && input.claimNature === 'غير مالي') {
        badges.push({
            id: 'exposed_non_financial',
            label: 'معرض للإحضار — التزام غير مالي',
            className: BADGE.orange,
        });
        if (!calendarGateOpen) {
            return applyIssuedMemoLock(
                {
                    canForceSummon: false,
                    lockReasonAr:
                        'لا يجوز الإحضار الجبري قبل انتهاء مهلة الإخبار (7 أيام عملية من اليوم التالي للتبليغ)، ما لم يثبت حضور المدين سابقاً.',
                    badges,
                    calendarGateOpen: false,
                },
                input.forcedAttendanceIssued
            );
        }
        return applyIssuedMemoLock(
            {
                canForceSummon: true,
                lockReasonAr: '',
                badges,
                calendarGateOpen: true,
            },
            input.forcedAttendanceIssued
        );
    }

    const alimonyShortfallException =
        input.isAlimony && input.salaryCoversAlimony === false;

    if (input.employmentType === 'موظف' && input.claimNature === 'مالي') {
        if (alimonyShortfallException) {
            badges.push({
                id: 'exposed_alimony_shortfall',
                label: 'معرض للإحضار — عجز عن سداد النفقة',
                className: BADGE.orange,
            });
            if (!calendarGateOpen) {
                return applyIssuedMemoLock(
                    {
                        canForceSummon: false,
                        lockReasonAr:
                            'عجز الراتب عن تغطية النفقة يسمح بالإحضار الجبري بعد انتهاء مهلة الإخبار (أو بإثبات حضور سابق يعفي من انتظار المهلة).',
                        badges,
                        calendarGateOpen: false,
                    },
                    input.forcedAttendanceIssued
                );
            }
            return applyIssuedMemoLock(
                {
                    canForceSummon: true,
                    lockReasonAr: '',
                    badges,
                    calendarGateOpen: true,
                },
                input.forcedAttendanceIssued
            );
        }

        if (!calendarGateOpen) {
            ensureWaitingBadge(badges);
        }
        badges.push({
            id: 'employee_salary_garnishment_only',
            label: 'محمي قانونياً — يُكتفى بحجز الراتب',
            className: BADGE.blue,
        });
        return applyIssuedMemoLock(
            {
                canForceSummon: false,
                lockReasonAr:
                    'لا يجوز إحضار الموظف جبراً في الديون المالية؛ يُكتفى بحجز الراتب وفق أحكام التنفيذ.',
                badges,
                employeeReplacementNoteAr: 'يُكتفى بحجز الراتب',
                calendarGateOpen,
            },
            input.forcedAttendanceIssued
        );
    }

    // كاسب + مطالبة مالية ضمن تنفيذ مالي صارم: لا إحضار جبري — إلا عند تجاوز 250,000 د.ع في المركز المالي
    const monetaryStrict = input.monetaryExecutionStrict === true;
    const earnerFinancialPersonalCoercive =
        input.earnerPersonalCoerciveFinancialThresholdMet === true;
    if (
        monetaryStrict &&
        !earnerFinancialPersonalCoercive &&
        !input.isAlimony &&
        input.employmentType === 'كاسب' &&
        input.claimNature === 'مالي'
    ) {
        if (!calendarGateOpen) {
            ensureWaitingBadge(badges);
        }
        badges.push({
            id: 'earner_monetary_seizures_only',
            label: 'تنفيذ مالي — حصر الإجراء بحجز الأموال',
            className: BADGE.blue,
        });
        return applyIssuedMemoLock(
            {
                canForceSummon: false,
                lockReasonAr:
                    'في التنفيذ المالي لا يُحضَّر المدين (كاسب) جبراً ولا يُتَخَذ بحقه قبض؛ يُكتفى بحجز الراتب أو العقار أو المركبة بعد مهلة الإخبار.',
                badges,
                employeeReplacementNoteAr: 'يُكتفى بحجز الراتب/العقار/المركبة',
                calendarGateOpen,
            },
            input.forcedAttendanceIssued
        );
    }

    // كاسب — بدون كفيل مالي (مُعالج) وبدون حصانة موظف
    if (!calendarGateOpen) {
        return applyIssuedMemoLock(
            {
                canForceSummon: false,
                lockReasonAr:
                    'لا يجوز الإحضار الجبري قبل انتهاء مهلة الإخبار (7 أيام من اليوم التالي للتبليغ)، ما لم يثبت حضور المدين سابقاً.',
                badges,
                calendarGateOpen: false,
            },
            input.forcedAttendanceIssued
        );
    }

    return applyIssuedMemoLock(
        {
            canForceSummon: true,
            lockReasonAr: '',
            badges,
            calendarGateOpen: true,
        },
        input.forcedAttendanceIssued
    );
}

export function deriveMonetaryClaimNature(
    claimType: string | undefined,
    explicit?: MonetaryClaimNature | null
): MonetaryClaimNature {
    if (explicit === 'مالي' || explicit === 'غير مالي') return explicit;
    const ct = String(claimType || '').trim();
    if (
        isVisitationClaim(ct) ||
        isMatwaaClaim(ct) ||
        isEncroachmentRemovalClaim(ct) ||
        isEvictionClaim(ct) ||
        isSpecificDeliveryClaim(ct) ||
        isMaritalFurnitureClaim(ct)
    ) {
        return 'غير مالي';
    }
    const NON_FINANCIAL = ['استصحاب', 'مبيت', 'تسليم طفل', 'تسليم ولد'];
    if (NON_FINANCIAL.some((k) => ct.includes(k))) return 'غير مالي';
    return 'مالي';
}

export function deriveEmploymentType(
    occupation: string | undefined,
    explicit?: EmploymentTypeSummoning | null
): EmploymentTypeSummoning {
    if (explicit === 'موظف' || explicit === 'كاسب' || explicit === 'متقاعد') return explicit;
    const o = (occupation || '').toLowerCase();
    if (o.includes('متقاعد') || o.includes('تقاعد')) return 'متقاعد';
    if (o.includes('موظف') || o.includes('حكومي')) return 'موظف';
    if (o.includes('كاسب') || o.includes('خاص')) return 'كاسب';
    return 'كاسب';
}

import type { VisitationScheduleConfig, VisitationSession } from '@/app/types/visitationSchedule';
import { computeVisitationSessionReturnYmd } from './visitationScheduleDateUtils';
import { isVisitationSessionDocumented } from './visitationScheduleSessions';

export type VisitationCalendarCellTone =
    | 'empty'
    | 'scheduled'
    | 'overdue'
    | 'documented_success'
    | 'documented_absence'
    | 'return_scheduled'
    | 'return_overdue'
    | 'return_documented_success'
    | 'return_documented_absence';

export type VisitationCalendarDayRole = 'pickup' | 'return';

export type VisitationCalendarDayMarker = {
    session: VisitationSession;
    role: VisitationCalendarDayRole;
};

export function buildVisitationCalendarDayMarkers(
    config: VisitationScheduleConfig,
    sessions: VisitationSession[],
): Map<string, VisitationCalendarDayMarker[]> {
    const map = new Map<string, VisitationCalendarDayMarker[]>();
    const push = (ymd: string, marker: VisitationCalendarDayMarker) => {
        const list = map.get(ymd) ?? [];
        list.push(marker);
        map.set(ymd, list);
    };
    for (const session of sessions) {
        push(session.date, { session, role: 'pickup' });
        const returnYmd = computeVisitationSessionReturnYmd(config, session.date);
        if (returnYmd && returnYmd !== session.date) {
            push(returnYmd, { session, role: 'return' });
        }
    }
    return map;
}

function resolvePickupCalendarTone(session: VisitationSession, todayYmd: string): VisitationCalendarCellTone {
    if (isVisitationSessionDocumented(session)) {
        return session.status === 'completed' ? 'documented_success' : 'documented_absence';
    }
    const today = String(todayYmd || '').trim();
    if (today && session.date < today) return 'overdue';
    return 'scheduled';
}

function resolveReturnCalendarTone(
    session: VisitationSession,
    returnYmd: string,
    todayYmd: string,
): VisitationCalendarCellTone {
    if (isVisitationSessionDocumented(session)) {
        return session.status === 'completed'
            ? 'return_documented_success'
            : 'return_documented_absence';
    }
    const today = String(todayYmd || '').trim();
    if (today && returnYmd < today) return 'return_overdue';
    return 'return_scheduled';
}

export function resolveVisitationCalendarCellToneForDate(
    markers: VisitationCalendarDayMarker[] | undefined,
    dateYmd: string,
    todayYmd: string,
): VisitationCalendarCellTone {
    if (!markers?.length) return 'empty';
    const pickup = markers.find((m) => m.role === 'pickup');
    if (pickup) return resolvePickupCalendarTone(pickup.session, todayYmd);
    const ret = markers.find((m) => m.role === 'return');
    if (ret) return resolveReturnCalendarTone(ret.session, dateYmd, todayYmd);
    return 'empty';
}

export function resolveVisitationCalendarCellTone(
    session: VisitationSession | undefined,
    todayYmd: string,
): VisitationCalendarCellTone {
    if (!session) return 'empty';
    return resolvePickupCalendarTone(session, todayYmd);
}

import type { VisitationDecisionMode, VisitationScheduleConfig, VisitationSession } from '@/app/types/visitationSchedule';
import {
    ARABIC_WEEKDAY_LABELS,
    ARABIC_WEEKDAY_SHORT_LABELS,
    getVisitationFieldLabels,
    IRAQI_ARABIC_MONTHS,
} from './visitationScheduleLabels';

export function parseYmdToLocalDate(ymd: string): Date | null {
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(String(ymd || '').trim());
    if (!m) return null;
    const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
    if (Number.isNaN(d.getTime())) return null;
    d.setHours(0, 0, 0, 0);
    return d;
}

export function formatYmdLocal(d: Date): string {
    const y = d.getFullYear();
    const mo = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${mo}-${day}`;
}

/** الأسبوع 1–4 ضمن الشهر (أيام 1–7، 8–14، …) */
export function weekOfMonthFromDate(d: Date): number {
    return Math.min(4, Math.ceil(d.getDate() / 7));
}

export function formatDateLongAr(ymd: string): string {
    const d = parseYmdToLocalDate(ymd);
    if (!d) return ymd;
    return `${ARABIC_WEEKDAY_LABELS[d.getDay()]} الموافق ${d.getDate()} ${IRAQI_ARABIC_MONTHS[d.getMonth()]} ${d.getFullYear()}`;
}

/** تاريخ مختصر للبطاقات — بدون سنة عند الحاجة للإيجاز */
export function formatDateCompactAr(ymd: string): string {
    const d = parseYmdToLocalDate(ymd);
    if (!d) return ymd;
    return `${ARABIC_WEEKDAY_SHORT_LABELS[d.getDay()]} ${d.getDate()} ${IRAQI_ARABIC_MONTHS[d.getMonth()]}`;
}

/** يضيف أياماً تقويمية إلى YYYY-MM-DD */
export function addCalendarDaysToYmd(ymd: string, days: number): string | null {
    const d = parseYmdToLocalDate(ymd);
    if (!d || !Number.isFinite(days)) return null;
    d.setDate(d.getDate() + Math.round(days));
    return formatYmdLocal(d);
}

export function formatVisitationClock(raw: string | undefined): string {
    const t = String(raw || '').trim();
    if (!t) return '—';
    const m = /^(\d{1,2}):(\d{2})/.exec(t);
    if (!m) return t;
    return `${m[1].padStart(2, '0')}:${m[2]}`;
}

export type VisitationSessionTimingLine = {
    label: string;
    value: string;
};

/**
 * يصف توقيت موعد واحد وفق نوع القرار:
 * - مشاهدة/استلام يومي: أوقات في يوم الموعد
 * - مبيت: تاريخ/وقت الاستلام + تاريخ/وقت الإرجاع بعد عدد الليالي
 */
export function describeVisitationSessionTiming(
    config: VisitationScheduleConfig,
    sessionDateYmd: string
): VisitationSessionTimingLine[] {
    const labels = getVisitationFieldLabels(config.decisionMode);
    const location = String(config.location || '').trim() || '—';
    const startClock = formatVisitationClock(config.startTime);
    const lines: VisitationSessionTimingLine[] = [
        { label: labels.location, value: location },
    ];

    switch (config.decisionMode) {
        case 'viewing_only':
            lines.push({
                label: 'التوقيت',
                value: `${labels.startTime}: ${startClock} — ${labels.endTime ?? 'النهاية'}: ${formatVisitationClock(config.endTime)}`,
            });
            break;
        case 'viewing_pickup':
            lines.push({
                label: 'التوقيت',
                value: `${labels.startTime}: ${startClock} — ${labels.endTime ?? 'الإرجاع'}: ${formatVisitationClock(config.endTime)} (نفس اليوم)`,
            });
            break;
        case 'viewing_pickup_sleepover': {
            const nights = Math.max(1, Number(config.sleepoverNights) || 1);
            const returnYmd = addCalendarDaysToYmd(sessionDateYmd, nights);
            const nightLabel = nights === 1 ? 'ليلة واحدة' : `${nights} ليالي`;
            lines.push({
                label: labels.startTime,
                value: `الساعة ${startClock}`,
            });
            lines.push({
                label: 'تاريخ الإرجاع بعد المبيت',
                value: `${returnYmd ? formatDateLongAr(returnYmd) : '—'} (بعد ${nightLabel})`,
            });
            lines.push({
                label: labels.returnTime ?? 'وقت الإرجاع',
                value: formatVisitationClock(config.returnTime),
            });
            break;
        }
    }

    return lines;
}

/** تاريخ إرجاع الطفل بعد المبيت — null إذا ليس وضع مبيت */
export function computeVisitationSessionReturnYmd(
    config: VisitationScheduleConfig,
    pickupYmd: string,
): string | null {
    if (config.decisionMode !== 'viewing_pickup_sleepover') return null;
    const nights = Math.max(1, Number(config.sleepoverNights) || 1);
    return addCalendarDaysToYmd(pickupYmd, nights);
}

export type VisitationAppointmentSummary = {
    mode: VisitationDecisionMode;
    location: string;
    pickupTime: string;
    endTime?: string;
    returnDateYmd?: string | null;
    returnTime?: string;
    nightsLabel?: string;
};

/** ملخص مدمج لعرض بطاقة الموعد دون ازدحام */
export function summarizeVisitationAppointment(
    config: VisitationScheduleConfig,
    sessionDateYmd: string,
): VisitationAppointmentSummary {
    const location = String(config.location || '').trim() || '—';
    const pickupTime = formatVisitationClock(config.startTime);
    const base: VisitationAppointmentSummary = {
        mode: config.decisionMode,
        location,
        pickupTime,
    };

    if (config.decisionMode === 'viewing_only') {
        return {
            ...base,
            endTime: formatVisitationClock(config.endTime),
        };
    }
    if (config.decisionMode === 'viewing_pickup') {
        return {
            ...base,
            endTime: formatVisitationClock(config.endTime),
        };
    }

    const nights = Math.max(1, Number(config.sleepoverNights) || 1);
    return {
        ...base,
        returnDateYmd: computeVisitationSessionReturnYmd(config, sessionDateYmd),
        returnTime: formatVisitationClock(config.returnTime),
        nightsLabel: nights === 1 ? 'ليلة واحدة' : `${nights} ليالي`,
    };
}

/** أول تاريخ ≥ executionStartDate يطابق أيام الأسبوع وترتيب أسابيع الشهر */
export function resolveFirstMatchingAppointmentDate(
    executionStartDate: string,
    weekDays: number[],
    monthWeeks: number[],
    maxScanDays = 366
): string | null {
    const start = parseYmdToLocalDate(executionStartDate);
    if (!start) return null;
    const wdSet = new Set(weekDays.filter((n) => n >= 0 && n <= 6));
    const mwSet = new Set(monthWeeks.filter((n) => n >= 1 && n <= 4));
    if (wdSet.size === 0 || mwSet.size === 0) return null;

    const cursor = new Date(start);
    for (let i = 0; i < maxScanDays; i++) {
        if (wdSet.has(cursor.getDay()) && mwSet.has(weekOfMonthFromDate(cursor))) {
            return formatYmdLocal(cursor);
        }
        cursor.setDate(cursor.getDate() + 1);
    }
    return null;
}

export function formatSmartFirstAppointmentMessage(firstYmd: string): string {
    return `النظام الذكي: بناءً على محدداتك، أول موعد فعلي سيكون بتاريخ: ${formatDateLongAr(firstYmd)}.`;
}

function daysUntilYmd(fromYmd: string, toYmd: string): number {
    const a = parseYmdToLocalDate(fromYmd);
    const b = parseYmdToLocalDate(toYmd);
    if (!a || !b) return 0;
    return Math.max(0, Math.round((b.getTime() - a.getTime()) / 86_400_000));
}

export function formatCountdownAr(fromYmd: string, sessionYmd: string): string {
    const days = daysUntilYmd(fromYmd, sessionYmd);
    if (days === 0) return 'اليوم هو الموعد القادم';
    if (days === 1) return 'متبقي يوم واحد للموعد القادم';
    return `متبقي ${days} أيام للموعد القادم`;
}

export function endOfCalendarMonth(d: Date): Date {
    return new Date(d.getFullYear(), d.getMonth() + 1, 0);
}

export function startOfCalendarMonthFromYmd(ymd: string): Date | null {
    const d = parseYmdToLocalDate(ymd);
    if (!d) return null;
    return new Date(d.getFullYear(), d.getMonth(), 1);
}

export function formatVisitationSessionDateAr(session: VisitationSession): string {
    const d = parseYmdToLocalDate(session.date);
    if (!d) return session.date;
    return `${session.dayLabel} ${d.getDate()}/${d.getMonth() + 1}/${d.getFullYear()}`;
}

