            expect([1, 3]).toContain(Math.ceil(d.getDate() / 7));
            expect(s.date >= '2026-06-04').toBe(true);
            expect(d.getMonth()).toBe(5);
            expect(d.getFullYear()).toBe(2026);
        }
    });

