                icFirstInstance({ lastJudgmentType: INTERPLEADER_JUDGMENT_THIRD_FULL }),
                icAppealRoll({
                    parties: [
                        { ...IC_PLAINTIFF, role: 'المستأنف (المدعي)', isClient: true, side: 'right' },
                        {
                            ...IC_INTERPLEADER,
