        it('حقوق المصلحة: مدعى عليه ينتظر؛ مدعي واختصامي يطعنان', () => {
            expect(
                resolveInterpleaderHadoriAppealRights(INTERPLEADER_JUDGMENT_BOTH_DISMISSED, 'defendant')
                    .action,
            ).toBe('wait_opponent');
            expect(
                resolveInterpleaderHadoriAppealRights(INTERPLEADER_JUDGMENT_BOTH_DISMISSED, 'plaintiff')
                    .action,
            ).toBe('self_appeal');
            expect(
                resolveInterpleaderHadoriAppealRights(INTERPLEADER_JUDGMENT_BOTH_DISMISSED, 'interpleader')
                    .action,
            ).toBe('self_appeal');
            expect(isInterpleaderRequestDismissed(INTERPLEADER_JUDGMENT_BOTH_DISMISSED)).toBe(true);
        });

        it('وضع interpleader_appellant عندما الموكل اختصامي خاسر', () => {
            expect(
                resolveAppealDossierMode(
                    INTERPLEADER_JUDGMENT_BOTH_DISMISSED,
                    IC_PARTIES.map((p) => (p.id === 5 ? { ...p, isClient: true } : p)),
                ),
            ).toBe('interpleader_appellant');
        });

        it('لا اعتراض غيابي عند تفريد حضور كامل — الفلتر لا يُبقي أحداً للاعتراض', () => {
            expect(
                filterAppellantPartiesByChallengeMethod(IC_PARTIES, {
                    appealType: 'اعتراض على الحكم الغيابي',
                    dispositions: IC_ALL_PRESENT,
                }),
            ).toEqual([]);
        });

        it('انعدام الاستئخار: لا غيابي → لا اعتراض قائم → لا عرض 172', () => {
            const stages = [
                icFirstInstance({
                    lastJudgmentType: INTERPLEADER_JUDGMENT_BOTH_DISMISSED,
                    judgmentForm: 'حضوري',
                    partyJudgmentDispositions: IC_ALL_PRESENT,
                }),
                icAppealRoll(),
            ];
            expect(isGhayabiObjectionPending({ stages })).toBe(false);
            expect(
                canOfferArt172AppealStay({
                    currentStage: stages[1],
                    stages,
                    parentIntegrity: 'indivisible',
                }),
            ).toBe(false);
        });
    });

    describe('مصلحة الطعن', () => {
        it('فلتر المصلحة يُبقي المدعي والاختصامي ويسقط المدعى عليهم الكاسبين', () => {
            const eligible = filterAppellantsByAppealInterest(
                filterAppellantPartiesByChallengeMethod(IC_PARTIES, {
                    appealType: 'استئناف',
                    dispositions: IC_ALL_PRESENT,
                }),
                {
                    appealType: 'استئناف',
                    judgmentType: INTERPLEADER_JUDGMENT_BOTH_DISMISSED,
                },
            );
            expect(eligible.map((p) => p.id).sort()).toEqual([1, 5]);
        });
    });

    describe('حدود S3', () => {
        it('fixtures بلا operative — إطفاء الكاسب عبر operative لا عبر CaseStage.EXEMPT', () => {
            const row = IC_ALL_PRESENT[0] as Record<string, unknown>;
            expect(row.operative).toBeUndefined();
            expect(row.released).toBeUndefined();
            const fi = icFirstInstance({
                partyJudgmentDispositions: IC_ALL_PRESENT,
            });
            expect(fi.status).not.toBe('EXEMPT');
        });
    });
});

/**
 * محاكاة سيناريو 4: حكم مركّب (إلزام البعض / رد بحق البعض) بعد فك التجميد.
 */
import { describe, expect, it } from 'vitest';
import { filterAppellantPartiesByChallengeMethod } from '@/app/domain/lawsuit/challengeAppellantEligibility';
import {
    canOfferArt172AppealStay,
    isGhayabiObjectionPending,
} from '@/app/components/lawyer/smart-modal/smartFile/art172AppealStay';
import { filterAppellantsByAppealInterest } from '@/app/components/lawyer/smart-modal/smartFile/appealInterestEligibility';
import {
    INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL,
    resolveInterpleaderHadoriAppealRights,
} from '@/app/components/lawyer/smart-modal/smartFile/interpleaderJudgmentEngine';
import {
    attachPartyChallengeLanes,
    LANE_STATE_WAIVED,
} from '@/app/domain/lawsuit/partyChallengeLanes';
import {
    coerceJudgmentTypeForReleasedOperatives,
    hasAnyReleasedDisposition,
} from '@/app/domain/lawsuit/partyJudgmentDisposition';
import {
    IC_D1,
    IC_PARTIES,
    IC_PLAINTIFF,
    IC_S4_MIXED_PRESENCE,
    icAppealRoll,
    icFirstInstance,
    icObjectionPending,
} from './interestContractFixtures';

describe('عقد المصلحة S4 — مركّب bound|released', () => {
    it('حقوق جزئية: المحرك يعطي self_appeal للاختصام الجزئي (مسار اختصام مستقل)', () => {
        expect(
            resolveInterpleaderHadoriAppealRights(INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL, 'plaintiff')
                .action,
        ).toBe('self_appeal');
        expect(
            resolveInterpleaderHadoriAppealRights(INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL, 'defendant')
                .action,
        ).toBe('self_appeal');
        expect(
            resolveInterpleaderHadoriAppealRights(INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL, 'interpleader')
                .action,
        ).toBe('self_appeal');
    });

    it('أي released يفرض رد جزئي حتى لو اختير إجابة كاملة', () => {
        expect(hasAnyReleasedDisposition(IC_S4_MIXED_PRESENCE)).toBe(true);
        expect(
            coerceJudgmentTypeForReleasedOperatives('إجابة الدعوى بالكامل', IC_S4_MIXED_PRESENCE),
        ).toBe('رد الدعوى جزئياً');
    });

    it('فلتر الحضور يسقط المبرَّأ (2) ويبقي الحاضر والغائب الملزَمين + الاختصامي', () => {
        expect(
            filterAppellantPartiesByChallengeMethod(IC_PARTIES, {
                appealType: 'استئناف',
                dispositions: IC_S4_MIXED_PRESENCE,
            })
                .map((p) => p.id)
                .sort(),
        ).toEqual([3, 4, 5]);
        expect(
            filterAppellantPartiesByChallengeMethod(IC_PARTIES, {
                appealType: 'اعتراض على الحكم الغيابي',
                dispositions: IC_S4_MIXED_PRESENCE,
            }).map((p) => p.id),
        ).toEqual([4]);
    });

    it('مصلحة الاستئناف: المبرَّأ لا يطعن؛ المدعي الموكل يُضم عند وجود رد فردي', () => {
        const partiesWithClientPlaintiff = IC_PARTIES.map((p) =>
            p.id === IC_PLAINTIFF.id ? { ...p, isClient: true } : p,
        );
        const byPresence = filterAppellantPartiesByChallengeMethod(partiesWithClientPlaintiff, {
            appealType: 'استئناف',
            dispositions: IC_S4_MIXED_PRESENCE,
        });
        expect(byPresence.map((p) => Number(p.id)).sort()).toEqual([1, 3, 4, 5]);

        const byInterest = filterAppellantsByAppealInterest(byPresence, {
            appealType: 'استئناف',
            judgmentType: 'رد الدعوى جزئياً',
            dispositions: IC_S4_MIXED_PRESENCE,
        });
        expect(byInterest.map((p) => Number(p.id)).sort()).toEqual([1, 3, 4, 5]);
        expect(byInterest.some((p) => Number(p.id) === Number(IC_D1.id))).toBe(false);
    });

    it('بطاقة المبرَّأ waived بلا مهلة', () => {
        const stage = attachPartyChallengeLanes(
            icFirstInstance({
                lastJudgmentType: 'رد الدعوى جزئياً',
                partyJudgmentDispositions: IC_S4_MIXED_PRESENCE,
            }),
            { dispositions: IC_S4_MIXED_PRESENCE, judgmentDate: '2026-01-10' },
        );
        const releasedLane = stage.partyChallengeLanes?.find((l) => l.partyId === '2');
        expect(releasedLane?.laneState).toBe(LANE_STATE_WAIVED);
        expect(releasedLane?.appealDeadline).toBeNull();
        expect(releasedLane?.objectionDeadline).toBeNull();
    });

    it('استئخار يعمل بوجود غيابي ملزَم + اعتراض — المبرَّأ لا يلغي م/172', () => {
        const stages = [
            icFirstInstance({
                lastJudgmentType: INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL,
                partyJudgmentDispositions: IC_S4_MIXED_PRESENCE,
            }),
            icAppealRoll(),
            icObjectionPending(),
        ];
        expect(isGhayabiObjectionPending({ stages })).toBe(true);
        expect(
            canOfferArt172AppealStay({
                currentStage: stages[1],
                stages,
                parentIntegrity: 'indivisible',
            }),
        ).toBe(true);
    });

    it('EXEMPT على CaseStage ما زال مرفوضاً — الإطفاء عبر operative فقط', () => {
        const fi = icFirstInstance({
            lastJudgmentType: INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL,
            partyJudgmentDispositions: IC_S4_MIXED_PRESENCE,
        });
        expect(fi.status).not.toBe('EXEMPT');
        expect(String(fi.status)).not.toMatch(/exempt/i);
    });
});

/**
 * مصفوفة شاملة: دخول الشخص الثالث الاختصامي × كل نتائج الحكم × كل المراكز.
 * محاكاة مقابل الـAPIs الإنتاجية — توثيق السلوك والتأثير على الطعن/الاستئخار/الاستقلال.
 */
import { describe, expect, it } from 'vitest';
import { filterAppellantPartiesByChallengeMethod } from '@/app/domain/lawsuit/challengeAppellantEligibility';
import { shouldSpawnIndependentChallengeDossier } from '@/app/domain/lawsuit/independentChallengeDossier';
import { listJudgmentDispositionDefendants } from '@/app/domain/lawsuit/partyJudgmentDisposition';
import {
    canOfferArt172AppealStay,
    isGhayabiObjectionPending,
} from '@/app/components/lawyer/smart-modal/smartFile/art172AppealStay';
import {
    filterAppellantsByAppealInterest,
    partyHasMeritAppealInterest,
    resolvePartyAppealInterestBucket,
} from '@/app/components/lawyer/smart-modal/smartFile/appealInterestEligibility';
import {
    isInterpleaderRequestAnswered,
    isInterpleaderRequestDismissed,
    resolveAppealDossierMode,
} from '@/app/components/lawyer/smart-modal/smartFile/interpleaderAppealEngine';
import {
    INTERPLEADER_JUDGMENT_BOTH_DISMISSED,
    INTERPLEADER_JUDGMENT_FORMAL_NULLITY,
    INTERPLEADER_JUDGMENT_PLAINTIFF_FULL,
    INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL,
    INTERPLEADER_JUDGMENT_THIRD_FULL,
    INTERPLEADER_JUDGMENT_THIRD_PARTIAL,
    interpleaderClientAwaitingOpponentAppeal,
    interpleaderOriginalClaimOutcome,
    resolveInterpleaderHadoriAppealRights,
    type LawyerJudgmentBucket,
} from '@/app/components/lawyer/smart-modal/smartFile/interpleaderJudgmentEngine';
import {
    IC_MIXED_D3_GHIABI,
    IC_PARTIES,
    IC_ALL_PRESENT,
    icAppealRoll,
    icFirstInstance,
    icObjectionPending,
} from './interestContractFixtures';

const BUCKETS: LawyerJudgmentBucket[] = ['plaintiff', 'defendant', 'interpleader'];

type Action = 'wait_opponent' | 'self_appeal' | 'archive_void' | 'both_paths' | 'finalize_non_merit';

/** العقد التشغيلي الحالي كما يُنفَّذ في المحرك (مصدر الحقيقة للاختبار). */
const RIGHTS_MATRIX: Record<string, Record<LawyerJudgmentBucket, Action>> = {
    [INTERPLEADER_JUDGMENT_PLAINTIFF_FULL]: {
        plaintiff: 'wait_opponent',
        defendant: 'self_appeal',
        interpleader: 'self_appeal',
    },
    [INTERPLEADER_JUDGMENT_THIRD_FULL]: {
        plaintiff: 'self_appeal',
        defendant: 'wait_opponent',
        interpleader: 'wait_opponent',
    },
    [INTERPLEADER_JUDGMENT_BOTH_DISMISSED]: {
        plaintiff: 'self_appeal',
        defendant: 'wait_opponent',
        interpleader: 'self_appeal',
    },
    [INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL]: {
        plaintiff: 'self_appeal',
        defendant: 'self_appeal',
        interpleader: 'self_appeal',
    },
    [INTERPLEADER_JUDGMENT_THIRD_PARTIAL]: {
        plaintiff: 'self_appeal',
        defendant: 'wait_opponent',
        interpleader: 'self_appeal',
    },
    [INTERPLEADER_JUDGMENT_FORMAL_NULLITY]: {
        plaintiff: 'archive_void',
        defendant: 'archive_void',
        interpleader: 'archive_void',
    },
};

const ORIGINAL_CLAIM: Record<string, 'full_win' | 'partial_win' | 'full_loss' | 'neutral'> = {
    [INTERPLEADER_JUDGMENT_PLAINTIFF_FULL]: 'full_win',
    [INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL]: 'partial_win',
    [INTERPLEADER_JUDGMENT_THIRD_FULL]: 'full_loss',
    [INTERPLEADER_JUDGMENT_THIRD_PARTIAL]: 'full_loss',
    [INTERPLEADER_JUDGMENT_BOTH_DISMISSED]: 'full_loss',
    [INTERPLEADER_JUDGMENT_FORMAL_NULLITY]: 'neutral',
};

function markClient(bucket: LawyerJudgmentBucket) {
    const id = bucket === 'plaintiff' ? 1 : bucket === 'defendant' ? 2 : 5;
    return IC_PARTIES.map((p) => ({ ...p, isClient: p.id === id }));
}

describe('مصفوفة شاملة — شخص ثالث اختصامي × النتائج × المراكز', () => {
    it('ثابت بنيوي: الاختصامي خارج تفريد الحضور/الغياب دائماً', () => {
        const defendants = listJudgmentDispositionDefendants(IC_PARTIES);
        expect(defendants.map((p) => p.id).sort()).toEqual([2, 3, 4]);
        expect(resolvePartyAppealInterestBucket(IC_PARTIES[4]!)).toBe('interpleader');
    });

    it.each(Object.keys(RIGHTS_MATRIX))(
        'حقوق الطعن لكل مركز — %s',
        (judgmentType) => {
            for (const bucket of BUCKETS) {
                const expected = RIGHTS_MATRIX[judgmentType]![bucket]!;
                expect(
                    resolveInterpleaderHadoriAppealRights(judgmentType, bucket).action,
                    `${judgmentType} / ${bucket}`,
                ).toBe(expected);
                const party = IC_PARTIES.find((p) =>
                    bucket === 'plaintiff'
                        ? p.id === 1
                        : bucket === 'defendant'
                          ? p.id === 2
                          : p.id === 5,
                )!;
                expect(
                    partyHasMeritAppealInterest({ judgmentType, party }),
                    `interest ${judgmentType} / ${bucket}`,
                ).toBe(expected === 'self_appeal' || expected === 'both_paths');
            }
            expect(interpleaderOriginalClaimOutcome(judgmentType)).toBe(ORIGINAL_CLAIM[judgmentType]);
        },
    );

    it('وضع إضبارة الطعن حسب الموكل × النتيجة', () => {
        const cases: Array<{
            type: string;
            bucket: LawyerJudgmentBucket;
            mode: 'standard' | 'interpleader_appellant' | 'against_interpleader';
        }> = [
            { type: INTERPLEADER_JUDGMENT_PLAINTIFF_FULL, bucket: 'interpleader', mode: 'interpleader_appellant' },
            { type: INTERPLEADER_JUDGMENT_PLAINTIFF_FULL, bucket: 'plaintiff', mode: 'standard' },
            { type: INTERPLEADER_JUDGMENT_PLAINTIFF_FULL, bucket: 'defendant', mode: 'standard' },
            { type: INTERPLEADER_JUDGMENT_BOTH_DISMISSED, bucket: 'interpleader', mode: 'interpleader_appellant' },
            { type: INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL, bucket: 'interpleader', mode: 'interpleader_appellant' },
            { type: INTERPLEADER_JUDGMENT_THIRD_FULL, bucket: 'plaintiff', mode: 'against_interpleader' },
            { type: INTERPLEADER_JUDGMENT_THIRD_FULL, bucket: 'defendant', mode: 'against_interpleader' },
            { type: INTERPLEADER_JUDGMENT_THIRD_FULL, bucket: 'interpleader', mode: 'standard' },
            { type: INTERPLEADER_JUDGMENT_THIRD_PARTIAL, bucket: 'plaintiff', mode: 'against_interpleader' },
            { type: INTERPLEADER_JUDGMENT_THIRD_PARTIAL, bucket: 'interpleader', mode: 'standard' },
            { type: INTERPLEADER_JUDGMENT_FORMAL_NULLITY, bucket: 'interpleader', mode: 'standard' },
            { type: INTERPLEADER_JUDGMENT_FORMAL_NULLITY, bucket: 'plaintiff', mode: 'standard' },
        ];
        for (const row of cases) {
            expect(
                resolveAppealDossierMode(row.type, markClient(row.bucket)),
                `${row.type} / ${row.bucket}`,
            ).toBe(row.mode);
        }
        expect(isInterpleaderRequestAnswered(INTERPLEADER_JUDGMENT_THIRD_FULL)).toBe(true);
        expect(isInterpleaderRequestDismissed(INTERPLEADER_JUDGMENT_PLAINTIFF_FULL)).toBe(true);
        expect(isInterpleaderRequestDismissed(INTERPLEADER_JUDGMENT_FORMAL_NULLITY)).toBe(false);
    });

    it('فلتر الحضور + المصلحة: من يظهر في قائمة الاستئناف المختلط لكل نتيجة', () => {
        const byPresence = filterAppellantPartiesByChallengeMethod(IC_PARTIES, {
            appealType: 'استئناف',
            dispositions: IC_MIXED_D3_GHIABI,
        });
        // حاضرون 2,3 + غائب ملزَم 4 + اختصامي 5
        expect(byPresence.map((p) => p.id).sort()).toEqual([2, 3, 4, 5]);

        const expectIds = (type: string, ids: number[]) => {
            expect(
                filterAppellantsByAppealInterest(byPresence, {
                    appealType: 'استئناف',
                    judgmentType: type,
                })
                    .map((p) => p.id)
                    .sort(),
            ).toEqual(ids);
        };

        expectIds(INTERPLEADER_JUDGMENT_PLAINTIFF_FULL, [2, 3, 4, 5]);
        expectIds(INTERPLEADER_JUDGMENT_THIRD_FULL, []); // الكاسبون في القائمة يسقطون
        expectIds(INTERPLEADER_JUDGMENT_BOTH_DISMISSED, [5]); // المدعى عليهم كاسبون؛ الاختصامي خاسر
        expectIds(INTERPLEADER_JUDGMENT_PLAINTIFF_PARTIAL, [2, 3, 4, 5]);
        expectIds(INTERPLEADER_JUDGMENT_THIRD_PARTIAL, [5]); // جزئي للاختصامي ⇒ canAppeal
        expectIds(INTERPLEADER_JUDGMENT_FORMAL_NULLITY, []);

        // المدعي يُمرَّر من تخطيط against_interpleader لا من فلتر dispositions
        expect(
            filterAppellantsByAppealInterest([IC_PARTIES[0]!], {
                appealType: 'استئناف',
                judgmentType: INTERPLEADER_JUDGMENT_THIRD_FULL,
            }).map((p) => p.id),
        ).toEqual([1]);
    });

    it('مسار الاعتراض: الاختصامي لا يدخل؛ الغائب فقط؛ لا يُصفّى بمصلحة الحكم البدائي', () => {
        expect(
            filterAppellantPartiesByChallengeMethod(IC_PARTIES, {
                appealType: 'اعتراض على الحكم الغيابي',
                dispositions: IC_MIXED_D3_GHIABI,
            }).map((p) => p.id),
        ).toEqual([4]);
        const objectionParties = [
            { id: 1, role: 'المعترض عليه بالحكم الغيابي (المدعي)' },
            { id: 4, role: 'المعترض على الحكم الغيابي (المدعى عليه)' },
        ];
        expect(
            filterAppellantsByAppealInterest(objectionParties, {
                appealType: 'استئناف',
                judgmentType: INTERPLEADER_JUDGMENT_PLAINTIFF_FULL,
            }),
        ).toEqual(objectionParties);
    });

    it('استئخار 172: مع غيابي+اعتراض يعمل؛ مع حضور كامل لا يعمل — لكل نتائج الحكم', () => {
        for (const type of Object.keys(RIGHTS_MATRIX)) {
            const withObj = [
                icFirstInstance({ lastJudgmentType: type }),
                icAppealRoll(),
                icObjectionPending(),
            ];
            expect(isGhayabiObjectionPending({ stages: withObj }), type).toBe(true);
            expect(
                canOfferArt172AppealStay({
                    currentStage: withObj[1],
                    stages: withObj,
                    parentIntegrity: 'indivisible',
                }),
                type,
            ).toBe(true);

            const allPresent = [
                icFirstInstance({
                    lastJudgmentType: type,
                    judgmentForm: 'حضوري',
                    partyJudgmentDispositions: IC_ALL_PRESENT,
                }),
                icAppealRoll(),
            ];
            expect(isGhayabiObjectionPending({ stages: allPresent }), `${type} present`).toBe(false);
            expect(
                canOfferArt172AppealStay({
                    currentStage: allPresent[1],
                    stages: allPresent,
                    parentIntegrity: 'indivisible',
                }),
                `${type} present stay`,
            ).toBe(false);
        }
    });

    it('استقلال الإضبارة: استئناف لاحق من الاعتراض ينشق مع رول استئناف مفتوح (إبطال أو تأييد)', () => {
        for (const type of [
            INTERPLEADER_JUDGMENT_PLAINTIFF_FULL,
            INTERPLEADER_JUDGMENT_THIRD_FULL,
            INTERPLEADER_JUDGMENT_BOTH_DISMISSED,
        ]) {
            const voidStages = [
                icFirstInstance({ lastJudgmentType: type }),
                icAppealRoll({ isSuspended: true }),
                icObjectionPending({
                    finalDecision: 'تعديل الحكم الغيابي — يحق لموكلك الطعن',
                    isPleadingsClosed: true,
                }),
            ];
            expect(
                shouldSpawnIndependentChallengeDossier({
                    stages: voidStages,
                    sourceStage: voidStages[2],
                    appealType: 'استئناف',
                }),
            ).toBe(true);

            const upholdStages = [
                icFirstInstance({ lastJudgmentType: type }),
                icAppealRoll(),
                icObjectionPending({
                    finalDecision: 'تأييد الحكم الغيابي — بانتظار طعن المعترض',
                    isPleadingsClosed: true,
                }),
            ];
            /** رول استئناف مفتوح + مصدر ≠ الرول ⇒ إضبارة مستقلة (سياسة الطعن اللاحق) */
            expect(
                shouldSpawnIndependentChallengeDossier({
                    stages: upholdStages,
                    sourceStage: upholdStages[2],
                    appealType: 'استئناف',
                }),
            ).toBe(true);
        }
    });

    it('awaitingOpponent: الكاسب ينتظر فقط (full_win في محرك النتيجة)', () => {
        expect(interpleaderClientAwaitingOpponentAppeal(INTERPLEADER_JUDGMENT_PLAINTIFF_FULL, 'plaintiff')).toBe(
            true,
        );
        expect(interpleaderClientAwaitingOpponentAppeal(INTERPLEADER_JUDGMENT_THIRD_FULL, 'interpleader')).toBe(
            true,
        );
        expect(interpleaderClientAwaitingOpponentAppeal(INTERPLEADER_JUDGMENT_THIRD_FULL, 'defendant')).toBe(
            true,
        );
        expect(interpleaderClientAwaitingOpponentAppeal(INTERPLEADER_JUDGMENT_BOTH_DISMISSED, 'defendant')).toBe(
            true,
        );
        expect(interpleaderClientAwaitingOpponentAppeal(INTERPLEADER_JUDGMENT_PLAINTIFF_FULL, 'interpleader')).toBe(
            false,
        );
        expect(interpleaderClientAwaitingOpponentAppeal(INTERPLEADER_JUDGMENT_FORMAL_NULLITY, 'plaintiff')).toBe(false);
    });
});

import { describe, expect, it } from 'vitest';
import {
    isPoorerLawsuitActiveList,
    mergeRicherLawsuitActive,
    mergeRicherLawsuitActiveRespectingHeldIds,
} from '../lawsuitActiveDurability';
import type { FileData } from '../lawsuitFileTypes';

const file = (id: number): FileData => ({
    id,
    type: 'lawsuit',
    status: 'active',
    caseNo: `2026/ب/${id}`,
    court: 'أحوال',
    parties: [],
    history: [],
    notes: [],
    images: [],
    date: '2026-01-01',
});

describe('lawsuitActiveDurability', () => {
    it('detects poorer list that drops ids', () => {
        expect(isPoorerLawsuitActiveList([file(2)], [file(1), file(2)])).toBe(true);
        expect(isPoorerLawsuitActiveList([], [file(1)])).toBe(true);
        expect(isPoorerLawsuitActiveList([file(1), file(2)], [file(1)])).toBe(false);
        expect(isPoorerLawsuitActiveList([file(1)], [file(1)])).toBe(false);
    });

    it('merge keeps existing ids when create list is partial', () => {
        const merged = mergeRicherLawsuitActive([file(3)], [file(1), file(2)]);
        expect(merged.map((f) => String(f.id)).sort()).toEqual(['1', '2', '3']);
        expect(merged[0]?.id).toBe(3);
    });

    it('لا يعيد إحياء معرّف موجود في السلة عند دمج قرص أغنى', () => {
        const merged = mergeRicherLawsuitActiveRespectingHeldIds(
            [file(2)],
            [file(1), file(2)],
            new Set(['1']),
        );
        expect(merged.map((f) => String(f.id))).toEqual(['2']);
    });
});

import { beforeEach, describe, expect, it } from 'vitest';
import fs from 'fs';
import path from 'path';
import type { FileData } from '../lawsuitFileTypes';
import { persistLawsuitActiveBundle } from '@/app/domain/lawsuit/lawsuitDurabilityGate';
import { stagePendingLawsuitCreate, clearLawsuitPendingCreatesForTests } from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import { persistLawsuitActiveSegment } from '@/app/domain/lawsuit/lawsuitSegmentStorage';
import { LAWSUIT_WRITE_JOURNAL_KEY } from '@/app/domain/lawsuit/lawsuitWriteJournal';
import SecureStoreService from '@/app/services/SecureStoreService';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import { emptyLawsuitLifecycleIndex } from '@/app/domain/lawsuit/lawsuitLifecycleIndex';

const file = (id: number): FileData =>
    ({
        id,
        type: 'lawsuit',
        status: 'active',
        caseNo: `2026/${id}`,
        court: 'بداءة',
        parties: [],
        history: [],
        notes: [],
        images: [],
        date: '2026-01-01',
    }) as FileData;

describe('lawsuitDurabilityGate', () => {
    beforeEach(() => {
        clearLawsuitPendingCreatesForTests();
        try {
            SecureStoreService.deleteItemSync(LAWSUIT_WRITE_JOURNAL_KEY);
        } catch {
            /* ignore */
        }
        localStorage.removeItem(LAWSUIT_WRITE_JOURNAL_KEY);
        try {
            SecureStoreService.deleteItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        } catch {
            /* ignore */
        }
    });
    it('persistLawsuitActiveBundle is the single write funnel for active+index+mirror', () => {
        const gate = fs.readFileSync(
            path.join(process.cwd(), 'src/app/domain/lawsuit/lawsuitDurabilityGate.ts'),
            'utf8',
        );
        expect(gate).toContain('persistLawsuitActiveBundle');
        expect(gate).toContain('persistLawsuitActiveSegment');
        expect(gate).toContain('persistLawsuitLifecycleIndex');
        expect(gate).toContain('mirrorLawsuitSegmentsSafe');
        expect(gate).toContain('stageLawsuitJournalRecords');
        expect(gate).not.toContain('pruneVerifiedLawsuitJournalEntries');
        expect(gate).toContain('lawsuitSegmentPersist');
        expect(gate).not.toContain("from '@/app/domain/lawsuit/lawsuitSegmentStorage'");
        expect(typeof persistLawsuitActiveBundle).toBe('function');
    });

    it('repository and hooks route autosave through the gate', () => {
        const repo = fs.readFileSync(
            path.join(process.cwd(), 'src/app/domain/lawsuit/lawsuitFilesRepository.ts'),
            'utf8',
        );
        const hooks = fs.readFileSync(
            path.join(process.cwd(), 'src/app/hooks/useLawsuitFilesState.ts'),
            'utf8',
        );
        const mutations = fs.readFileSync(
            path.join(process.cwd(), 'src/app/domain/lawsuit/lawsuitFilesSegmentMutations.ts'),
            'utf8',
        );
        expect(repo).toContain('persistLawsuitActiveBundle');
        expect(hooks).toContain('persistLawsuitActiveBundle');
        expect(mutations).toContain('persistLawsuitActiveBundle');
    });

    it('allowShrink still merges pending personal create into the written active list', () => {
        persistLawsuitActiveSegment([file(1)]);
        stagePendingLawsuitCreate({
            ...file(77),
            lawsuitJurisdiction: 'personal',
        } as FileData);

        persistLawsuitActiveBundle({
            active: [file(1)],
            index: emptyLawsuitLifecycleIndex(),
            options: { allowShrink: true },
        });

        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        const ids = parsed.map((r) => r.id).sort((a, b) => a - b);
        expect(ids).toEqual([1, 77]);
    });

    it('poorer bundle does not shrink a richer active segment', () => {
        persistLawsuitActiveSegment([file(1), file(2)]);
        persistLawsuitActiveBundle({
            active: [file(1)],
            index: emptyLawsuitLifecycleIndex(),
        });
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        expect(parsed.map((r) => r.id).sort((a, b) => a - b)).toEqual([1, 2]);
    });

    it('allowShrink + trash duplicate of every active id does not wipe active to []', () => {
        const LAWSUIT_FILES_TRASH_KEY = 'lawyer_files_trash';
        persistLawsuitActiveSegment([file(1), file(2)]);
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_TRASH_KEY,
            JSON.stringify([
                { ...file(1), status: 'deleted', deletedAt: 1 },
                { ...file(2), status: 'deleted', deletedAt: 1 },
            ]),
        );
        const result = persistLawsuitActiveBundle({
            active: [file(1), file(2)],
            index: emptyLawsuitLifecycleIndex(),
            trash: [
                { ...file(1), status: 'deleted', deletedAt: 1 } as FileData,
                { ...file(2), status: 'deleted', deletedAt: 1 } as FileData,
            ],
            options: { allowShrink: true },
        });
        expect(result.ok).toBe(true);
        expect(result.active.map((r) => Number(r.id)).sort((a, b) => a - b)).toEqual([1, 2]);
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        expect(parsed.map((r) => r.id).sort((a, b) => a - b)).toEqual([1, 2]);
    });

    it('allowShrink without trash/archive proof refuses emptying richer disk', () => {
        persistLawsuitActiveSegment([file(1), file(2), file(3)]);
        const result = persistLawsuitActiveBundle({
            active: [],
            index: emptyLawsuitLifecycleIndex(),
            trash: [],
            archived: [],
            options: { allowShrink: true, allowVerifiedEmpty: true },
        });
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        expect(parsed.map((r) => r.id).sort((a, b) => a - b)).toEqual([1, 2, 3]);
        expect(result.active.map((r) => Number(r.id)).sort((a, b) => a - b)).toEqual([1, 2, 3]);
    });

    it('allowShrink with proven trash move shrinks only the moved id', () => {
        persistLawsuitActiveSegment([file(1), file(2)]);
        const trashed = { ...file(1), status: 'deleted' as const, deletedAt: 1 };
        const result = persistLawsuitActiveBundle({
            active: [file(2)],
            index: emptyLawsuitLifecycleIndex(),
            trash: [trashed],
            options: { allowShrink: true },
        });
        expect(result.ok).toBe(true);
        expect(result.active.map((r) => Number(r.id))).toEqual([2]);
        const raw = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        const parsed = JSON.parse(String(raw)) as Array<{ id: number }>;
        expect(parsed.map((r) => r.id)).toEqual([2]);
    });
});

