            ...emptyLawsuitFileSegments(),
            active: [file(2)],
            trash: [trashed],
            index: {
                v: 1 as const,
                entries: {
                    '1': { status: 'deleted' as const, updatedAt: 1 },
                    '2': { status: 'active' as const, updatedAt: 1 },
                },
                counts: { active: 1, archived: 0, trash: 1 },
            },
        };
        const boot = {
            ...emptyLawsuitFileSegments(),
            active: [file(1), file(2)],
            trash: null,
        };
