describe('recoverLawsuitWorkspaceFromLocalDisk', () => {
    beforeEach(async () => {
        resetLawsuitCommitSchedulerForTests();
        try {
            localStorage.removeItem(LAWSUIT_WRITE_JOURNAL_KEY);
            clearLawsuitPendingCreatesForTests();
        } catch {
            /* ignore */
        }
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        await SecureStoreService.waitForAllPendingPersist();
        SecureStoreService.listKeysSync().forEach((k) => SecureStoreService.deleteItemSync(k));
        vi.clearAllMocks();
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([]);
        const { listDossierBackups } = await import(
            '@/app/services/dossierPersistence/dossierBackupStore'
        );
        vi.mocked(listDossierBackups).mockResolvedValue([]);
    });

    it('never throws and reports empty diagnosis', async () => {
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk();
        expect(result.ok).toBe(false);
        expect(result.source).toBe('none');
        expect(result.message.length).toBeGreaterThan(10);
    });

    it('recovers from monolithic when segments empty', async () => {
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([file(42)]);

        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk();
        expect(result.ok).toBe(true);
        expect(['monolithic', 'active']).toContain(result.source);
        expect(result.segments.active.some((f) => String(f.id) === '42')).toBe(true);
    });

    it('لا يستورد المرآة إلى النشط إن وُجدت سلة على القرص', async () => {
        const { loadLawsuitFilesRaw } = await import('@/app/utils/lawsuitFilesStorage');
        const {
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_INDEX_KEY,
            LAWSUIT_FILES_TRASH_KEY,
        } = await import('@/app/services/dossierPersistence/dossierStorageKeys');
        const { buildLawsuitLifecycleIndex } = await import(
            '@/app/domain/lawsuit/lawsuitLifecycleIndex'
        );
        const trashed = { ...file(42), status: 'deleted' as const, deletedAt: 1 };
        SecureStoreService.setItemSync(LAWSUIT_FILES_ACTIVE_KEY, '[]');
        SecureStoreService.setItemSync(LAWSUIT_FILES_TRASH_KEY, JSON.stringify([trashed]));
        SecureStoreService.setItemSync(
            LAWSUIT_FILES_INDEX_KEY,
            JSON.stringify(buildLawsuitLifecycleIndex([], [], [trashed])),
        );
        vi.mocked(loadLawsuitFilesRaw).mockReturnValue([file(42)]);

        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk({ includeCloud: false });
        expect(result.ok).toBe(true);
        expect(result.segments.active.some((f) => String(f.id) === '42')).toBe(false);
        expect(result.segments.trash?.some((f) => String(f.id) === '42')).toBe(true);
    });

    it('recovers from dossier backup list', async () => {
        const { listDossierBackups } = await import(
            '@/app/services/dossierPersistence/dossierBackupStore'
        );
        vi.mocked(listDossierBackups).mockResolvedValue([
            {
                meta: {
                    domain: 'lawsuit',
                    revision: 3,
                    savedAt: new Date().toISOString(),
                    itemCount: 1,
                },
                payload: [file(99)],
            },
        ]);

        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        const result = await recoverLawsuitWorkspaceFromLocalDisk();
        expect(result.ok).toBe(true);
        expect(result.source).toBe('backup');
        expect(result.segments.active.some((f) => String(f.id) === '99')).toBe(true);
    });

    it('includeCloud:false لا يستدعي المزامنة على مسار فتح المخزن', async () => {
        const { performCloudSyncBucket } = await import('@/app/services/cloudSyncEngine');
        const { restoreLastWorkCloudCheckpoint } = await import(
            '@/app/services/cloud/workCloudCheckpoint'
        );
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        await recoverLawsuitWorkspaceFromLocalDisk({
            includeCloud: false,
            fullPersistReady: false,
        });
        expect(performCloudSyncBucket).not.toHaveBeenCalled();
        expect(restoreLastWorkCloudCheckpoint).not.toHaveBeenCalled();
    });

    it('includeCloud الافتراضي يحاول استعادة نقطة العمل قبل مزامنة السلة', async () => {
        const { restoreLastWorkCloudCheckpoint } = await import(
            '@/app/services/cloud/workCloudCheckpoint'
        );
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        await recoverLawsuitWorkspaceFromLocalDisk({ fullPersistReady: false });
        expect(restoreLastWorkCloudCheckpoint).toHaveBeenCalled();
    });

    it('يمحو leftover الدعاوى من localStorage عند الاستعادة', async () => {
        const { LAWSUIT_FILES_STORAGE_KEY } = await import(
            '@/app/services/dossierPersistence/dossierStorageKeys'
        );
        localStorage.setItem(LAWSUIT_FILES_STORAGE_KEY, JSON.stringify([file(7)]));
        const { recoverLawsuitWorkspaceFromLocalDisk } = await import(
            '@/app/domain/lawsuit/lawsuitWorkspaceRecovery'
        );
        await recoverLawsuitWorkspaceFromLocalDisk({ includeCloud: false });
        expect(localStorage.getItem(LAWSUIT_FILES_STORAGE_KEY)).toBeNull();
    });
});

import { beforeEach, describe, expect, it } from 'vitest';
import type { FileData } from '../lawsuitFileTypes';
import {
    LAWSUIT_WRITE_JOURNAL_KEY,
    clearLawsuitWriteJournalForTests,
    hasUnverifiedLawsuitJournal,
    listLawsuitJournalEntries,
    mergeLawsuitJournalInto,
    pruneLawsuitJournalForFileIds,
    stageLawsuitJournalRecords,
} from '../lawsuitWriteJournal';

const file = (id: number): FileData =>
    ({
        id,
        type: 'lawsuit',
        status: 'active',
        caseNo: `j/${id}`,
        court: 'أحوال',
        parties: [],
        history: [],
        notes: [],
        images: [],
        date: '2026-01-01',
    }) as FileData;

describe('lawsuitWriteJournal', () => {
    beforeEach(() => {
        clearLawsuitWriteJournalForTests();
    });

    it('stages and merges journal entries in SecureStore and clears leftover localStorage', () => {
        localStorage.setItem(LAWSUIT_WRITE_JOURNAL_KEY, JSON.stringify([]));
        stageLawsuitJournalRecords([file(5)]);
        expect(hasUnverifiedLawsuitJournal()).toBe(true);
        expect(listLawsuitJournalEntries()).toHaveLength(1);
        expect(localStorage.getItem(LAWSUIT_WRITE_JOURNAL_KEY)).toBeNull();
        const merged = mergeLawsuitJournalInto([file(1)]);
        expect(merged.map((f) => Number(f.id)).sort((a, b) => a - b)).toEqual([1, 5]);
    });

    it('replaces same fileId and prunes after proof', () => {
        stageLawsuitJournalRecords([file(7)]);
        stageLawsuitJournalRecords([{ ...file(7), court: 'محدّث' } as FileData]);
        expect(listLawsuitJournalEntries()).toHaveLength(1);
        expect(listLawsuitJournalEntries()[0]?.file.court).toBe('محدّث');
        pruneLawsuitJournalForFileIds([7]);
        expect(hasUnverifiedLawsuitJournal()).toBe(false);
    });
});

import { describe, expect, it } from 'vitest';
import {
    alignPartyJudgmentDispositions,
    clientDefendantHasGhayabiDisposition,
    isDisputeIndivisible,
    judgmentFormHasGhayabi,
    listJudgmentDispositionDefendants,
    normalizePartyJudgmentDispositions,
    parseDisputeIntegrity,
    resolveJudgmentPresenceWindows,
    seedPartyJudgmentDispositions,
    stampPartyJudgmentOnStage,
    summarizePartyJudgmentForm,
} from '../partyJudgmentDisposition';
import { partitionLawsuitPartiesByRole } from '../lawsuitPartyRole';

const FOUR_DEFENDANTS = [
    { id: 1, name: 'أحمد', role: 'مدعي', isClient: true },
    { id: 2, name: 'سامي', role: 'مدعى عليه', isClient: false },
    { id: 3, name: 'كريم', role: 'مدعى عليه', isClient: false },
    { id: 4, name: 'نادر', role: 'مدعى عليه', isClient: false },
    { id: 5, name: 'هيثم', role: 'مدعى عليه', isClient: false },
];

describe('مصفوفة تعدد الأطراف — صفة الحكم', () => {
    it('يحصي أربعة مدعى عليهم مع مدعيين دون الاختصامي المستقل', () => {
        const listed = listJudgmentDispositionDefendants([
            { id: 10, name: 'مدعي أول', role: 'مدعي', isClient: true },
            { id: 11, name: 'مدعي ثان', role: 'مدعي', isClient: false },
            { id: 2, name: 'سامي', role: 'مدعى عليه' },
            { id: 3, name: 'كريم', role: 'مدعى عليه الثاني' },
            { id: 4, name: 'نادر', role: 'defendant' },
            { id: 5, name: 'هيثم', role: 'مدين', side: 'left' },
            { id: 6, name: 'زيد', role: 'شخص ثالث اختصامي' },
            { id: 7, name: 'هناء', role: 'شخص ثالث انضمامي — جانب المدعى عليه' },
            { id: '', name: 'بلا معرف', role: 'مدعى عليه' },
        ]);
        expect(listed.map((p) => Number(p.id))).toEqual([2, 3, 4, 5, 7]);
    });

    it('يستبعد من ظهر في عمود المدعي والمدعى عليه معاً', () => {
        const { plaintiffs, defendants } = partitionLawsuitPartiesByRole([
            { id: 1, role: 'مدعي' },
            { id: 1, role: 'مدعى عليه' },
            { id: 2, role: 'مدعى عليه' },
        ]);
        expect(plaintiffs.map((p) => p.id)).toEqual([1]);
        expect(defendants.map((p) => p.id)).toEqual([2]);
    });

    it('يلخّص أربعة مدعى عليهم: كل الحضور / كل الغياب / غائب واحد / ثلاثة غائبين', () => {
        const ids = ['2', '3', '4', '5'];
        expect(summarizePartyJudgmentForm(ids.map((partyId) => ({ partyId, form: 'حضوري' as const })))).toBe(
            'حضوري',
        );
        expect(summarizePartyJudgmentForm(ids.map((partyId) => ({ partyId, form: 'غيابي' as const })))).toBe(
            'غيابي',
        );
        expect(
            summarizePartyJudgmentForm([
                { partyId: '2', form: 'حضوري' },
                { partyId: '3', form: 'حضوري' },
                { partyId: '4', form: 'حضوري' },
                { partyId: '5', form: 'غيابي' },
            ]),
        ).toBe('مختلط');
        expect(
            summarizePartyJudgmentForm([
                { partyId: '2', form: 'حضوري' },
                { partyId: '3', form: 'غيابي' },
                { partyId: '4', form: 'بمثابة الحضوري' },
                { partyId: '5', form: 'غيابي' },
            ]),
        ).toBe('مختلط');
        expect(
            summarizePartyJudgmentForm([
                { partyId: '2', form: 'غيابي' },
                { partyId: '3', form: 'غيابي' },
                { partyId: '4', form: 'غيابي' },
                { partyId: '5', form: 'حضوري' },
            ]),
        ).toBe('مختلط');
    });

    it('يوحّد معرف الطرف رقم/نص ويسقط المكرر والمعطوب', () => {
        expect(
            normalizePartyJudgmentDispositions([
                { partyId: 2, form: 'غيابي' },
                { partyId: '2', form: 'حضوري' },
                { partyId: ' 4 ', form: 'حضوري' },
                { partyId: 'x', form: 'مختلط' },
                null,
                'bad',
            ]),
        ).toEqual([
            { partyId: '2', form: 'غيابي', operative: 'bound' },
            { partyId: '4', form: 'حضوري', operative: 'bound' },
        ]);
    });

    it('يملأ الطرف الجديد عند زيادة المدعى عليهم دون محو صفة السابق', () => {
        expect(
            alignPartyJudgmentDispositions(
                FOUR_DEFENDANTS.filter((p) => p.role === 'مدعى عليه'),
                [
                    { partyId: '2', form: 'غيابي' },
                    { partyId: '3', form: 'حضوري' },
                ],
                'حضوري',
            ),
        ).toEqual([
            { partyId: '2', form: 'غيابي', operative: 'bound' },
            { partyId: '3', form: 'حضوري', operative: 'bound' },
            { partyId: '4', form: 'حضوري', operative: 'bound' },
            { partyId: '5', form: 'حضوري', operative: 'bound' },
        ]);
    });

    it('يحذف disposition لطرف خرج من القائمة', () => {
        expect(
            alignPartyJudgmentDispositions(
                [{ id: 2 }, { id: 4 }],
                [
                    { partyId: '2', form: 'غيابي' },
                    { partyId: '3', form: 'غيابي' },
                    { partyId: '4', form: 'حضوري' },
                ],
                'حضوري',
            ),
        ).toEqual([
            { partyId: '2', form: 'غيابي', operative: 'bound' },
            { partyId: '4', form: 'حضوري', operative: 'bound' },
        ]);
    });

    it('الموكل الغائب بين أربعة: يُلتقط فقط إن كان مدعى عليه غائباً', () => {
        const mixed = [
            { partyId: '2', form: 'حضوري' as const },
            { partyId: '3', form: 'غيابي' as const },
            { partyId: '4', form: 'حضوري' as const },
            { partyId: '5', form: 'غيابي' as const },
        ];
        expect(
            clientDefendantHasGhayabiDisposition(
                [
                    { id: 1, role: 'مدعي', isClient: true },
                    { id: 2, role: 'مدعى عليه', isClient: false },
                    { id: 3, role: 'مدعى عليه', isClient: false },
                ],
                mixed,
            ),
        ).toBe(false);
        expect(
            clientDefendantHasGhayabiDisposition(
                [
                    { id: 1, role: 'مدعي', isClient: false },
                    { id: 5, role: 'مدعى عليه', isClient: true },
                ],
                mixed,
            ),
        ).toBe(true);
        expect(
            clientDefendantHasGhayabiDisposition(
                [
                    { id: 2, role: 'مدعى عليه', isClient: true },
                    { id: 5, role: 'مدعى عليه', isClient: true },
                ],
                mixed,
            ),
        ).toBe(true);
        expect(
            clientDefendantHasGhayabiDisposition(
                [{ id: 2, role: 'مدعى عليه', isClient: true }],
                mixed,
            ),
        ).toBe(false);
    });

    it('نوافذ الحضور/الغياب لأربعة أطراف ولملف قديم بلا dispositions', () => {
        expect(
            resolveJudgmentPresenceWindows(
                [
                    { partyId: '2', form: 'حضوري' },
                    { partyId: '3', form: 'غيابي' },
                    { partyId: '4', form: 'غيابي' },
                    { partyId: '5', form: 'حضوري' },
                ],
                'حضوري',
            ),
        ).toEqual({
            hasHadari: true,
            hasGhayabi: true,
            mixed: true,
            summary: 'مختلط',
        });
        expect(resolveJudgmentPresenceWindows([], 'غيابي')).toEqual({
            hasHadari: false,
            hasGhayabi: true,
            mixed: false,
            summary: 'غيابي',
        });
        expect(resolveJudgmentPresenceWindows([], 'مختلط')).toEqual({
            hasHadari: true,
            hasGhayabi: true,
            mixed: true,
            summary: 'مختلط',
        });
        expect(judgmentFormHasGhayabi('حضوري', undefined, [
            { partyId: '5', form: 'غيابي' },
        ])).toBe(true);
        expect(judgmentFormHasGhayabi('مختلط', undefined, [
            { partyId: '2', form: 'حضوري' },
            { partyId: '3', form: 'حضوري' },
        ])).toBe(false);
    });

    it('يقبل تسمية وحدة النزاع بالعربية ويختم أربعة صفوف', () => {
        expect(parseDisputeIntegrity('غير قابل للتجزئة')).toBe('indivisible');
        expect(isDisputeIndivisible('غير قابل للتجزئة')).toBe(true);
        expect(isDisputeIndivisible('قابل للتجزئة')).toBe(false);
        const stamped = stampPartyJudgmentOnStage(
            {},
            {
                judgmentForm: 'مختلط',
                disputeIntegrity: 'غير قابل للتجزئة',
                partyJudgmentDispositions: seedPartyJudgmentDispositions(
                    [{ id: 2 }, { id: 3 }, { id: 4 }, { id: 5 }],
                    'غيابي',
                ).map((row, i) => (i === 0 ? { ...row, form: 'حضوري' } : row)),
            },
        );
        expect(stamped.judgmentForm).toBe('مختلط');
        expect(stamped.disputeIntegrity).toBe('indivisible');
        expect(stamped.partyJudgmentDispositions).toHaveLength(4);
        expect(stamped.lastJudgmentType).toBeUndefined();
    });

    it('أدوار الطعن لا تُحسب مدعى عليهم للحكم البدائي إن كانوا مستأنفين فقط', () => {
        const listed = listJudgmentDispositionDefendants([
            { id: 1, role: 'المستأنف (المدعي)' },
            { id: 2, role: 'المستأنف عليه (المدعى عليه)' },
            { id: 3, role: 'المستأنف عليه (المدعى عليه)' },
        ]);
        expect(listed.map((p) => Number(p.id))).toEqual([2, 3]);
    });
});

/**
 * مصفوفة محاكاة: ربح / خسارة / جزئي × متعدّد مدّعين/مدعى عليهم × حضور مختلط × operative.
 */
import { describe, expect, it } from 'vitest';
import type { Party } from '@/app/components/lawyer/LawyerShared';
import { resolveFirstInstanceHadoriAppealRights } from '@/app/components/lawyer/smart-modal/smartFile/firstInstanceAppealRights';
import { stageOutcomeFromFirstInstanceRights } from '@/app/components/lawyer/smart-modal/smartFile/stageOutcomeResolution';
import { filterAppellantsByAppealInterest } from '@/app/components/lawyer/smart-modal/smartFile/appealInterestEligibility';
import { filterAppellantPartiesByChallengeMethod } from '@/app/domain/lawsuit/challengeAppellantEligibility';
import {
    attachPartyChallengeLanes,
    LANE_STATE_WAIVED,
} from '@/app/domain/lawsuit/partyChallengeLanes';
import {
    coerceJudgmentTypeForReleasedOperatives,
    type PartyJudgmentDisposition,
} from '@/app/domain/lawsuit/partyJudgmentDisposition';
import { applyArt210CassationExtension } from '@/app/domain/lawsuit/cassationArt210';
import { classifyAbsentObjectionOutcome } from '@/app/domain/lawsuit/objectionAppealConsequence';
import { resolveAbsentObjectionAppealRights } from '@/app/components/lawyer/smart-modal/smartFile/absentJudgmentAppealRights';

const multiDefendants: Party[] = [
    { id: 1, name: 'سامي', role: 'المدعى عليه', isClient: false, side: 'left' },
    { id: 2, name: 'باسم', role: 'المدعى عليه', isClient: false, side: 'left' },
    { id: 3, name: 'كريم', role: 'المدعى عليه', isClient: false, side: 'left' },
    { id: 4, name: 'أحمد', role: 'المدعي', isClient: true, side: 'right' },
];

const multiPlaintiffs: Party[] = [
    { id: 10, name: 'مدعي أ', role: 'المدعي', isClient: true, side: 'right' },
    { id: 11, name: 'مدعي ب', role: 'المدعي', isClient: false, side: 'right' },
    { id: 20, name: 'مدعى عليه', role: 'المدعى عليه', isClient: false, side: 'left' },
    { id: 21, name: 'مدعى عليه 2', role: 'المدعى عليه', isClient: false, side: 'left' },
];

describe('مصفوفة ربح/خسارة/جزئي — تعدد الأطراف + operative', () => {
    describe('فوز كامل — كل الملزَمين bound', () => {
        const dispositions: PartyJudgmentDisposition[] = [
            { partyId: '1', form: 'حضوري', operative: 'bound' },
            { partyId: '2', form: 'حضوري', operative: 'bound' },
            { partyId: '3', form: 'غيابي', operative: 'bound' },
        ];

        it('المدعي: wait_opponent + WIN؛ لا إكراه جزئي', () => {
            expect(
                coerceJudgmentTypeForReleasedOperatives('إجابة الدعوى بالكامل', dispositions),
            ).toBe('إجابة الدعوى بالكامل');
            const rights = resolveFirstInstanceHadoriAppealRights('إجابة الدعوى بالكامل', 'المدعي', {
                parties: multiDefendants,
                representedParty: 'المدعي',
            });
            expect(rights.action).toBe('wait_opponent');
            expect(stageOutcomeFromFirstInstanceRights(rights, 'إجابة الدعوى بالكامل')).toBe('WIN');
        });

        it('استئناف المختلط: الحاضر والغائب الملزَم؛ الاعتراض للغائب فقط', () => {
            expect(
                filterAppellantPartiesByChallengeMethod(multiDefendants, {
                    appealType: 'استئناف',
                    dispositions,
                })
                    .map((p) => Number(p.id))
                    .sort(),
            ).toEqual([1, 2, 3]);
            expect(
                filterAppellantPartiesByChallengeMethod(multiDefendants, {
                    appealType: 'اعتراض على الحكم الغيابي',
                    dispositions,
                }).map((p) => Number(p.id)),
            ).toEqual([3]);
        });
    });

    describe('خسارة كاملة — رد كلي', () => {
        it('المدعي: self_appeal + LOSS', () => {
            const rights = resolveFirstInstanceHadoriAppealRights('رد الدعوى كلياً', 'المدعي', {
