    it('يعيد بطاقة قديمة من LAPSED_EXECUTABLE إلى pending إذا بُذرت مهلة تمييز ما زالت مفتوحة', () => {
        const merged = mergePartyChallengeLanes({
            parties: PARTIES,
            dispositions: MIXED,
            existing: [
                {
