/**
 * بناء MatrixInput من مرحلة حكم محفوظة — جسر تشغيلي لمحرك القرار النقي.
 * لا يغيّر التخزين؛ يُستخدم لشريط الطعن المسمّى (resolveTopBarChallengeActions).
 */
import {
    isDisputeIndivisible,
    isPartyOperativeReleased,
    JUDGMENT_FORM_GHIABI,
    normalizePartyJudgmentDispositions,
    type DisputeIntegrity,
} from './partyJudgmentDisposition';
import {
    LANE_STATE_APPEAL,
    LANE_STATE_CASSATION,
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
    LANE_STATE_OBJECTION,
    LANE_STATE_WAIVED,
    normalizePartyChallengeLanes,
} from './partyChallengeLanes';
import {
    isLawsuitDefendantRecord,
    isLawsuitPlaintiffRecord,
    partitionLawsuitPartiesByRole,
} from './lawsuitPartyRole';
import type {
    MatrixInput,
    MatrixParty,
    PartyOutcome,
    PresenceForm,
    PartyRole,
} from './litigationDecisionEngine';

const CONSUMED = new Set([
    LANE_STATE_OBJECTION,
    LANE_STATE_APPEAL,
    LANE_STATE_CASSATION,
    LANE_STATE_WAIVED,
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
]);

export type MatrixStageSource = {
    stageName?: string | null;
    name?: string | null;
    judgmentForm?: string | null;
    lastJudgmentType?: string | null;
    finalDecision?: string | null;
    disputeIntegrity?: DisputeIntegrity | string | null;
    partyJudgmentDispositions?: unknown;
    partyChallengeLanes?: unknown;
    parties?: Array<{
        id?: number | string;
        name?: string | null;
        role?: string | null;
        isClient?: boolean;
    }> | null;
};

function judgmentText(stage: MatrixStageSource): string {
    return String(stage.finalDecision ?? stage.lastJudgmentType ?? '').trim();
}

function plaintiffOutcomeFromJudgment(text: string): PartyOutcome {
    const t = text;
    if (!t) return 'PARTIAL';
    if (t.includes('كلياً') && t.includes('رد')) return 'FULL_LOSS';
    if (t.includes('بالكامل') || (t.includes('إجابة') && !t.includes('جزئ'))) return 'FULL_WIN';
    if (t.includes('جزئ')) return 'PARTIAL';
    if (t.includes('رد')) return 'FULL_LOSS';
    return 'PARTIAL';
}

function presenceForm(raw: string | null | undefined): PresenceForm {
    return String(raw ?? '').includes('غيابي') ? 'GHIABI' : 'HADORI';
}

function mapRole(party: { role?: string | null }): PartyRole {
    const role = String(party.role ?? '');
    if (role.includes('اختصام') || (role.includes('شخص ثالث') && !role.includes('انضمام'))) {
        return 'interpleader';
    }
    if (isLawsuitPlaintiffRecord(party)) return 'plaintiff';
    if (isLawsuitDefendantRecord(party)) return 'defendant';
    return 'defendant';
}

/**
 * يحوّل مرحلة البداءة/الأحوال بعد الحكم إلى مدخلات المحرك.
 * يُرجع null إن لم توجد أطراف كافية.
 */
export function buildLitigationMatrixInputFromStage(params: {
    stage: MatrixStageSource;
    /** أطراف العرض إن لم تُخزَّن على المرحلة */
    partiesFallback?: MatrixStageSource['parties'];
    parentIntegrity?: DisputeIntegrity | string | null;
}): MatrixInput | null {
    const stage = params.stage;
    const rawParties = (stage.parties?.length ? stage.parties : params.partiesFallback) ?? [];
    if (rawParties.length === 0) return null;

    const dispositions = normalizePartyJudgmentDispositions(stage.partyJudgmentDispositions);
    const lanes = normalizePartyChallengeLanes(stage.partyChallengeLanes);
    const consumedIds = new Set(
        lanes.filter((lane) => CONSUMED.has(lane.laneState)).map((lane) => lane.partyId),
    );
    const dispById = new Map(dispositions.map((row) => [row.partyId, row]));
    const judgment = judgmentText(stage);
    const pOutcome = plaintiffOutcomeFromJudgment(judgment);

    const matrixParties: MatrixParty[] = rawParties.map((party) => {
        const id = String(party.id ?? '');
        const role = mapRole(party);
        const disp = dispById.get(id);
        let outcome: PartyOutcome = 'FULL_LOSS';
        if (role === 'plaintiff') {
            outcome = pOutcome;
        } else if (disp && isPartyOperativeReleased(disp)) {
            outcome = 'EXEMPT';
        } else if (role === 'interpleader') {
            outcome = pOutcome === 'FULL_WIN' ? 'FULL_LOSS' : pOutcome === 'FULL_LOSS' ? 'FULL_WIN' : 'PARTIAL';
        } else {
            outcome = 'FULL_LOSS';
        }
        return {
            id,
            name: String(party.name ?? id),
            role,
            outcome,
            form: presenceForm(disp?.form ?? stage.judgmentForm),
            challengeConsumed: consumedIds.has(id),
        };
    });

    const { plaintiffs, defendants } = partitionLawsuitPartiesByRole(rawParties);
    if (plaintiffs.length === 0 && defendants.length === 0) return null;

    const integrity = stage.disputeIntegrity ?? params.parentIntegrity;
    return {
        parties: matrixParties.filter((row) => Boolean(row.id)),
        isJointOrIndivisible: isDisputeIndivisible(integrity as DisputeIntegrity | null | undefined),
        hasCrossAppeal: false,
    };
}

/**
 * المادة 210 مرافعات — ميعاد التمييز الفردي وامتداد أثر النقض للشركاء.
 * التمييز/الاستئناف ليسا غيابيَين؛ الغياب يبقى على بطاقات البداءة.
 */
import {
    isDisputeIndivisible,
    JUDGMENT_FORM_GHIABI,
    releasedPartyIds,
    type DisputeIntegrity,
} from './partyJudgmentDisposition';
import {
    LANE_STATE_CASSATION,
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
    LANE_STATE_OBJECTION,
    LANE_STATE_REVIVED_BY_CASSATION_EXTENSION,
    LANE_STATE_WAIVED,
    normalizePartyChallengeLanes,
    type PartyChallengeLane,
} from './partyChallengeLanes';

export const CASSATION_JUDGMENT_AFFIRMED = 'تصديق الحكم';
export const CASSATION_JUDGMENT_REMANDED = 'نقض الحكم وإعادة الإضبارة';
export const CASSATION_JUDGMENT_REVERSE_FINAL = 'نقض الحكم والفصل في الموضوع';
export const CASSATION_JUDGMENT_DISMISS_FORMAL = 'رد الطعن التمييزي شكلاً';

export type CassationJudgmentEffect =
    | 'AFFIRMED'
    | 'REVERSED_REMANDED'
    | 'REVERSED_FINAL'
    | 'DISMISS_FORMAL';

export type CassationGroundsScope = 'COMMON' | 'PERSONAL';

export const ART210_EXTENSION_NOTICE =
    'استفاد الشركاء من نقض القرار حكماً لوحدة النزاع عملاً بالمادة 210 مرافعات';

export const DIRECT_CASSATION_BLOCKED_MESSAGE =
    'لا يُقبل التمييز المباشر للحكم الغيابي قبل التبليغ أو ما دامت مهلة الاعتراض قائمة إلا بعد ترك الاعتراض';

export function isCassationAppealMethod(appealType?: string | null): boolean {
    const t = String(appealType ?? '').trim();
    if (!t || t.includes('تصحيح') || t.includes('استئناف')) return false;
    return t === 'تمييز' || t === 'التمييز';
}

export function parseCassationGroundsScope(raw: unknown): CassationGroundsScope {
    return String(raw ?? '').trim() === 'PERSONAL' ? 'PERSONAL' : 'COMMON';
}

export function classifyCassationJudgmentEffect(raw: unknown): CassationJudgmentEffect | null {
    const t = String(raw ?? '').trim();
    if (!t) return null;
    if (t === CASSATION_JUDGMENT_REVERSE_FINAL || (t.includes('نقض') && t.includes('الموضوع'))) {
        return 'REVERSED_FINAL';
    }
    if (t === CASSATION_JUDGMENT_REMANDED || (t.includes('نقض') && t.includes('إعادة'))) {
        return 'REVERSED_REMANDED';
    }
    if (t === CASSATION_JUDGMENT_AFFIRMED || t.includes('تصديق')) return 'AFFIRMED';
    if (t.includes('رد') && t.includes('شكل')) return 'DISMISS_FORMAL';
    return null;
}

function deadlinePassed(deadline: string | null | undefined, today: string): boolean {
    const d = String(deadline ?? '').trim().slice(0, 10);
    if (!d) return false;
    return today > d;
}

/**
 * تمييز مباشر من البداءة: الغائب لا يميّز ما دامت مهلة اعتراضه قائمة، إلا بعد التنازل.
 * بعد الاستئناف لا يُستدعى هذا القيد (حكم الاستئناف حضوري).
 */
export function canPartyFileDirectCassation(
    lane: PartyChallengeLane,
    todayYmd: string,
): boolean {
    const today = String(todayYmd ?? '').trim().slice(0, 10);
    if (lane.laneState === LANE_STATE_OBJECTION) return false;
    if (lane.disposition === JUDGMENT_FORM_GHIABI) {
        if (!lane.servedAt) return false;
        if (
            lane.laneState !== LANE_STATE_WAIVED
            && lane.objectionDeadline
            && !deadlinePassed(lane.objectionDeadline, today)
        ) {
            return false;
        }
    }
    if (lane.cassationDeadline && deadlinePassed(lane.cassationDeadline, today)) return false;
    return true;
}

export function listBlockedDirectCassationPartyIds(params: {
    lanes?: unknown;
    partyIds?: Array<number | string> | null;
    today: string;
}): string[] {
    const wanted = new Set(
        (params.partyIds ?? []).map((id) => String(id ?? '').trim()).filter(Boolean),
    );
    if (wanted.size === 0) return [];
    return normalizePartyChallengeLanes(params.lanes)
        .filter((lane) => wanted.has(lane.partyId) && !canPartyFileDirectCassation(lane, params.today))
        .map((lane) => lane.partyId);
}

const REVIVABLE_STATES = new Set([
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
    LANE_STATE_WAIVED,
]);

export function applyArt210CassationExtension(params: {
    lanes?: unknown;
    integrity?: DisputeIntegrity | string | null;
    groundsScope?: CassationGroundsScope | string | null;
    cassatorPartyIds?: Array<number | string> | null;
    effect?: CassationJudgmentEffect | string | null;
    /** صفوف التفريد — المبرأون لا يُحيَون بم/210 */
    dispositions?: unknown;
}): PartyChallengeLane[] {
    const lanes = normalizePartyChallengeLanes(params.lanes);
    const effect =
        params.effect === 'REVERSED_REMANDED'
        || classifyCassationJudgmentEffect(params.effect) === 'REVERSED_REMANDED'
            ? 'REVERSED_REMANDED'
            : params.effect;
    if (effect !== 'REVERSED_REMANDED') return lanes;
    if (parseCassationGroundsScope(params.groundsScope) !== 'COMMON') return lanes;
    if (!isDisputeIndivisible(params.integrity)) return lanes;
    const cassators = new Set(
        (params.cassatorPartyIds ?? []).map((id) => String(id ?? '').trim()).filter(Boolean),
    );
    const released = new Set(releasedPartyIds(params.dispositions));
    return lanes.map((lane) => {
        if (cassators.has(lane.partyId)) return lane;
        if (released.has(lane.partyId)) return lane;
        if (lane.laneState === LANE_STATE_CASSATION) return lane;
        if (!REVIVABLE_STATES.has(lane.laneState)) return lane;
        return { ...lane, laneState: LANE_STATE_REVIVED_BY_CASSATION_EXTENSION };
    });
}

export function hasArt210ExtensionLanes(raw: unknown): boolean {
    return normalizePartyChallengeLanes(raw).some(
        (lane) => lane.laneState === LANE_STATE_REVIVED_BY_CASSATION_EXTENSION,
    );
}

/**
 * مسارا الطعن من حكم مختلط: الحاضر يستأنف فقط؛ الغائب يختار استئنافاً أو اعتراضاً غيابياً.
 * من استُهلك اعتراضه أو استئنافه لا يُعاد إدراجه. الحاضر لا يدخل قائمة الاعتراض.
 * الاختصامي المستقل حضور-مثل حتماً: يُبقى في فلتر الاستئناف/التمييز المختلط ولا يدخل اعتراض الغياب.
 */
import {
    remainingGhayabiObjectionPartyIds,
    remainingPresentAppealPartyIds,
} from './opponentChallengeTracks';
import {
    isIndependentInterpleaderRole,
    hasAnyReleasedDisposition,
    normalizePartyJudgmentDispositions,
    resolveJudgmentPresenceWindows,
    type PartyJudgmentDisposition,
} from './partyJudgmentDisposition';
import { normalizePartyChallengeLanes } from './partyChallengeLanes';
import { partitionLawsuitPartiesByRole } from './lawsuitPartyRole';

export function isGhayabiObjectionAppealType(appealType: string | null | undefined): boolean {
    const t = String(appealType ?? '').trim();
    if (!t || t.includes('اعتراض الغير')) return false;
    return (
        t.includes('اعتراض على الحكم الغيابي')
        || t.includes('اعتراض غيابي')
        || (t.includes('اعتراض') && t.includes('غيابي'))
    );
}

function isAppealOrCassationMethod(appealType: string): boolean {
    if (isGhayabiObjectionAppealType(appealType)) return false;
    return appealType.includes('استئناف') || appealType.includes('تمييز');
}

function partiesHaveAbsentObjectionRoles(parties: Array<{ role?: string }>): boolean {
    return parties.some((party) => {
        const role = String(party.role ?? '');
        return (
            role.includes('المعترض على الحكم الغيابي')
            || role.includes('المعترض عليه بالحكم الغيابي')
        );
    });
}

function keepByPartyIds<T extends { id: number | string }>(parties: T[], ids: string[]): T[] {
    const allowed = new Set(ids);
    return parties.filter((party) => allowed.has(String(party.id)));
}

function independentInterpleaderIds(
    parties: Array<{ id: number | string; role?: string }>,
): string[] {
    return parties
        .filter((party) => isIndependentInterpleaderRole(String(party.role ?? '')))
        .map((party) => String(party.id));
}

export function filterAppellantPartiesByChallengeMethod<
    T extends { id: number | string; role?: string; isClient?: boolean },
>(
    parties: T[],
    params: {
        appealType: string | null | undefined;
        dispositions?: PartyJudgmentDisposition[] | unknown;
        lanes?: unknown;
        scalarForm?: string | null;
    },
): T[] {
    if (!Array.isArray(parties) || parties.length === 0) return [];
    const appealType = String(params.appealType ?? '').trim();
    const dispositions = normalizePartyJudgmentDispositions(params.dispositions);
    const windows = resolveJudgmentPresenceWindows(dispositions, String(params.scalarForm ?? ''));

    if (isGhayabiObjectionAppealType(appealType)) {
        const remaining = remainingGhayabiObjectionPartyIds(params.lanes, dispositions);
        if (remaining.length > 0) return keepByPartyIds(parties, remaining);
        const hadExplicitGhayabi =
            dispositions.length > 0 || normalizePartyChallengeLanes(params.lanes).length > 0;
        return hadExplicitGhayabi ? [] : parties;
    }

    if (!isAppealOrCassationMethod(appealType)) return parties;
    if (partiesHaveAbsentObjectionRoles(parties)) return parties;
    if (!windows.mixed) return parties;

    const remainingPresent = remainingPresentAppealPartyIds(params.lanes, dispositions);
    const remainingGhayabi = remainingGhayabiObjectionPartyIds(params.lanes, dispositions);
    const allowed = new Set<string>([
        ...remainingPresent,
        ...remainingGhayabi,
        ...independentInterpleaderIds(parties),
    ]);
    /*
     * عند وجود مبرَّأ (released): المدعي الموكل يحتاج الطعن في الشق المردود
     * رغم أنه خارج صفوف disposition — يُضم إن وُجدت مصلحة جزئية.
     */
    if (hasAnyReleasedDisposition(dispositions)) {
        const { plaintiffs } = partitionLawsuitPartiesByRole(parties);
        for (const party of plaintiffs) {
            if (party.isClient) allowed.add(String(party.id));
        }
    }
    if (allowed.size > 0) return keepByPartyIds(parties, [...allowed]);
    return [];
}

type CourtReferralAcceptance = 'pending' | 'accepted' | 'rejected';

type CourtReferralStageFields = {
    court?: string;
    referredToCourt?: string;
    courtReferralDate?: string;
    courtReferralNotes?: string;
    previousCourtName?: string;
    courtReferralAcceptance?: CourtReferralAcceptance;
    courtReferralDecisionDate?: string;
};

type CourtReferralDisplay = {
    displayCourt: string;
    previousCourt: string | null;
    isPending: boolean;
    isAccepted: boolean;
    referredToCourt: string | null;
};

export type PendingCourtReferral = {
    referredToCourt: string;
    previousCourtName: string;
    transferDate: string;
    notes?: string;
};

function str(value: unknown): string {
    return String(value ?? '').trim();
}

export function inferCourtReferralAcceptance(
    stage: CourtReferralStageFields,
): CourtReferralAcceptance | undefined {
    const explicit = stage.courtReferralAcceptance;
    if (explicit) return explicit;
    const referred = str(stage.referredToCourt);
    if (!referred) return undefined;
    return 'pending';
}

export function resolveCourtReferralDisplay(stage: CourtReferralStageFields): CourtReferralDisplay {
    const referred = str(stage.referredToCourt);
    const storedCourt = str(stage.court);
    const acceptance = inferCourtReferralAcceptance(stage);
    const isRejected = acceptance === 'rejected';
    const isAccepted = acceptance === 'accepted' && Boolean(referred) && !isRejected;
    const isPending = acceptance === 'pending' && Boolean(referred);

    if (isAccepted) {
        const previousCourt = str(stage.previousCourtName) || storedCourt || null;
        return {
            displayCourt: referred,
            previousCourt,
            isPending: false,
            isAccepted: true,
            referredToCourt: referred,
        };
    }

    return {
        displayCourt: storedCourt,
        previousCourt: null,
        isPending,
        isAccepted: false,
        referredToCourt: isPending ? referred : null,
    };
}

export function readPendingCourtReferral(stage: CourtReferralStageFields): PendingCourtReferral | null {
    const referred = str(stage.referredToCourt);
    if (!referred) return null;
    if (inferCourtReferralAcceptance(stage) !== 'pending') return null;

    const previousCourtName = str(stage.previousCourtName) || str(stage.court);
    if (!previousCourtName) return null;

    return {
        referredToCourt: referred,
        previousCourtName,
        transferDate: str(stage.courtReferralDate) || '',
        notes: str(stage.courtReferralNotes) || undefined,
    };
}

export function hasBlockingCourtReferral(stage: CourtReferralStageFields): boolean {
    return readPendingCourtReferral(stage) !== null;
}

export function mergeDraftIntoPendingStage<T extends CourtReferralStageFields>(
    stage: T,
    draft: PendingCourtReferral,
): T {
    if (inferCourtReferralAcceptance(stage) === 'pending') {
        return stage;
    }
    return {
        ...stage,
        previousCourtName: draft.previousCourtName || str(stage.court),
        referredToCourt: draft.referredToCourt,
        courtReferralDate: draft.transferDate,
        courtReferralNotes: draft.notes,
        courtReferralAcceptance: 'pending',
    };
}

