export function allLawsuitFilesForArchive<T extends { type?: string }>(files: T[]): T[] {
    return files.filter((f) => f.type === 'lawsuit');
}

import type { FileData } from './lawsuitFileTypes';
import {
    rebuildActiveSegmentInIndex,
    type LawsuitLifecycleIndex,
} from '@/app/domain/lawsuit/lawsuitLifecycleIndex';
import {
    mirrorLawsuitSegmentsSafe,
    persistLawsuitActiveSegment,
    persistLawsuitLifecycleIndex,
} from '@/app/domain/lawsuit/lawsuitSegmentPersist';
import { stageLawsuitJournalRecords, mergeLawsuitJournalInto } from '@/app/domain/lawsuit/lawsuitWriteJournal';
import { mergePendingLawsuitCreatesInto } from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import {
    excludeLawsuitIdsBySet,
    lawsuitActiveIdSet,
    mergeRicherLawsuitActive,
    parseLawsuitActiveFiles,
} from '@/app/domain/lawsuit/lawsuitActiveDurability';
import { collectHeldOutOfActiveIds } from '@/app/domain/lawsuit/lawsuitFilesStatePolicy';
import { readLawsuitLifecycleHeldFenceIds } from '@/app/domain/lawsuit/lawsuitLifecycleMutationFence';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';

export type LawsuitActivePersistOptions = {
    allowVerifiedEmpty?: boolean;
    allowShrink?: boolean;
};

export type LawsuitActivePersistResult = {
    /** نجحت كتابة المقطع النشط — يُسمح بعدها بالفهرس والمرآة */
    ok: boolean;
    active: FileData[];
};

/**
 * اثبات تقلّص نشط: كل معرّف أُزيل من القرص يجب أن يكون في سلة/أرشيف/tombstone
 * وليس في المقترح النشط. بدون ذلك لا يُسمح بـ allowShrink.
 */
function proveLawsuitActiveShrink(
    proposed: FileData[],
    diskActive: FileData[],
    trash: FileData[] | null | undefined,
    archived: FileData[] | null | undefined,
): { ok: boolean; recovered: FileData[] } {
    const proposedIds = lawsuitActiveIdSet(proposed);
    const held = collectHeldOutOfActiveIds({
        trash,
        archived,
        includeTombstones: true,
        preferActiveIds: proposed,
    });
    const illicit: FileData[] = [];
    for (const row of diskActive) {
        const id = String(row.id ?? '').trim();
        if (!id || proposedIds.has(id)) continue;
        if (held.has(id)) continue;
        illicit.push(row);
    }
    if (illicit.length === 0) {
        return { ok: true, recovered: proposed };
    }
    return {
        ok: false,
        recovered: mergeRicherLawsuitActive(proposed, illicit),
    };
}

/**
 * بوابة الكتابة الموحّدة للمقطع النشط + الفهرس + المرآة.
 * كل مسارات الحفظ (إنشاء، autosave، تعديل إضبارة) تمر من هنا.
 */
export function persistLawsuitActiveBundle(input: {
    active: FileData[];
    index: LawsuitLifecycleIndex;
    archived?: FileData[] | null;
    trash?: FileData[] | null;
    options?: LawsuitActivePersistOptions;
}): LawsuitActivePersistResult {
    /*
     * ادمج المعلّق/السجل دائماً — حتى مع allowShrink (أرشفة/سلة).
     * المسارات تلك تُزيل المعرّف من overlay قبل الكتابة؛ بدون الدمج
     * تُفقد إضبارة منشأة ما زالت في pending بينما المدنية تُكتب وحدها.
     */
    /*
     * لا تمنح pending/WAL القديم حق إعادة ملف خرج من النشط. النشط الذي مرره
     * المستدعي وحده يملك أولوية active؛ أما overlay لم يُنظَّف بسبب مفتاح بارد
     * فيُحجب بحالة السلة/الأرشيف/الفهرس.
     */
    const fencedOutOfActive = readLawsuitLifecycleHeldFenceIds();
    const baseActive = excludeLawsuitIdsBySet(input.active, fencedOutOfActive);
    const heldAgainstOverlays = collectHeldOutOfActiveIds({
        trash: input.trash,
        archived: input.archived,
        index: input.index,
        includeTombstones: true,
        preferActiveIds: baseActive,
    });
    for (const id of fencedOutOfActive) heldAgainstOverlays.add(id);
    let active = excludeLawsuitIdsBySet(
        mergeLawsuitJournalInto(mergePendingLawsuitCreatesInto(baseActive)),
        heldAgainstOverlays,
    );
    if (active.length > 0) {
        stageLawsuitJournalRecords(active);
    }

    const diskActive = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
    );
    const preferActive = lawsuitActiveIdSet(active);
    const heldOutOfActive = collectHeldOutOfActiveIds({
        trash: input.trash,
        archived: input.archived,
        includeTombstones: true,
        preferActiveIds: preferActive,
    });

    let writeOptions = input.options;
    if (writeOptions?.allowShrink || writeOptions?.allowVerifiedEmpty) {
        const proof = proveLawsuitActiveShrink(
            active,
            diskActive,
            input.trash,
            input.archived,
        );
        if (!proof.ok) {
            /*
             * تقلّص بلا إثبات نقل — ادمج المفقود وارفض التفريغ.
             * يمنع allowShrink الأعمى من مسار الدمج/الإقلاع.
             */
            active = proof.recovered;
            writeOptions = {
                ...writeOptions,
                allowShrink: false,
                allowVerifiedEmpty: false,
            };
        } else if (active.length === 0 && diskActive.length > 0) {
            /*
             * تفريغ كامل: فقط إن كل معرّفات القرص held (سلة/أرشيف/tombstone).
             */
            let allHeld = true;
            for (const row of diskActive) {
                const id = String(row.id ?? '').trim();
                if (id && !heldOutOfActive.has(id)) {
                    allHeld = false;
                    break;
                }
            }
            if (!allHeld || !writeOptions.allowVerifiedEmpty) {
                active = excludeLawsuitIdsBySet(diskActive, heldOutOfActive);
                writeOptions = {
                    ...writeOptions,
                    allowShrink: active.length < diskActive.length,
                    allowVerifiedEmpty: active.length === 0,
                };
                if (active.length === 0 && !input.options?.allowVerifiedEmpty) {
                    return { ok: false, active: diskActive };
                }
            }
        }
    }

    const activeWritten = persistLawsuitActiveSegment(active, writeOptions);
    if (!activeWritten) {
        return { ok: false, active };
    }
    /*
     * اكتب الفهرس/المرآة من القائمة التي استقرّت على القرص لا من المقترح —
     * writeJsonArray قد يدمج الأغنى، والمرآة بالقائمة الأفقر كانت تسمّم lawyer_files.
     *
     * عند النقل العمدي (allowShrink): لا تُعد إحياء معرّفات خارج المقترح النشط
     * (سلة/أرشيف/tombstone) — لكن تكرار سلة∩نشط لا يُخرج النشط.
     */
    const diskAfter = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
    );
    const heldAfter = collectHeldOutOfActiveIds({
        trash: input.trash,
        archived: input.archived,
        includeTombstones: true,
        preferActiveIds: lawsuitActiveIdSet(active),
    });
    const diskSansHeld = excludeLawsuitIdsBySet(diskAfter, heldAfter);
    const canonical =
        writeOptions?.allowShrink || writeOptions?.allowVerifiedEmpty
            ? excludeLawsuitIdsBySet(
                  diskSansHeld.length > 0 ? diskSansHeld : active,
                  heldAfter,
              )
            : diskSansHeld.length > 0
              ? mergeRicherLawsuitActive(active, diskSansHeld)
              : active;
    /*
     * حارس أخير: لا تسمح لمرآة/فهرس فارغين إذا كان المقترح أو القرص يحمل بيانات
     * ولم يُطلب تفريغ موثّق صراحةً.
     */
    if (
        canonical.length === 0 &&
        (active.length > 0 || diskActive.length > 0) &&
        !writeOptions?.allowVerifiedEmpty
    ) {
        const fallback =
            active.length > 0 ? active : excludeLawsuitIdsBySet(diskActive, heldAfter);
        if (fallback.length > 0) {
            const index = rebuildActiveSegmentInIndex(input.index, fallback);
            persistLawsuitLifecycleIndex(index);
            mirrorLawsuitSegmentsSafe(fallback, input.archived ?? null, input.trash ?? null);
            return { ok: true, active: fallback };
        }
    }
    const index =
        canonical.length === input.active.length
            ? input.index
            : rebuildActiveSegmentInIndex(input.index, canonical);
    persistLawsuitLifecycleIndex(index);
    mirrorLawsuitSegmentsSafe(canonical, input.archived ?? null, input.trash ?? null);
    return { ok: true, active: canonical };
}

/**
 * تحديث الفهرس + المرآة دون إعادة كتابة المقطع النشط
 * (حذف نهائي من السلة، تحميل مقاطع كسولة).
 */
export function persistLawsuitLifecycleMirrorBundle(input: {
    active: FileData[];
    index: LawsuitLifecycleIndex;
    archived?: FileData[] | null;
    trash?: FileData[] | null;
}): void {
    persistLawsuitLifecycleIndex(input.index);
    mirrorLawsuitSegmentsSafe(input.active, input.archived ?? null, input.trash ?? null);
}

import type { FileData } from './lawsuitFileTypes';
import {
    pruneVerifiedLawsuitJournalEntries,
    tryClearPendingLawsuitCreateAfterProof,
    tryFinalizeLawsuitJournalAfterProof,
} from '@/app/domain/lawsuit/lawsuitDurabilityVerify';
import {
    clearPendingLawsuitCreate,
    flushPendingLawsuitCreatesToActive,
    listPendingLawsuitCreates,
    mergePendingLawsuitCreatesInto,
} from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import {
    awaitLawsuitWorkspaceCommit,
    type LawsuitCommitResult,
} from '@/app/domain/lawsuit/lawsuitPersistFlush';
import {
    flushLawsuitJournalToActive,
    hasUnverifiedLawsuitJournal,
    listLawsuitJournalEntries,
    mergeLawsuitJournalInto,
    pruneLawsuitJournalForFileIds,
    settleLawsuitJournalPersist,
} from '@/app/domain/lawsuit/lawsuitWriteJournal';

/** دمج كل طبقات المتانة (pending + journal) فوق المقطع النشط */
export function mergeLawsuitDurabilityOverlaysInto(active: FileData[]): FileData[] {
    return mergeLawsuitJournalInto(mergePendingLawsuitCreatesInto(active));
}

export function lawsuitDurabilityHasUncommittedWrites(): boolean {
    return listPendingLawsuitCreates().length > 0 || hasUnverifiedLawsuitJournal();
}

/** إزالة pending + WAL عند خروج الإضبارة من النشط (أرشفة/سلة/حذف نهائي) */
export function pruneLawsuitDurabilityOverlaysForFileIds(
    fileIds: readonly (string | number)[],
): void {
    for (const id of fileIds) {
        clearPendingLawsuitCreate(id);
    }
    pruneLawsuitJournalForFileIds(fileIds);
}

export async function flushLawsuitDurabilityOverlaysToActive(): Promise<number> {
    const pending = await flushPendingLawsuitCreatesToActive();
    const journal = await flushLawsuitJournalToActive();
    return pending + journal;
}

/**
 * بعد autosave/تعديل/pagehide: انتظر commit ثم أزل pending/WAL المثبت على القرص.
 * لا يُستدعى داخل بوابة الكتابة.
 */
export function scheduleFinalizeLawsuitDurabilityAfterCommit(
    fileIds?: readonly (string | number)[],
    options?: { timeoutMs?: number; requireActiveFileId?: string | number },
): void {
    void awaitLawsuitWorkspaceCommit({
        timeoutMs: options?.timeoutMs ?? 8_000,
        requireActiveFileId: options?.requireActiveFileId,
    })
        .then((commit) => finalizeLawsuitDurabilityAfterCommit(commit, fileIds))
        .catch(() => undefined);
}

export async function finalizeLawsuitDurabilityAfterCommit(
    commit: LawsuitCommitResult,
    fileIds?: readonly (string | number)[],
): Promise<number> {
    if (!commit.ok) return 0;

    const candidateIds = new Set<string>();
    if (fileIds?.length) {
        for (const id of fileIds) candidateIds.add(String(id));
    } else {
        for (const row of listPendingLawsuitCreates()) {
            candidateIds.add(String(row.id));
        }
        for (const entry of listLawsuitJournalEntries()) {
            candidateIds.add(entry.fileId);
        }
    }
    if (candidateIds.size === 0) return 0;

    let finalized = 0;
    for (const id of candidateIds) {
        const pendingCleared = await tryClearPendingLawsuitCreateAfterProof(id, commit);
        if (pendingCleared) {
            finalized += 1;
            continue;
        }
        const journalCleared = await tryFinalizeLawsuitJournalAfterProof(id, commit);
        if (journalCleared) finalized += 1;
    }

    await settleLawsuitJournalPersist();
    pruneVerifiedLawsuitJournalEntries(Array.from(candidateIds));
    return finalized;
}

import type { LawsuitCommitResult } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import { parseLawsuitActiveFiles } from '@/app/domain/lawsuit/lawsuitActiveDurability';
import {
    clearPendingLawsuitCreate,
    listPendingLawsuitCreates,
    settleLawsuitPendingPersist,
} from '@/app/domain/lawsuit/lawsuitPendingCreateStore';
import {
    isLawsuitJournalStillOpen,
    pruneLawsuitJournalForFileIds,
    settleLawsuitJournalPersist,
} from '@/app/domain/lawsuit/lawsuitWriteJournal';
import SecureStoreService from '@/app/services/SecureStoreService';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import {
    wasLawsuitJournaledThisPage,
    wasLawsuitStagedThisPage,
} from '@/app/domain/lawsuit/lawsuitPageWriteGuard';

/** هل النص المفكوك يحتوي معرّف الإضبارة في المقطع النشط؟ */
export function activePlaintextContainsFileId(
    plain: string | null,
    fileId: string | number,
): boolean {
    const id = String(fileId);
    return parseLawsuitActiveFiles(plain).some((row) => String(row.id) === id);
}

export function isLawsuitCreateStillPending(fileId: string | number): boolean {
    const id = String(fileId);
    return listPendingLawsuitCreates().some((row) => String(row.id) === id);
}

/**
 * تحقّق من IndexedDB مُفكّكاً — لا تعتمد على getItemSync (الذاكرة قد تكذب).
 */
export async function verifyLawsuitActiveFileOnDisk(fileId: string | number): Promise<boolean> {
    try {
        const plain = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        return activePlaintextContainsFileId(plain, fileId);
    } catch {
        return false;
    }
}

/** تحقّق سريع من الذاكرة المفكّكة — للتنظيف بعد كتابة ناجحة دون انتظار IDB.
 * leftover في localStorage وحده ليس إثبات قرص — لا drain هنا. */
export function verifyLawsuitActiveFileOnDiskSync(fileId: string | number): boolean {
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)) return false;
    try {
        const plain = SecureStoreService.getItemSync(LAWSUIT_FILES_ACTIVE_KEY);
        return typeof plain === 'string' && activePlaintextContainsFileId(plain, fileId);
    } catch {
        return false;
    }
}

/** يُزيل من السجل فقط المعرّفات المثبتة على المقطع النشط (sync) */
export function pruneVerifiedLawsuitJournalEntries(
    fileIds: readonly (string | number)[],
): number {
    const verified = fileIds.filter(
        (id) => !wasLawsuitJournaledThisPage(id) && verifyLawsuitActiveFileOnDiskSync(id),
    );
    if (verified.length === 0) return 0;
    pruneLawsuitJournalForFileIds(verified);
    return verified.length;
}

/**
 * القاعدة الذهبية لمسح المعلّق:
 * commit.ok ∧ لا يزال معلّقاً ∧ المعرّف موجود في active على القرص مُفكّكاً.
 */
export async function tryClearPendingLawsuitCreateAfterProof(
    fileId: string | number,
    commit: LawsuitCommitResult,
): Promise<boolean> {
    if (!commit.ok) return false;
    if (!isLawsuitCreateStillPending(fileId)) return false;
    /* نفس الصفحة التي أنشأت ≠ إقلاع بعد Reload */
    if (wasLawsuitStagedThisPage(fileId)) return false;
    if (!(await verifyLawsuitActiveFileOnDisk(fileId))) return false;
    await settleLawsuitPendingPersist();
    clearPendingLawsuitCreate(fileId);
    await settleLawsuitJournalPersist();
    pruneLawsuitJournalForFileIds([fileId]);
    return true;
}

/**
 * مسح سجل WAL بعد إثبات القرص — لكل كتابة (إنشاء أو تعديل).
 */
export async function tryFinalizeLawsuitJournalAfterProof(
    fileId: string | number,
    commit: LawsuitCommitResult,
): Promise<boolean> {
    if (!commit.ok) return false;
    if (!isLawsuitJournalStillOpen(fileId)) return false;
    if (wasLawsuitJournaledThisPage(fileId)) return false;
    if (!(await verifyLawsuitActiveFileOnDisk(fileId))) return false;
    await settleLawsuitJournalPersist();
    pruneLawsuitJournalForFileIds([fileId]);
    return true;
}

import type { FileData } from './lawsuitFileTypes';
import type { CaseType, Party } from '@/app/components/lawyer/lawyerShared/fileDataTypes';
import type { TimelineEvent } from '@/app/components/lawyer/lawyerShared/stageTimelineTypes';
import { FIRST_HEARING_TIMELINE_APPT_ID } from './firstHearingTimelineId';

export { FIRST_HEARING_TIMELINE_APPT_ID };
export { allLawsuitFilesForArchive } from './lawsuitArchivePool';

function buildFirstHearingTimelineEvent(date: string): TimelineEvent {
    return {
        id: FIRST_HEARING_TIMELINE_APPT_ID,
        type: 'appointment',
        date,
        title: 'أول مرافعة',
        details: 'تاريخ أول مرافعة عند إنشاء الإضبارة',
        subType: 'pleading',
        isDeleted: false,
        isNew: true,
    };
}

function normalizeYmd(value: unknown): string | undefined {
    if (typeof value !== 'string') return undefined;
    const trimmed = value.trim();
    return /^\d{4}-\d{2}-\d{2}$/.test(trimmed) ? trimmed : undefined;
}

function isRecord(v: unknown): v is Record<string, unknown> {
    return v !== null && typeof v === 'object';
}

function toParty(
    p: Record<string, unknown>,
    idx: number,
    listSide: 'right' | 'left',
): Party | null {
    const name = typeof p.name === 'string' ? p.name.trim() : '';
    if (!name) return null;
    const idRaw = p.id;
    const id =
        typeof idRaw === 'number'
            ? idRaw
            : typeof idRaw === 'string' && /^\d+$/.test(idRaw)
              ? Number(idRaw)
              : Date.now() + idx;
    const role =
        typeof p.status === 'string' && p.status.trim()
            ? p.status
            : typeof p.role === 'string' && p.role.trim()
              ? p.role
              : listSide === 'right'
                ? 'المدعي'
                : 'المدعى عليه';
    const isClient = p.isClient === true;
    return {
        id,
        name,
        role,
        isClient,
        phone: typeof p.phone === 'string' ? p.phone : undefined,
        address: typeof p.address === 'string' ? p.address : undefined,
        side: listSide,
    };
}

function thirdPartyToParty(tp: Record<string, unknown>, idx: number): Party | null {
    const name = typeof tp.name === 'string' ? tp.name.trim() : '';
    if (!name) return null;
    const affiliatedSide = tp.affiliatedSide === 1 || tp.affiliatedSide === 2 ? tp.affiliatedSide : null;
    const entryMode = typeof tp.entryMode === 'string' ? tp.entryMode : '';
    const roleLabel =
        typeof tp.roleLabel === 'string' && tp.roleLabel.trim()
            ? tp.roleLabel.trim()
            : entryMode === 'interpleader'
              ? 'شخص ثالث (اختصامي)'
              : entryMode === 'affiliative'
                ? affiliatedSide === 1
                    ? 'شخص ثالث (انضمامي — جانب المدعي)'
                    : 'شخص ثالث (انضمامي — جانب المدعى عليه)'
                : 'شخص ثالث';
    const side: 'right' | 'left' | undefined =
        entryMode === 'interpleader'
            ? undefined
            : affiliatedSide === 1
              ? 'right'
              : affiliatedSide === 2
                ? 'left'
                : undefined;
    const idRaw = tp.id;
    const id =
        typeof idRaw === 'number'
            ? idRaw
            : typeof idRaw === 'string' && /^\d+$/.test(idRaw)
              ? Number(idRaw)
              : Date.now() + idx + 200;
    return {
        id,
        name,
        role: roleLabel,
        isClient: tp.isClient === true,
        phone: typeof tp.phone === 'string' ? tp.phone : undefined,
        address: typeof tp.address === 'string' ? tp.address : undefined,
        ...(side ? { side } : {}),
    };
}

function resolveRepresentedPartyFromPayload(
    parties1: Record<string, unknown>[],
    parties2: Record<string, unknown>[],
    thirdParties: Record<string, unknown>[],
): 'المدعي' | 'المدعى عليه' | undefined {
    if (parties1.some((p) => p.isClient === true)) return 'المدعي';
    if (parties2.some((p) => p.isClient === true)) return 'المدعى عليه';
    if (thirdParties.some((tp) => tp.isClient === true && tp.affiliatedSide === 1)) return 'المدعي';
    if (thirdParties.some((tp) => tp.isClient === true && tp.affiliatedSide === 2)) return 'المدعى عليه';
    return undefined;
}

function buildFromStructuredPayload(d: Record<string, unknown>): FileData {
    const details = isRecord(d.details) ? d.details : {};
    const mainCategory =
        d.mainCategory === 'lawsuit' || d.mainCategory === 'transaction' || d.mainCategory === 'execution'
            ? (d.mainCategory as CaseType)
            : 'lawsuit';

    const caseNo =
        typeof details.number === 'string' && details.number.trim()
            ? details.number.trim()
            : typeof d.caseNumber === 'string' && d.caseNumber.trim()
              ? d.caseNumber.trim()
              : 'جديد';
    const court = typeof details.court === 'string' ? details.court : typeof d.court === 'string' ? d.court : 'بداءة الكرخ';
    const docType =
        typeof details.type === 'string'
            ? details.type
            : typeof d.subType === 'string'
              ? d.subType
              : undefined;
    const feesRaw =
        typeof details.totalAgreedFees === 'string'
            ? details.totalAgreedFees
            : typeof d.feesTotal === 'string'
              ? d.feesTotal
              : '';
    const feesTotal = feesRaw ? feesRaw.replace(/[^0-9.]/g, '') : '0';
    const judge =
        typeof details.judge === 'string' && details.judge.trim()
            ? details.judge.trim()
            : typeof d.judge === 'string'
              ? d.judge.trim()
              : undefined;
    const currentStage =
        typeof details.stage === 'string' && details.stage.trim()
            ? details.stage.trim()
            : typeof d.currentStage === 'string'
              ? d.currentStage.trim()
              : undefined;
    const claimValueRaw =
        typeof details.claimValue === 'string'
            ? details.claimValue
            : typeof d.claimValue === 'string'
              ? d.claimValue
              : '';
    const claimValue = claimValueRaw.replace(/[^0-9]/g, '') || undefined;

    const isUndeterminedValue = d.isUndeterminedValue === true;
    const isFixedFee = d.isFixedFee === true;
    const retrialTargetStage =
        typeof details.retrialTargetStage === 'string' && details.retrialTargetStage.trim()
            ? details.retrialTargetStage.trim()
            : typeof d.retrialTargetStage === 'string' && d.retrialTargetStage.trim()
              ? d.retrialTargetStage.trim()
              : undefined;

    const applicableLawRaw =
        typeof details.applicableLaw === 'string'
            ? details.applicableLaw
            : typeof d.applicableLaw === 'string'
              ? d.applicableLaw
              : undefined;
    const applicableLaw =
        applicableLawRaw === 'law_188_1959' || applicableLawRaw === 'jaafari_code'
            ? applicableLawRaw
            : undefined;

    const firstHearingDate = normalizeYmd(details.firstHearingDate);

    const parties1 = Array.isArray(d.parties1) ? (d.parties1 as Record<string, unknown>[]) : [];
    const parties2 = Array.isArray(d.parties2) ? (d.parties2 as Record<string, unknown>[]) : [];
    const thirdParties = Array.isArray(d.thirdParties) ? (d.thirdParties as Record<string, unknown>[]) : [];

    const parties: Party[] = [
        ...parties1
            .map((p, idx) => toParty(p, idx, 'right'))
            .filter((x): x is Party => x !== null),
        ...parties2
            .map((p, idx) => toParty(p, idx + 100, 'left'))
            .filter((x): x is Party => x !== null),
        ...thirdParties
            .map((p, idx) => thirdPartyToParty(p, idx))
            .filter((x): x is Party => x !== null),
    ];

    const representedParty = resolveRepresentedPartyFromPayload(parties1, parties2, thirdParties);
    const firstHearingHistory = firstHearingDate ? [buildFirstHearingTimelineEvent(firstHearingDate)] : [];

    if (parties.length === 0 && Array.isArray(d.parties)) {
        return buildFromCaseFormPayload(d);
    }

    const rawJurisdiction =
        typeof d.selectedType === 'string'
            ? d.selectedType
            : typeof d.lawsuitJurisdiction === 'string'
              ? d.lawsuitJurisdiction
              : undefined;
    const lawsuitJurisdiction =
        rawJurisdiction === 'civil' || rawJurisdiction === 'personal'
            ? rawJurisdiction
            : undefined;

    return {
        id: Date.now(),
        type: mainCategory,
        status: 'active',
        caseNo,
        caseNoParts: { year: new Date().getFullYear().toString(), type: '', seq: '' },
        court,
        docType,
        ...(judge ? { judge } : {}),
        ...(currentStage ? { currentStage } : {}),
        ...(claimValue ? { claimValue } : {}),
        ...(isUndeterminedValue ? { isUndeterminedValue: true } : {}),
        ...(isFixedFee ? { isFixedFee: true } : {}),
        ...(retrialTargetStage ? { retrialTargetStage } : {}),
        feesTotal,
        feesPaid: '0',
        date: new Date().toLocaleDateString('ar-EG'),
        parties,
        history: firstHearingHistory,
        notes: [],
        images: [],
        ...(representedParty ? { representedParty } : {}),
        ...(thirdParties.length > 0 ? { thirdParties } : {}),
        ...(lawsuitJurisdiction ? { lawsuitJurisdiction } : {}),
        ...(applicableLaw ? { applicableLaw } : {}),
        ...(firstHearingDate ? { firstHearingDate, nextDate: firstHearingDate } : {}),
    };
}

function buildFromCaseFormPayload(d: Record<string, unknown>): FileData {
    const title = typeof d.title === 'string' ? d.title : 'lawsuit';
    const mainCategory: CaseType =
        title === 'transaction' || title === 'execution' ? title : 'lawsuit';

    const caseNo =
        typeof d.caseNumber === 'string' && d.caseNumber.trim() ? d.caseNumber.trim() : 'جديد';
    const court = typeof d.court === 'string' && d.court.trim() ? d.court : 'بداءة الكرخ';
    const docType = typeof d.subType === 'string' ? d.subType : undefined;

    const rawParties = Array.isArray(d.parties) ? (d.parties as Record<string, unknown>[]) : [];
    const parties: Party[] = rawParties
        .map((p, idx) => {
            const isClient = p.isClient === true;
            return toParty(p, idx, isClient ? 'right' : 'left');
        })
        .filter((x): x is Party => x !== null);

    return {
        id: Date.now(),
        type: mainCategory,
        status: 'active',
        caseNo,
        caseNoParts: { year: new Date().getFullYear().toString(), type: '', seq: '' },
        court,
        docType,
        feesTotal: '0',
        feesPaid: '0',
        date: new Date().toLocaleDateString('ar-EG'),
        parties,
        history: [],
        notes: [],
        images: [],
    };
}

/** بناء FileData من حفظ LawyerNewCase أو الحمولة المنظّمة للداشبورد. */
export function buildFileDataFromNewCaseSave(data: unknown): FileData | null {
    if (!isRecord(data)) return null;

    if (Array.isArray(data.parties1) || Array.isArray(data.parties2) || isRecord(data.details)) {
        return buildFromStructuredPayload(data);
    }

    if (Array.isArray(data.parties)) {
        return buildFromCaseFormPayload(data);
    }

    return buildFromStructuredPayload(data);
}

import type { FileData } from './lawsuitFileTypes';
import { isLawsuitArchived, isLawsuitInTrash } from '@/app/utils/lawsuitTrash';

type LawsuitFileMutationTarget = {
    status?: string | null;
};

/** Null-safe archive check for mutation guards — delegates to `isLawsuitArchived`. */
function lawsuitTargetIsArchived(file: LawsuitFileMutationTarget | null | undefined): boolean {
    return isLawsuitArchived({ status: file?.status ?? undefined });
}

function isLawsuitFileDeleted(file: LawsuitFileMutationTarget | null | undefined): boolean {
    return isLawsuitInTrash({ status: file?.status ?? undefined });
}

export function isLawsuitFileMutationBlocked(file: LawsuitFileMutationTarget | null | undefined): boolean {
    return lawsuitTargetIsArchived(file) || isLawsuitFileDeleted(file);
}

/** رسالة عربية عند رفض التعديل — null إذا مسموح */
export function rejectLawsuitFileMutation(file: LawsuitFileMutationTarget | null | undefined): string | null {
    if (!file) return 'السجل غير موجود.';
    if (isLawsuitFileDeleted(file)) return 'الإضبارة في سلة المحذوفات — لا يمكن التعديل.';
    if (lawsuitTargetIsArchived(file)) return 'الإضبارة مؤرشفة — للقراءة فقط.';
    return null;
}

export function assertLawsuitFileMutable(
    file: FileData | LawsuitFileMutationTarget | null | undefined,
): FileData | LawsuitFileMutationTarget {
    const msg = rejectLawsuitFileMutation(file);
    if (msg) throw new Error(msg);
    return file as FileData;
}

