const STALE_MOCK_CASE_NO = '2025/ب/522';

/** إزالة mock قديم من الجلسات السابقة */
export function stripStaleMockLawsuitFile(files: FileData[]): FileData[] {
    if (files.length === 1 && files[0]?.id === 1 && files[0]?.caseNo === STALE_MOCK_CASE_NO) {
        return [];
    }
    return files;
}

export function loadInitialLawsuitFiles(): FileData[] {
    const boot = loadLawsuitBootSegments();
    const stripped = stripStaleMockLawsuitFile(boot.active);
    if (stripped.length !== boot.active.length && stripped.length > 0) {
        const index = rebuildActiveSegmentInIndex(boot.index, stripped);
        persistLawsuitActiveBundle({
            active: stripped,
            index,
            archived: boot.archived,
            trash: boot.trash,
            options: { allowShrink: true },
        });
    }
    return mergeLawsuitDurabilityOverlaysInto(stripped);
}

/**
 * تحميل غير متزامن — مقاطع الدعوى فقط (لا تنتظر PROTECTED_WARM_KEYS كلها).
 * ترحيل المخطط الشامل يبقى في الخلفية عبر ensurePersistedReady.
 */
export async function loadInitialLawsuitFilesAsync(): Promise<FileData[]> {
    await SecureStoreService.ensureLawsuitKeysReady();
    void SecureStoreService.ensurePersistedReady().catch(() => undefined);

    const syncFirst = stripStaleMockLawsuitFile(loadInitialLawsuitFiles());
    if (syncFirst.length > 0) {
        return syncFirst;
    }

    const needsWarm =
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_INDEX_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_STORAGE_KEY);

    if (needsWarm) {
        await SecureStoreService.warmKeys([
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_INDEX_KEY,
            LAWSUIT_FILES_STORAGE_KEY,
        ]);
    }

    const warmed = loadInitialLawsuitFiles();
    if (warmed.length > 0) {
        return warmed;
    }

    const bootAfterWarm = loadLawsuitBootSegments();
    if (shouldRefuseEmptyActiveMonolithRecovery(bootAfterWarm.index)) {
        return mergeLawsuitDurabilityOverlaysInto(
            stripStaleMockLawsuitFile(bootAfterWarm.active),
        );
    }

    const { loadDossierCollectionAsync } = await import(
        '@/app/services/dossierPersistence/dossierPersistenceService'
    );
    const asyncLoaded = (await loadDossierCollectionAsync('lawsuit')) as FileData[];
    const syncLoaded = loadLawsuitFilesRaw() as FileData[];
    const primary = asyncLoaded.length > 0 ? asyncLoaded : syncLoaded;
    if (primary.length > 0) {
        applyLawsuitMonolithicMergeToSegments(primary);
        return mergeLawsuitDurabilityOverlaysInto(
            stripStaleMockLawsuitFile(loadLawsuitBootSegments().active),
        );
    }
    return mergeLawsuitDurabilityOverlaysInto(
        stripStaleMockLawsuitFile(loadLawsuitBootSegments().active),
    );
}

export function loadLawsuitBootSegments(): LawsuitFileSegments {
    const boot = loadLawsuitBootState();
    const stripped = stripStaleMockLawsuitFile(boot.active);
    let diskTrash = boot.trash ?? readLawsuitTrashSegment();
    let diskArchived = boot.archived ?? readLawsuitArchivedSegment();
    const held = collectHeldOutOfActiveIds({
        trash: diskTrash,
        archived: diskArchived,
        index: boot.index,
        preferActiveIds: stripped,
    });
    const withoutHeld = excludeLawsuitIdsBySet(stripped, held);
    const healedTrash = healLawsuitTrashAgainstActive(withoutHeld, diskTrash);
    if (healedTrash && healedTrash.length !== diskTrash.length) {
        diskTrash = healedTrash;
        if (!shouldSkipBootSegmentPersistSafe()) {
            persistLawsuitTrashSegment(diskTrash, {
                allowShrink: true,
                allowVerifiedEmpty: diskTrash.length === 0,
            });
        }
    }
    const healedArchived = healLawsuitArchivedAgainstActive(withoutHeld, diskArchived);
    if (healedArchived && healedArchived.length !== diskArchived.length) {
        diskArchived = healedArchived;
        if (!shouldSkipBootSegmentPersistSafe()) {
            persistLawsuitArchivedSegment(diskArchived, {
                allowShrink: true,
                allowVerifiedEmpty: diskArchived.length === 0,
            });
        }
    }

    /*
     * لا تكتب تفريغاً/تقلّصاً للنشط من مسار الإقلاع أبداً.
     * شفاء السلة/الأرشيف المكرر مسموح؛ تثبيت withoutHeld على القرص كان wipe جزئياً.
     */
    let active = excludeLawsuitIdsBySet(
        mergeLawsuitDurabilityOverlaysInto(withoutHeld),
        collectHeldOutOfActiveIds({
            trash: diskTrash,
            archived: diskArchived,
            preferActiveIds: withoutHeld,
        }),
    );

    if (active.length === 0) {
        if (
            areLawsuitDossierTombstonesUnreadSync() ||
            shouldRefuseEmptyActiveMonolithRecovery(boot.index)
        ) {
            return {
                active,
                archived: boot.archived === null ? null : diskArchived,
                trash: boot.trash === null ? null : diskTrash,
                index: boot.index,
            };
        }
        const mono = stripStaleMockLawsuitFile(loadLawsuitFilesRaw() as FileData[]);
        if (mono.length > 0) {
            const monoActive = mono.filter((f) => {
                const status = String((f as { status?: string }).status ?? '').toLowerCase();
                return status !== 'archived' && status !== 'trash' && status !== 'deleted';
            });
            const recoverHeld = collectHeldOutOfActiveIds({
                trash: diskTrash,
                archived: diskArchived,
                preferActiveIds: stripped,
            });
            const recovered = excludeTombstonedLawsuitFiles(
                excludeLawsuitIdsBySet(monoActive, recoverHeld),
            );
            if (recovered.length > 0) {
                active = mergeLawsuitDurabilityOverlaysInto(recovered);
                diskTrash = healLawsuitTrashAgainstActive(active, diskTrash) ?? diskTrash;
                diskArchived =
                    healLawsuitArchivedAgainstActive(active, diskArchived) ?? diskArchived;
                const index = rebuildActiveSegmentInIndex(boot.index, active);
                if (!shouldSkipBootSegmentPersistSafe()) {
                    persistLawsuitActiveBundle({
                        active,
                        index,
                        archived: diskArchived,
                        trash: diskTrash,
                    });
                }
                return {
                    active,
                    archived: boot.archived === null ? null : diskArchived,
                    trash: boot.trash === null ? null : diskTrash,
                    index,
                };
            }
        }
    }

    return {
        active,
        archived: boot.archived === null ? null : diskArchived,
        trash: boot.trash === null ? null : diskTrash,
        index:
            active.length !== stripped.length
                ? rebuildActiveSegmentInIndex(boot.index, active)
                : boot.index,
    };
}

function shouldSkipBootSegmentPersistSafe(): boolean {
    try {
        if (!SecureStoreService.isDiskHydrationSettledSync()) return true;
        return (
            SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY) ||
            SecureStoreService.isUnreadSync(LAWSUIT_FILES_INDEX_KEY) ||
            SecureStoreService.isUnreadSync(LAWSUIT_FILES_STORAGE_KEY)
        );
    } catch {
        return true;
    }
}

export function loadLawsuitArchivedSegmentFiles(): FileData[] {
    migrateLawsuitMonolithicToSegmentsIfNeeded();
    return excludeTombstonedLawsuitFiles(readLawsuitArchivedSegment());
}

export function loadLawsuitTrashSegmentFiles(): FileData[] {
    migrateLawsuitMonolithicToSegmentsIfNeeded();
    return excludeTombstonedLawsuitFiles(readLawsuitTrashSegment());
}

export function reloadLawsuitFilesFromStorage(): LawsuitFileSegments {
    const full = loadLawsuitFullSegmentsFromStorage();
    const stripped = stripStaleMockLawsuitFile(full.active);
    const held = collectHeldOutOfActiveIds({
        trash: full.trash,
        archived: full.archived,
        index: full.index,
        preferActiveIds: stripped,
    });
    const withoutHeld = excludeLawsuitIdsBySet(stripped, held);
    const healedTrash = healLawsuitTrashAgainstActive(withoutHeld, full.trash) ?? full.trash;
    const healedArchived =
        healLawsuitArchivedAgainstActive(withoutHeld, full.archived) ?? full.archived;
    const active = excludeLawsuitIdsBySet(
        mergeLawsuitDurabilityOverlaysInto(withoutHeld),
        collectHeldOutOfActiveIds({
            trash: healedTrash,
            archived: healedArchived,
            preferActiveIds: withoutHeld,
        }),
    );
    return {
        active,
        archived: healedArchived,
        trash: healedTrash,
        index:
            active.length !== full.active.length
                ? rebuildActiveSegmentInIndex(full.index, active)
                : full.index,
    };
}

/** حفظ موحّد — النشطة فقط (توافق المسارات القديمة) */
export function persistLawsuitFiles(next: FileData[]): FileData[] {
    let payload = mergeLawsuitDurabilityOverlaysInto(Array.isArray(next) ? next : []);
    const boot = loadLawsuitBootSegments();

    if (payload.length === 0) {
        if (
            boot.active.length > 0 ||
            boot.index.counts.active > 0 ||
            boot.index.counts.archived > 0 ||
            boot.index.counts.trash > 0 ||
            lawsuitSegmentsNeedWarm()
        ) {
            return boot.active;
        }
    }

    if (isPoorerLawsuitActiveList(payload, boot.active)) {
        payload = mergeRicherLawsuitActive(payload, boot.active);
    }

    if (payload.length > 0 && boot.active.length === 0) {
        const mono = stripStaleMockLawsuitFile(loadLawsuitFilesRaw() as FileData[]);
        if (mono.length > 0) {
            const activeFromMono = mono.filter((f) => {
                const status = String((f as { status?: string }).status ?? '').toLowerCase();
                return status !== 'archived' && status !== 'trash' && status !== 'deleted';
            });
            if (activeFromMono.length > 0) {
                payload = mergeRicherLawsuitActive(payload, activeFromMono);
            }
        }
    }

    const nextIndex = rebuildActiveSegmentInIndex(boot.index, payload);
    persistLawsuitActiveBundle({
        active: payload,
        index: nextIndex,
        archived: boot.archived,
        trash: boot.trash,
    });
    return payload;
}

import type { FileData } from './lawsuitFileTypes';
import { assertLawsuitFileMutable } from './lawsuitFileMutationGuard';
import {
    applyLawsuitIndexStatusChange,
    buildLawsuitIndexEntryFromFile,
    buildLawsuitLifecycleIndex,
    removeLawsuitFromIndex,
    upsertLawsuitIndexEntry,
} from './lawsuitLifecycleIndex';
import {
    persistLawsuitArchivedSegment,
    persistLawsuitTrashSegment,
    readLawsuitArchivedSegment,
    readLawsuitTrashSegment,
    resolveLazyLawsuitSegmentForMirror,
} from './lawsuitSegmentStorage';
import { persistLawsuitActiveBundle } from './lawsuitDurabilityGate';
import { pruneLawsuitDurabilityOverlaysForFileIds } from './lawsuitDurabilityOverlay';
import type { LawsuitFileSegments } from './lawsuitFileSegments';

export type { LawsuitFileSegments } from './lawsuitFileSegments';

/** مقاطع كسولة (`null`) تُقرأ من القرص قبل أي طفرة تُpersist — لا `?? []`. */
function resolveTrashForMutation(segments: LawsuitFileSegments): FileData[] {
    return resolveLazyLawsuitSegmentForMirror(segments.trash, readLawsuitTrashSegment);
}

function resolveArchivedForMutation(segments: LawsuitFileSegments): FileData[] {
    return resolveLazyLawsuitSegmentForMirror(segments.archived, readLawsuitArchivedSegment);
}

export function persistLawsuitActiveRecord(
    record: FileData,
    segments: LawsuitFileSegments,
): LawsuitFileSegments {
    assertLawsuitFileMutable(record);
    const idStr = String(record.id);
    const nextActive = segments.active.some((f) => String(f.id) === idStr)
        ? segments.active.map((f) => (String(f.id) === idStr ? record : f))
        : [record, ...segments.active];
    const nextIndex = upsertLawsuitIndexEntry(segments.index, record);
    const next: LawsuitFileSegments = { ...segments, active: nextActive, index: nextIndex };
    persistLawsuitActiveBundle({
        active: nextActive,
        index: nextIndex,
        archived: segments.archived,
        trash: segments.trash,
    });
    return next;
}

export function applyLawsuitTrashSegments(
    segments: LawsuitFileSegments,
    fileId: string | number,
): LawsuitFileSegments {
    const idStr = String(fileId);
    const file = segments.active.find((f) => String(f.id) === idStr);
    if (!file) return segments;
    const trashed = { ...file, status: 'deleted' as const, deletedAt: Date.now() };
    const nextActive = segments.active.filter((f) => String(f.id) !== idStr);
    const existingTrash = resolveTrashForMutation(segments).filter((f) => String(f.id) !== idStr);
    const nextTrash = [...existingTrash, trashed];
    const nextIndex = applyLawsuitIndexStatusChange(
        segments.index,
        idStr,
        'active',
        'deleted',
        buildLawsuitIndexEntryFromFile(trashed),
    );
    const next: LawsuitFileSegments = {
        active: nextActive,
        archived: segments.archived,
        trash: nextTrash,
        index: nextIndex,
    };
    return next;
}

export function applyLawsuitRestoreFromTrashSegments(
    segments: LawsuitFileSegments,
    fileId: string | number,
): LawsuitFileSegments {
    const idStr = String(fileId);
    const trash = resolveTrashForMutation(segments);
    const file = trash.find((f) => String(f.id) === idStr);
    if (!file) return segments;
    const restored = { ...file, status: 'active' as const, deletedAt: undefined };
    const nextTrash = trash.filter((f) => String(f.id) !== idStr);
    const nextActive = [restored, ...segments.active];
    const nextIndex = applyLawsuitIndexStatusChange(
        segments.index,
        idStr,
        'deleted',
        'active',
        buildLawsuitIndexEntryFromFile(restored),
    );
    const next: LawsuitFileSegments = {
        active: nextActive,
        archived: segments.archived,
        trash: nextTrash,
        index: nextIndex,
    };
    return next;
}

export function applyLawsuitArchiveSegments(
    segments: LawsuitFileSegments,
    fileId: string | number,
): LawsuitFileSegments {
    const idStr = String(fileId);
    const file = segments.active.find((f) => String(f.id) === idStr);
    if (!file) return segments;
    const archived = { ...file, status: 'archived' as const };
    const nextActive = segments.active.filter((f) => String(f.id) !== idStr);
    const existingArchived = resolveArchivedForMutation(segments).filter(
        (f) => String(f.id) !== idStr,
    );
    const nextArchived = [...existingArchived, archived];
    const nextIndex = applyLawsuitIndexStatusChange(
        segments.index,
        idStr,
        'active',
        'archived',
        buildLawsuitIndexEntryFromFile(archived),
    );
    const next: LawsuitFileSegments = {
        active: nextActive,
        archived: nextArchived,
        trash: segments.trash,
        index: nextIndex,
    };
    return next;
}

export function applyLawsuitRestoreFromArchiveSegments(
    segments: LawsuitFileSegments,
    fileId: string | number,
): LawsuitFileSegments {
    const idStr = String(fileId);
    const archived = resolveArchivedForMutation(segments);
    const file = archived.find((f) => String(f.id) === idStr);
    if (!file) return segments;
    const restored = { ...file, status: 'active' as const };
    const nextArchived = archived.filter((f) => String(f.id) !== idStr);
    const nextActive = [restored, ...segments.active];
    const nextIndex = applyLawsuitIndexStatusChange(
        segments.index,
        idStr,
        'archived',
        'active',
        buildLawsuitIndexEntryFromFile(restored),
    );
    const next: LawsuitFileSegments = {
        active: nextActive,
        archived: nextArchived,
        trash: segments.trash,
        index: nextIndex,
    };
    return next;
}

export function applyLawsuitPermanentDeleteSegments(
    segments: LawsuitFileSegments,
    ids: Array<string | number>,
): LawsuitFileSegments {
    const idSet = new Set(ids.map(String));
    const trash = resolveTrashForMutation(segments);
    const nextTrash = trash.filter((f) => !idSet.has(String(f.id)));
    const archived = resolveArchivedForMutation(segments);
    const nextArchived = archived.filter((f) => !idSet.has(String(f.id)));
    const nextActive = segments.active.filter((f) => !idSet.has(String(f.id)));
    let nextIndex = segments.index;
    for (const id of ids) {
        nextIndex = removeLawsuitFromIndex(nextIndex, id);
    }
    const next: LawsuitFileSegments = {
        active: nextActive,
        archived: segments.archived === null && nextArchived === archived
            ? null
            : nextArchived,
        trash: nextTrash,
        index: nextIndex,
    };
    return next;
}

/**
 * توحيد دعويين: المحدّثة تبقى في active، والثانوية تُpersist في مقطع archived
 * (لا تُحقَن عبر persistLawsuitFiles في المقطع النشط).
 */
export function applyLawsuitConsolidationSegments(
    segments: LawsuitFileSegments,
    mergedPrimary: FileData,
    archivedSecondary: FileData,
): LawsuitFileSegments {
    const primaryId = String(mergedPrimary.id);
    const secondaryId = String(archivedSecondary.id);
    const archivedFile: FileData = { ...archivedSecondary, status: 'archived' };

    let nextActive = segments.active
        .filter((f) => String(f.id) !== secondaryId)
        .map((f) => (String(f.id) === primaryId ? mergedPrimary : f));
    if (!nextActive.some((f) => String(f.id) === primaryId)) {
        nextActive = [mergedPrimary, ...nextActive];
    }

    const nextArchived = [
        archivedFile,
        ...resolveArchivedForMutation(segments).filter(
            (f) => String(f.id) !== secondaryId && String(f.id) !== primaryId,
        ),
    ];
    const nextTrash = resolveTrashForMutation(segments).filter(
        (f) => String(f.id) !== secondaryId,
    );
    const nextIndex = buildLawsuitLifecycleIndex(nextActive, nextArchived, nextTrash);
    const next: LawsuitFileSegments = {
        active: nextActive,
        archived: nextArchived,
        trash: nextTrash,
        index: nextIndex,
    };
    persistLawsuitActiveBundle({
        active: nextActive,
        index: nextIndex,
        archived: nextArchived,
        trash: nextTrash,
        options: { allowShrink: true },
    });
    persistLawsuitArchivedSegment(nextArchived);
    persistLawsuitTrashSegment(nextTrash);
    pruneLawsuitDurabilityOverlaysForFileIds([secondaryId]);
    return next;
}

export function findLawsuitFileInSegments(
    segments: LawsuitFileSegments,
    fileId: string | number,
): FileData | undefined {
    const idStr = String(fileId);
    return (
        segments.active.find((f) => String(f.id) === idStr) ??
        resolveArchivedForMutation(segments).find((f) => String(f.id) === idStr) ??
        resolveTrashForMutation(segments).find((f) => String(f.id) === idStr)
    );
}

import SecureStoreService from '@/app/services/SecureStoreService';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import {
    excludeLawsuitIdsBySet,
    lawsuitActiveIdSet,
    mergeRicherLawsuitActive,
    mergeRicherLawsuitActiveRespectingHeldIds,
} from './lawsuitActiveDurability';
import { mergeLawsuitDurabilityOverlaysInto } from './lawsuitDurabilityOverlay';
import type { FileData } from './lawsuitFileTypes';
import type { LawsuitFileSegments } from './lawsuitFileSegments';
import {
    rebuildActiveSegmentInIndex,
    type LawsuitLifecycleIndex,
} from './lawsuitLifecycleIndex';
import { lawsuitSegmentsNeedWarm } from './lawsuitSegmentStorage';
import { readLawsuitDossierTombstoneIds } from '@/app/utils/lawsuitDossierTombstones';

function lifecycleIndexHoldsOutOfActive(
    index: LawsuitLifecycleIndex | null | undefined,
    id: string,
): boolean {
    const status = index?.entries?.[id]?.status;
    return status === 'deleted' || status === 'archived';
}

export function bootHasLawsuitRecords(boot: LawsuitFileSegments): boolean {
    return (
        boot.active.length > 0 ||
        boot.index.counts.active > 0 ||
        boot.index.counts.archived > 0 ||
        boot.index.counts.trash > 0
    );
}

/** لا تُكتب مصفوفة نشطة فارغة فوق قرص قد يحمل بيانات باردة أو فهرساً غير صفري */
export function shouldBlockEmptyLawsuitPersist(next: LawsuitFileSegments): boolean {
    if (next.active.length > 0) return false;
    if (lawsuitSegmentsNeedWarm()) return true;
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)) return true;
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_INDEX_KEY)) return true;
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_STORAGE_KEY)) return true;
    const counts = next.index.counts;
    return counts.active > 0 || counts.archived > 0 || counts.trash > 0;
}

function toIdSet(
    preferActiveIds?: ReadonlySet<string> | readonly FileData[] | null,
): Set<string> {
    if (!preferActiveIds) return new Set();
    if (Array.isArray(preferActiveIds)) {
        return lawsuitActiveIdSet(preferActiveIds as readonly FileData[]);
    }
    return new Set(preferActiveIds as ReadonlySet<string>);
}

/**
 * معرّفات خارج النشط عمداً.
 *
 * قواعد صارمة (منع المسح الذاتي):
 * - tombstone فقط (ليس في النشط) → يُمسك دائماً (حذف نهائي)
 * - tombstone ∩ نشط → **لا يُمسك** (شاهد فاسد؛ فضّل النشط)
 * - أرشيف فقط → يُمسك (النقل للأرشيف مقصود)
 * - أرشيف ∩ نشط → **لا يُمسك** (تكرار فاشل؛ فضّل النشط)
 * - سلة ∩ نشط → **لا يُمسك** (تكرار فاشل؛ فضّل النشط)
 * - سلة فقط → يُمسك
 * - فهرس status وحده + ليس في النشط المرشّح → يُمسك (مهم عند المقاطع الكسولة)
 * - فهرس قديم ∩ نشط مرشّح → النشط يفوز، فلا يسبب مسحاً
 */
export function collectHeldOutOfActiveIds(input: {
    archived?: FileData[] | null;
    trash?: FileData[] | null;
    index?: LawsuitLifecycleIndex | null;
    includeTombstones?: boolean;
    /** إضابير ما زالت في المرشّح النشط — لا تُخرجها بسبب صف مكرّر في السلة/الأرشيف */
    preferActiveIds?: ReadonlySet<string> | readonly FileData[] | null;
}): Set<string> {
    const preferActive = toIdSet(input.preferActiveIds);
    const held = new Set<string>();

    for (const row of input.trash ?? []) {
        const id = String(row.id ?? '').trim();
        if (!id) continue;
        if (preferActive.has(id)) continue;
        held.add(id);
    }
    for (const row of input.archived ?? []) {
        const id = String(row.id ?? '').trim();
        if (!id) continue;
        if (preferActive.has(id)) continue;
        held.add(id);
    }
    for (const entry of Object.values(input.index?.entries ?? {})) {
        if (entry.status !== 'archived' && entry.status !== 'deleted') continue;
        const id = String(entry.id ?? '').trim();
        if (!id || preferActive.has(id)) continue;
        held.add(id);
    }

    if (input.includeTombstones !== false) {
        try {
            for (const id of readLawsuitDossierTombstoneIds()) {
                /*
                 * tombstone ∩ نشط حي = شاهد قديم/فاسد. فضّل النشط حتى لا
                 * يُفرَّغ المخزن عند كل reload. الحذف النهائي يزيل من النشط أولاً.
                 */
                if (preferActive.has(id)) continue;
                held.add(id);
            }
        } catch {
            /* ignore */
        }
    }
    return held;
}

/** أزل من السلة أي معرّف ما زال في النشط — شفاء تكرار فاشل */
export function healLawsuitTrashAgainstActive(
    active: readonly FileData[],
    trash: readonly FileData[] | null | undefined,
): FileData[] | null {
    if (trash == null) return trash ?? null;
    if (trash.length === 0) return trash as FileData[];
    const activeIds = lawsuitActiveIdSet(active);
    if (activeIds.size === 0) return [...trash];
    const next = trash.filter((row) => !activeIds.has(String(row.id ?? '').trim()));
    return next.length === trash.length ? [...trash] : next;
}

/** أزل من الأرشيف أي معرّف ما زال في النشط — شفاء تكرار فاشل */
export function healLawsuitArchivedAgainstActive(
    active: readonly FileData[],
    archived: readonly FileData[] | null | undefined,
): FileData[] | null {
    if (archived == null) return archived ?? null;
    if (archived.length === 0) return archived as FileData[];
    const activeIds = lawsuitActiveIdSet(active);
    if (activeIds.size === 0) return [...archived];
    const next = archived.filter((row) => !activeIds.has(String(row.id ?? '').trim()));
    return next.length === archived.length ? [...archived] : next;
}

/**
 * دمج مقطع سلة/أرشيف: لا تُعد إحياء صفوف أُزيلت عمداً (حذف نهائي / تقلّص prev).
 */
export function mergeLawsuitLifecycleSegmentLists(
    boot: FileData[] | null,
    prev: FileData[] | null,
    permanentlyRemovedIds: ReadonlySet<string>,
): FileData[] | null {
    if (boot === null && prev === null) return null;
    if (boot === null) return excludeLawsuitIdsBySet(prev ?? [], permanentlyRemovedIds);
    if (prev === null) return excludeLawsuitIdsBySet(boot, permanentlyRemovedIds);

    const prevIds = lawsuitActiveIdSet(prev);
    const bootIds = lawsuitActiveIdSet(boot);
    let prevSubsetOfBoot = true;
    for (const id of prevIds) {
        if (!bootIds.has(id)) {
            prevSubsetOfBoot = false;
            break;
        }
    }
    if (prev.length < boot.length && prevSubsetOfBoot) {
        return excludeLawsuitIdsBySet(prev, permanentlyRemovedIds);
    }

    return excludeLawsuitIdsBySet(mergeRicherLawsuitActive(boot, prev), permanentlyRemovedIds);
}

/**
 * لا تُعد إحياء معرّف نُقل للسلة/الأرشيف أو حُذف نهائياً عند دمج boot مع الحالة الحالية.
 */
export function pickRicherLawsuitSegments(
    prev: LawsuitFileSegments,
    boot: LawsuitFileSegments,
): LawsuitFileSegments {
    const tombstoned = (() => {
        try {
            return readLawsuitDossierTombstoneIds();
        } catch {
            return new Set<string>();
        }
    })();

    /*
     * فضّل النشط فقط إن:
     * - الجلسة (prev) تعتبره نشطاً، و
     * - الفهرس لا يقول إنه في السلة/الأرشيف.
     * overlay/hydrate قد يضعان الملف في prev.active بينما القرص في السلة —
     * تفضيل prev كان يعيد البطاقة بعد Reload مع بقاء القرص صحيحاً.
     */
    const preferActive = new Set<string>();
    for (const id of lawsuitActiveIdSet(prev.active)) {
        if (lifecycleIndexHoldsOutOfActive(boot.index, id)) continue;
        if (lifecycleIndexHoldsOutOfActive(prev.index, id)) continue;
        preferActive.add(id);
    }
    const bootTrashIds = lawsuitActiveIdSet(boot.trash ?? []);
    for (const row of boot.active) {
        const id = String(row.id ?? '').trim();
        if (id && bootTrashIds.has(id) && !lifecycleIndexHoldsOutOfActive(boot.index, id)) {
            preferActive.add(id);
        }
    }

    const held = collectHeldOutOfActiveIds({
        archived: boot.archived ?? prev.archived,
        trash: boot.trash ?? prev.trash,
        index: boot.index ?? prev.index,
        includeTombstones: true,
        preferActiveIds: preferActive,
    });
    for (const id of collectHeldOutOfActiveIds({
        archived: prev.archived,
        trash: prev.trash,
        index: prev.index,
        includeTombstones: true,
        preferActiveIds: preferActive,
    })) {
        held.add(id);
    }

    const active = excludeLawsuitIdsBySet(
        mergeRicherLawsuitActiveRespectingHeldIds(boot.active, prev.active, held),
        held,
    );

    let archived = mergeLawsuitLifecycleSegmentLists(boot.archived, prev.archived, tombstoned);
    let trash = mergeLawsuitLifecycleSegmentLists(boot.trash, prev.trash, tombstoned);
    trash = healLawsuitTrashAgainstActive(active, trash);
    archived = healLawsuitArchivedAgainstActive(active, archived);

    if (
        active.length === boot.active.length &&
        active.every((row, i) => String(row.id) === String(boot.active[i]?.id)) &&
        archived === boot.archived &&
        trash === boot.trash
    ) {
        return boot;
    }

    return {
        active,
        archived,
        trash,
        index: rebuildActiveSegmentInIndex(boot.index, active),
    };
}

/**
 * قائمة eager-hydrate ليست مصدر حقيقة للنشط.
 * تُدمج فقط بعد إخراج معرّفات السلة/الأرشيف/الشواهد حتى لا تُبعث إضبارة
 * من lawyer_files / المرآة بينما القرص يحملها في المهملات.
 */
export function adoptHydratedLawsuitActive(
    boot: LawsuitFileSegments,
    hydrated: readonly FileData[],
): LawsuitFileSegments {
    const held = collectHeldOutOfActiveIds({
        archived: boot.archived,
        trash: boot.trash,
        index: boot.index,
        includeTombstones: true,
        preferActiveIds: boot.active,
    });
    const hydratedActive = excludeLawsuitIdsBySet(
        hydrated.length > 0 ? mergeLawsuitDurabilityOverlaysInto([...hydrated]) : [],
        held,
    );
    const active = excludeLawsuitIdsBySet(
        mergeRicherLawsuitActiveRespectingHeldIds(boot.active, hydratedActive, held),
        held,
    );
    return {
        ...boot,
        active,
        trash: healLawsuitTrashAgainstActive(active, boot.trash),
        archived: healLawsuitArchivedAgainstActive(active, boot.archived),
        index: rebuildActiveSegmentInIndex(boot.index, active),
    };
}

/** pending + WAL فوق مقاطع الإقلاع دون كتابة */
export function applyLawsuitDurabilityOverlaysToSegments(
    boot: LawsuitFileSegments,
): LawsuitFileSegments {
    const mergedSeed = mergeLawsuitDurabilityOverlaysInto(boot.active);
    const held = collectHeldOutOfActiveIds({
        archived: boot.archived,
        trash: boot.trash,
        index: boot.index,
        includeTombstones: true,
        /*
         * النشط المثبت فقط يملك حق كسر حالة السلة/الأرشيف. WAL قديم ليس
         * دليلاً على الاستعادة؛ اعتباره preferActive كان يبعث المحذوف.
         */
        preferActiveIds: boot.active,
    });
    const active = excludeLawsuitIdsBySet(mergedSeed, held);
    if (active.length === boot.active.length) return boot;
    return {
        ...boot,
        active,
        trash: healLawsuitTrashAgainstActive(active, boot.trash),
        index: rebuildActiveSegmentInIndex(boot.index, active),
    };
}

import type { FileData } from './lawsuitFileTypes';

const MAX_HAYSTACK_CHARS = 640;

function partySearchBlob(parties: FileData['parties']): string {
    if (!Array.isArray(parties) || parties.length === 0) return '';
    return parties
        .map((p) => [p.name, p.phone, p.role].filter(Boolean).join(' '))
        .join(' ');
}

function noteSearchBlob(notes: FileData['notes']): string {
    if (!Array.isArray(notes) || notes.length === 0) return '';
    return notes.map((n) => n.text || '').join(' ');
}

/** نص بحث مضغوط — يُخزَّن في lifecycleIndex للمخزن/المهملات دون تحميل segment */
export function buildLawsuitIndexSearchHaystack(file: FileData): string {
    const client =
        file.parties?.find((p) => p.isClient)?.name || file.parties?.[0]?.name || '';
    const title = String((file as { title?: string }).title ?? '').trim();
    const jurisdictionHint =
        file.lawsuitJurisdiction === 'personal'
            ? 'أحوال شخصية'
            : file.lawsuitJurisdiction === 'civil'
              ? 'قضاء مدني'
              : '';
    const applicableLaw = String(
        (file as { applicableLaw?: string }).applicableLaw ??
            (file as { personalApplicableLaw?: string }).personalApplicableLaw ??
            '',
    ).trim();
    const blob = [
        file.caseNo,
        title,
        file.court,
        file.docType,
        file.judge,
        client,
        partySearchBlob(file.parties),
        noteSearchBlob(file.notes),
        jurisdictionHint,
        applicableLaw,
    ]
        .filter(Boolean)
        .join(' ');
    return blob.length > MAX_HAYSTACK_CHARS ? blob.slice(0, MAX_HAYSTACK_CHARS) : blob;
}

export function resolveLawsuitIndexClientName(file: FileData): string | undefined {
    const client = file.parties?.find((p) => p.isClient)?.name || file.parties?.[0]?.name;
    const trimmed = client?.trim();
    return trimmed || undefined;
}

/** تبويب أقسام مخزن الدعاوى: اختصاصات مدنية + الجزائي. */
export type LawsuitJurisdictionTab = 'all' | 'civil' | 'personal' | 'criminal';

type LawsuitJurisdiction = 'civil' | 'personal';

const PERSONAL_JURISDICTION_HINT =
    /أحوال|شخصية|زواج|طلاق|نفقة|حضانة|مهر|قانون\s*1959|قانون\s*2025/i;

export type LawsuitJurisdictionSource = {
    lawsuitJurisdiction?: string;
    selectedType?: string;
    court?: string;
    docType?: string;
    subInfo?: string;
};

/** يحدد اختصاص الدعوى للعرض في المخزن (محفوظ أو استنتاج من بيانات قديمة). */
export function resolveLawsuitJurisdiction(file: LawsuitJurisdictionSource): LawsuitJurisdiction {
    const raw = String(file.lawsuitJurisdiction ?? file.selectedType ?? '').toLowerCase();
    if (raw === 'personal') return 'personal';
    if (raw === 'civil') return 'civil';

    const hay = [file.court, file.docType, file.subInfo].filter(Boolean).join(' ');
    if (PERSONAL_JURISDICTION_HINT.test(hay)) return 'personal';
    return 'civil';
}

export function filterByLawsuitJurisdictionTab<T extends LawsuitJurisdictionSource>(
    files: T[],
    tab: LawsuitJurisdictionTab,
): T[] {
    if (tab === 'all') return files;
    return files.filter((f) => resolveLawsuitJurisdiction(f) === tab);
}

import type { FileData } from './lawsuitFileTypes';
import { isLawsuitArchived, isLawsuitInTrash } from '@/app/utils/lawsuitTrash';
import {
    buildLawsuitIndexSearchHaystack,
    resolveLawsuitIndexClientName,
} from './lawsuitIndexSearchHaystack';

type LawsuitLifecycleStatus = 'active' | 'archived' | 'deleted';

type LawsuitIndexEntry = {
    id: string;
    status: LawsuitLifecycleStatus;
    caseNo?: string;
    title?: string;
    type?: string;
    updatedAt?: number;
    court?: string;
    clientName?: string;
    /** أطراف + ملاحظات + محكمة — للبحث دون تحميل segment */
    searchHaystack?: string;
};

export type LawsuitLifecycleCounts = {
    active: number;
    archived: number;
    trash: number;
};

export type LawsuitLifecycleIndex = {
    v: 1;
    entries: Record<string, LawsuitIndexEntry>;
    counts: LawsuitLifecycleCounts;
};

export function emptyLawsuitLifecycleIndex(): LawsuitLifecycleIndex {
    return { v: 1, entries: {}, counts: { active: 0, archived: 0, trash: 0 } };
}

function lawsuitStatusFromFile(file: FileData | { status?: string }): LawsuitLifecycleStatus {
    if (isLawsuitInTrash(file)) return 'deleted';
    if (isLawsuitArchived(file)) return 'archived';
    return 'active';
}

export function buildLawsuitIndexEntryFromFile(file: FileData): LawsuitIndexEntry {
    const id = String(file.id);
    const status = lawsuitStatusFromFile(file);
    const entry: LawsuitIndexEntry = { id, status };
    if (file.caseNo) entry.caseNo = String(file.caseNo);
    const title = (file as { title?: string }).title;
    if (title) entry.title = String(title);
    if (file.court) entry.court = String(file.court);
    const clientName = resolveLawsuitIndexClientName(file);
    if (clientName) entry.clientName = clientName;
    const haystack = buildLawsuitIndexSearchHaystack(file);
    if (haystack) entry.searchHaystack = haystack;
    if (file.type) entry.type = String(file.type);
    const updatedAt = (file as { updatedAt?: number }).updatedAt;
    if (typeof updatedAt === 'number' && Number.isFinite(updatedAt)) entry.updatedAt = updatedAt;
    return entry;
}

function recomputeCounts(entries: Record<string, LawsuitIndexEntry>): LawsuitLifecycleCounts {
    let active = 0;
    let archived = 0;
    let trash = 0;
    for (const entry of Object.values(entries)) {
        if (entry.status === 'deleted') trash += 1;
        else if (entry.status === 'archived') archived += 1;
        else active += 1;
    }
    return { active, archived, trash };
}

export function buildLawsuitLifecycleIndex(
    active: FileData[],
    archived: FileData[],
    trash: FileData[],
): LawsuitLifecycleIndex {
    const entries: Record<string, LawsuitIndexEntry> = {};
    const add = (file: FileData) => {
        const entry = buildLawsuitIndexEntryFromFile(file);
        entries[entry.id] = entry;
    };
    active.forEach(add);
    archived.forEach(add);
    trash.forEach(add);
    return { v: 1, entries, counts: recomputeCounts(entries) };
}

export function applyLawsuitIndexStatusChange(
    index: LawsuitLifecycleIndex,
    id: string,
    from: LawsuitLifecycleStatus | null,
    to: LawsuitLifecycleStatus,
    patch?: Partial<LawsuitIndexEntry>,
): LawsuitLifecycleIndex {
    const idStr = String(id);
    const prev = index.entries[idStr];
    const fromStatus = from ?? prev?.status ?? null;
    const patchSansStatus: Partial<LawsuitIndexEntry> = patch ? { ...patch } : {};
    delete patchSansStatus.id;
    delete patchSansStatus.status;
    const nextEntry: LawsuitIndexEntry = {
        ...prev,
        ...patchSansStatus,
        id: idStr,
        status: to,
    };
    const entries = { ...index.entries, [idStr]: nextEntry };
    const counts = { ...index.counts };
    if (fromStatus === 'active') counts.active = Math.max(0, counts.active - 1);
    else if (fromStatus === 'archived') counts.archived = Math.max(0, counts.archived - 1);
    else if (fromStatus === 'deleted') counts.trash = Math.max(0, counts.trash - 1);
    if (to === 'active') counts.active += 1;
    else if (to === 'archived') counts.archived += 1;
    else if (to === 'deleted') counts.trash += 1;
    return { v: 1, entries, counts };
}

export function removeLawsuitFromIndex(index: LawsuitLifecycleIndex, id: string | number): LawsuitLifecycleIndex {
    const idStr = String(id);
    const prev = index.entries[idStr];
    if (!prev) return index;
    const entries = { ...index.entries };
    delete entries[idStr];
    const counts = { ...index.counts };
    if (prev.status === 'active') counts.active = Math.max(0, counts.active - 1);
    else if (prev.status === 'archived') counts.archived = Math.max(0, counts.archived - 1);
    else if (prev.status === 'deleted') counts.trash = Math.max(0, counts.trash - 1);
    return { v: 1, entries, counts };
}

export function upsertLawsuitIndexEntry(
    index: LawsuitLifecycleIndex,
    file: FileData,
): LawsuitLifecycleIndex {
    const entry = buildLawsuitIndexEntryFromFile(file);
    const prev = index.entries[entry.id];
    if (prev?.status === entry.status) {
        const entries = { ...index.entries, [entry.id]: { ...prev, ...entry } };
        return { v: 1, entries, counts: index.counts };
    }
    return applyLawsuitIndexStatusChange(index, entry.id, prev?.status ?? null, entry.status, entry);
}

/** تحديث إدخالات النشطة فقط — يحافظ على مخزن/مهملات في الفهرس عند boot بدون تحميلهما */
export function rebuildActiveSegmentInIndex(
    index: LawsuitLifecycleIndex,
    active: FileData[],
): LawsuitLifecycleIndex {
    const entries: Record<string, LawsuitIndexEntry> = {};
    for (const [id, entry] of Object.entries(index.entries)) {
        if (entry.status !== 'active') entries[id] = entry;
    }
    for (const file of active) {
        const entry = buildLawsuitIndexEntryFromFile(file);
        entries[entry.id] = entry;
    }
    return { v: 1, entries, counts: recomputeCounts(entries) };
}

/** يُحدّث metadata البحث عند تحميل مخزن/مهملات لأول مرة */
export function enrichLifecycleIndexFromSegmentFiles(
    index: LawsuitLifecycleIndex,
    archived: FileData[] | null | undefined,
    trash: FileData[] | null | undefined,
): LawsuitLifecycleIndex {
    let next = index;
    const merge = (files: FileData[]) => {
        for (const file of files) {
            next = upsertLawsuitIndexEntry(next, file);
        }
    };
    if (archived) merge(archived);
    if (trash) merge(trash);
    return next;
}

export type LawsuitLifecycleTarget = 'active' | 'archived' | 'deleted' | 'permanent';

const inFlightTargets = new Map<string, LawsuitLifecycleTarget>();

/**
 * يمنع autosave/سجل WAL من إعادة معرّف بينما معاملة دورة الحياة قيد COMMIT.
 * الواجهة تُحدَّث بعد القرص، لذلك تبقى الحالة القديمة مرئية لبضعة أجزاء من الثانية.
 */
export function beginLawsuitLifecycleMutationFence(
    ids: readonly (string | number)[],
    target: LawsuitLifecycleTarget,
): () => void {
    const normalized = [...new Set(ids.map(String).filter(Boolean))];
    for (const id of normalized) inFlightTargets.set(id, target);
    return () => {
        for (const id of normalized) {
            if (inFlightTargets.get(id) === target) inFlightTargets.delete(id);
        }
    };
}

/** معرّفات لا يجوز لأي كاتب نشط إعادتها أثناء المعاملة. */
export function readLawsuitLifecycleHeldFenceIds(): Set<string> {
    const held = new Set<string>();
    for (const [id, target] of inFlightTargets) {
        if (target !== 'active') held.add(id);
    }
    return held;
}

export function clearLawsuitLifecycleMutationFencesForTests(): void {
    if (!import.meta.env.VITEST) return;
    inFlightTargets.clear();
}

import SecureStoreService, {
    type SecureStoreAtomicWrite,
} from '@/app/services/SecureStoreService';
import { CryptoService } from '@/app/services/CryptoService';
import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_STORAGE_KEYS_LEGACY,
    LAWSUIT_FILES_TRASH_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import {
    clearLegacyPlaintextMirror,
    readSecureOrDrainLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';
import { LAWSUIT_DOSSIER_TOMBSTONES_KEY } from '@/app/utils/lawsuitDossierTombstones';
import {
    applyLawsuitArchiveSegments,
    applyLawsuitPermanentDeleteSegments,
    applyLawsuitRestoreFromArchiveSegments,
    applyLawsuitRestoreFromTrashSegments,
    applyLawsuitTrashSegments,
} from './lawsuitFilesSegmentMutations';
import {
    excludeLawsuitIdsBySet,
    lawsuitActiveIdSet,
    mergeRicherLawsuitActive,
    parseLawsuitActiveFiles,
} from './lawsuitActiveDurability';
import {
    collectHeldOutOfActiveIds,
    healLawsuitArchivedAgainstActive,
    healLawsuitTrashAgainstActive,
} from './lawsuitFilesStatePolicy';
import { buildLawsuitLifecycleIndex } from './lawsuitLifecycleIndex';
import type { LawsuitFileSegments } from './lawsuitFileSegments';
import { LAWSUIT_PENDING_CREATES_KEY } from './lawsuitPendingCreateStore';
import { LAWSUIT_WRITE_JOURNAL_KEY } from './lawsuitWriteJournal';
import { pruneLawsuitDurabilityOverlaysForFileIds } from './lawsuitDurabilityOverlay';
import { recordLawsuitLifecycleE2e } from '@/app/runtime/lawsuitLifecycleE2eProbe';

export type LawsuitLifecycleMutationKind =
    | 'trash'
    | 'archive'
    | 'restore-trash'
    | 'restore-archive'
    | 'permanent-delete';

export type LawsuitLifecycleTransactionResult = {
    ok: boolean;
    next?: LawsuitFileSegments;
    reason?: 'not-found' | 'unread' | 'invalid-transition' | 'write-failed' | 'verify-failed';
};

const SEGMENT_KEYS = [
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_TRASH_KEY,
    LAWSUIT_FILES_INDEX_KEY,
] as const;

const REQUIRED_KEYS = [
    ...SEGMENT_KEYS,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_DOSSIER_TOMBSTONES_KEY,
] as const;

const LIFECYCLE_KEYS = [
    ...SEGMENT_KEYS,
    LAWSUIT_FILES_STORAGE_KEY,
    ...LAWSUIT_FILES_STORAGE_KEYS_LEGACY,
    LAWSUIT_PENDING_CREATES_KEY,
    LAWSUIT_WRITE_JOURNAL_KEY,
    LAWSUIT_DOSSIER_TOMBSTONES_KEY,
] as const;

function readArray(key: string): unknown[] {
    const raw = readSecureOrDrainLegacySync(key);
    if (!raw?.trim()) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : [];
    } catch {
        return [];
    }
}

function uniqueIds(ids: readonly (string | number)[]): string[] {
    return [...new Set(ids.map((id) => String(id ?? '').trim()).filter(Boolean))];
}

function canonicalizeCurrent(current: LawsuitFileSegments): LawsuitFileSegments {
    const diskActive = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
    );
    const diskArchived = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_ARCHIVED_KEY),
    );
    const diskTrash = parseLawsuitActiveFiles(
        readSecureOrDrainLegacySync(LAWSUIT_FILES_TRASH_KEY),
    );

    const archivedSeed =
        current.archived === null
            ? diskArchived
            : mergeRicherLawsuitActive(current.archived, diskArchived);
    const trashSeed =
        current.trash === null
            ? diskTrash
            : mergeRicherLawsuitActive(current.trash, diskTrash);

    const held = collectHeldOutOfActiveIds({
        archived: archivedSeed,
        trash: trashSeed,
        index: current.index,
        includeTombstones: true,
        preferActiveIds: current.active,
    });
    const active = excludeLawsuitIdsBySet(
        mergeRicherLawsuitActive(current.active, diskActive),
        held,
    );
    let archived = healLawsuitArchivedAgainstActive(active, archivedSeed) ?? [];
    let trash = healLawsuitTrashAgainstActive(active, trashSeed) ?? [];

    /*
     * تلف قديم قد يضع المعرّف في archive وtrash معاً. الفهرس يحسم إن كان
     * صريحاً، وإلا السلة أحدث/أشد من الأرشيف فتحفظ نسخة واحدة هناك.
     */
    const archivedIds = lawsuitActiveIdSet(archived);
    const trashIds = lawsuitActiveIdSet(trash);
    for (const id of archivedIds) {
        if (!trashIds.has(id)) continue;
        if (current.index.entries[id]?.status === 'archived') {
            trash = trash.filter((row) => String(row.id) !== id);
        } else {
            archived = archived.filter((row) => String(row.id) !== id);
        }
    }

    return {
        active,
        archived,
        trash,
        index: buildLawsuitLifecycleIndex(active, archived, trash),
    };
}

function applyTransition(
    current: LawsuitFileSegments,
    kind: LawsuitLifecycleMutationKind,
    ids: readonly string[],
): LawsuitFileSegments {
    if (kind === 'permanent-delete') {
        return applyLawsuitPermanentDeleteSegments(current, [...ids]);
    }
    let next = current;
    for (const id of ids) {
        if (kind === 'trash') next = applyLawsuitTrashSegments(next, id);
        else if (kind === 'archive') next = applyLawsuitArchiveSegments(next, id);
        else if (kind === 'restore-trash') {
            next = applyLawsuitRestoreFromTrashSegments(next, id);
        } else {
            next = applyLawsuitRestoreFromArchiveSegments(next, id);
        }
    }
    return next;
}

type Placement = 'active' | 'archived' | 'deleted';

function placementMap(segments: LawsuitFileSegments): Map<string, Placement> | null {
    const placements = new Map<string, Placement>();
    const add = (rows: NonNullable<LawsuitFileSegments['archived']>, place: Placement) => {
        for (const row of rows) {
            const id = String(row.id ?? '').trim();
            if (!id) continue;
            if (placements.has(id)) return false;
            placements.set(id, place);
        }
        return true;
    };
    if (!add(segments.active, 'active')) return null;
    if (!add(segments.archived ?? [], 'archived')) return null;
    if (!add(segments.trash ?? [], 'deleted')) return null;
    return placements;
}

function expectedPlacement(kind: LawsuitLifecycleMutationKind): Placement | null {
    if (kind === 'trash') return 'deleted';
    if (kind === 'archive') return 'archived';
    if (kind === 'restore-trash' || kind === 'restore-archive') return 'active';
    return null;
}

function validateTransition(
    previous: LawsuitFileSegments,
    next: LawsuitFileSegments,
    kind: LawsuitLifecycleMutationKind,
    ids: readonly string[],
): boolean {
    const before = placementMap(previous);
    const after = placementMap(next);
    if (!before || !after) return false;
    const targetIds = new Set(ids);
    const expected = expectedPlacement(kind);

    for (const id of targetIds) {
        if (!before.has(id)) return false;
        if (expected === null) {
            if (after.has(id)) return false;
        } else if (after.get(id) !== expected) {
            return false;
        }
    }

    for (const [id, placement] of before) {
        if (targetIds.has(id)) continue;
        if (after.get(id) !== placement) return false;
    }
    for (const id of after.keys()) {
        if (!targetIds.has(id) && !before.has(id)) return false;
    }
    return true;
}

function filterPendingRows(ids: ReadonlySet<string>): unknown[] {
    return readArray(LAWSUIT_PENDING_CREATES_KEY).filter((row) => {
        if (!row || typeof row !== 'object') return false;
        return !ids.has(String((row as { id?: unknown }).id ?? ''));
    });
}

function filterJournalRows(ids: ReadonlySet<string>): unknown[] {
    return readArray(LAWSUIT_WRITE_JOURNAL_KEY).filter((row) => {
        if (!row || typeof row !== 'object') return false;
        return !ids.has(String((row as { fileId?: unknown }).fileId ?? ''));
    });
}

function nextTombstones(
    kind: LawsuitLifecycleMutationKind,
    ids: readonly string[],
): string[] | null {
    if (kind !== 'permanent-delete' && kind !== 'restore-trash' && kind !== 'restore-archive') {
        return null;
    }
    const set = new Set(readArray(LAWSUIT_DOSSIER_TOMBSTONES_KEY).map(String).filter(Boolean));
    if (kind === 'permanent-delete') {
        for (const id of ids) set.add(id);
    } else {
        for (const id of ids) set.delete(id);
    }
    return [...set];
}

function canOverwriteLifecycleKey(key: string): boolean {
    return !(SecureStoreService.hasItemSync(key) && SecureStoreService.isUnreadSync(key));
}

function arrayWrite(key: string, rows: unknown[]): SecureStoreAtomicWrite {
    return {
        key,
        value: JSON.stringify(rows),
        options: {
            allowShrink: true,
            allowVerifiedEmptyOverwrite: rows.length === 0,
        },
    };
}

function pushOptionalWrite(writes: SecureStoreAtomicWrite[], write: SecureStoreAtomicWrite): void {
    if (!canOverwriteLifecycleKey(write.key)) return;
    writes.push(write);
}

function buildAtomicWrites(
    next: LawsuitFileSegments,
    kind: LawsuitLifecycleMutationKind,
    ids: readonly string[],
): SecureStoreAtomicWrite[] {
    const archived = next.archived ?? [];
    const trash = next.trash ?? [];
    const index = buildLawsuitLifecycleIndex(next.active, archived, trash);
    const idSet = new Set(ids);
    const merged = [...next.active, ...archived, ...trash];
    const writes: SecureStoreAtomicWrite[] = [
        arrayWrite(LAWSUIT_FILES_ACTIVE_KEY, next.active),
        arrayWrite(LAWSUIT_FILES_ARCHIVED_KEY, archived),
        arrayWrite(LAWSUIT_FILES_TRASH_KEY, trash),
        {
            key: LAWSUIT_FILES_INDEX_KEY,
            value: JSON.stringify(index),
            options: { allowShrink: true },
        },
        arrayWrite(LAWSUIT_FILES_STORAGE_KEY, merged),
    ];
    for (const legacyKey of LAWSUIT_FILES_STORAGE_KEYS_LEGACY) {
        pushOptionalWrite(writes, arrayWrite(legacyKey, merged));
    }
    pushOptionalWrite(writes, arrayWrite(LAWSUIT_PENDING_CREATES_KEY, filterPendingRows(idSet)));
    pushOptionalWrite(writes, arrayWrite(LAWSUIT_WRITE_JOURNAL_KEY, filterJournalRows(idSet)));
    const tombstones = nextTombstones(kind, ids);
    if (tombstones) {
        writes.push(arrayWrite(LAWSUIT_DOSSIER_TOMBSTONES_KEY, tombstones));
    }
    return writes;
}

async function verifyAtomicWrites(writes: readonly SecureStoreAtomicWrite[]): Promise<boolean> {
    for (const write of writes) {
        let disk: string | null = null;
        for (let attempt = 0; attempt < 8; attempt += 1) {
            disk = await SecureStoreService.getItemFromDisk(write.key);
            if (disk === write.value) break;
            if (disk != null) {
                try {
                    if (JSON.stringify(JSON.parse(disk)) === JSON.stringify(JSON.parse(write.value))) {
                        break;
                    }
                } catch {
                    /* مقارنة نصية أدناه */
                }
            }
            await new Promise<void>((resolve) => {
                setTimeout(resolve, 25);
            });
        }
        if (disk !== write.value) {
            let parsedMatch = false;
            if (disk != null) {
                try {
                    parsedMatch =
                        JSON.stringify(JSON.parse(disk)) === JSON.stringify(JSON.parse(write.value));
                } catch {
                    parsedMatch = false;
                }
            }
            if (parsedMatch) continue;
            const raw = await SecureStoreService.peekRawFromDisk(write.key);
            const keyState = CryptoService.probeKeyState();
            let decryptErr = '';
            if (
                raw != null &&
                raw.startsWith('hami_enc_v2:') &&
                CryptoService.hasMasterKey()
            ) {
                try {
                    const plain = await CryptoService.decryptData(raw.slice('hami_enc_v2:'.length));
                    decryptErr = `direct=${plain.length}`;
                } catch (error) {
                    decryptErr =
                        error instanceof Error
                            ? `${error.name}:${error.message.slice(0, 48)}`
                            : 'decrypt';
                }
            }
            recordLawsuitLifecycleE2e('tx-verify-mismatch', {
                kind: undefined,
                ids: write.key,
                extra: `disk=${disk == null ? 'null' : String(disk.length)},want=${write.value.length},raw=${raw == null ? 'null' : `${raw.length}:${raw.slice(0, 12)}`},has=${keyState.has ? 1 : 0},pin=${keyState.pin},bits=${keyState.bits},bound=${keyState.bound || 'empty'},${decryptErr}`,
            });
            return false;
        }
    }
    return true;
}

function tombstoneKeysForKind(kind: LawsuitLifecycleMutationKind): readonly string[] {
    if (kind === 'permanent-delete' || kind === 'restore-trash' || kind === 'restore-archive') {
        return [LAWSUIT_DOSSIER_TOMBSTONES_KEY];
    }
    return [];
}

async function warmLifecycleKeys(kind: LawsuitLifecycleMutationKind): Promise<boolean> {
    const extraRead = tombstoneKeysForKind(kind);
    try {
        await SecureStoreService.ensureLawsuitKeysReady();
        await SecureStoreService.warmKeys([...LIFECYCLE_KEYS]);
        for (const key of [...SEGMENT_KEYS, ...extraRead]) {
            if (SecureStoreService.hasItemSync(key) && SecureStoreService.isUnreadSync(key)) {
                await SecureStoreService.getItem(key);
            }
        }
    } catch {
        return false;
    }
    const required: readonly string[] =
        kind === 'restore-trash' || kind === 'permanent-delete'
            ? [LAWSUIT_FILES_TRASH_KEY]
            : kind === 'restore-archive'
              ? [LAWSUIT_FILES_ARCHIVED_KEY]
              : [LAWSUIT_FILES_ACTIVE_KEY];
    const blocked = [...required, ...extraRead].filter(
        (key) => SecureStoreService.hasItemSync(key) && SecureStoreService.isUnreadSync(key),
    );
    if (blocked.length === 0) return true;
    recordLawsuitLifecycleE2e('tx-unread', {
        kind,
        extra: blocked.join(','),
    });
    return false;
}

/**
 * العقد الوحيد لعمليات سلة/أرشيف/استعادة/حذف نهائي:
 * hydrate → انتقال نقي → تحقق invariant → COMMIT ذري → تحقق من القرص.
 */
export async function executeLawsuitLifecycleTransaction(
    current: LawsuitFileSegments,
    kind: LawsuitLifecycleMutationKind,
    requestedIds: readonly (string | number)[],
): Promise<LawsuitLifecycleTransactionResult> {
    const ids = uniqueIds(requestedIds);
    if (ids.length === 0) return { ok: false, reason: 'not-found' };
    recordLawsuitLifecycleE2e('tx-start', { kind, ids: ids.join(',') });
    SecureStoreService.acquireAtomicWriteBarriers(LIFECYCLE_KEYS);
    let masterKeyPinned = false;
    try {
        if (!(await warmLifecycleKeys(kind))) {
            return { ok: false, reason: 'unread' };
        }

        const previous = canonicalizeCurrent(current);
        const transitioned = applyTransition(previous, kind, ids);
        const next: LawsuitFileSegments = {
            active: transitioned.active,
            archived: transitioned.archived ?? [],
            trash: transitioned.trash ?? [],
            index: buildLawsuitLifecycleIndex(
                transitioned.active,
                transitioned.archived ?? [],
                transitioned.trash ?? [],
            ),
        };
        if (!validateTransition(previous, next, kind, ids)) {
            const reason = ids.some((id) => placementMap(previous)?.has(id))
                ? 'invalid-transition'
                : 'not-found';
            recordLawsuitLifecycleE2e('tx-validate', {
                kind,
                reason,
                ids: ids.join(','),
                extra: `active=${previous.active.length},trash=${previous.trash?.length ?? 0}`,
            });
            return { ok: false, reason };
        }

        /*
         * أزل pending/WAL من الذاكرة قبل بناء الكتابات حتى لا تُحذف مفاتيح
         * اختيارية بعد أن تُكتب [] في COMMIT.
         */
        if (kind === 'trash' || kind === 'archive' || kind === 'permanent-delete') {
            pruneLawsuitDurabilityOverlaysForFileIds(ids);
        }

        const writes = buildAtomicWrites(next, kind, ids);
        const required = writes.filter((write) =>
            (REQUIRED_KEYS as readonly string[]).includes(write.key),
        );
        const optional = writes.filter(
            (write) => !(REQUIRED_KEYS as readonly string[]).includes(write.key),
        );
        /*
         * ألغِ مؤقتات الكاتب القديم قبل COMMIT؛ وإلا قد يصل payload سابق بعد
         * المعاملة. لا نغيّر قرصاً هنا، فقط كاش LocalStorageRepository.
         */
        for (const write of writes) {
            persistenceRepository.synchronizeExternalWrite(
                write.key,
                readSecureOrDrainLegacySync(write.key),
            );
        }

        try {
            if (!CryptoService.hasMasterKey()) {
                await CryptoService.initialize();
            }
            if (!CryptoService.hasMasterKey()) {
                recordLawsuitLifecycleE2e('tx-crypto', { kind, ids: ids.join(',') });
                return { ok: false, reason: 'write-failed' };
            }
            CryptoService.pinMasterKeyForAtomicWrite();
            masterKeyPinned = true;
            await SecureStoreService.setItemsAtomically(required);
        } catch (error) {
            recordLawsuitLifecycleE2e('tx-write-failed', {
                kind,
                ids: ids.join(','),
                extra:
                    error instanceof Error
                        ? `${error.message}${error.cause != null ? ` | ${String(error.cause)}` : ''}`
                        : 'write',
            });
            return { ok: false, reason: 'write-failed' };
        }

        for (const write of required) {
            persistenceRepository.synchronizeExternalWrite(write.key, write.value);
            clearLegacyPlaintextMirror(write.key);
        }
        if (!(await verifyAtomicWrites(required))) {
            recordLawsuitLifecycleE2e('tx-verify-failed', { kind, ids: ids.join(',') });
            return { ok: false, reason: 'verify-failed' };
        }

        if (optional.length > 0) {
            for (const write of optional) {
                try {
                    await SecureStoreService.setItemsAtomically([write]);
                    persistenceRepository.synchronizeExternalWrite(write.key, write.value);
                    clearLegacyPlaintextMirror(write.key);
                } catch {
                    recordLawsuitLifecycleE2e('tx-optional-skipped', {
                        kind,
                        ids: ids.join(','),
                        extra: write.key,
                    });
                }
            }
        }
        recordLawsuitLifecycleE2e('tx-ok', { kind, ids: ids.join(',') });
        return { ok: true, next };
    } finally {
        if (masterKeyPinned) CryptoService.unpinMasterKeyForAtomicWrite();
        SecureStoreService.releaseAtomicWriteBarriers();
    }
}

/**
 * حارس صفحة الإنشاء: لا يُمسح pending/WAL في نفس تحميل الصفحة التي أنشأت الإضبارة.
 * إثبات القرص في الجلسة الحالية يكذب بعد Reload يقتل تشفير IndexedDB أو كتابة أقدم تسبق.
 * المسح مسموح فقط بعد إقلاع صفحة جديدة (module reload) ثم إثبات القرص.
 */

const stagedThisPage = new Set<string>();
const journaledThisPage = new Set<string>();

export function markLawsuitStagedThisPage(fileId: string | number): void {
    const id = String(fileId);
    if (id) stagedThisPage.add(id);
}

export function wasLawsuitStagedThisPage(fileId: string | number): boolean {
    return stagedThisPage.has(String(fileId));
}

export function markLawsuitJournaledThisPage(fileId: string | number): void {
    const id = String(fileId);
    if (id) journaledThisPage.add(id);
}

export function wasLawsuitJournaledThisPage(fileId: string | number): boolean {
    return journaledThisPage.has(String(fileId));
}

/** اختبارات: محاكاة Reload — يفرّغ حارس الصفحة دون مسح localStorage */
export function resetLawsuitPageWriteGuardForTests(): void {
    if (!import.meta.env.VITEST) return;
    stagedThisPage.clear();
    journaledThisPage.clear();
}

/** طرف إضبارة أو نموذج إنشاء — صفة من `role` أو `status`. */
export type LawsuitPartyRoleRecord = {
    id?: unknown;
    role?: unknown;
    status?: unknown;
    side?: unknown;
};

function partyRoleText(p: LawsuitPartyRoleRecord): string {
    return String(p.role ?? p.status ?? '')
        .trim()
        .toLowerCase();
}

function partySideText(p: LawsuitPartyRoleRecord): string {
    return String(p.side ?? '')
        .trim()
        .toLowerCase();
}

function partyRoleRaw(p: LawsuitPartyRoleRecord): string {
    return String(p.role ?? p.status ?? '').trim();
}

/** مستأنف عليه / مميز عليه — قبل فحص «مدعي» داخل الأقواس */
function isAppealAppelleeLabel(role: string): boolean {
    const r = role.trim();
    return (
        r.includes('المستأنف عليه')
        || r.includes('مستأنف عليه')
        || r.includes('المميز عليه')
        || r.includes('مميز عليه')
        || r.includes('المعترض عليه')
    );
}

function isAppealAppellantLabel(role: string): boolean {
    const r = role.trim();
    if (isAppealAppelleeLabel(r)) return false;
    return (
        r.includes('المستأنف')
        || r.includes('مستأنف')
        || r.includes('المميز')
        || r.includes('مميز')
        || r.includes('المعترض على الحكم')
        || (r.includes('معترض') && r.includes('على الحكم') && !r.includes('المعترض عليه'))
    );
}

export function isLawsuitPlaintiffRecord(p: LawsuitPartyRoleRecord): boolean {
    const raw = partyRoleRaw(p);
    const role = partyRoleText(p);
    const side = partySideText(p);

    if (isAppealAppelleeLabel(raw)) return false;
    if (isAppealAppellantLabel(raw)) return true;

    if (role === 'plaintiff' || role === 'client' || role === 'creditor') return true;
    if (side === 'right' || side === '1' || side === 'plaintiff') return true;
    /* مدعي دون مدعى — بعد استبعاد المستأنف عليه (المدعي) أعلاه */
    if (role.includes('مدعي') && !role.includes('مدعى')) return true;
    if (role.includes('دائن')) return true;
    return false;
}

export function isLawsuitDefendantRecord(p: LawsuitPartyRoleRecord): boolean {
    const raw = partyRoleRaw(p);
    const role = partyRoleText(p);
    const side = partySideText(p);

    if (isAppealAppelleeLabel(raw)) return true;
    if (isAppealAppellantLabel(raw)) return false;

    if (role === 'defendant' || role === 'opponent' || role === 'debtor') return true;
    if (side === 'left' || side === '2' || side === 'defendant') return true;
    if (role.includes('مدعى') || role.includes('مدين') || role.includes('خصم')) return true;
    return false;
}

export function normalizeLawsuitPartyRoleLabel(raw: string, fallback: string): string {
    const role = raw.trim();
    if (!role) return fallback;
    const lower = role.toLowerCase();
    if (lower === 'plaintiff' || lower === 'client' || lower === 'creditor') return 'المدعي';
    if (lower === 'defendant' || lower === 'opponent' || lower === 'debtor') return 'المدعى عليه';
    /* أبقِ تسمية الطعن الكاملة إن وُجدت — أوضح من «المدعي» وحده */
    if (isAppealAppelleeLabel(role) || isAppealAppellantLabel(role)) return role;
    return role;
}

export function partitionLawsuitPartiesByRole<T extends LawsuitPartyRoleRecord>(
    parties: T[],
): { plaintiffs: T[]; defendants: T[] } {
    const plaintiffs = parties.filter(isLawsuitPlaintiffRecord);
    const plaintiffIds = new Set(
        plaintiffs
            .map((p) => String(p.id ?? '').trim())
            .filter(Boolean),
    );
    const defendants = parties.filter((p) => {
        if (!isLawsuitDefendantRecord(p)) return false;
        const id = String(p.id ?? '').trim();
        if (id && plaintiffIds.has(id)) return false;
        return true;
    });
    return { plaintiffs, defendants };
}

import type { FileData } from './lawsuitFileTypes';
import { awaitLawsuitWorkspaceCommit } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import SecureStoreService from '@/app/services/SecureStoreService';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import { mergeRicherLawsuitActive } from '@/app/domain/lawsuit/lawsuitActiveDurability';
import { markLawsuitStagedThisPage } from '@/app/domain/lawsuit/lawsuitPageWriteGuard';
import {
    clearSecureJsonValue,
    readSecureJsonRawSync,
    writeSecureJsonValue,
} from '@/app/services/storage/syncSecureJson';

/**
 * مخزن إنشاء معلّق — مشفّر في SecureStore (نسخ FileData).
 * ليس في قشرة الإقلاع ولا PROTECTED_WARM. `flush` يفكّ المفتاح إن كان بارداً.
 * لا يُمسح إلا بعد تثبيت القرص (IndexedDB) — وإلا تختفي الإضبارة عند إعادة التحميل.
 */
export const LAWSUIT_PENDING_CREATES_KEY = 'hami_lawsuit_pending_creates_v1';

const PENDING_CAP = 40;

function parseFiles(raw: string | null): FileData[] {
    if (!raw?.trim()) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? (parsed as FileData[]) : [];
    } catch {
        return [];
    }
}

function clearSessionLeftover(): void {
    if (typeof sessionStorage === 'undefined') return;
    try {
        sessionStorage.removeItem(LAWSUIT_PENDING_CREATES_KEY);
    } catch {
        /* ignore */
    }
}

function peekSessionLeftover(): FileData[] {
    if (typeof sessionStorage === 'undefined') return [];
    try {
        return parseFiles(sessionStorage.getItem(LAWSUIT_PENDING_CREATES_KEY));
    } catch {
        return [];
    }
}

function takeSessionLeftover(): FileData[] {
    const files = peekSessionLeftover();
    if (files.length > 0) clearSessionLeftover();
    return files;
}

function readRaw(): FileData[] {
    const unread = SecureStoreService.isUnreadSync(LAWSUIT_PENDING_CREATES_KEY);
    const fromSecure = parseFiles(readSecureJsonRawSync(LAWSUIT_PENDING_CREATES_KEY));
    const fromSession = unread ? peekSessionLeftover() : takeSessionLeftover();
    if (fromSession.length === 0) return fromSecure;
    const merged = mergeRicherLawsuitActive(fromSecure, fromSession);
    if (!unread && merged.length > 0) {
        writeSecureJsonValue(LAWSUIT_PENDING_CREATES_KEY, merged);
    }
    return merged;
}

function writeRaw(files: FileData[]): void {
    if (files.length === 0) {
        if (SecureStoreService.isUnreadSync(LAWSUIT_PENDING_CREATES_KEY)) return;
        clearSecureJsonValue(LAWSUIT_PENDING_CREATES_KEY);
        clearSessionLeftover();
        return;
    }
    writeSecureJsonValue(LAWSUIT_PENDING_CREATES_KEY, files);
    clearSessionLeftover();
}

export function clearLawsuitPendingCreatesForTests(): void {
    clearSecureJsonValue(LAWSUIT_PENDING_CREATES_KEY);
    clearSessionLeftover();
}

export async function settleLawsuitPendingPersist(): Promise<void> {
    await SecureStoreService.waitForPendingSetItem(LAWSUIT_PENDING_CREATES_KEY);
}

export function stagePendingLawsuitCreate(file: FileData): void {
    const id = String(file.id);
    markLawsuitStagedThisPage(id);
    const next = [file, ...readRaw().filter((f) => String(f.id) !== id)].slice(0, PENDING_CAP);
    try {
        writeRaw(next);
        if (listPendingLawsuitCreates().some((row) => String(row.id) === id)) return;
    } catch {
        /* fall through to lite */
    }
    const lite: FileData = {
        ...file,
        history: Array.isArray(file.history) ? file.history.slice(0, 8) : [],
        notes: [],
        images: [],
    };
    writeRaw([lite, ...readRaw().filter((f) => String(f.id) !== id)].slice(0, PENDING_CAP));
}

export function listPendingLawsuitCreates(): FileData[] {
    return readRaw();
}

export function clearPendingLawsuitCreate(fileId: string | number): void {
    const id = String(fileId);
    writeRaw(readRaw().filter((f) => String(f.id) !== id));
}

export function mergePendingLawsuitCreatesInto(active: FileData[]): FileData[] {
    const pending = readRaw();
    if (pending.length === 0) return active;
    return mergeRicherLawsuitActive(active, pending);
}

/**
 * بعد تسخين المفاتيح: ادمج المعلّق في المقطع النشط وثبّت القرص.
 * لا يُمسح المعلّق إلا بعد تحقق القرص — لا بعد ذاكرة sync.
 */
export async function flushPendingLawsuitCreatesToActive(): Promise<number> {
    if (SecureStoreService.isUnreadSync(LAWSUIT_PENDING_CREATES_KEY)) {
        await SecureStoreService.getItem(LAWSUIT_PENDING_CREATES_KEY);
    }
    const pending = readRaw();
    if (pending.length === 0) return 0;
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)) return 0;

    const {
        loadLawsuitBootSegments,
        persistLawsuitFiles,
    } = await import('@/app/domain/lawsuit/lawsuitFilesRepository');
    const boot = loadLawsuitBootSegments().active;
    const merged = mergeRicherLawsuitActive(boot, pending);
    persistLawsuitFiles(merged);

    /* ديناميكي: كسر دائرة Pending → Verify → Pending عند تهيئة الوحدة */
    const { tryClearPendingLawsuitCreateAfterProof } = await import(
        '@/app/domain/lawsuit/lawsuitDurabilityVerify'
    );
    let cleared = 0;
    for (const row of pending) {
        const commit = await awaitLawsuitWorkspaceCommit({
            timeoutMs: 8_000,
            requireActiveFileId: row.id,
        });
        const didClear = await tryClearPendingLawsuitCreateAfterProof(row.id, commit);
        if (didClear) cleared += 1;
    }
    return cleared;
}

import SecureStoreService from '@/app/services/SecureStoreService';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_TRASH_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import {
    isPoorerLawsuitActiveList,
    mergeRicherLawsuitActiveRespectingHeldIds,
    parseLawsuitActiveFiles,
} from './lawsuitActiveDurability';
import { collectHeldOutOfActiveIds } from './lawsuitFilesStatePolicy';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';
import { readLawsuitDossierTombstoneIds } from '@/app/utils/lawsuitDossierTombstones';

const LAWSUIT_DURABLE_KEYS = [
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_TRASH_KEY,
] as const;

/** مهلة انتظار الطابور — إنشاء دعوى يحتاج تثبيتاً موثوقاً لا UX فقط */
export const LAWSUIT_FLUSH_TIMEOUT_MS = 5_000;
export const LAWSUIT_COMMIT_TIMEOUT_MS = 8_000;
export const LAWSUIT_COMMIT_DEBOUNCE_MS = 400;

export type LawsuitCommitOptions = {
    timeoutMs?: number;
    /** إن وُجد: يجب أن يظهر هذا المعرّف في المقطع النشط على القرص */
    requireActiveFileId?: string | number | null;
    debounceMs?: number;
};

export type LawsuitCommitResult = {
    ok: boolean;
    reason?: 'timeout' | 'verify-failed' | 'write-failed';
};

function raceWithTimeout(work: Promise<void>, timeoutMs: number): Promise<boolean> {
    if (timeoutMs <= 0) {
        return work.then(() => true);
    }
    return new Promise<boolean>((resolve) => {
        let settled = false;
        const finish = (ok: boolean) => {
            if (settled) return;
            settled = true;
            resolve(ok);
        };
        const timer = setTimeout(() => finish(false), timeoutMs);
        void work.then(
            () => {
                clearTimeout(timer);
                finish(true);
            },
            () => {
                clearTimeout(timer);
                finish(false);
            },
        );
    });
}

/**
 * انتظار وصول كتابات إضابير الدعوى إلى IndexedDB — قبل إغلاق أو إعادة تحميل.
 * @returns true إذا اكتمل خلال المهلة، false إذا انتهت المهلة (الكتابة قد تستمر بالخلفية).
 */
export async function flushLawsuitWorkspacePersist(
    timeoutMs = LAWSUIT_FLUSH_TIMEOUT_MS,
): Promise<boolean> {
    SecureStoreService.flushHeavyPersistPending();
    const work = (async () => {
        await SecureStoreService.waitForAllPendingPersist();
        await Promise.all(
            LAWSUIT_DURABLE_KEYS.map((key) => SecureStoreService.waitForPendingSetItem(key)),
        );
    })();
    return raceWithTimeout(work, timeoutMs);
}

/**
 * إعادة دفع صريح من ذاكرة القراءة المتزامنة إلى IndexedDB (تشفير + قرص).
 * @returns عدد المفاتيح التي أُعيدت كتابتها فعلاً
 */
async function forceRewriteLawsuitKeysFromMemory(): Promise<number> {
    let rewritten = 0;
    const keys = [
        LAWSUIT_FILES_ACTIVE_KEY,
        LAWSUIT_FILES_INDEX_KEY,
        LAWSUIT_FILES_ARCHIVED_KEY,
        LAWSUIT_FILES_TRASH_KEY,
    ] as const;

    for (const key of keys) {
        let plain = readSecureOrDrainLegacySync(key);
        if (plain == null && SecureStoreService.hasItemSync(key)) {
            try {
                plain = await SecureStoreService.getItem(key);
            } catch {
                continue;
            }
        }
        if (plain == null) continue;

        /*
         * لا تدفع ذاكرة أفقر فوق قرص أغنى — هذا كان مسار مسح الإضابير عند الإنشاء.
         * لا تُعد إحياء معرّف في أرشيف/tombstone أو سلة-فقط (لا تكرار سلة∩نشط).
         * تفريغ النشط مسموح فقط إن كل معرّفات القرص عليها tombstone حقيقي.
         */
        if (key === LAWSUIT_FILES_ACTIVE_KEY) {
            try {
                const diskPlain = await SecureStoreService.getItemFromDisk(key);
                const memFiles = parseLawsuitActiveFiles(plain);
                const diskFiles = parseLawsuitActiveFiles(diskPlain);
                const heldOutOfActive = collectHeldOutOfActiveIdsForRewrite(memFiles, diskFiles);
                if (isPoorerLawsuitActiveList(memFiles, diskFiles)) {
                    const merged = mergeRicherLawsuitActiveRespectingHeldIds(
                        memFiles,
                        diskFiles,
                        heldOutOfActive,
                    );
          if (
                    merged.length === 0 && diskFiles.length > 0
                ) {
                        const tombstones = safeTombstoneIds();
                        let allTrulyTombstoned = diskFiles.length > 0;
                        for (const row of diskFiles) {
                            const id = String(row.id ?? '').trim();
                            if (id && !tombstones.has(id)) {
                                allTrulyTombstoned = false;
                                break;
                            }
                        }
                        if (!allTrulyTombstoned) {
                            /* أبقِ القرص — لا تسمحShrink بـ [] بسبب تكرار سلة */
                            plain = diskPlain ?? plain;
                        } else {
                            plain = JSON.stringify(merged);
                            SecureStoreService.setItemSync(key, plain, {
                                allowVerifiedEmptyOverwrite: true,
                            });
                        }
                    } else {
                        plain = JSON.stringify(merged);
                        SecureStoreService.setItemSync(key, plain, {
                            allowShrink: merged.length < diskFiles.length,
                        });
                    }
                }
            } catch {
                /* المتابعة بالكتابة من الذاكرة */
            }
        }

        try {
            const allowShrinkWrite =
                key !== LAWSUIT_FILES_ACTIVE_KEY ||
                parseLawsuitActiveFiles(plain).length > 0 ||
                parseLawsuitActiveFiles(readSecureOrDrainLegacySync(key)).length === 0;
            if (!allowShrinkWrite) {
                continue;
            }
            await Promise.race([
                SecureStoreService.setItem(key, plain, {
                    allowShrink: key !== LAWSUIT_FILES_ACTIVE_KEY,
                }),
                new Promise<never>((_, reject) => {
                    setTimeout(() => reject(new Error('rewrite-timeout')), 2_000);
                }),
            ]);
            rewritten += 1;
        } catch {
            /* مفتاح واحد لا يُسقط التثبيت كله */
        }
    }
    return rewritten;
}

function safeTombstoneIds(): Set<string> {
    try {
        return readLawsuitDossierTombstoneIds();
    } catch {
        return new Set();
    }
}

/**
 * معرّفات خارج النشط عمداً — فضّل اتحاد الذاكرة+القرص النشطين حتى لا
 * تُفرَّغ الكتابة حين تكون الذاكرة فارغة والسلة تحمل نفس المعرّفات.
 */
function collectHeldOutOfActiveIdsForRewrite(
    memActive: ReturnType<typeof parseLawsuitActiveFiles>,
    diskActive: ReturnType<typeof parseLawsuitActiveFiles>,
): Set<string> {
    const preferActive = new Set<string>();
    for (const row of memActive) {
        const id = String(row.id ?? '').trim();
        if (id) preferActive.add(id);
    }
    for (const row of diskActive) {
        const id = String(row.id ?? '').trim();
        if (id) preferActive.add(id);
    }
    return collectHeldOutOfActiveIds({
        trash: parseLawsuitActiveFiles(readSecureOrDrainLegacySync(LAWSUIT_FILES_TRASH_KEY)),
        archived: parseLawsuitActiveFiles(
            readSecureOrDrainLegacySync(LAWSUIT_FILES_ARCHIVED_KEY),
        ),
        includeTombstones: true,
        preferActiveIds: preferActive,
    });
}

function parseActiveIds(raw: string | null): Set<string> {
    if (!raw) return new Set();
    try {
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return new Set();
        return new Set(
            parsed
                .map((row) =>
                    row && typeof row === 'object' && 'id' in row
                        ? String((row as { id: unknown }).id)
                        : '',
                )
                .filter(Boolean),
        );
    } catch {
        return new Set();
    }
}

function memoryHasLawsuitPayload(): boolean {
    for (const key of LAWSUIT_DURABLE_KEYS) {
        if (readSecureOrDrainLegacySync(key) != null) return true;
        if (SecureStoreService.hasItemSync(key)) return true;
    }
    return false;
}

/** هل يوجد أي بايتات على القرص لمفاتيح الدعاوى؟ (لا تعتمد على المرآة) */
async function diskHasLawsuitPayload(): Promise<boolean> {
    for (const key of LAWSUIT_DURABLE_KEYS) {
        try {
            const raw = await SecureStoreService.peekRawFromDisk(key);
            if (raw != null && String(raw).trim() !== '') return true;
        } catch {
            /* ignore per-key */
        }
    }
    return false;
}

/**
 * تثبيت موثوق لمخزن الدعاوى: flush → إعادة كتابة → تحقّق من **IndexedDB فقط**.
 * المهلة تحدّ الزمن الكلي عبر فحص دوري (لا Promise.race مزدوج يترك العمل معلّقاً).
 */
export async function commitLawsuitWorkspacePersist(
    options: LawsuitCommitOptions = {},
): Promise<LawsuitCommitResult> {
    const timeoutMs = options.timeoutMs ?? LAWSUIT_COMMIT_TIMEOUT_MS;
    const started = Date.now();
    const timedOut = () => Date.now() - started >= timeoutMs;
    try {
        return await commitLawsuitWorkspacePersistInner({
            ...options,
            timeoutMs,
            timedOut,
            started,
        });
    } catch {
        return { ok: false, reason: timedOut() ? 'timeout' : 'write-failed' };
    }
}

async function commitLawsuitWorkspacePersistInner(
    options: LawsuitCommitOptions & { timedOut: () => boolean; started: number },
): Promise<LawsuitCommitResult> {
    const timeoutMs = options.timeoutMs ?? LAWSUIT_COMMIT_TIMEOUT_MS;
    const requireId =
        options.requireActiveFileId != null && String(options.requireActiveFileId).trim() !== ''
            ? String(options.requireActiveFileId)
            : null;
    const { timedOut, started } = options;

    const flushBudget = Math.min(2_000, Math.max(800, Math.floor(timeoutMs * 0.4)));
    const flushed = await flushLawsuitWorkspacePersist(flushBudget);
    if (timedOut()) return { ok: false, reason: 'timeout' };

    if (!flushed) {
        try {
            await forceRewriteLawsuitKeysFromMemory();
        } catch {
            /* المتابعة للتحقق من القرص */
        }
    }
    if (timedOut()) return { ok: false, reason: 'timeout' };

    const syncActive = readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY);
    if (syncActive == null && !requireId && !memoryHasLawsuitPayload()) {
        if (!(await diskHasLawsuitPayload())) {
            return { ok: true };
        }
    }

    let diskActive: string | null = null;
    try {
        diskActive = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
    } catch {
        try {
            await forceRewriteLawsuitKeysFromMemory();
            diskActive = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        } catch {
            return { ok: false, reason: 'write-failed' };
        }
    }
    if (timedOut()) return { ok: false, reason: 'timeout' };

    if (syncActive != null && (diskActive == null || diskActive.trim() === '')) {
        try {
            await forceRewriteLawsuitKeysFromMemory();
            diskActive = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
        } catch {
            return { ok: false, reason: 'verify-failed' };
        }
        if (diskActive == null || diskActive.trim() === '') {
            return { ok: false, reason: flushed ? 'verify-failed' : 'timeout' };
        }
    }

    if (requireId) {
        const ids = parseActiveIds(diskActive);
        if (!ids.has(requireId)) {
            const memIds = parseActiveIds(syncActive);
            const deadline = Date.now() + Math.max(400, Math.min(4_000, timeoutMs - (Date.now() - started)));
            while (Date.now() < deadline) {
                if (timedOut()) break;
                try {
                    await forceRewriteLawsuitKeysFromMemory();
                    diskActive = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_ACTIVE_KEY);
                } catch {
                    break;
                }
                if (parseActiveIds(diskActive).has(requireId)) break;
                await new Promise((r) => setTimeout(r, 120));
            }
            const retryIds = parseActiveIds(diskActive);
            if (!retryIds.has(requireId)) {
                if (memIds.has(requireId)) {
                    /*
                     * الذاكرة تحمل الإضبارة والقرص متأخر — لا نفشل UX بصرامة:
                     * نُبقي جدولة خلفية عبر schedule بعد الإرجاع من طبقة التحذير.
                     */
                    return { ok: false, reason: 'timeout' };
                }
                return { ok: false, reason: 'verify-failed' };
            }
        }
    }

    if (timedOut()) return { ok: false, reason: 'timeout' };

    const indexPlain = readSecureOrDrainLegacySync(LAWSUIT_FILES_INDEX_KEY);
    if (indexPlain != null) {
        try {
            const diskIndex = await SecureStoreService.getItemFromDisk(LAWSUIT_FILES_INDEX_KEY);
            if (diskIndex == null || diskIndex.trim() === '') {
                await Promise.race([
                    SecureStoreService.setItem(LAWSUIT_FILES_INDEX_KEY, indexPlain),
                    new Promise<never>((_, reject) => {
                        setTimeout(() => reject(new Error('index-timeout')), 1_500);
                    }),
                ]).catch(() => undefined);
            }
        } catch {
            /* تجاهل */
        }
    }

    return { ok: true };
}

/* ——— جدولة موحّدة: autosave يُجمَّع، الطفرات الحرجة تنتظر ——— */

let commitDebounceTimer: ReturnType<typeof setTimeout> | null = null;
let commitChain: Promise<void> = Promise.resolve();
let pendingRequireActiveFileId: string | null = null;

function takePendingRequireId(
    explicit?: string | number | null,
): string | null {
    if (explicit != null && String(explicit).trim() !== '') {
        pendingRequireActiveFileId = null;
        return String(explicit);
    }
    const pending = pendingRequireActiveFileId;
    pendingRequireActiveFileId = null;
    return pending;
}

/**
 * تثبيت مؤجّل بعد كتابات متزامنة متكررة (تعديل/حفظ تلقائي).
 * لا يستبدل `awaitLawsuitWorkspaceCommit` لمسارات الإنشاء/الأرشفة.
 */
export function scheduleLawsuitWorkspaceCommit(options: LawsuitCommitOptions = {}): void {
    if (
        options.requireActiveFileId != null &&
        String(options.requireActiveFileId).trim() !== ''
    ) {
        pendingRequireActiveFileId = String(options.requireActiveFileId);
    }
    const debounceMs = options.debounceMs ?? LAWSUIT_COMMIT_DEBOUNCE_MS;
    if (commitDebounceTimer) clearTimeout(commitDebounceTimer);
    commitDebounceTimer = setTimeout(() => {
        commitDebounceTimer = null;
        const requireId = takePendingRequireId();
        const timeoutMs = options.timeoutMs ?? LAWSUIT_FLUSH_TIMEOUT_MS;
        commitChain = commitChain
            .then(() =>
                commitLawsuitWorkspacePersist({
                    timeoutMs,
                    requireActiveFileId: requireId,
                }).then(() => undefined),
            )
            .catch(() => undefined);
    }, debounceMs);
}

/** إلغاء الجدولة وانتظار التثبيت فوراً — إنشاء، أرشفة، إخفاء تبويب */
export async function awaitLawsuitWorkspaceCommit(
    options: LawsuitCommitOptions = {},
): Promise<LawsuitCommitResult> {
    if (commitDebounceTimer) {
        clearTimeout(commitDebounceTimer);
        commitDebounceTimer = null;
    }
    const requireId = takePendingRequireId(options.requireActiveFileId);
    const timeoutMs = options.timeoutMs ?? LAWSUIT_COMMIT_TIMEOUT_MS;

    /*
     * لا تنتظر طابور autosave المتراكم — كان يصفّ 8ث×N فيبدو الزر معلّقاً ثم يفشل.
     * تثبيت حرج معزول؛ الطابور يُصفَّر بعده حتى لا يُعاد تشغيل commit قديم فوقه.
     */
    const isolated = commitLawsuitWorkspacePersist({
        timeoutMs,
        requireActiveFileId: requireId,
    });
    commitChain = isolated.then(() => undefined).catch(() => undefined);
    return isolated;
}

/** اختبارات فقط — صفّر طابور الجدولة بين الحالات */
export function resetLawsuitCommitSchedulerForTests(): void {
    if (!import.meta.env.VITEST) return;
    if (commitDebounceTimer) clearTimeout(commitDebounceTimer);
    commitDebounceTimer = null;
    pendingRequireActiveFileId = null;
    commitChain = Promise.resolve();
}

/**
 * كتابة/قراءة مقاطع الدعوى — ورقة بلا اعتماد على بوابة المتانة.
 * البوابة تستورد من هنا لا من `lawsuitSegmentStorage` حتى لا تُغلق دائرة تهيئة
 * (Gate → Storage → Gate) وقت الإقلاع.
 */
import type { FileData } from './lawsuitFileTypes';
import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import SecureStoreService from '@/app/services/SecureStoreService';
import { ENCRYPT_MAX_BYTES } from '@/app/services/secureStorageKeys';
import { saveLawsuitFilesRaw } from '@/app/utils/lawsuitFilesStorage';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_TRASH_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { scheduleLawsuitWorkspaceCommit } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import { type LawsuitLifecycleIndex } from './lawsuitLifecycleIndex';
import {
    isPoorerLawsuitActiveList,
    mergeRicherLawsuitActive,
    parseLawsuitActiveFiles,
} from './lawsuitActiveDurability';
import {
    clearLegacyPlaintextMirror,
    readSecureOrDrainLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';

/** DEV: مقطع واحد ما زال فوق حدّ التشفير رغم التقسيم active/archived/trash */
export function warnIfLawsuitSegmentExceedsEncryptLimit(key: string, serialized: string): void {
    if (serialized.length <= ENCRYPT_MAX_BYTES) return;
    if (!import.meta.env.DEV) return;
    console.warn(
        `[lawsuitSegment] segment exceeds ENCRYPT_MAX_BYTES: key=${key} len=${serialized.length} limit=${ENCRYPT_MAX_BYTES} overBy=${serialized.length - ENCRYPT_MAX_BYTES}`,
    );
}

export function readLawsuitJsonArray(key: string): unknown[] | null {
    try {
        const raw = readSecureOrDrainLegacySync(key);
        if (!raw) return null;
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : null;
    } catch {
        return null;
    }
}

function isLawsuitSegmentArrayKey(key: string): boolean {
    return (
        key === LAWSUIT_FILES_ACTIVE_KEY ||
        key === LAWSUIT_FILES_ARCHIVED_KEY ||
        key === LAWSUIT_FILES_TRASH_KEY
    );
}

function writeJsonArray(
    key: string,
    payload: unknown[],
    options?: { allowVerifiedEmpty?: boolean; allowShrink?: boolean },
): boolean {
    /*
     * متانة المقطع: لا تستبدل قائمة أغنى بقائمة أفقر إلا بتصريح (أرشفة/سلة/نقل).
     */
    let nextPayload = payload;
    if (isLawsuitSegmentArrayKey(key) && !options?.allowVerifiedEmpty && !options?.allowShrink) {
        const existing = parseLawsuitActiveFiles(readSecureOrDrainLegacySync(key));
        const proposed = (Array.isArray(payload) ? payload : []) as FileData[];
        if (isPoorerLawsuitActiveList(proposed, existing)) {
            nextPayload = mergeRicherLawsuitActive(proposed, existing);
        }
    }

    if (SecureStoreService.isUnreadSync(key)) {
        /*
         * لا تستبدل مشفّراً بارداً بأي قائمة قبل فك التشفير —
         * كان مسار إنشاء الدعوى يمسح الخزنة بهذا الباب.
         */
        return false;
    }
    const serialized = JSON.stringify(nextPayload);
    warnIfLawsuitSegmentExceedsEncryptLimit(key, serialized);
    /*
     * setItemSync قد يرفض المسح الفارغ — تجاهل الرفض سابقاً كان يمرّر []
     * إلى persistenceRepository ويُفرّغ المرآة/المقاطع من باب خلفي.
     */
    const accepted = SecureStoreService.setItemSync(key, serialized, {
        allowVerifiedEmptyOverwrite: Boolean(options?.allowVerifiedEmpty),
        allowShrink: Boolean(options?.allowShrink),
    });
    if (accepted === false) {
        if (options?.allowVerifiedEmpty && nextPayload.length === 0) {
            SecureStoreService.applyVerifiedEmptyOverwrite(key, serialized);
            clearLegacyPlaintextMirror(key);
            try {
                persistenceRepository.save(key, nextPayload);
                persistenceRepository.flushPending(key);
            } catch {
                /* tests may mock persistence */
            }
            try {
                scheduleLawsuitWorkspaceCommit();
            } catch {
                /* ignore scheduler */
            }
            return true;
        }
        return false;
    }
    clearLegacyPlaintextMirror(key);
    try {
        persistenceRepository.save(key, nextPayload);
        persistenceRepository.flushPending(key);
    } catch {
        /* tests may mock persistence */
    }
    try {
        scheduleLawsuitWorkspaceCommit();
    } catch {
        /* ignore scheduler */
    }
    return true;
}

export function persistLawsuitActiveSegment(
    files: FileData[],
    options?: { allowVerifiedEmpty?: boolean; allowShrink?: boolean },
): boolean {
    return writeJsonArray(LAWSUIT_FILES_ACTIVE_KEY, files, options);
}

export function readLawsuitActiveSegment(): FileData[] {
    const fromKey = readLawsuitJsonArray(LAWSUIT_FILES_ACTIVE_KEY);
    if (fromKey !== null) return fromKey as FileData[];
    return [];
}

export function readLawsuitArchivedSegment(): FileData[] {
    const fromKey = readLawsuitJsonArray(LAWSUIT_FILES_ARCHIVED_KEY);
    if (fromKey !== null) return fromKey as FileData[];
    return [];
}

export function readLawsuitTrashSegment(): FileData[] {
    const fromKey = readLawsuitJsonArray(LAWSUIT_FILES_TRASH_KEY);
    if (fromKey !== null) return fromKey as FileData[];
    return [];
}

export function readLawsuitLifecycleIndex(): LawsuitLifecycleIndex | null {
    try {
        const raw = readSecureOrDrainLegacySync(LAWSUIT_FILES_INDEX_KEY);
        if (!raw) return null;
        const parsed: unknown = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object') return null;
        const obj = parsed as LawsuitLifecycleIndex;
        if (obj.v !== 1 || !obj.entries || !obj.counts) return null;
        return obj;
    } catch {
        return null;
    }
}

export function persistLawsuitArchivedSegment(
    files: FileData[],
    options?: { allowVerifiedEmpty?: boolean; allowShrink?: boolean },
): boolean {
    return writeJsonArray(LAWSUIT_FILES_ARCHIVED_KEY, files, options);
}

export function persistLawsuitTrashSegment(
    files: FileData[],
    options?: { allowVerifiedEmpty?: boolean; allowShrink?: boolean },
): boolean {
    return writeJsonArray(LAWSUIT_FILES_TRASH_KEY, files, options);
}

export function persistLawsuitLifecycleIndex(index: LawsuitLifecycleIndex): void {
    const total = index.counts.active + index.counts.archived + index.counts.trash;
    if (
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_STORAGE_KEY)
    ) {
        return;
    }
    if (total === 0 && SecureStoreService.isUnreadSync(LAWSUIT_FILES_INDEX_KEY)) {
        return;
    }
    const serialized = JSON.stringify(index);
    SecureStoreService.setItemSync(LAWSUIT_FILES_INDEX_KEY, serialized);
    clearLegacyPlaintextMirror(LAWSUIT_FILES_INDEX_KEY);
    try {
        persistenceRepository.save(LAWSUIT_FILES_INDEX_KEY, index);
        persistenceRepository.flushPending(LAWSUIT_FILES_INDEX_KEY);
    } catch {
        /* tests may mock persistence */
    }
    scheduleLawsuitWorkspaceCommit();
}

/** مرآة monolithic لتوافق cloud sync والمسارات القديمة */
export function syncLawsuitMonolithicMirror(
    active: FileData[],
    archived: FileData[],
    trash: FileData[],
): void {
    const merged = [...active, ...archived, ...trash];
    warnIfLawsuitSegmentExceedsEncryptLimit(
        'lawyer_files',
        JSON.stringify(merged),
    );
    saveLawsuitFilesRaw(merged as unknown[]);
}

/**
 * عند المقاطع الكسولة (`null`) اقرأ من القرص قبل بناء المرآة —
 * لا تستخدم `?? []` وإلا تُمسَح archived/trash من `lawyer_files`.
 */
export function resolveLazyLawsuitSegmentForMirror(
    lazy: FileData[] | null | undefined,
    readFromDisk: () => FileData[],
): FileData[] {
    if (lazy !== null && lazy !== undefined) return lazy;
    return readFromDisk();
}

/** مرآة آمنة: تُحلّ المقاطع الكسولة ثم تُزامن المرآة monolithic */
export function mirrorLawsuitSegmentsSafe(
    active: FileData[],
    archived: FileData[] | null | undefined,
    trash: FileData[] | null | undefined,
): void {
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)) {
        return;
    }
    /*
     * مقطع كسول غير مقروء ≠ قائمة فارغة. دمج النشطة فقط في lawyer_files
     * يحذف الأرشيف/السلة من المرآة، والحارس لا يرفض إلا التفريغ الكامل.
     */
    if (
        (archived === null || archived === undefined) &&
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_ARCHIVED_KEY)
    ) {
        return;
    }
    if (
        (trash === null || trash === undefined) &&
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_TRASH_KEY)
    ) {
        return;
    }
    syncLawsuitMonolithicMirror(
        active,
        resolveLazyLawsuitSegmentForMirror(archived, readLawsuitArchivedSegment),
        resolveLazyLawsuitSegmentForMirror(trash, readLawsuitTrashSegment),
    );
}

import type { FileData } from './lawsuitFileTypes';
import SecureStoreService from '@/app/services/SecureStoreService';
import { loadLawsuitFilesRaw } from '@/app/utils/lawsuitFilesStorage';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_TRASH_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { persistLawsuitActiveBundle } from '@/app/domain/lawsuit/lawsuitDurabilityGate';
import {
    collectHeldOutOfActiveIds,
    healLawsuitArchivedAgainstActive,
    healLawsuitTrashAgainstActive,
} from '@/app/domain/lawsuit/lawsuitFilesStatePolicy';
import {
    persistLawsuitActiveSegment,
    persistLawsuitArchivedSegment,
    persistLawsuitTrashSegment,
    readLawsuitActiveSegment,
    readLawsuitArchivedSegment,
    readLawsuitJsonArray,
    readLawsuitLifecycleIndex,
    readLawsuitTrashSegment,
} from '@/app/domain/lawsuit/lawsuitSegmentPersist';
import {
    buildLawsuitLifecycleIndex,
    emptyLawsuitLifecycleIndex,
    type LawsuitLifecycleIndex,
} from './lawsuitLifecycleIndex';
import { isLawsuitArchived, isLawsuitInTrash } from '@/app/utils/lawsuitTrash';
import {
    areLawsuitDossierTombstonesUnreadSync,
    excludeTombstonedLawsuitFiles,
    readLawsuitDossierTombstoneIds,
} from '@/app/utils/lawsuitDossierTombstones';

export {
    mirrorLawsuitSegmentsSafe,
    persistLawsuitActiveSegment,
    persistLawsuitArchivedSegment,
    persistLawsuitLifecycleIndex,
    persistLawsuitTrashSegment,
    readLawsuitActiveSegment,
    readLawsuitArchivedSegment,
    readLawsuitTrashSegment,
    resolveLazyLawsuitSegmentForMirror,
    syncLawsuitMonolithicMirror,
    warnIfLawsuitSegmentExceedsEncryptLimit,
} from '@/app/domain/lawsuit/lawsuitSegmentPersist';

function splitMonolithic(files: FileData[]): {
    active: FileData[];
    archived: FileData[];
    trash: FileData[];
} {
    const active: FileData[] = [];
    const archived: FileData[] = [];
    const trash: FileData[] = [];
    for (const file of files) {
        if (isLawsuitInTrash(file)) trash.push(file);
        else if (isLawsuitArchived(file)) archived.push(file);
        else active.push(file);
    }
    return { active, archived, trash };
}

type LawsuitBootState = {
    active: FileData[];
    archived: FileData[] | null;
    trash: FileData[] | null;
    index: LawsuitLifecycleIndex;
    migrated: boolean;
};

export function lawsuitSegmentsNeedWarm(): boolean {
    return (
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_INDEX_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_ARCHIVED_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_TRASH_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_STORAGE_KEY)
    );
}

export function lawsuitStorageMayHaveUnreadData(index: LawsuitLifecycleIndex): boolean {
    if (lawsuitSegmentsNeedWarm()) return true;
    return index.counts.active > 0 || index.counts.archived > 0 || index.counts.trash > 0;
}

function keyOccupiedAndUnread(key: string): boolean {
    return SecureStoreService.hasItemSync(key) && SecureStoreService.isUnreadSync(key);
}

/**
 * النشط الفارغ بعد سلة/أرشيف ليس «خزنة ضائعة» تُستورد من lawyer_files.
 * الاستيراد كان يعيد إضبارة محذوفة من مرآة/localStorage قديمة عند كل reload.
 */
export function shouldRefuseEmptyActiveMonolithRecovery(
    index: LawsuitLifecycleIndex | null,
): boolean {
    if (areLawsuitDossierTombstonesUnreadSync()) return true;
    if (
        keyOccupiedAndUnread(LAWSUIT_FILES_ACTIVE_KEY) ||
        keyOccupiedAndUnread(LAWSUIT_FILES_INDEX_KEY) ||
        keyOccupiedAndUnread(LAWSUIT_FILES_ARCHIVED_KEY) ||
        keyOccupiedAndUnread(LAWSUIT_FILES_TRASH_KEY) ||
        keyOccupiedAndUnread(LAWSUIT_FILES_STORAGE_KEY)
    ) {
        return true;
    }
    if (index && (index.counts.trash > 0 || index.counts.archived > 0)) return true;
    if (index) {
        for (const entry of Object.values(index.entries)) {
            if (entry.status === 'deleted' || entry.status === 'archived') return true;
        }
    }
    if (
        SecureStoreService.hasItemSync(LAWSUIT_FILES_TRASH_KEY) &&
        readLawsuitTrashSegment().length > 0
    ) {
        return true;
    }
    if (
        SecureStoreService.hasItemSync(LAWSUIT_FILES_ARCHIVED_KEY) &&
        readLawsuitArchivedSegment().length > 0
    ) {
        return true;
    }
    return false;
}

export function segmentsAlreadyPresent(): boolean {
    const activeReadable = readLawsuitJsonArray(LAWSUIT_FILES_ACTIVE_KEY);
    const indexReadable = readLawsuitLifecycleIndex();
    if (activeReadable !== null || indexReadable !== null) return true;
    return (
        SecureStoreService.hasItemSync(LAWSUIT_FILES_ACTIVE_KEY) ||
        SecureStoreService.hasItemSync(LAWSUIT_FILES_INDEX_KEY)
    );
}

function persistLawsuitSegmentBundle(
    active: FileData[],
    archived: FileData[],
    trash: FileData[],
    index: LawsuitLifecycleIndex,
    options?: { allowLifecycleRedistribute?: boolean },
): void {
    const redistribute = Boolean(options?.allowLifecycleRedistribute);
    let nextActive = active;
    /*
     * إعادة التوزيع من السحابة/المرآة لا تُفرّغ النشط فوق قرص أغنى.
     * ممنوع allowVerifiedEmpty على النشط هنا — كان يشرعن [] بعد held خاطئ.
     */
    if (redistribute && nextActive.length === 0) {
        const diskActive = readLawsuitActiveSegment();
        if (diskActive.length > 0) {
            nextActive = diskActive;
        }
    }
    persistLawsuitArchivedSegment(archived, {
        allowVerifiedEmpty: redistribute && archived.length === 0,
        allowShrink: redistribute,
    });
    persistLawsuitTrashSegment(trash, {
        allowVerifiedEmpty: redistribute && trash.length === 0,
        allowShrink: redistribute,
    });
    persistLawsuitActiveBundle({
        active: nextActive,
        index:
            nextActive.length === active.length
                ? index
                : buildLawsuitLifecycleIndex(nextActive, archived, trash),
        archived,
        trash,
        /*
         * إعادة التوزيع من السحابة/المرآة: لا allowShrink أعمى —
         * كان يكتب قائمة أفقر فوق أغنى عند قراءة sync مسمّمة.
         * التقلّص العمدي يبقى لمسارات الأرشفة/السلة فقط.
         */
    });
}

/** لا تكتب مقاطع من مرآة قديمة قبل أن تُملأ مرآة IndexedDB — هذا كان مسار اختفاء الأحوال. */
function shouldSkipBootSegmentPersist(): boolean {
    if (!SecureStoreService.isDiskHydrationSettledSync()) return true;
    return (
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_INDEX_KEY) ||
        SecureStoreService.isUnreadSync(LAWSUIT_FILES_STORAGE_KEY)
    );
}

export function migrateLawsuitMonolithicToSegmentsIfNeeded(): LawsuitBootState {
    if (segmentsAlreadyPresent()) {
        let active = readLawsuitActiveSegment();
        const index = readLawsuitLifecycleIndex() ?? buildLawsuitLifecycleIndex(active, [], []);

        if (active.length === 0) {
            /*
             * شواهد غير مقروءة أو دورة حياة قائمة: لا تستورد المرآة —
             * كانت تُعيد محذوفاً/منقولاً للسلة من lawyer_files القديم.
             */
            if (shouldRefuseEmptyActiveMonolithRecovery(index)) {
                return { active, archived: null, trash: null, index, migrated: false };
            }
            const monolithic = loadLawsuitFilesRaw() as FileData[];
            if (monolithic.length > 0) {
                const split = splitMonolithic(monolithic);
                const diskTrash = readLawsuitTrashSegment();
                const diskArchived = readLawsuitArchivedSegment();
                const held = collectHeldOutOfActiveIds({
                    trash: [...split.trash, ...diskTrash],
                    archived: [...split.archived, ...diskArchived],
                    index,
                    preferActiveIds: active,
                    includeTombstones: true,
                });
                let tombstoned = new Set<string>();
                try {
                    tombstoned = readLawsuitDossierTombstoneIds();
                } catch {
                    /* ignore */
                }
                active = excludeTombstonedLawsuitFiles(
                    split.active.filter((f) => !held.has(String(f.id ?? '').trim())),
                );
                const healedArchivedRaw = [
                    ...split.archived,
                    ...diskArchived.filter(
                        (f) => !split.archived.some((a) => String(a.id) === String(f.id)),
                    ),
                ].filter((f) => !tombstoned.has(String(f.id ?? '').trim()));
                let healedTrash = [
                    ...split.trash,
                    ...diskTrash.filter(
                        (f) => !split.trash.some((t) => String(t.id) === String(f.id)),
                    ),
                ].filter((f) => !tombstoned.has(String(f.id ?? '').trim()));
                healedTrash = healLawsuitTrashAgainstActive(active, healedTrash) ?? healedTrash;
                const healedArchived =
                    healLawsuitArchivedAgainstActive(active, healedArchivedRaw) ??
                    healedArchivedRaw;
                const healedIndex = buildLawsuitLifecycleIndex(
                    active,
                    healedArchived,
                    healedTrash,
                );
                /*
                 * عرض فقط حتى يستقر القرص. الكتابة هنا فوق ciphertext غير مقروء
                 * كانت تُثبّت المدنية القديمة وتمسح الأحوال المنشأة.
                 */
                if (
                    !shouldSkipBootSegmentPersist() &&
                    (active.length > 0 || healedArchived.length > 0 || healedTrash.length > 0)
                ) {
                    persistLawsuitSegmentBundle(
                        active,
                        healedArchived,
                        healedTrash,
                        healedIndex,
                        { allowLifecycleRedistribute: true },
                    );
                }
                return {
                    active,
                    archived: null,
                    trash: null,
                    index: healedIndex,
                    migrated: false,
                };
            }
        }

        /* نشط غير فارغ: اشفِ تكرار السلة/الأرشيف أولاً — لا تفرّغ النشط بسبب صف مكرّر */
        {
            const diskTrash = readLawsuitTrashSegment();
            const diskArchived = readLawsuitArchivedSegment();
            const healedTrash = healLawsuitTrashAgainstActive(active, diskTrash);
            const healedArchived = healLawsuitArchivedAgainstActive(active, diskArchived);
            if (
                healedTrash &&
                healedTrash.length !== diskTrash.length &&
                !shouldSkipBootSegmentPersist()
            ) {
                persistLawsuitTrashSegment(healedTrash, {
                    allowShrink: true,
                    allowVerifiedEmpty: healedTrash.length === 0,
                });
            }
            if (
                healedArchived &&
                healedArchived.length !== diskArchived.length &&
                !shouldSkipBootSegmentPersist()
            ) {
                persistLawsuitArchivedSegment(healedArchived, {
                    allowShrink: true,
                    allowVerifiedEmpty: healedArchived.length === 0,
                });
            }
            const held = collectHeldOutOfActiveIds({
                trash: healedTrash ?? diskTrash,
                archived: healedArchived ?? diskArchived,
                preferActiveIds: active,
                includeTombstones: true,
            });
            if (held.size > 0) {
                const cleaned = active.filter((f) => !held.has(String(f.id ?? '').trim()));
                if (cleaned.length !== active.length) {
                    /*
                     * عرض فقط — لا تكتب تقلّص نشط من مسار الإقلاع/الترحيل.
                     * الكتابة هنا كانت تثبّت wipe جزئياً عند كل reload.
                     */
                    return {
                        active: cleaned,
                        archived: null,
                        trash: null,
                        index: buildLawsuitLifecycleIndex(
                            cleaned,
                            healedArchived ?? diskArchived,
                            healedTrash ?? diskTrash,
                        ),
                        migrated: false,
                    };
                }
            }
        }

        return { active, archived: null, trash: null, index, migrated: false };
    }

    const monolithic = loadLawsuitFilesRaw() as FileData[];
    const { active, archived, trash } = splitMonolithic(monolithic);
    const index = buildLawsuitLifecycleIndex(active, archived, trash);

    if (monolithic.length === 0) {
        return {
            active: [],
            archived: null,
            trash: null,
            index: emptyLawsuitLifecycleIndex(),
            migrated: false,
        };
    }

    if (!shouldSkipBootSegmentPersist()) {
        persistLawsuitSegmentBundle(active, archived, trash, index);
    }

    return { active, archived: null, trash: null, index, migrated: monolithic.length > 0 };
}

export function loadLawsuitBootState(): LawsuitBootState {
    return migrateLawsuitMonolithicToSegmentsIfNeeded();
}

export function loadLawsuitFullSegmentsFromStorage(): {
    active: FileData[];
    archived: FileData[];
    trash: FileData[];
    index: LawsuitLifecycleIndex;
} {
    migrateLawsuitMonolithicToSegmentsIfNeeded();
    const active = readLawsuitActiveSegment();
    const archived = readLawsuitArchivedSegment();
    const trash = readLawsuitTrashSegment();
    const index =
        readLawsuitLifecycleIndex() ??
        buildLawsuitLifecycleIndex(active, archived, trash);
    return { active, archived, trash, index };
}

/**
 * دمج حمولة (سحابة/تقويم/مرآة) مع المقاطع على القرص دون إسقاط معرّفات محلية.
 * الحمولة مصدر حقيقة لحالتها؛ ما ليس فيها يبقى في مقطعه على القرص.
 * لا تُعاد إضبارة من السحابة إلى النشط إن كانت محلياً في السلة/الأرشيف.
 */
export function unionLawsuitPayloadWithDiskSegments(payload: FileData[]): {
    active: FileData[];
    archived: FileData[];
    trash: FileData[];
} {
    const rows = Array.isArray(payload) ? payload : [];
    const split = splitMonolithic(rows);
    const payloadIds = new Set(rows.map((f) => String(f?.id ?? '')).filter(Boolean));
    const diskTrash = readLawsuitTrashSegment();
    const diskArchived = readLawsuitArchivedSegment();
    const diskActive = readLawsuitActiveSegment();
    const diskActiveIds = new Set(
        diskActive.map((f) => String(f.id ?? '').trim()).filter(Boolean),
    );
    const preferActive = new Set(diskActiveIds);
    const heldOutOfActive = collectHeldOutOfActiveIds({
        trash: [...split.trash, ...diskTrash],
        archived: [...split.archived, ...diskArchived],
        preferActiveIds: preferActive,
        includeTombstones: true,
    });

    const active = [
        ...split.active.filter((f) => !heldOutOfActive.has(String(f.id ?? '').trim())),
        ...diskActive.filter(
            (f) =>
                !payloadIds.has(String(f.id)) && !heldOutOfActive.has(String(f.id ?? '').trim()),
        ),
    ];
    let archived = [
        ...split.archived,
        ...diskArchived.filter((f) => !payloadIds.has(String(f.id))),
    ];
    let trash = [
        ...split.trash.filter((f) => !diskActiveIds.has(String(f.id ?? '').trim())),
        ...diskTrash.filter(
            (f) =>
                !payloadIds.has(String(f.id)) && !diskActiveIds.has(String(f.id ?? '').trim()),
        ),
    ];
    trash = healLawsuitTrashAgainstActive(active, trash) ?? trash;
    archived = healLawsuitArchivedAgainstActive(active, archived) ?? archived;
    return {
        active: excludeTombstonedLawsuitFiles(active),
        archived: excludeTombstonedLawsuitFiles(archived),
        trash: excludeTombstonedLawsuitFiles(trash),
    };
}

/** صفوف محلية للمزامنة: مقاطع + مرآة — لا تعتمد على persistenceRepository وحده */
export function collectLawsuitLocalRowsForSync(): FileData[] {
    try {
        migrateLawsuitMonolithicToSegmentsIfNeeded();
        const seen = new Set<string>();
        const out: FileData[] = [];
        const add = (rows: FileData[]) => {
            for (const row of rows) {
                const id = String(row?.id ?? '').trim();
                if (!id || seen.has(id)) continue;
                seen.add(id);
                out.push(row);
            }
        };
        add(readLawsuitActiveSegment());
        add(readLawsuitArchivedSegment());
        add(readLawsuitTrashSegment());
        add((loadLawsuitFilesRaw() as FileData[]) ?? []);
        return excludeTombstonedLawsuitFiles(out);
    } catch {
        return [];
    }
}

/**
 * بعد دمج السحابة في المرآة: أعد تقسيم المقاطع + الفهرس.
 * بدون هذا تبقى المقاطع قديمة وتُعيد الكتابة فوق الدمج عند أي reload/persist.
 */
export function applyLawsuitMonolithicMergeToSegments(merged: FileData[]): {
    active: FileData[];
    archived: FileData[];
    trash: FileData[];
    index: LawsuitLifecycleIndex;
} {
    const payload = Array.isArray(merged) ? merged : [];
    const current = loadLawsuitFullSegmentsFromStorage();
    if (areLawsuitDossierTombstonesUnreadSync()) {
        return current;
    }
    const hasDisk =
        current.active.length > 0 ||
        current.archived.length > 0 ||
        current.trash.length > 0 ||
        current.index.counts.active > 0 ||
        current.index.counts.archived > 0 ||
        current.index.counts.trash > 0 ||
        lawsuitSegmentsNeedWarm();
    if (payload.length === 0) {
        if (hasDisk) {
            return current;
        }
        return {
            active: [],
            archived: current.archived,
            trash: current.trash,
            index: current.index,
        };
    }
    const unioned = unionLawsuitPayloadWithDiskSegments(payload);
    const index = buildLawsuitLifecycleIndex(unioned.active, unioned.archived, unioned.trash);
    if (shouldSkipBootSegmentPersist()) {
        return { ...unioned, index };
    }
    persistLawsuitSegmentBundle(unioned.active, unioned.archived, unioned.trash, index, {
        allowLifecycleRedistribute: true,
    });
    return { ...unioned, index };
}

/** بحث مزامَن عبر المقاطع — للبحث العام وفتح المخزن/السلة */
export function findLawsuitFileAcrossSegments(fileId: string | number): FileData | null {
    const idStr = String(fileId);
    migrateLawsuitMonolithicToSegmentsIfNeeded();
    const hit =
        readLawsuitActiveSegment().find((f) => String(f.id) === idStr) ??
        readLawsuitArchivedSegment().find((f) => String(f.id) === idStr) ??
        readLawsuitTrashSegment().find((f) => String(f.id) === idStr);
    return hit ?? null;
}

export function removeLawsuitSegmentRecords(
    segmentKey: typeof LAWSUIT_FILES_ACTIVE_KEY | typeof LAWSUIT_FILES_ARCHIVED_KEY | typeof LAWSUIT_FILES_TRASH_KEY,
    ids: Array<string | number>,
    current: FileData[],
): { next: FileData[]; ok: boolean } {
    const idSet = new Set(ids.map(String));
    const next = current.filter((f) => !idSet.has(String(f.id)));
    if (next.length === current.length) {
        return { next, ok: true };
    }
    let ok = false;
    if (segmentKey === LAWSUIT_FILES_ACTIVE_KEY) {
        ok = persistLawsuitActiveSegment(next, {
            allowVerifiedEmpty: next.length === 0,
            allowShrink: true,
        });
    } else if (segmentKey === LAWSUIT_FILES_ARCHIVED_KEY) {
        ok = persistLawsuitArchivedSegment(next, {
            allowVerifiedEmpty: next.length === 0,
            allowShrink: true,
        });
    } else {
        ok = persistLawsuitTrashSegment(next, {
            allowVerifiedEmpty: next.length === 0,
            allowShrink: true,
        });
    }
    return { next, ok };
}

/**
 * مراحل الدعوى حسب المحكمة — منطق النواة، بلا نموذج NewCase.
 * يُستخدم لتوليد الدعوى الحادثة / المتقابلة من إضبارة قائمة، لا لنموذج الفتح الجديد.
 */
export function computeLawsuitStageOptions(court: string): string[] {
    const c = court.toLowerCase();
    if (c.includes('بداءة')) {
        return [
            'بداءة بدرجة أخيرة',
            'بداءة بدرجة أولى',
            'اعتراض على الحكم الغيابي',
            'اعتراض الغير',
            'إعادة المحاكمة',
        ];
    }
    if (c.includes('استئناف')) {
        return ['استئناف', 'اعتراض على الحكم الغيابي', 'اعتراض الغير', 'إعادة المحاكمة'];
    }
    return [
        'بداءة بدرجة أولى',
        'بداءة بدرجة أخيرة',
        'استئناف',
        'اعتراض على الحكم الغيابي',
        'اعتراض الغير',
        'إعادة المحاكمة',
    ];
}

export const OPENING_STAGE_FIRST_DEGREE = 'بداءة بدرجة أولى';
export const OPENING_STAGE_LAST_DEGREE = 'بداءة بدرجة أخيرة';

/** عتبة المادة 31 مرافعات — فوقها بداءة بدرجة أولى، وإلا بدرجة أخيرة. */
export const LAWSUIT_FIRST_INSTANCE_DEGREE_THRESHOLD = 1_000_000;

export function parseLawsuitClaimValueAmount(claimValue: string | undefined): number {
    return parseInt(String(claimValue ?? '').replace(/[^0-9]/g, ''), 10) || 0;
}

export type OpeningLawsuitStageInput = {
    claimValue: string;
    isUndeterminedValue: boolean;
    isFixedFee: boolean;
    caseType: string;
};

function forcesLastDegreeType(caseType: string): boolean {
    return caseType.includes('تخلي') || caseType.includes('شيوع');
}

/**
 * درجة البداءة عند الإنشاء: أولى أو أخيرة حصراً حسب القيمة.
 * الاستئناف والاعتراض على الحكم الغيابي ليستا خياري فتح — يُرفعان من داخل الإضبارة.
 * اعتراض الغير وإعادة المحاكمة تبقيان خياري إنشاء مستقلّين.
 * أقل من مليون / غير مقدّرة / رسم مقطوع / تخلي أو شيوع → بدرجة أخيرة فقط.
 * أكثر من مليون دون تلك الحالات → بدرجة أولى فقط.
 */
export function computeOpeningDegreeOptions(input: OpeningLawsuitStageInput): string[] {
    const type = String(input.caseType ?? '');
    const amount = parseLawsuitClaimValueAmount(input.claimValue);

    if (forcesLastDegreeType(type) || input.isUndeterminedValue || input.isFixedFee) {
        return [OPENING_STAGE_LAST_DEGREE];
    }
    if (amount > LAWSUIT_FIRST_INSTANCE_DEGREE_THRESHOLD) {
        return [OPENING_STAGE_FIRST_DEGREE];
    }
    if (amount > 0) {
        return [OPENING_STAGE_LAST_DEGREE];
    }
    return [OPENING_STAGE_FIRST_DEGREE, OPENING_STAGE_LAST_DEGREE];
}

/** طعون استثنائية تُفتح ملفاً جديداً — ليست استئنافاً ولا اعتراضاً غيابياً. */
export const OPENING_EXTRAORDINARY_STAGES = ['اعتراض الغير', 'إعادة المحاكمة'] as const;

export function isOpeningExtraordinaryStage(stage: string): boolean {
    return (OPENING_EXTRAORDINARY_STAGES as readonly string[]).includes(stage);
}

export function computeOpeningLawsuitStageOptions(input: OpeningLawsuitStageInput): string[] {
    return [...computeOpeningDegreeOptions(input), ...OPENING_EXTRAORDINARY_STAGES];
}

export function isOpeningDegreeStage(stage: string): boolean {
    return stage === OPENING_STAGE_FIRST_DEGREE || stage === OPENING_STAGE_LAST_DEGREE;
}

/**
 * يُثبّت درجة البداءة عندما لا يبقى إلا خيار واحد.
 * يُبقي اعتراض الغير وإعادة المحاكمة. يمسح الاستئناف والاعتراض الغيابي من نموذج الفتح.
 */
export function snapOpeningStageToDegrees(currentStage: string, degrees: string[]): string {
    if (isOpeningExtraordinaryStage(currentStage)) return currentStage;
    if (degrees.includes(currentStage)) return currentStage;
    if (degrees.length === 1) return degrees[0]!;
    return '';
}

import type { FileData } from './lawsuitFileTypes';
import { reloadLawsuitFilesFromStorage, type LawsuitFileSegments } from '@/app/domain/lawsuit/lawsuitFilesRepository';
import { bootHasLawsuitRecords } from '@/app/domain/lawsuit/lawsuitFilesStatePolicy';
import { applyLawsuitMonolithicMergeToSegments } from '@/app/domain/lawsuit/lawsuitSegmentStorage';
import { awaitLawsuitWorkspaceCommit } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import { loadLawsuitFilesRaw } from '@/app/utils/lawsuitFilesStorage';
import {
    ensureLawsuitDossierTombstonesReadable,
    excludeTombstonedLawsuitFiles,
} from '@/app/utils/lawsuitDossierTombstones';
import SecureStoreService from '@/app/services/SecureStoreService';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_STORAGE_KEYS_LEGACY,
    LAWSUIT_FILES_TRASH_KEY,
    LAWSUIT_SEGMENT_WARM_KEYS,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';

const ENCRYPTED_PREFIX = 'hami_enc_v2:';

export type LawsuitRecoveryDiagnosis = {
    diskCipherPresent: boolean;
    diskActiveCount: number;
    memoryActiveCount: number;
    monolithicCount: number;
    backupCount: number;
    cloudCount: number;
    legacyLocalCount: number;
    decryptLikelyBroken: boolean;
};

export type LawsuitRecoveryResult = {
    ok: boolean;
    segments: LawsuitFileSegments;
    source:
        | 'active'
        | 'monolithic'
        | 'backup'
        | 'cloud'
        | 'legacy-ls'
        | 'emergency'
        | 'none';
    diagnosis: LawsuitRecoveryDiagnosis;
    message: string;
};

export type LawsuitRecoveryOptions = {
    /** افتراضي true — بعد الفشل المحلي تُجرَّب نقطة العمل/المزامنة إن كانت حيّة */
    includeCloud?: boolean;
    /** افتراضي false — لا تنتظر فك الجزائي/المنتدى. true لمسار الترحيل الشامل فقط. */
    fullPersistReady?: boolean;
};

function emptySegments(): LawsuitFileSegments {
    try {
        return reloadLawsuitFilesFromStorage();
    } catch {
        return {
            active: [],
            archived: null,
            trash: null,
            index: {
                v: 1,
                entries: {},
                counts: { active: 0, archived: 0, trash: 0 },
            },
        };
    }
}

function parseFilesArray(raw: string | null | undefined): FileData[] {
    if (!raw) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? (parsed as FileData[]) : [];
    } catch {
        return [];
    }
}

async function safeGetItem(key: string): Promise<string | null> {
    try {
        return await SecureStoreService.getItem(key);
    } catch {
        return null;
    }
}

async function safePeek(key: string): Promise<string | null> {
    try {
        return await SecureStoreService.peekRawFromDisk(key);
    } catch {
        return null;
    }
}

async function safeGetFromDisk(key: string): Promise<string | null> {
    try {
        return await SecureStoreService.getItemFromDisk(key);
    } catch {
        return null;
    }
}

function readLegacyLocalStorageArrays(): FileData[] {
    if (typeof window === 'undefined') return [];
    const keys = [LAWSUIT_FILES_STORAGE_KEY, ...LAWSUIT_FILES_STORAGE_KEYS_LEGACY];
    const merged: FileData[] = [];
    const seen = new Set<string>();
    try {
        for (const key of keys) {
            const raw = readSecureOrDrainLegacySync(key);
            if (!raw || raw.startsWith(ENCRYPTED_PREFIX)) continue;
            const rows = parseFilesArray(raw);
            for (const row of rows) {
                const id = String(row?.id ?? '');
                if (!id || seen.has(id)) continue;
                seen.add(id);
                merged.push(row);
            }
        }
    } catch {
        /* ignore */
    }
    return merged;
}

async function readEmergencyBackupArrays(): Promise<FileData[]> {
    const keys = [
        `emergency_backup_${LAWSUIT_FILES_STORAGE_KEY}`,
        `backup_${LAWSUIT_FILES_STORAGE_KEY}`,
        `emergency_backup_${LAWSUIT_FILES_ACTIVE_KEY}`,
        `backup_${LAWSUIT_FILES_ACTIVE_KEY}`,
    ];
    for (const key of keys) {
        const raw = await safeGetItem(key);
        if (!raw) continue;
        try {
            const parsed: unknown = JSON.parse(raw);
            if (Array.isArray(parsed)) return parsed as FileData[];
            if (parsed && typeof parsed === 'object' && 'data' in parsed) {
                const data = (parsed as { data: unknown }).data;
                if (Array.isArray(data)) return data as FileData[];
            }
        } catch {
            /* continue */
        }
    }
    return [];
}

function hasRecoveredRows(segments: LawsuitFileSegments): boolean {
    return (
        segments.active.length > 0 ||
        segments.index.counts.active > 0 ||
        segments.index.counts.archived > 0 ||
        segments.index.counts.trash > 0
    );
}

async function applyRecoveredPayload(
    files: FileData[],
    source: LawsuitRecoveryResult['source'],
): Promise<LawsuitRecoveryResult | null> {
    if (!Array.isArray(files) || files.length === 0) return null;
    try {
        await ensureLawsuitDossierTombstonesReadable();
        const stripped = excludeTombstonedLawsuitFiles(files);
        if (stripped.length === 0) return null;
        applyLawsuitMonolithicMergeToSegments(stripped);
    } catch {
        return null;
    }

    /*
     * التحقّق يقرأ المقاطع فوراً بعد الدمج. تثبيت الديمومة يُفرّغ المرآة المتزامنة
     * مؤقتاً أثناء إعادة الكتابة، فقراءة ما بعده كانت تُبلّغ فشل استعادة زائفاً
     * ثم تُنسب البيانات لمصدر لاحق (السحابة).
     */
    let segments = reloadLawsuitFilesFromStorage();
    if (!hasRecoveredRows(segments)) return null;

    try {
        await awaitLawsuitWorkspaceCommit({ timeoutMs: 8_000 });
        const committed = reloadLawsuitFilesFromStorage();
        if (hasRecoveredRows(committed) && committed.active.length >= segments.active.length) {
            segments = committed;
        }
    } catch {
        /* الديمومة أفضل جهد — الدمج والتحقّق نجحا بالفعل */
    }
    return {
        ok: true,
        segments,
        source,
        diagnosis: {
            diskCipherPresent: false,
            diskActiveCount: segments.active.length,
            memoryActiveCount: segments.active.length,
            monolithicCount: files.length,
            backupCount: 0,
            cloudCount: 0,
            legacyLocalCount: 0,
            decryptLikelyBroken: false,
        },
        message:
            segments.active.length > 0
                ? `تمت استعادة ${segments.active.length} إضبارة نشطة`
                : 'تمت الاستعادة — راجع الأرشيف أو السلة من الفلاتر',
    };
}

/**
 * استعادة جذرية متعددة المصادر — لا ترمي أبداً.
 */
export async function recoverLawsuitWorkspaceFromLocalDisk(
    options?: LawsuitRecoveryOptions,
): Promise<LawsuitRecoveryResult> {
    const diagnosis: LawsuitRecoveryDiagnosis = {
        diskCipherPresent: false,
        diskActiveCount: 0,
        memoryActiveCount: 0,
        monolithicCount: 0,
        backupCount: 0,
        cloudCount: 0,
        legacyLocalCount: 0,
        decryptLikelyBroken: false,
    };

    const fail = (message: string): LawsuitRecoveryResult => ({
        ok: false,
        segments: emptySegments(),
        source: 'none',
        diagnosis,
        message,
    });

    const includeCloud = options?.includeCloud !== false;
    const fullPersistReady = options?.fullPersistReady === true;

    try {
        try {
            await SecureStoreService.ensureLawsuitKeysReady();
        } catch {
            /* continue */
        }
        if (fullPersistReady) {
            try {
                await SecureStoreService.ensurePersistedReady();
            } catch {
                /* continue */
            }
        }

        for (const key of LAWSUIT_SEGMENT_WARM_KEYS) {
            await safeGetItem(key);
        }

        const peeks = await Promise.all(
            [...LAWSUIT_SEGMENT_WARM_KEYS].map(async (key) => ({
                key,
                raw: await safePeek(key),
            })),
        );
        diagnosis.diskCipherPresent = peeks.some((p) => p.raw?.startsWith(ENCRYPTED_PREFIX));

        /*
         * معلّقات الإنشاء + سجل WAL (SecureStore مشفّر، مع ترحيل بقايا صريحة).
         * كانت تُتجاهل فتظهر الخزنة فارغة رغم وجود إضبارة معلّقة.
         */
        try {
            const {
                flushLawsuitDurabilityOverlaysToActive,
                mergeLawsuitDurabilityOverlaysInto,
                lawsuitDurabilityHasUncommittedWrites,
            } = await import('@/app/domain/lawsuit/lawsuitDurabilityOverlay');
            const { listPendingLawsuitCreates } = await import(
                '@/app/domain/lawsuit/lawsuitPendingCreateStore',
            );
            const pending = listPendingLawsuitCreates();
            if (lawsuitDurabilityHasUncommittedWrites()) {
                await flushLawsuitDurabilityOverlaysToActive();
                let bootPending = reloadLawsuitFilesFromStorage();
                bootPending = {
                    ...bootPending,
                    active: mergeLawsuitDurabilityOverlaysInto(bootPending.active),
                };
                if (bootPending.active.length > 0) {
                    return {
                        ok: true,
                        segments: bootPending,
                        source: 'emergency',
                        diagnosis: {
                            ...diagnosis,
                            diskActiveCount: bootPending.active.length,
                            memoryActiveCount: bootPending.active.length,
                            legacyLocalCount: pending.length,
                        },
                        message: `تمت استعادة ${bootPending.active.length} إضبارة (منها معلّقات إنشاء)`,
                    };
                }
                const appliedPending = await applyRecoveredPayload(pending, 'emergency');
                if (appliedPending) {
                    return {
                        ...appliedPending,
                        diagnosis: {
                            ...diagnosis,
                            ...appliedPending.diagnosis,
                            legacyLocalCount: pending.length,
                        },
                    };
                }
            }
        } catch {
            /* ignore */
        }

        const diskActivePlain = parseFilesArray(await safeGetFromDisk(LAWSUIT_FILES_ACTIVE_KEY));
        const diskMonoPlain = parseFilesArray(await safeGetFromDisk(LAWSUIT_FILES_STORAGE_KEY));
        diagnosis.diskActiveCount = diskActivePlain.length;
        diagnosis.memoryActiveCount = parseFilesArray(
            readSecureOrDrainLegacySync(LAWSUIT_FILES_ACTIVE_KEY),
        ).length;

        if (diskActivePlain.length > diagnosis.memoryActiveCount) {
            try {
                SecureStoreService.setItemSync(
                    LAWSUIT_FILES_ACTIVE_KEY,
                    JSON.stringify(diskActivePlain),
                    { allowShrink: true },
                );
            } catch {
                /* ignore */
            }
        }

        let boot = reloadLawsuitFilesFromStorage();
        try {
            const { mergeLawsuitDurabilityOverlaysInto } = await import(
                '@/app/domain/lawsuit/lawsuitDurabilityOverlay',
            );
            boot = {
                ...boot,
                active: mergeLawsuitDurabilityOverlaysInto(boot.active),
            };
        } catch {
            /* ignore */
        }
        if (bootHasLawsuitRecords(boot) || boot.active.length > 0) {
            return {
                ok: true,
                segments: boot,
                source: 'active',
                diagnosis: {
                    ...diagnosis,
                    diskActiveCount: boot.active.length,
                    memoryActiveCount: boot.active.length,
                },
                message:
                    boot.active.length > 0
                        ? `تمت استعادة ${boot.active.length} إضبارة نشطة`
                        : 'المقاطع على القرص هي مصدر الحقيقة — لا استيراد من المرآة',
            };
        }

        const monoSync = loadLawsuitFilesRaw() as FileData[];
        diagnosis.monolithicCount = monoSync.length;
        if (monoSync.length > 0) {
            const applied = await applyRecoveredPayload(monoSync, 'monolithic');
            if (applied) return { ...applied, diagnosis: { ...diagnosis, ...applied.diagnosis } };
        }

        if (diskMonoPlain.length > 0) {
            const applied = await applyRecoveredPayload(diskMonoPlain, 'monolithic');
            if (applied) return { ...applied, diagnosis: { ...diagnosis, ...applied.diagnosis } };
        }

        try {
            const { listDossierBackups } = await import(
                '@/app/services/dossierPersistence/dossierBackupStore'
            );
            const backups = await listDossierBackups('lawsuit');
            diagnosis.backupCount = backups.reduce((n, b) => n + (b.payload?.length ?? 0), 0);
            for (const backup of backups) {
                const rows = backup.payload as FileData[];
                if (!rows.length) continue;
                const applied = await applyRecoveredPayload(rows, 'backup');
                if (applied) {
                    return {
                        ...applied,
                        diagnosis: { ...diagnosis, backupCount: diagnosis.backupCount },
                    };
                }
            }
        } catch {
            /* ignore */
        }

        const emergency = await readEmergencyBackupArrays();
        if (emergency.length > 0) {
            const applied = await applyRecoveredPayload(emergency, 'emergency');
            if (applied) return { ...applied, diagnosis };
        }

        const legacy = readLegacyLocalStorageArrays();
        diagnosis.legacyLocalCount = legacy.length;
        if (legacy.length > 0) {
            const applied = await applyRecoveredPayload(legacy, 'legacy-ls');
            if (applied) return { ...applied, diagnosis };
        }

        if (includeCloud) {
            try {
                const { restoreLastWorkCloudCheckpoint } = await import(
                    '@/app/services/cloud/workCloudCheckpoint'
                );
                const restored = await restoreLastWorkCloudCheckpoint();
                if (restored.applied && restored.lawsuits > 0) {
                    boot = reloadLawsuitFilesFromStorage();
                    diagnosis.cloudCount = boot.active.length + boot.index.counts.archived;
                    if (boot.active.length > 0 || boot.index.counts.active > 0 || boot.index.counts.archived > 0) {
                        return {
                            ok: true,
                            segments: boot,
                            source: 'cloud',
                            diagnosis,
                            message: `تمت الاستعادة من آخر نقطة سحابية — ${boot.active.length} إضبارة`,
                        };
                    }
                }
            } catch {
                /* ignore */
            }
            try {
                const { performCloudSyncBucket } = await import('@/app/services/cloudSyncEngine');
                const pulled = await performCloudSyncBucket(LAWSUIT_FILES_STORAGE_KEY);
                /* سلة معطّلة أو مزامنة ممتنعة = لا شيء نزل من الشبكة؛ لا تنسب النتيجة للسحابة */
                if (pulled.ok && pulled.skipped !== true) {
                    boot = reloadLawsuitFilesFromStorage();
                    diagnosis.cloudCount = boot.active.length + boot.index.counts.archived;
                    if (
                        boot.active.length > 0 ||
                        boot.index.counts.active > 0 ||
                        boot.index.counts.archived > 0
                    ) {
                        return {
                            ok: true,
                            segments: boot,
                            source: 'cloud',
                            diagnosis,
                            message:
                                boot.active.length > 0
                                    ? `تمت الاستعادة من السحابة — ${boot.active.length} إضبارة`
                                    : 'تمت الاستعادة من السحابة — راجع الأرشيف/السلة',
                        };
                    }
                }
            } catch {
                /* cloud may be offline / unauthenticated */
            }
        }

        diagnosis.decryptLikelyBroken =
            diagnosis.diskCipherPresent &&
            diagnosis.diskActiveCount === 0 &&
            diagnosis.monolithicCount === 0 &&
            diagnosis.backupCount === 0;

        if (diagnosis.decryptLikelyBroken) {
            return fail(
                'وُجدت بيانات مشفّرة محلياً لكن مفتاح الفكّ غير جاهز — أعد فتح التطبيق أو استورد نسخة العمل من الإعدادات. السحابة اختيارية للمزامنة فقط',
            );
        }

        if (diagnosis.backupCount === 0 && diagnosis.cloudCount === 0 && diagnosis.legacyLocalCount === 0) {
            return fail(
                'لا توجد دعاوى في التخزين المحلي ولا في النسخ الاحتياطية — استورد نسخة من الإعدادات إن توفّرت',
            );
        }

        return fail('تعذّر تطبيق بيانات الاستعادة — جرّب نسخة احتياطية من الإعدادات');
    } catch {
        return fail('حدث خطأ أثناء الاستعادة — أعد المحاولة أو استورد نسخة من الإعدادات');
    }
}

import type { FileData } from './lawsuitFileTypes';
import { mergeRicherLawsuitActive } from '@/app/domain/lawsuit/lawsuitActiveDurability';
import { awaitLawsuitWorkspaceCommit } from '@/app/domain/lawsuit/lawsuitPersistFlush';
import SecureStoreService from '@/app/services/SecureStoreService';
import { LAWSUIT_FILES_ACTIVE_KEY } from '@/app/services/dossierPersistence/dossierStorageKeys';
import { markLawsuitJournaledThisPage } from '@/app/domain/lawsuit/lawsuitPageWriteGuard';
import {
    clearSecureJsonValue,
    readSecureJsonRawSync,
    writeSecureJsonValue,
} from '@/app/services/storage/syncSecureJson';

/**
 * سجل كتابة append-only — مشفّر في SecureStore (نسخ FileData: أسماء وأرقام دعاوى).
 * ليس في قشرة الإقلاع ولا PROTECTED_WARM (الحمولة قد تكون ثقيلة).
 * `flushLawsuitJournalToActive` يفكّ المفتاح إن كان بارداً ثم يدمج.
 * يُمسح فقط بعد إثبات القرص.
 */
export const LAWSUIT_WRITE_JOURNAL_KEY = 'hami_lawsuit_write_journal_v1';

const JOURNAL_CAP = 80;

export type LawsuitWriteJournalEntry = {
    v: 1;
    fileId: string;
    file: FileData;
    ts: number;
};

function parseEntries(raw: string | null): LawsuitWriteJournalEntry[] {
    if (!raw?.trim()) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(
            (row): row is LawsuitWriteJournalEntry =>
                !!row &&
                typeof row === 'object' &&
                (row as LawsuitWriteJournalEntry).v === 1 &&
                typeof (row as LawsuitWriteJournalEntry).fileId === 'string' &&
                !!(row as LawsuitWriteJournalEntry).file,
        );
    } catch {
        return [];
    }
}

function readRaw(): LawsuitWriteJournalEntry[] {
    return parseEntries(readSecureJsonRawSync(LAWSUIT_WRITE_JOURNAL_KEY));
}

function writeRaw(entries: LawsuitWriteJournalEntry[]): void {
    if (entries.length === 0) {
        if (SecureStoreService.isUnreadSync(LAWSUIT_WRITE_JOURNAL_KEY)) return;
        clearSecureJsonValue(LAWSUIT_WRITE_JOURNAL_KEY);
        return;
    }
    writeSecureJsonValue(LAWSUIT_WRITE_JOURNAL_KEY, entries);
}

export function clearLawsuitWriteJournalForTests(): void {
    clearSecureJsonValue(LAWSUIT_WRITE_JOURNAL_KEY);
}

export async function settleLawsuitJournalPersist(): Promise<void> {
    await SecureStoreService.waitForPendingSetItem(LAWSUIT_WRITE_JOURNAL_KEY);
}

export function listLawsuitJournalEntries(): LawsuitWriteJournalEntry[] {
    return readRaw();
}

export function hasUnverifiedLawsuitJournal(): boolean {
    return readRaw().length > 0;
}

export function isLawsuitJournalStillOpen(fileId: string | number): boolean {
    const id = String(fileId);
    return readRaw().some((entry) => entry.fileId === id);
}

/** تسجيل محاولة كتابة قبل active segment — WAL */
export function stageLawsuitJournalRecords(files: readonly FileData[]): void {
    if (!files.length) return;
    const byId = new Map(readRaw().map((entry) => [entry.fileId, entry]));
    const ts = Date.now();
    for (const file of files) {
        const fileId = String(file.id ?? '');
        if (!fileId) continue;
        markLawsuitJournaledThisPage(fileId);
        byId.set(fileId, { v: 1, fileId, file, ts });
    }
    writeRaw(Array.from(byId.values()).slice(-JOURNAL_CAP));
}

export function mergeLawsuitJournalInto(active: FileData[]): FileData[] {
    const entries = readRaw();
    if (entries.length === 0) return active;
    return mergeRicherLawsuitActive(
        active,
        entries.map((entry) => entry.file),
    );
}

export function pruneLawsuitJournalForFileIds(fileIds: readonly (string | number)[]): void {
    const ids = new Set(fileIds.map(String));
    if (ids.size === 0) return;
    writeRaw(readRaw().filter((entry) => !ids.has(entry.fileId)));
}

/**
 * بعد تسخين المفاتيح: ادمج السجل في النشط وثبّت القرص.
 * يُمسح السجل فقط بعد تحقق القرص.
 */
export async function flushLawsuitJournalToActive(): Promise<number> {
    if (SecureStoreService.isUnreadSync(LAWSUIT_WRITE_JOURNAL_KEY)) {
        await SecureStoreService.getItem(LAWSUIT_WRITE_JOURNAL_KEY);
    }
    const entries = readRaw();
    if (entries.length === 0) return 0;
    if (SecureStoreService.isUnreadSync(LAWSUIT_FILES_ACTIVE_KEY)) return 0;

    const {
        loadLawsuitBootSegments,
        persistLawsuitFiles,
    } = await import('@/app/domain/lawsuit/lawsuitFilesRepository');
    const boot = loadLawsuitBootSegments().active;
    const merged = mergeLawsuitJournalInto(boot);
    persistLawsuitFiles(merged);

    /* ديناميكي: كسر دائرة Journal → Verify → Journal عند تهيئة الوحدة */
    const { tryFinalizeLawsuitJournalAfterProof } = await import(
        '@/app/domain/lawsuit/lawsuitDurabilityVerify'
    );
    let cleared = 0;
    for (const entry of entries) {
        const commit = await awaitLawsuitWorkspaceCommit({
            timeoutMs: 8_000,
            requireActiveFileId: entry.fileId,
        });
        const didClear = await tryFinalizeLawsuitJournalAfterProof(entry.fileId, commit);
        if (didClear) cleared += 1;
    }
    return cleared;
}

/**
 * LitigationDecisionEngine — محرك قرار نقي (Pure Domain)
 * =================================================================
 * مصدر حقيقة لعقد القبول المدني (تعدد مدعى عليهم + اختصام).
 * لا يعتمد على واجهات ولا محركات تشغيلية أخرى.
 *
 * عقد حسم التعارضات:
 * - م/190: hasCrossAppeal خامل فقط
 * - م/172: isJointOrIndivisible حارس إلزامي للاستئخار
 * - م/168: PARTIAL ⇒ canAppeal = true
 */
export type PartyOutcome = 'FULL_WIN' | 'FULL_LOSS' | 'PARTIAL' | 'EXEMPT';

export type PresenceForm = 'HADORI' | 'GHIABI';

export type ObjectionPath = 'NONE' | 'PENDING' | 'DIRECT_APPEAL' | 'SUCCEEDED_QUASH';

export type StagingStatus = 'ACTIVE' | 'FALSE';

export type PartyRole = 'plaintiff' | 'defendant' | 'interpleader';

/** حالة التفرد بعد الحكم — Party-Level Independence */
export type DispositionState =
    | 'EXEMPT'
    | 'RELEASED'
    | 'ELIGIBLE_FOR_APPEAL'
    | 'ELIGIBLE_FOR_OBJECTION_OR_DIRECT_APPEAL';

export type MatrixParty = {
    id: string;
    name?: string;
    role: PartyRole;
    outcome: PartyOutcome;
    form: PresenceForm;
    /** تدخل إرادي م/66 دائماً HADORI؛ إدخال جبري م/69 قد يكون GHAYABI */
    interpleaderKind?: 'voluntary_66' | 'compulsory_69';
    /** هل قيّد طعنه في هذه الإضبارة بعد؟ */
    challengeConsumed?: boolean;
};

export type MatrixInput = {
    parties: MatrixParty[];
    /** تضامن أو عدم قابلية تجزئة — حارس م/172 */
    isJointOrIndivisible: boolean;
    /**
     * اعتراض الغائب الملزَم إن وُجد.
     * partyId يشير للغائب الذي قيّد/أنهى الاعتراض.
     */
    ghayabiObjection?: {
        partyId: string;
        path: ObjectionPath;
    };
    /**
     * م/190 — خامل فقط في هذه المرحلة (لا مسارات تشغيل).
     * Feature Flag للواجهة: مؤجّل.
     */
    hasCrossAppeal?: boolean;
};

export type PartyDecision = {
    id: string;
    role: PartyRole;
    outcome: PartyOutcome;
    dispositionState: DispositionState;
    canAppeal: boolean;
    appealSuspendedByStaging: boolean;
    clockExtinguished: boolean;
    exempt: boolean;
};

export type TopBarAction = {
    kind: 'SPAWN_INDEPENDENT_CHALLENGE';
    label: string;
    challengerId: string;
    challengerName: string;
    /** لا يُعدَّل الملف المفتوح — يُستدعى spawnSmartBranchDossier */
    mutatesOpenDossier: false;
};

export type LineageSpawn = {
    parentId: string;
    originStageId: string;
    appellantId: string;
    appelleeIds: string[];
    /** أسماء المبرَّئين مستبعدة من قائمة الخصوم */
    excludedExemptIds: string[];
};

export type ConsolidationDecision = {
    unifiedRollSessionId: string;
    /** أرقام الأقلام تبقى مستقلة */
    retainedCaseNumbers: string[];
    mergesAdministrativeIdentity: false;
};

export type MatrixDecision = {
    staging: StagingStatus;
    parties: PartyDecision[];
    /** أزرار الشريط العلوي — طاعنون مؤهلون لم يقيّدوا بعد */
    topBarActions: TopBarAction[];
    /** إضبارة منشقة عند انقلاب المراكز (مدعي ضد المعترض الفائز) */
    spawnInvertedDossier: null | {
        appellantId: string;
        appelleeId: string;
        reason: 'ROLE_INVERSION_AFTER_OBJECTION_QUASH';
    };
    /** حقل خامل م/190 — لا يولّد إضبارة */
    hasCrossAppeal: boolean;
};

/** م/168: بوابة المصلحة من أثر الحكم فقط */
export function canAppealFromOutcome(outcome: PartyOutcome): boolean {
    if (outcome === 'FULL_WIN' || outcome === 'EXEMPT') return false;
    if (outcome === 'FULL_LOSS' || outcome === 'PARTIAL') return true;
    return false;
}

/**
 * تحويل نتيجة الموكل إلى كود مسار تشغيلي (بدون واجهة).
 * - FULL_WIN / EXEMPT → انتظار طعن الخصم
 * - FULL_LOSS → طعن ذاتي
 * - PARTIAL → both_paths (بداءة) أو self_appeal (اختصام — التلميح يذكر الطرفين)
 */
export type OperationalAppealAction = 'wait_opponent' | 'self_appeal' | 'both_paths';

export function resolveOperationalAppealAction(
    outcome: PartyOutcome,
    options?: { partialAction?: 'both_paths' | 'self_appeal' },
): OperationalAppealAction {
    if (!canAppealFromOutcome(outcome)) return 'wait_opponent';
    if (outcome === 'PARTIAL') return options?.partialAction ?? 'both_paths';
    return 'self_appeal';
}

/** تفريد الحالة بعد الحكم — لا كتلة مدمجة */
export function resolveDispositionState(
    outcome: PartyOutcome,
    form: PresenceForm,
): DispositionState {
    if (outcome === 'EXEMPT' || outcome === 'FULL_WIN') {
        return outcome === 'EXEMPT' ? 'EXEMPT' : 'RELEASED';
    }
    if (!canAppealFromOutcome(outcome)) return 'RELEASED';
    if (form === 'GHIABI') return 'ELIGIBLE_FOR_OBJECTION_OR_DIRECT_APPEAL';
    return 'ELIGIBLE_FOR_APPEAL';
}

/**
 * مهلة الغائب: من اليوم التالي للتبليغ فقط — يُحظر النطق.
 * الحاضر: من اليوم التالي للنطق.
 */
export function resolveChallengeClockAnchor(params: {
    form: PresenceForm;
    judgmentPronouncementDate: string;
    officialServiceDate?: string | null;
}): { anchorDate: string | null; source: 'PRONOUNCEMENT' | 'SERVICE' | null } {
    if (params.form === 'GHIABI') {
        const service = String(params.officialServiceDate ?? '').trim();
        if (!service) return { anchorDate: null, source: null };
        return { anchorDate: service, source: 'SERVICE' };
    }
    return { anchorDate: params.judgmentPronouncementDate, source: 'PRONOUNCEMENT' };
}

/**
 * م/172 زناد رباعي:
 * LIABLE ∧ GHAYABI ∧ Objection PENDING ∧ isJointOrIndivisible
 */
export function resolveStaging(input: MatrixInput): StagingStatus {
    if (!input.isJointOrIndivisible) return 'FALSE';
    const obj = input.ghayabiObjection;
    if (!obj || obj.path !== 'PENDING') return 'FALSE';
    const p = input.parties.find((row) => row.id === obj.partyId);
    if (!p) return 'FALSE';
    const liable = p.outcome === 'FULL_LOSS' || p.outcome === 'PARTIAL';
    if (!liable) return 'FALSE';
    if (p.form !== 'GHIABI') return 'FALSE';
    return 'ACTIVE';
}

/** شريط علوي: مؤهل لم يستهلك طعنه — لا تكديس داخل بطاقة المرحلة */
export function resolveTopBarChallengeActions(
    parties: MatrixParty[],
    decisions: PartyDecision[],
): TopBarAction[] {
    const byId = new Map(decisions.map((d) => [d.id, d]));
    const eligible = parties.filter((row) => {
        const d = byId.get(row.id);
        if (!d?.canAppeal || d.exempt || d.clockExtinguished) return false;
        if (row.challengeConsumed) return false;
        return true;
    });
    if (eligible.length <= 1) return [];
    return eligible.map((row) => ({
        kind: 'SPAWN_INDEPENDENT_CHALLENGE' as const,
        label: `تسجيل طعن مستقل باسم: ${row.name ?? row.id} — إنشاء إضبارة تابعة`,
        challengerId: row.id,
        challengerName: row.name ?? row.id,
        mutatesOpenDossier: false as const,
    }));
}

/** وراثة النسب + تصفية المبرَّئين */
export function buildLineageSpawn(params: {
    parentId: string;
    originStageId: string;
    challengerId: string;
    parties: MatrixParty[];
}): LineageSpawn {
    const challenger = params.parties.find((row) => row.id === params.challengerId);
    const exemptIds = params.parties
        .filter((row) => row.outcome === 'EXEMPT' || row.outcome === 'FULL_WIN')
        .map((row) => row.id)
        .filter((id) => id !== params.challengerId);

    if (challenger?.role === 'plaintiff') {
        const appellees = params.parties
            .filter((row) => row.role !== 'plaintiff' && !exemptIds.includes(row.id))
            .map((row) => row.id);
        return {
            parentId: params.parentId,
            originStageId: params.originStageId,
            appellantId: params.challengerId,
            appelleeIds: appellees,
            excludedExemptIds: exemptIds,
        };
    }

    const plaintiffs = params.parties.filter((row) => row.role === 'plaintiff').map((row) => row.id);
    return {
        parentId: params.parentId,
        originStageId: params.originStageId,
        appellantId: params.challengerId,
        appelleeIds: plaintiffs,
        excludedExemptIds: exemptIds,
    };
}

/** منع تناقض UI: الموكل لا يكون مستأنِفاً ومستأنَفاً عليه في نفس البطاقة */
export function assertsHomogeneousAppealCard(params: {
    clientPartyId: string;
    appellantIds: string[];
    appelleeIds: string[];
}): { ok: boolean; requiresSpawnedDossier: boolean } {
    const isAppellant = params.appellantIds.includes(params.clientPartyId);
    const isAppellee = params.appelleeIds.includes(params.clientPartyId);
    if (isAppellant && isAppellee) {
        return { ok: false, requiresSpawnedDossier: true };
    }
    return { ok: true, requiresSpawnedDossier: false };
}

/** توحيد قضائي: رول موحد بلا طمس أرقام الأقلام */
export function resolveJudicialConsolidation(params: {
    unifiedRollSessionId: string;
    caseNumbers: string[];
}): ConsolidationDecision {
    return {
        unifiedRollSessionId: params.unifiedRollSessionId,
        retainedCaseNumbers: [...params.caseNumbers],
        mergesAdministrativeIdentity: false,
    };
}

/**
 * م/190 — سطح المتقابل معطّل بقرار منتج (Feature Flag).
 * الحقل `hasCrossAppeal` على المرحلة خامل فقط؛ لا يفتح مسارات.
 */
export function isCrossAppealFeatureEnabled(): boolean {
    return false;
}

/** قراءة العلم الخامل دون تفعيل أهلية متقابل */
export function readDormantHasCrossAppeal(
    stage?: { hasCrossAppeal?: boolean } | null,
): boolean {
    return Boolean(stage?.hasCrossAppeal);
}

/** قرار مصفوفة خالص — مصدر حقيقة القبول */
export function resolveCivilLitigationMatrixDecision(input: MatrixInput): MatrixDecision {
    const staging = resolveStaging(input);
    const obj = input.ghayabiObjection;

    const spawnInvertedDossier =
        obj?.path === 'SUCCEEDED_QUASH'
            ? {
                  appellantId: input.parties.find((row) => row.role === 'plaintiff')?.id ?? 'plaintiff',
                  appelleeId: obj.partyId,
                  reason: 'ROLE_INVERSION_AFTER_OBJECTION_QUASH' as const,
              }
            : null;

    /** بعد إبطال ناجح عن الغائب: يُفك الاستئخار عن طعون الملزَمين الآخرين */
    const stagingReleasedAfterQuash = obj?.path === 'SUCCEEDED_QUASH';

    const parties: PartyDecision[] = input.parties.map((row) => {
        const exempt = row.outcome === 'EXEMPT';
        const canAppeal = canAppealFromOutcome(row.outcome);
        const clockExtinguished = exempt || row.outcome === 'FULL_WIN' || !canAppeal;
        const dispositionState = resolveDispositionState(row.outcome, row.form);

        const appealSuspendedByStaging =
            staging === 'ACTIVE'
            && canAppeal
            && row.id !== obj?.partyId
            && !stagingReleasedAfterQuash;

        return {
            id: row.id,
            role: row.role,
            outcome: row.outcome,
            dispositionState,
            canAppeal,
            appealSuspendedByStaging,
            clockExtinguished,
            exempt,
        };
    });

    return {
        staging: stagingReleasedAfterQuash ? 'FALSE' : staging,
        parties,
        topBarActions: resolveTopBarChallengeActions(input.parties, parties),
        spawnInvertedDossier,
        hasCrossAppeal: Boolean(input.hasCrossAppeal),
    };
}

/** مساعد اختبارات / مستهلكين: جلب قرار طرف بالمعرّف */
export function getPartyDecision(decision: MatrixDecision, id: string): PartyDecision {
    const row = decision.parties.find((p) => p.id === id);
    if (!row) throw new Error(`missing party ${id}`);
    return row;
}

/**
 * أثر قرار الاعتراض على الحكم الغيابي في الاستئناف المستأخر.
 * المسار خطي: لا رولين حيّين — فك سبب الاستئخار، عريضة أصلية عند الإبطال، توحيد الطعن اللاحق.
 */
export type AbsentObjectionOutcome = 'uphold' | 'form_reject' | 'void_full' | 'partial';
export type AbsentObjectionClientRole = 'objector' | 'objected' | null;

export const ART172_STAY_CAUSE_LIFTED =
    'زال سبب الاستئخار — قدّم طلب استئناف السير في الدعوى المستأخرة';

export const OBJECTION_VOID_PLAINTIFF_NEW_APPEAL_NOTICE =
    'لا تكتفِ بفك الاستئخار — سجّل عريضة استئناف أصلية للطعن في قرار الإبطال خلال 15 يوماً ثم وحّدها مع الاستئناف القائم';

export const ART172_VOID_EXTENDS_TO_PRESENT_NOTICE =
    'امتد أثر إبطال الحكم الغيابي لصالح الحاضر المستأنف عملاً بالمادة (172) مرافعات — اطلب فسخ الحكم بحق موكلك ورد دعوى المدعي';

export const OBJECTOR_UPHOLD_ORIGINAL_APPEAL_NOTICE =
    'لا استئناف متقابل ضد الشريك الحاضر (م/190) — السبيل عريضة استئناف أصلية خلال 15 يوماً ثم توحيدها مع استئناف الحاضر';

export const UNIFIED_APPEALS_TIMELINE_TITLE = 'توحيد الاستئنافين';

export function classifyAbsentObjectionOutcome(
    judgmentTypeOrDecision?: string | null,
): AbsentObjectionOutcome | null {
    const t = String(judgmentTypeOrDecision ?? '').trim();
    if (!t) return null;
    if (
        t.includes('رد الاعتراض شكلاً')
        || t.includes('إبطال الاعتراض')
        || t.includes('إبطاله للغياب')
        || (t.includes('م/179') && t.includes('اعتراض'))
    ) {
        return 'form_reject';
    }
    if (t.includes('رد الدعوى جزئياً') || t.includes('تعديل جزئي')) {
        return 'partial';
    }
    if (
        t.includes('رد الدعوى كلياً')
        || t.includes('تعديل الحكم الغيابي')
        || (t.includes('تعديل') && t.includes('الحكم') && !t.includes('جزئ'))
    ) {
        return 'void_full';
    }
    if (
        t.includes('إجابة الدعوى بالكامل')
        || t.includes('تأييد الحكم الغيابي')
        || (t.includes('تأييد') && t.includes('غيابي'))
    ) {
        return 'uphold';
    }
    return null;
}

export function objectionOutcomeLiftsStayCause(outcome: AbsentObjectionOutcome | null): boolean {
    return outcome === 'uphold'
        || outcome === 'form_reject'
        || outcome === 'void_full'
        || outcome === 'partial';
}

export function objectorMayFileOriginalAppeal(outcome: AbsentObjectionOutcome | null): boolean {
    return outcome === 'uphold' || outcome === 'partial';
}

export function plaintiffMustFileNewOriginalAppeal(outcome: AbsentObjectionOutcome | null): boolean {
    return outcome === 'void_full';
}

export function presentAppellantGainsArt172VoidCoverage(params: {
    outcome: AbsentObjectionOutcome | null;
    indivisible: boolean;
}): boolean {
    return params.outcome === 'void_full' && params.indivisible;
}

export function resolveObjectionAppealNotices(params: {
    outcome: AbsentObjectionOutcome | null;
    clientRole: AbsentObjectionClientRole;
    stayActive: boolean;
    objectionResolved: boolean;
    indivisible: boolean;
    clientIsPresentAppellant: boolean;
}): string[] {
    const notices: string[] = [];
    if (!params.objectionResolved || !params.outcome) return notices;

    if (params.stayActive && objectionOutcomeLiftsStayCause(params.outcome)) {
        notices.push(ART172_STAY_CAUSE_LIFTED);
    }

    if (params.clientRole === 'objected' && plaintiffMustFileNewOriginalAppeal(params.outcome)) {
        notices.push(OBJECTION_VOID_PLAINTIFF_NEW_APPEAL_NOTICE);
    }

    if (
        params.clientIsPresentAppellant
        && presentAppellantGainsArt172VoidCoverage({
            outcome: params.outcome,
            indivisible: params.indivisible,
        })
    ) {
        notices.push(ART172_VOID_EXTENDS_TO_PRESENT_NOTICE);
    }

    if (params.clientRole === 'objector' && objectorMayFileOriginalAppeal(params.outcome)) {
        notices.push(OBJECTOR_UPHOLD_ORIGINAL_APPEAL_NOTICE);
    }

    return notices;
}

export function resolveObjectionResumeWarning(params: {
    outcome: AbsentObjectionOutcome | null;
    clientRole: AbsentObjectionClientRole;
}): string | null {
    if (params.clientRole === 'objected' && plaintiffMustFileNewOriginalAppeal(params.outcome)) {
        return OBJECTION_VOID_PLAINTIFF_NEW_APPEAL_NOTICE;
    }
    return null;
}

/**
 * مسارا طعن الخصوم من حكم البداءة المختلط: استئناف الحاضر واعتراض الغائب.
 * المرحلة النشطة واحدة؛ المرحلتان تعيشان في الشريط. hop الثاني يُفتح من البداءة لا من الاستئناف.
 */
import {
    JUDGMENT_FORM_GHIABI,
    isPartyOperativeReleased,
    isPresentLikeJudgmentForm,
    normalizePartyJudgmentDispositions,
    resolveJudgmentPresenceWindows,
} from './partyJudgmentDisposition';
import {
    LANE_STATE_APPEAL,
    LANE_STATE_CASSATION,
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
    LANE_STATE_OBJECTION,
    LANE_STATE_WAIVED,
    normalizePartyChallengeLanes,
    type PartyChallengeLane,
} from './partyChallengeLanes';

const CONSUMED_LANE = new Set<string>([
    LANE_STATE_OBJECTION,
    LANE_STATE_APPEAL,
    LANE_STATE_CASSATION,
    LANE_STATE_WAIVED,
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
]);

function laneConsumed(lane: PartyChallengeLane): boolean {
    return CONSUMED_LANE.has(lane.laneState);
}

function dispositionReleasedSet(dispositions?: unknown): Set<string> {
    return new Set(
        normalizePartyJudgmentDispositions(dispositions)
            .filter(isPartyOperativeReleased)
            .map((row) => row.partyId),
    );
}

export function remainingGhayabiObjectionPartyIds(lanes: unknown, dispositions?: unknown): string[] {
    const released = dispositionReleasedSet(dispositions);
    const normalizedLanes = normalizePartyChallengeLanes(lanes);
    if (normalizedLanes.length > 0) {
        return normalizedLanes
            .filter(
                (lane) =>
                    lane.disposition === JUDGMENT_FORM_GHIABI
                    && !laneConsumed(lane)
                    && !released.has(lane.partyId),
            )
            .map((lane) => lane.partyId);
    }
    return normalizePartyJudgmentDispositions(dispositions)
        .filter((row) => row.form === JUDGMENT_FORM_GHIABI && !isPartyOperativeReleased(row))
        .map((row) => row.partyId);
}

export function remainingPresentAppealPartyIds(lanes: unknown, dispositions?: unknown): string[] {
    const released = dispositionReleasedSet(dispositions);
    const normalizedLanes = normalizePartyChallengeLanes(lanes);
    if (normalizedLanes.length > 0) {
        return normalizedLanes
            .filter(
                (lane) =>
                    isPresentLikeJudgmentForm(lane.disposition)
                    && !laneConsumed(lane)
                    && !released.has(lane.partyId),
            )
            .map((lane) => lane.partyId);
    }
    return normalizePartyJudgmentDispositions(dispositions)
        .filter((row) => isPresentLikeJudgmentForm(row.form) && !isPartyOperativeReleased(row))
        .map((row) => row.partyId);
}

export function firstInstanceHasMixedPresence(stage?: {
    judgmentForm?: string | null;
    lastJudgmentType?: string | null;
    partyJudgmentDispositions?: unknown;
} | null): boolean {
    if (!stage) return false;
    return resolveJudgmentPresenceWindows(
        normalizePartyJudgmentDispositions(stage.partyJudgmentDispositions),
        String(stage.judgmentForm ?? stage.lastJudgmentType ?? ''),
    ).mixed;
}

export function resolveRemainingOpponentChallengeMethods(params: {
    lanes?: unknown;
    dispositions?: unknown;
    /** @deprecated لم يعد يحجب المسار — الطعن يبقى حتى يستهلك كل مؤهل ليناه */
    hasObjectionStage?: boolean;
    /** @deprecated لم يعد يحجب المسار — الطعن يبقى حتى يستهلك كل مؤهل ليناه */
    hasAppealStageFromFirstInstance?: boolean;
}): string[] {
    void params.hasObjectionStage;
    void params.hasAppealStageFromFirstInstance;
    const methods: string[] = [];
    const objectionIds = remainingGhayabiObjectionPartyIds(params.lanes, params.dispositions);
    const presentAppealIds = remainingPresentAppealPartyIds(params.lanes, params.dispositions);
    /** أي غائب لم يستهلك حقه — يبقى زر الاعتراض حتى لو فُتحت اعتراضية لغيره */
    if (objectionIds.length > 0) {
        methods.push('اعتراض غيابي');
    }
    /** أي حاضر لم يطعن، أو غائب ما زال معلّقاً (يجوز استئناف/تمييز بدل الاعتراض) */
    if (presentAppealIds.length > 0 || objectionIds.length > 0) {
        methods.push('استئناف');
        methods.push('تمييز');
    }
    return methods;
}

export function hasRemainingOpponentChallengeTrack(params: {
    lanes?: unknown;
    dispositions?: unknown;
    hasObjectionStage?: boolean;
    hasAppealStageFromFirstInstance?: boolean;
}): boolean {
    return resolveRemainingOpponentChallengeMethods(params).length > 0;
}

/**
 * بطاقات الطعن الفردية — تتبع التبليغ والمهل لكل خصم دون فتح مراحل متوازية.
 * السيادة للموكل: المرحلة النشطة تتبع موكل الإضبارة؛ الشركاء/الخصوم على هذه البطاقات.
 */
import { addDaysToLocalYmd } from '@/app/utils/localYmd';
import {
    JUDGMENT_FORM_GHIABI,
    isDisputeIndivisible,
    isJudgmentPresenceForm,
    isPartyOperativeReleased,
    isPresentLikeJudgmentForm,
    listJudgmentDispositionDefendants,
    normalizePartyJudgmentDispositions,
    partyDispositionId,
    resolveClientDefendantJudgmentForm,
    seedPartyJudgmentDispositions,
    type DisputeIntegrity,
    type JudgmentPresenceForm,
    type PartyJudgmentDisposition,
} from './partyJudgmentDisposition';
import type { LawsuitPartyRoleRecord } from './lawsuitPartyRole';

export const LANE_STATE_PENDING = 'pending';
export const LANE_STATE_OBJECTION = 'objection';
export const LANE_STATE_APPEAL = 'appeal';
export const LANE_STATE_CASSATION = 'cassation';
export const LANE_STATE_WAIVED = 'waived';
export const LANE_STATE_LAPSED = 'lapsed';
export const LANE_STATE_LAPSED_EXECUTABLE = 'LAPSED_EXECUTABLE';
export const LANE_STATE_REVIVED_BY_CASSATION_EXTENSION = 'REVIVED_BY_CASSATION_EXTENSION';

export type PartyChallengeLaneState =
    | typeof LANE_STATE_PENDING
    | typeof LANE_STATE_OBJECTION
    | typeof LANE_STATE_APPEAL
    | typeof LANE_STATE_CASSATION
    | typeof LANE_STATE_WAIVED
    | typeof LANE_STATE_LAPSED
    | typeof LANE_STATE_LAPSED_EXECUTABLE
    | typeof LANE_STATE_REVIVED_BY_CASSATION_EXTENSION;

export type PartyChallengeLane = {
    partyId: string;
    disposition: JudgmentPresenceForm;
    servedAt?: string | null;
    objectionDeadline?: string | null;
    appealDeadline?: string | null;
    cassationDeadline?: string | null;
    laneState: PartyChallengeLaneState;
};

const LANE_STATES = new Set<PartyChallengeLaneState>([
    LANE_STATE_PENDING,
    LANE_STATE_OBJECTION,
    LANE_STATE_APPEAL,
    LANE_STATE_CASSATION,
    LANE_STATE_WAIVED,
    LANE_STATE_LAPSED,
    LANE_STATE_LAPSED_EXECUTABLE,
    LANE_STATE_REVIVED_BY_CASSATION_EXTENSION,
]);

/** مهلة الاعتراض الغيابي: 10 أيام من تاريخ التبليغ الشخصي (نفس محرك التبليغ القائم). */
export const LANE_OBJECTION_DAYS = 10;
/** مهلة الاستئناف: 15 يوماً من اليوم التالي لصدور الحكم (حاضر/بمثابة) أو للتبليغ (غائب). */
export const LANE_APPEAL_DAYS = 15;

export function computeLaneObjectionDeadline(servedAtYmd: string): string {
    return addDaysToLocalYmd(String(servedAtYmd ?? '').trim().slice(0, 10), LANE_OBJECTION_DAYS);
}

export function computeLaneAppealDeadlineFromService(servedAtYmd: string): string {
    const base = String(servedAtYmd ?? '').trim().slice(0, 10);
    const dayAfter = addDaysToLocalYmd(base, 1);
    return addDaysToLocalYmd(dayAfter, LANE_APPEAL_DAYS);
}

export function computeLaneAppealDeadlineFromJudgment(judgmentDateYmd: string): string {
    const base = String(judgmentDateYmd ?? '').trim().slice(0, 10);
    const dayAfter = addDaysToLocalYmd(base, 1);
    return addDaysToLocalYmd(dayAfter, LANE_APPEAL_DAYS);
}

/** مهلة التمييز: 30 يوماً من اليوم التالي للتبليغ الفعلي (م/210 — تمييز مباشر من البداءة). */
export const LANE_CASSATION_DAYS = 30;

export function computeLaneCassationDeadlineFromService(servedAtYmd: string): string {
    const base = String(servedAtYmd ?? '').trim().slice(0, 10);
    const dayAfter = addDaysToLocalYmd(base, 1);
    return addDaysToLocalYmd(dayAfter, LANE_CASSATION_DAYS);
}

export function computeLaneCassationDeadlineFromJudgment(judgmentDateYmd: string): string {
    const base = String(judgmentDateYmd ?? '').trim().slice(0, 10);
    const dayAfter = addDaysToLocalYmd(base, 1);
    return addDaysToLocalYmd(dayAfter, LANE_CASSATION_DAYS);
}

function parseLaneState(raw: unknown): PartyChallengeLaneState | null {
    const t = String(raw ?? '').trim();
    return LANE_STATES.has(t as PartyChallengeLaneState) ? (t as PartyChallengeLaneState) : null;
}

function ymdOrNull(raw: unknown): string | null {
    const t = String(raw ?? '').trim().slice(0, 10);
    return /^\d{4}-\d{2}-\d{2}$/.test(t) ? t : null;
}

export function normalizePartyChallengeLanes(raw: unknown): PartyChallengeLane[] {
    if (!Array.isArray(raw)) return [];
    const out: PartyChallengeLane[] = [];
    const seen = new Set<string>();
    for (const row of raw) {
        if (!row || typeof row !== 'object') continue;
        const rec = row as Record<string, unknown>;
        const partyId = String(rec.partyId ?? '').trim();
        if (!partyId || seen.has(partyId) || !isJudgmentPresenceForm(rec.disposition)) continue;
        const laneState = parseLaneState(rec.laneState) ?? LANE_STATE_PENDING;
        seen.add(partyId);
        out.push({
            partyId,
            disposition: rec.disposition,
            servedAt: ymdOrNull(rec.servedAt),
            objectionDeadline: ymdOrNull(rec.objectionDeadline),
            appealDeadline: ymdOrNull(rec.appealDeadline),
            cassationDeadline: ymdOrNull(rec.cassationDeadline),
            laneState,
        });
    }
    return out;
}

function seedLaneFromDisposition(
    partyId: string,
    form: JudgmentPresenceForm,
    existing: PartyChallengeLane | undefined,
    judgmentDate: string,
    released = false,
): PartyChallengeLane {
    if (released) {
        return {
            partyId,
            disposition: form,
            servedAt: existing?.servedAt ?? null,
            objectionDeadline: null,
            appealDeadline: null,
            cassationDeadline: null,
            laneState: LANE_STATE_WAIVED,
        };
    }
    const servedAt = existing?.servedAt ?? null;
    const present = isPresentLikeJudgmentForm(form);
    const appealFromJudgment = judgmentDate ? computeLaneAppealDeadlineFromJudgment(judgmentDate) : null;
    const cassationFromJudgment = judgmentDate ? computeLaneCassationDeadlineFromJudgment(judgmentDate) : null;
    return {
        partyId,
        disposition: form,
        servedAt,
        objectionDeadline:
            form === JUDGMENT_FORM_GHIABI
                ? (servedAt ? computeLaneObjectionDeadline(servedAt) : existing?.objectionDeadline ?? null)
                : null,
        appealDeadline: present
            ? (existing?.appealDeadline || appealFromJudgment)
            : servedAt
              ? computeLaneAppealDeadlineFromService(servedAt)
              : existing?.appealDeadline ?? null,
        cassationDeadline: present
            ? (existing?.cassationDeadline || cassationFromJudgment)
            : servedAt
              ? computeLaneCassationDeadlineFromService(servedAt)
              : existing?.cassationDeadline ?? null,
        laneState: existing?.laneState ?? LANE_STATE_PENDING,
    };
}

export function isScalarGhayabiJudgmentForm(raw?: string | null): boolean {
    const t = String(raw ?? '').trim();
    if (!t || t.includes('مختلط')) return false;
    return t === JUDGMENT_FORM_GHIABI || t.startsWith(JUDGMENT_FORM_GHIABI);
}

export function mergePartyChallengeLanes(params: {
    parties?: Array<LawsuitPartyRoleRecord & { name?: unknown; isClient?: boolean }> | null;
    dispositions?: PartyJudgmentDisposition[] | unknown;
    existing?: unknown;
    judgmentDate?: string | null;
    integrity?: DisputeIntegrity | string | null;
    today?: string | null;
    judgmentForm?: string | null;
}): PartyChallengeLane[] {
    const defendants = listJudgmentDispositionDefendants(params.parties ?? []);
    let dispositions = normalizePartyJudgmentDispositions(params.dispositions);
    if (dispositions.length === 0 && isScalarGhayabiJudgmentForm(params.judgmentForm)) {
        dispositions = seedPartyJudgmentDispositions(defendants, JUDGMENT_FORM_GHIABI);
    }
    const byDisposition = new Map(dispositions.map((row) => [row.partyId, row]));
    const existingById = new Map(
        normalizePartyChallengeLanes(params.existing).map((lane) => [lane.partyId, lane]),
    );
    const judgmentDate = String(params.judgmentDate ?? '').trim().slice(0, 10);
    const merged: PartyChallengeLane[] = [];
    const seen = new Set<string>();
    for (const party of defendants) {
        const partyId = partyDispositionId(party);
        if (!partyId || seen.has(partyId)) continue;
        seen.add(partyId);
        const row = byDisposition.get(partyId);
        const form = row?.form ?? existingById.get(partyId)?.disposition;
        if (!form) continue;
        merged.push(
            seedLaneFromDisposition(
                partyId,
                form,
                existingById.get(partyId),
                judgmentDate,
                isPartyOperativeReleased(row),
            ),
        );
    }
    if (merged.length === 0) {
        for (const row of dispositions) {
            if (seen.has(row.partyId)) continue;
            seen.add(row.partyId);
            merged.push(
                seedLaneFromDisposition(
                    row.partyId,
                    row.form,
                    existingById.get(row.partyId),
                    judgmentDate,
                    isPartyOperativeReleased(row),
                ),
            );
        }
    }
    return applySeverableLaneLapses(merged, params.integrity, params.today);
}

function deadlinePassed(deadline: string | null | undefined, today: string): boolean {
    const d = String(deadline ?? '').trim().slice(0, 10);
    if (!d) return false;
    return today > d;
}

export function applySeverableLaneLapses(
    lanes: PartyChallengeLane[],
    integrity?: DisputeIntegrity | string | null,
    todayYmd?: string | null,
): PartyChallengeLane[] {
    const today = String(todayYmd ?? '').trim().slice(0, 10);
    if (!today) return lanes;
    const executable = !isDisputeIndivisible(integrity);
    return lanes.map((lane) => {
        if (
            lane.laneState !== LANE_STATE_PENDING
            && lane.laneState !== LANE_STATE_LAPSED
            && lane.laneState !== LANE_STATE_LAPSED_EXECUTABLE
        ) {
            return lane;
        }
        const objectionOpen = lane.disposition === JUDGMENT_FORM_GHIABI && !deadlinePassed(lane.objectionDeadline, today);
        const appealOpen = !deadlinePassed(lane.appealDeadline, today);
        const cassationOpen = Boolean(lane.cassationDeadline) && !deadlinePassed(lane.cassationDeadline, today);
        const stillOpen =
            (lane.disposition === JUDGMENT_FORM_GHIABI && !lane.servedAt)
            || objectionOpen
            || appealOpen
            || cassationOpen;
        if (stillOpen) {
            if (
                lane.laneState === LANE_STATE_LAPSED
                || lane.laneState === LANE_STATE_LAPSED_EXECUTABLE
            ) {
                return { ...lane, laneState: LANE_STATE_PENDING };
            }
            return lane;
        }
        if (!lane.appealDeadline && lane.disposition === JUDGMENT_FORM_GHIABI) return lane;
        if (!lane.appealDeadline && isPresentLikeJudgmentForm(lane.disposition)) return lane;
        return {
            ...lane,
            laneState: executable ? LANE_STATE_LAPSED_EXECUTABLE : LANE_STATE_LAPSED,
        };
    });
}

export function isGhayabiJoinableLane(
    lane: PartyChallengeLane,
    todayYmd: string,
): boolean {
    if (lane.disposition !== JUDGMENT_FORM_GHIABI) return false;
    if (lane.laneState !== LANE_STATE_PENDING) return false;
    const servedAt = String(lane.servedAt ?? '').trim().slice(0, 10);
    if (!servedAt) return false;
    const deadline = lane.objectionDeadline || computeLaneObjectionDeadline(servedAt);
    if (!deadline) return false;
    return !deadlinePassed(deadline, todayYmd);
}

export function hasRegisteredObjectionLane(raw: unknown): boolean {
    return normalizePartyChallengeLanes(raw).some((lane) => lane.laneState === LANE_STATE_OBJECTION);
}

export function hasUnservedGhayabiLane(raw: unknown): boolean {
    return normalizePartyChallengeLanes(raw).some(
        (lane) =>
            lane.disposition === JUDGMENT_FORM_GHIABI
            && !lane.servedAt
            && lane.laneState !== LANE_STATE_OBJECTION
            && lane.laneState !== LANE_STATE_APPEAL
            && lane.laneState !== LANE_STATE_CASSATION
            && lane.laneState !== LANE_STATE_WAIVED
            && lane.laneState !== LANE_STATE_LAPSED
            && lane.laneState !== LANE_STATE_LAPSED_EXECUTABLE
            && lane.laneState !== LANE_STATE_REVIVED_BY_CASSATION_EXTENSION,
    );
}

export function listUnservedGhayabiNoticeOptions(params: {
    parties?: Array<LawsuitPartyRoleRecord & { name?: unknown }> | null;
    dispositions?: unknown;
    lanes?: unknown;
    judgmentForm?: string | null;
}): Array<{ partyId: string; name: string }> {
    const lanes = normalizePartyChallengeLanes(params.lanes);
    let dispositions = normalizePartyJudgmentDispositions(params.dispositions);
    if (dispositions.length === 0 && isScalarGhayabiJudgmentForm(params.judgmentForm)) {
        dispositions = seedPartyJudgmentDispositions(
            listJudgmentDispositionDefendants(params.parties ?? []),
            JUDGMENT_FORM_GHIABI,
        );
    }
    const sourceIds =
        lanes.length > 0
            ? lanes
                  .filter((lane) => lane.disposition === JUDGMENT_FORM_GHIABI && !lane.servedAt)
                  .filter(
                      (lane) =>
                          lane.laneState !== LANE_STATE_OBJECTION
                          && lane.laneState !== LANE_STATE_APPEAL
                          && lane.laneState !== LANE_STATE_CASSATION
                          && lane.laneState !== LANE_STATE_WAIVED
                          && lane.laneState !== LANE_STATE_LAPSED
                          && lane.laneState !== LANE_STATE_LAPSED_EXECUTABLE
                          && lane.laneState !== LANE_STATE_REVIVED_BY_CASSATION_EXTENSION,
                  )
                  .map((lane) => lane.partyId)
            : dispositions.filter((row) => row.form === JUDGMENT_FORM_GHIABI).map((row) => row.partyId);
    const ghayabiIds: string[] = [];
    for (const partyId of sourceIds) {
        if (!ghayabiIds.includes(partyId)) ghayabiIds.push(partyId);
    }
    const byId = new Map(
        (params.parties ?? []).map((party) => [partyDispositionId(party), String(party.name ?? '').trim()]),
    );
    return ghayabiIds.map((partyId) => ({
        partyId,
        name: byId.get(partyId) || `طرف ${partyId}`,
    }));
}

export function markLanesServed(
    raw: unknown,
    partyIds: Array<number | string>,
    servedAtYmd: string,
): PartyChallengeLane[] {
    const ids = new Set(partyIds.map((id) => String(id ?? '').trim()).filter(Boolean));
    const servedAt = String(servedAtYmd ?? '').trim().slice(0, 10);
    if (ids.size === 0) return normalizePartyChallengeLanes(raw);
    return normalizePartyChallengeLanes(raw).map((lane) => {
        if (!ids.has(lane.partyId) || lane.disposition !== JUDGMENT_FORM_GHIABI) return lane;
        return {
            ...lane,
            servedAt,
            objectionDeadline: computeLaneObjectionDeadline(servedAt),
            appealDeadline: computeLaneAppealDeadlineFromService(servedAt),
            cassationDeadline: computeLaneCassationDeadlineFromService(servedAt),
        };
    });
}

export function markLaneServed(
    raw: unknown,
    partyId: string,
    servedAtYmd: string,
): PartyChallengeLane[] {
    return markLanesServed(raw, [partyId], servedAtYmd);
}

export function markLanesState(
    raw: unknown,
    partyIds: Array<number | string>,
    laneState: PartyChallengeLaneState,
): PartyChallengeLane[] {
    const ids = new Set(partyIds.map((id) => String(id ?? '').trim()).filter(Boolean));
    return normalizePartyChallengeLanes(raw).map((lane) =>
        ids.has(lane.partyId) ? { ...lane, laneState } : lane,
    );
}

export function resolveGhayabiObjectorPartyIds(params: {
    parties?: Array<LawsuitPartyRoleRecord & { isClient?: boolean }> | null;
    dispositions?: unknown;
    explicitIds?: Array<number | string> | null;
    preferClient?: boolean;
}): string[] {
    const dispositions = normalizePartyJudgmentDispositions(params.dispositions);
    const ghayabi = dispositions
        .filter((row) => row.form === JUDGMENT_FORM_GHIABI)
        .map((row) => row.partyId);
    const explicit = (params.explicitIds ?? [])
        .map((id) => String(id ?? '').trim())
        .filter(Boolean);
    if (explicit.length > 0) {
        const filtered = explicit.filter((id) => ghayabi.length === 0 || ghayabi.includes(id));
        return filtered.length > 0 ? filtered : explicit;
    }
    if (params.preferClient) {
        const clientForm = resolveClientDefendantJudgmentForm(params.parties, dispositions);
        if (clientForm !== JUDGMENT_FORM_GHIABI) return [];
        const clients = listJudgmentDispositionDefendants(params.parties ?? []).filter((party) =>
            Boolean(party.isClient),
        );
        return clients
            .map((party) => partyDispositionId(party))
            .filter((id) => ghayabi.includes(id));
    }
    return ghayabi.length === 1 ? ghayabi : [];
}

export function resolveAbsentObjectionFlipSelection(objectorPartyIds: Array<number | string>): {
    includedAppellantPartyIds: Array<number | string>;
} | undefined {
    const ids = objectorPartyIds.map((id) => String(id ?? '').trim()).filter(Boolean);
    if (ids.length === 0) return undefined;
    return { includedAppellantPartyIds: ids };
}

export function missingCompulsoryJoinderIds(
    requiredIds: Array<number | string> | undefined,
    selectedIds: Array<number | string> | undefined,
): string[] {
    const selected = new Set(
        (selectedIds ?? []).map((id) => String(id ?? '').trim()).filter(Boolean),
    );
    return (requiredIds ?? [])
        .map((id) => String(id ?? '').trim())
        .filter((id) => Boolean(id) && !selected.has(id));
}

export function attachPartyChallengeLanes<T extends {
    parties?: Array<LawsuitPartyRoleRecord & { name?: unknown; isClient?: boolean }> | null;
    partyJudgmentDispositions?: unknown;
    partyChallengeLanes?: unknown;
    decisionDate?: string | null;
    disputeIntegrity?: DisputeIntegrity | string | null;
    judgmentForm?: string | null;
}>(
    stage: T,
    extras?: {
        dispositions?: unknown;
        existing?: unknown;
        judgmentDate?: string | null;
        integrity?: DisputeIntegrity | string | null;
        today?: string | null;
        judgmentForm?: string | null;
    },
): T {
    const lanes = mergePartyChallengeLanes({
        parties: stage.parties,
        dispositions: extras?.dispositions ?? stage.partyJudgmentDispositions,
        existing: extras?.existing ?? stage.partyChallengeLanes,
        judgmentDate: extras?.judgmentDate ?? stage.decisionDate,
        integrity: extras?.integrity ?? stage.disputeIntegrity,
        today: extras?.today,
        judgmentForm: extras?.judgmentForm ?? stage.judgmentForm,
    });
    if (lanes.length === 0) return stage;
    return { ...stage, partyChallengeLanes: lanes };
}

export type PartyChallengeLaneRadarRow = {
    partyId: string;
    name: string;
    disposition: JudgmentPresenceForm;
    laneState: PartyChallengeLaneState;
    summary: string;
};

function formatLaneRadarSummary(lane: PartyChallengeLane): string {
    if (lane.laneState === LANE_STATE_OBJECTION) return 'قيد الاعتراض الغيابي';
    if (lane.disposition === JUDGMENT_FORM_GHIABI && lane.laneState === LANE_STATE_APPEAL) {
        return 'تنازل عن الاعتراض وطعن استئنافاً';
    }
    if (lane.laneState === LANE_STATE_APPEAL) return 'استئناف مسجّل';
    if (lane.laneState === LANE_STATE_CASSATION) return 'تمييز مسجّل';
    if (lane.laneState === LANE_STATE_REVIVED_BY_CASSATION_EXTENSION) {
        return 'مستفيد من النقض (م/210)';
    }
    if (lane.laneState === LANE_STATE_WAIVED) return 'تنازل عن الاعتراض وطعن استئنافاً';
    if (lane.laneState === LANE_STATE_LAPSED_EXECUTABLE) return 'سقوط الحق بالطعن';
    if (lane.laneState === LANE_STATE_LAPSED) return 'سقوط الحق بالطعن';
    if (lane.disposition === JUDGMENT_FORM_GHIABI && !lane.servedAt) return 'بانتظار التبليغ';
    if (lane.disposition === JUDGMENT_FORM_GHIABI) {
        const objection = lane.objectionDeadline ? `اعتراض حتى ${lane.objectionDeadline}` : '';
        const appeal = lane.appealDeadline ? `استئناف حتى ${lane.appealDeadline}` : '';
        const cassation = lane.cassationDeadline ? `تمييز حتى ${lane.cassationDeadline}` : '';
        return [objection, appeal, cassation].filter(Boolean).join(' — ') || 'مهلة الطعن مفتوحة';
    }
    const appeal = lane.appealDeadline ? `استئناف حتى ${lane.appealDeadline}` : '';
    const cassation = lane.cassationDeadline ? `تمييز حتى ${lane.cassationDeadline}` : '';
    return [appeal, cassation].filter(Boolean).join(' — ') || 'مهلة الاستئناف مفتوحة';
}

export function listPartyChallengeLaneRadarRows(params: {
    parties?: Array<LawsuitPartyRoleRecord & { name?: unknown }> | null;
    dispositions?: unknown;
    lanes?: unknown;
    integrity?: DisputeIntegrity | string | null;
    judgmentDate?: string | null;
    today?: string | null;
}): PartyChallengeLaneRadarRow[] {
    const lanes = mergePartyChallengeLanes({
        parties: params.parties,
        dispositions: params.dispositions,
        existing: params.lanes,
        judgmentDate: params.judgmentDate,
        integrity: params.integrity,
        today: params.today,
    });
    const byId = new Map(
        (params.parties ?? []).map((party) => [partyDispositionId(party), String(party.name ?? '').trim()]),
    );
    return lanes.map((lane) => ({
        partyId: lane.partyId,
        name: byId.get(lane.partyId) || `طرف ${lane.partyId}`,
        disposition: lane.disposition,
        laneState: lane.laneState,
        summary: formatLaneRadarSummary(lane),
    }));
}

/**
 * صفة الحكم حضورياً / غيابياً / بمثابة الحضوري لكل مدعى عليه.
 * لا يفتح مسارات طعن متوازية؛ الملخص `مختلط` يمنع معاملة الحكم كغيابي أو حضوري بالكامل.
 * «بمثابة الحضوري» حضور-مثل إجرائياً: استئناف فقط، بلا اعتراض غيابي.
 */
import {
    partitionLawsuitPartiesByRole,
    type LawsuitPartyRoleRecord,
} from './lawsuitPartyRole';

export const JUDGMENT_FORM_HADARI = 'حضوري';
export const JUDGMENT_FORM_GHIABI = 'غيابي';
export const JUDGMENT_FORM_DEEMED_HADARI = 'بمثابة الحضوري';
export const JUDGMENT_FORM_MIXED = 'مختلط';

export type JudgmentPresenceForm =
    | typeof JUDGMENT_FORM_HADARI
    | typeof JUDGMENT_FORM_GHIABI
    | typeof JUDGMENT_FORM_DEEMED_HADARI;
export type JudgmentFormScalar = typeof JUDGMENT_FORM_HADARI | typeof JUDGMENT_FORM_GHIABI | typeof JUDGMENT_FORM_MIXED;
export type DisputeIntegrity = 'severable' | 'indivisible';

/** إلزام بحق الخصم = bound؛ رد الدعوى بحقه = released (صامت بلا مهلة طعن). */
export type PartyJudgmentOperative = 'bound' | 'released';

export type PartyJudgmentDisposition = {
    partyId: string;
    form: JudgmentPresenceForm;
    /** افتراضي bound عند الغياب — التضامن = bound */
    operative?: PartyJudgmentOperative;
};

export type PartyJudgmentStampTarget = {
    judgmentForm?: string;
    lastJudgmentType?: 'حضوري' | 'غيابي';
    partyJudgmentDispositions?: PartyJudgmentDisposition[];
    disputeIntegrity?: DisputeIntegrity;
};

export function isPartyJudgmentOperative(value: unknown): value is PartyJudgmentOperative {
    return value === 'bound' || value === 'released';
}

export function resolvePartyJudgmentOperative(
    row: Pick<PartyJudgmentDisposition, 'operative'> | null | undefined,
): PartyJudgmentOperative {
    return row?.operative === 'released' ? 'released' : 'bound';
}

export function isPartyOperativeReleased(
    row: Pick<PartyJudgmentDisposition, 'operative'> | null | undefined,
): boolean {
    return resolvePartyJudgmentOperative(row) === 'released';
}

export function hasAnyReleasedDisposition(
    dispositions: PartyJudgmentDisposition[] | unknown,
): boolean {
    return normalizePartyJudgmentDispositions(dispositions).some(isPartyOperativeReleased);
}

export function releasedPartyIds(dispositions: PartyJudgmentDisposition[] | unknown): string[] {
    return normalizePartyJudgmentDispositions(dispositions)
        .filter(isPartyOperativeReleased)
        .map((row) => row.partyId);
}

export function boundPartyIds(dispositions: PartyJudgmentDisposition[] | unknown): string[] {
    return normalizePartyJudgmentDispositions(dispositions)
        .filter((row) => !isPartyOperativeReleased(row))
        .map((row) => row.partyId);
}

export function areAllDispositionsReleased(
    dispositions: PartyJudgmentDisposition[] | unknown,
): boolean {
    const rows = normalizePartyJudgmentDispositions(dispositions);
    return rows.length > 0 && rows.every(isPartyOperativeReleased);
}

export type BoundMeritExtent = 'full' | 'partial';

/**
 * من إلزام/رد بحق كل خصم:
 * الكل مبرَّأ → رد كلي؛ مختلط خصوم → جزئي؛ الكل ملزَم → كامل أو جزئي موضوعي.
 */
export function resolveJudgmentTypeFromPartyOperatives(
    dispositions: PartyJudgmentDisposition[] | unknown,
    boundMerit: BoundMeritExtent = 'full',
): string {
    const rows = normalizePartyJudgmentDispositions(dispositions);
    if (rows.length === 0) return '';
    if (areAllDispositionsReleased(rows)) return 'رد الدعوى كلياً';
    if (hasAnyReleasedDisposition(rows)) return 'رد الدعوى جزئياً';
    return boundMerit === 'partial' ? 'رد الدعوى جزئياً' : 'إجابة الدعوى بالكامل';
}

/**
 * رد فردي → جزئي؛ رد الجميع → كلي.
 * يرفض إجابة كاملة مع وجود أي معفى.
 * (بدون released لا يغيّر النوع — الجزئي الموضوعي يبقى ممكناً على خصم ملزَم.)
 */
export function coerceJudgmentTypeForReleasedOperatives(
    judgmentType: string,
    dispositions: PartyJudgmentDisposition[] | unknown,
): string {
    const t = String(judgmentType ?? '').trim();
    if (!hasAnyReleasedDisposition(dispositions)) return t;
    if (areAllDispositionsReleased(dispositions)) return 'رد الدعوى كلياً';
    return 'رد الدعوى جزئياً';
}

/** شخص ثالث اختصامي مستقل — خارج مصفوفة الحضور/الغياب، وحضوري حتماً في مسار الاستئناف. */
export function isIndependentInterpleaderRole(role: string): boolean {
    const r = String(role ?? '').trim();
    if (r.includes('اختصامي')) return true;
    if (r.includes('شخص ثالث') && !r.includes('انضمامي')) return true;
    return false;
}

export function isJudgmentPresenceForm(value: unknown): value is JudgmentPresenceForm {
    return (
        value === JUDGMENT_FORM_HADARI
        || value === JUDGMENT_FORM_GHIABI
        || value === JUDGMENT_FORM_DEEMED_HADARI
    );
}

/** حضوري أو القيمة القديمة «بمثابة الحضوري»: نوافذ الاستئناف فقط، بلا اعتراض غيابي. */
export function isPresentLikeJudgmentForm(value: unknown): boolean {
    return value === JUDGMENT_FORM_HADARI || value === JUDGMENT_FORM_DEEMED_HADARI;
}

/** خيار الإصدار: حضوري أو غيابي أو بمثابة الحضوري. */
export function issuedJudgmentPresenceForm(value: unknown): JudgmentPresenceForm {
    if (value === JUDGMENT_FORM_GHIABI) return JUDGMENT_FORM_GHIABI;
    if (value === JUDGMENT_FORM_DEEMED_HADARI) return JUDGMENT_FORM_DEEMED_HADARI;
    return JUDGMENT_FORM_HADARI;
}

export function partyDispositionId(party: { id?: unknown } | null | undefined): string {
    return String(party?.id ?? '').trim();
}

export function parseDisputeIntegrity(raw: unknown): DisputeIntegrity | undefined {
    const t = String(raw ?? '').trim();
    if (t === 'severable' || t === 'indivisible') return t;
    if (t === 'قابل للتجزئة') return 'severable';
    if (t === 'غير قابل للتجزئة') return 'indivisible';
    return undefined;
}

/** غياب الحقل = قابل للتجزئة: لا يُفعَّل أثر المادتين 172 و191 دون اختيار صريح. */
export function isDisputeIndivisible(integrity?: DisputeIntegrity | string | null): boolean {
    return parseDisputeIntegrity(integrity) === 'indivisible';
}

export function isMixedJudgmentForm(form?: string | null): boolean {
    const raw = String(form ?? '').trim();
    return raw === JUDGMENT_FORM_MIXED || raw.includes(JUDGMENT_FORM_MIXED);
}

/** تخمين أوّلي — الحكم الجديد يُفترض غير قابل للتجزئة. */
export function suggestDisputeIntegrity(_caseType?: string | null): DisputeIntegrity {
    return 'indivisible';
}

export function formatPartyJudgmentPresenceSummary(
    parties: Array<{ id?: unknown; name?: unknown }> | null | undefined,
    dispositions: PartyJudgmentDisposition[] | unknown,
): string {
    const rows = normalizePartyJudgmentDispositions(dispositions);
    if (rows.length === 0) return '';
    const byId = new Map(
        (parties ?? []).map((party) => [
            partyDispositionId(party),
            String(party.name ?? '').trim(),
        ]),
    );
    return rows
        .map((row) => {
            const name = byId.get(row.partyId) || `طرف ${row.partyId}`;
            const form = isPresentLikeJudgmentForm(row.form) ? JUDGMENT_FORM_HADARI : JUDGMENT_FORM_GHIABI;
            return `${name} ${form}`;
        })
        .join(' — ');
}

/** نتيجة كل خصم: الاسم — الصفة — إلزام|رد (بلا تلميحات طعن). */
export function formatPartyJudgmentOutcomeSummary(
    parties: Array<{ id?: unknown; name?: unknown }> | null | undefined,
    dispositions: PartyJudgmentDisposition[] | unknown,
): string {
    const rows = normalizePartyJudgmentDispositions(dispositions);
    if (rows.length === 0) return '';
    const byId = new Map(
        (parties ?? []).map((party) => [
            partyDispositionId(party),
            String(party.name ?? '').trim(),
        ]),
    );
    return rows
        .map((row) => {
            const name = byId.get(row.partyId) || `طرف ${row.partyId}`;
            const form = isPresentLikeJudgmentForm(row.form) ? JUDGMENT_FORM_HADARI : JUDGMENT_FORM_GHIABI;
            const operative = isPartyOperativeReleased(row) ? 'رد' : 'إلزام';
            return `${name} — ${form} — ${operative}`;
        })
        .join('\n');
}

export function normalizePartyJudgmentDispositions(raw: unknown): PartyJudgmentDisposition[] {
    if (!Array.isArray(raw)) return [];
    const out: PartyJudgmentDisposition[] = [];
    const seen = new Set<string>();
    for (const row of raw) {
        if (!row || typeof row !== 'object') continue;
        const rec = row as { partyId?: unknown; form?: unknown; operative?: unknown };
        const partyId = String(rec.partyId ?? '').trim();
        if (!partyId || seen.has(partyId) || !isJudgmentPresenceForm(rec.form)) continue;
        seen.add(partyId);
        const operative: PartyJudgmentOperative = isPartyJudgmentOperative(rec.operative)
            ? rec.operative
            : 'bound';
        out.push({ partyId, form: rec.form, operative });
    }
    return out;
}

export function listJudgmentDispositionDefendants<
    T extends LawsuitPartyRoleRecord & { name?: unknown; isClient?: boolean },
>(parties: T[] | null | undefined): T[] {
    if (!Array.isArray(parties)) return [];
    const { defendants } = partitionLawsuitPartiesByRole(parties);
    return defendants.filter((party) => {
        if (!partyDispositionId(party)) return false;
        return !isIndependentInterpleaderRole(String(party.role ?? party.status ?? ''));
    });
}

export function seedPartyJudgmentDispositions(
    defendants: Array<{ id?: unknown }>,
    form: JudgmentPresenceForm = JUDGMENT_FORM_HADARI,
    operative: PartyJudgmentOperative = 'bound',
): PartyJudgmentDisposition[] {
    const issued = isJudgmentPresenceForm(form) ? form : JUDGMENT_FORM_HADARI;
    const op = isPartyJudgmentOperative(operative) ? operative : 'bound';
    const out: PartyJudgmentDisposition[] = [];
    const seen = new Set<string>();
    for (const party of defendants) {
        const partyId = partyDispositionId(party);
        if (!partyId || seen.has(partyId)) continue;
        seen.add(partyId);
        out.push({ partyId, form: issued, operative: op });
    }
    return out;
}

export function alignPartyJudgmentDispositions(
    defendants: Array<{ id?: unknown }>,
    existing: PartyJudgmentDisposition[],
    fallback: JudgmentPresenceForm = JUDGMENT_FORM_HADARI,
): PartyJudgmentDisposition[] {
    const issuedFallback = isJudgmentPresenceForm(fallback) ? fallback : JUDGMENT_FORM_HADARI;
    const byId = new Map(
        normalizePartyJudgmentDispositions(existing).map((row) => [row.partyId, row]),
    );
    return seedPartyJudgmentDispositions(defendants, issuedFallback).map((row) => {
        const prev = byId.get(row.partyId);
        return {
            partyId: row.partyId,
            form: prev?.form ?? issuedFallback,
            operative: resolvePartyJudgmentOperative(prev),
        };
    });
}

export function summarizePartyJudgmentForm(
    dispositions: PartyJudgmentDisposition[],
    fallback: string = JUDGMENT_FORM_HADARI,
): JudgmentFormScalar {
    if (dispositions.length === 0) {
        const raw = String(fallback ?? '').trim();
        if (raw === JUDGMENT_FORM_MIXED) return JUDGMENT_FORM_MIXED;
        if (raw === JUDGMENT_FORM_GHIABI || raw.startsWith(JUDGMENT_FORM_GHIABI)) {
            return JUDGMENT_FORM_GHIABI;
        }
        return JUDGMENT_FORM_HADARI;
    }
    const hasPresent = dispositions.some((row) => isPresentLikeJudgmentForm(row.form));
    const hasGhayabi = dispositions.some((row) => row.form === JUDGMENT_FORM_GHIABI);
    if (hasPresent && hasGhayabi) return JUDGMENT_FORM_MIXED;
    if (hasGhayabi) return JUDGMENT_FORM_GHIABI;
    return JUDGMENT_FORM_HADARI;
}

export function toLegacyLastJudgmentType(
    form: string | null | undefined,
): 'حضوري' | 'غيابي' | undefined {
    const raw = String(form ?? '').trim();
    if (raw === JUDGMENT_FORM_GHIABI) return JUDGMENT_FORM_GHIABI;
    if (raw === JUDGMENT_FORM_HADARI || raw === JUDGMENT_FORM_DEEMED_HADARI) {
        return JUDGMENT_FORM_HADARI;
    }
    return undefined;
}

export function resolveJudgmentPresenceWindows(
    dispositions: PartyJudgmentDisposition[],
    scalarForm: string,
): {
    hasHadari: boolean;
    hasGhayabi: boolean;
    mixed: boolean;
    summary: JudgmentFormScalar;
} {
    const summary = summarizePartyJudgmentForm(dispositions, scalarForm);
    if (dispositions.length > 0) {
        const hasHadari = dispositions.some((row) => isPresentLikeJudgmentForm(row.form));
        const hasGhayabi = dispositions.some((row) => row.form === JUDGMENT_FORM_GHIABI);
        return { hasHadari, hasGhayabi, mixed: hasHadari && hasGhayabi, summary };
    }
    if (summary === JUDGMENT_FORM_MIXED) {
        return { hasHadari: true, hasGhayabi: true, mixed: true, summary };
    }
    if (summary === JUDGMENT_FORM_GHIABI) {
        return { hasHadari: false, hasGhayabi: true, mixed: false, summary };
    }
    return { hasHadari: true, hasGhayabi: false, mixed: false, summary: JUDGMENT_FORM_HADARI };
}

export function judgmentFormHasGhayabi(
    judgmentForm?: string | null,
    lastJudgmentType?: string | null,
    dispositionsRaw?: unknown,
): boolean {
    const dispositions = normalizePartyJudgmentDispositions(dispositionsRaw);
    if (dispositions.length > 0) {
        return dispositions.some((row) => row.form === JUDGMENT_FORM_GHIABI);
    }
    const raw = String(judgmentForm ?? lastJudgmentType ?? '').trim();
    if (raw === JUDGMENT_FORM_MIXED || raw.includes(JUDGMENT_FORM_MIXED)) return true;
    return raw === JUDGMENT_FORM_GHIABI || raw.startsWith(JUDGMENT_FORM_GHIABI);
}

export function resolveClientDefendantJudgmentForm(
    parties: Array<LawsuitPartyRoleRecord & { isClient?: boolean }> | null | undefined,
    dispositions: PartyJudgmentDisposition[],
): JudgmentPresenceForm | null {
    const clients = listJudgmentDispositionDefendants(parties ?? []).filter((party) =>
        Boolean(party.isClient),
    );
    if (clients.length === 0) return null;
    const byId = new Map(dispositions.map((row) => [row.partyId, row.form]));
    const forms = clients
        .map((party) => byId.get(partyDispositionId(party)))
        .filter(isJudgmentPresenceForm);
    if (forms.includes(JUDGMENT_FORM_GHIABI)) return JUDGMENT_FORM_GHIABI;
    if (forms.includes(JUDGMENT_FORM_DEEMED_HADARI)) return JUDGMENT_FORM_DEEMED_HADARI;
    if (forms.includes(JUDGMENT_FORM_HADARI)) return JUDGMENT_FORM_HADARI;
    return null;
}

/** الموكل المدعى عليه غائب وملزَم — يحق له الاعتراض الغيابي (لا المبرَّأ). */
export function clientDefendantEligibleForGhayabiObjection(
    parties: Array<LawsuitPartyRoleRecord & { isClient?: boolean }> | null | undefined,
    dispositions: PartyJudgmentDisposition[],
): boolean {
    const clients = listJudgmentDispositionDefendants(parties ?? []).filter((party) =>
        Boolean(party.isClient),
    );
    if (clients.length === 0) return false;
    const byId = new Map(dispositions.map((row) => [row.partyId, row]));
    return clients.some((party) => {
        const row = byId.get(partyDispositionId(party));
        if (!row || row.form !== JUDGMENT_FORM_GHIABI) return false;
        return !isPartyOperativeReleased(row);
    });
}

export function clientDefendantHasGhayabiDisposition(
    parties: Array<LawsuitPartyRoleRecord & { isClient?: boolean }> | null | undefined,
    dispositions: PartyJudgmentDisposition[],
): boolean {
    return resolveClientDefendantJudgmentForm(parties, dispositions) === JUDGMENT_FORM_GHIABI;
}

/** أزرار الاعتراض الغيابي تتبع صفة الموكل الفردية — لا ملخص الحكم المختلط. */
export function clientUsesGhayabiChallengeActions(
    lawyerSide: string | null | undefined,
    clientDefendantForm: JudgmentPresenceForm | null,
    scalarForm?: string | null,
): boolean {
    if (String(lawyerSide ?? '').trim() !== 'المدعى عليه') return false;
    if (clientDefendantForm === JUDGMENT_FORM_GHIABI) return true;
    if (clientDefendantForm) return false;
    const raw = String(scalarForm ?? '').trim();
    return raw === JUDGMENT_FORM_GHIABI || raw.startsWith(JUDGMENT_FORM_GHIABI);
}

export function shouldPersistPartyJudgmentStamp(
    stageName: string,
    payload: { partyJudgmentDispositions?: unknown; disputeIntegrity?: unknown },
): boolean {
    const s = String(stageName ?? '').trim();
    if (
        s.includes('اعتراض على الحكم الغيابي')
        || s.includes('الاعتراض على الحكم الغيابي')
        || s.includes('اعتراض غيابي')
    ) {
        return false;
    }
    if (s.includes('اعتراض الغير') || s.includes('إعادة المحاكمة') || s.includes('إعادة محاكمة')) {
        return (
            normalizePartyJudgmentDispositions(payload.partyJudgmentDispositions).length > 0
            || Boolean(parseDisputeIntegrity(payload.disputeIntegrity))
        );
    }
    if (s.includes('استئناف') || s === 'التمييز' || (s.includes('تمييز') && !s.includes('استئناف'))) {
        return false;
    }
    return (
        normalizePartyJudgmentDispositions(payload.partyJudgmentDispositions).length > 0
        || Boolean(parseDisputeIntegrity(payload.disputeIntegrity))
    );
}

export function stampPartyJudgmentOnStage<T extends PartyJudgmentStampTarget>(
    stage: T,
    payload: {
        judgmentForm?: unknown;
        partyJudgmentDispositions?: unknown;
        disputeIntegrity?: unknown;
    },
): T {
    const dispositions = normalizePartyJudgmentDispositions(payload.partyJudgmentDispositions);
    const integrity = parseDisputeIntegrity(payload.disputeIntegrity);
    const summary = summarizePartyJudgmentForm(
        dispositions,
        String(payload.judgmentForm ?? stage.judgmentForm ?? JUDGMENT_FORM_HADARI),
    );
    return {
        ...stage,
        ...(dispositions.length > 0 ? { partyJudgmentDispositions: dispositions } : {}),
        ...(integrity ? { disputeIntegrity: integrity } : {}),
        judgmentForm: summary || stage.judgmentForm,
        lastJudgmentType: toLegacyLastJudgmentType(summary),
    };
}

/**
 * عرض صفة الحكم في السجل: نتيجة كل طرف (صفة + إلزام/رد) — بلا «مختلط» وبلا تلميحات طعن.
 * إعادة كتابة للعرض فقط؛ التخزين القديم يبقى كما هو.
 */
import type { PartyJudgmentDisposition } from './partyJudgmentDisposition';
import {
    formatPartyJudgmentOutcomeSummary,
    formatPartyJudgmentPresenceSummary,
    isPresentLikeJudgmentForm,
    JUDGMENT_FORM_GHIABI,
    JUDGMENT_FORM_HADARI,
} from './partyJudgmentDisposition';

const MIXED_WORD = 'مختلط';
const FORM_MIXED_RE = /الشكل:\s*مختلط/g;
const TITLE_MIXED_RE = /\s*\(\s*مختلط\s*\)/g;
const BARE_MIXED_PHRASE_RE = /حكم مختلط/g;
const CLIENT_HINT_LINE_RE = /^.*النتيجة للموكل:.*$/gm;
const CLOSED_PLEADING_LINE_RE = /^.*صدر الحكم وقُفلت المرافعة\.?\s*$/gm;
const PRESENCE_OR_OUTCOME_LABEL_RE = /^(?:الصفة|النتيجة):\s*.+$/m;

function toOutcomeBlock(presenceLine: string): string {
    const t = String(presenceLine ?? '').trim();
    if (!t) return '';
    if (t.includes('\n')) return t;
    return t.split(' — ').map((part) => part.trim()).filter(Boolean).join('\n');
}

function toInline(presenceLine: string): string {
    return toOutcomeBlock(presenceLine).split('\n').filter(Boolean).join(' — ');
}

export function rewriteJudgmentTimelinePresenceText(
    text: string,
    presenceLine: string,
): string {
    const raw = String(text ?? '');
    if (!raw) return raw;
    const outcomeBlock = toOutcomeBlock(presenceLine);
    const inline = toInline(presenceLine);
    let out = raw.replace(FORM_MIXED_RE, inline ? `الصفة: ${inline}` : '');
    out = out.replace(TITLE_MIXED_RE, '');
    out = out.replace(BARE_MIXED_PHRASE_RE, inline ? `حكم — ${inline}` : 'حكم');
    out = out.replace(CLIENT_HINT_LINE_RE, '');
    out = out.replace(CLOSED_PLEADING_LINE_RE, '');
    if (outcomeBlock && PRESENCE_OR_OUTCOME_LABEL_RE.test(out)) {
        out = out.replace(PRESENCE_OR_OUTCOME_LABEL_RE, `النتيجة:\n${outcomeBlock}`);
    } else if (outcomeBlock && !out.includes(outcomeBlock.split('\n')[0]!)) {
        out = `${out.trimEnd()}\nالنتيجة:\n${outcomeBlock}`;
    }
    if (!outcomeBlock) {
        out = out
            .split('\n')
            .filter((line) => !line.includes(MIXED_WORD))
            .join('\n');
    } else if (out.includes(MIXED_WORD)) {
        out = out.split(MIXED_WORD).join(inline);
    }
    return out.replace(/\n{3,}/g, '\n\n').trim();
}

export function rewriteTimelineEventJudgmentPresence<T extends { title?: string; details?: string }>(
    event: T,
    presenceLine: string,
): T {
    const presence = String(presenceLine ?? '').trim();
    const title = rewriteJudgmentTimelinePresenceText(String(event.title ?? ''), presence);
    const details = rewriteJudgmentTimelinePresenceText(String(event.details ?? ''), presence);
    if (title === event.title && details === (event.details ?? '')) return event;
    return { ...event, title, details };
}

export function rewriteTimelineEventsJudgmentPresence<T extends { title?: string; details?: string }>(
    events: T[] | null | undefined,
    presenceLine: string,
): T[] {
    if (!Array.isArray(events) || events.length === 0) return events ?? [];
    const presence = String(presenceLine ?? '').trim();
    const needsHintStrip = events.some((event) =>
        /النتيجة للموكل:|صدر الحكم وقُفلت المرافعة/.test(String(event.title ?? event.details ?? '')),
    );
    if (
        !presence
        && !needsHintStrip
        && !events.some((event) => String(event.title ?? event.details ?? '').includes(MIXED_WORD))
    ) {
        return events;
    }
    return events.map((event) => rewriteTimelineEventJudgmentPresence(event, presence));
}

export function formatJudgmentPresenceFromLanes(
    parties: Array<{ id?: unknown; name?: unknown }> | null | undefined,
    lanes: Array<{ partyId?: unknown; disposition?: unknown }> | null | undefined,
): string {
    if (!Array.isArray(lanes) || lanes.length === 0) return '';
    const byId = new Map(
        (parties ?? []).map((party) => [String(party.id ?? '').trim(), String(party.name ?? '').trim()]),
    );
    const parts: string[] = [];
    const seen = new Set<string>();
    for (const lane of lanes) {
        const partyId = String(lane.partyId ?? '').trim();
        if (!partyId || seen.has(partyId)) continue;
        const form = isPresentLikeJudgmentForm(lane.disposition)
            ? JUDGMENT_FORM_HADARI
            : lane.disposition === JUDGMENT_FORM_GHIABI
              ? JUDGMENT_FORM_GHIABI
              : '';
        if (!form) continue;
        seen.add(partyId);
        const name = byId.get(partyId) || `طرف ${partyId}`;
        parts.push(`${name} ${form}`);
    }
    return parts.join(' — ');
}

export function resolveStageJudgmentPresenceLine(stage?: {
    parties?: Array<{ id?: unknown; name?: unknown }> | null;
    partyJudgmentDispositions?: PartyJudgmentDisposition[] | unknown;
    partyChallengeLanes?: Array<{ partyId?: unknown; disposition?: unknown }> | unknown;
} | null): string {
    if (!stage) return '';
    const fromOutcomes = formatPartyJudgmentOutcomeSummary(
        stage.parties,
        stage.partyJudgmentDispositions,
    );
    if (fromOutcomes) return fromOutcomes;
    const fromDispositions = formatPartyJudgmentPresenceSummary(
        stage.parties,
        stage.partyJudgmentDispositions,
    );
    if (fromDispositions) return fromDispositions;
    const lanes = Array.isArray(stage.partyChallengeLanes) ? stage.partyChallengeLanes : [];
    return formatJudgmentPresenceFromLanes(stage.parties, lanes);
}

/** تصحيح الاسم الثلاثي مرة واحدة — المصدر الكانوني على الخادم لا JWT. */

export const DISPLAY_NAME_MAX_LEN = 80;
export const DISPLAY_NAME_PREVIOUS_VISIBLE_MS = 30 * 24 * 60 * 60 * 1000;

export const DISPLAY_NAME_REGISTER_NOTE =
    'تأكّد من الاسم الثلاثي كما في الهوية. يمكن تصحيحه مرة واحدة فقط لاحقاً من الملف الشخصي.';

export const DISPLAY_NAME_EDIT_NOTE =
    'تصحيح الاسم متاح مرة واحدة فقط. بعد الحفظ لا يمكن تغييره.';

export const DISPLAY_NAME_USED_NOTE = 'استُنفد التصحيح الوحيد لهذا الحساب.';

export function normalizeLegalDisplayName(raw: unknown): string {
    return String(raw ?? '')
        .trim()
        .replace(/\s+/g, ' ')
        .slice(0, DISPLAY_NAME_MAX_LEN);
}

export function previousDisplayNameVisibleUntil(
    correctedAt: string | null | undefined,
    now = Date.now(),
): string | null {
    if (!correctedAt) return null;
    const at = Date.parse(correctedAt);
    if (!Number.isFinite(at)) return null;
    const until = at + DISPLAY_NAME_PREVIOUS_VISIBLE_MS;
    if (now >= until) return null;
    return new Date(until).toISOString();
}

export function previousDisplayNamePublic(
    previous: string | null | undefined,
    correctedAt: string | null | undefined,
    now = Date.now(),
): string | null {
    if (!previousDisplayNameVisibleUntil(correctedAt, now)) return null;
    const name = normalizeLegalDisplayName(previous);
    return name || null;
}

export type DisplayNamePolicy = {
    fullName: string;
    previousFullName: string | null;
    previousVisibleUntil: string | null;
    correctionUsed: boolean;
    canCorrect: boolean;
    correctedAt: string | null;
};

export function toDisplayNamePolicy(
    input: {
        fullName?: string | null;
        previousFullName?: string | null;
        correctedAt?: string | null;
        corrections?: number | null;
    },
    now = Date.now(),
): DisplayNamePolicy {
    const fullName = normalizeLegalDisplayName(input.fullName);
    const corrections = Number(input.corrections ?? 0);
    const correctionUsed = corrections >= 1;
    const previousFullName = previousDisplayNamePublic(input.previousFullName, input.correctedAt, now);
    return {
        fullName,
        previousFullName,
        previousVisibleUntil: previousDisplayNameVisibleUntil(input.correctedAt, now),
        correctionUsed,
        canCorrect: !correctionUsed,
        correctedAt: input.correctedAt?.trim() || null,
    };
}

import { appendPendingExecutorSeizureDecision } from '@/app/utils/executorSeizureDecisionQueue';
