import {
    computeUrgentCaseStatus,
    type UrgentCase,
} from '@/app/components/lawyer/Component_Urgent_Card';
import { uuidv4 } from '@/app/services/urgent-actions-db';
import { resolveProcedureCategory } from './procedureCategory';
import type { UrgentFormSavePayload } from './types';

const DEFAULT_MS_PER_DAY = 1000 * 60 * 60 * 24;

function resolveRepresentedParty(data: UrgentFormSavePayload): 'client' | 'opponent' | null {
    const p1 = Array.isArray(data.allParty1) ? data.allParty1 : [];
    const p2 = Array.isArray(data.allParty2) ? data.allParty2 : [];
    const p1Rep = p1.some((p) => {
        const row = p && typeof p === 'object' ? (p as Record<string, unknown>) : null;
        return !!row?.isRepresented || !!row?.isClient;
    });
    const p2Rep = p2.some((p) => {
        const row = p && typeof p === 'object' ? (p as Record<string, unknown>) : null;
        return !!row?.isRepresented || !!row?.isClient;
    });
    if (p1Rep && !p2Rep) return 'client';
    if (p2Rep && !p1Rep) return 'opponent';
    if (data.representedParty === 'client' || data.representedParty === 'opponent') return data.representedParty;
    return null;
}

type CreateCaseFromFormOptions = {
    now?: Date;
    msPerDay?: number;
};

/** يبني UrgentCase جديداً من حمولة Form_Urgent_Actions بعد الحفظ */
export function createCaseFromForm(data: UrgentFormSavePayload, opts?: CreateCaseFromFormOptions): UrgentCase {
    const now = opts?.now ?? new Date();
    const msPerDay = opts?.msPerDay ?? DEFAULT_MS_PER_DAY;
    const nowYmd = now.toISOString().slice(0, 10);
    const requestDateRaw = typeof data.requestDate === 'string' ? data.requestDate : null;
    const requestDate = requestDateRaw ? new Date(requestDateRaw) : now;
    const specificActionType =
        typeof data.specificActionType === 'string' ? data.specificActionType.trim() : 'طلب مستعجل';
    const procedureCategory =
        data.procedureCategory === 'petition_orders' || data.procedureCategory === 'urgent_judiciary'
            ? data.procedureCategory
            : resolveProcedureCategory(null, specificActionType);
    const pathway =
        procedureCategory === 'urgent_judiciary' ||
        data.actionType === 'urgent_discovery' ||
        data.actionType === 'acknowledgment'
            ? 'urgent_action'
            : 'state_order';
    const startAtGrievance = data?.initialEntryMode === 'grievance';
    const startDefenderPhase2 = data?.initialEntryMode === 'defender_phase2';
    const startDefenderPhase3 = data?.initialEntryMode === 'defender_phase3';
    const judgeDecisionDate =
        typeof data?.initialJudgeDecisionDate === 'string' && data.initialJudgeDecisionDate
            ? data.initialJudgeDecisionDate
            : nowYmd;
    const hasIntervention = data?.hasIntervention === true;
    const guaranteeKind =
        data?.guaranteeKind === 'cash' ||
        data?.guaranteeKind === 'personal' ||
        data?.guaranteeKind === 'real_estate' ||
        data?.guaranteeKind === 'none'
            ? data.guaranteeKind
            : null;
    const guaranteeDetailsText = typeof data?.guaranteeDetailsText === 'string' ? data.guaranteeDetailsText : null;
    const defaultDeadlineDays = pathway === 'state_order' ? 3 : 7;
    const deadlineDays =
        typeof data.deadlineDays === 'number' && Number.isFinite(data.deadlineDays) && data.deadlineDays > 0
            ? data.deadlineDays
            : defaultDeadlineDays;
    const derivedDeadline = new Date(requestDate.getTime() + deadlineDays * msPerDay);
    const firstHearingYmd =
        typeof data.firstHearingDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.firstHearingDate.trim())
            ? data.firstHearingDate.trim()
            : null;

    const newCaseBase: UrgentCase = {
        id: uuidv4(),
        type: pathway === 'state_order' ? 'state_order' : 'urgent_action',
        actionType: specificActionType,
        applicantName: typeof data.party1Name === 'string' ? data.party1Name : 'مقدم الطلب',
        court: typeof data.courtName === 'string' ? data.courtName : 'غير محدد',
        requestNumber: typeof data.requestNumber === 'string' ? data.requestNumber : '',
        requestDate: typeof data.requestDate === 'string' ? data.requestDate : '',
        courtName: typeof data.courtName === 'string' ? data.courtName : '',
        judgeName: typeof data.judgeName === 'string' ? data.judgeName : '',
        specificActionType,
        procedureCategory,
        procedureDetails: typeof data.procedureDetails === 'string' ? data.procedureDetails.trim() : '',
        requestSubject: typeof data.requestSubject === 'string' ? data.requestSubject : '',
        urgentReason: typeof data.urgentReason === 'string' ? data.urgentReason : '',
        legalBasis: typeof data.legalBasis === 'string' ? data.legalBasis : '',
        requestNotes: typeof data.notes === 'string' ? data.notes : '',
        hasIntervention,
        guaranteeKind,
        guaranteeDetailsText,
        feeReceiptNumber: typeof data.feeReceiptNumber === 'string' ? data.feeReceiptNumber : null,
        feeReceiptDate: typeof data.feeReceiptDate === 'string' ? data.feeReceiptDate : null,
        initialNotificationMethod:
            data.initialNotificationMethod === 'personal' ||
            data.initialNotificationMethod === 'by_agent' ||
            data.initialNotificationMethod === 'publication'
                ? data.initialNotificationMethod
                : null,
        initialNotificationDate: typeof data.initialNotificationDate === 'string' ? data.initialNotificationDate : null,
        party1Name: typeof data.party1Name === 'string' ? data.party1Name : '',
        party1Phone: typeof data.party1Phone === 'string' ? data.party1Phone : '',
        party1Address: typeof data.party1Address === 'string' ? data.party1Address : '',
        party2Name: typeof data.party2Name === 'string' ? data.party2Name : '',
        party2Address: typeof data.party2Address === 'string' ? data.party2Address : '',
        allParty1: Array.isArray(data.allParty1) ? data.allParty1 : undefined,
        allParty2: Array.isArray(data.allParty2) ? data.allParty2 : undefined,
        representedParty: resolveRepresentedParty(data),
        deadlineDate: derivedDeadline,
        sessionDate: pathway !== 'state_order' && firstHearingYmd ? firstHearingYmd : null,
        notificationDate: null,
        deadlineDays,
        preDecisionClosed: startDefenderPhase3 ? true : false,
        expectedDecisionDate: null,
        judgeDecision: startDefenderPhase2 || startDefenderPhase3 ? 'rejected' : startAtGrievance ? 'accepted' : null,
        judgeDecisionDate: startDefenderPhase2
            ? typeof data.stateOrderIssuedDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.stateOrderIssuedDate)
                ? data.stateOrderIssuedDate
                : judgeDecisionDate
            : startDefenderPhase3
              ? typeof data.requestDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.requestDate)
                  ? data.requestDate
                  : judgeDecisionDate
              : startAtGrievance
                ? judgeDecisionDate
                : null,
        legalState: startDefenderPhase2
            ? 'Awaiting_Grievance'
            : startDefenderPhase3
              ? 'Awaiting_Cassation'
              : startAtGrievance
                ? 'Awaiting_Grievance'
                : null,
        phase: startDefenderPhase3
            ? 'cassation_window'
            : startDefenderPhase2 || startAtGrievance
              ? 'grievance_window'
              : procedureCategory === 'petition_orders'
                ? 'grievance_window'
                : 'notification_pending',
        defenderEntryPhase:
            typeof data.defenderEntryPhase === 'number' &&
            (data.defenderEntryPhase === 1 || data.defenderEntryPhase === 2 || data.defenderEntryPhase === 3)
                ? data.defenderEntryPhase
                : null,
        clientRole: data.clientRole === 'respondent' || data.clientRole === 'applicant' ? data.clientRole : null,
        stateOrderIssuedDate:
            typeof data.stateOrderIssuedDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.stateOrderIssuedDate)
                ? data.stateOrderIssuedDate
                : null,
        grievanceOutcome: startDefenderPhase3 ? 'filed' : null,
        grievanceFilingDate: startDefenderPhase3 ? (typeof data.requestDate === 'string' ? data.requestDate : null) : null,
        grievanceFirstHearingDate: startDefenderPhase3
            ? typeof data.requestDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(data.requestDate)
                ? data.requestDate
                : null
            : null,
        grievanceDecision: startDefenderPhase3 ? 'confirmed' : null,
        grievanceDecisionDate:
            startDefenderPhase3 &&
            typeof data.defenderPhase3GrievanceDecisionDate === 'string' &&
            /^\d{4}-\d{2}-\d{2}$/.test(data.defenderPhase3GrievanceDecisionDate)
                ? data.defenderPhase3GrievanceDecisionDate
                : null,
        firstHearingDate:
            startDefenderPhase2 &&
            typeof data.stateOrderIssuedDate === 'string' &&
            /^\d{4}-\d{2}-\d{2}$/.test(data.stateOrderIssuedDate)
                ? data.stateOrderIssuedDate
                : firstHearingYmd,
        isNotificationConfirmed: false,
        grievanceResult: null,
        archived: false,
        archivedAt: null,
        archivedReason: null,
        deleted: false,
        deletedAt: null,
        deletedReason: null,
        hearings: [],
        expertModule: {
            enabled: false,
            expertName: '',
            depositAmount: '',
            inspectionDate: '',
            reportDueDate: '',
            reportReceivedDate: '',
        },
        status: 'safe',
        createdAt: now,
    };

    return { ...newCaseBase, status: computeUrgentCaseStatus(newCaseBase) };
}

import { PETITION_ORDERS_DROPDOWN_OPTIONS, URGENT_JUDICIARY_DROPDOWN_OPTIONS } from './procedureCategory';

/** Phase 39 — نوعان مرجعيان (بيانات قديمة فقط) */
export const URGENT_PETITION_PRIMARY = 'أمر ولائي / قضاء مستعجل';
export const JUDICIAL_ACKNOWLEDGMENT_PRIMARY = 'إقرار قضائي / حجة إقرار';

const LEGACY_STATE_ORDER = [
    'وضع إشارة عدم تصرف/إشارة دعوى',
    'إيقاف الإجراءات التنفيذية/المزايدة',
    'إيقاف صرف مبالغ/خطاب ضمان',
    'الاستئخار المؤقت',
];

const LEGACY_URGENT_DISCOVERY = [
    'الكشف العقاري',
    'تثبيت حالة',
    'رفع التجاوز',
    'طرد الغاصب المستعجل',
    'الحراسة القضائية',
];

const LEGACY_ACKNOWLEDGMENT = ['إقرار الملكية', 'إقرار الدين', 'إقرار العقد'];

export const actionTypeOptions = {
    state_order: [...PETITION_ORDERS_DROPDOWN_OPTIONS, ...LEGACY_STATE_ORDER],
    urgent_discovery: [...URGENT_JUDICIARY_DROPDOWN_OPTIONS, ...LEGACY_URGENT_DISCOVERY],
    acknowledgment: [...LEGACY_ACKNOWLEDGMENT],
};

export type PathwayType = 'state_order' | 'urgent_discovery' | 'acknowledgment';

/** أنواع الإقرار القديمة فقط — لا يشمل استكتاب السندات بالبصمة */
export function isIqrarRequest(selectedType: string): boolean {
    const t = String(selectedType ?? '').trim();
    if (!t || t === URGENT_PETITION_PRIMARY) return false;
    if (t === JUDICIAL_ACKNOWLEDGMENT_PRIMARY) return true;
    return actionTypeOptions.acknowledgment.includes(t);
}

export function resolveStoredPathwayType(resolvedSpecificActionType: string): PathwayType {
    const t = String(resolvedSpecificActionType ?? '').trim();
    if (isIqrarRequest(t)) return 'acknowledgment';
    if (actionTypeOptions.urgent_discovery.includes(t)) return 'urgent_discovery';
    return 'state_order';
}

import {
    computeUrgentCaseStatus,
    type UrgentCase,
} from '@/app/components/lawyer/Component_Urgent_Card';
import { uuidv4 } from '@/app/services/urgent-actions-db';
import { resolveProcedureCategory } from './procedureCategory';
import {
    asRecord,
    hydrateExpertModule,
    mapLegacyCassationFields,
    normalizeUrgentHearings,
    pickYmdPrefix,
    resolveHydratedLegalState,
    resolveHydratedRepresentedParty,
} from './hydrateCaseParts';

function asString(value: unknown, fallback = ''): string {
    return typeof value === 'string' ? value : fallback;
}

function asStringOrNull(value: unknown): string | null {
    return typeof value === 'string' ? value : null;
}

function asBool(value: unknown): boolean | undefined {
    return typeof value === 'boolean' ? value : undefined;
}

function asDate(value: unknown): Date | null {
    if (!value) return null;
    const date = new Date(value as string | number | Date);
    return Number.isNaN(date.getTime()) ? null : date;
}

/** يحوّل صفاً خاماً من التخزين إلى UrgentCase مع حساب الحالة */
export function hydrateCase(raw: unknown): UrgentCase | null {
    const row = asRecord(raw);
    if (!row) return null;

    const type = row.type === 'state_order' ? 'state_order' : 'urgent_action';
    const specificActionType = asString(row.specificActionType);
    const actionType = asString(row.actionType, specificActionType || 'طلب مستعجل');
    const applicantName =
        asString(row.applicantName) ||
        (asString(row.party1Name).trim() ? asString(row.party1Name) : 'مقدم الطلب');
    const phase =
        row.phase === 'cassation_window' || row.phase === 'completed' || row.phase === 'notification_pending'
            ? row.phase
            : 'grievance_window';
    const judgeDecision =
        row.judgeDecision === 'accepted' ||
        row.judgeDecision === 'rejected' ||
        row.judgeDecision === 'partially_accepted'
            ? row.judgeDecision
            : null;

    const base: UrgentCase = {
        id: typeof row.id === 'string' ? row.id : uuidv4(),
        type,
        actionType,
        applicantName,
        court: asString(row.court, asString(row.courtName, 'غير محدد')),
        requestNumber: asString(row.requestNumber),
        requestDate: asString(row.requestDate),
        courtName: asString(row.courtName),
        judgeName: asString(row.judgeName),
        specificActionType,
        procedureCategory: resolveProcedureCategory(row.procedureCategory, specificActionType),
        procedureDetails: asString(row.procedureDetails),
        requestSubject: asString(row.requestSubject),
        urgentReason: asString(row.urgentReason),
        legalBasis: asString(row.legalBasis),
        requestNotes: asString(row.requestNotes, asString(row.notes)),
        hasIntervention: asBool(row.hasIntervention) ?? false,
        isMainLawsuitFiled: asBool(row.isMainLawsuitFiled),
        guaranteeKind:
            row.guaranteeKind === 'cash' ||
            row.guaranteeKind === 'personal' ||
            row.guaranteeKind === 'real_estate' ||
            row.guaranteeKind === 'none'
                ? row.guaranteeKind
                : null,
        guaranteeDetailsText: asStringOrNull(row.guaranteeDetailsText),
        feeReceiptNumber: asStringOrNull(row.feeReceiptNumber),
        feeReceiptDate: asStringOrNull(row.feeReceiptDate),
        initialNotificationMethod:
            row.initialNotificationMethod === 'personal' ||
            row.initialNotificationMethod === 'by_agent' ||
            row.initialNotificationMethod === 'publication'
                ? row.initialNotificationMethod
                : null,
        initialNotificationDate: asStringOrNull(row.initialNotificationDate),
        party1Name: asString(row.party1Name),
        party1Phone: asString(row.party1Phone),
        party1Address: asString(row.party1Address),
        party2Name: asString(row.party2Name),
        party2Address: asString(row.party2Address),
        allParty1: Array.isArray(row.allParty1) ? row.allParty1 : undefined,
        allParty2: Array.isArray(row.allParty2) ? row.allParty2 : undefined,
        representedParty: resolveHydratedRepresentedParty(row),
        deadlineDate: asDate(row.deadlineDate),
        sessionDate: asDate(row.sessionDate),
        notificationDate: asDate(row.notificationDate),
        deadlineDays: typeof row.deadlineDays === 'number' && Number.isFinite(row.deadlineDays) ? row.deadlineDays : null,
        preDecisionClosed: asBool(row.preDecisionClosed),
        expectedDecisionDate: asStringOrNull(row.expectedDecisionDate),
        judgeDecision,
        judgeDecisionDate: asStringOrNull(row.judgeDecisionDate),
        legalState: resolveHydratedLegalState(row),
        rejectionNotificationDate: asStringOrNull(row.rejectionNotificationDate),
        grievanceOutcome: row.grievanceOutcome === 'filed' || row.grievanceOutcome === 'expired' ? row.grievanceOutcome : null,
        grievanceFiledBy: row.grievanceFiledBy === 'client' || row.grievanceFiledBy === 'opponent' ? row.grievanceFiledBy : null,
        grievanceFilingDate: asStringOrNull(row.grievanceFilingDate),
        firstHearingDate: pickYmdPrefix(row.firstHearingDate) || pickYmdPrefix(row.phase1FirstHearingDate),
        grievanceFirstHearingDate: pickYmdPrefix(row.grievanceFirstHearingDate),
        grievanceSessionDate: asStringOrNull(row.grievanceSessionDate),
        grievanceDecision:
            row.grievanceDecision === 'confirmed' ||
            row.grievanceDecision === 'modified' ||
            row.grievanceDecision === 'canceled'
                ? row.grievanceDecision
                : null,
        grievanceDecisionDate: asStringOrNull(row.grievanceDecisionDate),
        ...mapLegacyCassationFields(row),
        requiresGuarantee: asBool(row.requiresGuarantee) ?? asBool(row.judgeDecisionRequiresGuarantee),
        guaranteeSubmitted: asBool(row.guaranteeSubmitted) ?? asBool(row.guaranteeStatus),
        guaranteeRecovered: asBool(row.guaranteeRecovered),
        guaranteeRecoveryDate: asStringOrNull(row.guaranteeRecoveryDate),
        orderLifted: asBool(row.orderLifted),
        orderLiftDate: asStringOrNull(row.orderLiftDate),
        hearings: normalizeUrgentHearings(row.hearings),
        expertModule: hydrateExpertModule(row.expertModule),
        guaranteeStatus: asBool(row.guaranteeStatus),
        notes: Array.isArray(row.notes) ? row.notes : undefined,
        events: Array.isArray(row.events) ? row.events : undefined,
        attachments: Array.isArray(row.attachments) ? row.attachments : undefined,
        followups: Array.isArray(row.followups) ? row.followups : undefined,
        archived: typeof row.archived === 'boolean' ? row.archived : false,
        archivedAt: asStringOrNull(row.archivedAt),
        archivedReason: asStringOrNull(row.archivedReason),
        deleted: typeof row.deleted === 'boolean' ? row.deleted : false,
        deletedAt: asStringOrNull(row.deletedAt),
        deletedReason: asStringOrNull(row.deletedReason),
        phase,
        isNotificationConfirmed: !!row.isNotificationConfirmed,
        grievanceResult: (row.grievanceResult as UrgentCase['grievanceResult']) ?? null,
        status: 'safe',
        createdAt: asDate(row.createdAt) ?? new Date(),
    };

    const storageExtras: Record<string, unknown> = {};
    if (row.iqrarDeedAuthenticated === true) storageExtras.iqrarDeedAuthenticated = true;
    if (row.legalState === 'Iqrar_Authenticated') storageExtras.legalState = 'Iqrar_Authenticated';
    if (typeof row.finalityReason === 'string') storageExtras.finalityReason = row.finalityReason;

    const merged = { ...base, ...storageExtras };
    return { ...merged, status: computeUrgentCaseStatus(merged as UrgentCase) } as UrgentCase;
}

import type { CaseHearing, ExpertModule, LegalState, UrgentCase } from '@/app/components/lawyer/Component_Urgent_Card';
import { uuidv4 } from '@/app/services/urgent-actions-db';

export function asRecord(raw: unknown): Record<string, unknown> | null {
    if (!raw || typeof raw !== 'object') return null;
    return raw as Record<string, unknown>;
}

export function pickYmdPrefix(value: unknown): string | null {
    const text = typeof value === 'string' ? value : '';
    return text.match(/^(\d{4}-\d{2}-\d{2})/)?.[1] ?? null;
}

export function normalizeUrgentHearings(raw: unknown): CaseHearing[] | undefined {
    if (!Array.isArray(raw)) return undefined;
    const hearings = raw
        .map((item): CaseHearing | null => {
            const hearing = asRecord(item);
            if (!hearing) return null;
            const stage = hearing.stage === 'pre_decision' || hearing.stage === 'grievance' ? hearing.stage : null;
            if (!stage) return null;
            return {
                id: typeof hearing.id === 'string' ? hearing.id : uuidv4(),
                stage,
                sessionDate: typeof hearing.sessionDate === 'string' ? hearing.sessionDate : '',
                notes: typeof hearing.notes === 'string' ? hearing.notes : '',
                nextSessionDate: typeof hearing.nextSessionDate === 'string' ? hearing.nextSessionDate : '',
                createdAt: typeof hearing.createdAt === 'string' ? hearing.createdAt : new Date().toISOString(),
            };
        })
        .filter((hearing): hearing is CaseHearing => hearing !== null);
    return hearings.length ? hearings : undefined;
}

export function resolveHydratedLegalState(row: Record<string, unknown>): LegalState | null {
    if (row.legalState === 'Awaiting_Appeal') return 'Awaiting_Cassation';
    if (
        row.legalState === 'Awaiting_Grievance' ||
        row.legalState === 'Grievance_Filed' ||
        row.legalState === 'Awaiting_Cassation'
    ) {
        return row.legalState;
    }
    return null;
}

export function resolveHydratedRepresentedParty(row: Record<string, unknown>): 'client' | 'opponent' | null {
    const party1 = Array.isArray(row.allParty1) ? row.allParty1 : [];
    const party2 = Array.isArray(row.allParty2) ? row.allParty2 : [];
    const sideHasClient = (list: unknown[]) =>
        list.some((item) => {
            const party = asRecord(item);
            return !!party?.isRepresented || !!party?.isClient;
        });
    const party1Client = sideHasClient(party1);
    const party2Client = sideHasClient(party2);
    if (party1Client && !party2Client) return 'client';
    if (party2Client && !party1Client) return 'opponent';
    if (row.representedParty === 'client' || row.representedParty === 'opponent') return row.representedParty;
    return null;
}

export function mapLegacyCassationFields(row: Record<string, unknown>): Pick<
    UrgentCase,
    | 'cassationOutcome'
    | 'cassationFiledBy'
    | 'cassationFilingDate'
    | 'cassationFileNumber'
    | 'cassationDecision'
    | 'cassationDecisionDate'
> {
    const legacyOutcome = row.appealOutcome;
    const legacyFiledBy = row.appealFiledBy;
    const legacyFilingDate = row.appealFilingDate;
    const legacyFileNumber = row.appealFileNumber;
    const legacyDecision = row.appealDecision;
    const legacyDecisionDate = row.appealDecisionDate;

    return {
        cassationOutcome:
            row.cassationOutcome === 'filed' || row.cassationOutcome === 'expired'
                ? row.cassationOutcome
                : legacyOutcome === 'filed' || legacyOutcome === 'expired'
                  ? legacyOutcome
                  : null,
        cassationFiledBy:
            row.cassationFiledBy === 'client' || row.cassationFiledBy === 'opponent'
                ? row.cassationFiledBy
                : legacyFiledBy === 'client' || legacyFiledBy === 'opponent'
                  ? legacyFiledBy
                  : null,
        cassationFilingDate:
            typeof row.cassationFilingDate === 'string'
                ? row.cassationFilingDate
                : typeof legacyFilingDate === 'string'
                  ? legacyFilingDate
                  : null,
        cassationFileNumber:
            typeof row.cassationFileNumber === 'string'
                ? row.cassationFileNumber
                : typeof legacyFileNumber === 'string'
                  ? legacyFileNumber
                  : null,
        cassationDecision:
            row.cassationDecision === 'confirmed' ||
            row.cassationDecision === 'modified' ||
            row.cassationDecision === 'canceled'
                ? row.cassationDecision
                : legacyDecision === 'confirmed' || legacyDecision === 'modified' || legacyDecision === 'canceled'
                  ? legacyDecision
                  : null,
        cassationDecisionDate:
            typeof row.cassationDecisionDate === 'string'
                ? row.cassationDecisionDate
                : typeof legacyDecisionDate === 'string'
                  ? legacyDecisionDate
                  : null,
    };
}

export function hydrateExpertModule(raw: unknown): ExpertModule | undefined {
    const module = asRecord(raw);
    if (!module) return undefined;
    return {
        enabled: !!module.enabled,
        expertName: typeof module.expertName === 'string' ? module.expertName : '',
        depositAmount: typeof module.depositAmount === 'string' ? module.depositAmount : '',
        inspectionDate: typeof module.inspectionDate === 'string' ? module.inspectionDate : '',
        reportDueDate: typeof module.reportDueDate === 'string' ? module.reportDueDate : '',
        reportReceivedDate: typeof module.reportReceivedDate === 'string' ? module.reportReceivedDate : '',
    };
}

import { isIqrarRequest } from '@/app/components/lawyer/Form_Urgent_Actions/constants';
