function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object';
}

export interface ExecutionFileDTO_Supabase {
  id: string;
  caseNo: string;
  executionType: 'مدني' | 'شرعي' | 'التزام بعمل/تسليم';
