  updatedAt?: string;
}

function generateId(prefix: string): string {
  return `${prefix}_${Date.now()}_${Math.random().toString(36).substring(7)}`;
}

type ExecutionFileRow = {
  id: string;
  external_id: string;
  case_no: string;
  execution_type: string;
  court: string | null;
  execution_basis: string | null;
  encrypted_data: string;
