            {
                id: 'keep',
                status: 'active',
                stages: [
                    {
                        id: 's1',
                        timeline: [
                            {
                                id: 'real-hearing',
                                type: 'appointment',
                                date: '2027-01-15',
                                title: 'جلسة حقيقية',
                            },
                        ],
                    },
                ],
            },
        ]);
        expect(loadLawsuitFilesRaw().some((f) => String((f as { id?: string }).id) === 'keep')).toBe(
            true,
