        resetCalendarEventsCacheForTests();
        const events = await CalendarDB.getEvents(USER);

        expect(events.some((e) => e.id === ghostId)).toBe(false);
        expect(events.some((e) => e.id === buildStableBridgeId('lawsuit', 'keep', 'real-hearing'))).toBe(
            true,
