        const keyA = computeGlobalSearchIndexKey(baseInput({ files: [file] }));
        const keyB = computeGlobalSearchIndexKey(baseInput({ files: [{ ...file } as unknown as FileData] }));
        expect(keyA).toEqual(keyB);
    });
});

