/**
 * Regression: حارس kv-proxy يمنع عاصفة الطلبات
 */
import { beforeEach, describe, expect, it, vi } from 'vitest';

vi.mock('@/app/services/secureApiNetworkFeatures', () => ({
    resolveDeniedNetworkFeatureResponse: () => null,
}));

import { fetchKvProxyGuarded, resetKvProxyGuardForTests } from '../kvProxyGuard';

const KV_URL = 'https://example.supabase.co/functions/v1/make-server/kv-proxy';

describe('kvProxyGuard', () => {
    beforeEach(() => {
        resetKvProxyGuardForTests();
    });

    it('deduplicates identical in-flight requests', async () => {
        let resolveNative!: (v: Response) => void;
        const native = vi.fn(
            () =>
                new Promise<Response>((resolve) => {
                    resolveNative = resolve;
                }),
        );

        const init = { method: 'POST', body: '{"action":"get","key":"x"}' };
        const p1 = fetchKvProxyGuarded(KV_URL, init, native);
        const p2 = fetchKvProxyGuarded(KV_URL, init, native);

        expect(native).toHaveBeenCalledTimes(1);

        resolveNative(new Response('{"ok":true}', { status: 200 }));
        const [r1, r2] = await Promise.all([p1, p2]);
        expect(r1.status).toBe(200);
        expect(r2.status).toBe(200);
    });

    it('returns 429 when window limit exceeded (dev: 48)', async () => {
        const native = vi.fn().mockResolvedValue(new Response('{}', { status: 200 }));

        for (let i = 0; i < 48; i++) {
            const res = await fetchKvProxyGuarded(
                KV_URL,
                { method: 'POST', body: `{"i":${i}}` },
                native,
            );
            expect(res.status).toBe(200);
        }

        const blocked = await fetchKvProxyGuarded(
            KV_URL,
            { method: 'POST', body: '{"blocked":true}' },
            native,
        );
        expect(blocked.status).toBe(429);
        expect(native).toHaveBeenCalledTimes(48);
    });
});

/**
 * اختبارات buildLawsuitAlerts.
 *
 * يتحقّق من:
 *  l1) status === 'paused' + stayReviewDate قريب → URGENT
 *  l2) nextDate خلال أسبوع → HEARING
 *  l3) CaseStage.legalTimers.appealDeadline → DEADLINE
 *  l4) tasks[] بـ dueDate
 *  l5) ركود > 90 يوم → TASK
 *  l6) ملف من النوع 'execution' أو 'transaction' لا يُنتج تنبيه (buildExecutionAlerts/Threading يتولّى)
 */
import { describe, expect, it, vi } from 'vitest';
import { buildLawsuitAlerts } from '../lawsuitAlerts';
import type { DossierRegistry } from '../alertDossierRegistry';
import type { FileData } from '@/app/domain/lawsuit/lawsuitFileTypes';

function fakeRegistry(): DossierRegistry {
    return {
        resolve: vi.fn((module: string, id: string) => ({
            module,
            entityId: id,
            caseNumber: `LAW-${id}`,
            clientName: 'موكل',
            courtName: 'بداءة بغداد',
            actionType: 'دعوى مدنية',
            clientPhone: '',
        })),
    } as unknown as DossierRegistry;
}

function ymdInDays(daysFromNow: number): string {
    const d = new Date(Date.now() + daysFromNow * 24 * 60 * 60 * 1000);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
}

function baseFile(overrides: Partial<FileData> & Record<string, unknown> = {}): FileData {
    return {
        id: 1,
        type: 'lawsuit',
        status: 'active',
        caseNo: '50/ب/2026',
        court: 'بداءة',
        parties: [{ id: 1, name: 'المدعي', role: 'مدعي', isClient: true }],
        history: [],
        notes: [],
        images: [],
        date: ymdInDays(-30),
        tasks: [],
        ...overrides,
    } as FileData;
}

describe('buildLawsuitAlerts', () => {
    it("l1) paused + stayReviewDate قريب → URGENT", () => {
        const file = baseFile({
            id: 11,
            status: 'paused',
            stayReason: 'وقف الاستئنافي',
            stayReviewDate: ymdInDays(5),
        });
        const alerts = buildLawsuitAlerts([file], new Date(), fakeRegistry());
        const hit = alerts.find((a) => a.id === 'lawsuit:11:stay-review');
        expect(hit).toBeDefined();
        expect(hit?.type).toBe('URGENT');
    });

    it('l2) nextDate خلال أسبوع → HEARING', () => {
        const file = baseFile({ id: 12, nextDate: ymdInDays(5) });
        const alerts = buildLawsuitAlerts([file], new Date(), fakeRegistry());
        const hit = alerts.find((a) => a.id === 'lawsuit:12:next-date');
        expect(hit).toBeDefined();
        expect(hit?.type).toBe('HEARING');
    });

    it('l3) CaseStage.legalTimers.appealDeadline → DEADLINE', () => {
        const file = baseFile({
            id: 13,
            stages: [
                {
                    id: 'st-1',
                    stageName: 'البداءة',
                    status: 'completed',
                    // مرحلة منتهية → تُتجاهَل
                },
                {
                    id: 'st-2',
                    stageName: 'الاستئناف',
                    status: 'active',
                    legalTimers: {
                        appealDeadline: ymdInDays(10),
                        cassationDeadline: ymdInDays(20),
                    },
                },
            ],
        });
        const alerts = buildLawsuitAlerts([file], new Date(), fakeRegistry());
        const appeal = alerts.find((a) => a.id === 'lawsuit:13:stage-1:appeal');
        const cassation = alerts.find((a) => a.id === 'lawsuit:13:stage-1:cassation');
        expect(appeal).toBeDefined();
        expect(cassation).toBeDefined();
        // المرحلة المكتملة (stage-0) لا تُنتج
        expect(alerts.find((a) => a.id.startsWith('lawsuit:13:stage-0:'))).toBeUndefined();
    });

    it('l4) tasks[] بـ dueDate قريب → TASK', () => {
        const file = baseFile({
            id: 14,
            tasks: [
                {
                    id: 'tk-1',
                    title: 'تحضير مذكرة',
                    description: 'مذكرة استئناف',
                    dueDate: ymdInDays(2),
                    completed: false,
                } as unknown as FileData['tasks'][number],
            ],
        });
        const alerts = buildLawsuitAlerts([file], new Date(), fakeRegistry());
        const hit = alerts.find((a) => a.id === 'lawsuit:14:task:tk-1');
        expect(hit).toBeDefined();
        expect(hit?.type).toBe('TASK');
    });

    it('l5) ركود > 90 يوم → TASK', () => {
        const file = baseFile({
            id: 15,
            date: ymdInDays(-120),
            history: [{ id: 1, stage: 'البداءة', result: '', date: ymdInDays(-100) }],
            notes: [],
        });
        const alerts = buildLawsuitAlerts([file], new Date(), fakeRegistry());
        const hit = alerts.find((a) => a.id === 'lawsuit:15:dormancy');
        expect(hit).toBeDefined();
        expect(hit?.priority).toBe(4);
    });

    it("l6) type='execution' لا يُنتج (buildExecutionAlerts يتولّى)", () => {
        const file = baseFile({ id: 16, type: 'execution', nextDate: ymdInDays(2) });
        const alerts = buildLawsuitAlerts([file], new Date(), fakeRegistry());
        expect(alerts.length).toBe(0);
    });
});

import { describe, expect, it, vi, beforeEach } from 'vitest';
import {
    LAWSUIT_CAL_APPT,
    collectStageLegalCalendarSpecs,
    mirrorSessionNextHearingToCalendar,
    mirrorStageLegalDatesToCalendar,
} from '../lawsuitTimelineCalendarMirror';

vi.mock('../calendarDossierSync', () => ({
    syncLawsuitTimelineAppointment: vi.fn(),
}));

describe('lawsuitTimelineCalendarMirror', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('creates pleading appointment for session next hearing', () => {
        const stages = [{ id: 's1', timeline: [] as unknown[] }];
        const next = mirrorSessionNextHearingToCalendar(
            stages as never,
            0,
            'sess-1',
            '2026-07-01',
            'محضر الجلسة 3',
            { fileId: 'case-1', userId: 'u1' },
        );
        const timeline = next[0].timeline ?? [];
        expect(timeline.some((e) => e.id === LAWSUIT_CAL_APPT.sessionNext('sess-1'))).toBe(true);
    });

    it('mirrors appeal deadline and judgment date from stage', () => {
        const stages = [
            {
                id: 'stage-1',
                stageName: 'بداءة',
                decisionDate: '2026-06-01',
                appealDeadline: '2026-06-26',
                timeline: [],
            },
        ];
        const next = mirrorStageLegalDatesToCalendar(stages as never, 0, {
            fileId: 'case-9',
            userId: 'u1',
        });
        const ids = (next[0].timeline ?? []).map((e) => e.id);
        expect(ids).toContain(LAWSUIT_CAL_APPT.appealDeadline('stage-1'));
        expect(ids).toContain(LAWSUIT_CAL_APPT.judgmentDate('stage-1'));
    });

    it('uses smart stage-aware labels for judgment and appeal deadlines', () => {
        const stages = [
            {
                id: 'first',
                stageName: 'بداءة',
                decisionDate: '2026-06-01',
                appealDeadline: '2026-06-26',
                timeline: [],
            },
            {
                id: 'appeal',
                stageName: 'الاستئناف',
                decisionDate: '2026-07-01',
                appealDeadline: '2026-07-31',
                timeline: [],
            },
            {
                id: 'cass',
                stageName: 'التمييز',
                decisionDate: '2026-08-01',
                appealDeadline: '2026-08-30',
                timeline: [],
            },
        ];

        const first = mirrorStageLegalDatesToCalendar(stages as never, 0, {
            fileId: 'case-1',
            userId: 'u1',
        });
        const appeal = mirrorStageLegalDatesToCalendar(stages as never, 1, {
            fileId: 'case-1',
            userId: 'u1',
        });
        const cass = mirrorStageLegalDatesToCalendar(stages as never, 2, {
            fileId: 'case-1',
            userId: 'u1',
        });

        expect(first[0].timeline?.find((e) => e.id === LAWSUIT_CAL_APPT.judgmentDate('first'))?.title).toBe(
            'تاريخ الحكم'
        );
        expect(appeal[1].timeline?.find((e) => e.id === LAWSUIT_CAL_APPT.judgmentDate('appeal'))?.title).toBe(
            'تاريخ الحكم الاستئنافي'
        );
        expect(cass[2].timeline?.find((e) => e.id === LAWSUIT_CAL_APPT.judgmentDate('cass'))?.title).toBe(
            'تاريخ القرار التمييزي'
        );

        expect(first[0].timeline?.find((e) => e.id === LAWSUIT_CAL_APPT.appealDeadline('first'))?.title).toBe(
            'آخر موعد طعن على الحكم'
        );
        expect(
            appeal[1].timeline?.find((e) => e.id === LAWSUIT_CAL_APPT.appealDeadline('appeal')),
        ).toBeUndefined();
    });

    it('cassation deadline on appeal stage uses تمييز context — not مرحلة الاستئناف', () => {
        const specs = collectStageLegalCalendarSpecs(
            {
                id: 'appeal-1',
                stageName: 'الاستئناف',
                legalTimers: { cassationDeadline: '2026-09-03' },
            },
            1,
        );
        const cassation = specs.find((s) => s.id === LAWSUIT_CAL_APPT.cassationDeadline('appeal-1'));
        expect(cassation?.title).toBe('مهلة التمييز');
        expect(cassation?.details).toContain('بعد الحكم الاستئنافي');
        expect(cassation?.details).not.toContain('مرحلة: الاستئناف');
    });

    it('skips appeal deadline mirror on appeal stage and correction stage', () => {
        const appealSpecs = collectStageLegalCalendarSpecs(
            {
                id: 'appeal-1',
                stageName: 'الاستئناف',
                appealDeadline: '2026-07-31',
            },
            1,
        );
        expect(
            appealSpecs.find((s) => s.id === LAWSUIT_CAL_APPT.appealDeadline('appeal-1'))?.date,
        ).toBeNull();

        const correctionSpecs = collectStageLegalCalendarSpecs(
            {
                id: 'corr-1',
                stageName: 'تصحيح قرار',
                legalTimers: { cassationDeadline: '2026-09-03' },
            },
            2,
        );
        expect(
            correctionSpecs.find((s) => s.id === LAWSUIT_CAL_APPT.cassationDeadline('corr-1'))?.date,
        ).toBeNull();
    });

    it('skips first-instance appeal deadline mirror on personal status stage', () => {
        const specs = collectStageLegalCalendarSpecs(
            {
                id: 'ps-1',
                stageName: 'أحوال شخصية',
                appealDeadline: '2026-07-31',
                legalTimers: { cassationDeadline: '2026-09-03' },
            },
            0,
        );
        expect(
            specs.find((s) => s.id === LAWSUIT_CAL_APPT.appealDeadline('ps-1'))?.date,
        ).toBeNull();
        expect(
            specs.find((s) => s.id === LAWSUIT_CAL_APPT.cassationDeadline('ps-1'))?.date,
        ).toBe('2026-09-03');
    });

    it('uses personal-status judgment labels — not civil بدائي terminology', () => {
        const specs = collectStageLegalCalendarSpecs(
            {
                id: 'ps-j',
                stageName: 'أحوال شخصية',
                decisionDate: '2026-06-15',
                finalDecision: 'إجابة الدعوى',
            },
            0,
        );
        const judgment = specs.find((s) => s.id === LAWSUIT_CAL_APPT.judgmentDate('ps-j'));
        expect(judgment?.title).toBe('تاريخ قرار أحوال شخصية');
        expect(judgment?.title).not.toContain('بدائي');
    });
});

