import { describe, it, expect } from 'vitest';
import { defaultPersistWipeGuard, countCasesInPersistPayload } from '@/app/services/securePersistStorage';

const CRIMINAL_KEY = 'hami:criminal:store';

/** الصيغة التي يكتبها createCriminalShardedStateStorage: casesById محذوفة، caseIds بدلاً منها. */
const shardedMeta = (ids: string[]) =>
    JSON.stringify({
        state: { draft: {}, pendingSeveranceContext: null },
        version: 49,
        caseIds: ids,
        sharded: true,
    });

const legacyMeta = (ids: string[]) =>
    JSON.stringify({
        state: { casesById: Object.fromEntries(ids.map((id) => [id, {}])), draft: {} },
        version: 49,
    });

const emptyPayload = JSON.stringify({
    state: { casesById: {}, draft: {}, pendingSeveranceContext: null },
    version: 49,
});

describe('countCasesInPersistPayload', () => {
    it('يَعُدّ القضايا في الصيغة القديمة', () => {
        expect(countCasesInPersistPayload(legacyMeta(['c1', 'c2', 'c3']))).toBe(3);
    });

    it('يَعُدّ القضايا في الصيغة المجزّأة عبر caseIds', () => {
        expect(countCasesInPersistPayload(shardedMeta(['c1', 'c2', 'c3']))).toBe(3);
    });

    it('يُرجع صفراً للحمولة الفارغة أو التالفة', () => {
        expect(countCasesInPersistPayload(emptyPayload)).toBe(0);
        expect(countCasesInPersistPayload(null)).toBe(0);
        expect(countCasesInPersistPayload('not json')).toBe(0);
    });
});

describe('defaultPersistWipeGuard — المتجر الجزائي', () => {
    it('يحجب الكتابة الفارغة فوق قضايا مخزّنة بالصيغة القديمة', () => {
        expect(defaultPersistWipeGuard(emptyPayload, legacyMeta(['c1']), CRIMINAL_KEY)).toBe(true);
    });

    // لو عمي الحارس عن الصيغة المجزّأة، تُحذف كل شظايا القضايا عند أول حفظ بعد فشل الترحيل.
    it('يحجب الكتابة الفارغة فوق قضايا مخزّنة بالصيغة المجزّأة', () => {
        expect(defaultPersistWipeGuard(emptyPayload, shardedMeta(['c1', 'c2']), CRIMINAL_KEY)).toBe(true);
    });

    it('يسمح بالكتابة عندما تحمل الحمولة الواردة قضايا', () => {
        const incoming = legacyMeta(['c1', 'c2']);
        expect(defaultPersistWipeGuard(incoming, shardedMeta(['c1']), CRIMINAL_KEY)).toBe(false);
    });

    it('لا يحجب شيئاً عندما لا توجد بيانات مخزّنة أصلاً', () => {
        expect(defaultPersistWipeGuard(emptyPayload, null, CRIMINAL_KEY)).toBe(false);
        expect(defaultPersistWipeGuard(emptyPayload, '   ', CRIMINAL_KEY)).toBe(false);
    });
});

describe('defaultPersistWipeGuard — الحمولات الفارغة العامة', () => {
    it('يحجب {} و null و الفراغ فوق أي بيانات قائمة', () => {
        for (const incoming of ['{}', 'null', '   ']) {
            expect(defaultPersistWipeGuard(incoming, legacyMeta(['c1']), 'any-store')).toBe(true);
        }
    });
});

import { describe, expect, it } from 'vitest';

import {
    ENCRYPT_MAX_BYTES,
    fallsBackToPlaintextBySize,
    isEncryptOrFailStorageKey,
    isExecutionLocalPlaintextKey,
    isSensitiveStorageKey,
    isTransactionsStorageKey,
    isWarmEncryptAlwaysKey,
    shouldEncryptValue,
} from '@/app/services/secureStorageKeys';

/**
 * سياسة offline-first للتنفيذ: لا تشفير محلي يومي — الحمولة السحابية وحدها تُشفَّر.
 * المعاملات ليست ضمن الاستثناء: العزل عندها شبكي لا تشفيري.
 */
describe('secureStorageKeys execution local plaintext', () => {
    it('بلوب الإضبارة والفهرس plaintext محلي', () => {
        expect(isExecutionLocalPlaintextKey('execution_exec_priv_1')).toBe(true);
        expect(isExecutionLocalPlaintextKey('execution_exec_priv_1_decisions')).toBe(true);
        expect(isExecutionLocalPlaintextKey('execution_form_exec_priv_1')).toBe(true);
        expect(isExecutionLocalPlaintextKey('executionFiles')).toBe(true);
        expect(isExecutionLocalPlaintextKey('executionFiles:user-abc')).toBe(true);
        expect(isSensitiveStorageKey('execution_exec_priv_1')).toBe(false);
        expect(shouldEncryptValue('execution_x', '{"id":"x"}')).toBe(false);
        expect(shouldEncryptValue('executionFiles:user-abc', '[{"id":"e1"}]')).toBe(false);
    });

    it('أقمار التنفيذ اليومية plaintext', () => {
        expect(isExecutionLocalPlaintextKey('hami_unified_funds_ledger_exec_1')).toBe(true);
        expect(isExecutionLocalPlaintextKey('hami_garnishment_details_exec_1')).toBe(true);
        expect(isExecutionLocalPlaintextKey('garnishment_exec_1')).toBe(true);
        expect(isSensitiveStorageKey('hami_unified_funds_ledger_exec_1')).toBe(false);
        expect(shouldEncryptValue('hami_unified_funds_ledger_exec_1', '{}')).toBe(false);
    });

    it('tombstones التنفيذ plaintext محلي', () => {
        expect(isExecutionLocalPlaintextKey('hami:execution:dossier-tombstones:v1')).toBe(true);
        expect(isExecutionLocalPlaintextKey('hami:execution:dossier-tombstones:v1:uid-1')).toBe(true);
        expect(shouldEncryptValue('hami:execution:dossier-tombstones:v1', '["e1"]')).toBe(false);
    });

    it('الدعاوى تبقى مشفّرة محلياً', () => {
        expect(isSensitiveStorageKey('lawyer_files_active')).toBe(true);
        expect(shouldEncryptValue('lawyer_files_active', '{"cases":[]}')).toBe(true);
        expect(isExecutionLocalPlaintextKey('lawyer_files_active')).toBe(false);
    });

    it('مفاتيح واجهة غير التنفيذ تبقى كما هي', () => {
        expect(isSensitiveStorageKey('lawyer_theme')).toBe(false);
        expect(isExecutionLocalPlaintextKey('lawyer_theme')).toBe(false);
    });
});

describe('secureStorageKeys transactions stay encrypted at rest', () => {
    const oversize = 'x'.repeat(ENCRYPT_MAX_BYTES + 1);

    it('سجل المعاملات والخيوط والقوالب مفاتيح حسّاسة تُشفَّر', () => {
        for (const key of [
            'hami:transactions:v1',
            'hami:transactionsThreading:v1:user-1',
            'hami:transactions:taskTemplates:v1:user-1',
        ] as const) {
            expect(isTransactionsStorageKey(key)).toBe(true);
            expect(isSensitiveStorageKey(key)).toBe(true);
            expect(shouldEncryptValue(key, '[]')).toBe(true);
        }
    });

    it('فوق حدّ الحجم تُشفَّر أو تفشل بلا سقوط لنص صريح', () => {
        for (const key of ['hami:transactions:v1', 'hami:transactionsThreading:v1:user-1'] as const) {
            expect(isWarmEncryptAlwaysKey(key)).toBe(true);
            expect(isEncryptOrFailStorageKey(key)).toBe(true);
            expect(fallsBackToPlaintextBySize(key, oversize)).toBe(false);
            expect(shouldEncryptValue(key, oversize)).toBe(true);
        }
    });

    it('لا يخلط معاملات مع مفاتيح أخرى', () => {
        expect(isTransactionsStorageKey('hami:calendar:events:v1')).toBe(false);
        expect(isTransactionsStorageKey('lawyer_files_active')).toBe(false);
    });
});

describe('secureStorageKeys settings stay encrypted at rest', () => {
    const oversize = 'x'.repeat(ENCRYPT_MAX_BYTES + 1);

    it('lawyer_settings تشفير أو فشل — بلا سقوط لنص صريح', () => {
        expect(isSensitiveStorageKey('lawyer_settings')).toBe(true);
        expect(isWarmEncryptAlwaysKey('lawyer_settings')).toBe(true);
        expect(isEncryptOrFailStorageKey('lawyer_settings')).toBe(true);
        expect(fallsBackToPlaintextBySize('lawyer_settings', oversize)).toBe(false);
        expect(shouldEncryptValue('lawyer_settings', oversize)).toBe(true);
        expect(shouldEncryptValue('lawyer_settings', '{}')).toBe(true);
    });
});

describe('secureStorageKeys tasks stay encrypted at rest', () => {
    const oversize = 'x'.repeat(ENCRYPT_MAX_BYTES + 1);

    it('مهام الأجندة وطلبات العون تشفير أو فشل', () => {
        for (const key of ['hami_quantum_legal_tasks_v1', 'hami_task_help_requests_v1'] as const) {
            expect(isSensitiveStorageKey(key)).toBe(true);
            expect(isWarmEncryptAlwaysKey(key)).toBe(true);
            expect(isEncryptOrFailStorageKey(key)).toBe(true);
            expect(fallsBackToPlaintextBySize(key, oversize)).toBe(false);
            expect(shouldEncryptValue(key, oversize)).toBe(true);
        }
    });
});

import { beforeEach, describe, expect, it } from 'vitest';
import SecureStoreService from '@/app/services/SecureStoreService';

/*
 * الحارس يعدّ عناصر JSON، والمخزَّن لهذه المفاتيح نصّ مشفَّر. حين كان النصّ
 * المشفَّر يُمرَّر كما هو، يفشل التحليل ويُقرأ «صفر عنصر» فتنطفئ الحماية عن
 * أثمن المفاتيح وحدها — الدعاوى والإضابير والملاحظات — بينما تبقى ظاهرياً
 * مفعّلة في الاختبارات التي تُمرّر نصّاً صريحاً.
 */

const ENCRYPTED_PROTECTED_KEYS = ['lawyer_files', 'executionFiles', 'lawyer_notes'] as const;

describe('SecureStoreService — حماية المفاتيح المشفَّرة من الكتابة المُفرِّغة', () => {
    beforeEach(async () => {
        for (const key of SecureStoreService.listKeysSync()) {
            await SecureStoreService.deleteItem(key);
        }
    });

    it.each(ENCRYPTED_PROTECTED_KEYS)('يرفض استبدال %s الممتلئ بمصفوفة فارغة', async (key) => {
        const stored = JSON.stringify([{ id: 'a', caseNo: '2026/1' }, { id: 'b', caseNo: '2026/2' }]);
        await SecureStoreService.setItem(key, stored);

        await SecureStoreService.setItem(key, '[]');

        expect(JSON.parse(String(await SecureStoreService.getItem(key)))).toHaveLength(2);
    });

    it('يمرّر التحديث الحقيقي فوق قيمة مشفَّرة', async () => {
        await SecureStoreService.setItem('lawyer_files', JSON.stringify([{ id: 'a' }]));
        await SecureStoreService.setItem('lawyer_files', JSON.stringify([{ id: 'a' }, { id: 'b' }]));

        expect(JSON.parse(String(await SecureStoreService.getItem('lawyer_files')))).toHaveLength(2);
    });

    it('يمرّر أول كتابة حين لا يوجد سابق', async () => {
        await SecureStoreService.setItem('lawyer_files', '[]');
        expect(await SecureStoreService.getItem('lawyer_files')).toBe('[]');
    });

    it('لا يستبدل نصاً مشفّراً فوراً حين الذاكرة باردة — التفريغ يُرفض', async () => {
        const stored = JSON.stringify([{ id: 'a' }, { id: 'b' }]);
        await SecureStoreService.setItem('lawyer_files', stored);
        SecureStoreService.clearDecryptedMemoryCache();

        expect(SecureStoreService.getItemSync('lawyer_files')).toBeNull();
        expect(SecureStoreService.isUnreadSync('lawyer_files')).toBe(true);

        SecureStoreService.setItemSync('lawyer_files', '[]');
        expect(SecureStoreService.getItemSync('lawyer_files')).toBeNull();

        await SecureStoreService.waitForPendingSetItem('lawyer_files');
        expect(JSON.parse(String(await SecureStoreService.getItem('lawyer_files')))).toHaveLength(2);
    });

    it('يرفض الكتابة غير الفارغة فوق أصل مشفَّر بارد لمفاتيح الدعاوى', async () => {
        await SecureStoreService.setItem(
            'lawyer_files',
            JSON.stringify([{ id: 'a' }, { id: 'b' }]),
        );
        SecureStoreService.clearDecryptedMemoryCache();

        const accepted = SecureStoreService.setItemSync(
            'lawyer_files',
            JSON.stringify([{ id: 'a' }]),
        );
        expect(accepted).toBe(false);
        expect(SecureStoreService.getItemSync('lawyer_files')).toBeNull();
        expect(SecureStoreService.isUnreadSync('lawyer_files')).toBe(true);
    });

    it('يرفض كتابة أفقر عندما المرآة صريحة والقرص مشفّر أغنى', async () => {
        await SecureStoreService.setItem(
            'lawyer_files',
            JSON.stringify([{ id: 'a' }, { id: 'b' }]),
        );
        SecureStoreService.poisonMemoryMirrorForTests('lawyer_files', JSON.stringify([{ id: 'a' }]));

        await SecureStoreService.setItem('lawyer_files', JSON.stringify([{ id: 'a' }]));

