/**
 * إقلاع جلسة مقر التطوير بعد اختصار الباب — كوكي + جهاز موثّق كالمسار الشرعي.
 */
import { DeviceTrustService } from '@/app/domain/admin/deviceTrust';
import { getWifeNativeFetch } from '@/app/security/wifeNativeFetch';
import {
    invalidateCsrfSessionReady,
    markCsrfSessionReadyFromServer,
} from '@/app/security/ensureCsrfSessionReady';
import { setCsrfSessionTokenFromServer } from '@/app/security/csrfSession';
import { readDevMockAccessToken } from '@/app/utils/authStorage';
import { setBffCryptoWrapCredential } from '@/app/utils/bffCryptoSession';
import { clearWifeSignAuthCircuit } from '@/app/utils/bffWifeSign';
import { clearPrimedHeadquartersStatus } from '@/app/services/admin/hqDevSessionPrime';
import { warmLiveHeadquartersApis } from '@/app/services/admin/hqDevSessionWarm';

const BOOTSTRAP_TIMEOUT_MS = 4_000;

type DevUnlockResponse = {
    ok?: boolean;
    csrfToken?: string;
    cryptoWrapCredential?: string;
};

async function postDevUnlock(token: string, fingerprint: string, signal: AbortSignal): Promise<Response> {
    return getWifeNativeFetch()('/api/admin/otp/dev-unlock', {
        method: 'POST',
        credentials: 'include',
        signal,
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
            'x-wife-device-id': fingerprint,
        },
        body: JSON.stringify({ deviceFingerprint: fingerprint }),
    });
}

export async function bootstrapHeadquartersDevSession(): Promise<boolean> {
    if (!import.meta.env.DEV) return false;
    const token = readDevMockAccessToken();
    if (!token) return false;
    const fingerprint = DeviceTrustService.getDeviceFingerprint();
    if (!fingerprint) return false;

    clearPrimedHeadquartersStatus();
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), BOOTSTRAP_TIMEOUT_MS);
    try {
        const res = await postDevUnlock(token, fingerprint, controller.signal);
        if (!res.ok) return false;
        const data = (await res.json().catch(() => null)) as DevUnlockResponse | null;
        if (!data?.ok) return false;
        DeviceTrustService.trustThisDevice(fingerprint);
        if (data.csrfToken) setCsrfSessionTokenFromServer(data.csrfToken);
        if (data.cryptoWrapCredential) setBffCryptoWrapCredential(data.cryptoWrapCredential);
        if (!data.csrfToken || !markCsrfSessionReadyFromServer(data.csrfToken)) {
            invalidateCsrfSessionReady();
        }
        const { clearSecureApiAuthPause } = await import('@/app/services/SecureAPIClient');
        clearSecureApiAuthPause();
        clearWifeSignAuthCircuit();
        window.clearTimeout(timer);
        try {
            await warmLiveHeadquartersApis();
        } catch {
            /* الجلسة قائمة؛ النبض الحي يُكمل إن فشل التسخين */
        }
        return true;
    } catch {
        return false;
    } finally {
        window.clearTimeout(timer);
    }
}

/**
 * نبض المقر بعد إقلاع الاختصار — يُقرأ عند أول رسم حتى لا تظهر «بلا جلسة» ثم تتصل.
 */
import type { HeadquartersLiveStatus } from '@/app/components/admin/hqLiveOverview';
import type { HqCourtStat } from '@/app/domain/admin/hqCourtStats';

let primedStatus: HeadquartersLiveStatus | null = null;
let primedCourts: HqCourtStat[] | null = null;
let primedAudit: unknown[] | null = null;
let primedDevices: unknown[] | null = null;

export function primeHeadquartersLiveStatus(status: HeadquartersLiveStatus): void {
    if (status.sessionRequired || status.system === 'checking') return;
    primedStatus = status;
}

export function peekPrimedHeadquartersStatus(): HeadquartersLiveStatus | null {
    return primedStatus;
}

export function primeHeadquartersCourts(rows: HqCourtStat[]): void {
    primedCourts = rows;
}

export function peekPrimedHeadquartersCourts(): HqCourtStat[] | null {
    return primedCourts;
}

export function primeHeadquartersAudit(entries: unknown[]): void {
    primedAudit = entries;
}

export function peekPrimedHeadquartersAudit(): unknown[] | null {
    return primedAudit;
}

export function primeHeadquartersDevices(devices: unknown[]): void {
    primedDevices = devices;
}

export function peekPrimedHeadquartersDevices(): unknown[] | null {
    return primedDevices;
}

export function clearPrimedHeadquartersStatus(): void {
    primedStatus = null;
    primedCourts = null;
    primedAudit = null;
    primedDevices = null;
}

/**
 * تسخين نبض المقر قبل أول رسم للوحة — اختصار التطوير ومسار الرمز/الجهاز الموثّق.
 */
import {
    markHqStatusFetched,
    parseHeadquartersLiveStatus,
} from '@/app/components/admin/hqLiveOverview';
import { sanitizeHqCourtRows } from '@/app/domain/admin/hqCourtStats';
import {
    primeHeadquartersAudit,
    primeHeadquartersCourts,
    primeHeadquartersDevices,
    primeHeadquartersLiveStatus,
} from '@/app/services/admin/hqDevSessionPrime';

const WARM_TIMEOUT_MS = 3_000;

export async function warmLiveHeadquartersApis(): Promise<void> {
    const { SecureAPIClient } = await import('@/app/services/SecureAPIClient');
    const controller = new AbortController();
    const timer = window.setTimeout(() => controller.abort(), WARM_TIMEOUT_MS);
    const get = (path: string) =>
        SecureAPIClient.fetchSecure<unknown>(path, { method: 'GET', signal: controller.signal });
    try {
        const [statusResult, auditResult, devicesResult, statsResult] = await Promise.allSettled([
            get('/api/admin/status'),
            get('/api/admin/audit'),
            get('/api/admin/devices'),
            get('/api/admin/stats'),
        ]);
        if (statusResult.status === 'fulfilled' && statusResult.value) {
            primeHeadquartersLiveStatus(
                markHqStatusFetched(parseHeadquartersLiveStatus(statusResult.value), new Date().toISOString()),
            );
        }
        if (auditResult.status === 'fulfilled' && auditResult.value && typeof auditResult.value === 'object') {
            const rec = auditResult.value as { ok?: boolean; entries?: unknown };
            if (rec.ok && Array.isArray(rec.entries)) primeHeadquartersAudit(rec.entries);
        }
        if (devicesResult.status === 'fulfilled' && devicesResult.value && typeof devicesResult.value === 'object') {
            const rec = devicesResult.value as { ok?: boolean; devices?: unknown };
            if (rec.ok && Array.isArray(rec.devices)) primeHeadquartersDevices(rec.devices);
        }
        if (statsResult.status === 'fulfilled' && statsResult.value && typeof statsResult.value === 'object') {
            const rec = statsResult.value as { ok?: boolean; courts?: unknown };
            if (rec.ok) {
                primeHeadquartersCourts(sanitizeHqCourtRows(rec.courts));
            }
        }
    } finally {
        window.clearTimeout(timer);
    }
}

import { noteHqAuditRecorded } from '@/app/components/admin/hqAuditClient';
import { isHqStepUpRequired, promptHqStepUp } from '@/app/components/admin/hqStepUpClient';
import { SecureAPIClient } from '@/app/services/SecureAPIClient';

async function fetchNoted<T>(endpoint: string, options?: RequestInit): Promise<T> {
    const data = await SecureAPIClient.fetchSecure<T>(endpoint, options);
    noteHqAuditRecorded(data);
    return data;
}

/** جلب طفرة مقر: إن طُلب رمز تحقق جديد يفتح الغطاء ثم يعيد المحاولة مرة واحدة. */
export async function hqMutatingFetch<T>(endpoint: string, options?: RequestInit): Promise<T> {
    try {
        return await fetchNoted<T>(endpoint, options);
    } catch (error) {
        if (!isHqStepUpRequired(error)) throw error;
        await promptHqStepUp();
        return await fetchNoted<T>(endpoint, options);
    }
}

import type {
    SecretaryAlert,
    SecretaryAlertTarget,
} from '@/app/services/SecretaryOrchestrator';
import { isInjectedFieldTaskAlert } from '@/app/services/fieldTaskAlerts';
import { isLikelyCaseReference } from '@/app/workspace/pinDisplayUtils';

const FIELD_DAY_SECTION_LABEL = 'مهام اليوم الميدانية';

const FALLBACK_HEADLINE: Partial<Record<SecretaryAlertTarget, string>> = {
    criminal: 'إضبارة جزائية غير معنونة',
    lawsuit: 'إضبارة مدنية غير معنونة',
    execution: 'إضبارة تنفيذ غير معنونة',
    urgent: 'طلب مستعجل غير معنون',
    transactions: 'معاملة ملف غير معنونة',
    threading: 'معاملة إدارية غير معنونة',
    notepad: 'ملاحظة بدون عنوان',
    schedule: 'موعد في التقويم',
};

function isBrokenDisplayValue(value?: string | null): boolean {
    if (value == null) return true;
    const t = String(value).trim();
    if (!t) return true;
    const lower = t.toLowerCase();
    return (
        lower === 'undefined' ||
        lower === 'null' ||
        lower === 'nan' ||
        t === '—' ||
        t === 'موكل غير محدد' ||
        t === 'مدين غير محدد'
    );
}

function sanitizeDisplayText(value?: string | null): string | undefined {
    if (isBrokenDisplayValue(value)) return undefined;
    return String(value).trim();
}

/** وقت نهاية اليوم البرمجي أو 23:59 — لا يُعرض في الشارة */
export function isEndOfDayPlaceholderTime(iso: string): boolean {
    const ts = Date.parse(iso);
    if (Number.isNaN(ts)) return false;
    const d = new Date(ts);
    return d.getHours() === 23 && d.getMinutes() >= 58;
}

export function isPlaceholderDisplayTime(iso: string): boolean {
    if (isEndOfDayPlaceholderTime(iso)) return true;
    const ts = Date.parse(iso);
    if (Number.isNaN(ts)) return false;
    const d = new Date(ts);
    return d.getHours() === 23 && d.getMinutes() === 59;
}

const SECTION_KIND_SHORT: Partial<Record<SecretaryAlertTarget, string>> = {
    criminal: 'جزائي',
    lawsuit: 'مدني',
    execution: 'تنفيذ',
    urgent: 'مستعجل',
    transactions: 'معاملات',
    threading: 'إداري',
    notepad: 'مفكرة',
    schedule: 'تقويم',
};

function normalizeArabicForCompare(text: string): string {
    return text
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase()
        .replace(/أ|إ|آ/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي');
}

/** محكمة الجنح/الجنايات لا تبقى في «مرحلة التحقيق» */
export function normalizeProceduralPhase(phase: string, courtName?: string): string {
    let p = phase.trim();
    if (!p) return p;
    const court = courtName?.trim() || '';
    const isFelonyCourt = /جنح|جنايات/i.test(court);
    if (isFelonyCourt && /تحقيق/i.test(p)) {
        return 'مرحلة المحاكمة';
    }
    if (isFelonyCourt && /^تحقيق/i.test(p)) {
        return 'مرحلة المحاكمة';
    }
    return p;
}

function dedupePhaseFromCourt(phase: string, courtName?: string): string {
    let p = phase.trim();
    const court = courtName?.trim();
    if (!court || !p) return p;

    const pNorm = normalizeArabicForCompare(p);
    const cNorm = normalizeArabicForCompare(court);
    if (cNorm && pNorm.includes(cNorm)) {
        p = p
            .replace(new RegExp(court.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'gi'), '')
            .replace(/^[—–\-\s]+/, '')
            .replace(/\s*[—–-]\s*/g, ' ')
            .trim();
    }

    const dash = p.indexOf('—');
    if (dash > 0) {
        const left = p.slice(0, dash).trim();
        const right = p.slice(dash + 1).trim();
        if (normalizeArabicForCompare(left) === cNorm) return right;
        if (normalizeArabicForCompare(right) === cNorm) return left;
    }

    return p;
}

function rawPhaseFromAlert(alert: SecretaryAlert): string {
    const explicit = sanitizeDisplayText(alert.actionType);
    if (explicit) return explicit;

    const summary = alert.summary?.trim() || '';
    const dash = summary.indexOf('—');
    if (dash >= 0) {
        const action = summary.slice(dash + 1).trim();
        if (action && !isBrokenDisplayValue(action)) return action;
    }
    return sanitizeDisplayText(summary) ?? '';
}

const TARGET_SECTION: Record<SecretaryAlertTarget, { label: string; icon: string }> = {
    schedule: { label: 'التقويم', icon: '📅' },
    lawsuit: { label: 'الدعاوى المدنية', icon: '⚖️' },
    execution: { label: 'التنفيذ', icon: '🔨' },
    criminal: { label: 'الجزائي', icon: '🏛️' },
    urgent: { label: 'المستعجلات', icon: '⚡' },
    transactions: { label: 'معاملات الملف', icon: '📁' },
    threading: { label: 'المعاملات الإدارية', icon: '📋' },
    notepad: { label: 'المستودع الذكي', icon: '📝' },
    community: { label: 'المنتدى القانوني', icon: '💬' },
};

export function sectionMetaForTarget(target: SecretaryAlertTarget): { label: string; icon: string } {
    return TARGET_SECTION[target] ?? { label: 'مساحة العمل', icon: '📌' };
}

export function extractValidCaseRef(alert: SecretaryAlert): string | undefined {
    const direct = alert.caseNumber?.trim();
    if (direct && direct !== '—' && isLikelyCaseReference(direct)) return direct;
    if (direct && direct !== '—') return direct;
    const dash = alert.title.lastIndexOf('—');
    if (dash >= 0) {
        const ref = alert.title.slice(dash + 1).trim();
        if (ref && ref !== '—') return ref;
    }
    return undefined;
}

export function formatAlertDueAt(iso?: string): string | undefined {
    if (!iso) return undefined;
    const ts = Date.parse(iso);
    if (Number.isNaN(ts)) return undefined;
    const d = new Date(ts);
    const dateOnly = isPlaceholderDisplayTime(iso);

    try {
        return new Intl.DateTimeFormat('ar-IQ', {
            weekday: 'long',
            day: 'numeric',
            month: 'long',
            ...(dateOnly
                ? {}
                : { hour: '2-digit' as const, minute: '2-digit' as const }),
        }).format(d);
    } catch {
        return d.toLocaleDateString('ar-IQ', {
            weekday: 'long',
            day: 'numeric',
            month: 'long',
        });
    }
}

/** سطر ثانٍ: [القسم] — [المرحلة] مع منع التكرار والتناقض */
export function buildSectionPhaseLine(alert: SecretaryAlert): string {
    if (isInjectedFieldTaskAlert(alert)) {
        const loc = sanitizeDisplayText(alert.actionType);
        if (loc && loc !== 'مهمة ميدانية' && !loc.includes(FIELD_DAY_SECTION_LABEL)) {
            return `${FIELD_DAY_SECTION_LABEL} — ${loc}`;
        }
        return FIELD_DAY_SECTION_LABEL;
    }

    const section =
        (alert.calendarSource?.module === 'task'
            ? 'مهمة ميدان'
            : SECTION_KIND_SHORT[alert.target]) ??
        sectionMetaForTarget(alert.target).label;

    const court = buildCourtSubtitle(alert);
    let phase = rawPhaseFromAlert(alert);
    phase = dedupePhaseFromCourt(phase, court);
    phase = normalizeProceduralPhase(phase, court);

    if (!phase || isBrokenDisplayValue(phase)) return section;
    const phaseNorm = normalizeArabicForCompare(phase);
    const sectionNorm = normalizeArabicForCompare(section);
    if (phaseNorm === sectionNorm || phaseNorm.startsWith(sectionNorm)) return phase;
    return `${section} — ${phase}`;
}

export function buildFutureTimeLabel(dueIso?: string): string | undefined {
    if (!dueIso) return undefined;
    const dueMs = Date.parse(dueIso);
    if (Number.isNaN(dueMs)) return undefined;
    const hoursLeft = (dueMs - Date.now()) / (1000 * 60 * 60);
    if (hoursLeft < 0) return undefined;
    if (hoursLeft < 1) return `خلال ${Math.max(1, Math.round(hoursLeft * 60))} دقيقة`;
    if (hoursLeft < 24) return `خلال ${Math.round(hoursLeft)} ساعة`;
    if (hoursLeft < 48) return 'قريباً';
    return `باقي ${Math.round(hoursLeft / 24)} يوم`;
}

/** عنوان رئيسي مع fallbacks حسب القسم */
export function buildAlertHeadline(alert: SecretaryAlert): string {
    const client = sanitizeDisplayText(alert.clientName);
    const caseRef =
        sanitizeDisplayText(alert.caseNumber) ||
        (extractValidCaseRef(alert) ? sanitizeDisplayText(extractValidCaseRef(alert)) : undefined);

    if (client && caseRef) return `${client} — ${caseRef}`;
    if (client) return client;
    if (caseRef) return caseRef;

    const fromTitle = sanitizeDisplayText(alert.title);
    if (
        fromTitle &&
        !isBrokenDisplayValue(fromTitle) &&
        !/\bundefined\b/i.test(fromTitle) &&
        !/\bnull\b/i.test(fromTitle)
    ) {
        return fromTitle;
    }

    return FALLBACK_HEADLINE[alert.target] ?? 'إضبارة غير معنونة';
}

/** اسم المحكمة — سطر فرعي مباشرة تحت العنوان */
export function buildCourtSubtitle(alert: SecretaryAlert): string | undefined {
    const court = sanitizeDisplayText(alert.courtName);
    if (court) return court;
    const summary = alert.summary?.trim() || '';
    const dash = summary.indexOf('—');
    if (dash > 0) {
        const maybeCourt = summary.slice(0, dash).trim();
        if (maybeCourt && maybeCourt !== '—' && !isBrokenDisplayValue(maybeCourt)) {
            return maybeCourt;
        }
    }
    return undefined;
}

export type AlertDisplayMeta = {
    sectionLabel: string;
    sectionIcon: string;
    headline: string;
    /** @deprecated استخدم courtSubtitle — بقي للتوافق */
    subtitle: string;
    courtSubtitle?: string;
    sectionPhaseLine?: string;
    alertReason?: string;
    caseRef?: string;
    dueFormatted?: string;
    clientName?: string;
    courtName?: string;
};

export function buildAlertDisplayMeta(alert: SecretaryAlert): AlertDisplayMeta {
    const caseRef = extractValidCaseRef(alert);
    const clientName = sanitizeDisplayText(alert.clientName);
    const sectionPhaseLine = buildSectionPhaseLine(alert);
    const headline = buildAlertHeadline(alert);

    if (isInjectedFieldTaskAlert(alert)) {
        return {
            sectionLabel: FIELD_DAY_SECTION_LABEL,
            sectionIcon: '📋',
            headline,
            subtitle: FIELD_DAY_SECTION_LABEL,
            courtSubtitle: FIELD_DAY_SECTION_LABEL,
            sectionPhaseLine,
            alertReason: undefined,
            caseRef,
            dueFormatted: formatAlertDueAt(alert.dueAt),
            clientName: clientName && clientName !== caseRef ? clientName : undefined,
            courtName: undefined,
        };
    }

    const section = sectionMetaForTarget(alert.target);
    const courtSubtitle = buildCourtSubtitle(alert);

    return {
        sectionLabel: section.label,
        sectionIcon: section.icon,
        headline,
        subtitle: sectionPhaseLine,
        courtSubtitle,
        sectionPhaseLine,
        alertReason: undefined,
        caseRef,
        dueFormatted: formatAlertDueAt(alert.dueAt),
        clientName: clientName && clientName !== caseRef ? clientName : undefined,
        courtName: courtSubtitle,
    };
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { UrgentCase } from '@/app/components/lawyer/Component_Urgent_Card';
import { isUrgentCaseClosed } from '@/app/components/lawyer/Component_Urgent_Card';
import type { CriminalCase } from '@/app/components/lawyer/criminal-system/criminalStore';
import type { CalendarSourceModule } from '@/app/services/calendarBridge.types';
import type { ExecutionFile } from '@/app/types/execution';
import { normalizeDossierLifecycleStatus } from '@/app/types/execution';
import { isExecutionArchived, isExecutionInTrash } from '@/app/utils/executionTrash';

export type DossierContext = {
    clientName: string;
    caseNumber: string;
    courtName: string;
    actionType: string;
};

export type DossierRegistry = {
    isActive: (module: string | undefined, entityId: string | undefined) => boolean;
    resolve: (module: string | undefined, entityId: string | undefined) => DossierContext | null;
};

function safeText(value: unknown): string {
    if (typeof value !== 'string') return '';
    return value.trim();
}

export function isActiveLawsuitFile(file: FileData): boolean {
    if (
        file.status === 'deleted' ||
        file.status === 'archived' ||
        file.status === 'archived_stage' ||
        file.status === 'paused'
    ) {
        return false;
    }
    return true;
}

export function isActiveExecutionFile(raw: unknown): boolean {
    if (!raw || typeof raw !== 'object') return false;
    const f = raw as ExecutionFile & { executionTrashDeletedAt?: string | null; deleted?: boolean };
    if (f.deleted === true) return false;
    if (isExecutionInTrash(f)) return false;
    if (isExecutionArchived(f)) return false;
    if (normalizeDossierLifecycleStatus(f.dossier_lifecycle_status) === 'finished') return false;
    return true;
}

export function isActiveUrgentCaseRecord(raw: unknown): boolean {
    if (!raw || typeof raw !== 'object') return false;
    const c = raw as UrgentCase;
    if (c.deleted || c.archived) return false;
    if (c.phase === 'completed' || c.status === 'completed') return false;
    if (isUrgentCaseClosed(c)) return false;
    return true;
}

export function isActiveCriminalCase(raw: unknown): boolean {
    if (!raw || typeof raw !== 'object') return false;
    const c = raw as CriminalCase;
    if (c.isArchived === true) return false;
    if (c.dossierStatus === 'merged') return false;
    return true;
}

function clientNameFromParties(file: FileData): string {
    const p = file.parties?.find((x) => x.isClient);
    return p?.name?.trim() || '';
}

function contextFromLawsuit(file: FileData): DossierContext {
    return {
        clientName: clientNameFromParties(file) || 'موكل غير محدد',
        caseNumber: safeText(file.caseNo) || '—',
        courtName: safeText(file.court) || '—',
        actionType: safeText(file.currentStage) || safeText(file.docType) || 'دعوى مدنية',
    };
}

function contextFromExecution(file: ExecutionFile): DossierContext {
    const debtor = file.debtors?.[0]?.name?.trim();
    const court =
        safeText((file as { court_name?: string }).court_name) ||
        safeText(file.directorate) ||
        '—';
    const fileNo = safeText(file.fileNumber) || '—';
    const year = safeText(file.fileYear);
    const caseNumber = year && fileNo !== '—' ? `${fileNo}/${year}` : fileNo;
    return {
        clientName: debtor || 'مدين غير محدد',
        caseNumber,
        courtName: court,
        actionType: safeText(file.claimType) || safeText(file.docType) || 'إضبارة تنفيذ',
    };
}

function contextFromUrgent(c: UrgentCase): DossierContext {
    return {
        clientName: safeText(c.applicantName) || 'موكل غير محدد',
        caseNumber: safeText(c.requestNumber) || '—',
        courtName: safeText(c.court) || safeText(c.courtName) || '—',
        actionType:
            safeText(c.actionType) || safeText(c.specificActionType) || 'طلب مستعجل',
    };
}

function contextFromCriminal(c: CriminalCase): DossierContext {
    const defendant = c.defendants?.[0]?.fullName?.trim();
    const complainant = c.complainants?.[0]?.fullName?.trim();
    const clientName = defendant || complainant || 'موكل غير محدد';
    const caseNumber =
        safeText(c.location?.caseNumber) ||
        safeText(c.location?.investigationDossierNumber) ||
        safeText(c.location?.baseRegisterNumberAndDate) ||
        '—';
    const courtName =
        safeText(c.location?.courtName) ||
        safeText(c.location?.investigationCourtName) ||
        '—';
    const stage = safeText(c.basics?.stage);
    return {
        clientName,
        caseNumber,
        courtName,
        actionType: stage ? `جزائي — ${stage}` : 'قضية جزائية',
    };
}

export function buildDossierRegistry(params: {
    lawsuitFiles: FileData[];
    executionFiles: unknown[];
    urgentCases: unknown[];
    criminalCases?: unknown[];
}): DossierRegistry {
    const byKey = new Map<string, DossierContext>();
    const activeKeys = new Set<string>();

    for (const f of params.lawsuitFiles) {
        if (!isActiveLawsuitFile(f)) continue;
        const id = String(f.id);
        activeKeys.add(`lawsuit:${id}`);
        byKey.set(`lawsuit:${id}`, contextFromLawsuit(f));
        if (f.type === 'transaction') {
            activeKeys.add(`transaction:${id}`);
            byKey.set(`transaction:${id}`, contextFromLawsuit(f));
        }
    }

    for (const raw of params.executionFiles) {
        if (!isActiveExecutionFile(raw)) continue;
        const f = raw as ExecutionFile;
        const id = String(f.id);
        activeKeys.add(`execution:${id}`);
        byKey.set(`execution:${id}`, contextFromExecution(f));
    }

    for (const raw of params.urgentCases) {
        if (!isActiveUrgentCaseRecord(raw)) continue;
        const c = raw as UrgentCase;
        const id = String(c.id);
        activeKeys.add(`urgent:${id}`);
        byKey.set(`urgent:${id}`, contextFromUrgent(c));
    }

    for (const raw of params.criminalCases ?? []) {
        if (!isActiveCriminalCase(raw)) continue;
        const c = raw as CriminalCase;
        const id = String(c.id);
        activeKeys.add(`criminal:${id}`);
        byKey.set(`criminal:${id}`, contextFromCriminal(c));
    }

    return {
        isActive(module, entityId) {
            if (!entityId?.trim()) return true;
            const mod = (module ?? 'manual') as CalendarSourceModule;
            // التقويم مصدر الحقيقة لمهل Threading والمهام/الملاحظات — ليست في سجل الإضابير.
            if (mod === 'manual' || mod === 'task' || mod === 'note' || mod === 'threading') {
                return true;
            }
            return activeKeys.has(`${mod}:${entityId}`);
        },
        resolve(module, entityId) {
            if (!entityId?.trim()) return null;
            const mod = module ?? 'lawsuit';
            return byKey.get(`${mod}:${entityId}`) ?? null;
        },
    };
}

export function contextFromCalendarEvent(ev: {
    title: string;
    caseNo?: string;
    clientName?: string;
    court?: string;
    sourceLabel?: string;
    partiesSummary?: string;
}): DossierContext {
    const session = ev.title.replace(/^جلسة(?:\s*قادمة)?\s*[—–-]\s*/u, '').trim();
    return {
        clientName: safeText(ev.clientName) || safeText(ev.partiesSummary) || 'موكل غير محدد',
        caseNumber: safeText(ev.caseNo) || '—',
        courtName: safeText(ev.court) || '—',
        actionType: session || safeText(ev.sourceLabel) || safeText(ev.title) || 'موعد',
    };
}

export function mergeDossierContext(
    primary: DossierContext | null,
    fallback: DossierContext,
): DossierContext {
    if (!primary) return fallback;
    return {
        clientName:
            primary.clientName !== 'موكل غير محدد' && primary.clientName !== 'مدين غير محدد'
                ? primary.clientName
                : fallback.clientName,
        caseNumber: primary.caseNumber !== '—' ? primary.caseNumber : fallback.caseNumber,
        courtName: primary.courtName !== '—' ? primary.courtName : fallback.courtName,
        actionType: primary.actionType || fallback.actionType,
    };
}

import type { SecretaryAlertType, SecretaryAlertTarget } from '@/app/services/SecretaryOrchestrator';
import type { CalendarAlertSource } from '@/app/services/SecretaryOrchestrator';
import { isInjectedFieldTaskAlert } from '@/app/services/fieldTaskAlerts';

type FutureActionAlertHint = {
    type: SecretaryAlertType;
    target: SecretaryAlertTarget;
    calendarSource?: CalendarAlertSource;
};

function isFieldTaskAlert(alert: FutureActionAlertHint): boolean {
    if (isInjectedFieldTaskAlert({ id: '', calendarSource: alert.calendarSource })) return true;
    if (alert.calendarSource?.module === 'task') return true;
    if (alert.target === 'schedule' && alert.type === 'DEADLINE') return true;
    if (alert.type === 'TASK') return true;
    return false;
}

function isHearingLikeAlert(alert: {
    type: SecretaryAlertType;
    target: SecretaryAlertTarget;
}): boolean {
    if (alert.type === 'HEARING' || alert.type === 'EXECUTION' || alert.type === 'URGENT') return true;
    if (alert.target === 'lawsuit' || alert.target === 'criminal' || alert.target === 'urgent') {
        return alert.type !== 'DEADLINE' && alert.type !== 'TASK';
    }
    return false;
}

/** نص الزر السفلي للمواعيد القادمة فقط */
export function suggestedFutureActionForAlert(alert: FutureActionAlertHint): string {
    if (isHearingLikeAlert(alert)) {
        return '⚖️ تحضير دفوع الجلسة';
    }
    if (isInjectedFieldTaskAlert({ id: '', calendarSource: alert.calendarSource })) {
        return '📋 استعراض وإنجاز المهمة الميدانية';
    }
    if (isFieldTaskAlert(alert)) {
        return '📋 استعراض تفاصيل المهمة';
    }
    switch (alert.target) {
        case 'lawsuit':
            return 'فتح إضبارة الدعوى';
        case 'execution':
            return 'فتح إضبارة التنفيذ';
        case 'criminal':
            return 'فتح القضية الجزائية';
        case 'urgent':
            return 'فتح الطلب المستعجل';
        case 'threading':
            return 'فتح المعاملة الإدارية';
        case 'transactions':
            return 'فتح ملف المعاملة';
        case 'notepad':
            return 'فتح المستودع الذكي';
        default:
            return 'فتح الموعد';
    }
}

import { normalizeDateToYmd } from '@/app/services/calendar/bridge/core';
import { toBaghdadYmd } from '@/app/utils/baghdadTime';

/** YYYY-MM-DD وفق Asia/Baghdad */
export function localTodayYmd(now: Date = new Date()): string {
    return toBaghdadYmd(now) ?? normalizeDateToYmd(now.toISOString()) ?? '';
}

export function compareYmd(a: string, b: string): number {
    if (a === b) return 0;
    return a < b ? -1 : 1;
}

/** تاريخ الحدث >= اليوم (مقارنة يومية محلية) */
export function isEventDateOnOrAfterToday(dateYmd: string | null | undefined, now?: Date): boolean {
    const ymd = normalizeDateToYmd(dateYmd ?? '');
    if (!ymd) return false;
    return compareYmd(ymd, localTodayYmd(now)) >= 0;
}

/**
 * تاريخ الحدث > اليوم بدقة (يستبعد التواريخ الماضية واليوم نفسه).
 * يُستخدم في البطاقة العامة لمنع ظهور تنبيهات اليوم نفسه (المستخدم يراها مباشرة في التقويم).
 */
export function isEventStrictlyAfterToday(
    dateYmd: string | null | undefined,
    now?: Date,
): boolean {
    const ymd = normalizeDateToYmd(dateYmd ?? '');
    if (!ymd) return false;
    return compareYmd(ymd, localTodayYmd(now)) > 0;
}

export function daysFromTodayYmd(eventYmd: string, todayYmd: string): number {
    const a = parseYmdParts(eventYmd);
    const b = parseYmdParts(todayYmd);
    if (!a || !b) return 0;
    const t1 = Date.UTC(a.y, a.m - 1, a.d);
    const t2 = Date.UTC(b.y, b.m - 1, b.d);
    return Math.round((t1 - t2) / (24 * 60 * 60 * 1000));
}

function parseYmdParts(ymd: string): { y: number; m: number; d: number } | null {
    const m = ymd.match(/^(\d{4})-(\d{2})-(\d{2})/);
    if (!m) return null;
    return { y: Number(m[1]), m: Number(m[2]), d: Number(m[3]) };
}

/** استحقاق ISO — الجزء اليومي >= اليوم */
export function isFutureDueIso(iso: string | null | undefined, now?: Date): boolean {
    if (!iso) return false;
    const ts = Date.parse(iso);
    if (Number.isNaN(ts)) return false;
    const d = new Date(ts);
    const ymd = localTodayYmd(d);
    return compareYmd(ymd, localTodayYmd(now)) >= 0;
}

/** أقصى أفق عرض في البطاقة العامة (يوم) */
export const ALERT_FUTURE_MAX_HORIZON_DAYS = 120;

import { AlertTriangle } from '@/app/components/ui/icons/AlertTriangle';
import { ClipboardList } from '@/app/components/ui/icons/ClipboardList';
import { Clock } from '@/app/components/ui/icons/Clock';
import { Hammer } from '@/app/components/ui/icons/Hammer';
import { Scale } from '@/app/components/ui/icons/Scale';
import { FileText } from '@/app/components/ui/icons/FileText';
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { isInjectedFieldTaskAlert } from '@/app/services/fieldTaskAlerts';
import { filterVisibleAlerts } from '@/app/services/appAlertDismiss';
import {
    buildAlertDisplayMeta,
    buildFutureTimeLabel,
    extractValidCaseRef,
} from '@/app/services/alertDisplayMeta';
import type { SmartAlert, AlertPriority } from '@/app/components/lawyer/NeuralAlertsCard/types';

function priorityFromSecretary(p: number): AlertPriority {
    if (p <= 1) return 'critical';
    if (p <= 2) return 'high';
    if (p <= 3) return 'medium';
    return 'low';
}

function actionForAlert(alert: SecretaryAlert): SmartAlert['actionType'] {
    if (
        alert.target === 'lawsuit' ||
        alert.target === 'execution' ||
        alert.target === 'urgent' ||
        alert.target === 'criminal'
    ) {
        return 'openChecklist';
    }
    if (alert.target === 'notepad') return 'openNotepad';
    if (alert.target === 'transactions' || alert.target === 'threading') return 'openScanner';
    if (alert.calendarSource?.module === 'task') return 'openChecklist';
    return 'openChecklist';
}

function iconForAlert(alert: SecretaryAlert) {
    if (isInjectedFieldTaskAlert(alert)) {
        return ClipboardList;
    }
    switch (alert.type) {
        case 'HEARING':
            return Scale;
        case 'NOTE':
            return FileText;
        case 'EXECUTION':
            return Hammer;
        case 'URGENT':
            return AlertTriangle;
        default:
            return Clock;
    }
}

function colorForPriority(p: AlertPriority): SmartAlert['colorTheme'] {
    if (p === 'critical') return 'amber';
    if (p === 'high') return 'blue';
    return 'purple';
}

export function secretaryAlertToSmartAlert(alert: SecretaryAlert): SmartAlert {
    const priority = priorityFromSecretary(alert.priority);
    const meta = buildAlertDisplayMeta(alert);
    const dueMs = alert.dueAt ? Date.parse(alert.dueAt) : NaN;
    const timeLabel = buildFutureTimeLabel(alert.dueAt) ?? (Number.isFinite(dueMs) ? 'قريباً' : undefined);

    return {
        id: alert.id,
        title: meta.headline,
        description: meta.sectionPhaseLine ?? meta.subtitle ?? '',
        priority,
        actionType: actionForAlert(alert),
        actionLabel: alert.suggestedAction ?? 'فتح',
        payload: {
            caseId: alert.entityId,
            entityId: alert.entityId,
            target: alert.target,
            secretaryType: alert.type,
        },
        timestamp: Number.isFinite(dueMs) ? dueMs : Date.now(),
        clientName: meta.clientName,
        caseNo: meta.caseRef ?? extractValidCaseRef(alert),
        timeLabel,
        colorTheme: colorForPriority(priority),
        icon: iconForAlert(alert),
        sectionLabel: meta.sectionLabel,
        sectionIcon: meta.sectionIcon,
        dueFormatted: meta.dueFormatted,
        courtName: meta.courtName,
        courtSubtitle: meta.courtSubtitle,
        sectionPhaseLine: meta.sectionPhaseLine,
        clientPhone: alert.clientPhone,
    };
}

/** أقصى أولوية تُحسب في شارة الجرس وتبويب «عاجل» الموحّد */
export const HEADER_BADGE_MAX_PRIORITY = 2;

export function isHeaderBadgePriority(priority: number): boolean {
    return priority <= HEADER_BADGE_MAX_PRIORITY;
}

export function countHighPriorityAlerts(alerts: SecretaryAlert[]): number {
    return alerts.filter((a) => isHeaderBadgePriority(a.priority)).length;
}

export function combineHeaderUnreadCount(
    notificationUnread: number,
    secretaryAlerts: SecretaryAlert[],
    dismissedIds?: string[],
): number {
    const visible = filterVisibleAlerts(secretaryAlerts, dismissedIds);
    return notificationUnread + countHighPriorityAlerts(visible);
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { SecretaryAlert, SecretaryAlertTarget } from '@/app/services/SecretaryOrchestrator';
import type { LegalTask } from '@/app/types/TaskEngine';
import { EXECUTION_VISIT_NEXT_EVENT_ID } from '@/app/services/calendar/dossierSync/executionVisitNextEventId';

export type AlertNavigationAction =
    | { kind: 'tab'; tab: 'schedule' | 'community' | 'home' }
    | { kind: 'notepad'; noteId?: string }
    | { kind: 'transactions'; entityId?: string }
    | { kind: 'threading_tx'; entityId: string }
    | { kind: 'urgent_dashboard'; entityId?: string }
    | { kind: 'open_lawsuit'; entityId: string }
    | { kind: 'open_execution'; entityId: string; openVisitationWorkspace?: boolean }
    | { kind: 'open_criminal'; entityId: string }
    | { kind: 'open_field_tasks' }
    | { kind: 'noop' };

export type AlertNavigationContext = {
    lawsuitFiles?: FileData[];
    fieldTasks?: LegalTask[];
};

function resolveFromCalendarSource(alert: SecretaryAlert): AlertNavigationAction | null {
    const cs = alert.calendarSource;
    if (!cs?.dossierModule || !cs.dossierId) return null;
    switch (cs.dossierModule) {
        case 'lawsuit':
            return { kind: 'open_lawsuit', entityId: cs.dossierId };
        case 'execution':
            return {
                kind: 'open_execution',
                entityId: cs.dossierId,
                openVisitationWorkspace: cs.eventId === EXECUTION_VISIT_NEXT_EVENT_ID,
            };
        case 'criminal':
            return { kind: 'open_criminal', entityId: cs.dossierId };
        case 'urgent':
            return { kind: 'urgent_dashboard', entityId: cs.dossierId };
        case 'threading':
            return { kind: 'threading_tx', entityId: cs.dossierId };
        case 'transaction':
            return { kind: 'transactions', entityId: cs.dossierId };
        default:
            return null;
    }
}

function resolveFieldTaskNavigation(
    alert: SecretaryAlert,
    ctx?: AlertNavigationContext,
): AlertNavigationAction | null {
    const cs = alert.calendarSource;
    if (cs?.module !== 'task' && cs?.module !== 'field_day_task') return null;

    const taskId = cs?.entityId ?? alert.entityId;
    if (ctx?.fieldTasks && taskId) {
        const task = ctx.fieldTasks.find((t) => String(t.id) === String(taskId));
        const linked = task?.linkedCaseId?.trim();
        if (linked) return { kind: 'open_lawsuit', entityId: linked };
    }

    const linkedFromCalendar = cs?.dossierId;
    if (linkedFromCalendar) return { kind: 'open_lawsuit', entityId: linkedFromCalendar };

    return { kind: 'open_field_tasks' };
}

function resolveNoteNavigation(alert: SecretaryAlert): AlertNavigationAction | null {
    if (alert.calendarSource?.module !== 'note' && alert.target !== 'notepad') return null;
    const noteId = alert.calendarSource?.entityId ?? alert.entityId;
    const dossier = resolveFromCalendarSource(alert);
    if (dossier && dossier.kind === 'open_lawsuit') return dossier;
    return { kind: 'notepad', noteId: noteId ? String(noteId) : undefined };
}

export function resolveAlertNavigation(
    alert: SecretaryAlert,
    ctx?: AlertNavigationContext,
): AlertNavigationAction {
    const fromCalendar = resolveFromCalendarSource(alert);
    if (fromCalendar) return fromCalendar;

    const fieldNav = resolveFieldTaskNavigation(alert, ctx);
    if (fieldNav) return fieldNav;

    const noteNav = resolveNoteNavigation(alert);
    if (noteNav) return noteNav;

    switch (alert.target as SecretaryAlertTarget) {
        case 'schedule':
            return { kind: 'tab', tab: 'schedule' };
        case 'notepad':
            return {
                kind: 'notepad',
                noteId: alert.entityId ? String(alert.entityId) : undefined,
            };
        case 'transactions':
            return alert.entityId
                ? { kind: 'transactions', entityId: String(alert.entityId) }
                : { kind: 'transactions' };
        case 'threading':
            return alert.entityId
                ? { kind: 'threading_tx', entityId: String(alert.entityId) }
                : { kind: 'transactions' };
        case 'community':
            return { kind: 'tab', tab: 'community' };
        case 'urgent':
            return alert.entityId
                ? { kind: 'urgent_dashboard', entityId: String(alert.entityId) }
                : { kind: 'urgent_dashboard' };
        case 'lawsuit':
            return alert.entityId ? { kind: 'open_lawsuit', entityId: String(alert.entityId) } : { kind: 'noop' };
        case 'execution':
            return alert.entityId
                ? {
                      kind: 'open_execution',
                      entityId: String(alert.entityId),
                      openVisitationWorkspace:
                          alert.calendarSource?.eventId === EXECUTION_VISIT_NEXT_EVENT_ID,
                  }
                : { kind: 'noop' };
        case 'criminal':
            return alert.entityId ? { kind: 'open_criminal', entityId: String(alert.entityId) } : { kind: 'noop' };
        default:
            return { kind: 'noop' };
    }
}

import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import type { DossierContext } from '@/app/services/alertDossierRegistry';
import { suggestedFutureActionForAlert } from '@/app/services/alertFutureActions';

export function formatAlertTitle(clientName: string, caseNumber: string): string {
    const client = clientName.trim() || 'موكل غير محدد';
    const ref = caseNumber.trim();
    if (ref && ref !== '—') return `${client} — ${ref}`;
    return client;
}

export function formatAlertSubtitle(courtName: string, actionType: string): string {
    const court = courtName.trim();
    const action = actionType.trim();
    if (court && court !== '—' && action) return `${court} — ${action}`;
    if (court && court !== '—') return court;
    return action || '—';
}

export function hasRichAlertMinimumContext(ctx: DossierContext): boolean {
    const hasClient =
        Boolean(ctx.clientName.trim()) &&
        ctx.clientName !== 'موكل غير محدد' &&
        ctx.clientName !== 'مدين غير محدد';
    const hasCase = Boolean(ctx.caseNumber.trim()) && ctx.caseNumber !== '—';
    return hasClient || hasCase;
}

export function composeRichAlert(
    base: Omit<SecretaryAlert, 'title' | 'summary'> & {
        context: DossierContext;
        alertReason?: string;
        suggestedAction?: string;
    },
): SecretaryAlert | null {
    if (!hasRichAlertMinimumContext(base.context)) return null;
    const { context, alertReason, suggestedAction, ...rest } = base;
    const reason = alertReason?.trim();
    return {
        ...rest,
        title: formatAlertTitle(context.clientName, context.caseNumber),
        summary: formatAlertSubtitle(context.courtName, context.actionType),
        clientName: context.clientName,
        caseNumber: context.caseNumber,
        courtName: context.courtName,
        actionType: context.actionType,
        alertReason: reason || undefined,
        suggestedAction:
            suggestedAction ??
            suggestedFutureActionForAlert({
                type: rest.type,
                target: rest.target,
                calendarSource: rest.calendarSource,
            }),
    };
}

export function isSchedulableDossierAlert(alert: SecretaryAlert): boolean {
    return (
        (alert.type === 'HEARING' ||
            alert.type === 'EXECUTION' ||
            alert.type === 'DEADLINE' ||
            alert.type === 'URGENT') &&
        Boolean(alert.entityId)
    );
}

import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';

import { daysFromTodayYmd, localTodayYmd } from '@/app/services/alertFutureGate';



/** بادئة حقن مهام الميدان — محليًا لكسر سحب fieldTaskAlerts إلى مسارات خفيفة */

const FIELD_TASK_ALERT_ID_PREFIX = 'field-task:';



function isInjectedFieldTaskAlert(

    alert: Pick<SecretaryAlert, 'id' | 'fieldTaskInjected' | 'calendarSource'>,

): boolean {

    if (alert.fieldTaskInjected) return true;

    const id = alert.id ?? '';

    if (id.startsWith(FIELD_TASK_ALERT_ID_PREFIX)) return true;

    return alert.calendarSource?.module === 'field_day_task';

}



function dueMs(alert: SecretaryAlert): number | null {

    if (!alert.dueAt) return null;

    const t = Date.parse(alert.dueAt);

    return Number.isNaN(t) ? null : t;

}



const HOUR_MS = 60 * 60 * 1000;

/** عاجل: اليوم وغداً */

const URGENT_MAX_HOURS = 48;

/** قادم: ما بعد غد ولمدة 3 أيام (حتى اليوم +4) */

const UPCOMING_MAX_HOURS = 4 * 24;



export type AlertTimeHorizon = 'urgent' | 'near' | 'upcoming';



export type ClassifiedSecretaryAlerts = {

    urgentAlerts: SecretaryAlert[];

    nearAlerts: SecretaryAlert[];

    upcomingAlerts: SecretaryAlert[];

};



export function hoursUntilAlertDue(alert: SecretaryAlert, nowMs: number): number | null {

    const ms = dueMs(alert);

    if (ms === null) return null;

    return (ms - nowMs) / HOUR_MS;

}



export function daysUntilAlertDue(alert: SecretaryAlert, todayYmd: string): number | null {

    const ms = dueMs(alert);

    if (ms === null) return null;

    const ymd = localTodayYmd(new Date(ms));

    return daysFromTodayYmd(ymd, todayYmd);

}



function sortBucket(alerts: SecretaryAlert[]): SecretaryAlert[] {

    return [...alerts].sort((a, b) => {

        const aPin = a.fieldTaskPinned ? 0 : 1;

        const bPin = b.fieldTaskPinned ? 0 : 1;

        if (aPin !== bPin) return aPin - bPin;

        const ta = dueMs(a) ?? Number.MAX_SAFE_INTEGER;

        const tb = dueMs(b) ?? Number.MAX_SAFE_INTEGER;

        if (ta !== tb) return ta - tb;

        return a.priority - b.priority;

    });

}



function classifyFieldTaskHorizon(

    alert: SecretaryAlert,

    todayYmd: string,

): AlertTimeHorizon | null {

    const days = daysUntilAlertDue(alert, todayYmd);

    if (days === null) {

        return alert.fieldTaskPinned ? 'urgent' : null;

    }

    if (days < 0) return 'urgent';

    if (days <= 1) return 'urgent';

    if (days <= 4) return 'upcoming';

    return alert.fieldTaskPinned ? 'upcoming' : null;

}



function classifyByDaysUntil(

    days: number,

): AlertTimeHorizon | null {

    if (days < 0) return null;

    if (days <= 1) return 'urgent';

    if (days <= 4) return 'upcoming';

    return null;

}



/** تصنيف زمني: عاجل (اليوم+غدا) · قادم (3 أيام بعد غد) */

export function classifySecretaryAlertsByHorizon(

    alerts: SecretaryAlert[],

    now: Date = new Date(),

): ClassifiedSecretaryAlerts {

    const nowMs = now.getTime();

    const todayYmd = localTodayYmd(now);

    const urgent: SecretaryAlert[] = [];

    const upcoming: SecretaryAlert[] = [];



    for (const alert of alerts) {

        if (isInjectedFieldTaskAlert(alert)) {

            const bucket = classifyFieldTaskHorizon(alert, todayYmd);

            if (bucket === 'urgent') urgent.push(alert);

            else if (bucket === 'upcoming') upcoming.push(alert);

            continue;

        }



        const days = daysUntilAlertDue(alert, todayYmd);

        if (days !== null) {

            const bucket = classifyByDaysUntil(days);

            if (bucket === 'urgent') urgent.push(alert);

            else if (bucket === 'upcoming') upcoming.push(alert);

            continue;

        }



        const hoursLeft = hoursUntilAlertDue(alert, nowMs);



        if (hoursLeft === null) {
            continue;
        }



        if (hoursLeft <= 0) continue;



        if (hoursLeft <= URGENT_MAX_HOURS) {

            urgent.push(alert);

        } else if (hoursLeft <= UPCOMING_MAX_HOURS) {

            upcoming.push(alert);

        }

    }



    return {

        urgentAlerts: sortBucket(urgent),

        nearAlerts: [],

        upcomingAlerts: sortBucket(upcoming),

    };

}



export function horizonCounts(classified: ClassifiedSecretaryAlerts): Record<AlertTimeHorizon, number> {

    return {

        urgent: classified.urgentAlerts.length,

        near: classified.nearAlerts.length,

        upcoming: classified.upcomingAlerts.length,

    };

}



export function pickDefaultHorizonFilter(

    counts: Record<AlertTimeHorizon, number>,

): AlertTimeHorizon {

    if (counts.urgent > 0) return 'urgent';

    if (counts.upcoming > 0) return 'upcoming';

    return 'urgent';

}



export function alertsForHorizon(

    classified: ClassifiedSecretaryAlerts,

    filter: AlertTimeHorizon,

): SecretaryAlert[] {

    switch (filter) {

        case 'urgent':

            return classified.urgentAlerts;

        case 'near':

            return classified.upcomingAlerts;

        case 'upcoming':

            return classified.upcomingAlerts;

        default:

            return classified.urgentAlerts;

    }

}

