export type HomeHubPanel = 'alerts' | 'pins';

export const HOME_HUB_PANEL_LABELS: Record<HomeHubPanel, string> = {
    alerts: 'التنبيهات',
    pins: 'التثبيت',
};

const HOME_HUB_PANEL_ORDER: HomeHubPanel[] = ['alerts', 'pins'];

/** عدد عناصر المعاينة في تبويبي عاجل/قادم قبل زر «البقية» — ثابت لئلا تتمدد البطاقة */
export const HOME_HUB_ALERTS_TAB_PREVIEW_LIMIT = 2;

export function resolveNextHomeHubPanel(panel: HomeHubPanel): HomeHubPanel {
    const idx = HOME_HUB_PANEL_ORDER.indexOf(panel);
    if (idx < 0) return 'alerts';
    return HOME_HUB_PANEL_ORDER[(idx + 1) % HOME_HUB_PANEL_ORDER.length];
}

export function resolveDefaultHomeHubPanel(
    alertsTabCount: number,
    pinsCount: number,
): HomeHubPanel {
    if (alertsTabCount > 0) return 'alerts';
    if (pinsCount > 0) return 'pins';
    return 'alerts';
}

/** عدد دبابيس الإضبارات للشارة — بلا تجميع عنقودي */
export function countHomeHubDossierPins(pinnedItems: WorkspacePinnedItem[]): number {
    let count = 0;
    for (const item of pinnedItems) {
        if (item.type !== 'hub') count += 1;
    }
    return count;
}

export function formatHomeHubTabBadgeCount(count: number): string {
    if (count <= 0) return '';
    if (count > 9) return '9+';
    return String(count);
}

export function shouldShowHomeHubTabBadge(count: number): boolean {
    return count > 0;
}

export function resolveHomeHubTabAriaLabel(panel: HomeHubPanel, count: number): string {
    const base = HOME_HUB_PANEL_LABELS[panel];
    if (!shouldShowHomeHubTabBadge(count)) return base;
    return `${base}، ${formatHomeHubTabBadgeCount(count)}`;
}

export type HomeHubPanelReconcileInput = {
    userChose: boolean;
    badgeCountsSettled: boolean;
    panelInit: boolean;
    hubPanel: HomeHubPanel;
    alertsTabCount: number;
    pinsCount: number;
};

export type HomeHubPanelReconcileResult = {
    nextPanel: HomeHubPanel;
    markInit: boolean;
};

/** يحل التبويب الافتراضي بعد استقرار العدّ — بلا setState. */
export function reconcileHomeHubPanelAfterCounts(
    input: HomeHubPanelReconcileInput,
): HomeHubPanelReconcileResult | null {
    if (input.userChose || !input.badgeCountsSettled) return null;
    const resolved = resolveDefaultHomeHubPanel(input.alertsTabCount, input.pinsCount);
    if (!input.panelInit) {
        return { nextPanel: resolved, markInit: true };
    }
    if (
        input.hubPanel === 'alerts' &&
        resolved === 'pins' &&
        input.pinsCount > 0 &&
        input.alertsTabCount === 0
    ) {
        return { nextPanel: 'pins', markInit: false };
    }
    return null;
}

/**
 * ميزانيات أداء بطاقة التنبيهات والتثبيت — مرجع E2E.
 */
export const HOME_HUB_PERF_BUDGET = {
    openToInteractiveMs: {
        target: 2_800,
        ciColdMax: 6_500,
        ciCachedMax: 3_500,
    },
} as const;

export type HomeHubPerfBudgetKey = keyof typeof HOME_HUB_PERF_BUDGET.openToInteractiveMs;

import { debug } from '@/app/utils/debug';
import {
    reportHomeHubOpenToSentry,
    type HomeHubSentryReportContext,
} from '@/app/services/alerts/homeHubSentryReporting';

const MARK_PREFIX = 'hami:home-hub:';

type HomeHubPerfPhase = 'open-request' | 'first-paint' | 'interactive';

type HomeHubPerfReportContext = {
    userId?: string;
    alertsTabCount?: number;
    pinsCount?: number;
    hadRadarCache?: boolean;
    hadAlertsCache?: boolean;
};

let homeHubPerfReported = false;

function resetHomeHubPerfReportSession(): void {
    homeHubPerfReported = false;
}

export function markHomeHubPerfPhase(phase: HomeHubPerfPhase): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark(`${MARK_PREFIX}${phase}`);
    } catch {
        /* ignore */
    }
}

export function clearHomeHubPerfMarks(): void {
    if (typeof performance === 'undefined' || typeof performance.clearMarks !== 'function') return;
    try {
        for (const phase of ['open-request', 'first-paint', 'interactive'] as const) {
            performance.clearMarks(`${MARK_PREFIX}${phase}`);
        }
    } catch {
        /* ignore */
    }
    resetHomeHubPerfReportSession();
}

/** ms من open-request → interactive (null إذا لم تُسجَّل المرحلتان) */
export function getHomeHubOpenToInteractiveMs(): number | null {
    if (typeof performance === 'undefined') return null;
    const open = performance.getEntriesByName(`${MARK_PREFIX}open-request`, 'mark')[0];
    const interactive = performance.getEntriesByName(`${MARK_PREFIX}interactive`, 'mark')[0];
    if (!open || !interactive) return null;
    const ms = interactive.startTime - open.startTime;
    if (!Number.isFinite(ms) || ms < 0) return null;
    return Math.round(ms);
}

export function reportHomeHubPerf(context: HomeHubPerfReportContext = {}): void {
    if (homeHubPerfReported) return;
    const ms = getHomeHubOpenToInteractiveMs();
    if (ms == null) return;
    homeHubPerfReported = true;
    if (import.meta.env.DEV) {
        const { userId: _omitUser, ...safeContext } = context;
        debug.log('[HomeHubPerf] open→interactive', ms, 'ms', safeContext);
    }
    reportHomeHubOpenToSentry(ms, context as HomeHubSentryReportContext);
}

/** عتبة قائمة التثبيت الافتراضية */
const HOME_HUB_PINS_VIRTUAL_THRESHOLD = 7;

/** صفوف مرئية قبل التمرير — 1/2/3 تتكيّف، الرابع+ يُمرَّر */
export const HOME_HUB_PINS_VISIBLE_MAX = 3;

export const HOME_HUB_PIN_ROW_ESTIMATE_PX = 52;

export function shouldVirtualizeHomeHubPins(pinCount: number): boolean {
    return pinCount >= HOME_HUB_PINS_VIRTUAL_THRESHOLD;
}

/**
 * تسليح رادار البطاقة — قرار نقي بلا I/O.
 * كاش null = لم يُؤكَّد هذا الجلسة → يجب الاكتشاف (موعد قضائي لا يُؤجَّل).
 * كاش [] = فراغ مؤكَّد هذا الجلسة → لا CalendarDB حتى يتغيّر المصدر.
 * deferForInFlightWarm: تسخين جارٍ — ننتظر نتيجته بدل جلب ثانٍ.
 */

export const HOME_HUB_RADAR_WARM_WAIT_MS = 2_000;

export function shouldArmHomeHubLiveRadar(input: {
    alertsPanelActive: boolean;
    secretaryAlertCount: number;
    radarCache: readonly unknown[] | null;
    deferForInFlightWarm?: boolean;
}): boolean {
    if (!input.alertsPanelActive) return false;
    if (input.secretaryAlertCount > 0) return true;
    if (input.radarCache === null && input.deferForInFlightWarm) return false;
    if (input.radarCache === null) return true;
    return input.radarCache.length > 0;
}

/** قفل أحادي الاتجاه: بعد أول تسليح على تبويب التنبيهات لا يُفصل أثناء الجلسة. */
export function resolveHomeHubLiveRadarEnabled(input: {
    alertsPanelActive: boolean;
    secretaryAlertCount: number;
    radarCache: readonly unknown[] | null;
    latched: boolean;
    deferForInFlightWarm?: boolean;
}): { enabled: boolean; latch: boolean } {
    const want = shouldArmHomeHubLiveRadar({
        alertsPanelActive: input.alertsPanelActive,
        secretaryAlertCount: input.secretaryAlertCount,
        radarCache: input.radarCache,
        deferForInFlightWarm: input.deferForInFlightWarm,
    });
    const latch = input.latched || want;
    return {
        enabled: input.alertsPanelActive && latch,
        latch,
    };
}

/** عدّ تبويب التنبيهات وفلتر رادار «عاجل». */
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import type { CalendarRadarEvent } from '@/app/workspace/types';

function buildCalendarAlertIdSet(secretaryAlerts: SecretaryAlert[]): Set<string> {
    return new Set(
        secretaryAlerts
            .filter((a) => a.id.startsWith('calendar:'))
            .map((a) => a.id.replace('calendar:', '')),
    );
}

/** كيانات مهام ميدانية مُحقونة — لا نُكرّرها في رادار 48 ساعة */
function buildFieldTaskEntityIdSet(secretaryAlerts: SecretaryAlert[]): Set<string> {
    const ids = new Set<string>();
    for (const alert of secretaryAlerts) {
        if (alert.id.startsWith('field-task:') && alert.entityId) {
            ids.add(String(alert.entityId));
        }
        if (alert.fieldTaskInjected && alert.entityId) {
            ids.add(String(alert.entityId));
        }
    }
    return ids;
}

type HomeHubRadarRow = {
    id: string;
    sourceEntityId?: string;
};

/**
 * رادار تبويب «عاجل» — يُبقي مواعيد التقويم (اليوم/غدا) حتى لو لم تُعرض في كاروسيل السكرتير.
 * يُزيل فقط تكرار مهام الميدان المُحقونة.
 */
export function filterHomeHubUrgentRadarEvents<T extends HomeHubRadarRow>(
    radarEvents: T[],
    secretaryAlerts: SecretaryAlert[],
): T[] {
    const fieldEntities = buildFieldTaskEntityIdSet(secretaryAlerts);
    return radarEvents.filter((ev) => {
        const eventId = String(ev.id ?? '').trim();
        if (!eventId) return false;
        if (eventId.includes('appt_judgment_')) return false;
        const entityId = String(ev.sourceEntityId ?? '').trim();
        if (entityId && fieldEntities.has(entityId)) return false;
        return true;
    });
}

/**
 * عدد عناصر تبويب «عاجل» دون تكرار موعد التقويم (سكرتير calendar:* + رادار لنفس ev.id).
 */
export function countUniqueHomeHubUrgentItems(
    secretaryUrgentAlerts: SecretaryAlert[],
    radarEvents: CalendarRadarEvent[],
): number {
    const calendarIds = buildCalendarAlertIdSet(secretaryUrgentAlerts);
    const radarOnlyCount = radarEvents.filter((ev) => {
        const eventId = String(ev.id ?? '').trim();
        return eventId && !calendarIds.has(eventId);
    }).length;
    return secretaryUrgentAlerts.length + radarOnlyCount;
}

export function computeHomeHubAlertsTabCount(
    upcomingCount: number,
    secretaryUrgentAlerts: SecretaryAlert[],
    radarEvents: CalendarRadarEvent[],
): number {
    return countUniqueHomeHubUrgentItems(secretaryUrgentAlerts, radarEvents) + upcomingCount;
}

/**
 * شارة تبويب التنبيهات خارج اللوحة — عاجل السكرتير المؤكد فقط.
 * لا رادار كاش ولا upcoming خام (كانا يُنتجان شارة كاذبة تختفي عند الفتح).
 */
export function computeHomeHubAlertsTabBadgeOffPanel(
    secretaryUrgentAlerts: SecretaryAlert[],
): number {
    if (secretaryUrgentAlerts.length === 0) return 0;
    return countUniqueHomeHubUrgentItems(secretaryUrgentAlerts, []);
}

export function computeHomeHubHorizonTabCounts(
    horizonCounts: Record<'urgent' | 'near' | 'upcoming', number>,
    secretaryUrgentAlerts: SecretaryAlert[],
    radarEvents: CalendarRadarEvent[],
): Record<'urgent' | 'near' | 'upcoming', number> {
    return {
        urgent: countUniqueHomeHubUrgentItems(secretaryUrgentAlerts, radarEvents),
        near: 0,
        upcoming: horizonCounts.upcoming,
    };
}

import { readSecureJsonRawSync, writeSecureJsonValue } from '@/app/services/storage/syncSecureJson';

/** إخفاء مواعيد رادار 48 ساعة من البطاقة العامة فقط — لا يحذف الموعد من التقويم */

export const HOME_HUB_RADAR_DISMISSED_KEY_PREFIX = 'hami:home-hub-radar-dismissed:v1';
export const HOME_HUB_RADAR_DISMISSED_EVENT = 'hami:home-hub-radar-dismissed';

const MAX_DISMISSED = 200;
const RETENTION_MS = 30 * 24 * 60 * 60 * 1000;

type DismissEntry = { id: string; at: number };

function storageKey(lawyerId: string): string {
    return `${HOME_HUB_RADAR_DISMISSED_KEY_PREFIX}:${lawyerId.slice(0, 128)}`;
}

function readEntries(lawyerId: string): DismissEntry[] {
    const safeLawyer = String(lawyerId ?? '').trim();
    if (!safeLawyer) return [];
    try {
        const raw = readSecureJsonRawSync(storageKey(safeLawyer));
        if (!raw) return [];
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return (parsed as DismissEntry[]).filter(
            (e) => e && typeof e.id === 'string' && typeof e.at === 'number',
        );
    } catch {
        return [];
    }
}

function writeEntries(lawyerId: string, entries: DismissEntry[]): void {
    const safeLawyer = String(lawyerId ?? '').trim();
    if (!safeLawyer) return;
    writeSecureJsonValue(storageKey(safeLawyer), entries.slice(-MAX_DISMISSED));
}

export function getDismissedHomeHubRadarIds(lawyerId: string | null | undefined): string[] {
    const safeLawyer = String(lawyerId ?? '').trim();
    if (!safeLawyer) return [];
    const cutoff = Date.now() - RETENTION_MS;
    return readEntries(safeLawyer)
        .filter((e) => e.at >= cutoff)
        .map((e) => e.id);
}

export function dismissHomeHubRadarId(lawyerId: string | null | undefined, eventId: string): void {
    const safeLawyer = String(lawyerId ?? '').trim().slice(0, 128);
    const safeId = String(eventId ?? '').trim().slice(0, 240);
    if (!safeLawyer || !safeId) return;
    const entries = readEntries(safeLawyer).filter((e) => e.id !== safeId);
    entries.push({ id: safeId, at: Date.now() });
    writeEntries(safeLawyer, entries);
    if (typeof window !== 'undefined') {
        window.dispatchEvent(
            new CustomEvent(HOME_HUB_RADAR_DISMISSED_EVENT, { detail: { lawyerId: safeLawyer, id: safeId } }),
        );
    }
}

export function filterVisibleHomeHubRadarEvents<T extends { id: string }>(
    events: T[],
    dismissedIds: Iterable<string>,
): T[] {
    const set = dismissedIds instanceof Set ? dismissedIds : new Set(dismissedIds);
    if (set.size === 0) return events;
    return events.filter((ev) => {
        const id = String(ev.id ?? '').trim();
        return id.length > 0 && !set.has(id);
    });
}

