/**
 * بوابة ثبات سطح الرئيسية بعد الكشف — CLS + إزاحة هندسية.
 * القياس في E2E؛ التقييم هنا حتى يبقى الحدّ قابلاً للاختبار بلا متصفح.
 */

export type HomeSurfaceRectSample = {
    present: boolean;
    x: number;
    y: number;
    w: number;
    h: number;
};

export type HomeSurfaceLayoutShiftSample = {
    value: number;
    startTime: number;
    hadRecentInput: boolean;
    /** إن وُجدت مصادر: هل لمست الشبكة/البطاقة/الهيدر */
    affectsHomeSurface: boolean;
};

export type HomeSurfaceFrameSample = {
    t: number;
    hub: HomeSurfaceRectSample;
    grid: HomeSurfaceRectSample;
    header: HomeSurfaceRectSample;
};

export type HomeSurfaceStabilityProbe = {
    firstHubVisibleAt: number | null;
    layoutShifts: HomeSurfaceLayoutShiftSample[];
    frames: HomeSurfaceFrameSample[];
};

export type HomeSurfaceStabilityMetrics = {
    postRevealCls: number;
    hubShiftPx: number;
    gridShiftPx: number;
    headerShiftPx: number;
    framesCaptured: number;
};

export type HomeSurfaceStabilityVerdict = {
    ok: boolean;
    failures: string[];
    metrics: HomeSurfaceStabilityMetrics;
};

/** Google «جيّد» < 0.1 — بعد الكشف نطلب أضيق لأن الرعشة هنا مرئية */
export const HOME_SURFACE_POST_REVEAL_CLS_MAX = 0.05;
/** إزاحة من أول إطار ظاهر — يطابق visual-stability-audit */
export const HOME_SURFACE_MAX_RECT_SHIFT_PX = 4;

export function scorePostRevealHomeCls(
    shifts: HomeSurfaceLayoutShiftSample[],
    firstHubVisibleAt: number | null,
): number {
    if (firstHubVisibleAt == null) return 0;
    return shifts
        .filter(
            (shift) =>
                !shift.hadRecentInput &&
                shift.affectsHomeSurface &&
                shift.startTime >= firstHubVisibleAt,
        )
        .reduce((sum, shift) => sum + shift.value, 0);
}

export function maxRectShiftFromAnchor(rects: HomeSurfaceRectSample[]): number {
    const anchor = rects.find((rect) => rect.present && rect.w > 0 && rect.h > 0);
    if (!anchor) return 0;
    let max = 0;
    for (const rect of rects) {
        if (!rect.present || rect.w <= 0 || rect.h <= 0) continue;
        max = Math.max(
            max,
            Math.abs(rect.x - anchor.x),
            Math.abs(rect.y - anchor.y),
            Math.abs(rect.w - anchor.w),
            Math.abs(rect.h - anchor.h),
        );
    }
    return max;
}

export function evaluateHomeSurfaceStability(
    probe: HomeSurfaceStabilityProbe,
): HomeSurfaceStabilityVerdict {
    const failures: string[] = [];
    if (probe.firstHubVisibleAt == null) {
        failures.push('hub never became visible');
    }

    const postRevealCls = scorePostRevealHomeCls(probe.layoutShifts, probe.firstHubVisibleAt);
    const hubShiftPx = maxRectShiftFromAnchor(probe.frames.map((frame) => frame.hub));
    const gridShiftPx = maxRectShiftFromAnchor(probe.frames.map((frame) => frame.grid));
    const headerShiftPx = maxRectShiftFromAnchor(probe.frames.map((frame) => frame.header));

    if (probe.firstHubVisibleAt != null && postRevealCls > HOME_SURFACE_POST_REVEAL_CLS_MAX) {
        failures.push(
            `postRevealCls=${postRevealCls.toFixed(4)} > ${HOME_SURFACE_POST_REVEAL_CLS_MAX}`,
        );
    }
    if (hubShiftPx > HOME_SURFACE_MAX_RECT_SHIFT_PX) {
        failures.push(`hubShiftPx=${hubShiftPx.toFixed(2)} > ${HOME_SURFACE_MAX_RECT_SHIFT_PX}`);
    }
    if (gridShiftPx > HOME_SURFACE_MAX_RECT_SHIFT_PX) {
        failures.push(`gridShiftPx=${gridShiftPx.toFixed(2)} > ${HOME_SURFACE_MAX_RECT_SHIFT_PX}`);
    }
    if (headerShiftPx > HOME_SURFACE_MAX_RECT_SHIFT_PX) {
        failures.push(
            `headerShiftPx=${headerShiftPx.toFixed(2)} > ${HOME_SURFACE_MAX_RECT_SHIFT_PX}`,
        );
    }

    return {
        ok: failures.length === 0,
        failures,
        metrics: {
            postRevealCls,
            hubShiftPx,
            gridShiftPx,
            headerShiftPx,
            framesCaptured: probe.frames.length,
        },
    };
}

import { debug } from '@/app/utils/debug';

const MARK_PREFIX = 'hami:lawsuit-archive:';

export type LawsuitArchivePerfPhase =
    | 'open-request'
    | 'keys-warm-start'
    | 'keys-ready'
    | 'hydrate-done'
    | 'interactive';

const PHASES: readonly LawsuitArchivePerfPhase[] = [
    'open-request',
    'keys-warm-start',
    'keys-ready',
    'hydrate-done',
    'interactive',
] as const;

let lawsuitArchivePerfReported = false;

export function markLawsuitArchivePerf(phase: LawsuitArchivePerfPhase): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark(`${MARK_PREFIX}${phase}`);
    } catch {
        /* ignore */
    }
}

export function clearLawsuitArchivePerfMarks(): void {
    if (typeof performance === 'undefined' || typeof performance.clearMarks !== 'function') return;
    try {
        for (const phase of PHASES) {
            performance.clearMarks(`${MARK_PREFIX}${phase}`);
        }
    } catch {
        /* ignore */
    }
    lawsuitArchivePerfReported = false;
}

function markStartTime(phase: LawsuitArchivePerfPhase): number | null {
    if (typeof performance === 'undefined') return null;
    const entry = performance.getEntriesByName(`${MARK_PREFIX}${phase}`, 'mark')[0];
    if (!entry || !Number.isFinite(entry.startTime)) return null;
    return entry.startTime;
}

/** فرق ms بين مرحلتين (null إن نقصت علامة) */
export function getLawsuitArchivePhaseDeltaMs(
    from: LawsuitArchivePerfPhase,
    to: LawsuitArchivePerfPhase,
): number | null {
    const a = markStartTime(from);
    const b = markStartTime(to);
    if (a == null || b == null) return null;
    const ms = b - a;
    if (!Number.isFinite(ms) || ms < 0) return null;
    return Math.round(ms);
}

export type LawsuitArchivePerfSnapshot = {
    openToKeysReadyMs: number | null;
    openToHydrateMs: number | null;
    openToInteractiveMs: number | null;
    keysWarmDurationMs: number | null;
};

export function getLawsuitArchivePerfSnapshot(): LawsuitArchivePerfSnapshot {
    return {
        openToKeysReadyMs: getLawsuitArchivePhaseDeltaMs('open-request', 'keys-ready'),
        openToHydrateMs: getLawsuitArchivePhaseDeltaMs('open-request', 'hydrate-done'),
        openToInteractiveMs: getLawsuitArchivePhaseDeltaMs('open-request', 'interactive'),
        keysWarmDurationMs: getLawsuitArchivePhaseDeltaMs('keys-warm-start', 'keys-ready'),
    };
}

/** يُستدعى مرة لكل جلسة فتح — يسجّل في DEV عبر performance marks */
export function reportLawsuitArchivePerf(): void {
    if (lawsuitArchivePerfReported) return;
    const snap = getLawsuitArchivePerfSnapshot();
    if (snap.openToInteractiveMs == null && snap.openToKeysReadyMs == null) return;
    lawsuitArchivePerfReported = true;
    if (import.meta.env.DEV) {
        debug.log('[LawsuitArchivePerf]', snap);
    }
}

import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';

export const APP_ALERTS_DISMISSED_KEY = 'hami:app-alerts-dismissed:v1';
const LEGACY_DISMISSED_KEY = 'neural-alerts-dismissed';
const MAX_DISMISSED = 300;

type DismissEntry = { id: string; at: number };

function readEntries(): DismissEntry[] {
    try {
        for (const key of [APP_ALERTS_DISMISSED_KEY, LEGACY_DISMISSED_KEY]) {
            const raw = localStorage.getItem(key);
            if (!raw) continue;
            const parsed: unknown = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                if (parsed.length > 0 && typeof parsed[0] === 'string') {
                    return parsed
                        .filter((id): id is string => typeof id === 'string')
                        .map((id) => ({ id, at: Date.now() }));
                }
                if (parsed.length > 0 && parsed[0] && typeof parsed[0] === 'object') {
                    return (parsed as DismissEntry[]).filter(
                        (e) => e && typeof e.id === 'string' && typeof e.at === 'number',
                    );
                }
            }
        }
    } catch {
        /* ignore */
    }
    return [];
}

function writeEntries(entries: DismissEntry[]): void {
    try {
        const capped = entries.slice(-MAX_DISMISSED);
        localStorage.setItem(APP_ALERTS_DISMISSED_KEY, JSON.stringify(capped));
    } catch {
        /* ignore */
    }
}

/** معرّفات التنبيهات المخفاة (مقروءة/مُهمَلة من المستخدم) */
export function getDismissedAlertIds(): string[] {
    const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
    return readEntries()
        .filter((e) => e.at >= cutoff)
        .map((e) => e.id);
}

export function dismissAlertId(id: string): void {
    const safe = String(id ?? '').trim().slice(0, 200);
    if (!safe) return;
    const entries = readEntries().filter((e) => e.id !== safe);
    entries.push({ id: safe, at: Date.now() });
    writeEntries(entries);
    window.dispatchEvent(new CustomEvent('hami:alerts-dismissed'));
}

export function filterVisibleAlerts(alerts: SecretaryAlert[], dismissedIds?: string[]): SecretaryAlert[] {
    const dismissed = dismissedIds ?? getDismissedAlertIds();
    if (dismissed.length === 0) return alerts;
    const set = new Set(dismissed);
    return alerts.filter((a) => !set.has(a.id));
}

import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { PushNotificationService } from '@/app/services/PushNotificationService';
import { savePushSubscription } from '@/app/services/pushSubscriptionStore';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import {
    canSendPushNotifications,
    filterAlertsByNotificationSettings,
} from '@/app/services/settings/settingsRuntime';
import { getLawyerSettingsSnapshot } from '@/app/services/settings/settingsSnapshot';
import { alertNotificationChannel } from '@/app/services/notifications/notificationAlertPolicy';
import { showHamiNotification } from '@/app/services/notifications/HamiNotificationBridge';
import { debug } from '@/app/utils/debug';

const SEEN_KEY = 'hami:alert-push-seen:v1';
const MAX_SEEN = 400;
// مدة احتفاظ الـ seen في localStorage — 7 أيام تمنع إعادة-push للتنبيه نفسه عبر تحديثات الصفحة
const SEEN_TTL_MS = 7 * 24 * 60 * 60 * 1000;

type SeenEntry = { id: string; ts: number };

function loadSeen(): Map<string, number> {
    try {
        // مهاجرة من sessionStorage السابق (إن وُجدت): نقرأ القائمة القديمة ونحوّلها مرة واحدة
        const legacyRaw =
            typeof sessionStorage !== 'undefined' ? sessionStorage.getItem(SEEN_KEY) : null;
        const raw =
            typeof localStorage !== 'undefined' ? localStorage.getItem(SEEN_KEY) : null;
        const now = Date.now();
        const out = new Map<string, number>();
        if (raw) {
            const parsed: unknown = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                for (const item of parsed) {
                    if (item && typeof item === 'object') {
                        const e = item as Partial<SeenEntry>;
                        if (typeof e.id === 'string' && typeof e.ts === 'number') {
                            if (now - e.ts <= SEEN_TTL_MS) out.set(e.id, e.ts);
                        }
                    } else if (typeof item === 'string') {
                        // legacy shape داخل localStorage أيضاً
                        out.set(item, now);
                    }
                }
            }
        }
        if (legacyRaw && typeof localStorage !== 'undefined') {
            try {
                const parsed: unknown = JSON.parse(legacyRaw);
                if (Array.isArray(parsed)) {
                    for (const item of parsed) {
                        if (typeof item === 'string' && !out.has(item)) out.set(item, now);
                    }
                }
                sessionStorage.removeItem(SEEN_KEY);
            } catch { /* ignore */ }
        }
        return out;
    } catch {
        return new Map();
    }
}

function saveSeen(seen: Map<string, number>): void {
    try {
        if (typeof localStorage === 'undefined') return;
        const now = Date.now();
        const arr: SeenEntry[] = Array.from(seen.entries())
            .filter(([, ts]) => now - ts <= SEEN_TTL_MS)
            .slice(-MAX_SEEN)
            .map(([id, ts]) => ({ id, ts }));
        localStorage.setItem(SEEN_KEY, JSON.stringify(arr));
    } catch {
        /* ignore */
    }
}

/** لا نطلب صلاحية المتصفح تلقائياً — التنبيهات داخل التطبيق تكفي حتى يفعّل المستخدم الإشعارات من الإعدادات. */
export async function ensurePushPermissionForCriticalAlerts(_alerts: SecretaryAlert[]): Promise<void> {
    return;
}

/** إشعار محلي للتنبيهات الحرجة الجديدة فقط (بدون تكرار في الجلسة) */
const PUSH_SUB_ATTEMPTED = 'hami:push-sub-attempted';

async function persistPushSubscription(lawyerId: string | null): Promise<void> {
    if (!lawyerId) return;
    if (isCapacitorNativePlatform()) return;
    try {
        if (sessionStorage.getItem(PUSH_SUB_ATTEMPTED) === lawyerId) return;
        const sub = await PushNotificationService.subscribeToPush();
        // سجّل المحاولة حتى عند الفشل — يمنع مئات التحذيرات عند كل refresh للتنبيهات
        sessionStorage.setItem(PUSH_SUB_ATTEMPTED, lawyerId);
        if (sub) {
            await savePushSubscription(lawyerId, sub.toJSON());
        }
    } catch {
        try {
            sessionStorage.setItem(PUSH_SUB_ATTEMPTED, lawyerId);
        } catch {
            /* ignore */
        }
    }
}

export async function syncPushForNewCriticalAlerts(
    alerts: SecretaryAlert[],
    lawyerId?: string | null,
): Promise<void> {
    if (typeof window === 'undefined' || !('Notification' in window)) return;

    const settings = getLawyerSettingsSnapshot();
    if (!canSendPushNotifications(settings)) return;

    const channelFiltered = filterAlertsByNotificationSettings(alerts, settings);
    await ensurePushPermissionForCriticalAlerts(channelFiltered);
    if (PushNotificationService.getPermission() === 'granted' && lawyerId) {
        void persistPushSubscription(lawyerId);
    }
    const nativePush = isCapacitorNativePlatform();
    if (!nativePush && PushNotificationService.getPermission() !== 'granted') return;

    const critical = channelFiltered.filter((a) => a.priority <= 1);
    if (critical.length === 0) return;

    const seen = loadSeen();
    let changed = false;
    const now = Date.now();

    for (const a of critical) {
        if (seen.has(a.id)) continue;
        const channel = alertNotificationChannel(a) ?? 'secretary';
        try {
            await showHamiNotification(
                channel,
                {
                    title: a.title,
                    body: a.summary,
                    tag: a.id,
                    data: { alertId: a.id, target: a.target, entityId: a.entityId },
                    requireInteraction: a.type === 'HEARING' || a.type === 'URGENT',
                },
                a.priority <= 1,
            );
            seen.set(a.id, now);
            changed = true;
        } catch (err) {
            debug.warn('[appAlertPushSync] push failed:', err);
        }
    }

    if (changed) saveSeen(seen);
}

export function markAlertSeenForPush(alertId: string): void {
    const seen = loadSeen();
    seen.set(alertId, Date.now());
    saveSeen(seen);
}

/**
 * Audit Log Publisher — إشعارات واردة فقط (منتدى، نظام، inbox).
 * سجل النشاطات (civil/criminal/execution/...) مُلغى — واجهات no-op للتوافق.
 */

import { useNotificationStore } from '@/app/stores/notificationStore';
import type {
    NotificationCategory,
    NotificationDirection,
    NotificationModel,
    NotificationType,
} from '@/app/infrastructure/NotificationRepository';
import { isActivityAuditNotificationType } from '@/app/infrastructure/NotificationRepository';
import { sanitizeNotificationDisplayMessage } from '@/app/services/notificationMessageFormat';
import { createDisabledAuditDomain } from '@/app/services/notifications/auditLogDisabledDomain';

const DEDUPE_WINDOW_MS = 30_000;
const dedupeCache = new Map<string, number>();

function shouldDedupe(dedupeKey: string | undefined, now: number): boolean {
    if (!dedupeKey) return false;
    const lastTs = dedupeCache.get(dedupeKey);
    if (lastTs && now - lastTs < DEDUPE_WINDOW_MS) return true;
    dedupeCache.set(dedupeKey, now);
    if (dedupeCache.size > 200) {
        const cutoff = now - DEDUPE_WINDOW_MS * 4;
        for (const [k, ts] of dedupeCache) {
            if (ts < cutoff) dedupeCache.delete(k);
        }
    }
    return false;
}

export function resetAuditLogDedupe(): void {
    dedupeCache.clear();
}

interface PublishParams {
    type: NotificationType;
    category: NotificationCategory;
    title: string;
    message: string;
    direction?: NotificationDirection;
    actionPayload?: Record<string, unknown>;
    dedupeKey?: string;
}

function defaultDirectionForCategory(c: NotificationCategory): NotificationDirection {
    switch (c) {
        case 'document':
            return 'outgoing';
        case 'forum':
        case 'system':
        case 'ai':
            return 'incoming';
        default:
            return 'outgoing';
    }
}

function makeId(prefix: string): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return `${prefix}_${crypto.randomUUID()}`;
    }
    return `${prefix}_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

function publish(params: PublishParams): NotificationModel | null {
    if (isActivityAuditNotificationType(params.type)) return null;

    const direction = params.direction ?? defaultDirectionForCategory(params.category);
    if (direction === 'outgoing') return null;
    if (
        params.category === 'civil' ||
        params.category === 'criminal' ||
        params.category === 'execution' ||
        params.category === 'task'
    ) {
        return null;
    }

    const now = Date.now();
    if (shouldDedupe(params.dedupeKey, now)) return null;

    const message = sanitizeNotificationDisplayMessage({
        message: params.message,
        title: params.title,
        category: params.category,
        type: params.type,
    });
    if (!message.trim()) return null;

    const notif: NotificationModel = {
        id: makeId(params.category),
        title: params.title,
        message,
        type: params.type,
        category: params.category,
        direction,
        isRead: false,
        actionPayload: {
            ...(params.actionPayload ?? {}),
            ...(params.dedupeKey ? { dedupeKey: params.dedupeKey } : {}),
        },
        createdAt: new Date(now).toISOString(),
    };

    try {
        useNotificationStore.getState().addNotification(notif);
    } catch {
        /* non-fatal */
    }
    return notif;
}

