import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import { ACCOUNT_FROZEN_CODE, ACCOUNT_LOCKED_CODE } from '@/app/api/security/accountRestrictionCopy';

export type AccountNetworkGate = {
    frozen: boolean;
    forumBanned: boolean;
    freezeUntil: string | null;
    code: string | null;
    message: string | null;
};

const OPEN_GATE: AccountNetworkGate = {
    frozen: false,
    forumBanned: false,
    freezeUntil: null,
    code: null,
    message: null,
};

const CHANGE_EVENT = 'hami:account-network-gate-changed';

let cached: { userId: string; at: number; gate: AccountNetworkGate } | null = null;
const GATE_TTL_MS = 8_000;

function emitAccountNetworkGateChange(): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new Event(CHANGE_EVENT));
}

export function peekAccountNetworkGate(userId?: string | null): AccountNetworkGate | null {
    const id = userId?.trim();
    if (!cached) return null;
    if (id && cached.userId !== id) return null;
    return cached.gate;
}

export function subscribeAccountNetworkGate(onChange: () => void): () => void {
    if (typeof window === 'undefined') return () => undefined;
    window.addEventListener(CHANGE_EVENT, onChange);
    return () => window.removeEventListener(CHANGE_EVENT, onChange);
}

export function invalidateAccountNetworkGateCache(): void {
    cached = null;
}

export async function fetchAccountNetworkGate(userId: string): Promise<AccountNetworkGate> {
    const id = userId.trim();
    if (!id) return OPEN_GATE;
    const now = Date.now();
    if (cached && cached.userId === id && now - cached.at < GATE_TTL_MS) {
        return cached.gate;
    }
    const data = await SecureAPIClient.fetchSecure<{
        ok?: boolean;
        frozen?: boolean;
        forumBanned?: boolean;
        freezeUntil?: string | null;
        code?: string | null;
        message?: string | null;
        loginAllowed?: boolean;
    }>('/api/auth/account-gate', { method: 'GET' });
    const gate: AccountNetworkGate = {
        frozen: data?.frozen === true || data?.code === ACCOUNT_LOCKED_CODE || data?.loginAllowed === false,
        forumBanned: data?.forumBanned === true,
        freezeUntil: typeof data?.freezeUntil === 'string' ? data.freezeUntil : null,
        code: typeof data?.code === 'string' ? data.code : data?.frozen ? ACCOUNT_FROZEN_CODE : null,
        message: typeof data?.message === 'string' ? data.message : null,
    };
    cached = { userId: id, at: now, gate };
    emitAccountNetworkGateChange();
    return gate;
}

const PREFERRED_GATE_MODE_KEY = 'hami:auth:preferred-gate-mode';

export type AuthGatePreferredMode = 'choice' | 'login' | 'register';

function readPreferredAuthGateMode(): AuthGatePreferredMode | null {
    if (typeof sessionStorage === 'undefined') return null;
    try {
        const raw = sessionStorage.getItem(PREFERRED_GATE_MODE_KEY);
        if (raw === 'login' || raw === 'register' || raw === 'choice') return raw;
    } catch {
        /* ignore */
    }
    return null;
}

export function setPreferredAuthGateMode(mode: AuthGatePreferredMode): void {
    if (typeof sessionStorage === 'undefined') return;
    try {
        sessionStorage.setItem(PREFERRED_GATE_MODE_KEY, mode);
    } catch {
        /* ignore */
    }
}

/** يقرأ دون مسح — إعادة تركيب البوابة لا تُرجع المستخدم لشاشة الاختيار. */
export function peekPreferredAuthGateMode(): AuthGatePreferredMode | null {
    return readPreferredAuthGateMode();
}

export function consumePreferredAuthGateMode(): AuthGatePreferredMode | null {
    const mode = readPreferredAuthGateMode();
    if (!mode || typeof sessionStorage === 'undefined') return mode;
    try {
        sessionStorage.removeItem(PREFERRED_GATE_MODE_KEY);
    } catch {
        /* ignore */
    }
    return mode;
}

import { parseJsonResponse } from '@/app/utils/bffJsonResponse';
import { getOrCreateDeviceId } from '@/app/security/deviceId';
import { getWifeNativeFetch } from '@/app/security/wifeNativeFetch';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';
import { AUTH_OTP_CODE_LEN } from '@/app/api/auth/otp/authOtpTypes';

/** طول الرمز المُصدَر — الخادم يرفض أي طول مختلف، فالواجهة تمنعه قبل الشبكة. */
export const AUTH_OTP_CODE_LENGTH = AUTH_OTP_CODE_LEN;

export type AuthOtpPurpose = 'password_reset' | 'email_confirm';
export type AuthOtpChannel = 'email' | 'whatsapp';
export type AuthOtpDelivery = 'otp' | 'link';

export type AuthOtpRequestResult = {
    delivery: AuthOtpDelivery;
    message: string;
    resendAfterSec: number;
    phoneTail: string | null;
};

export type AuthOtpChannelsStatus = {
    email: boolean;
    whatsapp: boolean;
};

export type AuthOtpAccountPreview = {
    /** لا يصل من المعاينة — يُملأ من نتيجة إرسال فعلي فقط. */
    phoneTail: string | null;
    hasWhatsAppNumber: boolean;
    emailReady: boolean;
    whatsappSendReady: boolean;
    adminWhatsappUrl: string | null;
};

function nativeFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    return getWifeNativeFetch()(input, init);
}

function deviceHeaders(): Record<string, string> {
    const deviceId = typeof window === 'undefined' ? '' : getOrCreateDeviceId();
    return deviceId ? { 'x-wife-device-id': deviceId } : {};
}

function recoveryRedirect(): string | undefined {
    if (typeof window === 'undefined') return undefined;
    return isCapacitorNativePlatform()
        ? 'iq.hami.legal:///?hami_auth=recovery'
        : `${window.location.origin}/?hami_auth=recovery`;
}

function readPhoneTail(value: unknown): string | null {
    if (typeof value !== 'string') return null;
    const tail = value.replace(/\D/g, '');
    return tail.length === 2 ? tail : null;
}

export async function previewAuthOtpAccount(input: {
    email: string;
    purpose: AuthOtpPurpose;
}): Promise<AuthOtpAccountPreview> {
    const response = await nativeFetch('/api/auth/otp/preview', {
        method: 'POST',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            ...deviceHeaders(),
        },
        body: JSON.stringify({
            email: input.email.trim().toLowerCase(),
            purpose: input.purpose,
        }),
    });
    const payload = await parseJsonResponse<{
        ok?: boolean;
        hasWhatsAppNumber?: boolean;
        emailReady?: boolean;
        whatsappSendReady?: boolean;
        adminWhatsappUrl?: unknown;
        error?: string;
    }>(response);
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر التحقق من البريد');
    }
    const adminUrl =
        typeof payload.adminWhatsappUrl === 'string' && payload.adminWhatsappUrl.startsWith('https://')
            ? payload.adminWhatsappUrl
            : null;
    return {
        phoneTail: null,
        hasWhatsAppNumber: payload.hasWhatsAppNumber === true,
        emailReady: payload.emailReady === true,
        whatsappSendReady: payload.whatsappSendReady === true,
        adminWhatsappUrl: adminUrl,
    };
}

export async function requestAuthOtp(input: {
    email: string;
    channel: AuthOtpChannel;
    purpose: AuthOtpPurpose;
}): Promise<AuthOtpRequestResult> {
    const response = await nativeFetch('/api/auth/otp/request', {
        method: 'POST',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            ...deviceHeaders(),
        },
        body: JSON.stringify({
            email: input.email.trim().toLowerCase(),
            channel: input.channel,
            purpose: input.purpose,
            redirectTo: recoveryRedirect(),
        }),
    });
    const payload = await parseJsonResponse<{
        ok?: boolean;
        delivery?: AuthOtpDelivery;
        message?: string;
        resendAfterSec?: number;
        phoneTail?: unknown;
        error?: string;
    }>(response);
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر إرسال رمز التحقق');
    }
    return {
        delivery: payload.delivery === 'link' ? 'link' : 'otp',
        message: payload.message ?? 'أُرسل رمز التحقق.',
        resendAfterSec:
            typeof payload.resendAfterSec === 'number' && payload.resendAfterSec > 0
                ? payload.resendAfterSec
                : 60,
        phoneTail: readPhoneTail(payload.phoneTail),
    };
}

export async function completeAuthOtp(input: {
    email: string;
    code: string;
    purpose: AuthOtpPurpose;
    newPassword?: string;
}): Promise<string> {
    const response = await nativeFetch('/api/auth/otp/complete', {
        method: 'POST',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            'Content-Type': 'application/json',
            ...deviceHeaders(),
        },
        body: JSON.stringify({
            email: input.email.trim().toLowerCase(),
            code: input.code.replace(/\D/g, ''),
            purpose: input.purpose,
            newPassword: input.newPassword,
        }),
    });
    const payload = await parseJsonResponse<{ ok?: boolean; message?: string; error?: string }>(
        response,
    );
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر إكمال التحقق');
    }
    return payload.message ?? 'تم بنجاح';
}

export async function fetchAuthOtpChannels(): Promise<AuthOtpChannelsStatus> {
    const response = await nativeFetch('/api/auth/otp/channels', {
        method: 'GET',
        credentials: 'include',
        headers: {
            Accept: 'application/json',
            ...deviceHeaders(),
        },
    });
    const payload = await parseJsonResponse<{
        ok?: boolean;
        email?: boolean;
        whatsapp?: boolean;
        error?: string;
    }>(response);
    if (!response.ok) {
        throw new Error(payload.error ?? 'تعذّر معرفة قنوات التحقق');
    }
    return {
