const PENDING_EMAIL_KEY = 'hami:auth:email-confirm-pending';

function canUseSessionStorage(): boolean {
    return typeof sessionStorage !== 'undefined';
}

export function markEmailConfirmationPending(email: string): void {
    const trimmed = email.trim().toLowerCase();
    if (!trimmed.includes('@') || !canUseSessionStorage()) return;
    try {
        sessionStorage.setItem(PENDING_EMAIL_KEY, trimmed);
    } catch {
        /* ignore */
    }
}

export function clearEmailConfirmationPending(): void {
    if (!canUseSessionStorage()) return;
    try {
        sessionStorage.removeItem(PENDING_EMAIL_KEY);
    } catch {
        /* ignore */
    }
}

export function readEmailConfirmationPending(): string | null {
    if (!canUseSessionStorage()) return null;
    try {
        const value = sessionStorage.getItem(PENDING_EMAIL_KEY)?.trim().toLowerCase() ?? '';
        return value.includes('@') ? value : null;
    } catch {
        return null;
    }
}

export function isEmailConfirmationErrorMessage(message: string | null | undefined): boolean {
    const raw = String(message ?? '');
    return /email not confirmed/i.test(raw) || /أكّد بريدك|تأكيد البريد/u.test(raw);
}

import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';

/** خروج من التطبيق بعد رفض الشروط — أصلي أولاً، وإلا يبقى الحظر على الشاشة */
export async function exitApplicationAfterTermsDecline(): Promise<void> {
    if (!isCapacitorNativePlatform()) return;
    try {
        const { App } = await import('@capacitor/app');
        await App.exitApp();
    } catch {
        try {
            const { App } = await import('@capacitor/app');
            await App.minimizeApp();
        } catch {
            /* يبقى المستخدم على شاشة الرفض */
        }
    }
}

/**
 * رسائل مصادقة عربية — خاصة تكرار التسجيل.
 */

const DUPLICATE_PATTERNS = [
    /already\s+registered/i,
    /already\s+been\s+registered/i,
    /user\s+already\s+exists/i,
    /email.*exists/i,
    /duplicate/i,
    /identity.*exists/i,
    /المستخدم موجود/i,
    /مسج.?ل مسبقا/i,
];

type AuthErrorContext = 'login' | 'register' | 'generic';

export function isDuplicateSignupErrorMessage(message: string | null | undefined): boolean {
    const m = String(message ?? '').trim();
    if (!m) return false;
    return DUPLICATE_PATTERNS.some((re) => re.test(m));
}

export function humanizeAuthError(
    error: unknown,
    fallback = 'فشلت العملية',
    context: AuthErrorContext = 'generic',
): string {
    const raw =
        error instanceof Error
            ? error.message
            : typeof error === 'string'
              ? error
              : fallback;
    if (isDuplicateSignupErrorMessage(raw)) {
        return 'هذا البريد مسجّل مسبقاً — سجّل الدخول بدل إنشاء حساب جديد، أو استخدم «نسيت كلمة المرور».';
    }
    if (/invalid login credentials/i.test(raw) || /invalid.?credentials/i.test(raw)) {
        if (context === 'register') {
            return 'تم إنشاء الحساب لكن تعذّر فتح الجلسة تلقائياً — سجّل الدخول يدوياً، أو أكّد البريد إن طُلب ذلك.';
        }
        return 'البريد أو كلمة المرور غير صحيحة';
    }
    if (/TERMS_REQUIRED/i.test(raw) || /يلزم الموافقة على الشروط/.test(raw)) {
        return 'يلزم الموافقة على الشروط والأحكام الحالية قبل المتابعة';
    }
    if (/email not confirmed/i.test(raw)) {
        if (context === 'register') {
            return 'أُنشئ الحساب. تأكيد البريد آخر خطوة لإثبات الصندوق — اعتماد صفة المحامي حصراً من الإدارة.';
        }
        return 'يرجى تأكيد البريد الإلكتروني من الرسالة المرسلة إليك ثم أعد المحاولة';
    }
    if (/account unavailable/i.test(raw) || /ACCOUNT_LOCKED/.test(raw)) {
        return 'قُفل الدخول إلى هذا الحساب من مقر القيادة. الدعاوى والمعاملات لم تُحذف.';
    }
    if (/auth not configured/i.test(raw) || /auth service unavailable/i.test(raw)) {
        return 'خدمة الدخول غير متاحة حالياً — أعد المحاولة بعد قليل';
    }
    if (
        /failed to fetch/i.test(raw) ||
        /networkerror/i.test(raw) ||
        /load failed/i.test(raw) ||
        /network request failed/i.test(raw) ||
        /fetch failed/i.test(raw)
    ) {
        return 'تعذّر الاتصال بالخادم — تأكد أن npm run dev يعمل ثم أعد المحاولة';
    }
    if (/rate.?limit|too many|over_email_send_rate_limit|حد رسائل Auth/i.test(raw)) {
        return context === 'register'
            ? 'تعذّر إكمال التسجيل لأن حد رسائل Auth ممتلئ. انتظر نحو ساعة ثم أعد المحاولة مرة واحدة.'
            : 'محاولات كثيرة — انتظر قليلاً ثم أعد المحاولة';
    }
    if (/signup failed/i.test(raw)) {
        return context === 'register' ? fallback : 'تعذّر إنشاء الحساب';
    }
    if (/ID_FRONT_REQUIRED/i.test(raw) || /هوية النقابة/.test(raw)) {
        return raw.trim() || 'صورتا وجه وظهر هوية النقابة مطلوبتان';
    }
    if ((context === 'login' || context === 'register') && !/[\u0600-\u06FF]/.test(raw)) {
        return fallback;
    }
    return raw.trim() || fallback;
}

export const DUPLICATE_SIGNUP_CODE = 'EMAIL_ALREADY_REGISTERED';

/**
 * صور هوية النقابة — تحقق من data URL قبل التخزين/الإرسال.
 * القصّ متعمّد حتى لا يُسقط جسم التسجيل (مئات الكيلوبايت) طلب الإنشاء.
 */

export const IDENTITY_IMAGE_DATA_URL_RE =
    /^data:image\/(jpeg|jpg|png|webp);base64,[A-Za-z0-9+/=\s]{64,}$/i;

/** معاينة صغيرة داخل POST /signup — فوق هذا الحد يفشل الإنشاء غالباً */
export const SIGNUP_IDENTITY_PREVIEW_MAX_CHARS = 12_000;

/** معاينة مقر القيادة في KV */
export const KV_IDENTITY_PREVIEW_MAX_CHARS = 80_000;

export function isIdentityImageDataUrl(value: string | null | undefined): boolean {
    const raw = String(value ?? '').trim();
    if (!raw || raw === '[omitted]') return false;
    return IDENTITY_IMAGE_DATA_URL_RE.test(raw);
}

export function clipIdentityImageDataUrl(
    value: string | null | undefined,
    maxChars: number,
): string | null {
    const raw = String(value ?? '').trim();
    if (!isIdentityImageDataUrl(raw)) return null;
    if (raw.length <= maxChars) return raw;
    const clipped = raw.slice(0, maxChars);
    return isIdentityImageDataUrl(clipped) ? clipped : null;
}

export function compactIdentityPreviewForSignup(value: string | null | undefined): string | null {
    return clipIdentityImageDataUrl(value, SIGNUP_IDENTITY_PREVIEW_MAX_CHARS);
}

export function compactIdentityPreviewForKv(value: string | null | undefined): string | null {
    return clipIdentityImageDataUrl(value, KV_IDENTITY_PREVIEW_MAX_CHARS);
}

export function assertLawyerIdentityImagesReady(
    idFrontDataUrl: string | null | undefined,
    idBackDataUrl: string | null | undefined,
): string | null {
    if (!isIdentityImageDataUrl(idFrontDataUrl)) {
        return 'صورة وجه هوية النقابة مطلوبة — اختر من المعرض أو الكاميرا';
    }
    if (!isIdentityImageDataUrl(idBackDataUrl)) {
        return 'صورة ظهر هوية النقابة مطلوبة — اختر من المعرض أو الكاميرا';
    }
    return null;
}

/**
 * تحويل ملف الهوية إلى JPEG مضغوط يقبله الخادم (لا HEIC/نصوص أصلية للمتصفح).
 */

import { isIdentityImageDataUrl } from '@/app/services/auth/identityImageDataUrl';

const MAX_EDGE = 1280;
const JPEG_QUALITY = 0.72;
const MIN_OUTPUT_CHARS = 120;
const MAX_SOURCE_BYTES = 4_500_000;

function readFileAsDataUrl(file: Blob): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result ?? ''));
        reader.onerror = () => reject(new Error('تعذّر قراءة الملف'));
        reader.readAsDataURL(file);
    });
}

function loadHtmlImage(src: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
        const image = new Image();
        image.onload = () => resolve(image);
        image.onerror = () => reject(new Error('تعذّر فتح الصورة — استخدم JPG أو PNG'));
        image.src = src;
    });
}

function fitEdge(width: number, height: number, maxEdge: number): { width: number; height: number } {
    const w = Math.max(1, width);
    const h = Math.max(1, height);
    const edge = Math.max(w, h);
    if (edge <= maxEdge) return { width: w, height: h };
    const scale = maxEdge / edge;
    return {
        width: Math.max(1, Math.round(w * scale)),
        height: Math.max(1, Math.round(h * scale)),
    };
}

async function canvasJpegDataUrl(
    draw: (ctx: CanvasRenderingContext2D, width: number, height: number) => void,
    width: number,
    height: number,
): Promise<string> {
    const size = fitEdge(width, height, MAX_EDGE);
    const canvas = document.createElement('canvas');
    canvas.width = size.width;
    canvas.height = size.height;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('تعذّر تجهيز الصورة');
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, size.width, size.height);
    draw(ctx, size.width, size.height);
    const dataUrl = canvas.toDataURL('image/jpeg', JPEG_QUALITY);
    if (!isIdentityImageDataUrl(dataUrl) || dataUrl.length < MIN_OUTPUT_CHARS) {
        throw new Error('تعذّر اعتماد الصورة — أعد الالتقاط بصيغة JPG أو PNG');
    }
    return dataUrl;
}

async function blobToJpegDataUrl(blob: Blob): Promise<string> {
    if (typeof createImageBitmap === 'function') {
        try {
            const bitmap = await createImageBitmap(blob, { imageOrientation: 'from-image' });
            try {
                return await canvasJpegDataUrl(
                    (ctx, w, h) => {
                        ctx.drawImage(bitmap, 0, 0, w, h);
                    },
                    bitmap.width,
                    bitmap.height,
                );
            } finally {
                bitmap.close();
            }
        } catch {
            /* HTMLImage احتياط */
        }
    }
    const dataUrl = await readFileAsDataUrl(blob);
    const image = await loadHtmlImage(dataUrl);
    return canvasJpegDataUrl(
        (ctx, w, h) => {
            ctx.drawImage(image, 0, 0, w, h);
        },
        image.naturalWidth || image.width,
        image.naturalHeight || image.height,
    );
}

export async function fileToIdentityJpegDataUrl(file: File): Promise<string> {
    if (!file || file.size < 32) {
        throw new Error('الملف فارغ — أرفق صورة حقيقية لوجه أو ظهر الهوية');
    }
    if (file.size > MAX_SOURCE_BYTES) {
        throw new Error('حجم الصورة كبير — اختر صورة أوضح وأصغر من 4.5MB');
    }
    const type = String(file.type || '').toLowerCase();
    if (type && !type.startsWith('image/')) {
        throw new Error('يُقبل ملف صورة فقط');
    }
    return blobToJpegDataUrl(file);
}

