import {
    applyLawyerVerificationStatusFromServer,
    markLawyerVerificationUiReady,
} from '@/app/services/auth/lawyerVerificationStore';
import { compactIdentityPreviewForKv } from '@/app/services/auth/identityImageDataUrl';
import { getLiveAuthUserId } from '@/app/utils/liveAuthUserId';
import { readPersistedSupabaseAuth } from '@/app/utils/authStorage';

export const LAWYER_VERIFICATION_HQ_RECEIVED_AR =
    'وصل طلبك إلى الإدارة. يمكنك العمل الآن دون انتظار؛ المنتدى والمزامنة بعد الاعتماد.';

export const LAWYER_VERIFICATION_HQ_UNREACHABLE_AR =
    'حُفظ الطلب على جهازك وتعذّر إرساله لمقر القيادة. أعد المحاولة عند استقرار الشبكة — الإدارة لم تستلم الطلب بعد.';

export type SubmitLawyerVerificationInput = {
    email: string;
    fullName: string;
    familyName: string;
    phone: string;
    governorate: string;
    lawyerBarRoom: string;
    faceAssistOptedIn: boolean;
    idFrontDataUrl: string | null;
    idBackDataUrl: string | null;
    faceSelfieDataUrl: string | null;
};

/** يرفع ملخص طلب التوثيق للخادم (KV) بعد إنشاء الجلسة */
export async function submitLawyerVerificationToServer(
    input: SubmitLawyerVerificationInput,
): Promise<void> {
    await SecureAPIClient.fetchSecure('/api/auth/lawyer-verification', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
        body: JSON.stringify({
            email: input.email,
            fullName: input.fullName,
            familyName: input.familyName,
            phone: input.phone,
            governorate: input.governorate,
            lawyerBarRoom: input.lawyerBarRoom,
            faceAssistOptedIn: input.faceAssistOptedIn,
            hasIdFront: Boolean(input.idFrontDataUrl),
            hasIdBack: Boolean(input.idBackDataUrl),
            hasFaceSelfie: Boolean(input.faceSelfieDataUrl),
            idFrontPreview: compactIdentityPreviewForKv(input.idFrontDataUrl),
            idBackPreview: compactIdentityPreviewForKv(input.idBackDataUrl),
            faceSelfiePreview: compactIdentityPreviewForKv(input.faceSelfieDataUrl),
        }),
    });
}

let verificationSyncInflight: Promise<void> | null = null;
let verificationSyncUserId: string | null = null;

/** يزامن حالة التوثيق من KV إلى التخزين المحلي — مرة لكل مستخدم لكل جلسة */
export async function syncLawyerVerificationFromServer(userId?: string | null): Promise<void> {
    const persisted = readPersistedSupabaseAuth();
    const uid = (userId ?? getLiveAuthUserId() ?? persisted.user?.id ?? '').trim();
    if (!uid) return;
    if (verificationSyncInflight && verificationSyncUserId === uid) {
        await verificationSyncInflight;
        return;
    }
    verificationSyncUserId = uid;
    verificationSyncInflight = (async () => {
        try {
            const data = await SecureAPIClient.fetchSecure<{
                ok?: boolean;
                record?: { status?: string; rejectionReason?: string } | null;
            }>('/api/auth/lawyer-verification?scope=self', {
                method: 'GET',
                headers: { Accept: 'application/json' },
            });
            const status = data?.record?.status;
            if (status === 'active' || status === 'pending' || status === 'rejected') {
                applyLawyerVerificationStatusFromServer(
                    uid,
                    status,
                    typeof data?.record?.rejectionReason === 'string'
                        ? data.record.rejectionReason
                        : undefined,
                );
            }
        } catch {
            /* صامت — الخادم قد يكون بلا KV */
        } finally {
            markLawyerVerificationUiReady(uid);
        }
    })().finally(() => {
        verificationSyncInflight = null;
    });
    await verificationSyncInflight;
}

export async function fetchLawyerPersonnelDossier(
    userId: string,
    signal?: AbortSignal,
): Promise<Record<string, unknown> | null> {
    const id = userId.trim();
    if (!id) return null;
    const data = await SecureAPIClient.fetchSecure<{
        ok?: boolean;
        record?: Record<string, unknown> | null;
    }>(`/api/auth/lawyer-verification?scope=dossier&userId=${encodeURIComponent(id)}`, {
        method: 'GET',
        headers: { Accept: 'application/json' },
        cache: 'no-store',
        signal,
    });
    if (!data?.ok) {
        throw new Error('تعذّر جلب ملف المحامي');
    }
    return data.record ?? null;
}

export async function fetchLawyerVerifications(
    scope: 'pending' | 'all' = 'pending',
    signal?: AbortSignal,
): Promise<Array<Record<string, unknown>> & { capped: boolean }> {
    const data = await SecureAPIClient.fetchSecure<{
        ok?: boolean;
        records?: Array<Record<string, unknown>>;
        capped?: boolean;
    }>(`/api/auth/lawyer-verification?scope=${scope}`, {
        method: 'GET',
        headers: { Accept: 'application/json' },
        cache: 'no-store',
        signal,
    });
    if (!data?.ok) {
        throw new Error('تعذّر جلب طلبات التوثيق');
    }
    const records = Array.isArray(data.records) ? data.records : [];
    return Object.assign(records, { capped: Boolean(data.capped) });
}

export async function fetchPendingLawyerVerifications(): Promise<
    Array<Record<string, unknown>>
> {
    return fetchLawyerVerifications('pending');
}

function patchErrorMessage(error: unknown): string {
    if (error instanceof SecureFetchError) {
        if (error.status === 429) return 'تجاوزت حد عمليات المقر — حاول لاحقاً';
        try {
            const parsed = JSON.parse(error.bodyText) as { error?: unknown };
            const msg = String(parsed.error ?? '').trim();
            if (msg) return msg;
        } catch {
            /* نص غير JSON */
        }
    }
    return 'فشل تحديث حالة التوثيق';
}

export async function patchLawyerVerificationStatus(params: {
    userId: string;
    status: 'active' | 'rejected' | 'pending';
    rejectionReason?: string;
}): Promise<{ ok: true } | { ok: false; error: string }> {
    try {
        const data = await hqMutatingFetch<{ ok?: boolean; error?: string }>(
            '/api/auth/lawyer-verification',
            {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json', Accept: 'application/json' },
                body: JSON.stringify(params),
            },
        );
        if (!data?.ok) {
            return { ok: false, error: String(data?.error ?? '').trim() || 'فشل تحديث حالة التوثيق' };
        }
        return { ok: true };
    } catch (error) {
        return { ok: false, error: patchErrorMessage(error) };
    }
}

import {
    clearSecureJsonValue,
    readSecureJsonRaw,
    readSecureJsonRawSync,
    writeSecureJsonValue,
} from '@/app/services/storage/syncSecureJson';

/**
 * سجل تحقق محلي لطلب تسجيل المحامي (KYC خفيف).
 * الصور تُحفظ كـ data URL مضغوطة اختيارياً — الحجم محدود عمداً.
 */

export type LawyerVerificationStatus = 'guest' | 'pending' | 'active' | 'rejected';

export type LawyerRegistrationPayload = {
    email: string;
    fullName: string;
    familyName: string;
    phone: string;
    governorate: string;
    lawyerBarRoom: string;
    idFrontDataUrl: string | null;
    idBackDataUrl: string | null;
    faceSelfieDataUrl: string | null;
    faceAssistOptedIn: boolean;
};

export type LawyerVerificationRecord = {
    userId: string;
    status: Exclude<LawyerVerificationStatus, 'guest'>;
    submittedAt: string;
    updatedAt: string;
    rejectionReason?: string;
    payload: Omit<LawyerRegistrationPayload, never> & {
        /** لا نخزّن كلمة المرور */
        password?: undefined;
    };
};

export const LAWYER_VERIFICATION_STORE_KEY = 'hami:auth:lawyer-verification:v1';
const CHANGE_EVENT = 'hami:lawyer-verification-changed';
const MAX_IMAGE_CHARS = 420_000;

type StoreShape = Record<string, LawyerVerificationRecord>;

let verificationUiReadyUserId: string | null = null;
let verificationHydrateStarted = false;

function emitLawyerVerificationStoreChange(): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new Event(CHANGE_EVENT));
}

function scheduleLawyerVerificationHydrate(): void {
    if (verificationHydrateStarted || typeof window === 'undefined') return;
    verificationHydrateStarted = true;
    void readSecureJsonRaw(LAWYER_VERIFICATION_STORE_KEY).then((raw) => {
        if (!raw?.trim()) return;
        emitLawyerVerificationStoreChange();
    });
}

export function markLawyerVerificationUiReady(userId: string): void {
    const id = userId.trim();
    if (!id) return;
    verificationUiReadyUserId = id;
    emitLawyerVerificationStoreChange();
}

export function isLawyerVerificationUiReady(userId: string | null | undefined): boolean {
    const id = userId?.trim();
    return Boolean(id) && verificationUiReadyUserId === id;
}

export function resetLawyerVerificationUiReadyForTests(): void {
    verificationUiReadyUserId = null;
}

export function resetLawyerVerificationStoreForTests(): void {
    verificationHydrateStarted = false;
    verificationUiReadyUserId = null;
    clearSecureJsonValue(LAWYER_VERIFICATION_STORE_KEY);
}

export function subscribeLawyerVerificationStore(onChange: () => void): () => void {
    if (typeof window === 'undefined') return () => undefined;
    scheduleLawyerVerificationHydrate();
    const onStorage = (event: StorageEvent) => {
        if (event.key === LAWYER_VERIFICATION_STORE_KEY || event.key === null) onChange();
    };
    window.addEventListener(CHANGE_EVENT, onChange);
    window.addEventListener('storage', onStorage);
    return () => {
        window.removeEventListener(CHANGE_EVENT, onChange);
        window.removeEventListener('storage', onStorage);
    };
}

function parseStore(raw: string | null): StoreShape {
    if (!raw?.trim()) return {};
    try {
        const parsed = JSON.parse(raw) as StoreShape;
        return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
    } catch {
        return {};
    }
}

function readStore(): StoreShape {
    if (typeof window === 'undefined') return {};
    const fromSync = parseStore(readSecureJsonRawSync(LAWYER_VERIFICATION_STORE_KEY));
    if (Object.keys(fromSync).length === 0) scheduleLawyerVerificationHydrate();
    return fromSync;
}

function slimStoreWithoutImages(next: StoreShape): StoreShape {
    const slim: StoreShape = {};
    for (const [id, rec] of Object.entries(next)) {
        slim[id] = {
            ...rec,
            payload: {
                ...rec.payload,
                idFrontDataUrl: rec.payload.idFrontDataUrl ? '[omitted]' : null,
                idBackDataUrl: rec.payload.idBackDataUrl ? '[omitted]' : null,
                faceSelfieDataUrl: rec.payload.faceSelfieDataUrl ? '[omitted]' : null,
            },
        };
    }
    return slim;
}

function writeStore(next: StoreShape): void {
    if (typeof window === 'undefined') return;
    try {
        if (Object.keys(next).length === 0) {
            clearSecureJsonValue(LAWYER_VERIFICATION_STORE_KEY);
        } else {
            writeSecureJsonValue(LAWYER_VERIFICATION_STORE_KEY, next);
        }
    } catch {
        try {
            writeSecureJsonValue(LAWYER_VERIFICATION_STORE_KEY, slimStoreWithoutImages(next));
        } catch {
            /* ignore */
        }
    }
    emitLawyerVerificationStoreChange();
}

export function truncateImageDataUrl(dataUrl: string | null): string | null {
    if (!dataUrl) return null;
    if (dataUrl.length <= MAX_IMAGE_CHARS) return dataUrl;
    return dataUrl.slice(0, MAX_IMAGE_CHARS);
}

export function readLawyerVerificationRecord(
    userId: string | null | undefined,
): LawyerVerificationRecord | null {
    const id = userId?.trim();
    if (!id) return null;
    return readStore()[id] ?? null;
}

export function writeLawyerVerificationPending(
    userId: string,
    payload: LawyerRegistrationPayload,
): LawyerVerificationRecord {
    const now = new Date().toISOString();
    const existing = readLawyerVerificationRecord(userId);
    const record: LawyerVerificationRecord = {
        userId,
        status: 'pending',
        submittedAt: existing?.submittedAt ?? now,
        updatedAt: now,
        payload: {
            email: payload.email.trim(),
            fullName: payload.fullName.trim(),
            familyName: payload.familyName.trim(),
            phone: payload.phone.trim(),
            governorate: payload.governorate,
            lawyerBarRoom: payload.lawyerBarRoom,
            idFrontDataUrl: truncateImageDataUrl(payload.idFrontDataUrl),
            idBackDataUrl: truncateImageDataUrl(payload.idBackDataUrl),
            faceSelfieDataUrl: truncateImageDataUrl(payload.faceSelfieDataUrl),
            faceAssistOptedIn: payload.faceAssistOptedIn,
        },
    };
    const store = readStore();
    store[userId] = record;
    writeStore(store);
    return record;
}

export function setLawyerVerificationStatus(
    userId: string,
    status: 'pending' | 'active' | 'rejected',
    rejectionReason?: string,
): LawyerVerificationRecord | null {
    const store = readStore();
    const existing = store[userId];
    if (!existing) return null;
    const next: LawyerVerificationRecord = {
        ...existing,
        status,
        updatedAt: new Date().toISOString(),
        rejectionReason: status === 'rejected' ? rejectionReason ?? existing.rejectionReason : undefined,
    };
    store[userId] = next;
    writeStore(store);
    return next;
}

/** مزامنة حالة التوثيق من الخادم — ينشئ سجلاً محلياً خفيفاً إن لم يوجد */
export function applyLawyerVerificationStatusFromServer(
    userId: string,
    status: 'pending' | 'active' | 'rejected',
    rejectionReason?: string,
): LawyerVerificationRecord {
    const existing = readLawyerVerificationRecord(userId);
    if (existing) {
        const updated = setLawyerVerificationStatus(userId, status, rejectionReason);
        return updated ?? existing;
    }
    const now = new Date().toISOString();
    const record: LawyerVerificationRecord = {
        userId,
        status,
        submittedAt: now,
        updatedAt: now,
        rejectionReason: status === 'rejected' ? rejectionReason : undefined,
        payload: {
            email: '',
            fullName: '',
            familyName: '',
            phone: '',
            governorate: '',
            lawyerBarRoom: '',
            idFrontDataUrl: null,
            idBackDataUrl: null,
            faceSelfieDataUrl: null,
            faceAssistOptedIn: false,
        },
    };
    const store = readStore();
    store[userId] = record;
    writeStore(store);
    return record;
}

export function clearLawyerVerificationRecord(userId: string): void {
    const store = readStore();
    if (!store[userId]) return;
    delete store[userId];
    writeStore(store);
}

export function listLawyerVerificationRecords(): LawyerVerificationRecord[] {
    return Object.values(readStore());
}

﻿/**
 * قبول الشروط والأحكام — إلزامي قبل التسجيل/الدخول/الضيف أو فتح اللوحة بجلسة. الترتيب: اختيار المسار أولاً ثم الوثيقة كاملة.
 * النسخة تُبطِل القبول القديم عند تحديث الوثيقة القانونية.
 */

import { isShellAuthBypassed } from '@/app/services/auth/shellAuth';
import { LEGAL_TERMS_ACCEPTANCE_VERSION } from '@/app/services/auth/legalTermsVersion';

export { LEGAL_TERMS_ACCEPTANCE_VERSION } from '@/app/services/auth/legalTermsVersion';

const ACCEPT_KEY = 'hami:legal:terms-accepted:v1';
const ACCEPT_COOKIE = 'hami_legal_terms_accepted';

export type LegalTermsAcceptanceRecord = {
    version: string;
    acceptedAt: string;
};

function canUseStorage(): boolean {
    return typeof window !== 'undefined' && typeof window.localStorage !== 'undefined';
}

function readCookieVersion(): string | null {
    if (typeof document === 'undefined') return null;
    try {
        const match = document.cookie
            .split(';')
            .map((p) => p.trim())
            .find((p) => p.startsWith(`${ACCEPT_COOKIE}=`));
        if (!match) return null;
        const value = decodeURIComponent(match.slice(ACCEPT_COOKIE.length + 1)).trim();
        return value || null;
    } catch {
        return null;
    }
}

function writeCookieVersion(version: string | null): void {
    if (typeof document === 'undefined') return;
    try {
        document.cookie = version
            ? `${ACCEPT_COOKIE}=${encodeURIComponent(version)}; path=/; max-age=31536000; SameSite=Lax`
            : `${ACCEPT_COOKIE}=; path=/; max-age=0; SameSite=Lax`;
    } catch {
        /* ignore */
    }
}

function parseRecord(raw: string | null): LegalTermsAcceptanceRecord | null {
    if (!raw) return null;
    try {
        const data = JSON.parse(raw) as LegalTermsAcceptanceRecord;
        if (typeof data?.version !== 'string' || typeof data?.acceptedAt !== 'string') return null;
        return data;
    } catch {
        return null;
    }
}

export function readLegalTermsAcceptance(): LegalTermsAcceptanceRecord | null {
    if (canUseStorage()) {
        try {
            const fromStore = parseRecord(window.localStorage.getItem(ACCEPT_KEY));
            if (fromStore) return fromStore;
        } catch {
            /* ignore */
        }
    }
    const cookieVersion = readCookieVersion();
    if (!cookieVersion) return null;
    return { version: cookieVersion, acceptedAt: '' };
}

/** E2E / shell bypass — لا تُحجب الشروط في مسار القياس */
export function isLegalTermsGateRequired(): boolean {
    if (isShellAuthBypassed()) return false;
    return !hasAcceptedCurrentLegalTerms();
}

export function hasAcceptedCurrentLegalTerms(): boolean {
    const record = readLegalTermsAcceptance();
    if (!record) return false;
    if (record.version !== LEGAL_TERMS_ACCEPTANCE_VERSION) return false;
    return true;
}

function persistLegalTermsRecord(record: LegalTermsAcceptanceRecord): void {
    if (canUseStorage()) {
        try {
            window.localStorage.setItem(ACCEPT_KEY, JSON.stringify(record));
        } catch {
            /* ignore quota */
        }
    }
    writeCookieVersion(record.version);
}

export function markLegalTermsAccepted(now = new Date()): LegalTermsAcceptanceRecord {
    const record: LegalTermsAcceptanceRecord = {
        version: LEGAL_TERMS_ACCEPTANCE_VERSION,
        acceptedAt: now.toISOString(),
    };
    persistLegalTermsRecord(record);
    if (typeof window !== 'undefined') {
        window.dispatchEvent(new Event('hami:legal-terms-accepted'));
    }
    return record;
}

/** لقطة قبل localStorage.clear — موافقة الجهاز ليست بيانات حساب */
export function captureLegalTermsAcceptance(): LegalTermsAcceptanceRecord | null {
    const record = readLegalTermsAcceptance();
    if (!record || record.version !== LEGAL_TERMS_ACCEPTANCE_VERSION) return null;
    return {
        version: record.version,
        acceptedAt: record.acceptedAt || new Date().toISOString(),
    };
}

export function restoreLegalTermsAcceptance(record: LegalTermsAcceptanceRecord | null): void {
    if (!record || record.version !== LEGAL_TERMS_ACCEPTANCE_VERSION) return;
    persistLegalTermsRecord({
        version: record.version,
        acceptedAt: record.acceptedAt || new Date().toISOString(),
    });
}

export function clearLegalTermsAcceptance(): void {
    if (canUseStorage()) {
        try {
            window.localStorage.removeItem(ACCEPT_KEY);
        } catch {
            /* ignore */
        }
    }
    writeCookieVersion(null);
}

/** يُستدعى من مسارات الدخول لمنع أي ثغرة برمجية */
export function assertLegalTermsAcceptedOrThrow(): void {
    if (isShellAuthBypassed()) return;
    if (hasAcceptedCurrentLegalTerms()) return;
    throw new Error('يلزم الموافقة على الشروط والأحكام وسياسة الاستخدام والخصوصية قبل المتابعة');
}

