/**
 * جلسة عمل التطوير المحلي — محامٍ معتمد محلياً (نفس عقد «دخول كمطور»).
 * ليست ضيفاً: الضيف يغلق المنتدى ويُظهر نقصاً في الصلاحيات.
 */
export function activateLocalDevWorkLawyerSession(): { user: User; session: Session } {
    clearExplicitLocalGuest();
    markExplicitDevUnlock();
    markLegalTermsAccepted();
    applyLawyerVerificationStatusFromServer(DEV_UNLOCK_LAWYER_ID, 'active');
    return createDevUnlockLawyerSession();
}

export function tryActivateLocalDevWorkLawyerSession(): { user: User; session: Session } | null {
    if (!isLocalDevWorkLawyerEnabled()) return null;
    return activateLocalDevWorkLawyerSession();
}

/**
 * دخول صريح «بدون تسجيل» — جلسة محلية فقط، بلا تجاوز بيئة الإنتاج.
 * يختلف عن VITE_SHELL_AUTH_OPEN (تجاوز تطوير/E2E).
 *
 * يُحفظ في localStorage + cookie احتياطي حتى لا تُفقد الجلسة عند إعادة فتح WebView.
 */

const LOCAL_GUEST_KEY = 'hami:auth:explicit-local-guest:v1';
const LOCAL_GUEST_COOKIE = 'hami_explicit_local_guest';

function canUseStorage(): boolean {
    return typeof window !== 'undefined' && typeof window.localStorage !== 'undefined';
}

function readGuestCookie(): boolean {
    if (typeof document === 'undefined') return false;
    try {
        return document.cookie.split(';').some((part) => part.trim() === `${LOCAL_GUEST_COOKIE}=1`);
    } catch {
        return false;
    }
}

function writeGuestCookie(on: boolean): void {
    if (typeof document === 'undefined') return;
    try {
        document.cookie = on
            ? `${LOCAL_GUEST_COOKIE}=1; path=/; max-age=31536000; SameSite=Lax`
            : `${LOCAL_GUEST_COOKIE}=; path=/; max-age=0; SameSite=Lax`;
    } catch {
        /* ignore */
    }
}

export function isExplicitLocalGuest(): boolean {
    if (canUseStorage()) {
        try {
            if (window.localStorage.getItem(LOCAL_GUEST_KEY) === '1') return true;
        } catch {
            /* quota / private mode */
        }
    }
    if (readGuestCookie()) {
        /* أعِد زرع localStorage إن بقيت الكوكي وحدها */
        markExplicitLocalGuest();
        return true;
    }
    return false;
}

export function markExplicitLocalGuest(): void {
    if (canUseStorage()) {
        try {
            window.localStorage.setItem(LOCAL_GUEST_KEY, '1');
        } catch {
            /* ignore quota */
        }
    }
    writeGuestCookie(true);
}

export function clearExplicitLocalGuest(): void {
    if (canUseStorage()) {
        try {
            window.localStorage.removeItem(LOCAL_GUEST_KEY);
        } catch {
            /* ignore */
        }
    }
    writeGuestCookie(false);
}

/**
 * توكن التوقيع عندما getSession() فارغ أو لم يُحمَّل بعد.
 * لا يخلط HMAC العميل مع توقيع BFF — يوفّر المادة فقط.
 */
import {
    readDevMockAccessToken,
    readPersistedSupabaseAuth,
} from '@/app/utils/authStorage';
import {
    createDevUnlockLawyerSession,
    isExplicitDevUnlock,
} from '@/app/services/auth/devUnlockSession';
import { isExplicitLocalGuest } from '@/app/services/auth/localGuestSession';
import { getDevMockLawyerSession } from '@/app/services/auth/devMockLawyerAuth';
import { isShellAuthBypassed } from '@/app/services/auth/shellAuth';

function trimToken(value: string | null | undefined): string | null {
    const token = value?.trim() ?? '';
    return token || null;
}

/** JWT مخزَّن أو توكن تطوير مكتوب بعد الإقلاع — بلا انتظار عميل Supabase. */
export function readStoredAccessToken(): string | null {
    const persisted = trimToken(readPersistedSupabaseAuth().session?.access_token);
    if (persisted) return persisted;
    return trimToken(readDevMockAccessToken());
}

/**
 * جلسة الواجهة المحلية (شِل مفتوح / ضيف صريح / دخول مطور).
 * الإنتاج يبقي الرايات مغلقة؛ الخادم يرفض `dev-access-token-*` هناك.
 */
export function readDevShellAccessToken(): string | null {
    if (isExplicitDevUnlock()) {
        return trimToken(createDevUnlockLawyerSession().session.access_token);
    }
    if (isShellAuthBypassed() || isExplicitLocalGuest()) {
        return trimToken(getDevMockLawyerSession().session.access_token);
    }
    return null;
}

export function readClientAccessTokenFallback(): string | null {
    return readStoredAccessToken() ?? readDevShellAccessToken();
}

/**
 * بوابة استعادة كلمة المرور — علامة جلسة + اكتشاف رابط البريد.
 * لا تخزّن أسراراً؛ فقط نية واجهة بعد `PASSWORD_RECOVERY` أو `?hami_auth=recovery`.
 */

const PENDING_KEY = 'hami:auth:password-recovery-pending';
const LISTENERS = new Set<() => void>();

function canUseSessionStorage(): boolean {
    return typeof sessionStorage !== 'undefined';
}

function emit(): void {
    LISTENERS.forEach((listener) => {
        try {
            listener();
        } catch {
            /* ignore */
        }
    });
}

export function subscribePasswordRecovery(listener: () => void): () => void {
    LISTENERS.add(listener);
    return () => LISTENERS.delete(listener);
}

export function markPasswordRecoveryPending(): void {
    if (canUseSessionStorage()) {
        try {
            sessionStorage.setItem(PENDING_KEY, '1');
        } catch {
            /* ignore */
        }
    }
    emit();
}

export function clearPasswordRecoveryPending(): void {
    if (canUseSessionStorage()) {
        try {
            sessionStorage.removeItem(PENDING_KEY);
        } catch {
            /* ignore */
        }
    }
    emit();
}

export function isPasswordRecoveryPending(): boolean {
    if (canUseSessionStorage()) {
        try {
            if (sessionStorage.getItem(PENDING_KEY) === '1') return true;
        } catch {
            /* ignore */
        }
    }
    return isPasswordRecoveryReturnUrl();
}

/** رابط العودة من رسالة الاستعادة (query أو hash من GoTrue). */
export function isPasswordRecoveryReturnUrl(
    search = typeof window !== 'undefined' ? window.location.search : '',
    hash = typeof window !== 'undefined' ? window.location.hash : '',
): boolean {
    try {
        const params = new URLSearchParams(search.startsWith('?') ? search.slice(1) : search);
        if (params.get('hami_auth') === 'recovery') return true;
        if ((params.get('type') ?? '').toLowerCase() === 'recovery') return true;
    } catch {
        /* ignore */
    }

    const rawHash = hash.startsWith('#') ? hash.slice(1) : hash;
    if (!rawHash) return false;
    try {
        const hashParams = new URLSearchParams(rawHash);
        if ((hashParams.get('type') ?? '').toLowerCase() === 'recovery') return true;
        // بعض القوالب تضع type في query داخل hash segment
        if (rawHash.includes('type=recovery')) return true;
    } catch {
        /* ignore */
    }
    return false;
}

/** هل العنوان يبدو كعودة OAuth/PKCE أو رابط تطبيق أصلي؟ */
export function applyAuthDeepLink(rawUrl: string): boolean {
    const raw = rawUrl.trim();
    if (!raw) return false;
    let search = '';
    let hash = '';
    try {
        const normalized = raw.replace(/^iq\.hami\.legal:\/\//i, 'https://hami.legal/');
        const u = new URL(normalized);
        search = u.search;
        hash = u.hash;
    } catch {
        const q = raw.indexOf('?');
        const h = raw.indexOf('#');
        if (q >= 0) search = raw.slice(q);
        if (h >= 0) hash = raw.slice(h);
    }
    if (isPasswordRecoveryReturnUrl(search, hash) || isAuthCallbackReturnUrl(search)) {
        markPasswordRecoveryPending();
        return true;
    }
    return false;
}
export function isAuthCallbackReturnUrl(
    search = typeof window !== 'undefined' ? window.location.search : '',
): boolean {
    if (isPasswordRecoveryReturnUrl(search)) return true;
    try {
        const params = new URLSearchParams(search.startsWith('?') ? search.slice(1) : search);
        return Boolean(params.get('code'));
    } catch {
        return false;
    }
}

/** ينظّف علامات الاستعادة من العنوان بعد التقاط الجلسة (لا يمس مسارات أخرى). */
export function scrubPasswordRecoveryUrlMarkers(): void {
    if (typeof window === 'undefined' || typeof history === 'undefined') return;
    try {
        const url = new URL(window.location.href);
        let changed = false;
        if (url.searchParams.get('hami_auth') === 'recovery') {
            url.searchParams.delete('hami_auth');
            changed = true;
        }
        if (url.hash && /type=recovery/i.test(url.hash)) {
            url.hash = '';
            changed = true;
        }
        if (changed) {
            const next = `${url.pathname}${url.search}${url.hash}`;
            window.history.replaceState(window.history.state, '', next || '/');
        }
    } catch {
        /* ignore */
    }
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import { isPublicVerifiedBadgeSubject } from '@/app/services/auth/publicVerifiedBadgeStore';

const MAX_IDS = 40;

export async function fetchPublicVerifiedBadges(userIds: string[]): Promise<Record<string, boolean>> {
    const seen = new Set<string>();
    const ids: string[] = [];
    for (const raw of userIds) {
        const id = String(raw ?? '').trim();
        if (!id || seen.has(id) || !isPublicVerifiedBadgeSubject(id)) continue;
        seen.add(id);
        ids.push(id);
        if (ids.length >= MAX_IDS) break;
    }
    if (ids.length === 0) return {};
    const data = await SecureAPIClient.fetchSecure<{
        ok?: boolean;
        badges?: Record<string, unknown>;
        shown?: unknown;
        userId?: unknown;
    }>(`/api/auth/public-verified-badge?ids=${encodeURIComponent(ids.join(','))}`, {
        method: 'GET',
        headers: { Accept: 'application/json' },
    });
    const out: Record<string, boolean> = {};
    for (const id of ids) out[id] = false;
    const badges = data?.badges;
    if (badges && typeof badges === 'object') {
        for (const id of ids) {
            out[id] = badges[id] === true;
        }
    } else if (ids.length === 1 && data?.shown === true) {
        out[ids[0]!] = true;
    }
    return out;
}

const UUID_RE =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const cache = new Map<string, boolean>();
const listeners = new Set<() => void>();
const queued = new Set<string>();
let flushTimer: ReturnType<typeof setTimeout> | null = null;
let flushInflight: Promise<void> | null = null;

function emit(): void {
    for (const listener of listeners) listener();
}

export function isPublicVerifiedBadgeSubject(userId: string): boolean {
    return UUID_RE.test(userId.trim());
}

export function peekPublicVerifiedBadge(userId?: string | null): boolean {
    const id = String(userId ?? '').trim();
    if (!id) return false;
    return cache.get(id) === true;
}

export function writePublicVerifiedBadge(userId: string, shown: boolean): void {
    const id = String(userId ?? '').trim();
    if (!id) return;
    const next = shown === true;
    if (cache.get(id) === next) return;
    cache.set(id, next);
    emit();
}

export function subscribePublicVerifiedBadge(listener: () => void): () => void {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}

export function resetPublicVerifiedBadgeStoreForTests(): void {
    cache.clear();
    queued.clear();
    if (flushTimer) {
        clearTimeout(flushTimer);
        flushTimer = null;
    }
    flushInflight = null;
}

function scheduleFlush(): void {
    if (flushTimer) return;
    flushTimer = setTimeout(() => {
        flushTimer = null;
        void flushQueuedBadges();
    }, 16);
}

export function requestPublicVerifiedBadge(userId?: string | null): void {
    const id = String(userId ?? '').trim();
    if (!id || cache.has(id) || !isPublicVerifiedBadgeSubject(id)) return;
    queued.add(id);
    scheduleFlush();
}

async function flushQueuedBadges(): Promise<void> {
    if (flushInflight) {
        await flushInflight;
        if (queued.size > 0) scheduleFlush();
        return;
    }
    const ids = [...queued];
    queued.clear();
    if (ids.length === 0) return;
    flushInflight = (async () => {
        try {
            const { fetchPublicVerifiedBadges } = await import(
                '@/app/services/auth/publicVerifiedBadgeRemote'
            );
            const badges = await fetchPublicVerifiedBadges(ids);
            let changed = false;
            for (const id of ids) {
                const shown = badges[id] === true;
                if (cache.get(id) !== shown) {
                    cache.set(id, shown);
                    changed = true;
                }
            }
            if (changed) emit();
        } catch {
            /* تبقى القيمة السابقة أو مخفية */
        } finally {
            flushInflight = null;
        }
    })();
    await flushInflight;
}

