describe('calendarEventReminder', () => {
    beforeEach(() => {
        resetCalendarReminderFiredKeysForTests();
        clearCalendarReminderFiredForTests();
    });

    it('يحسب وقت التذكير قبل الموعد', () => {
        const fireAt = computeCalendarReminderFireAt('2026-08-07', '10:00', 10);
        expect(fireAt?.getHours()).toBe(9);
        expect(fireAt?.getMinutes()).toBe(50);
    });

    it('يعيد null بدون وقت أو تذكير', () => {
        expect(computeCalendarReminderFireAt('2026-08-07', '', 10)).toBeNull();
        expect(computeCalendarReminderFireAt('2026-08-07', '10:00', null)).toBeNull();
    });

    it('يُطلق التذكير مرة واحدة ضمن النافذة', () => {
        const fired: string[] = [];
        const now = new Date('2026-08-07T09:50:30');
        scanAndFireCalendarReminders(
            [baseEvent({ reminderMinutesBefore: 10 })],
            now,
            (event) => fired.push(event.id),
        );
        expect(fired).toEqual(['evt-1']);
        scanAndFireCalendarReminders(
            [baseEvent({ reminderMinutesBefore: 10 })],
            now,
            (event) => fired.push(event.id),
        );
        expect(fired).toEqual(['evt-1']);
    });

    it('يلتقط التذكير المتأخر ما دام الموعد لم يبدأ', () => {
        const fired: string[] = [];
        const now = new Date('2026-08-07T09:56:00');
        scanAndFireCalendarReminders(
            [baseEvent({ reminderMinutesBefore: 10 })],
            now,
            (event) => fired.push(event.id),
        );
        expect(fired).toEqual(['evt-1']);
    });

    it('لا يطلق بعد بداية الموعد', () => {
        const fired: string[] = [];
        scanAndFireCalendarReminders(
            [baseEvent({ reminderMinutesBefore: 10 })],
            new Date('2026-08-07T10:01:00'),
            (event) => fired.push(event.id),
        );
        expect(fired).toEqual([]);
    });

    it('يفهم الوقت المخزَّن بالثواني', () => {
        const fireAt = computeCalendarReminderFireAt('2026-08-07', '10:00:00', 10);
        expect(fireAt?.getHours()).toBe(9);
        expect(fireAt?.getMinutes()).toBe(50);
    });

    it('يُنسّق تسمية التذكير', () => {
        expect(formatCalendarReminderLabel(10)).toBe('قبل 10 د');
        expect(formatCalendarReminderLabel(60)).toBe('قبل ساعة');
        expect(formatCalendarReminderSnoozeLabel(5)).toBe('5 دقائق');
        expect(formatCalendarReminderSnoozeLabel(15)).toBe('15 دقيقة');
        expect(formatCalendarReminderSnoozeLabel(30)).toBe('30 دقيقة');
    });
});

import { describe, expect, it, beforeEach, vi } from 'vitest';
import {
    dedupeCalendarGetEvents,
    getCachedCalendarEvents,
    invalidateCalendarEventsCache,
    resetCalendarEventsCacheForTests,
    setCachedCalendarEvents,
    subscribeCalendarEventsCache,
} from '@/app/services/calendar/calendarEventsCache';
import type { CalendarEvent } from '@/app/services/lawyer-cloud';

const USER = 'lawyer-cache-1';

const sampleEvent = (id: string): CalendarEvent => ({
    id,
    userId: USER,
    title: 'موعد',
    date: '2026-06-01',
    type: 'custom',
    createdAt: '2026-01-01T00:00:00.000Z',
    updatedAt: '2026-01-01T00:00:00.000Z',
});

describe('calendarEventsCache', () => {
    beforeEach(() => {
        resetCalendarEventsCacheForTests();
    });

    it('يُرجع cache من الذاكرة دون إعادة fetch', async () => {
        setCachedCalendarEvents(USER, [sampleEvent('a')]);
        const fetcher = vi.fn(async () => [sampleEvent('b')]);

        const first = await dedupeCalendarGetEvents(USER, fetcher);
        const second = await dedupeCalendarGetEvents(USER, fetcher);

        expect(first[0]?.id).toBe('a');
        expect(second[0]?.id).toBe('a');
        expect(fetcher).not.toHaveBeenCalled();
    });

    it('forceRefresh يُبطل cache ويعيد fetch', async () => {
        setCachedCalendarEvents(USER, [sampleEvent('a')]);
        const fetcher = vi.fn(async () => [sampleEvent('b')]);

        const result = await dedupeCalendarGetEvents(USER, fetcher, { forceRefresh: true });

        expect(result[0]?.id).toBe('b');
        expect(getCachedCalendarEvents(USER)?.[0]?.id).toBe('b');
    });

    it('يُجمّع طلبات getEvents المتزامنة', async () => {
        let resolve!: (v: CalendarEvent[]) => void;
        const fetcher = vi.fn(
            () =>
                new Promise<CalendarEvent[]>((r) => {
                    resolve = r;
                }),
        );

        const p1 = dedupeCalendarGetEvents(USER, fetcher);
        const p2 = dedupeCalendarGetEvents(USER, fetcher);
        resolve([sampleEvent('x')]);

        const [a, b] = await Promise.all([p1, p2]);
        expect(a).toEqual(b);
        expect(fetcher).toHaveBeenCalledTimes(1);
    });

    it('invalidateCalendarEventsCache يمسح الذاكرة', () => {
        setCachedCalendarEvents(USER, [sampleEvent('a')]);
        invalidateCalendarEventsCache(USER);
        expect(getCachedCalendarEvents(USER)).toBeNull();
    });

    it('subscribeCalendarEventsCache يُخطر عند الكتابة', () => {
        const listener = vi.fn();
        const unsub = subscribeCalendarEventsCache(listener);
        setCachedCalendarEvents(USER, [sampleEvent('a')]);
        expect(listener).toHaveBeenCalledTimes(1);
        unsub();
        setCachedCalendarEvents(USER, [sampleEvent('b')]);
        expect(listener).toHaveBeenCalledTimes(1);
    });
});

