import type { CalendarEvent } from '@/app/services/cloud/lawyerCalendarTypes';

/**
 * صف مخزّن صالح للعرض/الفهرسة — بلا تاريخ نصّي ينهار `date.startsWith` في الرادار.
 */
export function newCalendarEventId(): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return crypto.randomUUID();
    }
    return `cal_${Date.now()}_${Math.random().toString(36).slice(2, 11)}`;
}

export function isUsableCalendarEventRecord(raw: unknown): raw is CalendarEvent {
    if (!raw || typeof raw !== 'object') return false;
    const e = raw as Partial<CalendarEvent>;
    return (
        typeof e.id === 'string' &&
        e.id.trim().length > 0 &&
        typeof e.userId === 'string' &&
        e.userId.trim().length > 0 &&
        typeof e.title === 'string' &&
        typeof e.date === 'string' &&
        e.date.trim().length > 0
    );
}

import type { CalendarEvent } from '@/app/services/cloud/lawyerCalendarTypes';
import {
    isCalendarReminderFired,
    markCalendarReminderFired,
} from '@/app/services/calendar/calendarReminderFiredStore';

export const CALENDAR_REMINDER_OPTIONS_MINUTES = [5, 10, 15, 30, 60] as const;

export type CalendarReminderMinutes = (typeof CALENDAR_REMINDER_OPTIONS_MINUTES)[number];

const firedReminderKeys = new Set<string>();

/** HH:mm أو HH:mm:ss — بدون لاحقة :00 التي تفسد الوقت المخزَّن بالثواني */
function parseCalendarDateTime(date: string, time: string | undefined): Date | null {
    const ymd = date?.trim().slice(0, 10);
    const match = time?.trim().match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
    if (!ymd || !match) return null;
    const parsed = new Date(`${ymd}T${match[1].padStart(2, '0')}:${match[2]}:00`);
    return Number.isNaN(parsed.getTime()) ? null : parsed;
}

export function formatCalendarReminderLabel(minutes: number): string {
    if (minutes >= 60 && minutes % 60 === 0) {
        const hours = minutes / 60;
        return hours === 1 ? 'قبل ساعة' : `قبل ${hours} ساعات`;
    }
    return `قبل ${minutes} د`;
}

export function formatCalendarReminderChip(minutes: number): string {
    if (minutes >= 60 && minutes % 60 === 0) {
        return minutes === 60 ? '١س' : `${minutes / 60}س`;
    }
    return `${minutes}د`;
}

export function formatCalendarReminderSnoozeLabel(minutes: number): string {
    if (minutes === 1) return 'دقيقة واحدة';
    if (minutes === 2) return 'دقيقتان';
    if (minutes >= 3 && minutes <= 10) return `${minutes} دقائق`;
    return `${minutes} دقيقة`;
}

export function buildCalendarReminderKey(
    eventId: string,
    date: string,
    time: string,
    minutesBefore: number,
): string {
    return `${eventId}|${date}|${time}|${minutesBefore}`;
}

/** وقت إطلاق التذكير — null إذا لا وقت أو لا تذكير */
export function computeCalendarReminderFireAt(
    date: string,
    time: string | undefined,
    minutesBefore: number | null | undefined,
): Date | null {
    const lead = minutesBefore ?? 0;
    if (lead <= 0) return null;
    const start = parseCalendarDateTime(date, time);
    if (!start) return null;
    start.setMinutes(start.getMinutes() - lead);
    return start;
}

export function isCalendarReminderKeyFired(key: string): boolean {
    return firedReminderKeys.has(key) || isCalendarReminderFired(key);
}

export function rememberCalendarReminderFired(key: string): void {
    firedReminderKeys.add(key);
    markCalendarReminderFired(key);
}

export function resolveCalendarReminderTickMs(
    events: CalendarEvent[],
    now: Date = new Date(),
): number {
    const nowMs = now.getTime();
    let nearestFutureMs = Infinity;

    for (const event of events) {
        const minutes = event.reminderMinutesBefore;
        if (!minutes || minutes <= 0) continue;
        const fireAt = computeCalendarReminderFireAt(event.date, event.time, minutes);
        if (!fireAt) continue;
        const delta = fireAt.getTime() - nowMs;
        if (delta > 0 && delta < nearestFutureMs) {
            nearestFutureMs = delta;
        }
    }

    if (nearestFutureMs <= 2 * 60_000) return 5_000;
    if (nearestFutureMs <= 15 * 60_000) return 12_000;
    return 30_000;
}

export function scanAndFireCalendarReminders(
    events: CalendarEvent[],
    now: Date = new Date(),
    onFire?: (event: CalendarEvent, fireAt: Date) => void,
    options?: {
        isSnoozed?: (key: string) => boolean;
    },
): void {
    const nowMs = now.getTime();
    for (const event of events) {
        const minutes = event.reminderMinutesBefore;
        if (!minutes || minutes <= 0) continue;
        const fireAt = computeCalendarReminderFireAt(event.date, event.time, minutes);
        const eventStart = parseCalendarDateTime(event.date, event.time);
        if (!fireAt || !eventStart) continue;
        const fireMs = fireAt.getTime();
        if (nowMs < fireMs || nowMs >= eventStart.getTime()) continue;

        const key = buildCalendarReminderKey(event.id, event.date, event.time ?? '', minutes);
        if (options?.isSnoozed?.(key)) continue;
        if (isCalendarReminderKeyFired(key)) continue;

        rememberCalendarReminderFired(key);
        onFire?.(event, fireAt);
    }
}

export function resetCalendarReminderFiredKeysForTests(): void {
    firedReminderKeys.clear();
}

import type { CalendarEvent } from '@/app/services/calendar/calendarTypes';

type CacheEntry = {
    events: CalendarEvent[];
    contentSig: string;
};

const memoryByUser = new Map<string, CacheEntry>();
const inFlightByUser = new Map<string, Promise<CalendarEvent[]>>();
const cacheListeners = new Set<() => void>();

function notifyCalendarEventsCacheListeners(): void {
    for (const listener of cacheListeners) listener();
}

/** إشعار خفيف عند امتلاء الكاش — قشرة الفتح ترسم نقاط الأسبوع دون قراءة SecureStore */
export function subscribeCalendarEventsCache(listener: () => void): () => void {
    cacheListeners.add(listener);
    return () => {
        cacheListeners.delete(listener);
    };
}

function eventsSignature(events: CalendarEvent[]): string {
    if (events.length === 0) return '0';
    const parts: string[] = [`n:${events.length}`];
    for (const e of events) {
        parts.push(`${e.id}:${e.updatedAt ?? ''}:${e.date ?? ''}`);
    }
    return parts.join('|');
}

export function getCachedCalendarEvents(userId: string): CalendarEvent[] | null {
    if (!userId) return null;
    const entry = memoryByUser.get(userId);
    if (!entry) return null;
    return entry.events;
}

/** هل وُجدت لقطة ذاكرة (حتى لو فارغة بعد جلب سابق)؟ */
export function hasCachedCalendarEvents(userId: string): boolean {
    if (!userId) return false;
    return memoryByUser.has(userId);
}

export function setCachedCalendarEvents(userId: string, events: CalendarEvent[]): void {
    if (!userId) return;
    memoryByUser.set(userId, {
        events,
        contentSig: eventsSignature(events),
    });
    notifyCalendarEventsCacheListeners();
}

export function invalidateCalendarEventsCache(userId?: string): void {
    if (userId) {
        memoryByUser.delete(userId);
        inFlightByUser.delete(userId);
        notifyCalendarEventsCacheListeners();
        return;
    }
    memoryByUser.clear();
    inFlightByUser.clear();
    notifyCalendarEventsCacheListeners();
}

/**
 * يُجمّع طلبات getEvents المتزامنة لنفس المحامي في promise واحد.
 * يُستخدم من CalendarDB.getEvents.
 */
export function dedupeCalendarGetEvents(
    userId: string,
    fetcher: () => Promise<CalendarEvent[]>,
    options?: { forceRefresh?: boolean },
): Promise<CalendarEvent[]> {
    if (!userId) return fetcher();

    if (!options?.forceRefresh) {
        const cached = getCachedCalendarEvents(userId);
        if (cached) return Promise.resolve(cached);

        const inflight = inFlightByUser.get(userId);
        if (inflight) return inflight;
    } else {
        invalidateCalendarEventsCache(userId);
    }

    const promise = fetcher()
        .then((events) => {
            setCachedCalendarEvents(userId, events);
            return events;
        })
        .finally(() => {
            if (inFlightByUser.get(userId) === promise) {
                inFlightByUser.delete(userId);
            }
        });

    inFlightByUser.set(userId, promise);
    return promise;
}

/** للاختبارات */
export function resetCalendarEventsCacheForTests(): void {
    cacheListeners.clear();
    invalidateCalendarEventsCache();
}

/**
 * تسخين كاش أحداث التقويم — ورقة معزولة عن مُرطِّب الإقلاع.
 *
 * لماذا انفصلت عن `scheduleIntentWarm`: ذاك الملفّ يستورد
 * `hydrateScheduleShellForInstantOpenWithData` من `runtime/scheduleBootHydrator`،
 * والمُرطِّب يستورد `warmCalendarEventsCache` منه — دائرة استيراد ثابتة على مسار
 * الإقلاع نفسه، وهو أخطر موضع تقع فيه: ترتيب التهيئة هناك يُحدّده مَن حُمِّل أوّلاً،
 * وعطل TDZ فيه يمنع رفع حاجز الإقلاع فلا يرى المحامي شاشة أصلاً.
 *
 * وهذه الثلاثيّة لا تحتاج المُرطِّب قطّ: كاشٌ لأحداث وجَلبٌ واحدٌ مُدمَج. أمّا
 * `warmSchedulePipeline` فهو الذي يحتاجه، ويبقى هناك.
 *
 * حالة `registeredWarmUserId` تسكن هنا لأنها للجَلب لا للتسخين العامّ، ويقرأها
 * خطّ الأنابيب بالدالّة المُصدَّرة أدناه — نسخةٌ واحدة لا نسختان تفترقان.
 */
import { fetchCalendarEvents } from '@/app/services/calendar/calendarCloudRuntime';
import { resolveCalendarUserId } from '@/app/services/calendar/bridge/core';
import {
    getCachedCalendarEvents,
    setCachedCalendarEvents,
} from '@/app/services/calendar/calendarEventsCache';
import {
    peekLocalCalendarSnapshotSync,
    readLocalCalendarSnapshotSync,
} from '@/app/services/calendar/calendarLocalSnapshot';
import type { CalendarEvent } from '@/app/services/cloud/lawyerCalendarTypes';

let registeredWarmUserId: string | null | undefined;
let warmInflight: Promise<CalendarEvent[]> | null = null;
let warmForUserId: string | null = null;

/** يسجّل userId للـ prefetch من الدوك دون تمرير صريح */
export function registerScheduleWarmUserId(userId: string | null | undefined): () => void {
    registeredWarmUserId = userId;
    return () => {
        if (registeredWarmUserId === userId) registeredWarmUserId = undefined;
    };
}

/** المُسجَّل الحالي — يقرأه خطّ تسخين الجدول بدل نسخ الحالة */
export function getRegisteredScheduleWarmUserId(): string | null | undefined {
    return registeredWarmUserId;
}

/**
 * يملأ كاش الذاكرة من لقطة peek قبل أول رسم للقشرة — بلا ترحيل تشفير.
 * لا يكتب مصفوفة فارغة حتى لا يحجب الجلب من القرص.
 */
export function primeCalendarEventsCacheFromPeek(userId?: string | null): boolean {
    if (typeof window === 'undefined') return false;
    const uid = resolveCalendarUserId(userId ?? registeredWarmUserId ?? null);
    if (!uid) return false;
    const cached = getCachedCalendarEvents(uid);
    if (cached && cached.length > 0) return true;
    const events = peekLocalCalendarSnapshotSync(uid);
    if (events.length === 0) return false;
    setCachedCalendarEvents(uid, events);
    return true;
}

/** ترحيل مرآة leftover بعد الإطار — ليس على مسار النقرة */
export function drainCalendarLegacyMirrorsWhenIdle(userId?: string | null): void {
    if (typeof window === 'undefined') return;
    const uid = resolveCalendarUserId(userId ?? registeredWarmUserId ?? null);
    if (!uid) return;
    const run = () => {
        readLocalCalendarSnapshotSync(uid);
    };
    if (typeof window.requestIdleCallback === 'function') {
        window.requestIdleCallback(run, { timeout: 2_200 });
        return;
    }
    window.setTimeout(run, 400);
}

/** ينتظر جلب الأحداث الجاري إن وُجد — يمنع fetch مكرر عند فتح الرادار */
export function awaitCalendarWarmIfInflight(userId: string | null | undefined): Promise<void> {
    const uid = resolveCalendarUserId(userId ?? registeredWarmUserId ?? null);
    if (!uid || warmForUserId !== uid || !warmInflight) return Promise.resolve();
    return warmInflight.then(() => undefined).catch(() => undefined);
}

/** تحميل مسبق لأحداث التقويم في الذاكرة */
export function warmCalendarEventsCache(
    userId: string | null | undefined,
): Promise<CalendarEvent[]> {
    if (typeof window === 'undefined') return Promise.resolve([]);
    const uid = resolveCalendarUserId(userId ?? registeredWarmUserId ?? null);
    if (!uid) return Promise.resolve([]);
    if (warmForUserId === uid && warmInflight) return warmInflight;

    warmForUserId = uid;
    const warmUid = uid;
    warmInflight = fetchCalendarEvents(uid)
        .catch(() => [] as CalendarEvent[])
        .then((events) => {
            setCachedCalendarEvents(warmUid, events);
            if (warmForUserId === warmUid) warmInflight = null;
            return events;
        });

    return warmInflight;
}

import { createContext, useContext } from 'react';

/** هل استقر جسم الرادار الحي داخل صدفة الكروم؟ الافتراضي true للرادار المستقل في الاختبارات */
