import type { CalendarEvent } from '@/app/services/cloud/lawyerCalendarTypes';
import { isUsableCalendarEventRecord } from '@/app/services/calendar/calendarEventRecord';
import {
    CALENDAR_EVENTS_STORAGE_KEY,
    CALENDAR_TOMBSTONES_STORAGE_KEY,
} from '@/app/services/calendar/calendarStorageKeys';
import {
    clearLegacyPlaintextMirror,
    peekSecureOrLegacySync,
    readSecureOrDrainLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';

export const CALENDAR_LOCAL_STORAGE_KEY = CALENDAR_EVENTS_STORAGE_KEY;

function parseJsonUnknown(raw: string | null): unknown {
    if (raw == null) return null;
    try {
        return JSON.parse(raw);
    } catch {
        return null;
    }
}

function tombstoneIdsFromParsed(parsed: unknown, userId: string): Set<string> {
    if (!parsed || typeof parsed !== 'object') return new Set<string>();
    const list = (parsed as Record<string, Array<{ eventId?: string }>>)[userId];
    if (!Array.isArray(list)) return new Set<string>();
    const ids = new Set<string>();
    for (const t of list) {
        if (typeof t?.eventId === 'string' && t.eventId) ids.add(t.eventId);
    }
    return ids;
}

function collectEventsForUser(userId: string, eventsRaw: unknown, tombsRaw: unknown): CalendarEvent[] {
    if (!Array.isArray(eventsRaw)) return [];
    const tombstones = tombstoneIdsFromParsed(tombsRaw, userId);
    const events: CalendarEvent[] = [];
    for (const raw of eventsRaw) {
        if (!isUsableCalendarEventRecord(raw)) continue;
        if (raw.userId !== userId) continue;
        if (tombstones.has(raw.id)) continue;
        events.push(raw);
    }
    return events;
}

/** أول طلاء — بلا ترحيل ولا setItemSync */
export function peekLocalCalendarSnapshotSync(userId: string): CalendarEvent[] {
    if (!userId) return [];
    return collectEventsForUser(
        userId,
        parseJsonUnknown(peekSecureOrLegacySync(CALENDAR_LOCAL_STORAGE_KEY)),
        parseJsonUnknown(peekSecureOrLegacySync(CALENDAR_TOMBSTONES_STORAGE_KEY)),
    );
}

/**
 * قراءة مع ترحيل مرآة localStorage — ليس لمسار أول إطار.
 * SecureStore / decryptedCache؛ المرآة تُرحَّل وتُمحى.
 */
export function readLocalCalendarSnapshotSync(userId: string): CalendarEvent[] {
    if (!userId) return [];
    return collectEventsForUser(
        userId,
        parseJsonUnknown(readSecureOrDrainLegacySync(CALENDAR_LOCAL_STORAGE_KEY)),
        parseJsonUnknown(readSecureOrDrainLegacySync(CALENDAR_TOMBSTONES_STORAGE_KEY)),
    );
}

export function clearCalendarEventsLocalStorageMirror(): void {
    clearLegacyPlaintextMirror(CALENDAR_LOCAL_STORAGE_KEY);
}

import { getLocalTodayYmd } from '@/app/utils/localYmd';
import { CALENDAR_MONTHS } from '@/app/services/calendar/calendarArabicLabels';

export function calendarTodayYmd(now: Date = new Date()): string {
    return getLocalTodayYmd(now);
}

export function isCalendarToday(dateStr: string, now: Date = new Date()): boolean {
    return dateStr === calendarTodayYmd(now);
}

/** يوم سابق — للعرض الشفاف دون الحذف */
export function isCalendarPastDay(dateStr: string, now: Date = new Date()): boolean {
    if (!dateStr || dateStr.length < 10) return false;
    return dateStr < calendarTodayYmd(now);
}

export function calendarMonthGridMetrics(
    viewYear: number,
    viewMonth: number,
): {
    daysInMonth: number;
    firstDayOfMonth: number;
} {
    return {
        daysInMonth: new Date(viewYear, viewMonth + 1, 0).getDate(),
        firstDayOfMonth: new Date(viewYear, viewMonth, 1).getDay(),
    };
}

export function shiftCalendarMonth(
    viewYear: number,
    viewMonth: number,
    delta: -1 | 1,
): { year: number; month: number } {
    const next = viewMonth + delta;
    if (next < 0) return { year: viewYear - 1, month: 11 };
    if (next > 11) return { year: viewYear + 1, month: 0 };
    return { year: viewYear, month: next };
}

export function clampYmdToCalendarMonth(
    year: number,
    monthIndex: number,
    preferredDay: number,
): string {
    const { daysInMonth } = calendarMonthGridMetrics(year, monthIndex);
    const day = Math.min(Math.max(1, preferredDay), daysInMonth);
    return `${year}-${String(monthIndex + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
}

/** يُبقي اليوم المحدد داخل الشهر المعروض حتى لا ينفصل شريط الأسبوع عن شريط الشهر */
export function selectedDateAfterCalendarMonthShift(
    selectedDate: string,
    viewYear: number,
    viewMonth: number,
    delta: -1 | 1,
): { year: number; month: number; selectedDate: string } {
    const { year, month } = shiftCalendarMonth(viewYear, viewMonth, delta);
    const parsed = Number.parseInt(selectedDate.slice(8, 10), 10);
    const preferredDay = Number.isFinite(parsed) && parsed > 0 ? parsed : 1;
    return { year, month, selectedDate: clampYmdToCalendarMonth(year, month, preferredDay) };
}

export function viewFromCalendarYmd(
    ymd: string,
): { selectedDate: string; viewYear: number; viewMonth: number } | null {
    const d = new Date(`${ymd}T12:00:00`);
    if (Number.isNaN(d.getTime())) return null;
    return { selectedDate: ymd, viewYear: d.getFullYear(), viewMonth: d.getMonth() };
}

/** تسمية عربية لخلية يوم التقويم — قارئ الشاشة فقط */
export function buildCalendarDayAriaLabel(
    day: number,
    viewMonth: number,
    viewYear: number,
    eventCount: number,
    isTodayCell: boolean,
): string {
    const parts = [`${day} ${CALENDAR_MONTHS[viewMonth]} ${viewYear}`];
    if (isTodayCell) parts.push('اليوم');
    if (eventCount > 0) {
        parts.push(`${eventCount} ${eventCount === 1 ? 'موعد' : 'مواعيد'}`);
    }
    return parts.join('، ');
}

export function buildCalendarGridAriaLabel(viewMonth: number, viewYear: number): string {
    return `تقويم ${CALENDAR_MONTHS[viewMonth]} ${viewYear}`;
}

export function calendarEventTimeValue(t?: string): number {
    if (!t) return 9999;
    const [h, m] = t.split(':').map(Number);
    if (isNaN(h) || isNaN(m)) return 9999;
    return h * 60 + m;
}

export type CalendarOpenSourceDetail = {
    sourceModule: string;
    sourceEntityId: string;
    sourceEventId?: string;
};

const listeners = new Set<(detail: CalendarOpenSourceDetail) => void>();
let pending: CalendarOpenSourceDetail | null = null;

export function requestCalendarOpenSource(detail: CalendarOpenSourceDetail): void {
    const moduleId = detail.sourceModule.trim();
    const entityId = detail.sourceEntityId.trim();
    if (!moduleId || !entityId) return;
    const next: CalendarOpenSourceDetail = {
        sourceModule: moduleId,
        sourceEntityId: entityId,
        sourceEventId: detail.sourceEventId,
    };
    if (listeners.size === 0) {
        pending = next;
        return;
    }
    for (const listener of listeners) listener(next);
}

export function subscribeCalendarOpenSource(
    listener: (detail: CalendarOpenSourceDetail) => void,
): () => void {
    listeners.add(listener);
    if (pending) {
        const queued = pending;
        pending = null;
        listener(queued);
    }
    return () => {
        listeners.delete(listener);
    };
}

export function resetCalendarOpenSourceForTests(): void {
    listeners.clear();
    pending = null;
}

/**
 * ميزانيات أداء التقويم — مرجع E2E + Sentry.
 * CI: حدود سخية لتفادي flakiness.
 * target: الهدف بعد تحسينات UI/cache (يُضبط من p95 إنتاج لاحقاً).
 */
export const CALENDAR_PERF_BUDGET = {
    /** open-request → interactive (performance marks) */
    openToInteractiveMs: {
        target: 2_500,
        /** أول فتح بدون كاش — CI */
        ciColdMax: 6_000,
        /** فتح مع snapshot محلي — CI */
        ciCachedMax: 3_000,
    },
    sentryMetric: 'calendar.open_to_interactive_ms',
} as const;

export type CalendarPerfBudgetKey = keyof typeof CALENDAR_PERF_BUDGET.openToInteractiveMs;

import { debug } from '@/app/utils/debug';
import {
    reportCalendarOpenToSentry,
    type CalendarPerfReportContext,
} from '@/app/services/calendar/calendarSentryReporting';

const MARK_PREFIX = 'hami:calendar:';

export type CalendarPerfPhase = 'open-request' | 'first-paint' | 'interactive';

export type { CalendarPerfReportContext };

export function markCalendarPerfPhase(phase: CalendarPerfPhase): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark(`${MARK_PREFIX}${phase}`);
    } catch {
        /* ignore */
    }
}

export function clearCalendarPerfMarks(): void {
    if (typeof performance === 'undefined' || typeof performance.clearMarks !== 'function') return;
    try {
        for (const phase of ['open-request', 'first-paint', 'interactive'] as const) {
            performance.clearMarks(`${MARK_PREFIX}${phase}`);
        }
    } catch {
        /* ignore */
    }
}

/** ms من open-request → interactive (null إذا لم تُسجَّل المرحلتان) */
export function getCalendarOpenToInteractiveMs(): number | null {
    if (typeof performance === 'undefined') return null;
    const open = performance.getEntriesByName(`${MARK_PREFIX}open-request`, 'mark')[0];
    const interactive = performance.getEntriesByName(`${MARK_PREFIX}interactive`, 'mark')[0];
    if (!open || !interactive) return null;
    return Math.round(interactive.startTime - open.startTime);
}

export function reportCalendarPerfIfDev(context?: string): void {
    if (!import.meta.env.DEV) return;
    const ms = getCalendarOpenToInteractiveMs();
    if (ms == null) return;
    debug.log(`[CalendarPerf] open→interactive ${ms}ms`, context ?? '');
}

/** DEV: log — PROD (مع DSN): Sentry breadcrumb + metric */
export function reportCalendarPerf(context: CalendarPerfReportContext = {}): void {
    const ms = getCalendarOpenToInteractiveMs();
    if (ms == null) return;
    if (import.meta.env.DEV) {
        debug.log('[CalendarPerf] open→interactive', ms, 'ms', context);
    }
    reportCalendarOpenToSentry(ms, context);
}

import { cleanupCalendarForUser } from '@/app/services/calendarDossierSync';
import { invalidateCalendarEventsCache } from '@/app/services/calendar/calendarEventsCache';

const RECONCILE_STATE_KEY = 'hami:calendar:reconcile-state:v1';
const FULL_RECONCILE_INTERVAL_MS = 24 * 60 * 60 * 1000;
const FINGERPRINT_CHANGE_COOLDOWN_MS = 5 * 60 * 1000;

type ReconcileState = {
    fingerprint: string;
    lastFullAt: number;
};

type ReconcileStore = Record<string, ReconcileState>;

const inFlightByUser = new Map<string, Promise<boolean>>();

function readStore(): ReconcileStore {
    if (typeof localStorage === 'undefined') return {};
    try {
        const raw = localStorage.getItem(RECONCILE_STATE_KEY);
        if (!raw) return {};
        const parsed = JSON.parse(raw);
        return parsed && typeof parsed === 'object' ? (parsed as ReconcileStore) : {};
    } catch {
        return {};
    }
}

function writeState(userId: string, state: ReconcileState): void {
    if (typeof localStorage === 'undefined') return;
    try {
        const store = readStore();
        store[userId] = state;
        localStorage.setItem(RECONCILE_STATE_KEY, JSON.stringify(store));
    } catch {
        /* ignore */
    }
}

export function shouldRunCalendarReconcile(
    userId: string,
    dossierFingerprint: string,
    now = Date.now(),
): boolean {
    if (!userId) return false;
    const state = readStore()[userId];
    if (!state) return true;
    if (now - state.lastFullAt >= FULL_RECONCILE_INTERVAL_MS) return true;
    if (state.fingerprint !== dossierFingerprint && now - state.lastFullAt >= FINGERPRINT_CHANGE_COOLDOWN_MS) {
        return true;
    }
    return false;
}

/** للاختبارات */
export function resetCalendarReconcileStateForTests(): void {
    if (typeof localStorage === 'undefined') return;
    localStorage.removeItem(RECONCILE_STATE_KEY);
    inFlightByUser.clear();
}

/**
 * reconcile عميق فقط عند الحاجة:
 * - أول مرة
 * - تغيّر fingerprint الإضابير (بعد cooldown 5 د)
 * - مرّ 24 ساعة من آخر reconcile
 */
export async function runSmartCalendarReconcileIfNeeded(
    userId: string,
    dossierFingerprint: string,
): Promise<boolean> {
    if (!userId) return false;
    if (!shouldRunCalendarReconcile(userId, dossierFingerprint)) return false;

    const existing = inFlightByUser.get(userId);
    if (existing) return existing;

    const job = (async (): Promise<boolean> => {
        if (!shouldRunCalendarReconcile(userId, dossierFingerprint)) return false;
        await cleanupCalendarForUser(userId);
        writeState(userId, { fingerprint: dossierFingerprint, lastFullAt: Date.now() });
        invalidateCalendarEventsCache(userId);
        return true;
    })();

    inFlightByUser.set(userId, job);
    try {
        return await job;
    } finally {
        if (inFlightByUser.get(userId) === job) {
            inFlightByUser.delete(userId);
        }
    }
}

/**
 * نغمة «حامي» القانونية — ملف WAV حقيقي أولاً، ثم إيقاع مُركَّب إن تعذّر التشغيل.
 * نبرة عميقة (سلطة) → ثنائية شرقية → نداء ذهبي قابل للتمييز من بعيد.
 */

import { HAMI_LEGAL_ALARM_SOUND_WEB } from '@/app/services/notifications/native/hamiNativeSound';
import {
    HAMI_LEGAL_ALARM_VIBRATE_PATTERN,
    playDeviceHaptic,
} from '@/app/services/platform/deviceHaptic';

type ChimeStep =
    | { kind: 'tone'; freq: number; duration: number; gain: number; wave?: OscillatorType; detune?: number }
    | { kind: 'pause'; duration: number };

/** توقيع صوتي ثابت للمشروع — يطابق scripts/generate-hami-notification-sound.mjs */
const HAMI_LEGAL_ALARM_SEQUENCE: ChimeStep[] = [
    { kind: 'tone', freq: 146.83, duration: 0.48, gain: 0.58, wave: 'sine' },
    { kind: 'pause', duration: 0.16 },
    { kind: 'tone', freq: 185.0, duration: 0.4, gain: 0.46, wave: 'triangle', detune: 12 },
    { kind: 'tone', freq: 220.0, duration: 0.52, gain: 0.34, wave: 'sine', detune: -8 },
    { kind: 'pause', duration: 0.12 },
    { kind: 'tone', freq: 293.66, duration: 0.62, gain: 0.52, wave: 'sine' },
    { kind: 'tone', freq: 369.99, duration: 0.5, gain: 0.3, wave: 'triangle', detune: 6 },
    { kind: 'pause', duration: 0.18 },
    { kind: 'tone', freq: 440.0, duration: 0.95, gain: 0.44, wave: 'sine' },
    { kind: 'tone', freq: 554.37, duration: 0.72, gain: 0.22, wave: 'sine', detune: 4 },
];

let sharedAudioContext: AudioContext | null = null;
let activePlaybackGeneration = 0;
let webAlarmAudio: HTMLAudioElement | null = null;

function getAudioContext(): AudioContext | null {
    if (typeof window === 'undefined') return null;
    const Ctx = window.AudioContext || (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext;
    if (!Ctx) return null;
    if (!sharedAudioContext || sharedAudioContext.state === 'closed') {
        sharedAudioContext = new Ctx();
    }
    return sharedAudioContext;
}

async function ensureAudioRunning(ctx: AudioContext): Promise<void> {
    if (ctx.state === 'suspended') {
        try {
            await ctx.resume();
        } catch {
            /* ignore */
        }
    }
}

function stopWebAlarmAudio(): void {
    if (!webAlarmAudio) return;
    try {
        webAlarmAudio.pause();
        webAlarmAudio.currentTime = 0;
        webAlarmAudio.loop = false;
        webAlarmAudio.src = '';
    } catch {
        /* ignore */
    }
    webAlarmAudio = null;
}

function scheduleTone(
    ctx: AudioContext,
    destination: AudioNode,
    startAt: number,
    step: Extract<ChimeStep, { kind: 'tone' }>,
): void {
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    const filter = ctx.createBiquadFilter();

    osc.type = step.wave ?? 'sine';
    osc.frequency.setValueAtTime(step.freq, startAt);
    if (step.detune) {
        osc.detune.setValueAtTime(step.detune, startAt);
    }

    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(1_800, startAt);
    filter.Q.setValueAtTime(0.7, startAt);

    const attack = 0.018;
    const release = Math.min(0.35, step.duration * 0.45);
    gain.gain.setValueAtTime(0.0001, startAt);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0001, step.gain), startAt + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, startAt + step.duration - release);

    osc.connect(filter);
    filter.connect(gain);
    gain.connect(destination);

    osc.start(startAt);
    osc.stop(startAt + step.duration + 0.02);
}

function playSequenceOnContext(ctx: AudioContext, destination: AudioNode, startOffset = 0): number {
    let cursor = ctx.currentTime + startOffset;
    for (const step of HAMI_LEGAL_ALARM_SEQUENCE) {
        if (step.kind === 'pause') {
            cursor += step.duration;
            continue;
        }
        scheduleTone(ctx, destination, cursor, step);
        cursor += step.duration;
    }
    return cursor - (ctx.currentTime + startOffset);
}

function vibrateLegalAlarm(): void {
    playDeviceHaptic(HAMI_LEGAL_ALARM_VIBRATE_PATTERN);
}

async function playWebLegalAlarmWav(loop: boolean): Promise<HTMLAudioElement | null> {
    if (typeof window === 'undefined' || typeof Audio === 'undefined') return null;
    try {
        stopWebAlarmAudio();
        const audio = new Audio(HAMI_LEGAL_ALARM_SOUND_WEB);
        audio.preload = 'auto';
        audio.loop = loop;
        audio.volume = 1;
        await audio.play();
        webAlarmAudio = audio;
        return audio;
    } catch {
        stopWebAlarmAudio();
        return null;
    }
}

export type PlayHamiLegalReminderAlarmOptions = {
    /** تكرار النغمة الكاملة (للمنبه المستمر) — يُستخدم عند سقوط ملف WAV */
    repeats?: number;
    /** فاصل بين التكرارات بالثواني */
    repeatGapSec?: number;
    /** حلقة WAV حتى الإيقاف — منبّه حقيقي داخل التطبيق */
    loop?: boolean;
};

/**
 * يشغّل نغمة التذكير القانونية. يُرجع دالة إيقاف إن كان التكرار مفعّلاً.
 */
export async function playHamiLegalReminderAlarm(
    options: PlayHamiLegalReminderAlarmOptions = {},
): Promise<() => void> {
    const { shouldPlayCalendarAlarmSound, shouldVibrateChannel } = await import(
        '@/app/services/notifications/notificationAlertPolicy'
    );
    if (!shouldPlayCalendarAlarmSound()) {
        return () => undefined;
    }

    const generation = ++activePlaybackGeneration;
    const loop = options.loop === true;

    if (shouldVibrateChannel('calendar', undefined, true)) {
        vibrateLegalAlarm();
    }

    const wavEl = await playWebLegalAlarmWav(loop);
    if (wavEl && generation === activePlaybackGeneration) {
        return () => {
            if (generation === activePlaybackGeneration) {
                activePlaybackGeneration += 1;
            }
            stopWebAlarmAudio();
        };
    }

    const repeats = Math.max(1, options.repeats ?? 1);
    const repeatGapSec = options.repeatGapSec ?? 0.35;

    const ctx = getAudioContext();
    if (!ctx) return () => undefined;

    await ensureAudioRunning(ctx);

    const master = ctx.createGain();
    master.gain.setValueAtTime(0.92, ctx.currentTime);
    master.connect(ctx.destination);

    let cursor = 0;
    for (let i = 0; i < repeats; i += 1) {
        if (generation !== activePlaybackGeneration) break;
        const duration = playSequenceOnContext(ctx, master, cursor);
        cursor += duration + repeatGapSec;
    }

    const stop = () => {
        if (generation === activePlaybackGeneration) {
            activePlaybackGeneration += 1;
        }
        stopWebAlarmAudio();
        try {
            master.disconnect();
        } catch {
            /* ignore */
        }
    };

    const totalMs = Math.ceil(cursor * 1000) + 120;
    const autoStopTimer = window.setTimeout(stop, totalMs);

    return () => {
        window.clearTimeout(autoStopTimer);
        stop();
    };
}

/** إيقاف أي تشغيل جارٍ */
export function stopHamiLegalReminderAlarm(): void {
    activePlaybackGeneration += 1;
    stopWebAlarmAudio();
}

/** يُستدعى من إيماءة المستخدم (تفعيل الجرس) لتفادي حظر الصوت على iOS/Safari */
export async function primeHamiLegalReminderAudio(): Promise<void> {
    const ctx = getAudioContext();
    if (ctx) await ensureAudioRunning(ctx);
    if (typeof Audio === 'undefined') return;
    try {
        const audio = new Audio(HAMI_LEGAL_ALARM_SOUND_WEB);
        audio.preload = 'auto';
        audio.muted = true;
        audio.volume = 0;
        await audio.play().catch(() => undefined);
        audio.pause();
        audio.src = '';
    } catch {
        /* ignore */
    }
}

export function resetHamiLegalReminderAlarmForTests(): void {
    activePlaybackGeneration = 0;
    stopWebAlarmAudio();
    if (sharedAudioContext && sharedAudioContext.state !== 'closed') {
        void sharedAudioContext.close();
    }
    sharedAudioContext = null;
}

import {
    clearSecureJsonValue,
    readSecureJsonRawSync,
    writeSecureJsonValue,
} from '@/app/services/storage/syncSecureJson';

const STORAGE_KEY = 'hami-calendar-reminder-fired-v1';
const MAX_ENTRIES = 200;

function readEntries(): string[] {
    try {
        const raw = readSecureJsonRawSync(STORAGE_KEY);
        if (!raw) return [];
        const parsed = JSON.parse(raw) as unknown;
        return Array.isArray(parsed) ? parsed.filter((k) => typeof k === 'string') : [];
    } catch {
        return [];
    }
}

function writeEntries(entries: string[]): void {
    writeSecureJsonValue(STORAGE_KEY, entries.slice(-MAX_ENTRIES));
}

export function isCalendarReminderFired(key: string): boolean {
    return readEntries().includes(key);
}

export function markCalendarReminderFired(key: string): void {
    const entries = readEntries();
    if (entries.includes(key)) return;
    writeEntries([...entries, key]);
}

export function clearCalendarReminderFiredForTests(): void {
    clearSecureJsonValue(STORAGE_KEY);
}

