import {
    clearSecureJsonValue,
    readSecureJsonRawSync,
    writeSecureJsonValue,
} from '@/app/services/storage/syncSecureJson';

const STORAGE_KEY = 'hami-calendar-reminder-snooze-v1';
const MAX_ENTRIES = 80;

export const HAMI_CALENDAR_NATIVE_SYNC_EVENT = 'hami:calendar-native-sync';

export type CalendarReminderSnoozeRecord = {
    key: string;
    eventId: string;
    date: string;
    time: string;
    reminderMinutesBefore: number;
    title: string;
    location?: string;
    untilMs: number;
};

function isRecord(value: unknown): value is CalendarReminderSnoozeRecord {
    if (!value || typeof value !== 'object') return false;
    const row = value as CalendarReminderSnoozeRecord;
    return (
        typeof row.key === 'string' &&
        typeof row.eventId === 'string' &&
        typeof row.date === 'string' &&
        typeof row.time === 'string' &&
        typeof row.reminderMinutesBefore === 'number' &&
        typeof row.title === 'string' &&
        typeof row.untilMs === 'number' &&
        Number.isFinite(row.untilMs)
    );
}

function readAll(): CalendarReminderSnoozeRecord[] {
    try {
        const raw = readSecureJsonRawSync(STORAGE_KEY);
        if (!raw) return [];
        const parsed = JSON.parse(raw) as unknown;
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(isRecord);
    } catch {
        return [];
    }
}

function writeAll(entries: CalendarReminderSnoozeRecord[]): void {
    writeSecureJsonValue(STORAGE_KEY, entries.slice(-MAX_ENTRIES));
}

export function readCalendarReminderSnoozes(nowMs: number = Date.now()): CalendarReminderSnoozeRecord[] {
    const active = readAll().filter((row) => row.untilMs > nowMs);
    writeAll(active);
    return active;
}

export function upsertCalendarReminderSnooze(record: CalendarReminderSnoozeRecord): void {
    const next = readAll().filter((row) => row.key !== record.key);
    next.push(record);
    writeAll(next);
}

export function removeCalendarReminderSnooze(key: string): void {
    writeAll(readAll().filter((row) => row.key !== key));
}

export function isCalendarReminderSnoozed(key: string, nowMs: number = Date.now()): boolean {
    return readCalendarReminderSnoozes(nowMs).some((row) => row.key === key);
}

export function requestCalendarNativeReminderSync(): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new Event(HAMI_CALENDAR_NATIVE_SYNC_EVENT));
}

export function clearCalendarReminderSnoozesForTests(): void {
    clearSecureJsonValue(STORAGE_KEY);
}

import { isSentryEnabledInBuild as isSentryConfigured } from '@/app/observability/sentryBuildPolicy';

export type CalendarPerfReportContext = {
    userId?: string;
    eventCount?: number;
    hadLocalCache?: boolean;
};

type SentryModule = {
    addBreadcrumb?: (crumb: {
        category?: string;
        message?: string;
        level?: string;
        data?: Record<string, unknown>;
    }) => void;
    metrics?: {
        distribution?: (
            name: string,
            value: number,
            options?: { unit?: string; attributes?: Record<string, string | number | boolean> },
        ) => void;
    };
};

let sentryModulePromise: Promise<SentryModule | null> | null = null;

function loadSentryModule(): Promise<SentryModule | null> {
    if (!isSentryConfigured()) return Promise.resolve(null);
    if (!sentryModulePromise) {
        sentryModulePromise = import('@sentry/react')
            .then((mod) => mod as SentryModule)
            .catch(() => null);
    }
    return sentryModulePromise;
}

/** breadcrumb + metric distribution — best effort، لا يرمي */
export function reportCalendarOpenToSentry(
    durationMs: number,
    context: CalendarPerfReportContext = {},
): void {
    if (durationMs < 0 || !Number.isFinite(durationMs)) return;

    void loadSentryModule().then((Sentry) => {
        if (!Sentry) return;

        Sentry.addBreadcrumb?.({
            category: 'calendar.perf',
            message: `calendar open→interactive ${durationMs}ms`,
            level: 'info',
            data: {
                durationMs,
                eventCount: context.eventCount ?? null,
                hadLocalCache: context.hadLocalCache ?? null,
                userId: context.userId ? '[redacted]' : null,
            },
        });

        Sentry.metrics?.distribution?.('calendar.open_to_interactive_ms', durationMs, {
            unit: 'millisecond',
            attributes: {
                had_local_cache: Boolean(context.hadLocalCache),
            },
        });
    });
}

export type CalendarBridgeSyncFailureContext = {
    phase: string;
    userId?: string;
};

/** breadcrumb عند فشل مزامنة جسر التقويم — لا يرمي */
export function reportCalendarBridgeSyncFailure(
    error: unknown,
    context: CalendarBridgeSyncFailureContext,
): void {
    const message = error instanceof Error ? error.message : String(error);
    void loadSentryModule().then((Sentry) => {
        Sentry?.addBreadcrumb?.({
            category: 'calendar.bridge',
            message: `bridge sync failed: ${context.phase}`,
            level: 'error',
            data: {
                phase: context.phase,
                userId: context.userId ? '[redacted]' : null,
                error: message.slice(0, 240),
            },
        });
    });
}

/** للاختبارات */
export function resetCalendarSentryModuleForTests(): void {
    sentryModulePromise = null;
}

import { calendarTodayYmd, viewFromCalendarYmd, selectedDateAfterCalendarMonthShift } from '@/app/services/calendar/calendarMonthMath';

export type CalendarShellSession = {
    selectedDate: string;
    viewYear: number;
    viewMonth: number;
    showFullMonth: boolean;
};

const listeners = new Set<() => void>();

export type CalendarShellFormIntent =
    | { kind: 'add' }
    | { kind: 'edit'; eventId: string };

let formIntent: CalendarShellFormIntent | null = null;
let session: CalendarShellSession | null = null;

function notifyCalendarShellSession(): void {
    for (const listener of listeners) listener();
}

function sameSession(a: CalendarShellSession, b: CalendarShellSession): boolean {
    return (
        a.selectedDate === b.selectedDate &&
        a.viewYear === b.viewYear &&
        a.viewMonth === b.viewMonth &&
        a.showFullMonth === b.showFullMonth
    );
}

export function peekCalendarShellSession(): CalendarShellSession | null {
    return session;
}

export function subscribeCalendarShellSession(listener: () => void): () => void {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}

export function patchCalendarShellSession(partial: Partial<CalendarShellSession>): CalendarShellSession {
    const base = session ?? seedCalendarShellSession();
    const next: CalendarShellSession = {
        selectedDate: partial.selectedDate ?? base.selectedDate,
        viewYear: partial.viewYear ?? base.viewYear,
        viewMonth: partial.viewMonth ?? base.viewMonth,
        showFullMonth: partial.showFullMonth ?? base.showFullMonth,
    };
    if (session && sameSession(session, next)) return session;
    session = next;
    notifyCalendarShellSession();
    return next;
}

export function seedCalendarShellSession(now: Date = new Date()): CalendarShellSession {
    if (session) return session;
    const today = calendarTodayYmd(now);
    const fromYmd = viewFromCalendarYmd(today);
    session = {
        selectedDate: today,
        viewYear: fromYmd?.viewYear ?? now.getFullYear(),
        viewMonth: fromYmd?.viewMonth ?? now.getMonth(),
        showFullMonth: false,
    };
    return session;
}

export function applyCalendarShellMonthShift(delta: -1 | 1): CalendarShellSession {
    const shell = peekCalendarShellSession() ?? seedCalendarShellSession();
    const next = selectedDateAfterCalendarMonthShift(
        shell.selectedDate,
        shell.viewYear,
        shell.viewMonth,
        delta,
    );
    return patchCalendarShellSession({
        viewYear: next.year,
        viewMonth: next.month,
        selectedDate: next.selectedDate,
    });
}

export function requestCalendarShellAdd(): void {
    formIntent = { kind: 'add' };
    notifyCalendarShellSession();
}

export function requestCalendarShellEdit(eventId: string): void {
    const id = eventId.trim();
    if (!id) return;
    formIntent = { kind: 'edit', eventId: id };
    notifyCalendarShellSession();
}

export function consumeCalendarShellFormIntent(): CalendarShellFormIntent | null {
    const next = formIntent;
    formIntent = null;
    return next;
}

export function focusCalendarShellDate(ymd: string): CalendarShellSession {
    const view = viewFromCalendarYmd(ymd);
    if (!view) return seedCalendarShellSession();
    return patchCalendarShellSession(view);
}

/** للاختبارات */
export function resetCalendarShellSessionForTests(): void {
    session = null;
    formIntent = null;
    listeners.clear();
}

export const CALENDAR_FETCH_TIMEOUT_MS = 6_000;
export const CALENDAR_MUTATION_TIMEOUT_MS = 8_000;

const TIMEOUT_CODES = new Set([
    'calendar-fetch-timeout',
    'calendar-save-timeout',
    'calendar-mutation-timeout',
]);

export function isCalendarTimeoutError(err: unknown): boolean {
    return err instanceof Error && TIMEOUT_CODES.has(err.message);
}

/** مهلة مع مسح المؤقّت — لا تسرّب setTimeout بعد نجاح العملية */
export function withCalendarTimeout<T>(promise: Promise<T>, ms: number, code: string): Promise<T> {
    if (typeof window === 'undefined') return promise;
    let timer: number | undefined;
    const timeout = new Promise<never>((_, reject) => {
        timer = window.setTimeout(() => reject(new Error(code)), ms);
    });
    return Promise.race([promise, timeout]).finally(() => {
        if (timer !== undefined) window.clearTimeout(timer);
    });
}

import { formatDateToLocalYmd } from '@/app/utils/localYmd';

/** أيام الأسبوع (أحد→سبت) التي يقع فيها التاريخ المحدد */
export function buildCalendarWeekStrip(selectedDate: string): string[] {
    const d = new Date(`${selectedDate}T12:00:00`);
    if (Number.isNaN(d.getTime())) return [];
    const start = new Date(d);
    start.setDate(d.getDate() - d.getDay());
    return Array.from({ length: 7 }, (_, i) => {
        const x = new Date(start);
        x.setDate(start.getDate() + i);
        return formatDateToLocalYmd(x);
    });
}

export function formatCalendarSelectedDayTitle(selectedDate: string, fallback = selectedDate): string {
    const d = new Date(`${selectedDate}T12:00:00`);
    if (Number.isNaN(d.getTime())) return fallback;
    try {
        return new Intl.DateTimeFormat('ar-IQ', {
            weekday: 'long',
            day: 'numeric',
            month: 'long',
        }).format(d);
    } catch {
        return fallback;
    }
}

export function formatCalendarEventTimeRange(time?: string | null, endTime?: string | null): string | null {
    const start = String(time ?? '').trim();
    if (!start) return null;
    const end = String(endTime ?? '').trim();
    if (end && end !== start) return `${start}–${end}`;
    return start;
}

export function formatCalendarSelectedDayCaption(selectedDate: string): { title: string; meta: string } {
    const d = new Date(`${selectedDate}T12:00:00`);
    if (Number.isNaN(d.getTime())) {
        return { title: selectedDate, meta: '' };
    }
    try {
        return {
            title: formatCalendarSelectedDayTitle(selectedDate),
            meta: new Intl.DateTimeFormat('ar-IQ', { year: 'numeric' }).format(d),
        };
    } catch {
        return { title: formatCalendarSelectedDayTitle(selectedDate), meta: '' };
    }
}

/** فتح التقويم من دوك الرئيسية — منطق موحّد قابل للاختبار */
