/**
 * مزامنة التنفيذ → التقويم: مواعيد الخط الزمني + المشاهدة القادمة + مهام الاستحقاق ذات التاريخ.
 */
import { CalendarBridge, normalizeDateToYmd } from '@/app/services/calendar/bridge';
import type { DossierSyncStats, SyncScope } from './types';
import { shouldExcludeExecutionFromCalendar } from './exclusions';
import { isRecord, readEntityId, readStr } from './shared';
import { syncExecutionTaskDue, syncExecutionTimelineAppointment } from './incrementalSync';
import { EXECUTION_VISIT_NEXT_EVENT_ID } from './executionVisitNextEventId';
import { resolveNextExecutionVisitation } from './visitationCalendarSync';

export function syncOneExecutionFile(
    file: Record<string, unknown>,
    userId: string,
    stats: DossierSyncStats,
    scope: SyncScope = {},
): void {
    const whitelistOnly = scope.whitelistOnly === true;
    const includeTasks = scope.includeTasks !== false && !whitelistOnly;
    const executionId = readEntityId(file);
    if (executionId === null) return;
    if (shouldExcludeExecutionFromCalendar(file)) return;
    const caseNo =
        readStr(file, 'fileNumber') ||
        readStr(file, 'caseNo') ||
        readStr(file as Record<string, unknown>, 'caseNumber');
    const clientName = readStr(file, 'creditor') || readStr(file, 'clientName');
    const executionIdStr = String(executionId);

    const timeline = Array.isArray(file.timelineEvents) ? file.timelineEvents : [];
    for (const ev of timeline) {
        if (!isRecord(ev)) continue;
        syncExecutionTimelineAppointment({
            userId,
            executionId,
            event: {
                id: String(ev.id ?? ''),
                type: readStr(ev, 'type') || undefined,
                date: readStr(ev, 'date') || undefined,
                title: readStr(ev, 'title') || undefined,
                description: readStr(ev, 'description') || undefined,
                trashedAt: (ev.trashedAt as string | null | undefined) ?? null,
            },
            caseNo,
            clientName,
        });
        if (String(ev.type) === 'appointment' && !ev.trashedAt && normalizeDateToYmd(readStr(ev, 'date'))) {
            stats.executionAppointments++;
        }
    }

    const nextVisit = resolveNextExecutionVisitation(file);
    if (nextVisit) {
        syncExecutionTimelineAppointment({
            userId,
            executionId,
            event: {
                id: EXECUTION_VISIT_NEXT_EVENT_ID,
                type: 'appointment',
                date: nextVisit.date,
                title: 'موعد مشاهدة',
                description: [nextVisit.time, nextVisit.location].filter(Boolean).join(' · ') || undefined,
            },
            caseNo,
            clientName,
        });
        stats.executionAppointments++;
    } else {
        CalendarBridge.remove('execution', executionIdStr, EXECUTION_VISIT_NEXT_EVENT_ID, userId);
    }

    if (!includeTasks) return;

    const tasks = Array.isArray(file.caseTasksPending) ? file.caseTasksPending : [];
    for (const t of tasks) {
        if (!isRecord(t)) continue;
        const tid = String(t.id ?? '').trim();
        if (!tid) continue;
        if (t.trashedAt) {
            CalendarBridge.remove('execution', executionIdStr, `task_${tid}`, userId);
            continue;
        }
        const due = normalizeDateToYmd(readStr(t, 'dueDate'));
        if (!due) {
            CalendarBridge.remove('execution', executionIdStr, `task_${tid}`, userId);
            continue;
        }
        syncExecutionTaskDue({
            userId,
            executionId,
            task: {
                id: tid,
                title: readStr(t, 'title') || 'مهمة تنفيذ',
                dueDate: due,
                trashedAt: null,
            },
            caseNo,
            clientName,
        });
        stats.executionTasks++;
    }
}

/**
 * مزامنة منهجية: أي موعد/تاريخ في إضبارة (دعوى، تنفيذ، مستعجل، معاملة، جزائي، Threading)
 * يُرفع إلى التقويم المركزي عبر معرّف ثابت — لا ربط عشوائي لكل زر على حدة.
 */
import {
    CalendarBridge,
    normalizeDateToYmd,
} from '@/app/services/calendarBridge';
import type { LegalTask } from '@/app/types/TaskEngine';
import type { DossierSyncStats } from './types';
import {
    isFieldTaskCalendarEligible,
    isRecord,
    readStr,
    taskDateYmd,
} from './shared';


export function syncGlobalNotesToCalendar(
    notes: unknown[],
    userId: string,
    stats: DossierSyncStats,
): void {
    for (const raw of notes) {
        if (!isRecord(raw)) continue;
        const noteId = String(raw.id ?? '').trim();
        if (!noteId) continue;
        const date =
            normalizeDateToYmd(readStr(raw, 'apptDate')) ||
            normalizeDateToYmd(readStr(raw, 'reminder_at')) ||
            normalizeDateToYmd(readStr(raw, 'date'));
        if (!date) {
            CalendarBridge.remove('note', noteId, 'reminder', userId);
            continue;
        }
        const title =
            readStr(raw, 'title') ||
            readStr(raw, 'body')?.slice(0, 80) ||
            readStr(raw, 'text')?.slice(0, 80) ||
            'ملاحظة';
        const body = readStr(raw, 'body') || readStr(raw, 'text') || readStr(raw, 'content');
        CalendarBridge.syncNoteReminder({
            userId,
            noteId,
            date,
            title,
            body: body || undefined,
            linkedFileId:
                typeof raw.linkedFileId === 'string' || typeof raw.linkedFileId === 'number'
                    ? raw.linkedFileId
                    : undefined,
        });
        stats.globalNotes++;
    }
}

/** مهام الميدان (Quantum Tasks) */
export function syncFieldTasksToCalendar(
    tasks: LegalTask[],
    userId: string,
    stats: DossierSyncStats,
): void {
    for (const t of tasks) {
        const taskId = String(t.id ?? '').trim();
        if (!taskId) continue;
        if (!isFieldTaskCalendarEligible(t)) {
            CalendarBridge.remove('task', taskId, 'due', userId);
            continue;
        }
        const ymd = taskDateYmd(t);
        if (!ymd) {
            CalendarBridge.remove('task', taskId, 'due', userId);
            continue;
        }
        const loc =
            t.location?.trim() ||
            t.subTasks.find((s) => !s.isCompleted && s.location)?.location?.trim() ||
            null;
        CalendarBridge.syncFieldTaskDue({
            userId,
            taskId,
            date: ymd,
            title: t.title || t.rawText?.slice(0, 60) || 'مهمة ميدان',
            location: loc,
            linkedCaseId: t.linkedCaseId,
            isFatalDeadline: t.isFatalDeadline,
        });
        stats.fieldTasks++;
    }
}

export function syncLawsuitTimelineAppointment(p: {
    userId?: string | null;
    fileId: string | number;
    event: { id: string; date?: string; title?: string; details?: string; isDeleted?: boolean };
    caseNo?: string;
    court?: string;
    parties?: unknown;
    clientName?: string;
}): void {
    if (p.event.isDeleted) {
        CalendarBridge.remove('lawsuit', String(p.fileId), String(p.event.id), p.userId);
        return;
    }
    const ymd = normalizeDateToYmd(p.event.date);
    if (!ymd) return;
    CalendarBridge.syncLawsuitAppointment({
        userId: p.userId,
        fileId: p.fileId,
        timelineEventId: String(p.event.id),
        date: ymd,
        title: String(p.event.title || 'موعد'),
        details: p.event.details,
        caseNo: p.caseNo,
        court: p.court,
        parties: p.parties,
        clientName: p.clientName,
    });
}

/** مهمة بتاريخ استحقاق في دعوى مدنية */
export function syncLawsuitTaskDue(p: {
    userId?: string | null;
