/**
 * كاشف تعارضات/إثقال عبر أقسام الجدول ليوم محدد.
 * يوحّد الجلسات والمعاملات والمهام، ويستبعد المكتمل، ويستخدم المحكمة كاحتياطي موقع.
 */
import { resolveExplicitCalendarEventDurationMinutes } from '@/app/services/calendar/calendarDurationUtils';
import {
    mapCalendarModuleToScheduleSource,
    resolveScheduleItemDurationMinutes,
    type ScheduleItemSource,
} from '@/app/services/calendar/scheduleItemSource';

export {
    mapCalendarModuleToScheduleSource,
    resolveScheduleItemDurationMinutes,
    type ScheduleItemSource,
};

export type UnifiedScheduleItem = {
    id: string;
    title: string;
    date: string;
    location?: string;
    time?: string;
    source: ScheduleItemSource;
    durationMinutes?: number;
};

export type CrossSectionConflictInput = {
    hearings?: Array<{
        id: string;
        title: string;
        date: string;
        location?: string;
        time?: string;
        isCompleted?: boolean;
    }>;
    transactions?: Array<{
        id: string;
        title: string;
        date: string;
        location?: string;
        time?: string;
        isCompleted?: boolean;
    }>;
    tasks?: Array<{
        id: string;
        title: string;
        date: string;
        location?: string;
        time?: string;
        isCompleted?: boolean;
    }>;
    /** يوم الهدف YYYY-MM-DD — إن وُجد يُصفّى إليه */
    targetDate?: string;
};

export type SourceCounts = Record<ScheduleItemSource, number>;

export type TravelConflictDetail = {
    prevTitle: string;
    currTitle: string;
    prevLocation: string;
    currLocation: string;
    gapMinutes: number;
};

export type CrossSectionConflictResult = {
    items: UnifiedScheduleItem[];
    totalCount: number;
    sourceCounts: SourceCounts;
    isOverloaded: boolean;
    hasLocationMismatch: boolean;
    hasTravelConflict: boolean;
    distinctLocations: string[];
    travelConflict: TravelConflictDetail | null;
    warningMessage: string | null;
    travelWarning: string | null;
    hasConflict: boolean;
};

const OVERLOAD_THRESHOLD = 3;
const TRAVEL_GAP_MINUTES = 60;

const EMPTY_SOURCE_COUNTS = (): SourceCounts => ({
    HEARING: 0,
    TRANSACTION: 0,
    TASK: 0,
});

function normalizeYmd(date: string): string {
    return String(date ?? '').trim().slice(0, 10);
}

/** تطبيع موقع للمقارنة والعرض — فراغات مضغوطة */
export function normalizeLocation(location: string | undefined | null): string {
    return String(location ?? '')
        .trim()
        .replace(/\s+/g, ' ');
}

function timeToMinutes(time: string | undefined): number | null {
    const raw = String(time ?? '').trim();
    if (!raw) return null;
    const m = raw.match(/^(\d{1,2}):(\d{2})/);
    if (!m) return null;
    const h = Number(m[1]);
    const min = Number(m[2]);
    if (!Number.isFinite(h) || !Number.isFinite(min)) return null;
    return h * 60 + min;
}

function pushSource(
    out: UnifiedScheduleItem[],
    seenIds: Set<string>,
    rows:
        | Array<{
              id: string;
              title: string;
              date: string;
              location?: string;
              time?: string;
              isCompleted?: boolean;
              durationMinutes?: number;
          }>
        | undefined,
    source: ScheduleItemSource,
    targetDate: string | undefined,
): void {
    if (!rows?.length) return;
    for (const row of rows) {
        if (row.isCompleted) continue;
        const date = normalizeYmd(row.date);
        if (!date) continue;
        if (targetDate && date !== targetDate) continue;
        const id = String(row.id ?? '').trim();
        if (!id || seenIds.has(id)) continue;
        seenIds.add(id);
        const location = normalizeLocation(row.location) || undefined;
        const time = String(row.time ?? '').trim() || undefined;
        out.push({
            id,
            title: String(row.title ?? '').trim() || 'موعد',
            date,
            location,
            time,
            source,
            durationMinutes: row.durationMinutes,
        });
    }
}

function sourceLabelAr(source: ScheduleItemSource): string {
    switch (source) {
        case 'HEARING':
            return 'جلسات/مواعيد';
        case 'TRANSACTION':
            return 'معاملات';
        case 'TASK':
            return 'مهام';
    }
}

function formatSourceBreakdown(counts: SourceCounts): string {
    const parts: string[] = [];
    (['HEARING', 'TRANSACTION', 'TASK'] as ScheduleItemSource[]).forEach((key) => {
        if (counts[key] > 0) parts.push(`${counts[key]} ${sourceLabelAr(key)}`);
    });
    return parts.join('، ');
}

function findTravelConflict(items: UnifiedScheduleItem[]): TravelConflictDetail | null {
    const timed = items
        .map((item) => ({ item, minutes: timeToMinutes(item.time) }))
        .filter((row): row is { item: UnifiedScheduleItem; minutes: number } => row.minutes !== null)
        .sort((a, b) => a.minutes - b.minutes);

    for (let i = 1; i < timed.length; i++) {
        const prev = timed[i - 1];
        const curr = timed[i];
        const prevDuration =
            prev.item.durationMinutes != null
                ? resolveScheduleItemDurationMinutes(prev.item.source, prev.item.durationMinutes)
                : 0;
        const gap = curr.minutes - (prev.minutes + prevDuration);
        const prevLoc = normalizeLocation(prev.item.location);
        const currLoc = normalizeLocation(curr.item.location);
        if (
            gap >= 0 &&
            gap < TRAVEL_GAP_MINUTES &&
            prevLoc &&
            currLoc &&
            prevLoc !== currLoc
        ) {
            return {
                prevTitle: prev.item.title,
                currTitle: curr.item.title,
                prevLocation: prevLoc,
                currLocation: currLoc,
                gapMinutes: gap,
            };
        }
    }
    return null;
}

function buildArabicWarning(
    totalCount: number,
    sourceCounts: SourceCounts,
    isOverloaded: boolean,
    hasLocationMismatch: boolean,
    distinctLocations: string[],
): string | null {
    if (!isOverloaded && !hasLocationMismatch) return null;

    const parts: string[] = [];
    const breakdown = formatSourceBreakdown(sourceCounts);
    if (isOverloaded) {
        parts.push(
            `إثقال عمل: ${totalCount} بنود مجدولة في هذا اليوم (أكثر من ${OVERLOAD_THRESHOLD}${
                breakdown ? ` — ${breakdown}` : ''
            }).`,
        );
    }
    if (hasLocationMismatch) {
        parts.push(
            `تعارض مواقع: ${distinctLocations.length} مواقع مختلفة (${distinctLocations.join('، ')}).`,
        );
    }
    return parts.join(' ');
}

function buildTravelWarning(detail: TravelConflictDetail | null): string | null {
    if (!detail) return null;
    return `تعارض زمني/مكاني: "${detail.prevTitle}" ثم "${detail.currTitle}" (فارق ${detail.gapMinutes} د) — من «${detail.prevLocation}» إلى «${detail.currLocation}».`;
}

/**
 * يوحّد جلسات + معاملات + مهام ليوم واحد، ويكشف الإثقال وتعارض المواقع والتنقّل الضيق.
 */
export function detectCrossSectionConflicts(
    input: CrossSectionConflictInput,
): CrossSectionConflictResult {
    const targetDate = input.targetDate ? normalizeYmd(input.targetDate) : undefined;
    const items: UnifiedScheduleItem[] = [];
    const seenIds = new Set<string>();
    pushSource(items, seenIds, input.hearings, 'HEARING', targetDate);
    pushSource(items, seenIds, input.transactions, 'TRANSACTION', targetDate);
    pushSource(items, seenIds, input.tasks, 'TASK', targetDate);

    const sourceCounts = EMPTY_SOURCE_COUNTS();
    for (const item of items) sourceCounts[item.source] += 1;

    const totalCount = items.length;
    const isOverloaded = totalCount > OVERLOAD_THRESHOLD;

    const locationSet = new Set<string>();
    for (const item of items) {
        const loc = normalizeLocation(item.location);
        if (loc) locationSet.add(loc);
    }
    const distinctLocations = [...locationSet];
    const hasLocationMismatch = distinctLocations.length > 1;

    const travelConflict = findTravelConflict(items);
    const hasTravelConflict = travelConflict !== null;
    const travelWarning = buildTravelWarning(travelConflict);

    const warningMessage = buildArabicWarning(
        totalCount,
        sourceCounts,
        isOverloaded,
        hasLocationMismatch,
        distinctLocations,
    );

    return {
        items,
        totalCount,
        sourceCounts,
        isOverloaded,
        hasLocationMismatch,
        hasTravelConflict,
        distinctLocations,
        travelConflict,
        warningMessage,
        travelWarning,
        hasConflict: Boolean(warningMessage) || hasTravelConflict,
    };
}


export type CalendarLikeEvent = {
    id: string;
    title: string;
    date: string;
    location?: string;
    court?: string;
    time?: string;
    endTime?: string;
    durationMinutes?: number;
    type?: string;
    source?: string;
    isCompleted?: boolean;
    bridge?: { sourceModule?: string } | null;
};

/**
 * يحلّل أحداث التقويم الموحّدة ليوم محدد (ما يظهر فعلاً في الرادار).
 */
export function detectConflictsFromUnifiedEvents(
    events: CalendarLikeEvent[],
    targetDate?: string,
): CrossSectionConflictResult {
    const hearings: CrossSectionConflictInput['hearings'] = [];
    const transactions: CrossSectionConflictInput['transactions'] = [];
    const tasks: CrossSectionConflictInput['tasks'] = [];

    for (const ev of events) {
        if (ev.isCompleted) continue;
        const source = mapCalendarModuleToScheduleSource(
            ev.bridge?.sourceModule,
            ev.source,
            ev.type,
        );
        const location =
            normalizeLocation(ev.location) || normalizeLocation(ev.court) || undefined;
        const explicitDuration = resolveExplicitCalendarEventDurationMinutes(ev);
        const row = {
            id: ev.id,
            title: ev.title,
            date: normalizeYmd(ev.date),
            location,
            time: ev.time,
            isCompleted: false,
            durationMinutes: explicitDuration ?? undefined,
        };
        if (source === 'TRANSACTION') transactions!.push(row);
        else if (source === 'TASK') tasks!.push(row);
        else hearings!.push(row);
    }

    return detectCrossSectionConflicts({
        hearings,
        transactions,
        tasks,
        targetDate,
    });
}

/**
 * تصنيف عنصر الجدول ومدّته الافتراضية — أوّليات نقية بلا اعتماديات.
 *
 * كانت تسكن `scheduleConflictDetector`، فاضطر `calendarDurationUtils` إلى
 * استيرادها منه بينما الكاشف يستورد منه المدّة الصريحة — دائرة استيراد كاملة
 * بين ملفين. فصلها هنا يجعل الاتجاه واحداً: كلاهما يستورد من هذه الورقة.
 */
export type ScheduleItemSource = 'HEARING' | 'TRANSACTION' | 'TASK';

const DEFAULT_DURATION_MINUTES: Record<ScheduleItemSource, number> = {
    HEARING: 60,
    TRANSACTION: 45,
    TASK: 30,
};

export function resolveScheduleItemDurationMinutes(
    source: ScheduleItemSource,
    explicitMinutes?: number | null,
): number {
    const raw = Number(explicitMinutes);
    if (Number.isFinite(raw) && raw > 0) return Math.round(raw);
    return DEFAULT_DURATION_MINUTES[source];
}

/** خريطة مصدر الجسر → تصنيف الكاشف */
export function mapCalendarModuleToScheduleSource(
    sourceModule: string | null | undefined,
    fallbackSource?: string | null,
    eventType?: string | null,
): ScheduleItemSource {
    const mod = String(sourceModule ?? '').trim().toLowerCase();
    if (mod === 'transaction' || mod === 'threading') return 'TRANSACTION';
    if (mod === 'task' || mod === 'note') return 'TASK';
    if (mod === 'lawsuit' || mod === 'execution' || mod === 'criminal' || mod === 'urgent') {
        return 'HEARING';
    }
    const fb = String(fallbackSource ?? '').trim().toLowerCase();
    if (fb === 'hearing' || fb === 'deadline') return 'HEARING';
    const typ = String(eventType ?? '').trim().toLowerCase();
    if (typ === 'consultation' || typ === 'deadline') return 'TASK';
    if (typ === 'execution') return 'HEARING';
    return 'HEARING';
}

import { describe, expect, it } from 'vitest';
import {
    applyShareAccessPolicy,
    canFetchShareDetail,
    toShareListSummary,
} from '../caseShareAccessControl';
import type { CaseShareRecord } from '../caseShareTypes';
import { fieldsWith, PERSONAS, richLawsuitSource } from './caseShareTestFixtures';
import { buildMaskedView } from '../caseShareMasking';

function buildPendingShare(): CaseShareRecord {
    const source = richLawsuitSource();
    const maskedView = buildMaskedView(source, fieldsWith({}), PERSONAS.sender.name, 60);
    return {
        id: 'share-1',
        ownerId: PERSONAS.sender.id,
        ownerName: PERSONAS.sender.name,
        recipientId: PERSONAS.recipient.id,
        recipientName: PERSONAS.recipient.name,
        dossierModule: source.module,
        dossierId: source.dossierId,
        dossierTitle: source.title,
        visibleFields: fieldsWith({}),
        maskedView,
        status: 'pending',
        createdAt: new Date().toISOString(),
        sessionDurationMinutes: 60,
    };
}

describe('caseShareAccessControl', () => {
    it('يخفي تفاصيل الإضبارة عن المستقبل قبل الموافقة', () => {
        const share = buildPendingShare();
        const sanitized = applyShareAccessPolicy(share, PERSONAS.recipient.id);

        expect(sanitized.maskedView.parties).toEqual([]);
        expect(sanitized.maskedView.caseNumbers).toEqual([]);
        expect(sanitized.maskedView.visibleCatalog).toEqual([]);
        expect(sanitized.dossierId).toBe('');
        expect(sanitized.maskedView.narrative).toContain('بعد الموافقة');
    });

    it('يُبقي المرسل يرى المعاينة المقنّعة كما أرسلها', () => {
        const share = buildPendingShare();
        const forSender = applyShareAccessPolicy(share, PERSONAS.sender.id);
        expect(forSender.maskedView.parties.length).toBeGreaterThan(0);
        expect(forSender.dossierId).toBeTruthy();
    });

    it('قائمة الإشعارات لا تحتوي محتوى حساساً', () => {
        const share = buildPendingShare();
        const summary = toShareListSummary(share, PERSONAS.sender.id);
        expect(summary.maskedView.visibleCatalog).toEqual([]);
        expect(summary.maskedView.caseNumbers).toEqual([]);
        expect(summary.maskedView.parties).toEqual([]);
    });

    it('يمنع جلب التفاصيل قبل موافقة المستقبل', () => {
        const share = buildPendingShare();
        expect(canFetchShareDetail(share, PERSONAS.recipient.id)).toBe(false);
        expect(canFetchShareDetail(share, PERSONAS.sender.id)).toBe(true);
    });

    it('يسحب المحتوى الحساس من المستقبل بعد إنهاء الجلسة', () => {
        const share = buildPendingShare();
        const accepted = {
            ...share,
            status: 'accepted' as const,
            sessionStartedAt: new Date(Date.now() - 3_600_000).toISOString(),
            sessionDurationMinutes: 60,
        };
        const ended = {
            ...accepted,
            status: 'ended' as const,
            sessionEndedAt: new Date().toISOString(),
        };

        const sanitized = applyShareAccessPolicy(ended, PERSONAS.recipient.id);
        expect(sanitized.maskedView.parties).toEqual([]);
        expect(sanitized.maskedView.caseNumbers).toEqual([]);
        expect(sanitized.maskedView.visibleCatalog).toEqual([]);
        expect(sanitized.dossierId).toBe('');
        expect(canFetchShareDetail(ended, PERSONAS.recipient.id)).toBe(false);
        expect(canFetchShareDetail(ended, PERSONAS.sender.id)).toBe(true);
    });
});

/**
 * CaseShare في PROD: فشل API → fail-closed بلا سقوط إلى المستودع المحلي.
 * list/detail → [] / null؛ mutations → throw.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';

const fetchSecure = vi.fn();
const updateStatus = vi.fn();
const endSession = vi.fn();
const listForUser = vi.fn();
const getById = vi.fn();
const createShare = vi.fn();

vi.mock('@/app/services/SecureAPIClient', () => ({
    SecureAPIClient: {
        fetchSecure: (...args: unknown[]) => fetchSecure(...args),
    },
}));

vi.mock('../caseShareRepository', () => ({
    CaseShareRepository: {
        updateStatus: (...args: unknown[]) => updateStatus(...args),
        endSession: (...args: unknown[]) => endSession(...args),
        createShare: (...args: unknown[]) => createShare(...args),
        listForUser: (...args: unknown[]) => listForUser(...args),
        getById: (...args: unknown[]) => getById(...args),
    },
}));

vi.mock('../caseShareNetworkGuard', () => ({
    assertRecipientInNetwork: vi.fn().mockResolvedValue(true),
}));

vi.mock('@/app/services/settings/collaborationNetworkGate', () => ({
    canReachCollaborationNetwork: () => true,
    COLLABORATION_NETWORK_OFF: 'COLLABORATION_NETWORK_OFF',
    assertCollaborationNetworkReachable: () => undefined,
}));

import { CaseShareApiService } from '../caseShareApiService';

describe('CaseShareApiService — PROD fail-closed', () => {
    beforeEach(() => {
        vi.clearAllMocks();
        vi.stubEnv('PROD', true);
        vi.stubEnv('DEV', false);
        vi.stubEnv('MODE', 'production');
    });

    afterEach(() => {
        vi.unstubAllEnvs();
    });

    it('listShares: API failure in PROD returns [] and does not call repository', async () => {
        fetchSecure.mockRejectedValue(new Error('NETWORK'));
        await expect(CaseShareApiService.listShares('user-1')).resolves.toEqual([]);
        expect(listForUser).not.toHaveBeenCalled();
    });

    it('listShares: empty/malformed API payload in PROD returns [] without repository', async () => {
        fetchSecure.mockResolvedValue({ ok: true, shares: null });
        await expect(CaseShareApiService.listShares('user-1')).resolves.toEqual([]);
        expect(listForUser).not.toHaveBeenCalled();
    });

    it('getShareDetail: API failure in PROD returns null and does not call repository', async () => {
        fetchSecure.mockRejectedValue(new Error('NETWORK'));
        await expect(CaseShareApiService.getShareDetail('share-1', 'user-1')).resolves.toBeNull();
        expect(getById).not.toHaveBeenCalled();
    });

    it('getShareDetail: missing share in PROD returns null without repository', async () => {
        fetchSecure.mockResolvedValue({ ok: true });
        await expect(CaseShareApiService.getShareDetail('share-1', 'user-1')).resolves.toBeNull();
        expect(getById).not.toHaveBeenCalled();
    });

    it('listShares: DEV keeps local repository fallback', async () => {
        vi.stubEnv('PROD', false);
        vi.stubEnv('DEV', true);
        vi.stubEnv('MODE', 'development');
        fetchSecure.mockRejectedValue(new Error('NETWORK'));
        listForUser.mockResolvedValue([{ id: 'local-1' }]);
        await expect(CaseShareApiService.listShares('user-1')).resolves.toEqual([{ id: 'local-1' }]);
