    return file;
}

export function buildRichExecutionFile(): ExecutionFile {
    return {
        id: 'exec-9001',
        directorate: 'مديرية تنفيذ الرصافة',
        fileNumber: '1540',
        fileYear: '2026',
        claimType: 'استحصال دين مالي',
        documentType: 'حكم نهائي',
        docNumber: '8821/2025',
        lifecycleStatus: 'active',
        notes: 'ملاحظة تنفيذية سرية',
