import type { CaseShareRecord, CaseShareVisibleFields } from './caseShareTypes';
import { isCaseShareSessionActive, isCaseShareSessionExpired } from './caseShareSession';

/** ملخص فقط — قبل موافقة المستقبل */
export function buildPendingRecipientPreview(share: CaseShareRecord): CaseShareRecord['maskedView'] {
    return {
        module: share.dossierModule,
        dossierId: '',
        title: share.maskedView.title,
        caseNumbers: [],
        parties: [],
        court: '—',
        narrative: 'تفاصيل الإضبارة متاحة بعد الموافقة على طلب الاستشارة.',
        documentsIncluded: false,
        ownerDisplayName: share.ownerName,
        visibleCatalog: [],
        sessionDurationMinutes: share.sessionDurationMinutes ?? share.maskedView.sessionDurationMinutes,
    };
}

const EMPTY_VISIBLE_FIELDS: CaseShareVisibleFields = {
    documents: false,
    case_numbers: false,
    parties_names: 'hidden',
    court_details: 'hidden',
    hiddenItemIds: [],
};

/** بعد انتهاء/رفض الجلسة — للمستقبل فقط */
function buildEndedRecipientPreview(share: CaseShareRecord): CaseShareRecord['maskedView'] {
    return {
        module: share.dossierModule,
        dossierId: '',
        title: share.maskedView.title,
        caseNumbers: [],
        parties: [],
        court: '—',
        narrative: 'انتهت الجلسة — لم يعد بإمكانك عرض تفاصيل الإضبارة.',
        documentsIncluded: false,
        ownerDisplayName: share.maskedView.ownerDisplayName ?? share.ownerName,
        visibleCatalog: [],
        sessionDurationMinutes: share.sessionDurationMinutes ?? share.maskedView.sessionDurationMinutes,
    };
}

function stripRecipientSensitiveView(share: CaseShareRecord, viewerId: string): CaseShareRecord {
    if (share.ownerId === viewerId) return share;
    return {
        ...share,
        dossierId: '',
        visibleFields: EMPTY_VISIBLE_FIELDS,
        maskedView: buildEndedRecipientPreview(share),
    };
}

/** يمنع تسريب maskedView قبل الموافقة وبعد إنهاء الجلسة */
export function applyShareAccessPolicy(share: CaseShareRecord, viewerId: string): CaseShareRecord {
    let next = share;

    if (next.status === 'accepted' && isCaseShareSessionExpired(next)) {
        next = {
            ...next,
            status: 'ended',
            sessionEndedAt: next.sessionEndedAt ?? new Date().toISOString(),
            endedByUserId: next.endedByUserId ?? 'system:expired',
        };
    }

    if (next.status === 'pending' && next.recipientId === viewerId) {
        return {
            ...next,
            dossierId: '',
            visibleFields: EMPTY_VISIBLE_FIELDS,
            maskedView: buildPendingRecipientPreview(next),
        };
    }

    if (next.recipientId === viewerId && next.status === 'declined') {
        return stripRecipientSensitiveView(next, viewerId);
    }

    if (next.recipientId === viewerId && next.status === 'ended') {
        return stripRecipientSensitiveView(next, viewerId);
    }

    if (next.status === 'accepted' && next.recipientId === viewerId && !isCaseShareSessionActive(next)) {
        return stripRecipientSensitiveView(next, viewerId);
    }

    return next;
}

export function applyShareListAccessPolicy(shares: CaseShareRecord[], viewerId: string): CaseShareRecord[] {
    return shares.map((s) => applyShareAccessPolicy(s, viewerId));
}

const LIST_SUMMARY_VISIBLE_FIELDS: CaseShareVisibleFields = {
    documents: false,
    case_numbers: false,
    parties_names: 'hidden',
    court_details: 'hidden',
    hiddenItemIds: [],
};

/** قائمة الإشعارات — بدون محتوى حساس (defense in depth) */
export function toShareListSummary(share: CaseShareRecord, viewerId: string): CaseShareRecord {
    const policy = applyShareAccessPolicy(share, viewerId);
    const ownerPreview = policy.ownerId === viewerId && policy.status !== 'declined';

    return {
        ...policy,
        dossierId: ownerPreview ? policy.dossierId : '',
        visibleFields: LIST_SUMMARY_VISIBLE_FIELDS,
        maskedView: {
            module: policy.maskedView.module,
            dossierId: '',
            title: policy.maskedView.title,
            caseNumbers: [],
            parties: [],
            court: '—',
            narrative:
                policy.status === 'pending' && policy.recipientId === viewerId
                    ? policy.maskedView.narrative
                    : '',
            documentsIncluded: policy.maskedView.documentsIncluded,
            ownerDisplayName: policy.maskedView.ownerDisplayName ?? policy.ownerName,
            visibleCatalog: [],
            sessionDurationMinutes: policy.sessionDurationMinutes ?? policy.maskedView.sessionDurationMinutes,
        },
    };
}

/** تفاصيل كاملة — فقط أثناء جلسة نشطة للمستقبل، أو للمرسل */
export function canFetchShareDetail(share: CaseShareRecord, viewerId: string): boolean {
    if (share.ownerId !== viewerId && share.recipientId !== viewerId) return false;
    if (share.recipientId === viewerId && share.status === 'pending') return false;
    if (share.recipientId === viewerId && (share.status === 'ended' || share.status === 'declined')) {
        return false;
    }
    if (
        share.recipientId === viewerId &&
        share.status === 'accepted' &&
        !isCaseShareSessionActive(share)
    ) {
        return false;
    }
    return true;
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import {
    assertCollaborationNetworkReachable,
    canReachCollaborationNetwork,
} from '@/app/services/settings/collaborationNetworkGate';
import type {
    CaseShareRecord,
    CaseShareVisibleFields,
    DossierShareSource,
} from './caseShareTypes';
import { CaseShareRepository } from './caseShareRepository';
import { assertRecipientInNetwork } from './caseShareNetworkGuard';
import { listNetworkColleagues } from './lawyerNetworkRepository';
import {
    assertShareSourceOwnedByUser,
    ShareSourceOwnershipError,
} from './caseShareDossierOwnership';
import { registerCriminalCaseOwnershipOnServer } from './caseShareCriminalOwnershipApi';

type ApiOk<T> = { ok: true } & T;

async function postJson<T>(path: string, body: Record<string, unknown>): Promise<T> {
    return SecureAPIClient.fetchSecure<T>(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
    });
}

export class CaseShareApiService {
    static async listNetworkColleagues(userId: string) {
        if (!canReachCollaborationNetwork()) return [];
        return listNetworkColleagues(userId);
    }

    static async listShares(userId: string): Promise<CaseShareRecord[]> {
        if (!canReachCollaborationNetwork()) {
            return CaseShareRepository.listForUser(userId, { summary: true });
        }
        try {
            const res = await SecureAPIClient.fetchSecure<ApiOk<{ shares: CaseShareRecord[] }>>(
                '/api/case-share',
                { method: 'GET' },
            );
            if (Array.isArray(res.shares)) return res.shares;
            if (import.meta.env.PROD) return [];
        } catch {
            if (import.meta.env.PROD) return [];
            /* DEV: repository fallback below */
        }
        return CaseShareRepository.listForUser(userId, { summary: true });
    }

    static async getShareDetail(shareId: string, userId: string): Promise<CaseShareRecord | null> {
        if (!canReachCollaborationNetwork()) {
            return CaseShareRepository.getById(shareId, userId);
        }
        try {
            const res = await SecureAPIClient.fetchSecure<ApiOk<{ share: CaseShareRecord }>>(
                `/api/case-share/detail?shareId=${encodeURIComponent(shareId)}`,
                { method: 'GET' },
            );
            if (res.share) return res.share;
            if (import.meta.env.PROD) return null;
        } catch {
            if (import.meta.env.PROD) return null;
            /* DEV: repository fallback below */
        }
        return CaseShareRepository.getById(shareId, userId);
    }

    static async listIncoming(userId: string): Promise<CaseShareRecord[]> {
        const all = await this.listShares(userId);
        return all.filter((s) => s.recipientId === userId);
    }

    static async createShare(params: {
        recipientId: string;
        recipientName: string;
        source: DossierShareSource;
        visibleFields: CaseShareVisibleFields;
        ownerId: string;
        ownerName: string;
        sessionDurationMinutes?: number;
    }): Promise<CaseShareRecord> {
        assertCollaborationNetworkReachable();
        const inNetwork = await assertRecipientInNetwork(params.ownerId, params.recipientId);
        if (!inNetwork) {
            throw new Error('RECIPIENT_NOT_IN_NETWORK');
        }
        try {
            if (params.source.module === 'criminal') {
                await assertShareSourceOwnedByUser(params.ownerId, params.source);
                await registerCriminalCaseOwnershipOnServer(params.source.dossierId);
            }
            const res = await postJson<ApiOk<{ share: CaseShareRecord }>>('/api/case-share', {
                action: 'create',
                recipientId: params.recipientId,
                recipientName: params.recipientName,
                source: params.source,
                visibleFields: params.visibleFields,
                ownerName: params.ownerName,
                sessionDurationMinutes: params.sessionDurationMinutes,
            });
            if (res.share) return res.share;
            throw new Error('CREATE_SHARE_EMPTY');
        } catch (err) {
            if (err instanceof ShareSourceOwnershipError) throw err;
            if (import.meta.env.PROD) {
                throw err;
            }
            return CaseShareRepository.createShare(params);
        }
    }

    static async respond(shareId: string, action: 'accept' | 'decline', userId: string): Promise<void> {
        assertCollaborationNetworkReachable();
        try {
            const res = await postJson<ApiOk<{ share: CaseShareRecord }>>('/api/case-share', {
                action,
                shareId,
            });
            if (!res.share) throw new Error('RESPOND_FAILED');
            return;
        } catch (err) {
            if (import.meta.env.PROD) {
                throw err;
            }
            const updated = await CaseShareRepository.updateStatus(
                shareId,
                userId,
                action === 'accept' ? 'accepted' : 'declined',
            );
            if (!updated) throw new Error('SHARE_NOT_FOUND');
        }
    }

    static async endSession(shareId: string, userId: string): Promise<CaseShareRecord | null> {
        assertCollaborationNetworkReachable();
        try {
            const res = await postJson<ApiOk<{ share: CaseShareRecord }>>('/api/case-share', {
                action: 'end',
                shareId,
            });
            if (res.share) return res.share;
            throw new Error('END_SESSION_EMPTY');
        } catch (err) {
            if (import.meta.env.PROD) {
                throw err;
            }
            return CaseShareRepository.endSession(shareId, userId);
        }
    }
}

import type { ExecutionFile } from '@/app/types/execution';
import type { FileData, CaseStage } from '@/app/components/lawyer/LawyerShared';
import type { CriminalCase } from '@/app/components/lawyer/criminal-system/criminalStore';
import { readExecutorDecisionsFromActiveNamespace } from '@/app/utils/executionDecisionsNamespace';
import { executionDocumentsStorageKey } from '@/app/utils/executionStorageKeysLite';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';
import type { ShareCatalogItem, ShareCatalogSection } from './caseShareTypes';
import { EXECUTION_CONSULT_SECTION_DEFS } from './caseShareTypes';

function clip(text: string | undefined, max = 100): string {
    const t = String(text ?? '').trim();
    if (!t) return '';
    return t.length <= max ? t : `${t.slice(0, max)}…`;
}

function timelineKind(type: string, isAttachment?: boolean): ShareCatalogItem['kind'] {
    if (isAttachment || type === 'document') return 'document';
    if (type === 'appointment') return 'hearing';
    return 'timeline';
}

function isFollowupEvent(ev: { type?: string; title?: string; source?: string }): boolean {
    const source = String(ev.source ?? '').toLowerCase();
    const title = String(ev.title ?? '');
    const type = String(ev.type ?? '').toLowerCase();
    return source.includes('followup') || type.includes('followup') || title.includes('محضر');
}

function isDecisionEvent(type: string): boolean {
    return type === 'decision' || type === 'appeal' || type === 'coercive';
}

function isDocumentEvent(ev: { type?: string; isAttachment?: boolean }): boolean {
    return Boolean((ev as { isAttachment?: boolean }).isAttachment) || String(ev.type ?? '') === 'document';
}

function readStoredExecutionDocuments(executionId: string): ShareCatalogItem[] {
    try {
        const raw = readSecureOrDrainLegacySync(executionDocumentsStorageKey(executionId));
        if (!raw) return [];
        const parsed = JSON.parse(raw) as unknown;
        if (!Array.isArray(parsed)) return [];
        return parsed.map((row, i) => {
            const doc = row as Record<string, unknown>;
            return {
                id: `ex:doc:store:${String(doc.id ?? i)}`,
                kind: 'document' as const,
                label: String(doc.name ?? doc.title ?? doc.fileName ?? `مستند ${i + 1}`).trim(),
                preview: clip(String(doc.type ?? doc.category ?? doc.mimeType ?? '')),
            };
        });
    } catch {
        return [];
    }
}

function readStoredExecutionDecisions(file: ExecutionFile): ShareCatalogItem[] {
    const rows = readExecutorDecisionsFromActiveNamespace(file.id, file as unknown as Record<string, unknown>);
    return rows.map((row, i) => {
        const title = String(row.title ?? row.requestKind ?? row.kind ?? `قرار ${i + 1}`).trim();
        const status = String(row.outcome ?? row.status ?? '').trim();
        return {
            id: `ex:dec:${String(row.id ?? row.decisionId ?? i)}`,
            kind: 'timeline' as const,
            label: title,
            preview: clip([status, row.date, row.createdAt].filter(Boolean).join(' · ')),
        };
    });
}

/** يضمن ظهور كل أقسام شبكة أدوات التنفيذ في واجهة الاستشارة */
export function normalizeExecutionConsultCatalog(catalog: ShareCatalogSection[]): ShareCatalogSection[] {
    const byKey = new Map(catalog.map((section) => [section.key, section]));
    return EXECUTION_CONSULT_SECTION_DEFS.map(({ key, title }) => {
        const existing = byKey.get(key);
        return existing ? { ...existing, title } : { key, title, items: [] };
    });
}

export function buildLawsuitShareCatalog(file: FileData, stage?: CaseStage | null): ShareCatalogSection[] {
    const activeStage = stage ?? file.stages?.[file.activeStageIndex ?? 0] ?? file.stages?.[0];
    const stages = file.stages?.length ? file.stages : activeStage ? [activeStage] : [];

    const timelineItems: ShareCatalogItem[] = [];
    stages.forEach((st, si) => {
        const stageLabel = String(st.stageName ?? st.name ?? `مرحلة ${si + 1}`);
        (st.timeline ?? [])
            .filter((ev) => !ev.isDeleted)
            .forEach((ev) => {
                timelineItems.push({
                    id: `tl:${si}:${ev.id}`,
                    kind: timelineKind(String(ev.type ?? ''), Boolean(ev.isAttachment)),
                    label: `${stageLabel} — ${ev.title || 'حدث'}`,
                    preview: clip([ev.date, ev.time, ev.details].filter(Boolean).join(' · ')),
                });
            });
    });

    const noteItems: ShareCatalogItem[] = (file.notes ?? []).map((n) => ({
        id: `note:${n.id}`,
        kind: 'note',
        label: n.meta?.trim() || n.stageCtx?.trim() || 'ملاحظة',
        preview: clip(n.text),
    }));

    const docItems: ShareCatalogItem[] = [];
    (file.images ?? []).forEach((img, i) => {
        docItems.push({
            id: `doc:img:${i}`,
            kind: 'document',
            label: img.name?.trim() || `مرفق ${i + 1}`,
            preview: clip(img.name),
        });
    });
    stages.forEach((st, si) => {
        (st.timeline ?? [])
            .filter((ev) => !ev.isDeleted && (ev.isAttachment || ev.type === 'document'))
            .forEach((ev) => {
                docItems.push({
                    id: `doc:tl:${si}:${ev.id}`,
                    kind: 'document',
                    label: `${st.stageName ?? 'مرحلة'} — ${ev.title || 'مستند'}`,
                    preview: clip(ev.details),
                });
            });
    });

    const partyItems: ShareCatalogItem[] = (activeStage?.parties ?? file.parties ?? []).map((p, i) => ({
        id: `party:${p.id ?? i}`,
        kind: 'meta',
        label: p.name?.trim() || `طرف ${i + 1}`,
        preview: p.role,
    }));

    const metaItems: ShareCatalogItem[] = [];
    const caseNo = activeStage?.caseNo ?? file.caseNo;
    if (caseNo?.trim()) {
        metaItems.push({ id: 'meta:caseNo', kind: 'meta', label: 'رقم الدعوى', preview: caseNo });
    }
    const court = activeStage?.court ?? file.court;
    if (court?.trim()) {
        metaItems.push({ id: 'meta:court', kind: 'meta', label: 'المحكمة', preview: court });
    }
    if (file.subInfo?.trim()) {
        metaItems.push({ id: 'meta:subInfo', kind: 'meta', label: 'معلومات إضافية', preview: clip(file.subInfo) });
    }

    const sections: ShareCatalogSection[] = [];
    if (timelineItems.length) sections.push({ key: 'timeline', title: 'السجل الزمني والجلسات', items: timelineItems });
    if (noteItems.length) sections.push({ key: 'notes', title: 'الملاحظات', items: noteItems });
    if (docItems.length) sections.push({ key: 'documents', title: 'المستندات والمرفقات', items: docItems });
    if (partyItems.length) sections.push({ key: 'parties', title: 'الأطراف', items: partyItems });
    if (metaItems.length) sections.push({ key: 'meta', title: 'بيانات الإضبارة', items: metaItems });
    if (court?.trim()) {
        sections.push({
            key: 'court',
            title: 'المحكمة والقاضي',
            items: [{ id: 'court:main', kind: 'meta', label: court, preview: file.subInfo }],
        });
    }
    return sections;
}

export function buildExecutionShareCatalog(file: ExecutionFile): ShareCatalogSection[] {
    const events = (file.timelineEvents ?? []).filter((ev) => !ev.trashedAt);

    const followupItems: ShareCatalogItem[] = [];
    const decisionItems: ShareCatalogItem[] = readStoredExecutionDecisions(file);
    const appointmentItems: ShareCatalogItem[] = [];
    const documentItems: ShareCatalogItem[] = readStoredExecutionDocuments(file.id);
    const timelineItems: ShareCatalogItem[] = [];

    events.forEach((ev, i) => {
        const id = `ex:tl:${ev.id ?? i}`;
        const type = String(ev.type ?? '');
        const item: ShareCatalogItem = {
            id,
            kind: timelineKind(type, false),
            label: ev.title?.trim() || `حدث ${i + 1}`,
            preview: clip([ev.date, ev.description ?? ev.details].filter(Boolean).join(' · ')),
        };

        if (isFollowupEvent(ev)) {
            followupItems.push(item);
            return;
        }
        if (isDecisionEvent(type)) {
            decisionItems.push(item);
            return;
        }
        if (type === 'appointment') {
            appointmentItems.push(item);
            return;
        }
        if (isDocumentEvent(ev)) {
            documentItems.push(item);
            return;
        }
        timelineItems.push(item);
    });

    const noteItems: ShareCatalogItem[] = [];
    (file.caseNotesLog ?? [])
        .filter((n) => !n.trashedAt)
        .forEach((n) => {
            noteItems.push({
                id: `ex:note:${n.id}`,
                kind: 'note',
                label: n.title?.trim() || 'ملاحظة',
                preview: clip(n.body),
            });
        });
    const executionNotes = typeof file.notes === 'string' ? file.notes.trim() : '';
    if (executionNotes) {
        noteItems.push({
            id: 'ex:note:main',
            kind: 'note',
            label: 'ملاحظات الإضبارة',
            preview: clip(executionNotes),
        });
    }

    (file.caseTasksPending ?? [])
        .filter((t) => !t.trashedAt)
        .forEach((t) => {
            if (t.dueDate?.trim()) {
                appointmentItems.push({
                    id: `ex:appt:task:${t.id}`,
                    kind: 'hearing',
                    label: t.title?.trim() || 'موعد مهمة',
                    preview: clip([t.dueDate, t.body].filter(Boolean).join(' · ')),
                });
            } else {
                noteItems.push({
                    id: `ex:task:${t.id}`,
                    kind: 'note',
                    label: t.title?.trim() || 'مهمة',
                    preview: clip(t.body),
                });
            }
        });

    const financialItems: ShareCatalogItem[] = (file.financialLedger ?? []).map((entry, i) => ({
        id: `ex:fin:${entry.id ?? i}`,
        kind: 'meta',
        label: entry.description?.trim() || entry.type?.trim() || `حركة مالية ${i + 1}`,
        preview: clip([entry.amount, entry.date].filter(Boolean).join(' · ')),
    }));
    if (!financialItems.length) {
        const debt = Number(file.debtAmount ?? 0);
        const paid = Number(file.paidDebt ?? 0);
        if (debt > 0 || paid > 0) {
            financialItems.push({
                id: 'ex:fin:summary',
                kind: 'meta',
                label: 'ملخص الذمة المالية',
                preview: clip(`المطلوب: ${debt} · المدفوع: ${paid}`),
            });
        }
    }

    if (file.guarantor_followup?.executor_approved) {
        followupItems.push({
            id: 'ex:followup:guarantor',
            kind: 'meta',
            label: 'طلب كفيل — محضر المتابعة',
            preview: clip(String(file.guarantor_followup.channel ?? '')),
        });
    }

    const built: ShareCatalogSection[] = [
        { key: 'followup', title: 'محضر المتابعة', items: followupItems },
        { key: 'decisions', title: 'القرارات والطعون', items: decisionItems },
        { key: 'notes', title: 'ملاحظات', items: noteItems },
        { key: 'appointments', title: 'المواعيد', items: appointmentItems },
        { key: 'documents', title: 'المستندات', items: documentItems },
        { key: 'timeline', title: 'السجل الزمني', items: timelineItems },
        { key: 'financial', title: 'المركز المالي', items: financialItems },
    ];

    return normalizeExecutionConsultCatalog(built);
}

export function buildCriminalShareCatalog(caseData: CriminalCase): ShareCatalogSection[] {
    const noteItems: ShareCatalogItem[] = [];
    const article = caseData.basics?.legalArticle;
    if (article?.trim()) {
        noteItems.push({ id: 'cr:article', kind: 'meta', label: 'المادة القانونية', preview: article });
    }

    const partyItems: ShareCatalogItem[] = [];
    (caseData.complainants ?? []).forEach((c, i) => {
        if (c.fullName?.trim()) {
            partyItems.push({ id: `cr:comp:${i}`, kind: 'meta', label: c.fullName, preview: 'شاكٍ' });
        }
    });
    (caseData.defendants ?? []).forEach((d, i) => {
        if (d.fullName?.trim()) {
            partyItems.push({ id: `cr:def:${i}`, kind: 'meta', label: d.fullName, preview: 'متهم' });
        }
    });

    const docItems: ShareCatalogItem[] = (caseData.otherEvidenceItems ?? []).map((ev, i) => ({
        id: `cr:doc:${ev.id ?? i}`,
        kind: 'document',
        label: ev.evidenceType?.trim() || ev.notes?.trim() || `دليل ${i + 1}`,
        preview: clip(ev.notes),
    }));

    const sections: ShareCatalogSection[] = [];
    if (noteItems.length) sections.push({ key: 'notes', title: 'ملخص القضية', items: noteItems });
    if (partyItems.length) sections.push({ key: 'parties', title: 'الأطراف', items: partyItems });
    if (docItems.length) sections.push({ key: 'documents', title: 'الأدلة والمستندات', items: docItems });
    return sections;
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';

type ApiOk = { ok: true; dossierId?: string };

/**
 * يسجّل إثبات ملكية جزائية على الخادم (بعد تحقق محلي من criminalStore).
 * مطلوب قبل CaseShare create عبر API للوحدة criminal.
 */
export async function registerCriminalCaseOwnershipOnServer(dossierId: string): Promise<void> {
    const id = String(dossierId ?? '').trim();
    if (!id) throw new Error('DOSSIER_ID_REQUIRED');
    const res = await SecureAPIClient.fetchSecure<ApiOk>('/api/case-share/criminal-ownership', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'register', dossierId: id }),
    });
    if (!res?.ok) throw new Error('CRIMINAL_OWNERSHIP_REGISTER_FAILED');
}

/** إلغاء إثبات الملكية بعد حذف الإضبارة — best-effort */
export async function unregisterCriminalCaseOwnershipOnServer(dossierId: string): Promise<void> {
    const id = String(dossierId ?? '').trim();
    if (!id) return;
    try {
        await SecureAPIClient.fetchSecure<ApiOk>('/api/case-share/criminal-ownership', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'unregister', dossierId: id }),
        });
    } catch {
        /* ignore — الحذف المحلي والـ revoke يبقيان المصدر */
    }
}

export function scheduleUnregisterCriminalCaseOwnership(dossierId: string | number): void {
    void unregisterCriminalCaseOwnershipOnServer(String(dossierId)).catch(() => undefined);
}

