import type { ExecutionFile } from '@/app/types/execution';

import { normalizeDossierLifecycleStatus } from '@/app/types/execution';

import type { FileData, CaseStage } from '@/app/components/lawyer/LawyerShared';

import type { CriminalCase } from '@/app/components/lawyer/criminal-system/criminalStore';

import type { CaseShareDossierModule, DossierShareSource, ExecutionShareMeta } from './caseShareTypes';

import { isPersonalStatusFile } from '@/app/components/lawyer/personal-status/personalStatusValidation';

import {

    buildCriminalShareCatalog,

    buildExecutionShareCatalog,

    buildLawsuitShareCatalog,

} from './caseShareCatalogBuilder';



function uniqueStrings(values: string[]): string[] {

    return [...new Set(values.map((v) => v.trim()).filter(Boolean))];

}



function directorateLabel(file: ExecutionFile): string {

    const d = file.directorate;

    return typeof d === 'string' ? d : String(d ?? '');

}



const LIFECYCLE_AR: Record<string, string> = {

    active: 'نشطة',

    paused: 'متوقفة',

    suspended: 'مستأخرة',

    finished: 'منتهية',

};



function buildExecutionShareMeta(file: ExecutionFile): ExecutionShareMeta {

    const lifecycle = normalizeDossierLifecycleStatus(file.dossier_lifecycle_status);

    return {

        directorate: directorateLabel(file),

        fileNumber: String(file.fileNumber ?? '').trim(),

        fileYear: String(file.fileYear ?? '').trim(),

        claimType: String(file.claimType ?? '').trim(),

        documentType: String(file.documentType ?? '').trim(),

        lifecycleStatus: LIFECYCLE_AR[lifecycle] ?? lifecycle,

        docNumber: String(file.docNumber ?? '').trim(),

    };

}



export function extractExecutionShareSource(file: ExecutionFile): DossierShareSource {
    const meta = buildExecutionShareMeta(file);
    const catalog = buildExecutionShareCatalog(file);
    const caseNumbers = uniqueStrings([
        meta.fileNumber ? `${meta.fileNumber}/${meta.fileYear ?? ''}` : '',
        meta.docNumber,
    ]);
    const ref = caseNumbers[0] ?? '';
    const title =
        meta.directorate && ref
            ? `${meta.directorate} — ${ref}`
            : ref || meta.directorate || `تنفيذ — ${file.id}`.slice(0, 120);
    return {
        module: 'execution',
        dossierId: file.id,
        title,
        caseNumbers,
        partyNames: [],
        courtLabel: meta.directorate,
        courtProvince: meta.directorate,
        narrativeText: [
            meta.claimType ? `نوع المطالبة: ${meta.claimType}` : '',
            meta.documentType ? `نوع السند: ${meta.documentType}` : '',
            typeof file.notes === 'string' && file.notes.trim() ? String(file.notes).slice(0, 500) : '',
        ]
            .filter(Boolean)
            .join('\n'),
        documentCount: catalog.find((s) => s.key === 'documents')?.items.length ?? 0,
        catalog,
        executionMeta: meta,
    };
}



export function extractLawsuitShareSource(

    file: FileData,

    stage?: CaseStage | null,

): DossierShareSource {

    const activeStage = stage ?? file.stages?.[file.activeStageIndex ?? 0] ?? file.stages?.[0];

    const module: CaseShareDossierModule = isPersonalStatusFile(file) ? 'personal' : 'lawsuit';

    const stageParties = activeStage?.parties ?? file.parties ?? [];

    const parties = stageParties.map((p) => p.name).filter(Boolean);

    const caseNumbers = uniqueStrings([activeStage?.caseNo ?? '', file.caseNo ?? '']);

    const court = activeStage?.court ?? file.court ?? '';

    const clientParty = stageParties.find((p) => p.isClient);

    const titleLabel =

        activeStage?.stageName ??

        activeStage?.name ??

        clientParty?.name ??

        String(file.id);

    const title = `${module === 'personal' ? 'أحوال شخصية' : 'دعوى'} — ${titleLabel}`.slice(0, 120);

    const narrativeParts = [

        file.notes?.[0]?.text,

        file.subInfo,

        activeStage?.timeline?.[0]?.details,

        activeStage?.timeline?.[0]?.title,

    ].filter((v): v is string => Boolean(v && String(v).trim()));

    return {

        module,

        dossierId: String(file.id),

        title,

        caseNumbers,

        partyNames: uniqueStrings(parties),

        courtLabel: court,

        courtProvince: file.subInfo,

        narrativeText: (narrativeParts[0] ?? '').slice(0, 2000),

        documentCount:

            (file.images?.length ?? 0) +

            (activeStage?.timeline?.filter((e) => e.isAttachment).length ?? 0),

        catalog: buildLawsuitShareCatalog(file, activeStage),

    };

}



export function extractCriminalShareSource(caseData: CriminalCase): DossierShareSource {

    const complainants = (caseData.complainants ?? []).map((c) => c.fullName).filter(Boolean);

    const defendants = (caseData.defendants ?? []).map((d) => d.fullName).filter(Boolean);

    const article = caseData.basics?.legalArticle ?? '';

    const title = `جزائي — ${article || caseData.id}`.slice(0, 120);

    return {

        module: 'criminal',

        dossierId: caseData.id,

        title,

        caseNumbers: uniqueStrings([caseData.id]),

        partyNames: uniqueStrings([...complainants, ...defendants]),

        courtLabel: caseData.physicalLocationCustomName ?? String(caseData.physicalLocation ?? ''),

        narrativeText: [

            article ? `المادة: ${article}` : '',

            caseData.basics?.crimeType ? `نوع الجريمة: ${caseData.basics.crimeType}` : '',

        ]

            .filter(Boolean)

            .join('\n'),

        documentCount: (caseData.otherEvidenceItems ?? []).length,

        catalog: buildCriminalShareCatalog(caseData),

    };

}

import type { CaseShareRecord } from './caseShareTypes';
import SecureStoreService from '@/app/services/SecureStoreService';
import {
    clearLegacyPlaintextMirror,
    readSecureOrDrainLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';

export const CASE_SHARE_LOCAL_KEY = 'hami:case-shares:v1';

function useInMemoryTestStore(): boolean {
    return import.meta.env.MODE === 'test' || import.meta.env.VITEST === true || typeof window === 'undefined';
}

function getTestStore(): CaseShareRecord[] {
    const g = globalThis as unknown as { __HAMI_CASE_SHARES?: CaseShareRecord[] };
    if (!Array.isArray(g.__HAMI_CASE_SHARES)) g.__HAMI_CASE_SHARES = [];
    return g.__HAMI_CASE_SHARES;
}

function parseShareRows(raw: string | null): CaseShareRecord[] {
    if (!raw) return [];
    try {
        const parsed = JSON.parse(raw) as unknown;
        return Array.isArray(parsed) ? (parsed as CaseShareRecord[]) : [];
    } catch {
        return [];
    }
}

export async function loadCaseShareRecords(): Promise<CaseShareRecord[]> {
    if (useInMemoryTestStore()) {
        return [...getTestStore()];
    }
    try {
        const drained = readSecureOrDrainLegacySync(CASE_SHARE_LOCAL_KEY);
        const raw = drained ?? (await SecureStoreService.getItem(CASE_SHARE_LOCAL_KEY));
        return parseShareRows(raw);
    } catch {
        return [];
    }
}

export async function saveCaseShareRecords(rows: CaseShareRecord[]): Promise<void> {
    if (useInMemoryTestStore()) {
        const g = globalThis as unknown as { __HAMI_CASE_SHARES?: CaseShareRecord[] };
        g.__HAMI_CASE_SHARES = rows;
        return;
    }
    try {
        const payload = JSON.stringify(rows);
        await SecureStoreService.setItem(CASE_SHARE_LOCAL_KEY, payload);
        clearLegacyPlaintextMirror(CASE_SHARE_LOCAL_KEY);
    } catch {
        /* silent */
    }
}

export async function clearCaseShareRecords(): Promise<void> {
    if (useInMemoryTestStore()) {
        getTestStore().length = 0;
        return;
    }
    try {
        await SecureStoreService.deleteItem(CASE_SHARE_LOCAL_KEY);
    } catch {
        /* silent */
    }
    clearLegacyPlaintextMirror(CASE_SHARE_LOCAL_KEY);
}

import type {
    CaseShareMaskedView,
    CaseShareVisibleFields,
    DossierShareSource,
} from './caseShareTypes';
import { DEFAULT_SECTION_VISIBILITY, resolveVisibleCatalog } from './caseShareVisibility';
import type { ShareCatalogItem, ShareCatalogSection, ShareSectionKey } from './caseShareTypes';

const HIDDEN_CASE = '[XXXX]';
const HIDDEN_PARTY = '[الطرف مجهول]';
const HIDDEN_COURT = '[محكمة مجهولة]';

export function maskPersonName(name: string, mode: 'full' | 'partial' | 'hidden'): string {
    const trimmed = name.trim();
    if (!trimmed) return '—';
    if (mode === 'hidden') return HIDDEN_PARTY;
    if (mode === 'full') return trimmed;
    const parts = trimmed.split(/\s+/).filter(Boolean);
    if (parts.length <= 1) return `${parts[0]!.slice(0, 1)}.`;
    const first = parts[0]!;
    const lastInitial = parts[parts.length - 1]!.slice(0, 1);
    return `${first} ${lastInitial}.`;
}

export function maskCourtLabel(
    label: string,
    province: string | undefined,
    mode: 'full' | 'partial' | 'hidden',
): string {
    const trimmed = label.trim();
    if (!trimmed && !province?.trim()) return '—';
    if (mode === 'hidden') return HIDDEN_COURT;
    if (mode === 'full') return trimmed || province || '—';
    const prov = province?.trim();
    if (prov) {
        const degree = trimmed.includes('استئناف')
            ? 'محكمة استئناف'
            : trimmed.includes('تمييز')
              ? 'محكمة تمييز'
              : 'محكمة بداءة';
        return `${degree} في ${prov}`;
    }
    return trimmed.split(/\s+/).slice(0, 3).join(' ') || HIDDEN_COURT;
}

export function maskCaseNumber(value: string, visible: boolean): string {
    const v = value.trim();
    if (!v) return '—';
    return visible ? v : HIDDEN_CASE;
}

function applyTermMasking(text: string, terms: string[]): string {
    let out = text;
    for (const term of terms) {
        const t = term.trim();
        if (t.length < 2) continue;
        const escaped = t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
        out = out.replace(new RegExp(escaped, 'gi'), '████');
    }
    return out;
}

function redactCatalogItem(
    item: ShareCatalogItem,
    sectionKey: ShareSectionKey,
    fields: CaseShareVisibleFields,
): ShareCatalogItem {
    const terms = fields.masked_terms ?? [];
    let label = applyTermMasking(item.label, terms);
    let preview = item.preview ? applyTermMasking(item.preview, terms) : item.preview;

    if (sectionKey === 'parties') {
        label = maskPersonName(item.label, fields.parties_names);
        if (item.preview) preview = maskPersonName(item.preview, fields.parties_names);
    } else if (sectionKey === 'court') {
        label = maskCourtLabel(item.label, undefined, fields.court_details);
        if (item.preview) preview = maskCourtLabel(item.preview, undefined, fields.court_details);
    } else if (sectionKey === 'meta') {
        if (!fields.case_numbers) {
            label = maskCaseNumber(item.label, false);
            if (item.preview) preview = maskCaseNumber(item.preview, false);
        }
    }

    return { ...item, label, preview };
}

function redactVisibleCatalog(
    catalog: ShareCatalogSection[],
    fields: CaseShareVisibleFields,
): ShareCatalogSection[] {
    return catalog.map((section) => ({
        ...section,
        items: section.items.map((item) => redactCatalogItem(item, section.key, fields)),
    }));
}

export function buildMaskedView(
    source: DossierShareSource,
    fields: CaseShareVisibleFields,
    ownerDisplayName?: string,
    sessionDurationMinutes?: number,
): CaseShareMaskedView {
    const narrativeBase = fields.text_masking?.trim() || source.narrativeText;
    const narrative = applyTermMasking(narrativeBase, fields.masked_terms ?? []);

    const sectionMode = { ...DEFAULT_SECTION_VISIBILITY, ...fields.sectionMode };
    const hiddenItemIds = fields.hiddenItemIds ?? [];
    const visibleCatalog = redactVisibleCatalog(
        resolveVisibleCatalog(source.catalog ?? [], sectionMode, hiddenItemIds),
        fields,
    );

    const docsSection = visibleCatalog.find((s) => s.key === 'documents');
    const documentsIncluded =
        fields.documents && sectionMode.documents !== 'none' && (docsSection?.items.length ?? 0) > 0;

    return {
        module: source.module,
        dossierId: source.dossierId,
        title: source.title,
        caseNumbers: source.caseNumbers.map((n) => maskCaseNumber(n, fields.case_numbers)),
        parties: source.partyNames.map((n) => maskPersonName(n, fields.parties_names)),
        court: maskCourtLabel(source.courtLabel, source.courtProvince, fields.court_details),
        narrative,
        documentsIncluded,
        ownerDisplayName,
        visibleCatalog,
        sessionDurationMinutes,
    };
}

