        if (typeof window === 'undefined') return [];
        const raw = peekSecureOrLegacySync(CASE_SHARE_LOCAL_KEY);
        if (!raw) return [];
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? (parsed as CaseShareRecord[]) : [];
    } catch {
