export type CloudSyncStatusMessageInput = {
    localOnlyMode: boolean;
    cloudSyncEnabled: boolean;
    anyBucketEnabled: boolean;
    cloudBuildEnabled: boolean;
    signedIn: boolean;
    /** حساب مسجّل لكن قيد التدقيق / مرفوض */
    verificationBlocked?: boolean;
    isOnline: boolean;
    isSyncing: boolean;
    lastSyncTime: number | null;
    lastError: string | null;
    now?: Date;
};

export type CloudSyncStatusMessage = {
    text: string;
    tone: 'muted' | 'active' | 'success' | 'warning' | 'error';
    canSyncNow: boolean;
};

export function formatRelativeTimeAr(fromMs: number, nowMs: number): string {
    const diffSec = Math.max(0, Math.floor((nowMs - fromMs) / 1000));
    if (diffSec < 45) return 'الآن';
    const diffMin = Math.floor(diffSec / 60);
    if (diffMin < 60) return `منذ ${diffMin} دقيقة`;
    const diffHr = Math.floor(diffMin / 60);
    if (diffHr < 24) return `منذ ${diffHr} ساعة`;
    const diffDay = Math.floor(diffHr / 24);
    return `منذ ${diffDay} يوم`;
}

export function resolveCloudSyncStatusMessage(input: CloudSyncStatusMessageInput): CloudSyncStatusMessage {
    const now = input.now ?? new Date();

    if (input.localOnlyMode) {
        return {
            text: 'متوقفة — وضع قطع الاتصال مفعّل',
            tone: 'warning',
            canSyncNow: false,
        };
    }

    if (!input.cloudSyncEnabled) {
        return {
            text: 'متوقفة — المزامنة السحابية معطّلة',
            tone: 'muted',
            canSyncNow: false,
        };
    }

    if (!input.cloudBuildEnabled) {
        return {
            text: 'غير متاحة في هذا الإصدار',
            tone: 'muted',
            canSyncNow: false,
        };
    }

    if (!input.signedIn) {
        if (input.verificationBlocked) {
            return {
                text: 'متوقفة — الحساب قيد التدقيق أو غير معتمد',
                tone: 'warning',
                canSyncNow: false,
            };
        }
        return {
            text: 'متوقفة — غير مسجّل الدخول',
            tone: 'warning',
            canSyncNow: false,
        };
    }

    if (!input.isOnline) {
        return {
            text: 'متوقفة — لا اتصال بالإنترنت',
            tone: 'warning',
            canSyncNow: false,
        };
    }

    if (!input.anyBucketEnabled) {
        return {
            text: 'متوقفة — لا مجالات مزامنة مفعّلة',
            tone: 'muted',
            canSyncNow: false,
        };
    }

    if (input.isSyncing) {
        return {
            text: 'جاري المزامنة...',
            tone: 'active',
            canSyncNow: false,
        };
    }

    if (input.lastError) {
        const short = input.lastError.length > 48 ? `${input.lastError.slice(0, 45)}…` : input.lastError;
        return {
            text: `فشلت — ${short}`,
            tone: 'error',
            canSyncNow: true,
        };
    }

    if (input.lastSyncTime) {
        return {
            text: `آخر مزامنة: ${formatRelativeTimeAr(input.lastSyncTime, now.getTime())}`,
            tone: 'success',
            canSyncNow: true,
        };
    }

    return {
        text: 'لم تُنفَّذ مزامنة بعد — اضغط «مزامنة الآن»',
        tone: 'muted',
        canSyncNow: true,
    };
}

export function isCloudSyncBuildEnabled(): boolean {
    return import.meta.env.VITE_ENABLE_CLOUD_SYNC === 'true';
}

import { create } from 'zustand';
import { useShallow } from 'zustand/react/shallow';
import type { CloudSyncBucket } from '@/app/services/cloudSyncEngine';
import { resolveSyncBucket } from '@/app/services/cloudSyncEngine';

export type CloudSyncBucketId = Extract<CloudSyncBucket, 'notes' | 'lawsuit' | 'execution'>;

export type CloudSyncBucketStatus = {
    isSyncing: boolean;
    lastSyncTime: number | null;
    syncStatus: 'idle' | 'syncing' | 'success' | 'error';
    syncError: string | null;
};

type CloudSyncStatusStoreState = {
    signedIn: boolean;
    isOnline: boolean;
    buckets: Record<CloudSyncBucketId, CloudSyncBucketStatus>;
    syncNowHandlers: Partial<Record<CloudSyncBucketId, () => Promise<void>>>;
    setSignedIn: (signedIn: boolean) => void;
    setOnline: (isOnline: boolean) => void;
    reportBucket: (bucket: CloudSyncBucketId, partial: Partial<CloudSyncBucketStatus>) => void;
    registerSyncHandler: (bucket: CloudSyncBucketId, fn: () => Promise<void>) => void;
    unregisterSyncHandler: (bucket: CloudSyncBucketId) => void;
    syncAllNow: () => Promise<{ ok: boolean; skipped: boolean; failed: boolean }>;
};

const emptyBucket = (): CloudSyncBucketStatus => ({
    isSyncing: false,
    lastSyncTime: null,
    syncStatus: 'idle',
    syncError: null,
});

const BUCKET_ORDER: CloudSyncBucketId[] = ['notes', 'lawsuit', 'execution'];

export function mapLocalKeyToCloudSyncBucket(localKey: string): CloudSyncBucketId | null {
    const bucket = resolveSyncBucket(localKey);
    if (bucket === 'notes' || bucket === 'lawsuit' || bucket === 'execution') return bucket;
    return null;
}

type AggregateCloudSyncRuntime = {
    isSyncing: boolean;
    lastSyncTime: number | null;
    lastError: string | null;
    isOnline: boolean;
    signedIn: boolean;
};

export function selectAggregateCloudSyncRuntime(state: CloudSyncStatusStoreState): AggregateCloudSyncRuntime {
    const buckets = BUCKET_ORDER.map((id) => state.buckets[id]);
    const isSyncing = buckets.some((b) => b.isSyncing);
    const lastSyncTime = buckets.reduce((max, b) => Math.max(max, b.lastSyncTime ?? 0), 0);
    const errorBucket = [...buckets].reverse().find((b) => b.syncError);
    return {
        isSyncing,
        lastSyncTime: lastSyncTime > 0 ? lastSyncTime : null,
        lastError: errorBucket?.syncError ?? null,
        isOnline: state.isOnline,
        signedIn: state.signedIn,
    };
}

export const useCloudSyncStatusStore = create<CloudSyncStatusStoreState>((set, get) => ({
    signedIn: false,
    isOnline: typeof navigator !== 'undefined' ? navigator.onLine : true,
    buckets: {
        notes: emptyBucket(),
        lawsuit: emptyBucket(),
        execution: emptyBucket(),
    },
    syncNowHandlers: {},
    setOnline: (isOnline) =>
        set((s) => (s.isOnline === isOnline ? s : { isOnline })),
    setSignedIn: (signedIn) =>
        set((s) => (s.signedIn === signedIn ? s : { signedIn })),
    reportBucket: (bucket, partial) =>
        set((s) => {
            const prev = s.buckets[bucket];
            const next = { ...prev, ...partial };
            if (
                prev.isSyncing === next.isSyncing &&
                prev.lastSyncTime === next.lastSyncTime &&
                prev.syncStatus === next.syncStatus &&
                prev.syncError === next.syncError
            ) {
                return s;
            }
            return {
                buckets: {
                    ...s.buckets,
                    [bucket]: next,
                },
            };
        }),
    registerSyncHandler: (bucket, fn) =>
        set((s) => {
            if (s.syncNowHandlers[bucket] === fn) return s;
            return {
                syncNowHandlers: { ...s.syncNowHandlers, [bucket]: fn },
            };
        }),
    unregisterSyncHandler: (bucket) =>
        set((s) => {
            if (!(bucket in s.syncNowHandlers)) return s;
            const next = { ...s.syncNowHandlers };
            delete next[bucket];
            return { syncNowHandlers: next };
        }),
    syncAllNow: async () => {
        const { runCloudSyncAllNow } = await import('@/app/services/cloudSync/runCloudSyncAllNow');
        return runCloudSyncAllNow();
    },
}));

/**
 * اشتراك آمن — المنتقي يعيد كائناً جديداً كل استدعاء؛ بلا مقارنة ضحلة
 * يدخل React في Maximum update depth عبر useSyncExternalStore.
 */
export function useAggregateCloudSyncRuntime(): AggregateCloudSyncRuntime {
    return useCloudSyncStatusStore(useShallow(selectAggregateCloudSyncRuntime));
}

export { BUCKET_ORDER };

import { performCloudSyncBuckets, type PerformCloudSyncResult } from '@/app/services/cloudSyncEngine';
import { STORAGE_KEYS } from '@/app/utils/constants';
import { resolveExecutionFilesStorageKey } from '@/app/utils/executionFilesStorage';
import { resolveLiveAuthUserIdForStorage } from '@/app/utils/liveAuthUserId';
import { getLawyerSettingsSnapshot } from '@/app/services/settings/settingsSnapshot';
import { isCloudSyncBucketEnabled } from '@/app/services/settings/cloudSyncBucket';
import type { AppSettingsState } from '@/app/services/settings/types';
import type { WorkCloudCheckpointPushResult } from '@/app/services/cloud/workCloudCheckpoint';

export type CloudSyncAllSummary = {
    ok: boolean;
    skipped: boolean;
    failed: boolean;
};

function summarize(values: PerformCloudSyncResult[]): CloudSyncAllSummary {
    if (values.length === 0) return { ok: false, skipped: true, failed: false };
    const failed = values.some((v) => !v.ok);
    const skipped = values.every((v) => v.skipped);
    return { ok: !failed && !skipped, skipped, failed };
}

function canAttemptWorkCheckpoint(settings: AppSettingsState): boolean {
    if (settings.security.localOnlyMode) return false;
    if (!settings.data.cloudSync) return false;
    return true;
}

async function pushWorkCheckpointIntoSummary(
    summary: CloudSyncAllSummary,
): Promise<CloudSyncAllSummary> {
    if (!summary.ok) return summary;
    try {
        const { pushWorkCloudCheckpointNow } = await import(
            '@/app/services/cloud/workCloudCheckpoint'
        );
        const checkpoint: WorkCloudCheckpointPushResult = await pushWorkCloudCheckpointNow();
        if (checkpoint.failed) {
            return { ok: false, skipped: false, failed: true };
        }
        return summary;
    } catch {
        return { ok: false, skipped: false, failed: true };
    }
}

async function pushCalendarCheckpointWhenBucketsEmpty(): Promise<CloudSyncAllSummary> {
    try {
        const { pushWorkCloudCheckpointNow } = await import(
            '@/app/services/cloud/workCloudCheckpoint'
        );
        const checkpoint: WorkCloudCheckpointPushResult = await pushWorkCloudCheckpointNow();
        if (checkpoint.pushed) return { ok: true, skipped: false, failed: false };
        if (checkpoint.failed) return { ok: false, skipped: false, failed: true };
        return { ok: false, skipped: true, failed: false };
    } catch {
        return { ok: false, skipped: false, failed: true };
    }
}

/** مزامنة صريحة من الإعدادات — لا تعتمد على hooks قد تكون لا تزال disabled بعد setState */
export async function runCloudSyncAllNow(
    settings: AppSettingsState = getLawyerSettingsSnapshot(),
): Promise<CloudSyncAllSummary> {
    const keys: string[] = [];
    if (isCloudSyncBucketEnabled(settings, 'notes')) keys.push(STORAGE_KEYS.LAWYER_NOTES);
    if (isCloudSyncBucketEnabled(settings, 'files')) keys.push(STORAGE_KEYS.LAWYER_FILES);
    if (isCloudSyncBucketEnabled(settings, 'execution')) {
        keys.push(resolveExecutionFilesStorageKey(resolveLiveAuthUserIdForStorage()));
    }
    if (keys.length === 0) {
        if (!canAttemptWorkCheckpoint(settings)) {
            return { ok: false, skipped: true, failed: false };
        }
        return pushCalendarCheckpointWhenBucketsEmpty();
    }

    const results = await performCloudSyncBuckets(keys, { allowWhenRealtimeActive: true });
    const values = [...results.values()];
    const summary = summarize(values);
    if (!summary.skipped && typeof window !== 'undefined') {
        window.dispatchEvent(
            new CustomEvent('hami:data-imported', {
                detail: { keys },
            }),
        );
    }
    return pushWorkCheckpointIntoSummary(summary);
}

import { beforeEach, describe, expect, it } from 'vitest';
import SecureStoreService from '@/app/services/SecureStoreService';
