vi.mock('@/app/api/security/supabaseAdminClient', () => ({
    getSupabaseAdminClient: () => ({
        from() {
            return {
                insert: async (row: {
                    user_id: string;
                    encrypted_data: string;
                    data_signature: string;
                    security_version: number;
                    keep_anchor?: boolean;
                }) => {
                    rows.unshift({
                        ...row,
                        keep_anchor: row.keep_anchor === true,
                        id: `cp-${rows.length + 1}`,
                        created_at: new Date(Date.now() + rows.length).toISOString(),
                    });
                    return { error: null };
                },
                select() {
                    return {
                        eq(col: string, value: unknown) {
                            let matched = rows.filter((r) =>
                                col === 'user_id' ? r.user_id === value : true,
                            );
                            const chain = {
                                eq(col2: string, value2: unknown) {
                                    if (col2 === 'keep_anchor') {
                                        matched = matched.filter((r) => r.keep_anchor === value2);
                                    }
                                    return chain;
                                },
                                order() {
                                    const ordered = [...matched].sort((a, b) =>
                                        a.created_at < b.created_at ? 1 : -1,
                                    );
                                    const result = {
                                        data: ordered,
                                        error: null,
                                        limit(n: number) {
                                            return Promise.resolve({
                                                data: ordered.slice(0, n),
                                                error: null,
                                            });
                                        },
                                    };
                                    return Object.assign(Promise.resolve(result), result);
                                },
                            };
                            return chain;
                        },
                    };
                },
                delete() {
                    return {
                        in: async (_col: string, ids: string[]) => {
                            const drop = new Set(ids);
                            for (let i = rows.length - 1; i >= 0; i -= 1) {
                                if (drop.has(rows[i].id)) rows.splice(i, 1);
                            }
                            return { error: null };
                        },
                    };
                },
            };
        },
    }),
}));

