import { isUnreadableProtectedValue } from './dossierWipeGuard';

/**
 * تلف مخزون على مفتاح محمي — إشارة واحدة لكل مفتاح في العمر.
 *
 * الحارس يمنع الكتابة فوق البيانات التالفة، لكن المنع وحده صمت: المحامي يفتح
 * التطبيق فيرى شاشة خالية ولا يعلم أن أضابيره ما تزال على الجهاز، ولا يعلم بها
 * أحد في أي لوحة. الفشل الصامت هنا لا يقلّ سوءاً عن الفقد نفسه.
 *
 * القراءة تُشير كما تُشير الكتابة: مَن يفتح ولا يحفظ لن يمرّ بمسار الكتابة أبداً.
 */
const reportedKeys = new Set<string>();

const ENCRYPTED_PREFIX = 'hami_enc_v2:';

export type CorruptStoragePhase = 'read' | 'write';

export function signalUnreadableStoredValue(
    key: string,
    raw: string,
    phase: CorruptStoragePhase,
): void {
    if (reportedKeys.has(key)) return;
    reportedKeys.add(key);

    /*
     * استيراد ديناميّ: هذه السلسلة تُقلع مع المخزن، وربط عميل الرصد بها ثابتاً
     * يجرّه إلى مسار الإقلاع لأجل بلاغ لا يقع إلا عند عطل.
     */
    void import('@/app/observability/sentryClient')
        .then((m) =>
            m.sentryCaptureMessage(`storage-unreadable: ${key}`, {
                storageKey: key,
                phase,
                storedLength: raw.length,
                looksEncrypted: raw.startsWith(ENCRYPTED_PREFIX),
            }),
        )
        .catch(() => {
            /* فشل التبليغ لا يجوز أن يمسّ القراءة أو الكتابة */
        });
}

/** يُشير فقط حين يكون المفتاح محميّاً والمحتوى غير مفهوم */
export function signalIfUnreadableProtected(
    key: string,
    raw: string | null | undefined,
    phase: CorruptStoragePhase,
): void {
    if (!raw) return;
    if (!isUnreadableProtectedValue(key, raw)) return;
    signalUnreadableStoredValue(key, raw, phase);
}

export function __resetCorruptStorageSignalForTests(): void {
    reportedKeys.clear();
}

import type { BackupDomain, DossierSnapshotMeta } from './dossierPersistenceTypes';

const DB_NAME = 'hami-dossier-backups';
const DB_VERSION = 1;
const STORE = 'snapshots';
const MAX_SNAPSHOTS_PER_DOMAIN = 8;

type SnapshotRecord = {
    meta: DossierSnapshotMeta;
    payload: unknown[];
};

function openDb(): Promise<IDBDatabase | null> {
    if (typeof indexedDB === 'undefined') return Promise.resolve(null);
    return new Promise((resolve) => {
        const req = indexedDB.open(DB_NAME, DB_VERSION);
        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(STORE)) {
                db.createObjectStore(STORE);
            }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => resolve(null);
    });
}

function snapshotKey(domain: BackupDomain, revision: number): string {
    return `${domain}:rev:${revision}`;
}

/** كل النسخ الاحتياطية للمجال — الأحدث أولاً */
export async function listDossierBackups(domain: BackupDomain): Promise<SnapshotRecord[]> {
    const db = await openDb();
    if (!db) return [];
    return new Promise((resolve) => {
        const tx = db.transaction(STORE, 'readonly');
        const req = tx.objectStore(STORE).getAll();
        req.onsuccess = () => {
            const rows = (req.result as SnapshotRecord[])
                .filter(
                    (rec) =>
                        rec &&
                        Array.isArray(rec.payload) &&
                        rec.payload.length > 0 &&
                        String(rec.meta?.domain ?? '') === domain,
                )
                .sort((a, b) => (b.meta?.revision ?? 0) - (a.meta?.revision ?? 0));
            resolve(rows);
        };
        req.onerror = () => resolve([]);
        tx.oncomplete = () => db.close();
        tx.onabort = () => db.close();
        tx.onerror = () => db.close();
    });
}

export async function readLatestDossierBackup(domain: BackupDomain): Promise<SnapshotRecord | null> {
    const all = await listDossierBackups(domain);
    return all[0] ?? null;
}

export async function writeDossierBackup(
    domain: BackupDomain,
    payload: unknown[],
    revision: number,
): Promise<void> {
    if (!Array.isArray(payload) || payload.length === 0) return;
    const db = await openDb();
    if (!db) return;

    const record: SnapshotRecord = {
        meta: {
            domain,
            revision,
            savedAt: new Date().toISOString(),
            itemCount: payload.length,
        },
        payload,
    };

    await new Promise<void>((resolve) => {
        const tx = db.transaction(STORE, 'readwrite');
        tx.objectStore(STORE).put(record, snapshotKey(domain, revision));
        tx.oncomplete = () => {
            db.close();
            resolve();
        };
        tx.onabort = () => {
            db.close();
            resolve();
        };
        tx.onerror = () => {
            db.close();
            resolve();
        };
    });

    await pruneOldSnapshots(domain);
}

async function pruneOldSnapshots(domain: BackupDomain): Promise<void> {
    const db = await openDb();
    if (!db) return;
    await new Promise<void>((resolve) => {
        const tx = db.transaction(STORE, 'readwrite');
        const store = tx.objectStore(STORE);
        const req = store.getAllKeys();
        req.onsuccess = () => {
            const prefix = `${domain}:rev:`;
            const keys = (req.result as unknown[])
                .filter((k): k is string => typeof k === 'string' && k.startsWith(prefix))
                .sort()
                .reverse();
            keys.slice(MAX_SNAPSHOTS_PER_DOMAIN).forEach((k) => store.delete(k));
        };
        tx.oncomplete = () => {
            db.close();
            resolve();
        };
        tx.onabort = () => {
            db.close();
            resolve();
        };
        tx.onerror = () => {
            db.close();
            resolve();
        };
    });
}

/**
 * نواة مزامنة إضبارات خفيفة — SecureStore فقط بلا backup/cloud/executionFilesStorage.
 * تُستخدم من مسار الدعاوى على اللوحة حتى لا يُسحب app-execution-storage-deferred إلى LD stem.
 */
import { debug } from '@/app/utils/debug';
import {
    EXECUTION_FILES_STORAGE_KEY,
    EXECUTION_FILES_STORAGE_KEYS_LEGACY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_STORAGE_KEYS_LEGACY,
} from './dossierStorageKeys';
import { shouldRejectDossierWipe } from './dossierWipeGuard';
import type { DossierDomain } from './dossierPersistenceTypes';
import SecureStoreService from '@/app/services/SecureStoreService';
import { mergeDossierRowsById, resolveLoadedDossierPrimary } from './dossierKeyLoad';
import {
    readSecureOrDrainLegacySync,
    writeSecureAndClearLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';

type DomainConfig = {
    domain: DossierDomain;
    primaryKey: string;
    legacyKeys: readonly string[];
};

const DOMAIN_CONFIG: Record<DossierDomain, DomainConfig> = {
    lawsuit: {
        domain: 'lawsuit',
        primaryKey: LAWSUIT_FILES_STORAGE_KEY,
        legacyKeys: LAWSUIT_FILES_STORAGE_KEYS_LEGACY,
    },
    execution: {
        domain: 'execution',
        primaryKey: EXECUTION_FILES_STORAGE_KEY,
        legacyKeys: EXECUTION_FILES_STORAGE_KEYS_LEGACY,
    },
};

function parseArray(raw: string | null): unknown[] | null {
    if (raw === null) return null;
    try {
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed) ? parsed : null;
    } catch {
        return null;
    }
}

function decidePrimaryLoad(config: DomainConfig, primary: unknown[] | null) {
    try {
        return resolveLoadedDossierPrimary({
            primary,
            unread: SecureStoreService.isUnreadSync(config.primaryKey),
            occupied: SecureStoreService.hasItemSync(config.primaryKey),
        });
    } catch {
        return resolveLoadedDossierPrimary({
            primary,
            unread: false,
            occupied: false,
        });
    }
}

function loadFromAllKeysSync(config: DomainConfig): unknown[] {
    const primary = parseArray(readSecureOrDrainLegacySync(config.primaryKey));
    const decision = decidePrimaryLoad(config, primary);
    if (decision === 'unread' || decision === 'canonical-empty') return [];
    if (decision === 'use-primary') return primary ?? [];

    let merged: unknown[] = primary ?? [];
    for (const legacyKey of config.legacyKeys) {
        const legacy = parseArray(readSecureOrDrainLegacySync(legacyKey));
        if (legacy !== null && legacy.length > 0) {
            merged = mergeDossierRowsById(merged, legacy);
        }
    }
    return merged;
}

/** تحميل متزامن خفيف — بدون استعادة backup */
export function loadDossierCollectionSync(domain: DossierDomain): unknown[] {
    return loadFromAllKeysSync(DOMAIN_CONFIG[domain]);
}

/**
 * حفظ متزامن خفيف — مفاتيح SecureStore فقط (بلا backup/طابور سحابة).
 * المسارات الكاملة تستخدم dossierPersistenceService.persistDossierCollectionSync.
 */
export function persistDossierCollectionSyncLite(
    domain: DossierDomain,
    next: unknown[],
): unknown[] {
    const payload = Array.isArray(next) ? next : [];
    const serialized = JSON.stringify(payload);
    const config = DOMAIN_CONFIG[domain];

    const existing = readSecureOrDrainLegacySync(config.primaryKey);
    if (existing && shouldRejectDossierWipe(config.primaryKey, serialized, existing)) {
        debug.warn(`[DossierSyncLite] رفض مسح "${config.primaryKey}" — البيانات الحالية محفوظة.`);
        return parseArray(existing) ?? payload;
    }
    /*
     * getItemSync على أصل مشفَّر بارد تُرجع null فيتخطّى الحارس أعلاه.
     * setItemSync يؤجّل الكتابة ويفكّ الأصل قبل حارس المسح — لا نكتب هنا يدوياً.
     */
    writeSecureAndClearLegacySync(config.primaryKey, serialized);

    config.legacyKeys.forEach((legacyKey) => {
        try {
            const legacyExisting = readSecureOrDrainLegacySync(legacyKey);
            if (legacyExisting && shouldRejectDossierWipe(legacyKey, serialized, legacyExisting)) {
                return;
            }
            writeSecureAndClearLegacySync(legacyKey, serialized);
        } catch {
            /* ignore */
        }
    });

    return payload;
}

import { isCanonicalEmptyDossierPrimary } from './dossierPrimaryEmpty';

export type DossierPrimaryLoadDecision =
    | 'unread'
    | 'canonical-empty'
    | 'use-primary'
    | 'try-legacy';

/**
 * أصل مشغول لم يُفكّ ≠ خزنة فارغة، ومصفوفة `[]` مقروءة ≠ «ابحث في المفاتيح القديمة».
 */
export function resolveLoadedDossierPrimary(input: {
    primary: unknown[] | null;
    unread: boolean;
    occupied: boolean;
}): DossierPrimaryLoadDecision {
    if (input.occupied && input.unread) return 'unread';
    if (input.primary !== null && input.primary.length > 0) return 'use-primary';
    if (isCanonicalEmptyDossierPrimary(input.primary, input.unread)) return 'canonical-empty';
    return 'try-legacy';
}

export function mergeDossierRowsById(primary: unknown[], incoming: unknown[]): unknown[] {
    const out: unknown[] = [];
    const seen = new Set<string>();
    const add = (value: unknown) => {
        if (!value || typeof value !== 'object' || Array.isArray(value)) return;
        const id = String((value as { id?: unknown }).id ?? '').trim();
        if (!id || seen.has(id)) return;
        seen.add(id);
        out.push(value);
    };
    primary.forEach(add);
    incoming.forEach(add);
    return out;
}

