    | DossierDomain
    | 'notes'
    | 'community'
    | 'vault'
    | 'repository'
    | 'calendar'
    | 'tasks'
    | 'transactions'
    | 'transactionsThreading';

export type DossierSnapshotMeta = {
    domain: BackupDomain;
    revision: number;
    savedAt: string;
    itemCount: number;
};

export type DossierCloudSyncOp = {
    id: string;
    domain: DossierDomain;
    op: 'upsert_collection' | 'delete_item';
    payloadRef?: string;
    createdAt: string;
    /** للمزامنة السحابية المستقبلية */
    status: 'pending' | 'synced' | 'failed';
};

export const DOSSIER_SYNC_QUEUE_KEY = 'hami:dossier-sync-queue:v1';

/**
 * مصفوفة أساسية فارغة بعد فكّ التشفير = الحالة المعتمدة.
 * الدمج من المفاتيح القديمة فوقها كان يعيد إضبارة محذوفة إلى `lawyer_files`.
 */
export function isCanonicalEmptyDossierPrimary(
    primary: unknown[] | null,
    unread: boolean,
): boolean {
    return primary !== null && primary.length === 0 && !unread;
}

