/** شواهد حذف إضابير — قائمة معرّفات؛ الكتابة فوق ciphertext بارد تُعيد المحذوف من السحابة */
export function isDossierTombstonesStorageKey(key: string): boolean {
    if (key === 'hami:lawsuit:dossier-tombstones:v1') return true;
    if (key === 'hami:execution:dossier-tombstones:v1') return true;
    return key.startsWith('hami:execution:dossier-tombstones:v1:');
}

/** شواهد حذف وثائق/ملاحظات — نفس صنف المسح إن هُيِّئت فارغة فوق أصل مشفّر */
export function isDeletedIdsTombstoneStorageKey(key: string): boolean {
    return (
        key === 'hami:smartvault:deleted:v1' ||
        key === 'hami:repository:deleted:v1' ||
        key === 'hami:lawyer-notes:deleted:v1' ||
        key === 'hami:community:deleted-ids:v1' ||
        key === 'hami:calendar:tombstones:v1'
    );
}

/**
 * حالة خيوط المعاملات حسب المالك — كانت خارج الحماية بينما سجل المعاملات داخلها،
 * وهي المخزن الفعلي للمهام والمستندات. قراءة فاشلة تُظهر قسماً خالياً، وأول حفظة
 * بعدها تكتب حالة بمصفوفات خالية فوق العمل.
 * العدّ في wipe guard على السجلات لا على Object.keys (حقول ثابتة).
 */
export function isTransactionsThreadingStateKey(key: string): boolean {
    return key === 'hami:transactionsThreading:v1' || key.startsWith('hami:transactionsThreading:v1:');
}

/** قوالب مهام المعاملات حسب المالك — مصفوفة؛ الحماية من التفريغ فوق ciphertext بارد فقط */
export function isTransactionsTaskTemplatesKey(key: string): boolean {
    return key.startsWith('hami:transactions:taskTemplates:v1:');
}

/** طلبات عون المهام — مصفوفة؛ المسح المتعمَّد مسموح، التفريغ فوق ciphertext بارد مرفوض */
export function isTaskHelpRequestsKey(key: string): boolean {
    return key === 'hami_task_help_requests_v1';
}

export function isProtectedStorageKey(key: string): boolean {
    if (PROTECTED_ARRAY_STORAGE_KEYS.has(key)) return true;
    if (PROTECTED_OBJECT_STORAGE_KEYS.has(key)) return true;
    if (isTransactionsThreadingStateKey(key)) return true;
    if (isTransactionsTaskTemplatesKey(key)) return true;
    if (isTaskHelpRequestsKey(key)) return true;
    if (key.includes('lawyer_files')) return true;
    // فهرس التنفيذ حسب المالك: executionFiles:<userId>
    if (key.startsWith(`${EXECUTION_FILES_STORAGE_KEY}:`)) return true;
    if (isDossierTombstonesStorageKey(key)) return true;
    if (isDeletedIdsTombstoneStorageKey(key)) return true;
    /*
     * البادئة الفعلية `hami:criminal:case:` — وكان المكتوب هنا `hami:criminal:shard:`
     * وهي بادئة لا يكتبها أحد. فكل قضية جنائية كانت خارج الحماية بالكامل.
     */
    if (isCriminalCaseShardRootKey(key)) return true;
    return false;
}

/*
 * إشعارات المستخدم (`hami:notifications:v1:<userId>`) عمداً خارج هذه القائمة:
 * حذف آخر إشعار متبقٍ طريقٌ مشروع يكتب `[]` فوق سجلٍّ كان فيه عنصر واحد
 * (notificationStore.removeNotification → saveNotifications). القائمة هنا
 * تُطبَّق أيضاً كحارس رفضٍ في dossierWipeGuard (isArrayKey)، فلا تمييز تلقائي
 * بين «حذف متعمَّد» و«تفريغ غير مقصود» بلا نظام tombstone كالذي تملكه
 * lawyer_notes/smartvault/repository. الإشعارات محتوًى قابل لإعادة التوليد من
 * الخادم عند تفعيل المزامنة — فحماية «رفض الفراغ» هنا كانت لتُعيد بعث إشعارات
 * حذفها المستخدم عمداً بعد كل حذف لآخر عنصر. المفتاح مشفَّر فعلاً (سرّية
 * محتواه محمية) دون هذه الحماية الإضافية غير الملائمة لشكل كتابته.
 */

export function backupDomainForStorageKey(key: string): BackupDomain | null {
    if (LAWSUIT_KEY_SET.has(key) || key.includes('lawyer_files')) return 'lawsuit';
    if (EXECUTION_KEY_SET.has(key) || key.startsWith(`${EXECUTION_FILES_STORAGE_KEY}:`)) {
        return 'execution';
    }
    if (key === LAWYER_NOTES_STORAGE_KEY || key === 'globalNotes' || key === 'global_notes') return 'notes';
    if (key === 'hami:community:posts:v1') return 'community';
    if (key === 'hami:smartvault:docs:v1') return 'vault';
    if (key === 'hami:repository:docs:v1') return 'repository';
    if (key === 'hami:calendar:events:v1') return 'calendar';
    if (key === QUANTUM_TASKS_STORAGE_KEY) return 'tasks';
    if (key === 'hami:transactions:v1' || isTransactionsTaskTemplatesKey(key)) return 'transactions';
    if (isTransactionsThreadingStateKey(key)) return 'transactionsThreading';
    return null;
}

import { readLatestDossierBackup } from './dossierBackupStore';
import { loadExecutionFilesRaw } from '@/app/utils/executionFilesStorage';
import { loadLawsuitFilesRaw } from '@/app/utils/lawsuitFilesStorage';
import { loadCriminalCasesRaw } from '@/app/utils/criminalCasesStorage';
import SecureStoreService from '@/app/services/SecureStoreService';
import { debug } from '@/app/utils/debug';

/**
 * يُرجع true عندما تبدو الإضابير فارغة لكن توجد نسخة احتياطية —
 * أي أن التخزين لم يُحمَّل بعد أو حدث فساد مؤقت. في هذه الحالة لا نُجرِّب purge للتقويم.
 */
export async function shouldSkipDossierDependentCalendarPurge(): Promise<boolean> {
    await SecureStoreService.ensurePersistedReady();

    const lawsuits = loadLawsuitFilesRaw();
    const executions = loadExecutionFilesRaw();
    const criminal = loadCriminalCasesRaw();

    if (lawsuits.length > 0 || executions.length > 0 || criminal.length > 0) {
        return false;
    }

    const [lawsuitBk, execBk] = await Promise.all([
        readLatestDossierBackup('lawsuit'),
        readLatestDossierBackup('execution'),
    ]);

    const hasBackup =
        (lawsuitBk?.payload.length ?? 0) > 0 || (execBk?.payload.length ?? 0) > 0;

    if (hasBackup) {
        debug.warn(
            '[storageHydrationGuard] تخطي تنظيف التقويم — الإضابير فارغة لكن النسخة الاحتياطية تحتوي بيانات',
        );
    }

    return hasBackup;
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { normalizeClientPhone } from '@/app/components/lawyer/NeuralAlertsCard/alertContactUtils';

function readStr(o: Record<string, unknown>, key: string): string {
    const v = o[key];
    return typeof v === 'string' ? v.trim() : '';
}

function phoneFromLawsuit(file: FileData): string | null {
    const direct = normalizeClientPhone(file.clientPhone);
    if (direct) return direct;
    for (const p of file.parties ?? []) {
        if (!p.isClient) continue;
        const ph = normalizeClientPhone(p.phone);
        if (ph) return ph;
    }
    for (const p of file.parties ?? []) {
        const ph = normalizeClientPhone(p.phone);
        if (ph) return ph;
    }
    return null;
}

function phoneFromExecution(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const f = raw as Record<string, unknown>;
    const debtors = Array.isArray(f.debtors) ? f.debtors : [];
    for (const d of debtors) {
        if (!d || typeof d !== 'object') continue;
        const ph = normalizeClientPhone(readStr(d as Record<string, unknown>, 'phone'));
        if (ph) return ph;
    }
    return normalizeClientPhone(readStr(f, 'clientPhone'));
}

function phoneFromCriminal(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const c = raw as Record<string, unknown>;
    const defendants = Array.isArray(c.defendants) ? c.defendants : [];
    for (const d of defendants) {
        if (!d || typeof d !== 'object') continue;
        const o = d as Record<string, unknown>;
        if (o.isOurClient !== true && o.isClient !== true) continue;
        const ph =
            normalizeClientPhone(readStr(o, 'phone')) ||
            normalizeClientPhone(readStr(o, 'mobile'));
        if (ph) return ph;
    }
    return null;
}

function phoneFromUrgent(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const c = raw as Record<string, unknown>;
    return (
        normalizeClientPhone(readStr(c, 'applicantPhone')) ||
        normalizeClientPhone(readStr(c, 'clientPhone')) ||
        normalizeClientPhone(readStr(c, 'phone'))
    );
}

/** يكمّل رقم الموكل من الإضابيرة إن لم يُمرَّر من التقويم */
export function enrichAlertClientPhone(
    alert: SecretaryAlert,
    ctx: {
        lawsuitFiles?: FileData[];
        executionFiles?: unknown[];
        criminalCases?: unknown[];
        urgentCases?: unknown[];
    },
): SecretaryAlert {
    if (normalizeClientPhone(alert.clientPhone)) return alert;

    const id = alert.entityId ? String(alert.entityId) : '';
    if (!id) return alert;

    let phone: string | null = null;
    const dossier = alert.calendarSource?.dossierModule;
    const dossierId = alert.calendarSource?.dossierId;

    const resolveId = dossierId ?? id;

    if (alert.target === 'lawsuit' || dossier === 'lawsuit') {
        const file = ctx.lawsuitFiles?.find((f) => String(f.id) === resolveId);
        if (file) phone = phoneFromLawsuit(file);
    } else if (alert.target === 'execution' || dossier === 'execution') {
        const file = ctx.executionFiles?.find((f) => String((f as { id?: unknown }).id ?? '') === resolveId);
        if (file) phone = phoneFromExecution(file);
    } else if (alert.target === 'criminal' || dossier === 'criminal') {
        const row = ctx.criminalCases?.find((c) => String((c as { id?: unknown }).id ?? '') === resolveId);
        if (row) phone = phoneFromCriminal(row);
    } else if (alert.target === 'urgent' || dossier === 'urgent') {
        const row = ctx.urgentCases?.find((c) => String((c as { id?: unknown }).id ?? '') === resolveId);
        if (row) phone = phoneFromUrgent(row);
    }

    if (!phone) return alert;
    return { ...alert, clientPhone: phone };
}

/**
 * Helpers مشتركة بين builders الإشعارات الجديدة (execution/lawsuit/financial).
 * نُخرجها لملف منفصل لتجنّب circular import مع SecretaryOrchestrator.
 */

const DAY_MS = 24 * 60 * 60 * 1000;

/**
 * يحاول تفسير YMD أو ISO إلى timestamp. يقبل: 'YYYY-MM-DD' و 'YYYY-MM-DDTHH:mm:ss[.sss]Z' و timestamp رقمي.
 */
export function parseYmdToTs(value: unknown): number | null {
    if (value instanceof Date) {
        const t = value.getTime();
        return Number.isFinite(t) ? t : null;
    }
    if (typeof value === 'number' && Number.isFinite(value)) {
        return value < 10_000_000_000 ? value * 1000 : value;
    }
    if (typeof value !== 'string') return null;
    const s = value.trim();
    if (!s) return null;
    // YYYY-MM-DD (محلي)
    const ymd = /^(\d{4})-(\d{1,2})-(\d{1,2})$/.exec(s);
    if (ymd) {
        const d = new Date(Number(ymd[1]), Number(ymd[2]) - 1, Number(ymd[3]));
        const t = d.getTime();
        return Number.isFinite(t) ? t : null;
    }
    const d = new Date(s);
    const t = d.getTime();
    return Number.isFinite(t) ? t : null;
}

/** عدد الأيام (مدوّر للأسفل) من نقطة الآن إلى ts مستقبلي. */
export function dayDiff(targetTs: number, nowTs: number): number {
    return Math.floor((targetTs - nowTs) / DAY_MS);
}

/** أيام تقويمية حتى يوم الهدف (٠ = اليوم نفسه) — بلا انزلاق ساعة منتصف الليل. */
export function calendarDaysUntil(targetTs: number, nowTs: number): number {
    const targetDay = new Date(targetTs);
    targetDay.setHours(0, 0, 0, 0);
    const nowDay = new Date(nowTs);
    nowDay.setHours(0, 0, 0, 0);
    return Math.round((targetDay.getTime() - nowDay.getTime()) / DAY_MS);
}

/** التحقق من تاريخ ISO آمن. */
export function safeIso(value: unknown): string | undefined {
    if (typeof value !== 'string') return undefined;
    const t = parseYmdToTs(value);
    return t != null ? new Date(t).toISOString() : undefined;
}

/**
 * تنبيهات قسم التنفيذ — Direct producer (لا يعتمد على calendar bridge فقط).
 *
 * يُولّد تنبيهات لـ:
 *  - مهام الإضبارة (caseTasksPending[].dueDate)
 *  - مهل قانونية مباشرة:
 *      • executive_detention_until (تنبيه قبل 2 يوم)
 *      • eviction_vacate_deadline (تنبيه قبل 3 أيام)
 *      • eviction_first_notice_date + 7 يوم (نهاية المهلة الطوعية للإخلاء)
 *      • publication_notice_by_debtor + 15 يوم
 *      • employee_summons_assignments_by_debtor[*].deadlineDate
 *      • guarantor_notification.noticeDateYmd + 7 يوم
 *      • stay_of_execution.next_hearing_date
 *  - ركود (المادة 112 ق.ت.): dossier_last_action_date منذ > 300 يوم → تنبيه قبل سقوط الحق
 *  - دفعات راكدة: total_remaining_balance > 0 و lastPaymentDate > 60 يوم → تنبيه مالي
 */

import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { composeRichAlert } from '@/app/services/alertRichContext';
import type { DossierRegistry } from '@/app/services/alertDossierRegistry';
import { parseYmdToTs, dayDiff, calendarDaysUntil } from '@/app/services/executionAlerts.helpers';

const DAY_MS = 24 * 60 * 60 * 1000;

// قرارات أولوية موحّدة بناءً على القرب الزمني (بالأيام)
function priorityByDaysToDue(daysToDue: number): number {
    if (daysToDue <= 1) return 1; // حرج
    if (daysToDue <= 3) return 2; // عاجل
    if (daysToDue <= 7) return 3; // مهم
    return 4; // عادي
}

function safeStr(v: unknown): string {
    return typeof v === 'string' ? v.trim() : '';
}

function asArray(v: unknown): unknown[] {
    return Array.isArray(v) ? v : [];
}

function asRecord(v: unknown): Record<string, unknown> {
    return v && typeof v === 'object' ? (v as Record<string, unknown>) : {};
}

function pushAlert(out: SecretaryAlert[], a: SecretaryAlert | null): void {
    if (a) out.push(a);
}

export function buildExecutionAlerts(
    files: unknown[],
    now: Date,
    registry: DossierRegistry,
): SecretaryAlert[] {
    const out: SecretaryAlert[] = [];
    const nowTs = now.getTime();

    for (const raw of files) {
        if (!raw || typeof raw !== 'object') continue;
        const f = raw as Record<string, unknown>;
        const id = String(f.id ?? '');
        if (!id) continue;

        const ctx = registry.resolve('execution', id);
        if (!ctx) continue;

        const lifecycle = safeStr(f.dossier_lifecycle_status) || 'active';
        const isFinished = lifecycle === 'finished';
        if (isFinished) continue; // لا تنبيهات لإضبارات منتهية

        const caseNo = safeStr(f.executionCaseNumber) || safeStr(f.caseNo) || String(id);

        // 1) مهام الإضبارة المعلّقة (caseTasksPending[])
        const tasks = asArray(f.caseTasksPending);
        for (const tRaw of tasks) {
            const t = asRecord(tRaw);
            if (t.trashedAt) continue;
            const due = safeStr(t.dueDate);
            const ts = parseYmdToTs(due);
            if (ts == null) continue;
            const days = dayDiff(ts, nowTs);
            if (days < 0) continue; // متأخرة — تُعالج كمعلّق ولكن دون تكرار في الشريط
            if (days > 30) continue;
            pushAlert(
                out,
                composeRichAlert({
                    id: `execution:${id}:task:${t.id ?? due}`,
                    type: 'TASK',
                    dueAt: new Date(ts).toISOString(),
                    aiDeepDive: safeStr(t.body) || safeStr(t.title) || 'مهمة معلّقة في إضبارة التنفيذ.',
                    target: 'execution',
                    entityId: id,
                    priority: priorityByDaysToDue(days),
                    context: ctx,
                }),
            );
        }

        // 2) executive_detention_until — خلال ٧ أيام تقويمية حتى نهاية يوم الانتهاء
        const detentionUntil = safeStr(f.executive_detention_until);
        const detentionReminderSent = f.executive_detention_reminder_sent === true;
        if (detentionUntil && !detentionReminderSent) {
            const ts = parseYmdToTs(detentionUntil);
            if (ts != null) {
                const days = calendarDaysUntil(ts, nowTs);
                if (days >= 0 && days <= 7) {
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `execution:${id}:detention`,
                            type: 'DEADLINE',
                            dueAt: new Date(ts).toISOString(),
                            aiDeepDive: `ينتهي الحبس التنفيذي بتاريخ ${detentionUntil}. راجِع التمديد أو الإفراج.`,
                            target: 'execution',
                            entityId: id,
                            priority: priorityByDaysToDue(days),
                            context: ctx,
                        }),
                    );
                }
            }
        }

        // 3) eviction_vacate_deadline — مهلة الإخلاء
        const evictDeadline = safeStr(f.eviction_vacate_deadline);
        if (evictDeadline) {
            const ts = parseYmdToTs(evictDeadline);
            if (ts != null) {
                const days = dayDiff(ts, nowTs);
                if (days >= 0 && days <= 14) {
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `execution:${id}:eviction`,
                            type: 'DEADLINE',
                            dueAt: new Date(ts).toISOString(),
                            aiDeepDive: `تنتهي مهلة الإخلاء بتاريخ ${evictDeadline}. حضّر طلب الاستعانة بالقوة العامة.`,
                            target: 'execution',
                            entityId: id,
                            priority: priorityByDaysToDue(days),
                            context: ctx,
                        }),
                    );
                }
            }
        }

        // 4) eviction_first_notice_date + 7 يوم = نهاية المهلة الطوعية
        const firstNotice = safeStr(f.eviction_first_notice_date);
        if (firstNotice && !f.notice_voluntary_period_end_declared) {
            const ts = parseYmdToTs(firstNotice);
            if (ts != null) {
                const endTs = ts + 7 * DAY_MS;
                const days = dayDiff(endTs, nowTs);
                if (days >= 0 && days <= 7) {
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `execution:${id}:voluntary-end`,
                            type: 'DEADLINE',
                            dueAt: new Date(endTs).toISOString(),
                            aiDeepDive: 'تنتهي المهلة الطوعية للإخلاء (7 أيام من تاريخ التبليغ الأول). يمكن البدء بالإجراءات الجبرية.',
                            target: 'execution',
                            entityId: id,
                            priority: priorityByDaysToDue(days),
                            context: ctx,
                        }),
                    );
                }
            }
        }

        // 5) publication_notice_by_debtor — كل تبليغ بالنشر له 15 يوم
        const pubByDebtor = asRecord(f.publication_notice_by_debtor);
        for (const debtorKey of Object.keys(pubByDebtor)) {
            const entry = asRecord(pubByDebtor[debtorKey]);
            if (entry.periodEndedAt) continue; // أُعلنت نهايته
            const startYmd = safeStr(entry.publicationDateYmd);
            if (!startYmd) continue;
            const startTs = parseYmdToTs(startYmd);
            if (startTs == null) continue;
            const endTs = startTs + 15 * DAY_MS;
            const days = dayDiff(endTs, nowTs);
            if (days < 0 || days > 5) continue;
            pushAlert(
                out,
                composeRichAlert({
                    id: `execution:${id}:publication:${debtorKey}`,
                    type: 'DEADLINE',
                    dueAt: new Date(endTs).toISOString(),
                    aiDeepDive: `مدة تبليغ النشر (15 يوماً) للمدين «${debtorKey}» تقترب من الانتهاء.`,
                    target: 'execution',
                    entityId: id,
                    priority: priorityByDaysToDue(days),
                    context: ctx,
                }),
            );
        }

        // 6) employee_summons_assignments_by_debtor — تكليفات للموظف بمهلة
        const empByDebtor = asRecord(f.employee_summons_assignments_by_debtor);
        for (const debtorKey of Object.keys(empByDebtor)) {
            const entry = asRecord(empByDebtor[debtorKey]);
            const phase = safeStr(entry.phase);
            if (phase === 'completed' || phase === 'cancelled') continue;
            const dl = safeStr(entry.deadlineDate);
            if (!dl) continue;
            const ts = parseYmdToTs(dl);
            if (ts == null) continue;
            const days = dayDiff(ts, nowTs);
            if (days < 0 || days > 7) continue;
            pushAlert(
                out,
                composeRichAlert({
                    id: `execution:${id}:emp-summons:${debtorKey}`,
                    type: 'DEADLINE',
                    dueAt: new Date(ts).toISOString(),
                    aiDeepDive: `تنتهي مهلة تكليف موظف التبليغ للمدين «${debtorKey}». تابع التنفيذ.`,
                    target: 'execution',
                    entityId: id,
                    priority: priorityByDaysToDue(days),
                    context: ctx,
                }),
            );
        }

        // 7) guarantor_notification.noticeDateYmd + 7 يوم
        const guar = asRecord(f.guarantor_notification);
        const guarStart = safeStr(guar.noticeDateYmd);
        if (guarStart && !guar.endedAt && !guar.attendedAt) {
            const ts = parseYmdToTs(guarStart);
            if (ts != null) {
                const endTs = ts + 7 * DAY_MS;
                const days = dayDiff(endTs, nowTs);
                if (days >= 0 && days <= 7) {
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `execution:${id}:guarantor`,
                            type: 'DEADLINE',
                            dueAt: new Date(endTs).toISOString(),
                            aiDeepDive: 'مهلة الكفيل تنتهي قريباً — تابع الحضور أو تفعيل الكفالة.',
                            target: 'execution',
                            entityId: id,
                            priority: priorityByDaysToDue(days),
                            context: ctx,
                        }),
                    );
                }
            }
        }

        // 8) stay_of_execution.next_hearing_date — جلسة وقف التنفيذ
        const stay = asRecord(f.stay_of_execution);
        if (stay.active === true) {
            const hearing = safeStr(stay.next_hearing_date);
            if (hearing) {
                const ts = parseYmdToTs(hearing);
                if (ts != null) {
                    const days = dayDiff(ts, nowTs);
                    if (days >= 0 && days <= 14) {
                        pushAlert(
                            out,
                            composeRichAlert({
                                id: `execution:${id}:stay-hearing`,
                                type: 'HEARING',
                                dueAt: new Date(ts).toISOString(),
                                aiDeepDive: 'جلسة قادمة في طلب وقف التنفيذ.',
                                target: 'execution',
                                entityId: id,
                                priority: priorityByDaysToDue(days),
                                context: ctx,
                            }),
                        );
                    }
                }
            }
        }

        // 9) ركود الإضبارة (المادة 112 ق.ت.) — سنة بدون إجراء = سقوط حق
        const lastAction =
            safeStr(f.dossier_last_action_date) ||
            safeStr(f.lastActionDate) ||
            safeStr(f.updatedAt);
        if (lifecycle === 'active' && lastAction) {
            const ts = parseYmdToTs(lastAction);
            if (ts != null) {
                const daysSince = Math.floor((nowTs - ts) / DAY_MS);
                // ننبّه بدءاً من 300 يوم — 65 يوماً قبل السقوط
                if (daysSince >= 300) {
                    const daysToExpiry = 365 - daysSince;
                    const expiryTs = ts + 365 * DAY_MS;
                    const priority = daysToExpiry <= 14 ? 1 : daysToExpiry <= 30 ? 2 : 3;
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `execution:${id}:dormancy`,
                            type: 'URGENT',
                            dueAt: new Date(expiryTs).toISOString(),
                            aiDeepDive: `الإضبارة راكدة منذ ${daysSince} يوماً. عند 365 يوم بدون إجراء يسقط الحق وفق المادة 112 ق.ت.`,
                            target: 'execution',
                            entityId: id,
                            priority,
                            context: ctx,
                        }),
                    );
                }
            }
        }

        // 10) دفعات راكدة: total_remaining_balance > 0 + lastPaymentDate > 60 يوم
        const remaining = Number(f.total_remaining_balance ?? f.remainingDebt ?? 0);
        if (remaining > 0 && lifecycle === 'active') {
            const lastPay = safeStr(f.lastPaymentDate);
            if (lastPay) {
                const ts = parseYmdToTs(lastPay);
                if (ts != null) {
                    const daysSince = Math.floor((nowTs - ts) / DAY_MS);
                    if (daysSince >= 60) {
                        // اصطنع dueAt = اليوم + يوم (لاجتياز فلتر authenticity)
                        const dueTs = nowTs + DAY_MS;
                        pushAlert(
                            out,
                            composeRichAlert({
                                id: `execution:${id}:stale-payment`,
                                type: 'TASK',
                                dueAt: new Date(dueTs).toISOString(),
                                aiDeepDive: `لا توجد دفعات في إضبارة ${caseNo} منذ ${daysSince} يوماً، مع رصيد متبقٍّ ${remaining.toLocaleString()} د.ع. تابع جدولة التحصيل.`,
                                target: 'execution',
                                entityId: id,
                                priority: 4,
                                context: ctx,
                            }),
                        );
                    }
                }
            }
        }
    }

    return out;
}

import { SupabaseService, type ExecutionFileDTO_Supabase } from '@/app/services/SupabaseService';
import { isExecutionDossierTombstoned } from '@/app/utils/executionDossierTombstones';
import { isLiveCloudSyncBucketEnabled } from '@/app/services/settings/cloudSyncBucket';
import { debug } from '@/app/utils/debug';

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function idOf(item: unknown): string | null {
    if (!isRecord(item)) return null;
    const id = item.id;
    if (typeof id === 'string' && id.trim()) return id.trim();
    if (typeof id === 'number' && Number.isFinite(id)) return String(id);
    return null;
}

function updatedAtMsOf(item: unknown): number {
    if (!isRecord(item)) return 0;
    const v = item.updatedAt;
    if (typeof v === 'number' && Number.isFinite(v)) return v;
    if (typeof v !== 'string') return 0;
    const t = Date.parse(v);
    return Number.isNaN(t) ? 0 : t;
}

function resolveExecutionType(raw: string): ExecutionFileDTO_Supabase['executionType'] {
    if (raw === 'مدني' || raw === 'شرعي' || raw === 'التزام بعمل/تسليم') return raw;
    if (raw.includes('شرع')) return 'شرعي';
    if (raw.includes('تسليم') || raw.includes('التزام')) return 'التزام بعمل/تسليم';
    return 'مدني';
}

function toExecutionDto(item: Record<string, unknown>): ExecutionFileDTO_Supabase | null {
    const id = idOf(item);
    if (!id) return null;
    const caseNo =
        (typeof item.caseNo === 'string' && item.caseNo.trim()) ||
        [item.fileNumber, item.fileYear]
            .filter((x) => typeof x === 'string' && String(x).trim())
            .join('/') ||
        id;
    const executionType = resolveExecutionType(String(item.executionType ?? item.docType ?? '').trim());
    const statusRaw = typeof item.status === 'string' ? item.status : 'active';
    const status: ExecutionFileDTO_Supabase['status'] =
        statusRaw === 'archived' || statusRaw === 'completed' ? statusRaw : 'active';
    return {
        id,
        caseNo,
        executionType,
        court:
            typeof item.court === 'string'
                ? item.court
                : typeof item.directorate === 'string'
                  ? item.directorate
                  : '',
        executionBasis: typeof item.executionBasis === 'string' ? item.executionBasis : '',
        creditor: isRecord(item.creditor) ? item.creditor : {},
        debtor: isRecord(item.debtor) ? item.debtor : {},
        totalAmount: Number(item.totalAmount) || 0,
        status,
        createdAt: typeof item.createdAt === 'string' ? item.createdAt : undefined,
        updatedAt: typeof item.updatedAt === 'string' ? item.updatedAt : new Date().toISOString(),
    };
}

/** يختار الصفوف المحلية التي يجب دفعها (أحدث من السحابة أو غير موجودة هناك) */
export function selectExecutionRowsToPush(localRows: unknown[], cloudRows: unknown[]): unknown[] {
    const cloudMap = new Map<string, unknown>();
    for (const row of cloudRows) {
        const id = idOf(row);
        if (id) cloudMap.set(id, row);
    }
    const out: unknown[] = [];
    for (const row of localRows) {
        const id = idOf(row);
        if (!id || isExecutionDossierTombstoned(id)) continue;
        const cloud = cloudMap.get(id);
        if (!cloud || updatedAtMsOf(row) > updatedAtMsOf(cloud)) {
            out.push(row);
        }
    }
    return out;
}

const MAX_PUSH_PER_CYCLE = 25;

export async function pushDirtyExecutionFilesToCloud(
    localRows: unknown[],
    cloudRows: unknown[],
): Promise<{ attempted: number; succeeded: number }> {
    if (!isLiveCloudSyncBucketEnabled('execution')) {
        return { attempted: 0, succeeded: 0 };
    }
    const candidates = selectExecutionRowsToPush(localRows, cloudRows).slice(0, MAX_PUSH_PER_CYCLE);
    let succeeded = 0;
    for (const row of candidates) {
        if (!isRecord(row)) continue;
        const dto = toExecutionDto(row);
        if (!dto) continue;
        try {
            await SupabaseService.saveExecutionFile(dto);
            succeeded += 1;
        } catch (error) {
            debug.warn('[CloudSync] فشل دفع إضبارة تنفيذ إلى السحابة:', dto.id, error);
        }
    }
    return { attempted: candidates.length, succeeded };
}

/**
 * فلترة صفوف السحابة قبل الدمج — يمنع قيامة إضبارة محذوفة محلياً.
 */
import { isExecutionDossierTombstoned } from '@/app/utils/executionDossierTombstones';

function isRecord(value: unknown): value is Record<string, unknown> {
    return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function idOf(item: unknown): string | null {
    if (!isRecord(item)) return null;
    const id = item.id;
    if (typeof id === 'string' && id.trim()) return id.trim();
    if (typeof id === 'number' && Number.isFinite(id)) return String(id);
    return null;
}

export function filterTombstonedExecutionSyncRows(rows: unknown): unknown[] {
    if (!Array.isArray(rows)) return [];
    return rows.filter((row) => {
        const id = idOf(row);
        if (!id) return false;
        return !isExecutionDossierTombstoned(id);
    });
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { resolveFileSearchLifecycle, type SearchLifecycle } from '@/app/services/searchLifecycle';
import { normalizeArabic } from '@/app/components/lawyer/LawyerShared';
import { storageCache } from '@/app/utils/storageCache';
import { readSecureOrDrainLegacySync } from '@/app/services/storage/readSecureOrDrainLegacySync';
import {
    executionDocumentsStorageKey,
    executionStorageKey,
} from '@/app/utils/executionStorageKeys';
import { readExecutionDossierBlobScanningScopes } from '@/app/utils/executionDossierBlobPersistence';

function norm(text: string): string {
    return normalizeArabic(text).toLowerCase();
}

function blob(parts: (string | undefined | null)[]): string {
    return norm(parts.filter(Boolean).join(' '));
}

function readStorageJson(key: string): unknown {
    try {
        const cached = storageCache.get(key);
        if (cached != null) return cached;
        const raw = readSecureOrDrainLegacySync(key);
        if (!raw) return null;
        return JSON.parse(raw) as unknown;
    } catch {
        return null;
    }
}

/**
 * بلوب الإضبارة للفهرسة — عبر القارئ المدرك لنطاق المستخدم.
 *
 * الكتابة تُقيّد مفتاح البلوب الرئيسي بـ`:u:<uid>`، والقراءة هنا كانت بالمفتاح
 * الحرّ `execution_<id>`. فما دامت الجلسة قائمة تُغطّي الذاكرة المؤقتة الفرق،
 * لكنها تخلو بعد أول إعادة تحميل: فيعود `getItemSync` فارغاً، ويصمت البحث
 * العميق عن كل أحداث السجل الزمني رغم وجودها على القرص. القارئ المقيّد يجرّب
 * مفتاح المستخدم أولاً ثم يمسح النطاقات المرئية له.
 */
function readDossierPayload(id: string): Record<string, unknown> | null {
    const cached = storageCache.get(executionStorageKey(id));
    if (cached && typeof cached === 'object') return cached as Record<string, unknown>;
    return readExecutionDossierBlobScanningScopes(id);
}

type EntryDraft = Omit<GlobalSearchEntry, 'lifecycle'>;

/** أحداث السجل الزمني ومستندات مخزن كل إضبارة تنفيذ */
export function buildExecutionDeepSearchEntries(
    executionFiles: (FileData & { executionTrashDeletedAt?: string | null })[],
    stamp: (draft: EntryDraft, lifecycle: SearchLifecycle) => GlobalSearchEntry,
): GlobalSearchEntry[] {
    const out: GlobalSearchEntry[] = [];

    for (const f of executionFiles) {
        const id = String(f.id);
        const lifecycle = resolveFileSearchLifecycle(f);
        const fileLabel = f.caseNo || f.parties?.[0]?.name || id;

        const payload = readDossierPayload(id);
        const haystackParts: string[] = [];
        let firstTitle = '';
        let firstSnippet = '';

        if (payload && typeof payload === 'object') {
            const rec = payload as Record<string, unknown>;
            const events = Array.isArray(rec.timelineEvents) ? rec.timelineEvents : [];
            for (const rawEv of events) {
                if (!rawEv || typeof rawEv !== 'object') continue;
                const ev = rawEv as Record<string, unknown>;
                if (ev.trashedAt) continue;
                const title = String(ev.title ?? '').trim();
                if (!title) continue;
                const desc = String(ev.description ?? ev.details ?? '').trim();
                haystackParts.push(title, desc, String(ev.type ?? ''));
                if (!firstTitle) {
                    firstTitle = title;
                    firstSnippet = desc;
                }
            }

            const notesLog = Array.isArray(rec.caseNotesLog) ? rec.caseNotesLog : [];
            for (const rawNote of notesLog) {
                if (!rawNote || typeof rawNote !== 'object') continue;
                const n = rawNote as Record<string, unknown>;
                if (n.isDeleted || n.trashedAt) continue;
                const text = String(n.text ?? n.content ?? '').trim();
                if (!text) continue;
                haystackParts.push(text);
                if (!firstTitle) {
                    firstTitle = text.slice(0, 80);
                    firstSnippet = text;
                }
            }
        }

        const docsRaw = readStorageJson(executionDocumentsStorageKey(id));
        if (Array.isArray(docsRaw)) {
            for (const rawDoc of docsRaw) {
                if (!rawDoc || typeof rawDoc !== 'object') continue;
                const d = rawDoc as Record<string, unknown>;
                if (d.trashedAt) continue;
                const name = String(d.name ?? d.originalFileName ?? '').trim();
                if (!name) continue;
                haystackParts.push(name, String(d.folderId ?? ''));
                if (!firstTitle) firstTitle = name;
            }
        }

        if (haystackParts.length === 0) continue;

        const haystack = haystackParts.join(' ');
        out.push(
            stamp(
                {
                    id: `ex-deep-${id}`,
                    category: 'execution',
                    title: firstTitle || fileLabel,
                    subtitle: `إضبارة تنفيذ — ${fileLabel}`,
                    snippet: firstSnippet || undefined,
                    _searchStr: blob([haystack.slice(0, 8_000), fileLabel]),
                    navigate: { type: 'file', fileId: f.id },
                },
                lifecycle,
            ),
        );
    }

    return out;
}

/**
 * منسّق تسخين التنفيذ — يمنع سباق hub + archive overlay على نفس الـ chunks.
 */
let workspaceWarmGeneration = 0;
let lastWorkspaceWarmAt = 0;
let lastDossierWarmAt = 0;

const WORKSPACE_COOLDOWN_MS = 2_500;
const DOSSIER_FROM_ARCHIVE_COOLDOWN_MS = 3_000;

export function markExecutionWorkspaceWarmed(now = Date.now()): void {
    workspaceWarmGeneration += 1;
    lastWorkspaceWarmAt = now;
}

export function markExecutionDossierWarmed(now = Date.now()): void {
    lastDossierWarmAt = now;
}

/** هل يُسمح بتسخين ثانوي للإضبارة من مضيف الأرشيف؟ (تجنّب تكرار خلال نافذة قصيرة بعد تسخين الـ hub) */
export function shouldWarmExecutionDossierFromArchiveHost(now = Date.now()): boolean {
    if (now - lastDossierWarmAt < DOSSIER_FROM_ARCHIVE_COOLDOWN_MS) return false;
    if (now - lastWorkspaceWarmAt < WORKSPACE_COOLDOWN_MS) return false;
    return true;
}

export function getExecutionWarmCoordinatorSnapshot(): {
    workspaceWarmGeneration: number;
    lastWorkspaceWarmAt: number;
    lastDossierWarmAt: number;
} {
    return {
        workspaceWarmGeneration,
        lastWorkspaceWarmAt,
        lastDossierWarmAt,
    };
}

/** للاختبارات فقط */
export function __resetExecutionWarmCoordinatorForTests(): void {
    workspaceWarmGeneration = 0;
    lastWorkspaceWarmAt = 0;
    lastDossierWarmAt = 0;
}

import type { LegalTask } from '@/app/types/TaskEngine';
import type { DossierRegistry } from '@/app/services/alertDossierRegistry';
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { fieldTaskHasExplicitUserDate } from '@/app/services/calendarAuthenticity';
import {
    daysFromTodayYmd,
    isEventDateOnOrAfterToday,
    localTodayYmd,
} from '@/app/services/alertFutureGate';
import { normalizeDateToYmd } from '@/app/services/calendar/bridge/core';
import { calendarEventToTimestamp } from '@/app/utils/calendarDateTime';
import {
    isTaskDayOverdueIncomplete,
    isTaskMarkedDone,
} from '@/app/services/tasks/taskAgendaStatusLite';

export const FIELD_TASK_ALERT_ID_PREFIX = 'field-task:';

export function isInjectedFieldTaskAlert(
    alert: Pick<SecretaryAlert, 'id' | 'fieldTaskInjected' | 'calendarSource'>,
): boolean {
    if (alert.fieldTaskInjected) return true;
    const id = alert.id ?? '';
    if (id.startsWith(FIELD_TASK_ALERT_ID_PREFIX)) return true;
    return alert.calendarSource?.module === 'field_day_task';
}

export function fieldTaskDueYmd(task: LegalTask): string | null {
    if (!fieldTaskHasExplicitUserDate(task)) return null;
    if (task.reminderAt && !Number.isNaN(task.reminderAt.getTime())) {
        return normalizeDateToYmd(task.reminderAt.toISOString());
    }
    if (task.parsedDate && !Number.isNaN(task.parsedDate.getTime())) {
        return normalizeDateToYmd(task.parsedDate.toISOString());
    }
    return null;
}

function fieldTaskDueIso(task: LegalTask, ymd: string | null, now: Date): string {
    if (ymd) {
        const ts = calendarEventToTimestamp(ymd, undefined, 'end');
        if (ts !== null) return new Date(ts).toISOString();
    }
    const endToday = new Date(now);
    endToday.setHours(23, 59, 0, 0);
    return endToday.toISOString();
}

function fieldTaskLocation(task: LegalTask): string | undefined {
    const direct = task.location?.trim();
    if (direct) return direct;
    const sub = task.subTasks.find((s) => !s.isCompleted && s.location?.trim());
    return sub?.location?.trim() || undefined;
}

/**
 * حقن قراءة فقط لمهام اليوم الميدانية المعلّقة — دون تعديل مصدر Quantum Tasks.
 */
export function buildFieldTaskAlerts(
    tasks: LegalTask[],
    now: Date,
    registry: DossierRegistry,
): SecretaryAlert[] {
    const todayYmd = localTodayYmd(now);
    const out: SecretaryAlert[] = [];

    for (const task of tasks) {
        if (task.status !== 'pending') continue;
        if (isTaskMarkedDone(task)) continue;

        const ymd = fieldTaskDueYmd(task);
        const pinned = Boolean(task.pinnedToFieldCurtain);
        const overdueIncomplete = isTaskDayOverdueIncomplete(task, now);

        if (!ymd && !pinned && !overdueIncomplete) continue;

        if (ymd && !isEventDateOnOrAfterToday(ymd, now) && !overdueIncomplete) continue;

        const days = ymd ? daysFromTodayYmd(ymd, todayYmd) : 0;
        if (ymd && days > 7 && !pinned && !overdueIncomplete) continue;

        const taskId = String(task.id).trim();
        if (!taskId) continue;

        const linkedId = task.linkedCaseId?.trim() || undefined;
        const dossier = linkedId ? registry.resolve('lawsuit', linkedId) : null;
        const title = (task.title || task.rawText?.slice(0, 80) || 'مهمة ميدانية').trim();
        const location = fieldTaskLocation(task);

        const alert: SecretaryAlert = {
            id: `${FIELD_TASK_ALERT_ID_PREFIX}${taskId}`,
            type: 'DEADLINE',
            title,
            summary: overdueIncomplete
                ? location
                    ? `${location} — مهمة لم تُؤكَّد إنجازها`
                    : 'مهمة ميدانية لم تُؤكَّد إنجازها'
                : location
                  ? `${location} — مهمة ميدانية`
                  : 'مهمة ميدانية',
            dueAt: fieldTaskDueIso(task, ymd, now),
            suggestedAction: overdueIncomplete
                ? '⚠️ اضغط «إنهاء المهمة» لتأكيد الإنجاز'
                : '📋 استعراض وإنجاز المهمة الميدانية',
            aiDeepDive: task.rawText?.trim() || title,
            target: 'schedule',
            entityId: taskId,
            priority: overdueIncomplete || task.isFatalDeadline ? 1 : pinned ? 2 : 3,
            clientName: dossier?.clientName,
            caseNumber: dossier?.caseNumber,
            actionType: location || 'مهمة ميدانية',
            fieldTaskInjected: true,
            fieldTaskPinned: pinned,
            calendarSource: {
                module: 'field_day_task',
                entityId: taskId,
                ...(linkedId
                    ? { dossierModule: 'lawsuit' as const, dossierId: linkedId }
                    : {}),
            },
        };
        out.push(alert);
    }

    return out;
}

export function stripCalendarDuplicatesForFieldTasks(alerts: SecretaryAlert[]): SecretaryAlert[] {
    const injectedIds = new Set<string>();
    for (const a of alerts) {
        if (!isInjectedFieldTaskAlert(a) || !a.entityId) continue;
        injectedIds.add(String(a.entityId));
    }
    if (injectedIds.size === 0) return alerts;

    return alerts.filter((a) => {
        if (!a.id.startsWith('calendar:')) return true;
        const mod = a.calendarSource?.module;
        if (mod !== 'task' && mod !== 'field_day_task') return true;
        const entityId = a.calendarSource?.entityId ?? a.entityId;
        if (!entityId) return true;
        return !injectedIds.has(String(entityId));
    });
}

