import type { CommunityAttachment } from '@/app/services/lawyer-cloud';
import { LawyerStorage } from '@/app/services/storage/lawyerStorageRuntime';
import {
    getForumBlob,
    putForumBlob,
} from '@/app/services/forumBlobStore';
import { FORUM_IDB_PREFIX, buildForumIdbPath, parseForumIdbPath } from '@/app/services/forumBlobPath';
import { isSafeForumAttachmentUrl } from '@/app/services/forum/forumUrlSafety';

export { isSafeForumAttachmentUrl } from '@/app/services/forum/forumUrlSafety';
export { resolveCommunityAttachmentUrl } from '@/app/services/forum/forumAttachmentResolve';

const IDB_PERSIST_TIMEOUT_MS = 4_000;

function createCacheKey(): string {
    const cryptoObj = globalThis.crypto as Crypto | undefined;
    if (cryptoObj?.randomUUID) return cryptoObj.randomUUID();
    return `${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function isCloudStoragePath(path: string | undefined | null): boolean {
    const trimmed = path?.trim() ?? '';
    return Boolean(trimmed && !trimmed.startsWith(FORUM_IDB_PREFIX));
}

function isEphemeralIdbKey(idbKey: string | null): boolean {
    if (!idbKey) return true;
    return idbKey.startsWith('pending:') || idbKey.startsWith('blob:');
}

function fileToDataUrl(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(String(reader.result || ''));
        reader.onerror = () => reject(reader.error ?? new Error('forum-attachment-data-url-failed'));
        reader.readAsDataURL(file);
    });
}

async function blobUrlToFile(
    url: string,
    fileName: string,
    mimeType?: string,
): Promise<File | null> {
    try {
        const res = await fetch(url);
        if (!res.ok) return null;
        const blob = await res.blob();
        return new File([blob], fileName, {
            type: mimeType || blob.type || 'application/octet-stream',
        });
    } catch {
        return null;
    }
}

export async function readCommunityAttachmentFile(attachment: CommunityAttachment): Promise<File | null> {
    const fileName = attachment.name?.trim() || 'forum-attachment';
    const fallbackMime =
        attachment.type === 'image'
            ? 'image/jpeg'
            : attachment.type === 'audio'
              ? 'audio/webm'
              : 'application/octet-stream';
    const mimeType = attachment.mimeType || fallbackMime;

    const idbKey = parseForumIdbPath(attachment.storagePath);
    if (!idbKey || isEphemeralIdbKey(idbKey)) {
        if (attachment.url?.startsWith('blob:')) {
            const fromBlob = await blobUrlToFile(attachment.url, fileName, mimeType);
            if (fromBlob) return fromBlob;
        }
        if (attachment.url?.startsWith('data:')) {
            const fromData = await blobUrlToFile(attachment.url, fileName, mimeType);
            if (fromData) return fromData;
        }
    }

    if (idbKey && !isEphemeralIdbKey(idbKey)) {
        const fromIdb = await getForumBlob(idbKey);
        if (fromIdb) {
            return new File([fromIdb.blob], fileName, {
                type: attachment.mimeType || fromIdb.mimeType || mimeType,
            });
        }
    }

    if (attachment.url?.startsWith('blob:')) {
        return blobUrlToFile(attachment.url, fileName, mimeType);
    }

    if (attachment.url?.startsWith('data:')) {
        return blobUrlToFile(attachment.url, fileName, mimeType);
    }

    const storagePath = attachment.storagePath?.trim();
    if (isCloudStoragePath(storagePath)) {
        const signed = await LawyerStorage.getSignedUrl(storagePath!);
        if (signed) {
            return blobUrlToFile(signed, fileName, mimeType);
        }
    }

    const rawUrl = attachment.url?.trim();
    if (rawUrl && !rawUrl.startsWith('blob:') && isSafeForumAttachmentUrl(rawUrl)) {
        return blobUrlToFile(rawUrl, fileName, mimeType);
    }

    return null;
}

export { createInstantForumAttachmentPreview } from '@/app/services/forumAttachmentPreview';

/** يخزّن المرفق في IDB خلفياً — لا يُستخدم لمسار المعاينة الفورية */
export async function persistForumAttachmentFile(file: File): Promise<string> {
    const cacheKey = createCacheKey();
    try {
        await Promise.race([
            putForumBlob(cacheKey, file, file.type || 'application/octet-stream'),
            new Promise<never>((_, reject) => {
                setTimeout(() => reject(new Error('forum-attachment-timeout')), IDB_PERSIST_TIMEOUT_MS);
            }),
        ]);
        return buildForumIdbPath(cacheKey);
    } catch {
        throw new Error('forum-attachment-idb-failed');
    }
}

/** يجهّز المرفق للنشر: IDB ثم سحابة — يجب await قبل createPost */
export async function prepareForumAttachmentForPublish(
    attachment: CommunityAttachment,
    userId: string,
    sourceFile?: File | null,
): Promise<CommunityAttachment> {
    let working = { ...attachment };

    if (sourceFile) {
        const storagePath = await persistForumAttachmentFile(sourceFile);
        working = {
            ...working,
            storagePath,
            mimeType: sourceFile.type || working.mimeType,
        };
    } else if (!isCloudStoragePath(working.storagePath)) {
        const idbKey = parseForumIdbPath(working.storagePath);
        if (!idbKey || isEphemeralIdbKey(idbKey)) {
            const file = await readCommunityAttachmentFile(working);
            if (file) {
                const storagePath = await persistForumAttachmentFile(file);
                working = { ...working, storagePath };
            }
        }
    }

    try {
        return await finalizeForumAttachmentForPersist(working, userId);
    } catch {
        return persistLocalForumAttachment(working, sourceFile ?? null);
    }
}

async function persistLocalForumAttachment(
    attachment: CommunityAttachment,
    sourceFile: File | null,
): Promise<CommunityAttachment> {
    const file = sourceFile ?? (await readCommunityAttachmentFile(attachment));
    let url = attachment.url?.trim() ?? '';
    if (attachment.type === 'image' && (!url || url.startsWith('blob:')) && file) {
        try {
            const dataUrl = await fileToDataUrl(file);
            if (dataUrl.startsWith('data:image/') && isSafeForumAttachmentUrl(dataUrl)) {
                url = dataUrl;
            }
        } catch {
            /* keep existing url */
        }
    }
    return {
        ...attachment,
        url: url || attachment.url,
        mimeType: file?.type || attachment.mimeType,
        bucket: undefined,
        encrypted: undefined,
    };
}

/** يرفع المرفق للسحابة قبل حفظ المنشور — يمنع اختفاء الصور بعد إعادة التحميل */
async function finalizeForumAttachmentForPersist(
    attachment: CommunityAttachment,
    userId: string,
): Promise<CommunityAttachment> {
    const storagePath = attachment.storagePath?.trim() ?? '';

    if (isCloudStoragePath(storagePath)) {
        const signed =
            (await LawyerStorage.getSignedUrl(storagePath)) ||
            (attachment.url && !attachment.url.startsWith('blob:') ? attachment.url.trim() : '') ||
            '';
        if (signed && isSafeForumAttachmentUrl(signed) && !signed.startsWith('blob:')) {
            return {
                ...attachment,
                url: signed,
                storagePath,
            };
        }
    }

    const file = await readCommunityAttachmentFile(attachment);
    if (!file) {
        throw new Error('forum-attachment-missing-bytes');
    }

    const category =
        attachment.type === 'image' ? 'forum-media' : attachment.type === 'audio' ? 'audio' : 'drafts';
    try {
        const uploaded = await LawyerStorage.uploadSmartFile(userId, file, category);
        const cloudPath = uploaded.path || uploaded.fullPath;
        const url =
            uploaded.downloadUrl ||
            (cloudPath ? await LawyerStorage.getSignedUrl(cloudPath) : '') ||
            '';
        if (cloudPath && url && isSafeForumAttachmentUrl(url)) {
            return {
                ...attachment,
                url,
                storagePath: cloudPath,
                bucket: uploaded.bucket || (category === 'forum-media' ? 'forum-media' : attachment.bucket),
                mimeType: file.type || attachment.mimeType,
            };
        }
    } catch {
        /* يبقى المسار المحلي */
    }

    return persistLocalForumAttachment(attachment, file);
}

/** بادئة مسار IndexedDB للمرفقات — بلا فتح قاعدة ولا تشفير */

export const FORUM_IDB_PREFIX = 'idb:forum:';

export function buildForumIdbPath(cacheKey: string): string {
    return `${FORUM_IDB_PREFIX}${cacheKey.trim()}`;
}

export function parseForumIdbPath(path: string | undefined | null): string | null {
    if (!path?.startsWith(FORUM_IDB_PREFIX)) return null;
    const key = path.slice(FORUM_IDB_PREFIX.length).trim();
    return key || null;
}

import { unwrapForumBlobFromAtRest, wrapForumBlobForAtRest } from '@/app/services/forum/forumBlobAtRest';

export {
    FORUM_IDB_PREFIX,
    buildForumIdbPath,
    parseForumIdbPath,
} from '@/app/services/forumBlobPath';

const DB_NAME = 'hami-forum-blobs';
const DB_VERSION = 1;
const STORE = 'attachments';

type ForumBlobRow = {
    key: string;
    mimeType: string;
    size: number;
    blob: Blob;
    updatedAt: string;
    encrypted?: boolean;
};

function openDb(): Promise<IDBDatabase | null> {
    if (typeof indexedDB === 'undefined') return Promise.resolve(null);
    return new Promise((resolve) => {
        try {
            const request = indexedDB.open(DB_NAME, DB_VERSION);
            request.onerror = () => resolve(null);
            request.onsuccess = () => resolve(request.result);
            request.onupgradeneeded = () => {
                const db = request.result;
                if (!db.objectStoreNames.contains(STORE)) {
                    db.createObjectStore(STORE, { keyPath: 'key' });
                }
            };
        } catch {
            resolve(null);
        }
    });
}

function writeForumBlobRow(db: IDBDatabase, row: ForumBlobRow): Promise<void> {
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE, 'readwrite');
        tx.oncomplete = () => {
            db.close();
            resolve();
        };
        tx.onerror = () => {
            db.close();
            reject(tx.error ?? new Error('forum blob write failed'));
        };
        tx.onabort = () => {
            db.close();
            reject(tx.error ?? new Error('forum blob write aborted'));
        };
        tx.objectStore(STORE).put(row);
    });
}

export async function putForumBlob(cacheKey: string, blob: Blob, mimeType: string): Promise<void> {
    const wrapped = await wrapForumBlobForAtRest(blob);
    const db = await openDb();
    if (!db) throw new Error('forum blob store unavailable');

    const row: ForumBlobRow = {
        key: cacheKey.trim(),
        mimeType: mimeType || blob.type || 'application/octet-stream',
        size: blob.size,
        blob: wrapped.blob,
        updatedAt: new Date().toISOString(),
        ...(wrapped.encrypted ? { encrypted: true } : {}),
    };

    await writeForumBlobRow(db, row);
}

export async function getForumBlob(
    cacheKey: string,
): Promise<{ blob: Blob; mimeType: string } | null> {
    const db = await openDb();
    if (!db) return null;

    const row = await new Promise<ForumBlobRow | null>((resolve) => {
        let value: ForumBlobRow | null = null;
        const tx = db.transaction(STORE, 'readonly');
        const req = tx.objectStore(STORE).get(cacheKey.trim());
        req.onsuccess = () => {
            value = (req.result as ForumBlobRow | undefined) ?? null;
        };
        req.onerror = () => {
            value = null;
        };
        tx.oncomplete = () => {
            db.close();
            resolve(value);
        };
        tx.onerror = () => {
            db.close();
            resolve(null);
        };
        tx.onabort = () => {
            db.close();
            resolve(null);
        };
    });

    if (!row?.blob) return null;
    const mimeType = row.mimeType || row.blob.type || 'application/octet-stream';
    const plain = await unwrapForumBlobFromAtRest({
        blob: row.blob,
        mimeType,
        encrypted: row.encrypted,
    });
    if (!plain) return null;
    if (!row.encrypted) {
        maybeUpgradeLegacyForumBlob(cacheKey, plain, mimeType);
    }
    return { blob: plain, mimeType };
}

function maybeUpgradeLegacyForumBlob(cacheKey: string, plain: Blob, mimeType: string): void {
    void (async () => {
        try {
            const wrapped = await wrapForumBlobForAtRest(plain);
            if (!wrapped.encrypted) return;
            const db = await openDb();
            if (!db) return;
            await writeForumBlobRow(db, {
                key: cacheKey.trim(),
                mimeType,
                size: plain.size,
                blob: wrapped.blob,
                updatedAt: new Date().toISOString(),
                encrypted: true,
            });
        } catch {
            /* fail-open: keep serving the plaintext already returned */
        }
    })();
}

export async function getForumBlobObjectUrl(cacheKey: string): Promise<string | null> {
    const row = await getForumBlob(cacheKey);
    if (!row) return null;
    return URL.createObjectURL(row.blob);
}

export async function deleteForumBlob(cacheKey: string): Promise<void> {
    const key = cacheKey.trim();
    if (!key) return;
    const db = await openDb();
    if (!db) return;
    await new Promise<void>((resolve) => {
        const tx = db.transaction(STORE, 'readwrite');
        tx.oncomplete = () => {
            db.close();
            resolve();
        };
        tx.onerror = () => {
            db.close();
            resolve();
        };
        tx.onabort = () => {
            db.close();
            resolve();
        };
        tx.objectStore(STORE).delete(key);
    });
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import type { ForumNotification } from '@/app/services/forum/forumTypes';
import { emitForumUnreadCount } from '@/app/services/forum/forumNotificationEvents';
import { notifyForumActivity } from '@/app/services/notifications/domainNotifications';
import { canReachProtectedServerNetwork } from '@/app/services/secureApiNetworkFeatures';
import { isAppForeground, subscribeAppForeground } from '@/app/runtime/appForegroundGate';
import { readPersistedSupabaseAuth } from '@/app/utils/authStorage';

export type ForumStreamPayload = {
    type?: 'connected';
    unreadCount: number;
    latestId?: string | null;
    notification?: ForumNotification | null;
};

type StreamHandler = (payload: ForumStreamPayload) => void;

let running = false;
let refCount = 0;
let streamUserId: string | null = null;
let reconnectTimer: ReturnType<typeof setTimeout> | null = null;
let lastPushedId: string | null = null;
let releaseForegroundGate: (() => void) | null = null;
/** الخلفية تُغلق البثّ لكنها لا تُلغي الاشتراك — العودة تعيد فتحه لنفس المشتركين. */
let suspendedForBackground = false;
const handlers = new Set<StreamHandler>();

function canStartForumStream(userId: string): boolean {
    const persisted = readPersistedSupabaseAuth();
    const meta = (persisted.user?.user_metadata ?? null) as Record<string, unknown> | null;
    return canReachProtectedServerNetwork(userId, meta);
}

function isExpectedStreamDenial(err: unknown): boolean {
    if (!(err instanceof Error)) return false;
    if (err.message.startsWith('stream 403')) return true;
    if (err.message.includes('NETWORK_FEATURES_DENIED')) return true;
    return false;
}

function parseSseChunk(buffer: string): { events: ForumStreamPayload[]; rest: string } {
    const events: ForumStreamPayload[] = [];
    const parts = buffer.split('\n\n');
    const rest = parts.pop() ?? '';
    for (const part of parts) {
        for (const line of part.split('\n')) {
            if (!line.startsWith('data:')) continue;
            const raw = line.slice(5).trim();
            if (!raw) continue;
            try {
                events.push(JSON.parse(raw) as ForumStreamPayload);
            } catch {
                /* skip */
            }
        }
    }
    return { events, rest };
}

async function consumeStream(onPayload: StreamHandler, signal: AbortSignal): Promise<void> {
    const response = await SecureAPIClient.fetchSecureResponse('/api/forum/notifications/stream', {
        method: 'GET',
        signal,
        headers: { Accept: 'text/event-stream' },
    });

    if (!response.ok || !response.body) {
        throw new Error(`stream ${response.status}`);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (!signal.aborted) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const { events, rest } = parseSseChunk(buffer);
        buffer = rest;
        for (const ev of events) onPayload(ev);
    }
}

function dispatchPayload(payload: ForumStreamPayload): void {
    if (typeof payload.unreadCount === 'number') {
        emitForumUnreadCount(payload.unreadCount, { refresh: true });
    }

    const notif = payload.notification;
    if (notif && !notif.read && notif.id && notif.id !== lastPushedId) {
        lastPushedId = notif.id;
        void notifyForumActivity({
            title: notif.title,
            message: notif.message,
            postId: notif.postId,
            type: notif.type,
        });
    }

    for (const h of handlers) h(payload);
}

function scheduleReconnect(userId: string): void {
    if (reconnectTimer) clearTimeout(reconnectTimer);
    reconnectTimer = setTimeout(() => {
        reconnectTimer = null;
        /* إعادة الوصل للمقدّمة فقط: في الخلفية تتحوّل إلى دورة إشعال للراديو */
        if (running && refCount > 0 && isAppForeground()) {
            void ForumNotificationStreamService.start(userId);
        }
    }, 3_000);
}

function abortActiveStream(): void {
    const abort = (ForumNotificationStreamService as { _abort?: AbortController })._abort;
    abort?.abort();
    (ForumNotificationStreamService as { _abort?: AbortController })._abort = undefined;
}

/*
 * البثّ لا يُترك مفتوحاً والتطبيق في الخلفية: الاتصال المفتوح يُبقي الراديو مستيقظاً،
 * والنظام يقطعه فتدخل `scheduleReconnect` دورة إعادة وصل كل ٣ ثوانٍ بلا نهاية.
 * التسليم في الخلفية يمرّ عبر دفع FCM، فلا يُفقد تنبيه بإغلاق البثّ هنا.
 */
function bindForegroundGate(): void {
    if (releaseForegroundGate) return;
    releaseForegroundGate = subscribeAppForeground({
        onSuspend: () => {
            if (!running && !reconnectTimer) return;
            suspendedForBackground = true;
            ForumNotificationStreamService.stop();
        },
        onResume: () => {
            if (!suspendedForBackground) return;
            suspendedForBackground = false;
            const userId = streamUserId;
            if (refCount > 0 && userId) void ForumNotificationStreamService.start(userId);
        },
    });
}

function unbindForegroundGate(): void {
    releaseForegroundGate?.();
    releaseForegroundGate = null;
    suspendedForBackground = false;
}

export const ForumNotificationStreamService = {
    isRunning(): boolean {
        return running;
    },

    subscribe(handler: StreamHandler): () => void {
        handlers.add(handler);
        return () => handlers.delete(handler);
    },

    acquire(userId: string): () => void {
        if (!userId) return () => undefined;

        refCount += 1;
        const userChanged = streamUserId !== userId;
        streamUserId = userId;
        bindForegroundGate();

        if (userChanged && running) {
            abortActiveStream();
            running = false;
        }
        /* في الخلفية لا يُفتح بثّ عند الاشتراك — العودة للمقدّمة هي التي تفتحه */
        if (!running && isAppForeground()) {
            void ForumNotificationStreamService.start(userId);
        } else if (!running) {
            suspendedForBackground = true;
        }

        return () => {
            refCount = Math.max(0, refCount - 1);
            if (refCount === 0) {
                streamUserId = null;
                unbindForegroundGate();
                ForumNotificationStreamService.stop();
            }
        };
    },

    async start(userId: string | null): Promise<void> {
        if (!userId || typeof window === 'undefined') return;
        if (!canStartForumStream(userId)) {
            running = false;
            return;
        }
        if (!isAppForeground()) {
            /* فحص الصحّة الدوري قد ينادي `start` بعد الخلفية — لا يُفتح بثّ هناك */
            suspendedForBackground = true;
            running = false;
            return;
        }
        if (running && streamUserId === userId) return;

        abortActiveStream();
        if (reconnectTimer) {
            clearTimeout(reconnectTimer);
            reconnectTimer = null;
        }

        running = true;
        streamUserId = userId;

        const controller = new AbortController();
        (ForumNotificationStreamService as { _abort?: AbortController })._abort = controller;

        try {
            await consumeStream(dispatchPayload, controller.signal);
        } catch (err) {
            if (isExpectedStreamDenial(err)) {
                running = false;
                return;
            }
            /* reconnect below */
        } finally {
            if (running && !controller.signal.aborted && refCount > 0 && canStartForumStream(userId)) {
                scheduleReconnect(userId);
            }
        }
    },

    stop(): void {
        running = false;
        if (reconnectTimer) {
            clearTimeout(reconnectTimer);
            reconnectTimer = null;
        }
        abortActiveStream();
    },

    /** @internal — إعادة حالة الخدمة في الاختبارات فقط */
    _resetForTests(): void {
        refCount = 0;
        streamUserId = null;
        lastPushedId = null;
        handlers.clear();
        unbindForegroundGate();
        this.stop();
    },
};

