    shouldRethrowForumMutationError,
    withForumMutationFallback,
    withForumReadFallback,
    type ForumApiOk,
} from '@/app/services/forum/forumApi/forumApiClientCore';
import {
    deleteCommunityPost,
    reportCommunityPost,
    updateCommunityPost,
} from '@/app/services/cloud/lawyerCommunityCloud';
