export async function toggleForumPostSubscription(
    postId: string,
    requesterId?: string | null,
): Promise<boolean> {
    const userId = await getForumSessionUserId(requesterId);
    if (!userId) throw new Error('يجب تسجيل الدخول');

    const wasSubscribed = await ForumPostFollowRepository.isSubscribed(userId, postId);
    let subscribed: boolean;
    if (wasSubscribed) {
        await ForumPostFollowRepository.unsubscribe(userId, postId);
        subscribed = false;
    } else {
        await ForumPostFollowRepository.subscribe(userId, postId);
        subscribed = true;
    }

    void forumApiPostJson<ApiOk<{ subscribed: boolean }>>('/api/forum/post-follow', {
        postId,
        action: 'toggle',
    }).catch(() => undefined);

    return subscribed;
}

import type { CommunityAttachment } from '@/app/services/cloud/lawyerCommunityTypes';
import { isSafeForumAttachmentUrl } from '@/app/services/forum/forumUrlSafety';
import { FORUM_IDB_PREFIX, parseForumIdbPath } from '@/app/services/forumBlobPath';

function isCloudStoragePath(path: string | undefined | null): boolean {
    const trimmed = path?.trim() ?? '';
    return Boolean(trimmed && !trimmed.startsWith(FORUM_IDB_PREFIX));
}

function isEphemeralIdbKey(idbKey: string | null): boolean {
    if (!idbKey) return true;
    return idbKey.startsWith('pending:') || idbKey.startsWith('blob:');
}

function isEncryptedForumAttachment(
    attachment: CommunityAttachment,
    storagePath: string,
): boolean {
    if (attachment.encrypted === true) return true;
    return /\.enc$/i.test(storagePath);
}

async function blobUrlToFile(
    url: string,
    fileName: string,
    mimeType?: string,
): Promise<File | null> {
    try {
        const res = await fetch(url);
        if (!res.ok) return null;
        const blob = await res.blob();
        return new File([blob], fileName, {
            type: mimeType || blob.type || 'application/octet-stream',
        });
    } catch {
        return null;
    }
}

/** يُجدّد رابط المرفق (signed URL منتهٍ، blob ميت، أو idb) — بلا LawyerStorage على التقييم */
export async function resolveCommunityAttachmentUrl(
    attachment: CommunityAttachment | null | undefined,
): Promise<string | null> {
    if (!attachment) return null;

    const storagePath = attachment.storagePath?.trim() ?? '';
    if (isEncryptedForumAttachment(attachment, storagePath)) {
        try {
            const { resolveEncryptedForumImageUrl } = await import('@/lib/forumService.js');
            const decrypted = await resolveEncryptedForumImageUrl(attachment);
            if (decrypted) return decrypted;
        } catch {
            /* نكمل المسارات غير المشفّرة */
        }
    }

    if (isCloudStoragePath(storagePath)) {
        const { LawyerStorage } = await import('@/app/services/storage/lawyerStorageRuntime');
        const fresh = await LawyerStorage.getSignedUrl(storagePath);
        if (fresh) {
            return fresh;
        }
    }

    const idbKey = parseForumIdbPath(storagePath);
    if (idbKey && !isEphemeralIdbKey(idbKey)) {
        const { getForumBlobObjectUrl } = await import('@/app/services/forumBlobStore');
        const fromIdb = await getForumBlobObjectUrl(idbKey);
        if (fromIdb) {
            return fromIdb;
        }
    }

    if (attachment.url?.startsWith('data:')) {
        return isSafeForumAttachmentUrl(attachment.url) ? attachment.url : null;
    }

    const rawUrl = attachment.url?.trim();
    if (rawUrl && !rawUrl.startsWith('blob:') && isSafeForumAttachmentUrl(rawUrl)) {
        return rawUrl;
    }
    if (rawUrl?.startsWith('blob:')) {
        const file = await blobUrlToFile(rawUrl, attachment.name || 'attachment', attachment.mimeType);
        if (file) {
            return URL.createObjectURL(file);
        }
    }

    return null;
}

import type { CommunityPost } from '@/app/services/forum/forumTypes';
import { FORUM_MEDIA_BUCKET, SIGNED_URL_TTL_SEC, resolveUploadBucket } from '@/app/api/upload/uploadStorageUtils';
import { isCloudForumStoragePath } from '@/app/services/forum/forumPostCreateGuard';
import { loadForumSupabaseAdmin } from '@/app/services/forum/loadForumSupabaseAdmin';

function resolveAttachmentBucket(attachment: NonNullable<CommunityPost['attachment']>): string {
    if (attachment.bucket === FORUM_MEDIA_BUCKET || attachment.encrypted === true) {
        return FORUM_MEDIA_BUCKET;
    }
    if (attachment.bucket?.trim()) return attachment.bucket.trim();
    if (attachment.type === 'image') return FORUM_MEDIA_BUCKET;
    return resolveUploadBucket();
}

/** يوقع روابط المرفقات للمشاهدين — لا يُخزَّن الرابط الموقّع في Postgres. */
export async function signForumPostAttachments(posts: CommunityPost[]): Promise<CommunityPost[]> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) return posts;

    return Promise.all(
        posts.map(async (post) => {
            const attachment = post.attachment;
            if (!attachment || !isCloudForumStoragePath(attachment.storagePath)) return post;
            const { data } = await admin.storage
                .from(resolveAttachmentBucket(attachment))
                .createSignedUrl(attachment.storagePath!, SIGNED_URL_TTL_SEC);
            if (!data?.signedUrl) return post;
            return {
                ...post,
                attachment: {
                    ...attachment,
                    url: data.signedUrl,
                },
            };
        }),
    );
}

import { resolveLawyerDisplayName } from '@/app/services/profile/resolveLawyerDisplayName';

const DISPLAY_NAME_CACHE_TTL_MS = 60_000;
const displayNameCache = new Map<string, { name: string; expiresAt: number }>();

function readCachedName(userId: string): string | undefined {
    const cached = displayNameCache.get(userId);
    if (!cached) return undefined;
    if (Date.now() >= cached.expiresAt) {
        displayNameCache.delete(userId);
        return undefined;
    }
    return cached.name;
}

function writeCachedName(userId: string, name: string): void {
    displayNameCache.set(userId, { name, expiresAt: Date.now() + DISPLAY_NAME_CACHE_TTL_MS });
}

async function readProfileNameFromKv(userId: string): Promise<string> {
    if (typeof window !== 'undefined') return '';
    try {
        const spec = '@/app/api/security/kvStoreAdmin.ts';
        const { kvGet } = await import(/* @vite-ignore */ spec);
        const raw = await kvGet(`profile:${userId}`);
        if (!raw || typeof raw !== 'object') return '';
        const header = (raw as { header?: { name?: unknown } }).header;
        const name = typeof header?.name === 'string' ? header.name.trim() : '';
        return name;
    } catch {
        return '';
    }
}

/** اسم العرض الموثوق من السيرفر — لا نثق بـ authorName القادم من العميل. */
export async function resolveForumAuthorDisplayName(userId: string): Promise<string> {
    if (!userId.trim()) return 'المحامي';

    const cached = readCachedName(userId);
    if (cached) return cached;

    const profileName = await readProfileNameFromKv(userId);
    const resolved = resolveLawyerDisplayName(profileName, userId);
    writeCachedName(userId, resolved);
    return resolved;
}

