import { FollowDB } from '@/app/services/cloud/lawyerCommunityFollowDb';
import type { FollowRecord } from '@/app/services/cloud/lawyerCommunityTypes';
import { loadForumSupabaseAdmin } from './loadForumSupabaseAdmin';

import type { ForumFollowPrefs, ForumFollowRecord } from './forumFollowTypes';
import { readSecureJsonRaw, persistSecureJsonValue } from '@/app/services/storage/syncSecureJson';

const DEFAULT_PREFS: ForumFollowPrefs = {
    notifyPosts: true,
    notifyComments: true,
    notifyReplies: true,
};

const PREFS_LOCAL_KEY = 'hami:forum:follow:prefs:v1';

function rowToRecord(row: Record<string, unknown>): ForumFollowRecord {
    return {
        followerId: String(row.follower_id),
        followingId: String(row.following_id),
        createdAt: String(row.created_at ?? new Date().toISOString()),
        notifyPosts: row.notify_posts !== false,
        notifyComments: row.notify_comments !== false,
        notifyReplies: row.notify_replies !== false,
    };
}

async function loadLocalPrefs(): Promise<Record<string, ForumFollowPrefs>> {
    try {
        const raw = await readSecureJsonRaw(PREFS_LOCAL_KEY);
        if (!raw) return {};
        const parsed = JSON.parse(raw) as Record<string, ForumFollowPrefs>;
        return parsed && typeof parsed === 'object' ? parsed : {};
    } catch {
        return {};
    }
}

async function saveLocalPrefs(map: Record<string, ForumFollowPrefs>): Promise<void> {
    await persistSecureJsonValue(PREFS_LOCAL_KEY, map);
}

function prefsKey(followerId: string, followingId: string): string {
    return `${followerId}:${followingId}`;
}

function attachLocalPrefs(records: FollowRecord[], prefsMap: Record<string, ForumFollowPrefs>): ForumFollowRecord[] {
    return records.map((r) => {
        const prefs = prefsMap[prefsKey(r.followerId, r.followingId)] ?? DEFAULT_PREFS;
        return { ...r, ...prefs };
    });
}

export const ForumFollowRepository = {
    async follow(
        followerId: string,
        followingId: string,
        prefs: Partial<ForumFollowPrefs> = {},
    ): Promise<ForumFollowRecord> {
        if (followerId === followingId) {
            throw new Error('لا يمكنك متابعة نفسك');
        }
        const merged: ForumFollowPrefs = { ...DEFAULT_PREFS, ...prefs };
        const admin = await loadForumSupabaseAdmin();
        const createdAt = new Date().toISOString();

        if (!admin) {
            await FollowDB.follow(followerId, followingId);
            const map = await loadLocalPrefs();
            map[prefsKey(followerId, followingId)] = merged;
            await saveLocalPrefs(map);
            return { followerId, followingId, createdAt, ...merged };
        }

        const { error } = await admin.from('forum_follows').upsert(
            {
                follower_id: followerId,
                following_id: followingId,
                notify_posts: merged.notifyPosts,
                notify_comments: merged.notifyComments,
                notify_replies: merged.notifyReplies,
                created_at: createdAt,
            },
            { onConflict: 'follower_id,following_id' },
        );
        if (error) throw new Error(error.message);
        return { followerId, followingId, createdAt, ...merged };
    },

    async unfollow(followerId: string, followingId: string): Promise<void> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            await FollowDB.unfollow(followerId, followingId);
            const map = await loadLocalPrefs();
            delete map[prefsKey(followerId, followingId)];
            await saveLocalPrefs(map);
            return;
        }
        const { error } = await admin
            .from('forum_follows')
            .delete()
            .eq('follower_id', followerId)
            .eq('following_id', followingId);
        if (error) throw new Error(error.message);
    },

    async isFollowing(followerId: string, followingId: string): Promise<boolean> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) return FollowDB.isFollowing(followerId, followingId);
        const { data } = await admin
            .from('forum_follows')
            .select('follower_id')
            .eq('follower_id', followerId)
            .eq('following_id', followingId)
            .maybeSingle();
        return Boolean(data);
    },

    async getFollowing(followerId: string): Promise<ForumFollowRecord[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const prefsMap = await loadLocalPrefs();
            return attachLocalPrefs(await FollowDB.getFollowing(followerId), prefsMap);
        }
        const { data, error } = await admin
            .from('forum_follows')
            .select('*')
            .eq('follower_id', followerId)
            .order('created_at', { ascending: false });
        if (error || !data) return [];
        return (data as Record<string, unknown>[]).map(rowToRecord);
    },

    async getFollowers(followingId: string): Promise<ForumFollowRecord[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const prefsMap = await loadLocalPrefs();
            return attachLocalPrefs(await FollowDB.getFollowers(followingId), prefsMap);
        }
        const { data, error } = await admin
            .from('forum_follows')
            .select('*')
            .eq('following_id', followingId)
            .order('created_at', { ascending: false });
        if (error || !data) return [];
        return (data as Record<string, unknown>[]).map(rowToRecord);
    },

    async getFollowerCount(userId: string): Promise<number> {
        const followers = await this.getFollowers(userId);
        return followers.length;
    },

    async updatePreferences(
        followerId: string,
        followingId: string,
        prefs: Partial<ForumFollowPrefs>,
    ): Promise<ForumFollowRecord> {
        const existing = await this.getFollowing(followerId);
        const row = existing.find((r) => r.followingId === followingId);
        if (!row) throw new Error('لم تعد تتابع هذا المحامي');
        const merged: ForumFollowPrefs = {
            notifyPosts: prefs.notifyPosts ?? row.notifyPosts,
            notifyComments: prefs.notifyComments ?? row.notifyComments,
            notifyReplies: prefs.notifyReplies ?? row.notifyReplies,
        };

        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const map = await loadLocalPrefs();
            map[prefsKey(followerId, followingId)] = merged;
            await saveLocalPrefs(map);
            return { ...row, ...merged };
        }

        const { error } = await admin
            .from('forum_follows')
            .update({
                notify_posts: merged.notifyPosts,
                notify_comments: merged.notifyComments,
                notify_replies: merged.notifyReplies,
            })
            .eq('follower_id', followerId)
            .eq('following_id', followingId);
        if (error) throw new Error(error.message);
        return { ...row, ...merged };
    },
};

/** أنواع المتابعة — منفصلة عن المستودع لتجنّب سحب كود الخادم في العميل */
export type ForumFollowPrefs = {
    notifyPosts: boolean;
    notifyComments: boolean;
    notifyReplies: boolean;
};

export type ForumFollowRecord = {
    followerId: string;
    followingId: string;
    createdAt: string;
} & ForumFollowPrefs;

import type {
    CreateForumGroupInput,
    ForumGroup,
    ForumGroupMember,
    ForumGroupMemberRow,
    ForumGroupRow,
} from './forumGroupTypes';
import { readSecureJsonRawSync, writeSecureJsonValue } from '@/app/services/storage/syncSecureJson';

const GROUPS_KEY = 'hami:forum:groups:v1';
const MEMBERS_KEY = 'hami:forum:group-members:v1';

function createId(): string {
    const cryptoObj = globalThis.crypto as Crypto | undefined;
    if (cryptoObj?.randomUUID) return cryptoObj.randomUUID();
    return `${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function readJson<T>(key: string): T[] {
    const raw = readSecureJsonRawSync(key);
    if (!raw) return [];
    try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? (parsed as T[]) : [];
    } catch {
        return [];
    }
}

function writeJson<T>(key: string, rows: T[]): void {
    writeSecureJsonValue(key, rows);
}

function rowToGroup(
    row: ForumGroupRow,
    memberCount: number,
    viewerId: string | null,
    members: ForumGroupMemberRow[],
): ForumGroup {
    const membership = viewerId
        ? members.find((m) => m.group_id === row.id && m.lawyer_id === viewerId)
        : undefined;
    return {
        id: row.id,
        name: row.name,
        description: row.description ?? '',
        coverImage: row.cover_image,
        creatorId: row.creator_id,
        isOfficial: row.is_official,
        createdAt: row.created_at,
        memberCount,
        isMember: Boolean(membership),
        viewerRole: membership?.role ?? null,
    };
}

export const ForumGroupLocalStore = {
    listGroups(viewerId: string | null, query = ''): ForumGroup[] {
        const groups = readJson<ForumGroupRow>(GROUPS_KEY);
        const members = readJson<ForumGroupMemberRow>(MEMBERS_KEY);
        const q = query.trim().toLowerCase();
        const filtered = q
            ? groups.filter(
                  (g) =>
                      g.name.toLowerCase().includes(q) ||
                      (g.description ?? '').toLowerCase().includes(q),
              )
            : groups;
        return filtered
            .map((row) => {
                const memberCount = members.filter((m) => m.group_id === row.id).length;
                return rowToGroup(row, memberCount, viewerId, members);
            })
            .sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
    },

    getGroup(groupId: string, viewerId: string | null): ForumGroup | null {
        return this.listGroups(viewerId).find((g) => g.id === groupId) ?? null;
    },

    createGroup(creatorId: string, input: CreateForumGroupInput): ForumGroup {
        const groups = readJson<ForumGroupRow>(GROUPS_KEY);
        const members = readJson<ForumGroupMemberRow>(MEMBERS_KEY);
        const now = new Date().toISOString();
        const row: ForumGroupRow = {
            id: createId(),
            name: input.name.trim(),
            description: input.description.trim(),
            cover_image: input.coverImage?.trim() || null,
            creator_id: creatorId,
            is_official: input.isOfficial === true,
            created_at: now,
        };
        groups.unshift(row);
        const memberRow: ForumGroupMemberRow = {
            id: createId(),
            group_id: row.id,
            lawyer_id: creatorId,
            role: 'admin',
            joined_at: now,
        };
        members.push(memberRow);
        writeJson(GROUPS_KEY, groups);
        writeJson(MEMBERS_KEY, members);
        return rowToGroup(row, 1, creatorId, members);
    },

    joinGroup(groupId: string, lawyerId: string): ForumGroupMember | null {
        const groups = readJson<ForumGroupRow>(GROUPS_KEY);
        if (!groups.some((g) => g.id === groupId)) return null;
        const members = readJson<ForumGroupMemberRow>(MEMBERS_KEY);
        const existing = members.find((m) => m.group_id === groupId && m.lawyer_id === lawyerId);
        if (existing) {
            return {
                id: existing.id,
                groupId: existing.group_id,
                lawyerId: existing.lawyer_id,
                role: existing.role,
                joinedAt: existing.joined_at,
            };
        }
        const row: ForumGroupMemberRow = {
            id: createId(),
            group_id: groupId,
            lawyer_id: lawyerId,
            role: 'member',
            joined_at: new Date().toISOString(),
        };
        members.push(row);
        writeJson(MEMBERS_KEY, members);
        return {
            id: row.id,
            groupId: row.group_id,
            lawyerId: row.lawyer_id,
            role: row.role,
            joinedAt: row.joined_at,
        };
    },

    leaveGroup(groupId: string, lawyerId: string): boolean {
        const members = readJson<ForumGroupMemberRow>(MEMBERS_KEY);
        const next = members.filter((m) => !(m.group_id === groupId && m.lawyer_id === lawyerId));
        if (next.length === members.length) return false;
        writeJson(MEMBERS_KEY, next);
        return true;
    },

    isMember(groupId: string, lawyerId: string): boolean {
        return readJson<ForumGroupMemberRow>(MEMBERS_KEY).some(
            (m) => m.group_id === groupId && m.lawyer_id === lawyerId,
        );
    },

    listMemberIds(groupId: string): string[] {
        return readJson<ForumGroupMemberRow>(MEMBERS_KEY)
            .filter((m) => m.group_id === groupId)
            .map((m) => m.lawyer_id);
    },
};

