/** العمود المطبّع المولَّد — انظر هجرة 20260830120000_forum_search_text.sql */
export const FORUM_SEARCH_TEXT_COLUMN = 'search_text';

function escapeIlikeBody(text: string): string | null {
    const escaped = text
        .replace(/\\/g, '')
        .replace(/[%_,()"]/g, ' ')
        .replace(/\s+/g, ' ')
        .trim();
    return escaped || null;
}

/**
 * نمط ILIKE مطبّع — يقابل `search_text` المولَّد على الخادم.
 * الطيّ هنا صحيح فقط لأن العمود مطبّع بنفس القواعد.
 */
export function forumIlikeContainsPattern(raw: string): string | null {
    const folded = normalizeArabicSearch(clampGlobalSearchQuery(raw));
    if (!folded) return null;
    const body = escapeIlikeBody(folded);
    return body ? `%${body}%` : null;
}

/** نمط ILIKE بلا طيّ — للأعمدة الخام قبل تطبيق هجرة `search_text`. */
export function forumIlikeRawContainsPattern(raw: string): string | null {
    const body = escapeIlikeBody(clampGlobalSearchQuery(raw));
    return body ? `%${body}%` : null;
}

export function forumOrIlikeContentAndAuthor(pattern: string): string {
    const quoted = `"${pattern}"`;
    return `content.ilike.${quoted},author_name.ilike.${quoted}`;
}

export function forumOrIlikeTitleAndDescription(pattern: string): string {
    const quoted = `"${pattern}"`;
    return `title.ilike.${quoted},description.ilike.${quoted},author_name.ilike.${quoted}`;
}

/** هل فشل الاستعلام لأن هجرة `search_text` لم تُطبَّق بعد؟ */
export function isMissingSearchTextColumn(message: string | null | undefined): boolean {
    if (!message) return false;
    return (
        message.includes(FORUM_SEARCH_TEXT_COLUMN) &&
        /does not exist|schema cache|undefined column|42703/i.test(message)
    );
}

const MAX_DIMENSION_PX = 2048;
const COMPRESS_THRESHOLD_BYTES = 1_500_000;
const JPEG_QUALITY = 0.85;

/** صيَغ لا تُضغط: GIF (حركة)، SVG (متجه)، وغير الصور */
function isCompressibleImage(file: File): boolean {
    const type = file.type.toLowerCase();
    if (!type.startsWith('image/')) return false;
    if (type === 'image/gif' || type === 'image/svg+xml') return false;
    return true;
}

async function decodeImage(file: File): Promise<ImageBitmap | HTMLImageElement | null> {
    try {
        if (typeof createImageBitmap === 'function') {
            return await createImageBitmap(file);
        }
    } catch {
        /* HEIC وغيرها قد تفشل — نجرب <img> */
    }
    try {
        const url = URL.createObjectURL(file);
        const img = new Image();
        const loaded = await new Promise<HTMLImageElement | null>((resolve) => {
            img.onload = () => resolve(img);
            img.onerror = () => resolve(null);
            img.src = url;
        });
        URL.revokeObjectURL(url);
        return loaded;
    } catch {
        return null;
    }
}

function canvasToBlob(canvas: HTMLCanvasElement, type: string, quality: number): Promise<Blob | null> {
    return new Promise((resolve) => {
        try {
            canvas.toBlob((blob) => resolve(blob), type, quality);
        } catch {
            resolve(null);
        }
    });
}

/**
 * يضغط صورة المرفق قبل الرفع — تصغير للأبعاد القصوى وإعادة ترميز JPEG.
 * يعيد الملف الأصلي عند الفشل أو إذا كانت النتيجة أكبر (لا يفشل النشر أبداً).
 */
export async function compressForumImageFile(file: File): Promise<File> {
    if (!isCompressibleImage(file)) return file;

    let source: ImageBitmap | HTMLImageElement | null = null;
    try {
        source = await decodeImage(file);
        if (!source) return file;

        const width = source.width;
        const height = source.height;
        if (!width || !height) return file;

        const needsResize = Math.max(width, height) > MAX_DIMENSION_PX;
        const needsRecode = file.size > COMPRESS_THRESHOLD_BYTES;
        if (!needsResize && !needsRecode) return file;

        const scale = needsResize ? MAX_DIMENSION_PX / Math.max(width, height) : 1;
        const targetW = Math.max(1, Math.round(width * scale));
        const targetH = Math.max(1, Math.round(height * scale));

        const canvas = document.createElement('canvas');
        canvas.width = targetW;
        canvas.height = targetH;
        const ctx = canvas.getContext('2d');
        if (!ctx) return file;
        ctx.drawImage(source, 0, 0, targetW, targetH);

        const hasAlpha = file.type.toLowerCase() === 'image/png';
        const outType = hasAlpha ? 'image/webp' : 'image/jpeg';
        const blob =
            (await canvasToBlob(canvas, outType, JPEG_QUALITY)) ??
            (await canvasToBlob(canvas, 'image/jpeg', JPEG_QUALITY));
        if (!blob || blob.size === 0) return file;
        if (blob.size >= file.size) return file;

        const ext = blob.type === 'image/webp' ? 'webp' : 'jpg';
        const baseName = file.name.replace(/\.[^.]+$/, '') || 'image';
        return new File([blob], `${baseName}.${ext}`, { type: blob.type });
    } catch {
        return file;
    } finally {
        if (source && 'close' in source) {
            try {
                (source as ImageBitmap).close();
            } catch {
                /* ignore */
            }
        }
    }
}

export const FORUM_POST_MAX_LENGTH = 10_000;
export const FORUM_TAGS_MAX_LENGTH = 200;
export const FORUM_ACTOR_LABEL_MAX = 80;
export const FORUM_REPORT_REASON_MAX = 500;

const FORUM_C0_EXCEPT_WHITESPACE = /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g;

export function clampForumText(value: string, max: number): string {
    return value.slice(0, max);
}

export function sanitizeForumPostContent(content: string): string {
    /* إزالة null/C0 عدا الأسطر البيضاء الشائعة — نص المنشور يُعرض كنص React */
    const cleaned = content.replace(FORUM_C0_EXCEPT_WHITESPACE, '');
    return clampForumText(cleaned.trim(), FORUM_POST_MAX_LENGTH);
}

export function sanitizeForumTagsInput(tags: string): string {
    const cleaned = tags.replace(FORUM_C0_EXCEPT_WHITESPACE, '').replace(/[<>]/g, '');
    return clampForumText(cleaned.trim(), FORUM_TAGS_MAX_LENGTH);
}

/** اسم ظاهر في إشعار متابعة — بلا وسوم ولا محارف تحكم */
export function sanitizeForumActorLabel(name: string): string {
    return clampForumText(sanitizeForumTagsInput(name), FORUM_ACTOR_LABEL_MAX);
}

export function sanitizeForumReportReason(reason: string): string {
    return clampForumText(sanitizeForumPostContent(reason), FORUM_REPORT_REASON_MAX);
}

import type { CommunityComment, CommunityPost } from '@/app/services/forum/forumTypes';

/** القيمة المجهولة الموحّدة عند النشر المجهول (للحماية من تسريب الهوية) */
export const ANONYMOUS_USER_ID = '__anonymous__';
export const ANONYMOUS_USER_NAME = 'زميل مجهول';

/** اسم العرض الآمن في الإشعارات والرسائل العامة */
export function forumAuthorDisplayName(post: Pick<CommunityPost, 'isAnonymous' | 'authorName'>): string {
    return post.isAnonymous ? ANONYMOUS_USER_NAME : post.authorName;
}

/**
 * يُخفي هوية المؤلف عند `isAnonymous=true` لكل من ليس المؤلف ولا أدمن.
 *
 * يُخفي أيضاً هوية المعلّقين الذين هم أنفسهم صاحب المنشور المجهول
 * (وإلا انكشف أن «الناشر المجهول» = «المعلّق ذو الاسم الفلاني»).
 *
 * استثناءات (لا يُخفى عنهم):
 * - صاحب المنشور نفسه (يحتاج معرفة هويته لزر التعديل/الحذف)
 * - الأدمن (للإشراف)
 *
 * يُستخدم في كل مكان يخرج فيه CommunityPost من الـ repo قبل وصوله للمشاهد.
 */
export function redactAnonymousAuthor(
    post: CommunityPost,
    viewerId: string | null,
    viewerIsAdmin: boolean,
): CommunityPost {
    if (!post.isAnonymous) return post;
    const realAuthorId = post.authorId;
    const isOwner = viewerId !== null && viewerId === realAuthorId;
    if (isOwner || viewerIsAdmin) return post;

    const redactedComments = post.comments.map((c) => {
        // التعليق من صاحب المنشور نفسه → يجب إخفاؤه لمنع كشف الهوية بالاستنتاج
        if (c.authorId === realAuthorId) {
            return {
                ...c,
                authorId: ANONYMOUS_USER_ID,
                authorName: ANONYMOUS_USER_NAME,
                author_id: ANONYMOUS_USER_ID,
            };
        }
        return c;
    });

    return {
        ...post,
        authorId: ANONYMOUS_USER_ID,
        authorName: ANONYMOUS_USER_NAME,
        author_id: ANONYMOUS_USER_ID,
        comments: redactedComments,
    };
}

