};

/** خريطة upvotes للتعليقات: commentId → Set<userId> */
export type CommentUpvoteMap = Map<string, string[]>;

function parseAttachment(raw: unknown): CommunityPost['attachment'] {
    if (!raw || typeof raw !== 'object') return null;
    const a = raw as Record<string, unknown>;
    const type =
        a.type === 'image' ? 'image' : a.type === 'document' ? 'document' : a.type === 'audio' ? 'audio' : null;
    const url = typeof a.url === 'string' && a.url.trim() ? a.url.trim() : undefined;
    const name = typeof a.name === 'string' && a.name.trim() ? a.name.trim() : null;
    const storagePath =
        typeof a.storagePath === 'string' && a.storagePath.trim() ? a.storagePath.trim() : undefined;
    if (!type || !name || (!url && !storagePath)) return null;
    const bucket = typeof a.bucket === 'string' && a.bucket.trim() ? a.bucket.trim() : undefined;
    return {
        type,
        ...(url ? { url } : {}),
        name,
        mimeType: typeof a.mimeType === 'string' ? a.mimeType : undefined,
        storagePath,
        ...(bucket ? { bucket } : {}),
        ...(a.encrypted === true ? { encrypted: true } : {}),
    };
}

export function commentRowToCommunity(
    c: ForumCommentRow,
    upvoterIds: string[] = [],
): CommunityComment {
    return {
        id: c.id,
        postId: c.post_id,
        authorId: c.author_id,
        author_id: c.author_id,
        authorName: c.author_name,
        content: c.content,
        createdAt: c.created_at,
        parentId: c.parent_id ?? undefined,
        upvoterIds,
    };
}

export function postRowToCommunity(
    row: ForumPostRow,
    comments: ForumCommentRow[],
    commentUpvotes: CommentUpvoteMap = new Map(),
): CommunityPost {
    return {
        id: row.id,
        authorId: row.author_id,
        author_id: row.author_id,
        authorName: row.author_name,
        content: row.content,
        tags: Array.isArray(row.tags) ? row.tags : [],
        createdAt: row.created_at,
        updatedAt: row.updated_at,
        attachment: parseAttachment(row.attachment),
        upvoterIds: Array.isArray(row.upvoter_ids) ? row.upvoter_ids : [],
        comments: comments.map((c) => commentRowToCommunity(c, commentUpvotes.get(c.id) ?? [])),
        bestCommentId: row.best_comment_id,
        isUrgent: row.is_urgent || undefined,
        isAnonymous: row.is_anonymous || undefined,
        isEdited: row.is_edited || undefined,
        isPinned: row.is_pinned || undefined,
        isLocked: row.is_locked || undefined,
        groupId: row.group_id ?? undefined,
    };
}

export function communityPostToInsertRow(post: CommunityPost): Record<string, unknown> {
    return {
        id: post.id,
        author_id: post.authorId,
        author_name: post.authorName,
        content: post.content,
        tags: post.tags ?? [],
        attachment: post.attachment
            ? {
                  type: post.attachment.type,
                  name: post.attachment.name,
                  mimeType: post.attachment.mimeType,
                  storagePath: post.attachment.storagePath,
                  ...(post.attachment.bucket ? { bucket: post.attachment.bucket } : {}),
                  ...(post.attachment.encrypted === true ? { encrypted: true } : {}),
              }
            : null,
        upvoter_ids: post.upvoterIds ?? [],
        best_comment_id: post.bestCommentId ?? null,
        is_urgent: post.isUrgent === true,
        is_anonymous: post.isAnonymous === true,
        is_edited: post.isEdited === true,
        is_pinned: post.isPinned === true,
        is_locked: post.isLocked === true,
        group_id: post.groupId ?? null,
        created_at: post.createdAt,
        updated_at: post.updatedAt,
    };
}

import type { CommunityPost } from '@/app/services/forum/forumTypes';

const UUID_MENTION =
    /@([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})/gi;

function escapeRegExp(value: string): string {
    return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

export type ForumParticipant = { id: string; name: string };

/** مشاركون في النقاش — للربط بين @الاسم والمعرّف */
export function collectForumParticipants(post: CommunityPost): ForumParticipant[] {
    const byId = new Map<string, string>();
    if (post.authorId && post.authorName && post.authorId !== '__anonymous__') {
        byId.set(post.authorId, post.authorName);
    }
    for (const c of post.comments) {
        if (c.authorId && c.authorName && c.authorId !== '__anonymous__') {
            byId.set(c.authorId, c.authorName);
        }
    }
    return [...byId.entries()].map(([id, name]) => ({ id, name }));
}

/**
 * يستخرج معرّفات المذكورين:
 * - @uuid
 * - @اسم المحامي (يطابق مشاركي النقاش فقط)
 */
export function extractForumMentionIds(content: string, participants: ForumParticipant[]): string[] {
    const ids = new Set<string>();
    const trimmed = content.trim();
    if (!trimmed) return [];

    for (const match of trimmed.matchAll(UUID_MENTION)) {
        const id = match[1]?.toLowerCase();
        if (id) ids.add(id);
    }

    const sorted = [...participants].sort((a, b) => b.name.trim().length - a.name.trim().length);
    for (const p of sorted) {
        const name = p.name.trim();
        if (!name || name.length < 2) continue;
        const re = new RegExp(`@${escapeRegExp(name)}(?=\\s|$|[.,!?،؛])`, 'u');
        if (re.test(trimmed)) ids.add(p.id);
    }

    return [...ids];
}

function getConfiguredAdminUuid(): string {
    const env = typeof process !== 'undefined' ? process.env : undefined;
    const configured = (env?.ADMIN_UUID ?? '').trim();
    if (configured) return configured;
    if ((env?.NODE_ENV ?? '').toLowerCase() !== 'production') return 'admin-uuid-1';
    return '';
}

/** معرّفات المشرفين/الأدمن لإشعارات البلاغات (سيرفر) */
export async function listForumModeratorUserIds(): Promise<string[]> {
    const ids = new Set<string>();
    const adminUuid = getConfiguredAdminUuid();
    if (adminUuid) ids.add(adminUuid);

    if (typeof window !== 'undefined') return [...ids];

    try {
        const { loadForumSupabaseAdmin } = await import('./loadForumSupabaseAdmin');
        const admin = await loadForumSupabaseAdmin();
        if (admin) {
            const { data } = await admin.from('profiles').select('id').in('role', ['admin', 'moderator']);
            for (const row of data ?? []) {
                const id = String((row as { id: string }).id ?? '').trim();
                if (id) ids.add(id);
            }
        }
    } catch {
        /* server admin optional */
    }
    return [...ids];
}

import { loadForumSupabaseAdmin } from './loadForumSupabaseAdmin';
import { readSecureJsonRawSync, writeSecureJsonValue } from '@/app/services/storage/syncSecureJson';

const LOCAL_KEY_PREFIX = 'hami:forum:muted-users:v1';

function localKey(muterId: string): string {
    return `${LOCAL_KEY_PREFIX}:${muterId}`;
}

function loadLocalMutes(muterId: string): string[] {
    try {
        const raw = readSecureJsonRawSync(localKey(muterId));
        if (!raw) return [];
        const parsed = JSON.parse(raw) as unknown;
        return Array.isArray(parsed) ? parsed.filter((x): x is string => typeof x === 'string') : [];
    } catch {
        return [];
    }
}

function saveLocalMutes(muterId: string, ids: string[]): void {
    writeSecureJsonValue(localKey(muterId), [...new Set(ids)]);
}

/**
 * كتم المستخدمين على الخادم — يُخفي إشعارات المكتومين ويُزامن عبر الأجهزة.
 * fallback محلي (localStorage) عند غياب Supabase admin (تطوير/أوفلاين).
 */
export const ForumMuteRepository = {
    async listMuted(muterId: string): Promise<string[]> {
        if (!muterId) return [];
        const admin = await loadForumSupabaseAdmin();
        if (!admin) return loadLocalMutes(muterId);
        const { data, error } = await admin
            .from('forum_mutes')
            .select('muted_id')
            .eq('muter_id', muterId);
        if (error || !data) return [];
        return (data as { muted_id: string }[]).map((r) => r.muted_id);
    },

    async mute(muterId: string, mutedId: string): Promise<void> {
        if (!muterId || !mutedId || muterId === mutedId) return;
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const next = [...loadLocalMutes(muterId), mutedId];
            saveLocalMutes(muterId, next);
            return;
        }
        const { error } = await admin
            .from('forum_mutes')
            .upsert({ muter_id: muterId, muted_id: mutedId }, { onConflict: 'muter_id,muted_id' });
        if (error) throw new Error(error.message);
    },

    async unmute(muterId: string, mutedId: string): Promise<void> {
        if (!muterId || !mutedId) return;
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            saveLocalMutes(
                muterId,
                loadLocalMutes(muterId).filter((id) => id !== mutedId),
            );
            return;
        }
        const { error } = await admin
            .from('forum_mutes')
            .delete()
            .eq('muter_id', muterId)
            .eq('muted_id', mutedId);
        if (error) throw new Error(error.message);
    },

    async isMutedBy(muterId: string, mutedId: string): Promise<boolean> {
        if (!muterId || !mutedId || muterId === mutedId) return false;
        const admin = await loadForumSupabaseAdmin();
        if (!admin) return loadLocalMutes(muterId).includes(mutedId);
        const { data } = await admin
            .from('forum_mutes')
            .select('muted_id')
            .eq('muter_id', muterId)
            .eq('muted_id', mutedId)
            .maybeSingle();
        return Boolean(data);
    },
};

