            userId: comment.authorId,
            type: 'best_answer',
            title: 'تم اعتماد إجابتك',
            message: `اختار ${forumAuthorDisplayName(post)} تعليقك كأفضل إجابة`,
            postId: post.id,
        },
        `forum:best:${post.id}:${comment.id}`,
    );
}

