import type { ForumNotification } from '@/app/services/forum/forumTypes';
import { deriveNotificationCategory } from '@/app/infrastructure/notificationModel';
import { peekLocalNotifications } from '@/app/infrastructure/notificationPeekLite';
import { mapModelToForumNotification } from '@/app/services/notifications/forumNotificationMapper';
import { withForumAsyncTimeout } from '@/app/components/lawyer/CommunityScreen/forumAsync';

let warmedNotifications: ForumNotification[] | null = null;
let warmedUnread = 0;
let warmedUserId: string | null = null;
let warmPromise: Promise<{ notifications: ForumNotification[]; unreadCount: number }> | null = null;

function loadForumApiService() {
    return import('@/app/services/forumApiService');
}

export function peekForumNotificationsFromLocal(userId: string): ForumNotification[] {
    return peekLocalNotifications(userId)
        .filter((n) => deriveNotificationCategory(n) === 'forum')
        .map((n) => mapModelToForumNotification(n, userId))
        .filter((n): n is ForumNotification => n !== null)
        .slice(0, 25);
}

/** قراءة فورية من blob محلي — بدون انتظار API */
export function peekForumNotificationsCache(userId?: string | null): ForumNotification[] | null {
    if (userId && warmedUserId === userId && warmedNotifications) return warmedNotifications;
    if (!userId) return warmedNotifications;
    const local = peekForumNotificationsFromLocal(userId);
    return local.length > 0 ? local : warmedNotifications;
}

export function peekForumNotificationsUnreadCache(userId?: string | null): number | null {
    if (userId && warmedUserId === userId) return warmedUnread;
    if (!userId) return warmedUnread > 0 ? warmedUnread : null;
    const local = peekForumNotificationsFromLocal(userId);
    if (local.length === 0) return warmedUnread > 0 ? warmedUnread : null;
    return local.filter((n) => !n.read).length;
}

export function warmForumNotificationsCache(userId: string): void {
    if (!userId) return;
    if (warmPromise && warmedUserId === userId) return;

    const local = peekForumNotificationsFromLocal(userId);
    if (local.length > 0) {
        warmedNotifications = local;
        warmedUnread = local.filter((n) => !n.read).length;
        warmedUserId = userId;
    }

    warmedUserId = userId;
    warmPromise = loadForumApiService()
        .then(({ ForumApiService }) =>
            withForumAsyncTimeout(
                ForumApiService.listForumNotifications(userId).then(({ notifications, unreadCount }) => {
                    const slice = notifications.slice(0, 25);
                    warmedNotifications = slice;
                    warmedUnread = unreadCount;
                    return { notifications: slice, unreadCount };
                }),
                5_000,
                {
                    notifications: warmedNotifications ?? local,
                    unreadCount: warmedUnread || local.filter((n) => !n.read).length,
                },
            ),
        )
        .catch(() => ({
            notifications: warmedNotifications ?? local,
            unreadCount: warmedUnread || local.filter((n) => !n.read).length,
        }));
}

export async function readForumNotificationsCache(
    userId: string,
): Promise<{ notifications: ForumNotification[]; unreadCount: number }> {
    warmForumNotificationsCache(userId);
    if (warmPromise) {
        return warmPromise;
    }
    const local = peekForumNotificationsFromLocal(userId);
    return {
        notifications: local,
        unreadCount: local.filter((n) => !n.read).length,
    };
}

export async function readForumNotificationsCacheTimed(
    userId: string,
    ms: number,
    fallback: () => { notifications: ForumNotification[]; unreadCount: number },
): Promise<{ notifications: ForumNotification[]; unreadCount: number; timedOut: boolean }> {
    return withForumAsyncTimeout(
        readForumNotificationsCache(userId).then((snapshot) => ({ timedOut: false, ...snapshot })),
        ms,
        () => ({ timedOut: true, ...fallback() }),
    );
}

import { loadForumSupabaseAdmin } from './loadForumSupabaseAdmin';

export type ForumOfficialStats = {
    totalPosts: number;
    totalComments: number;
    totalUpvotes: number;
    totalReports: number;
    pendingReports: number;
    totalDocuments: number;
    totalBannedUsers: number;
    topTags: { tag: string; count: number }[];
};

type CountBuilder = {
    is: (column: string, value: null) => CountBuilder;
    eq: (column: string, value: string) => CountBuilder;
    not: (column: string, operator: string, value: null) => CountBuilder;
    gt: (column: string, value: string) => CountBuilder;
};

async function headCount(
    admin: { from: (table: string) => { select: (cols: string, opts: { count: 'exact'; head: boolean }) => CountBuilder } },
    table: string,
    filter?: (q: CountBuilder) => CountBuilder,
): Promise<number> {
    /** `*` — forum_bans بلا عمود id؛ العدّ HEAD لا يحتاج عموداً محدداً. */
    const base = admin.from(table).select('*', { count: 'exact', head: true });
    const query = filter ? filter(base) : base;
    const { count, error } = await (query as unknown as PromiseLike<{
        count: number | null;
        error: unknown;
    }>);
    if (error) throw new Error('forum stats count failed');
    return typeof count === 'number' ? count : 0;
}

/**
 * إحصاءات المنتدى من Postgres الحي — ليست مرآة CommunityDB على عملية BFF.
 * totalDocuments = منشورات عامة لها مرفق (`attachment`) — ليست خزنة المحامي المشفّرة.
 * totalBannedUsers = حظر ساري (دائم أو لم ينتهِ) — ليس أرشيف الصفوف المنتهية.
 */
export async function loadForumOfficialStats(): Promise<ForumOfficialStats | null> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) {
        return null;
    }

    const nowIso = new Date().toISOString();
    const [
        totalPosts,
        totalComments,
        totalReports,
        pendingReports,
        bannedPermanent,
        bannedTimedActive,
        totalDocuments,
        postRows,
        commentUpvotes,
    ] = await Promise.all([
        headCount(admin, 'forum_posts', (q) => q.is('group_id', null)),
        headCount(admin, 'forum_comments'),
        headCount(admin, 'forum_reports'),
        headCount(admin, 'forum_reports', (q) => q.eq('status', 'pending')),
        headCount(admin, 'forum_bans', (q) => q.is('expires_at', null)),
        headCount(admin, 'forum_bans', (q) => q.gt('expires_at', nowIso)),
        headCount(admin, 'forum_posts', (q) => q.is('group_id', null).not('attachment', 'is', null)),
        admin.from('forum_posts').select('tags, upvoter_ids').is('group_id', null).limit(2000),
        admin.from('forum_comment_upvotes').select('comment_id', { count: 'exact', head: true }),
    ]);

    const tagCount = new Map<string, number>();
    let postUpvotes = 0;
    if (!postRows.error && Array.isArray(postRows.data)) {
        for (const row of postRows.data as Array<{ tags?: unknown; upvoter_ids?: unknown }>) {
            const tags = Array.isArray(row.tags) ? row.tags : [];
            for (const tag of tags) {
                const label = String(tag ?? '')
                    .replace(/[\u0000-\u001F\u007F]/g, '')
                    .trim()
                    .slice(0, 40);
                if (!label) continue;
                tagCount.set(label, (tagCount.get(label) ?? 0) + 1);
            }
            if (Array.isArray(row.upvoter_ids)) postUpvotes += row.upvoter_ids.length;
        }
    }
    const commentVoteCount =
        commentUpvotes.error || typeof commentUpvotes.count !== 'number' ? 0 : commentUpvotes.count;
    const topTags = Array.from(tagCount.entries())
        .map(([tag, count]) => ({ tag, count }))
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

    return {
        totalPosts,
        totalComments,
        totalUpvotes: postUpvotes + commentVoteCount,
        totalReports,
        pendingReports,
        totalDocuments,
        totalBannedUsers: bannedPermanent + bannedTimedActive,
        topTags,
    };
}

/**
 * ميزانيات أداء المنتدى — مرجع E2E + Sentry.
 */
export const FORUM_PERF_BUDGET = {
    openToInteractiveMs: {
        target: 3_200,
        ciColdMax: 7_000,
        ciCachedMax: 3_800,
    },
    sentryMetric: 'forum.open_to_interactive_ms',
} as const;

export type ForumPerfBudgetKey = keyof typeof FORUM_PERF_BUDGET.openToInteractiveMs;

import { debug } from '@/app/utils/debug';
import {
    reportForumOpenToSentry,
    type ForumPerfReportContext,
} from '@/app/services/forum/forumSentryReporting';

const MARK_PREFIX = 'hami:forum:';

type ForumPerfPhase = 'open-request' | 'first-paint' | 'interactive' | 'chunk-ready';

export type { ForumPerfReportContext };

export function markForumPerfPhase(phase: ForumPerfPhase): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark(`${MARK_PREFIX}${phase}`);
    } catch {
        /* ignore */
    }
}

export function clearForumPerfMarks(): void {
    if (typeof performance === 'undefined' || typeof performance.clearMarks !== 'function') return;
    try {
        for (const phase of ['open-request', 'first-paint', 'interactive', 'chunk-ready'] as const) {
            performance.clearMarks(`${MARK_PREFIX}${phase}`);
        }
    } catch {
        /* ignore */
    }
}

/** ms من open-request → interactive (null إذا لم تُسجَّل المرحلتان) */
export function getForumOpenToInteractiveMs(): number | null {
    if (typeof performance === 'undefined') return null;
    const open = performance.getEntriesByName(`${MARK_PREFIX}open-request`, 'mark')[0];
    const interactive = performance.getEntriesByName(`${MARK_PREFIX}interactive`, 'mark')[0];
    if (!open || !interactive) return null;
    return Math.round(interactive.startTime - open.startTime);
}

/** DEV: log — PROD (مع DSN): Sentry breadcrumb + metric */
export function reportForumPerf(context: ForumPerfReportContext = {}): void {
    const ms = getForumOpenToInteractiveMs();
    if (ms == null) return;
    if (import.meta.env.DEV) {
        debug.log('[ForumPerf] open→interactive', ms, 'ms', context);
    }
    reportForumOpenToSentry(ms, context);
}

import type { CommunityAttachment, CommunityComment, CommunityPost } from '@/app/services/forum/forumTypes';
import { createForumEntityId } from '@/app/services/forum/forumEntityIdCore';
import { isSafeForumAttachmentUrl } from '@/app/services/forum/forumUrlSafety';
import { sanitizeForumPostContent, sanitizeForumTagsInput } from '@/app/services/forum/forumInputSecurity';

/** معرّف خادم فقط — لا يُقبل معرّف من العميل في مسارات الإنشاء. */
export const mintForumEntityId = createForumEntityId;

export function isCloudForumStoragePath(path: string | undefined | null): boolean {
    const trimmed = path?.trim() ?? '';
    if (!trimmed) return false;
    if (trimmed.startsWith('idb:') || trimmed.startsWith('blob:') || trimmed.startsWith('local:')) {
        return false;
    }
    return true;
}

export function assertPublishableForumAttachment(attachment: CommunityAttachment | null): void {
    if (!attachment) return;
    if (!isCloudForumStoragePath(attachment.storagePath)) {
        throw new Error('يجب رفع المرفق إلى الخادم قبل النشر');
    }
}

function sanitizeAttachment(raw: CommunityPost['attachment']): CommunityAttachment | null {
    if (!raw || typeof raw !== 'object') return null;
    const type =
        raw.type === 'image' ? 'image' : raw.type === 'document' ? 'document' : raw.type === 'audio' ? 'audio' : null;
    const url = typeof raw.url === 'string' ? raw.url.trim() : '';
    const name = typeof raw.name === 'string' ? raw.name.trim() : '';
    const storagePath = typeof raw.storagePath === 'string' ? raw.storagePath.trim() : '';
    const hasDurableStorage = storagePath.length > 0;
    const persistableUrl =
        url && !url.startsWith('blob:') && isSafeForumAttachmentUrl(url) ? url : '';
    if (!type || !name || (!persistableUrl && !hasDurableStorage) || (url && !isSafeForumAttachmentUrl(url))) {
        return null;
    }
    const bucket = typeof raw.bucket === 'string' ? raw.bucket.trim() : '';
    return {
        type,
        ...(persistableUrl ? { url: persistableUrl } : {}),
        name,
        mimeType: typeof raw.mimeType === 'string' ? raw.mimeType : undefined,
        storagePath: storagePath || undefined,
        ...(bucket ? { bucket } : {}),
        ...(raw.encrypted === true ? { encrypted: true } : {}),
    };
}

/**
 * يبني منشوراً آمناً للإنشاء — يزيل حقول الصلاحيات/التصويت/التعليقات المحقونة من العميل،
 * ويولّد معرّفاً جديداً دائماً (يمنع overwrite عبر upsert بمعرّف مهاجم).
 */
export function sanitizeCommunityPostForCreate(post: CommunityPost, authorId: string): CommunityPost {
    const now = new Date().toISOString();
    const tags = Array.isArray(post.tags)
        ? post.tags
              .filter((tag): tag is string => typeof tag === 'string' && tag.trim().length > 0)
              .map((tag) => sanitizeForumTagsInput(tag))
              .filter((tag) => tag.length > 0)
              .slice(0, 12)
        : [];

    return {
        id: mintForumEntityId(),
        authorId,
        author_id: authorId,
        authorName: typeof post.authorName === 'string' ? post.authorName.trim() : '',
        content: typeof post.content === 'string' ? sanitizeForumPostContent(post.content) : '',
        tags,
        createdAt: now,
        updatedAt: now,
        attachment: sanitizeAttachment(post.attachment),
        upvoterIds: [],
        comments: [],
        bestCommentId: null,
        isUrgent: post.isUrgent === true ? true : undefined,
        isAnonymous: post.isAnonymous === true ? true : undefined,
        isEdited: undefined,
        isPinned: undefined,
        isLocked: undefined,
        groupId: typeof post.groupId === 'string' && post.groupId.trim() ? post.groupId.trim() : undefined,
    };
}

/**
 * يبني تعليقاً آمناً — معرّف خادم + طوابع زمنية خادم، يتجاهل id/createdAt من العميل.
 */
export function sanitizeCommunityCommentForCreate(input: {
    postId: string;
    authorId: string;
    authorName: string;
    content: string;
    parentId?: string;
}): CommunityComment {
    const content = sanitizeForumPostContent(input.content);
    return {
        id: mintForumEntityId(),
        postId: input.postId,
        authorId: input.authorId,
        authorName: input.authorName.trim(),
        content,
        createdAt: new Date().toISOString(),
        parentId: input.parentId?.trim() || undefined,
    };
}

import { loadForumSupabaseAdmin } from './loadForumSupabaseAdmin';
import { persistSecureJsonValue, readSecureJsonRaw } from '@/app/services/storage/syncSecureJson';

const LOCAL_KEY = 'hami:forum:post-sub:v1';

export type PostSubscription = {
    userId: string;
    postId: string;
    createdAt: string;
};

async function loadLocal(): Promise<PostSubscription[]> {
    try {
        const raw = await readSecureJsonRaw(LOCAL_KEY);
        if (!raw) return [];
        const parsed = JSON.parse(raw) as PostSubscription[];
        return Array.isArray(parsed) ? parsed : [];
    } catch {
        return [];
    }
}

async function saveLocal(rows: PostSubscription[]): Promise<void> {
    await persistSecureJsonValue(LOCAL_KEY, rows);
}

export const ForumPostFollowRepository = {
    async subscribe(userId: string, postId: string): Promise<PostSubscription> {
        const createdAt = new Date().toISOString();
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const rows = await loadLocal();
            const next = rows.filter((r) => !(r.userId === userId && r.postId === postId));
            next.unshift({ userId, postId, createdAt });
            await saveLocal(next);
            return { userId, postId, createdAt };
        }
        const { error } = await admin.from('forum_post_subscriptions').upsert(
            { user_id: userId, post_id: postId, created_at: createdAt },
            { onConflict: 'user_id,post_id' },
        );
        if (error) throw new Error(error.message);
        return { userId, postId, createdAt };
    },

    async unsubscribe(userId: string, postId: string): Promise<void> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const rows = await loadLocal();
            await saveLocal(rows.filter((r) => !(r.userId === userId && r.postId === postId)));
            return;
        }
        const { error } = await admin
            .from('forum_post_subscriptions')
            .delete()
            .eq('user_id', userId)
            .eq('post_id', postId);
        if (error) throw new Error(error.message);
    },

    async isSubscribed(userId: string, postId: string): Promise<boolean> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const rows = await loadLocal();
            return rows.some((r) => r.userId === userId && r.postId === postId);
        }
        const { data } = await admin
            .from('forum_post_subscriptions')
            .select('user_id')
            .eq('user_id', userId)
            .eq('post_id', postId)
            .maybeSingle();
        return Boolean(data);
    },

    async listPostIdsForUser(userId: string): Promise<string[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return (await loadLocal()).filter((r) => r.userId === userId).map((r) => r.postId);
        }
        const { data } = await admin
            .from('forum_post_subscriptions')
            .select('post_id')
            .eq('user_id', userId)
            .order('created_at', { ascending: false });
        if (!data) return [];
        return (data as Array<{ post_id: string }>).map((r) => r.post_id);
    },

    async getSubscribers(postId: string): Promise<PostSubscription[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return (await loadLocal()).filter((r) => r.postId === postId);
        }
        const { data } = await admin
            .from('forum_post_subscriptions')
            .select('*')
            .eq('post_id', postId);
        if (!data) return [];
        return (data as Array<Record<string, unknown>>).map((row) => ({
            userId: String(row.user_id),
            postId: String(row.post_id),
            createdAt: String(row.created_at ?? new Date().toISOString()),
        }));
    },
};

import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import type { CommunityPost } from '@/app/services/forum/forumTypes';
import { readCommunityAttachmentFile, resolveCommunityAttachmentUrl } from '@/app/services/forumAttachmentService';
import { saveFileToVault } from '@/app/services/vaultUploadService';

async function urlToFile(url: string, fileName: string, mimeType: string): Promise<File | null> {
    try {
        const res = await fetch(url);
        if (!res.ok) return null;
        const blob = await res.blob();
        return new File([blob], fileName, { type: mimeType || blob.type || 'application/octet-stream' });
    } catch {
        return null;
    }
}

/** حفظ مرفق المنشور (صورة/ملف) في مخزن المستخدم */
export async function saveForumAttachmentToVault(
    post: CommunityPost,
    userId: string,
    authorName: string,
): Promise<SmartVaultDoc> {
    if (!post.attachment) {
        throw new Error('no-attachment');
    }

    const fileName = post.attachment.name?.trim() || `forum-${post.id}`;
    const mimeType =
        post.attachment.mimeType?.trim() ||
        (post.attachment.type === 'image'
            ? 'image/jpeg'
            : post.attachment.type === 'audio'
              ? 'audio/mpeg'
              : 'application/pdf');

    const resolvedUrl = await resolveCommunityAttachmentUrl(post.attachment);
    const file =
        (await readCommunityAttachmentFile(post.attachment)) ??
        (resolvedUrl ? await urlToFile(resolvedUrl, fileName, mimeType) : null);
    if (!file) {
        throw new Error('fetch-failed');
    }

    const titleBase = post.content.trim().slice(0, 60) || fileName;
    const saved = await saveFileToVault(userId, file, {
        title: `من المنتدى — ${titleBase}`,
        tags: ['منتدى', ...post.tags.map((t) => t.replace(/^#/, ''))].slice(0, 8),
        customCategory: 'المنتدى',
        lawyerNote: `محفوظ من منشور المنتدى بواسطة ${authorName}\n\n${post.content.trim().slice(0, 400)}`,
        fileName,
    });
    return saved.doc;
}

/**
 * يتحقق أن تغييرات upvoterIds في sync مقتصرة على toggle معرّف المصوّت الحالي فقط.
 */
export function computeAllowedUpvoterIds(
    existingIds: string[],
    clientIds: string[] | undefined,
    voterId: string,
): { ok: true; upvoterIds: string[]; changed: boolean } | { ok: false; error: string } {
    const existing = [...new Set(existingIds)];
    const client = clientIds ?? existing;
    const existingSet = new Set(existing);
    const clientSet = new Set(client);

    const added = [...clientSet].filter((id) => !existingSet.has(id));
    const removed = [...existingSet].filter((id) => !clientSet.has(id));
    const changed = added.length > 0 || removed.length > 0;

    if (!changed) {
        return { ok: true, upvoterIds: existing, changed: false };
    }

    const mutations = [...added, ...removed];
    if (mutations.length !== 1 || mutations[0] !== voterId) {
        return { ok: false, error: 'غير مصرح بتعديل التصويتات' };
    }

    const next = new Set(existingSet);
    if (next.has(voterId)) next.delete(voterId);
    else next.add(voterId);

    return { ok: true, upvoterIds: [...next], changed: true };
}

export function resolveSyncBestCommentId(
    existingBest: string | null | undefined,
    clientBest: string | null | undefined,
    isOwner: boolean,
    isAdmin: boolean,
): { ok: true; bestCommentId: string | null; changed: boolean } | { ok: false; error: string } {
    const next = clientBest ?? null;
    const prev = existingBest ?? null;
    if (next === prev) {
        return { ok: true, bestCommentId: prev, changed: false };
    }
    if (!isOwner && !isAdmin) {
        return { ok: false, error: 'فقط صاحب المنشور يحدد أفضل إجابة' };
    }
    return { ok: true, bestCommentId: next, changed: true };
}

