import { getLiveAuthUserId } from '@/app/utils/liveAuthUserId';
import { readPersistedSupabaseAuth } from '@/app/utils/authStorage';

let warmedPosts: CommunityPost[] | null = null;
let warmPromise: Promise<CommunityPost[]> | null = null;

function liveSessionCanUseForumNetwork(): boolean {
    const persisted = readPersistedSupabaseAuth();
    const uid = getLiveAuthUserId() ?? persisted.user?.id ?? null;
    const meta = (persisted.user?.user_metadata ?? null) as Record<string, unknown> | null;
    return canUseNetworkFeatures(uid, meta);
}

/** تجهيز cache محلي للمنشورات — يُستدعى عند hover/فتح المنتدى */
export function warmForumPostsCache(): void {
    if (warmPromise) return;
    if (!liveSessionCanUseForumNetwork()) return;
    prefetchCommunityCloudModule();
    warmPromise = withForumAsyncTimeout(
        fetchCommunityPosts().then((rows) => {
            const local = sortCommunityPosts(rows).filter((p) => !p.groupId);
            warmedPosts = local;
            return local;
        }),
        4_000,
        [],
    ).catch(() => {
        warmedPosts = [];
        return [];
    });
}

export function peekForumPostsCache(): CommunityPost[] | null {
    return warmedPosts;
}

/** لقطة محلية مشفّرة — بلا شبكة. تملأ الكاش قبل الجلب إن كان فارغاً. */
export function warmForumPostsCacheFromLocal(): void {
    if (warmedPosts && warmedPosts.length > 0) return;
    void import('@/app/services/forum/forumCommunityRuntime')
        .then((m) => m.CommunityDB.listPosts())
        .then((rows) => {
            if (warmedPosts && warmedPosts.length > 0) return;
            const local = sortCommunityPosts(rows).filter((p) => !p.groupId);
            if (local.length > 0) warmedPosts = local;
        })
        .catch(() => undefined);
}

export async function readForumPostsCache(): Promise<CommunityPost[]> {
    if (warmedPosts) return warmedPosts;
    warmForumPostsCache();
    return warmPromise ?? Promise.resolve([]);
}

export function resetForumPostsCacheForTests(): void {
    warmedPosts = null;
    warmPromise = null;
}

import { consumeRateLimitSlot } from '@/app/api/security/wifeRateLimitStore';

export type ForumRateAction =
    | 'post'
    | 'comment'
    | 'report'
    | 'upvote'
    | 'delete'
    | 'update'
    | 'lock'
    | 'follow'
    | 'group_join'
    | 'bookmark'
    | 'mute'
    | 'comment_mutate'
    | 'group_create'
    | 'pin'
    | 'search'
    | 'repository'
    | 'repository_mutate'
    | 'repository_read';

type RateLimitRule = {
    scope: string;
    maxRequests: number;
    windowMs: number;
};

function buildRateLimitKey(userId: string, action: ForumRateAction, postId?: string): string {
    if (action === 'report') return `${userId}:${postId ?? 'any'}`;
    return userId;
}

function rulesForAction(action: ForumRateAction): RateLimitRule[] {
    switch (action) {
        case 'post':
            return [{ scope: 'forum:post:burst', maxRequests: 1, windowMs: 30_000 }];
        case 'comment':
            return [
                { scope: 'forum:comment:burst', maxRequests: 1, windowMs: 8_000 },
                { scope: 'forum:comment:min', maxRequests: 30, windowMs: 60_000 },
            ];
        case 'report':
            return [{ scope: 'forum:report', maxRequests: 1, windowMs: 24 * 60 * 60_000 }];
        case 'upvote':
            return [{ scope: 'forum:upvote:min', maxRequests: 60, windowMs: 60_000 }];
        case 'delete':
            return [{ scope: 'forum:delete:min', maxRequests: 20, windowMs: 60_000 }];
        case 'update':
            return [{ scope: 'forum:update:min', maxRequests: 30, windowMs: 60_000 }];
        case 'lock':
            return [{ scope: 'forum:lock:min', maxRequests: 30, windowMs: 60_000 }];
        case 'follow':
            return [
                { scope: 'forum:follow:burst', maxRequests: 5, windowMs: 10_000 },
                { scope: 'forum:follow:min', maxRequests: 40, windowMs: 60_000 },
            ];
        case 'group_join':
            return [{ scope: 'forum:group_join:min', maxRequests: 20, windowMs: 60_000 }];
        case 'bookmark':
            return [{ scope: 'forum:bookmark:min', maxRequests: 60, windowMs: 60_000 }];
        case 'mute':
            return [{ scope: 'forum:mute:min', maxRequests: 30, windowMs: 60_000 }];
        case 'comment_mutate':
            return [{ scope: 'forum:comment_mutate:min', maxRequests: 40, windowMs: 60_000 }];
        case 'group_create':
            return [
                { scope: 'forum:group_create:burst', maxRequests: 1, windowMs: 20_000 },
                { scope: 'forum:group_create:hour', maxRequests: 8, windowMs: 60 * 60_000 },
            ];
        case 'pin':
            return [{ scope: 'forum:pin:min', maxRequests: 30, windowMs: 60_000 }];
        case 'search':
            return [{ scope: 'forum:search:min', maxRequests: 40, windowMs: 60_000 }];
        case 'repository':
            return [
                { scope: 'forum:repository:burst', maxRequests: 1, windowMs: 20_000 },
                { scope: 'forum:repository:hour', maxRequests: 20, windowMs: 60 * 60_000 },
            ];
        case 'repository_mutate':
            return [{ scope: 'forum:repository_mutate:min', maxRequests: 40, windowMs: 60_000 }];
        case 'repository_read':
            return [{ scope: 'forum:repository_read:min', maxRequests: 120, windowMs: 60_000 }];
        default:
            return [];
    }
}

/** حد معدّل على السيرفر — Redis عند التوفر، ذاكرة محلية في التطوير. */
export async function checkForumActionRateLimit(
    userId: string,
    action: ForumRateAction,
    opts?: { postId?: string },
): Promise<boolean> {
    if (!userId) return false;

    const subjectKey = buildRateLimitKey(userId, action, opts?.postId);
    for (const rule of rulesForAction(action)) {
        const allowed = await consumeRateLimitSlot(subjectKey, {
            scope: rule.scope,
            maxRequests: rule.maxRequests,
            windowMs: rule.windowMs,
        });
        if (!allowed) return false;
    }
    return true;
}

/**
 * إشعارات بلاغات المنتدى للمشرفين — خادم فقط (لا يُستورد من مسارات العميل).
 */
import type { ForumNotification } from '@/app/services/forum/forumTypes';
import { resolveForumNotificationDb } from '@/app/services/notifications/forumNotificationDbResolver';

function createId(): string {
    const cryptoObj = globalThis.crypto as Crypto | undefined;
    if (cryptoObj?.randomUUID) return cryptoObj.randomUUID();
    return `${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function snippet(text: string, max = 80): string {
    const trimmed = String(text ?? '').trim();
    if (trimmed.length <= max) return trimmed;
    return `${trimmed.slice(0, max)}…`;
}

async function pushReportNotify(
    partial: Omit<ForumNotification, 'id' | 'read' | 'createdAt'>,
    dedupeKey: string,
): Promise<void> {
    if (!partial.userId?.trim()) return;
    const db = await resolveForumNotificationDb();
    const recent = await db.getNotifications(partial.userId);
    if (recent.some((n) => n.dedupeKey === dedupeKey)) return;
    await db.addNotification({
        ...partial,
        id: createId(),
        read: false,
        createdAt: new Date().toISOString(),
        dedupeKey,
    });
}

export async function dispatchForumReportSubmitted(params: {
    postId: string;
    reporterId: string;
    reason: string;
    targetLabel?: string;
}): Promise<void> {
    if (typeof window !== 'undefined') return;
    const { postId, reporterId, reason, targetLabel = 'منشور' } = params;
    const { listForumModeratorUserIds } = await import('./forumModeratorIds');
    const moderators = await listForumModeratorUserIds();
    await Promise.allSettled(
        moderators.map(async (modId) => {
            if (modId === reporterId) return;
            await pushReportNotify(
                {
                    userId: modId,
                    type: 'report_update',
                    title: `بلاغ جديد على ${targetLabel}`,
                    message: snippet(reason, 80),
                    postId,
                },
                `forum:report-new:${postId}:${reporterId}:${modId}`,
            );
        }),
    );
}

