export async function searchForumRepositoryDocsOnServer(
    filters: ForumRepositorySearchFilters,
    viewerId: string,
    isAdmin: boolean,
): Promise<RepositoryDocument[]> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) return [];

    const buildQuery = (useSearchText: boolean, useMediaKind: boolean) => {
        const wantsMedia = filters.hasPdf || filters.hasImage;
        const fetchLimit =
            wantsMedia && !useMediaKind
                ? Math.min(200, Math.max(1, filters.limit) * 4)
                : Math.min(80, Math.max(1, filters.limit));
        let query = admin
            .from('forum_repository_docs')
            .select('*')
            .order('created_at', { ascending: false })
            .limit(fetchLimit);

        if (filters.tag?.trim()) {
            query = query.contains('tags', [filters.tag.trim()]);
        }
        if (useMediaKind && filters.hasPdf) {
            query = query.eq(REPOSITORY_MEDIA_KIND_COLUMN, 'pdf');
        } else if (useMediaKind && filters.hasImage) {
            query = query.eq(REPOSITORY_MEDIA_KIND_COLUMN, 'image');
        }
        if (useSearchText) {
            const pattern = forumIlikeContainsPattern(filters.q);
            if (pattern) query = query.ilike(FORUM_SEARCH_TEXT_COLUMN, pattern);
        } else {
            const legacy = forumIlikeRawContainsPattern(filters.q);
            if (legacy) query = query.or(forumOrIlikeTitleAndDescription(legacy));
        }
        return query;
    };

    let useSearchText = true;
    let useMediaKind = true;
    let { data, error } = await buildQuery(useSearchText, useMediaKind);
    if (error && isMissingMediaKindColumn(error.message)) {
        useMediaKind = false;
        ({ data, error } = await buildQuery(useSearchText, useMediaKind));
    }
    if (error && isMissingSearchTextColumn(error.message)) {
        useSearchText = false;
        ({ data, error } = await buildQuery(useSearchText, useMediaKind));
    }
    if (error && isMissingMediaKindColumn(error.message)) {
        useMediaKind = false;
        ({ data, error } = await buildQuery(useSearchText, useMediaKind));
    }
    if (error || !data) return [];

    return (data as ForumRepositoryDocRow[])
        .map(rowToDocument)
        .filter((d) => matchesDocFilters(d, filters))
        .slice(0, filters.limit)
        .map((doc) => redactForumRepositoryDocument(doc, viewerId, isAdmin));
}

export async function createForumRepositoryDocOnServer(doc: RepositoryDocument): Promise<RepositoryDocument> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) throw new Error('تعذّر حفظ المستند في الفهرس');
    const { error } = await admin.from('forum_repository_docs').insert({
        id: doc.id,
        author_id: doc.authorId,
        author_name: doc.authorName,
        title: doc.title,
        description: doc.description,
        doc_type: doc.type,
        tags: doc.tags ?? [],
        file_name: doc.fileName,
        mime_type: doc.mimeType,
        storage_path: doc.storagePath,
        file_size: doc.fileSize,
    });
    if (error) {
        if (error.code === '23505') {
            const { data } = await admin
                .from('forum_repository_docs')
                .select('*')
                .eq('id', doc.id)
                .eq('author_id', doc.authorId)
                .maybeSingle();
            if (data) return rowToDocument(data as ForumRepositoryDocRow);
        }
        if (isMissingTableError(error.message)) throw new Error('فهرس المستودع غير جاهز بعد');
        throw new Error('تعذّر حفظ المستند في الفهرس');
    }
    return doc;
}

export async function updateForumRepositoryDocOnServer(
    docId: string,
    patch: ForumRepositoryDocPatch,
    requesterId: string,
    isAdmin: boolean,
): Promise<RepositoryDocument | null> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) throw new Error('تعذّر تحديث المستند في الفهرس');
    let query = admin.from('forum_repository_docs').update(patch).eq('id', docId);
    if (!isAdmin) query = query.eq('author_id', requesterId);
    const { data, error } = await query.select('*');
    if (error) {
        if (isMissingTableError(error.message)) throw new Error('فهرس المستودع غير جاهز بعد');
        throw new Error('تعذّر تحديث المستند في الفهرس');
    }
    const rows = (data ?? []) as ForumRepositoryDocRow[];
    if (rows.length === 0) throw new Error('المستند غير موجود أو لا يخصّك');
    return rowToDocument(rows[0]!);
}

export async function signForumRepositoryDocPath(storagePath: string): Promise<string | null> {
    const path = storagePath.trim();
    if (!path) return null;
    const admin = await loadForumSupabaseAdmin();
    if (!admin) return null;

    const refId = parseForumRepositoryRef(path);
    const lookup = admin.from('forum_repository_docs').select('storage_path').limit(1);
    const { data: rows, error } = refId
        ? await lookup.eq('id', refId)
        : isCloudForumStoragePath(path)
          ? await lookup.eq('storage_path', path)
          : { data: null, error: null };
    const storage = (rows as { storage_path?: string }[] | null)?.[0]?.storage_path?.trim();
    if (error || !storage || !isCloudForumStoragePath(storage)) return null;

    const { data } = await admin.storage
        .from(resolveUploadBucket())
        .createSignedUrl(storage, SIGNED_URL_TTL_SEC);
    return data?.signedUrl?.trim() || null;
}

export { deleteForumRepositoryDocOnServer } from '@/app/services/forum/forumRepositoryDocsDelete';

import { loadForumSupabaseAdmin } from '@/app/services/forum/loadForumSupabaseAdmin';
import { isMissingTableError } from '@/app/services/forum/forumRepositoryDocsMap';
import { removeForumRepositoryStorageOrEnqueue } from '@/app/services/forum/forumRepositoryOrphanSweep';

export async function deleteForumRepositoryDocOnServer(
    docId: string,
    requesterId: string,
    isAdmin: boolean,
): Promise<void> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) throw new Error('تعذّر حذف المستند من الفهرس');

    const { data: existing, error: fetchError } = await admin
        .from('forum_repository_docs')
        .select('id, author_id, storage_path')
        .eq('id', docId)
        .maybeSingle();
    if (fetchError && !isMissingTableError(fetchError.message)) {
        throw new Error('تعذّر حذف المستند من الفهرس');
    }
    if (!existing) throw new Error('المستند غير موجود أو لا يخصّك');
    const row = existing as { id: string; author_id: string; storage_path: string };
    if (!isAdmin && row.author_id !== requesterId) {
        throw new Error('المستند غير موجود أو لا يخصّك');
    }

    const { error } = await admin.from('forum_repository_docs').delete().eq('id', docId);
    if (error && !isMissingTableError(error.message)) {
        throw new Error('تعذّر حذف المستند من الفهرس');
    }

    const storagePath = row.storage_path?.trim();
    if (!storagePath) return;
    try {
        const { count } = await admin
            .from('forum_repository_docs')
            .select('id', { count: 'exact', head: true })
            .eq('storage_path', storagePath);
        if ((count ?? 0) > 0) return;
    } catch {
        /* إن تعذّر العدّ نحاول الإزالة — المرجع سقط أصلاً */
    }
    await removeForumRepositoryStorageOrEnqueue(admin, row.author_id, storagePath);
}

import type { RepositoryDocument } from '@/app/services/lawyer-cloud';
import { getRepositoryMediaKind } from '@/app/services/forum/repositoryMediaKind';
import { archiveTextMatchesQuery } from '@/app/services/search/normalizeArabicSearch';

export type ForumRepositorySearchFilters = {
    q: string;
    hasPdf: boolean;
    hasImage: boolean;
    tag: string | null;
    limit: number;
};

/** مرجع عام — يخفي مسار التخزين الذي يبدأ بمعرّف الناشر. */
export const FORUM_REPOSITORY_REF_PREFIX = 'forum-repo:';

export type ForumRepositoryDocRow = {
    id: string;
    author_id: string;
    author_name: string;
    title: string;
    description: string;
    doc_type: RepositoryDocument['type'];
    tags: string[] | null;
    file_name: string;
    mime_type: string;
    storage_path: string;
    file_size: number;
    created_at: string;
    updated_at?: string | null;
};

export function parseForumRepositoryRef(path: string): string | null {
    const trimmed = path.trim();
    if (!trimmed.startsWith(FORUM_REPOSITORY_REF_PREFIX)) return null;
    const id = trimmed.slice(FORUM_REPOSITORY_REF_PREFIX.length).trim();
    return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)
        ? id
        : null;
}

export function rowToDocument(row: ForumRepositoryDocRow): RepositoryDocument {
    const createdAt = row.created_at ?? '';
    return {
        id: row.id,
        title: row.title,
        description: row.description,
        type: row.doc_type,
        authorId: row.author_id,
        authorName: row.author_name,
        uploadDate: createdAt.slice(0, 10),
        updatedAt: (row.updated_at ?? createdAt) || undefined,
        fileName: row.file_name,
        mimeType: row.mime_type ?? '',
        storagePath: row.storage_path,
        fileSize: row.file_size ?? 0,
        tags: Array.isArray(row.tags) ? row.tags : [],
    };
}

/**
 * يخفي UUID الناشر ومسار التخزين عن غير المالك/المشرف.
 * الاسم المعروض يبقى — المكتبة مشتركة بالاسم لا بالمعرّف.
 */
export function redactForumRepositoryDocument(
    doc: RepositoryDocument,
    viewerId: string,
    isAdmin: boolean,
): RepositoryDocument {
    if (isAdmin || doc.authorId === viewerId) return doc;
    return {
        ...doc,
        authorId: '',
        storagePath: `${FORUM_REPOSITORY_REF_PREFIX}${doc.id}`,
    };
}

export function matchesDocFilters(doc: RepositoryDocument, filters: ForumRepositorySearchFilters): boolean {
    const kind = getRepositoryMediaKind(doc.mimeType, doc.fileName);
    if (filters.hasPdf && kind !== 'pdf') return false;
    if (filters.hasImage && kind !== 'image') return false;
    if (filters.tag?.trim()) {
        const needle = filters.tag.trim().replace(/^#/, '');
        if (!(doc.tags ?? []).some((t) => t.replace(/^#/, '') === needle)) return false;
    }
    const q = filters.q.trim();
    if (!q) return true;
    const hay = [doc.title, doc.description, doc.type, doc.authorName, ...(doc.tags ?? [])].join(' ');
    return archiveTextMatchesQuery(hay, q);
}

export function isMissingTableError(message: string): boolean {
    return /forum_repository_docs|does not exist|schema cache/i.test(message);
}

import { clampForumText, sanitizeForumTagsInput } from '@/app/services/forum/forumInputSecurity';
import { mintForumEntityId, isCloudForumStoragePath } from '@/app/services/forum/forumPostCreateGuard';
import { isStoragePathOwnedByUser } from '@/app/api/upload/uploadStorageUtils';
import type { RepositoryDocument } from '@/app/services/lawyer-cloud';

const DOC_TYPES = new Set(['عقد', 'قرار حكم', 'عريضة', 'بحث قانوني', 'أخرى']);
const MAX_TAGS = 12;
const UUID_RE =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

export type ForumRepositoryDocPatch = {
    title: string;
    description: string;
    doc_type: RepositoryDocument['type'];
    tags: string[];
    updated_at: string;
    file_name?: string;
    mime_type?: string;
    storage_path?: string;
    file_size?: number;
};

export function assertPublishableRepositoryStoragePath(storagePath: string, authorId: string): void {
    if (!isCloudForumStoragePath(storagePath)) {
        throw new Error('يجب رفع الملف إلى الخادم قبل النشر');
    }
    if (!isStoragePathOwnedByUser(storagePath, authorId)) {
        throw new Error('مسار الملف لا يخص الناشر');
    }
}

function cleanTags(raw: unknown): string[] {
    if (!Array.isArray(raw)) return [];
    return raw
        .map((tag) => sanitizeForumTagsInput(String(tag)))
        .filter(Boolean)
        .slice(0, MAX_TAGS);
}

function cleanFileSize(raw: unknown): number {
    return typeof raw === 'number' && Number.isFinite(raw) ? Math.max(0, raw) : 0;
}

function requireTitleAndDescription(raw: Partial<RepositoryDocument>): {
    title: string;
    description: string;
} {
    const title = clampForumText(String(raw.title ?? '').trim(), 200);
    const description = clampForumText(String(raw.description ?? '').trim(), 4000);
    if (!title || title.length < 2 || !description || description.length < 2) {
        throw new Error('العنوان والوصف مطلوبان');
    }
    return { title, description };
}

function requireDocType(raw: Partial<RepositoryDocument>): RepositoryDocument['type'] {
    if (!raw.type || !DOC_TYPES.has(raw.type)) {
        throw new Error('نوع المستند غير صالح');
    }
    return raw.type;
}

export function sanitizeForumRepositoryDocument(
    raw: Partial<RepositoryDocument>,
    authorId: string,
    authorName: string,
): RepositoryDocument {
    const { title, description } = requireTitleAndDescription(raw);
    const type = requireDocType(raw);
    const fileName = clampForumText(String(raw.fileName ?? '').trim(), 200);
    if (!fileName) throw new Error('اسم الملف مطلوب');

    const storagePath = typeof raw.storagePath === 'string' ? raw.storagePath.trim() : '';
    assertPublishableRepositoryStoragePath(storagePath, authorId);

    const now = new Date().toISOString();
    const rawId = typeof raw.id === 'string' ? raw.id.trim() : '';
    return {
        id: UUID_RE.test(rawId) ? rawId : mintForumEntityId(),
        title,
        description,
        type,
        authorId,
        authorName: clampForumText(authorName.trim() || 'محامٍ', 80),
        uploadDate: now.slice(0, 10),
        updatedAt: now,
        fileName,
        mimeType: typeof raw.mimeType === 'string' ? raw.mimeType : '',
        storagePath,
        fileSize: cleanFileSize(raw.fileSize),
        tags: cleanTags(raw.tags),
    };
}

/** الحقول القابلة للتعديل فقط — لا يُسمح بتغيير المالك أو تاريخ الإنشاء. */
export function sanitizeForumRepositoryDocumentPatch(
    raw: Partial<RepositoryDocument>,
    authorId: string,
): ForumRepositoryDocPatch {
    const { title, description } = requireTitleAndDescription(raw);
    const patch: ForumRepositoryDocPatch = {
        title,
        description,
        doc_type: requireDocType(raw),
        tags: cleanTags(raw.tags),
        updated_at: new Date().toISOString(),
    };

    const storagePath = typeof raw.storagePath === 'string' ? raw.storagePath.trim() : '';
    if (storagePath) {
        assertPublishableRepositoryStoragePath(storagePath, authorId);
        patch.storage_path = storagePath;
        patch.file_name = clampForumText(String(raw.fileName ?? '').trim(), 200) || 'ملف';
        patch.mime_type = typeof raw.mimeType === 'string' ? raw.mimeType : '';
        patch.file_size = cleanFileSize(raw.fileSize);
    }
    return patch;
}

import type { CommunityPost } from '@/app/services/forum/forumTypes';
import { getCommunityPosts } from '@/app/services/forum/forumCommunityRuntime';
import {
    communityPostToInsertRow,
    postRowToCommunity,
    type CommentUpvoteMap,
    type ForumCommentRow,
    type ForumPostRow,
} from './forumMapper';
import { loadForumSupabaseAdmin } from './loadForumSupabaseAdmin';
import { compareCommunityPostsForFeed } from './forumUrgentConsultation';

export function createForumRepositoryId(): string {
    const cryptoObj = globalThis.crypto as Crypto | undefined;
    if (cryptoObj && 'randomUUID' in cryptoObj && typeof cryptoObj.randomUUID === 'function') {
        return cryptoObj.randomUUID();
    }
    return `${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

export function sortForumRepositoryPosts(posts: CommunityPost[]): CommunityPost[] {
    return posts.sort((a, b) => compareCommunityPostsForFeed(a, b));
}

export type ForumListPostsOptions = {
    groupId?: string;
    publicOnly?: boolean;
};

export function matchesForumListScope(post: CommunityPost, options?: ForumListPostsOptions): boolean {
    if (options?.groupId) return post.groupId === options.groupId;
    if (options?.publicOnly !== false) return !post.groupId;
    return true;
}

export async function loadCommentsForPosts(postIds: string[]): Promise<Map<string, ForumCommentRow[]>> {
    const admin = await loadForumSupabaseAdmin();
    const map = new Map<string, ForumCommentRow[]>();
    if (!admin || postIds.length === 0) return map;

    const { data, error } = await admin
        .from('forum_comments')
        .select('*')
        .in('post_id', postIds)
        .order('created_at', { ascending: true });
    if (error || !data) return map;

    for (const row of data as ForumCommentRow[]) {
        const list = map.get(row.post_id) ?? [];
        list.push(row);
        map.set(row.post_id, list);
    }
    return map;
}

export async function loadCommentUpvotes(commentIds: string[]): Promise<CommentUpvoteMap> {
    const map: CommentUpvoteMap = new Map();
    const admin = await loadForumSupabaseAdmin();
    if (!admin || commentIds.length === 0) return map;
    const { data, error } = await admin
        .from('forum_comment_upvotes')
        .select('comment_id, user_id')
        .in('comment_id', commentIds);
    if (error || !data) return map;
    for (const row of data as Array<{ comment_id: string; user_id: string }>) {
        const list = map.get(row.comment_id) ?? [];
        list.push(row.user_id);
        map.set(row.comment_id, list);
    }
    return map;
}

export async function hydrateForumPosts(rows: ForumPostRow[]): Promise<CommunityPost[]> {
    const commentMap = await loadCommentsForPosts(rows.map((r) => r.id));
    const allCommentIds: string[] = [];
    for (const list of commentMap.values()) {
        for (const c of list) allCommentIds.push(c.id);
    }
    const upvotesMap = await loadCommentUpvotes(allCommentIds);
    const posts = rows.map((row) => postRowToCommunity(row, commentMap.get(row.id) ?? [], upvotesMap));
    const { signForumPostAttachments } = await import('./forumAttachmentSigning');
    return signForumPostAttachments(posts);
}

let migrationAttempted = false;

export async function migrateForumFromLegacyKvIfEmpty(): Promise<void> {
    if (migrationAttempted) return;
    migrationAttempted = true;
    if (typeof window === 'undefined') return;

    const admin = await loadForumSupabaseAdmin();
    if (!admin) return;

    const { count, error } = await admin.from('forum_posts').select('*', { count: 'exact', head: true });
    if (error || (count ?? 0) > 0) return;

    const UUID_RE =
        /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
    const legacy = (await getCommunityPosts()).filter(
        (post) => UUID_RE.test(post.id) && UUID_RE.test(post.authorId),
    );
    if (!legacy.length) return;

    for (const post of legacy) {
        const row = communityPostToInsertRow(post);
        await admin.from('forum_posts').upsert(row, { onConflict: 'id' });
        if (post.comments.length) {
            const commentRows = post.comments.map((c) => ({
                id: c.id,
                post_id: post.id,
                author_id: c.authorId,
                author_name: c.authorName,
                content: c.content,
                parent_id: c.parentId ?? null,
                created_at: c.createdAt,
            }));
            await admin.from('forum_comments').upsert(commentRows, { onConflict: 'id' });
        }
    }
}

import { RepositoryDB, type RepositoryDocument } from '@/app/services/cloud/lawyerRepositoryCloud';
import {
    createForumRepositoryDocument,
    updateForumRepositoryDocument,
} from '@/app/services/forum/forumApi/forumApiRepository';
import { isCloudForumStoragePath } from '@/app/services/forum/forumPostCreateGuard';

export async function flushForumRepositoryIndexQueue(): Promise<RepositoryDocument[]> {
    const docs = await RepositoryDB.listDocuments();
    const pending = docs.filter((doc) => doc.indexSync && isCloudForumStoragePath(doc.storagePath));
    const done: RepositoryDocument[] = [];
    for (const doc of pending) {
        try {
            const saved =
                doc.indexSync === 'update'
                    ? await updateForumRepositoryDocument(doc.id, doc)
                    : await createForumRepositoryDocument(doc);
            const cleared: RepositoryDocument = { ...saved, indexSync: undefined };
            await RepositoryDB.saveDocument(cleared);
            done.push(cleared);
        } catch {
            /* يبقى indexSync — العامل يعيد المحاولة طالما المنتدى مفتوحاً */
        }
    }
    return done;
}

import { flushForumRepositoryIndexQueue } from '@/app/services/forum/forumRepositoryIndexQueue';

/** فوري، ثم 2ث / 8ث / 20ث، وبعدها كل دقيقة طالما سطح المنتدى مفتوحاً. */
const RETRY_DELAYS_MS = [0, 2_000, 8_000, 20_000, 60_000] as const;

let stopActive: (() => void) | null = null;

export function startForumRepositoryIndexRetryWorker(): void {
    if (typeof window === 'undefined') return;
    if (stopActive) return;
    stopActive = runForumRepositoryIndexRetryWorker();
}

export function stopForumRepositoryIndexRetryWorker(): void {
    stopActive?.();
    stopActive = null;
}

function runForumRepositoryIndexRetryWorker(): () => void {
    let cancelled = false;
    let timer: number | null = null;
    let delayIndex = 0;

    const flush = () => {
        if (cancelled) return;
        void flushForumRepositoryIndexQueue();
    };

    const scheduleNext = () => {
        if (cancelled) return;
        const ms = RETRY_DELAYS_MS[Math.min(delayIndex, RETRY_DELAYS_MS.length - 1)]!;
        delayIndex += 1;
        timer = window.setTimeout(() => {
            timer = null;
            flush();
            scheduleNext();
        }, ms) as unknown as number;
    };

    const onOnline = () => flush();
    const onVisible = () => {
        if (document.visibilityState === 'visible') flush();
    };

    window.addEventListener('online', onOnline);
    document.addEventListener('visibilitychange', onVisible);
    scheduleNext();

    return () => {
        cancelled = true;
        if (timer !== null) window.clearTimeout(timer);
        timer = null;
        window.removeEventListener('online', onOnline);
        document.removeEventListener('visibilitychange', onVisible);
    };
}

import type { BanRecord, CommunityReport } from '@/app/services/forum/forumTypes';
import {
    BanDB,
    dismissCommunityReport,
    ForumBookmarkDB,
    getCommunityReports,
    reportCommunityPost,
} from '@/app/services/forum/forumCommunityRuntime';
import { loadForumSupabaseAdmin } from './loadForumSupabaseAdmin';
import { createForumRepositoryId, loadCommentUpvotes } from './forumRepositoryHydration';

export const forumRepositoryModeration = {
    async reportPost(
        postId: string,
        reason: string,
        reporterId: string,
    ): Promise<{ ok: boolean; duplicate?: boolean }> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return reportCommunityPost(postId, reason, reporterId);
        }

        const { data: existing } = await admin
            .from('forum_reports')
            .select('id')
            .eq('post_id', postId)
            .eq('reporter_id', reporterId)
            .eq('status', 'pending')
            .maybeSingle();
        if (existing) return { ok: false, duplicate: true };

        const { error } = await admin.from('forum_reports').insert({
            id: createForumRepositoryId(),
            post_id: postId,
            reporter_id: reporterId,
            reason,
            status: 'pending',
        });
        if (error) {
            if (error.code === '23505') return { ok: false, duplicate: true };
            throw new Error(error.message);
        }
        return { ok: true };
    },

    async listReports(): Promise<CommunityReport[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return getCommunityReports();
        }
        const { data, error } = await admin
            .from('forum_reports')
            .select('*')
            .order('created_at', { ascending: false });
        if (error || !data) return [];
        return (data as Array<Record<string, unknown>>).map((r) => ({
            id: String(r.id),
            postId: String(r.post_id),
            reporterId: String(r.reporter_id),
            reason: String(r.reason),
            status: r.status as CommunityReport['status'],
            createdAt: String(r.created_at),
            reviewedById: typeof r.reviewed_by_id === 'string' ? r.reviewed_by_id : undefined,
            reviewedAt: typeof r.reviewed_at === 'string' ? r.reviewed_at : undefined,
        }));
    },

    async dismissReport(
        reportId: string,
        reviewerId: string,
        notifyOutcome: 'dismissed' | 'removed' | false = 'dismissed',
    ): Promise<void> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            await dismissCommunityReport(reportId, reviewerId);
            return;
        }
        const { data: reportRow } = await admin
            .from('forum_reports')
            .select('reporter_id, post_id')
            .eq('id', reportId)
            .maybeSingle();
        await admin
            .from('forum_reports')
            .update({
                status: 'dismissed',
                reviewed_by_id: reviewerId,
                reviewed_at: new Date().toISOString(),
            })
            .eq('id', reportId);
        if (notifyOutcome && reportRow) {
            const row = reportRow as { reporter_id: string; post_id: string };
            void import('./forumNotificationDispatch').then(({ dispatchReportOutcomeNotification }) =>
                dispatchReportOutcomeNotification({
                    reporterId: row.reporter_id,
                    postId: row.post_id,
                    outcome: notifyOutcome,
                }),
            );
        }
    },

    async isBanned(userId: string): Promise<BanRecord | null> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return BanDB.isBanned(userId);
        }
        const { data } = await admin.from('forum_bans').select('*').eq('user_id', userId).maybeSingle();
        if (!data) return null;
        const row = data as Record<string, unknown>;
        if (row.expires_at && Date.parse(String(row.expires_at)) < Date.now()) {
            await admin.from('forum_bans').delete().eq('user_id', userId);
            return null;
        }
        return {
            userId: String(row.user_id),
            userName: String(row.user_name ?? ''),
            reason: String(row.reason ?? ''),
            bannedBy: String(row.banned_by ?? ''),
            bannedAt: String(row.banned_at),
            expiresAt: typeof row.expires_at === 'string' ? row.expires_at : undefined,
        };
    },

    async banUser(record: BanRecord): Promise<void> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            await BanDB.banUser(record);
            return;
        }
        await admin.from('forum_bans').upsert({
            user_id: record.userId,
            user_name: record.userName,
            reason: record.reason,
            banned_by: record.bannedBy,
            banned_at: record.bannedAt,
            expires_at: record.expiresAt ?? null,
        });
    },

    async unbanUser(userId: string): Promise<void> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            await BanDB.unbanUser(userId);
            return;
        }
        await admin.from('forum_bans').delete().eq('user_id', userId);
    },

    async listBannedUsers(): Promise<BanRecord[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return BanDB.listBannedUsers();
        }
        const { data } = await admin.from('forum_bans').select('*');
        if (!data) return [];
        return (data as Array<Record<string, unknown>>).map((row) => ({
            userId: String(row.user_id),
            userName: String(row.user_name ?? ''),
            reason: String(row.reason ?? ''),
            bannedBy: String(row.banned_by ?? ''),
            bannedAt: String(row.banned_at),
            expiresAt: typeof row.expires_at === 'string' ? row.expires_at : undefined,
        }));
    },

    async toggleBookmark(postId: string, userId: string): Promise<{ bookmarked: boolean }> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            const bookmarked = await ForumBookmarkDB.toggle(userId, postId);
            return { bookmarked };
        }
        const { data: existing } = await admin
            .from('forum_bookmarks')
            .select('post_id')
            .eq('user_id', userId)
            .eq('post_id', postId)
            .maybeSingle();
        if (existing) {
            await admin.from('forum_bookmarks').delete().eq('user_id', userId).eq('post_id', postId);
            return { bookmarked: false };
        }
        const { error } = await admin
            .from('forum_bookmarks')
            .insert({ user_id: userId, post_id: postId });
        if (error) throw new Error(error.message);
        return { bookmarked: true };
    },

    async listBookmarkedPostIds(userId: string): Promise<string[]> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) {
            return ForumBookmarkDB.listPostIds(userId);
        }
        const { data } = await admin
            .from('forum_bookmarks')
            .select('post_id')
            .eq('user_id', userId)
            .order('created_at', { ascending: false });
        if (!data) return [];
        return (data as Array<{ post_id: string }>).map((r) => r.post_id);
    },

    async toggleCommentUpvote(
        commentId: string,
        userId: string,
    ): Promise<{ upvoted: boolean; upvoterIds: string[] }> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) return { upvoted: false, upvoterIds: [] };
        const { data: comment } = await admin
            .from('forum_comments')
            .select('author_id')
            .eq('id', commentId)
            .maybeSingle();
        if (!comment) throw new Error('التعليق غير موجود');
        if ((comment as { author_id: string }).author_id === userId) {
            throw new Error('لا يمكنك التصويت على تعليقك');
        }
        const { data: existing } = await admin
            .from('forum_comment_upvotes')
            .select('comment_id')
            .eq('user_id', userId)
            .eq('comment_id', commentId)
            .maybeSingle();
        if (existing) {
            await admin
                .from('forum_comment_upvotes')
                .delete()
                .eq('user_id', userId)
                .eq('comment_id', commentId);
        } else {
            const { error } = await admin
                .from('forum_comment_upvotes')
                .insert({ user_id: userId, comment_id: commentId });
            if (error) throw new Error(error.message);
        }
        const map = await loadCommentUpvotes([commentId]);
        const upvoterIds = map.get(commentId) ?? [];
        return { upvoted: upvoterIds.includes(userId), upvoterIds };
    },

    async reportComment(
        commentId: string,
        reason: string,
        reporterId: string,
    ): Promise<{ ok: boolean; duplicate?: boolean }> {
        const admin = await loadForumSupabaseAdmin();
        if (!admin) return { ok: false };

        const { data: existing } = await admin
            .from('forum_comment_reports')
            .select('id')
            .eq('comment_id', commentId)
            .eq('reporter_id', reporterId)
            .eq('status', 'pending')
            .maybeSingle();
        if (existing) return { ok: false, duplicate: true };

        const { error } = await admin.from('forum_comment_reports').insert({
            id: createForumRepositoryId(),
            comment_id: commentId,
            reporter_id: reporterId,
            reason,
            status: 'pending',
        });
        if (error) {
            if (error.code === '23505') return { ok: false, duplicate: true };
            throw new Error(error.message);
        }
        return { ok: true };
    },
};

import type { SupabaseClient } from '@supabase/supabase-js';
import { isCloudForumStoragePath } from '@/app/services/forum/forumPostCreateGuard';
import { parseForumRepositoryRef } from '@/app/services/forum/forumRepositoryDocsMap';
import { loadForumSupabaseAdmin } from '@/app/services/forum/loadForumSupabaseAdmin';
import { isStoragePathOwnedByUser, resolveUploadBucket } from '@/app/api/upload/uploadStorageUtils';

export const FORUM_REPOSITORY_ORPHAN_TABLE = 'forum_repository_orphan_paths';
export const FORUM_REPOSITORY_ORPHAN_GRACE_MS = 120_000;
const QUEUE_LIMIT = 40;
const PREFIX_LIST_LIMIT = 100;
const PREFIX_REMOVE_CAP = 20;
const SWEEP_DEBOUNCE_MS = 30_000;

const lastSweepAt = new Map<string, number>();

export function isForumRepositorySweepablePath(authorId: string, storagePath: string): boolean {
    const path = storagePath.trim();
    if (!path || parseForumRepositoryRef(path)) return false;
    if (!isCloudForumStoragePath(path)) return false;
    return isStoragePathOwnedByUser(path, authorId);
}

export function isMissingOrphanTableError(message: string): boolean {
    return /forum_repository_orphan_paths/i.test(message);
}

/** ملفات في بادئة المالك غير الموجودة في الفهرس، مع مهلة للرفع الجاري. */
export function repositoryPrefixOrphanPaths(params: {
    userId: string;
    catalogPaths: Iterable<string>;
    objects: Array<{ name?: string; id?: string | null; created_at?: string | null }>;
    nowMs: number;
    graceMs?: number;
}): string[] {
    const catalog = new Set(params.catalogPaths);
    const prefix = `${params.userId}/repository`;
    const grace = params.graceMs ?? FORUM_REPOSITORY_ORPHAN_GRACE_MS;
    const out: string[] = [];
    for (const obj of params.objects) {
        if (!obj.id || !obj.name || obj.name.includes('/') || obj.name === '.' || obj.name === '..') {
            continue;
        }
        const path = `${prefix}/${obj.name}`;
        if (catalog.has(path)) continue;
        const created = obj.created_at ? Date.parse(obj.created_at) : Number.NaN;
        if (!Number.isFinite(created) || params.nowMs - created < grace) continue;
        out.push(path);
    }
    return out;
}

export async function enqueueForumRepositoryOrphanPath(
    admin: SupabaseClient,
    authorId: string,
    storagePath: string,
): Promise<void> {
    if (!isForumRepositorySweepablePath(authorId, storagePath)) return;
    try {
        const { error } = await admin.from(FORUM_REPOSITORY_ORPHAN_TABLE).insert({
            author_id: authorId,
            storage_path: storagePath,
        });
        if (error && error.code !== '23505' && !isMissingOrphanTableError(error.message)) {
            /* الطابور أفضل جهد — الفهرس سقط مسبقاً */
        }
    } catch {
        /* الجدول غير مُطبَّق أو التخزين غير متاح */
    }
}

export async function removeForumRepositoryStorageOrEnqueue(
    admin: SupabaseClient,
    authorId: string,
    storagePath: string,
): Promise<void> {
    if (!isForumRepositorySweepablePath(authorId, storagePath)) return;
    try {
        const { error } = await admin.storage.from(resolveUploadBucket()).remove([storagePath]);
        if (!error) {
            await dropOrphanQueueRow(admin, storagePath);
            return;
        }
    } catch {
        /* يسقط إلى الطابور */
    }
    await enqueueForumRepositoryOrphanPath(admin, authorId, storagePath);
}

async function dropOrphanQueueRow(admin: SupabaseClient, storagePath: string): Promise<void> {
    try {
        const { error } = await admin.from(FORUM_REPOSITORY_ORPHAN_TABLE).delete().eq('storage_path', storagePath);
        if (error && !isMissingOrphanTableError(error.message)) return;
    } catch {
        /* الجدول غير موجود */
    }
}

type QueuedOrphan = { id: string; storage_path: string };

async function retryQueuedOrphans(admin: SupabaseClient, userId: string, live: Set<string>): Promise<void> {
    let queued: QueuedOrphan[] = [];
    try {
        const { data, error } = await admin
            .from(FORUM_REPOSITORY_ORPHAN_TABLE)
            .select('id, storage_path')
            .eq('author_id', userId)
            .limit(QUEUE_LIMIT);
        if (error) return;
        queued = (data ?? []) as QueuedOrphan[];
    } catch {
        return;
    }

    for (const row of queued) {
        const path = typeof row.storage_path === 'string' ? row.storage_path.trim() : '';
        if (!path) continue;
        if (live.has(path)) {
            await dropOrphanQueueRow(admin, path);
            continue;
        }
        await removeForumRepositoryStorageOrEnqueue(admin, userId, path);
    }
}

async function sweepPrefixOrphans(admin: SupabaseClient, userId: string, live: Set<string>): Promise<void> {
    const { data, error } = await admin.storage.from(resolveUploadBucket()).list(`${userId}/repository`, {
        limit: PREFIX_LIST_LIMIT,
    });
    if (error || !data) return;
    const orphans = repositoryPrefixOrphanPaths({
        userId,
        catalogPaths: live,
        objects: data,
        nowMs: Date.now(),
    }).slice(0, PREFIX_REMOVE_CAP);
    for (const path of orphans) {
        await removeForumRepositoryStorageOrEnqueue(admin, userId, path);
    }
}

export async function sweepForumRepositoryOrphansForUser(
    userId: string,
    options?: { force?: boolean },
): Promise<void> {
    const id = userId.trim();
    if (!id) return;
    const now = Date.now();
    if (!options?.force) {
        const prev = lastSweepAt.get(id) ?? 0;
        if (now - prev < SWEEP_DEBOUNCE_MS) return;
    }
    lastSweepAt.set(id, now);

    const admin = await loadForumSupabaseAdmin();
    if (!admin) return;

    const { data: catalog, error } = await admin
        .from('forum_repository_docs')
        .select('storage_path')
        .eq('author_id', id)
        .limit(500);
    if (error) return;
    const live = new Set<string>();
    for (const row of (catalog ?? []) as Array<{ storage_path?: string | null }>) {
        const path = typeof row.storage_path === 'string' ? row.storage_path.trim() : '';
        if (path) live.add(path);
    }

    await retryQueuedOrphans(admin, id, live);
    await sweepPrefixOrphans(admin, id, live);
}

import type { CommunityPost } from '@/app/services/forum/forumTypes';
import { redactAnonymousAuthor, postRowToCommunity, type ForumPostRow } from '@/app/services/forum/forumMapper';
import { signForumPostAttachments } from '@/app/services/forum/forumAttachmentSigning';
import { loadForumSupabaseAdmin } from '@/app/services/forum/loadForumSupabaseAdmin';
import { CommunityDB } from '@/app/services/forum/forumCommunityRuntime';
import {
    FORUM_SEARCH_TEXT_COLUMN,
    forumIlikeContainsPattern,
    forumIlikeRawContainsPattern,
    forumOrIlikeContentAndAuthor,
    isMissingSearchTextColumn,
} from '@/app/services/forum/forumIlikePattern';
import { compareCommunityPostsForFeed } from '@/app/services/forum/forumUrgentConsultation';
import { archiveTextMatchesQuery } from '@/app/services/search/normalizeArabicSearch';

export type ForumPostSearchFilters = {
    q: string;
    hasPdf: boolean;
    hasImage: boolean;
    tag: string | null;
    limit: number;
};

function matchesAttachmentFilters(post: CommunityPost, filters: ForumPostSearchFilters): boolean {
    if (filters.hasPdf && post.attachment?.type !== 'document') return false;
    if (filters.hasImage && post.attachment?.type !== 'image') return false;
    if (!filters.tag?.trim()) return true;
    const needle = filters.tag.trim().replace(/^#/, '');
    return (post.tags ?? []).some((t) => t.replace(/^#/, '') === needle);
}

function matchesLocalPostSearch(post: CommunityPost, filters: ForumPostSearchFilters): boolean {
    if (post.groupId) return false;
    if (!matchesAttachmentFilters(post, filters)) return false;
    const q = filters.q.trim();
    if (!q) return true;
    const hay = [post.content, post.authorName, ...(post.tags ?? [])].join(' ');
    return archiveTextMatchesQuery(hay, q);
}

async function searchPostsFromLocal(filters: ForumPostSearchFilters): Promise<CommunityPost[]> {
    const all = await CommunityDB.listPosts();
    return all
        .filter((p) => matchesLocalPostSearch(p, filters))
        .sort(compareCommunityPostsForFeed)
        .slice(0, filters.limit);
}

export async function searchForumPostsOnServer(
    filters: ForumPostSearchFilters,
    viewerId: string,
    viewerIsAdmin: boolean,
): Promise<CommunityPost[]> {
    const admin = await loadForumSupabaseAdmin();
    if (!admin) {
        return (await searchPostsFromLocal(filters)).map((p) =>
            redactAnonymousAuthor(p, viewerId, viewerIsAdmin),
        );
    }

    const buildQuery = (useSearchText: boolean) => {
        let query = admin
            .from('forum_posts')
            .select('*')
            .is('group_id', null)
            .order('is_pinned', { ascending: false })
            .order('created_at', { ascending: false })
            .limit(Math.min(80, Math.max(1, filters.limit)));

        if (filters.tag?.trim()) {
            query = query.contains('tags', [filters.tag.trim()]);
        }
        if (filters.hasImage) {
            query = query.filter('attachment->>type', 'eq', 'image');
        }
        if (filters.hasPdf) {
            query = query.filter('attachment->>type', 'eq', 'document');
        }
        if (useSearchText) {
            const pattern = forumIlikeContainsPattern(filters.q);
            if (pattern) query = query.ilike(FORUM_SEARCH_TEXT_COLUMN, pattern);
        } else {
            const legacy = forumIlikeRawContainsPattern(filters.q);
            if (legacy) query = query.or(forumOrIlikeContentAndAuthor(legacy));
        }
        return query;
    };

    let { data, error } = await buildQuery(true);
    if (error && isMissingSearchTextColumn(error.message)) {
        ({ data, error } = await buildQuery(false));
    }
    if (error || !data) {
        return (await searchPostsFromLocal(filters)).map((p) =>
            redactAnonymousAuthor(p, viewerId, viewerIsAdmin),
        );
    }

    const mapped = (data as ForumPostRow[]).map((row) => postRowToCommunity(row, []));
    const signed = await signForumPostAttachments(mapped);
    return signed
        .filter((p) => matchesLocalPostSearch(p, filters))
        .map((p) => redactAnonymousAuthor(p, viewerId, viewerIsAdmin));
}

import { isSentryEnabledInBuild as isSentryConfigured } from '@/app/observability/sentryBuildPolicy';

export type ForumPerfReportContext = {
    userId?: string;
    postCount?: number;
    hadLocalCache?: boolean;
};

type SentryModule = {
    addBreadcrumb?: (crumb: {
        category?: string;
        message?: string;
        level?: string;
        data?: Record<string, unknown>;
    }) => void;
    metrics?: {
        distribution?: (
            name: string,
            value: number,
            options?: { unit?: string; attributes?: Record<string, string | number | boolean> },
        ) => void;
    };
};

let sentryModulePromise: Promise<SentryModule | null> | null = null;

function loadSentryModule(): Promise<SentryModule | null> {
    if (!isSentryConfigured()) return Promise.resolve(null);
    if (!sentryModulePromise) {
        sentryModulePromise = import('@sentry/react')
            .then((mod) => mod as SentryModule)
            .catch(() => null);
    }
    return sentryModulePromise;
}

/** breadcrumb + metric distribution — best effort، لا يرمي */
export function reportForumOpenToSentry(
    durationMs: number,
    context: ForumPerfReportContext = {},
): void {
    if (durationMs < 0 || !Number.isFinite(durationMs)) return;

    void loadSentryModule().then((Sentry) => {
        if (!Sentry) return;

        Sentry.addBreadcrumb?.({
            category: 'forum.perf',
            message: `forum open→interactive ${durationMs}ms`,
            level: 'info',
            data: {
                durationMs,
                postCount: context.postCount ?? null,
                hadLocalCache: context.hadLocalCache ?? null,
                userId: context.userId ? '[redacted]' : null,
            },
        });

        Sentry.metrics?.distribution?.('forum.open_to_interactive_ms', durationMs, {
            unit: 'millisecond',
            attributes: {
                had_local_cache: Boolean(context.hadLocalCache),
            },
        });
    });
}

/** فتح المنتدى من لوحة المحامي — منطق موحّد */
export const FORUM_SHELL_FEATURE = 'المنتدى القانوني';

export type OpenLawyerForumInput = {
    signedIn: boolean;
    onOpen: () => void;
    onSignedOut?: () => void;
};

export function openLawyerForumFromShell(input: OpenLawyerForumInput): boolean {
    if (!input.signedIn) {
        input.onSignedOut?.();
        return false;
    }
    input.onOpen();
    return true;
}

export function shouldShowForumUnreadBadge(unreadCount: number): boolean {
    return unreadCount > 0;
}

export function formatForumUnreadBadge(unreadCount: number): string {
    if (unreadCount > 99) return '99+';
    return String(unreadCount);
}

/** تسمية قارئ الشاشة — تتضمن عدد غير المقروء عند وجود شارة */
export function resolveForumShellAriaLabel(
    unreadCount: number,
    options?: { layoutEditMode?: boolean },
): string {
    if (options?.layoutEditMode || !shouldShowForumUnreadBadge(unreadCount)) {
        return FORUM_SHELL_FEATURE;
    }
    return `${FORUM_SHELL_FEATURE}، ${formatForumUnreadBadge(unreadCount)} غير مقروء`;
}

/** إغلاق overlays المتنافسة قبل فتح المنتدى — نفس نمط الإشعارات والبحث */
