import type { ForumFollowRecord } from '@/app/services/forum/forumFollowTypes';
import { withForumAsyncTimeout } from '@/app/components/lawyer/CommunityScreen/forumAsync';

export type ForumFollowerRow = { followerId: string; createdAt: string };

let warmedFollowing: ForumFollowRecord[] | null = null;
let warmedFollowers: ForumFollowerRow[] | null = null;
let warmPromise: Promise<void> | null = null;
let warmedUserId: string | null = null;

function loadForumApiService() {
    return import('@/app/services/forumApiService');
}

export function warmForumSocialCache(userId: string): void {
    if (!userId) return;
    if (warmPromise && warmedUserId === userId) return;
    warmedUserId = userId;
    warmPromise = loadForumApiService()
        .then(({ ForumApiService }) =>
            withForumAsyncTimeout(
                Promise.all([
                    ForumApiService.listFollowing(userId),
                    ForumApiService.listFollowers(userId, userId),
                ]).then(([following, followers]) => {
                    warmedFollowing = following;
                    warmedFollowers = followers.map((r) => ({
                        followerId: r.followerId,
                        createdAt: r.createdAt,
                    }));
                }),
                4_000,
                undefined,
            ),
        )
        .catch(() => undefined);
}

export function peekForumFollowingCache(): ForumFollowRecord[] | null {
    return warmedFollowing;
}

export function peekForumFollowersCache(): ForumFollowerRow[] | null {
    return warmedFollowers;
}

export async function readForumSocialCache(userId: string): Promise<{
    following: ForumFollowRecord[];
    followers: ForumFollowerRow[];
}> {
    warmForumSocialCache(userId);
    if (warmPromise) await warmPromise;
    return {
        following: warmedFollowing ?? [],
        followers: warmedFollowers ?? [],
    };
}

import { describe, expect, it } from 'vitest';
import {
    compareCommunityPostsForFeed,
    isActiveUrgentConsultation,
    URGENT_CONSULTATION_WINDOW_MS,
} from '@/app/services/forum/forumUrgentConsultation';
import type { CommunityPost } from '@/app/services/lawyer-cloud';

function post(partial: Partial<CommunityPost> & Pick<CommunityPost, 'id' | 'createdAt'>): CommunityPost {
    return {
        authorId: 'u1',
        authorName: 'محامي',
        content: 'نص',
        tags: [],
        updatedAt: partial.createdAt,
        attachment: null,
        upvoterIds: [],
        comments: [],
        ...partial,
    };
}

describe('forumUrgentConsultation', () => {
    it('treats urgent posts as active within 24 hours', () => {
        const now = Date.parse('2026-06-20T12:00:00.000Z');
        const recent = post({
            id: '1',
            createdAt: '2026-06-20T10:00:00.000Z',
            isUrgent: true,
        });
        expect(isActiveUrgentConsultation(recent, now)).toBe(true);
    });

    it('expires urgent priority after 24 hours', () => {
        const now = Date.parse('2026-06-21T13:00:00.000Z');
        const old = post({
            id: '2',
            createdAt: '2026-06-20T12:00:00.000Z',
            isUrgent: true,
        });
        expect(now - Date.parse(old.createdAt)).toBeGreaterThan(URGENT_CONSULTATION_WINDOW_MS);
        expect(isActiveUrgentConsultation(old, now)).toBe(false);
    });

    it('ranks active urgent posts before normal posts', () => {
        const now = Date.parse('2026-06-20T12:00:00.000Z');
        const urgent = post({
            id: 'u',
            createdAt: '2026-06-20T11:00:00.000Z',
            isUrgent: true,
        });
        const normal = post({
            id: 'n',
            createdAt: '2026-06-20T11:30:00.000Z',
        });
        expect(compareCommunityPostsForFeed(urgent, normal, now)).toBeLessThan(0);
    });

    it('does not boost expired urgent posts', () => {
