import type { CommunityPost } from '@/app/services/forum/forumTypes';

/** مدة أولوية «الاستشارة العاجلة» في الترتيب (24 ساعة من وقت النشر). */
export const URGENT_CONSULTATION_WINDOW_MS = 24 * 60 * 60 * 1000;

export const URGENT_CONSULTATION_LABEL = 'الاستشارة العاجلة';
export const URGENT_CONSULTATION_BADGE = 'عاجلة';
export const URGENT_CONSULTATION_HINT =
    'تُعرض في مقدمة المقترحات لمدة 24 ساعة ثم تصبح استشارة عادية';

type UrgentPostFields = Pick<CommunityPost, 'isUrgent' | 'createdAt'>;

export function isUrgentConsultationPost(post: UrgentPostFields): boolean {
    return post.isUrgent === true;
}

export function isActiveUrgentConsultation(
    post: UrgentPostFields,
    nowMs: number = Date.now(),
): boolean {
    if (!isUrgentConsultationPost(post)) return false;
    const created = Date.parse(post.createdAt);
    if (!Number.isFinite(created)) return false;
    return nowMs - created < URGENT_CONSULTATION_WINDOW_MS;
}

export function getActiveUrgentConsultationPriority(
    post: UrgentPostFields,
    nowMs: number = Date.now(),
): number {
    return isActiveUrgentConsultation(post, nowMs) ? 1 : 0;
}

export function compareCommunityPostsForFeed(
    a: CommunityPost,
    b: CommunityPost,
    nowMs: number = Date.now(),
): number {
    const aPin = a.isPinned ? 1 : 0;
    const bPin = b.isPinned ? 1 : 0;
    if (aPin !== bPin) return bPin - aPin;

    const aUrg = getActiveUrgentConsultationPriority(a, nowMs);
    const bUrg = getActiveUrgentConsultationPriority(b, nowMs);
    if (aUrg !== bUrg) return bUrg - aUrg;

    return Date.parse(b.createdAt) - Date.parse(a.createdAt);
}

export function compareCommunityPostsByUpvotes(
    a: CommunityPost,
    b: CommunityPost,
    nowMs: number = Date.now(),
): number {
    const aPin = a.isPinned ? 1 : 0;
    const bPin = b.isPinned ? 1 : 0;
    if (aPin !== bPin) return bPin - aPin;

    const aUrg = getActiveUrgentConsultationPriority(a, nowMs);
    const bUrg = getActiveUrgentConsultationPriority(b, nowMs);
    if (aUrg !== bUrg) return bUrg - aUrg;

    return (
        b.upvoterIds.length - a.upvoterIds.length ||
        Date.parse(b.createdAt) - Date.parse(a.createdAt)
    );
}

export function hasAnyActiveUrgentConsultation(
    posts: readonly UrgentPostFields[],
    nowMs: number = Date.now(),
): boolean {
    return posts.some((post) => isActiveUrgentConsultation(post, nowMs));
}

/** سلامة روابط مرفقات/عرض المنتدى — مشتركة بين الحارس وخدمة المرفقات */

const BLOCKED_URL_SCHEMES = /^(javascript|data:text\/html|vbscript):/i;
const HAS_SCHEME = /^[a-zA-Z][a-zA-Z0-9+.-]*:/;

function isSvgDataUrl(url: string): boolean {
    const lower = url.toLowerCase();
    return lower.startsWith('data:image/svg') || lower.includes('image/svg+xml');
}

export function isSafeForumAttachmentUrl(url: string): boolean {
    const trimmed = url.trim();
    if (!trimmed) return false;
    if (/[\0\r\n\\]/.test(trimmed)) return false;
    /* //cdn.evil/x يُفسَّر في المتصفح كـ https:// — رفض صريح */
    if (trimmed.startsWith('//')) return false;
    if (trimmed.startsWith('data:')) {
        if (isSvgDataUrl(trimmed)) return false;
        return trimmed.startsWith('data:image/') || trimmed.startsWith('data:audio/');
    }
    if (trimmed.startsWith('blob:')) return true;
    if (trimmed.startsWith('idb:')) {
        return !trimmed.includes('..');
    }
    /* مسارات تخزين محلية/نسبية بلا مخطط شبكة */
    if (!HAS_SCHEME.test(trimmed)) {
        return !trimmed.includes('..');
    }
    if (BLOCKED_URL_SCHEMES.test(trimmed)) return false;
    try {
        const parsed = new URL(trimmed);
        return parsed.protocol === 'http:' || parsed.protocol === 'https:';
    } catch {
        return false;
    }
}

/** غلاف مجموعة/صورة عرض — يُرفض إن لم يكن رابط مرفق آمناً */
export function sanitizeForumCoverImage(url: string | null | undefined): string | null {
    const trimmed = typeof url === 'string' ? url.trim() : '';
    if (!trimmed) return null;
    if (!isSafeForumAttachmentUrl(trimmed)) return null;
    return trimmed.slice(0, 2_000);
}

export function isSafeRepositorySharePath(storagePath: string): boolean {
    const trimmed = storagePath.trim();
    if (!trimmed) return false;
    if (/[\0\r\n\\]/.test(trimmed)) return false;
    if (trimmed.includes('..')) return false;
    if (trimmed.startsWith('//')) return false;
    if (trimmed.startsWith('idb:forum:')) return true;
    if (HAS_SCHEME.test(trimmed)) return false;
    return true;
}

function isHttpOrigin(origin: string): boolean {
    try {
        const parsed = new URL(origin);
        return parsed.protocol === 'http:' || parsed.protocol === 'https:';
    } catch {
        return false;
    }
}

export function buildRepositoryPublicFileUrl(origin: string, storagePath: string): string | null {
    if (!isHttpOrigin(origin) || !isSafeRepositorySharePath(storagePath)) return null;
    const path = storagePath.startsWith('idb:')
        ? encodeURIComponent(storagePath)
        : storagePath
              .split('/')
              .filter(Boolean)
              .map((segment) => encodeURIComponent(segment))
              .join('/');
    return `${origin.replace(/\/$/, '')}/api/file/${path}`;
}

