import type { GlobalSearchExtras } from '@/app/services/globalSearchExtrasCache';
import { djb2Hash } from '@/app/utils/djb2';

/** فاصل extras في مفتاح الفهرس — لا يعتمد على lastIndexOf('|') لأن profileLine قد يحتوي |. */
export const GLOBAL_SEARCH_INDEX_EXTRAS_MARK = '|gsx:';

function field(value: unknown): string {
    if (value == null) return '';
    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
        return String(value);
    }
    if (value instanceof Date) return String(value.getTime());
    return '';
}

function urgentSearchBlob(rows: unknown[]): string {
    return rows
        .map((raw, idx) => {
            if (!raw || typeof raw !== 'object') return String(idx);
            const r = raw as Record<string, unknown>;
            return [
                field(r.id ?? idx),
                field(r.title),
                field(r.applicantName),
                field(r.clientName),
                field(r.notes),
                field(r.description),
                field(r.requestNumber),
                field(r.caseNo),
            ].join('\u001f');
        })
        .join('\n');
}

function extrasSearchBlob(extras: GlobalSearchExtras): string {
    const tasks = extras.quantumTasks
        .map((t) =>
            [
                t.id,
                t.title,
                t.rawText,
                t.location ?? '',
                t.status,
                t.subTasks.map((s) => s.title).join(','),
            ].join('\u001f'),
        )
        .join('\n');
    const calendar = extras.calendarEvents
        .map((e) =>
            [e.id, e.title, e.date, e.notes ?? '', e.clientName ?? '', e.caseNo ?? '', e.updatedAt].join(
                '\u001f',
            ),
        )
        .join('\n');
    const vault = extras.vaultDocs
        .map((d) => [d.id, d.title, d.lawyerNote ?? '', d.aiSummary ?? '', d.fileName].join('\u001f'))
        .join('\n');
    const repo = extras.repositoryDocs
        .map((d) => [d.id, d.title, d.description, d.fileName, (d.tags ?? []).join(',')].join('\u001f'))
        .join('\n');
    const threadingTx = extras.threadingTransactions
        .map((tx) => [tx.id, tx.title, tx.clientName, tx.status].join('\u001f'))
        .join('\n');
    const threadingTasks = extras.threadingTasks
        .map((t) => [t.id, t.title, t.notes ?? '', t.officialReference ?? ''].join('\u001f'))
        .join('\n');
    const posts = extras.communityPosts
        .map((p) => {
            const comments = (p.comments ?? []).map((c) => `${c.id}:${c.content}`).join(',');
            return [p.id, p.content, p.authorName, (p.tags ?? []).join(','), comments].join('\u001f');
        })
        .join('\n');
    return [
        tasks,
        calendar,
        urgentSearchBlob(extras.urgentCases),
        vault,
        repo,
        threadingTx,
        threadingTasks,
        posts,
    ].join('\n\n');
}

/** أطوال + هاش محتوى قابل للبحث — تعديل عنوان موعد دون تغيّر العدد يغيّر المفتاح. */
export function globalSearchExtrasSignature(extras: GlobalSearchExtras | null | undefined): string {
    if (!extras) return '0';
    return [
        extras.quantumTasks.length,
        extras.calendarEvents.length,
        extras.urgentCases.length,
        extras.vaultDocs.length,
        extras.repositoryDocs.length,
        extras.threadingTransactions.length,
        extras.threadingTasks.length,
        extras.communityPosts.length,
        djb2Hash(extrasSearchBlob(extras)),
    ].join('.');
}

export function composeGlobalSearchIndexCacheKey(core: string, extrasSig: string): string {
    return `${core}${GLOBAL_SEARCH_INDEX_EXTRAS_MARK}${extrasSig}`;
}

/** وصول extras فقط (المحتوى أو العدد) يغيّر المقطع بعد gsx. */
export function isSearchIndexKeyExtrasOnlyChange(appliedKey: string | null, cacheKey: string): boolean {
    if (!appliedKey || !cacheKey || appliedKey === cacheKey) return false;
    const mark = GLOBAL_SEARCH_INDEX_EXTRAS_MARK;
    const appliedCut = appliedKey.lastIndexOf(mark);
    const cacheCut = cacheKey.lastIndexOf(mark);
    if (appliedCut < 0 || cacheCut < 0) return false;
    return (
        appliedKey.slice(0, appliedCut) === cacheKey.slice(0, cacheCut) &&
        appliedKey.slice(appliedCut) !== cacheKey.slice(cacheCut)
    );
}

import type Fuse from 'fuse.js';
import type { IFuseOptions } from 'fuse.js';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { PERFORMANCE } from '@/app/utils/constants';
import { normalizeArabicSearch } from '@/app/services/search/normalizeArabicSearch';

type FuseInstance = Fuse<GlobalSearchEntry>;

let fuseModulePromise: Promise<{ default: typeof Fuse }> | null = null;

const fuseCache = new Map<string, FuseInstance>();
const MAX_FUSE_CACHE = 4;
/** يُرفَع عند تغيّر خيارات المحرك لإبطال كاش قديم */
const FUSE_ENGINE_REV = 6;
let appliedEngineRev = 0;

function normalizeSearchField(value: unknown): string {
    if (typeof value !== 'string') return '';
    return normalizeArabicSearch(value).toLowerCase();
}

function readPath(obj: GlobalSearchEntry, path: string | string[]): unknown {
    const parts = Array.isArray(path) ? path : String(path).split('.');
    let cur: unknown = obj;
    for (const part of parts) {
        if (cur == null || typeof cur !== 'object') return undefined;
        cur = (cur as Record<string, unknown>)[part];
    }
    return cur;
}

const FUSE_OPTIONS: IFuseOptions<GlobalSearchEntry> = {
    keys: [
        { name: 'title', weight: 3 },
        { name: 'subtitle', weight: 1.6 },
        { name: '_searchStr', weight: 1.5 },
        { name: 'snippet', weight: 0.6 },
    ],
    threshold: Math.min(PERFORMANCE.FUSE_THRESHOLD, 0.24),
    ignoreLocation: true,
    minMatchCharLength: PERFORMANCE.FUSE_MIN_MATCH_LENGTH,
    includeScore: true,
    shouldSort: true,
    findAllMatches: false,
    ignoreFieldNorm: false,
    useExtendedSearch: false,
    getFn(obj, path) {
        const raw = readPath(obj, path);
        if (Array.isArray(raw)) {
            return raw.map(normalizeSearchField).filter(Boolean);
        }
        return normalizeSearchField(raw);
    },
};

export function prefetchFuseModule(): void {
    if (typeof window === 'undefined') return;
    if (!fuseModulePromise) fuseModulePromise = import('fuse.js');
}

function trimFuseCache(): void {
    while (fuseCache.size > MAX_FUSE_CACHE) {
        const oldest = fuseCache.keys().next().value;
        if (oldest === undefined) break;
        fuseCache.delete(oldest);
    }
}

function ensureEngineRev(): void {
    if (appliedEngineRev === FUSE_ENGINE_REV) return;
    fuseCache.clear();
    appliedEngineRev = FUSE_ENGINE_REV;
}

const fuseDocsRef = new WeakMap<FuseInstance, readonly GlobalSearchEntry[]>();

export function getGlobalSearchFuseDocs(fuse: FuseInstance): readonly GlobalSearchEntry[] | null {
    return fuseDocsRef.get(fuse) ?? null;
}

async function createGlobalSearchFuse(index: GlobalSearchEntry[]): Promise<FuseInstance> {
    if (!fuseModulePromise) fuseModulePromise = import('fuse.js');
    const mod = await fuseModulePromise;
    const fuse = new mod.default<GlobalSearchEntry>(index, FUSE_OPTIONS);
    fuseDocsRef.set(fuse, index);
    return fuse;
}

export async function getOrCreateGlobalSearchFuse(
    cacheKey: string,
    index: GlobalSearchEntry[],
): Promise<FuseInstance> {
    ensureEngineRev();
    const hit = fuseCache.get(cacheKey);
    if (hit) return hit;
    const fuse = await createGlobalSearchFuse(index);
    fuseCache.set(cacheKey, fuse);
    trimFuseCache();
    return fuse;
}

