/** يجمع بيانات vault/localStorage على الخيط الرئيسي — جاهزة للـ Worker أو idle build. */
export function prepareGlobalSearchIndexInput(source: GlobalSearchIndexSource): BuildGlobalSearchIndexInput {
    const preparedVaultNotes: PreparedVaultNote[] = [];
    if (source.userId) {
        notesVault.setUserScope(source.userId);
        for (const n of notesVault.getNotes()) {
            preparedVaultNotes.push({
                id: n.id,
                content: n.content,
                type: n.type,
            });
        }
    }

    const preparedDocsVault: PreparedDocsVaultDoc[] = [];
    if (source.userId) {
        docsVault.setUserScope(source.userId);
        for (const d of docsVault.getDocuments()) {
            preparedDocsVault.push({
                id: d.id,
                name: d.name,
                caseId: d.caseId,
                tags: d.tags,
            });
        }
    }

    const preparedExecutionDeepEntries =
        source.executionFiles?.length ?
            buildExecutionDeepSearchEntries(source.executionFiles, (draft, lifecycle) => ({
                ...draft,
                lifecycle,
            }))
        :   [];

    return {
        ...source,
        preparedVaultNotes,
        preparedDocsVault,
        preparedExecutionDeepEntries,
    };
}

export function computeGlobalSearchIndexKey(input: BuildGlobalSearchIndexInput): string {
    const extrasSig = globalSearchExtrasSignature(input.extras);

    // توقيع واعٍ بالمحتوى — يلتقط تعديل العنوان/الأطراف/الملاحظات/المراحل دون انتظار تغيّر العدد
    const filesSig = djb2Hash(input.files.map(fileSearchIndexSignature).join('~'));
    const executionFilesSig = djb2Hash(
        (input.executionFiles ?? []).map((f) => fileSearchIndexSignature({ ...f, type: 'execution' })).join('~'),
    );
    const notesSig = djb2Hash(
        input.globalNotes
            .map((n) => `${String(n.id ?? '')}:${n.type ?? ''}:${n.title ?? ''}:${n.body ?? ''}`)
            .join('~'),
    );

    const lawsuitIndexSig = djb2Hash(lawsuitLifecycleIndexSignature(input.lawsuitLifecycleIndex));

    const core = [
        input.userId ?? '',
        input.cacheGeneration ?? 0,
        input.files.length,
        filesSig,
        lawsuitIndexSig,
        input.executionFiles?.length ?? 0,
        executionFilesSig,
        input.globalNotes.length,
        notesSig,
        input.cases.length,
        input.criminalCases?.length ?? 0,
        input.profileLine ?? '',
        input.notifications?.length ?? 0,
        input.preparedVaultNotes?.length ?? -1,
        input.preparedDocsVault?.length ?? -1,
        input.preparedStoredNotes?.length ?? -1,
        input.preparedExecutionDeepEntries?.length ?? -1,
    ].join('|');
    return composeGlobalSearchIndexCacheKey(core, extrasSig);
}

import {
    type BuildGlobalSearchIndexInput,
    type GlobalSearchEntry,
} from '@/app/services/globalSearchIndex';
import { computeGlobalSearchIndexKey } from '@/app/services/globalSearchIndexPrepare';
import {
    buildGlobalSearchIndexOffThread,
    prefetchGlobalSearchIndexWorker,
} from '@/app/services/search/globalSearchIndexWorkerClient';

const indexCache = new Map<string, GlobalSearchEntry[]>();
const inflightByKey = new Map<string, Promise<GlobalSearchEntry[]>>();
const MAX_INDEX_CACHE = 4;
let cacheEpoch = 0;

function trimIndexCache(): void {
    while (indexCache.size > MAX_INDEX_CACHE) {
        const oldest = indexCache.keys().next().value;
        if (oldest === undefined) break;
        indexCache.delete(oldest);
    }
}

function buildOnIdleThread(input: BuildGlobalSearchIndexInput): Promise<GlobalSearchEntry[]> {
    return new Promise((resolve, reject) => {
        const run = () => {
            void buildGlobalSearchIndexOffThread(input).then(resolve, reject);
        };
        if (typeof requestIdleCallback !== 'undefined') {
            requestIdleCallback(run, { timeout: 160 });
        } else {
            setTimeout(run, 0);
        }
    });
}

/** بناء الفهرس مع كاش — Worker عند الإمكان، idle للتسخين، تفاعلي عند فتح البحث. */
export async function resolveGlobalSearchIndex(
    input: BuildGlobalSearchIndexInput,
    priority: 'interactive' | 'idle' = 'idle',
): Promise<GlobalSearchEntry[]> {
    const key = computeGlobalSearchIndexKey(input);
    const hit = indexCache.get(key);
    if (hit) return hit;

    const existing = inflightByKey.get(key);
    if (existing) return existing;

    const epoch = cacheEpoch;
    let promise: Promise<GlobalSearchEntry[]>;
    promise = (
        priority === 'interactive'
            ? buildGlobalSearchIndexOffThread(input)
            : buildOnIdleThread(input)
    )
        .then((index) => {
            if (epoch === cacheEpoch) {
                indexCache.set(key, index);
                trimIndexCache();
            }
            return index;
        })
        .finally(() => {
            if (inflightByKey.get(key) === promise) inflightByKey.delete(key);
        });

    inflightByKey.set(key, promise);
    return promise;
}

export function invalidateGlobalSearchIndexCache(): void {
    cacheEpoch += 1;
    indexCache.clear();
    inflightByKey.clear();
}

export function getCachedGlobalSearchIndex(key: string): GlobalSearchEntry[] | null {
    return indexCache.get(key) ?? null;
}

