    const opened = openHubArchiveFromShell({
        signedIn: hasLocalAppSession(userId),
        archiveId,
        onSignedOut: () => toastHubSignedOut(archiveId),
        onOpen,
    });
    if (opened) {
        prefetchHubArchiveIntentImmediate(archiveId, userId);
    }
    return opened;
}

