/**
 * التحكم في استدعاءات kv-proxy من المتصفح.
 * في التطوير: محلي افتراضياً (مثل urgent-actions-db) لتجنب عاصفة الطلبات.
 * فعّل بـ VITE_ENABLE_KV_PROXY=true عندما يُراد حفظ التقويم/المعاملات سحابياً على Vite.
 * على الاستضافة الثابتة: لا نستدعي الشبكة إلا بعد تأكيد توفر /api.
 */
import { getSameOriginApiState } from '@/app/runtime/sameOriginApiProbe';

export function isKvProxyNetworkEnabled(): boolean {
    if (import.meta.env.VITE_ENABLE_KV_PROXY === 'false') return false;
    const optedIn = import.meta.env.VITE_ENABLE_KV_PROXY === 'true';
    if (import.meta.env.DEV && !optedIn) return false;
    return getSameOriginApiState() === 'available';
}

/**
 * حارس طلبات kv-proxy — يمنع عاصفة الطلبات التي تجمد المتصفح
 */
import { debug } from '@/app/utils/debug';
import { resolveDeniedNetworkFeatureResponse } from '@/app/services/secureApiNetworkFeatures';

type InFlightEntry = { promise: Promise<Response>; startedAt: number };

const WINDOW_MS = import.meta.env.DEV ? 10_000 : 12_000;
const MAX_REQUESTS_PER_WINDOW = import.meta.env.DEV ? 48 : 16;
const MAX_IN_FLIGHT = import.meta.env.DEV ? 8 : 6;
const DEV_RATE_LIMIT_WAIT_MS = 2_000;

let windowStart = 0;
let windowCount = 0;
const inFlight = new Map<string, InFlightEntry>();

function requestKey(url: string, method: string, body: string): string {
    return `${method}:${url}:${body}`;
}

function pruneWindow(now: number): void {
    if (now - windowStart > WINDOW_MS) {
        windowStart = now;
        windowCount = 0;
    }
}

export function resetKvProxyGuardForTests(): void {
    windowStart = 0;
    windowCount = 0;
    inFlight.clear();
}

export async function fetchKvProxyGuarded(
    url: string,
    init: RequestInit,
    nativeFetch: typeof fetch,
): Promise<Response> {
    const now = Date.now();
    pruneWindow(now);

    const method = (init.method ?? 'GET').toUpperCase();
    const body = typeof init.body === 'string' ? init.body : '';

    const key = requestKey(url, method, body);
    const existing = inFlight.get(key);
    if (existing) {
        return existing.promise;
    }

    const windowWaitStarted = Date.now();
    while (windowCount >= MAX_REQUESTS_PER_WINDOW) {
        const waitMs = Math.max(50, WINDOW_MS - (Date.now() - windowStart));
        await new Promise((r) => setTimeout(r, Math.min(waitMs, 500)));
        pruneWindow(Date.now());
        if (windowCount < MAX_REQUESTS_PER_WINDOW) break;
        if (import.meta.env.DEV && Date.now() - windowWaitStarted < DEV_RATE_LIMIT_WAIT_MS) {
            continue;
        }
        if (import.meta.env.DEV) {
            debug.warn('[KvGuard] تجاوز حد kv-proxy — تم تخطي الطلب');
        }
        return new Response(JSON.stringify({ error: 'rate_limited', localOnly: true }), {
            status: 429,
            headers: { 'Content-Type': 'application/json' },
        });
    }

    while (inFlight.size >= MAX_IN_FLIGHT) {
        if (import.meta.env.DEV) {
            debug.warn('[KvGuard] طلبات kv-proxy متزامنة كثيرة — انتظار');
        }
        await Promise.race([...inFlight.values()].map((e) => e.promise)).catch(() => undefined);
        if (inFlight.size < MAX_IN_FLIGHT) break;
    }

    windowCount += 1;

    const denied = resolveDeniedNetworkFeatureResponse('/api/kv-proxy');
    if (denied) {
        windowCount = Math.max(0, windowCount - 1);
        return denied;
    }

    const promise = nativeFetch(url, init).finally(() => {
        inFlight.delete(key);
    });

    inFlight.set(key, { promise, startedAt: now });
    return promise;
}

export function isKvProxyUrl(url: string): boolean {
    return url.includes('/kv-proxy');
}

/**
 * تنبيهات قسم الدعاوى المدنية — Direct producer.
 *
 * يُولّد تنبيهات لـ:
 *  - الإضبارات المعطّلة (status === 'paused'): تنبيه بناءً على stayReviewDate
 *  - مهل الطعن في المراحل: CaseStage.legalTimers.* + CaseStage.appealDeadline
 *  - تواريخ نظر مستقبلية: FileData.nextDate
 *  - tasks بـ dueDate غير مرتبطة بـ calendar
 *  - الإضبارات الراكدة (لا نشاط منذ > 90 يوم) — بناءً على آخر history/notes
 */

import type { FileData } from '@/app/domain/lawsuit/lawsuitFileTypes';
import type { SecretaryAlert } from '@/app/services/SecretaryOrchestrator';
import { composeRichAlert } from '@/app/services/alertRichContext';
import type { DossierRegistry } from '@/app/services/alertDossierRegistry';
import { parseYmdToTs, dayDiff } from '@/app/services/executionAlerts.helpers';

const DAY_MS = 24 * 60 * 60 * 1000;
const DORMANCY_DAYS = 90;

function priorityByDaysToDue(days: number): number {
    if (days <= 1) return 1;
    if (days <= 3) return 2;
    if (days <= 7) return 3;
    return 4;
}

function safeStr(v: unknown): string {
    return typeof v === 'string' ? v.trim() : '';
}

function asArray(v: unknown): unknown[] {
    return Array.isArray(v) ? v : [];
}

function asRecord(v: unknown): Record<string, unknown> {
    return v && typeof v === 'object' ? (v as Record<string, unknown>) : {};
}

function pushAlert(out: SecretaryAlert[], a: SecretaryAlert | null): void {
    if (a) out.push(a);
}

/** اشتقاق آخر تاريخ نشاط من history/notes (لمعرفة الركود). */
function lastLawsuitActivityTs(f: FileData): number | null {
    let max: number | null = null;
    const consider = (v: unknown) => {
        const t = parseYmdToTs(v);
        if (t != null && (max === null || t > max)) max = t;
    };

    consider(f.date);
    consider((f as unknown as Record<string, unknown>).nextDate);
    consider((f as unknown as Record<string, unknown>).firstHearingDate);
    consider((f as unknown as Record<string, unknown>).stayReviewDate);
    for (const h of asArray(f.history)) consider(asRecord(h).date);
    for (const n of asArray(f.notes)) {
        const rec = asRecord(n);
        consider(rec.date);
        consider(rec.apptDate);
    }
    return max;
}

/** بناء تنبيهات لمرحلة واحدة (CaseStage). */
function buildStageAlerts(
    stage: Record<string, unknown>,
    stageIndex: number,
    f: FileData,
    now: number,
    ctx: ReturnType<DossierRegistry['resolve']>,
): SecretaryAlert[] {
    if (!ctx) return [];
    const out: SecretaryAlert[] = [];
    const stageStatus = safeStr(stage.status);
    if (stageStatus === 'locked' || stageStatus === 'completed' || stage.isVoided === true) {
        return out;
    }

    const stageName = safeStr(stage.stageName) || safeStr(stage.name);
    const fileId = String(f.id);

    const recordDeadline = (
        label: string,
        kind: 'appeal' | 'cassation' | 'review' | 'finalAppeal' | 'defaultObjection',
        ymd: string,
    ) => {
        const ts = parseYmdToTs(ymd);
        if (ts == null) return;
        const days = dayDiff(ts, now);
        if (days < 0 || days > 30) return;
        pushAlert(
            out,
            composeRichAlert({
                id: `lawsuit:${fileId}:stage-${stageIndex}:${kind}`,
                type: 'DEADLINE',
                dueAt: new Date(ts).toISOString(),
                aiDeepDive: `${label}${stageName ? ` — ${stageName}` : ''}. لا تفوّت الموعد.`,
                target: 'lawsuit',
                entityId: fileId,
                priority: priorityByDaysToDue(days),
                context: ctx,
            }),
        );
    };

    // legalTimers (المصدر الأغنى)
    const timers = asRecord(stage.legalTimers);
    recordDeadline('مهلة الاستئناف', 'appeal', safeStr(timers.appealDeadline));
    recordDeadline('مهلة التمييز', 'cassation', safeStr(timers.cassationDeadline));
    recordDeadline('مهلة إعادة المحاكمة', 'review', safeStr(timers.reviewDeadline));
    recordDeadline('مهلة الطعن النهائي', 'finalAppeal', safeStr(timers.finalAppealDeadline));
    recordDeadline('مهلة الاعتراض على القرار الغيابي', 'defaultObjection', safeStr(timers.defaultObjectionDeadline));

    // appealDeadline على المرحلة (مكرّر للحماية إن لم تكن legalTimers موجودة)
    if (!timers.appealDeadline) {
        const direct = safeStr(stage.appealDeadline);
        if (direct) recordDeadline('مهلة الاستئناف', 'appeal', direct);
    }

    return out;
}

export function buildLawsuitAlerts(
    files: FileData[],
    now: Date,
    registry: DossierRegistry,
): SecretaryAlert[] {
    const out: SecretaryAlert[] = [];
    const nowTs = now.getTime();

    for (const f of files) {
        if (!f) continue;
        if (f.type !== 'lawsuit') continue;
        if (f.status === 'deleted') continue;

        const fileId = String(f.id);
        const ctx = registry.resolve('lawsuit', fileId);
        if (!ctx) continue;

        // 1) إضبارة معطّلة بـ stayReviewDate قادم
        if (f.status === 'paused') {
            const reviewStr = safeStr((f as unknown as Record<string, unknown>).stayReviewDate);
            if (reviewStr) {
                const ts = parseYmdToTs(reviewStr);
                if (ts != null) {
                    const days = dayDiff(ts, nowTs);
                    if (days >= 0 && days <= 14) {
                        pushAlert(
                            out,
                            composeRichAlert({
                                id: `lawsuit:${fileId}:stay-review`,
                                type: 'URGENT',
                                dueAt: new Date(ts).toISOString(),
                                aiDeepDive: `موعد مراجعة وقف الإضبارة قريب${f.stayReason ? `: ${f.stayReason}` : '.'}`,
                                target: 'lawsuit',
                                entityId: fileId,
                                priority: priorityByDaysToDue(days),
                                context: ctx,
                            }),
                        );
                    }
                }
            }
        }

        // 2) nextDate / firstHearingDate — تاريخ نظر مستقبلي قريب (في حال لم يُسجّل في calendar)
        const fileRec = f as unknown as Record<string, unknown>;
        const nextDateStr = safeStr(fileRec.nextDate) || safeStr(fileRec.firstHearingDate);
        if (nextDateStr) {
            const ts = parseYmdToTs(nextDateStr);
            if (ts != null) {
                const days = dayDiff(ts, nowTs);
                if (days >= 0 && days <= 14) {
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `lawsuit:${fileId}:next-date`,
                            type: 'HEARING',
                            dueAt: new Date(ts).toISOString(),
                            aiDeepDive: 'موعد قادم على ملف الدعوى.',
                            target: 'lawsuit',
                            entityId: fileId,
                            priority: priorityByDaysToDue(days),
                            context: ctx,
                        }),
                    );
                }
            }
        }

        // 3) tasks بـ dueDate
        for (const taskRaw of asArray(f.tasks)) {
            const t = asRecord(taskRaw);
            if (t.completed === true) continue;
            const due = safeStr(t.dueDate);
            const ts = parseYmdToTs(due);
            if (ts == null) continue;
            const days = dayDiff(ts, nowTs);
            if (days < 0 || days > 30) continue;
            pushAlert(
                out,
                composeRichAlert({
                    id: `lawsuit:${fileId}:task:${t.id ?? due}`,
                    type: 'TASK',
                    dueAt: new Date(ts).toISOString(),
                    aiDeepDive: safeStr(t.description) || safeStr(t.title) || 'مهمة على ملف الدعوى.',
                    target: 'lawsuit',
                    entityId: fileId,
                    priority: priorityByDaysToDue(days),
                    context: ctx,
                }),
            );
        }

        // 4) stages — مهل الطعن
        const stages = asArray((f as unknown as Record<string, unknown>).stages);
        stages.forEach((stRaw, idx) => {
            const st = asRecord(stRaw);
            const stageAlerts = buildStageAlerts(st, idx, f, nowTs, ctx);
            for (const a of stageAlerts) out.push(a);
        });

        // 5) الركود (> 90 يوم بلا نشاط) للإضبارات النشطة
        if (f.status === 'active') {
            const last = lastLawsuitActivityTs(f);
            if (last != null) {
                const daysSince = Math.floor((nowTs - last) / DAY_MS);
                if (daysSince >= DORMANCY_DAYS) {
                    const dueTs = nowTs + DAY_MS;
                    pushAlert(
                        out,
                        composeRichAlert({
                            id: `lawsuit:${fileId}:dormancy`,
                            type: 'TASK',
                            dueAt: new Date(dueTs).toISOString(),
                            aiDeepDive: `الإضبارة بدون نشاط منذ ${daysSince} يوماً. تحقق من المرحلة الحالية أو حدّد جلسة جديدة.`,
                            target: 'lawsuit',
                            entityId: fileId,
                            priority: 4,
                            context: ctx,
                        }),
                    );
                }
            }
        }
    }

    return out;
}

import type { CaseStage, TimelineEvent } from '@/app/components/lawyer/lawyerShared/stageTimelineTypes';
import { normalizeDateToYmd } from '@/app/services/calendar/bridge';
import { syncLawsuitTimelineAppointment } from '@/app/services/calendar/dossierSync/incrementalSync';
import {
    formatPersonalStatusStageDisplayName,
    isPersonalStatusAppealContext,
    isPersonalStatusDossierFromStages,
} from '@/app/components/lawyer/personal-status/personalStatusAppealStageHelpers';
import {
    isCassationCorrectionStageName,
    isCassationStageName,
} from '@/app/components/lawyer/smart-modal/smartFile/judgmentStageNames';

export const LAWSUIT_CAL_APPT = {
    sessionNext: (sessionId: string) => `appt_session_next_${sessionId}`,
    appealDeadline: (stageId: string) => `appt_appeal_deadline_${stageId}`,
    judgmentDate: (stageId: string) => `appt_judgment_${stageId}`,
    cassationDeadline: (stageId: string) => `appt_cassation_deadline_${stageId}`,
    reviewDeadline: (stageId: string) => `appt_review_deadline_${stageId}`,
    finalAppealDeadline: (stageId: string) => `appt_final_appeal_deadline_${stageId}`,
    defaultObjectionDeadline: (stageId: string) => `appt_default_objection_deadline_${stageId}`,
} as const;

export type LawsuitLegalCalendarSpec = {
    id: string;
    date: string | null;
    title: string;
    details?: string;
    subType?: TimelineEvent['subType'];
};

type MirrorContext = {
    userId?: string | null;
    fileId: string;
    caseNo?: string;
    court?: string;
    parties?: unknown;
    clientName?: string;
};

function stageDegreeLabel(stageName?: string | null): 'first_instance' | 'appeal' | 'cassation' | 'other' {
    const raw = String(stageName ?? '').trim();
    if (!raw) return 'other';
    if (raw === 'التمييز' || (raw.includes('تمييز') && !raw.includes('استئناف'))) return 'cassation';
    if (raw.includes('استئناف') && !raw.includes('تمييز')) return 'appeal';
    if (!raw.includes('استئناف') && !raw.includes('التمييز')) return 'first_instance';
    return 'other';
}

function resolveJudgmentMirrorMeta(stage: CaseStage): { title: string; details?: string } {
    const finalDecision = typeof stage.finalDecision === 'string' ? stage.finalDecision.trim() : '';
    const stageLabel = String(stage.stageName ?? '').trim();
    const isPersonalContext =
        isPersonalStatusAppealContext(stage.stageName, [stage])
        || isPersonalStatusDossierFromStages([stage]);

    if (isPersonalContext) {
        if (isCassationStageName(stage.stageName)) {
            return {
                title: 'تاريخ القرار التمييزي',
                details: finalDecision || (stageLabel ? `مرحلة: ${stageLabel}` : undefined),
            };
        }
        const displayLabel =
            formatPersonalStatusStageDisplayName(stageLabel, { showCoreStage: true })
            ?? 'محكمة الموضوع';
        return {
            title: `تاريخ قرار ${displayLabel}`,
            details: finalDecision || (stageLabel ? `مرحلة: ${stageLabel}` : undefined),
        };
    }

    const degree = stageDegreeLabel(stage.stageName);

    if (degree === 'first_instance') {
        return {
            title: 'تاريخ الحكم',
            details: finalDecision || (stageLabel ? `مرحلة: ${stageLabel}` : undefined),
        };
    }
    if (degree === 'appeal') {
        return {
            title: 'تاريخ الحكم الاستئنافي',
            details: finalDecision || (stageLabel ? `مرحلة: ${stageLabel}` : undefined),
        };
    }
    if (degree === 'cassation') {
        return {
            title: 'تاريخ القرار التمييزي',
            details: finalDecision || (stageLabel ? `مرحلة: ${stageLabel}` : undefined),
        };
    }

    return {
        title: stageLabel ? `تاريخ القرار في ${stageLabel}` : 'تاريخ الحكم',
        details: finalDecision || undefined,
    };
}

function resolveCassationDeadlineMirrorMeta(stage: CaseStage): { title: string; details?: string } {
    const degree = stageDegreeLabel(stage.stageName);
    if (degree === 'appeal') {
        return {
            title: 'مهلة التمييز',
            details: 'آخر مهلة للتمييز بعد الحكم الاستئنافي (شهر من صدور القرار)',
        };
    }
    if (degree === 'first_instance') {
        return {
            title: 'مهلة التمييز',
            details: 'آخر مهلة للتمييز إن لم يُستأنف الحكم (شهر من صدور القرار)',
        };
    }
    if (degree === 'cassation') {
        return {
            title: 'مهلة الطعن على القرار التمييزي',
            details: 'آخر موعد للطعن على القرار التمييزي',
        };
    }
    const stageLabel = String(stage.stageName ?? '').trim();
    return {
        title: 'مهلة التمييز',
        details: stageLabel ? `مرحلة: ${stageLabel}` : undefined,
    };
}

function shouldMirrorAppealDeadline(stage: CaseStage): boolean {
    if (isCassationCorrectionStageName(stage.stageName)) return false;
    if (isPersonalStatusAppealContext(stage.stageName)) return false;
    if (isPersonalStatusDossierFromStages([stage])) return false;
    const degree = stageDegreeLabel(stage.stageName);
    return degree === 'first_instance';
}

function shouldMirrorCassationDeadline(stage: CaseStage): boolean {
    if (isCassationCorrectionStageName(stage.stageName)) return false;
    /* التمييز آخر درجة — لا مهلة «تمييز على التمييز» */
    if (isCassationStageName(stage.stageName)) return false;
    const degree = stageDegreeLabel(stage.stageName);
    return degree === 'first_instance' || degree === 'appeal';
}

function shouldMirrorExtraordinaryDeadline(stage: CaseStage): boolean {
    if (isCassationCorrectionStageName(stage.stageName)) return false;
    /* الطعون الاستثنائية بعد التمييز ممكنة؛ تُدار من مساراتها لا من مرآة مهلة التمييز */
    const degree = stageDegreeLabel(stage.stageName);
    return degree === 'first_instance' || degree === 'appeal';
}

function resolveAppealDeadlineMirrorMeta(stage: CaseStage): { title: string; details?: string } {
    const degree = stageDegreeLabel(stage.stageName);
    const stageLabel = String(stage.stageName ?? '').trim();

    if (degree === 'first_instance') {
        return {
            title: 'آخر موعد طعن على الحكم',
            details: 'آخر موعد للاستئناف (15 يوماً من اليوم التالي لصدور الحكم)',
        };
    }
    if (degree === 'appeal') {
        return {
            title: 'آخر موعد طعن على الحكم الاستئنافي',
            details: 'آخر موعد للتمييز بعد الحكم الاستئنافي',
        };
    }
    if (degree === 'cassation') {
        return {
            title: 'آخر موعد على القرار التمييزي',
            details: stageLabel ? `مرحلة: ${stageLabel}` : undefined,
        };
    }

    return {
        title: stageLabel ? `آخر موعد في ${stageLabel}` : 'مهلة الطعن',
        details: stageLabel ? `مرحلة: ${stageLabel}` : undefined,
    };
}

function upsertTimelineAppointment(
    timeline: TimelineEvent[],
    spec: {
        id: string;
        date?: string | null;
        title: string;
        details?: string;
        subType?: TimelineEvent['subType'];
    },
): TimelineEvent[] {
    const ymd = normalizeDateToYmd(spec.date);
    if (!ymd) {
        return timeline.filter((e) => e.id !== spec.id);
    }
    const appt: TimelineEvent = {
        id: spec.id,
        type: 'appointment',
        date: ymd,
        title: spec.title,
        details: spec.details,
        subType: spec.subType ?? 'other',
        isDeleted: false,
    };
    const idx = timeline.findIndex((e) => e.id === spec.id);
    if (idx >= 0) {
        return timeline.map((e, i) => (i === idx ? { ...e, ...appt } : e));
    }
    return [{ ...appt, isNew: true }, ...timeline];
}

function readAppealDeadline(stage: CaseStage): string | null {
    const direct = normalizeDateToYmd(stage.appealDeadline ?? null);
    if (direct) return direct;
    const timers = stage.legalTimers as { appealDeadline?: string } | undefined;
    return normalizeDateToYmd(timers?.appealDeadline ?? null);
}

/** يستخرج كل المُهل/التواريخ القانونية المخزّنة صراحةً في المرحلة (لا حساب آلي). */
export function collectStageLegalCalendarSpecs(
    stage: CaseStage | Record<string, unknown>,
    stageIndex = 0,
): LawsuitLegalCalendarSpec[] {
    const s = stage as CaseStage;
    const stageId = String(s.id ?? `stage_${stageIndex}`).trim() || `stage_${stageIndex}`;
    const timers = (s.legalTimers ?? {}) as {
        appealDeadline?: string;
        cassationDeadline?: string;
        reviewDeadline?: string;
        finalAppealDeadline?: string;
        defaultObjectionDeadline?: string;
    };
    const appealMeta = resolveAppealDeadlineMirrorMeta(s);
    const judgmentMeta = resolveJudgmentMirrorMeta(s);
    const cassationMeta = resolveCassationDeadlineMirrorMeta(s);

    return [
        {
            id: LAWSUIT_CAL_APPT.appealDeadline(stageId),
            date: shouldMirrorAppealDeadline(s) ? readAppealDeadline(s) : null,
            title: appealMeta.title,
            details: appealMeta.details,
            subType: 'other',
        },
        {
            id: LAWSUIT_CAL_APPT.judgmentDate(stageId),
            date: normalizeDateToYmd(s.decisionDate ?? null),
            title: judgmentMeta.title,
            details: judgmentMeta.details ? String(judgmentMeta.details).slice(0, 120) : undefined,
            subType: 'verdict',
        },
        {
            id: LAWSUIT_CAL_APPT.cassationDeadline(stageId),
            date: shouldMirrorCassationDeadline(s)
                ? normalizeDateToYmd(timers.cassationDeadline ?? null)
                : null,
            title: cassationMeta.title,
            details: cassationMeta.details,
            subType: 'other',
        },
        {
            id: LAWSUIT_CAL_APPT.reviewDeadline(stageId),
            date: shouldMirrorExtraordinaryDeadline(s)
                ? normalizeDateToYmd(timers.reviewDeadline ?? null)
                : null,
            title: 'مهلة إعادة المحاكمة',
            details: 'آخر موعد لطلب إعادة المحاكمة',
            subType: 'other',
        },
        {
            id: LAWSUIT_CAL_APPT.finalAppealDeadline(stageId),
            date: shouldMirrorExtraordinaryDeadline(s)
                ? normalizeDateToYmd(timers.finalAppealDeadline ?? null)
                : null,
            title: 'مهلة الطعن النهائي',
            details: 'آخر موعد للطعن النهائي',
            subType: 'other',
        },
        {
            id: LAWSUIT_CAL_APPT.defaultObjectionDeadline(stageId),
            date: shouldMirrorAppealDeadline(s)
                ? normalizeDateToYmd(timers.defaultObjectionDeadline ?? null)
                : null,
            title: 'مهلة الاعتراض على الحكم الغيابي',
            details: 'آخر موعد للاعتراض الغيابي (10 أيام من التبليغ)',
            subType: 'other',
        },
    ];
}

function syncMirrorAppointment(
    ctx: MirrorContext,
    event: { id: string; date?: string | null; title: string; details?: string },
): void {
    if (!ctx.fileId) return;
    const ymd = normalizeDateToYmd(event.date);
    if (!ymd) {
        syncLawsuitTimelineAppointment({
            userId: ctx.userId,
            fileId: ctx.fileId,
            event: { id: event.id, isDeleted: true },
            caseNo: ctx.caseNo,
            court: ctx.court,
            parties: ctx.parties,
            clientName: ctx.clientName,
        });
        return;
    }
    syncLawsuitTimelineAppointment({
        userId: ctx.userId,
        fileId: ctx.fileId,
        event: {
            id: event.id,
            date: ymd,
            title: event.title,
            details: event.details,
        },
        caseNo: ctx.caseNo,
        court: ctx.court,
        parties: ctx.parties,
        clientName: ctx.clientName,
    });
}

/** يرفع «تاريخ المرافعة القادمة» من محضر الجلسة إلى موعد في الخط الزمني + التقويم */
export function mirrorSessionNextHearingToCalendar(
    stages: CaseStage[],
    stageIndex: number,
    sessionEventId: string,
    nextHearingDate: string | undefined | null,
    sessionTitle: string,
    ctx: MirrorContext,
): CaseStage[] {
    const next = [...stages];
    const stage = next[stageIndex];
    if (!stage) return stages;

    const apptId = LAWSUIT_CAL_APPT.sessionNext(sessionEventId);
    const timeline = upsertTimelineAppointment(stage.timeline ?? [], {
        id: apptId,
        date: nextHearingDate,
        title: 'مرافعة قادمة',
        details: sessionTitle,
        subType: 'pleading',
    });
    next[stageIndex] = { ...stage, timeline };

    syncMirrorAppointment(ctx, {
        id: apptId,
        date: nextHearingDate,
        title: 'مرافعة قادمة',
        details: sessionTitle,
    });

    return next;
}

/** يرفع مهلة الطعن وتاريخ الحكم والمُهل القانونية المخزّنة إلى مواعيد في الخط الزمني + التقويم */
export function mirrorStageLegalDatesToCalendar(
    stages: CaseStage[],
    stageIndex: number,
    ctx: MirrorContext,
): CaseStage[] {
    const next = [...stages];
    const stage = next[stageIndex];
    if (!stage) return stages;

    const specs = collectStageLegalCalendarSpecs(stage, stageIndex);
    let timeline = stage.timeline ?? [];

    for (const spec of specs) {
        timeline = upsertTimelineAppointment(timeline, {
            id: spec.id,
            date: spec.date,
            title: spec.title,
            details: spec.details,
            subType: spec.subType,
        });
    }

    next[stageIndex] = { ...stage, timeline };

    for (const spec of specs) {
        syncMirrorAppointment(ctx, {
            id: spec.id,
            date: spec.date,
            title: spec.title,
            details: spec.details,
        });
    }

    return next;
}

/**
 * مرآة تقويم الإضبارة — تُحمَّل عند الحفظ فقط، بلا سحب incrementalSync إلى أول إطار.
 */

type MirrorMod = typeof import('./lawsuitTimelineCalendarMirror');

let mirrorPromise: Promise<MirrorMod> | null = null;
let stageDatesEpoch = 0;
let sessionHearingEpoch = 0;

function loadMirror(): Promise<MirrorMod> {
    if (!mirrorPromise) {
        mirrorPromise = import('./lawsuitTimelineCalendarMirror');
    }
    return mirrorPromise;
}

export function overlayMirrorStageLegalDatesToCalendar(
    stages: Parameters<MirrorMod['mirrorStageLegalDatesToCalendar']>[0],
    stageIndex: number,
    ctx: Parameters<MirrorMod['mirrorStageLegalDatesToCalendar']>[2],
    apply: (next: ReturnType<MirrorMod['mirrorStageLegalDatesToCalendar']>) => void,
): void {
    const epoch = ++stageDatesEpoch;
    void loadMirror()
        .then((m) => {
            if (epoch !== stageDatesEpoch) return;
            apply(m.mirrorStageLegalDatesToCalendar(stages, stageIndex, ctx));
        })
        .catch(() => undefined);
}

export function overlayMirrorSessionNextHearingToCalendar(
    stages: Parameters<MirrorMod['mirrorSessionNextHearingToCalendar']>[0],
    stageIndex: number,
    sessionEventId: string,
    nextHearingDate: string | undefined,
    sessionTitle: string,
    ctx: Parameters<MirrorMod['mirrorSessionNextHearingToCalendar']>[5],
    apply: (next: ReturnType<MirrorMod['mirrorSessionNextHearingToCalendar']>) => void,
): void {
    const epoch = ++sessionHearingEpoch;
    void loadMirror()
        .then((m) => {
            if (epoch !== sessionHearingEpoch) return;
            apply(
                m.mirrorSessionNextHearingToCalendar(
                    stages,
                    stageIndex,
                    sessionEventId,
                    nextHearingDate,
                    sessionTitle,
                    ctx,
                ),
            );
        })
        .catch(() => undefined);
}

