import SecureStoreService from '@/app/services/SecureStoreService';
import {
    clearLegacyPlaintextMirror,
    readSecureOrDrainLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';
import type { Note } from '@/app/data/NotesVault';
import type { GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';

export const NOTES_VAULT_CHANGED = 'hami-notes-vault-changed';

export type NotesSyncMap = Record<string, string>;

const syncMapKey = (userId: string) => `hami_notes_sync_map_${userId}`;

export function loadSyncMap(userId: string): NotesSyncMap {
    try {
        const raw = readSecureOrDrainLegacySync(syncMapKey(userId));
        if (!raw) return {};
        const parsed: unknown = JSON.parse(raw);
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return {};
        return parsed as NotesSyncMap;
    } catch {
        return {};
    }
}

export function saveSyncMap(userId: string, map: NotesSyncMap): void {
    const serialized = JSON.stringify(map);
    const key = syncMapKey(userId);
    if (serialized === '{}' || serialized === 'null') {
        try {
            const existing = readSecureOrDrainLegacySync(key);
            if (existing && existing.trim() !== '' && existing !== '{}' && existing !== 'null') {
                return;
            }
        } catch {
            /* ignore */
        }
    }
    SecureStoreService.setItemSync(key, serialized);
    clearLegacyPlaintextMirror(key);
}

export function emitVaultNotesChanged(): void {
    if (typeof window !== 'undefined') {
        window.dispatchEvent(new CustomEvent(NOTES_VAULT_CHANGED));
    }
}

function normalizeContent(s: string): string {
    return s.trim().replace(/\s+/g, ' ').toLowerCase();
}

export function contentFingerprint(body: string, createdAtMs?: number): string {
    const ms = createdAtMs && !Number.isNaN(createdAtMs) ? createdAtMs : 0;
    return `${ms}|${normalizeContent(body)}`;
}

export function vaultToGlobal(v: Note, title = 'ملاحظة قانونية'): GlobalNote {
    return {
        id: v.id,
        title,
        body: v.content,
        isPinned: false,
        date: new Date(v.createdAt).toISOString(),
        type: v.type,
    };
}

export function globalToVault(g: GlobalNote): Note {
    const parsed = g.date ? Date.parse(g.date) : Date.now();
    return {
        id: `g_${String(g.id)}`,
        content: g.body || '',
        type: g.type === 'voice' ? 'voice' : 'text',
        createdAt: Number.isNaN(parsed) ? Date.now() : parsed,
        linkedCaseId: g.linkedFileId != null ? String(g.linkedFileId) : undefined,
    };
}

/** دمج رجعي ثنائي الاتجاه بين globalNotes و notesVault */
export function bidirectionalMerge(
    userId: string,
    globalNotes: GlobalNote[],
    vaultNotes: Note[],
): { mergedGlobal: GlobalNote[]; mergedVault: Note[]; syncMap: NotesSyncMap } {
    const map = { ...loadSyncMap(userId) };
    const vaultIds = new Set(vaultNotes.map((v) => v.id));
    const orphanedGlobalIds = new Set<string>();
    Object.entries(map).forEach(([gid, vid]) => {
        if (!vaultIds.has(vid)) orphanedGlobalIds.add(gid);
    });
    orphanedGlobalIds.forEach((gid) => delete map[gid]);

    let nextVault = [...vaultNotes];
    let nextGlobal = globalNotes.filter((g) => !orphanedGlobalIds.has(String(g.id)));

    const vaultById = new Map(nextVault.map((n) => [n.id, n]));
    const globalById = new Map(nextGlobal.map((n) => [String(n.id), n]));
    const vaultByFp = new Map<string, Note>();
    nextVault.forEach((v) => vaultByFp.set(contentFingerprint(v.content, v.createdAt), v));

    for (const g of nextGlobal) {
        const gid = String(g.id);
        const body = (g.body || '').trim();
        if (!body) continue;
        if (map[gid] && vaultById.has(map[gid])) continue;

        const fp = contentFingerprint(body, g.date ? Date.parse(g.date) : undefined);
        const existing = vaultByFp.get(fp);
        if (existing) {
            map[gid] = existing.id;
            continue;
        }

        const vaultNote = globalToVault(g);
        nextVault = [vaultNote, ...nextVault.filter((n) => n.id !== vaultNote.id)];
        map[gid] = vaultNote.id;
        vaultById.set(vaultNote.id, vaultNote);
        vaultByFp.set(fp, vaultNote);
    }

    for (const v of nextVault) {
        const linkedGid = Object.entries(map).find(([, vid]) => vid === v.id)?.[0];
        if (linkedGid && globalById.has(linkedGid)) continue;

        const fp = contentFingerprint(v.content, v.createdAt);
        const dup = nextGlobal.find(
            (g) =>
                contentFingerprint(g.body || '', g.date ? Date.parse(g.date) : undefined) === fp,
        );
        if (dup) {
            map[String(dup.id)] = v.id;
            continue;
        }

        const g = vaultToGlobal(v);
        if (!globalById.has(String(g.id))) {
            nextGlobal.push(g);
            globalById.set(String(g.id), g);
        }
        map[String(g.id)] = v.id;
    }

    nextGlobal.sort((a, b) => {
        const ta = a.date ? Date.parse(a.date) : 0;
        const tb = b.date ? Date.parse(b.date) : 0;
        return (Number.isNaN(tb) ? 0 : tb) - (Number.isNaN(ta) ? 0 : ta);
    });

    saveSyncMap(userId, map);
    return { mergedGlobal: nextGlobal, mergedVault: nextVault, syncMap: map };
}

export function linkGlobalToVault(userId: string, globalId: string | number, vaultId: string): void {
    const map = loadSyncMap(userId);
    map[String(globalId)] = vaultId;
    saveSyncMap(userId, map);
}

export function unlinkGlobal(userId: string, globalId: string | number): void {
    const map = loadSyncMap(userId);
    delete map[String(globalId)];
    saveSyncMap(userId, map);
}

export function vaultIdForGlobal(userId: string, globalId: string | number): string | undefined {
    return loadSyncMap(userId)[String(globalId)];
}

/**
 * Tombstones لملاحظات المستودع/المفكرة.
 * ذاكرة أمام حارس المسح — التشفير عبر جسر SecureStore.
 * لا تستورد SecureStore هنا: dossierWipeGuard → هذه الوحدة → SecureStore = دورة.
 */
import { createDeletedIdsLiteStore } from '@/app/services/storage/deletedIdsLiteStore';
import { isDeletedIdsStorageUnreadSync } from '@/app/services/storage/deletedIdsPersistBridge';

export const NOTES_DELETED_IDS_KEY = 'hami:lawyer-notes:deleted:v1';
const LOCAL_SCOPE = '_local_';

const store = createDeletedIdsLiteStore(NOTES_DELETED_IDS_KEY, (k) => k.includes(':'));

/** أصل مشفّر لم يُفكّ ≠ لا حذف — دمج السحابة عندها يُعيد المحذوف. */
export function areNotesDeletedIdsUnreadSync(): boolean {
    return isDeletedIdsStorageUnreadSync(NOTES_DELETED_IDS_KEY);
}

/** يفكّ شواهد حذف الملاحظات. false = لا تدمج السحابة. */
export async function ensureNotesDeletedIdsReadable(): Promise<boolean> {
    if (!areNotesDeletedIdsUnreadSync()) return true;
    try {
        const { default: SecureStoreService } = await import('@/app/services/SecureStoreService');
        await SecureStoreService.getItem(NOTES_DELETED_IDS_KEY);
    } catch {
        /* يبقى unread */
    }
    return !areNotesDeletedIdsUnreadSync();
}

function noteTombstoneKey(userId: string | null | undefined, noteId: string): string {
    const scope = userId?.trim() || LOCAL_SCOPE;
    return `${scope}:${String(noteId).trim()}`;
}

/** يُسجّل حذفاً محلياً — يمنع إعادة الدمج من القرص/السحابة/NotesVault */
export function markGlobalNoteDeleted(
    userId: string | null | undefined,
    noteId: string | number,
): void {
    const id = String(noteId).trim();
    if (!id) return;
    store.add([noteTombstoneKey(userId, id), noteTombstoneKey(LOCAL_SCOPE, id)]);
}

export function isGlobalNoteDeleted(
    userId: string | null | undefined,
    noteId: string | number,
): boolean {
    const id = String(noteId).trim();
    if (!id) return false;
    return store.has(noteTombstoneKey(userId, id)) || store.has(noteTombstoneKey(LOCAL_SCOPE, id));
}

export function filterDeletedGlobalNotes<T extends { id?: string | number | null }>(
    notes: T[],
    userId?: string | null,
): T[] {
    const keys = store.read();
    if (keys.size === 0) return notes;
    return notes.filter((n) => {
        const id = n?.id != null ? String(n.id).trim() : '';
        if (!id) return true;
        return !(keys.has(noteTombstoneKey(userId, id)) || keys.has(noteTombstoneKey(LOCAL_SCOPE, id)));
    });
}

/**
 * ترشيح صفوف المزامنة (سحابة/محلي) — نفس عقد الدعاوى/التنفيذ.
 * mark يزرع `_local_:` دائماً فيمرّ الترشيح بلا userId.
 */
export function filterTombstonedNotesSyncRows(rows: unknown, userId?: string | null): unknown[] {
    if (!Array.isArray(rows)) return [];
    return filterDeletedGlobalNotes(
        rows.filter((row): row is { id?: string | number | null } => Boolean(row) && typeof row === 'object'),
        userId,
    );
}

/** هل كل ملاحظات القرص الحالية عليها tombstone؟ — يسمح بمسح `[]` عبر wipe-guard */
export function areAllStoredNotesTombstoned(
    existingRaw: string | null | undefined,
    userId?: string | null,
): boolean {
    if (!existingRaw?.trim()) return true;
    try {
        const parsed: unknown = JSON.parse(existingRaw);
        if (!Array.isArray(parsed) || parsed.length === 0) return true;
        return parsed.every((item) => {
            if (!item || typeof item !== 'object') return true;
            const id = (item as { id?: unknown }).id;
            if (id == null) return true;
            return isGlobalNoteDeleted(userId, String(id));
        });
    } catch {
        return false;
    }
}

/** للاختبارات */
export function resetGlobalNotesTombstonesForTests(): void {
    store.resetForTests();
}

import {
    deriveNotificationDirection,
    type NotificationModel,
} from '@/app/infrastructure/NotificationRepository';

/** عناوين إجراءات ذاتية (قديمة أو حالية) — ليست إشعارات واردة حقيقية. */
const SELF_ACTION_TITLES = new Set([
    'نشرت سؤالاً في المنتدى',
    'حذفت سؤالاً',
    'رددت على سؤال',
    'حددت أفضل إجابة',
    'تمت إضافة مستند',
    'تم مسح مستند ضوئياً',
    'ربط مستند بقضية',
]);

/** إجراء قام به المحامي بنفسه — لا يُعرض في لوحة الإشعارات. */
export function isSelfActionNotification(n: NotificationModel): boolean {
    const title = String(n.title ?? '').trim();
    if (SELF_ACTION_TITLES.has(title)) return true;
    return deriveNotificationDirection(n) === 'outgoing';
}

/** إشعار وارد حقيقي يستحق عرضاً للمستخدم. */
export function isIncomingNotification(n: NotificationModel): boolean {
    return !isSelfActionNotification(n);
}

import type { NotificationCategory, NotificationModel, NotificationType } from '@/app/infrastructure/NotificationRepository';

const UUID_RE =
    /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const UUID_IN_TEXT =
    /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;

const DOSSIER_NOISE_LABELS = new Set([
    'تنفيذ',
    'جزائي',
    'جزائية',
    'مدني',
    'مدنية',
    'معاملة',
    'تنفيذي',
    'تنفيذية',
    '—',
    '-',
]);

const ENGLISH_TOKEN_MAP: Record<string, string> = {
    active: 'نشطة',
    paused: 'معلّقة',
    finished: 'منتهية',
    closed: 'مغلقة',
    open: 'مفتوحة',
    off: 'إيقاف',
    on: 'تشغيل',
    debtor: 'المدين',
    guarantor: 'الكفيل',
    publication: 'تبليغ بالنشر',
    mal: 'حجز مال',
    aqar: 'حجز عقار',
    manqul: 'حجز منقول',
    'ladaal-ghair': 'حجز لدى الغير',
    incoming: 'وارد',
    outgoing: 'صادر',
};

function isUuidLike(value: unknown): boolean {
    return UUID_RE.test(String(value ?? '').trim());
}

function normalizeArabicToken(value: string): string {
    return value
        .trim()
        .toLowerCase()
        .replace(/أ|إ|آ/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي');
}

function isTechnicalNotificationToken(value: unknown): boolean {
    const v = String(value ?? '').trim();
    if (!v) return true;
    if (isUuidLike(v)) return true;
    if (/^(case|crim|criminal|exe|execution|e|q|n|task|persist|body|note|doc)-[\w-]+$/i.test(v)) {
        return true;
    }
    if (/^#?\d{6,}$/.test(v)) return true;
    return false;
}

function isNoiseDossierLabel(value: unknown, module?: string): boolean {
    const v = String(value ?? '').trim();
    if (!v) return true;
    if (isTechnicalNotificationToken(v)) return true;
    const norm = normalizeArabicToken(v);
    if (DOSSIER_NOISE_LABELS.has(norm)) return true;
    if (module) {
        const moduleNorm = normalizeArabicToken(
            (
                {
                    civil: 'مدنية',
                    personal: 'أحوال شخصية',
                    criminal: 'جزائية',
                    execution: 'تنفيذ',
                    threading: 'معاملة',
                } as Record<string, string>
            )[module] ?? '',
        );
        if (norm === moduleNorm) return true;
    }
    return false;
}

export function stripTechnicalTokensFromMessage(message: string): string {
    return String(message ?? '')
        .replace(UUID_IN_TEXT, '')
        .replace(/\b(case|crim|criminal|exe|execution|task|note|doc)-[\w-]+\b/gi, '')
        .replace(/\s*(?:[—•·|→]\s*){2,}/g, ' — ')
        .replace(/^\s*[—•·|→]\s*|\s*[—•·|→]\s*$/g, '')
        .replace(/\s{2,}/g, ' ')
        .trim();
}

function translateKnownEnglishTokens(message: string): string {
    return message.replace(/\b([a-z][a-z0-9_-]*)\b/gi, (match) => {
        const mapped = ENGLISH_TOKEN_MAP[match.toLowerCase()];
        return mapped ?? match;
    });
}

export function formatAuditCaseReference(p: {
    caseNo?: string | null;
    clientName?: string | null;
    fileNumber?: string | null;
    module?: string;
    fallback?: string;
}): string {
    const parts: string[] = [];
    for (const raw of [p.caseNo, p.fileNumber, p.clientName]) {
        const v = String(raw ?? '').trim();
        if (!v || isNoiseDossierLabel(v, p.module)) continue;
        if (parts.some((existing) => normalizeArabicToken(existing) === normalizeArabicToken(v))) {
            continue;
        }
        parts.push(v);
    }
    if (parts.length > 0) return parts.join(' — ');
    return p.fallback ?? 'إضبارة مسجّلة';
}

/** تنقّلات واجهة لا تُعرض في سجل النشاطات (فتح/إغلاق إضبارة، ...). */
export function isNavigationNoiseNotification(
    notification: Pick<NotificationModel, 'title' | 'message' | 'actionPayload'>,
): boolean {
    const title = String(notification.title ?? '').trim();
    if (/^فتح\s+إضبارة/i.test(title)) return true;
    const payload = notification.actionPayload;
    if (payload && typeof payload === 'object') {
        const module = String((payload as { module?: string }).module ?? '').trim();
        const entityId = (payload as { entityId?: unknown }).entityId;
        if (module && entityId != null && /^فتح/i.test(title)) return true;
    }
    const message = String(notification.message ?? '').trim();
    if (/^فتح\s+إضبارة/i.test(message)) return true;
    if (message === 'تم فتح الإضبارة' && /^فتح/i.test(title)) return true;
    return false;
}

export function formatNotificationForCard(
    notification: NotificationModel,
): { eventTitle: string; caseRef: string | null; detailLine: string } {
    if (isNavigationNoiseNotification(notification)) {
        return { eventTitle: '', caseRef: null, detailLine: '' };
    }

    const payload = notification.actionPayload ?? {};
    const payloadCaseNo = String(
        (payload as { caseNo?: string }).caseNo ??
            (payload as { caseNumber?: string }).caseNumber ??
            '',
    ).trim();
    const payloadClient = String((payload as { clientName?: string }).clientName ?? '').trim();
    const payloadDetail = String((payload as { detail?: string }).detail ?? '').trim();

    const message = sanitizeNotificationDisplayMessage(notification);
    const segments = message.split(/\s*•\s*/).map((s) => s.trim()).filter(Boolean);

    let caseRef: string | null = null;
    let detailLine = message;

    if (segments.length >= 2) {
        caseRef = segments[0] ?? null;
        detailLine = segments.slice(1).join(' • ');
    } else if (payloadCaseNo && !isTechnicalNotificationToken(payloadCaseNo)) {
        caseRef = formatAuditCaseReference({
            caseNo: payloadCaseNo,
            clientName: payloadClient || undefined,
            module:
                notification.category === 'criminal'
                    ? 'criminal'
                    : notification.category === 'execution'
                      ? 'execution'
                      : undefined,
        });
        detailLine = payloadDetail || segments[0] || message;
        if (caseRef && detailLine === caseRef) detailLine = payloadDetail || notification.title;
    } else {
        detailLine = payloadDetail || segments[0] || message;
    }

    if (caseRef && detailLine.startsWith(`${caseRef} •`)) {
        detailLine = detailLine.slice(caseRef.length + 2).trim();
    }

    return {
        eventTitle: String(notification.title ?? '').trim() || 'نشاط مسجّل',
        caseRef: caseRef && !isTechnicalNotificationToken(caseRef) ? caseRef : null,
        detailLine: detailLine || String(notification.title ?? '').trim(),
    };
}

function inferFallbackMessage(input: {
    title?: string;
    category?: NotificationCategory;
    type?: NotificationType;
}): string {
    const title = String(input.title ?? '').trim();
    if (title.includes('فتح إضبارة')) return '';
    if (title.includes('إنشاء')) return title;
    if (title.includes('تم ')) return title;
    switch (input.category) {
        case 'criminal':
            return 'نشاط جزائي';
        case 'execution':
            return 'نشاط تنفيذي';
        case 'civil':
            return 'نشاط مدني';
        case 'task':
            return 'نشاط في المعاملات';
        case 'forum':
            return 'نشاط في المنتدى';
        case 'document':
            return 'نشاط في المستندات';
        case 'system':
            return 'تنبيه نظام';
        default:
            return title || 'نشاط مسجّل';
    }
}

export function sanitizeNotificationDisplayMessage(
    notification: Pick<NotificationModel, 'message' | 'title' | 'category' | 'type'>,
): string {
    let message = stripTechnicalTokensFromMessage(String(notification.message ?? '').trim());
    message = translateKnownEnglishTokens(message);

    if (!message || isTechnicalNotificationToken(message) || message === 'قضية') {
        return inferFallbackMessage(notification);
    }

    if (/^قضية\s*[—•·|→]?\s*$/i.test(message)) {
        return inferFallbackMessage(notification);
    }

    return message;
}

