};

let clientDbPromise: Promise<ForumNotificationDb> | null = null;
let serverDbPromise: Promise<ForumNotificationDb> | null = null;

/** يختار NotificationDB (عميل) أو ServerNotificationDB (خادم) حسب runtime. */
export async function resolveForumNotificationDb(): Promise<ForumNotificationDb> {
    if (typeof window === 'undefined') {
        if (!serverDbPromise) {
            // @vite-ignore — لا تُدرَج وحدة الخادم/kvStoreAdmin في حزم العميل
            const spec = '@/app/services/notifications/notificationForumStorage.server.ts';
            serverDbPromise = import(/* @vite-ignore */ spec).then(
                (m: { ServerNotificationDB: ForumNotificationDb }) => m.ServerNotificationDB,
            );
        }
        return serverDbPromise;
    }
    if (!clientDbPromise) {
        clientDbPromise = Promise.resolve(NotificationDB);
    }
    return clientDbPromise;
}

import type { ForumNotification, NotificationType as ForumNotificationType } from '@/app/services/forum/forumTypes';
import {
    deriveNotificationCategory,
    type NotificationModel,
    type NotificationType,
} from '@/app/infrastructure/notificationModel';

function mapForumTypeToAppType(forumType: ForumNotificationType): NotificationType {
    switch (forumType) {
        case 'best_answer':
            return 'forum_solved';
        case 'mention':
            return 'forum_mention';
        case 'follow':
        case 'upvote':
        case 'new_post':
        case 'comment':
        case 'reply':
        case 'report_update':
        case 'system':
        case 'new_document':
        default:
            return 'forum_reply';
    }
}

function mapAppTypeToForumType(
    appType: NotificationType,
    payload?: Record<string, unknown>,
): ForumNotificationType {
    const preserved = payload?.forumType;
    if (typeof preserved === 'string') {
        return preserved as ForumNotificationType;
    }
    switch (appType) {
        case 'forum_mention':
            return 'mention';
        case 'forum_solved':
            return 'best_answer';
        default:
            return 'reply';
    }
}

/** تحويل إشعار منتدى → NotificationModel بنفس المعرّف (مصدر واحد للحقيقة). */
export function mapForumNotificationToModel(n: ForumNotification): NotificationModel {
    const postId = n.postId ?? n.id;
    return {
        id: n.id,
        title: n.title,
        message: n.message,
        type: mapForumTypeToAppType(n.type),
        category: 'forum',
        direction: 'incoming',
        isRead: n.read,
        createdAt: n.createdAt,
        actionPayload: {
            postId,
            questionId: postId,
            forumType: n.type,
            ...(n.dedupeKey ? { dedupeKey: n.dedupeKey } : {}),
            ...(typeof n.activityCount === 'number' ? { activityCount: n.activityCount } : {}),
        },
    };
}

/** NotificationModel → ForumNotification (للوحة المنتدى). */
export function mapModelToForumNotification(
    model: NotificationModel,
    userId: string,
): ForumNotification | null {
    if (deriveNotificationCategory(model) !== 'forum') return null;
    const payload = model.actionPayload ?? {};
    const postId = String(payload.postId ?? payload.questionId ?? model.id);
    return {
        id: model.id,
        userId,
        type: mapAppTypeToForumType(model.type, payload),
        title: model.title,
        message: model.message,
        postId,
        read: model.isRead,
        createdAt: model.createdAt,
        dedupeKey: typeof payload.dedupeKey === 'string' ? payload.dedupeKey : undefined,
        activityCount: typeof payload.activityCount === 'number' ? payload.activityCount : undefined,
    };
}

import { NotificationDB } from '@/app/services/notifications/notificationForumStorage';

type ApiOk<T> = { ok: true } & T;
type ApiErr = { ok: false; error?: string };

async function postForumJson<T>(endpoint: string, body: Record<string, unknown>): Promise<T> {
    const { SecureAPIClient, SecureFetchError } = await import('@/app/services/SecureAPIClient');
    const res = await SecureAPIClient.fetchSecure<T & ApiErr>(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
    });
    if (res && typeof res === 'object' && (res as ApiErr).ok === false) {
        const message = (res as ApiErr).error?.trim() || 'تعذّر تنفيذ العملية';
        throw new SecureFetchError(message, 400, JSON.stringify(res), endpoint);
    }
    return res as T;
}

