                message: input.message,
                type: input.type,
                category: input.category,
                dedupeKey: input.dedupeKey,
                actionPayload: input.actionPayload,
            }),
        });
        if (res?.ok && res.notification) return res.notification;
        return null;
    } catch {
        return null;
    }
}

