    mergeLegacyForumIntoModels,
    parseNotificationBlob,
} from '@/app/services/notifications/notificationForumBlobOps';

export const FORUM_KV_UNIFIED_MIGRATION_VERSION = 'v1';
const MIGRATION_FLAG_PREFIX = 'hami:notifications:kv-unified:';
const MERGED_IDS_PREFIX = 'hami:notifications:kv-unified:merged-ids:';
const LEGACY_GLOBAL_FORUM_LOCAL = 'hami:notifications:v1';
const DELETE_RETRY_ATTEMPTS = 5;
const DELETE_RETRY_DELAY_MS = 400;

function migrationFlagKey(userId: string): string {
    return `${MIGRATION_FLAG_PREFIX}${userId}:${FORUM_KV_UNIFIED_MIGRATION_VERSION}`;
}

function mergedIdsKey(userId: string): string {
    return `${MERGED_IDS_PREFIX}${userId}:${FORUM_KV_UNIFIED_MIGRATION_VERSION}`;
}

function sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

function isValidForumNotification(value: unknown): value is ForumNotification {
    if (!value || typeof value !== 'object') return false;
    const o = value as Record<string, unknown>;
    return typeof o.id === 'string' && typeof o.userId === 'string';
}

function loadMergedLegacyIds(userId: string): Set<string> {
    try {
        const raw = readSecureOrDrainLegacySync(mergedIdsKey(userId));
        if (!raw) return new Set();
        const parsed = JSON.parse(raw) as string[];
        return new Set(Array.isArray(parsed) ? parsed : []);
    } catch {
        return new Set();
    }
}

function saveMergedLegacyIds(userId: string, ids: Set<string>): void {
    try {
        const key = mergedIdsKey(userId);
        SecureStoreService.setItemSync(key, JSON.stringify([...ids].slice(-500)));
        clearLegacyPlaintextMirror(key);
    } catch {
        /* ignore */
    }
}

function getMigrationFlag(userId: string): string | null {
    try {
        return readSecureOrDrainLegacySync(migrationFlagKey(userId));
    } catch {
        return null;
    }
}

function setMigrationFlag(userId: string, value: '1' | 'partial'): void {
    try {
        const key = migrationFlagKey(userId);
        SecureStoreService.setItemSync(key, value);
        clearLegacyPlaintextMirror(key);
    } catch {
        /* ignore */
    }
}

async function loadLegacyPrefixForumNotifications(userId: string): Promise<ForumNotification[]> {
    if (!isKvProxyNetworkEnabled() || !canUseServerBackedNetworkFeatures(userId)) return [];
    try {
        const res = await SecureAPIClient.fetchSecure<{ values?: unknown[] }>('/api/kv-proxy', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'getByPrefix', prefix: `notifications:${userId}:` }),
        });
        const values = Array.isArray(res?.values) ? res.values : [];
        return values.filter(isValidForumNotification);
    } catch {
        return [];
    }
}

function loadLegacyGlobalLocalForum(userId: string): Set<string> {
    try {
        const raw = readSecureOrDrainLegacySync(LEGACY_GLOBAL_FORUM_LOCAL);
        if (!raw) return new Set();
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return new Set();
        return new Set(
            parsed
                .filter(isValidForumNotification)
                .filter((n) => n.userId === userId)
                .map((n) => n.id),
        );
    } catch {
        return new Set();
    }
}

async function deleteLegacyPrefixKeysOnce(userId: string): Promise<void> {
    if (!isKvProxyNetworkEnabled() || !canUseServerBackedNetworkFeatures(userId)) return;
    await SecureAPIClient.fetchSecure('/api/kv-proxy', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'delByPrefix', prefix: `notifications:${userId}:` }),
    });
}

async function deleteLegacyPrefixKeysWithRetry(userId: string): Promise<boolean> {
    for (let attempt = 0; attempt < DELETE_RETRY_ATTEMPTS; attempt += 1) {
        try {
            await deleteLegacyPrefixKeysOnce(userId);
        } catch {
            /* retry */
        }
        const remaining = await loadLegacyPrefixForumNotifications(userId);
        if (remaining.length === 0) return true;
        if (attempt < DELETE_RETRY_ATTEMPTS - 1) {
            await sleep(DELETE_RETRY_DELAY_MS);
        }
    }
    return false;
}

function filterUnmergedLegacy(
    legacy: ForumNotification[],
    mergedIds: Set<string>,
): ForumNotification[] {
    return legacy.filter((n) => !mergedIds.has(n.id));
}

/** دمج per-item keys القديمة في blob — مع retry للحذف وتتبّع ids المدمجة. */
export async function migrateLegacyForumKvToBlobIfNeeded(
    userId: string,
    loadBlob: () => Promise<NotificationModel[]>,
    saveBlob: (models: NotificationModel[]) => Promise<void>,
): Promise<boolean> {
    const flag = getMigrationFlag(userId);
    if (flag === '1') return false;

    const mergedIds = loadMergedLegacyIds(userId);
    const prefixLegacy = filterUnmergedLegacy(await loadLegacyPrefixForumNotifications(userId), mergedIds);
    const localLegacyIds = loadLegacyGlobalLocalForum(userId);

    let localLegacy: ForumNotification[] = [];
    if (localLegacyIds.size > 0) {
        try {
            const raw = readSecureOrDrainLegacySync(LEGACY_GLOBAL_FORUM_LOCAL);
            const parsed: unknown = raw ? JSON.parse(raw) : [];
            if (Array.isArray(parsed)) {
                localLegacy = filterUnmergedLegacy(
                    parsed.filter(isValidForumNotification).filter((n) => n.userId === userId),
                    mergedIds,
                );
            }
        } catch {
            /* ignore */
        }
    }

    const legacy = [...prefixLegacy, ...localLegacy];
    if (legacy.length === 0) {
        if (flag !== 'partial') setMigrationFlag(userId, '1');
        return false;
    }

    const current = parseNotificationBlob(await loadBlob());
    const merged = mergeLegacyForumIntoModels(current, legacy);
    await saveBlob(merged);

    for (const n of legacy) mergedIds.add(n.id);
    saveMergedLegacyIds(userId, mergedIds);

    const deleted = await deleteLegacyPrefixKeysWithRetry(userId);
    setMigrationFlag(userId, deleted ? '1' : 'partial');

    return true;
}

export async function retryLegacyPrefixCleanupIfPartial(userId: string): Promise<boolean> {
    if (getMigrationFlag(userId) !== 'partial') return false;
    const deleted = await deleteLegacyPrefixKeysWithRetry(userId);
    if (deleted) setMigrationFlag(userId, '1');
    return deleted;
}

import type { ForumNotification } from '@/app/services/forum/forumTypes';
import { mapForumNotificationToModel } from '@/app/services/notifications/forumNotificationMapper';
import {
    dismissForumNotificationInModels,
    extractForumNotificationsFromModels,
    markAllForumReadInModels,
    markForumReadInModels,
    patchForumInModels,
    upsertForumIntoModels,
} from '@/app/services/notifications/notificationForumBlobOps';
import {
    readNotificationBlobServer,
    saveNotificationBlobServer,
    upsertNotificationModelsServer,
    cleanupLegacyForumPrefixServer,
} from '@/app/services/notifications/notificationServerBlob';

function withServerTimestamp(notif: ForumNotification): ForumNotification {
    return {
        ...notif,
        createdAt: new Date().toISOString(),
    };
}

/** NotificationDB على الخادم — blob موحّد + طابع زمني خادمي. */
export const ServerNotificationDB = {
    async getNotifications(userId: string): Promise<ForumNotification[]> {
        try {
            await cleanupLegacyForumPrefixServer(userId).catch(() => undefined);
            const models = await readNotificationBlobServer(userId);
            return extractForumNotificationsFromModels(models, userId);
        } catch {
            /* KV/Supabase غير متاح في التطوير — لا نكسر SSE */
            return [];
        }
    },

    async getUnreadCount(userId: string): Promise<number> {
        try {
            const rows = await this.getNotifications(userId);
            return rows.filter((n) => !n.read).length;
        } catch {
            return 0;
        }
    },

    async markAsRead(notificationId: string, userId: string): Promise<void> {
        const models = await readNotificationBlobServer(userId);
        const next = markForumReadInModels(models, userId, notificationId);
        await saveNotificationBlobServer(userId, next);
    },

    async markAllAsRead(userId: string): Promise<void> {
        const models = await readNotificationBlobServer(userId);
        const next = markAllForumReadInModels(models, userId);
        await saveNotificationBlobServer(userId, next);
    },

    async removeNotification(notificationId: string, userId: string): Promise<void> {
        const models = await readNotificationBlobServer(userId);
        const next = dismissForumNotificationInModels(models, userId, notificationId);
        await saveNotificationBlobServer(userId, next);
    },

    async addNotification(notif: ForumNotification): Promise<void> {
        const stamped = withServerTimestamp(notif);
        const models = await readNotificationBlobServer(stamped.userId);
        const next = upsertForumIntoModels(models, stamped);
        await saveNotificationBlobServer(stamped.userId, next);
        void import('@/app/services/notifications/fcm/fcmInboxDispatch.server').then((m) =>
            m.dispatchFcmForForumNotification(stamped),
        );
    },

    async updateNotification(
        userId: string,
        notificationId: string,
        patch: Partial<
            Pick<ForumNotification, 'title' | 'message' | 'read' | 'createdAt' | 'activityCount' | 'dedupeKey'>
        >,
    ): Promise<void> {
        const models = await readNotificationBlobServer(userId);
        const next = patchForumInModels(models, userId, notificationId, {
            ...patch,
            createdAt: patch.createdAt ?? new Date().toISOString(),
        });
        await saveNotificationBlobServer(userId, next);
    },

    async upsertModelsFromForum(notifs: ForumNotification[]): Promise<void> {
        if (notifs.length === 0) return;
        const userId = notifs[0]!.userId;
        const models = notifs.map(mapForumNotificationToModel);
        await upsertNotificationModelsServer(userId, models);
    },
};

import { NotificationRepository } from '@/app/infrastructure/NotificationRepository';
import type { ForumNotification } from '@/app/services/forum/forumTypes';
import { mapForumNotificationToModel } from '@/app/services/notifications/forumNotificationMapper';
import { useNotificationStore } from '@/app/stores/notificationStore';
import {
    dismissForumNotificationInModels,
    extractForumNotificationsFromModels,
    markAllForumReadInModels,
    markForumReadInModels,
    patchForumInModels,
    upsertForumIntoModels,
} from '@/app/services/notifications/notificationForumBlobOps';
import { migrateLegacyForumKvToBlobIfNeeded, retryLegacyPrefixCleanupIfPartial } from '@/app/services/notifications/notificationForumKvMigration';

async function loadBlobModels(userId: string) {
    await migrateLegacyForumKvToBlobIfNeeded(
        userId,
        () => NotificationRepository.fetchNotifications(userId),
        async (models) => {
            await NotificationRepository.saveNotifications(userId, models);
        },
    );
    await retryLegacyPrefixCleanupIfPartial(userId).catch(() => undefined);
    return NotificationRepository.fetchNotifications(userId);
}

async function saveBlobModels(userId: string, models: Awaited<ReturnType<typeof loadBlobModels>>) {
    await NotificationRepository.saveNotifications(userId, models);
}

function syncStoreUpsert(notif: ForumNotification): void {
    if (typeof window === 'undefined') return;
    useNotificationStore.getState().upsertNotification(mapForumNotificationToModel(notif));
}

function syncStoreRemove(notificationId: string): void {
    if (typeof window === 'undefined') return;
    useNotificationStore.getState().removeNotification(notificationId);
}

function syncStoreFromBlob(userId: string, models: Awaited<ReturnType<typeof loadBlobModels>>): void {
    if (typeof window === 'undefined') return;
    const forumModels = extractForumNotificationsFromModels(models, userId).map(mapForumNotificationToModel);
    if (forumModels.length === 0) return;
    useNotificationStore.getState().upsertNotifications(forumModels);
}

/**
 * NotificationDB — تخزين موحّد عبر blob `notifications_${userId}`.
 * per-item keys (`notifications:${userId}:${id}`) legacy — تُدمَج ثم تُحذَف.
 */
export const NotificationDB = {
    async addNotification(notif: ForumNotification): Promise<void> {
        const models = await loadBlobModels(notif.userId);
        const next = upsertForumIntoModels(models, notif);
        await saveBlobModels(notif.userId, next);
        syncStoreUpsert(notif);
    },

    async updateNotification(
        userId: string,
        notificationId: string,
        patch: Partial<
            Pick<ForumNotification, 'title' | 'message' | 'read' | 'createdAt' | 'activityCount' | 'dedupeKey'>
        >,
    ): Promise<void> {
        const models = await loadBlobModels(userId);
        const next = patchForumInModels(models, userId, notificationId, patch);
        await saveBlobModels(userId, next);
        const updated = extractForumNotificationsFromModels(next, userId).find((n) => n.id === notificationId);
        if (updated) syncStoreUpsert(updated);
    },

    async getNotifications(userId: string): Promise<ForumNotification[]> {
        const models = await loadBlobModels(userId);
        return extractForumNotificationsFromModels(models, userId);
    },

    async markAsRead(notificationId: string, userId: string): Promise<void> {
        const models = await loadBlobModels(userId);
        const next = markForumReadInModels(models, userId, notificationId);
        await saveBlobModels(userId, next);
        syncStoreFromBlob(userId, next);
    },

    async markAllAsRead(userId: string): Promise<void> {
        const models = await loadBlobModels(userId);
        const next = markAllForumReadInModels(models, userId);
        await saveBlobModels(userId, next);
        syncStoreFromBlob(userId, next);
    },

    async getUnreadCount(userId: string): Promise<number> {
        const notifs = await this.getNotifications(userId);
        return notifs.filter((n) => !n.read).length;
    },

    async removeNotification(notificationId: string, userId: string): Promise<void> {
        const models = await loadBlobModels(userId);
        const next = dismissForumNotificationInModels(models, userId, notificationId);
        await saveBlobModels(userId, next);
        syncStoreRemove(notificationId);
    },
};

/**
 * keepAlive الدافئ يُكلّف شجرة React كاملة في الخلفية.
 * على الهاتف الأصلي أو وضع التوفير نُبقي المقطع في الذاكرة فقط ونركّب الشجرة عند الفتح.
 */
export function shouldKeepNotificationHostWarm(): boolean {
    if (typeof document === 'undefined') return true;
    const root = document.documentElement.dataset;
    if (root.hamiLite === '1') return false;
    if (root.hamiNative === '1') return false;
    return true;
}

import type {
    NotificationCategory,
    NotificationModel,
    NotificationType,
} from '@/app/infrastructure/notificationModel';
import {
    sanitizeNotificationActionPayload,
    sanitizeNotificationEntityId,
} from '@/app/services/notifications/notificationNavigateSecurity';

export const MAX_NOTIFICATION_TITLE_LEN = 200;
export const MAX_NOTIFICATION_MESSAGE_LEN = 2000;
const MAX_NOTIFICATION_DEDUPE_KEY_LEN = 128;
export const MAX_OS_NOTIFY_QUERY_CHARS = 4_096;
const MAX_FCM_TOKEN_LEN = 4_096;
const MIN_FCM_TOKEN_LEN = 20;

const ALLOWED_TYPES = new Set<NotificationType>([
    'deadline',
    'system_alert',
    'ai_insight',
    'new_document',
    'audit_log_civil',
    'audit_log_criminal',
    'audit_log_execution',
    'audit_log_task',
    'forum_reply',
    'forum_mention',
    'forum_solved',
]);

const ALLOWED_CATEGORIES = new Set<NotificationCategory>([
    'civil',
    'criminal',
    'execution',
    'task',
    'forum',
    'system',
    'document',
    'ai',
]);

export function clampNotificationInboxText(raw: unknown, max: number): string {
    if (typeof raw !== 'string') return '';
    return raw.replace(/\u0000/g, '').trim().slice(0, max);
}

export function sanitizeNotificationDedupeKey(raw: unknown): string | undefined {
    const id = sanitizeNotificationEntityId(
        typeof raw === 'string' ? raw.trim().slice(0, MAX_NOTIFICATION_DEDUPE_KEY_LEN) : raw,
    );
    return id ?? undefined;
}

export function isAllowedFcmToken(token: string): boolean {
    if (token.length < MIN_FCM_TOKEN_LEN || token.length > MAX_FCM_TOKEN_LEN) return false;
    if (/[<>'"\s]/.test(token)) return false;
    return true;
}

function sanitizeCreatedAt(raw: unknown): string {
    if (typeof raw !== 'string') return new Date().toISOString();
    const t = Date.parse(raw.trim().slice(0, 40));
    if (!Number.isFinite(t)) return new Date().toISOString();
    return new Date(t).toISOString();
}

/**
 * يصفّر سجل صندوق للتخزين/الدمج: معرّف آمن، نصوص محدودة، حمولة تنقّل مُعقَّمة.
 * يُبقي مفاتيح خادم (dedupeKey / appendedBy / readSynced*) خارج قائمة التنقّل.
 */
export function sanitizeNotificationModelForPersist(
    notification: NotificationModel,
): NotificationModel | null {
    const id = sanitizeNotificationEntityId(notification.id);
    if (!id) return null;
    if (!ALLOWED_TYPES.has(notification.type)) return null;

    const title = clampNotificationInboxText(notification.title, MAX_NOTIFICATION_TITLE_LEN);
    const message = clampNotificationInboxText(notification.message, MAX_NOTIFICATION_MESSAGE_LEN);
    if (!title || !message) return null;

    const category =
        notification.category && ALLOWED_CATEGORIES.has(notification.category)
            ? notification.category
            : undefined;
    const direction =
        notification.direction === 'outgoing' || notification.direction === 'incoming'
            ? notification.direction
            : undefined;

    const rawPayload =
        notification.actionPayload && typeof notification.actionPayload === 'object'
            ? notification.actionPayload
            : {};
    const nav = sanitizeNotificationActionPayload(rawPayload);
    const dedupeKey = sanitizeNotificationDedupeKey(rawPayload.dedupeKey);
    const appendedBy = rawPayload.appendedBy === 'server' ? 'server' : undefined;
    const readSyncedBy = rawPayload.readSyncedBy === 'server' ? 'server' : undefined;
    const readSyncedAt =
        typeof rawPayload.readSyncedAt === 'string' ? sanitizeCreatedAt(rawPayload.readSyncedAt) : undefined;

    const actionPayload: Record<string, unknown> = { ...nav };
    if (dedupeKey) actionPayload.dedupeKey = dedupeKey;
    if (appendedBy) actionPayload.appendedBy = appendedBy;
    if (readSyncedBy) actionPayload.readSyncedBy = readSyncedBy;
    if (readSyncedAt) actionPayload.readSyncedAt = readSyncedAt;

    return {
        id,
        title,
        message,
        type: notification.type,
        ...(category ? { category } : {}),
        ...(direction ? { direction } : {}),
        isRead: notification.isRead === true,
        actionPayload,
        createdAt: sanitizeCreatedAt(notification.createdAt),
    };
}

import SecureStoreService from '@/app/services/SecureStoreService';
import {
    clearLegacyPlaintextMirror,
    readSecureOrDrainLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';
import { NotificationRepository } from '@/app/infrastructure/NotificationRepository';
import {
    isActivityLogNotification,
    type NotificationModel,
} from '@/app/infrastructure/NotificationRepository';
import { isIncomingNotification } from '@/app/services/notificationIncomingFilter';
import { isNavigationNoiseNotification } from '@/app/services/notificationMessageFormat';

export const NOTIFICATION_LEGACY_PURGE_VERSION = 'v1';

const PURGE_FLAG_PREFIX = 'hami:notifications:legacy-purged:';

function purgeFlagKey(userId: string): string {
    return `${PURGE_FLAG_PREFIX}${userId}:${NOTIFICATION_LEGACY_PURGE_VERSION}`;
}

function stripLegacyActivityNotifications(list: NotificationModel[]): NotificationModel[] {
    return list.filter((n) => !isActivityLogNotification(n));
}

function stripNonIncomingNotifications(list: NotificationModel[]): NotificationModel[] {
    return list.filter(
        (n) => isIncomingNotification(n) && !isNavigationNoiseNotification(n),
    );
}

/** تنظيف blob KV من audit_log/deadline — مرة واحدة لكل مستخدم. */
export async function purgeLegacyNotificationsIfNeeded(userId: string): Promise<boolean> {
    if (!userId) return false;

    try {
        if (readSecureOrDrainLegacySync(purgeFlagKey(userId)) === '1') {
            return false;
        }
    } catch {
        /* continue */
    }

    const raw = await NotificationRepository.fetchNotifications(userId);
    const withoutLegacy = stripLegacyActivityNotifications(raw);
    const cleaned = stripNonIncomingNotifications(withoutLegacy);

    if (cleaned.length !== raw.length) {
        await NotificationRepository.replaceAllNotifications(userId, cleaned);
    }

    try {
        SecureStoreService.setItemSync(purgeFlagKey(userId), '1');
        clearLegacyPlaintextMirror(purgeFlagKey(userId));
    } catch {
        /* ignore */
    }

    return cleaned.length !== raw.length;
}

import type { NotificationModel } from '@/app/infrastructure/notificationModel';

/** سقف موحّد لقائمة الإشعارات (محلي + KV blob). */
export const NOTIFICATION_LIST_CAP = 400;

function isServerAppendedNotification(n: NotificationModel): boolean {
    const payload = n.actionPayload && typeof n.actionPayload === 'object' ? n.actionPayload : {};
    return payload.appendedBy === 'server';
}

/**
 * يُبقي تنبيهات المقر (appendedBy=server) داخل السقف حتى لو كانت في ذيل القائمة.
 * إن زاد عددها عن السقف تُحفظ الأحدث حسب ترتيب القائمة.
 */
export function capNotificationList(list: NotificationModel[]): NotificationModel[] {
    if (list.length <= NOTIFICATION_LIST_CAP) return list;

    const protectedCount = Math.min(
        list.reduce((n, item) => n + (isServerAppendedNotification(item) ? 1 : 0), 0),
        NOTIFICATION_LIST_CAP,
    );
    const otherBudget = NOTIFICATION_LIST_CAP - protectedCount;
    const out: NotificationModel[] = [];
    let protectedTaken = 0;
    let otherTaken = 0;
    for (const item of list) {
        if (isServerAppendedNotification(item)) {
            if (protectedTaken < protectedCount) {
                out.push(item);
                protectedTaken += 1;
            }
        } else if (otherTaken < otherBudget) {
            out.push(item);
            otherTaken += 1;
        }
        if (protectedTaken >= protectedCount && otherTaken >= otherBudget) break;
    }
    return out;
}

import SecureStoreService from '@/app/services/SecureStoreService';
import { useNotificationStore } from '@/app/stores/notificationStore';
import {
    FORUM_KV_UNIFIED_MIGRATION_VERSION,
} from '@/app/services/notifications/notificationForumKvMigration';
import { NOTIFICATION_LEGACY_PURGE_VERSION } from '@/app/services/notifications/notificationLegacyMigration';

const LOCAL_BLOB_PREFIX = 'hami:notifications:v1:';
const LEGACY_GLOBAL_FORUM = 'hami:notifications:v1';

function migrationFlagKey(userId: string): string {
    return `hami:notifications:kv-unified:${userId}:${FORUM_KV_UNIFIED_MIGRATION_VERSION}`;
}

function mergedIdsKey(userId: string): string {
    return `hami:notifications:kv-unified:merged-ids:${userId}:${FORUM_KV_UNIFIED_MIGRATION_VERSION}`;
}

function legacyPurgeKey(userId: string): string {
    return `hami:notifications:legacy-purged:${userId}:${NOTIFICATION_LEGACY_PURGE_VERSION}`;
}

/** مسح cache محلي للإشعارات (SecureStore) — أثناء wipe. */
export function clearLocalNotificationCache(userId: string | null): void {
    const keys = [
        LEGACY_GLOBAL_FORUM,
        ...(userId
            ? [
                  `${LOCAL_BLOB_PREFIX}${userId}`,
                  migrationFlagKey(userId),
                  mergedIdsKey(userId),
                  legacyPurgeKey(userId),
              ]
            : []),
    ];

    for (const key of keys) {
        try {
            SecureStoreService.deleteItemSync(key);
        } catch {
            /* ignore */
        }
    }
}

/** إعادة ضبط Zustand store للجرس. */
export async function resetNotificationStoreAfterWipe(): Promise<void> {
    if (typeof window === 'undefined') return;
    useNotificationStore.getState().setUserId(null);
}

import type { NotificationModel } from '@/app/infrastructure/NotificationRepository';
import { capNotificationList } from '@/app/services/notifications/notificationLimits';

function parseCreatedAt(value: string): number {
    const t = Date.parse(value);
    return Number.isFinite(t) ? t : 0;
}

function payloadOf(n: NotificationModel): Record<string, unknown> {
    return n.actionPayload && typeof n.actionPayload === 'object' ? n.actionPayload : {};
}

/** سجل خادمي — يفوز على نسخة العميل عند التعارض (ما عدا isRead أحادي). */
export function isServerAppendedNotification(n: NotificationModel): boolean {
    return payloadOf(n).appendedBy === 'server';
}

function shallowEqualPayload(a?: Record<string, unknown>, b?: Record<string, unknown>): boolean {
    if (a === b) return true;
    const av = a ?? {};
    const bv = b ?? {};
    const aKeys = Object.keys(av);
    if (aKeys.length !== Object.keys(bv).length) return false;
    return aKeys.every((k) => Object.is(av[k], bv[k]));
}

/** يقارن محتوى سجلّين — يُستخدم لتفادي إنشاء مرجع جديد عند غياب أي تغيير فعلي. */
function isSameNotificationContent(x: NotificationModel, y: NotificationModel): boolean {
    return (
        x.id === y.id &&
        x.title === y.title &&
        x.message === y.message &&
        x.type === y.type &&
        x.category === y.category &&
        x.direction === y.direction &&
        x.isRead === y.isRead &&
        x.createdAt === y.createdAt &&
        shallowEqualPayload(x.actionPayload, y.actionPayload)
    );
}

/**
 * دمج إشعارين بنفس المعرّف — isRead أحادي (true يفوز)، الخادم يفوز على المحتوى عند التعارض.
 * يُعيد نفس مرجع `a` حرفياً عندما لا يُحدث الدمج أي تغيير فعلي — ضروري لاستقرار مراجع
 * notifications في الـ store ومنع إعادة رندر لا نهائية عند إعادة مزامنة بيانات مطابقة
 * (مثال: منتدى ↔ لوحة الجرس عبر syncForumNotificationsToAppStore على كل نبضة مزامنة).
 */
export function mergeNotificationRecord(
    a: NotificationModel,
    b: NotificationModel,
): NotificationModel {
    const aServer = isServerAppendedNotification(a);
    const bServer = isServerAppendedNotification(b);

    let merged: NotificationModel;
    if (aServer && !bServer) {
        merged = {
            ...a,
            isRead: a.isRead || b.isRead,
            actionPayload: { ...payloadOf(b), ...payloadOf(a) },
        };
    } else if (bServer && !aServer) {
        merged = {
            ...b,
            isRead: a.isRead || b.isRead,
            actionPayload: { ...payloadOf(a), ...payloadOf(b) },
        };
    } else {
        const aTime = parseCreatedAt(a.createdAt);
        const bTime = parseCreatedAt(b.createdAt);
        const newer = bTime >= aTime ? b : a;
        const older = bTime >= aTime ? a : b;

        merged = {
            ...newer,
            title: newer.title || older.title,
            message: newer.message || older.message,
            isRead: a.isRead || b.isRead,
            actionPayload: { ...payloadOf(older), ...payloadOf(newer) },
        };
    }

    return isSameNotificationContent(merged, a) ? a : merged;
}

/** مساواة سطحية بالمرجع لقائمتين مُرتّبتين — صحيحة طالما عناصر القوائم تحافظ على ثبات مرجعي عند غياب التغيير. */
export function notificationListsReferenceEqual(
    x: NotificationModel[],
    y: NotificationModel[],
): boolean {
    if (x === y) return true;
    if (x.length !== y.length) return false;
    return x.every((item, i) => item === y[i]);
}

/**
 * مساواة بالمحتوى لقائمتين مُرتّبتين — لطبقات لا تملك ثبات مرجع بين نداءين
 * (`NotificationRepository.loadLocal` يُعيد `JSON.parse` جديداً كل مرّة، فلا
 * ثبات مرجعي ممكن حتى مع محتوى مطابق حرفياً). `notificationListsReferenceEqual`
 * تُخطئ دائماً هنا؛ هذه تفحص القيم فعلاً — أغلى قليلاً، لكنها الصحيحة عند
 * غياب سلسلة مرجعية بين النداءين.
 */
export function notificationListsContentEqual(
    x: NotificationModel[],
    y: NotificationModel[],
): boolean {
    if (x === y) return true;
    if (x.length !== y.length) return false;
    return x.every((item, i) => isSameNotificationContent(item, y[i]));
}

/** اتحاد قوائم — لا last-write-wins على isRead. */
export function mergeNotificationLists(...lists: NotificationModel[][]): NotificationModel[] {
    const byId = new Map<string, NotificationModel>();

    for (const list of lists) {
        for (const item of list) {
            const existing = byId.get(item.id);
            byId.set(item.id, existing ? mergeNotificationRecord(existing, item) : item);
        }
    }

    return Array.from(byId.values()).sort(
        (x, y) => parseCreatedAt(y.createdAt) - parseCreatedAt(x.createdAt),
    );
}

export function capMergedNotificationLists(...lists: NotificationModel[][]): NotificationModel[] {
    return capNotificationList(mergeNotificationLists(...lists));
}

/** مسارات التنقّل المسموحة من إشعار */
const NOTIFICATION_NAV_TARGETS = [
    'community',
    'vault',
    'scan_document',
    'schedule',
    'case_details',
    'execution_home',
    'lawsuit_home',
] as const;

export type NotificationNavTarget = (typeof NOTIFICATION_NAV_TARGETS)[number];

const ALLOWED_PAYLOAD_KEYS = new Set([
    'postId',
    'questionId',
    'fileId',
    'tab',
    'commentId',
    'threadId',
    'caseId',
    'caseNo',
    'notificationId',
    'type',
    'forumType',
    /** تذكير تقويم أصلي — يفتح الموعد مباشرة بعد نقر إشعار النظام */
    'eventId',
    'date',
]);

const DANGEROUS_KEYS = new Set(['__proto__', 'constructor', 'prototype']);

const SERVER_PAYLOAD_META_KEYS = new Set(['dedupeKey', 'appendedBy', 'readSyncedBy', 'readSyncedAt']);

const MAX_PAYLOAD_STRING_LEN = 128;

/** أحرف تكسر مُحدِّد CSS / HTML أو تُدخل مخططاً خطيراً */
const UNSAFE_ID_CHARS = /[<>'"[\]\u0000-\u001F\u007F]/;
const SCHEME_ID = /^(javascript|data|vbscript):/i;

export function isNotificationNavTarget(path: string): path is NotificationNavTarget {
    return (NOTIFICATION_NAV_TARGETS as readonly string[]).includes(path);
}

/**
 * معرّف تنقّل/تركيز آمن — يرفض javascript: وعلامات HTML وأقواس المُحدِّد.
 * يسمح بالعربية والشرطة المائلة (رقم إضبارة مثل 1/ك/2024).
 */
export function sanitizeNotificationEntityId(raw: unknown): string | null {
    if (raw == null) return null;
    const id = String(raw).trim();
    if (!id || id.length > MAX_PAYLOAD_STRING_LEN) return null;
    if (UNSAFE_ID_CHARS.test(id) || SCHEME_ID.test(id)) return null;
    return id;
}

export function sanitizeNotificationFocusId(raw: unknown): string | null {
    return sanitizeNotificationEntityId(raw);
}

export function sanitizeNotificationCalendarDate(raw: unknown): string | null {
    const s = String(raw ?? '').trim();
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
    if (!m) return null;
    const year = Number(m[1]);
    const month = Number(m[2]);
    const day = Number(m[3]);
    const dt = new Date(Date.UTC(year, month - 1, day));
    if (dt.getUTCFullYear() !== year || dt.getUTCMonth() !== month - 1 || dt.getUTCDate() !== day) {
        return null;
    }
    return s;
}

function sanitizePayloadValue(key: string, value: unknown): string | null {
    if (typeof value === 'number' && Number.isFinite(value)) {
        return sanitizeNotificationEntityId(String(value));
    }
    if (typeof value !== 'string') return null;
    if (key === 'date') return sanitizeNotificationCalendarDate(value);
    return sanitizeNotificationEntityId(value);
}

export function sanitizeNotificationActionPayload(
    payload: Record<string, unknown> | null | undefined,
): Record<string, unknown> {
    if (!payload || typeof payload !== 'object' || Array.isArray(payload)) return {};
    const out: Record<string, unknown> = {};
    for (const [key, value] of Object.entries(payload)) {
        if (DANGEROUS_KEYS.has(key) || !ALLOWED_PAYLOAD_KEYS.has(key)) continue;
        const next = sanitizePayloadValue(key, value);
        if (next) out[key] = next;
    }
    return out;
}

/**
 * يُبقي مفاتيح الخادم (dedupeKey / appendedBy) ويصفّر مفاتيح التنقّل فقط.
 */
export function mergeSanitizedNotificationActionPayload(
    payload: Record<string, unknown> | null | undefined,
): Record<string, unknown> {
    const src =
        payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : {};
    const out: Record<string, unknown> = { ...sanitizeNotificationActionPayload(src) };
    const dedupe = sanitizeNotificationEntityId(src.dedupeKey);
    if (dedupe) out.dedupeKey = dedupe;
    if (src.appendedBy === 'server') out.appendedBy = 'server';
    if (src.readSyncedBy === 'server') out.readSyncedBy = 'server';
    if (typeof src.readSyncedAt === 'string') {
        const t = Date.parse(src.readSyncedAt.trim().slice(0, 40));
        if (Number.isFinite(t)) out.readSyncedAt = new Date(t).toISOString();
    }
    for (const key of Object.keys(out)) {
        if (DANGEROUS_KEYS.has(key)) delete out[key];
    }
    void SERVER_PAYLOAD_META_KEYS;
    return out;
}

