import {
    sanitizeNotificationFocusId,
    type NotificationNavTarget,
} from '@/app/services/notifications/notificationNavigateSecurity';
import { MAX_OS_NOTIFY_QUERY_CHARS } from '@/app/services/notifications/notificationInboxSanitize';

export type OsNotificationTapIntent = {
    path: NotificationNavTarget;
    payload: Record<string, unknown>;
};

export type OsNotificationTapResolution = {
    navigate: OsNotificationTapIntent | null;
    openPanel: boolean;
    focusNotificationId: string | null;
};

export function asOsTapRecord(value: unknown): Record<string, unknown> | null {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
    return value as Record<string, unknown>;
}

/** يستخرج حمولة التوجيه من أشكال Capacitor/Web/SW المختلفة. */
export function extractOsNotificationTapData(detail: unknown): Record<string, unknown> {
    const root = asOsTapRecord(detail);
    if (!root) return {};

    const nestedExtra = asOsTapRecord(root.extra);
    if (nestedExtra && Object.keys(nestedExtra).length > 0) return nestedExtra;

    const nestedData = asOsTapRecord(root.data);
    if (nestedData && Object.keys(nestedData).length > 0) return nestedData;

    return root;
}

/** معرّف إشعار الصندوق — نص فقط (لا id الرقمي الأصلي لـ Capacitor). */
export function extractOsNotificationFocusId(raw: Record<string, unknown>): string | null {
    for (const key of ['notificationId', 'shellNotificationId'] as const) {
        const id = sanitizeNotificationFocusId(raw[key]);
        if (id) return id;
    }
    if (typeof raw.id === 'string') {
        return sanitizeNotificationFocusId(raw.id);
    }
    return null;
}

export function decodeOsNotifyQueryPayload(raw: string | null | undefined): unknown {
    if (!raw?.trim() || raw.length > MAX_OS_NOTIFY_QUERY_CHARS) return null;
    try {
        const decoded = decodeURIComponent(raw);
        if (decoded.length > MAX_OS_NOTIFY_QUERY_CHARS) return null;
        const parsed: unknown = JSON.parse(decoded);
        if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return null;
        return parsed;
    } catch {
        return null;
    }
}

import {
    isNotificationNavTarget,
    sanitizeNotificationActionPayload,
} from '@/app/services/notifications/notificationNavigateSecurity';
import { stashNotificationPanelFocusId } from '@/app/services/notifications/notificationPanelFocus';
import { HAMI_OS_NOTIFICATION_OPEN_PANEL_EVENT } from '@/app/services/notifications/notificationOsTapEvents';
import {
    extractOsNotificationFocusId,
    extractOsNotificationTapData,
    type OsNotificationTapIntent,
    type OsNotificationTapResolution,
} from '@/app/services/notifications/osTap/notificationOsTapExtract';

export type { OsNotificationTapIntent, OsNotificationTapResolution };

/**
 * يحوّل حمولة إشعار نظام التشغيل إلى مسار تنقّل مسموح + حمولة مُعقَّمة.
 */
export function resolveOsNotificationTapIntent(detail: unknown): OsNotificationTapIntent | null {
    const raw = extractOsNotificationTapData(detail);
    const type = typeof raw.type === 'string' ? raw.type.trim() : '';

    if (type === 'calendar-reminder' || type === 'calendar_reminder') {
        const payload = sanitizeNotificationActionPayload({
            eventId: raw.eventId,
            date: raw.date,
        });
        return { path: 'schedule', payload };
    }

    const explicitPath = typeof raw.path === 'string' ? raw.path.trim() : '';
    if (explicitPath === 'notifications') {
        return null;
    }
    if (explicitPath && isNotificationNavTarget(explicitPath)) {
        return {
            path: explicitPath,
            payload: sanitizeNotificationActionPayload(raw),
        };
    }

    const category = typeof raw.category === 'string' ? raw.category.trim() : '';
    if (
        category === 'forum' ||
        type === 'forum' ||
        type.startsWith('forum_') ||
        (typeof raw.forumType === 'string' && raw.forumType.trim())
    ) {
        return {
            path: 'community',
            payload: sanitizeNotificationActionPayload(raw),
        };
    }
    if (category === 'document' || type === 'new_document') {
        return {
            path: 'vault',
            payload: sanitizeNotificationActionPayload(raw),
        };
    }
    if ((category === 'ai' || type === 'ai_insight') && typeof raw.caseId === 'string' && raw.caseId.trim()) {
        return {
            path: 'case_details',
            payload: sanitizeNotificationActionPayload(raw),
        };
    }
    if (type === 'execution' || category === 'execution') {
        const caseId = typeof raw.caseId === 'string' ? raw.caseId.trim() : '';
        if (caseId) {
            return { path: 'case_details', payload: sanitizeNotificationActionPayload(raw) };
        }
        return {
            path: 'execution_home',
            payload: sanitizeNotificationActionPayload(raw),
        };
    }
    if (type === 'lawsuit' || category === 'civil' || category === 'criminal') {
        const caseId = typeof raw.caseId === 'string' ? raw.caseId.trim() : '';
        if (caseId) {
            return { path: 'case_details', payload: sanitizeNotificationActionPayload(raw) };
        }
        return {
            path: 'lawsuit_home',
            payload: sanitizeNotificationActionPayload(raw),
        };
    }

    return null;
}

/**
 * قرار موحّد: تنقّل ميزة و/أو فتح لوحة الإشعارات مع تركيز البطاقة.
 */
export function resolveOsNotificationTap(detail: unknown): OsNotificationTapResolution {
    const raw = extractOsNotificationTapData(detail);
    const focusNotificationId = extractOsNotificationFocusId(raw);
    const type = typeof raw.type === 'string' ? raw.type.trim() : '';
    const explicitPath = typeof raw.path === 'string' ? raw.path.trim() : '';
    const navigate = resolveOsNotificationTapIntent(detail);

    const explicitPanel =
        explicitPath === 'notifications' ||
        raw.openPanel === true ||
        raw.openPanel === 1 ||
        raw.openPanel === '1' ||
        raw.openPanel === 'true';

    const isPreview = type === 'os-preview';
    const hasMeaningfulPayload = Object.keys(raw).length > 0;

    const openPanel =
        !isPreview &&
        (explicitPanel || (!navigate && hasMeaningfulPayload) || Boolean(focusNotificationId && !navigate));

    return {
        navigate: explicitPanel ? null : navigate,
        openPanel,
        focusNotificationId,
    };
}

export function dispatchOsNotificationOpenPanel(focusNotificationId: string | null): void {
    if (typeof window === 'undefined') return;
    if (focusNotificationId) {
        stashNotificationPanelFocusId(focusNotificationId);
    }
    window.dispatchEvent(
        new CustomEvent(HAMI_OS_NOTIFICATION_OPEN_PANEL_EVENT, {
            detail: { notificationId: focusNotificationId },
        }),
    );
}

import {
    isNotificationNavTarget,
    sanitizeNotificationActionPayload,
    sanitizeNotificationFocusId,
} from '@/app/services/notifications/notificationNavigateSecurity';
import { HAMI_OS_NOTIFY_PENDING_KEY } from '@/app/services/notifications/notificationOsTapEvents';
import {
    asOsTapRecord,
    type OsNotificationTapIntent,
    type OsNotificationTapResolution,
} from '@/app/services/notifications/osTap/notificationOsTapExtract';
import { resolveOsNotificationTap } from '@/app/services/notifications/osTap/notificationOsTapIntent';

export function stashPendingOsNotifyIntent(detail: unknown): void {
    if (typeof sessionStorage === 'undefined') return;
    try {
        const resolution = resolveOsNotificationTap(detail);
        if (!resolution.navigate && !resolution.openPanel) return;
        sessionStorage.setItem(
            HAMI_OS_NOTIFY_PENDING_KEY,
            JSON.stringify({
                v: 2,
                navigate: resolution.navigate,
                openPanel: resolution.openPanel,
                focusNotificationId: resolution.focusNotificationId,
            }),
        );
    } catch {
        /* ignore quota / private mode */
    }
}

export function consumePendingOsNotifyResolution(): OsNotificationTapResolution | null {
    if (typeof sessionStorage === 'undefined') return null;
    try {
        const raw = sessionStorage.getItem(HAMI_OS_NOTIFY_PENDING_KEY);
        if (!raw) return null;
        sessionStorage.removeItem(HAMI_OS_NOTIFY_PENDING_KEY);
        const parsed = JSON.parse(raw) as Record<string, unknown>;

        if (parsed?.v === 2) {
            const navigateRecord = asOsTapRecord(parsed.navigate);
            const path = typeof navigateRecord?.path === 'string' ? navigateRecord.path : '';
            const navigate =
                path && isNotificationNavTarget(path)
                    ? {
                          path,
                          payload: sanitizeNotificationActionPayload(
                              asOsTapRecord(navigateRecord?.payload) ?? {},
                          ),
                      }
                    : null;
            const focus = sanitizeNotificationFocusId(parsed.focusNotificationId);
            return {
                navigate,
                openPanel: parsed.openPanel === true,
                focusNotificationId: focus,
            };
        }

        const legacy = parsed as Partial<OsNotificationTapIntent>;
        if (!legacy?.path || !isNotificationNavTarget(legacy.path)) return null;
        return {
            navigate: {
                path: legacy.path,
                payload: sanitizeNotificationActionPayload(asOsTapRecord(legacy.payload) ?? {}),
            },
            openPanel: false,
            focusNotificationId: null,
        };
    } catch {
        return null;
    }
}

/** توافق الاختبارات القديمة */
export function consumePendingOsNotifyIntent(): OsNotificationTapIntent | null {
    const resolution = consumePendingOsNotifyResolution();
    return resolution?.navigate ?? null;
}

/**
 * فشل التثبيت على القرص — أخطر صمت في طبقة التخزين.
 *
 * `webDbSetItem` كانت تعود صامتة في كل مسار فشل: القاعدة محجوبة، أو الحصّة
 * ممتلئة (`QuotaExceededError`)، أو المعاملة أُجهضت. و`setItem` تُرجع `void`، فلا
 * سبيل للمتصل أن يعرف. والذاكرة (`webFallbackStore`) تحتفظ بالقيمة فتبدو الجلسة
 * سليمة تماماً: الواجهة تُظهر «حُفِظ»، والقراءة اللاحقة تُرجع ما كُتب.
 *
 * ثم يُقلع المحامي في الغد فلا يجد شيئاً. لا سطر في سجلّ، ولا بلاغ في لوحة، ولا
 * أثر يدلّ على أن الكتابة لم تبلغ القرص قطّ. وهذا أسوأ من عطل ظاهر: العطل الظاهر
 * يُوقف العمل قبل أن يُبنى عليه، والصمت يدع المحامي يبني يومه على وعدٍ كاذب.
 *
 * لا تغيير في الواجهة هنا — القاعدة الذهبية تمنعه بلا إذن. لكن الحالة تُسجَّل
 * وتُصبح مقروءة، فمن أراد إظهارها لاحقاً وجدها جاهزة.
 */
const reportedKeys = new Set<string>();

export type PersistenceFailureReason =
    /** `indexedDB.open` لم يُرجع قاعدة — محجوبة أو غير مدعومة */
    | 'db-unavailable'
    /** المعاملة أُجهضت أو أخطأت — الحصّة الممتلئة أشهر أسبابها */
    | 'transaction-failed'
    /** فشل التشفير أو setItem بعد أن بدت الذاكرة «محفوظة» */
    | 'encrypt-or-write-failed';

let lastFailure: { key: string; reason: PersistenceFailureReason; at: number } | null = null;
let failureCount = 0;

export function signalPersistenceFailure(
    key: string,
    reason: PersistenceFailureReason,
    detail?: string,
): void {
    failureCount += 1;
    lastFailure = { key, reason, at: Date.now() };

    /* بلاغ واحد لكل مفتاح: الحصّة الممتلئة تُفشل كل كتابة، فالتبليغ بلا حدٍّ يغرق الرصد */
    if (reportedKeys.has(key)) return;
    reportedKeys.add(key);

    /*
     * استيراد ديناميّ: هذه السلسلة تُقلع مع المخزن، وربط عميل الرصد بها ثابتاً
     * يجرّه إلى مسار الإقلاع لأجل بلاغ لا يقع إلا عند عطل.
     */
    void import('@/app/observability/sentryClient')
        .then((m) =>
            m.sentryCaptureMessage(`storage-persist-failed: ${reason}`, {
                storageKey: key,
                reason,
                detail: detail ?? '',
                failureCount,
            }),
        )
        .catch(() => {
            /* فشل التبليغ لا يجوز أن يمسّ الكتابة */
        });
}

/** هل تعذّر التثبيت في هذه الجلسة؟ يقرأها من أراد إظهار الحال أو منع عملٍ مُدمِّر */
export function hasPersistenceFailed(): boolean {
    return failureCount > 0;
}

export function getLastPersistenceFailure(): {
    key: string;
    reason: PersistenceFailureReason;
    at: number;
} | null {
    return lastFailure;
}

export function __resetPersistenceFailureSignalForTests(): void {
    reportedKeys.clear();
    lastFailure = null;
    failureCount = 0;
}

/**
 * حمولة حسّاسة سقط عنها التشفير لتجاوزها حدّ الحجم — إشارة واحدة لكل مفتاح.
 *
 * `shouldEncryptValue` تعود `false` فوق الحدّ، فتُكتب أثقل الإضابير نصّاً صريحاً
 * على القرص. القرار مقصود (قرّاء `getItemSync` لا يفكّون تشفيراً) لكنّه كان
 * **صامتاً**: لا سبيل لمعرفة أي مفتاح يقع فيه، ولا بأي حجم، ولا على كم جهاز.
 *
 * والقياس شرط القرار: رفع الحدّ بلا معرفةِ ما يقع فوقه تخمينٌ، وإبقاؤه بلا معرفةٍ
 * إهمال. فتُسجَّل الواقعة مرّة لكل مفتاح — لا في كل كتابة كي لا يصير البلاغ ضجيجاً.
 *
 * مفاتيح الدعاوى المُسخَّنة (بما فيها `lawyer_files_archived|trash`) لا تصل هنا
 * أصلاً (`isLawsuitEncryptAlwaysKey`) — تُسخَّن عند فتح مساحة الدعاوى.
 */
import { isLawsuitLegalStorageKey } from './secureStorageKeys';

const reportedKeys = new Set<string>();

export function signalPlaintextFallback(key: string, valueLength: number, limit: number): void {
    if (reportedKeys.has(key)) return;
    reportedKeys.add(key);

    const overBy = valueLength - limit;
    if (import.meta.env.DEV) {
        const lawsuitTag = isLawsuitLegalStorageKey(key) ? ' [lawsuit]' : '';
        console.warn(
            `[SecureStore] plaintext size-fallback${lawsuitTag}: key=${key} len=${valueLength} limit=${limit} overBy=${overBy}`,
        );
    }

    /* استيراد ديناميّ — عميل الرصد لا يُجرّ إلى مسار المخزن لأجل بلاغ نادر */
    void import('@/app/observability/sentryClient')
        .then((m) =>
            m.sentryCaptureMessage(`storage-plaintext-fallback: ${key}`, {
                storageKey: key,
                valueLength,
                limit,
                overBy,
                lawsuitLegal: isLawsuitLegalStorageKey(key),
            }),
        )
        .catch(() => {
            /* فشل التبليغ لا يمسّ الكتابة */
        });
}

export function __resetPlaintextFallbackSignalForTests(): void {
    reportedKeys.clear();
}

