/**
 * اهتزاز الجهاز — Capacitor Haptics على الهاتف، و navigator.vibrate على الويب/WebView.
 * iOS لا يدعم navigator.vibrate؛ بدون الملحق لا يُحسّ الاهتزاز داخل التطبيق.
 */
import { getCapacitorPlatformId, isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';

/** نمط وصول إشعار داخل التطبيق — أقصر من منبّه التقويم وأوضح من نقرة واحدة */
export const HAMI_NOTIFICATION_VIBRATE_PATTERN = [80, 50, 140, 60, 220] as const;

/** نمط إشعار نظام التشغيل (ويب Notification / قناة أندرويد) */
export const HAMI_OS_NOTIFICATION_VIBRATE_PATTERN = [180, 90, 180, 90, 320] as const;

/** منبّه المواعيد — أطول ليُميَّز عن وصول إشعار */
export const HAMI_LEGAL_ALARM_VIBRATE_PATTERN = [180, 90, 180, 90, 320, 120, 420] as const;

function sleep(ms: number): Promise<void> {
    return new Promise((resolve) => {
        window.setTimeout(resolve, ms);
    });
}

function playWebVibrate(pattern: readonly number[]): void {
    if (typeof navigator === 'undefined' || typeof navigator.vibrate !== 'function') return;
    try {
        navigator.vibrate([...pattern]);
    } catch {
        /* ignore */
    }
}

async function playNativeHapticPattern(pattern: readonly number[]): Promise<boolean> {
    if (typeof window === 'undefined' || !isCapacitorNativePlatform()) return false;
    try {
        const { Capacitor } = await import('@capacitor/core');
        if (!Capacitor.isPluginAvailable('Haptics')) return false;
        const spec = '@capacitor/haptics';
        const { Haptics, NotificationType } = (await import(/* @vite-ignore */ spec)) as {
            Haptics: {
                notification: (options: { type: string }) => Promise<void>;
                vibrate: (options: { duration: number }) => Promise<void>;
            };
            NotificationType: { Warning: string };
        };
        if (getCapacitorPlatformId() === 'ios') {
            await Haptics.notification({ type: NotificationType.Warning });
            return true;
        }
        void (async () => {
            for (let i = 0; i < pattern.length; i += 1) {
                const ms = pattern[i];
                if (i % 2 === 0) {
                    await Haptics.vibrate({ duration: Math.max(1, ms) });
                } else {
                    await sleep(ms);
                }
            }
        })();
        return true;
    } catch {
        return false;
    }
}

/**
 * لا يرمي. على الويب يُنفَّذ فوراً. على الأصل يفضّل الملحق ثم يسقط إلى Vibration API.
 */
export function playDeviceHaptic(
    pattern: readonly number[] = HAMI_NOTIFICATION_VIBRATE_PATTERN,
): void {
    if (isCapacitorNativePlatform()) {
        void playNativeHapticPattern(pattern).then((ok) => {
            if (!ok) playWebVibrate(pattern);
        });
        return;
    }
    playWebVibrate(pattern);
}

import { whenNativeBridgeReady } from '@/app/runtime/nativeBridgeReady';
import { isCapacitorNativePlatform } from '@/app/runtime/nativePlatform';

export type ExportTextFileResult = 'shared' | 'downloaded' | 'cancelled' | 'failed';

function isAbortError(err: unknown): boolean {
    return err instanceof Error && err.name === 'AbortError';
}

async function tryWebShareFile(filename: string, content: string, mimeType: string): Promise<ExportTextFileResult | null> {
    if (typeof navigator === 'undefined' || typeof File === 'undefined') return null;
    const file = new File([content], filename, { type: mimeType });
    if (!navigator.canShare?.({ files: [file] })) return null;
    try {
        await navigator.share({ files: [file], title: filename });
        return 'shared';
    } catch (err) {
        if (isAbortError(err)) return 'cancelled';
        return null;
    }
}

async function tryCapacitorShareFile(
    filename: string,
    content: string,
    dialogTitle: string,
): Promise<ExportTextFileResult | null> {
    if (!isCapacitorNativePlatform()) return null;

    try {
        await whenNativeBridgeReady();
        const { Capacitor } = await import('@capacitor/core');
        if (!Capacitor.isPluginAvailable('Filesystem') || !Capacitor.isPluginAvailable('Share')) {
            return null;
        }

        const { Filesystem, Directory, Encoding } = await import('@capacitor/filesystem');
        const { Share } = await import('@capacitor/share');
        const safeName = filename.replace(/[^\w.\-]+/g, '_');
        const path = `hami-export/${Date.now()}-${safeName}`;

        await Filesystem.writeFile({
            path,
            data: content,
            directory: Directory.Cache,
            encoding: Encoding.UTF8,
            recursive: true,
        });

        const { uri } = await Filesystem.getUri({
            directory: Directory.Cache,
            path,
        });

        await Share.share({
            title: filename,
            files: [uri],
            dialogTitle,
        });
        return 'shared';
    } catch (err) {
        if (isAbortError(err)) return 'cancelled';
        return null;
    }
}

function tryAnchorDownload(filename: string, content: string, mimeType: string): ExportTextFileResult {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = filename;
    anchor.rel = 'noopener';
    anchor.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 2_000);
    return 'downloaded';
}

/**
 * تصدير ملف نصي — على الموبايل: مشاركة عبر Share/Filesystem؛ على الويب: تنزيل أو Web Share.
 */
export async function exportTextFile(options: {
    filename: string;
    content: string;
    mimeType?: string;
    dialogTitle?: string;
}): Promise<ExportTextFileResult> {
    const { filename, content, mimeType = 'application/json', dialogTitle = 'حفظ الملف' } = options;

    const webShare = await tryWebShareFile(filename, content, mimeType);
    if (webShare) return webShare;

    const nativeShare = await tryCapacitorShareFile(filename, content, dialogTitle);
    if (nativeShare) return nativeShare;

    if (typeof document === 'undefined') return 'failed';

    try {
        return tryAnchorDownload(filename, content, mimeType);
    } catch {
        return 'failed';
    }
}

/** يوقف التقاط الكاميرا/المايك عند إخفاء التطبيق — LED والخصوصية على الموبايل */

import { isAppForeground, subscribeAppForeground } from '@/app/runtime/appForegroundGate';

export function subscribeCaptureBackgroundRelease(onRelease: () => void): () => void {
    if (typeof document === 'undefined') return () => undefined;
    if (!isAppForeground()) {
        onRelease();
        return () => undefined;
    }
    return subscribeAppForeground({
        onSuspend: onRelease,
        onResume: () => undefined,
    });
}

/** مهلة تدفق وسائط — كاميرا/ميكروفون. الاسم في الخطأ TimeoutError لرسائل الواجهة. */
export function withMediaStreamTimeout<T>(
    promise: Promise<T>,
    ms: number,
    timeoutMessage: string,
): Promise<T> {
    return new Promise((resolve, reject) => {
        const timer = setTimeout(() => {
            reject(Object.assign(new Error(timeoutMessage), { name: 'TimeoutError' }));
        }, ms);
        promise.then(
            (value) => {
                clearTimeout(timer);
                resolve(value);
            },
            (error) => {
                clearTimeout(timer);
                reject(error);
            },
        );
    });
}

/** يحتفظ بتدفق المايكروفون المُسبَق بين نقرة المستخدم وفتح المسجّل */
import { subscribeCaptureBackgroundRelease } from '@/app/services/platform/mediaCaptureBackgroundRelease';

let pendingMicrophoneStream: MediaStream | null = null;
let pendingBackgroundUnsub: (() => void) | undefined;

function disarmPendingBackgroundRelease(): void {
    pendingBackgroundUnsub?.();
    pendingBackgroundUnsub = undefined;
}

function stopStreamTracks(stream: MediaStream | null): void {
    if (!stream) return;
    stream.getTracks().forEach((track) => {
        try {
            track.stop();
        } catch {
            /* ignore */
        }
    });
}

function releasePendingStream(): void {
    const held = pendingMicrophoneStream;
    pendingMicrophoneStream = null;
    disarmPendingBackgroundRelease();
    stopStreamTracks(held);
}

export function setPendingMicrophoneStream(stream: MediaStream | null): void {
    if (pendingMicrophoneStream && pendingMicrophoneStream !== stream) {
        stopStreamTracks(pendingMicrophoneStream);
    }
    disarmPendingBackgroundRelease();
    pendingMicrophoneStream = stream;
    if (!stream || typeof document === 'undefined') return;

    const held = stream;
    const unsub = subscribeCaptureBackgroundRelease(() => {
        if (pendingMicrophoneStream !== held) return;
        releasePendingStream();
    });
    /* إن أطلق التحرير متزامناً (التطبيق مخفى أصلاً) لا نُسند مُلغياً فوق حالة فارغة */
    if (pendingMicrophoneStream === held) {
        pendingBackgroundUnsub = unsub;
    }
}

export function consumePendingMicrophoneStream(): MediaStream | null {
    disarmPendingBackgroundRelease();
    const stream = pendingMicrophoneStream;
    pendingMicrophoneStream = null;
    return stream;
}

export function clearPendingMicrophoneStream(): void {
    releasePendingStream();
}

export function hasLiveMicrophoneStream(stream: MediaStream | null | undefined): boolean {
    if (!stream) return false;
    const getAudioTracks = stream.getAudioTracks;
    if (typeof getAudioTracks !== 'function') return false;
    try {
        return getAudioTracks.call(stream).some((track) => track.readyState === 'live');
    } catch {
        return false;
    }
}

export type NativeSharePayload = {
    title?: string;
    text?: string;
    url?: string;
    dialogTitle?: string;
};

export type NativeShareResult = 'shared' | 'copied' | 'cancelled' | 'unavailable';

function isAbortError(err: unknown): boolean {
    return err instanceof Error && err.name === 'AbortError';
}

async function tryCapacitorShare(payload: NativeSharePayload): Promise<NativeShareResult | null> {
    try {
        const { Capacitor } = await import('@capacitor/core');
        if (!Capacitor.isNativePlatform()) return null;
        const { Share } = await import('@capacitor/share');
        await Share.share({
            title: payload.title,
            text: payload.text,
            url: payload.url,
            dialogTitle: payload.dialogTitle ?? payload.title ?? 'مشاركة',
        });
        return 'shared';
    } catch (err) {
        if (isAbortError(err)) return 'cancelled';
        return null;
    }
}

/**
 * مشاركة أصلية: Capacitor Share على الجهاز، ثم Web Share API، ثم الحافظة.
 */
export async function shareNative(payload: NativeSharePayload): Promise<NativeShareResult> {
    const capacitorResult = await tryCapacitorShare(payload);
    if (capacitorResult) return capacitorResult;

    if (typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
        try {
            await navigator.share({
                title: payload.title,
                text: payload.text,
                url: payload.url,
            });
            return 'shared';
        } catch (err) {
            if (isAbortError(err)) return 'cancelled';
        }
    }

    const clipboardText = [payload.text, payload.url].filter(Boolean).join('\n');
    if (clipboardText && navigator.clipboard?.writeText) {
        await navigator.clipboard.writeText(clipboardText);
        return 'copied';
    }

    return 'unavailable';
}

export type MicrophonePermissionStatus = 'granted' | 'prompt' | 'denied' | 'unsupported';

export function isMicrophoneAllowedByDocumentPolicy(): boolean {
    if (typeof document === 'undefined') return true;
    try {
        const policy = (
            document as Document & {
                permissionsPolicy?: { allowsFeature: (feature: string) => boolean };
            }
        ).permissionsPolicy;
        if (policy?.allowsFeature) {
            return policy.allowsFeature('microphone');
        }
    } catch {
        /* ignore */
    }
    return true;
}

/** فحص حالة إذن المايكروفون دون طلب التدفق — لإظهار/إخفاء البنر */
async function hasEnumeratedMicrophoneLabel(): Promise<boolean> {
    try {
        const devices = await navigator.mediaDevices.enumerateDevices();
        return devices.some((device) => device.kind === 'audioinput' && Boolean(device.label?.trim()));
    } catch {
        return false;
    }
}

export async function queryMicrophonePermission(): Promise<MicrophonePermissionStatus> {
    if (typeof navigator === 'undefined' || !navigator.mediaDevices?.getUserMedia) {
        return 'unsupported';
    }

    if (!isMicrophoneAllowedByDocumentPolicy()) {
        return 'denied';
    }

    try {
        const permissions = navigator.permissions;
        if (permissions?.query) {
            const result = await permissions.query({ name: 'microphone' as PermissionName });
            if (result.state === 'granted') return 'granted';
            if (result.state === 'denied') return 'denied';
            if (await hasEnumeratedMicrophoneLabel()) return 'granted';
            return 'prompt';
        }
    } catch {
        /* بعض المتصفحات/WebView لا تدعم name: microphone */
    }

    if (await hasEnumeratedMicrophoneLabel()) return 'granted';
    return 'prompt';
}

export function watchMicrophonePermission(
    onChange: (status: MicrophonePermissionStatus) => void,
): () => void {
    if (typeof navigator === 'undefined' || !navigator.permissions?.query) {
        return () => undefined;
    }

    let disposed = false;
    let permissionStatus: PermissionStatus | null = null;

    void permissionsQuery()
        .then((result) => {
            if (disposed || !result) return;
            permissionStatus = result;
            const apply = () => {
                if (result.state === 'granted') onChange('granted');
                else if (result.state === 'denied') onChange('denied');
                else onChange('prompt');
            };
            apply();
            result.onchange = apply;
        })
        .catch(() => undefined);

    return () => {
        disposed = true;
        if (permissionStatus) permissionStatus.onchange = null;
    };

    async function permissionsQuery(): Promise<PermissionStatus | null> {
        try {
            return await navigator.permissions!.query({ name: 'microphone' as PermissionName });
        } catch {
            return null;
        }
    }
}

