import { SecureAPIClient, SecureFetchError } from '@/app/services/SecureAPIClient';
import {
    toDisplayNamePolicy,
    type DisplayNamePolicy,
} from '@/app/domain/profile/displayNameCorrection';

export class DisplayNameCorrectionError extends Error {
    readonly code: 'used' | 'invalid' | 'network';
    constructor(message: string, code: 'used' | 'invalid' | 'network') {
        super(message);
        this.name = 'DisplayNameCorrectionError';
        this.code = code;
    }
}

function asPolicy(raw: unknown): DisplayNamePolicy | null {
    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
    const rec = raw as Record<string, unknown>;
    if (rec.ok === false) return null;
    return toDisplayNamePolicy({
        fullName: String(rec.fullName ?? ''),
        previousFullName: rec.previousFullName == null ? null : String(rec.previousFullName),
        correctedAt: rec.correctedAt == null ? null : String(rec.correctedAt),
        corrections: rec.correctionUsed === true || rec.canCorrect === false ? 1 : 0,
    });
}

export async function fetchOwnDisplayNamePolicy(): Promise<DisplayNamePolicy | null> {
    try {
        const data = await SecureAPIClient.fetchSecure<unknown>('/api/auth/display-name', { method: 'GET' });
        return asPolicy(data);
    } catch {
        return null;
    }
}

export async function submitDisplayNameCorrection(fullName: string): Promise<DisplayNamePolicy> {
    try {
        const data = await SecureAPIClient.fetchSecure<unknown>('/api/auth/display-name', {
            method: 'PATCH',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ fullName }),
        });
        const policy = asPolicy(data);
        if (!policy) {
            throw new DisplayNameCorrectionError('تعذّر حفظ الاسم', 'network');
        }
        return policy;
    } catch (error) {
        if (error instanceof DisplayNameCorrectionError) throw error;
        if (error instanceof SecureFetchError && error.status === 409) {
            throw new DisplayNameCorrectionError('يمكن تصحيح الاسم مرة واحدة فقط', 'used');
        }
        if (error instanceof SecureFetchError && error.status === 400) {
            throw new DisplayNameCorrectionError('الاسم الثلاثي مطلوب', 'invalid');
        }
        throw new DisplayNameCorrectionError('تعذّر حفظ الاسم', 'network');
    }
}

import type { LawyerProfileData } from '@/app/services/cloud/lawyerProfileTypes';
import type { EditDraft } from '@/app/services/profile/profileEditDraft';
import { getGallery } from '@/app/services/profile/profileSections';

/** جدولة حذف وسائط — مسار واحد بدل import ديناميكي مكرر */
export function scheduleRemoveProfileMediaPaths(paths: readonly string[]): void {
    const cleaned = [...new Set(paths.map((p) => p.trim()).filter(Boolean))];
    if (cleaned.length === 0) return;
    void import('@/app/services/profileMediaService')
        .then((m) => m.removeProfileMediaPaths(cleaned))
        .catch(() => undefined);
}

/** مسارات رُفعت أثناء جلسة التحرير ولم تُثبَّت في الملف المحفوظ */
export function collectEditDraftOrphanMediaPaths(
    draft: EditDraft,
    committed: LawyerProfileData | null | undefined,
): string[] {
    if (!committed) return [];
    const orphans: string[] = [];
    const seen = new Set<string>();

    const push = (path: string | undefined) => {
        const next = path?.trim();
        if (!next || seen.has(next)) return;
        seen.add(next);
        orphans.push(next);
    };

    const committedAvatar = committed.header.profileImagePath?.trim();
    const draftAvatar = draft.header.profileImagePath?.trim();
    if (draftAvatar && draftAvatar !== committedAvatar) {
        push(draftAvatar);
    }

    const committedGallery = new Set(
        getGallery(committed.sections)
            .map((item) => item.storagePath?.trim())
            .filter((path): path is string => Boolean(path)),
    );
    for (const item of draft.gallery) {
        const path = item.storagePath?.trim();
        if (path && !committedGallery.has(path)) {
            push(path);
        }
    }

    return orphans;
}

export function discardEditDraftOrphanMedia(
    draft: EditDraft | null,
    committed: LawyerProfileData | null | undefined,
) {
    if (!draft) return;
    scheduleRemoveProfileMediaPaths(collectEditDraftOrphanMediaPaths(draft, committed));
}

/** يحذف مساراً مرفوعاً في الجلسة فقط إن لم يكن مثبتاً في الملف المحفوظ */
export function discardUnsavedMediaPath(
    path: string | undefined,
    committedPath: string | undefined | null,
) {
    const next = path?.trim();
    if (!next || next === committedPath?.trim()) return;
    scheduleRemoveProfileMediaPaths([next]);
}

export function discardUnsavedMediaPathUnlessCommitted(
    path: string | undefined,
    committedPaths: Iterable<string | undefined | null>,
) {
    const next = path?.trim();
    if (!next) return;
    for (const raw of committedPaths) {
        if (raw?.trim() === next) return;
    }
    scheduleRemoveProfileMediaPaths([next]);
}

import type { LawyerProfileData } from '@/app/services/lawyer-cloud';
import { getGallery } from '@/app/services/profile/profileSections';
import { scheduleRemoveProfileMediaPaths } from '@/app/services/profile/editDraftMediaPaths';

/** GC وسائط بعد حفظ ناجح — أفاتار + معارض لم تعد في الملف */
export function gcProfileEditOrphanMediaAfterSave(
    previousProfile: LawyerProfileData,
    nextProfile: LawyerProfileData,
): void {
    const previousAvatarPath = previousProfile.header.profileImagePath?.trim() || undefined;
    const nextAvatarPath = nextProfile.header.profileImagePath?.trim() || undefined;
    if (previousAvatarPath && previousAvatarPath !== nextAvatarPath) {
        scheduleRemoveProfileMediaPaths([previousAvatarPath]);
    }

    const prevGalleryPaths = new Set(
        getGallery(previousProfile.sections)
            .map((g) => g.storagePath?.trim())
            .filter((p): p is string => Boolean(p)),
    );
    const nextGalleryPaths = new Set(
        getGallery(nextProfile.sections)
            .map((g) => g.storagePath?.trim())
            .filter((p): p is string => Boolean(p)),
    );
    const orphanedGallery = [...prevGalleryPaths].filter((p) => !nextGalleryPaths.has(p));
    if (orphanedGallery.length > 0) {
        scheduleRemoveProfileMediaPaths(orphanedGallery);
    }
}

