import type {
    LawyerProfileData,
    LawyerProfileHeader,
    LawyerProfileSection,
    ProfileAction,
    ProfileGalleryItem,
} from '@/app/services/cloud/lawyerProfileTypes';
import { coerceGalleryItems } from '@/app/services/profile/profileGalleryItems';
import { getActions, getGallery } from '@/app/services/profile/profileSections';
import { normalizeProfilePageCustomization } from '@/app/services/profile/profilePageCustomization';
import { preferRicherLawyerDisplayName } from '@/app/services/profile/resolveLawyerDisplayName';
import {
    isProfilePaintReady,
    shouldAwaitCloudProfileSettle,
} from '@/app/services/profile/profileSparseDetect';

function pickNonEmpty(local: string | undefined, remote: string | undefined): string {
    const a = local?.trim() ?? '';
    const b = remote?.trim() ?? '';
    if (a && !b) return a;
    if (b && !a) return b;
    return a.length >= b.length ? a : b;
}

function mergeHeaders(local: LawyerProfileHeader, remote: LawyerProfileHeader): LawyerProfileHeader {
    return {
        ...remote,
        ...local,
        name: preferRicherLawyerDisplayName(remote.name ?? '', local.name ?? ''),
        title: pickNonEmpty(local.title, remote.title),
        coverImage: pickNonEmpty(local.coverImage, remote.coverImage),
        profileImage: pickNonEmpty(local.profileImage, remote.profileImage),
        profileImagePath: pickNonEmpty(local.profileImagePath, remote.profileImagePath) || undefined,
        coverImagePath: pickNonEmpty(local.coverImagePath, remote.coverImagePath) || undefined,
        phone: pickNonEmpty(local.phone, remote.phone),
        city: pickNonEmpty(local.city, remote.city),
        workplace: pickNonEmpty(local.workplace, remote.workplace),
        specialization: pickNonEmpty(local.specialization, remote.specialization),
        syndicateId: pickNonEmpty(local.syndicateId, remote.syndicateId),
        practiceSinceYear: local.practiceSinceYear ?? remote.practiceSinceYear,
    };
}

function galleryItemKey(item: ProfileGalleryItem): string {
    return (item.storagePath || item.url || '').trim();
}

function mergeGallery(
    local: ProfileGalleryItem[],
    remote: ProfileGalleryItem[],
): ProfileGalleryItem[] {
    const byKey = new Map<string, ProfileGalleryItem>();
    for (const item of remote) {
        const key = galleryItemKey(item);
        if (key) byKey.set(key, item);
    }
    for (const item of local) {
        const key = galleryItemKey(item);
        if (key) byKey.set(key, item);
    }
    const merged = [...byKey.values()];
    if (merged.length > 0) return merged;
    return local.length >= remote.length ? local : remote;
}

function mergeActions(local: ProfileAction[], remote: ProfileAction[]): ProfileAction[] {
    const byId = new Map<string, ProfileAction>();
    for (const action of remote) {
        if (action.id) byId.set(action.id, action);
    }
    for (const action of local) {
        if (!action.id) continue;
        const existing = byId.get(action.id);
        if (!existing) {
            byId.set(action.id, action);
            continue;
        }
        byId.set(
            action.id,
            (action.value?.trim().length ?? 0) >= (existing.value?.trim().length ?? 0)
                ? action
                : existing,
        );
    }
    const merged = [...byId.values()];
    if (merged.length > 0) return merged;
    return local.length >= remote.length ? local : remote;
}

function upsertSection(
    sections: LawyerProfileSection[],
    type: 'gallery' | 'actions',
    data: ProfileGalleryItem[] | ProfileAction[],
): LawyerProfileSection[] {
    const fallbackId = type === 'gallery' ? 'gallery-1' : 'actions-1';
    const existing = sections.find((section) => section.type === type);
    const next: LawyerProfileSection = {
        id: existing?.id ?? fallbackId,
        type,
        data,
    };
    return [...sections.filter((section) => section.type !== type), next];
}

function mergeOwnerProfiles(local: LawyerProfileData, remote: LawyerProfileData): LawyerProfileData {
    const localGallery = coerceGalleryItems(getGallery(local.sections));
    const remoteGallery = coerceGalleryItems(getGallery(remote.sections));
    const gallery = mergeGallery(localGallery, remoteGallery);
    const actions = mergeActions(getActions(local.sections), getActions(remote.sections));
    const baseSections = local.sections.length > 0 ? local.sections : remote.sections;
    const sections = upsertSection(
        upsertSection(baseSections, 'gallery', gallery),
        'actions',
        actions,
    );
    const localCustomization = normalizeProfilePageCustomization(local.customization);
    const remoteCustomization = normalizeProfilePageCustomization(remote.customization);
    const localBlocks = localCustomization.customBlocks.length;
    const remoteBlocks = remoteCustomization.customBlocks.length;
    const customization =
        localBlocks > 0 && remoteBlocks === 0
            ? localCustomization
            : remoteBlocks > 0 && localBlocks === 0
              ? remoteCustomization
              : {
                    ...remoteCustomization,
                    ...localCustomization,
                    customBlocks:
                        localBlocks >= remoteBlocks
                            ? localCustomization.customBlocks
                            : remoteCustomization.customBlocks,
                    appearance: localCustomization.appearance ?? remoteCustomization.appearance,
                    privacy: localCustomization.privacy ?? remoteCustomization.privacy,
                };

    return {
        header: mergeHeaders(local.header, remote.header),
        sections,
        customization,
    };
}

/**
 * لا تُكتب سحابة شحيحة فوق ملف محلي أغنى (معرض/تواصل لم تُزامَن بعد).
 * عند الطرفين الغنيين تُدمج القنوات والمعرض بدل آخر-كتابة-تفوز.
 */
export function reconcileOwnerProfileFromCloud(
    local: LawyerProfileData | null,
    remote: LawyerProfileData,
): LawyerProfileData {
    if (!local) return remote;
    if (isProfilePaintReady(local) && shouldAwaitCloudProfileSettle(remote)) {
        return local;
    }
    if (shouldAwaitCloudProfileSettle(local) && isProfilePaintReady(remote)) {
        return remote;
    }
    if (shouldAwaitCloudProfileSettle(local) && shouldAwaitCloudProfileSettle(remote)) {
        return local.header.name?.trim() ? local : remote;
    }
    return mergeOwnerProfiles(local, remote);
}

import type { ProfileAction } from '@/app/services/profile/profileTypes';
import {
    buildProfileContactTarget,
    normalizeAsciiDigits,
    normalizeTelHref,
} from '@/app/services/profile/profileContactNavigation';
import { sanitizeProfilePlainText } from '@/app/services/profile/profileUrlSanitize';

const MAX_PROFILE_CONTACT_LABEL_LENGTH = 48;
const MAX_PROFILE_CONTACT_VALUE_LENGTH = 240;
const MAX_PROFILE_DISPLAY_NAME_LENGTH = 80;

export class ProfileContactValidationError extends Error {
    constructor(message: string) {
        super(message);
        this.name = 'ProfileContactValidationError';
    }
}

/** أثناء الكتابة — يحافظ على المسافات الطرفية حتى يمكن إدخال كلمات متعددة */
export function clampProfileContactLabelLive(raw: string): string {
    return raw.replace(/[\r\n\t]/g, ' ').slice(0, MAX_PROFILE_CONTACT_LABEL_LENGTH);
}

/** أثناء الكتابة — لا يقصّ المسافات الطرفية */
export function clampProfileContactValueLive(raw: string): string {
    return raw.replace(/[\r\n\t]/g, ' ').slice(0, MAX_PROFILE_CONTACT_VALUE_LENGTH);
}

export function clampProfileContactLabel(raw: string): string {
    return sanitizeProfilePlainText(clampProfileContactLabelLive(raw), MAX_PROFILE_CONTACT_LABEL_LENGTH).trim();
}

export function clampProfileContactValue(raw: string): string {
    return clampProfileContactValueLive(raw).trim();
}

export function clampProfileDisplayName(raw: string): string {
    return sanitizeProfilePlainText(raw.replace(/[\r\n\t]/g, ' '), MAX_PROFILE_DISPLAY_NAME_LENGTH).trim();
}

const UNSAFE_CLIPBOARD_SCHEME = /^\s*(javascript|data|vbscript|file|blob):/i;

/** نص النسخ — يرفض مخططات خطرة حتى لو وُجدت في قيمة مخزّنة قديمة */
export function safeProfileContactClipboardText(raw: string): string {
    const value = clampProfileContactValue(raw);
    if (!value || UNSAFE_CLIPBOARD_SCHEME.test(value)) return '';
    return value;
}

function sanitizeProfileAction(action: ProfileAction): ProfileAction {
    let value = clampProfileContactValue(action.value || '');
    if (action.type === 'call') {
        value = normalizeAsciiDigits(value);
    }
    return {
        ...action,
        label: clampProfileContactLabel(action.label || ''),
        value,
    };
}

export function sanitizeProfileActions(actions: ProfileAction[]): ProfileAction[] {
    return actions.map(sanitizeProfileAction).filter((a) => a.label.length > 0 || a.value.length > 0);
}

/** هاتف الهيدر: يُقبل فارغاً أو رقماً قابلاً للاتصال؛ غير ذلك يُفرَّغ */
export function sanitizeProfileHeaderPhone(raw: string | undefined | null): string {
    const trimmed = normalizeAsciiDigits(clampProfileContactValue(raw ?? ''));
    if (!trimmed) return '';
    return normalizeTelHref(trimmed) ? trimmed : '';
}

/**
 * يتحقق أن كل قناة ذات قيمة غير فارغة تُنتج هدفاً صالحاً (tel/mailto/https…).
 * يرمي ProfileContactValidationError عند أول قيمة غير صالحة.
 */
function assertProfileContactsValid(actions: ProfileAction[]): void {
    for (const action of sanitizeProfileActions(actions)) {
        if (!action.value.trim()) continue;
        if (buildProfileContactTarget(action) == null) {
            const label = action.label || action.type;
            throw new ProfileContactValidationError(`قيمة «${label}» غير صالحة — صحّحها قبل الحفظ`);
        }
    }
}

/** يصفّي القنوات الفارغة ويتحقق من صلاحية الباقي قبل Persist */
export function sanitizeProfileActionsForPersist(actions: ProfileAction[]): ProfileAction[] {
    const cleaned = sanitizeProfileActions(actions).filter((a) => a.value.trim().length > 0);
    assertProfileContactsValid(cleaned);
    return cleaned;
}

import type { ProfileAction, ProfileLocationMode } from '@/app/services/profile/profileTypes';

export type ProfileContactOpenResult = 'opened' | 'invalid' | 'display_only';

/** يحوّل الأرقام العربية/الفارسية إلى لاتينية — لوحة Android العربية تُدخل ٦٧٨ بدل 678 */
export function normalizeAsciiDigits(value: string): string {
    return value
        .replace(/[\u0660-\u0669]/g, (ch) => String(ch.charCodeAt(0) - 0x0660))
        .replace(/[\u06f0-\u06f9]/g, (ch) => String(ch.charCodeAt(0) - 0x06f0));
}

function digitsOnlyPhone(value: string): string {
    return normalizeAsciiDigits(value).replace(/[^\d+]/g, '');
}

function isLatLngPair(value: string): boolean {
    return /^-?\d+(\.\d+)?\s*,\s*-?\d+(\.\d+)?$/.test(value.trim());
}

function parseLatLng(value: string): { lat: number; lng: number } | null {
    const match = value.trim().match(/^(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)$/);
    if (!match) return null;
    const lat = Number(match[1]);
    const lng = Number(match[2]);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) return null;
    return { lat, lng };
}

export function resolveLocationMode(action: ProfileAction): ProfileLocationMode {
    if (action.type !== 'location') return 'manual';
    if (action.locationMode === 'gps' || action.locationMode === 'manual') {
        return action.locationMode;
    }
    return isLatLngPair(action.value) ? 'gps' : 'manual';
}

function isIosDevice(): boolean {
    if (typeof navigator === 'undefined') return false;
    return /iPad|iPhone|iPod/i.test(navigator.userAgent);
}

function isMobileDevice(): boolean {
    if (typeof navigator === 'undefined') return false;
    return /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent);
}

/** تنسيق رقم للاتصال — يدعم الأرقام العراقية المحلية (07… أو 7…) */
export function normalizeTelHref(raw: string): string | null {
    let tel = digitsOnlyPhone(raw.trim());
    if (!tel) return null;

    if (tel.startsWith('00')) {
        tel = `+${tel.slice(2)}`;
    } else if (tel.startsWith('0') && !tel.startsWith('+')) {
        tel = `+964${tel.slice(1)}`;
    } else if (/^7\d{9}$/.test(tel)) {
        /* موبايل عراقي بلا صفر بادئ */
        tel = `+964${tel}`;
    } else if (!tel.startsWith('+') && tel.length >= 9) {
        tel = `+${tel}`;
    }

    const digitCount = tel.replace(/\D/g, '').length;
    if (digitCount < 7) return null;
    return `tel:${tel}`;
}

function buildMapsSearchTarget(query: string): string | null {
    const trimmed = query.trim();
    if (!trimmed) return null;
    const encoded = encodeURIComponent(trimmed);
    if (isIosDevice()) {
        return `https://maps.apple.com/?q=${encoded}`;
    }
    return `https://www.google.com/maps/search/?api=1&query=${encoded}`;
}

function buildMapsCoordinateTarget(lat: number, lng: number): string {
    if (isIosDevice()) {
        return `https://maps.apple.com/?ll=${lat},${lng}&q=${lat},${lng}`;
    }
    return `https://www.google.com/maps/search/?api=1&query=${lat},${lng}`;
}

/** يفتح روابط tel/mailto عبر معالج النظام — احتياطي عند عدم استخدام <a href> */
const NATIVE_CONTACT_PROTOCOLS = new Set(['https:', 'tel:', 'mailto:']);

function isAllowedNativeContactUrl(url: string): boolean {
    try {
        const parsed = new URL(url);
        return NATIVE_CONTACT_PROTOCOLS.has(parsed.protocol);
    } catch {
        return false;
    }
}

export function openNativeScheme(url: string): void {
    if (typeof window === 'undefined') return;
    if (!isAllowedNativeContactUrl(url)) return;

    // mailto/tel يعملان أفضل عبر location.assign على الموبايل وWebView
    if (url.startsWith('mailto:') || url.startsWith('tel:') || isMobileDevice()) {
        window.location.assign(url);
        return;
    }

    if (typeof document === 'undefined') return;
    const link = document.createElement('a');
    link.href = url;
    link.rel = 'noopener noreferrer';
    link.style.display = 'none';
    document.body.appendChild(link);
    link.click();
    link.remove();
}

export function buildProfileContactTarget(action: ProfileAction): string | null {
    const raw = String(action.value ?? '').trim();
    if (!raw) return null;

    switch (action.type) {
        case 'call':
            return normalizeTelHref(raw);
        case 'email': {
            const email = raw.replace(/\s+/g, '');
            /* منع حقن استعلام/مسار في mailto (?bcc=، #، /) */
            if (/[\r\n?#/\\]/.test(email)) return null;
            if (!email.includes('@')) return null;
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return null;
            return `mailto:${email}`;
        }
        case 'website': {
            const rawHost = raw.replace(/^https?:\/\//i, '').split('/')[0]?.split('?')[0] ?? '';
            if (/^\d+$/.test(rawHost)) return null;

            let url = raw;
            if (!/^https?:\/\//i.test(url)) url = `https://${url}`;
            try {
                const parsed = new URL(url);
                /* تنقّل المستخدم — HTTPS فقط (HTTP عرضة لاعتراض الوسيط) */
                if (parsed.protocol !== 'https:') return null;
                const host = parsed.hostname.toLowerCase();
                if (!host.includes('.') || /^\d{1,3}(\.\d{1,3}){3}$/.test(host)) return null;
                if (!/^[a-z0-9.-]+$/i.test(host)) return null;
                return parsed.toString();
            } catch {
                return null;
            }
        }
        case 'location': {
            if (resolveLocationMode(action) === 'gps') {
                const coords = parseLatLng(raw);
                if (!coords) return null;
                return buildMapsCoordinateTarget(coords.lat, coords.lng);
            }
            return buildMapsSearchTarget(raw);
        }
        default:
            return null;
    }
}

/** يفتح قناة التواصل بالتطبيق المناسب (هاتف / بريد / خرائط) */
export function openProfileContact(action: ProfileAction): ProfileContactOpenResult {
    const target = buildProfileContactTarget(action);
    if (!target) return 'invalid';

    switch (action.type) {
        case 'call':
        case 'email':
        case 'location':
            openNativeScheme(target);
            break;
        case 'website':
            if (!isAllowedNativeContactUrl(target)) return 'invalid';
            window.open(target, '_blank', 'noopener,noreferrer');
            break;
        default:
            openNativeScheme(target);
    }

    return 'opened';
}

export function contactValuePlaceholder(type: ProfileAction['type']): string {
    switch (type) {
        case 'call':
            return '07XXXXXXXX';
        case 'email':
            return 'name@example.com';
        case 'website':
            return 'https://example.com';
        case 'location':
            return 'العنوان أو اضغط «تحديد المكان»';
        default:
            return 'القيمة';
    }
}

import type { ProfileCustomBlock } from '@/app/services/profile/profilePageCustomization';
import { defaultTextCanvasStyle } from '@/app/services/profile/profilePageCustomization';

/** دمج patch كتلة مع دمج متداخل لإطار الصورة و canvasStyle */
export function mergeProfileCustomBlockPatch(
    block: ProfileCustomBlock,
    patch: Partial<ProfileCustomBlock>,
): ProfileCustomBlock {
    const next: ProfileCustomBlock = { ...block, ...patch };
    if (patch.imageFrameStyle) {
        next.imageFrameStyle = {
            ...block.imageFrameStyle,
            ...patch.imageFrameStyle,
        };
    }
    if (patch.canvasStyle) {
        next.canvasStyle = { ...block.canvasStyle, ...patch.canvasStyle };
    }
    return next;
}

export function applyCanvasBackgroundToBlock(
    block: ProfileCustomBlock,
    displayUrl: string,
    storagePath?: string,
): ProfileCustomBlock {
    return {
        ...block,
        canvasStyle: {
            ...defaultTextCanvasStyle(),
            ...block.canvasStyle,
            enabled: true,
            backgroundImage: displayUrl,
            backgroundStoragePath: storagePath,
        },
    };
}

export function clearCanvasBackgroundOnBlock(block: ProfileCustomBlock): ProfileCustomBlock {
    return {
        ...block,
        canvasStyle: {
            ...defaultTextCanvasStyle(),
            ...block.canvasStyle,
            backgroundImage: undefined,
            backgroundStoragePath: undefined,
        },
    };
}

export function clearBlockImageFields(block: ProfileCustomBlock): ProfileCustomBlock {
