    return trimmed.charAt(0) || fallback;
}

/** هل حدث تحديث الملف يخص المستخدم الحالي */
export function shouldApplyProfileHeaderUpdate(
    eventUserId: string | undefined,
    currentUserId: string,
): boolean {
    if (!eventUserId?.trim()) return true;
