/**
 * جلب قديم بعد الحفظ كان يستبدل الاسم المحفوظ باسم الجلسة/القرص السابق.
 * إن طابق المعروض الكاش الدافئ، لا نقبل اسماً وارداً مختلفاً إلا إغناء بادئة.
 */
export function resolveHeaderDisplayNameAfterLoad(
    displayed: string,
    incoming: string,
    warmName: string,
): string {
    const shown = displayed.trim();
    const next = incoming.trim();
    const warm = warmName.trim();
    if (
        shown &&
        warm &&
        shown === warm &&
        next &&
        next !== shown &&
        !isNamePrefixEnrichment(shown, next)
    ) {
        return shown;
    }
    return preferRicherLawyerDisplayName(shown, next);
}

/** نسبة إطار خلفية لوحة الكتابة في الملف المهني */
export const PROFILE_CANVAS_BACKGROUND_ASPECT = 16 / 9;

/** أقصى حافة للتصدير — بدون تقليل إلا إذا تجاوزت المصدر */
export const PROFILE_CANVAS_EXPORT_MAX_EDGE = 3840;

export const PROFILE_CANVAS_EXPORT_JPEG_QUALITY = 0.96;

export type ProfileBackgroundEditState = {
    /** 1 = أقل تكبير يغطي الإطار بالكامل */
    scale: number;
    /** -1..1 أفقي */
    panX: number;
    /** -1..1 عمودي */
    panY: number;
};

export function defaultProfileBackgroundEditState(): ProfileBackgroundEditState {
    return { scale: 1, panX: 0, panY: 0 };
}

export function clampProfileBackgroundEditState(
    state: ProfileBackgroundEditState,
): ProfileBackgroundEditState {
    return {
        scale: Math.min(4, Math.max(1, state.scale)),
        panX: Math.min(1, Math.max(-1, state.panX)),
        panY: Math.min(1, Math.max(-1, state.panY)),
    };
}

export type ProfileBackgroundCropRect = {
    sx: number;
    sy: number;
    sw: number;
    sh: number;
};

/** يحسب مستطيل الاقتصاص في إحداثيات الصورة الأصلية */
export function computeProfileBackgroundCropRect(
    srcW: number,
    srcH: number,
    state: ProfileBackgroundEditState,
    aspect = PROFILE_CANVAS_BACKGROUND_ASPECT,
): ProfileBackgroundCropRect {
    const safe = clampProfileBackgroundEditState(state);
    const srcAspect = srcW / srcH;

    let baseW: number;
    let baseH: number;
    if (srcAspect > aspect) {
        baseH = srcH;
        baseW = baseH * aspect;
    } else {
        baseW = srcW;
        baseH = baseW / aspect;
    }

    const zoom = safe.scale;
    const sw = baseW / zoom;
    const sh = baseH / zoom;
    const maxPanX = Math.max(0, (srcW - sw) / 2);
    const maxPanY = Math.max(0, (srcH - sh) / 2);
    const cx = srcW / 2 + safe.panX * maxPanX;
    const cy = srcH / 2 + safe.panY * maxPanY;

    let sx = cx - sw / 2;
    let sy = cy - sh / 2;
    sx = Math.max(0, Math.min(srcW - sw, sx));
    sy = Math.max(0, Math.min(srcH - sh, sy));

    return { sx, sy, sw, sh };
}

export async function loadProfileImageBitmap(file: File): Promise<ImageBitmap> {
    if (typeof createImageBitmap === 'function') {
        return createImageBitmap(file, { imageOrientation: 'from-image' });
    }
    const objectUrl = URL.createObjectURL(file);
    try {
        const image = await new Promise<HTMLImageElement>((resolve, reject) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => reject(new Error('image load failed'));
            img.src = objectUrl;
        });
        const canvas = document.createElement('canvas');
        canvas.width = image.naturalWidth || image.width;
        canvas.height = image.naturalHeight || image.height;
        const ctx = canvas.getContext('2d');
        if (!ctx) throw new Error('canvas unavailable');
        ctx.drawImage(image, 0, 0);
        return createImageBitmap(canvas);
    } finally {
        URL.revokeObjectURL(objectUrl);
    }
}

export type ExportProfileBackgroundOptions = {
    aspect?: number;
    maxEdge?: number;
    quality?: number;
    preferPng?: boolean;
};

/** يصدّر الصورة المحرَّرة بأعلى دقة ممكنة ضمن الحد الآمن */
export async function exportProfileBackgroundImage(
    bitmap: ImageBitmap,
    state: ProfileBackgroundEditState,
    sourceName: string,
    opts?: ExportProfileBackgroundOptions,
): Promise<File> {
    const aspect = opts?.aspect ?? PROFILE_CANVAS_BACKGROUND_ASPECT;
    const maxEdge = opts?.maxEdge ?? PROFILE_CANVAS_EXPORT_MAX_EDGE;
    const quality = opts?.quality ?? PROFILE_CANVAS_EXPORT_JPEG_QUALITY;
    const preferPng = opts?.preferPng ?? false;

    const { sx, sy, sw, sh } = computeProfileBackgroundCropRect(
        bitmap.width,
        bitmap.height,
        state,
        aspect,
    );

    const longest = Math.max(sw, sh);
    const scale = longest > maxEdge ? maxEdge / longest : 1;
    const outW = Math.max(1, Math.round(sw * scale));
    const outH = Math.max(1, Math.round(sh * scale));

    const canvas = document.createElement('canvas');
    canvas.width = outW;
    canvas.height = outH;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('canvas unavailable');

    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(bitmap, sx, sy, sw, sh, 0, 0, outW, outH);

    const usePng = preferPng;
    const mime = usePng ? 'image/png' : 'image/jpeg';
    const blob = await new Promise<Blob | null>((resolve) => {
        canvas.toBlob((b) => resolve(b), mime, usePng ? undefined : quality);
    });
    if (!blob) throw new Error('export failed');

    const base = sourceName.replace(/\.[^.]+$/, '') || 'profile-bg';
    const ext = usePng ? 'png' : 'jpg';
    return new File([blob], `${base}-edited.${ext}`, { type: mime });
}

import { redactProfileForVisitorView } from '@/app/services/profile/profileVisitorView';
import { normalizeProfilePageCustomization } from '@/app/services/profile/profilePageCustomization';
import { canViewProfilePage, resolveProfilePageAccess } from '@/app/services/profile/profilePageAccess';
import type { LawyerProfileData } from '@/app/services/cloud/lawyerProfileTypes';

/** يستخرج معرّف صاحب الملف من مفتاح KV: profile:{userId} */
export function parseProfileKvOwnerId(key: string): string | null {
    if (!key.startsWith('profile:')) return null;
    const ownerId = key.slice('profile:'.length).trim();
    return ownerId || null;
}

function looksLikeLawyerProfile(value: unknown): value is LawyerProfileData {
    if (!value || typeof value !== 'object') return false;
    const rec = value as Record<string, unknown>;
    return Boolean(rec.header) && typeof rec.header === 'object' && Array.isArray(rec.sections);
}

/**
 * تحقّق خادمي من علاقة "متابعة" — مستقل عن ثقة العميل.
 * ديناميكي عمداً (كما في useProfilePageAccess) لتجنّب ربط وحدة forum بمسار kv-proxy إحصائياً.
 * أي فشل (شبكة/تهيئة) ⇒ الأكثر تحفّظاً هو رفض الوصول لا منحه.
 */
async function isViewerFollowingOwner(viewerId: string, ownerId: string): Promise<boolean> {
    try {
        const { ForumFollowRepository } = await import('@/app/services/forum/forumFollowRepository');
        return await ForumFollowRepository.isFollowing(viewerId, ownerId);
    } catch {
        return false;
    }
}

/**
 * صفحة محجوبة كاملاً (private، أو followers بلا متابعة فعلية) — صفر تسريب محتوى.
 * يُبقى فقط ما تحتاجه شاشة الحجب نفسها (الاسم)، بلا هاتف/مدينة/نقابة/أقسام/كتل مخصّصة،
 * بصرف النظر عن تفضيلات الخصوصية الحقلية للمالك (تلك تخصّ من *يُسمح* له بالعرض، لا من يُحجَب كليةً).
 */
function blockedProfileStub(value: LawyerProfileData): LawyerProfileData {
    const visitorSafe = redactProfileForVisitorView(value);
    return {
        ...visitorSafe,
        header: { ...visitorSafe.header, phone: '', city: '', syndicateId: '' },
        sections: [],
        customization: {
            ...normalizeProfilePageCustomization(visitorSafe.customization),
            customBlocks: [],
        },
    };
}

/**
 * عند قراءة ملف مهني لغير المالك عبر kv-proxy:
 * ١) تُفرض بوابة pageAccess (public/followers/private) خادمياً أولاً — لا تعتمد على فحص العميل.
 * ٢) إن سُمح بالعرض، تُطبَّق تصفية الحقول الجزئية (showPhoneMeta...) كما كانت.
 */
export async function redactProfileKvValueForViewer(
    key: string,
    viewerId: string,
    value: unknown,
): Promise<unknown> {
    if (value == null) return value;
    const ownerId = parseProfileKvOwnerId(key);
    if (!ownerId) return value;
    if (ownerId === viewerId.trim()) return value;
    if (!looksLikeLawyerProfile(value)) return value;

    const pageAccess = resolveProfilePageAccess(
        normalizeProfilePageCustomization(value.customization).privacy,
    );
    const isFollowing =
        pageAccess === 'followers' ? await isViewerFollowingOwner(viewerId.trim(), ownerId) : false;

    if (!canViewProfilePage({ pageAccess, isOwner: false, isFollowing })) {
        return blockedProfileStub(value);
    }

    return redactProfileForVisitorView(value);
}

/** بادئة التخزين المحلي لملف المحامي — مفتاح لكل userId */
export const LAWYER_PROFILE_LOCAL_KEY_PREFIX = 'hami:profile:v1:';

export function getLawyerProfileLocalKey(userId: string): string {
    return `${LAWYER_PROFILE_LOCAL_KEY_PREFIX}${userId.trim()}`;
}

/** هوية وسائط الملف بلا query — لا تستخدم data: كامل كمفتاح React/كاش */
export function profileMediaIdentity(url: string): string {
    const trimmed = url.trim();
    if (!trimmed) return '';
    if (trimmed.startsWith('data:')) {
        const comma = trimmed.indexOf(',');
        const meta = (comma >= 0 ? trimmed.slice(0, comma) : trimmed.slice(0, 48)).slice(0, 64);
        const payloadLen = comma >= 0 ? trimmed.length - comma - 1 : 0;
        let hash = 0;
        const sampleStart = Math.max(0, trimmed.length - 48);
        for (let i = sampleStart; i < trimmed.length; i += 1) {
            hash = (hash * 33 + trimmed.charCodeAt(i)) >>> 0;
        }
        return `${meta}:L${payloadLen}:h${hash.toString(16)}`;
    }
    try {
        const base =
            typeof window !== 'undefined' ? window.location.href : 'https://hami.local/';
        const parsed = new URL(trimmed, base);
        return `${parsed.origin}${parsed.pathname}`;
    } catch {
        return trimmed.split('?')[0] ?? trimmed;
    }
}

import type { ProfilePageCustomization } from '@/app/services/profile/profilePageTypes';

/** يجمع مسارات التخزين السحابي المرتبطة بحاويات الصفحة */
export function collectProfileMediaPaths(
    customization: ProfilePageCustomization | undefined | null,
): string[] {
    const paths: string[] = [];
    const seen = new Set<string>();
    for (const block of customization?.customBlocks ?? []) {
        const imagePath = block.imageStoragePath?.trim();
        if (imagePath && !seen.has(imagePath)) {
            seen.add(imagePath);
            paths.push(imagePath);
        }
        const bgPath = block.canvasStyle?.backgroundStoragePath?.trim();
        if (bgPath && !seen.has(bgPath)) {
            seen.add(bgPath);
            paths.push(bgPath);
        }
    }
    return paths;
}

/** مسارات كانت في السابق واختفت بعد الحفظ/الحذف */
export function profileMediaPathsRemovedFrom(
    previous: ProfilePageCustomization | undefined | null,
    next: ProfilePageCustomization | undefined | null,
): string[] {
    const keep = new Set(collectProfileMediaPaths(next));
    return collectProfileMediaPaths(previous).filter((path) => !keep.has(path));
}

/** مسارات رُفعت في المسودة ولم تُحفظ بعد — تُحذف عند الإلغاء */
export function profileMediaPathsOnlyIn(
    candidate: ProfilePageCustomization | undefined | null,
    baseline: ProfilePageCustomization | undefined | null,
): string[] {
    const base = new Set(collectProfileMediaPaths(baseline));
    return collectProfileMediaPaths(candidate).filter((path) => !base.has(path));
}

import type { ProfilePageAccess, ProfilePrivacySettings } from './profilePageTypes';

export const PROFILE_PAGE_ACCESS_ORDER: readonly ProfilePageAccess[] = ['public', 'followers', 'private'];

export type ProfilePageAccessMeta = {
    id: ProfilePageAccess;
    label: string;
    shortLabel: string;
    hint: string;
};

export const PROFILE_PAGE_ACCESS_OPTIONS: readonly ProfilePageAccessMeta[] = [
