/**
 * فتح/إغلاق الملف المهني لحظياً.
 * المصدر الوحيد للحقيقة البصرية: html[data-hami-profile-open]
 * أثناء الإغلاق: html[data-hami-profile-closing] يفرض إخفاء السطح حتى لو
 * React مسح inline styles وأبقى --active (سبب الشاشة السوداء + الهيدر).
 * React يُزامَن بـ flushSync في مسار الفتح/الإغلاق — بلا rAF معلّق.
 * التقويم يلغي إطاراً معلّقاً برمز جيل لأن Hostه قد لا يكون في DOM بعد.
 */

import { wasProfileOpenedThisPage } from '@/app/hooks/lawyerDashboard/profile/profileOpenSession';
import { isViteE2eHooksEnabled } from '@/app/utils/viteE2eHooks';

const PROFILE_SURFACE = '[data-testid="lawyer-dashboard-profile-surface"]';
const OPEN_ATTR = 'data-hami-profile-open';
const CLOSING_ATTR = 'data-hami-profile-closing';

function recordE2eSnapClose(blocked: boolean): void {
    if (!isViteE2eHooksEnabled() || typeof window === 'undefined') return;
    const w = window as Window & {
        __hamiE2eLastProfileSnapClose?: {
            blocked: boolean;
            at: number;
            stack: string;
        };
    };
    w.__hamiE2eLastProfileSnapClose = {
        blocked,
        at: Date.now(),
        stack: new Error().stack?.split('\n').slice(0, 14).join('\n') ?? '',
    };
}

export function isProfileShellSnappedOpen(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.getAttribute(OPEN_ATTR) === '1';
}

export function isProfileShellClosing(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.getAttribute(CLOSING_ATTR) === '1';
}

export function clearProfileShellClosing(): void {
    if (typeof document === 'undefined') return;
    document.documentElement.removeAttribute(CLOSING_ATTR);
}

/**
 * يضع علم الفتح فوراً حتى بلا سطح مركّب —
 * يخفي غطاء الرئيسية والهيدر بالـ CSS قبل اكتمال React/chunk.
 * @returns true إذا وُجد سطح الملف في DOM
 */
export function snapProfileShellOpen(): boolean {
    if (typeof document === 'undefined') return false;
    clearProfileShellClosing();
    document.documentElement.setAttribute(OPEN_ATTR, '1');
    const surface = document.querySelector(PROFILE_SURFACE);
    return surface instanceof HTMLElement;
}

export function snapProfileShellClose(): void {
    if (typeof document === 'undefined') return;
    /* جلسة فتح قائمة: لا تمسح snap من مسار جانبي (إعادة تركيب اللوحة / إغلاق دعاوى).
     * الإغلاق المقصود يصفّر النية أولاً (runProfileClosePaint / returnToLawyerHome). */
    if (wasProfileOpenedThisPage()) {
        recordE2eSnapClose(true);
        return;
    }
    const wasOpen = document.documentElement.getAttribute(OPEN_ATTR) === '1';
    recordE2eSnapClose(false);
    document.documentElement.removeAttribute(OPEN_ATTR);
    /* حزمة E2E تتخطى التلاشي — closing العالق كان يبقي z-index 200 فوق الرئيسية */
    const skipClosingFade =
        import.meta.env.VITE_E2E === '1' || import.meta.env.VITE_E2E === 'true';
    if (wasOpen && !skipClosingFade) {
        document.documentElement.setAttribute(CLOSING_ATTR, '1');
    }
}

/** للاختبارات */
export function resetProfileShellSnapForTests(): void {
    if (typeof document !== 'undefined') {
        document.documentElement.removeAttribute(OPEN_ATTR);
        document.documentElement.removeAttribute(CLOSING_ATTR);
    }
}

import type { LawyerProfileData } from '@/app/services/cloud/lawyerProfileTypes';

/**
 * ملف بلا وسائط/تواصل — stub قبل استقرار البيانات.
 * لا يُرسم كواجهة «جاهزة» حتى لا يومض حرف/فراغ ← صورة/محتوى.
 */
export function shouldAwaitCloudProfileSettle(profile: LawyerProfileData | null | undefined): boolean {
    if (!profile) return true;
    const hasImage = Boolean(profile.header?.profileImage?.trim());
    const gallery = profile.sections?.find((s) => s.type === 'gallery');
    const actions = profile.sections?.find((s) => s.type === 'actions');
    const galleryLen = Array.isArray(gallery?.data) ? gallery.data.length : 0;
    const actionsLen = Array.isArray(actions?.data) ? actions.data.length : 0;
    return !hasImage && galleryLen === 0 && actionsLen === 0;
}

/** جاهز لرسم إطار واحد نظيف — بلا بذرة فارغة */
export function isProfilePaintReady(profile: LawyerProfileData | null | undefined): boolean {
    return Boolean(profile) && !shouldAwaitCloudProfileSettle(profile);
}

import {
    resolveProfileAccentHex,
    resolveProfileAccentInkHex,
    resolveProfileAccentOnSolidHex,
    resolveProfilePageBackground,
    type ProfilePageCustomization,
} from '@/app/services/profile/profilePageCustomization';

type ProfileAppearance = ProfilePageCustomization['appearance'];

/** آخر مظهر طُبّق على الجذر — يُقرأ عند إعادة رسم React حتى لا يُعاد الثيم المحفوظ فوق معاينة الاستوديو */
let liveProfileAppearance: ProfileAppearance | null = null;

export function getLiveProfileAppearance(): ProfileAppearance | null {
    return liveProfileAppearance;
}

/** يُصفَّر عند تبديل هوية الملف حتى لا يتسرّب مظهر مستخدم سابق */
export function clearLiveProfileAppearance(): void {
    liveProfileAppearance = null;
}

/** يؤجّل تطبيق الثيم بعد إغلاق الاستوديو — يترك حركة الإغلاق تكتمل بلا وميض */
export function scheduleProfileRootTheme(
    appearance: ProfileAppearance,
    root?: HTMLElement | null,
): void {
    if (typeof window === 'undefined') {
        applyProfileRootTheme(appearance, root);
        return;
    }
    requestAnimationFrame(() => {
        requestAnimationFrame(() => {
            applyProfileRootTheme(appearance, root);
        });
    });
}

/** تحديث متغيرات CSS للمعاينة دون إعادة رسم React */
export function applyProfileRootTheme(
    appearance: ProfileAppearance,
    root?: HTMLElement | null,
): void {
    liveProfileAppearance = appearance;
    const el =
        root ??
        (typeof document !== 'undefined'
            ? document.querySelector('[data-lawyer-profile-root]')
            : null);
    if (!el || !(el instanceof HTMLElement)) return;
    el.dataset.profileMaterial = appearance.material;
    el.dataset.profilePortraitFrame = appearance.portraitFrame ?? 'classic';
    el.dataset.profileAccent = appearance.accentColor;
    const pageBg = resolveProfilePageBackground(appearance.accentColor);
    el.style.setProperty('--profile-accent', resolveProfileAccentHex(appearance.accentColor));
    el.style.setProperty('--profile-accent-ink', resolveProfileAccentInkHex(appearance.accentColor));
    el.style.setProperty(
        '--profile-accent-on-solid',
        resolveProfileAccentOnSolidHex(appearance.accentColor),
    );
    el.style.setProperty('--profile-page-bg', pageBg);
    el.style.backgroundColor = pageBg;
}

