};

export { subscribeProfileWarmCache } from '@/app/services/profile/profileWarmCacheStore';

const inflight = new Map<string, Promise<LawyerProfileData | null>>();

/**
 * يملأ الكاش الدافئ متزامناً من التخزين المحلي أو بذرة الاسم من الجلسة —
 * قبل fetchLawyerProfile/async getProfile.
 */
export function hydrateProfileWarmCachePeekSync(
    userId?: string | null,
    userMeta?: Record<string, unknown> | null,
    viewerId?: string | null,
): LawyerProfileData | null {
    const uid = userId?.trim();
    if (!uid || typeof window === 'undefined') return null;

    const viewer = viewerId?.trim() || uid;
    const existing = peekProfileWarmCache(uid);
    const local = viewer === uid ? readLocalProfileSync(uid) : null;

    if (local) {
        const resolved =
            resolveFirstPaintLawyerDisplayName(local.header?.name, uid, userMeta ?? {}).trim() ||
            local.header?.name?.trim() ||
            '';
        const mergedName = preferRicherLawyerDisplayName(existing?.header?.name ?? '', resolved);
        const next: LawyerProfileData = {
            ...local,
            header: { ...local.header, name: mergedName || local.header.name },
        };
        setProfileWarmCache(uid, next);
        return peekProfileWarmCache(uid) ?? next;
    }

    const localUnread = viewer === uid && isLawyerProfileLocalUnread(uid);
    const warmPending = viewer === uid && isLawyerProfileBootWarmPending();
    const hasLocalRecord = viewer === uid && lawyerProfileLocalRecordExists(uid);

    if (localUnread || warmPending || hasLocalRecord) {
        return existing ?? null;
    }

    if (existing?.header?.name?.trim() && viewer === uid) {
        const name = resolveFirstPaintLawyerDisplayName(existing.header?.name, uid, userMeta ?? {}).trim();
        if (name && name !== existing.header?.name?.trim()) {
            const enriched: LawyerProfileData = {
                ...existing,
                header: { ...existing.header, name },
            };
            setProfileWarmCache(uid, enriched);
            return peekProfileWarmCache(uid) ?? enriched;
        }
        return existing;
    }

    if (viewer !== uid) return null;

    /* بلا ملف محلي: بذرة الاسم والصورة من الجلسة/الهوية — لا حقل JWT القصير `name`. */
    const name = resolveFirstPaintLawyerDisplayName(undefined, uid, userMeta ?? {}).trim();
    if (!name) return null;

    const metaAvatarRaw =
        userMeta &&
        (typeof userMeta.avatar_url === 'string'
            ? userMeta.avatar_url
            : typeof userMeta.avatarUrl === 'string'
              ? userMeta.avatarUrl
              : typeof userMeta.picture === 'string'
                ? userMeta.picture
                : '');
    const profileImage =
        getUserIdentityUiState(uid)?.avatarUrl ||
        (typeof metaAvatarRaw === 'string' ? sanitizeProfileMediaUrl(metaAvatarRaw) ?? '' : '') ||
        '';

    const stub: LawyerProfileData = {
        ...DEFAULT_LAWYER_PROFILE,
        header: { ...DEFAULT_LAWYER_PROFILE.header, name, profileImage },
        sections: DEFAULT_LAWYER_PROFILE.sections.map((section) => ({ ...section })),
    };
    setProfileWarmCache(uid, stub);
    return peekProfileWarmCache(uid) ?? stub;
}

function writeWarmPreferRich(uid: string, data: LawyerProfileData): LawyerProfileData {
    const existing = peekProfileWarmCache(uid);
    if (
        existing &&
        isProfilePaintReady(existing) &&
        shouldAwaitCloudProfileSettle(data)
    ) {
        return existing;
    }
    setProfileWarmCache(uid, data);
    return peekProfileWarmCache(uid) ?? data;
}

/** تحميل مسبق — لا يُرجع stub شحيح كـ «جاهز» إن وُجد أغنى.
 * لا يكتب كاشاً دافئاً لملف الغير (يمنع تسميم كاش المالك بعرض زائر منقّح).
 */
export function warmProfileDataCache(
    userId?: string | null,
    viewerId?: string | null,
): Promise<LawyerProfileData | null> {
    const uid = userId?.trim();
    if (!uid || typeof window === 'undefined') return Promise.resolve(null);

    const existing = peekProfileWarmCache(uid);
    if (existing && isProfilePaintReady(existing)) {
        return Promise.resolve(existing);
    }

    const pending = inflight.get(uid);
    if (pending) return pending.catch(() => null);

    const run = import('@/app/services/auth/lawyerAccountStatus')
        .then(async ({ canUseServerBackedNetworkFeatures }): Promise<LawyerProfileData | null> => {
            if (!canUseServerBackedNetworkFeatures(uid)) {
                return peekProfileWarmCache(uid) ?? null;
            }
            const m = await import('@/app/services/cloud/lawyerProfileCloud');
            const data = await m.ProfileDB.getProfile(uid, viewerId);
            let viewer = viewerId?.trim() || '';
            if (!viewer) {
                try {
                    viewer = (await m.resolveSessionProfileUserId())?.trim() || '';
                } catch {
                    viewer = '';
                }
            }
            if (!viewer || viewer !== uid) {
                /* زائر أو جلسة مجهولة — لا تُسمّم كاش المالك بعرض منقّح */
                return data ?? null;
            }
            if (!data) return peekProfileWarmCache(uid) ?? null;
            return writeWarmPreferRich(uid, data);
        })
        .finally(() => {
            inflight.delete(uid);
        });

    inflight.set(uid, run);
    return run.catch(() => null);
}

export function prefetchProfileData(userId?: string | null): void {
    void warmProfileDataCache(userId).catch(() => undefined);
}

function waitForProfileUpdated(userId: string, timeoutMs: number): Promise<void> {
    if (typeof window === 'undefined') return Promise.resolve();
    return new Promise((resolve) => {
        let settled = false;
        const finish = () => {
            if (settled) return;
            settled = true;
            if (typeof window === 'undefined') {
                resolve();
                return;
            }
            try {
                window.clearTimeout(timer);
            } catch {
                /* jsdom teardown */
            }
            try {
                window.removeEventListener(LAWYER_PROFILE_UPDATED, onUpdated);
            } catch {
                /* jsdom teardown */
            }
            resolve();
        };
        const onUpdated = (e: Event) => {
            const uid = (e as CustomEvent<{ userId?: string }>).detail?.userId?.trim();
            if (uid && uid === userId) finish();
        };
        const timer = window.setTimeout(finish, timeoutMs);
        window.addEventListener(LAWYER_PROFILE_UPDATED, onUpdated);
    });
}

/**
 * يضمن بيانات قابلة للرسم قبل كشف التبويب — إطار واحد نظيف بلا وميض بذرة.
 * إن بقي الملف فارغاً فعلياً بعد المهلة يُعاد stub مستقر للعرض مرة واحدة.
 */
export async function ensureProfilePaintReady(
    userId?: string | null,
    timeoutMs = 480,
): Promise<LawyerProfileData | null> {
    const uid = userId?.trim();
    if (!uid || typeof window === 'undefined') return null;

    const peekReady = () => {
        const p = peekProfileWarmCache(uid);
        return isProfilePaintReady(p) ? p! : null;
    };

    const hit = peekReady();
    if (hit) return hit;

    const data = await warmProfileDataCache(uid);
    const afterWarm = peekReady();
    if (afterWarm) return afterWarm;

    // السحابة قد تُكمّل بعد getProfile المحلي
    void import('@/app/services/cloud/lawyerProfileCloud')
        .then((m) => m.ProfileDB.getProfile(uid))
        .catch(() => undefined);
    await waitForProfileUpdated(uid, timeoutMs);

    const afterCloud = peekReady();
    if (afterCloud) return afterCloud;

    /* لا تكتب حمولة منقّحة/مجهولة في الكاش الدافئ */
    return peekProfileWarmCache(uid) ?? data;
}

import type { LawyerProfileData } from '@/app/services/profile/profileTypes';
import { sanitizeLawyerProfile } from '@/app/services/profileSanitizer';
import { redactProfileForVisitorView } from '@/app/services/profile/profileVisitorView';
import {
    deleteProfileWarmCacheRaw,
    getProfileWarmCacheRaw,
    hasProfileWarmCacheRaw,
    setProfileWarmCacheRaw,
} from '@/app/services/profile/profileWarmCacheStore';

export type ProfileWarmCachePeekOptions = {
    viewerId?: string | null;
};

function resolveWarmCacheEntry(
    userId: string,
    raw: LawyerProfileData,
    options?: ProfileWarmCachePeekOptions,
): LawyerProfileData {
    /* بلا options = مسار المالك الداخلي؛ مع options: لا تفتح الحمولة إلا لمشاهد = المالك */
    if (!options) return raw;
    const viewer = options.viewerId?.trim();
    if (viewer && viewer === userId.trim()) return raw;
    return redactProfileForVisitorView(raw);
}

export function peekProfileWarmCache(
    userId: string,
    options?: ProfileWarmCachePeekOptions,
): LawyerProfileData | undefined {
    const uid = userId.trim();
    const raw = getProfileWarmCacheRaw(uid);
    if (!raw) return undefined;
    return resolveWarmCacheEntry(uid, raw, options);
}

export function setProfileWarmCache(userId: string, data: LawyerProfileData): void {
    setProfileWarmCacheRaw(userId, sanitizeLawyerProfile(data));
}

export function invalidateProfileWarmCache(userId?: string): void {
    deleteProfileWarmCacheRaw(userId);
}

export function hasProfileWarmCache(userId: string): boolean {
    return hasProfileWarmCacheRaw(userId);
}

import type { LawyerProfileData } from '@/app/services/cloud/lawyerProfileTypes';

const cache = new Map<string, LawyerProfileData>();
const listeners = new Set<(userId: string) => void>();

function notifyWarmCache(userId: string): void {
    listeners.forEach((fn) => {
        try {
            fn(userId);
        } catch {
            /* ignore */
        }
    });
}

/** يُخطر غطاء الفتح عندما يمتلئ الكاش بعد أول إطار */
export function subscribeProfileWarmCache(listener: (userId: string) => void): () => void {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}

/** قراءة خام للكاش — بلا sanitizer/visitor. الهيدر يحتاج الصورة/الاسم فقط. */
export function getProfileWarmCacheRaw(userId: string): LawyerProfileData | undefined {
    const uid = userId.trim();
    if (!uid) return undefined;
    return cache.get(uid);
}

export function setProfileWarmCacheRaw(userId: string, data: LawyerProfileData): void {
    const uid = userId.trim();
    if (!uid) return;
    cache.set(uid, data);
    notifyWarmCache(uid);
}

export function deleteProfileWarmCacheRaw(userId?: string): void {
    if (userId?.trim()) cache.delete(userId.trim());
    else cache.clear();
}

export function hasProfileWarmCacheRaw(userId: string): boolean {
    const uid = userId.trim();
    return Boolean(uid) && cache.has(uid);
}

/** يمنع كتابة ملف محامٍ آخر — defense-in-depth مع kv-proxy ownership */
export class ProfileWriteForbiddenError extends Error {
    constructor(message = 'profile-write-forbidden') {
        super(message);
        this.name = 'ProfileWriteForbiddenError';
    }
}

export function assertCanWriteProfile(writerId: string | null | undefined, targetUserId: string): void {
    const writer = writerId?.trim();
    const target = targetUserId?.trim();
    if (!writer || !target) {
        throw new ProfileWriteForbiddenError('profile-write-unauthorized');
    }
    if (writer !== target) {
        throw new ProfileWriteForbiddenError();
    }
}

import { resolveProfileHeaderInitial } from '@/app/services/profile/profileHeaderLogic';
import { hydrateProfileWarmCachePeekSync } from '@/app/services/profile/profileWarmCache';
import { getProfileWarmCacheRaw } from '@/app/services/profile/profileWarmCacheStore';
import { isLawyerProfileBootWarmPending } from '@/app/services/profile/profileBootWarmPending';
import { isLawyerProfileLocalUnread } from '@/app/services/profile/lawyerProfileLocalRead';
import { sanitizeProfileMediaUrl } from '@/app/services/profile/profileUrlSanitize';
import { resolveFirstPaintLawyerDisplayName } from '@/app/services/profile/resolveLawyerDisplayName';
import {
    getUserIdentityUiState,
    mergeUserIdentityUiState,
    type UserIdentityUiState,
} from '@/app/services/profile/userIdentityUiState';

export type ForumTileProfileChrome = {
    displayName: string;
    profileInitial: string;
    avatarUrl: string;
    showInitial: boolean;
    /** مطابق UserIdentityUiState.isLoaded */
    isLoaded: boolean;
};

function avatarFromSessionMetadata(
    userMetadata?: Record<string, unknown> | null,
): string {
    if (!userMetadata) return '';
    const raw = userMetadata.avatar_url ?? userMetadata.avatarUrl ?? userMetadata.picture;
    return typeof raw === 'string' ? sanitizeProfileMediaUrl(raw) ?? '' : '';
}

function toChrome(state: UserIdentityUiState): ForumTileProfileChrome {
    return {
        displayName: state.displayName,
        profileInitial: state.profileInitial,
        avatarUrl: state.avatarUrl,
        /* الحرف الذهبي يقرره الربع الحي عند التسوية — لا من الكروم أثناء وجود userId */
        showInitial: state.isLoaded && !state.avatarUrl && state.userId === 'anon',
        isLoaded: state.isLoaded,
    };
}

/**
 * مصدر واحد لكروم ربع الملف — يفضّل التجميد الذرّي إن وُجد،
 * وإلا يبني لقطة ويُحدّث المتجر دون تفريغ الاسم أثناء التسخين.
 */
export function resolveForumTileProfileChrome(
    userId?: string | null,
    userMetadata?: Record<string, unknown> | null,
): ForumTileProfileChrome {
    const uid = userId?.trim();
    const frozen = uid ? getUserIdentityUiState(uid) : null;
    if (frozen?.isLoaded) {
        return toChrome(frozen);
    }

    if (uid) {
        hydrateProfileWarmCachePeekSync(uid, userMetadata ?? undefined, uid);
    }
    const cached = uid ? getProfileWarmCacheRaw(uid) : undefined;
    const cachedName = cached?.header?.name;
    const avatarUrl =
        sanitizeProfileMediaUrl(cached?.header?.profileImage) ||
        sanitizeProfileMediaUrl(frozen?.avatarUrl) ||
        avatarFromSessionMetadata(userMetadata) ||
        '';
    const displayName =
        resolveFirstPaintLawyerDisplayName(cachedName, uid, userMetadata ?? undefined) ||
        frozen?.displayName ||
        (!uid ? 'المحامي' : '');
    const profileInitial = resolveProfileHeaderInitial(displayName || frozen?.profileInitial || 'م');
    const warmPending = isLawyerProfileBootWarmPending();
    const localUnread = Boolean(uid && isLawyerProfileLocalUnread(uid));

    if (!uid) {
        return {
            displayName,
            profileInitial: resolveProfileHeaderInitial(displayName || 'المحامي'),
            avatarUrl: '',
            showInitial: !avatarUrl,
            isLoaded: true,
        };
    }

    /* أثناء التسخين: احتفظ بالاسم/الصورة المعروفين — لا تُفرّغ الحقول ثم تملأها */
    const snapshot = mergeUserIdentityUiState({
        userId: uid,
        displayName,
        avatarUrl,
        profileInitial,
        /* بعد التسخين: الحساب الجديد بلا اسم جاهز للحرف — لا يُعلَّق «جاري التحميل» إلى الأبد */
        isLoaded: !warmPending && !localUnread,
    });

    return toChrome(snapshot);
}

import { DEV_MOCK_LAWYER_NAME, GUEST_LAWYER_ID } from '@/app/utils/guestLawyerSession';
import { sanitizeProfilePlainText } from '@/app/services/profile/profileUrlSanitize';

const STALE_PLACEHOLDER_NAMES = new Set(['', 'المحامي', 'محامٍ', 'محامٍ تجريبي', 'محامي تجريبي']);

function readStringField(meta: Record<string, unknown>, key: string): string {
    const value = meta[key];
    return typeof value === 'string' ? value.trim() : '';
}

function pickLongestName(values: string[]): string {
    let best = '';
    for (const value of values) {
        if (value.length > best.length) best = value;
    }
    return best;
}

/** طيّ أشكال الألف/التاء حتى لا تُعتبر «احمد» و«أحمد مهدي» اسمين مختلفين. */
export function foldArabicIdentityLetters(value: string): string {
    return value
        .replace(/[أإآٱ]/g, 'ا')
        .replace(/ة/g, 'ه')
        .replace(/ى/g, 'ي')
        .replace(/\s+/g, ' ')
        .trim();
}

/** بادئة بعد طيّ الهمزة — «احمد» تكمل إلى «أحمد مهدي» دون استبدال باسم أجنبي */
export function isNamePrefixEnrichment(current: string, next: string): boolean {
    const a = foldArabicIdentityLetters(current);
    const b = foldArabicIdentityLetters(next);
    if (!a || !b) return false;
    return b.startsWith(a) || a.startsWith(b);
}

function readCompleteMetadataName(meta?: Record<string, unknown>): string {
    if (!meta) return '';
    const given = readStringField(meta, 'given_name') || readStringField(meta, 'first_name');
    const family = readStringField(meta, 'family_name') || readStringField(meta, 'last_name');
    const composed = [given, family].filter(Boolean).join(' ').trim();
    return pickLongestName([
        readStringField(meta, 'fullName'),
        readStringField(meta, 'full_name'),
        composed,
    ]);
}

function readMetadataName(meta?: Record<string, unknown>): string {
    if (!meta) return '';
    const named = [
        readStringField(meta, 'fullName'),
        readStringField(meta, 'full_name'),
        readStringField(meta, 'name'),
        readStringField(meta, 'displayName'),
    ];
    const given = readStringField(meta, 'given_name') || readStringField(meta, 'first_name');
    const family = readStringField(meta, 'family_name') || readStringField(meta, 'last_name');
    const composed = [given, family].filter(Boolean).join(' ').trim();
    return pickLongestName([...named, composed]);
}

/**
 * يثبّت الاسم الظاهر: لا نرجع من كامل إلى بادئة أقصر (أحمد ← أحمد مهدي).
 * التغيير الحقيقي (اسم مختلف تماماً) يُطبَّق.
 */
function publicLawyerDisplayName(raw: string, fallback = ''): string {
    return sanitizeProfilePlainText(raw, 80).trim() || fallback;
}

export function preferRicherLawyerDisplayName(current: string, next: string): string {
    const a = current.trim();
    const b = next.trim();
    if (!b) return a;
    if (!a || STALE_PLACEHOLDER_NAMES.has(a)) return b;
    if (STALE_PLACEHOLDER_NAMES.has(b)) return a;
    if (a === b) return a;
    if (isNamePrefixEnrichment(a, b)) {
        return a.length >= b.length ? a : b;
    }
    return b;
}

/** اسم العرض في الهيدر والملف — يفضّل بيانات الجلسة التجريبية على الأسماء القديمة المحفوظة محلياً */
export function resolveLawyerDisplayName(
    profileName: string | undefined,
    userId?: string | null,
    meta?: Record<string, unknown>,
): string {
    const trimmedProfile = profileName?.trim() ?? '';
    const metaName = readMetadataName(meta);

    if (userId === GUEST_LAWYER_ID) {
        if (STALE_PLACEHOLDER_NAMES.has(trimmedProfile)) {
            return publicLawyerDisplayName(metaName, DEV_MOCK_LAWYER_NAME);
        }
    }

    if (trimmedProfile && metaName) {
        if (isNamePrefixEnrichment(trimmedProfile, metaName)) {
            return publicLawyerDisplayName(preferRicherLawyerDisplayName(trimmedProfile, metaName), trimmedProfile);
        }
    }
    if (trimmedProfile) return publicLawyerDisplayName(trimmedProfile, userId === GUEST_LAWYER_ID ? DEV_MOCK_LAWYER_NAME : 'المحامي');
    if (metaName) return publicLawyerDisplayName(metaName, userId === GUEST_LAWYER_ID ? DEV_MOCK_LAWYER_NAME : 'المحامي');
    return userId === GUEST_LAWYER_ID ? DEV_MOCK_LAWYER_NAME : 'المحامي';
}

/**
 * اسم أول طلاء — الملف المحلي أو إغناء بادئة من الاسم الكامل في الجلسة.
 * لا يُستبدل اسم محفوظ باسم جلسة مختلف، ولا يُستخدم حقل `name` القصير وحده.
 */
export function resolveFirstPaintLawyerDisplayName(
    profileName: string | undefined,
    userId?: string | null,
    meta?: Record<string, unknown>,
): string {
    const trimmedProfile = profileName?.trim() ?? '';
    const complete = readCompleteMetadataName(meta);
    if (trimmedProfile && !STALE_PLACEHOLDER_NAMES.has(trimmedProfile)) {
        if (complete) {
            if (isNamePrefixEnrichment(trimmedProfile, complete)) {
                return publicLawyerDisplayName(
                    preferRicherLawyerDisplayName(trimmedProfile, complete),
                    trimmedProfile,
                );
            }
            return publicLawyerDisplayName(trimmedProfile);
        }
        const sessionShort = meta ? readStringField(meta, 'name') : '';
        if (
            sessionShort &&
            (trimmedProfile === sessionShort ||
                foldArabicIdentityLetters(trimmedProfile) === foldArabicIdentityLetters(sessionShort))
        ) {
            return '';
        }
        return publicLawyerDisplayName(trimmedProfile);
    }
    if (complete) return publicLawyerDisplayName(complete);
    if (userId === GUEST_LAWYER_ID) return DEV_MOCK_LAWYER_NAME;
    return '';
}

import { profileMediaIdentity } from '@/app/services/profile/profileMediaIdentity';

/** فوق هذا الطول يُفضَّل تصغير data: قبل وضعه في <img> */
export const PROFILE_AVATAR_INLINE_HEAVY_CHARS = 12_000;

/** بلاط المنتدى (~90px @2–3×) */
export const PROFILE_AVATAR_DISPLAY_MAX_EDGE_TILE = 256;

/** افتراضي للصور الشخصية المضغوطة للعرض */
export const PROFILE_AVATAR_DISPLAY_MAX_EDGE_DEFAULT = 384;

const JPEG_QUALITY = 0.88;
const MAX_CACHE = 24;

type CacheEntry = {
    edge: number;
    url: string;
    blobUrl: boolean;
};

const cache = new Map<string, CacheEntry>();
const inflight = new Map<string, Promise<string>>();

function cacheKey(src: string, maxEdge: number): string {
    return `${profileMediaIdentity(src)}@${maxEdge}`;
}

function remember(key: string, entry: CacheEntry): void {
    if (cache.size >= MAX_CACHE) {
        const oldest = cache.keys().next().value;
        if (oldest) {
            const prev = cache.get(oldest);
            if (prev?.blobUrl) {
                try {
                    URL.revokeObjectURL(prev.url);
                } catch {
                    /* ignore */
                }
            }
            cache.delete(oldest);
        }
    }
    cache.set(key, entry);
}

export function peekProfileAvatarDisplaySrc(
    src: string,
    maxEdge: number = PROFILE_AVATAR_DISPLAY_MAX_EDGE_DEFAULT,
): string | null {
    const url = src.trim();
    if (!url || maxEdge <= 0 || !shouldDownscaleProfileAvatarSrc(url)) return url || null;
    return cache.get(cacheKey(url, maxEdge))?.url ?? null;
}

export function shouldDownscaleProfileAvatarSrc(src: string): boolean {
    const url = src.trim();
    return url.startsWith('data:') && url.length > PROFILE_AVATAR_INLINE_HEAVY_CHARS;
}

async function downscaleDataUrl(src: string, maxEdge: number): Promise<string> {
    const response = await fetch(src);
    const blob = await response.blob();

    let bitmap: ImageBitmap | null = null;
    let sourceW = 0;
    let sourceH = 0;
    let draw: ((ctx: CanvasRenderingContext2D, w: number, h: number) => void) | null = null;

    if (typeof createImageBitmap === 'function') {
        try {
            bitmap = await createImageBitmap(blob, { imageOrientation: 'from-image' });
            sourceW = bitmap.width;
            sourceH = bitmap.height;
            const bmp = bitmap;
            draw = (ctx, w, h) => {
                ctx.drawImage(bmp, 0, 0, w, h);
            };
        } catch {
            bitmap = null;
        }
    }

    if (!draw) {
        const objectUrl = URL.createObjectURL(blob);
        try {
            const image = await new Promise<HTMLImageElement>((resolve, reject) => {
                const img = new Image();
                img.onload = () => resolve(img);
                img.onerror = () => reject(new Error('avatar decode failed'));
                img.src = objectUrl;
            });
            sourceW = image.naturalWidth || image.width;
            sourceH = image.naturalHeight || image.height;
            draw = (ctx, w, h) => {
                ctx.drawImage(image, 0, 0, w, h);
            };
        } finally {
            URL.revokeObjectURL(objectUrl);
        }
    }

    if (!sourceW || !sourceH || !draw) {
        bitmap?.close();
        return src;
    }

    const ratio = Math.min(1, maxEdge / Math.max(sourceW, sourceH));
    if (ratio >= 1) {
        bitmap?.close();
        return URL.createObjectURL(blob);
    }
    const w = Math.max(1, Math.round(sourceW * ratio));
    const h = Math.max(1, Math.round(sourceH * ratio));
    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');
    if (!ctx) {
        bitmap?.close();
        return src;
    }
    ctx.imageSmoothingEnabled = true;
    ctx.imageSmoothingQuality = 'medium';
    draw(ctx, w, h);
    bitmap?.close();

    const outBlob = await new Promise<Blob | null>((resolve) => {
        canvas.toBlob((b) => resolve(b), 'image/jpeg', JPEG_QUALITY);
    });
    if (!outBlob) return src;
    return URL.createObjectURL(outBlob);
}

/**
 * يعيد مصدراً خفيفاً للعرض (blob: مصغّر) لـ data:JPEG الثقيل.
 * الروابط الشبكية والصغيرة تُمرَّر كما هي.
 */
export async function resolveProfileAvatarDisplaySrc(
    src: string,
    maxEdge: number = PROFILE_AVATAR_DISPLAY_MAX_EDGE_DEFAULT,
): Promise<string> {
    const url = src.trim();
    if (!url || maxEdge <= 0 || !shouldDownscaleProfileAvatarSrc(url)) return url;

    const key = cacheKey(url, maxEdge);
    const hit = cache.get(key);
    if (hit) return hit.url;

    const pending = inflight.get(key);
    if (pending) return pending;

    const work = downscaleDataUrl(url, maxEdge)
        .then((resolved) => {
            const blobUrl = resolved.startsWith('blob:');
            remember(key, { edge: maxEdge, url: resolved, blobUrl });
            return resolved;
        })
        .catch(() => url)
        .finally(() => {
            inflight.delete(key);
        });

    inflight.set(key, work);
    return work;
}

/** تسخين كسول لكاش العرض — لا يفكّ data: الكامل في Image() على خيط الإقلاع */
export function warmProfileAvatarDisplaySrc(
    src: string | undefined,
    maxEdge: number = PROFILE_AVATAR_DISPLAY_MAX_EDGE_DEFAULT,
): void {
    if (typeof window === 'undefined') return;
    const url = src?.trim() ?? '';
    if (!shouldDownscaleProfileAvatarSrc(url)) return;
    const key = cacheKey(url, maxEdge);
    if (cache.has(key) || inflight.has(key)) return;

    const start = () => {
        void resolveProfileAvatarDisplaySrc(url, maxEdge);
    };

    if (typeof requestIdleCallback === 'function') {
        requestIdleCallback(start, { timeout: 1_800 });
        return;
    }
    window.setTimeout(start, 0);
}

export function resetProfileAvatarDisplayCacheForTests(): void {
    for (const entry of cache.values()) {
        if (entry.blobUrl) {
            try {
                URL.revokeObjectURL(entry.url);
            } catch {
                /* ignore */
            }
        }
    }
    cache.clear();
    inflight.clear();
}

import type { ProfilePageCustomization } from '@/app/services/profile/profilePageCustomization';

/** يعيد كتلة محذوفة إلى المسودة الحالية دون مسح تعديلات متزامنة أخرى */
export function restoreRemovedCustomBlock(
    current: ProfilePageCustomization,
    previous: ProfilePageCustomization,
    blockId: string,
): ProfilePageCustomization {
    if (current.customBlocks.some((block) => block.id === blockId)) return current;
    const removed = previous.customBlocks.find((block) => block.id === blockId);
    if (!removed) return current;
    const at = previous.customBlocks.findIndex((block) => block.id === blockId);
    const customBlocks = [...current.customBlocks];
    const insertAt = Math.min(Math.max(at < 0 ? customBlocks.length : at, 0), customBlocks.length);
    customBlocks.splice(insertAt, 0, removed);
    return { ...current, customBlocks };
}

/**
 * مصدر حقيقة واحد لهوية الواجهة على المنزل — ذرّي غير قابل للتجزئة.
 * الاسم والصورة والحرف يُنشران معاً؛ ممنوع تحديث الاسم بلا صورة أو العكس.
 */
import { sanitizeProfileMediaUrl, sanitizeProfilePlainText } from '@/app/services/profile/profileUrlSanitize';
import { preferRicherLawyerDisplayName } from '@/app/services/profile/resolveLawyerDisplayName';

export type UserIdentityUiState = {
    userId: string;
    displayName: string;
    avatarUrl: string;
    profileInitial: string;
    /** true = جاهز للرسم الكامل (تحت الغطاء أو بعده) */
    isLoaded: boolean;
};

type Listener = (state: UserIdentityUiState | null) => void;

let freeze: UserIdentityUiState | null = null;
const listeners = new Set<Listener>();

function safeAvatarUrl(raw: string | undefined): string {
    return sanitizeProfileMediaUrl(raw) ?? '';
}

function normalizeIdentity(next: UserIdentityUiState): UserIdentityUiState {
    const avatarUrl = safeAvatarUrl(next.avatarUrl);
    const displayName = sanitizeProfilePlainText(next.displayName, 80);
    const profileInitial = sanitizeProfilePlainText(next.profileInitial, 4) || 'م';
    if (
        avatarUrl === next.avatarUrl &&
        displayName === next.displayName &&
        profileInitial === next.profileInitial
    ) {
        return next;
    }
    return { ...next, avatarUrl, displayName, profileInitial };
}

export function isSameUserIdentity(
    a: UserIdentityUiState | null | undefined,
    b: UserIdentityUiState | null | undefined,
): boolean {
    if (!a || !b) return a === b;
    return (
        a.userId === b.userId &&
        a.displayName === b.displayName &&
        a.avatarUrl === b.avatarUrl &&
        a.profileInitial === b.profileInitial &&
        a.isLoaded === b.isLoaded
    );
}

export function getUserIdentityUiState(userId?: string | null): UserIdentityUiState | null {
    const uid = userId?.trim();
    if (!freeze) return null;
    if (uid && freeze.userId !== uid) return null;
    return freeze;
}

export function publishUserIdentityUiState(next: UserIdentityUiState): void {
    const normalized = normalizeIdentity(next);
    const prev = freeze;
    if (isSameUserIdentity(prev, normalized)) {
        return;
    }
    freeze = normalized;
    listeners.forEach((fn) => {
        try {
            fn(normalized);
        } catch {
            /* ignore */
        }
    });
}

/** دمج أغنى — لا يُرجع للأسوأ ولا يفرّغ حقلاً كان ممتلئاً إلا عند isLoaded صريح ببيانات كاملة */
export function mergeUserIdentityUiState(
    next: Omit<UserIdentityUiState, 'isLoaded'> & { isLoaded?: boolean },
): UserIdentityUiState {
    const prev = freeze?.userId === next.userId ? freeze : null;
    const incomingName = sanitizeProfilePlainText(next.displayName, 80).trim();
    const displayName = preferRicherLawyerDisplayName(prev?.displayName ?? '', incomingName);
    const avatarUrl =
        safeAvatarUrl(next.avatarUrl) ||
        safeAvatarUrl(prev?.avatarUrl) ||
        '';
    const profileInitial =
        sanitizeProfilePlainText(next.profileInitial, 4).trim() ||
        prev?.profileInitial ||
        'م';
    const isLoaded =
        next.isLoaded === true || (Boolean(prev?.isLoaded) && next.isLoaded !== false);
    const merged: UserIdentityUiState = {
        userId: next.userId,
        displayName,
        avatarUrl,
        profileInitial,
        isLoaded,
    };
    publishUserIdentityUiState(merged);
    return merged;
}

export function subscribeUserIdentityUiState(listener: Listener): () => void {
    listeners.add(listener);
    return () => {
        listeners.delete(listener);
    };
}

/** يصفّر التجميد عند تبديل الحساب — المستمعون يبقون */
export function resetUserIdentityUiState(): void {
    freeze = null;
    listeners.forEach((fn) => {
        try {
            fn(null);
        } catch {
            /* ignore */
        }
    });
}

export function resetUserIdentityUiStateForTests(): void {
    resetUserIdentityUiState();
    listeners.clear();
}

/**
 * تسخين ملف المحامي المحلي قبل بذرة Frame-1.
 * المفتاح per-user ومشفّر — `getItemSync` تُرجع null ما دام `decryptedCache` بارداً.
 * سقف المستدعي فشل أمان إن علِق IndexedDB — ليس ميزانية النجاح المعتادة.
 */
import {
    setLawyerProfileBootWarmPending,
    BOOT_PROFILE_WARM_BUDGET_MS,
} from '@/app/services/profile/profileBootWarmPending';

export { BOOT_PROFILE_WARM_BUDGET_MS };

type BootProfileStore = {
    kickoffBootShellSync?: () => void;
    warmKeys: (keys: readonly string[]) => Promise<void>;
};

export async function warmBootLawyerProfile(store: BootProfileStore): Promise<void> {
    store.kickoffBootShellSync?.();
    setLawyerProfileBootWarmPending(true);
    try {
        const { peekBootSessionUserIdSync } = await import('@/boot/peekBootSessionUserId');
        const uid = peekBootSessionUserIdSync()?.trim();
        if (!uid) return;

        const { getLawyerProfileLocalKey } = await import('@/app/services/profile/profileLocalKey');
        await store.warmKeys([getLawyerProfileLocalKey(uid)]);
    } finally {
        setLawyerProfileBootWarmPending(false);
    }
}

import SecureStoreService from '@/app/services/SecureStoreService';
import { isKvProxyNetworkEnabled } from '@/app/services/kvProxyConfig';
import { SecureAPIClient, getCurrentAccessToken } from '@/app/services/SecureAPIClient';

const KV_PROXY_URL = '/api/kv-proxy';
const LOCAL_PREFIX = 'hami:push-subscription:';

const kv = {
    async set(key: string, value: unknown) {
        if (!isKvProxyNetworkEnabled()) throw new Error('kv_local_only');
        const token = await getCurrentAccessToken();
        if (!token) throw new Error('kv_local_only');
        await SecureAPIClient.fetchSecure(KV_PROXY_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ action: 'set', key, value }),
        });
    },
};

export async function savePushSubscription(lawyerId: string, subscription: unknown): Promise<void> {
    if (!lawyerId) return;
    try {
        await kv.set(`hami:push:${lawyerId}`, {
            subscription,
            updatedAt: new Date().toISOString(),
        });
    } catch {
        await SecureStoreService.setItem(`${LOCAL_PREFIX}${lawyerId}`, JSON.stringify(subscription));
    }
}

/**
 * يوقف polling السحابة عند وجود قنوات Realtime نشطة — يوفر شبكة وبطارية.
 */
let subscribedRealtimeChannels = 0;

export function notifyRealtimeChannelSubscribed(): void {
    subscribedRealtimeChannels += 1;
}

export function notifyRealtimeChannelClosed(): void {
    subscribedRealtimeChannels = Math.max(0, subscribedRealtimeChannels - 1);
}

export function resetRealtimeSyncGate(): void {
    subscribedRealtimeChannels = 0;
}

export function isCloudPollingPausedByRealtime(): boolean {
    return subscribedRealtimeChannels > 0;
}

export function getActiveRealtimeChannelCount(): number {
    return subscribedRealtimeChannels;
}

