import type { FileData, CaseStage } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile, GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { DossierKind } from './repositoryDossierRegistry';
import type { DossierNoteRef } from './repositoryDossierNotes';
import { stripRepositoryHtml } from './stripRepositoryHtml';

type ParsedDossierNoteId = {
    kind: DossierKind;
    dossierId: string;
    noteId: string;
};

export function parseDossierNoteRefId(id: string): ParsedDossierNoteId | null {
    const parts = id.split(':');
    if (parts.length < 3) return null;
    const kind = parts[0];
    if (kind !== 'lawsuit' && kind !== 'execution') return null;
    return {
        kind,
        dossierId: parts[1] ?? '',
        noteId: parts.slice(2).join(':'),
    };
}

export function resolveDossierNoteBody(
    ref: DossierNoteRef,
    lawsuitFiles: FileData[],
    executionFiles: ExecutionFile[],
): string {
    const parsed = parseDossierNoteRefId(ref.id);
    if (!parsed) return ref.excerpt;

    if (parsed.kind === 'lawsuit') {
        const file = lawsuitFiles.find((f) => String(f.id) === parsed.dossierId);
        const note = file?.notes?.find((n) => String(n.id) === parsed.noteId);
        if (note?.text) return String(note.text);

        const stages = Array.isArray(file?.stages) ? file!.stages! : [];
        for (const stage of stages) {
            const event = stage.timeline?.find((e) => e.id === parsed.noteId && e.type === 'note');
            if (event?.details) return String(event.details);
        }
        return ref.excerpt;
    }

    const file = executionFiles.find((f) => String(f.id) === parsed.dossierId);
    const caseNotesLog = Array.isArray(file?.caseNotesLog)
        ? (file!.caseNotesLog as Array<{ id?: unknown; body?: unknown }>)
        : [];
    const note = caseNotesLog.find((n) => String(n.id) === parsed.noteId);
    return String(note?.body ?? ref.excerpt);
}

export function patchLawsuitDossierNote(
    file: FileData,
    noteId: string,
    patch: { text?: string; meta?: string; isPinned?: boolean; title?: string },
): FileData {
    const notes = Array.isArray(file.notes) ? file.notes : [];
    if (notes.some((n) => String(n.id) === noteId)) {
        return patchLawsuitFileNote(file, noteId, patch);
    }

    const stages = Array.isArray(file.stages) ? file.stages : [];
    const nextStages = stages.map((stage) => ({
        ...stage,
        timeline: (stage.timeline ?? []).map((event) =>
            event.id === noteId && event.type === 'note'
                ? {
                      ...event,
                      title: patch.title ?? patch.meta ?? event.title,
                      details: patch.text ?? event.details,
                  }
                : event,
        ),
    })) as CaseStage[];

    return { ...file, stages: nextStages };
}

function patchLawsuitFileNote(
    file: FileData,
    noteId: string,
    patch: { text?: string; meta?: string; isPinned?: boolean },
): FileData {
    const notes = Array.isArray(file.notes) ? file.notes : [];
    return {
        ...file,
        notes: notes.map((n) =>
            String(n.id) === noteId
                ? {
                      ...n,
                      ...(patch.text !== undefined ? { text: patch.text } : {}),
                      ...(patch.meta !== undefined ? { meta: patch.meta } : {}),
                      ...(patch.isPinned !== undefined ? { isPinned: patch.isPinned } : {}),
                  }
                : n,
        ),
    };
}

export function patchExecutionFileNote(
    file: ExecutionFile,
    noteId: string,
    patch: { title?: string; body?: string; pinned?: boolean },
): ExecutionFile {
    const notes = Array.isArray(file.caseNotesLog) ? file.caseNotesLog : [];
    return {
        ...file,
        caseNotesLog: notes.map((n) =>
            String(n.id) === noteId
                ? {
                      ...n,
                      ...(patch.title !== undefined ? { title: patch.title } : {}),
                      ...(patch.body !== undefined ? { body: patch.body } : {}),
                      ...(patch.pinned !== undefined ? { pinned: patch.pinned } : {}),
                  }
                : n,
        ),
    };
}

export function appendNoteToLawsuitFile(
    file: FileData,
    payload: { title: string; body: string; isPinned?: boolean },
): { file: FileData; noteId: string } {
    const notes = Array.isArray(file.notes) ? file.notes : [];
    const numericId = Date.now();
    const noteId = String(numericId);
    return {
        noteId,
        file: {
            ...file,
            notes: [
                {
                    id: numericId,
                    text: payload.body,
                    meta: payload.title,
                    stageCtx: 'المستودع الذكي',
                    date: new Date().toLocaleDateString('ar-EG'),
                    isPinned: Boolean(payload.isPinned),
                },
                ...notes,
            ],
        },
    };
}

export function appendNoteToExecutionFile(
    file: ExecutionFile,
    payload: { title: string; body: string; pinned?: boolean },
): { file: ExecutionFile; noteId: string } {
    const notes = Array.isArray(file.caseNotesLog) ? file.caseNotesLog : [];
    const noteId = `repo_${Date.now()}`;
    return {
        noteId,
        file: {
            ...file,
            caseNotesLog: [
                {
                    id: noteId,
                    title: payload.title,
                    body: payload.body,
                    createdAt: new Date().toISOString(),
                    pinned: Boolean(payload.pinned),
                },
                ...notes,
            ],
        },
    };
}

export function globalNoteToDossierPayload(note: GlobalNote): {
    title: string;
    body: string;
    isPinned: boolean;
} {
    const plainBody = stripRepositoryHtml(note.body || '');
    return {
        title: note.title?.trim() || 'ملاحظة من المستودع',
        body: note.body?.trim() || plainBody,
        isPinned: Boolean(note.isPinned),
    };
}

export function encodeBoundDossierId(kind: DossierKind, dossierId: string): string {
    return `${kind}:${dossierId}`;
}

export function vaultDocToDossierPayload(doc: {
    title?: string;
    lawyerNote?: string | null;
    aiSummary?: string | null;
}): { title: string; body: string; isPinned: boolean } {
    const body = (doc.lawyerNote || doc.aiSummary || '').trim();
    return {
        title: doc.title?.trim() || 'ملف من المستودع',
        body,
        isPinned: false,
    };
}

export function deleteLawsuitDossierNote(file: FileData, noteId: string): FileData {
    const notes = Array.isArray(file.notes) ? file.notes : [];
    if (notes.some((n) => String(n.id) === noteId)) {
        return {
            ...file,
            notes: notes.filter((n) => String(n.id) !== noteId),
        };
    }

    const stages = Array.isArray(file.stages) ? file.stages : [];
    const nextStages = stages.map((stage) => ({
        ...stage,
        timeline: (stage.timeline ?? []).map((event) =>
            event.id === noteId && event.type === 'note'
                ? { ...event, isDeleted: true as boolean }
                : event,
        ),
    })) as CaseStage[];

    return { ...file, stages: nextStages };
}

export function deleteExecutionDossierNote(file: ExecutionFile, noteId: string): ExecutionFile {
    const notes = Array.isArray(file.caseNotesLog) ? file.caseNotesLog : [];
    const ts = new Date().toISOString();
    return {
        ...file,
        caseNotesLog: notes.map((n) =>
            String(n.id) === noteId ? { ...n, trashedAt: ts } : n,
        ),
    };
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';
import { listLinkableDossiers, type DossierKind } from './repositoryDossierRegistry';
import { stripRepositoryHtml } from './stripRepositoryHtml';

export type DossierNoteRef = {
    id: string;
    dossierId: string;
    dossierKind: DossierKind;
    dossierLabel: string;
    title: string;
    excerpt: string;
    date?: string;
    isPinned?: boolean;
};

function excerptFromBody(body: string, max = 120): string {
    const plain = stripRepositoryHtml(body);
    if (plain.length <= max) return plain;
    return `${plain.slice(0, max)}…`;
}

function collectLawsuitTimelineNotes(file: FileData, dossierLabel: string): DossierNoteRef[] {
    const dossierId = String(file.id);
    const refs: DossierNoteRef[] = [];
    const stages = Array.isArray(file.stages) ? file.stages : [];
    for (const stage of stages) {
        const timeline = Array.isArray(stage.timeline) ? stage.timeline : [];
        for (const event of timeline) {
            if (event.type !== 'note') continue;
            if ((event as { isDeleted?: boolean }).isDeleted) continue;
            const body = String(event.details ?? '').trim();
            if (!body) continue;
            refs.push({
                id: `lawsuit:${dossierId}:${event.id}`,
                dossierId,
                dossierKind: 'lawsuit',
                dossierLabel,
                title: String(event.title ?? 'ملاحظة دعوى').trim() || 'ملاحظة دعوى',
                excerpt: excerptFromBody(body),
                date: event.date,
            });
        }
    }
    return refs;
}

/** يجمع ملاحظات الدعاوى والتنفيذ لعرضها كبطاقات مختصرة في المفكرة */
export function collectDossierNotes(
    lawsuitFiles: FileData[],
    executionFiles: ExecutionFile[],
): DossierNoteRef[] {
    const dossierLabels = new Map(
        listLinkableDossiers(lawsuitFiles, executionFiles).map((d) => [
            `${d.kind}:${d.id}`,
            d.label,
        ]),
    );

    const refs: DossierNoteRef[] = [];
    const seen = new Set<string>();

    for (const file of lawsuitFiles) {
        const dossierId = String(file.id);
        const dossierLabel = dossierLabels.get(`lawsuit:${dossierId}`) ?? `دعوى #${dossierId}`;
        const notes = Array.isArray(file.notes) ? file.notes : [];
        for (const note of notes) {
            const body = String(note.text ?? '').trim();
            if (!body) continue;
            const refId = `lawsuit:${dossierId}:${note.id}`;
            if (seen.has(refId)) continue;
            seen.add(refId);
            refs.push({
                id: refId,
                dossierId,
                dossierKind: 'lawsuit',
                dossierLabel,
                title: String(note.meta ?? note.stageCtx ?? 'ملاحظة دعوى').trim() || 'ملاحظة دعوى',
                excerpt: excerptFromBody(body),
                date: note.date,
                isPinned: note.isPinned,
            });
        }
        for (const timelineRef of collectLawsuitTimelineNotes(file, dossierLabel)) {
            if (seen.has(timelineRef.id)) continue;
            seen.add(timelineRef.id);
            refs.push(timelineRef);
        }
    }

    for (const file of executionFiles) {
        const dossierId = String(file.id);
        const dossierLabel = dossierLabels.get(`execution:${dossierId}`) ?? `تنفيذ #${dossierId}`;
        const notes = Array.isArray(file.caseNotesLog) ? file.caseNotesLog : [];
        for (const note of notes) {
            if (note.trashedAt) continue;
            const body = String(note.body ?? '').trim();
            if (!body) continue;
            refs.push({
                id: `execution:${dossierId}:${note.id}`,
                dossierId,
                dossierKind: 'execution',
                dossierLabel,
                title: String(note.title ?? 'ملاحظة تنفيذ').trim() || 'ملاحظة تنفيذ',
                excerpt: excerptFromBody(body),
                date: note.createdAt,
                isPinned: note.pinned,
            });
        }
    }

    return refs.sort((a, b) => {
        if (a.isPinned && !b.isPinned) return -1;
        if (!a.isPinned && b.isPinned) return 1;
        return (b.date ?? '').localeCompare(a.date ?? '', 'ar');
    });
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';

export type DossierKind = 'lawsuit' | 'execution';

export type DossierPickerOption = {
    id: string;
    kind: DossierKind;
    label: string;
    subtitle: string;
};

function lawsuitLabel(file: FileData): string {
    const meta = file as unknown as Record<string, unknown>;
    const caseNo = String(file.caseNo ?? '').trim();
    const client = String(meta.clientName ?? meta.plaintiff ?? '').trim();
    if (caseNo && client) return `${caseNo} — ${client}`;
    return caseNo || client || `دعوى #${file.id}`;
}

function executionLabel(file: ExecutionFile): string {
    const no = String(file.fileNumber ?? file.case_no ?? file.caseNo ?? '').trim();
    const debtor = String(
        (file as Record<string, unknown>).debtorName ??
            (file as Record<string, unknown>).clientName ??
            '',
    ).trim();
    if (no && debtor) return `${no} — ${debtor}`;
    return no || debtor || `تنفيذ #${file.id}`;
}

/** قائمة الأضابير القابلة للربط من الدعاوى والتنفيذ */
export function listLinkableDossiers(
    lawsuitFiles: FileData[],
    executionFiles: ExecutionFile[],
): DossierPickerOption[] {
    const lawsuit: DossierPickerOption[] = lawsuitFiles.map((f) => ({
        id: String(f.id),
        kind: 'lawsuit' as const,
        label: lawsuitLabel(f),
        subtitle: 'دعوى',
    }));
    const execution: DossierPickerOption[] = executionFiles.map((f) => ({
        id: String(f.id),
        kind: 'execution' as const,
        label: executionLabel(f),
        subtitle: 'تنفيذ',
    }));
    return [...lawsuit, ...execution].sort((a, b) => a.label.localeCompare(b.label, 'ar'));
}

import type { GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import type { RepositoryFeedItem } from '@/app/services/repository/repositoryUnifiedFeed';
import { djb2Hash as hashText } from '@/app/utils/djb2';

type RepositoryFeedBuildInput = {
    globalNotes: GlobalNote[];
    lawsuitFiles: FileData[];
    executionFiles: ExecutionFile[];
    vaultDocs: SmartVaultDoc[];
};

/** توقيع بطاقة عامة — يلتقط كل ما يؤثّر في البناء/الترتيب/العرض/التصفية */
function globalNoteSig(n: RepositoryFeedBuildInput['globalNotes'][number]): string {
    return [
        n.id,
        n.createdAtIso ?? n.date ?? '',
        n.repositoryInboxHidden ? 1 : 0,
        n.isPinned ? 1 : 0,
        n.type ?? '',
        n.attachmentDocId ?? '',
        n.linkedFileId ?? '',
        n.roomId ?? '',
        hashText(n.title ?? ''),
        hashText(n.body ?? ''),
        (n.tags ?? []).join(','),
    ].join(':');
}

/** توقيع محتوى ملف دعوى — ملاحظات + أحداث note داخل مراحل الخط الزمني */
function lawsuitFileSig(file: RepositoryFeedBuildInput['lawsuitFiles'][number]): string {
    const notes = Array.isArray(file.notes) ? file.notes : [];
    const noteParts = notes.map(
        (n) =>
            `${n.id}|${hashText(String(n.text ?? ''))}|${hashText(String(n.meta ?? n.stageCtx ?? ''))}|${n.isPinned ? 1 : 0}|${n.date ?? ''}`,
    );
    const stages = Array.isArray(file.stages) ? file.stages : [];
    const timelineParts: string[] = [];
    for (const stage of stages) {
        const timeline = Array.isArray(stage.timeline) ? stage.timeline : [];
        for (const event of timeline) {
            if (event.type !== 'note') continue;
            timelineParts.push(
                `${event.id}|${hashText(String(event.title ?? ''))}|${hashText(String(event.details ?? ''))}|${event.date ?? ''}|${
                    (event as { isDeleted?: boolean }).isDeleted ? 1 : 0
                }`,
            );
        }
    }
    return `${file.id}#${noteParts.join(',')}#${timelineParts.join(',')}`;
}

/** توقيع محتوى ملف تنفيذ — سجلّ ملاحظات القضية */
function executionFileSig(file: RepositoryFeedBuildInput['executionFiles'][number]): string {
    const notes = Array.isArray(file.caseNotesLog)
        ? (file.caseNotesLog as Array<Record<string, unknown>>)
        : [];
    const noteParts = notes.map(
        (n) =>
            `${String(n.id ?? '')}|${hashText(String(n.title ?? ''))}|${hashText(String(n.body ?? ''))}|${n.pinned ? 1 : 0}|${n.trashedAt ? 1 : 0}|${String(n.createdAt ?? '')}`,
    );
    return `${file.id}#${noteParts.join(',')}`;
}

/** مفتاح جلسة لـ buildRepositoryFeed — يتخطى إعادة البناء عند نفس المدخلات */
export function buildRepositoryFeedCacheKey(input: RepositoryFeedBuildInput): string {
    const notesSig = input.globalNotes.map(globalNoteSig).join('|');
    const lawsuitSig = `${input.lawsuitFiles.length}:${input.lawsuitFiles.map(lawsuitFileSig).join('|')}`;
    const execSig = `${input.executionFiles.length}:${input.executionFiles.map(executionFileSig).join('|')}`;
    const vaultSig = `${input.vaultDocs.length}:${input.vaultDocs
        .map(
            (d) =>
                `${d.id}:${d.updatedAt ?? ''}:${d.boundDossierId ?? ''}:${d.roomId ?? ''}:${hashText(d.title)}:${d.customCategory ?? ''}:${hashText(d.lawyerNote ?? '')}`,
        )
        .join(',')}`;
    return `${notesSig}::${lawsuitSig}::${execSig}::${vaultSig}`;
}

let lastKey = '';
let lastItems: RepositoryFeedItem[] = [];

export function peekRepositoryFeedCache(key: string): RepositoryFeedItem[] | undefined {
    return key === lastKey ? lastItems : undefined;
}

export function setRepositoryFeedCache(key: string, items: RepositoryFeedItem[]): void {
    lastKey = key;
    lastItems = items;
}

export function invalidateRepositoryFeedCache(): void {
    lastKey = '';
    lastItems = [];
}

/** للاختبارات */
export function resetRepositoryFeedCacheForTests(): void {
    invalidateRepositoryFeedCache();
}

/**
 * ميزانيات أداء المستودع — مرجع E2E + Sentry.
 */
export const REPOSITORY_PERF_BUDGET = {
    openToInteractiveMs: {
        target: 2_800,
        ciColdMax: 6_500,
        ciCachedMax: 3_200,
    },
    sentryMetric: 'repository.open_to_interactive_ms',
} as const;

import { debug } from '@/app/utils/debug';
import {
    reportRepositoryOpenToSentry,
    type RepositoryPerfReportContext,
} from '@/app/services/repository/repositorySentryReporting';

const MARK_PREFIX = 'hami:repository:';

type RepositoryPerfPhase = 'open-request' | 'first-paint' | 'interactive';

export function markRepositoryPerfPhase(phase: RepositoryPerfPhase): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark(`${MARK_PREFIX}${phase}`);
    } catch {
        /* ignore */
    }
}

export function clearRepositoryPerfMarks(): void {
    if (typeof performance === 'undefined' || typeof performance.clearMarks !== 'function') return;
    try {
        for (const phase of ['open-request', 'first-paint', 'interactive'] as const) {
            performance.clearMarks(`${MARK_PREFIX}${phase}`);
        }
    } catch {
        /* ignore */
    }
}

/** ms من open-request → interactive (null إذا لم تُسجَّل المرحلتان) */
export function getRepositoryOpenToInteractiveMs(): number | null {
    if (typeof performance === 'undefined') return null;
    const open = performance.getEntriesByName(`${MARK_PREFIX}open-request`, 'mark')[0];
    const interactive = performance.getEntriesByName(`${MARK_PREFIX}interactive`, 'mark')[0];
    if (!open || !interactive) return null;
    return Math.round(interactive.startTime - open.startTime);
}

/** DEV: log — PROD (مع DSN): Sentry breadcrumb + metric */
export function reportRepositoryPerf(context: RepositoryPerfReportContext = {}): void {
    const ms = getRepositoryOpenToInteractiveMs();
    if (ms == null) return;
    if (import.meta.env.DEV) {
        debug.log('[RepositoryPerf] open→interactive', ms, 'ms', context);
    }
    reportRepositoryOpenToSentry(ms, context);
}

import { readSecureJsonRawSync, writeSecureJsonValue } from '@/app/services/storage/syncSecureJson';
import {
    type RepositoryRoom,
    type RepositoryRoomFilter,
    normalizeRoomId,
} from './repositoryRooms';

const PINNED_KEY = 'hami:repository:rooms:pinned:v1';

/** أقصى غرف مثبّتة على الشريط — يبقى مضغوطاً وأنيقاً */
export const REPOSITORY_PINNED_MAX = 5;
/** سقف حماية من بطء التخزين/العرض */
export const REPOSITORY_ROOMS_SOFT_MAX = 80;

function pinnedStorageKey(userId: string): string {
    return `${PINNED_KEY}:${userId.trim()}`;
}

function parsePinnedIds(raw: string | null): string[] {
    if (!raw) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed
            .filter((id): id is string => typeof id === 'string' && id.trim().length > 0)
            .slice(0, REPOSITORY_PINNED_MAX);
    } catch {
        return [];
    }
}

export function loadRepositoryPinnedRoomIds(userId: string): string[] {
    if (!userId.trim()) return [];
    return parsePinnedIds(readSecureJsonRawSync(pinnedStorageKey(userId)));
}

export function saveRepositoryPinnedRoomIds(userId: string, ids: string[]): void {
    if (!userId.trim()) return;
    const unique: string[] = [];
    const seen = new Set<string>();
    for (const id of ids) {
        const trimmed = id.trim();
        if (!trimmed || seen.has(trimmed)) continue;
        seen.add(trimmed);
        unique.push(trimmed);
        if (unique.length >= REPOSITORY_PINNED_MAX) break;
    }
    writeSecureJsonValue(pinnedStorageKey(userId), unique);
}

export function pruneRepositoryPinnedRoomIds(userId: string, validRoomIds: Set<string>): string[] {
    const next = loadRepositoryPinnedRoomIds(userId).filter((id) => validRoomIds.has(id));
    saveRepositoryPinnedRoomIds(userId, next);
    return next;
}

export function toggleRepositoryPinnedRoom(
    userId: string,
    roomId: string,
    pinnedIds: string[],
): { ids: string[]; pinned: boolean; atLimit: boolean } {
    const id = roomId.trim();
    if (!id) return { ids: pinnedIds, pinned: false, atLimit: false };
    if (pinnedIds.includes(id)) {
        const ids = pinnedIds.filter((x) => x !== id);
        saveRepositoryPinnedRoomIds(userId, ids);
        return { ids, pinned: false, atLimit: false };
    }
    if (pinnedIds.length >= REPOSITORY_PINNED_MAX) {
        return { ids: pinnedIds, pinned: false, atLimit: true };
    }
    const ids = [...pinnedIds, id];
    saveRepositoryPinnedRoomIds(userId, ids);
    return { ids, pinned: true, atLimit: false };
}

/** حرف أبجدي للتجميع — يوحّد أشكال الألف */
export function repositoryRoomInitial(title: string): string {
    const raw = title.trim().charAt(0);
    if (!raw) return '#';
    const map: Record<string, string> = {
        أ: 'ا',
        إ: 'ا',
        آ: 'ا',
        ٱ: 'ا',
        ء: 'ا',
        ؤ: 'و',
        ئ: 'ي',
        ة: 'ه',
    };
    return map[raw] ?? raw.toUpperCase();
}

type RepositoryRoomAlphaGroup = {
    letter: string;
    rooms: RepositoryRoom[];
};

export function groupRepositoryRoomsByInitial(rooms: RepositoryRoom[]): RepositoryRoomAlphaGroup[] {
    const map = new Map<string, RepositoryRoom[]>();
    const sorted = [...rooms].sort((a, b) => a.title.localeCompare(b.title, 'ar'));
    for (const room of sorted) {
        const letter = repositoryRoomInitial(room.title);
        const bucket = map.get(letter);
        if (bucket) bucket.push(room);
        else map.set(letter, [room]);
    }
    return Array.from(map.entries())
        .sort(([a], [b]) => a.localeCompare(b, 'ar'))
        .map(([letter, list]) => ({ letter, rooms: list }));
}

/** غرف الشريط = المثبّتة فقط (+ الغرفة النشطة إن لم تكن مثبّتة — شريحة واحدة مؤقتة) */
export function resolvePinnedRailRooms(
    rooms: RepositoryRoom[],
    pinnedIds: string[],
    selectedRoomId: RepositoryRoomFilter,
): { pinned: RepositoryRoom[]; activeUnpinned: RepositoryRoom | null } {
    const byId = new Map(rooms.map((r) => [r.id, r]));
    const pinned: RepositoryRoom[] = [];
    for (const id of pinnedIds) {
        const room = byId.get(id);
        if (room) pinned.push(room);
    }
    let activeUnpinned: RepositoryRoom | null = null;
    if (selectedRoomId !== 'main' && !pinnedIds.includes(selectedRoomId)) {
        activeUnpinned = byId.get(selectedRoomId) ?? null;
    }
    return { pinned, activeUnpinned };
}

/** عدّاد واحد O(notes+docs) — آمن مع كثرة الغرف */
export function buildRepositoryRoomCounts(
    roomIds: Iterable<string>,
    notes: { roomId?: string | null }[],
    docs: { roomId?: string | null }[],
): Map<string, number> {
    const map = new Map<string, number>();
    for (const id of roomIds) map.set(id, 0);
    for (const note of notes) {
        const id = normalizeRoomId(note.roomId);
        if (id != null && map.has(id)) map.set(id, (map.get(id) ?? 0) + 1);
    }
    for (const doc of docs) {
        const id = normalizeRoomId(doc.roomId);
        if (id != null && map.has(id)) map.set(id, (map.get(id) ?? 0) + 1);
    }
    return map;
}

import type { GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';

export function repositoryItemsInRoom<T extends { roomId?: string | null }>(
    items: T[],
    roomId: string,
): T[] {
    const id = roomId.trim();
    return items.filter((item) => (item.roomId?.trim() || null) === id);
}

export async function clearRoomIdOnGlobalNotes(
    notes: GlobalNote[],
    onSaveNote: (note: GlobalNote) => void | Promise<void>,
): Promise<GlobalNote[]> {
    const relocated: GlobalNote[] = [];
    for (const note of notes) {
        await onSaveNote({ ...note, roomId: null });
        relocated.push(note);
    }
    return relocated;
}

export async function restoreGlobalNotesRoom(
    notes: GlobalNote[],
    onSaveNote: (note: GlobalNote) => void | Promise<void>,
): Promise<void> {
    for (const note of notes) {
        try {
            await onSaveNote(note);
        } catch {
            /* أفضل جهد — لا نُسقط بقية الاستعادة */
        }
    }
}

export async function clearRoomIdOnVaultDocs(
    docs: SmartVaultDoc[],
    uid: string,
    updateDoc: (doc: SmartVaultDoc, uid: string) => Promise<void>,
): Promise<SmartVaultDoc[]> {
    const relocated: SmartVaultDoc[] = [];
    for (const doc of docs) {
        await updateDoc({ ...doc, roomId: null, updatedAt: new Date().toISOString() }, uid);
        relocated.push(doc);
    }
    return relocated;
}

export async function restoreVaultDocsRoom(
    docs: SmartVaultDoc[],
    uid: string,
    updateDoc: (doc: SmartVaultDoc, uid: string) => Promise<void>,
): Promise<void> {
    for (const doc of docs) {
        try {
            await updateDoc(doc, uid);
        } catch {
            /* أفضل جهد */
        }
    }
}

/** غرف المستودع المخصصة (ملكية/موكل) — منفصلة عن SmartVault وتصنيفات customCategory */
import { readSecureJsonRawSync, writeSecureJsonValue } from '@/app/services/storage/syncSecureJson';

export type RepositoryRoom = {
    id: string;
    title: string;
    description?: string;
    createdAt: string;
    clientLabel?: string | null;
};

/** `main` = المستودع العام (roomId فارغ)، وإلا معرف الغرفة */
export type RepositoryRoomFilter = 'main' | (string & {});

const STORAGE_KEY = 'hami:repository:rooms:v1';

function storageKey(userId: string): string {
    return `${STORAGE_KEY}:${userId.trim()}`;
}

function sanitizeTitle(title: string): string {
    return title.trim().slice(0, 80);
}

function isRoom(value: unknown): value is RepositoryRoom {
    if (!value || typeof value !== 'object') return false;
    const r = value as RepositoryRoom;
    return typeof r.id === 'string' && r.id.length > 0 && typeof r.title === 'string' && r.title.trim().length > 0;
}

export function normalizeRoomId(roomId?: string | null): string | null {
    const trimmed = roomId?.trim();
    return trimmed ? trimmed : null;
}

export function itemMatchesRoomFilter(
    roomId: string | null | undefined,
    filter: RepositoryRoomFilter,
): boolean {
    const normalized = normalizeRoomId(roomId);
    if (filter === 'main') return normalized == null;
    return normalized === filter;
}

export function loadRepositoryRooms(userId: string): RepositoryRoom[] {
    if (!userId.trim()) return [];
    try {
        const raw = readSecureJsonRawSync(storageKey(userId));
        if (!raw) return [];
        const parsed = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(isRoom).map((r) => ({
            id: r.id,
            title: sanitizeTitle(r.title),
            description: r.description?.trim() || undefined,
            createdAt: typeof r.createdAt === 'string' ? r.createdAt : new Date().toISOString(),
            clientLabel: r.clientLabel?.trim() || null,
        }));
    } catch {
        return [];
    }
}

function saveRepositoryRooms(userId: string, rooms: RepositoryRoom[]): void {
    if (!userId.trim()) return;
    writeSecureJsonValue(storageKey(userId), rooms);
}

function createRepositoryRoomId(): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return `room_${crypto.randomUUID()}`;
    }
    return `room_${Date.now()}_${Math.random().toString(36).slice(2, 9)}`;
}

export function addRepositoryRoom(
    userId: string,
    title: string,
    extras?: { description?: string; clientLabel?: string | null; maxRooms?: number },
): RepositoryRoom[] {
    const trimmed = sanitizeTitle(title);
    if (!trimmed || !userId.trim()) return loadRepositoryRooms(userId);
    const existing = loadRepositoryRooms(userId);
    if (existing.some((r) => r.title === trimmed)) return existing;
    const maxRooms = extras?.maxRooms;
    if (typeof maxRooms === 'number' && existing.length >= maxRooms) return existing;
    const next: RepositoryRoom[] = [
        ...existing,
        {
            id: createRepositoryRoomId(),
            title: trimmed,
            description: extras?.description?.trim() || undefined,
            createdAt: new Date().toISOString(),
            clientLabel: extras?.clientLabel?.trim() || null,
        },
    ];
    saveRepositoryRooms(userId, next);
    return next;
}

export function removeRepositoryRoom(userId: string, roomId: string): RepositoryRoom[] {
    const id = roomId.trim();
    if (!id || !userId.trim()) return loadRepositoryRooms(userId);
    const next = loadRepositoryRooms(userId).filter((r) => r.id !== id);
    saveRepositoryRooms(userId, next);
    return next;
}

export function countItemsInRoom(
    roomId: string,
    notes: { roomId?: string | null }[],
    docs: { roomId?: string | null }[],
): number {
    const id = roomId.trim();
    if (!id) return 0;
    let n = 0;
    for (const note of notes) {
        if (normalizeRoomId(note.roomId) === id) n += 1;
    }
    for (const doc of docs) {
        if (normalizeRoomId(doc.roomId) === id) n += 1;
    }
    return n;
}

import { isSentryEnabledInBuild as isSentryConfigured } from '@/app/observability/sentryBuildPolicy';

export type RepositoryPerfReportContext = {
    userId?: string;
    vaultDocCount?: number;
    notesCount?: number;
    hadVaultCache?: boolean;
};

type SentryModule = {
    addBreadcrumb?: (crumb: {
        category?: string;
        message?: string;
        level?: string;
        data?: Record<string, unknown>;
    }) => void;
    metrics?: {
        distribution?: (
            name: string,
            value: number,
            options?: { unit?: string; attributes?: Record<string, string | number | boolean> },
        ) => void;
    };
};

let sentryModulePromise: Promise<SentryModule | null> | null = null;

function loadSentryModule(): Promise<SentryModule | null> {
    if (!isSentryConfigured()) return Promise.resolve(null);
    if (!sentryModulePromise) {
        sentryModulePromise = import('@sentry/react')
            .then((mod) => mod as SentryModule)
            .catch(() => null);
    }
    return sentryModulePromise;
}

/** breadcrumb + metric distribution — best effort، لا يرمي */
export function reportRepositoryOpenToSentry(
    durationMs: number,
    context: RepositoryPerfReportContext = {},
): void {
    if (durationMs < 0 || !Number.isFinite(durationMs)) return;

    void loadSentryModule().then((Sentry) => {
        if (!Sentry) return;

        Sentry.addBreadcrumb?.({
            category: 'repository.perf',
            message: `repository open→interactive ${durationMs}ms`,
            level: 'info',
            data: {
                durationMs,
                vaultDocCount: context.vaultDocCount ?? null,
                notesCount: context.notesCount ?? null,
                hadVaultCache: context.hadVaultCache ?? null,
                userId: context.userId ? '[redacted]' : null,
            },
        });

        Sentry.metrics?.distribution?.('repository.open_to_interactive_ms', durationMs, {
            unit: 'millisecond',
            attributes: {
                had_vault_cache: Boolean(context.hadVaultCache),
            },
        });
    });
}

export const REPOSITORY_SHELL_FEATURE = 'المستودع';

type OpenRepositoryFromShellParams = {
    signedIn: boolean;
    onSignedOut: () => void;
    onOpen: () => void;
};

export function openRepositoryFromShell(params: OpenRepositoryFromShellParams): void {
    if (!params.signedIn) {
        params.onSignedOut();
        return;
    }
    params.onOpen();
}

import type { GlobalNote } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { ExecutionFile } from '@/app/components/lawyer/LawyerDashboardParts/types';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { docMatchesCategoryFilter, noteMatchesRepositoryActionCategory } from '@/app/services/vaultCustomCategories';
import { collectDossierNotes, type DossierNoteRef } from './repositoryDossierNotes';
import { resolveDossierNoteBody } from './repositoryDossierNoteSync';
import {
    itemMatchesRoomFilter,
    type RepositoryRoomFilter,
} from './repositoryRooms';
import { stripRepositoryHtml } from './stripRepositoryHtml';
import { archiveTextMatchesQuery } from '@/app/services/search/normalizeArabicSearch';
import { clampGlobalSearchQuery } from '@/app/services/search/globalSearchQuerySecurity';

export type RepositoryFeedFilter = 'all' | 'media' | 'drafts' | 'dossier';

export type RepositoryFeedItem =
    | { kind: 'global'; note: GlobalNote; sortKey: number }
    | { kind: 'dossier'; ref: DossierNoteRef; body: string; sortKey: number }
    | { kind: 'vault_doc'; doc: SmartVaultDoc; sortKey: number };

const FILTER_LABELS: Record<RepositoryFeedFilter, string> = {
    all: 'الكل',
    media: 'صور وملفات',
    drafts: 'مسودات حرة',
    dossier: 'ملاحظات الأضابير',
};

const REPOSITORY_FEED_FILTERS: RepositoryFeedFilter[] = ['all', 'media', 'drafts', 'dossier'];

export function repositoryFeedFilterLabel(filter: RepositoryFeedFilter): string {
    return FILTER_LABELS[filter];
}

function parseSortKey(raw?: string): number {
    if (!raw) return Date.now();
    const ms = Date.parse(raw);
    return Number.isNaN(ms) ? Date.now() : ms;
}

function globalNoteSortKey(note: GlobalNote): number {
    return parseSortKey(note.createdAtIso ?? note.date);
}

function isGlobalInInbox(note: GlobalNote): boolean {
    if (note.repositoryInboxHidden) return false;
    if (note.linkedFileId != null) return false;
    return true;
}

function isMediaNote(note: GlobalNote): boolean {
    return Boolean(note.attachmentDocId) || note.type === 'media';
}

function isDraftNote(note: GlobalNote): boolean {
    return !isMediaNote(note);
}

export function buildRepositoryFeed(input: {
    globalNotes: GlobalNote[];
    lawsuitFiles: FileData[];
    executionFiles: ExecutionFile[];
    vaultDocs: SmartVaultDoc[];
}): RepositoryFeedItem[] {
    const items: RepositoryFeedItem[] = [];

    for (const note of input.globalNotes) {
        if (!isGlobalInInbox(note)) continue;
        items.push({ kind: 'global', note, sortKey: globalNoteSortKey(note) });
    }

    const dossierRefs = collectDossierNotes(input.lawsuitFiles, input.executionFiles);
    for (const ref of dossierRefs) {
        items.push({
            kind: 'dossier',
            ref,
            body: resolveDossierNoteBody(ref, input.lawsuitFiles, input.executionFiles),
            sortKey: parseSortKey(ref.date),
        });
    }

    for (const doc of input.vaultDocs) {
        if (doc.boundDossierId) continue;
        const attachedToNote = input.globalNotes.some((n) => n.attachmentDocId === doc.id);
        if (attachedToNote) continue;
        items.push({
            kind: 'vault_doc',
            doc,
            sortKey: parseSortKey(doc.createdAt ?? doc.updatedAt),
        });
    }

    return items.sort((a, b) => {
        const pinA = a.kind === 'global' ? a.note.isPinned : a.kind === 'dossier' ? a.ref.isPinned : false;
        const pinB = b.kind === 'global' ? b.note.isPinned : b.kind === 'dossier' ? b.ref.isPinned : false;
        if (pinA && !pinB) return -1;
        if (!pinA && pinB) return 1;
        return b.sortKey - a.sortKey;
    });
}

export function filterRepositoryFeed(
    items: RepositoryFeedItem[],
    filter: RepositoryFeedFilter,
): RepositoryFeedItem[] {
    if (filter === 'all') return items;
    if (filter === 'dossier') return items.filter((item) => item.kind === 'dossier');
    if (filter === 'media') {
        return items.filter(
            (item) =>
                item.kind === 'vault_doc' ||
                (item.kind === 'global' && isMediaNote(item.note)),
        );
    }
    return items.filter(
        (item) => item.kind === 'global' && isDraftNote(item.note),
    );
}

/**
 * نطاق الغرفة: ملاحظات عامة + وثائق حسب roomId.
 * ملاحظات الأضابير بلا roomId — تظهر في المستودع العام فقط.
 */
export function filterRepositoryFeedByRoom(
    items: RepositoryFeedItem[],
    filter: RepositoryRoomFilter,
): RepositoryFeedItem[] {
    return items.filter((item) => {
        if (item.kind === 'dossier') return filter === 'main';
        const roomId = item.kind === 'global' ? item.note.roomId : item.doc.roomId;
        return itemMatchesRoomFilter(roomId, filter);
    });
}

export function countRepositoryFeedByFilter(items: RepositoryFeedItem[]): Record<RepositoryFeedFilter, number> {
    let media = 0;
    let drafts = 0;
    let dossier = 0;
    for (const item of items) {
        if (item.kind === 'dossier') {
            dossier += 1;
            continue;
        }
        if (item.kind === 'vault_doc') {
            media += 1;
            continue;
        }
        if (isMediaNote(item.note)) media += 1;
        else drafts += 1;
    }
    return { all: items.length, media, drafts, dossier };
}

export function repositoryFeedItemKey(item: RepositoryFeedItem): string {
    if (item.kind === 'global') return `g-${item.note.id}`;
    if (item.kind === 'dossier') return item.ref.id;
    return `v-${item.doc.id}`;
}

/** قوائم جاهزة لكل تبويب — يُبدَّل العرض بـ hidden دون إعادة mount */
export function buildRepositoryVisibleFeedByMainFilter(
    feedItems: RepositoryFeedItem[],
    vaultCategory: string,
    searchQuery: string,
    vaultDocs: SmartVaultDoc[],
): Record<RepositoryFeedFilter, RepositoryFeedItem[]> {
    const result = {} as Record<RepositoryFeedFilter, RepositoryFeedItem[]>;
    for (const filter of REPOSITORY_FEED_FILTERS) {
        let slice = filterRepositoryFeed(feedItems, filter);
        slice = filterRepositoryFeedByCustomCategory(slice, vaultCategory, vaultDocs);
        slice = searchRepositoryFeed(slice, searchQuery, vaultDocs);
        result[filter] = slice;
    }
    return result;
}

function haystackForItem(item: RepositoryFeedItem, vaultDocs: SmartVaultDoc[]): string[] {
    if (item.kind === 'global') {
        const note = item.note;
        const parts = [note.title, stripRepositoryHtml(note.body || ''), ...(note.tags ?? []), ...(note.quickTaskLines ?? [])];
        if (note.attachmentDocId) {
            const doc = vaultDocs.find((d) => d.id === note.attachmentDocId);
            if (doc) {
                parts.push(doc.title, doc.lawyerNote ?? '', doc.customCategory ?? '', doc.fileName ?? '');
            }
        }
        return parts;
    }
    if (item.kind === 'dossier') {
        return [
            item.ref.title,
            item.ref.excerpt,
            item.ref.dossierLabel,
            stripRepositoryHtml(item.body),
            item.ref.dossierKind === 'lawsuit' ? 'دعوى' : 'تنفيذ',
        ];
    }
    const doc = item.doc;
    return [doc.title, doc.lawyerNote ?? '', doc.customCategory ?? '', doc.fileName ?? '', doc.type ?? ''];
}

export function searchRepositoryFeed(
    items: RepositoryFeedItem[],
    query: string,
    vaultDocs: SmartVaultDoc[] = [],
): RepositoryFeedItem[] {
    const q = clampGlobalSearchQuery(query);
    if (!q.trim()) return items;
    return items.filter((item) =>
        archiveTextMatchesQuery(haystackForItem(item, vaultDocs).join(' '), q),
    );
}

function filterRepositoryFeedByCustomCategory(
    items: RepositoryFeedItem[],
    category: string,
    vaultDocs: SmartVaultDoc[],
): RepositoryFeedItem[] {
    if (!category || category === 'الكل') return items;
    return items.filter((item) => {
        if (item.kind === 'vault_doc') {
            return docMatchesCategoryFilter(item.doc, category);
        }
        if (item.kind === 'global') {
            if (noteMatchesRepositoryActionCategory(item.note, category)) return true;
            const tags = item.note.tags ?? [];
            if (tags.some((t) => t.trim() === category)) return true;
            const attId = item.note.attachmentDocId;
            if (attId) {
                const doc = vaultDocs.find((d) => d.id === attId);
                if (doc && docMatchesCategoryFilter(doc, category)) return true;
            }
            return false;
        }
        return false;
    });
}

export type RepositoryEntryLayoutMode = 'text-only' | 'image-dominant' | 'text-dominant';

export function resolveRepositoryEntryLayout(
    bodyHtml: string,
    attachment?: SmartVaultDoc | null,
): RepositoryEntryLayoutMode {
    const plainLen = stripRepositoryHtml(bodyHtml).length;
    const hasImage = Boolean(attachment?.signedUrl && attachment.type === 'image');
    if (!hasImage) return 'text-only';
    if (plainLen <= 100) return 'image-dominant';
    return 'text-dominant';
}

export function formatRepositoryTimestamp(raw?: string): string {
    const d = raw ? new Date(raw) : new Date();
    const target = Number.isNaN(d.getTime()) ? new Date() : d;
    return target.toLocaleString('ar-EG', {
        weekday: 'long',
        hour: '2-digit',
        minute: '2-digit',
    });
}

/** نص عادي من HTML للبحث والمقتطفات والحفظ — بلا DOM ولا DOMPurify. */
export function stripRepositoryHtml(text: string): string {
    return text
        .replace(/<[^>]+>/g, ' ')
        .replace(/&nbsp;|&#160;/gi, ' ')
        .replace(/&lt;/gi, '<')
        .replace(/&gt;/gi, '>')
        .replace(/&quot;/gi, '"')
        .replace(/&#39;|&apos;/gi, "'")
        .replace(/&amp;/gi, '&')
        .replace(/\s+/g, ' ')
        .trim();
}

import { describe, expect, it, beforeEach, afterEach, vi } from 'vitest';
import {
    snapScheduleShellOpen,
    snapScheduleShellClose,
    scheduleShellReactSync,
