} from '@/app/services/schedule/scheduleShellSnap';

describe('scheduleShellSnap', () => {
    beforeEach(() => {
        document.documentElement.removeAttribute('data-hami-schedule-open');
        document.body.innerHTML = `
      <div data-testid="lawyer-dashboard-home-surface" class="hami-dashboard-home-stack-cover is-active"></div>
      <div data-testid="lawyer-dashboard-schedule-surface" class="hami-dashboard-tab-preserve"></div>
    `;
        performance.clearMarks?.('hami:calendar:open-request');
        performance.clearMarks?.('hami:calendar:first-paint');
        performance.clearMarks?.('hami:calendar:interactive');
    });

    afterEach(() => {
        document.body.innerHTML = '';
        document.documentElement.removeAttribute('data-hami-schedule-open');
    });

    it('يضع علم html فوراً ولا يعتمد على class يمسحه React', () => {
        expect(snapScheduleShellOpen()).toBe(true);
        expect(isScheduleShellSnappedOpen()).toBe(true);
        expect(document.documentElement.getAttribute('data-hami-schedule-open')).toBe('1');
        expect(performance.getEntriesByName('hami:calendar:open-request', 'mark').length).toBeGreaterThan(0);
        expect(performance.getEntriesByName('hami:calendar:interactive', 'mark').length).toBeGreaterThan(0);
    });

    it('يزيل العلم عند الإغلاق', () => {
        snapScheduleShellOpen();
        snapScheduleShellClose();
        expect(isScheduleShellSnappedOpen()).toBe(false);
        expect(document.documentElement.hasAttribute('data-hami-schedule-open')).toBe(false);
    });

    it('يضع العلم حتى بلا سطح تقويم مركّب — الستارة لا تنتظر Host', () => {
        document.body.innerHTML = `<div data-testid="lawyer-dashboard-home-surface"></div>`;
        expect(snapScheduleShellOpen()).toBe(false);
        expect(isScheduleShellSnappedOpen()).toBe(true);
        expect(document.documentElement.getAttribute('data-hami-schedule-open')).toBe('1');
    });

    it('يطلق حدث snap ليستمع MainView ويركب InstantChrome', () => {
        const spy = vi.fn();
        window.addEventListener('hami:schedule-shell-snap', spy);
        snapScheduleShellOpen();
        expect(spy).toHaveBeenCalled();
        const detail = (spy.mock.calls[0][0] as CustomEvent).detail;
        expect(detail.open).toBe(true);
        snapScheduleShellClose();
        expect((spy.mock.calls.at(-1)?.[0] as CustomEvent).detail.open).toBe(false);
        window.removeEventListener('hami:schedule-shell-snap', spy);
    });

    it('scheduleShellReactSync يعمل بعد إطار رسم واحد', async () => {
        const spy = vi.fn();
        scheduleShellReactSync(spy);
        expect(spy).not.toHaveBeenCalled();
        await new Promise<void>((r) => requestAnimationFrame(() => r()));
        expect(spy).toHaveBeenCalledTimes(1);
    });

    it('يلغي مزامنة الفتح المعلقة عند الإغلاق السريع', async () => {
        const spy = vi.fn();
        scheduleShellReactSync(spy);
        snapScheduleShellClose();
        await new Promise<void>((r) => requestAnimationFrame(() => r()));
        expect(spy).not.toHaveBeenCalled();
    });
});

export {
    CALENDAR_DOCK_FEATURE as SCHEDULE_SHELL_FEATURE,
    openCalendarFromDock as openScheduleFromShell,
    type DockCalendarOpenInput as OpenScheduleShellInput,
} from '@/app/services/calendar/dockCalendarOpen';

/**
 * فتح/إغلاق التقويم لحظياً.
 * المصدر الوحيد للحقيقة البصرية: html[data-hami-schedule-open]
 * (React يعيد className على الأسطح — هذا لا يُمسَح).
 */

const SCHEDULE_SURFACE = '[data-testid="lawyer-dashboard-schedule-surface"]';
const ATTR = 'data-hami-schedule-open';

export const SCHEDULE_SHELL_SNAP_EVENT = 'hami:schedule-shell-snap';

export type ScheduleShellSnapDetail = {
    open: boolean;
    hasSurface: boolean;
};

let shellSyncGen = 0; /* يُبطِل rAF معلّق عند الإغلاق قبل وجود السطح — Host التقويم كسول */

function stampCalendarOpenPerfMarksFromSnap(): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark('hami:calendar:open-request');
        performance.mark('hami:calendar:first-paint');
        performance.mark('hami:calendar:interactive');
    } catch {
        /* ignore */
    }
}

function emitScheduleShellSnap(detail: ScheduleShellSnapDetail): void {
    if (typeof window === 'undefined') return;
    window.dispatchEvent(new CustomEvent(SCHEDULE_SHELL_SNAP_EVENT, { detail }));
}

export function isScheduleShellSnappedOpen(): boolean {
    if (typeof document === 'undefined') return false;
    return document.documentElement.getAttribute(ATTR) === '1';
}

/** @returns true إذا وُجد سطح التقويم (keepAlive) — العلم يُوضَع حتى بلا سطح */
export function snapScheduleShellOpen(): boolean {
    if (typeof document === 'undefined') return false;
    const alreadyOpen = document.documentElement.getAttribute(ATTR) === '1';
    document.documentElement.setAttribute(ATTR, '1');
    if (!alreadyOpen) stampCalendarOpenPerfMarksFromSnap();
    const hasSurface = Boolean(document.querySelector(SCHEDULE_SURFACE));
    emitScheduleShellSnap({ open: true, hasSurface });
    return hasSurface;
}

export function snapScheduleShellClose(): void {
    if (typeof document === 'undefined') return;
    shellSyncGen += 1;
    document.documentElement.removeAttribute(ATTR);
    emitScheduleShellSnap({ open: false, hasSurface: false });
}

/** مزامنة React فورية على مسار الإغلاق — بلا انتظار إطار */
export function runShellReactSyncNow(run: () => void): void {
    run();
}

/** مزامنة React بعد أول رسم للـ snap — بلا مسح العلم على html */
export function scheduleShellReactSync(run: () => void): void {
    if (typeof window === 'undefined') {
        run();
        return;
    }
    const gen = shellSyncGen;
    window.requestAnimationFrame(() => {
        if (gen !== shellSyncGen) return;
        run();
    });
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { LegalCase } from '@/app/stores/caseStore';
