    });

    it('escapes regex metacharacters', () => {
        const pattern = buildSafeHighlightPattern('hello.world');
        expect(pattern).not.toBeNull();
        expect(pattern!.source).toContain('\\.');
    });

    it('clamps query length before tokenization', () => {
