/** يستخرج معرّف قضية جزائية من صف الفهرس */
export function resolveCriminalCaseId(raw: unknown): string | null {
    if (!raw || typeof raw !== 'object') return null;
    const id = String((raw as Record<string, unknown>).id ?? '').trim();
    return id || null;
}

/** يتحقق أن المعرّف يخص قضية جزائية ضمن ملكية المستخدم الحالية */
export function isOwnedCriminalCaseId(criminalCases: unknown[], criminalId: string): boolean {
    const target = criminalId.trim();
    if (!target) return false;
    return criminalCases.some((row) => resolveCriminalCaseId(row) === target);
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { djb2Hash } from '@/app/utils/djb2';

const MAX_FILE_SLICES = 2_500;

type FileSlice = {
    sig: string;
    entries: GlobalSearchEntry[];
};

const fileSliceCache = new Map<string, FileSlice>();

/** هاش لمحتوى الأطراف — يلتقط تعديل الاسم/الهاتف/الدور (مصدر عنوان النتيجة) */
function partiesContentHash(parties: FileData['parties']): number {
    if (!Array.isArray(parties) || parties.length === 0) return 0;
    const blob = parties
        .map((p) => `${p.id ?? ''}:${p.name ?? ''}:${p.phone ?? ''}:${p.role ?? ''}:${p.isClient ? 1 : 0}`)
        .join('|');
    return djb2Hash(blob);
}

/** هاش لنصوص ملاحظات الملف */
function notesContentHash(notes: FileData['notes']): number {
    if (!Array.isArray(notes) || notes.length === 0) return 0;
    return djb2Hash(notes.map((n) => `${n.id ?? ''}:${n.text ?? ''}`).join('|'));
}

/** هاش لعناوين/تفاصيل المهام */
function tasksContentHash(tasks: FileData['tasks']): number {
    if (!Array.isArray(tasks) || tasks.length === 0) return 0;
    return djb2Hash(
        tasks
            .map((t) => {
                const rec = t as { id?: unknown; title?: unknown; text?: unknown; details?: unknown };
                return `${String(rec.id ?? '')}:${String(rec.title ?? rec.text ?? '')}:${String(rec.details ?? '')}`;
            })
            .join('|'),
    );
}

/** هاش مضغوط لمحتوى المراحل (timeline / tasks / incidentals) — يلتقط تعديل الأحداث */
function stagesContentHash(stagesRaw: unknown): number {
    if (!Array.isArray(stagesRaw) || stagesRaw.length === 0) return 0;
    const parts: string[] = [];
    for (const stageRaw of stagesRaw) {
        if (!stageRaw || typeof stageRaw !== 'object') continue;
        const stage = stageRaw as Record<string, unknown>;
        parts.push(String(stage.id ?? ''), String(stage.stageName ?? stage.name ?? ''));
        const timeline = Array.isArray(stage.timeline) ? stage.timeline : [];
        for (const evRaw of timeline) {
            if (!evRaw || typeof evRaw !== 'object') continue;
            const ev = evRaw as Record<string, unknown>;
            parts.push(
                `e${String(ev.id ?? '')}:${String(ev.title ?? '')}:${String(ev.details ?? '')}:${ev.isDeleted ? 1 : 0}`,
            );
        }
        const stageTasks = Array.isArray(stage.tasks) ? stage.tasks : [];
        for (const tRaw of stageTasks) {
            if (!tRaw || typeof tRaw !== 'object') continue;
            const t = tRaw as Record<string, unknown>;
            parts.push(`t${String(t.id ?? '')}:${String(t.title ?? '')}`);
        }
        const incidentals = Array.isArray(stage.incidentalCases) ? stage.incidentalCases : [];
        for (const iRaw of incidentals) {
            if (!iRaw || typeof iRaw !== 'object') continue;
            const i = iRaw as Record<string, unknown>;
            parts.push(`i${String(i.id ?? '')}:${String(i.title ?? i.subject ?? '')}`);
        }
    }
    return djb2Hash(parts.join('|'));
}

export function fileSearchIndexSignature(f: FileData & { executionTrashDeletedAt?: string | null }): string {
    const id = String(f.id);
    const stagesRaw = (f as unknown as { stages?: unknown }).stages;
    return [
        id,
        f.type ?? '',
        f.status ?? '',
        f.caseNo ?? '',
        f.court ?? '',
        f.docType ?? '',
        f.judge ?? '',
        f.executionTrashDeletedAt ?? '',
        partiesContentHash(f.parties),
        notesContentHash(f.notes),
        tasksContentHash(f.tasks),
        stagesContentHash(stagesRaw),
    ].join('|');
}

export function getCachedFileSearchEntries(
    f: FileData & { executionTrashDeletedAt?: string | null },
): GlobalSearchEntry[] | null {
    const hit = fileSliceCache.get(String(f.id));
    if (!hit) return null;
    if (hit.sig !== fileSearchIndexSignature(f)) return null;
    return hit.entries;
}

export function rememberFileSearchEntries(
    f: FileData & { executionTrashDeletedAt?: string | null },
    entries: GlobalSearchEntry[],
): void {
    const id = String(f.id);
    fileSliceCache.set(id, { sig: fileSearchIndexSignature(f), entries });
    while (fileSliceCache.size > MAX_FILE_SLICES) {
        const oldest = fileSliceCache.keys().next().value;
        if (oldest === undefined) break;
        fileSliceCache.delete(oldest);
    }
}

export function invalidateFileSearchSliceCache(fileId?: string): void {
    if (fileId) {
        fileSliceCache.delete(String(fileId));
        return;
    }
    fileSliceCache.clear();
}

import { normalizeArabicSearch } from '@/app/services/search/normalizeArabicSearch';

/** بناء نمط RegExp آمن لتظليل البحث — يهرب الأحرف الخاصة ويحدّ طول الاستعلام */
export const HIGHLIGHT_QUERY_MAX_LENGTH = 64;

function escapeRegexChar(ch: string): string {
    return ch.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** توسيع أحرف عربية شائعة ليطابق التظليل كل الأشكال */
function expandArabicTokenForRegex(token: string): string {
    return Array.from(token)
        .map((ch) => {
            if (ch === 'ا' || ch === 'أ' || ch === 'إ' || ch === 'آ') return '[اأإآ]';
            if (ch === 'ه' || ch === 'ة') return '[هة]';
            if (ch === 'ي' || ch === 'ى') return '[يى]';
            return escapeRegexChar(ch);
        })
        .join('');
}

/** يقسّم الاستعلام إلى رموز ذات معنى (كلمة كاملة — ليس حرفاً حرفاً) */
export function tokenizeHighlightQuery(query: string): string[] {
    const safe = query.slice(0, HIGHLIGHT_QUERY_MAX_LENGTH).trim();
    if (!safe) return [];
    return normalizeArabicSearch(safe)
        .toLowerCase()
        .split(/\s+/u)
        .map((t) => t.trim())
        .filter((t) => t.length >= 1);
}

/**
 * نمط تظليل صارم: يطابق الرموز كاملة (أو أرقام)، مع مرونة عربية.
 * سابقاً كان `split('').join('.*?')` فيلوّن حروفاً متفرقة بشكل خاطئ.
 */
export function buildSafeHighlightPattern(query: string): RegExp | null {
    const tokens = tokenizeHighlightQuery(query).filter((t) => t.length >= 2 || /\d/u.test(t));
    if (!tokens.length) {
        const single = tokenizeHighlightQuery(query);
        if (single.length === 1 && single[0].length === 1 && /\d/u.test(single[0])) {
            return new RegExp(`(${escapeRegexChar(single[0])})`, 'giu');
        }
        return null;
    }
    const parts = tokens.map((t) => expandArabicTokenForRegex(t));
    try {
        return new RegExp(`(${parts.join('|')})`, 'giu');
    } catch {
        return null;
    }
}

import type { LegalCase } from '@/app/stores/caseStore';
import { resolveCaseSearchLifecycle } from '@/app/services/searchLifecycle';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { blob, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';

export function caseToEntry(c: LegalCase): GlobalSearchEntry[] {
    const lifecycle = resolveCaseSearchLifecycle(c.status);
    const searchBlob = `${c.title} ${c.caseNo} ${c.court || ''} ${c.clientName} ${c.opponentName}`;
    const entries: GlobalSearchEntry[] = [
        withLifecycle(
            {
                id: `case-${c.id}`,
                category: 'case',
                title: c.title,
                subtitle: `${c.caseNo} • ${c.court || ''}`,
                _searchStr: norm(searchBlob),
                navigate: { type: 'case', caseId: c.id },
            },
            lifecycle,
        ),
    ];
    if (c.clientName) {
        entries.push(
            withLifecycle(
                {
                    id: `case-client-${c.id}`,
                    category: 'party',
                    title: c.clientName,
                    subtitle: `موكل — ${c.title}`,
                    _searchStr: blob([c.clientName, searchBlob]),
                    navigate: { type: 'case', caseId: c.id },
                },
                lifecycle,
            ),
        );
    }
    if (c.opponentName) {
        entries.push(
            withLifecycle(
                {
                    id: `case-opponent-${c.id}`,
                    category: 'party',
                    title: c.opponentName,
                    subtitle: `خصم — ${c.title}`,
                    _searchStr: blob([c.opponentName, searchBlob]),
                    navigate: { type: 'case', caseId: c.id },
                },
                lifecycle,
            ),
        );
    }
    for (const n of c.notes ?? []) {
        if (n.isDeleted || !n.content?.trim()) continue;
        entries.push(
            withLifecycle(
                {
                    id: `case-note-${c.id}-${n.id}`,
                    category: 'note',
                    title: n.content.slice(0, 80),
                    subtitle: `ملاحظة — ${c.title}`,
                    snippet: n.content,
                    _searchStr: blob([n.content, searchBlob]),
                    navigate: { type: 'case', caseId: c.id },
                },
                lifecycle,
            ),
        );
    }
    return entries;
}

import type { SearchLifecycle } from '@/app/services/searchLifecycle';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { blob, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';

const LIFECYCLE_ACTIVE: SearchLifecycle = 'active';

export function criminalToEntry(raw: unknown): GlobalSearchEntry[] {
    if (!raw || typeof raw !== 'object') return [];
    const c = raw as Record<string, unknown>;
    const id = String(c.id ?? '');
    if (!id) return [];

    const location =
        c.location && typeof c.location === 'object' ? (c.location as Record<string, unknown>) : {};
    const caseNo =
        String(c.courtCaseNumber ?? location.caseNumber ?? location.investigationDossierNumber ?? '').trim();
    const defendants = Array.isArray(c.defendants) ? c.defendants : [];
    const d0 =
        defendants[0] && typeof defendants[0] === 'object' ? (defendants[0] as Record<string, unknown>) : null;
    const complainants = Array.isArray(c.complainants) ? c.complainants : [];
    const comp0 =
        complainants[0] && typeof complainants[0] === 'object'
            ? (complainants[0] as Record<string, unknown>)
            : null;
    const clientName = String(d0?.fullName ?? comp0?.fullName ?? '').trim();
    const basics = c.basics && typeof c.basics === 'object' ? (c.basics as Record<string, unknown>) : {};
    const stage = String(basics.stage ?? '').trim();
    const title = clientName || (stage ? `جزائي — ${stage}` : 'إضبارة جزائية');
    const lifecycle: SearchLifecycle = c.isArchived === true ? 'archived' : LIFECYCLE_ACTIVE;
    const notesRaw = Array.isArray(c.notes) ? c.notes : [];
    const noteTextsForMain: string[] = [];
    for (const nRaw of notesRaw) {
        if (!nRaw || typeof nRaw !== 'object') continue;
        const n = nRaw as Record<string, unknown>;
        if (n.isDeleted) continue;
        const noteText = String(n.text ?? n.content ?? '').trim();
        if (noteText) noteTextsForMain.push(noteText);
    }

    const proceduralTimeline = Array.isArray(c.proceduralTimeline) ? c.proceduralTimeline : [];
    const proceduralTexts: string[] = [];
    for (const evRaw of proceduralTimeline) {
        if (!evRaw || typeof evRaw !== 'object') continue;
        const ev = evRaw as Record<string, unknown>;
        const evTitle = String(ev.title ?? ev.name ?? '').trim();
        const evDetails = String(ev.details ?? ev.description ?? '').trim();
        if (evTitle || evDetails) proceduralTexts.push(`${evTitle} ${evDetails}`.trim());
    }

    const partyNamesForMain = [
        ...defendants.map((p) =>
            p && typeof p === 'object' ? String((p as Record<string, unknown>).fullName ?? '') : '',
        ),
        ...complainants.map((p) =>
            p && typeof p === 'object' ? String((p as Record<string, unknown>).fullName ?? '') : '',
        ),
    ]
        .map((n) => n.trim())
        .filter(Boolean);

    const text = [title, caseNo, stage, ...partyNamesForMain, ...noteTextsForMain, ...proceduralTexts]
        .filter(Boolean)
        .join(' ');

    const entries: GlobalSearchEntry[] = [
        withLifecycle(
            {
                id: `criminal-${id}`,
                category: 'criminal',
                title,
                subtitle: caseNo ? `جزائي • ${caseNo}` : 'قضايا جزائية',
                _searchStr: norm(text),
                navigate: { type: 'criminal', criminalId: id },
            },
            lifecycle,
        ),
    ];

    const indexParty = (
        person: Record<string, unknown>,
        idx: number,
        role: 'متهم' | 'شاكٍ',
        partyType: 'defendant' | 'complainant',
    ) => {
        const name = String(person.fullName ?? '').trim();
        if (!name) return;
        const nat = String(person.nationality ?? '').trim();
        const occ = String(person.occupation ?? '').trim();
        const addr = String(person.address ?? '').trim();
        entries.push(
            withLifecycle(
                {
                    id: `criminal-${partyType}-${id}-${idx}`,
                    category: 'party',
                    title: name,
                    subtitle: `${role} — ${title}${caseNo ? ` • ${caseNo}` : ''}`,
                    _searchStr: blob([name, nat, occ, addr, role]),
                    navigate: { type: 'criminal', criminalId: id },
                },
                lifecycle,
            ),
        );
    };

    defendants.forEach((p, i) => {
        if (p && typeof p === 'object') indexParty(p as Record<string, unknown>, i, 'متهم', 'defendant');
    });
    complainants.forEach((p, i) => {
        if (p && typeof p === 'object') indexParty(p as Record<string, unknown>, i, 'شاكٍ', 'complainant');
    });

    for (const nRaw of notesRaw) {
        if (!nRaw || typeof nRaw !== 'object') continue;
        const n = nRaw as Record<string, unknown>;
        if (n.isDeleted) continue;
        const noteText = String(n.text ?? n.content ?? '').trim();
        if (!noteText) continue;
        entries.push(
            withLifecycle(
                {
                    id: `criminal-note-${id}-${String(n.id ?? noteText.slice(0, 20))}`,
                    category: 'note',
                    title: noteText.slice(0, 80),
                    subtitle: `ملاحظة جزائية — ${title}`,
                    snippet: noteText,
                    _searchStr: blob([noteText]),
                    navigate: { type: 'criminal', criminalId: id },
                },
                lifecycle,
            ),
        );
    }

    for (const evRaw of proceduralTimeline) {
        if (!evRaw || typeof evRaw !== 'object') continue;
        const ev = evRaw as Record<string, unknown>;
        const evTitle = String(ev.title ?? ev.name ?? '').trim();
        const evDetails = String(ev.details ?? ev.description ?? '').trim();
        if (!evTitle && !evDetails) continue;
        entries.push(
            withLifecycle(
                {
                    id: `criminal-event-${id}-${String(ev.id ?? evTitle)}`,
                    category: 'criminal',
                    title: evTitle || evDetails.slice(0, 80),
                    subtitle: `إجراء — ${title}`,
                    snippet: evDetails || undefined,
                    _searchStr: blob([evTitle, evDetails]),
                    navigate: { type: 'criminal', criminalId: id },
                },
                lifecycle,
            ),
        );
    }

    return entries;
}

import type { CalendarEvent } from '@/app/services/calendar/calendarTypes';
import type { CommunityPost } from '@/app/services/forum/forumTypes';
import type { LegalTask } from '@/app/types/TaskEngine';
import {
    TransactionStatus,
    type Transaction,
    type TransactionTask,
} from '@/app/modules/transactionsThreading/types';
import type { SearchLifecycle } from '@/app/services/searchLifecycle';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { blob, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';

const LIFECYCLE_ACTIVE: SearchLifecycle = 'active';

export function quantumTaskToEntry(t: LegalTask, fileLifecycleById: Map<string, SearchLifecycle>): GlobalSearchEntry {
    const sub = t.subTasks.map((s) => s.title).join(' ');
    const docs = t.documentRequirements.map((d) => d.text).join(' ');
    const text = `${t.title} ${t.rawText} ${t.location || ''} ${sub} ${docs}`;
    const linkedLifecycle = t.linkedCaseId ? fileLifecycleById.get(String(t.linkedCaseId)) : undefined;
    return withLifecycle(
        {
            id: `qtask-${t.id}`,
            category: 'task',
            title: t.title,
            subtitle: t.location ? `مهمة ميدانية — ${t.location}` : 'مهام المحامي الكمية',
            snippet: t.rawText || undefined,
            _searchStr: norm(text),
            navigate: { type: 'tasks_manager', taskId: t.id },
        },
        linkedLifecycle ?? LIFECYCLE_ACTIVE,
    );
}

export function calendarToEntry(e: CalendarEvent, fileLifecycleById: Map<string, SearchLifecycle>): GlobalSearchEntry {
    const text = `${e.title} ${e.notes || ''} ${e.clientName || ''} ${e.location || ''} ${e.caseNo || ''} ${e.court || ''} ${e.caseId || ''}`;
    const linkedLifecycle = e.caseId ? fileLifecycleById.get(String(e.caseId)) : undefined;
    return withLifecycle(
        {
            id: `cal-${e.id}`,
            category: 'calendar',
            title: e.title,
            subtitle: `${e.date}${e.time ? ` ${e.time}` : ''}${e.clientName ? ` • ${e.clientName}` : ''}${e.caseNo ? ` • ${e.caseNo}` : ''}`,
            snippet: e.notes,
            _searchStr: norm(text),
            navigate: { type: 'calendar', eventId: e.id, date: e.date },
        },
        linkedLifecycle ?? LIFECYCLE_ACTIVE,
    );
}

export function urgentToEntry(raw: unknown, idx: number): GlobalSearchEntry[] {
    if (!raw || typeof raw !== 'object') return [];
    const r = raw as Record<string, unknown>;
    const name = String(r.applicantName ?? r.title ?? r.clientName ?? `طلب ${idx + 1}`);
    const court = String(r.court ?? r.courtName ?? '');
    const caseNo = String(r.requestNumber ?? r.caseNo ?? r.caseNumber ?? '').trim();
    const text = [
        r.applicantName,
        r.title,
        r.clientName,
        r.court,
        r.courtName,
        r.requestNumber,
        r.caseNo,
        r.caseNumber,
        r.notes,
        r.description,
    ]
        .filter((v) => typeof v === 'string' && v.trim())
        .join(' ');
    const lifecycle: SearchLifecycle = r.archived === true ? 'archived' : LIFECYCLE_ACTIVE;
    return [
        withLifecycle(
            {
                id: `urgent-${r.id ?? idx}`,
                category: 'urgent',
                title: name,
                subtitle: court ? `${court}${caseNo ? ` • ${caseNo}` : ''}` : 'طلبات مستعجلة',
                _searchStr: norm(`${name} ${court} ${caseNo} ${text}`),
                navigate: { type: 'urgent', urgentId: String(r.id ?? idx) },
            },
            lifecycle,
        ),
    ];
}

export function threadingTxToEntry(tx: Transaction): GlobalSearchEntry {
    const text = `${tx.title} ${tx.clientName} ${tx.targetDepartment} ${tx.status}`;
    const lifecycle: SearchLifecycle =
        tx.status === TransactionStatus.Completed ? 'archived' : LIFECYCLE_ACTIVE;
    return withLifecycle(
        {
            id: `tx-${tx.id}`,
            category: 'threading',
            title: tx.clientName || tx.title,
            subtitle: `معاملة إدارية — ${tx.targetDepartment}`,
            _searchStr: norm(text),
            navigate: { type: 'transactions', transactionId: tx.id },
        },
        lifecycle,
    );
}

export function threadingTaskToEntry(t: TransactionTask, txTitle: string, transactionId: string): GlobalSearchEntry {
    const text = `${t.title} ${t.notes || ''} ${t.officialReference || ''} ${txTitle}`;
    return withLifecycle(
        {
            id: `txtask-${t.id}`,
            category: 'task',
            title: t.title,
            subtitle: `مهمة معاملة — ${txTitle}`,
            snippet: t.notes || undefined,
            _searchStr: norm(text),
            navigate: { type: 'transactions', transactionId },
        },
        LIFECYCLE_ACTIVE,
    );
}

export function notificationToEntry(n: {
    id: string;
    title: string;
    message: string;
    type: string;
}): GlobalSearchEntry {
    return withLifecycle(
        {
            id: `notif-${n.id}`,
            category: 'notification',
            title: n.title,
            subtitle: n.message.slice(0, 80) || 'إشعار',
            snippet: n.message.length > 80 ? n.message : undefined,
            _searchStr: norm(`${n.title} ${n.message} ${n.type}`),
            navigate: { type: 'notifications' },
        },
        LIFECYCLE_ACTIVE,
    );
}

export function communityPostToEntries(p: CommunityPost): GlobalSearchEntry[] {
    const tagText = p.tags.join(' ');
    const attach = p.attachment?.name || '';
    const postText = `${p.content} ${tagText} ${attach} ${p.authorName}`;
    const entries: GlobalSearchEntry[] = [
        withLifecycle(
            {
                id: `forum-${p.id}`,
                category: 'community',
                title: p.content.slice(0, 80) || 'منشور مجتمع المحامين',
                subtitle: `${p.authorName}${p.tags.length ? ` • ${p.tags.join(', ')}` : ''}`,
                snippet: p.content.length > 80 ? p.content : undefined,
                _searchStr: norm(postText),
                navigate: { type: 'community', postId: p.id },
            },
            LIFECYCLE_ACTIVE,
        ),
    ];
    for (const c of p.comments ?? []) {
        if (!c.content?.trim()) continue;
        entries.push(
            withLifecycle(
                {
                    id: `forum-c-${p.id}-${c.id}`,
                    category: 'community',
                    title: c.content.slice(0, 80),
                    subtitle: `تعليق — ${p.authorName}`,
                    snippet: c.content,
                    _searchStr: blob([c.content, c.authorName, postText]),
                    navigate: { type: 'community', postId: p.id },
                },
                LIFECYCLE_ACTIVE,
            ),
        );
    }
    return entries;
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { resolveFileSearchLifecycle } from '@/app/services/searchLifecycle';
import type { GlobalSearchCategory, GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import {
    clipSearchHaystack,
    norm,
    noteTexts,
    partyNames,
    withLifecycle,
} from '@/app/services/search/globalSearchIndexPureHelpers';
import { fileTasksSearchHaystack } from '@/app/services/search/globalSearchIndexFileTasks';
import { lawsuitStagesSearchHaystack } from '@/app/services/search/globalSearchIndexLawsuitStages';

export function fileToEntry(f: FileData & { executionTrashDeletedAt?: string | null }): GlobalSearchEntry[] {
    const lifecycle = resolveFileSearchLifecycle(f);
    const cat: GlobalSearchCategory =
        f.type === 'execution' ? 'execution' : f.type === 'transaction' ? 'transaction' : 'lawsuit';
    const client = f.parties?.find((p) => p.isClient)?.name || f.parties?.[0]?.name || '';
    const jurisdictionHint =
        f.lawsuitJurisdiction === 'personal'
            ? 'أحوال شخصية قضاء أحوال personal status'
            : f.lawsuitJurisdiction === 'civil'
              ? 'قضاء مدني civil'
              : '';
    const applicableLaw = String(
        (f as { applicableLaw?: string }).applicableLaw ??
            (f as { personalApplicableLaw?: string }).personalApplicableLaw ??
            '',
    ).trim();
    const searchBlob = clipSearchHaystack(
        [
            f.caseNo,
            f.court,
            f.docType,
            f.judge,
            client,
            partyNames(f.parties),
            noteTexts(f.notes),
            fileTasksSearchHaystack(f),
            f.type === 'execution' ? '' : lawsuitStagesSearchHaystack(f),
            jurisdictionHint,
            applicableLaw,
        ]
            .filter(Boolean)
            .join(' '),
    );

    const jurisdictionSubtitle =
        f.lawsuitJurisdiction === 'personal'
            ? 'أحوال شخصية'
            : f.lawsuitJurisdiction === 'civil'
              ? 'قضاء مدني'
              : null;

    return [
        withLifecycle(
            {
                id: `file-${f.id}`,
                category: cat,
                title:
                    f.type === 'transaction'
                        ? client || f.caseNo || 'معاملة'
                        : f.parties?.find((p) => p.isClient)?.name || f.caseNo || 'ملف',
                subtitle:
                    f.type === 'transaction'
                        ? f.caseNo
                            ? `إضبارة · ${f.caseNo}`
                            : 'إضبارة'
                        : jurisdictionSubtitle
                          ? `${jurisdictionSubtitle} • ${f.court} • ${f.caseNo}`
                          : `${f.court} • ${f.caseNo}`,
                _searchStr: norm(searchBlob),
                navigate: { type: 'file', fileId: f.id },
            },
            lifecycle,
        ),
    ];
}

import type { FileData, Task } from '@/app/components/lawyer/LawyerShared';

/** عناوين مهام الملف داخل وثيقة الملف — بلا وثيقة Fuse لكل مهمة. */
export function fileTasksSearchHaystack(f: FileData): string {
    const parts: string[] = [];
    for (const t of f.tasks ?? []) {
        const title = (t as Task).title?.trim() || (t as { text?: string }).text?.trim();
        if (title) parts.push(title);
        const details = (t as Task).details?.trim();
        if (details) parts.push(details);
    }
    return parts.join(' ');
}

import type { LawsuitLifecycleIndex } from '@/app/domain/lawsuit/lawsuitLifecycleIndex';
import type { GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import type { SearchLifecycle } from '@/app/services/searchLifecycle';
import { blob, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';

function lifecycleFromIndexStatus(status: 'active' | 'archived' | 'deleted'): SearchLifecycle {
    if (status === 'deleted') return 'deleted';
    if (status === 'archived') return 'archived';
    return 'active';
}

/** إدخالات خفيفة من فهرس lifecycle — للمخزن/المهملات غير المحمّلة في الذاكرة */
export function lawsuitLifecycleIndexToSearchEntries(
    index: LawsuitLifecycleIndex | undefined,
    indexedFileIds: Set<string>,
): GlobalSearchEntry[] {
    if (!index) return [];
    const entries: GlobalSearchEntry[] = [];
    for (const entry of Object.values(index.entries)) {
        if (entry.status === 'active') continue;
        if (indexedFileIds.has(entry.id)) continue;
        const lifecycle = lifecycleFromIndexStatus(entry.status);
        const displayTitle = entry.clientName || entry.title || entry.caseNo || 'ملف دعوى';
        const baseSubtitle = [
            entry.status === 'deleted' ? 'سلة المهملات' : null,
            entry.court,
            entry.caseNo ? `إضبارة • ${entry.caseNo}` : 'دعوى قضائية',
        ]
            .filter(Boolean)
            .join(' • ');
        entries.push(
            withLifecycle(
                {
                    id: `file-${entry.id}`,
                    category: 'lawsuit',
                    title: displayTitle,
                    subtitle: baseSubtitle,
                    _searchStr: norm(
                        blob([
                            entry.searchHaystack,
                            entry.caseNo,
                            entry.title,
                            entry.clientName,
                            entry.court,
                            entry.type,
                        ]),
                    ),
                    navigate: { type: 'file', fileId: entry.id },
                },
                lifecycle,
            ),
        );
    }
    return entries;
}

export function lawsuitLifecycleIndexSignature(index: LawsuitLifecycleIndex | undefined): string {
    if (!index) return '0';
    const parts: string[] = [
        String(index.counts.active),
        String(index.counts.archived),
        String(index.counts.trash),
    ];
    for (const entry of Object.values(index.entries)) {
        if (entry.status === 'active') continue;
        parts.push(
            `${entry.id}:${entry.status}:${entry.caseNo ?? ''}:${entry.title ?? ''}:${entry.type ?? ''}:${entry.court ?? ''}:${entry.clientName ?? ''}:${entry.searchHaystack ?? ''}`,
        );
    }
    return parts.join('~');
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import { sanitizeSearchDisplayText } from '@/app/services/search/searchDisplayText';

const STAGES_HAYSTACK_MAX = 4_000;

/** نصوص المراحل للبحث داخل وثيقة الملف — بلا وثيقة Fuse لكل حدث. */
export function lawsuitStagesSearchHaystack(f: FileData): string {
    const parts: string[] = [];
    const stagesRaw = (f as unknown as Record<string, unknown>).stages;
    const stages = Array.isArray(stagesRaw) ? stagesRaw : [];

    for (const stageRaw of stages) {
        if (!stageRaw || typeof stageRaw !== 'object') continue;
        const stage = stageRaw as Record<string, unknown>;
        const stageName = String(stage.stageName ?? stage.name ?? '').trim();
        if (stageName) parts.push(stageName);

        const timeline = Array.isArray(stage.timeline) ? stage.timeline : [];
        for (const evRaw of timeline) {
            if (!evRaw || typeof evRaw !== 'object') continue;
            const ev = evRaw as Record<string, unknown>;
            if (ev.isDeleted) continue;
            const title = sanitizeSearchDisplayText(String(ev.title ?? '').trim());
            const details = sanitizeSearchDisplayText(String(ev.details ?? '').trim());
            const tagsStr = Array.isArray(ev.tags) ? (ev.tags as unknown[]).join(' ') : '';
            parts.push(title, details, String(ev.type ?? ''), String(ev.subType ?? ''), tagsStr);
        }

        const stageTasks = Array.isArray(stage.tasks) ? stage.tasks : [];
        for (const tRaw of stageTasks) {
            if (!tRaw || typeof tRaw !== 'object') continue;
            const t = tRaw as Record<string, unknown>;
            parts.push(
                sanitizeSearchDisplayText(String(t.title ?? '').trim()),
                sanitizeSearchDisplayText(String(t.details ?? '').trim()),
            );
        }

        const incidentals = Array.isArray(stage.incidentalCases) ? stage.incidentalCases : [];
        for (const iRaw of incidentals) {
            if (!iRaw || typeof iRaw !== 'object') continue;
            const i = iRaw as Record<string, unknown>;
            parts.push(
                sanitizeSearchDisplayText(String(i.title ?? i.subject ?? '').trim()),
                sanitizeSearchDisplayText(String(i.details ?? '').trim()),
                String(i.type ?? ''),
            );
        }
    }

    const joined = parts.filter(Boolean).join(' ');
    return joined.length > STAGES_HAYSTACK_MAX ? joined.slice(0, STAGES_HAYSTACK_MAX) : joined;
}

import type { FileData } from '@/app/components/lawyer/LawyerShared';
import type { SearchLifecycle } from '@/app/services/searchLifecycle';
import type { BuildGlobalSearchIndexInput, GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import {
    getCachedFileSearchEntries,
    rememberFileSearchEntries,
} from '@/app/services/search/globalSearchFileSliceCache';
import { caseToEntry } from '@/app/services/search/globalSearchIndexCaseEntries';
import { criminalToEntry } from '@/app/services/search/globalSearchIndexCriminalEntries';
import {
    calendarToEntry,
    communityPostToEntries,
    notificationToEntry,
    quantumTaskToEntry,
    threadingTaskToEntry,
    threadingTxToEntry,
    urgentToEntry,
} from '@/app/services/search/globalSearchIndexExtrasEntries';
import { fileToEntry } from '@/app/services/search/globalSearchIndexFileEntries';
import { lawsuitLifecycleIndexToSearchEntries } from '@/app/services/search/globalSearchIndexLawsuitLifecycleEntries';
import { blob, isSearchEntryVisible, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';
import {
    docsVaultEntriesFromPrepared,
    noteRowToEntry,
    repositoryToEntry,
    vaultToEntry,
} from '@/app/services/search/globalSearchIndexVaultEntries';

const LIFECYCLE_ACTIVE: SearchLifecycle = 'active';

/** فهرس موحّد — Worker-safe (بيانات JSON جاهزة من الخيط الرئيسي) */
export function buildGlobalSearchIndex(input: BuildGlobalSearchIndexInput): GlobalSearchEntry[] {
    const seen = new Set<string>();
    const list: GlobalSearchEntry[] = [];
    const fileLifecycleById = new Map<string, SearchLifecycle>();

    const push = (e: GlobalSearchEntry) => {
        if (!isSearchEntryVisible(e)) return;
        if (seen.has(e.id)) return;
        seen.add(e.id);
        list.push(e);
    };

    /** metadata من lifecycleIndex — يُسمح بـ deleted للوصول إلى المهملات غير المحمّلة */
    const pushLifecycleIndexEntry = (e: GlobalSearchEntry) => {
        if (seen.has(e.id)) return;
        seen.add(e.id);
        list.push(e);
    };

    const indexFile = (f: FileData & { executionTrashDeletedAt?: string | null }) => {
        const cached = getCachedFileSearchEntries(f);
        const entries = cached ?? fileToEntry(f);
        if (!cached) rememberFileSearchEntries(f, entries);
        if (entries.length > 0) {
            fileLifecycleById.set(String(f.id), entries[0].lifecycle);
        }
        for (const entry of entries) {
            push(entry);
        }
    };

    for (const f of input.files) {
        indexFile(f);
    }

    const indexedLawsuitIds = new Set<string>();
    for (const f of input.files) indexedLawsuitIds.add(String(f.id));
    for (const entry of lawsuitLifecycleIndexToSearchEntries(
        input.lawsuitLifecycleIndex,
        indexedLawsuitIds,
    )) {
        pushLifecycleIndexEntry(entry);
    }

    for (const f of input.executionFiles ?? []) {
        indexFile({ ...f, type: 'execution' });
    }

    for (const entry of input.preparedExecutionDeepEntries ?? []) {
        push(entry);
    }

    const fileIds = new Set<string>();
    for (const f of input.files) fileIds.add(String(f.id));
    for (const f of input.executionFiles ?? []) fileIds.add(String(f.id));

    for (const c of input.cases) {
        if (!fileIds.has(c.id)) caseToEntry(c).forEach(push);
    }

    for (const c of input.criminalCases ?? []) {
        criminalToEntry(c).forEach(push);
    }

    const seenNoteIds = new Set<string>();
    const preparedVaultNotes = input.preparedVaultNotes ?? [];
    const preparedStoredNotes = input.preparedStoredNotes ?? [];
    const preparedDocsVault = input.preparedDocsVault ?? [];

    for (const n of preparedVaultNotes) {
        seenNoteIds.add(String(n.id));
        const isVoice = n.type === 'voice';
        push(
            withLifecycle(
                {
                    id: `nv-${n.id}`,
                    category: isVoice ? 'voice' : 'note',
                    title: isVoice ? 'تسجيل صوتي' : n.content.slice(0, 80) || 'ملاحظة',
                    subtitle: isVoice ? 'مفكرة — صوت' : 'مفكرة الملاحظات',
                    snippet: isVoice ? undefined : n.content,
                    _searchStr: blob([n.content, isVoice ? 'صوت' : '']),
                    navigate: isVoice
                        ? { type: 'voice', noteId: String(n.id) }
                        : { type: 'note', noteId: String(n.id) },
                },
                LIFECYCLE_ACTIVE,
            ),
        );
    }

    for (const n of input.globalNotes) {
        if (seenNoteIds.has(String(n.id))) continue;
        seenNoteIds.add(String(n.id));
        push(noteRowToEntry(n, 'المفكرة العامة'));
    }

    for (const n of preparedStoredNotes) {
        if (seenNoteIds.has(String(n.id))) continue;
        seenNoteIds.add(String(n.id));
        push(noteRowToEntry(n, 'ملاحظات المحامي'));
    }

    docsVaultEntriesFromPrepared(preparedDocsVault, fileLifecycleById).forEach(push);

    for (const n of input.notifications ?? []) {
        if (n.title?.trim() || n.message?.trim()) push(notificationToEntry(n));
    }

    const extras = input.extras;
    if (extras) {
        extras.vaultDocs.forEach((d) => push(vaultToEntry(d)));
        extras.repositoryDocs.forEach((d) => push(repositoryToEntry(d)));
        extras.quantumTasks.forEach((t) => push(quantumTaskToEntry(t, fileLifecycleById)));
        extras.calendarEvents.forEach((e) => push(calendarToEntry(e, fileLifecycleById)));
        extras.urgentCases.forEach((c, i) => urgentToEntry(c, i).forEach(push));

        const txById = new Map(extras.threadingTransactions.map((t) => [t.id, t]));
        extras.threadingTransactions.forEach((tx) => push(threadingTxToEntry(tx)));
        for (const t of extras.threadingTasks) {
            const tx = txById.get(t.transactionId);
            push(threadingTaskToEntry(t, tx?.clientName || tx?.title || 'معاملة', t.transactionId));
        }
        extras.communityPosts.forEach((p) => communityPostToEntries(p).forEach(push));
    }

    if (input.profileLine?.trim()) {
        push(
            withLifecycle(
                {
                    id: 'profile-self',
                    category: 'profile',
                    title: 'الملف الشخصي',
                    subtitle: input.profileLine.trim(),
                    _searchStr: norm(input.profileLine),
                    navigate: { type: 'profile' },
                },
                LIFECYCLE_ACTIVE,
            ),
        );
    }

    return list;
}

import type { FileData, Party } from '@/app/components/lawyer/LawyerShared';
