import type { SearchLifecycle } from '@/app/services/searchLifecycle';
import type { GlobalSearchEntry, PreparedDocsVaultDoc } from '@/app/services/globalSearchIndex';
import { blob, clipSearchHaystack, norm, withLifecycle } from '@/app/services/search/globalSearchIndexPureHelpers';

const LIFECYCLE_ACTIVE: SearchLifecycle = 'active';

export type GlobalNoteRow = {
    id: number | string;
    title?: string;
    body?: string;
    type?: string;
    transcript?: string;
    voiceDurationSec?: number;
};

export function vaultToEntry(d: SmartVaultDoc): GlobalSearchEntry {
    const text = clipSearchHaystack(
        [d.title, d.fileName, d.tags.join(' '), d.aiSummary || '', d.customCategory || '', d.lawyerNote || ''].join(
            ' ',
        ),
    );
    return withLifecycle(
        {
            id: `vault-${d.id}`,
            category: 'vault',
            title: d.title || d.fileName,
            subtitle: d.tags.length ? d.tags.join(' • ') : 'المستودع الذكي',
            snippet: d.aiSummary || undefined,
            _searchStr: norm(text),
            navigate: { type: 'vault' },
        },
        LIFECYCLE_ACTIVE,
    );
}

export function repositoryToEntry(d: RepositoryDocument): GlobalSearchEntry {
    const text = `${d.title} ${d.description} ${d.type} ${d.fileName} ${d.authorName}`;
    return withLifecycle(
        {
            id: `repo-${d.id}`,
            category: 'repository',
            title: d.title,
            subtitle: `${d.type} • ${d.authorName}`,
            snippet: d.description || undefined,
            _searchStr: norm(text),
            navigate: { type: 'repository' },
        },
        LIFECYCLE_ACTIVE,
    );
}

export function docsVaultEntriesFromPrepared(
    docs: PreparedDocsVaultDoc[],
    fileLifecycleById: Map<string, SearchLifecycle>,
): GlobalSearchEntry[] {
    return docs.map((d) => {
        const linkedLifecycle = d.caseId ? fileLifecycleById.get(String(d.caseId)) : undefined;
        return withLifecycle(
            {
                id: `docs-vault-${d.id}`,
                category: 'vault' as const,
                title: d.name,
                subtitle: d.caseId ? `مستند إضبارة #${d.caseId}` : 'مستندات الإضبارة',
                _searchStr: blob([d.name, d.tags?.join(' '), d.caseId]),
                navigate: d.caseId ? { type: 'file', fileId: d.caseId } : { type: 'vault' },
            },
            linkedLifecycle ?? LIFECYCLE_ACTIVE,
        );
    });
}

export function noteRowToEntry(n: GlobalNoteRow, source: string): GlobalSearchEntry {
    const title = n.title?.trim() || 'ملاحظة';
    const body = n.body?.trim() || '';
    const isVoice = n.type === 'voice' || body.startsWith('data:audio') || body.startsWith('hami-voice-ref:');
    const transcript = n.transcript?.trim();
    return withLifecycle(
        {
            id: `gnote-${n.id}-${source}`,
            category: isVoice ? 'voice' : 'note',
            title: isVoice ? title || 'تسجيل صوتي' : title,
            subtitle: isVoice ? (transcript ? source : 'مفكرة — صوت') : source,
            snippet: isVoice ? transcript || undefined : body,
            _searchStr: blob([title, body, transcript, isVoice ? 'صوت تسجيل' : '']),
            navigate: isVoice
                ? { type: 'voice', noteId: String(n.id) }
                : { type: 'note', noteId: String(n.id) },
        },
        LIFECYCLE_ACTIVE,
    );
}

import type { BuildGlobalSearchIndexInput, GlobalSearchEntry } from '@/app/services/globalSearchIndex';
import { buildGlobalSearchIndex } from '@/app/services/search/globalSearchIndexPure';

type WorkerRequest = {
    id: number;
    input: BuildGlobalSearchIndexInput;
};

type WorkerResponse = {
    id: number;
    index?: GlobalSearchEntry[];
    error?: string;
};

let worker: Worker | null = null;
let workerFailed = false;
let requestSeq = 0;
const pending = new Map<
    number,
    { resolve: (v: GlobalSearchEntry[]) => void; reject: (e: Error) => void }
>();

function settleWorkerMessage(event: MessageEvent<WorkerResponse>): void {
    const { id, index, error } = event.data;
    const job = pending.get(id);
    if (!job) return;
    pending.delete(id);
    if (error) {
        job.reject(new Error(error));
        return;
    }
    job.resolve(index ?? []);
}

function ensureWorker(): Worker | null {
    if (workerFailed || typeof Worker === 'undefined') return null;
    if (worker) return worker;
    try {
        worker = new Worker(new URL('@/app/workers/globalSearchIndex.worker.ts', import.meta.url), {
            type: 'module',
        });
        worker.onmessage = settleWorkerMessage;
        worker.onerror = () => {
            workerFailed = true;
            worker?.terminate();
            worker = null;
            for (const [, job] of pending) {
                job.reject(new Error('global-search-worker-error'));
            }
            pending.clear();
        };
        return worker;
    } catch {
        workerFailed = true;
        return null;
    }
}

export function prefetchGlobalSearchIndexWorker(): void {
    ensureWorker();
}

export function buildGlobalSearchIndexOffThread(
    input: BuildGlobalSearchIndexInput,
): Promise<GlobalSearchEntry[]> {
    const instance = ensureWorker();
    if (!instance) {
        return Promise.resolve(buildGlobalSearchIndex(input));
    }

    const id = ++requestSeq;
    return new Promise<GlobalSearchEntry[]>((resolve, reject) => {
        pending.set(id, { resolve, reject });
        const payload: WorkerRequest = { id, input };
        instance.postMessage(payload);
    });
}

import { hasAnyCachedGlobalSearchFuse } from '@/app/services/globalSearchFuse';
import { getCachedGlobalSearchExtras } from '@/app/services/globalSearchExtrasCache';

/** Peek كاش الجلسة فقط — لا يبني فهرساً ولا يحمّل cloud. */
export function hasGlobalSearchLocalWarmCache(userId: string | null | undefined): boolean {
    if (hasAnyCachedGlobalSearchFuse()) return true;
    if (!userId) return false;
    return getCachedGlobalSearchExtras(userId) != null;
}

import type { GlobalSearchNavigate } from '@/app/services/globalSearchIndex';

const GLOBAL_SEARCH_NAV_ID_MAX = 128;
const GLOBAL_SEARCH_STAGE_INDEX_MAX = 512;

const UNSAFE_ID_CHARS = /[<>'"\u0000-\u001F\u007F]/;
const SCHEME_ID = /^(javascript|data|vbscript):/i;

function sanitizeSearchEntityId(raw: unknown): string | null {
    if (raw == null) return null;
    const id = String(raw).trim();
    if (!id || id.length > GLOBAL_SEARCH_NAV_ID_MAX) return null;
    if (UNSAFE_ID_CHARS.test(id) || SCHEME_ID.test(id)) return null;
    return id;
}

function sanitizeSearchCalendarDate(raw: unknown): string | null {
    const s = String(raw ?? '').trim();
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
    if (!m) return null;
    const year = Number(m[1]);
    const month = Number(m[2]);
    const day = Number(m[3]);
    const dt = new Date(Date.UTC(year, month - 1, day));
    if (
        dt.getUTCFullYear() !== year ||
        dt.getUTCMonth() !== month - 1 ||
        dt.getUTCDate() !== day
    ) {
        return null;
    }
    return s;
}

function sanitizeSearchStageIndex(raw: unknown): number | null {
    if (typeof raw !== 'number' || !Number.isInteger(raw)) return null;
    if (raw < 0 || raw > GLOBAL_SEARCH_STAGE_INDEX_MAX) return null;
    return raw;
}

function optionalId(raw: unknown): { ok: true; id?: string } | { ok: false } {
    if (raw == null) return { ok: true };
    if (typeof raw === 'string' && !raw.trim()) return { ok: true };
    const id = sanitizeSearchEntityId(raw);
    if (!id) return { ok: false };
    return { ok: true, id };
}

/** ينظّف هدف التنقّل من البحث — يرفض معرّفات/تواريخ غير آمنة */
export function sanitizeGlobalSearchNavigate(nav: GlobalSearchNavigate): GlobalSearchNavigate | null {
    switch (nav.type) {
        case 'notifications':
        case 'repository':
        case 'profile':
        case 'vault':
            return { type: nav.type };
        case 'calendar': {
            let date: string | undefined;
            if (nav.date != null && String(nav.date).trim() !== '') {
                const next = sanitizeSearchCalendarDate(nav.date);
                if (!next) return null;
                date = next;
            }
            const event = optionalId(nav.eventId);
            if (!event.ok) return null;
            return { type: 'calendar', date, eventId: event.id };
        }
        case 'community': {
            const post = optionalId(nav.postId);
            if (!post.ok) return null;
            return { type: 'community', postId: post.id };
        }
        case 'urgent': {
            const urgent = optionalId(nav.urgentId);
            if (!urgent.ok) return null;
            return { type: 'urgent', urgentId: urgent.id };
        }
        case 'criminal': {
            const criminalId = sanitizeSearchEntityId(nav.criminalId);
            if (!criminalId) return null;
            return { type: 'criminal', criminalId };
        }
        case 'transactions': {
            const tx = optionalId(nav.transactionId);
            if (!tx.ok) return null;
            return { type: 'transactions', transactionId: tx.id };
        }
        case 'tasks_manager': {
            const task = optionalId(nav.taskId);
            if (!task.ok) return null;
            return { type: 'tasks_manager', taskId: task.id };
        }
        case 'note':
        case 'voice': {
            const note = optionalId(nav.noteId);
            if (!note.ok) return null;
            return { type: nav.type, noteId: note.id };
        }
        case 'file': {
            const fileId = sanitizeSearchEntityId(nav.fileId);
            if (!fileId) return null;
            let stageIndex: number | undefined;
            if (nav.stageIndex != null) {
                const stage = sanitizeSearchStageIndex(nav.stageIndex);
                if (stage == null) return null;
                stageIndex = stage;
            }
            const event = optionalId(nav.eventId);
            if (!event.ok) return null;
            return { type: 'file', fileId, stageIndex, eventId: event.id };
        }
        case 'case': {
            const caseId = sanitizeSearchEntityId(nav.caseId);
            if (!caseId) return null;
            return { type: 'case', caseId };
        }
        default:
            return null;
    }
}

/**
 * ميزانيات أداء البحث الشامل — مرجع E2E + Sentry.
 */
export const GLOBAL_SEARCH_PERF_BUDGET = {
    openToInteractiveMs: {
        target: 2_400,
        ciColdMax: 7_000,
        ciCachedMax: 4_000,
    },
    sentryMetric: 'global_search.open_to_interactive_ms',
} as const;

import { debug } from '@/app/utils/debug';
import {
    reportGlobalSearchOpenToSentry,
    type GlobalSearchPerfReportContext,
} from '@/app/services/search/globalSearchSentryReporting';

const MARK_PREFIX = 'hami:global-search:';

type GlobalSearchPerfPhase = 'open-request' | 'chunk-ready' | 'first-paint' | 'interactive';

export type { GlobalSearchPerfReportContext };

export function markGlobalSearchPerfPhase(phase: GlobalSearchPerfPhase): void {
    if (typeof performance === 'undefined' || typeof performance.mark !== 'function') return;
    try {
        performance.mark(`${MARK_PREFIX}${phase}`);
    } catch {
        /* ignore */
    }
}

export function clearGlobalSearchPerfMarks(): void {
    if (typeof performance === 'undefined' || typeof performance.clearMarks !== 'function') return;
    try {
        for (const phase of ['open-request', 'chunk-ready', 'first-paint', 'interactive'] as const) {
            performance.clearMarks(`${MARK_PREFIX}${phase}`);
        }
    } catch {
        /* ignore */
    }
}

export function getGlobalSearchOpenToInteractiveMs(): number | null {
    if (typeof performance === 'undefined') return null;
    const open = performance.getEntriesByName(`${MARK_PREFIX}open-request`, 'mark')[0];
    const interactive = performance.getEntriesByName(`${MARK_PREFIX}interactive`, 'mark')[0];
    if (!open || !interactive) return null;
    return Math.round(interactive.startTime - open.startTime);
}

export function reportGlobalSearchPerf(context: GlobalSearchPerfReportContext = {}): void {
    const ms = getGlobalSearchOpenToInteractiveMs();
    if (ms == null) return;
    if (import.meta.env.DEV) {
        debug.log('[GlobalSearchPerf] open→interactive', ms, 'ms', context);
    }
    reportGlobalSearchOpenToSentry(ms, context);
}

/** حد أقصى لطول استعلام البحث — يمنع إساءة استخدام Fuse والذاكرة */
export const GLOBAL_SEARCH_MAX_QUERY_LENGTH = 128;

/** حد تسمية النتيجة المحفوظة في «الأخيرة» */
export const GLOBAL_SEARCH_MAX_RECENT_LABEL_LENGTH = 80;

export const GLOBAL_SEARCH_MAX_RECENT_COUNT = 8;

const RECENT_SEARCHES_KEY_PREFIX = 'lawyer_recent_searches';
export const LEGACY_RECENT_SEARCHES_KEY = 'lawyer_recent_searches';

/** مفتاح تخزين «الأخيرة» مرتبط بالمستخدم — يمنع تسرّب بين الحسابات على نفس الجهاز */
export function globalSearchRecentStorageKey(userId: string | null | undefined): string | null {
    const id = typeof userId === 'string' ? userId.trim() : '';
    if (!id) return null;
    return `${RECENT_SEARCHES_KEY_PREFIX}:${id}`;
}

/** أحرف تحكم + تجاوز اتجاه النص — لا تُمرَّر للاستعلام أو العرض */
const SEARCH_UNSAFE_CHARS_RE = /[\u0000-\u001F\u007F\u202A-\u202E\u2066-\u2069]/g;

export function stripSearchUnsafeChars(raw: string): string {
    return raw.replace(SEARCH_UNSAFE_CHARS_RE, '');
}

export function clampGlobalSearchQuery(raw: string): string {
    if (!raw) return '';
    return stripSearchUnsafeChars(raw)
        .replace(/<[^>]*>/g, '')
        .slice(0, GLOBAL_SEARCH_MAX_QUERY_LENGTH);
}

export function clampRecentSearchLabel(raw: string): string {
    const trimmed = stripSearchUnsafeChars(raw).replace(/<[^>]*>/g, '').trim();
    if (!trimmed) return '';
    return trimmed.slice(0, GLOBAL_SEARCH_MAX_RECENT_LABEL_LENGTH);
}

export function sanitizeRecentSearchLabels(raw: unknown): string[] {
    if (!Array.isArray(raw)) return [];
    const seen = new Set<string>();
    const out: string[] = [];
    for (const item of raw) {
        if (typeof item !== 'string') continue;
        const label = clampRecentSearchLabel(item);
        if (!label || seen.has(label)) continue;
        seen.add(label);
        out.push(label);
        if (out.length >= GLOBAL_SEARCH_MAX_RECENT_COUNT) break;
    }
    return out;
}

export function pushGlobalSearchRecentLabel(prev: readonly string[], label: string): string[] {
    const safe = clampRecentSearchLabel(label);
    if (!safe) return prev.length ? [...prev] : [];
    return [safe, ...prev.filter((s) => s !== safe)].slice(0, GLOBAL_SEARCH_MAX_RECENT_COUNT);
}

import {
    globalSearchRecentStorageKey,
    sanitizeRecentSearchLabels,
} from '@/app/services/search/globalSearchQuerySecurity';

/**
 * قراءة أخيرة بلا SecureStore — لغطاء InstantPaintCover حتى لا يدخل التشفير على FullBoot.
 * الطبقة الحية (`useGlobalSearch`) تُرطّب عبر SecureStore عند الفتح الكامل.
 */
export function peekGlobalSearchRecentSearches(userId: string | null | undefined): string[] {
    const key = globalSearchRecentStorageKey(userId);
    if (!key || typeof localStorage === 'undefined') return [];
    try {
        const saved = localStorage.getItem(key);
        if (!saved) return [];
        return sanitizeRecentSearchLabels(JSON.parse(saved));
    } catch {
        return [];
    }
}

