    if (key.startsWith('hami:home-hub-radar-dismissed:v1:')) return true;
    return false;
}

export function isSensitiveStorageKey(key: string): boolean {
    if (isNeverEncryptedKey(key)) return false;
    if (isCriminalShardKey(key)) return true;
    if (ENCRYPTED_EXACT_KEYS.has(key)) return true;
    return ENCRYPTED_KEY_PREFIXES.some((prefix) => key.startsWith(prefix));
}

export function encryptionSizeLimitFor(key: string): number {
    return isCriminalShardKey(key) ? CRIMINAL_SHARD_ENCRYPT_MAX_BYTES : ENCRYPT_MAX_BYTES;
}

/**
 * مفتاح حسّاس تجاوزت حمولته الحدّ فتُخزَّن **نصّاً صريحاً**.
 *
 * هذا هو الفرع الذي يُسقط التشفير عن أكبر الحمولات — أي عن الإضابير الأثقل، وهي
 * غالباً الأغنى بأسماء الموكّلين وأرقامهم الوطنية.
 *
 * **استثناء الدعاوى المُسخَّنة:** `lawyer_files` / `_active` / `_index` /
 * `_archived` / `_trash` (+ legacy) لا تسقط إلى plaintext — تُشفَّر حتى فوق الحدّ
 * (encrypt-or-fail عبر CryptoService). archived/trash تُسخَّن عند فتح مساحة
 * الدعاوى عبر `warmLawsuitWorkspace` حتى تبقى `getItemSync` صالحة بعد الفتح.
 *
 * بلوبات التنفيذ: plaintext محلي — لا تشفير فوق الحدّ.
 * مفاتيح التسخين الحسّاسة (`isWarmEncryptAlwaysKey`) — لا مرآة صريحة فوق الحدّ.
 * شظايا القضايا الجنائية: تشفير أو فشل (التجزئة تُبقي كل جزء تحت حدّ التشفير).
 */
export function fallsBackToPlaintextBySize(key: string, value: string): boolean {
    if (!isSensitiveStorageKey(key)) return false;
    if (isLawsuitEncryptAlwaysKey(key)) return false;
    if (isWarmEncryptAlwaysKey(key)) return false;
    if (isCriminalShardKey(key)) return false;
    return value.length > encryptionSizeLimitFor(key);
}

export function shouldEncryptValue(key: string, value: string): boolean {
    if (!isSensitiveStorageKey(key)) return false;
    return !fallsBackToPlaintextBySize(key, value);
}

import type SecureStoreService from '@/app/services/SecureStoreService';

/** جسر E2E للقراءة بعد التشفير — preview لا يستطيع import `/src/...` */
export function bindSecureStoreE2eBridge(store: typeof SecureStoreService): void {
    if (typeof window === 'undefined') return;
    if (import.meta.env.VITE_SHELL_AUTH_OPEN !== 'true') return;
    if (import.meta.env.VITEST) return;

    const w = window as Window & {
        __hamiE2eSecureStore?: {
            flushHeavyPersistPending: () => void;
            waitForAllPendingPersist: () => Promise<void>;
            ensurePersistedReady: () => Promise<void>;
            getItemSync: (key: string) => string | null;
            getItem: (key: string) => Promise<string | null>;
            getItemFromDisk: (key: string) => Promise<string | null>;
            setItemSync: (key: string, value: string) => boolean;
            setItem: (key: string, value: string) => Promise<void>;
            deleteItem: (key: string) => Promise<void>;
        };
    };
    w.__hamiE2eSecureStore = {
        flushHeavyPersistPending: () => store.flushHeavyPersistPending(),
        waitForAllPendingPersist: () => store.waitForAllPendingPersist(),
        ensurePersistedReady: () => store.ensurePersistedReady(),
        getItemSync: (key) => store.getItemSync(key),
            getItem: (key) => store.getItem(key),
            getItemFromDisk: (key) => store.getItemFromDisk(key),
            setItemSync: (key, value) => store.setItemSync(key, value),
        setItem: (key, value) => store.setItem(key, value),
        deleteItem: (key) => store.deleteItem(key),
    };
}

/**
 * سياسة استعادة plaintext بعد فشل فك التشفير (معلنة — ليست صامتة):
 * - مسار هجرة متعمّد من localStorage قديم / نسخة احتياطية للدومين.
 * - يُستدعى مرة واحدة لكل مفتاح (memo عبر decryptRecoveryAttempted).
 * - كل استعادة ناجحة تُسجَّل عبر debug.warn (لا نجاح صامت).
 * - افتراضياً مُعطَّل؛ يُفعَّل صراحةً بـ VITE_SECURE_STORE_PLAINTEXT_RECOVERY=true أثناء الهجرة فقط.
 */
import type { BackupDomain } from '@/app/services/dossierPersistence/dossierPersistenceTypes';
import {
    backupDomainForStorageKey,
    isTransactionsThreadingStateKey,
} from '@/app/services/dossierPersistence/protectedStorageKeys';
import {
    EXECUTION_FILES_STORAGE_KEY,
    EXECUTION_FILES_STORAGE_KEYS_LEGACY,
    LAWSUIT_FILES_STORAGE_KEY,
    LAWSUIT_FILES_STORAGE_KEYS_LEGACY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';
import { debug } from '@/app/utils/debug';

const LAWYER_NOTES_STORAGE_KEY = 'lawyer_notes';

const ENCRYPTED_PREFIX = 'hami_enc_v2:';
const decryptRecoveryAttempted = new Set<string>();

function isEncryptedBlob(raw: string): boolean {
    return raw.startsWith(ENCRYPTED_PREFIX);
}

function readLegacyPlaintextFromLocalStorage(key: string): string | null {
    if (typeof window === 'undefined') return null;
    try {
        const ls = globalThis.localStorage;
        if (!ls) return null;
        const raw = ls.getItem(key);
        if (!raw?.trim() || isEncryptedBlob(raw)) return null;
        JSON.parse(raw);
        return raw;
    } catch {
        return null;
    }
}

function lawsuitDomainForKey(key: string): boolean {
    return key === LAWSUIT_FILES_STORAGE_KEY || LAWSUIT_FILES_STORAGE_KEYS_LEGACY.includes(key as never);
}

function executionDomainForKey(key: string): boolean {
    return key === EXECUTION_FILES_STORAGE_KEY || EXECUTION_FILES_STORAGE_KEYS_LEGACY.includes(key as never);
}

async function readBackup(domain: BackupDomain): Promise<string | null> {
    if (__HAMI_CLIENT_PRODUCT__ === 'hq') return null;
    const { readLatestDossierBackup } = await import(
        '@/app/services/dossierPersistence/dossierBackupStore'
    );
    const backup = await readLatestDossierBackup(domain);
    if (!backup?.payload.length) return null;
    return JSON.stringify(backup.payload);
}

/** هل مسار استعادة plaintext مفعّل صراحةً؟ (افتراضي: لا) */
export function isPlaintextRecoveryEnabled(): boolean {
    return import.meta.env.VITE_SECURE_STORE_PLAINTEXT_RECOVERY === 'true';
}

/** استعادة plaintext عند فشل فك التشفير — نسخة احتياطية أو localStorage قديم */
export async function recoverPlaintextAfterDecryptFailure(storageKey: string): Promise<string | null> {
    if (!isPlaintextRecoveryEnabled()) {
        return null;
    }
    if (decryptRecoveryAttempted.has(storageKey)) return null;
    decryptRecoveryAttempted.add(storageKey);

    const announce = (source: string, value: string | null): string | null => {
        if (!value) return null;
        debug.warn(
            `[SecureStoreRecovery] plaintext recovery used for key=${storageKey} source=${source}`,
        );
        return value;
    };

    for (const legacyKey of LAWSUIT_FILES_STORAGE_KEYS_LEGACY) {
        if (storageKey === legacyKey || storageKey === LAWSUIT_FILES_STORAGE_KEY) {
            const fromLs = announce(`legacy-ls:${legacyKey}`, readLegacyPlaintextFromLocalStorage(legacyKey));
            if (fromLs) return fromLs;
        }
    }
    for (const legacyKey of EXECUTION_FILES_STORAGE_KEYS_LEGACY) {
        if (storageKey === legacyKey || storageKey === EXECUTION_FILES_STORAGE_KEY) {
            const fromLs = announce(`legacy-ls:${legacyKey}`, readLegacyPlaintextFromLocalStorage(legacyKey));
            if (fromLs) return fromLs;
        }
    }

    const fromPrimaryLs = announce('primary-ls', readLegacyPlaintextFromLocalStorage(storageKey));
    if (fromPrimaryLs) return fromPrimaryLs;

    if (lawsuitDomainForKey(storageKey)) {
        return announce('backup:lawsuit', await readBackup('lawsuit'));
    }
    if (executionDomainForKey(storageKey)) {
        return announce('backup:execution', await readBackup('execution'));
    }

    if (isTransactionsThreadingStateKey(storageKey)) {
        if (__HAMI_CLIENT_PRODUCT__ === 'hq') return null;
        const { readLatestDossierBackup } = await import(
            '@/app/services/dossierPersistence/dossierBackupStore'
        );
        const backup = await readLatestDossierBackup('transactionsThreading');
        const first = backup?.payload[0];
        if (first && typeof first === 'object' && !Array.isArray(first)) {
            return announce('backup:transactionsThreading', JSON.stringify(first));
        }
        return null;
    }

    const backupDomain = backupDomainForStorageKey(storageKey);
    if (backupDomain && backupDomain !== 'lawsuit' && backupDomain !== 'execution') {
        return announce(`backup:${backupDomain}`, await readBackup(backupDomain));
    }

    if (storageKey === LAWYER_NOTES_STORAGE_KEY) {
        return announce('backup:notes', await readBackup('notes'));
    }
    if (storageKey === 'hami:community:posts:v1') {
        return announce('backup:community', await readBackup('community'));
    }
    if (storageKey === 'hami:smartvault:docs:v1') {
        return announce('backup:vault', await readBackup('vault'));
    }
    if (storageKey === 'hami:calendar:events:v1') {
        return announce('backup:calendar', await readBackup('calendar'));
    }
    if (storageKey === 'hami_quantum_legal_tasks_v1') {
        return announce('backup:tasks', await readBackup('tasks'));
    }

    return null;
}

export function clearDecryptRecoveryAttempt(storageKey: string): void {
    decryptRecoveryAttempted.delete(storageKey);
}

