type MalwareScanResult = {
  safe: boolean;
  reason?: string;
};

interface MalwareScanAdapter {
  scan(buffer: Buffer): Promise<MalwareScanResult>;
}

const PDF_SIGNATURE = Buffer.from('%PDF-');
const SUSPICIOUS_PDF_MARKERS = [
  '/JS',
  '/JavaScript',
  '/OpenAction',
  '/AA',
  '/Launch',
  '/EmbeddedFile',
  '/RichMedia',
] as const;

function isPdfBuffer(buffer: Buffer): boolean {
  if (!buffer || buffer.length < PDF_SIGNATURE.length) return false;
  return buffer.subarray(0, PDF_SIGNATURE.length).equals(PDF_SIGNATURE);
}

function scanPdfHeuristics(buffer: Buffer): MalwareScanResult {
  if (!isPdfBuffer(buffer)) return { safe: true };

  const text = buffer.subarray(0, Math.min(buffer.length, 2_000_000)).toString('latin1');
  const suspiciousHits = SUSPICIOUS_PDF_MARKERS.filter((marker) => text.includes(marker));
  if (suspiciousHits.length === 0) return { safe: true };

  return {
    safe: false,
    reason: `Suspicious PDF action markers detected: ${suspiciousHits.join(', ')}`,
  };
}

class HeuristicMalwareScanAdapter implements MalwareScanAdapter {
  async scan(buffer: Buffer): Promise<MalwareScanResult> {
    return scanPdfHeuristics(buffer);
  }
}

class CloudmersiveMalwareScanAdapter implements MalwareScanAdapter {
  private readonly apiKey: string;
  private readonly endpoint = 'https://api.cloudmersive.com/virus/scan/file';

  constructor(apiKey: string) {
    this.apiKey = apiKey;
  }

  async scan(buffer: Buffer): Promise<MalwareScanResult> {
    const form = new FormData();
    const bytes = new Uint8Array(buffer);
    form.append('inputFile', new Blob([bytes]), 'scan.bin');

    const abort = new AbortController();
    const timer = setTimeout(() => abort.abort(), 12_000);
    try {
      const res = await fetch(this.endpoint, {
        method: 'POST',
        headers: {
          Apikey: this.apiKey,
        },
        body: form,
        signal: abort.signal,
      });
      if (!res.ok) {
        return { safe: false, reason: `Cloud scan failed with status ${res.status}` };
      }

      const data = (await res.json().catch(() => null)) as Record<string, unknown> | null;
      const clean = Boolean(data?.CleanResult);
      return clean ? { safe: true } : { safe: false, reason: 'Cloud malware scan flagged file' };
    } catch {
      return { safe: false, reason: 'Cloud malware scan request failed' };
    } finally {
      clearTimeout(timer);
    }
  }
}

function resolveAdapter(): MalwareScanAdapter {
  const cloudKey = (process.env.CLOUDMERSIVE_API_KEY ?? '').trim();
  if (cloudKey) return new CloudmersiveMalwareScanAdapter(cloudKey);
  return new HeuristicMalwareScanAdapter();
}

export async function scanBufferForMalware(buffer: Buffer): Promise<MalwareScanResult> {
  const adapter = resolveAdapter();
  return await adapter.scan(buffer);
}

