    }
}

export async function buildBusinessBackupPayload(
    selection: BusinessBackupSelection,
    options: { materializeVaultBlobs?: boolean } = {},
) {
    const items: Record<string, string> = {};
    const vaultBlobs: BusinessBackupVaultBlob[] = [];
    let estimatedVaultManifestBytes = 0;
    const materializeVaultBlobs = options.materializeVaultBlobs !== false;
    const counts: BusinessBackupCounts = {
        lawsuits: { items: 0, undated: 0 },
        execution: { items: 0, undated: 0 },
        notes: { items: 0, undated: 0 },
        vault: { items: 0, undated: 0, localFiles: 0, localBytes: 0 },
        urgent: { keys: 0 },
    };

    const includeKeys: string[] = [];

    if (selection.includeLawsuits) {
        includeKeys.push(
            STORAGE_KEYS.LAWYER_FILES,
            LAWSUIT_FILES_STORAGE_KEY,
            LAWSUIT_FILES_ACTIVE_KEY,
            LAWSUIT_FILES_ARCHIVED_KEY,
            LAWSUIT_FILES_TRASH_KEY,
            LAWSUIT_FILES_INDEX_KEY,
        );
    }
    if (selection.includeExecution) includeKeys.push(EXECUTION_FILES_STORAGE_KEY);
    if (selection.includeNotes) {
        includeKeys.push(STORAGE_KEYS.LAWYER_NOTES, 'globalNotes', 'global_notes', 'hami_notes_vault');
    }
    if (selection.includeVault) includeKeys.push('hami_docs_vault', VAULT_LOCAL_KEY);

    const allKeys = await SecureStoreService.listKeys();
    if (selection.includeExecution) {
        allKeys
            .filter(
                (k) =>
                    (k.startsWith('execution_') && k !== EXECUTION_FILES_STORAGE_KEY) ||
                    k.startsWith(`${EXECUTION_FILES_STORAGE_KEY}:`),
            )
            .forEach((k) => includeKeys.push(k));
    }
    if (selection.includeNotes) {
        allKeys.filter((k) => k.startsWith('hami_notes_vault_')).forEach((k) => includeKeys.push(k));
    }
    if (selection.includeUrgent) {
        const urgentKeys = allKeys.filter((k) => k.startsWith('hami:urgentActions:v1:'));
        urgentKeys.forEach((k) => includeKeys.push(k));
        counts.urgent.keys = urgentKeys.length;
    }

    const uniqueKeys = Array.from(new Set(includeKeys));

    for (const k of uniqueKeys) {
        const raw = await SecureStoreService.getItem(k);
        if (typeof raw === 'string') items[k] = raw;
    }

    const parseArrayCount = async (key: string) => {
        const v = await readJson(key);
        if (!Array.isArray(v)) return { items: 0, undated: 0, raw: null as unknown[] | null };
        const { filtered, undated } = filterByRange(v, selection);
        return { items: filtered.length, undated, raw: filtered };
    };

    if (selection.includeLawsuits) {
        const lawsuitCountKey = items[LAWSUIT_FILES_ACTIVE_KEY]
            ? LAWSUIT_FILES_ACTIVE_KEY
            : STORAGE_KEYS.LAWYER_FILES;
        if (items[lawsuitCountKey]) {
            const parsed = await parseArrayCount(lawsuitCountKey);
            counts.lawsuits.items = parsed.items;
            counts.lawsuits.undated = parsed.undated;
            items[lawsuitCountKey] = JSON.stringify(parsed.raw ?? []);
        }
        for (const key of [LAWSUIT_FILES_ARCHIVED_KEY, LAWSUIT_FILES_TRASH_KEY, STORAGE_KEYS.LAWYER_FILES]) {
            if (key === lawsuitCountKey || !items[key]) continue;
            const parsed = await parseArrayCount(key);
            items[key] = JSON.stringify(parsed.raw ?? []);
        }
    }

    const executionIndexKeys = Object.keys(items).filter(
        (key) => key === EXECUTION_FILES_STORAGE_KEY || key.startsWith(`${EXECUTION_FILES_STORAGE_KEY}:`),
    );
    if (selection.includeExecution && executionIndexKeys.length > 0) {
        let richest: { items: number; undated: number; raw: unknown[] | null; key: string } = {
            items: 0,
            undated: 0,
            raw: null,
            key: executionIndexKeys[0],
        };
        for (const key of executionIndexKeys) {
            const parsed = await parseArrayCount(key);
            items[key] = JSON.stringify(parsed.raw ?? []);
            if (parsed.items >= richest.items) {
                richest = { ...parsed, key };
            }
        }
        counts.execution.items = richest.items;
        counts.execution.undated = richest.undated;

        if (selection.from || selection.to) {
            const selectedIds = new Set(
                (richest.raw ?? [])
                    .map((item) => {
                        if (!item || typeof item !== 'object' || Array.isArray(item)) return '';
                        const id = (item as Record<string, unknown>).id;
                        return typeof id === 'string' || typeof id === 'number' ? String(id).trim() : '';
                    })
                    .filter(Boolean),
            );
            const selectedDossierIds = [...selectedIds];
            for (const key of Object.keys(items)) {
                if (!key.startsWith('execution_') || key === EXECUTION_FILES_STORAGE_KEY) continue;
                if (key.startsWith(`${EXECUTION_FILES_STORAGE_KEY}:`)) continue;
                const belongsToSelectedDossier = selectedDossierIds.some((id) => {
                    const dossierBase = `execution_${id}`;
                    return (
                        key === dossierBase ||
                        key.startsWith(`${dossierBase}_`) ||
                        key.startsWith(`${dossierBase}:u:`) ||
                        key.startsWith(`execution_form_${id}`)
                    );
                });
                if (!belongsToSelectedDossier) delete items[key];
            }
        }
    }

    if (selection.includeNotes) {
        const noteKeys = Object.keys(items).filter(
            (key) =>
                key === STORAGE_KEYS.LAWYER_NOTES ||
                key === 'globalNotes' ||
                key === 'global_notes' ||
                key === 'hami_notes_vault' ||
                key.startsWith('hami_notes_vault_'),
        );
        for (const key of noteKeys) {
            const parsed = await parseArrayCount(key);
            counts.notes.items += parsed.items;
            counts.notes.undated += parsed.undated;
            items[key] = JSON.stringify(parsed.raw ?? []);
        }
    }

    if (selection.includeVault) {
        const selectedVaultDocs = new Map<string, Record<string, unknown>>();
        const undatedVaultDocs = new Set<string>();
        for (const key of ['hami_docs_vault', VAULT_LOCAL_KEY]) {
            if (!items[key]) continue;
            let raw: unknown;
            try {
                raw = JSON.parse(items[key]);
            } catch {
                raw = null;
            }
            if (!Array.isArray(raw)) {
                items[key] = '[]';
                continue;
            }
            const { filtered } = filterByRange(raw, selection);
            items[key] = JSON.stringify(filtered);
            raw.forEach((candidate, index) => {
                if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) return;
                const doc = candidate as Record<string, unknown>;
                const id = typeof doc.id === 'string' ? doc.id.trim() : '';
                const authorId = typeof doc.authorId === 'string' ? doc.authorId.trim() : '';
                const identity = id && authorId ? `${authorId}:${id}` : `${key}:${index}`;
                if (!extractDate(doc)) undatedVaultDocs.add(identity);
            });
            filtered.forEach((candidate, index) => {
                if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) return;
                const doc = candidate as Record<string, unknown>;
                const id = typeof doc.id === 'string' ? doc.id.trim() : '';
                const authorId = typeof doc.authorId === 'string' ? doc.authorId.trim() : '';
                const identity = id && authorId ? `${authorId}:${id}` : `${key}:${index}`;
                selectedVaultDocs.set(identity, doc);
            });
        }
        counts.vault.items = selectedVaultDocs.size;
        counts.vault.undated = undatedVaultDocs.size;

        const localDocs = [...selectedVaultDocs.values()].filter(
            (doc) => typeof doc.storagePath === 'string' && doc.storagePath.startsWith('idb:vault:'),
        );
        if (localDocs.length > MAX_BACKUP_VAULT_BLOB_COUNT) {
            throw new Error('عدد ملفات المخزن المحلي يتجاوز حد النسخة الآمن');
        }
        if (localDocs.length > 0 && !materializeVaultBlobs) {
            for (const doc of localDocs) {
                const size =
                    typeof doc.fileSize === 'number' &&
                    Number.isSafeInteger(doc.fileSize) &&
                    doc.fileSize >= 0
                        ? doc.fileSize
                        : 0;
                if (counts.vault.localBytes + size > MAX_BACKUP_VAULT_BINARY_BYTES) {
                    throw new Error('ملفات المخزن المحلي تتجاوز حد النسخة الآمن للهاتف');
                }
                counts.vault.localFiles += 1;
                counts.vault.localBytes += size;
                estimatedVaultManifestBytes += Math.ceil(size / 3) * 4 + 320;
            }
        } else if (localDocs.length > 0) {
            const vaultStore = await import('@/app/services/vaultBlobStore');
            await vaultStore.waitForVaultBlobWrites();
            for (const doc of localDocs) {
                const parsedPath = vaultStore.parseVaultIdbPath(String(doc.storagePath));
                if (!parsedPath) throw new Error('مسار ملف محلي غير صالح في المخزن الذكي');
                const blob = await vaultStore.getVaultBlob(parsedPath.userId, parsedPath.docId);
                if (!blob) {
                    throw new Error(`ملف المخزن المحلي غير متاح للنسخ: ${String(doc.fileName ?? doc.id ?? '')}`);
                }
                if (counts.vault.localBytes + blob.size > MAX_BACKUP_VAULT_BINARY_BYTES) {
                    throw new Error('ملفات المخزن المحلي تتجاوز حد النسخة الآمن للهاتف');
                }
                const buffer = await blob.arrayBuffer();
                const mimeType =
                    (typeof doc.mimeType === 'string' && doc.mimeType) ||
                    blob.type ||
                    'application/octet-stream';
                vaultBlobs.push({
                    authorId: parsedPath.userId,
                    docId: parsedPath.docId,
                    mimeType,
                    size: buffer.byteLength,
                    sha256: await sha256Hex(buffer),
                    data: toBase64(buffer),
                });
                counts.vault.localFiles += 1;
                counts.vault.localBytes += buffer.byteLength;
            }
        }
    }

    const payload = {
        kind: 'hami-business-backup',
        version: 2,
        createdAt: new Date().toISOString(),
        selection: {
            lawsuits: selection.includeLawsuits,
            execution: selection.includeExecution,
            notes: selection.includeNotes,
            vault: selection.includeVault,
            urgent: selection.includeUrgent,
        },
        range: {
            from: selection.from || null,
            to: selection.to || null,
            includeUndated: selection.includeUndated,
        },
        counts,
        items,
        vaultBlobs,
    };

    const text = JSON.stringify(payload);
    const entries = Object.entries(items);
    if (entries.length > 0) {
        const validation = validateBusinessBackupImport(entries);
        if (!validation.ok) throw new Error(validation.reason);
    }
    validateVaultBlobRecords(vaultBlobs);
    const bytes = new TextEncoder().encode(text).byteLength + estimatedVaultManifestBytes;
    if (bytes > MAX_BACKUP_PLAINTEXT_BYTES) {
        throw new Error('حجم النسخة يتجاوز الحد الآمن للأجهزة المحمولة');
    }
    return {
        payload,
        text,
        bytes,
        keys: Object.keys(items).length,
        counts,
    };
}

import {
    BACKUP_KDF_ITERATIONS,
    BACKUP_KDF_MAX_ITERATIONS,
    BACKUP_KDF_MIN_ITERATIONS,
    MAX_BACKUP_PLAINTEXT_BYTES,
    validateBackupPassword,
} from '@/app/services/settings/businessBackupSecurity';
import { fromBase64, toBase64 } from './businessBackupEncoding';

async function derivePasswordKey(password: string, salt: Uint8Array<ArrayBuffer>, iterations: number) {
    const keyMaterial = await crypto.subtle.importKey(
        'raw',
        new TextEncoder().encode(password),
        { name: 'PBKDF2' },
        false,
        ['deriveKey'],
    );
    return crypto.subtle.deriveKey(
        { name: 'PBKDF2', salt, iterations, hash: 'SHA-256' },
        keyMaterial,
        { name: 'AES-GCM', length: 256 },
        false,
        ['encrypt', 'decrypt'],
    );
}

export async function encryptBusinessBackupText(plainText: string, password: string) {
    const passwordCheck = validateBackupPassword(password);
    if (!passwordCheck.ok) throw new Error(`invalid backup password:${passwordCheck.reason}`);
    const plainBytes = new TextEncoder().encode(plainText);
    if (plainBytes.byteLength > MAX_BACKUP_PLAINTEXT_BYTES) {
        throw new Error('backup plaintext exceeds mobile-safe limit');
    }
    const saltBuf = new ArrayBuffer(16);
    const salt = new Uint8Array(saltBuf);
    crypto.getRandomValues(salt);
    const ivBuf = new ArrayBuffer(12);
    const iv = new Uint8Array(ivBuf);
    crypto.getRandomValues(iv);
    const iterations = BACKUP_KDF_ITERATIONS;
    const key = await derivePasswordKey(password, salt, iterations);
    const cipher = await crypto.subtle.encrypt(
        { name: 'AES-GCM', iv },
        key,
        plainBytes,
    );
    return {
        kind: 'hami-business-backup-encrypted' as const,
        version: 1 as const,
        createdAt: new Date().toISOString(),
        kdf: { name: 'PBKDF2' as const, hash: 'SHA-256' as const, iterations },
        salt: toBase64(salt.buffer),
        iv: toBase64(iv.buffer),
        ciphertext: toBase64(cipher),
    };
}

export async function decryptBusinessBackupText(
    encrypted: {
        kind?: unknown;
        version?: unknown;
        kdf?: unknown;
        salt?: unknown;
        iv?: unknown;
        ciphertext?: unknown;
    },
    password: string,
) {
    if (encrypted.kind !== 'hami-business-backup-encrypted' || encrypted.version !== 1) {
        throw new Error('invalid encrypted backup envelope');
    }
    const saltB64 = typeof encrypted.salt === 'string' ? encrypted.salt : '';
    const ivB64 = typeof encrypted.iv === 'string' ? encrypted.iv : '';
    const cipherB64 = typeof encrypted.ciphertext === 'string' ? encrypted.ciphertext : '';
    const kdf = encrypted.kdf as { iterations?: unknown } | undefined;
    const iterations = typeof kdf?.iterations === 'number' ? kdf.iterations : Number.NaN;
    if (!saltB64 || !ivB64 || !cipherB64) throw new Error('invalid encrypted backup');
    if (
        !Number.isSafeInteger(iterations) ||
        iterations < BACKUP_KDF_MIN_ITERATIONS ||
        iterations > BACKUP_KDF_MAX_ITERATIONS
    ) {
        throw new Error('invalid backup KDF iterations');
    }
    if (
        !kdf ||
        (kdf as { name?: unknown }).name !== 'PBKDF2' ||
        (kdf as { hash?: unknown }).hash !== 'SHA-256'
    ) {
        throw new Error('unsupported backup KDF');
    }
    if (cipherB64.length > Math.ceil(MAX_BACKUP_PLAINTEXT_BYTES / 3) * 4 + 64) {
        throw new Error('encrypted backup exceeds size limit');
    }
    const salt = new Uint8Array(fromBase64(saltB64, 'salt'));
    const iv = new Uint8Array(fromBase64(ivB64, 'iv'));
    const cipher = fromBase64(cipherB64, 'ciphertext');
    if (salt.byteLength !== 16 || iv.byteLength !== 12 || cipher.byteLength < 16) {
        throw new Error('invalid encrypted backup parameters');
    }
    const key = await derivePasswordKey(password, salt, iterations);
    const plainBuf = await crypto.subtle.decrypt({ name: 'AES-GCM', iv }, key, cipher);
    if (plainBuf.byteLength > MAX_BACKUP_PLAINTEXT_BYTES) {
        throw new Error('decrypted backup exceeds size limit');
    }
    return new TextDecoder().decode(plainBuf);
}

import {
    MAX_BACKUP_VAULT_BINARY_BYTES,
    MAX_BACKUP_VAULT_BLOB_COUNT,
    type BusinessBackupVaultBlob,
} from './businessBackupTypes';

export function toBase64(buf: ArrayBuffer) {
    const bytes = new Uint8Array(buf);
    let binary = '';
    const chunkSize = 0x8000;
    for (let i = 0; i < bytes.length; i += chunkSize) {
        binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
    }
    return btoa(binary);
}

export function fromBase64(b64: string, label: string) {
    if (!/^[A-Za-z0-9+/]*={0,2}$/u.test(b64) || b64.length % 4 !== 0) {
        throw new Error(`invalid ${label} encoding`);
    }
    const binary = atob(b64);
    const buf = new ArrayBuffer(binary.length);
    const bytes = new Uint8Array(buf);
    for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
    return buf;
}

function decodedBase64ByteLength(value: string): number {
    if (value.length === 0) return 0;
    const padding = value.endsWith('==') ? 2 : value.endsWith('=') ? 1 : 0;
    return (value.length / 4) * 3 - padding;
}

export function validateVaultBlobRecords(value: unknown): BusinessBackupVaultBlob[] {
    if (value === undefined) return [];
    if (!Array.isArray(value) || value.length > MAX_BACKUP_VAULT_BLOB_COUNT) {
        throw new Error('invalid vault blob manifest');
    }
    const records: BusinessBackupVaultBlob[] = [];
    const seen = new Set<string>();
    let totalBytes = 0;
    for (const candidate of value) {
        if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) {
            throw new Error('invalid vault blob record');
        }
        const record = candidate as Record<string, unknown>;
        const authorId = typeof record.authorId === 'string' ? record.authorId : '';
        const docId = typeof record.docId === 'string' ? record.docId : '';
        const mimeType = typeof record.mimeType === 'string' ? record.mimeType : '';
        const sha256 = typeof record.sha256 === 'string' ? record.sha256 : '';
        const data = typeof record.data === 'string' ? record.data : '';
        const size = record.size;
        if (
            !authorId ||
            authorId !== authorId.trim() ||
            authorId.length > 128 ||
            authorId.includes(':') ||
            /[\u0000-\u001f\u007f]/u.test(authorId) ||
            !docId ||
            docId !== docId.trim() ||
            docId.length > 512 ||
            /[\u0000-\u001f\u007f]/u.test(docId) ||
            !/^[\w.+-]+\/[\w.+-]+$/iu.test(mimeType) ||
            mimeType.length > 200 ||
            !/^[a-f0-9]{64}$/u.test(sha256) ||
            !Number.isSafeInteger(size) ||
            (size as number) < 0 ||
            !/^[A-Za-z0-9+/]*={0,2}$/u.test(data) ||
            data.length % 4 !== 0 ||
            decodedBase64ByteLength(data) !== size
        ) {
            throw new Error('invalid vault blob record');
        }
        const identity = `${authorId}:${docId}`;
        if (seen.has(identity)) throw new Error('duplicate vault blob record');
        seen.add(identity);
        totalBytes += size as number;
        if (totalBytes > MAX_BACKUP_VAULT_BINARY_BYTES) {
            throw new Error('vault blobs exceed the mobile-safe backup limit');
        }
        records.push({
            authorId,
            docId,
            mimeType,
            size: size as number,
            sha256,
            data,
        });
    }
    return records;
}

export async function sha256Hex(value: ArrayBuffer): Promise<string> {
    const digest = await crypto.subtle.digest('SHA-256', value);
    return [...new Uint8Array(digest)]
        .map((byte) => byte.toString(16).padStart(2, '0'))
        .join('');
}

import SecureStoreService from '@/app/services/SecureStoreService';
import {
    MAX_BACKUP_PLAINTEXT_BYTES,
    validateBusinessBackupImport,
} from '@/app/services/settings/businessBackupSecurity';
import { VAULT_LOCAL_KEY } from '@/app/services/vault/vaultLocalIndex';
import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import type { BusinessBackupVaultBlob } from './businessBackupTypes';
import { fromBase64, sha256Hex, validateVaultBlobRecords } from './businessBackupEncoding';

export async function importBusinessBackupEntries(
    entries: Array<[string, string]>,
    vaultBlobInput: BusinessBackupVaultBlob[] = [],
) {
    const validation = validateBusinessBackupImport(entries);
    if (validation.ok === false) {
        throw new Error(validation.reason);
    }
    const vaultBlobs = validateVaultBlobRecords(vaultBlobInput);
    const vaultStore =
        vaultBlobs.length > 0 ? await import('@/app/services/vaultBlobStore') : null;
    const expectedVaultBlobPaths = new Set<string>();
    for (const [key, value] of entries) {
        if (key !== 'hami_docs_vault' && key !== VAULT_LOCAL_KEY) continue;
        const docs = JSON.parse(value) as unknown;
        if (!Array.isArray(docs)) continue;
        for (const candidate of docs) {
            if (!candidate || typeof candidate !== 'object' || Array.isArray(candidate)) continue;
            const storagePath = (candidate as Record<string, unknown>).storagePath;
            if (typeof storagePath === 'string' && storagePath.startsWith('idb:vault:')) {
                expectedVaultBlobPaths.add(storagePath);
            }
        }
    }
    const preparedVaultBlobs: Array<{
        record: BusinessBackupVaultBlob;
        blob: Blob;
        previous: Blob | null;
    }> = [];
    if (vaultStore) {
        for (const record of vaultBlobs) {
            const expectedPath = vaultStore.buildVaultIdbPath(record.authorId, record.docId);
            if (!expectedVaultBlobPaths.has(expectedPath)) {
                throw new Error('vault blob is not referenced by the imported vault index');
            }
            const buffer = fromBase64(record.data, 'vault blob');
            if ((await sha256Hex(buffer)) !== record.sha256) {
                throw new Error('vault blob checksum mismatch');
            }
            preparedVaultBlobs.push({
                record,
                blob: new Blob([buffer], { type: record.mimeType }),
                previous: await vaultStore.getVaultBlob(record.authorId, record.docId),
            });
        }
    }

    const snapshot = new Map<string, string | null>();
    for (const [k] of entries) {
        if (typeof k !== 'string') continue;
        const prior = await SecureStoreService.getItem(k);
        snapshot.set(k, prior == null ? null : String(prior));
    }

    const written: string[] = [];
    const writtenVaultBlobs: typeof preparedVaultBlobs = [];
    try {
        for (const [k, v] of entries) {
            await SecureStoreService.setItem(k, v, { allowVerifiedEmptyOverwrite: true });
            if ((await SecureStoreService.getItem(k)) !== v) {
                throw new Error(`backup restore verification failed:${k}`);
            }
            written.push(k);
            persistenceRepository.synchronizeExternalWrite(k, v);
        }
        if (vaultStore) {
            for (const prepared of preparedVaultBlobs) {
                const { record, blob } = prepared;
                await vaultStore.putVaultBlobVerified(
                    record.authorId,
                    record.docId,
                    blob,
                    record.mimeType,
                );
                writtenVaultBlobs.push(prepared);
            }
        }
        const executionEntries = entries.filter(([key]) =>
            key === 'executionFiles' ||
            key.startsWith('executionFiles:') ||
            key.startsWith('execution_'),
        );
        if (executionEntries.length > 0) {
            const { storageCache } = await import('@/app/utils/storageCache');
            for (const [key, value] of executionEntries) {
                storageCache.touchCacheEntry(key, JSON.parse(value));
            }
        }
        window.dispatchEvent(
            new CustomEvent('hami:data-imported', {
                detail: { keys: entries.map(([key]) => key) },
            }),
        );
    } catch (err) {
        let rollbackIncomplete = false;
        if (vaultStore) {
            for (const prepared of writtenVaultBlobs.reverse()) {
                try {
                    if (prepared.previous) {
                        await vaultStore.putVaultBlobVerified(
                            prepared.record.authorId,
                            prepared.record.docId,
                            prepared.previous,
                            prepared.previous.type || prepared.record.mimeType,
                        );
                    } else {
                        await vaultStore.deleteVaultBlobVerified(
                            prepared.record.authorId,
                            prepared.record.docId,
                        );
                    }
                } catch {
                    rollbackIncomplete = true;
                }
            }
        }
        for (const k of written.reverse()) {
            const prior = snapshot.get(k);
            try {
                if (prior == null) {
                    await SecureStoreService.deleteItem(k);
                    if ((await SecureStoreService.getItem(k)) != null) {
                        throw new Error(`backup rollback delete verification failed:${k}`);
                    }
                    persistenceRepository.synchronizeExternalWrite(k, null);
                } else {
                    await SecureStoreService.setItem(k, prior, {
                        allowVerifiedEmptyOverwrite: true,
                    });
                    if ((await SecureStoreService.getItem(k)) !== prior) {
                        throw new Error(`backup rollback restore verification failed:${k}`);
                    }
                    persistenceRepository.synchronizeExternalWrite(k, prior);
                }
            } catch {
                rollbackIncomplete = true;
            }
        }
        if (rollbackIncomplete) {
            throw new Error('backup restore failed and rollback was incomplete', { cause: err });
        }
        throw err;
    }
}

export function parseBusinessBackupFile(text: string): {
    version: 1 | 2;
    createdAt: string | null;
    selection: Record<string, unknown> | null;
    range: Record<string, unknown> | null;
    counts: Record<string, unknown> | null;
    keys: string[];
    entries: Array<[string, string]>;
    vaultBlobs: BusinessBackupVaultBlob[];
} {
    if (new TextEncoder().encode(text).byteLength > MAX_BACKUP_PLAINTEXT_BYTES) {
        throw new Error('backup exceeds the mobile-safe import limit');
    }
    const parsed = JSON.parse(text) as unknown;
    const obj = parsed as {
        kind?: unknown;
        version?: unknown;
        createdAt?: unknown;
        selection?: unknown;
        range?: unknown;
        counts?: unknown;
        items?: unknown;
        vaultBlobs?: unknown;
    };
    if (
        obj?.kind !== 'hami-business-backup' ||
        (obj?.version !== 1 && obj?.version !== 2) ||
        !obj.items ||
        typeof obj.items !== 'object'
    ) {
        throw new Error('invalid backup');
    }
    const entriesAll = Object.entries(obj.items as Record<string, unknown>);
    const entries = entriesAll.filter(
        (e): e is [string, string] => typeof e[0] === 'string' && typeof e[1] === 'string',
    );
    if (entries.length !== entriesAll.length) {
        throw new Error('backup contains invalid records');
    }
    const validation = validateBusinessBackupImport(entries);
    if (!validation.ok) throw new Error(validation.reason);
    const vaultBlobs = validateVaultBlobRecords(obj.vaultBlobs);
    return {
        version: obj.version as 1 | 2,
        createdAt: typeof obj.createdAt === 'string' ? obj.createdAt : null,
        selection: obj.selection && typeof obj.selection === 'object' ? (obj.selection as Record<string, unknown>) : null,
        range: obj.range && typeof obj.range === 'object' ? (obj.range as Record<string, unknown>) : null,
        counts: obj.counts && typeof obj.counts === 'object' ? (obj.counts as Record<string, unknown>) : null,
        keys: entries.map((e) => e[0]).sort((a, b) => a.localeCompare(b)),
        entries,
        vaultBlobs,
    };
}

import type { BusinessBackupSelection } from './businessBackupTypes';

function parseRange(from: string, to: string) {
    const fromDate = from ? new Date(`${from}T00:00:00`) : null;
    const toDate = to ? new Date(`${to}T23:59:59`) : null;
    return {
        from: fromDate && !Number.isNaN(fromDate.getTime()) ? fromDate : null,
        to: toDate && !Number.isNaN(toDate.getTime()) ? toDate : null,
    };
}

export function extractDate(v: unknown): Date | null {
    if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
    const obj = v as Record<string, unknown>;
    const candidates: unknown[] = [
        obj.createdAt,
        obj.updatedAt,
        obj.created_at,
        obj.updated_at,
        obj.date,
        obj.filingDate,
        obj.filing_date,
        obj.requestDate,
        obj.sessionDate,
        obj.nextSessionDate,
        obj.decisionDate,
    ];
    for (const c of candidates) {
        if (typeof c === 'number') {
            const d = new Date(c);
            if (!Number.isNaN(d.getTime())) return d;
        }
        if (typeof c === 'string' && c.trim()) {
            const d = new Date(c);
            if (!Number.isNaN(d.getTime())) return d;
        }
    }
    return null;
}

export function filterByRange(items: unknown[], selection: BusinessBackupSelection) {
    const { from, to } = parseRange(selection.from, selection.to);
    if (!from && !to) return { filtered: items, undated: 0 };
    let undated = 0;
    const filtered = items.filter((it) => {
        const d = extractDate(it);
        if (!d) {
            undated += 1;
            return selection.includeUndated;
        }
        if (from && d < from) return false;
        if (to && d > to) return false;
        return true;
    });
    return { filtered, undated };
}

import { STORAGE_KEYS } from '@/app/utils/constants';
import {
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    LAWSUIT_FILES_TRASH_KEY,
} from '@/app/services/dossierPersistence/dossierStorageKeys';

/** حد أدنى لكلمة مرور حماية نسخة التصدير (بيانات قانونية حساسة) */
export const BACKUP_PASSWORD_MIN_LENGTH = 12;
export const BACKUP_PASSWORD_MAX_LENGTH = 1_024;

/** PBKDF2-SHA256 bounds: accept older exports, reject attacker-controlled work factors. */
export const BACKUP_KDF_ITERATIONS = 600_000;
export const BACKUP_KDF_MIN_ITERATIONS = 100_000;
export const BACKUP_KDF_MAX_ITERATIONS = 1_000_000;

/** Keeps JSON parse + one-shot AES-GCM memory within a mobile-safe envelope. */
export const MAX_BACKUP_FILE_BYTES = 25_000_000;
export const MAX_BACKUP_PLAINTEXT_BYTES = 18_000_000;

type BackupPasswordValidation =
    | { ok: true }
    | { ok: false; reason: 'empty' | 'too_short' | 'too_long' };

/** يتحقق من كلمة مرور حماية النسخة قبل التشفير. */
export function validateBackupPassword(password: string): BackupPasswordValidation {
    if (!password.trim()) return { ok: false, reason: 'empty' };
    const length = Array.from(password).length;
    if (length < BACKUP_PASSWORD_MIN_LENGTH) return { ok: false, reason: 'too_short' };
    if (length > BACKUP_PASSWORD_MAX_LENGTH) return { ok: false, reason: 'too_long' };
    return { ok: true };
}

/** أقصى عدد مفاتيح في استيراد واحد */
export const MAX_BACKUP_IMPORT_KEYS = 2_000;

/** أقصى حجم إجمالي للقيم المستوردة (حروف) */
const MAX_BACKUP_IMPORT_VALUE_CHARS = 17_000_000;
const MAX_BACKUP_IMPORT_KEY_LENGTH = 512;

const EXACT_ALLOWED_KEYS = new Set<string>([
    STORAGE_KEYS.LAWYER_FILES,
    STORAGE_KEYS.LAWYER_NOTES,
    LAWSUIT_FILES_ACTIVE_KEY,
    LAWSUIT_FILES_ARCHIVED_KEY,
    LAWSUIT_FILES_TRASH_KEY,
    LAWSUIT_FILES_INDEX_KEY,
    'executionFiles',
    'globalNotes',
    'global_notes',
    'hami_notes_vault',
    'hami_docs_vault',
    'hami:smartvault:docs:v1',
]);

/** مفاتيح lawyer_* المسموحة — بيانات أعمال فقط، لا إعدادات/مظهر */
const ALLOWED_LAWYER_PREFIX_KEYS = new Set<string>([
    STORAGE_KEYS.LAWYER_FILES,
    STORAGE_KEYS.LAWYER_NOTES,
    STORAGE_KEYS.LAWYER_EXECUTION_FILES,
]);

/** ممنوع استيرادها — تغيّر الأمان والمظهر دون علم المستخدم */
const BLOCKED_BACKUP_KEYS = new Set<string>([
    STORAGE_KEYS.LAWYER_SETTINGS,
    'lawyer_theme',
    'lawyer_shape',
    'lawyer_wallpaper',
]);

const ALLOWED_PREFIXES = [
    'execution_',
    'executionFiles:',
    'hami_notes_vault_',
    'hami:urgentActions:v1:',
    'notifications_',
    'vault:docs:',
    'hami:repository:rooms:',
    'hami:smartvault:custom-categories:v1',
] as const;

export function isAllowedBusinessBackupKey(key: string): boolean {
    if (!key || typeof key !== 'string') return false;
    if (key.length > MAX_BACKUP_IMPORT_KEY_LENGTH || /[\u0000-\u001f\u007f]/u.test(key)) return false;
    if (BLOCKED_BACKUP_KEYS.has(key)) return false;
    if (EXACT_ALLOWED_KEYS.has(key)) return true;
    if (ALLOWED_LAWYER_PREFIX_KEYS.has(key)) return true;
    return ALLOWED_PREFIXES.some((prefix) => key.startsWith(prefix));
}

type BackupImportValidation =
    | { ok: true; keyCount: number; totalChars: number }
    | { ok: false; reason: string };

export function validateBusinessBackupImport(entries: Array<[string, string]>): BackupImportValidation {
    if (!Array.isArray(entries) || entries.length === 0) {
        return { ok: false, reason: 'النسخة فارغة' };
    }
    if (entries.length > MAX_BACKUP_IMPORT_KEYS) {
        return { ok: false, reason: `عدد المفاتيح (${entries.length}) يتجاوز الحد المسموح` };
    }

    let totalChars = 0;
    const seen = new Set<string>();
    for (const [key, value] of entries) {
        if (typeof key !== 'string' || typeof value !== 'string') {
            return { ok: false, reason: 'بنية مفتاح/قيمة غير صالحة' };
        }
        if (!isAllowedBusinessBackupKey(key)) {
            return { ok: false, reason: `مفتاح غير مسموح: ${key}` };
        }
        if (seen.has(key)) {
            return { ok: false, reason: `مفتاح مكرر: ${key}` };
        }
        seen.add(key);
        totalChars += value.length;
        if (totalChars > MAX_BACKUP_IMPORT_VALUE_CHARS) {
            return { ok: false, reason: 'حجم البيانات المستوردة كبير جداً' };
        }
        try {
            JSON.parse(value);
        } catch {
            return { ok: false, reason: `قيمة JSON غير صالحة للمفتاح: ${key}` };
        }
    }

    return { ok: true, keyCount: entries.length, totalChars };
}

