/** حقول المظهر القديمة من وضع التحرير — تُزال عند المزامنة فقط */
const HOME_BLOCK_GLOBAL_APPEARANCE_KEYS = [
    'accentColor',
    'shape',
] as const satisfies ReadonlyArray<keyof HomeBlockStyleOverride>;

export function hasConflictingAppearanceOverrides(
    override?: HomeBlockStyleOverride,
): boolean {
    if (!override) return false;
    return HOME_BLOCK_GLOBAL_APPEARANCE_KEYS.some((key) => override[key] !== undefined);
}

export function stripConflictingAppearanceOverrides(
    override?: HomeBlockStyleOverride,
): HomeBlockStyleOverride | undefined {
    if (!override) return undefined;
    const next: HomeBlockStyleOverride = { ...override };
    for (const key of HOME_BLOCK_GLOBAL_APPEARANCE_KEYS) {
        delete next[key];
    }
    return Object.keys(next).length > 0 ? next : undefined;
}

/** patch لمسح تجاوزات المظهر المتعارضة مع الإعدادات العامة */
export function buildClearConflictingAppearancePatch(): Partial<HomeBlockStyleOverride> {
    return Object.fromEntries(
        HOME_BLOCK_GLOBAL_APPEARANCE_KEYS.map((key) => [key, undefined]),
    ) as Partial<HomeBlockStyleOverride>;
}

import type { HomeBlockSize, HomeBlockStyleOverride } from './homeLayout';

const SIZE_SCALE: Record<HomeBlockSize, number> = {
    compact: 0.86,
    normal: 1,
    large: 1.18,
};

/** مقياس موحّد للنص والأيقونة داخل البطاقة */
export function resolveContentScale(
    override: HomeBlockStyleOverride | undefined,
    baseMinHeightPx?: number,
    ignoreHeightPx = false,
): number {
    const sizeScale = SIZE_SCALE[override?.size ?? 'normal'];
    if (ignoreHeightPx || !override?.heightPx || !baseMinHeightPx) return sizeScale;
    const heightRatio = override.heightPx / baseMinHeightPx;
    const heightScale = Math.max(0.78, Math.min(1.32, heightRatio));
    return sizeScale * heightScale;
}

export function contentScaleVar(scale: number): Record<'--hami-content-scale', string> {
    return { '--hami-content-scale': String(Number(scale.toFixed(3))) };
}

/** أحجام خط البلاطات النصفية — داخل الحاوية دون ملء الارتفاع */
