/**
 * مزامنة العمل — ليست منتدى ولا استشارة زميل ولا طلب عون.
 * الدعاوى/التنفيذ/المعاملات/المخزن تبقى محلية حتى يُفعَّل cloudSync.
 * مستودع المنتدى العام سحابي عبر `forum_repository_docs` ولا يخضع لهذه البوابة؛
 * مرآة KV `repository:docs:` المحلية تبقى خلفها.
 * التعاون الصريح خلف `canReachCollaborationNetwork` (قطع الاتصال فقط).
 * التقويم خارج KV دائماً (`isCalendarNeverCloudKvMaterial`).
 * يدخل المزامنة الشاملة فقط داخل نقطة الحفظ المشفّرة (`workCloudCheckpoint`).
 * `lawyer_settings` محلي مشفّر — لا يمر عبر KV ولا `/api/settings/cloud-sync`.
 */
import { isCloudSyncEnabled } from '@/lib/cloudSyncEnv.js';
import { getLawyerSettingsSnapshot } from './settingsSnapshot';
import type { AppSettingsState } from './types';

export { isCalendarNeverCloudKvMaterial } from '@/app/security/kvProxyKeyOwnership';

const USER_PROFILE_KV_RE = /^user:[^:]+:profile(?::|$)/;

export function isLawyerWorkCloudLive(settings?: AppSettingsState): boolean {
    const snap = settings ?? getLawyerSettingsSnapshot();
    if (snap.security.localOnlyMode) return false;
    if (!snap.data.cloudSync) return false;
    return isCloudSyncEnabled();
}

/** مفاتيح KV التي تخص أقسام العمل المحلية — ليست profile/follow/notifications */
export function isWorkLocalKvMaterial(keyOrPrefix: string): boolean {
    const k = keyOrPrefix.trim();
    if (!k) return false;
    if (k.startsWith('calendar:') || k.startsWith('hami:calendar:events:')) return true;
    if (k.startsWith('transactions:') || k.startsWith('transactionsThreading:')) return true;
    if (k.startsWith('vault:docs:') || k.startsWith('repository:docs:')) return true;
    if (k.startsWith('lawyer_files:') || k.startsWith('urgentActions:')) return true;
    if (k.startsWith('user:')) {
        if (USER_PROFILE_KV_RE.test(k)) return false;
        return true;
    }
    return false;
}

/**
 * تسليح قطع الاتصال من القرص قبل أي import ديناميكي في entry.
 * لا يستورد لقطة الإعدادات ولا عميل التوقيع الآمن.
 */
import { captureWifeNativeFetch, getWifeNativeFetch } from '@/app/security/wifeNativeFetch';
import {
    isUrlPermittedUnderLocalOnly,
    LocalOnlyNetworkError,
    persistLocalOnlyBootFlag,
    readLocalOnlyBootFlag,
    readPlaintextPersistedLocalOnlyMode,
    resolveAppOrigin,
    resetLocalOnlyPersistMemoForTests,
} from '@/app/services/settings/localOnlyUrlPolicy';

const EMPTY_BYPASS = new Map<string, number>();

let earlyInstalled = false;

function shouldArmFromDisk(): boolean {
    return readLocalOnlyBootFlag() || readPlaintextPersistedLocalOnlyMode();
}

function isLocalOnlyOnNow(): boolean {
    try {
        if (typeof document !== 'undefined' && document.documentElement.dataset.hamiLocalOnly === '1') {
            return true;
        }
    } catch {
        /* ignore */
    }
    return readLocalOnlyBootFlag();
}

function resolveFetchUrl(input: RequestInfo | URL): string {
    if (typeof input === 'string') return input;
    if (input instanceof URL) return input.href;
    if (typeof Request !== 'undefined' && input instanceof Request) return input.url;
    return String(input);
}

function installEarlyLocalOnlyFetchGuard(): void {
    if (earlyInstalled || typeof window === 'undefined') return;
    earlyInstalled = true;
    const native = captureWifeNativeFetch();
    globalThis.fetch = (input, init) => {
        if (isLocalOnlyOnNow()) {
            const url = resolveFetchUrl(input as RequestInfo | URL);
            if (!isUrlPermittedUnderLocalOnly(url, resolveAppOrigin(), EMPTY_BYPASS)) {
                return Promise.reject(new LocalOnlyNetworkError('قطع الاتصال مفعّل — العمل محلياً فقط'));
            }
        }
        return native(input as RequestInfo, init);
    };
}

/** يضبط العلم من القرص ويلفّ fetch قبل stem اللوحة */
export function armLocalOnlyIsolationAtBoot(): void {
    if (typeof window === 'undefined') return;
    if (shouldArmFromDisk()) {
        persistLocalOnlyBootFlag(true);
        try {
            document.documentElement.dataset.hamiLocalOnly = '1';
        } catch {
            /* ignore */
        }
    }
    installEarlyLocalOnlyFetchGuard();
}

export function resetLocalOnlyBootArmForTests(): void {
    if (earlyInstalled) {
        globalThis.fetch = getWifeNativeFetch();
    }
    earlyInstalled = false;
    persistLocalOnlyBootFlag(false);
    resetLocalOnlyPersistMemoForTests();
    try {
        delete document.documentElement.dataset.hamiLocalOnly;
    } catch {
        /* ignore */
    }
}

import {
    isLocalOnlyModeEnabled,
    isNetworkUrlAllowed,
    isSrcsetNetworkAllowed,
    LocalOnlyNetworkError,
} from '@/app/services/settings/localOnlyGuard';

const SRC_TAGS = new Set(['IMG', 'AUDIO', 'VIDEO', 'SCRIPT', 'IFRAME', 'SOURCE']);

let egressInstalled = false;
let nativeSetAttribute: typeof Element.prototype.setAttribute | null = null;
let nativeSetAttributeNS: typeof Element.prototype.setAttributeNS | null = null;
let nativeRtc: typeof RTCPeerConnection | null = null;
let nativeImgSrcDesc: PropertyDescriptor | null = null;
let nativeMediaSrcDesc: PropertyDescriptor | null = null;
let nativeScriptSrcDesc: PropertyDescriptor | null = null;
let nativeIframeSrcDesc: PropertyDescriptor | null = null;
let nativeLinkHrefDesc: PropertyDescriptor | null = null;
let nativeOpen: typeof window.open | null = null;
let nativeAssign: ((url: string | URL) => void) | null = null;
let nativeReplace: ((url: string | URL) => void) | null = null;
let nativeSetProperty: typeof CSSStyleDeclaration.prototype.setProperty | null = null;
let nativeFormSubmit: typeof HTMLFormElement.prototype.submit | null = null;
let nativeHrefDesc: PropertyDescriptor | null = null;
let clickBound = false;
let submitBound = false;
let networkNodeObserver: MutationObserver | null = null;

export function installLocalOnlyEgressPatches(): void {
    if (typeof window === 'undefined' || egressInstalled) return;

    patchSetAttribute();
    patchSetAttributeNS();
    patchSrcAccessor(typeof HTMLImageElement !== 'undefined' ? HTMLImageElement.prototype : null, 'img');
    patchSrcAccessor(typeof HTMLMediaElement !== 'undefined' ? HTMLMediaElement.prototype : null, 'media');
    patchSrcAccessor(typeof HTMLScriptElement !== 'undefined' ? HTMLScriptElement.prototype : null, 'script');
    patchSrcAccessor(typeof HTMLIFrameElement !== 'undefined' ? HTMLIFrameElement.prototype : null, 'iframe');
    patchLinkHref();
    patchRtcPeerConnection();
    patchWindowOpen();
    patchLocationNavigation();
    patchCssSetProperty();
    patchFormSubmit();
    bindNavigationGuards();

    egressInstalled = true;
}

function patchSetAttribute(): void {
    if (typeof Element === 'undefined' || typeof Element.prototype.setAttribute !== 'function' || nativeSetAttribute) {
        return;
    }

    nativeSetAttribute = Element.prototype.setAttribute;

    Element.prototype.setAttribute = function (this: Element, name: string, value: string) {
        if (shouldBlockAttribute(this, name, value)) return;
        return nativeSetAttribute!.call(this, name, value);
    };
}

function patchSetAttributeNS(): void {
    if (
        typeof Element === 'undefined' ||
        typeof Element.prototype.setAttributeNS !== 'function' ||
        nativeSetAttributeNS
    ) {
        return;
    }
    nativeSetAttributeNS = Element.prototype.setAttributeNS;
    Element.prototype.setAttributeNS = function (this: Element, ns: string | null, name: string, value: string) {
        const local = name.includes(':') ? name.slice(name.lastIndexOf(':') + 1) : name;
        if (shouldBlockAttribute(this, local, value)) return;
        return nativeSetAttributeNS!.call(this, ns, name, value);
    };
}

function shouldBlockAttribute(el: Element, name: string, value: string): boolean {
    const attr = name.toLowerCase();
    if (el.tagName === 'LINK' && attr === 'href') {
        return !isNetworkUrlAllowed(value);
    }
    if (el.tagName === 'FORM' && attr === 'action') {
        return !isNetworkUrlAllowed(value);
    }
    if ((el.tagName === 'A' || el.tagName === 'AREA') && attr === 'href') {
        return false;
    }
    if (!SRC_TAGS.has(el.tagName)) return false;
    if (attr === 'srcset') return !isSrcsetNetworkAllowed(value);
    if (attr === 'src' || attr === 'poster') return !isNetworkUrlAllowed(value);
    return false;
}

function patchSrcAccessor(
    proto: { src?: string } | null,
    kind: 'img' | 'media' | 'script' | 'iframe',
): void {
    if (!proto) return;
    const existing =
        kind === 'img'
            ? nativeImgSrcDesc
            : kind === 'media'
              ? nativeMediaSrcDesc
              : kind === 'script'
                ? nativeScriptSrcDesc
                : nativeIframeSrcDesc;
    if (existing) return;

    const desc = Object.getOwnPropertyDescriptor(proto, 'src');
    if (!desc?.set || !desc.get) return;

    if (kind === 'img') nativeImgSrcDesc = desc;
    else if (kind === 'media') nativeMediaSrcDesc = desc;
    else if (kind === 'script') nativeScriptSrcDesc = desc;
    else nativeIframeSrcDesc = desc;

    Object.defineProperty(proto, 'src', {
        configurable: true,
        enumerable: desc.enumerable,
        get() {
            return desc.get!.call(this);
        },
        set(next: string) {
            if (!isNetworkUrlAllowed(String(next))) return;
            desc.set!.call(this, next);
        },
    });
}

function patchLinkHref(): void {
    if (typeof HTMLLinkElement === 'undefined' || nativeLinkHrefDesc) return;
    const desc = Object.getOwnPropertyDescriptor(HTMLLinkElement.prototype, 'href');
    if (!desc?.set || !desc.get) return;
    nativeLinkHrefDesc = desc;
    Object.defineProperty(HTMLLinkElement.prototype, 'href', {
        configurable: true,
        enumerable: desc.enumerable,
        get() {
            return desc.get!.call(this);
        },
        set(next: string) {
            if (!isNetworkUrlAllowed(String(next))) return;
            desc.set!.call(this, next);
        },
    });
}

function patchRtcPeerConnection(): void {
    const Native = window.RTCPeerConnection;
    if (typeof Native !== 'function' || nativeRtc) return;
    nativeRtc = Native;

    const Guarded = function GuardedRtcPeerConnection(
        this: RTCPeerConnection,
        config?: RTCConfiguration,
        _constraints?: unknown,
    ) {
        if (isLocalOnlyModeEnabled()) {
            throw new LocalOnlyNetworkError('قطع الاتصال مفعّل — العمل محلياً فقط');
        }
        return new Native(config);
    } as unknown as typeof RTCPeerConnection;

    Guarded.prototype = Native.prototype;
    window.RTCPeerConnection = Guarded;
}

function patchWindowOpen(): void {
    if (typeof window.open !== 'function' || nativeOpen) return;
    nativeOpen = window.open.bind(window);
    window.open = (url?: string | URL, target?: string, features?: string) => {
        if (url != null && String(url).trim() && !isNetworkUrlAllowed(String(url))) {
            return null;
        }
        return nativeOpen!.call(window, url, target, features);
    };
}

function patchLocationNavigation(): void {
    try {
        const proto = Location.prototype;
        if (!nativeAssign && typeof proto.assign === 'function') {
            nativeAssign = proto.assign;
            proto.assign = function (this: Location, url: string | URL) {
                if (!isNetworkUrlAllowed(String(url))) return;
                return nativeAssign!.call(this, url);
            };
        }
        if (!nativeReplace && typeof proto.replace === 'function') {
            nativeReplace = proto.replace;
            proto.replace = function (this: Location, url: string | URL) {
                if (!isNetworkUrlAllowed(String(url))) return;
                return nativeReplace!.call(this, url);
            };
        }
        if (!nativeHrefDesc) {
            const hrefDesc = Object.getOwnPropertyDescriptor(proto, 'href');
            if (hrefDesc?.set && hrefDesc.get) {
                nativeHrefDesc = hrefDesc;
                Object.defineProperty(proto, 'href', {
                    configurable: true,
                    enumerable: hrefDesc.enumerable,
                    get() {
                        return hrefDesc.get!.call(this);
                    },
                    set(next: string) {
                        if (!isNetworkUrlAllowed(String(next))) return;
                        hrefDesc.set!.call(this, next);
                    },
                });
            }
        }
    } catch {
        /* jsdom Location may be frozen */
    }
}

function extractCssUrls(value: string): string[] {
    const out: string[] = [];
    const re = /url\(\s*(['"]?)([^'")]+)\1\s*\)/gi;
    let match: RegExpExecArray | null;
    while ((match = re.exec(value))) {
        const token = match[2]?.trim();
        if (token) out.push(token);
    }
    return out;
}

function patchCssSetProperty(): void {
    if (typeof CSSStyleDeclaration === 'undefined' || nativeSetProperty) return;
    nativeSetProperty = CSSStyleDeclaration.prototype.setProperty;
    CSSStyleDeclaration.prototype.setProperty = function (prop: string, value?: string, priority?: string) {
        if (isLocalOnlyModeEnabled() && typeof value === 'string' && value.toLowerCase().includes('url(')) {
            if (extractCssUrls(value).some((token) => !isNetworkUrlAllowed(token))) return;
        }
        return nativeSetProperty!.call(this, prop, value ?? '', priority);
    };
}

function patchFormSubmit(): void {
    if (typeof HTMLFormElement === 'undefined' || nativeFormSubmit) return;
    nativeFormSubmit = HTMLFormElement.prototype.submit;
    HTMLFormElement.prototype.submit = function (this: HTMLFormElement) {
        const action = this.getAttribute('action') || this.action || '';
        if (action && !isNetworkUrlAllowed(action)) return;
        return nativeFormSubmit!.call(this);
    };
}

function bindNavigationGuards(): void {
    if (typeof document === 'undefined') return;
    if (!clickBound) {
        document.addEventListener('click', onDocumentClickCapture, true);
        clickBound = true;
    }
    if (!submitBound) {
        document.addEventListener('submit', onDocumentSubmitCapture, true);
        submitBound = true;
    }
}

function onDocumentClickCapture(event: Event): void {
    if (!isLocalOnlyModeEnabled()) return;
    const target = event.target;
    if (!(target instanceof Element)) return;
    const link = target.closest('a[href], area[href]');
    if (!link) return;
    const href = link.getAttribute('href');
    if (!href || isNetworkUrlAllowed(href)) return;
    event.preventDefault();
    event.stopPropagation();
}

function onDocumentSubmitCapture(event: Event): void {
    if (!isLocalOnlyModeEnabled()) return;
    const form = event.target;
    if (!(form instanceof HTMLFormElement)) return;
    const action = form.getAttribute('action') || form.action || '';
    if (!action || isNetworkUrlAllowed(action)) return;
    event.preventDefault();
    event.stopPropagation();
}

const SCRUB_SELECTOR = 'img,audio,video,script,iframe,source,link,form';

function scrubElement(el: Element): void {
    if (!isLocalOnlyModeEnabled()) return;
    const tag = el.tagName;
    if (SRC_TAGS.has(tag)) {
        const src = el.getAttribute('src');
        if (src && !isNetworkUrlAllowed(src)) el.removeAttribute('src');
        const srcset = el.getAttribute('srcset');
        if (srcset && !isSrcsetNetworkAllowed(srcset)) el.removeAttribute('srcset');
        const poster = el.getAttribute('poster');
        if (poster && !isNetworkUrlAllowed(poster)) el.removeAttribute('poster');
    }
    if (tag === 'LINK') {
        const href = el.getAttribute('href');
        if (href && !isNetworkUrlAllowed(href)) el.removeAttribute('href');
    }
    if (tag === 'FORM') {
        const action = el.getAttribute('action');
        if (action && !isNetworkUrlAllowed(action)) el.removeAttribute('action');
    }
}

function scrubTree(root: ParentNode | null): void {
    if (!root || typeof root.querySelectorAll !== 'function') return;
    if (root instanceof Element) scrubElement(root);
    root.querySelectorAll(SCRUB_SELECTOR).forEach(scrubElement);
}

function startNetworkNodeObserver(): void {
    if (networkNodeObserver || typeof MutationObserver === 'undefined' || typeof document === 'undefined') {
        return;
    }
    networkNodeObserver = new MutationObserver((records) => {
        if (!isLocalOnlyModeEnabled()) return;
        for (const rec of records) {
            if (rec.type === 'attributes' && rec.target instanceof Element) {
                scrubElement(rec.target);
            }
            rec.addedNodes.forEach((node) => {
                if (node instanceof Element) scrubTree(node);
            });
        }
    });
    networkNodeObserver.observe(document.documentElement, {
        subtree: true,
        childList: true,
        attributes: true,
        attributeFilter: ['src', 'srcset', 'href', 'action', 'poster'],
    });
}

function stopNetworkNodeObserver(): void {
    networkNodeObserver?.disconnect();
    networkNodeObserver = null;
}

/** يُشغَّل المراقب فقط أثناء التسليح — صفر تكلفة وهو مطفأ */
export function setLocalOnlyEgressArmed(enabled: boolean): void {
    if (enabled) {
        startNetworkNodeObserver();
        try {
            scrubTree(document);
        } catch {
            /* ignore */
        }
        return;
    }
    stopNetworkNodeObserver();
}

export function resetLocalOnlyEgressPatchesForTests(): void {
    if (typeof window === 'undefined') return;

    if (nativeSetAttribute) {
        Element.prototype.setAttribute = nativeSetAttribute;
    }
    if (nativeSetAttributeNS) {
        Element.prototype.setAttributeNS = nativeSetAttributeNS;
    }
    restoreSrc('img', typeof HTMLImageElement !== 'undefined' ? HTMLImageElement.prototype : null, nativeImgSrcDesc);
    restoreSrc(
        'media',
        typeof HTMLMediaElement !== 'undefined' ? HTMLMediaElement.prototype : null,
        nativeMediaSrcDesc,
    );
    restoreSrc(
        'script',
        typeof HTMLScriptElement !== 'undefined' ? HTMLScriptElement.prototype : null,
        nativeScriptSrcDesc,
    );
    restoreSrc(
        'iframe',
        typeof HTMLIFrameElement !== 'undefined' ? HTMLIFrameElement.prototype : null,
        nativeIframeSrcDesc,
    );
    if (nativeLinkHrefDesc && typeof HTMLLinkElement !== 'undefined') {
        Object.defineProperty(HTMLLinkElement.prototype, 'href', nativeLinkHrefDesc);
    }
    if (nativeRtc) window.RTCPeerConnection = nativeRtc;
    if (nativeOpen) window.open = nativeOpen;
    try {
        if (nativeAssign) Location.prototype.assign = nativeAssign;
        if (nativeReplace) Location.prototype.replace = nativeReplace;
        if (nativeHrefDesc) Object.defineProperty(Location.prototype, 'href', nativeHrefDesc);
    } catch {
        /* ignore */
    }
    if (nativeSetProperty) CSSStyleDeclaration.prototype.setProperty = nativeSetProperty;
    if (nativeFormSubmit) HTMLFormElement.prototype.submit = nativeFormSubmit;
    if (clickBound) {
        document.removeEventListener('click', onDocumentClickCapture, true);
        clickBound = false;
    }
    if (submitBound) {
        document.removeEventListener('submit', onDocumentSubmitCapture, true);
        submitBound = false;
    }
    stopNetworkNodeObserver();

    egressInstalled = false;
    nativeSetAttribute = null;
    nativeSetAttributeNS = null;
    nativeRtc = null;
    nativeImgSrcDesc = null;
    nativeMediaSrcDesc = null;
    nativeScriptSrcDesc = null;
    nativeIframeSrcDesc = null;
    nativeLinkHrefDesc = null;
    nativeOpen = null;
    nativeAssign = null;
    nativeReplace = null;
    nativeHrefDesc = null;
    nativeSetProperty = null;
    nativeFormSubmit = null;
}

function restoreSrc(
    _kind: string,
    proto: object | null,
    desc: PropertyDescriptor | null,
): void {
    if (proto && desc) Object.defineProperty(proto, 'src', desc);
}

import { getLawyerSettingsSnapshot } from './settingsSnapshot';
import type { AppSettingsState } from './types';
import {
    isAllowlistedTransactionUrl,
    isUrlPermittedUnderLocalOnly,
    LocalOnlyNetworkError,
    LOCAL_ONLY_BYPASS_PATHS,
    readLocalOnlyBootFlag,
    resolveAppOrigin,
} from './localOnlyUrlPolicy';

export { LocalOnlyNetworkError, LOCAL_ONLY_BYPASS_PATHS, LOCAL_ONLY_SESSION_PATHS } from './localOnlyUrlPolicy';

const localOnlyBypassedUrls = new Map<string, number>();

function canonicalNetworkUrl(url: string): string {
    if (typeof window === 'undefined') return url;
    return new URL(url, window.location.origin).href;
}

function isAllowlistedBypassUrl(url: string): boolean {
    try {
        if (typeof window === 'undefined') {
            const path = url.split('?')[0]?.split('#')[0] ?? url;
            return (LOCAL_ONLY_BYPASS_PATHS as readonly string[]).includes(path);
        }
        return isAllowlistedTransactionUrl(url, window.location.origin);
    } catch {
        return false;
    }
}

/**
 * يسمح بعنوان واحد مع بقاء العزل على كل طلب موازٍ.
 * يرفض أي عنوان خارج قائمة المسارات المعتمدة.
 */
export async function runBypassingLocalOnlyForUrl<T>(url: string, fn: () => Promise<T>): Promise<T> {
    if (!isAllowlistedBypassUrl(url)) {
        throw new LocalOnlyNetworkError('قطع الاتصال مفعّل — مسار غير مسموح');
    }
    const canonical = canonicalNetworkUrl(url);
    localOnlyBypassedUrls.set(canonical, (localOnlyBypassedUrls.get(canonical) ?? 0) + 1);
    try {
        return await fn();
    } finally {
        const remaining = (localOnlyBypassedUrls.get(canonical) ?? 1) - 1;
        if (remaining <= 0) localOnlyBypassedUrls.delete(canonical);
        else localOnlyBypassedUrls.set(canonical, remaining);
    }
}

export function isLocalOnlyModeEnabled(settings?: AppSettingsState): boolean {
    try {
        if (typeof document !== 'undefined') {
            const flag = document.documentElement.dataset.hamiLocalOnly;
            if (flag === '1') return true;
            if (readLocalOnlyBootFlag()) return true;
            if (flag === '0' && settings === undefined) return false;
        }
    } catch {
        /* ignore */
    }
    if (readLocalOnlyBootFlag()) return true;
    return (settings ?? getLawyerSettingsSnapshot()).security.localOnlyMode === true;
}

/** متون القوانين من المقر تحتاج خادماً — لا تُطلب عند قطع الاتصال */
export function canReachPublishedLawCatalog(): boolean {
    return !isLocalOnlyModeEnabled();
}

export function isSrcsetNetworkAllowed(srcset: string, settings?: AppSettingsState): boolean {
    const urls = srcset
        .split(',')
        .map((part) => part.trim().split(/\s+/)[0])
        .filter((token): token is string => Boolean(token));
    if (urls.length === 0) return true;
    return urls.every((token) => isNetworkUrlAllowed(token, settings));
}

/** هل يُسمح بهذا الرابط أثناء وضع قطع الاتصال؟ */
export function isNetworkUrlAllowed(url: string, settings?: AppSettingsState): boolean {
    if (!isLocalOnlyModeEnabled(settings)) return true;
    if (typeof window === 'undefined') return false;
    return isUrlPermittedUnderLocalOnly(url, resolveAppOrigin(), localOnlyBypassedUrls);
}

export function assertNetworkAllowed(url: string, settings?: AppSettingsState): void {
    if (!isNetworkUrlAllowed(url, settings)) {
        throw new LocalOnlyNetworkError('قطع الاتصال مفعّل — العمل محلياً فقط');
    }
}

/**
 * قاطع شبكة على مستوى التطبيق عند «قطع الاتصال».
 * لا يغيّر إنترنت نظام التشغيل — يمنع التطبيق من فتح اتصال خارج الجهاز.
 */

import { installWifeFetchGuard } from '@/app/security/wifeFetchGuard';
import {
    assertNetworkAllowed,
    isNetworkUrlAllowed,
    LocalOnlyNetworkError,
} from '@/app/services/settings/localOnlyGuard';
import {
    persistLocalOnlyBootFlag,
    readLocalOnlyBootFlag,
    resetLocalOnlyPersistMemoForTests,
} from '@/app/services/settings/localOnlyUrlPolicy';
import {
    installLocalOnlyEgressPatches,
    resetLocalOnlyEgressPatchesForTests,
    setLocalOnlyEgressArmed,
} from '@/app/services/settings/localOnlyEgressPatches';

let isolationInstalled = false;
let nativeWebSocket: typeof WebSocket | null = null;
let nativeXhrOpen: typeof XMLHttpRequest.prototype.open | null = null;
let nativeSendBeacon: typeof navigator.sendBeacon | null = null;
let nativeEventSource: typeof EventSource | null = null;
let nativeCapacitorHttpRequest: ((options: { url?: string }) => Promise<unknown>) | null = null;
let stickyArmed = false;

export function setLocalOnlyNetworkFlag(enabled: boolean): void {
    if (typeof document === 'undefined') return;
    document.documentElement.dataset.hamiLocalOnly = enabled ? '1' : '0';
}

/** يضبط العلم فوراً ثم يركّب القاطع — قبل اكتمال setState */
export function armLocalOnlyNetworkIsolation(enabled: boolean): void {
    if (enabled) {
        persistLocalOnlyBootFlag(true);
        stickyArmed = true;
        setLocalOnlyNetworkFlag(true);
    } else {
        stickyArmed = false;
        persistLocalOnlyBootFlag(false);
        setLocalOnlyNetworkFlag(false);
    }
    installLocalOnlyNetworkIsolation();
    setLocalOnlyEgressArmed(enabled);
}

/**
 * يرفع العلم من الإعدادات المحفوظة. لا يخفضه إذا كان التسليح الصريح أو علم القرص قائماً —
 * حتى لا تُصفَّر الحماية بلقطة إعدادات قديمة.
 */
export function syncLocalOnlyFlagFromSettings(enabled: boolean): void {
    installLocalOnlyNetworkIsolation();
    if (enabled) {
        stickyArmed = true;
        persistLocalOnlyBootFlag(true);
        setLocalOnlyNetworkFlag(true);
        setLocalOnlyEgressArmed(true);
        return;
    }
    if (stickyArmed || readLocalOnlyBootFlag()) return;
    setLocalOnlyNetworkFlag(false);
    setLocalOnlyEgressArmed(false);
}

export function installLocalOnlyNetworkIsolation(): void {
    if (typeof window === 'undefined') return;
    installWifeFetchGuard();
    installLocalOnlyEgressPatches();
    if (isolationInstalled) return;

    patchWebSocket();
    patchXhrOpen();
    patchSendBeacon();
    patchEventSource();
    patchCapacitorHttp();
    if (typeof document !== 'undefined') {
        document.addEventListener('deviceready', () => patchCapacitorHttp(), { once: true });
    }

    isolationInstalled = true;
}

function patchWebSocket(): void {
    if (typeof WebSocket === 'undefined' || nativeWebSocket) return;

    const Native = WebSocket;
    nativeWebSocket = Native;

    class GuardedWebSocket extends Native {
        constructor(url: string | URL, protocols?: string | string[]) {
            assertNetworkAllowed(String(url));
            super(url, protocols);
        }
    }

    window.WebSocket = GuardedWebSocket;
}

function patchXhrOpen(): void {
    if (typeof XMLHttpRequest === 'undefined' || nativeXhrOpen) return;

    nativeXhrOpen = XMLHttpRequest.prototype.open;

    XMLHttpRequest.prototype.open = function (
        this: XMLHttpRequest,
        method: string,
        url: string | URL,
        async?: boolean,
        username?: string | null,
        password?: string | null,
    ) {
        assertNetworkAllowed(String(url));
        return nativeXhrOpen!.call(this, method, url, async ?? true, username, password);
    };
}

function patchSendBeacon(): void {
    if (typeof navigator === 'undefined' || typeof navigator.sendBeacon !== 'function' || nativeSendBeacon) {
        return;
    }

    nativeSendBeacon = navigator.sendBeacon.bind(navigator);

    navigator.sendBeacon = (url: string | URL, data?: BodyInit | null) => {
        if (!isNetworkUrlAllowed(String(url))) return false;
        return nativeSendBeacon!(url, data);
    };
}

function patchEventSource(): void {
    if (typeof EventSource === 'undefined' || nativeEventSource) return;

    const Native = EventSource;
    nativeEventSource = Native;

    const Guarded = function GuardedEventSource(
        this: EventSource,
        url: string | URL,
        eventSourceInitDict?: EventSourceInit,
    ) {
        assertNetworkAllowed(String(url));
        return new Native(url, eventSourceInitDict);
    } as unknown as typeof EventSource;

    Guarded.prototype = Native.prototype;
    Object.defineProperties(Guarded, {
        CONNECTING: { value: Native.CONNECTING },
        OPEN: { value: Native.OPEN },
        CLOSED: { value: Native.CLOSED },
    });

    window.EventSource = Guarded;
}

function patchCapacitorHttp(): void {
    if (nativeCapacitorHttpRequest) return;
    const cap = (window as unknown as { Capacitor?: { Plugins?: { Http?: { request?: unknown } } } }).Capacitor;
    const Http = cap?.Plugins?.Http;
    if (!Http || typeof Http.request !== 'function') return;

    const native = Http.request.bind(Http) as (options: { url?: string }) => Promise<unknown>;
    nativeCapacitorHttpRequest = native;
    Http.request = (options: { url?: string }) => {
        assertNetworkAllowed(String(options?.url ?? ''));
        return native(options);
    };
}

export function resetLocalOnlyNetworkIsolationForTests(): void {
    if (typeof window === 'undefined') return;

    if (nativeWebSocket) window.WebSocket = nativeWebSocket;
    if (nativeXhrOpen) XMLHttpRequest.prototype.open = nativeXhrOpen;
    if (nativeSendBeacon && typeof navigator !== 'undefined') {
        navigator.sendBeacon = nativeSendBeacon;
    }
    if (nativeEventSource) window.EventSource = nativeEventSource;

    const cap = (window as unknown as { Capacitor?: { Plugins?: { Http?: { request?: unknown } } } }).Capacitor;
    if (nativeCapacitorHttpRequest && cap?.Plugins?.Http) {
        cap.Plugins.Http.request = nativeCapacitorHttpRequest;
    }

    isolationInstalled = false;
    nativeWebSocket = null;
    nativeXhrOpen = null;
    nativeSendBeacon = null;
    nativeEventSource = null;
    nativeCapacitorHttpRequest = null;
    stickyArmed = false;
    persistLocalOnlyBootFlag(false);
    resetLocalOnlyPersistMemoForTests();
    setLocalOnlyEgressArmed(false);
    resetLocalOnlyEgressPatchesForTests();
    try {
        delete document.documentElement.dataset.hamiLocalOnly;
    } catch {
        /* ignore */
    }
}

export { LocalOnlyNetworkError };

/**
 * سياسة قطع الاتصال بلا لقطة إعدادات ولا عميل سحابي —
 * تُستورد من مسار الإقلاع الحرج ومن الحارس الكامل.
 */

export const LOCAL_ONLY_PERSIST_KEY = 'hami_local_only';

/** مسارات حسّاسة تُفتح فقط داخل نافذة runBypassingLocalOnlyForUrl */
export const LOCAL_ONLY_BYPASS_PATHS = Object.freeze([
    '/api/settings/wipe',
    '/api/account/delete',
]);

/** إنهاء الجلسة — مسموح أثناء العزل (ليس تسريب ملفات) */
export const LOCAL_ONLY_SESSION_PATHS = Object.freeze(['/api/auth/logout']);

/** مسارات GoTrue على أصل المشروع فقط — تجديد/قراءة الجلسة لا ملفات القضايا */
const SUPABASE_SESSION_PATHS = new Set(['/auth/v1/logout', '/auth/v1/token', '/auth/v1/user']);

let persistMemo: boolean | undefined;

const NON_NETWORK_PROTOCOLS = new Set(['blob:', 'data:', 'about:', 'tel:', 'mailto:', 'sms:']);

export class LocalOnlyNetworkError extends Error {
    constructor(message = 'local-only-mode') {
        super(message);
        this.name = 'LocalOnlyNetworkError';
    }
}

export function persistLocalOnlyBootFlag(enabled: boolean): void {
    persistMemo = enabled;
    if (typeof localStorage === 'undefined') return;
    try {
        if (enabled) localStorage.setItem(LOCAL_ONLY_PERSIST_KEY, '1');
        else localStorage.removeItem(LOCAL_ONLY_PERSIST_KEY);
    } catch {
        /* private mode */
    }
}

export function readLocalOnlyBootFlag(): boolean {
    if (persistMemo !== undefined) return persistMemo;
    if (typeof localStorage === 'undefined') {
        persistMemo = false;
        return false;
    }
    try {
        persistMemo = localStorage.getItem(LOCAL_ONLY_PERSIST_KEY) === '1';
    } catch {
        persistMemo = false;
    }
    return persistMemo;
}

export function resetLocalOnlyPersistMemoForTests(): void {
    persistMemo = undefined;
}

/** قراءة plaintext فقط — الكتلة المشفّرة لا تُفسَّر هنا */
export function readPlaintextPersistedLocalOnlyMode(): boolean {
    if (typeof localStorage === 'undefined') return false;
    try {
        const raw = localStorage.getItem('lawyer_settings');
        if (!raw || raw.startsWith('hami_enc_v2:')) return false;
        const parsed = JSON.parse(raw) as { security?: { localOnlyMode?: unknown } };
        return parsed?.security?.localOnlyMode === true;
    } catch {
        return false;
    }
}

export function resolveAppOrigin(): string {
    if (typeof window !== 'undefined' && typeof window.location?.origin === 'string') {
        return window.location.origin;
    }
    return 'http://localhost';
}

function getConfiguredSupabaseOrigin(): string | null {
    try {
        const raw =
            typeof import.meta.env.VITE_SUPABASE_URL === 'string'
                ? import.meta.env.VITE_SUPABASE_URL.trim()
                : '';
        if (!raw || /YOUR_PROJECT|placeholder|CHANGE_ME/i.test(raw)) return null;
        return new URL(raw).origin;
    } catch {
        return null;
    }
}

export function isAllowlistedTransactionUrl(url: string, origin: string): boolean {
    try {
        const resolved = new URL(url, origin);
        if (resolved.origin !== origin) return false;
        return (LOCAL_ONLY_BYPASS_PATHS as readonly string[]).includes(resolved.pathname);
    } catch {
        return false;
    }
}

function isAlwaysAllowedSessionUrl(resolved: URL, origin: string): boolean {
    if (
        resolved.origin === origin &&
        (LOCAL_ONLY_SESSION_PATHS as readonly string[]).includes(resolved.pathname)
    ) {
        return true;
    }
    const supabaseOrigin = getConfiguredSupabaseOrigin();
    if (!supabaseOrigin || resolved.origin !== supabaseOrigin) return false;
    const path = resolved.pathname.replace(/\/+$/, '') || '/';
    return SUPABASE_SESSION_PATHS.has(path);
}

export function isUrlPermittedUnderLocalOnly(
    url: string,
    origin: string,
    bypassedHrefs: ReadonlyMap<string, number>,
): boolean {
    const trimmed = url.trim();
    if (!trimmed) return true;
    if (trimmed.startsWith('blob:') || trimmed.startsWith('data:') || trimmed.startsWith('about:')) {
        return true;
    }
    try {
        const resolved = new URL(url, origin);
        if ((bypassedHrefs.get(resolved.href) ?? 0) > 0) return true;
        if (NON_NETWORK_PROTOCOLS.has(resolved.protocol)) return true;
        if (isAlwaysAllowedSessionUrl(resolved, origin)) return true;
        if (resolved.origin !== origin) return false;
        if (resolved.pathname.startsWith('/api/')) return false;
        return true;
    } catch {
        return false;
    }
}

import type { ThemeKey, ShapeKey, ThemeMode } from '@/app/types/common';

import { LAWYER_SETTINGS_V2_DEFAULTS } from './defaults';

import { normalizeBackgroundPreset } from './backgroundPresets';

import {
    normalizeBackgroundPatternOpacity,
    normalizeGlassOpacity,
} from './surfaceAppearance';

import {
    collapseLegacyThemeApplyTarget,
    normalizeAppearanceLanguage,
    normalizeAppearancePatternBlur,
} from './appearanceNormalize';

import type { AppSettingsState } from './types';
import { SETTINGS_SCHEMA_VERSION } from './types';
import { normalizeHomeLayout } from './homeLayout';
import { normalizeLitePerformanceMode } from '@/app/runtime/devicePerformanceTier';
import { normalizeNotificationSettings } from './notificationSettings';



/** الواجهة تدعم الوضع الداكن فقط — يُحوَّل أي وضع فاتح/تلقائي محفوظ. */

function normalizeThemeMode(_mode: unknown): ThemeMode {

    return 'dark';

}



type LegacyFlat = Partial<{

    version: number;

    themeMode: AppSettingsState['appearance']['themeMode'];

    theme: ThemeKey;

    shape: ShapeKey;

    language: AppSettingsState['appearance']['language'];

    biometric: boolean;

    glassOpacity: number;

    wallpaper: string;

    fontSize: number;

    autoSave: boolean;

    cloudSync: boolean;

    privacyBlur: boolean;

    brandColor: string;

    appearance: AppSettingsState['appearance'];

    security: AppSettingsState['security'];

    data: AppSettingsState['data'];

    performance: AppSettingsState['performance'];

}>;



function deepMerge<T>(base: T, patch: Partial<T>): T {

    const out = { ...(base as unknown as Record<string, unknown>) };

    const patchObj = patch as unknown as Record<string, unknown>;

    for (const key of Object.keys(patchObj)) {

        const val = patchObj[key];

        if (val === undefined) continue;

        const baseVal = out[key];

        if (

            val &&

            typeof val === 'object' &&

            !Array.isArray(val) &&

            baseVal &&

            typeof baseVal === 'object' &&

            !Array.isArray(baseVal)

        ) {

            out[key] = deepMerge(baseVal as Record<string, unknown>, val as Record<string, unknown>);

        } else {

            out[key] = val;

        }

    }

    return out as unknown as T;

}



function normalizeAppSettings(merged: AppSettingsState): AppSettingsState {
    const themeTargets = collapseLegacyThemeApplyTarget(merged.appearance);

    return {
        version: SETTINGS_SCHEMA_VERSION,
        appearance: {
            ...merged.appearance,
            themeMode: normalizeThemeMode(merged.appearance.themeMode),
            language: normalizeAppearanceLanguage(merged.appearance.language),
            backgroundPreset: normalizeBackgroundPreset(merged.appearance.backgroundPreset),
            backgroundPatternOpacity: normalizeBackgroundPatternOpacity(merged.appearance.backgroundPatternOpacity),
            backgroundPatternBlur: normalizeAppearancePatternBlur(merged.appearance.backgroundPatternBlur),
            glassOpacity: normalizeGlassOpacity(merged.appearance.glassOpacity),
            homeContainerBorder: merged.appearance.homeContainerBorder !== false,
            themeApplyTarget: themeTargets.themeApplyTarget,
            patternApplyTarget: 'blocks',
            cardTheme: themeTargets.cardTheme,
            patternTheme: themeTargets.patternTheme,
            wallpaperStamp: merged.appearance.wallpaperStamp,
            fontSize: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontSize,
            fontPreset: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontPreset,
        },

        security: {

            ...merged.security,

            localOnlyMode: merged.security.localOnlyMode === true,
            privacyBlur: LAWYER_SETTINGS_V2_DEFAULTS.security.privacyBlur,

        },

        data: merged.security.localOnlyMode
            ? {
                  ...merged.data,
                  cloudSync: false,
                  syncNotes: false,
                  syncFiles: false,
                  syncExecution: false,
              }
            : { ...merged.data },

        performance: {
            ...merged.performance,
            litePerformance: normalizeLitePerformanceMode(merged.performance.litePerformance),
        },

        homeLayout: normalizeHomeLayout(merged.homeLayout),

        notifications: normalizeNotificationSettings(merged.notifications),

    };

}



/** Load v2 settings or migrate legacy `lawyer_settings` + theme keys. */

export function migrateLawyerSettings(

    raw: unknown,

    themeKey?: ThemeKey | null,

    shapeKey?: ShapeKey | null,

): AppSettingsState {

    if (raw && typeof raw === 'object') {

        const obj = raw as LegacyFlat & Record<string, unknown>;

        if (obj.version === SETTINGS_SCHEMA_VERSION && obj.appearance) {

            const merged = deepMerge(LAWYER_SETTINGS_V2_DEFAULTS, obj as unknown as Partial<AppSettingsState>);

            return normalizeAppSettings(merged);

        }

        if (obj.version === 2 && obj.appearance) {

            const merged = deepMerge(LAWYER_SETTINGS_V2_DEFAULTS, obj as unknown as Partial<AppSettingsState>);

            return normalizeAppSettings(merged);

        }



        const migrated: Partial<AppSettingsState> = {

            appearance: {

                ...LAWYER_SETTINGS_V2_DEFAULTS.appearance,

                themeMode: normalizeThemeMode(obj.themeMode ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.themeMode),

                theme: themeKey ?? obj.theme ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.theme,

                shape: shapeKey ?? obj.shape ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.shape,

                language: obj.language ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.language,

                fontSize: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontSize,
                fontPreset: LAWYER_SETTINGS_V2_DEFAULTS.appearance.fontPreset,

                glassOpacity: normalizeGlassOpacity(obj.glassOpacity ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.glassOpacity),

                wallpaper: obj.wallpaper,

                backgroundPreset: normalizeBackgroundPreset(

                    (obj.appearance as AppSettingsState['appearance'] | undefined)?.backgroundPreset,

                ),

                brandColor: obj.brandColor ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.brandColor,

            },

            security: {

                ...LAWYER_SETTINGS_V2_DEFAULTS.security,

                privacyBlur: LAWYER_SETTINGS_V2_DEFAULTS.security.privacyBlur,

                biometricLock: obj.biometric ?? LAWYER_SETTINGS_V2_DEFAULTS.security.biometricLock,

            },

            data: {

                ...LAWYER_SETTINGS_V2_DEFAULTS.data,

                autoSave: obj.autoSave ?? LAWYER_SETTINGS_V2_DEFAULTS.data.autoSave,

                cloudSync: obj.cloudSync ?? LAWYER_SETTINGS_V2_DEFAULTS.data.cloudSync,

            },

        };

        return normalizeAppSettings(deepMerge(LAWYER_SETTINGS_V2_DEFAULTS, migrated));

    }



    const base = { ...LAWYER_SETTINGS_V2_DEFAULTS };

    if (themeKey) base.appearance = { ...base.appearance, theme: themeKey };

    if (shapeKey) base.appearance = { ...base.appearance, shape: shapeKey };

    return base;

}

