/** يُطبّق ثلاثة أحجام فقط — يُحوّل «واضح»/20px إلى كبير/18px. */
export function normalizeFontSizePx(px: unknown): number {
    const n = typeof px === 'number' && Number.isFinite(px) ? px : 16;
    if (n <= 14) return 14;
    if (n >= 18) return 18;
    if (n <= 15) return 14;
    if (n <= 17) return 16;
    return 18;
