import { reconcileBiometricSessionLockEnabled } from '@/app/services/security/biometricSessionService';
import type { SecuritySettings } from '@/app/services/settings/types';

type SettingsSecurityRuntimeHandlers = {
    patchSecurity: (patch: Partial<SecuritySettings>) => void;
};

/**
 * Side effects that must follow persisted security flags — not only UI toggles.
 * Runs at boot/rehydrate and whenever security settings change.
 */
export async function applySettingsSecurityRuntime(
    security: SecuritySettings,
    handlers?: SettingsSecurityRuntimeHandlers,
): Promise<'ok' | 'biometric-reset'> {
    if (security.localOnlyMode) {
        const { RealtimeService } = await import('@/app/services/RealtimeService');
        await RealtimeService.unsubscribeAll();
        try {
            const { supabase } = await import('@/app/lib/supabase-client');
            await supabase.removeAllChannels();
            supabase.realtime?.disconnect?.();
        } catch {
            /* العميل قد لا يكون مهيأً بعد */
        }
    }

    const reconcile = reconcileBiometricSessionLockEnabled(security.biometricLock);
    if (reconcile === 'reset') {
        handlers?.patchSecurity({ biometricLock: false });
        return 'biometric-reset';
    }

    return 'ok';
}

import { isSentryEnabledInBuild as isSentryConfigured } from '@/app/observability/sentryBuildPolicy';

export type SettingsPerfReportContext = {
    userId?: string;
    activeSection?: string;
    hadChunkCached?: boolean;
};

type SentryModule = {
    addBreadcrumb?: (crumb: {
        category?: string;
        message?: string;
        level?: string;
        data?: Record<string, unknown>;
    }) => void;
    metrics?: {
        distribution?: (
            name: string,
            value: number,
            options?: { unit?: string; attributes?: Record<string, string | number | boolean> },
        ) => void;
    };
};

let sentryModulePromise: Promise<SentryModule | null> | null = null;

function loadSentryModule(): Promise<SentryModule | null> {
    if (!isSentryConfigured()) return Promise.resolve(null);
    if (!sentryModulePromise) {
        sentryModulePromise = import('@sentry/react')
            .then((mod) => mod as SentryModule)
            .catch(() => null);
    }
    return sentryModulePromise;
}

/** breadcrumb + metric distribution — best effort، لا يرمي */
export function reportSettingsOpenToSentry(
    durationMs: number,
    context: SettingsPerfReportContext = {},
): void {
    if (durationMs < 0 || !Number.isFinite(durationMs)) return;

    void loadSentryModule().then((Sentry) => {
        if (!Sentry) return;

        Sentry.addBreadcrumb?.({
            category: 'settings.perf',
            message: `settings open→interactive ${durationMs}ms`,
            level: 'info',
            data: {
                durationMs,
                activeSection: context.activeSection ?? null,
                hadChunkCached: context.hadChunkCached ?? null,
                userId: context.userId ? '[redacted]' : null,
            },
        });

        Sentry.metrics?.distribution?.('settings.open_to_interactive_ms', durationMs, {
            unit: 'millisecond',
            attributes: {
                had_chunk_cached: Boolean(context.hadChunkCached),
                active_section: context.activeSection ?? 'unknown',
            },
        });
    });
}

