import { persistenceRepository } from '@/app/infrastructure/persistence/LocalStorageRepository';
import type { ThemeKey, ShapeKey } from '@/app/types/common';
import { LAWYER_SETTINGS_V2_DEFAULTS } from './defaults';
import type { AppSettingsState } from './types';
import { SETTINGS_SCHEMA_VERSION } from './types';
import { normalizeLitePerformanceMode } from '@/app/runtime/devicePerformanceTier';
import { normalizeHomeLayout } from './homeLayout';
import { normalizeNotificationSettings } from './notificationSettings';
import { normalizeGlassOpacity } from './surfaceAppearance';
import { persistLocalOnlyBootFlag } from './localOnlyUrlPolicy';

let cached: AppSettingsState | null = null;
let cacheAt = 0;
let live: AppSettingsState | null = null;
let liveAt = 0;
const liveListeners = new Set<() => void>();

function notifyLawyerSettingsLiveListeners(): void {
    for (const listener of liveListeners) listener();
}

function ensureRuntimeListener(): void {
    if (typeof window === 'undefined') return;
    const w = window as unknown as { __hamiSettingsRuntimeInstalled?: boolean };
    if (w.__hamiSettingsRuntimeInstalled) return;
    w.__hamiSettingsRuntimeInstalled = true;
    window.addEventListener('hami:settings-updated', (evt) => {
        try {
            const next = (evt as CustomEvent).detail as unknown;
            if (!next || typeof next !== 'object') return;
            live = next as AppSettingsState;
            liveAt = Date.now();
            cached = live;
            cacheAt = liveAt;
            notifyLawyerSettingsLiveListeners();
        } catch {
            return;
        }
    });
}

export function invalidateLawyerSettingsCache(): void {
    cached = null;
    cacheAt = 0;
}

export function publishLawyerSettingsLive(next: AppSettingsState): void {
    live = next;
    liveAt = Date.now();
    cached = next;
    cacheAt = liveAt;
    notifyLawyerSettingsLiveListeners();
}

/** اشتراك React (useSyncExternalStore) — بلا TTL يعيد إنشاء المرجع */
export function subscribeLawyerSettingsLive(onStoreChange: () => void): () => void {
    ensureRuntimeListener();
    liveListeners.add(onStoreChange);
    return () => {
        liveListeners.delete(onStoreChange);
    };
}

/** مرجع مستقر طالما لم يُنشر تحديث — مناسب لـ useSyncExternalStore */
export function getLawyerSettingsStoreSnapshot(): AppSettingsState {
    ensureRuntimeListener();
    if (live) return live;
    if (cached) return cached;
    return getLawyerSettingsSnapshot();
}

function clampGlassOpacity(value: unknown): number {
    return normalizeGlassOpacity(value);
}

function clamp01(value: unknown, fallback: number): number {
    const n = typeof value === 'number' && Number.isFinite(value) ? value : fallback;
    return Math.min(1, Math.max(0, n));
}

/**
 * لقطة sync خفيفة بلا migrate / backgroundPresets / homeLayout —
 * المخطط الحالي يُدمَج سطحياً؛ الإرث يأخذ defaults + theme/shape حتى يكتمل migrate بعد paint.
 */
export function hydrateLawyerSettingsFast(
    raw: unknown,
    themeKey?: ThemeKey | null,
    shapeKey?: ShapeKey | null,
): AppSettingsState {
    if (raw && typeof raw === 'object') {
        const obj = raw as Partial<AppSettingsState> & Record<string, unknown>;
        if (obj.version === SETTINGS_SCHEMA_VERSION && obj.appearance) {
            const appearance = {
                ...LAWYER_SETTINGS_V2_DEFAULTS.appearance,
                ...obj.appearance,
                themeMode: 'dark' as const,
                theme: (themeKey ?? obj.appearance.theme ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.theme) as ThemeKey,
                shape: (shapeKey ?? obj.appearance.shape ?? LAWYER_SETTINGS_V2_DEFAULTS.appearance.shape) as ShapeKey,
                glassOpacity: clampGlassOpacity(obj.appearance.glassOpacity),
                backgroundPreset: obj.appearance.backgroundPreset ?? 'none',
                backgroundPatternOpacity: clamp01(
                    obj.appearance.backgroundPatternOpacity,
                    LAWYER_SETTINGS_V2_DEFAULTS.appearance.backgroundPatternOpacity,
                ),
                backgroundPatternBlur: clamp01(
                    obj.appearance.backgroundPatternBlur,
                    LAWYER_SETTINGS_V2_DEFAULTS.appearance.backgroundPatternBlur,
                ),
                homeContainerBorder: obj.appearance.homeContainerBorder !== false,
                wallpaper: undefined,
            };
            const localOnlyMode = obj.security?.localOnlyMode === true;
            if (localOnlyMode) persistLocalOnlyBootFlag(true);
            return {
                version: SETTINGS_SCHEMA_VERSION,
                appearance,
                security: {
                    ...LAWYER_SETTINGS_V2_DEFAULTS.security,
                    ...obj.security,
                    localOnlyMode,
                },
                data: { ...LAWYER_SETTINGS_V2_DEFAULTS.data, ...obj.data },
                performance: {
                    ...LAWYER_SETTINGS_V2_DEFAULTS.performance,
                    ...obj.performance,
                    litePerformance: normalizeLitePerformanceMode(obj.performance?.litePerformance),
                },
                homeLayout: normalizeHomeLayout(obj.homeLayout ?? LAWYER_SETTINGS_V2_DEFAULTS.homeLayout),
            notifications: normalizeNotificationSettings(obj.notifications),
            };
        }
    }

    const base: AppSettingsState = {
        ...LAWYER_SETTINGS_V2_DEFAULTS,
        appearance: { ...LAWYER_SETTINGS_V2_DEFAULTS.appearance },
    };
    if (themeKey) base.appearance = { ...base.appearance, theme: themeKey };
    if (shapeKey) base.appearance = { ...base.appearance, shape: shapeKey };
    return base;
}

/** Sync read for services/hooks outside React (short TTL cache). */
export function getLawyerSettingsSnapshot(): AppSettingsState {
    ensureRuntimeListener();
    const now = Date.now();
    if (live && now - liveAt < 60_000) return live;
    if (cached && now - cacheAt < 400) return cached;
    const raw = persistenceRepository.load('lawyer_settings');
    const theme = persistenceRepository.load<ThemeKey>('lawyer_theme');
    const shape = persistenceRepository.load<ShapeKey>('lawyer_shape');
    cached = hydrateLawyerSettingsFast(raw, theme, shape);
    cacheAt = now;
    return cached;
}

import type { CSSProperties } from 'react';
import type { ThemeKey, ThemeMode } from '@/app/types/common';
import { resolveThemeMode } from './resolveThemeMode';
import { LAWYER_THEME_TOKENS } from './lawyerThemeTokens';
import {
    BACKGROUND_PRESET_MAP,
    normalizeBackgroundPreset,
    type BackgroundPresetId,
} from './backgroundPresets';
import type { AppearanceSettings } from './types';

const BACKGROUND_PATTERN_OPACITY_MIN = 0.05;
export const BACKGROUND_PATTERN_OPACITY_MAX = 0.78;

/** كثافة/شفافية بطاقات لوحة القيادة — 0 شفاف، 1 كثيف */
const GLASS_OPACITY_MIN = 0;
const GLASS_OPACITY_MAX = 1;
const GLASS_OPACITY_DEFAULT = 0.92;

export function normalizeGlassOpacity(raw: unknown): number {
    if (typeof raw !== 'number' || Number.isNaN(raw)) return GLASS_OPACITY_DEFAULT;
    return Math.min(GLASS_OPACITY_MAX, Math.max(GLASS_OPACITY_MIN, raw));
}

/** الوضع الفاتح — رمادي هادئ دافئ لتقليل الوهج */
const LAWYER_LIGHT_SURFACE_BG = '#cfd3db';

/** يُعاد ضبط القيم القديمة المحفوظة إلى النطاق الجديد */
function remapLegacyPatternOpacity(raw: number): number {
    if (raw > BACKGROUND_PATTERN_OPACITY_MAX) {
        return BACKGROUND_PATTERN_OPACITY_MIN + (raw - BACKGROUND_PATTERN_OPACITY_MIN) * 0.65;
    }
    return raw;
}

export function normalizeBackgroundPatternOpacity(raw: unknown): number {
    if (typeof raw !== 'number' || Number.isNaN(raw)) return 0.32;
    const remapped = remapLegacyPatternOpacity(raw);
    return Math.min(BACKGROUND_PATTERN_OPACITY_MAX, Math.max(BACKGROUND_PATTERN_OPACITY_MIN, remapped));
}

function svgDataUrl(svg: string): string {
    return `url("data:image/svg+xml,${encodeURIComponent(svg.trim())}")`;
}

function resolvePatternAccent(theme: ThemeKey, themeMode: ThemeMode): string {
    const token = LAWYER_THEME_TOKENS[theme] ?? LAWYER_THEME_TOKENS.gold;
    if (resolveThemeMode(themeMode) === 'light') {
        return token.secondary;
    }
    return token.primary;
}

function buildPresetSvg(presetId: BackgroundPresetId, accent: string): string | null {
    const preset = BACKGROUND_PRESET_MAP[presetId];
    if (!preset?.svg) return null;
    return preset.svg.replace(/\{\{ACCENT\}\}/g, accent);
}

/**
 * شفافية طبقة الزخرفة على البطاقة — تتبع المنزلق/المستوى بلا أرضية تلغي «خفيف».
 */
export function resolvePatternLayerOpacity(rawOpacity: unknown, themeMode: ThemeMode): number {
    let opacity = normalizeBackgroundPatternOpacity(rawOpacity);
    if (resolveThemeMode(themeMode) === 'light') {
        opacity = opacity * 0.88;
    }
    const scaled = opacity * 0.95;
    return Math.min(0.92, Math.max(0.05, scaled));
}

export function resolveLawyerSurfaceBaseColor(
    themeKey: ThemeKey,
    themeMode: ThemeMode,
    hasWallpaper: boolean,
): string {
    if (hasWallpaper) return 'transparent';
    if (resolveThemeMode(themeMode) === 'light') return LAWYER_LIGHT_SURFACE_BG;
    const token = LAWYER_THEME_TOKENS[themeKey] ?? LAWYER_THEME_TOKENS.gold;
    return token.bg;
}

type PatternAppearance = Pick<
    AppearanceSettings,
    'backgroundPreset' | 'backgroundPatternOpacity' | 'theme' | 'themeMode'
>;

export function resolvePatternOverlayStyle(
    appearance: PatternAppearance,
    enabled: boolean,
): CSSProperties | null {
    if (!enabled) return null;

    const presetId = normalizeBackgroundPreset(appearance.backgroundPreset);
    if (presetId === 'none') return null;

    const preset = BACKGROUND_PRESET_MAP[presetId];
    if (!preset) return null;

    const accent = resolvePatternAccent(appearance.theme, appearance.themeMode);
    const opacity = resolvePatternLayerOpacity(
        appearance.backgroundPatternOpacity,
        appearance.themeMode,
    );

    const svg = buildPresetSvg(presetId, accent);
    if (!svg) return null;

    return {
        backgroundImage: svgDataUrl(svg),
        backgroundSize: preset.backgroundSize,
        backgroundRepeat: preset.backgroundSize.includes('100%') ? 'no-repeat' : 'repeat',
        backgroundPosition: 'center',
        opacity,
    };
}

/**
 * زخرفة بطاقة رئيسية حيّة — شريط التخصيص يُترجم بوضوح على البطاقة
 * (معاينة الإعدادات أقوى؛ الحيّة تبقى تحت سقف يمنع طمس المحتوى).
 */
export function resolveHomeBlockPatternStyle(
    presetId: BackgroundPresetId,
    accent: string,
    patternOpacity = 0.32,
    themeMode: ThemeMode = 'dark',
): CSSProperties | null {
    if (presetId === 'none') return null;
    const preset = BACKGROUND_PRESET_MAP[presetId];
    if (!preset?.svg) return null;
    const svg = preset.svg.replace(/\{\{ACCENT\}\}/g, accent);
    const layerOpacity = resolvePatternLayerOpacity(patternOpacity, themeMode);
    return {
        backgroundImage: svgDataUrl(svg),
        backgroundSize: preset.backgroundSize,
        backgroundRepeat: preset.backgroundSize.includes('100%') ? 'no-repeat' : 'repeat',
        backgroundPosition: 'center',
        opacity: layerOpacity,
    };
}

/** معاينة مصغّرة في الإعدادات — فروق خفيف/متوسط/واضح واضحة */
export function resolvePatternPreviewStyle(
    presetId: BackgroundPresetId,
    accent: string,
    baseColor: string,
    patternOpacity = 0.32,
    themeMode: ThemeMode = 'dark',
): CSSProperties {
    if (presetId === 'none') {
        return { backgroundColor: baseColor };
    }
    const preset = BACKGROUND_PRESET_MAP[presetId];
    if (!preset) return { backgroundColor: baseColor };
    const svg = preset.svg?.replace(/\{\{ACCENT\}\}/g, accent);
    const normalized = normalizeBackgroundPatternOpacity(patternOpacity);
    const previewOpacity = 0.22 + normalized * 0.78;
    return {
        backgroundColor: baseColor,
        ...(svg
            ? {
                  backgroundImage: svgDataUrl(svg),
                  backgroundSize: preset.backgroundSize,
                  backgroundRepeat: preset.backgroundSize.includes('100%') ? 'no-repeat' : 'repeat',
                  backgroundPosition: 'center',
              }
            : {}),
        opacity: Math.min(1, previewOpacity),
    };
}

/** نطاق تطبيق لون الخلفية / زخرفة اللوحة */
export type SurfaceApplyTarget = 'board' | 'blocks' | 'both';

/** نطاق تطبيق ألوان الشبكة — يشمل النقوش على البطاقات */
export type ColorApplyTarget = SurfaceApplyTarget | 'patterns';

export const SURFACE_APPLY_TARGET_OPTIONS: ReadonlyArray<{
    value: SurfaceApplyTarget;
    label: string;
}> = [
    { value: 'board', label: 'اللوحة' },
    { value: 'blocks', label: 'الأقسام' },
];

export const COLOR_APPLY_TARGET_OPTIONS: ReadonlyArray<{
    value: ColorApplyTarget;
    label: string;
}> = [
    ...SURFACE_APPLY_TARGET_OPTIONS,
    { value: 'patterns', label: 'النقوش' },
];

export function normalizeSurfaceApplyTarget(raw: unknown): SurfaceApplyTarget {
    if (raw === 'board' || raw === 'blocks' || raw === 'both') return raw;
    return 'board';
}

export function normalizeColorApplyTarget(raw: unknown): ColorApplyTarget {
    if (raw === 'patterns') return 'patterns';
    return normalizeSurfaceApplyTarget(raw);
}

export function isPatternsColorTarget(target: ColorApplyTarget | undefined): boolean {
    return normalizeColorApplyTarget(target) === 'patterns';
}

export function appliesToBoard(target: SurfaceApplyTarget | ColorApplyTarget | undefined): boolean {
    const t = normalizeColorApplyTarget(target);
    return t === 'board' || t === 'both';
}

export function appliesToBlocks(target: SurfaceApplyTarget | ColorApplyTarget | undefined): boolean {
    const t = normalizeColorApplyTarget(target);
    return t === 'blocks' || t === 'both';
}

