type VerifySensitiveSettingsOptions = {
    /** نص يُطلب كتابته حرفياً عند غياب البيومتري */
    confirmPhrase: string;
    promptMessage?: string;
    title?: string;
};

const CHALLENGE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

function randomChallengeToken(length = 4): string {
    if (typeof crypto === 'undefined' || typeof crypto.getRandomValues !== 'function') {
        throw new Error('csprng_unavailable');
    }
    const bytes = new Uint8Array(length);
    crypto.getRandomValues(bytes);
    let out = '';
    for (let i = 0; i < length; i += 1) {
        out += CHALLENGE_ALPHABET[bytes[i]! % CHALLENGE_ALPHABET.length]!;
    }
    return out;
}

function timingSafeEqualUtf8(left: string, right: string): boolean {
    const encoder = new TextEncoder();
    const a = encoder.encode(left);
    const b = encoder.encode(right);
    const len = Math.max(a.length, b.length);
    let diff = a.length ^ b.length;
    for (let i = 0; i < len; i += 1) {
        diff |= (a[i] ?? 0) ^ (b[i] ?? 0);
    }
    return diff === 0;
}

/**
 * يولّد عبارة تأكيد لمرة واحدة (أساس + رمز عشوائي) حتى لا تُخمَّن العبارة الثابتة
 * عند غياب البيومتري.
 */
export function mintSensitiveConfirmChallenge(basePhrase: string): {
    confirmPhrase: string;
    promptMessage: string;
} {
    const token = randomChallengeToken(4);
    const confirmPhrase = `${basePhrase.trim()}-${token}`;
    return {
        confirmPhrase,
        promptMessage: `اكتب «${confirmPhrase}» حرفياً للمتابعة:`,
    };
}

async function verifyWithBiometric(security: ReturnType<typeof getLawyerSettingsSnapshot>['security']): Promise<boolean | null> {
    if (!security.biometricLock) return null;

    const biometricOk = await verifyBiometricSessionUnlock();
    if (biometricOk === true) return true;
    if (biometricOk === false) {
        SmartToast.warning('تعذّر التحقق البيومتري — ألغِ العملية أو فعّل البصمة من جديد');
        return false;
    }

    return null;
}

/** تحقق إضافي قبل مسح/إعادة ضبط — بيومتري إن وُجد، وإلا عبارة تأكيد مكتوبة */
export async function verifySensitiveSettingsAction(options: VerifySensitiveSettingsOptions): Promise<boolean> {
    const { confirmPhrase, promptMessage, title } = options;
    const security = getLawyerSettingsSnapshot().security;

    const biometricResult = await verifyWithBiometric(security);
    if (biometricResult === true) return true;
    if (biometricResult === false) return false;

    const typed = await SmartDialog.prompt(
        promptMessage ?? `اكتب «${confirmPhrase}» للمتابعة:`,
        '',
        { title: title ?? 'تأكيد الهوية', confirmText: 'متابعة', cancelText: 'إلغاء' },
    );
    const normalized = typed?.trim() ?? '';
    if (!normalized) return false;
    if (!timingSafeEqualUtf8(normalized, confirmPhrase)) {
        SmartToast.warning('نص التأكيد غير صحيح');
        return false;
    }
    return true;
}

/** نسبة إطار الهاتف — تطابق غطاء لوحة المحامي */
export const WALLPAPER_EDITOR_ASPECT = 9 / 19.5;

const WALLPAPER_EXPORT_WIDTH = 960;
export const WALLPAPER_EXPORT_MAX_BYTES = 480_000;

export type WallpaperEditorTransform = {
    /** مضاعف فوق ملء الإطار — 1 = cover افتراضي */
    scale: number;
    /** -1…1 أفقي */
    offsetX: number;
    /** -1…1 عمودي */
    offsetY: number;
};

export const WALLPAPER_EDITOR_DEFAULT_TRANSFORM: WallpaperEditorTransform = {
    scale: 1,
    offsetX: 0,
    offsetY: 0,
};

export function clampWallpaperEditorTransform(
    transform: WallpaperEditorTransform,
): WallpaperEditorTransform {
    return {
        scale: Math.min(3, Math.max(1, transform.scale)),
        offsetX: Math.min(1, Math.max(-1, transform.offsetX)),
        offsetY: Math.min(1, Math.max(-1, transform.offsetY)),
    };
}

export function computeWallpaperCoverLayout(
    imgW: number,
    imgH: number,
    frameW: number,
    frameH: number,
    transform: WallpaperEditorTransform,
): {
    drawW: number;
    drawH: number;
    maxPanX: number;
    maxPanY: number;
    left: number;
    top: number;
} {
    const { scale, offsetX, offsetY } = clampWallpaperEditorTransform(transform);
    const coverScale = Math.max(frameW / imgW, frameH / imgH);
    const drawScale = coverScale * scale;
    const drawW = imgW * drawScale;
    const drawH = imgH * drawScale;
    const maxPanX = Math.max(0, (drawW - frameW) / 2);
    const maxPanY = Math.max(0, (drawH - frameH) / 2);
    const left = (frameW - drawW) / 2 + offsetX * maxPanX;
    const top = (frameH - drawH) / 2 + offsetY * maxPanY;
    return { drawW, drawH, maxPanX, maxPanY, left, top };
}

export function renderWallpaperCanvas(
    img: Pick<HTMLImageElement, 'naturalWidth' | 'naturalHeight' | 'width' | 'height'>,
    transform: WallpaperEditorTransform,
    aspect = WALLPAPER_EDITOR_ASPECT,
): HTMLCanvasElement {
    const canvas = document.createElement('canvas');
    const outW = WALLPAPER_EXPORT_WIDTH;
    const outH = Math.round(outW / aspect);
    canvas.width = outW;
    canvas.height = outH;

    const imgW = img.naturalWidth || img.width;
    const imgH = img.naturalHeight || img.height;
    const { left, top, drawW, drawH } = computeWallpaperCoverLayout(
        imgW,
        imgH,
        outW,
        outH,
        transform,
    );

    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('canvas unavailable');
    ctx.drawImage(img as CanvasImageSource, left, top, drawW, drawH);
    return canvas;
}

export function canvasToWallpaperDataUrl(canvas: HTMLCanvasElement): Promise<string> {
    const minQuality = 0.5;
    const maxQuality = 0.72;
    let low = minQuality;
    let high = maxQuality;

    const yieldToMain = (): Promise<void> =>
        new Promise((resolve) => {
            const sched = (
                globalThis as unknown as {
                    scheduler?: { yield?: () => Promise<void> };
                }
            ).scheduler;
            if (sched?.yield) {
                void sched.yield().then(resolve, () => {
                    setTimeout(resolve, 0);
                });
                return;
            }
            setTimeout(resolve, 0);
        });

    return (async () => {
        let best = canvas.toDataURL('image/jpeg', high);
        if (!best) throw new Error('canvas export failed');

        if (best.length <= WALLPAPER_EXPORT_MAX_BYTES) {
            return best;
        }

        for (let i = 0; i < 6; i++) {
            await yieldToMain();
            const mid = (low + high) / 2;
            const candidate = canvas.toDataURL('image/jpeg', mid);
            if (candidate.length <= WALLPAPER_EXPORT_MAX_BYTES) {
                best = candidate;
                low = mid;
            } else {
                high = mid;
            }
        }

        if (best.length > WALLPAPER_EXPORT_MAX_BYTES) {
            throw new Error('image too large');
        }
        return best;
    })();
}

export async function loadWallpaperImageFromUrl(url: string): Promise<HTMLImageElement> {
    return new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => resolve(img);
        img.onerror = () => reject(new Error('image load failed'));
        img.src = url;
    });
}

import { HOME_MAIN_GRID_PAINTED_EVENT } from '@/app/bootstrap/bootEventNames';

const decodedSources = new Set<string>();
let holdWallpaperCssImage = false;
const HOME_PAINT_FALLBACK_MS = 2_500;

function isHomeMainGridPaintedFlag(): boolean {
    return typeof window !== 'undefined' && window.__hamiHomeMainGridPainted__ === true;
}

/** يمنع حقن --hami-wallpaper-image حتى تُرسم شبكة المنزل */
export function holdWallpaperCssImageUntilHomePainted(): void {
    holdWallpaperCssImage = true;
}

export function isWallpaperCssImageHeld(): boolean {
    return holdWallpaperCssImage;
}

export function releaseWallpaperCssImageHold(): void {
    holdWallpaperCssImage = false;
}

/** بعد أول طلاء للشبكة — أو مهلة إن لم تُرسم (شاشة دخول) */
export function scheduleAfterHomeMainGridPaint(task: () => void): void {
    if (typeof window === 'undefined' || isHomeMainGridPaintedFlag()) {
        task();
        return;
    }
    let done = false;
    const run = () => {
        if (done) return;
        done = true;
        window.removeEventListener(HOME_MAIN_GRID_PAINTED_EVENT, run);
        window.clearTimeout(fallback);
        task();
    };
    const fallback = window.setTimeout(run, HOME_PAINT_FALLBACK_MS);
    window.addEventListener(HOME_MAIN_GRID_PAINTED_EVENT, run, { once: true });
}

export function resetWallpaperPaintDeferralForTests(): void {
    holdWallpaperCssImage = false;
    decodedSources.clear();
}

/**
 * يضمن فك ترميز الصورة قبل رسمها كخلفية — يمنع وميض/فراغ أثناء paint.
 * يفشل بصمت (لا يحجب الإقلاع).
 */
export async function ensureWallpaperDecoded(src: string | undefined | null): Promise<void> {
    if (!src || typeof Image === 'undefined') return;
    if (decodedSources.has(src)) return;

    await new Promise<void>((resolve) => {
        const img = new Image();
        const finish = () => {
            decodedSources.add(src);
            resolve();
        };
        img.onload = () => {
            if (typeof img.decode === 'function') {
                void img.decode().then(finish).catch(finish);
                return;
            }
            finish();
        };
        img.onerror = finish;
        img.src = src;
    });
}

export function clearWallpaperDecodeCache(): void {
    decodedSources.clear();
}

