        const outcome = await applyStorageSchemaBoot(port, RELEASE);

        expect(outcome.kind).toBe('stamped');
        expect(outcome.record.origin).toBe('pre-stamp');
    });

    it('لا يعيد الكتابة حين لا يتغيّر شيء', async () => {
        const port = memoryPort();
        await applyStorageSchemaBoot(port, RELEASE);
        const first = port.dump()[STORAGE_SCHEMA_KEY];

        const outcome = await applyStorageSchemaBoot(port, RELEASE);
        expect(outcome.kind).toBe('unchanged');
        expect(port.dump()[STORAGE_SCHEMA_KEY]).toBe(first);
    });

    it('يسجّل الإصدار الجديد ويحفظ تاريخ أول ظهور', async () => {
        const port = memoryPort();
        await applyStorageSchemaBoot(port, RELEASE);
        const firstSeenAt = parseStorageSchemaRecord(port.dump()[STORAGE_SCHEMA_KEY])?.firstSeenAt;

        await applyStorageSchemaBoot(port, 'hami-app@10.6.0+def5678');
        const after = parseStorageSchemaRecord(port.dump()[STORAGE_SCHEMA_KEY]);

        expect(after?.lastRelease).toBe('hami-app@10.6.0+def5678');
        expect(after?.firstSeenAt).toBe(firstSeenAt);
    });

    it('لا يلمس بيانات كتبها إصدار أحدث', async () => {
        const ahead = JSON.stringify({
            v: CURRENT_STORAGE_SCHEMA_VERSION + 5,
            firstSeenAt: '2026-01-01T00:00:00.000Z',
            origin: 'fresh',
            lastRelease: 'hami-app@99.0.0+future',
        });
        const port = memoryPort({ [STORAGE_SCHEMA_KEY]: ahead });

        const outcome = await applyStorageSchemaBoot(port, RELEASE);

        expect(outcome.kind).toBe('ahead');
        expect(port.dump()[STORAGE_SCHEMA_KEY]).toBe(ahead);
    });

    it('يُعيد الختم حين يكون المخزون غير مفهوم بدل البناء على نسب كاذب', async () => {
        const port = memoryPort({ [STORAGE_SCHEMA_KEY]: '{"v":"ليس رقماً"}' });
        const outcome = await applyStorageSchemaBoot(port, RELEASE);

        expect(outcome.kind).toBe('stamped');
        expect(outcome.record.v).toBe(CURRENT_STORAGE_SCHEMA_VERSION);
    });

    it('يرفض سلسلة ترحيل مقطوعة بدل تخطّي خطوة بصمت', async () => {
        const port = memoryPort({
            [STORAGE_SCHEMA_KEY]: JSON.stringify({
                v: -0 + CURRENT_STORAGE_SCHEMA_VERSION - 1,
                firstSeenAt: '2026-01-01T00:00:00.000Z',
                origin: 'pre-stamp',
                lastRelease: 'old',
            }),
        });

        // لا ترحيل مسجَّل من النسخة السابقة — يجب أن يرمي لا أن يقفز
        await expect(applyStorageSchemaBoot(port, RELEASE)).rejects.toThrow(/سلسلة الترحيل مقطوعة/);
    });
});

describe('سلامة سجلّ الترحيلات', () => {
    /*
     * رفع النسخة بلا ترحيل يرمي على جهاز المستخدم لا هنا. هذا الفحص يُسقِط
     * البناء بدلاً من ذلك: كل قفزة نسخة لها خطوة، والخطوات بلا فجوة ولا تكرار.
     */
    it('يغطّي كل قفزة نسخة بخطوة واحدة بلا فجوة', () => {
        const froms = STORAGE_SCHEMA_MIGRATIONS.map((m) => m.from);
        expect(new Set(froms).size).toBe(froms.length);

        for (let step = 1; step < CURRENT_STORAGE_SCHEMA_VERSION; step += 1) {
            expect(froms).toContain(step);
        }
    });

    it('لا يسجّل ترحيلاً لنسخة لم تصدر بعد', () => {
        for (const migration of STORAGE_SCHEMA_MIGRATIONS) {
            expect(migration.from).toBeLessThan(CURRENT_STORAGE_SCHEMA_VERSION);
            expect(migration.from).toBeGreaterThanOrEqual(1);
            expect(migration.describe.trim()).not.toBe('');
        }
    });

    it('ينفّذ الخطوات بالترتيب ويختم بعدها', async () => {
        const calls: string[] = [];
        const migrations: SchemaMigration[] = [
            { from: 1, describe: 'أ', run: async () => void calls.push('1->2') },
            { from: 2, describe: 'ب', run: async () => void calls.push('2->3') },
        ];

        // نحاكي المُشغّل بحدود مُعلَنة بدل تزييف الثوابت المُصدَّرة
        const chain = [1, 2].map((step) => migrations.find((m) => m.from === step)!);
        for (const migration of chain) await migration.run(memoryPort());

        expect(calls).toEqual(['1->2', '2->3']);
    });
});

import {
    applyStorageSchemaBoot,
    type SchemaBootOutcome,
    type SchemaStoragePort,
} from './storageSchemaMigrations';

/**
 * يُشغَّل مرّة واحدة لكل جلسة، من داخل `ensurePersistedReady` — أي قبل أي قراءة
 * نطاقية، لأن كل قارئ في التطبيق ينتظرها أصلاً. لا حاجة لبوّابة ثانية.
 */
let bootPromise: Promise<SchemaBootOutcome | null> | null = null;

async function reportOutcome(outcome: SchemaBootOutcome, appRelease: string): Promise<void> {
    if (outcome.kind === 'unchanged') return;

    /*
     * الاستيراد ديناميّ: هذه السلسلة تُقلع مع المخزن، وربط عميل الرصد بها
     * ثابتاً يجرّه إلى المسار الحرج لأجل بلاغ يقع مرّة في عمر التثبيت.
     */
    const { sentryCaptureMessage } = await import('@/app/observability/sentryClient');

    if (outcome.kind === 'ahead') {
        await sentryCaptureMessage('storage-schema: data written by a newer build', {
            storedVersion: outcome.record.v,
            runningRelease: appRelease,
            wroteBy: outcome.record.lastRelease,
        });
        return;
    }

    if (outcome.kind === 'migrated') {
        await sentryCaptureMessage('storage-schema: migrated', {
            toVersion: outcome.record.v,
            steps: outcome.applied,
            origin: outcome.record.origin,
        });
    }
}

export async function runStorageSchemaBootOnce(
    port: SchemaStoragePort,
    appRelease: string,
): Promise<SchemaBootOutcome | null> {
    if (bootPromise) return bootPromise;
    bootPromise = (async () => {
        try {
            const outcome = await applyStorageSchemaBoot(port, appRelease);
            void reportOutcome(outcome, appRelease).catch(() => undefined);
            return outcome;
        } catch {
            /*
             * فشل الختم لا يجوز أن يمنع فتح التطبيق: البيانات تُقرأ بلا ختم كما
             * كانت تُقرأ قبل وجوده. نُعيد `null` ونترك المحاولة للإقلاع التالي.
             */
            return null;
        }
    })();
    return bootPromise;
}

export function __resetStorageSchemaBootForTests(): void {
    bootPromise = null;
}

import {
    CURRENT_STORAGE_SCHEMA_VERSION,
    parseStorageSchemaRecord,
    serializeStorageSchemaRecord,
    STORAGE_SCHEMA_KEY,
    type StorageSchemaRecord,
} from './storageSchemaVersion';

/**
 * منفذ تخزين ضيّق عمداً.
 *
 * المُشغّل يعمل **داخل** `ensurePersistedReady`، فأي ترحيل يستدعيها يقف على
 * وعدٍ ينتظر نفسه. تمرير `get/set/remove/listKeys` وحدها يجعل هذا القفل
 * مستحيلاً بالبناء لا بالتذكير في تعليق.
 */
export interface SchemaStoragePort {
    get(key: string): Promise<string | null>;
    set(key: string, value: string): Promise<void>;
    remove(key: string): Promise<void>;
    listKeys(): Promise<string[]>;
}

export interface SchemaMigration {
    /** يُرحّل من `from` إلى `from + 1` */
    from: number;
    /** وصف قصير يظهر في السجل والبلاغ */
    describe: string;
    run(port: SchemaStoragePort): Promise<void>;
}

/**
 * لا ترحيلات بعد — وهذا هو الصدق: شكل البيانات لم يتغيّر منذ بدء الترقيم.
 *
 * أول تغيير في شكل مُخزَّن يضيف مُدخلاً هنا ويرفع
 * `CURRENT_STORAGE_SCHEMA_VERSION` بواحد. الترتيب تصاعديّ ولا فجوات.
 */
export const STORAGE_SCHEMA_MIGRATIONS: readonly SchemaMigration[] = [];

export type SchemaBootOutcome =
    | { kind: 'stamped'; record: StorageSchemaRecord }
    | { kind: 'unchanged'; record: StorageSchemaRecord }
    | { kind: 'migrated'; record: StorageSchemaRecord; applied: number }
    | { kind: 'ahead'; record: StorageSchemaRecord };

/** مفاتيح تكفي للحكم بأن الجهاز ليس تثبيتاً جديداً */
const DATA_PRESENCE_PREFIXES = [
    'lawyer_',
    'execution',
    'lawsuit',
    'hami:criminal:',
    'hami:calendar:',
    'hami:smartvault:',
    'hami:community:',
    'hami_quantum_legal_tasks',
];

async function deviceHasExistingData(port: SchemaStoragePort): Promise<boolean> {
    const keys = await port.listKeys();
    return keys.some(
        (key) => key !== STORAGE_SCHEMA_KEY && DATA_PRESENCE_PREFIXES.some((p) => key.startsWith(p)),
    );
}

function orderedMigrationsFrom(version: number): SchemaMigration[] {
    const chain: SchemaMigration[] = [];
    for (let step = version; step < CURRENT_STORAGE_SCHEMA_VERSION; step += 1) {
        const migration = STORAGE_SCHEMA_MIGRATIONS.find((m) => m.from === step);
        if (!migration) {
            throw new Error(
                `[storage-schema] لا ترحيل من ${step} إلى ${step + 1} — سلسلة الترحيل مقطوعة`,
            );
        }
        chain.push(migration);
    }
    return chain;
}

/**
 * يقرأ الختم، ويُطبّق ما يلزم، ويُعيد الكتابة.
 *
 * البيانات القادمة من إصدار **أحدث** لا تُلمس ولا تُنزَّل: الكود الحالي لا يعرف
 * شكلها، وكتابة أي شيء فوقها قد تُسقِط حقولاً لا يفهمها. نُبلِغ ونمضي بالقراءة
 * كما هي — والتحمّل أسلم من الإصلاح المُتوهَّم.
 */
export async function applyStorageSchemaBoot(
    port: SchemaStoragePort,
    appRelease: string,
): Promise<SchemaBootOutcome> {
    const stored = parseStorageSchemaRecord(await port.get(STORAGE_SCHEMA_KEY));
    const now = new Date().toISOString();

    if (!stored) {
        const origin = (await deviceHasExistingData(port)) ? 'pre-stamp' : 'fresh';
        const record: StorageSchemaRecord = {
            v: CURRENT_STORAGE_SCHEMA_VERSION,
            firstSeenAt: now,
            origin,
            lastRelease: appRelease,
        };
        await port.set(STORAGE_SCHEMA_KEY, serializeStorageSchemaRecord(record));
        return { kind: 'stamped', record };
    }

    if (stored.v > CURRENT_STORAGE_SCHEMA_VERSION) {
        return { kind: 'ahead', record: stored };
    }

    if (stored.v === CURRENT_STORAGE_SCHEMA_VERSION) {
        if (stored.lastRelease === appRelease) return { kind: 'unchanged', record: stored };
        const record: StorageSchemaRecord = { ...stored, lastRelease: appRelease };
        await port.set(STORAGE_SCHEMA_KEY, serializeStorageSchemaRecord(record));
        return { kind: 'unchanged', record };
    }

    const chain = orderedMigrationsFrom(stored.v);
    for (const migration of chain) {
        await migration.run(port);
    }
    const record: StorageSchemaRecord = {
        ...stored,
        v: CURRENT_STORAGE_SCHEMA_VERSION,
        lastRelease: appRelease,
        lastMigratedAt: now,
    };
    await port.set(STORAGE_SCHEMA_KEY, serializeStorageSchemaRecord(record));
    return { kind: 'migrated', record, applied: chain.length };
}

/**
 * مرساة نسخة البيانات على الجهاز.
 *
 * البيانات القانونية تعيش على جهاز المحامي وتبقى عبر التحديثات. وحين يتغيّر
 * شكل حقلٍ في إصدار قادم، يحتاج الترحيل أن يعرف **بأي إصدار كُتبت** البيانات
 * التي أمامه. بلا ختم مكتوب من اليوم، لا سبيل لمعرفة ذلك لاحقاً: كل جهاز
 * يحمل بيانات بلا نسب، والترحيل يصير تخميناً على أضابير لا تُعوَّض.
 *
 * ولهذا يُكتب الختم قبل الإطلاق لا بعده: بعده تبقى أجهزةٌ بلا ختم إلى الأبد.
 */

export const STORAGE_SCHEMA_KEY = 'hami:schema:v';

/**
 * النسخة الحالية لشكل البيانات المخزَّنة.
 *
 * تُرفع **فقط** حين يتغيّر شكل بيانات مُخزَّنة تغييراً لا يقرأه الكود القديم
 * أو لا يقرأه الجديد. ورفعها يوجب إضافة ترحيل في `storageSchemaMigrations`.
 */
export const CURRENT_STORAGE_SCHEMA_VERSION = 1;

/** أول إقلاع على هذا الجهاز: بيانات موجودة قبل الختم، أم تثبيت جديد */
export type StorageSchemaOrigin = 'fresh' | 'pre-stamp';

export interface StorageSchemaRecord {
    /** نسخة شكل البيانات المكتوبة على هذا الجهاز */
    v: number;
    /** أول لحظة وُضع فيها ختم — لا تُكتب ثانية */
    firstSeenAt: string;
    /** هل وُجدت بيانات قبل أول ختم */
    origin: StorageSchemaOrigin;
    /** آخر إصدار تطبيق كتب هنا — لتتبّع الترقية والتنزيل */
    lastRelease: string;
    /** آخر ترحيل نُفِّذ فعلاً */
    lastMigratedAt?: string;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

/**
 * تحليل صارم: ختم لا يُفهَم أسوأ من غياب ختم، لأنه يدّعي نسباً كاذباً.
 * الرجوع بـ`null` يدفع المُشغّل إلى إعادة الختم من جديد بدل البناء على وهم.
 */
export function parseStorageSchemaRecord(raw: string | null | undefined): StorageSchemaRecord | null {
    if (!raw?.trim()) return null;
    let parsed: unknown;
    try {
        parsed = JSON.parse(raw);
    } catch {
        return null;
    }
    if (!isPlainObject(parsed)) return null;

    const v = parsed.v;
    if (typeof v !== 'number' || !Number.isInteger(v) || v < 0) return null;

    const firstSeenAt = typeof parsed.firstSeenAt === 'string' ? parsed.firstSeenAt : '';
    if (!firstSeenAt) return null;

    const origin: StorageSchemaOrigin = parsed.origin === 'pre-stamp' ? 'pre-stamp' : 'fresh';
    const lastRelease = typeof parsed.lastRelease === 'string' ? parsed.lastRelease : 'unknown';
    const lastMigratedAt = typeof parsed.lastMigratedAt === 'string' ? parsed.lastMigratedAt : undefined;

    return { v, firstSeenAt, origin, lastRelease, ...(lastMigratedAt ? { lastMigratedAt } : {}) };
}

export function serializeStorageSchemaRecord(record: StorageSchemaRecord): string {
    return JSON.stringify(record);
}

