type DecryptedCacheListener = (key: string, value: string) => void;

const listeners: DecryptedCacheListener[] = [];

/** يُسجَّل من وحدات شواهد القبر — بلا استيراد SecureStore. */
export function onDecryptedCacheWrite(listener: DecryptedCacheListener): void {
    listeners.push(listener);
}

export function notifyDecryptedCacheWrite(key: string, value: string): void {
    for (const listener of listeners) listener(key, value);
}

import { onDecryptedCacheWrite } from '@/app/services/storage/decryptedCacheNotify';
import {
    cancelDeletedIdsPersist,
    isDeletedIdsStorageUnreadSync,
    queueDeletedIdsPersist,
} from '@/app/services/storage/deletedIdsPersistBridge';

function parseDeletedIdList(raw: string | null | undefined, isValidKey: (k: string) => boolean): string[] {
    if (!raw?.trim()) return [];
    try {
        const parsed: unknown = JSON.parse(raw);
        return Array.isArray(parsed)
            ? parsed.filter((k): k is string => typeof k === 'string' && isValidKey(k))
            : [];
    } catch {
        return [];
    }
}

/**
 * ذاكرة شواهد القبر لحارس المسح — بلا SecureStore.
 * التشفير عبر الجسر بعد أن يربط SecureStore نفسه.
 */
export function createDeletedIdsLiteStore(storageKey: string, isValidKey: (k: string) => boolean) {
    let memory: Set<string> | null = null;
    /** إضافات أثناء ciphertext بارد — تُدمَج عند فكّ التشفير دون مسح الأصل */
    let pendingWhileUnread: string[] = [];

    function hydrateFromRaw(raw: string | null | undefined): void {
        memory = new Set(parseDeletedIdList(raw, isValidKey));
        if (pendingWhileUnread.length > 0) {
            for (const id of pendingWhileUnread) {
                if (isValidKey(id)) memory.add(id);
            }
            pendingWhileUnread = [];
            queueDeletedIdsPersist(storageKey, [...memory]);
        }
    }

    onDecryptedCacheWrite((key, value) => {
        if (key === storageKey) hydrateFromRaw(value);
    });

    function read(): Set<string> {
        if (memory) return memory;
        if (typeof localStorage !== 'undefined') {
            try {
                const raw = localStorage.getItem(storageKey);
                if (raw !== null) {
                    localStorage.removeItem(storageKey);
                    hydrateFromRaw(raw);
                    queueDeletedIdsPersist(storageKey, [...(memory ?? [])]);
                    return memory ?? new Set();
                }
            } catch {
                /* ignore */
            }
        }
        /*
         * أصل مشفّر بارد ≠ قائمة فارغة. تثبيت [] عبر الجسر يمسح شواهد القرص.
         * أعد مجموعة مؤقتة بلا تثبيت memory حتى يصل onDecryptedCacheWrite.
         */
        if (isDeletedIdsStorageUnreadSync(storageKey)) {
            return new Set(pendingWhileUnread.filter(isValidKey));
        }
        memory = new Set();
        return memory;
    }

    function persistSnapshot(): void {
        queueDeletedIdsPersist(storageKey, [...read()]);
    }

    return {
        storageKey,
        read,
        add(ids: string[]): void {
            if (isDeletedIdsStorageUnreadSync(storageKey) && !memory) {
                for (const id of ids) {
                    if (isValidKey(id)) pendingWhileUnread.push(id);
                }
                return;
            }
            const set = read();
            for (const id of ids) {
                if (isValidKey(id)) set.add(id);
            }
            persistSnapshot();
        },
        has(id: string): boolean {
            return read().has(id);
        },
        resetForTests(): void {
            memory = null;
            pendingWhileUnread = [];
            cancelDeletedIdsPersist(storageKey);
            if (typeof localStorage === 'undefined') return;
            try {
                localStorage.removeItem(storageKey);
            } catch {
                /* ignore */
            }
        },
    };
}

type PersistDeletedIds = (storageKey: string, ids: string[]) => void;
type IsUnreadSync = (storageKey: string) => boolean;

let persistDeletedIds: PersistDeletedIds | null = null;
let isUnreadSyncProbe: IsUnreadSync | null = null;
const pending = new Map<string, string[]>();
let persistEpoch = 0;

/**
 * يربطه SecureStore عند التحميل. وحدات شواهد القبر لا تستورد SecureStore —
 * وإلا أغلقت دائرة مع حارس المسح.
 */
export function bindDeletedIdsPersist(fn: PersistDeletedIds): void {
    persistDeletedIds = fn;
    for (const [key, ids] of pending) fn(key, ids);
    pending.clear();
}

/** فحص unread بلا دائرة استيراد مع SecureStore */
export function bindDeletedIdsUnreadProbe(fn: IsUnreadSync): void {
    isUnreadSyncProbe = fn;
}

export function isDeletedIdsStorageUnreadSync(storageKey: string): boolean {
    try {
        return isUnreadSyncProbe?.(storageKey) ?? false;
    } catch {
        return false;
    }
}

export function queueDeletedIdsPersist(storageKey: string, ids: string[]): void {
    const epoch = persistEpoch;
    const run = () => {
        if (epoch !== persistEpoch) return;
        persistDeletedIds?.(storageKey, ids);
    };
    if (persistDeletedIds) {
        queueMicrotask(run);
        return;
    }
    pending.set(storageKey, ids);
}

export function cancelDeletedIdsPersist(storageKey: string): void {
    persistEpoch += 1;
    pending.delete(storageKey);
}

import { supabase } from '@/app/lib/supabase-client';
import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import { stripImageMetadata } from '@/app/utils/stripMetadata';
import { isLawyerWorkCloudLive } from '@/app/services/settings/lawyerWorkCloudGate';

const WORK_LOCAL_UPLOAD_CATEGORIES = new Set(['vault', 'scans']);

export const LawyerStorage = {
    /**
     * Uploads a file via WIFE-protected /api/upload (malware scan + ownership on server).
     */
    async uploadSmartFile(
        userId: string,
        file: File,
        category: 'scans' | 'audio' | 'drafts' | 'repository' | 'vault' | 'forum-media',
    ) {
        const sessionUserId = (await supabase.auth.getSession()).data.session?.user?.id ?? null;
        if (!sessionUserId || sessionUserId !== userId) {
            throw new Error('Unauthorized upload: session user mismatch');
        }
        if (WORK_LOCAL_UPLOAD_CATEGORIES.has(category) && !isLawyerWorkCloudLive()) {
            throw new Error('work_cloud_upload_disabled');
        }

        const looksLikeImage =
            file.type.startsWith('image/') || /\.(jpe?g|png|webp|gif|bmp|heic|heif)$/i.test(file.name);
        let uploadFile = file;
        if (looksLikeImage) {
            try {
                uploadFile = await stripImageMetadata(file);
            } catch {
                uploadFile = file;
            }
        }

        const formData = new FormData();
        formData.append('file', uploadFile);
        formData.append('category', category);

        const response = await SecureAPIClient.fetchSecureResponse('/api/upload', {
            method: 'POST',
            body: formData,
        });
        const text = await response.text().catch(() => '');
        let body: Record<string, unknown> = {};
        try {
            body = JSON.parse(text) as Record<string, unknown>;
        } catch {
            /* ignore */
        }
        if (!response.ok) {
            const message =
                typeof body.error === 'string' && body.error.trim()
                    ? body.error.trim()
                    : `Upload failed (${response.status})`;
            throw new Error(message);
        }

        const path = typeof body.path === 'string' ? body.path : '';
        const downloadUrl = typeof body.downloadUrl === 'string' ? body.downloadUrl : null;
        const bucket = typeof body.bucket === 'string' ? body.bucket : undefined;
        if (!path) {
            throw new Error('Upload response missing path');
        }

        return {
            path,
            fullPath: path,
            downloadUrl,
            bucket,
        };
    },

    async getSignedUrl(path: string): Promise<string | null> {
        const category = path.replace(/^\/+/, '').split('/')[1] ?? '';
        if (WORK_LOCAL_UPLOAD_CATEGORIES.has(category) && !isLawyerWorkCloudLive()) {
            return null;
        }
        try {
            const res = await SecureAPIClient.fetchSecure<{ ok: boolean; downloadUrl?: string }>(
                '/api/upload/signed-url',
                {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({ path }),
                },
            );
            return res?.downloadUrl?.trim() || null;
        } catch {
            return null;
        }
    },
};

import SecureStoreService from '@/app/services/SecureStoreService';

function isEmptyJsonCollection(raw: string): boolean {
    const trimmed = raw.trim();
    if (trimmed === '' || trimmed === '[]' || trimmed === '{}') return true;
    try {
        const parsed: unknown = JSON.parse(trimmed);
        if (Array.isArray(parsed)) return parsed.length === 0;
        if (parsed && typeof parsed === 'object') return Object.keys(parsed as object).length === 0;
    } catch {
        return false;
    }
    return false;
}

/** يمحو مرآة localStorage على نفس مفتاح SecureStore — لا تُكتب بعد اليوم. */
export function clearLegacyPlaintextMirror(key: string): void {
    if (typeof localStorage === 'undefined') return;
    try {
        localStorage.removeItem(key);
    } catch {
        /* ignore */
    }
}

/**
 * كتابة متزامنة في SecureStore ثم محو مرآة localStorage على نفس المفتاح.
 * حارس المسح قد يرفض التفريغ — عندها يبقى الأصل في الكاش.
 */
export function writeSecureAndClearLegacySync(key: string, payload: string): void {
    try {
        SecureStoreService.setItemSync(key, payload);
    } catch {
        /* الحارس أو التشفير رفض — لا تُمحى مرآة leftover فوق فشل الكتابة */
        return;
    }
    clearLegacyPlaintextMirror(key);
}

/**
 * كتابة القرص بعد أن يفتح IndexedDB هذا المفتاح — بلا مهلة تُحسب نجاحاً
 * وبلا انتظار تسخين كل المفاتيح المحمية (`ensurePersistedReady`).
 * `getItem`/`setItem` ينتظران البنية التحتية فقط.
 * `skipIfUnchanged: false` بعد `setItemSync` — وإلا تُتخطى كتابة IndexedDB.
 */
export async function persistSecurePayloadWhenReady(
    key: string,
    payload: string,
    options?: { skipIfUnchanged?: boolean },
): Promise<void> {
    if (options?.skipIfUnchanged !== false) {
        const existing = await SecureStoreService.getItem(key);
        if (existing === payload) {
            clearLegacyPlaintextMirror(key);
            return;
        }
    }
    await SecureStoreService.setItem(key, payload);
    clearLegacyPlaintextMirror(key);
}

/**
 * قراءة بعد فشل المرآة المتزامنة. `getItem` يفتح البنية ويفكّ هذا المفتاح فقط.
 */
export async function readSecurePayloadWhenReady(key: string): Promise<string | null> {
    const drained = readSecureOrDrainLegacySync(key);
    if (drained != null) return drained;
    const raw = await SecureStoreService.getItem(key);
    if (raw != null) clearLegacyPlaintextMirror(key);
    return raw;
}

/**
 * قراءة أول طلاء: كاش SecureStore ثم leftover في localStorage.
 * لا ترحيل ولا setItemSync — التشفير على مسار الجرس/الشبكة يجمّد الإطار الأول.
 * أصل unread لا يُسمَّم leftover.
 */
export function peekSecureOrLegacySync(key: string): string | null {
    try {
        const fromSecure = SecureStoreService.getItemSync(key);
        if (fromSecure != null) return fromSecure;
    } catch {
        /* fall through */
    }
    try {
        if (SecureStoreService.isUnreadSync(key)) return null;
    } catch {
        /* fall through to leftover peek */
    }
    if (typeof localStorage === 'undefined') return null;
    try {
        return localStorage.getItem(key);
    } catch {
        return null;
    }
}

/**
 * قراءة متزامنة: الكاش المشفّر أولاً، ثم ترحيل مرآة صريحة قديمة ومَحوها.
 *
 * إن وُجد الأصل في SecureStore تُمحى المرآة أيضاً — بذرة E2E أو نسخة قديمة
 * لا تُترك نصاً صريحاً بعد أن صار المخزن المعياري مشفَّراً.
 *
 * مصفوفة/كائن فارغ في المرآة لا يُرحَّل — كان ذلك مسار تظليل حارس المسح.
 *
 * أصل مشفَّر لم يُفكّ بعد: لا تُرحَّل المرآة فوقه. بعد التسخين تُمحى المرآة
 * لأن getItemSync يصيب الكاش.
 *
 * لا تُستدعَ على مسار أول طلاء (جرس/شارة/ملف شخصي للكاش الدافئ) — استخدم
 * `peekSecureOrLegacySync`. الترحيل للتحميل غير المتزامن بعد التفاعل.
 */
export function readSecureOrDrainLegacySync(key: string): string | null {
    try {
        const fromSecure = SecureStoreService.getItemSync(key);
        if (fromSecure != null) {
            clearLegacyPlaintextMirror(key);
            return fromSecure;
        }
    } catch {
        /* fall through */
    }
    try {
        if (SecureStoreService.isUnreadSync(key)) return null;
    } catch {
        /* fall through to leftover drain */
    }
    if (typeof localStorage === 'undefined') return null;
    try {
        const raw = localStorage.getItem(key);
        if (raw === null) return null;
        localStorage.removeItem(key);
        if (isEmptyJsonCollection(raw)) return null;
        try {
            SecureStoreService.setItemSync(key, raw);
        } catch {
            /* القيمة المُعادة تكفي هذه القراءة */
        }
        return raw;
    } catch {
        return null;
    }
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import { isLawyerWorkCloudLive } from '@/app/services/settings/lawyerWorkCloudGate';
import { isVaultIdbStoragePath } from '@/app/services/vault/vaultBlobPathLite';

export function isRemoteStorageObjectPath(path: string): boolean {
    const p = path.trim();
    if (!p) return false;
    if (p.startsWith('idb:') || p.startsWith('local:')) return false;
    if (isVaultIdbStoragePath(p)) return false;
    return true;
}

/** حذف كائن تخزين سحابي — لا شبكة إن مزامنة العمل مطفأة */
export async function removeRemoteStoragePathsBestEffort(paths: string[]): Promise<void> {
    if (!isLawyerWorkCloudLive()) return;
    const toRemove = [...new Set(paths.map((p) => p.trim()).filter(isRemoteStorageObjectPath))];
    if (toRemove.length === 0) return;
    try {
        await SecureAPIClient.fetchSecure('/api/upload/remove', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ paths: toRemove }),
        });
    } catch {
        console.warn('[LawyerStorage] فشل حذف ملف(ات) من المخزن:', toRemove.join(', '));
    }
}

/** أخطاء تشفير/كتابة القرص — ورقة بلا SecureStore حتى لا يسحبها مسار المعاملات إلى الإقلاع. */
export class StorageEncryptionError extends Error {
    constructor(key: string, cause?: unknown) {
        super(`Refused to persist sensitive key "${key}" without encryption`);
        this.name = 'StorageEncryptionError';
        if (cause !== undefined) (this as { cause?: unknown }).cause = cause;
    }
}

export class StoragePersistenceError extends Error {
    constructor(key: string, cause?: unknown) {
        super(`Failed to persist key "${key}" to IndexedDB`);
        this.name = 'StoragePersistenceError';
        if (cause !== undefined) (this as { cause?: unknown }).cause = cause;
    }
}

import SecureStoreService from '@/app/services/SecureStoreService';
import {
    clearLegacyPlaintextMirror,
    persistSecurePayloadWhenReady,
    readSecureOrDrainLegacySync,
    readSecurePayloadWhenReady,
    writeSecureAndClearLegacySync,
} from '@/app/services/storage/readSecureOrDrainLegacySync';

/** كتابة متزامنة مشفّرة ثم محو المرآة، مع انتظار IndexedDB في الخلفية. */
export function writeSecureJsonValue(key: string, value: unknown): void {
    const payload = JSON.stringify(value);
    writeSecureAndClearLegacySync(key, payload);
    if (import.meta.env.VITEST) return;
    void persistSecurePayloadWhenReady(key, payload);
}

/** يمحو المفتاح من SecureStore ومرآة localStorage. */
export function clearSecureJsonValue(key: string): void {
    try {
        SecureStoreService.deleteItemSync(key);
    } catch {
        /* ignore */
    }
    clearLegacyPlaintextMirror(key);
}

export function readSecureJsonRawSync(key: string): string | null {
    return readSecureOrDrainLegacySync(key);
}

export async function readSecureJsonRaw(key: string): Promise<string | null> {
    return readSecurePayloadWhenReady(key);
}

export async function persistSecureJsonValue(key: string, value: unknown): Promise<void> {
    const payload = JSON.stringify(value);
    writeSecureAndClearLegacySync(key, payload);
    if (import.meta.env.VITEST) return;
    await persistSecurePayloadWhenReady(key, payload);
}

