import { SecureAPIClient, SecureFetchError } from '@/app/services/SecureAPIClient';
import type { ShareScope, TaskHelpRequest } from '@/app/types/taskHelpTypes';
import { TaskHelpRepository } from './taskHelpRepository';
import { assertRecipientInNetwork } from '@/app/services/caseShare/caseShareNetworkGuard';
import { canReachCollaborationNetwork } from '@/app/services/settings/collaborationNetworkGate';

type ApiOk<T> = { ok: true } & T;

/** طلب العون شبكة تعاون صريحة — لا يُستدعى عند قطع الاتصال، ولا ينتظر مزامنة الإضابير */
export function canReachTaskHelpNetwork(): boolean {
    return canReachCollaborationNetwork();
}

async function postJson<T>(path: string, body: Record<string, unknown>): Promise<T> {
    return SecureAPIClient.fetchSecure<T>(path, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
    });
}

function rethrowAuthoritativeApiError(err: unknown): never | void {
    if (!(err instanceof SecureFetchError)) return;
    // لا نسمح بالسقوط المحلي بعد رفض خادم موثوق (قفل/صلاحية)
    if (err.status === 403 || err.status === 404 || err.status === 409) {
        let code = 'API_REJECTED';
        try {
            const parsed = JSON.parse(err.bodyText) as { code?: string };
            if (typeof parsed.code === 'string' && parsed.code) code = parsed.code;
        } catch {
            /* ignore */
        }
        throw Object.assign(new Error(code), { code, status: err.status });
    }
}

export class TaskHelpApiService {
    static async list(userId: string): Promise<TaskHelpRequest[]> {
        if (canReachTaskHelpNetwork()) {
            try {
                const res = await SecureAPIClient.fetchSecure<ApiOk<{ requests: TaskHelpRequest[] }>>(
                    '/api/task-help/list',
                    { method: 'GET' },
                );
                if (Array.isArray(res.requests)) return res.requests;
            } catch {
                /* local fallback */
            }
        }
        return TaskHelpRepository.listForUser(userId);
    }

    static async create(params: {
        sourceTaskId: string;
        requesterId: string;
        requesterName?: string;
        shareScope: ShareScope;
        title: string;
        location?: string | null;
        dueDate?: string | null;
        instructions?: string;
        isSanitised: boolean;
        targetColleagueId?: string;
        targetColleagueName?: string;
        forumPostId?: string | null;
        note?: string;
    }): Promise<TaskHelpRequest> {
        if (
            canReachTaskHelpNetwork() &&
            params.shareScope === 'PRIVATE_DIRECT' &&
            params.targetColleagueId
        ) {
            const inNetwork = await assertRecipientInNetwork(
                params.requesterId,
                params.targetColleagueId,
            );
            if (!inNetwork) throw new Error('RECIPIENT_NOT_IN_NETWORK');
        }
        if (canReachTaskHelpNetwork()) {
            try {
                const res = await postJson<ApiOk<{ request: TaskHelpRequest }>>('/api/task-help/create', {
                    ...params,
                });
                if (res.request) return res.request;
            } catch (err) {
                rethrowAuthoritativeApiError(err);
            }
        }
        return TaskHelpRepository.create(params);
    }

    static async accept(
        helpRequestId: string,
        colleagueId: string,
        colleagueName?: string,
    ): Promise<TaskHelpRequest> {
        if (canReachTaskHelpNetwork()) {
            try {
                const res = await postJson<ApiOk<{ request: TaskHelpRequest }>>('/api/task-help/accept', {
                    helpRequestId,
                    colleagueName,
                });
                if (res.request) return res.request;
                throw new Error('ACCEPT_FAILED');
            } catch (err) {
                rethrowAuthoritativeApiError(err);
            }
        }
        const local = await TaskHelpRepository.accept(helpRequestId, colleagueId, colleagueName);
        if (local.ok === false) {
            const { code } = local;
            throw Object.assign(new Error(code), { code });
        }
        return local.request;
    }

    static async addNote(
        helpRequestId: string,
        authorId: string,
        text: string,
        authorName?: string,
    ): Promise<TaskHelpRequest> {
        if (canReachTaskHelpNetwork()) {
            try {
                const res = await postJson<ApiOk<{ request: TaskHelpRequest }>>('/api/task-help/note', {
                    helpRequestId,
                    text,
                    authorName,
                });
                if (res.request) return res.request;
            } catch (err) {
                rethrowAuthoritativeApiError(err);
            }
        }
        const updated = await TaskHelpRepository.addNote(helpRequestId, authorId, text, authorName);
        if (!updated) throw new Error('NOTE_FAILED');
        return updated;
    }

    static async markHelperDone(helpRequestId: string, actorId: string): Promise<TaskHelpRequest> {
        return this.complete(helpRequestId, actorId, 'helper_done');
    }

    static async confirmOwnerReview(helpRequestId: string, actorId: string): Promise<TaskHelpRequest> {
        return this.complete(helpRequestId, actorId, 'owner_confirm');
    }

    private static async complete(
        helpRequestId: string,
        actorId: string,
        mode: 'helper_done' | 'owner_confirm',
    ): Promise<TaskHelpRequest> {
        if (canReachTaskHelpNetwork()) {
            try {
                const res = await postJson<ApiOk<{ request: TaskHelpRequest }>>(
                    '/api/task-help/complete',
                    { helpRequestId, mode },
                );
                if (res.request) return res.request;
            } catch (err) {
                rethrowAuthoritativeApiError(err);
            }
        }
        const result = await TaskHelpRepository.complete(helpRequestId, actorId, mode);
        if (result.ok === false) {
            const { code } = result;
            throw Object.assign(new Error(code), { code });
        }
        return result.request;
    }

    static async attachForumPost(
        helpRequestId: string,
        requesterId: string,
        forumPostId: string,
    ): Promise<TaskHelpRequest | null> {
        return TaskHelpRepository.attachForumPost(helpRequestId, requesterId, forumPostId);
    }
}

import type { TaskHelpRequest } from '@/app/types/taskHelpTypes';
import { persistSecureJsonValue, readSecureJsonRaw } from '@/app/services/storage/syncSecureJson';

const STORAGE_KEY = 'hami_task_help_requests_v1';

export async function loadTaskHelpRecords(): Promise<TaskHelpRequest[]> {
    try {
        const raw = await readSecureJsonRaw(STORAGE_KEY);
        if (!raw?.trim()) return [];
        const parsed: unknown = JSON.parse(raw);
        if (!Array.isArray(parsed)) return [];
        return parsed.filter(
            (r) => r && typeof r === 'object' && typeof (r as TaskHelpRequest).id === 'string',
        ) as TaskHelpRequest[];
    } catch {
        return [];
    }
}

export async function saveTaskHelpRecords(rows: TaskHelpRequest[]): Promise<void> {
    await persistSecureJsonValue(STORAGE_KEY, rows);
}

import type {
    CollaborationStatus,
    SharedTaskNote,
    ShareScope,
    TaskHelpRequest,
} from '@/app/types/taskHelpTypes';
import { loadTaskHelpRecords, saveTaskHelpRecords } from './taskHelpLocalStore';

const MAX_SHARED_NOTES = 50;

type KvAdmin = {
    kvSet: (key: string, value: unknown) => Promise<void>;
    kvGet: (key: string) => Promise<unknown>;
    kvDel: (key: string) => Promise<void>;
    kvGetByPrefix: (prefix: string) => Promise<unknown[]>;
};

/** لا يسحب Vite kvStoreAdmin إلى حزمة العميل (@vite-ignore + حارس window). */
async function loadKvAdmin(): Promise<KvAdmin | null> {
    if (typeof window !== 'undefined') return null;
    const spec = '@/app/api/security/kvStoreAdmin.ts';
    return import(/* @vite-ignore */ spec) as Promise<KvAdmin>;
}

function createId(): string {
    const c = globalThis.crypto as Crypto | undefined;
    if (c?.randomUUID) return c.randomUUID();
    return `thr_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

async function serverKvSet(key: string, value: unknown): Promise<void> {
    try {
        const kv = await loadKvAdmin();
        if (!kv) return;
        await kv.kvSet(key, value);
    } catch {
        /* silent */
    }
}

async function serverKvDel(key: string): Promise<void> {
    try {
        const kv = await loadKvAdmin();
        if (!kv) return;
        await kv.kvDel(key);
    } catch {
        /* silent */
    }
}

async function serverKvGet(key: string): Promise<unknown> {
    try {
        const kv = await loadKvAdmin();
        if (!kv) return null;
        return kv.kvGet(key);
    } catch {
        return null;
    }
}

async function serverKvGetByPrefix(prefix: string): Promise<unknown[]> {
    try {
        const kv = await loadKvAdmin();
        if (!kv) return [];
        const res = await kv.kvGetByPrefix(prefix);
        return Array.isArray(res) ? res : [];
    } catch {
        return [];
    }
}

async function persistRecord(record: TaskHelpRequest): Promise<void> {
    const rows = await loadTaskHelpRecords();
    const next = [record, ...rows.filter((r) => r.id !== record.id)];
    await saveTaskHelpRecords(next);
    await serverKvSet(`task_help:${record.id}`, record);
    await serverKvSet(`task_help:requester:${record.requesterId}:${record.id}`, record.id);
    if (record.targetColleagueId) {
        await serverKvSet(`task_help:recipient:${record.targetColleagueId}:${record.id}`, record.id);
    }
    if (record.assigneeId) {
        await serverKvSet(`task_help:assignee:${record.assigneeId}:${record.id}`, record.id);
    }
    const openKey = `task_help:open:${record.id}`;
    if (record.shareScope === 'PUBLIC_FORUM' && record.collaborationStatus === 'PENDING') {
        await serverKvSet(openKey, record.id);
    } else {
        // يمنع تضخّم فهرس الطلبات العامة المفتوحة بعد القبول/الإكمال
        await serverKvDel(openKey);
    }
}

async function loadRecordById(id: string): Promise<TaskHelpRequest | null> {
    const rows = await loadTaskHelpRecords();
    const localHit = rows.find((r) => r.id === id);
    if (localHit) return localHit;
    const raw = await serverKvGet(`task_help:${id}`);
    if (raw && typeof raw === 'object') return raw as TaskHelpRequest;
    return null;
}

async function collectIdsForUser(userId: string): Promise<Set<string>> {
    const ids = new Set<string>();
    const prefixes = [
        `task_help:requester:${userId}:`,
        `task_help:recipient:${userId}:`,
        `task_help:assignee:${userId}:`,
    ];
    for (const prefix of prefixes) {
        for (const row of await serverKvGetByPrefix(prefix)) {
            if (typeof row === 'string') ids.add(row);
        }
    }
    const openIds = await serverKvGetByPrefix('task_help:open:');
    for (const row of openIds) {
        if (typeof row === 'string') ids.add(row);
    }
    return ids;
}

function canView(record: TaskHelpRequest, userId: string): boolean {
    if (record.requesterId === userId) return true;
    if (record.assigneeId === userId) return true;
    if (record.targetColleagueId === userId) return true;
    if (record.shareScope === 'PUBLIC_FORUM' && record.collaborationStatus === 'PENDING') return true;
    return false;
}

type CreateTaskHelpParams = {
    sourceTaskId: string;
    requesterId: string;
    requesterName?: string;
    shareScope: ShareScope;
    title: string;
    location?: string | null;
    dueDate?: string | null;
    instructions?: string;
    isSanitised: boolean;
    targetColleagueId?: string;
    targetColleagueName?: string;
    forumPostId?: string | null;
};

export const TaskHelpRepository = {
    async create(params: CreateTaskHelpParams): Promise<TaskHelpRequest> {
        const now = new Date().toISOString();
        const record: TaskHelpRequest = {
            id: createId(),
            sourceTaskId: params.sourceTaskId,
            requesterId: params.requesterId,
            requesterName: params.requesterName,
            shareScope: params.shareScope,
            collaborationStatus: 'PENDING',
            isSanitised: params.isSanitised,
            title: params.title,
            location: params.location ?? null,
            dueDate: params.dueDate ?? null,
            instructions: params.instructions,
            targetColleagueId: params.targetColleagueId,
            targetColleagueName: params.targetColleagueName,
            forumPostId: params.forumPostId ?? null,
            sharedNotes: [],
            createdAt: now,
            updatedAt: now,
        };
        await persistRecord(record);
        return record;
    },

    async getById(id: string, requesterId: string): Promise<TaskHelpRequest | null> {
        const existing = await loadRecordById(id);
        if (!existing || !canView(existing, requesterId)) return null;
        return existing;
    },

    async listForUser(userId: string): Promise<TaskHelpRequest[]> {
        const local = await loadTaskHelpRecords();
        const ids = await collectIdsForUser(userId);
        const map = new Map<string, TaskHelpRequest>();
        for (const r of local) {
            if (canView(r, userId)) map.set(r.id, r);
        }
        for (const id of ids) {
            if (map.has(id)) continue;
            const raw = await serverKvGet(`task_help:${id}`);
            if (raw && typeof raw === 'object') {
                const rec = raw as TaskHelpRequest;
                if (canView(rec, userId)) map.set(rec.id, rec);
            }
        }
        return [...map.values()].sort((a, b) => Date.parse(b.createdAt) - Date.parse(a.createdAt));
    },

    /**
     * قفل قبول ذري: فقط إن كانت الحالة PENDING.
     * ملاحظة: بدون CAS على KV يبقى سباق نادر تحت حمل عالٍ.
     */
    async accept(id: string, colleagueId: string, colleagueName?: string): Promise<
        | { ok: true; request: TaskHelpRequest }
        | { ok: false; code: 'NOT_FOUND' | 'ALREADY_ACCEPTED' | 'FORBIDDEN' }
    > {
        const existing = await loadRecordById(id);
        if (!existing) return { ok: false, code: 'NOT_FOUND' };
        if (existing.requesterId === colleagueId) return { ok: false, code: 'FORBIDDEN' };
        if (existing.shareScope === 'PRIVATE_DIRECT' && existing.targetColleagueId !== colleagueId) {
            return { ok: false, code: 'FORBIDDEN' };
        }
        if (existing.collaborationStatus !== 'PENDING') {
            return { ok: false, code: 'ALREADY_ACCEPTED' };
        }
        const now = new Date().toISOString();
        const updated: TaskHelpRequest = {
            ...existing,
            assigneeId: colleagueId,
            assigneeName: colleagueName,
            collaborationStatus: 'ACCEPTED',
            updatedAt: now,
        };
        await persistRecord(updated);
        return { ok: true, request: updated };
    },

    async addNote(
        id: string,
        authorId: string,
        text: string,
        authorName?: string,
    ): Promise<TaskHelpRequest | null> {
        const existing = await loadRecordById(id);
        if (!existing) return null;
        const isParty = existing.requesterId === authorId || existing.assigneeId === authorId;
        if (!isParty) return null;
        if (
            existing.collaborationStatus !== 'ACCEPTED' &&
            existing.collaborationStatus !== 'AWAITING_OWNER_REVIEW'
        ) {
            return null;
        }
        const note: SharedTaskNote = {
            id: createId(),
            authorId,
            authorName,
            text: text.trim().slice(0, 2000),
            timestamp: new Date().toISOString(),
        };
        if (!note.text) return null;
        const nextNotes = [...existing.sharedNotes, note].slice(-MAX_SHARED_NOTES);
        const updated: TaskHelpRequest = {
            ...existing,
            sharedNotes: nextNotes,
            updatedAt: note.timestamp,
        };
        await persistRecord(updated);
        return updated;
    },

    async complete(
        id: string,
        actorId: string,
        mode: 'helper_done' | 'owner_confirm',
    ): Promise<
        | { ok: true; request: TaskHelpRequest }
        | { ok: false; code: 'NOT_FOUND' | 'FORBIDDEN' | 'INVALID_STATE' }
    > {
        const existing = await loadRecordById(id);
        if (!existing) return { ok: false, code: 'NOT_FOUND' };
        const now = new Date().toISOString();

        if (mode === 'helper_done') {
            if (existing.assigneeId !== actorId) return { ok: false, code: 'FORBIDDEN' };
            if (existing.collaborationStatus !== 'ACCEPTED') {
                return { ok: false, code: 'INVALID_STATE' };
            }
            const updated: TaskHelpRequest = {
                ...existing,
                collaborationStatus: 'AWAITING_OWNER_REVIEW',
                updatedAt: now,
            };
            await persistRecord(updated);
            return { ok: true, request: updated };
        }

        if (existing.requesterId !== actorId) return { ok: false, code: 'FORBIDDEN' };
        if (existing.collaborationStatus !== 'AWAITING_OWNER_REVIEW') {
            return { ok: false, code: 'INVALID_STATE' };
        }
        const updated: TaskHelpRequest = {
            ...existing,
            collaborationStatus: 'COMPLETED' satisfies CollaborationStatus,
            updatedAt: now,
        };
        await persistRecord(updated);
        return { ok: true, request: updated };
    },

    async attachForumPost(id: string, requesterId: string, forumPostId: string): Promise<TaskHelpRequest | null> {
        const existing = await loadRecordById(id);
        if (!existing || existing.requesterId !== requesterId) return null;
        const updated: TaskHelpRequest = {
            ...existing,
            forumPostId,
            updatedAt: new Date().toISOString(),
        };
        await persistRecord(updated);
        return updated;
    },
};

/**
 * سيناريوهات تشغيل محلية لميزة طلب المساعدة — بدون شبكة حية.
 * تُستخدم في الاختبارات للتحقق من مسار العمل الكامل.
 */
import type { LegalTask } from '@/app/types/TaskEngine';
import type { TaskHelpRequest } from '@/app/types/taskHelpTypes';
import { sanitizeTaskForPublic } from '@/app/services/tasks/taskSanitizer';
import { TaskHelpRepository } from '@/app/services/taskHelp/taskHelpRepository';

type ScenarioActor = { id: string; name: string };

type HelpLifecycleResult = {
    request: TaskHelpRequest;
    publicTitle?: string;
    secondAcceptCode?: string;
    strangerNoteOk: boolean;
    notesCount: number;
};

/** سيناريو: طلب عام → قبول أول زميل → رفض الثاني → ملاحظات → إنجاز → تأكيد مالك */
export async function runPublicHelpLifecycleScenario(params: {
    owner: ScenarioActor;
    helperA: ScenarioActor;
    helperB: ScenarioActor;
    stranger: ScenarioActor;
    task: LegalTask;
}): Promise<HelpLifecycleResult> {
    const sanitized = sanitizeTaskForPublic(params.task);
    const created = await TaskHelpRepository.create({
        sourceTaskId: params.task.id,
        requesterId: params.owner.id,
        requesterName: params.owner.name,
        shareScope: 'PUBLIC_FORUM',
        title: sanitized.title,
        location: sanitized.location,
        dueDate: sanitized.dueDate,
        instructions: sanitized.instructions,
        isSanitised: true,
    });

    const first = await TaskHelpRepository.accept(created.id, params.helperA.id, params.helperA.name);
    if (first.ok === false) throw new Error(`expected first accept ok, got ${first.code}`);

    const second = await TaskHelpRepository.accept(created.id, params.helperB.id, params.helperB.name);
    const secondAcceptCode = second.ok === false ? second.code : undefined;

    const strangerNote = await TaskHelpRepository.addNote(
        created.id,
        params.stranger.id,
        'ملاحظة دخيل',
        params.stranger.name,
    );

    const ownerNote = await TaskHelpRepository.addNote(
        created.id,
        params.owner.id,
        'شكراً على القبول',
        params.owner.name,
    );
    const helperNote = await TaskHelpRepository.addNote(
        created.id,
        params.helperA.id,
        'حضرت الجلسة',
        params.helperA.name,
    );
    if (!ownerNote || !helperNote) throw new Error('party notes should succeed');

    const done = await TaskHelpRepository.complete(created.id, params.helperA.id, 'helper_done');
    if (done.ok === false) throw new Error(`helper_done failed: ${done.code}`);

    const confirmed = await TaskHelpRepository.complete(created.id, params.owner.id, 'owner_confirm');
    if (confirmed.ok === false) throw new Error(`owner_confirm failed: ${confirmed.code}`);

    return {
        request: confirmed.request,
        publicTitle: sanitized.title,
        secondAcceptCode,
        strangerNoteOk: strangerNote != null,
        notesCount: confirmed.request.sharedNotes.length,
    };
}

/** سيناريو: طلب خاص — فقط الزميل المستهدف يقبل */
export async function runPrivateDirectLockScenario(params: {
    owner: ScenarioActor;
    target: ScenarioActor;
    other: ScenarioActor;
    taskId: string;
}): Promise<{ acceptedByTarget: boolean; otherCode?: string; finalStatus: string }> {
    const created = await TaskHelpRepository.create({
        sourceTaskId: params.taskId,
