import type { LegalTask } from '@/app/types/TaskEngine';
import { isTaskOnFieldCurtain } from '@/app/utils/fieldCurtain';
import {
    isTaskDayOverdueIncomplete,
    isTaskInCurrentAgendaWeek,
    isTaskMarkedDone,
} from '@/app/services/tasks/taskAgendaStatusLite';

/**
 * أهلية/عدّاد ستارة الميدان لمسار metrics البارد —
 * بلا tasksManager/utils أو calendarAuthenticity أو جسر التقويم.
 */
function dateToLocalYmd(d: Date): string {
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    return `${y}-${m}-${day}`;
}

function hasExplicitUserDate(task: LegalTask): boolean {
    if (task.status !== 'pending') return false;
    if (task.reminderAt && !Number.isNaN(task.reminderAt.getTime())) return true;
    if (task.parsedDate && !Number.isNaN(task.parsedDate.getTime())) return true;
    return false;
}

/** استحقاق محلي YYYY-MM-DD — بلا UTC/ISO */
export function fieldDaySheetDueYmdLite(task: LegalTask): string | null {
    if (!hasExplicitUserDate(task)) return null;
    if (task.reminderAt && !Number.isNaN(task.reminderAt.getTime())) {
        return dateToLocalYmd(task.reminderAt);
    }
    if (task.parsedDate && !Number.isNaN(task.parsedDate.getTime())) {
        return dateToLocalYmd(task.parsedDate);
    }
    return null;
}

/** نفس قاعدة ستارة «مهام اليوم» — بلا فرز أو تخصيص مصفوفة */
export function isEligibleFieldDaySheetTaskLite(task: LegalTask, now: Date): boolean {
    if (task.status !== 'pending' && task.status !== 'delegated') return false;
    if (isTaskMarkedDone(task)) return false;
    if (isTaskOnFieldCurtain(task)) return true;
    /** الحتمي يظهر إن استحق اليوم أو تأخّر — التثبيت اليدوي يبقى للأجندة */
    const todayYmd = dateToLocalYmd(now);
    if (task.parsedDate && isTaskInCurrentAgendaWeek(task, now)) {
        const weekDue = fieldDaySheetDueYmdLite(task);
        if (weekDue && weekDue <= todayYmd) return true;
    }
    if (isTaskDayOverdueIncomplete(task, now)) return true;
    const ymd = fieldDaySheetDueYmdLite(task);
    if (!ymd) return false;
    return ymd === todayYmd;
}

export function countFieldDaySheetTasksLite(tasks: LegalTask[], now = new Date()): number {
    let n = 0;
    for (const task of tasks) {
        if (isEligibleFieldDaySheetTaskLite(task, now)) n += 1;
    }
    return n;
}

import type { LegalTask } from '@/app/types/TaskEngine';
import {
    fieldDaySheetDueYmdLite,
    isEligibleFieldDaySheetTaskLite,
} from '@/app/services/tasks/fieldCurtainDayCountLite';

export function listFieldDaySheetTasks(tasks: LegalTask[], now = new Date()): LegalTask[] {
    return sortFieldCurtainTasks(tasks.filter((t) => isEligibleFieldDaySheetTaskLite(t, now)));
}

export function sortFieldCurtainTasks(tasks: LegalTask[]): LegalTask[] {
    return [...tasks].sort((a, b) => {
        if (a.isFatalDeadline !== b.isFatalDeadline) {
            return a.isFatalDeadline ? -1 : 1;
        }
        if (a.pinnedToFieldCurtain !== b.pinnedToFieldCurtain) {
            return a.pinnedToFieldCurtain ? -1 : 1;
        }
        const aPin = a.fieldCurtainPinnedAt?.getTime() ?? 0;
        const bPin = b.fieldCurtainPinnedAt?.getTime() ?? 0;
        if (aPin !== bPin) return bPin - aPin;
        const aDue = fieldDaySheetDueYmdLite(a) ?? '';
        const bDue = fieldDaySheetDueYmdLite(b) ?? '';
        if (aDue !== bDue) return aDue.localeCompare(bDue);
        return a.title.localeCompare(b.title, 'ar');
    });
}

import type { LegalTask } from '@/app/types/TaskEngine';

/** حقول الصوت الفارغة — مصدر واحد لمسارات الإنشاء */
export const EMPTY_TASK_VOICE = {
    voiceRef: null,
    voiceTranscript: null,
    voiceDurationSec: null,
} as const;

export function newTaskId(): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
        return crypto.randomUUID();
    }
    return `qt-${Date.now()}-${Math.random().toString(36).slice(2, 11)}`;
}

type PendingTaskShell = Pick<
    LegalTask,
    | 'status'
    | 'completedAt'
    | 'pinnedToFieldCurtain'
    | 'fieldCurtainPinnedAt'
    | 'subTasks'
    | 'documentRequirements'
    | 'expenses'
    | 'voiceRef'
    | 'voiceTranscript'
    | 'voiceDurationSec'
>;

/** صدفة مهمة معلّقة — المتداخلات والصوت فارغة ما لم يُمرَّر خلاف ذلك */
export function pendingTaskShell(overrides?: Partial<PendingTaskShell>): PendingTaskShell {
    return {
        status: 'pending',
        completedAt: null,
        pinnedToFieldCurtain: false,
        fieldCurtainPinnedAt: null,
        subTasks: [],
        documentRequirements: [],
        expenses: [],
        ...EMPTY_TASK_VOICE,
        ...overrides,
    };
}

import type { LegalSubTask, LegalTask } from '@/app/types/TaskEngine';
import { parseTaskInput, startOfLocalDay } from '@/app/utils/nlpParser';
import {
    applySilentPracticalEnrichment,
    type TaskEnrichmentOptions,
} from '@/app/utils/quantumTaskEnrichment';
import {
    clampTaskText,
    MAX_NESTED_ITEMS,
    MAX_TASK_LINE_LENGTH,
    MAX_TASK_LOCATION_LENGTH,
    MAX_TASK_RAW_LENGTH,
    MAX_TASK_TITLE_LENGTH,
} from '@/app/services/tasks/taskInputGuard';
import { newTaskId, pendingTaskShell } from '@/app/services/tasks/quantumPendingTaskFactory';

export type { TaskEnrichmentOptions };

/** يبني مهمة معلّقة من نص خام — بدون إلحاق بالقائمة */
export function buildPendingTaskFromRaw(
    rawText: string,
    options?: TaskEnrichmentOptions,
): LegalTask | null {
    const trimmed = String(rawText ?? '').trim();
    if (!trimmed || trimmed.length > MAX_TASK_RAW_LENGTH) return null;

    const parsed = parseTaskInput(trimmed);
    const enriched = applySilentPracticalEnrichment(trimmed, parsed, options);
    return {
        id: newTaskId(),
        ...enriched,
        linkedCaseId: enriched.linkedCaseId ?? null,
        reminderAt: null,
        ...pendingTaskShell(),
    };
}

/** حزمة موقع أسبوعية: تفاصيل نصية أو إجراءات فرعية ميدانية */
export function buildWeeklyLocationBundleTask(
    scheduledFor: Date,
    location: string,
    mainTitleOrActions: string | string[],
    legacyMainTitle?: string,
): LegalTask | null {
    const loc = clampTaskText(location, MAX_TASK_LOCATION_LENGTH);
    let details = '';
    let actionTitles: string[] = [];

    if (typeof mainTitleOrActions === 'string') {
        details = clampTaskText(mainTitleOrActions, MAX_TASK_TITLE_LENGTH);
    } else {
        actionTitles = mainTitleOrActions
            .map((x) => clampTaskText(x, MAX_TASK_LINE_LENGTH))
            .filter((x) => x.length > 0)
            .slice(0, MAX_NESTED_ITEMS);
        details = clampTaskText(legacyMainTitle ?? '', MAX_TASK_TITLE_LENGTH);
    }

    if (!details && actionTitles.length === 0 && !loc) return null;

    const day = startOfLocalDay(scheduledFor);
    const parentTitle = details || actionTitles[0] || loc;
    const extraTitles = details ? actionTitles : actionTitles.slice(1);
    const subTasks: LegalSubTask[] = extraTitles.map((title) => ({
        id: newTaskId(),
        title,
        location: null,
        isCompleted: false,
        kind: details ? 'branch' : 'field',
        planStatus: 'pending' as const,
    }));

    return {
        id: newTaskId(),
        rawText: clampTaskText(
            [loc, parentTitle, ...extraTitles].filter(Boolean).join(' — '),
            MAX_TASK_RAW_LENGTH,
        ),
        title: parentTitle,
        location: loc || null,
        parsedDate: new Date(day.getTime()),
        reminderAt: null,
        isFatalDeadline: false,
        linkedCaseId: null,
        ...pendingTaskShell({ subTasks }),
    };
}

/** مهمة مؤجلة للتذكير — بلا تاريخ تنفيذ في الأجندة */
export function buildSnoozedBacklogTask(
    title: string,
    reminderAt: Date,
    location: string | null = null,
): LegalTask | null {
    const trimmed = title.trim();
    if (!trimmed || trimmed.length > MAX_TASK_RAW_LENGTH) return null;
    const parsed = parseTaskInput(trimmed);
    const enriched = applySilentPracticalEnrichment(trimmed, parsed);
    const remind = startOfLocalDay(reminderAt);
    const locRaw = location?.trim() ? location.trim() : enriched.location;
    const loc = locRaw ? clampTaskText(locRaw, MAX_TASK_LOCATION_LENGTH) || null : null;
    return {
        id: newTaskId(),
        rawText: trimmed,
        title: enriched.title || trimmed,
        location: loc,
        parsedDate: null,
        reminderAt: new Date(remind.getTime()),
        isFatalDeadline: enriched.isFatalDeadline,
        linkedCaseId: enriched.linkedCaseId,
        ...pendingTaskShell(),
    };
}

import type {
    buildPendingTaskFromRaw,
    buildSnoozedBacklogTask,
    buildWeeklyLocationBundleTask,
} from '@/app/services/tasks/quantumTaskCreateBuilders';

type CreateBuilders = {
    buildPendingTaskFromRaw: typeof buildPendingTaskFromRaw;
    buildWeeklyLocationBundleTask: typeof buildWeeklyLocationBundleTask;
    buildSnoozedBacklogTask: typeof buildSnoozedBacklogTask;
};

type VoiceAttach = typeof import('@/app/services/tasks/taskVoiceAttachment');
type Nlp = typeof import('@/app/utils/nlpParser');
type Enrich = typeof import('@/app/utils/quantumTaskEnrichment');
type Factory = typeof import('@/app/services/tasks/quantumPendingTaskFactory');

export type QuantumTaskCreateBundle = {
    builders: CreateBuilders;
    voice: VoiceAttach;
    nlp: Nlp;
    enrich: Enrich;
    factory: Factory;
};

let bundle: QuantumTaskCreateBundle | null = null;
let promise: Promise<QuantumTaskCreateBundle> | null = null;

export function peekQuantumTaskCreateBundle(): QuantumTaskCreateBundle | null {
    return bundle;
}

/** NLP / إنشاء المهام — يُحمَّل مع الأجندة لا مع ستارة الميدان */
export function loadQuantumTaskCreateBundle(): Promise<QuantumTaskCreateBundle> {
    if (!promise) {
        promise = Promise.all([
            import('@/app/services/tasks/quantumTaskCreateBuilders'),
            import('@/app/services/tasks/taskVoiceAttachment'),
            import('@/app/utils/nlpParser'),
            import('@/app/utils/quantumTaskEnrichment'),
