/**
 * إكمال / إعادة فتح / ترحيل / تثبيت — بلا nlpParser ولا prepareAgendaTasks.
 * مسار ستارة الميدان يستورد هذا الملف فقط.
 */
import type { LegalTask } from '@/app/types/TaskEngine';
import { addDays, startOfLocalDay } from '@/app/utils/localDay';
import { getSaturdayOfWeekContaining, isTaskMarkedDone } from '@/app/services/tasks/taskAgendaStatusLite';
import { WORK_WEEK_LAST_OFFSET } from '@/app/components/lawyer/dashboard/tasksManager/constants';

export function isTaskArchivedToHistory(task: LegalTask, now = new Date()): boolean {
    if (!task.parsedDate || task.isFatalDeadline) return false;
    const taskWeek = getSaturdayOfWeekContaining(task.parsedDate).getTime();
    const thisWeek = getSaturdayOfWeekContaining(now).getTime();
    return taskWeek < thisWeek;
}

/** إعادة فتح مهمة منتهية — الأرشيف يُعاد إلى اليوم حتى لا يُغلق الأسبوع السابق فوراً */
export function applyReopenTask(task: LegalTask, now = new Date()): LegalTask | null {
    if (!task.completedAt) return null;
    const archived = isTaskArchivedToHistory(task, now);
    const today = startOfLocalDay(now);
    return {
        ...task,
        completedAt: null,
        status: 'pending',
        parsedDate: archived ? today : task.parsedDate,
        reminderAt: archived ? null : task.reminderAt,
    };
}

export function releaseExpiredFieldCurtainPins(tasks: LegalTask[], _now = new Date()): LegalTask[] {
    return tasks.map((t) => {
        if (!t.pinnedToFieldCurtain) return t;
        if (isTaskMarkedDone(t)) {
            return { ...t, pinnedToFieldCurtain: false, fieldCurtainPinnedAt: null };
        }
        return t;
    });
}

function isDateInWorkWeekLite(date: Date, weekStartSaturday: Date): boolean {
    const start = startOfLocalDay(weekStartSaturday).getTime();
    const end = addDays(weekStartSaturday, WORK_WEEK_LAST_OFFSET).getTime();
    const t = startOfLocalDay(date).getTime();
    return t >= start && t <= end;
}

/** ترحيل مهمة إلى يوم — داخل الأسبوع الحالي أو المؤجلة لأسبوع لاحق */
export function buildPostponeTaskPatch(
    targetDate: Date,
    now = new Date(),
): Pick<LegalTask, 'parsedDate' | 'reminderAt'> {
    const day = startOfLocalDay(targetDate);
    const weekStart = getSaturdayOfWeekContaining(now);
    if (isDateInWorkWeekLite(day, weekStart)) {
        return { parsedDate: day, reminderAt: null };
    }
    return { parsedDate: null, reminderAt: day };
}

/**
 * حالة أجندة المهام — خفيف لمسار التنبيهات/authenticity
 * بلا nlpParser / taskVoiceAttachment / tasksManager.
 */
import type { LegalTask } from '@/app/types/TaskEngine';

function startOfLocalDay(d: Date = new Date()): Date {
    const x = new Date(d);
    x.setHours(0, 0, 0, 0);
    return x;
}

export function getSaturdayOfWeekContaining(ref: Date): Date {
    const d = startOfLocalDay(ref);
    const dow = d.getDay();
    const daysFromSat = (dow - 6 + 7) % 7;
    const sat = new Date(d);
    sat.setDate(d.getDate() - daysFromSat);
    return startOfLocalDay(sat);
}

export function isTaskMarkedDone(task: LegalTask): boolean {
    return task.completedAt != null;
}

/** يوم المهمة في الأجندة — تاريخ المهمة أو يوم الإنجاز للمهام بلا تاريخ */
function getTaskAgendaDay(task: LegalTask): Date | null {
    if (task.parsedDate) return startOfLocalDay(task.parsedDate);
    if (task.completedAt) return startOfLocalDay(task.completedAt);
    return null;
}

/** بعد انتهاء يوم المهمة: بطاقة للمعاينة فقط */
export function isTaskAgendaReadOnly(task: LegalTask, now = new Date()): boolean {
    const taskDay = getTaskAgendaDay(task);
    if (!taskDay) return false;
    return startOfLocalDay(taskDay).getTime() < startOfLocalDay(now).getTime();
}

export function isTaskInCurrentAgendaWeek(task: LegalTask, now = new Date()): boolean {
    if (!task.parsedDate) return true;
    const taskWeek = getSaturdayOfWeekContaining(task.parsedDate).getTime();
    const thisWeek = getSaturdayOfWeekContaining(now).getTime();
    return taskWeek === thisWeek;
}

/** يوم المهمة انتهى ولم يُضغط «إنهاء المهمة» */
export function isTaskDayOverdueIncomplete(task: LegalTask, now = new Date()): boolean {
    if (isTaskMarkedDone(task)) return false;
    if (!task.parsedDate) return false;
    const day = startOfLocalDay(task.parsedDate).getTime();
    const today = startOfLocalDay(now).getTime();
    return day < today && isTaskInCurrentAgendaWeek(task, now);
}

import type {
    DocumentRequirementItem,
    LegalSubTask,
    LegalTask,
    TaskExpenseEntry,
} from '@/app/types/TaskEngine';
import type { SharedTaskNote } from '@/app/types/taskHelpTypes';

/** حد النص الخام — يمنع تضخّم التخزين المحلي */
export const MAX_TASK_RAW_LENGTH = 2000;
export const MAX_TASK_TITLE_LENGTH = 500;
export const MAX_TASK_LOCATION_LENGTH = 200;
export const MAX_TASK_LINE_LENGTH = 500;
export const MAX_EXPENSE_LABEL_LENGTH = 120;
export const MAX_EXPENSE_AMOUNT = 1_000_000_000_000;
export const MAX_VOICE_TRANSCRIPT_LENGTH = 4000;
export const MAX_HELP_NOTE_LENGTH = 2000;
export const MAX_NESTED_ITEMS = 40;
export const MAX_TASKS_IN_STORE = 2000;
export const MAX_ID_LENGTH = 80;
export const MAX_VOICE_DATA_URL_CHARS = 6_000_000;

const CONTROL_CHARS =
    /[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F\u202A-\u202E\u2066-\u2069]/g;

const TASK_VOICE_REF_PREFIX = 'hami-voice-ref:';

const TASK_PATCH_KEYS = [
    'rawText',
    'title',
    'location',
    'parsedDate',
    'reminderAt',
    'isFatalDeadline',
    'linkedCaseId',
    'status',
    'completedAt',
    'pinnedToFieldCurtain',
    'fieldCurtainPinnedAt',
    'subTasks',
    'documentRequirements',
    'expenses',
    'voiceRef',
    'voiceTranscript',
    'voiceDurationSec',
    'helpRequestId',
    'requesterId',
    'assigneeId',
    'shareScope',
    'collaborationStatus',
    'isSanitised',
    'sharedNotes',
] as const;

export function clampTaskText(value: string, max: number): string {
    return String(value ?? '')
        .replace(CONTROL_CHARS, '')
        .trim()
        .slice(0, max);
}

export function clampExpenseAmount(amount: number): number | null {
    if (!Number.isFinite(amount) || amount <= 0) return null;
    return Math.min(amount, MAX_EXPENSE_AMOUNT);
}

export function isAllowedTaskVoiceRef(ref: string | null | undefined): boolean {
    if (!ref) return false;
    if (!ref.startsWith(TASK_VOICE_REF_PREFIX)) return false;
    const key = ref.slice(TASK_VOICE_REF_PREFIX.length).trim();
    if (!key.startsWith('task-voice-')) return false;
    if (key.length > 180) return false;
    if (key.includes('..') || key.includes('/') || key.includes('\\')) return false;
    return true;
}

function sanitizeTaskVoiceRef(ref: string | null | undefined): string | null {
    if (ref == null) return null;
    const trimmed = String(ref).trim();
    return isAllowedTaskVoiceRef(trimmed) ? trimmed : null;
}

function clampId(id: string): string {
    return clampTaskText(id, MAX_ID_LENGTH);
}

function sanitizeSubTask(raw: LegalSubTask): LegalSubTask | null {
    const id = clampId(raw.id);
    const title = clampTaskText(raw.title, MAX_TASK_LINE_LENGTH);
    if (!id || !title) return null;
    const loc = raw.location == null ? null : clampTaskText(raw.location, MAX_TASK_LOCATION_LENGTH);
    return {
        ...raw,
        id,
        title,
        location: loc || null,
        isCompleted: !!raw.isCompleted,
        kind: raw.kind === 'field' || raw.kind === 'branch' ? raw.kind : undefined,
    };
}

function sanitizeDocumentRequirement(raw: DocumentRequirementItem): DocumentRequirementItem | null {
    const id = clampId(raw.id);
    const text = clampTaskText(raw.text, MAX_TASK_LINE_LENGTH);
    if (!id || !text) return null;
    return { ...raw, id, text, isChecked: !!raw.isChecked };
}

function sanitizeExpense(raw: TaskExpenseEntry): TaskExpenseEntry | null {
    const id = clampId(raw.id);
    const amount = clampExpenseAmount(raw.amount);
    if (!id || amount == null) return null;
    return {
        ...raw,
        id,
        amount,
        label: clampTaskText(raw.label, MAX_EXPENSE_LABEL_LENGTH) || 'مصروف',
    };
}

function sanitizeSharedNotes(notes: SharedTaskNote[] | undefined): SharedTaskNote[] | undefined {
    if (!Array.isArray(notes)) return undefined;
    const next = notes
        .map((n) => {
            const id = clampId(n.id);
            const authorId = clampTaskText(n.authorId, MAX_ID_LENGTH);
            const text = clampTaskText(n.text, MAX_HELP_NOTE_LENGTH);
            const timestamp = clampTaskText(n.timestamp, 40);
            if (!id || !authorId || !text || !timestamp) return null;
            const note: SharedTaskNote = { id, authorId, text, timestamp };
            if (n.authorName) {
                const name = clampTaskText(n.authorName, 80);
                if (name) note.authorName = name;
            }
            return note;
        })
        .filter((n): n is SharedTaskNote => n != null)
        .slice(0, MAX_NESTED_ITEMS);
    return next.length > 0 ? next : undefined;
}

export function sanitizeLegalTask(task: LegalTask): LegalTask {
    const id = clampId(task.id);
    const rawText = clampTaskText(task.rawText, MAX_TASK_RAW_LENGTH);
    const title =
        clampTaskText(task.title, MAX_TASK_TITLE_LENGTH) || rawText.slice(0, MAX_TASK_TITLE_LENGTH);
    const location =
        task.location == null ? null : clampTaskText(task.location, MAX_TASK_LOCATION_LENGTH) || null;
    const linkedCaseId =
        task.linkedCaseId == null ? null : clampTaskText(task.linkedCaseId, MAX_ID_LENGTH) || null;
    const voiceTranscript =
        task.voiceTranscript == null
            ? null
            : clampTaskText(task.voiceTranscript, MAX_VOICE_TRANSCRIPT_LENGTH) || null;
    const voiceDurationSec =
        typeof task.voiceDurationSec === 'number' && Number.isFinite(task.voiceDurationSec)
            ? Math.min(Math.max(task.voiceDurationSec, 0), 180)
            : null;

    const sanitized: LegalTask = {
        ...task,
        id,
        rawText,
        title: title || 'مهمة',
        location,
        linkedCaseId,
        subTasks: (task.subTasks ?? [])
            .map(sanitizeSubTask)
            .filter((s): s is LegalSubTask => s != null)
            .slice(0, MAX_NESTED_ITEMS),
        documentRequirements: (task.documentRequirements ?? [])
            .map(sanitizeDocumentRequirement)
            .filter((s): s is DocumentRequirementItem => s != null)
            .slice(0, MAX_NESTED_ITEMS),
        expenses: (task.expenses ?? [])
            .map(sanitizeExpense)
            .filter((s): s is TaskExpenseEntry => s != null)
            .slice(0, MAX_NESTED_ITEMS),
        voiceRef: sanitizeTaskVoiceRef(task.voiceRef),
        voiceTranscript,
        voiceDurationSec,
    };

    const notes = sanitizeSharedNotes(task.sharedNotes);
    if (notes) sanitized.sharedNotes = notes;
    else delete sanitized.sharedNotes;

    if (task.helpRequestId) {
        const hid = clampTaskText(task.helpRequestId, MAX_ID_LENGTH);
        if (hid) sanitized.helpRequestId = hid;
        else delete sanitized.helpRequestId;
    }
    if (task.requesterId) {
        const rid = clampTaskText(task.requesterId, MAX_ID_LENGTH);
        if (rid) sanitized.requesterId = rid;
        else delete sanitized.requesterId;
    }
    if (task.assigneeId) {
        const aid = clampTaskText(task.assigneeId, MAX_ID_LENGTH);
        if (aid) sanitized.assigneeId = aid;
        else delete sanitized.assigneeId;
    }

    return sanitized;
}

export function sanitizeLegalTaskList(tasks: LegalTask[]): LegalTask[] {
    return tasks
        .map(sanitizeLegalTask)
        .filter((t) => t.id.length > 0)
        .slice(0, MAX_TASKS_IN_STORE);
}

export function sanitizeTaskPatch(patch: Partial<LegalTask>): Partial<LegalTask> {
    const picked: Partial<LegalTask> = {};
    for (const key of TASK_PATCH_KEYS) {
        if (Object.prototype.hasOwnProperty.call(patch, key) && patch[key] !== undefined) {
            (picked as Record<string, unknown>)[key] = patch[key];
        }
    }
    const full = sanitizeLegalTask({
        id: 'patch',
        rawText: '',
        title: '',
        location: null,
        parsedDate: null,
        reminderAt: null,
        isFatalDeadline: false,
        linkedCaseId: null,
        status: 'pending',
        completedAt: null,
        pinnedToFieldCurtain: false,
        fieldCurtainPinnedAt: null,
        subTasks: [],
        documentRequirements: [],
        expenses: [],
        voiceRef: null,
        voiceTranscript: null,
        voiceDurationSec: null,
        ...picked,
    });
    const out: Partial<LegalTask> = {};
    for (const key of TASK_PATCH_KEYS) {
        if (Object.prototype.hasOwnProperty.call(patch, key)) {
            (out as Record<string, unknown>)[key] = full[key];
        }
    }
    return out;
}

import type { LegalTask } from '@/app/types/TaskEngine';
import type { SanitizeTaskForPublicResult } from '@/app/types/taskHelpTypes';

const PUBLIC_TITLE_PREFIX = '[طلب مساعدة عامة]';
const REDACTION_TOKEN = '[محذوف]';

/** إزالة بريد / جوال عراقي / أرقام طويلة (هوية أو رقم قضية) */
export function redactPiiText(input: string): string {
    let out = String(input ?? '');

    out = out.replace(
        /([a-zA-Z0-9._%+-]{1,64})@([a-zA-Z0-9.-]{1,253})\.([a-zA-Z]{2,24})/g,
        REDACTION_TOKEN,
    );
    out = out.replace(/(?:\+?964|0)?\s*7\d{2}[\s-]?\d{3}[\s-]?\d{4}/g, REDACTION_TOKEN);
    out = out.replace(/(?:\d[\s-]?){10,16}/g, (m) => {
        const digits = m.replace(/[^\d]/g, '');
        if (digits.length < 10 || digits.length > 16) return m;
        return REDACTION_TOKEN;
    });

    // أنماط شائعة: موكل / المدعي / المدعى عليه + اسم
    out = out.replace(
        /(?:الموكل|موكل|المدعي|المدعى\s*عليه|المدعية)\s*[:：-]?\s*[^\s،,]{2,40}/giu,
        REDACTION_TOKEN,
    );
    out = out.replace(
        /(?:رقم\s*القضية|رقم\s*الإضبارة|قضية\s*رقم)\s*[:：-]?\s*[\d\/\-]+/giu,
        REDACTION_TOKEN,
    );

    return out.replace(/\s{2,}/g, ' ').trim();
}

function buildPublicInstructions(task: LegalTask): string {
    const parts: string[] = [];
    for (const st of task.subTasks ?? []) {
        const t = redactPiiText(st.title);
        if (t) parts.push(`• ${t}`);
    }
    for (const d of task.documentRequirements ?? []) {
        const t = redactPiiText(d.text);
        if (t) parts.push(`• مستند: ${t}`);
    }
    return parts.join('\n');
}

/**
 * تصفية مهمة قبل النشر العام في المنتدى.
 * يحذف بيانات الموكل/القضية/الصوت/المصروفات؛ يحافظ على محكمة وعنوان وتعليمات عامة.
 */
export function sanitizeTaskForPublic(task: LegalTask): SanitizeTaskForPublicResult {
    const cleanedTitle = redactPiiText(task.title || task.rawText || 'مهمة');
    const title = cleanedTitle.startsWith(PUBLIC_TITLE_PREFIX)
        ? cleanedTitle
        : `${PUBLIC_TITLE_PREFIX} ${cleanedTitle}`.trim();
    const location = task.location ? redactPiiText(task.location) || null : null;
    const dueDate = task.parsedDate ? task.parsedDate.toISOString() : null;
    const instructions = buildPublicInstructions(task);
    const rawText = [title, location ? `الموقع: ${location}` : '', instructions]
        .filter(Boolean)
        .join('\n');

    return {
        title,
        rawText,
        location,
        dueDate,
        instructions,
        isSanitised: true,
    };
}

import type { VoiceNoteSavePayload } from '@/app/components/lawyer/commandCenterTypes';
import { voiceNoteTitleFromMeta } from '@/app/services/voice/voiceNoteCodec';
import {
    isVoiceBlobWithinLimit,
    isVoiceDurationValid,
    persistVoiceRecording,
} from '@/app/services/voice/voiceRecordingLimits';
import { deleteVoiceBlob } from '@/app/services/voice/voiceNoteStorage';
import {
    clampTaskText,
    isAllowedTaskVoiceRef,
    MAX_VOICE_TRANSCRIPT_LENGTH,
} from '@/app/services/tasks/taskInputGuard';

type TaskVoiceFields = {
    voiceRef: string | null;
    voiceTranscript: string | null;
    voiceDurationSec: number | null;
};

export function taskVoiceStorageKey(taskId: string): string {
    return `task-voice-${taskId}`;
}

export function parseTaskVoiceStorageKey(voiceRef: string | null | undefined): string | null {
    if (!voiceRef) return null;
    const prefix = 'hami-voice-ref:';
    if (!voiceRef.startsWith(prefix)) return null;
    const key = voiceRef.slice(prefix.length).trim();
    return key.startsWith('task-voice-') ? key : null;
}

export function titleFromVoicePayload(payload: VoiceNoteSavePayload, fallbackText?: string): string {
    const transcript = payload.transcript?.trim();
    if (transcript) return transcript.length > 200 ? `${transcript.slice(0, 197)}…` : transcript;
    const fb = fallbackText?.trim();
    if (fb) return fb;
    return voiceNoteTitleFromMeta({
        durationSec: payload.durationSeconds,
        fallback: 'مهمة صوتية',
    });
}

export async function persistTaskVoiceAttachment(
    taskId: string,
    payload: VoiceNoteSavePayload,
): Promise<TaskVoiceFields | null> {
    if (!isVoiceDurationValid(payload.durationSeconds)) return null;
    if (!isVoiceBlobWithinLimit(payload.blob.size)) return null;

    const storageKey = taskVoiceStorageKey(taskId);
    try {
        const { body: voiceRef } = await persistVoiceRecording(storageKey, payload.blob);
        if (!isAllowedTaskVoiceRef(voiceRef)) return null;
        const transcript = payload.transcript
            ? clampTaskText(payload.transcript, MAX_VOICE_TRANSCRIPT_LENGTH) || null
            : null;
        return {
            voiceRef,
            voiceTranscript: transcript,
            voiceDurationSec: payload.durationSeconds,
        };
    } catch {
        return null;
    }
}

export async function removeTaskVoiceAttachment(voiceRef: string | null | undefined): Promise<void> {
    const key = parseTaskVoiceStorageKey(voiceRef);
    if (!key) return;
    await deleteVoiceBlob(key);
}

import { SecureAPIClient } from '@/app/services/SecureAPIClient';
import { isLiveCloudSyncBucketEnabled } from '@/app/services/settings/cloudSyncBucket';
import { debug } from '@/app/utils/debug';
import type { TimelineEvent } from '@/app/types/execution';
import type { TimelineEventDbRow } from '@/app/types/supabase-timeline';

function canReachExecutionTimelineCloud(): boolean {
    return isLiveCloudSyncBucketEnabled('execution');
}

/**
 * إدراج حدث زمني عبر WIFE BFF.
 * محلي بالكامل حتى تُفعَّل مزامنة التنفيذ — الفشل عند التزامن يُتجاهل بهدوء.
 */
export async function insertTimelineEventToSupabase(params: {
    executionFileId: string;
    event: TimelineEvent;
    snapshotData?: unknown;
}): Promise<void> {
    const { executionFileId, event, snapshotData } = params;
    if (!executionFileId || executionFileId === 'undefined') return;
    if (!canReachExecutionTimelineCloud()) return;

    try {
        await SecureAPIClient.fetchSecure('/api/timeline-events', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ executionFileId, event, snapshotData }),
        });
    } catch (e) {
        debug.error('[timelineEventsSupabase] فشل upsert:', e);
    }
}

/**
 * جلب أحداث السجل من BFF مع snapshot_data للدمج مع الواجهة.
 */
export async function fetchTimelineEventsFromSupabase(
    executionFileId: string
): Promise<TimelineEventDbRow[]> {
    if (!executionFileId || executionFileId === 'undefined') return [];
    if (!canReachExecutionTimelineCloud()) return [];

    try {
        const res = await SecureAPIClient.fetchSecure<{ ok: boolean; rows?: TimelineEventDbRow[] }>(
            `/api/timeline-events?executionFileId=${encodeURIComponent(executionFileId)}`,
            { method: 'GET' },
        );
        return Array.isArray(res?.rows) ? res.rows : [];
    } catch (e) {
        debug.error('[timelineEventsSupabase] جلب — استثناء:', e);
        return [];
    }
}

/**
 * يدمج snapshot_data القادم من Supabase في أحداث الواجهة المحلية (حسب event_id).
 */
export function mergeRemoteSnapshotsIntoTimelineEvents(
    local: TimelineEvent[],
    remoteRows: TimelineEventDbRow[]
): TimelineEvent[] {
    if (!remoteRows.length) return local;
    const byId = new Map(remoteRows.map((r) => [r.event_id, r.snapshot_data]));
    return local.map((e) => {
        const snap = byId.get(String(e.id));
        if (snap == null || e.snapshot != null) return e;
        return { ...e, snapshot: snap };
    });
}

