describe('warmTransactionsDiskRead', () => {
    beforeEach(() => {
        vi.clearAllMocks();
    });

    it('يربط فوراً ويسخّن مفتاح الخيوط فقط ثم يعيد الربط بعد الفك', async () => {
        warmTransactionsDiskRead('lawyer-1');
