import type { ProcedureGuideApplyPayload } from '@/app/services/transactions/procedureGuideNavigation';
import type { TransactionDocumentOwnerTag } from '@/app/modules/transactionsThreading/types';
import type { TransactionTask } from '@/app/modules/transactionsThreading/types';

type ApplyProcedureGuideDeps = {
    addTask: (input: {
        transactionId: string;
        title: string;
        parentTaskId: string | null;
        deadline: string | null;
        notes?: string | null;
    }) => Promise<TransactionTask>;
    addDocument: (input: {
        transactionId: string;
        title: string;
        ownerTag: TransactionDocumentOwnerTag;
    }) => Promise<unknown>;
    refreshTransactionData: (transactionId: string) => Promise<void>;
};

/** يستورد خطوات الدليل + عناوين المستمسكات إلى معاملة جديدة */
export async function applyProcedureGuideToTransaction(
    transactionId: string,
    guide: ProcedureGuideApplyPayload,
    deps: ApplyProcedureGuideDeps,
): Promise<void> {
    const mapOldToNew = new Map<string, string>();
    const remaining = guide.steps.slice();
    let guard = 0;

    while (remaining.length && guard < 200) {
        guard += 1;
        let progressed = false;
        for (let i = 0; i < remaining.length; i += 1) {
            const t = remaining[i];
            const canCreate = !t.parentTaskId || mapOldToNew.has(t.parentTaskId);
            if (!canCreate) continue;
            const parentTaskId = t.parentTaskId ? mapOldToNew.get(t.parentTaskId)! : null;
            const created = await deps.addTask({
                transactionId,
                title: t.title,
                parentTaskId,
                deadline: null,
                notes: t.notes?.trim() ? t.notes : null,
            });
            mapOldToNew.set(t.id, created.id);
            remaining.splice(i, 1);
            i -= 1;
            progressed = true;
        }
        if (!progressed) {
            for (const t of remaining) {
                const created = await deps.addTask({
                    transactionId,
                    title: t.title,
                    parentTaskId: null,
                    deadline: null,
                    notes: t.notes?.trim() ? t.notes : null,
                });
                mapOldToNew.set(t.id, created.id);
            }
            remaining.length = 0;
        }
    }

    for (const doc of guide.documents) {
        const title = doc.title.trim();
        if (!title) continue;
        await deps.addDocument({
            transactionId,
            title,
            ownerTag: doc.ownerTag,
        });
    }

    await deps.refreshTransactionData(transactionId);
}

import { TransactionStatus, type Transaction } from '@/app/modules/transactionsThreading/types';
import { archiveTextMatchesQuery } from '@/app/services/search/normalizeArabicSearch';
import { clampGlobalSearchQuery } from '@/app/services/search/globalSearchQuerySecurity';

export type TransactionsListStatusFilter = 'all' | TransactionStatus | 'archived' | 'deleted';

function transactionMatchesQuery(tx: Transaction, query: string): boolean {
    if (!query.trim()) return true;
    const hay = [tx.title, tx.clientName, tx.targetDepartment].join(' ');
    return archiveTextMatchesQuery(hay, query);
}

function isDeletedTransaction(tx: Transaction): boolean {
    return Boolean(tx.deletedAt);
}

function isArchivedTransaction(tx: Transaction): boolean {
    return Boolean(tx.archivedAt) && !isDeletedTransaction(tx);
}

function isPrimaryListTransaction(tx: Transaction): boolean {
    return !isDeletedTransaction(tx) && !tx.archivedAt;
}

function matchesListBucket(tx: Transaction, filter: TransactionsListStatusFilter): boolean {
    if (filter === 'deleted') return isDeletedTransaction(tx);
    if (filter === 'archived') return isArchivedTransaction(tx);
    if (!isPrimaryListTransaction(tx)) return false;
    if (filter === 'all') return true;
    return tx.status === filter;
}

export function filterTransactionsList(
    transactions: Transaction[],
    query: string,
    filter: TransactionsListStatusFilter,
): Transaction[] {
    const q = clampGlobalSearchQuery(query);
    return transactions.filter((tx) => {
        return matchesListBucket(tx, filter) && transactionMatchesQuery(tx, q);
    });
}

