const PII_TOKEN = SHARE_PII_TOKEN;

function normalizeTag(label: string): string {
    const core = label
        .trim()
        .replace(/^#/, '')
        .replace(/\s+/g, '_')
        .replace(/[^\p{L}\p{N}_]+/gu, '');
    return core ? `#${core}` : '';
}

function proceduralTitle(rawTitle: string, clientName?: string | null): string {
    let title = scrubPiiText(rawTitle, clientName);
    if (!title || title === PII_TOKEN) title = 'دليل إجرائي لمعاملة';
    if (!title.includes('دليل')) {
        title = `دليل إجرائي — ${title}`;
    }
    return title.slice(0, 120);
}

function deriveTypeTag(title: string): string {
    const tagged = normalizeTag(title.replace(/^دليل\s*إجرائي\s*[—\-–]?\s*/u, '').slice(0, 40));
    return tagged || '#معاملات';
}

function toTreeTasks(
    tasks: Array<{
        id: string;
        title: string;
        parentTaskId: string | null;
        notes?: string | null;
        createdAt?: string;
    }>,
): TransactionTask[] {
    return tasks.map((t, index) => ({
        id: t.id,
        transactionId: 'share',
        title: t.title,
        status: TransactionTaskStatus.Pending,
        parentTaskId: t.parentTaskId,
        notes: t.notes ?? null,
        deadline: null,
        officialReference: null,
        createdAt: t.createdAt ?? `1970-01-01T00:00:${String(index).padStart(2, '0')}.000Z`,
        completedAt: null,
    }));
}

function collectSteps(
    nodes: TransactionTaskNode[],
    clientName: string | null | undefined,
    prefix: string,
    depth: number,
    out: ShareProcedureStepCard[],
): void {
    nodes.forEach((node, index) => {
        const number = prefix ? `${prefix}.${index + 1}` : String(index + 1);
        const stepTitle = scrubPiiText(node.title, clientName) || 'خطوة';
        const notes = scrubPiiText(node.notes ?? '', clientName);
        out.push({
            id: node.id,
            number,
            title: stepTitle,
            notes: notes && notes !== PII_TOKEN ? notes : '',
            depth,
            parentTaskId: node.parentTaskId,
        });
        if (node.children.length > 0) {
            collectSteps(node.children, clientName, number, depth + 1, out);
        }
    });
}

function scrubDocuments(
    documents: Array<Pick<TransactionDocument, 'title' | 'ownerTag'>>,
    clientName?: string | null,
): ShareProcedureDocumentCard[] {
    const out: ShareProcedureDocumentCard[] = [];
    for (const doc of documents) {
        const title = scrubPiiText(doc.title, clientName);
        if (!title || title === PII_TOKEN) continue;
        out.push({
            title,
            ownerTag: doc.ownerTag === 'للدائرة' || doc.ownerTag === 'أخرى' ? doc.ownerTag : 'للموكل',
        });
    }
    return out;
}

function buildDraft(params: {
    sourceTitle: string;
    clientName?: string | null;
    tasks: Array<{
        id: string;
        title: string;
        parentTaskId: string | null;
        notes?: string | null;
        createdAt?: string;
    }>;
    documents?: Array<Pick<TransactionDocument, 'title' | 'ownerTag'>>;
}): ShareProcedureDraft {
    const clientName = params.clientName?.trim() || null;
    const title = proceduralTitle(params.sourceTitle, clientName);

    const tree = buildTaskTree(toTreeTasks(params.tasks));
    const steps: ShareProcedureStepCard[] = [];
    collectSteps(tree, clientName, '', 0, steps);
    const documents = scrubDocuments(params.documents ?? [], clientName);

    const tags = Array.from(
        new Set([PROCEDURE_GUIDE_TAG, deriveTypeTag(title), '#معاملات'].map(normalizeTag).filter(Boolean)),
    );

    const body = formatProcedureCardsBody({ title, steps, documents });

    return { title, body, tags, steps, documents };
}

/** مشاركة مسار معاملة حيّة — إجراءات + عناوين مستمسكات (بلا ملفات/موكل) */
export function sanitizeTransactionForSharing(
    transaction: Pick<Transaction, 'title' | 'clientName' | 'targetDepartment'>,
    tasks: TransactionTask[],
    documents: Array<Pick<TransactionDocument, 'title' | 'ownerTag'>> = [],
): ShareProcedureDraft {
    return buildDraft({
        sourceTitle: transaction.title,
        clientName: transaction.clientName,
        tasks: tasks.map((t) => ({
            id: t.id,
            title: t.title,
            parentTaskId: t.parentTaskId,
            notes: t.notes,
            createdAt: t.createdAt,
        })),
        documents,
    });
}

/** مشاركة قالب محفوظ — خطوات القالب فقط */
export function sanitizeTemplateForSharing(template: TaskTemplate): ShareProcedureDraft {
    return buildDraft({
        sourceTitle: template.name,
        clientName: null,
        tasks: template.tasks.map((t) => ({
            id: t.id,
            title: t.title,
            parentTaskId: t.parentTaskId,
            notes: null,
        })),
        documents: [],
    });
}

/** شبكة أمان قبل الإرسال — يحافظ على النص اليدوي مع تنقيح PII وإعادة بيانات الآلة */
export function resanitizeShareDraft(
    draft: ShareProcedureDraft,
    clientName?: string | null,
): ShareProcedureDraft {
    const title = scrubPiiText(draft.title, clientName) || 'دليل إجرائي لمعاملة';
    const steps = (draft.steps ?? []).slice(0, 80).map((s) => ({
        id: String(s.id ?? ''),
        number: String(s.number ?? ''),
        title: scrubPiiText(s.title, clientName) || 'خطوة',
        notes: scrubPiiText(s.notes, clientName),
        depth: Number.isFinite(s.depth) ? Math.min(Math.max(0, Math.floor(s.depth)), 8) : 0,
        parentTaskId: s.parentTaskId ?? null,
    }));
    const documents = scrubDocuments(draft.documents ?? [], clientName).slice(0, 40);
    const tags = Array.from(
        new Set(
            [...draft.tags, PROCEDURE_GUIDE_TAG]
                .map((t) => normalizeTag(String(t)))
                .filter(Boolean),
        ),
    ).slice(0, 8);
    const manualBody = clampTransactionText(scrubPiiMultiline(draft.body ?? '', clientName), TX_SHARE_BODY_MAX);
    const baseBody = manualBody.trim()
        ? manualBody
        : formatProcedureCardsBody({ title, steps, documents });
    const body = ensureMachineTrail(baseBody, { title, steps, documents });
    return { title, body, tags, steps, documents };
}

import type {
    TransactionsThreadingSaveInput,
    TransactionsThreadingState,
} from '@/app/services/cloud/lawyerTransactionTypes';
import {
    TransactionStatus,
    TransactionTaskStatus,
    type Transaction,
    type TransactionDocument,
    type TransactionTask,
} from '@/app/modules/transactionsThreading/types';
import {
    sanitizeTransactionCreateFields,
    sanitizeTransactionDocumentOwnerTag,
    sanitizeTransactionDocumentTitle,
    sanitizeTransactionDocumentType,
    sanitizeTransactionId,
    sanitizeTransactionIsoTimestamp,
    sanitizeTransactionOfficialReference,
    sanitizeTransactionTaskNotes,
    sanitizeTransactionTaskTitle,
    sanitizeTransactionUserId,
} from '@/app/services/transactions/transactionsInputSecurity';

const MAX_TRANSACTIONS = 400;
const MAX_TASKS = 1_500;
const MAX_DOCUMENTS = 1_500;

function sanitizeTransactionStatus(value: unknown): TransactionStatus {
    if (value === TransactionStatus.Paused || value === TransactionStatus.Completed) return value;
    return TransactionStatus.Active;
}

function sanitizeTaskStatus(value: unknown): TransactionTaskStatus {
    if (
        value === TransactionTaskStatus.InProgress ||
        value === TransactionTaskStatus.Blocked ||
        value === TransactionTaskStatus.Done
    ) {
        return value;
    }
    return TransactionTaskStatus.Pending;
}

function optionalIso(value: unknown): string | null | undefined {
    if (value === undefined) return undefined;
    if (value === null) return null;
    const raw = sanitizeTransactionIsoTimestamp(value, '');
    return raw.length > 0 ? raw : null;
}

function sanitizeTransactionRecord(tx: Transaction): Transaction | null {
    const id = sanitizeTransactionId(tx.id);
    if (!id) return null;
    const fields = sanitizeTransactionCreateFields({
        title: tx.title ?? '',
        clientName: tx.clientName ?? '',
        targetDepartment: tx.targetDepartment ?? '',
    });
    const createdAt = sanitizeTransactionIsoTimestamp(tx.createdAt, new Date().toISOString());
    const row: Transaction = {
        id,
        title: fields.title,
        clientName: fields.clientName,
        targetDepartment: fields.targetDepartment,
        status: sanitizeTransactionStatus(tx.status),
        createdAt,
        updatedAt: sanitizeTransactionIsoTimestamp(tx.updatedAt, createdAt),
    };
    const archivedAt = optionalIso(tx.archivedAt);
    const deletedAt = optionalIso(tx.deletedAt);
    if (archivedAt !== undefined) row.archivedAt = archivedAt;
    if (deletedAt !== undefined) row.deletedAt = deletedAt;
    return row;
}

function sanitizeTaskRecord(task: TransactionTask): TransactionTask | null {
    const id = sanitizeTransactionId(task.id);
    const transactionId = sanitizeTransactionId(task.transactionId);
    if (!id || !transactionId) return null;
    const createdAt = sanitizeTransactionIsoTimestamp(task.createdAt, new Date().toISOString());
    const parentId = task.parentTaskId == null ? null : sanitizeTransactionId(task.parentTaskId);
    return {
        id,
        transactionId,
        title: sanitizeTransactionTaskTitle(task.title ?? ''),
        status: sanitizeTaskStatus(task.status),
        parentTaskId: parentId || null,
        notes: sanitizeTransactionTaskNotes(task.notes),
        deadline: task.deadline == null ? null : optionalIso(task.deadline) ?? null,
        officialReference: sanitizeTransactionOfficialReference(task.officialReference),
        createdAt,
        completedAt: task.completedAt == null ? null : optionalIso(task.completedAt) ?? null,
    };
}

function sanitizeDocumentRecord(doc: TransactionDocument): TransactionDocument | null {
    const id = sanitizeTransactionId(doc.id);
    const transactionId = sanitizeTransactionId(doc.transactionId);
    if (!id || !transactionId) return null;
    return {
        id,
        transactionId,
        type: sanitizeTransactionDocumentType(doc.type),
        title: sanitizeTransactionDocumentTitle(doc.title ?? ''),
        ownerTag: sanitizeTransactionDocumentOwnerTag(doc.ownerTag),
        uploadedAt: sanitizeTransactionIsoTimestamp(doc.uploadedAt, new Date().toISOString()),
    };
}

/** يعقّم حمولة الحالة قبل الكتابة المحلية/السحابية — بلا حقول مالية مهجورة */
export function sanitizeTransactionsThreadingSaveInput(
    userId: string,
    input: TransactionsThreadingSaveInput,
): TransactionsThreadingState {
    return {
        schemaVersion: 1,
        userId: sanitizeTransactionUserId(userId),
        updatedAt: new Date().toISOString(),
        transactions: (Array.isArray(input.transactions) ? (input.transactions as Transaction[]) : [])
            .map(sanitizeTransactionRecord)
            .filter((row): row is Transaction => row != null)
            .slice(0, MAX_TRANSACTIONS),
        tasks: (Array.isArray(input.tasks) ? (input.tasks as TransactionTask[]) : [])
            .map(sanitizeTaskRecord)
            .filter((row): row is TransactionTask => row != null)
            .slice(0, MAX_TASKS),
        documents: (Array.isArray(input.documents) ? (input.documents as TransactionDocument[]) : [])
            .map(sanitizeDocumentRecord)
            .filter((row): row is TransactionDocument => row != null)
            .slice(0, MAX_DOCUMENTS),
    };
}

export const SHARE_PII_TOKEN = '[محذوف]';

const EMAIL_RE = /([a-zA-Z0-9._%+-]{1,64})@([a-zA-Z0-9.-]{1,253})\.([a-zA-Z]{2,24})/g;
const IRAQ_MOBILE_RE = /(?:\+?964|0)?\s*7\d{2}[\s-]?\d{3}[\s-]?\d{4}/g;
const LONG_ID_RE = /(?:\d[\s-]?){10,16}/g;
const OFFICIAL_REF_INLINE_RE = /(?:صادر|وارد|وصل)\s*[:：]?\s*[\d\u0660-\u0669\-/]+/gi;

function escapeRegExp(value: string): string {
    return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function scrubCore(input: string, clientName: string | null | undefined, collapseNewlines: boolean): string {
    let out = String(input ?? '');
    const name = clientName?.trim();
    if (name && name.length >= 2) {
        out = out.replace(new RegExp(escapeRegExp(name), 'gi'), SHARE_PII_TOKEN);
    }
    out = out.replace(EMAIL_RE, SHARE_PII_TOKEN);
    out = out.replace(IRAQ_MOBILE_RE, SHARE_PII_TOKEN);
    out = out.replace(LONG_ID_RE, (m) => {
        const digits = m.replace(/[^\d]/g, '');
        if (digits.length < 10 || digits.length > 16) return m;
        return SHARE_PII_TOKEN;
    });
    out = out.replace(OFFICIAL_REF_INLINE_RE, SHARE_PII_TOKEN);
    if (collapseNewlines) {
        return out.replace(/\s{2,}/g, ' ').trim();
    }
    return out.replace(/[^\S\n]{2,}/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

/** تنقيح نصي للبيانات الحساسة — آمن لإعادة التشغيل قبل النشر */
export function scrubPiiText(input: string, clientName?: string | null): string {
    return scrubCore(input, clientName, true);
}

/** تنقيح مع الحفاظ على أسطر النص الإجرائي */
export function scrubPiiMultiline(input: string, clientName?: string | null): string {
    return scrubCore(input, clientName, false);
}

