export const REPOSITORY_ACTION_CATEGORY = {
    note: 'مسودة',
    scan: 'مسح',
    image: 'صورة',
    pdf: 'PDF',
    voice: 'تسجيل صوتي',
} as const;

export type RepositoryActionCategoryKey = keyof typeof REPOSITORY_ACTION_CATEGORY;

export const PRIORITIZED_VISIBLE_CATEGORIES = [
