import {
    mergeVaultDocPair,
    parseVaultDocFromKv,
    sealVaultDocForKv,
} from '@/app/services/vault/vaultCloudKvPayload';

async function loadLocalVaultDocs(): Promise<SmartVaultDoc[]> {
    return readVaultLocalIndex();
}

function mergeVaultDocs(local: SmartVaultDoc[], remote: SmartVaultDoc[]): SmartVaultDoc[] {
    const map = new Map<string, SmartVaultDoc>();
    for (const d of local) map.set(d.id, d);
    for (const d of remote) {
        const prev = map.get(d.id);
        if (!prev) {
            map.set(d.id, d);
            continue;
        }
        const prevTime = Number.isFinite(Date.parse(prev.updatedAt)) ? Date.parse(prev.updatedAt) : 0;
        const nextTime = Number.isFinite(Date.parse(d.updatedAt)) ? Date.parse(d.updatedAt) : 0;
        const winner = nextTime > prevTime ? d : prev;
        const other = nextTime > prevTime ? prev : d;
        map.set(d.id, mergeVaultDocPair(winner, other));
    }
    return Array.from(map.values());
}

async function persistVaultDocToKv(doc: SmartVaultDoc): Promise<void> {
    const sealed = await sealVaultDocForKv(doc);
    await kv.set(`vault:docs:${doc.authorId}:${doc.id}`, sealed);
}

export const SmartVaultDB = {
    async listDocs(userId?: string): Promise<SmartVaultDoc[]> {
        if (!userId?.trim()) return [];
        const uid = userId.trim();
        const localDocs = (await loadLocalVaultDocs()).filter((d) => d.authorId === uid);
        if (!isLawyerWorkCloudLive()) {
            return localDocs.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
        }
        try {
            const raw = await kv.getByPrefix(`vault:docs:${uid}:`);
            const remoteDocs: SmartVaultDoc[] = [];
            if (Array.isArray(raw)) {
                for (const item of raw) {
                    const doc = await parseVaultDocFromKv(item, uid);
                    if (doc) remoteDocs.push(doc);
                }
            }
            const mergedForUser = filterDeletedVaultDocs(
                mergeVaultDocs(localDocs, remoteDocs).filter((d) => d.authorId === uid),
            ).sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());

            const latestLocalForUser = (await loadLocalVaultDocs()).filter((d) => d.authorId === uid);
            const finalForUser = filterDeletedVaultDocs(
                mergeVaultDocs(mergedForUser, latestLocalForUser).filter((d) => d.authorId === uid),
            ).sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());

            return finalForUser;
        } catch {
            return localDocs.sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
        }
    },

    async saveDoc(doc: SmartVaultDoc, requesterId?: string): Promise<void> {
        const requester = (requesterId ?? doc.authorId ?? '').trim();
        assertVaultDocOwner(doc, requester);
        if (doc.storagePath) {
            assertVaultStoragePathOwner(doc.storagePath, requester);
        }
        try {
            upsertVaultLocalIndexDocImmediate(doc);
            mergeVaultDocsWarmCache(doc.authorId, [doc]);
            void upsertVaultLocalIndexDocAndFlush(doc).catch((err) => {
                console.error('[Vault] saveDoc background flush failed', err);
            });
        } catch (err) {
            console.error('[Vault] saveDoc degraded persist - keeping in-memory index', err);
            upsertVaultLocalIndexDoc(doc);
        }
        if (isKvProxyNetworkEnabled() && isLawyerWorkCloudLive()) {
            void persistVaultDocToKv(doc).catch(() => {
                /* local-first — لا سقوط لنص صريح على KV */
            });
        }
    },

    async deleteDoc(docId: string, authorId: string): Promise<void> {
        if (!authorId || !docId) throw new Error('معرف الملف والمستخدم مطلوب');
        const localDocs = await loadLocalVaultDocs();
        const localDoc = localDocs.find((d) => d?.id === docId && d.authorId === authorId);
        if (isLawyerWorkCloudLive()) {
            try {
                const doc = await parseVaultDocFromKv(await kv.get(`vault:docs:${authorId}:${docId}`), authorId);
                const path = doc?.storagePath || '';
                if (path && !path.startsWith('local:') && !isVaultIdbStoragePath(path)) {
                    await removeRemoteStoragePathsBestEffort([path]);
                }
            } catch {
                /* continue */
            }
            try {
                await kv.del(`vault:docs:${authorId}:${docId}`);
            } catch {
                /* local first */
            }
        }
        if (localDoc?.storagePath && isVaultIdbStoragePath(localDoc.storagePath)) {
            await deleteVaultBlobByPath(localDoc.storagePath);
        }
        removeVaultLocalIndexDoc(docId, authorId);
        removeVaultDocFromWarmCache(authorId, docId);
        await flushVaultLocalIndexPersist();
    },

    async updateDoc(doc: SmartVaultDoc, requesterId?: string): Promise<void> {
        const requester = (requesterId ?? doc.authorId ?? '').trim();
        assertVaultDocOwner(doc, requester);
        await this.saveDoc(doc, requester);
    },

    async bindToDossier(docId: string, authorId: string, dossierId: string): Promise<void> {
        if (!docId || !authorId || !dossierId) throw new Error('جميع الحقول مطلوبة');

        let doc: SmartVaultDoc | null = null;
        const localDocs = await loadLocalVaultDocs();
        const localIdx = localDocs.findIndex((d) => d.id === docId && d.authorId === authorId);
        if (localIdx !== -1) {
            doc = localDocs[localIdx];
        } else if (isLawyerWorkCloudLive()) {
            try {
                doc = await parseVaultDocFromKv(await kv.get(`vault:docs:${authorId}:${docId}`), authorId);
            } catch {
                /* ignore */
            }
        }
        if (!doc) throw new Error('الملف غير موجود');
        if (doc.authorId !== authorId) throw new Error('غير مصرح بربط هذا الملف');

        const updated: SmartVaultDoc = {
            ...doc,
            boundDossierId: dossierId,
            updatedAt: new Date().toISOString(),
        };
        await this.updateDoc(updated, authorId);
    },

    async getSignedUrl(storagePath: string): Promise<string | null> {
        if (!isLawyerWorkCloudLive()) return null;
        return LawyerStorage.getSignedUrl(storagePath);
    },
};

/** مسار vault IDB — بدون سحب vaultBlobStore الثقيل إلى LD stem */
export const VAULT_IDB_PATH_PREFIX = 'idb:vault:';

export function isVaultIdbStoragePath(path: string | undefined | null): boolean {
    return (path || '').startsWith(VAULT_IDB_PATH_PREFIX);
}

import { sealWorkCloudKvValue, unsealWorkCloudKvValue } from '@/app/services/cloud/workCloudKvSeal';
import { sanitizeVaultPlainNote, sanitizeVaultPreviewUrl } from '@/app/services/vault/vaultPreviewUrlSafety';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';

function isVaultDocShape(value: unknown, uid?: string): value is SmartVaultDoc {
    if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
    const o = value as Record<string, unknown>;
    if (typeof o.id !== 'string' || !o.id.trim()) return false;
    if (typeof o.title !== 'string' || typeof o.authorId !== 'string') return false;
    if (uid && o.authorId !== uid) return false;
    return true;
}

/** بيانات الفهرس للمزامنة — بلا OCR ولا روابط مؤقتة ولا حالة واجهة */
export function vaultDocPayloadForKv(doc: SmartVaultDoc): SmartVaultDoc {
    return {
        ...doc,
        signedUrl: null,
        extractedText: null,
        extractedTextAt: null,
        isProcessing: false,
        lawyerNote: sanitizeVaultPlainNote(doc.lawyerNote),
        aiSummary: sanitizeVaultPlainNote(doc.aiSummary),
    };
}

export async function sealVaultDocForKv(doc: SmartVaultDoc): Promise<unknown> {
    return sealWorkCloudKvValue(vaultDocPayloadForKv(doc));
}

export async function parseVaultDocFromKv(raw: unknown, uid?: string): Promise<SmartVaultDoc | null> {
    const plain = await unsealWorkCloudKvValue(raw);
    if (!isVaultDocShape(plain, uid)) return null;
    return {
        ...plain,
        signedUrl: sanitizeVaultPreviewUrl(plain.signedUrl),
    };
}

/** الفائز زمنياً مع الإبقاء على نص البحث المحلي إن غاب عن السحابة */
export function mergeVaultDocPair(winner: SmartVaultDoc, other: SmartVaultDoc): SmartVaultDoc {
    return {
        ...winner,
        signedUrl: winner.signedUrl ?? other.signedUrl ?? null,
        storagePath: winner.storagePath || other.storagePath,
        extractedText: winner.extractedText || other.extractedText || null,
        extractedTextAt: winner.extractedTextAt || other.extractedTextAt || null,
    };
}

import { SmartVaultDB } from '@/app/services/vault/smartVaultRuntime';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { resolveVaultMediaKind } from '@/app/services/vault/vaultDocUtils';
import { assertVaultStoragePathOwner } from '@/app/services/vault/vaultOwnership';
import { sanitizeVaultPreviewUrl } from '@/app/services/vault/vaultPreviewUrlSafety';
import {
    getVaultBlob,
    getVaultBlobObjectUrl,
    isVaultIdbStoragePath,
    parseVaultIdbPath,
    peekVaultBlob,
    prefetchVaultBlobStore,
    waitForVaultBlobWrites,
} from '@/app/services/vaultBlobStore';

export type VaultDocViewerKind = 'image' | 'pdf' | 'audio' | 'file';

export function vaultDocStorageOwned(doc: SmartVaultDoc): boolean {
    const path = doc.storagePath?.trim() || '';
    const author = (doc.authorId || '').trim();
    if (!path) return true;
    if (!author) return false;
    try {
        assertVaultStoragePathOwner(path, author);
    } catch {
        return false;
    }
    if (isVaultIdbStoragePath(path)) {
        const parsed = parseVaultIdbPath(path);
        if (parsed && parsed.userId !== author) return false;
    }
    return true;
}

export function isVaultDocImage(doc: SmartVaultDoc): boolean {
    return resolveVaultMediaKind(doc) === 'image';
}

export function isVaultDocPdf(doc: SmartVaultDoc): boolean {
    return resolveVaultMediaKind(doc) === 'pdf';
}

export function isVaultDocLocal(doc: SmartVaultDoc): boolean {
    const path = doc.storagePath || '';
    return path.startsWith('local:vault:') || isVaultIdbStoragePath(path);
}

export async function resolveVaultDocBlob(doc: SmartVaultDoc): Promise<Blob | null> {
    if (!vaultDocStorageOwned(doc)) return null;
    const path = doc.storagePath?.trim() || '';
    if (isVaultIdbStoragePath(path)) {
        const parsed = parseVaultIdbPath(path);
        if (!parsed) return null;
        const hot = peekVaultBlob(parsed.userId, parsed.docId);
        if (hot) return hot;
        return getVaultBlob(parsed.userId, parsed.docId);
    }

    const cached = sanitizeVaultPreviewUrl(doc.signedUrl);
    if (cached && (cached.startsWith('data:') || cached.startsWith('blob:'))) {
        try {
            const response = await fetch(cached);
            const blob = await response.blob();
            return blob.size > 0 ? blob : null;
        } catch {
            return null;
        }
    }

    return null;
}

export async function resolveVaultDocUrl(doc: SmartVaultDoc): Promise<string | null> {
    if (!vaultDocStorageOwned(doc)) return null;
    const path = doc.storagePath?.trim() || '';
    const author = (doc.authorId || '').trim();

    const cached = sanitizeVaultPreviewUrl(doc.signedUrl);
    const isPdfDoc =
        doc.type === 'pdf' ||
        (doc.mimeType || '').toLowerCase() === 'application/pdf' ||
        /\.pdf$/i.test(doc.fileName || doc.title || '');

    const objectUrlFromBlob = (blob: Blob): string => {
        if (isPdfDoc && blob.type !== 'application/pdf') {
            return URL.createObjectURL(new Blob([blob], { type: 'application/pdf' }));
        }
        return URL.createObjectURL(blob);
    };

    if (cached && cached.startsWith('data:')) {
        return cached;
    }

    if (isVaultIdbStoragePath(path)) {
        const parsed = parseVaultIdbPath(path);
        if (parsed) {
            if (author && parsed.userId !== author) return null;
            const memoryBlob = peekVaultBlob(parsed.userId, parsed.docId);
            if (memoryBlob) {
                try {
                    return objectUrlFromBlob(memoryBlob);
                } catch {
                    /* fall through */
                }
            }
            const blobUrl = await getVaultBlobObjectUrl(parsed.userId, parsed.docId, {
                mimeType: isPdfDoc ? 'application/pdf' : doc.mimeType,
            });
            if (blobUrl) return blobUrl;
        }
        return cached && !cached.startsWith('blob:') ? cached : null;
    }

    if (path.startsWith('local:vault:')) {
        return cached;
    }

    if (path && !path.startsWith('local:')) {
        try {
            const remote = sanitizeVaultPreviewUrl(await SmartVaultDB.getSignedUrl(path));
            if (remote) return remote;
        } catch {
            /* fall through */
        }
    }
    return cached;
}

const VAULT_VIEW_RESOLVE_TIMEOUT_MS = 14_000;
const VAULT_VIEW_IDB_RETRY_MS = 6_000;

function isVaultPdfDoc(doc: SmartVaultDoc): boolean {
    return (
        doc.type === 'pdf' ||
        (doc.mimeType || '').toLowerCase() === 'application/pdf' ||
        /\.pdf$/i.test(doc.fileName || doc.title || '')
    );
}

function createVaultBlobPreviewUrl(blob: Blob, doc: SmartVaultDoc): string {
    if (isVaultPdfDoc(doc) && blob.type !== 'application/pdf') {
        return URL.createObjectURL(new Blob([blob], { type: 'application/pdf' }));
    }
    return URL.createObjectURL(blob);
}

function rejectVaultViewAfter<T>(ms: number): Promise<T> {
    return new Promise((_, reject) => {
        window.setTimeout(() => reject(new Error('vault view resolve timeout')), ms);
    });
}

async function resolveVaultDocBlobAndUrl(
    doc: SmartVaultDoc,
): Promise<{ blob: Blob | null; url: string | null }> {
    const blob = await resolveVaultDocBlob(doc);
    let url = await resolveVaultDocUrl(doc);
    if (!url && blob) {
        try {
            url = createVaultBlobPreviewUrl(blob, doc);
        } catch {
            url = null;
        }
    }
    return { blob, url };
}

export type VaultDocViewPayload = {
    doc: SmartVaultDoc;
    url: string;
    blob: Blob | null;
    kind: VaultDocViewerKind;
    revokeOnClose: boolean;
};

export async function resolveVaultDocForViewing(
    doc: SmartVaultDoc,
): Promise<VaultDocViewPayload | null> {
    if (!vaultDocStorageOwned(doc)) return null;
    prefetchVaultBlobStore();

    let { blob, url } = await Promise.race([
        resolveVaultDocBlobAndUrl(doc),
        rejectVaultViewAfter<{ blob: Blob | null; url: string | null }>(VAULT_VIEW_RESOLVE_TIMEOUT_MS),
    ]).catch(() => ({ blob: null as Blob | null, url: null as string | null }));

    if (!url && isVaultIdbStoragePath(doc.storagePath || '')) {
        await Promise.race([
            waitForVaultBlobWrites(),
            new Promise<void>((resolve) => window.setTimeout(resolve, VAULT_VIEW_IDB_RETRY_MS)),
        ]);
        const retry = await Promise.race([
            resolveVaultDocBlobAndUrl(doc),
            rejectVaultViewAfter<{ blob: Blob | null; url: string | null }>(VAULT_VIEW_RESOLVE_TIMEOUT_MS),
        ]).catch(() => ({ blob, url }));
        blob = retry.blob ?? blob;
        url = retry.url ?? url;
    }

    if (!url) {
        url = sanitizeVaultPreviewUrl(doc.signedUrl);
    }

    const path = doc.storagePath?.trim() || '';
    if (!url && path && !isVaultIdbStoragePath(path) && !path.startsWith('local:')) {
        try {
            url = sanitizeVaultPreviewUrl(await SmartVaultDB.getSignedUrl(path));
        } catch {
            /* fall through */
        }
    }

    url = sanitizeVaultPreviewUrl(url);
    if (!url) return null;

    const kind = resolveVaultMediaKind(doc);
    const cached = doc.signedUrl?.trim() || '';
    const revokeOnClose = url.startsWith('blob:') && url !== cached;

    return { doc, url, blob, kind, revokeOnClose };
}

const PDF_VIEWER_PREP_TIMEOUT_MS = 12_000;

export async function toVaultPdfViewerUrl(url: string): Promise<string> {
    if (!sanitizeVaultPreviewUrl(url)) {
        throw new Error('unsafe vault preview url');
    }
    const prepare = async (): Promise<string> => {
        if (url.startsWith('http://') || url.startsWith('https://')) {
            return url;
        }
        if (url.startsWith('blob:')) {
            const res = await fetch(url);
            const blob = await res.blob();
            if (blob.type === 'application/pdf') return url;
            return URL.createObjectURL(new Blob([blob], { type: 'application/pdf' }));
        }
        const res = await fetch(url);
        const blob = await res.blob();
        const pdfBlob =
            blob.type === 'application/pdf' ? blob : new Blob([blob], { type: 'application/pdf' });
        return URL.createObjectURL(pdfBlob);
    };

    return Promise.race([
        prepare(),
        new Promise<string>((_, reject) => {
            window.setTimeout(() => reject(new Error('pdf viewer prep timeout')), PDF_VIEWER_PREP_TIMEOUT_MS);
        }),
    ]);
}

export async function downloadVaultDocToDevice(
    doc: SmartVaultDoc,
    opts?: { fileUrl?: string | null; fileBlob?: Blob | null },
): Promise<void> {
    const safeFileUrl = sanitizeVaultPreviewUrl(opts?.fileUrl);
    const blob =
        opts?.fileBlob ??
        (safeFileUrl ? await fetch(safeFileUrl).then((r) => r.blob()).catch(() => null) : null) ??
        (await resolveVaultDocBlob(doc));
    if (!blob) throw new Error('vault download unavailable');
    const url = URL.createObjectURL(blob);
    const anchor = document.createElement('a');
    anchor.href = url;
    anchor.download = doc.fileName || doc.title || 'vault-doc';
    anchor.click();
    URL.revokeObjectURL(url);
}

import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { docMatchesCategoryFilter } from '@/app/services/vaultCustomCategories';
import { isAllowedVaultImageMeta, isScriptableVaultMedia } from '@/app/services/vault/vaultPreviewUrlSafety';
import { archiveTextMatchesQuery } from '@/app/services/search/normalizeArabicSearch';
import { clampGlobalSearchQuery } from '@/app/services/search/globalSearchQuerySecurity';

export function inferDocType(mimeType: string, fileName?: string): 'pdf' | 'image' {
    const mime = (mimeType || '').toLowerCase();
    const name = fileName || '';
    if (isAllowedVaultImageMeta(mime, name)) return 'image';
    if (mime === 'application/pdf' || /\.pdf$/i.test(name)) return 'pdf';
    return 'pdf';
}

export type VaultMediaKind = 'image' | 'pdf' | 'audio' | 'file';

export function resolveVaultMediaKind(doc: SmartVaultDoc): VaultMediaKind {
    const mime = (doc.mimeType || '').toLowerCase();
    const name = (doc.fileName || doc.title || '').toLowerCase();

    if (
        !isScriptableVaultMedia(mime, name) &&
        (doc.type === 'image' || isAllowedVaultImageMeta(mime, name))
    ) {
        return 'image';
    }
    if (mime.startsWith('audio/') || /\.(mp3|wav|m4a|ogg|aac|webm|flac)$/i.test(name)) {
        return 'audio';
    }
    if (doc.type === 'pdf' || mime === 'application/pdf' || /\.pdf$/i.test(name)) {
        return 'pdf';
    }
    return 'file';
}

export function vaultMediaKindLabel(kind: VaultMediaKind): string {
    switch (kind) {
        case 'image':
            return 'صورة';
        case 'pdf':
            return 'PDF';
        case 'audio':
            return 'صوت';
        default:
            return 'ملف';
    }
}

export function inferTags(title: string): string[] {
    const tags: string[] = [];
    if (/عقد|إيجار/.test(title)) tags.push('عقود');
    if (/طابو|تمليك/.test(title)) tags.push('طابو');
    if (/عريضة|عرائض|مرافعات|تعويض/.test(title)) tags.push('عرائض');
    if (tags.length === 0) {
        if (/بحث|مذكرة|دراسة/.test(title)) tags.push('بحث قانوني');
        else if (/حكم|قرار|تمييز/.test(title)) tags.push('قرار حكم');
        else tags.push('أخرى');
    }
    return tags;
}

export function formatFileSize(bytes: number): string {
    if (!bytes || bytes === 0) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i];
}

export function formatVaultDate(dateStr: string): string {
    try {
        const d = new Date(dateStr);
        const now = new Date();
        const diff = now.getTime() - d.getTime();
        const days = Math.floor(diff / (1000 * 60 * 60 * 24));
        if (days === 0) return 'اليوم';
        if (days === 1) return 'أمس';
        if (days < 7) return `منذ ${days} أيام`;
        return d.toLocaleDateString('ar-IQ', { month: 'short', day: 'numeric' });
    } catch {
        return dateStr;
    }
}

export function vaultDocMatchesSearch(doc: SmartVaultDoc, query: string): boolean {
    const q = clampGlobalSearchQuery(query);
    if (!q.trim()) return true;
    const hay = [
        doc.title,
        doc.customCategory ?? '',
        ...doc.tags,
        doc.lawyerNote ?? '',
        doc.aiSummary ?? '',
        doc.extractedText ?? '',
        doc.fileName ?? '',
    ].join(' ');
    return archiveTextMatchesQuery(hay, q);
}

export function filterVaultDocs(
    docs: SmartVaultDoc[],
    activeFilter: string,
    searchQuery: string,
): SmartVaultDoc[] {
    return docs.filter(
        (doc) => docMatchesCategoryFilter(doc, activeFilter) && vaultDocMatchesSearch(doc, searchQuery),
    );
}

export function revokeBlobUrlIfNeeded(url: string | null | undefined): void {
    if (!url?.startsWith('blob:')) return;
    try {
        URL.revokeObjectURL(url);
    } catch {
        /* ignore */
    }
}

/** دمج قوائم وثائق المخزن — يحافظ على signedUrl الأحدث */
export function mergeSmartVaultDocs(base: SmartVaultDoc[], overlay: SmartVaultDoc[]): SmartVaultDoc[] {
    const map = new Map<string, SmartVaultDoc>();
    for (const d of base) map.set(d.id, d);
    for (const d of overlay) {
        const prev = map.get(d.id);
        if (!prev) {
            map.set(d.id, d);
            continue;
        }
        const prevTime = Number.isFinite(Date.parse(prev.updatedAt)) ? Date.parse(prev.updatedAt) : 0;
        const nextTime = Number.isFinite(Date.parse(d.updatedAt)) ? Date.parse(d.updatedAt) : 0;
        const winner = nextTime >= prevTime ? d : prev;
        const other = nextTime >= prevTime ? prev : d;
        map.set(d.id, {
            ...winner,
            signedUrl: winner.signedUrl ?? other.signedUrl ?? null,
            storagePath: winner.storagePath || other.storagePath,
        });
    }
    return Array.from(map.values());
}

/**
 * شواهد قبر وثائق الخزنة — ذاكرة فقط أمام حارس المسح.
 * التشفير عبر جسر SecureStore بعد الربط، بلا دائرة استيراد.
 */
import { createDeletedIdsLiteStore } from '@/app/services/storage/deletedIdsLiteStore';

export const VAULT_DELETED_IDS_KEY = 'hami:smartvault:deleted:v1';

const store = createDeletedIdsLiteStore(VAULT_DELETED_IDS_KEY, (k) => k.includes(':'));

function vaultDocTombstoneKey(authorId: string, docId: string): string {
    return `${authorId.trim()}:${docId.trim()}`;
}

/** يُسجّل حذفاً محلياً — يمنع إعادة دمج الملف من KV/القرص */
export function markVaultDocDeleted(authorId: string, docId: string): void {
    const author = authorId.trim();
    const id = docId.trim();
    if (!author || !id) return;
    store.add([vaultDocTombstoneKey(author, id)]);
}

export function isVaultDocDeleted(authorId: string, docId: string): boolean {
    const author = authorId.trim();
    const id = docId.trim();
    if (!author || !id) return false;
    return store.has(vaultDocTombstoneKey(author, id));
}

export function filterDeletedVaultDocs<T extends { id: string; authorId: string }>(docs: T[]): T[] {
    const keys = store.read();
    if (keys.size === 0) return docs;
    return docs.filter((d) => !keys.has(vaultDocTombstoneKey(d.authorId, d.id)));
}

/** هل كل وثائق القرص عليها tombstone؟ — يسمح بمسح `[]` عبر wipe-guard */
export function areAllStoredVaultDocsTombstoned(existingRaw: string | null | undefined): boolean {
    if (!existingRaw?.trim()) return true;
    try {
        const parsed: unknown = JSON.parse(existingRaw);
        if (!Array.isArray(parsed) || parsed.length === 0) return true;
        return parsed.every((item) => {
            if (!item || typeof item !== 'object') return false;
            const id = (item as { id?: unknown }).id;
            const authorId = (item as { authorId?: unknown }).authorId;
            if (id == null || typeof authorId !== 'string' || !authorId.trim()) return false;
            return isVaultDocDeleted(authorId, String(id));
        });
    } catch {
        return false;
    }
}

/** للاختبارات فقط */
export function resetVaultDocsTombstonesForTests(): void {
    store.resetForTests();
}

import { SmartVaultDB } from '@/app/services/vault/smartVaultRuntime';
import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { mergeSmartVaultDocs } from '@/app/services/vault/vaultDocUtils';
import { readVaultLocalIndexSync } from '@/app/services/vault/vaultLocalIndex';
import {
    mergeVaultDocsWarmCache,
    sortVaultDocs,
    SMART_VAULT_DOCS_UPDATED_EVENT,
    vaultDocsWarmCacheStore as cache,
    vaultDocsWarmInflightStore as inflight,
} from '@/app/services/vault/vaultDocsWarmState';
export {
    invalidateVaultDocsWarmCache,
    mergeVaultDocsWarmCache,
    peekVaultDocsWarmCache,
    removeVaultDocFromWarmCache,
    setVaultDocsWarmCache,
    SMART_VAULT_DOCS_UPDATED_EVENT,
} from '@/app/services/vault/vaultDocsWarmState';

export function notifySmartVaultDocsUpdated(userId: string, docs?: SmartVaultDoc[]): void {
    if (typeof window === 'undefined') return;
    const uid = userId.trim();
    if (!uid) return;
    window.dispatchEvent(
        new CustomEvent(SMART_VAULT_DOCS_UPDATED_EVENT, {
            detail: {
                userId: uid,
                docs: docs ?? [],
            },
        }),
    );
}

function settleVaultDocsFailure(uid: string): SmartVaultDoc[] {
    return cache.get(uid) ?? [];
}

async function loadVaultDocsIntoCache(uid: string): Promise<SmartVaultDoc[]> {
    const pending = inflight.get(uid);
    if (pending) return pending;

    const run = SmartVaultDB.listDocs(uid)
        .then((fetched) => {
            const live = cache.get(uid);
            const merged = live?.length ? mergeSmartVaultDocs(live, fetched) : fetched;
            const sorted = sortVaultDocs(merged);
            cache.set(uid, sorted);
            return sorted;
        })
        .catch(() => settleVaultDocsFailure(uid))
        .finally(() => {
            inflight.delete(uid);
        });

    inflight.set(uid, run);
    return run;
}

/** جلب وثائق المخزن مع dedupe — لا يرفض أبداً (يُعيد [] عند الفشل) */
export function fetchVaultDocsDeduped(userId: string): Promise<SmartVaultDoc[]> {
    const uid = userId.trim();
    if (!uid) return Promise.resolve([]);
    const cached = cache.get(uid);
    if (cached?.length) {
        void loadVaultDocsIntoCache(uid).catch(() => undefined);
        return Promise.resolve(cached);
    }
    return loadVaultDocsIntoCache(uid).catch(() => cache.get(uid) ?? []);
}

/** انتظار تحديث كامل من التخزين — للواجهة التي تحتاج قائمة محدّثة */
export function refreshVaultDocsFromStore(userId: string): Promise<SmartVaultDoc[]> {
    const uid = userId.trim();
    if (!uid) return Promise.resolve([]);
    return loadVaultDocsIntoCache(uid).catch(() => cache.get(uid) ?? []);
}

/** بذر الكاش الدافئ من الفهرس المحلي الفوري */
export function seedVaultWarmCacheFromLocalIndex(userId: string): SmartVaultDoc[] {
    const uid = userId.trim();
    if (!uid) return [];
    const local = readVaultLocalIndexSync().filter((d) => d.authorId === uid);
    if (!local.length) return cache.get(uid) ?? [];
    return mergeVaultDocsWarmCache(uid, local);
}

/** تحميل مسبق لوثائق المخزن — يُستخدم عند hover/تشغيل اللوحة */
export function prefetchSmartVaultDocs(userId?: string | null): void {
    const uid = userId?.trim();
    if (!uid || typeof window === 'undefined') return;
    if (cache.get(uid)?.length) return;
    if (inflight.has(uid)) return;
    void loadVaultDocsIntoCache(uid).catch(() => undefined);
}

import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { mergeSmartVaultDocs } from '@/app/services/vault/vaultDocUtils';

export const SMART_VAULT_DOCS_UPDATED_EVENT = 'hami:smart-vault-docs-updated';

export const vaultDocsWarmCacheStore = new Map<string, SmartVaultDoc[]>();
export const vaultDocsWarmInflightStore = new Map<string, Promise<SmartVaultDoc[]>>();

export function sortVaultDocs(docs: SmartVaultDoc[]): SmartVaultDoc[] {
    return [...docs].sort((a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime());
}

export function peekVaultDocsWarmCache(userId: string): SmartVaultDoc[] | undefined {
    const uid = userId.trim();
    return uid ? vaultDocsWarmCacheStore.get(uid) : undefined;
}

export function setVaultDocsWarmCache(userId: string, docs: SmartVaultDoc[]): void {
    const uid = userId.trim();
    if (uid) vaultDocsWarmCacheStore.set(uid, sortVaultDocs(docs));
}

export function mergeVaultDocsWarmCache(userId: string, docs: SmartVaultDoc[]): SmartVaultDoc[] {
    const uid = userId.trim();
    if (!uid) return docs;
    const prev = vaultDocsWarmCacheStore.get(uid) ?? [];
    const merged = sortVaultDocs(mergeSmartVaultDocs(prev, docs));
    vaultDocsWarmCacheStore.set(uid, merged);
    return merged;
}

export function removeVaultDocFromWarmCache(userId: string, docId: string): SmartVaultDoc[] {
    const uid = userId.trim();
    const id = docId.trim();
    if (!uid || !id) return [];
    const next = (vaultDocsWarmCacheStore.get(uid) ?? []).filter((doc) => doc.id !== id);
    vaultDocsWarmCacheStore.set(uid, next);
    vaultDocsWarmInflightStore.delete(uid);
    return next;
}

export function invalidateVaultDocsWarmCache(userId?: string): void {
    if (userId?.trim()) vaultDocsWarmCacheStore.delete(userId.trim());
    else vaultDocsWarmCacheStore.clear();
}

import { isAllowedVaultImageMeta, isScriptableVaultMedia } from '@/app/services/vault/vaultPreviewUrlSafety';

export const VAULT_MAX_FILE_SIZE = 50 * 1024 * 1024;

export type VaultUploadKind = 'image' | 'pdf';

export function isVaultImageFile(file: File): boolean {
    return isAllowedVaultImageMeta(file.type || '', file.name);
}

export function isVaultPdfFile(file: File): boolean {
    const mime = (file.type || '').toLowerCase();
    const name = file.name.toLowerCase();
    if (isScriptableVaultMedia(mime, name)) return false;
    return mime === 'application/pdf' || name.endsWith('.pdf');
}

export function reportVaultPersistFailure(err: unknown, fileLabel: string): string {
    if (err instanceof Error && err.message === 'vault persist failed') {
        return 'تعذر حفظ الملف على الجهاز — قد تكون مساحة التخزين ممتلئة';
    }
    if (err instanceof Error && err.message === 'vault blob write timeout') {
        return `استغرق حفظ ${fileLabel} وقتاً طويلاً — جرّب ملفاً أصغر أو أعد المحاولة`;
    }
    if (err instanceof Error && err.message === 'vault save timeout') {
        return `استغرق رفع ${fileLabel} وقتاً طويلاً — أعد المحاولة`;
    }
    if (err instanceof Error && err.message === 'file too large') {
        return 'يتجاوز الحد الأقصى 50MB';
    }
    return `فشل حفظ ${fileLabel}`;
}

