    markVaultDocDeleted,
} from '@/app/services/vault/vaultDocsTombstonesLite';

export const VAULT_LOCAL_KEY = 'hami:smartvault:docs:v1';
/*
 * مرآة قديمة نصّاً صريحاً — تُقرأ مرّة للترحيل ثم تُمحى، ولا يُكتب فيها بعد اليوم.
 *
 * كانت المرآة موجودة لتُتيح قراءة متزامنة بلا انتظار IndexedDB، وكانت أوسع ثقب في
 * المخزن: فهرسٌ فيه أسماء مستندات الموكّلين على القرص بلا تشفير، في أسهل موضع
 * وصولاً. وحين شُفِّر الفهرس بقيت المرآة تنسخه صريحاً — فالتشفير معها زينة.
 *
 * بديلها ليس جديداً: `memoryDocs` هنا، و`decryptedCache` في `SecureStoreService`
 * تُملأ من تسخين مفاتيح القشرة. فالقراءة المتزامنة قائمة على الذاكرة لا على القرص،
 * وهو ما كان يجب أن تكون عليه من البداية.
 */
const VAULT_LEGACY_PLAINTEXT_MIRROR_KEY = 'hami:smartvault:mirror:v1';

const PERSIST_DEBOUNCE_MS = 350;

let memoryDocs: SmartVaultDoc[] | null = null;
let persistTimer: ReturnType<typeof setTimeout> | null = null;
let persistChain: Promise<void> = Promise.resolve();

/** فهرس خفيف — بدون data URLs ضخمة (الملفات في IDB منفصلة) */
export function normalizeVaultDocForLocalPersist(doc: SmartVaultDoc): SmartVaultDoc {
    const path = doc.storagePath || '';
    if (isVaultIdbStoragePath(path)) {
        return { ...doc, signedUrl: null };
    }
    const signed = doc.signedUrl?.trim() || '';
    if (path.startsWith('local:vault:') && signed.startsWith('data:') && signed.length > 96_000) {
        return { ...doc, signedUrl: null };
    }
    return doc;
}

/**
 * يقرأ المرآة الصريحة القديمة ويمحوها في النفس نفسه.
 *
 * القراءة لأجل الترحيل وحده: جهازٌ حدّث التطبيق قد يحمل فهرسه هنا فقط. والمحو
 * فوراً لأن تركها يعني إبقاء الأسماء صريحةً على القرص إلى الأبد — وهي الحال التي
 * جاء هذا التغيير ليُنهيها. الناتج يُعاد كتابته مشفَّراً في مسار الحفظ العادي.
 */
function drainLegacyPlaintextMirror(): string | null {
    if (typeof localStorage === 'undefined') return null;
    try {
        const raw = localStorage.getItem(VAULT_LEGACY_PLAINTEXT_MIRROR_KEY);
        if (raw !== null) localStorage.removeItem(VAULT_LEGACY_PLAINTEXT_MIRROR_KEY);
        return raw;
    } catch {
        return null;
    }
}

function parseVaultDocsPayload(raw: string | null | undefined): SmartVaultDoc[] {
    if (!raw) return [];
    try {
        const parsed = JSON.parse(raw);
        return Array.isArray(parsed) ? (parsed as SmartVaultDoc[]) : [];
    } catch {
        return [];
    }
}

/** قراءة متزامنة من الذاكرة أو المرآة أو الكاش — بدون انتظار IndexedDB */
export function readVaultLocalIndexSync(): SmartVaultDoc[] {
    if (memoryDocs !== null) return memoryDocs;
    /*
     * الترحيل مرّة واحدة: ما وجدناه في المرآة القديمة يُعاد حفظه مشفَّراً، والمرآة
     * تُمحى في القراءة نفسها. لا يُنتظر الحفظ — القراءة متزامنة بحكم عقدها.
     */
    const legacy = parseVaultDocsPayload(drainLegacyPlaintextMirror());
    if (legacy.length > 0) {
        memoryDocs = legacy;
        scheduleVaultLocalIndexPersist(legacy);
        return legacy;
    }
    const parsed = parseVaultDocsPayload(readSecureOrDrainLegacySync(VAULT_LOCAL_KEY));
    if (parsed.length > 0) memoryDocs = parsed;
    return parsed;
}

export async function readVaultLocalIndex(): Promise<SmartVaultDoc[]> {
    if (memoryDocs !== null) return memoryDocs;
    const sync = readVaultLocalIndexSync();
    if (sync.length > 0) return sync;
    try {
        const raw = await SecureStoreService.getItem(VAULT_LOCAL_KEY);
        if (!raw) {
            memoryDocs = [];
            return memoryDocs;
        }
        memoryDocs = parseVaultDocsPayload(raw);
        return memoryDocs;
    } catch {
        memoryDocs = [];
        return memoryDocs;
    }
}

export function peekVaultLocalIndex(): SmartVaultDoc[] | null {
    return memoryDocs;
}

export function writeVaultLocalIndexSync(docs: SmartVaultDoc[]): void {
    memoryDocs = docs;
}

function mergeVaultLocalDoc(current: SmartVaultDoc[], doc: SmartVaultDoc): SmartVaultDoc[] {
    const idx = current.findIndex((d) => d.id === doc.id);
    if (idx < 0) return [doc, ...current];
    const prev = current[idx]!;
    const next = [...current];
    next[idx] = {
        ...prev,
        ...doc,
        signedUrl: doc.signedUrl ?? prev.signedUrl ?? null,
        storagePath: doc.storagePath || prev.storagePath,
    };
    return next;
}

function writeVaultIndexPayload(docs: SmartVaultDoc[]): void {
    const payload = JSON.stringify(docs.map(normalizeVaultDocForLocalPersist));
    /*
     * `setItemSync` تُحدّث `decryptedCache` فوراً ثم تُشفّر وتحفظ في IndexedDB خلفياً.
     * فالقراءة المتزامنة التالية تجدها في الذاكرة — وهو ما كانت المرآة الصريحة تفعله،
     * بلا نسخة على القرص.
     */
    writeSecureAndClearLegacySync(VAULT_LOCAL_KEY, payload);
}

/**
 * تحديث فوري في الذاكرة + الكاش المتزامن — لا ينتظر ensureWebReady/IDB.
 * يُستخدم في مسار الحفظ الحرج (رفع ملف، مسح، بطاقة).
 */
export function upsertVaultLocalIndexDocImmediate(doc: SmartVaultDoc): SmartVaultDoc[] {
    if (persistTimer) {
        clearTimeout(persistTimer);
        persistTimer = null;
    }
    const base = memoryDocs ?? readVaultLocalIndexSync();
    memoryDocs = mergeVaultLocalDoc(mergeSmartVaultDocs(base, []), doc);
    writeVaultIndexPayload(memoryDocs);
    return memoryDocs;
}

async function loadVaultLocalIndexFromStore(): Promise<SmartVaultDoc[]> {
    const sync = readVaultLocalIndexSync();
    if (sync.length > 0) return sync;
    try {
        const raw = await SecureStoreService.getItem(VAULT_LOCAL_KEY);
        return parseVaultDocsPayload(raw);
    } catch {
        return [];
    }
}

function persistVaultLocalIndexNow(docs: SmartVaultDoc[]): void {
    // memoryDocs هو المصدر الحقيقي — لا دمج مع قراءة قديمة من القرص (يعيد الملفات المحذوفة)
    const snapshot = memoryDocs ?? docs;
    memoryDocs = snapshot;
    writeVaultIndexPayload(snapshot);
}

async function persistVaultLocalIndexToDisk(docs: SmartVaultDoc[]): Promise<void> {
    persistVaultLocalIndexNow(docs);
    const payload = JSON.stringify((memoryDocs ?? docs).map(normalizeVaultDocForLocalPersist));
    /*
     * لا `Promise.race` يحلّ عند المهلة: ذلك كان يُعلن نجاحاً والقرص ما زال
     * خلف IndexedDB. `setItemSync` حدّث الكاش؛ هذا الانتظار هو الكتابة الفعلية.
     * لا تخطَّ الكتابة إن طابق الكاش — وإلا لن تُستدعى `setItem` بعد `setItemSync`.
     */
    await SecureStoreService.setItem(VAULT_LOCAL_KEY, payload);
    clearLegacyPlaintextMirror(VAULT_LOCAL_KEY);
}

/** حفظ فوري في الذاكرة ثم انتظار IndexedDB — بلا مهلة تُحسب نجاحاً */
export async function upsertVaultLocalIndexDocAndFlush(doc: SmartVaultDoc): Promise<void> {
    upsertVaultLocalIndexDocImmediate(doc);
    const snapshot = memoryDocs ?? [doc];
    await persistVaultLocalIndexToDisk(snapshot).catch(() => {
        scheduleVaultLocalIndexPersist(snapshot);
    });
}

/** تحديث فوري في الذاكرة — للمسارات غير الحرجة */
export function upsertVaultLocalIndexDoc(doc: SmartVaultDoc): void {
    upsertVaultLocalIndexDocImmediate(doc);
    scheduleVaultLocalIndexPersist(memoryDocs ?? [doc]);
}

export function removeVaultLocalIndexDoc(docId: string, authorId?: string): SmartVaultDoc[] {
    const id = docId.trim();
    if (!id) return memoryDocs ?? [];
    const current = memoryDocs ?? readVaultLocalIndexSync();
    const next = current.filter((d) => d.id !== id || (authorId ? d.authorId !== authorId : false));
    memoryDocs = next;
    if (authorId?.trim()) {
        markVaultDocDeleted(authorId, id);
    }
    writeVaultIndexPayload(next);
    scheduleVaultLocalIndexPersist(next);
    return next;
}

export function scheduleVaultLocalIndexPersist(docs: SmartVaultDoc[]): void {
    memoryDocs = memoryDocs?.length ? mergeSmartVaultDocs(docs, memoryDocs) : docs;
    if (persistTimer) clearTimeout(persistTimer);
    persistTimer = setTimeout(() => {
        persistTimer = null;
        const snapshot = memoryDocs ?? docs;
        persistChain = persistChain
            .then(() => persistVaultLocalIndexToDisk(snapshot))
            .catch(() => undefined);
    }, PERSIST_DEBOUNCE_MS);
}

export async function flushVaultLocalIndexPersist(): Promise<void> {
    if (persistTimer) {
        clearTimeout(persistTimer);
        persistTimer = null;
    }
    const snapshot = memoryDocs;
    if (!snapshot) return;
    persistVaultLocalIndexNow(snapshot);
    await persistVaultLocalIndexToDisk(snapshot).catch(() => {
        scheduleVaultLocalIndexPersist(snapshot);
    });
}

export function queueVaultLocalIndexPersist(docs: SmartVaultDoc[]): void {
    memoryDocs = docs;
    writeVaultIndexPayload(docs);
    persistChain = persistChain
        .then(() => persistVaultLocalIndexToDisk(docs))
        .catch(() => undefined);
}

/** للاختبارات */
export function resetVaultLocalIndexForTests(): void {
    memoryDocs = null;
    resetVaultDocsTombstonesForTests();
    if (persistTimer) clearTimeout(persistTimer);
    persistTimer = null;
    persistChain = Promise.resolve();
    if (typeof localStorage !== 'undefined') {
        localStorage.removeItem(VAULT_LEGACY_PLAINTEXT_MIRROR_KEY);
    }
}

if (typeof document !== 'undefined' && !import.meta.env.VITEST) {
    const flush = () => void flushVaultLocalIndexPersist();
    let hiddenFlushTimer: number | null = null;
    document.addEventListener('visibilitychange', () => {
        if (document.visibilityState !== 'hidden') {
            if (hiddenFlushTimer !== null) {
                window.clearTimeout(hiddenFlushTimer);
                hiddenFlushTimer = null;
            }
            return;
        }
        if (hiddenFlushTimer !== null) window.clearTimeout(hiddenFlushTimer);
        hiddenFlushTimer = window.setTimeout(() => {
            hiddenFlushTimer = null;
            if (document.visibilityState === 'hidden') flush();
        }, 900);
    });
    window.addEventListener('pagehide', () => {
        if (hiddenFlushTimer !== null) {
            window.clearTimeout(hiddenFlushTimer);
            hiddenFlushTimer = null;
        }
        flush();
    });
}

/** حراسة ملكية مستندات المخزن — كل طفرة تمر عبر المطابقة authorId === الجلسة */

export function assertVaultRequester(requesterId: string | null | undefined): asserts requesterId is string {
    if (!requesterId?.trim()) {
        throw new Error('مطلوب تسجيل الدخول لإجراءاء عملية المخزن');
    }
}

export function assertVaultDocOwner(
    doc: { authorId?: string | null },
    requesterId: string | null | undefined,
): void {
    assertVaultRequester(requesterId);
    const author = (doc.authorId ?? '').trim();
    if (!author) {
        throw new Error('authorId مطلوب لحفظ الملف');
    }
    if (author !== requesterId.trim()) {
        throw new Error('غير مصرح بالوصول إلى ملف مستخدم آخر');
    }
}

/** مسار تخزين سحابي أو idb يجب أن يعود لنفس المستخدم */
export function assertVaultStoragePathOwner(
    storagePath: string | null | undefined,
    requesterId: string,
): void {
    assertVaultRequester(requesterId);
    const path = (storagePath ?? '').trim();
    if (!path) return;

    if (path.startsWith('idb:vault:')) {
        const parts = path.split(':');
        // idb:vault:userId:docId
        if (parts.length >= 4) {
            const pathUser = parts[2] ?? '';
            if (pathUser && pathUser !== requesterId.trim()) {
                throw new Error('غير مصرح بالوصول إلى مسار تخزين مستخدم آخر');
            }
        }
        return;
    }

    if (path.startsWith('local:vault:')) {
        const parts = path.split(':');
        // local:vault:userId:… فقط — المسارات المختصرة القديمة بلا userId تُ defer إلى authorId
        if (parts.length >= 4) {
            const pathUser = parts[2] ?? '';
            if (pathUser && pathUser !== requesterId.trim()) {
                throw new Error('غير مصرح بالوصول إلى مسار تخزين مستخدم آخر');
            }
        }
        return;
    }

    const normalized = path.replace(/^\/+/, '');
    if (normalized.includes('..') || normalized.includes('\\')) {
        throw new Error('مسار تخزين غير صالح');
    }
    if (!normalized.startsWith(`${requesterId.trim()}/`)) {
        throw new Error('غير مصرح بالوصول إلى مسار تخزين مستخدم آخر');
    }
}

/**
 * أصول pdf.js تُقدَّم من أصل التطبيق حصراً.
 *
 * كان الإنتاج يجلب `pdf.worker` من cdn.jsdelivr.net افتراضياً: شيفرة طرف ثالث
 * تُنفَّذ داخل أصلنا وتمرّ عليها مستندات الموكّلين، بلا SRI (وهي غير ممكنة على
 * العمّال أصلاً). أي اختراق للـCDN أو اختطاف DNS يعني تنفيذاً عن بُعد فوق
 * إضابير محامٍ. الملفات محلية ولا تُجلب إلا عند فتح PDF، فالمقابل معدوم.
 */

/** يُشحن standard_fonts إلا إذا استُثني صراحةً لتصغير حجم النشر */
function shipsStandardFonts(): boolean {
    return import.meta.env.VITE_PDF_MINIMAL_ASSETS !== 'true';
}

/**
 * خرائط CJK (~1.1MB) تُحذف من نشر أندرويد المصغّر.
 * PDF عربي بخط مضمّن يبقى صالحاً؛ مستند CID صيني/ياباني قد يفقد خريطة الحروف.
 */

export function resolvePdfJsWorkerUrl(): string {
    return '/pdfjs-assets/pdf.worker.min.mjs';
}

export function resolvePdfCmapUrl(): string {
    return '/pdfjs-assets/cmaps/';
}

export function resolvePdfStandardFontUrl(): string | undefined {
    return shipsStandardFonts() ? '/pdfjs-assets/standard_fonts/' : undefined;
}

import {
    classifyVaultPdfLoadError,
    VaultPdfLoadError,
    type VaultPdfLoadErrorKind,
    type VaultPdfSource,
} from '@/app/services/vault/vaultPdfDocumentTypes';
import { resolvePdfCmapUrl, resolvePdfStandardFontUrl } from '@/app/services/vault/vaultPdfAssetUrls';
import { getVaultPdfJs } from '@/app/services/vault/vaultPdfRuntime';

export type { VaultPdfLoadErrorKind, VaultPdfSource };
export { VaultPdfLoadError, classifyVaultPdfLoadError };

const PDF_LOAD_TIMEOUT_MS = 20_000;

function isHttpUrl(value: string): boolean {
    return /^https?:\/\//i.test(value);
}

function pdfDocumentBaseOptions() {
    const standardFontDataUrl = resolvePdfStandardFontUrl();
    return {
        cMapUrl: resolvePdfCmapUrl(),
        cMapPacked: true,
        ...(standardFontDataUrl ? { standardFontDataUrl } : {}),
        isEvalSupported: false,
        useSystemFonts: true,
        stopAtErrors: false,
    };
}

async function readBytesFromBlob(blob: Blob): Promise<Uint8Array> {
    const normalized =
        blob.type === 'application/pdf' ? blob : new Blob([blob], { type: 'application/pdf' });
    const buffer = await normalized.arrayBuffer();
    if (!buffer.byteLength) throw new VaultPdfLoadError('invalid', 'pdf empty');
    return new Uint8Array(buffer);
}

async function readBytesFromUrl(url: string): Promise<Uint8Array> {
    const response = await fetch(url);
    const buffer = await response.arrayBuffer();
    if (!buffer.byteLength) throw new VaultPdfLoadError('invalid', 'pdf empty');
    return new Uint8Array(buffer);
}

function withTimeout<T>(promise: Promise<T>, ms: number, onTimeout?: () => void): Promise<T> {
    return new Promise<T>((resolve, reject) => {
        const timer = window.setTimeout(() => {
            onTimeout?.();
            reject(new VaultPdfLoadError('timeout', 'pdf load timeout'));
        }, ms);
        promise.then(
            (value) => {
                window.clearTimeout(timer);
                resolve(value);
            },
            (err) => {
                window.clearTimeout(timer);
                reject(err);
            },
        );
    });
}

async function loadOnce(source: VaultPdfSource) {
    const pdfjs = await getVaultPdfJs();
    const base = pdfDocumentBaseOptions();

    let task: import('pdfjs-dist').PDFDocumentLoadingTask;
    if (source instanceof Blob) {
        const data = await readBytesFromBlob(source);
        task = pdfjs.getDocument({ ...base, data, useWorkerFetch: false });
    } else if (isHttpUrl(source)) {
        task = pdfjs.getDocument({ ...base, url: source, withCredentials: false });
    } else {
        const data = await withTimeout(readBytesFromUrl(source), PDF_LOAD_TIMEOUT_MS);
        task = pdfjs.getDocument({ ...base, data, useWorkerFetch: false });
    }

    return withTimeout(task.promise, PDF_LOAD_TIMEOUT_MS, () => {
        void task.destroy().catch(() => {});
    });
}

/**
 * تحميل PDF — Blob محلياً، أو رابط https مباشرة، أو data/blob URL.
 * pdfjs-dist + worker يُحمَّلان عند أول فتح فقط (lazy).
 */
export async function loadVaultPdfDocument(source: VaultPdfSource) {
    try {
        return await loadOnce(source);
    } catch (err) {
        if (classifyVaultPdfLoadError(err) !== 'transient') throw err;
        await new Promise((resolve) => window.setTimeout(resolve, 300));
        return loadOnce(source);
    }
}

/**
 * تصنيف فشل تحميل PDF — يسمح للواجهة بتمييز الملف التالف/المحمي
 * (لا تنفع إعادة المحاولة) عن الفشل العابر (شبكة/worker — تنفع إعادة المحاولة).
 */
export type VaultPdfLoadErrorKind = 'password' | 'invalid' | 'timeout' | 'transient';

export type VaultPdfSource = string | Blob;

export class VaultPdfLoadError extends Error {
    readonly kind: VaultPdfLoadErrorKind;

    constructor(kind: VaultPdfLoadErrorKind, message: string, cause?: unknown) {
        super(message);
        this.name = 'VaultPdfLoadError';
        this.kind = kind;
        if (cause !== undefined) (this as { cause?: unknown }).cause = cause;
    }
}

export function classifyVaultPdfLoadError(err: unknown): VaultPdfLoadErrorKind {
    if (err instanceof VaultPdfLoadError) return err.kind;
    const name = String((err as { name?: unknown } | null)?.name ?? '');
    if (name === 'PasswordException') return 'password';
    if (name === 'InvalidPDFException') return 'invalid';
    const message = String((err as { message?: unknown } | null)?.message ?? '');
    if (/invalid pdf structure|pdf empty/i.test(message)) return 'invalid';
    return 'transient';
}

import type * as PdfJs from 'pdfjs-dist';
import { resolvePdfJsWorkerUrl } from '@/app/services/vault/vaultPdfAssetUrls';

type PdfJsModule = typeof PdfJs;

let pdfJsModulePromise: Promise<PdfJsModule> | null = null;
let workerConfigured = false;

async function loadPdfJsModule(): Promise<PdfJsModule> {
    if (!pdfJsModulePromise) {
        pdfJsModulePromise = (async () => {
            const pdfjs = await import('pdfjs-dist');
            if (!workerConfigured) {
                pdfjs.GlobalWorkerOptions.workerSrc = resolvePdfJsWorkerUrl();
                workerConfigured = true;
            }
            return pdfjs;
        })();
    }
    return pdfJsModulePromise;
}

export async function getVaultPdfJs(): Promise<PdfJsModule> {
    return loadPdfJsModule();
}

export function resetVaultPdfRuntimeForTests(): void {
    pdfJsModulePromise = null;
    workerConfigured = false;
}

import { loadVaultPdfDocument, type VaultPdfSource } from '@/app/services/vault/vaultPdfDocument';

const DEFAULT_MAX_CHARS = 12_000;

/** استخراج نص من PDF محلياً عبر pdf.js — بدون OCR */
export async function extractTextFromVaultPdf(
    source: VaultPdfSource,
    maxChars: number = DEFAULT_MAX_CHARS,
): Promise<string> {
    const pdf = await loadVaultPdfDocument(source);
    const parts: string[] = [];
    try {
        for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
            const page = await pdf.getPage(pageNum);
            const content = await page.getTextContent();
            const pageText = content.items
                .map((item) => ('str' in item ? String(item.str ?? '') : ''))
                .join(' ')
                .replace(/\s+/g, ' ')
                .trim();
            if (pageText) parts.push(pageText);
            if (parts.join('\n').length >= maxChars) break;
        }
    } finally {
        await pdf.destroy().catch(() => {});
    }
    return parts.join('\n').slice(0, maxChars).trim();
}

const VAULT_IMAGE_MIME = new Set([
    'image/jpeg',
    'image/jpg',
    'image/png',
    'image/webp',
    'image/gif',
    'image/bmp',
    'image/heic',
    'image/heif',
]);

const SCRIPTABLE_NAME = /\.(svg|xml|html?|js|mjs|xhtml)$/i;

export function isScriptableVaultMedia(mimeType: string, fileName?: string): boolean {
    const mime = (mimeType || '').toLowerCase();
    const name = fileName || '';
    return (
        mime.includes('svg') ||
        mime.includes('xml') ||
        mime === 'text/html' ||
        mime === 'application/javascript' ||
        SCRIPTABLE_NAME.test(name)
    );
}

export function isAllowedVaultImageMeta(mimeType: string, fileName?: string): boolean {
    const mime = (mimeType || '').toLowerCase();
    const name = fileName || '';
    if (isScriptableVaultMedia(mime, name)) return false;
    if (VAULT_IMAGE_MIME.has(mime)) return true;
    return /\.(jpe?g|png|webp|gif|bmp|heic|heif)$/i.test(name);
}

const DATA_IMAGE =
    /^data:image\/(jpeg|jpg|png|webp|gif|bmp|heic|heif)[;,]/i;
const DATA_PDF = /^data:application\/pdf[;,]/i;
const DATA_AUDIO = /^data:audio\/[a-z0-9.+-]+[;,]/i;

/**
 * روابط معاينة المخزن المسموحة فقط — يمنع javascript: وdata:text/html وSVG.
 * blob: وhttps: وdata للصورة/PDF/الصوت. http فقط لـ localhost أثناء التطوير.
 */
export function isSafeVaultPreviewUrl(url: string | null | undefined): boolean {
    const value = (url || '').trim();
    if (!value) return false;
    const lower = value.toLowerCase();
    if (lower.startsWith('javascript:') || lower.startsWith('vbscript:')) return false;
    if (lower.startsWith('blob:')) return true;
    if (DATA_IMAGE.test(value) || DATA_PDF.test(value) || DATA_AUDIO.test(value)) return true;
    if (lower.startsWith('data:')) return false;
    try {
        const parsed = new URL(value, typeof window !== 'undefined' ? window.location.href : 'https://local.invalid');
        if (parsed.protocol === 'https:') return true;
        if (parsed.protocol === 'http:') {
            return parsed.hostname === 'localhost' || parsed.hostname === '127.0.0.1';
        }
        return false;
    } catch {
        return false;
    }
}

export function sanitizeVaultPreviewUrl(url: string | null | undefined): string | null {
    const value = (url || '').trim();
    return isSafeVaultPreviewUrl(value) ? value : null;
}

/** ملاحظة/وصف المخزن تُعرض كنص — تُزال الوسوم قبل التخزين */
export function sanitizeVaultPlainNote(note: string | null | undefined): string | null {
    if (note == null) return null;
    const stripped = String(note)
        .replace(/<[^>]*>/g, ' ')
        .replace(/javascript:/gi, '')
        .replace(/\s+/g, ' ')
        .trim();
    if (!stripped) return null;
    return stripped.slice(0, 8_000);
}

import type { SmartVaultDoc } from '@/app/services/vault/vaultTypes';
import { extractTextFromVaultPdf } from '@/app/services/vault/vaultPdfTextExtraction';
import { isVaultDocPdf, resolveVaultDocBlob } from '@/app/services/vault/vaultDocResolve';

const VAULT_EXTRACT_MAX_CHARS = 12_000;

/** يستخرج نصاً من مرفق خزنة — PDF محلياً عبر pdf.js؛ الصور بلا استخراج */
export async function extractTextFromVaultDoc(doc: SmartVaultDoc): Promise<string> {
    const existing = String(doc.extractedText ?? doc.aiSummary ?? '').trim();
    if (existing.length >= 24) return existing.slice(0, VAULT_EXTRACT_MAX_CHARS);

    const blob = await resolveVaultDocBlob(doc);
    if (!blob) return '';

    if (isVaultDocPdf(doc)) {
        try {
            return await extractTextFromVaultPdf(blob, VAULT_EXTRACT_MAX_CHARS);
        } catch {
            return '';
        }
    }

    return '';
}

