type RecognitionCtor = new () => {
    lang: string;
    continuous: boolean;
    interimResults: boolean;
    maxAlternatives: number;
    onresult: ((event: { resultIndex: number; results: { length: number; [i: number]: { isFinal?: boolean; [j: number]: { transcript?: string } | undefined } | undefined } }) => void) | null;
    onerror: (() => void) | null;
    start: () => void;
    stop: () => void;
};

function getRecognitionCtor(): RecognitionCtor | null {
    if (typeof window === 'undefined') return null;
    const w = window as Window & {
        SpeechRecognition?: RecognitionCtor;
        webkitSpeechRecognition?: RecognitionCtor;
    };
    return w.SpeechRecognition ?? w.webkitSpeechRecognition ?? null;
}

export function isSpeechRecognitionSupported(): boolean {
    return getRecognitionCtor() != null;
}

export type LiveTranscriptSession = {
    start: () => void;
    stop: () => void;
    getTranscript: () => string;
};

/** تحويل صوت → نص (Web Speech API) — يعمل offline على بعض المتصفحات */
export function createArabicTranscriptSession(
    onUpdate: (text: string, isFinal: boolean) => void,
): LiveTranscriptSession | null {
    const Ctor = getRecognitionCtor();
    if (!Ctor) return null;

    const recognition = new Ctor();
    recognition.lang = 'ar-IQ';
    recognition.continuous = true;
    recognition.interimResults = true;
    recognition.maxAlternatives = 1;

    let finalParts: string[] = [];
    let interim = '';

    recognition.onresult = (event) => {
        interim = '';
        for (let i = event.resultIndex; i < event.results.length; i++) {
            const piece = event.results[i]?.[0]?.transcript?.trim();
            if (!piece) continue;
            if (event.results[i]?.isFinal) {
                finalParts.push(piece);
            } else {
                interim = piece;
            }
        }
        const merged = [...finalParts, interim].filter(Boolean).join(' ').trim();
        onUpdate(merged, interim === '');
    };

    recognition.onerror = () => {
        /* لا نوقف التسجيل — STT اختياري */
    };

    return {
        start: () => {
            finalParts = [];
            interim = '';
            try {
                recognition.start();
            } catch {
                /* already started */
            }
        },
        stop: () => {
            try {
                recognition.stop();
            } catch {
                /* ignore */
            }
        },
        getTranscript: () => [...finalParts, interim].filter(Boolean).join(' ').trim(),
    };
}

/** مرجع خفيف في lawyer_notes — الصوت في IndexedDB */
export const VOICE_NOTE_REF_PREFIX = 'hami-voice-ref:';

export type VoiceNoteMeta = {
    ref: string;
    transcript?: string;
    durationSec?: number;
};

export function encodeVoiceNoteRef(noteId: string | number): string {
    return `${VOICE_NOTE_REF_PREFIX}${noteId}`;
}

export function parseVoiceNoteRef(body?: string | null): string | null {
    const value = body?.trim();
    if (!value?.startsWith(VOICE_NOTE_REF_PREFIX)) return null;
    const id = value.slice(VOICE_NOTE_REF_PREFIX.length).trim();
    return id || null;
}

export function isVoiceNoteRef(body?: string | null): boolean {
    return parseVoiceNoteRef(body) != null;
}

export function voiceNoteTitleFromMeta(meta: {
    transcript?: string;
    durationSec?: number;
    fallback?: string;
}): string {
    const t = meta.transcript?.trim();
    if (t) return t.length > 80 ? `${t.slice(0, 77)}…` : t;
    if (meta.durationSec != null && meta.durationSec > 0) {
        const m = Math.floor(meta.durationSec / 60);
        const s = meta.durationSec % 60;
        return m > 0 ? `تسجيل صوتي (${m}:${s.toString().padStart(2, '0')})` : `تسجيل صوتي (${s}ث)`;
    }
    return meta.fallback ?? 'تسجيل صوتي';
}

const DB_NAME = 'hami-voice-notes';
const DB_VERSION = 1;
const STORE = 'blobs';

function openDb(): Promise<IDBDatabase> {
    return new Promise((resolve, reject) => {
        if (typeof indexedDB === 'undefined') {
            reject(new Error('IndexedDB unavailable'));
            return;
        }
        const req = indexedDB.open(DB_NAME, DB_VERSION);
        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(STORE)) {
                db.createObjectStore(STORE);
            }
        };
        req.onsuccess = () => resolve(req.result);
        req.onerror = () => reject(req.error ?? new Error('IndexedDB open failed'));
    });
}

function withStore<T>(mode: IDBTransactionMode, fn: (store: IDBObjectStore) => IDBRequest<T>): Promise<T> {
    return openDb().then(
        (db) =>
            new Promise<T>((resolve, reject) => {
                const tx = db.transaction(STORE, mode);
                const store = tx.objectStore(STORE);
                const req = fn(store);
                req.onsuccess = () => resolve(req.result as T);
                req.onerror = () => reject(req.error ?? new Error('IndexedDB request failed'));
                tx.oncomplete = () => db.close();
                tx.onerror = () => {
                    db.close();
                    reject(tx.error ?? new Error('IndexedDB transaction failed'));
                };
            }),
    );
}

const testBlobStore = new Map<string, Blob>();

function useMemoryStore(): boolean {
    return import.meta.env.MODE === 'test' || import.meta.env.VITEST === true;
}

export async function putVoiceBlob(noteId: string, blob: Blob): Promise<void> {
    const key = String(noteId);
    if (useMemoryStore()) {
        testBlobStore.set(key, blob);
        return;
    }
    await withStore('readwrite', (store) => store.put(blob, key));
}

export async function getVoiceBlob(noteId: string): Promise<Blob | null> {
    const key = String(noteId);
    if (useMemoryStore()) {
        return testBlobStore.get(key) ?? null;
    }
    try {
        const hit = await withStore<Blob | undefined>('readonly', (store) => store.get(key));
        return hit ?? null;
    } catch {
        return null;
    }
}

export async function deleteVoiceBlob(noteId: string): Promise<void> {
    const key = String(noteId);
    if (useMemoryStore()) {
        testBlobStore.delete(key);
        return;
    }
    try {
        await withStore('readwrite', (store) => store.delete(key));
    } catch {
        /* silent */
    }
}

export async function getVoiceObjectUrl(noteId: string): Promise<string | null> {
    const blob = await getVoiceBlob(noteId);
    if (!blob) return null;
    return URL.createObjectURL(blob);
}

export function clearVoiceBlobTestStore(): void {
    testBlobStore.clear();
}

import { encodeVoiceNoteRef } from './voiceNoteCodec';
import { putVoiceBlob } from './voiceNoteStorage';

export const MAX_VOICE_DURATION_SEC = 180;
export const MIN_VOICE_DURATION_SEC = 1;
export const MAX_VOICE_BLOB_BYTES = 4 * 1024 * 1024;

export function formatVoiceDuration(seconds: number): string {
    const m = Math.floor(seconds / 60);
    const s = seconds % 60;
    return `${m}:${s.toString().padStart(2, '0')}`;
}

export function isVoiceBlobWithinLimit(bytes: number): boolean {
    return bytes > 0 && bytes <= MAX_VOICE_BLOB_BYTES;
}

export function isVoiceDurationValid(seconds: number): boolean {
    return seconds >= MIN_VOICE_DURATION_SEC && seconds <= MAX_VOICE_DURATION_SEC;
}

export async function blobToDataUrl(blob: Blob): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => {
            const result = reader.result;
            if (typeof result === 'string') resolve(result);
            else reject(new Error('Invalid read result'));
        };
        reader.onerror = () => reject(reader.error ?? new Error('read failed'));
        reader.readAsDataURL(blob);
    });
}

/** fallback للأجهزة القديمة — data URL مباشر */
export async function persistVoiceRecording(
    noteId: string | number,
    blob: Blob,
): Promise<{ body: string; usedIndexedDb: boolean }> {
    const id = String(noteId);
    if (blob.size <= MAX_VOICE_BLOB_BYTES) {
        try {
            await putVoiceBlob(id, blob);
            return { body: encodeVoiceNoteRef(id), usedIndexedDb: true };
        } catch {
            /* fallback below */
        }
    }
    const dataUrl = await blobToDataUrl(blob);
    if (dataUrl.length > MAX_VOICE_BLOB_BYTES * 1.4) {
        throw new Error('VOICE_TOO_LARGE');
    }
    return { body: dataUrl, usedIndexedDb: false };
}
